const ADMIN_ID = 'admin'
const ADMIN_PW = 'Qta@2026!Sec#Admin'

// ============================================================
// P0+P2 영구 안전 헬퍼 — 모든 백필/manual INSERT 엔드포인트 의무 사용
// ----------------------------------------------------
// 사장님 영구룰 #이중지급 절대 금지 / #cron 단일화 위반 방지
// 이 헬퍼를 통하지 않는 INSERT 는 영구룰 위반 — 코드 리뷰 시 즉시 차단
// ============================================================

/**
 * P0+P2 — 같은 (user_id, type, coin_type, amount, KST date) row 존재 시 throw
 * 모든 백필/manual transactions INSERT 직전 의무 호출
 *
 * D안 (2026-05-13): refereeId 컨텍스트 옵션 추가
 *   - 추천 보너스 매칭처럼 같은 (uid, type, amount, date) 에 여러 referee 분이 들어가는 경우
 *     referee 별 가드가 필요. 같은 amount 라도 referee_id 가 다르면 다른 row 로 인정.
 *   - 식별 방법:
 *     A) referral_rewards 원장에 (referrer_id, referee_id, level, reward_date OR paid_date, reward_amount) row 존재
 *     B) transactions.ref_id 가 `*_referee{N}` 패턴 + N === refereeId
 *     C) transactions.ref_id 가 referral_rewards.id 와 매핑되면 해당 referee_id 비교
 *   - 위 중 하나라도 일치하면 차단, 모두 불일치하면 통과 (즉 새로운 referee 분 INSERT 허용)
 *
 * @param db D1Database
 * @param uid user_id
 * @param type 'daily_reward' | 'referral_reward' | 기타 transactions.type
 * @param amount 금액 (QKEY 단위)
 * @param kstDate 'YYYY-MM-DD' KST 기준 날짜
 * @param coinType 'QKEY' (기본) | 'QTA' | 'QX' | 'USDT'
 * @param refereeId (옵션) 같은 amount 라도 다른 referee 면 통과 — referral_rewards 컨텍스트
 * @param level (옵션, refereeId 와 함께) 1 또는 2 — referral_rewards.level 정확 매칭
 * @param stakingOriginalAmount (G plan, 2026-05-13) 같은 referee 의 다른 staking 분 백필 허용
 *   - referee 의 그 staking 의 daily(QKEY) 값
 *   - referral_rewards.original_amount 와 비교 → 일치하는 ledger row 가 이미 있으면 차단,
 *     없으면 같은 referee 라도 "다른 staking 분" 으로 인정해 통과
 *   - cron 의 매칭 누락 결함(referee 의 첫 staking 만 ledger 에 들어감) 보정용
 * @param stakingId (G2-B, 2026-05-13) 영구 인프라 — referral_rewards.staking_id 컬럼과 정확 비교
 *   - migrations/0014 에서 referral_rewards.staking_id 컬럼 추가 (NULL 허용)
 *   - ledger.staking_id NOT NULL 이고 호출자 stakingId 와 다르면 → 다른 staking 분으로 통과
 *   - ledger.staking_id NULL (legacy) 이면 → stakingOriginalAmount 폴백
 *   - 가장 정확한 매칭 (cron H plan 적용 후 신규 row 부터 100% 정확)
 * @returns true (안전) — 존재 시 Error throw
 */
async function assertNoExistingPayment(
  db: any,
  uid: number,
  type: string,
  amount: number,
  kstDate: string,
  coinType: string = 'QKEY',
  refereeId?: number,
  level?: 1 | 2,
  stakingOriginalAmount?: number,
  stakingId?: number
): Promise<boolean> {
  // STEP 0: 같은 (uid, type, coin, amount, kst_date) row 모두 조회
  const candidatesRes = await db.prepare(`
    SELECT id, ref_id, created_at FROM transactions
    WHERE user_id = ? AND type = ? AND coin_type = ? AND amount = ?
      AND date(datetime(created_at, '+9 hours')) = ?
    ORDER BY id ASC
  `).bind(uid, type, coinType, amount, kstDate).all()
  const candidates = (candidatesRes.results as any[]) || []

  if (candidates.length === 0) return true  // 같은 amount/date row 없음 → 안전

  // refereeId 미지정 → 기존 broad guard 그대로 (첫 후보로 차단)
  if (!refereeId) {
    const existing = candidates[0]
    const e: any = new Error(
      `DUPLICATE_PAYMENT_BLOCKED: uid=${uid} type=${type} amount=${amount} ` +
      `coin=${coinType} kst_date=${kstDate} existing_tx_id=${existing.id} ` +
      `existing_ref_id=${existing.ref_id}`
    )
    e.code = 'DUPLICATE_PAYMENT_BLOCKED'
    e.existing = existing
    e.candidate_count = candidates.length
    throw e
  }

  // refereeId 지정 → 각 후보가 "그 referee 분" 인지 검증
  // 같은 referee 분이 이미 있으면 차단, 모두 다른 referee 분이면 통과
  for (const cand of candidates) {
    const refIdStr = String(cand.ref_id || '')

    // Pattern B: ref_id 가 '*_referee{N}' 패턴
    const refereeMatch = refIdStr.match(/_referee(\d+)\b/)
    if (refereeMatch && Number(refereeMatch[1]) === refereeId) {
      const e: any = new Error(
        `DUPLICATE_PAYMENT_BLOCKED (referee context): uid=${uid} type=${type} amount=${amount} ` +
        `kst_date=${kstDate} referee_id=${refereeId} existing_tx_id=${cand.id} ref_id=${cand.ref_id}`
      )
      e.code = 'DUPLICATE_PAYMENT_BLOCKED'
      e.existing = cand
      e.match_reason = 'ref_id_referee_pattern'
      throw e
    }

    // Pattern C: ref_id 가 숫자 → referral_rewards.id 매핑 → referee_id 비교
    if (/^\d+$/.test(refIdStr)) {
      // G2-B (2026-05-13): staking_id 컬럼이 추가됐으나 schema 마이그레이션 전 인스턴스 호환을 위해
      //   PRAGMA 로 컬럼 존재 여부 동적 확인 후 SELECT
      let hasStakingIdCol = false
      try {
        const pragmaRes = await db.prepare(`PRAGMA table_info(referral_rewards)`).all()
        const cols = ((pragmaRes.results as any[]) || []).map((r: any) => r.name)
        hasStakingIdCol = cols.includes('staking_id')
      } catch {}
      const selectSql = hasStakingIdCol
        ? `SELECT id, referee_id, level, original_amount, staking_id FROM referral_rewards WHERE id = ?`
        : `SELECT id, referee_id, level, original_amount FROM referral_rewards WHERE id = ?`
      const rrRow = await db.prepare(selectSql).bind(Number(refIdStr)).first() as any
      if (rrRow && Number(rrRow.referee_id) === refereeId) {
        // level 도 지정됐으면 함께 매칭
        if (level && Number(rrRow.level) !== level) continue
        // G2-B (2026-05-13): ledger.staking_id 가 NOT NULL 이고 호출자 stakingId 와 다르면 → 통과
        //   가장 정확한 매칭 (cron H plan 적용 후 신규 row 부터 100% 정확)
        if (
          typeof stakingId === 'number' &&
          rrRow.staking_id != null &&
          Number(rrRow.staking_id) !== stakingId
        ) {
          continue  // ledger 가 다른 staking_id 분 → 백필 통과 허용
        }
        // G plan (2026-05-13): stakingOriginalAmount 지정됐으면 ledger.original_amount 와 비교
        //   다르면 같은 referee 라도 "다른 staking 분" 으로 인정 → 차단하지 않음
        if (
          typeof stakingOriginalAmount === 'number' &&
          rrRow.original_amount != null &&
          Number(rrRow.original_amount) !== stakingOriginalAmount
        ) {
          continue  // 다른 staking 의 ledger row → 백필 통과 허용
        }
        // G2-B (2026-05-13): ledger.staking_id NULL (legacy) + 호출자 stakingId 명시
        //   → legacy 는 "어느 staking 분인지 모름" → 신규 row 가 다른 staking 분이라고 주장 가능
        //   단, 같은 (uid, level, kst_date, referee) 의 ledger row 수가 referee 의 active staking 수보다 적을 때만 통과
        if (
          hasStakingIdCol &&
          typeof stakingId === 'number' &&
          rrRow.staking_id == null
        ) {
          // referee 의 active staking 수
          const stCountRow = await db.prepare(
            `SELECT COUNT(*) AS n FROM staking WHERE user_id = ? AND status = 'active'`
          ).bind(refereeId).first() as any
          // 같은 (uid, referee, level, date) 의 ledger row 총 수
          const ldCountRow = await db.prepare(`
            SELECT COUNT(*) AS n FROM referral_rewards
            WHERE referrer_id = ? AND referee_id = ? AND level = ?
              AND (paid_date = ? OR reward_date = ?
                   OR date(datetime(created_at, '+9 hours')) = ?)
          `).bind(uid, refereeId, level, kstDate, kstDate, kstDate).first() as any
          const stCount = Number(stCountRow?.n || 0)
          const ldCount = Number(ldCountRow?.n || 0)
          if (ldCount < stCount) {
            continue  // legacy gap 존재 → 누락된 staking 분 백필 허용
          }
        }
        const e: any = new Error(
          `DUPLICATE_PAYMENT_BLOCKED (referee context via ledger): uid=${uid} type=${type} amount=${amount} ` +
          `kst_date=${kstDate} referee_id=${refereeId} existing_tx_id=${cand.id} rr_ledger_id=${rrRow.id}` +
          (typeof stakingId === 'number' ? ` ledger_staking_id=${rrRow.staking_id} new_staking_id=${stakingId}` : '') +
          (typeof stakingOriginalAmount === 'number' ? ` ledger_original=${rrRow.original_amount} new_original=${stakingOriginalAmount}` : '')
        )
        e.code = 'DUPLICATE_PAYMENT_BLOCKED'
        e.existing = cand
        e.match_reason = 'rr_ledger_referee_match'
        throw e
      }
    }

    // Pattern E (G plan, 2026-05-13): ref_id 가 '*_referee{N}_s{M}' 패턴 — staking_id 인식
    //   같은 referee 라도 다른 staking_id 분이면 통과
    const stakingMatch = refIdStr.match(/_referee(\d+)_s(\d+)\b/)
    if (stakingMatch && Number(stakingMatch[1]) === refereeId) {
      // 같은 referee + 같은 staking 분 → 차단
      // 같은 referee + 다른 staking 분 → continue (다른 후보 검사)
      // 호출자가 stakingOriginalAmount 를 넘기지 않으면 broad 동작 (차단)
      const existingStakingId = Number(stakingMatch[2])
      // 호출자가 백필 ref_id 에 staking_id 를 넣었다면 동일 staking_id 인 경우만 차단
      // 다른 staking 분이면 통과는 다음 후보로
      // (broad fallback — 호출자가 명시적 stakingOriginalAmount 안 줬을 때는 차단)
      if (typeof stakingOriginalAmount !== 'number') {
        const e: any = new Error(
          `DUPLICATE_PAYMENT_BLOCKED (referee+staking pattern): uid=${uid} type=${type} amount=${amount} ` +
          `kst_date=${kstDate} referee_id=${refereeId} existing_staking_id=${existingStakingId} existing_tx_id=${cand.id}`
        )
        e.code = 'DUPLICATE_PAYMENT_BLOCKED'
        e.existing = cand
        e.match_reason = 'ref_id_referee_staking_pattern'
        throw e
      }
      // stakingOriginalAmount 명시 → 다른 staking 분으로 인정 → continue
    }
  }

  // Pattern A: referral_rewards 원장 자체에 같은 (referrer, referee, level, date, amount) row 있는지
  //   referrer_id = uid (수령자), referee_id = refereeId
  //   G plan (2026-05-13): stakingOriginalAmount 지정 시 original_amount 도 함께 매칭
  //   G2-B (2026-05-13): staking_id 컬럼 인식 (가장 정확)
  if (level) {
    // G2-B: PRAGMA 로 staking_id 컬럼 존재 여부 동적 확인
    let hasStakingIdColA = false
    try {
      const pragmaRes = await db.prepare(`PRAGMA table_info(referral_rewards)`).all()
      const cols = ((pragmaRes.results as any[]) || []).map((r: any) => r.name)
      hasStakingIdColA = cols.includes('staking_id')
    } catch {}
    const selectSqlA = hasStakingIdColA
      ? `SELECT id, original_amount, staking_id FROM referral_rewards
         WHERE referrer_id = ? AND referee_id = ? AND level = ? AND reward_amount = ?
           AND (paid_date = ? OR reward_date = ?
                OR date(datetime(created_at, '+9 hours')) = ?)`
      : `SELECT id, original_amount FROM referral_rewards
         WHERE referrer_id = ? AND referee_id = ? AND level = ? AND reward_amount = ?
           AND (paid_date = ? OR reward_date = ?
                OR date(datetime(created_at, '+9 hours')) = ?)`
    const rrExist = await db.prepare(selectSqlA)
      .bind(uid, refereeId, level, amount, kstDate, kstDate, kstDate).all()
    const rrRows = (rrExist.results as any[]) || []

    // legacy gap 계산 사전 준비 (NULL row 존재 시에만)
    let legacyGapInfo: { stCount: number, ldCount: number } | null = null
    const hasLegacyNull = rrRows.some((rr: any) => hasStakingIdColA && rr.staking_id == null)
    if (hasStakingIdColA && hasLegacyNull && typeof stakingId === 'number') {
      const stCountRow = await db.prepare(
        `SELECT COUNT(*) AS n FROM staking WHERE user_id = ? AND status = 'active'`
      ).bind(refereeId).first() as any
      const ldCountRow = await db.prepare(`
        SELECT COUNT(*) AS n FROM referral_rewards
        WHERE referrer_id = ? AND referee_id = ? AND level = ?
          AND (paid_date = ? OR reward_date = ?
               OR date(datetime(created_at, '+9 hours')) = ?)
      `).bind(uid, refereeId, level, kstDate, kstDate, kstDate).first() as any
      legacyGapInfo = {
        stCount: Number(stCountRow?.n || 0),
        ldCount: Number(ldCountRow?.n || 0),
      }
    }

    for (const rr of rrRows) {
      // G2-B: ledger.staking_id NOT NULL + 호출자 stakingId 와 다르면 → 통과 (다른 staking 분)
      if (
        hasStakingIdColA &&
        typeof stakingId === 'number' &&
        rr.staking_id != null &&
        Number(rr.staking_id) !== stakingId
      ) {
        continue
      }
      // G2-B: ledger.staking_id NULL (legacy) + legacy gap 존재 → 누락 staking 분 백필 허용
      if (
        hasStakingIdColA &&
        typeof stakingId === 'number' &&
        rr.staking_id == null &&
        legacyGapInfo &&
        legacyGapInfo.ldCount < legacyGapInfo.stCount
      ) {
        continue
      }
      // G plan: stakingOriginalAmount 명시 + 일치하지 않으면 → 다른 staking 분으로 인정해 skip
      if (
        typeof stakingOriginalAmount === 'number' &&
        rr.original_amount != null &&
        Number(rr.original_amount) !== stakingOriginalAmount
      ) {
        continue
      }
      const e: any = new Error(
        `DUPLICATE_PAYMENT_BLOCKED (ledger pre-existing): uid=${uid} type=${type} amount=${amount} ` +
        `kst_date=${kstDate} referee_id=${refereeId} level=${level} rr_id=${rr.id}` +
        (hasStakingIdColA ? ` ledger_staking_id=${rr.staking_id}` : '') +
        (typeof stakingId === 'number' ? ` new_staking_id=${stakingId}` : '') +
        (typeof stakingOriginalAmount === 'number' ? ` ledger_original=${rr.original_amount} new_original=${stakingOriginalAmount}` : '')
      )
      e.code = 'DUPLICATE_PAYMENT_BLOCKED'
      e.match_reason = 'rr_ledger_direct'
      throw e
    }
  }

  // 같은 amount row 들이 있지만 모두 다른 referee 분 → 통과
  return true
}

/**
 * P0+P2 — daily_rewards 테이블 (staking_id, reward_date) 존재 시 throw
 */
async function assertNoExistingDailyReward(
  db: any,
  stakingId: number,
  rewardDate: string
): Promise<boolean> {
  const existing = await db.prepare(`
    SELECT id, user_id, usdt_amount FROM daily_rewards
    WHERE staking_id = ? AND reward_date = ?
    LIMIT 1
  `).bind(stakingId, rewardDate).first()
  if (existing) {
    const e: any = new Error(
      `DUPLICATE_DAILY_REWARD_BLOCKED: staking_id=${stakingId} reward_date=${rewardDate} ` +
      `existing_id=${(existing as any).id} existing_qkey=${(existing as any).usdt_amount}`
    )
    e.code = 'DUPLICATE_DAILY_REWARD_BLOCKED'
    e.existing = existing
    throw e
  }
  return true
}

/**
 * P0 Stage 1 (2026-05-13) — 레거시 backfill/fix/exec endpoint deprecation guard
 *
 * 사장님 영구 룰 #이중지급 절대 금지 원천 차단:
 * - 13개 레거시 endpoint 는 모든 보정 작업 완료 상태 (재호출 의미 없음)
 * - 단순 재호출만으로도 가드 미적용 INSERT INTO transactions 발생 가능 → 이중지급 위험
 * - 이 헬퍼는 ?force=GO 키가 명시되지 않으면 410 Gone 응답
 * - 사장님이 명시적으로 force=GO 주지 않는 한 호출 자체 차단
 *
 * 사용:
 *   const dep = assertNotDeprecated(c, 'endpoint-name', '...작업 완료 일자/이유')
 *   if (dep) return dep
 *
 * 강제 호출 (사장님 명시 명령 시만):
 *   ?key=ADMIN_PW&force=GO  → 가드 우회, 원본 endpoint 로직 실행
 */
function assertNotDeprecated(c: any, endpointName: string, reason: string): Response | null {
  const force = c.req.query('force') || ''
  if (force === 'GO') return null  // 사장님 명시 명령 — 통과
  return c.json({
    error: 'ENDPOINT_DEPRECATED',
    endpoint: endpointName,
    deprecated_since: '2026-05-13',
    reason,
    permanent_rule: '#이중지급 절대 금지 — 재호출 통한 이중지급 원천 차단',
    note: '본 endpoint 는 보정 작업이 이미 완료되어 재호출 의미가 없습니다. 사장님 명시 명령 시에만 ?force=GO 추가로 우회 가능합니다.',
    docs: 'P0 Stage 1 deprecation guard (lucky4492 5/8 dup payment 사건 후속 영구 인프라)',
  }, 410)
}

/**
 * P0+P2 — ref_id 존재 시 throw (백필 ref_id 가드)
 */
async function assertNoExistingRefId(db: any, refId: string): Promise<boolean> {
  const existing = await db.prepare(
    `SELECT id, user_id, amount FROM transactions WHERE ref_id = ? LIMIT 1`
  ).bind(refId).first()
  if (existing) {
    const e: any = new Error(`DUPLICATE_REF_ID_BLOCKED: ref_id=${refId} existing_tx_id=${(existing as any).id}`)
    e.code = 'DUPLICATE_REF_ID_BLOCKED'
    e.existing = existing
    throw e
  }
  return true
}

/**
 * P0+P2 — 안전한 transactions INSERT (3중 가드 자동 수행)
 *   1. assertNoExistingRefId
 *   2. assertNoExistingPayment (refereeId 컨텍스트 옵션 포함, D안 보강)
 *   3. INSERT + qkey_balance UPDATE (옵션)
 *
 * D안 (2026-05-13): refereeId / level 옵션 추가
 *   - 추천 보너스 매칭: 같은 uid 가 같은 날 같은 amount 를 여러 referee 분 받는 정상 케이스 지원
 *   - 백필 ref_id 패턴 추천: 'bf_{date}_{ctx}_referee{refereeId}' — 가드가 자동 인식
 *   - referee 컨텍스트 미사용 시 기존 broad guard 그대로 (호환성 유지)
 *
 * 사용 예 (referee 컨텍스트):
 *   await safeInsertTransaction(db, {
 *     user_id: 44, type: 'referral_reward', coin_type: 'QKEY',
 *     amount: 150, description: '추천 보너스 (Level 1)',
 *     ref_id: 'bf_513_solbat_l1_referee45_s72', kst_date: '2026-05-13',
 *     refereeId: 45, level: 1,
 *     updateBalance: true
 *   })
 */
async function safeInsertTransaction(db: any, p: {
  user_id: number
  type: string
  coin_type: string
  amount: number
  description: string
  ref_id: string
  kst_date: string
  updateBalance?: boolean
  balanceColumn?: string  // 'qkey_balance' (기본)
  refereeId?: number      // D안 — 추천 보너스 컨텍스트
  level?: 1 | 2           // D안 — referral_rewards.level
  stakingOriginalAmount?: number  // G plan (2026-05-13) — referee 의 다른 staking 분 백필
  stakingId?: number      // G2-B (2026-05-13) — referral_rewards.staking_id 컬럼 정확 비교
}): Promise<{ tx_id: number }> {
  // 1) ref_id 가드
  await assertNoExistingRefId(db, p.ref_id)
  // 2) 같은 날 같은 사용자 같은 amount 가드 — D안: refereeId/level + G plan: stakingOriginalAmount + G2-B: stakingId
  await assertNoExistingPayment(
    db, p.user_id, p.type, p.amount, p.kst_date, p.coin_type,
    p.refereeId, p.level, p.stakingOriginalAmount, p.stakingId
  )
  // 3) INSERT
  const res = await db.prepare(`
    INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
    VALUES (?, ?, ?, ?, ?, ?)
  `).bind(p.user_id, p.type, p.coin_type, p.amount, p.description, p.ref_id).run()
  // 4) 잔액 UPDATE (옵션)
  if (p.updateBalance) {
    const col = p.balanceColumn || 'qkey_balance'
    await db.prepare(
      `UPDATE users SET ${col} = COALESCE(${col},0) + ? WHERE id = ?`
    ).bind(p.amount, p.user_id).run()
  }
  return { tx_id: Number(res.meta?.last_row_id || 0) }
}

