// 회원가입
app.post('/api/auth/register', async (c) => {
  try {
    const { email, password, name, phone, walletAddress, usdtWalletAddress, referralCode, country, language } = await c.req.json()

    if (!email || !password || !name || !phone || !walletAddress || !usdtWalletAddress) {
      return c.json({ error: t(c, 'auth.all_fields_required') }, 400)
    }

    // 이메일을 소문자로 변환 (대소문자 구분 제거)
    const normalizedEmail = email.toLowerCase().trim()

    // 전화번호에서 하이픈 제거 및 형식 검증 (010 + 8자리 숫자)
    const cleanPhone = phone.replace(/-/g, '')
    if (!cleanPhone.match(/^010\d{8}$/)) {
      return c.json({ error: t(c, 'auth.invalid_phone') }, 400)
    }

    // QKEY 지갑주소 형식 검증 (0x로 시작하는 42자리)
    if (!walletAddress.match(/^0x[a-fA-F0-9]{40}$/)) {
      return c.json({ error: t(c, 'auth.invalid_qkey_wallet') }, 400)
    }

    // USDT 지갑주소 형식 검증 (0x로 시작하는 42자리)
    if (!usdtWalletAddress.match(/^0x[a-fA-F0-9]{40}$/)) {
      return c.json({ error: t(c, 'auth.invalid_usdt_wallet') }, 400)
    }

    const db = c.env.DB

    // 추천인 코드 검증 (필수)
    if (!referralCode || !referralCode.trim()) {
      return c.json({ error: t(c, 'auth.referral_required') }, 400)
    }
    let referrerId = null
    const MASTER_REFERRAL_CODE = 'QTAICVDN2'
    const upperCode = referralCode.trim().toUpperCase()
    
    if (upperCode === MASTER_REFERRAL_CODE) {
      // 최초 가입용 마스터 추천코드 - referrerId는 null
      referrerId = null
    } else {
      const referrer = await db.prepare('SELECT id FROM users WHERE referral_code = ?')
        .bind(upperCode)
        .first()
      
      if (!referrer) {
        return c.json({ error: t(c, 'auth.invalid_referral') }, 400)
      }
      referrerId = referrer.id
    }

    // 이메일 중복 체크 (소문자로 비교)
    const existingEmail = await db.prepare('SELECT id FROM users WHERE LOWER(email) = ?')
      .bind(normalizedEmail)
      .first()

    if (existingEmail) {
      return c.json({ error: t(c, 'auth.email_exists') }, 400)
    }

    // 전화번호 중복 체크
    const existingPhone = await db.prepare('SELECT id FROM users WHERE phone = ?')
      .bind(cleanPhone)
      .first()

    if (existingPhone) {
      return c.json({ error: t(c, 'auth.phone_exists') }, 400)
    }

    // 지갑주소 중복 체크
    const existingWallet = await db.prepare('SELECT id FROM users WHERE wallet_address = ?')
      .bind(walletAddress)
      .first()

    if (existingWallet) {
      return c.json({ error: t(c, 'auth.wallet_exists') }, 400)
    }

    // 고유한 추천인 코드 생성 (SAY + 6자리 랜덤)
    let newReferralCode = ''
    let isUnique = false
    while (!isUnique) {
      newReferralCode = 'QTA' + Math.random().toString(36).substring(2, 8).toUpperCase()
      const existing = await db.prepare('SELECT id FROM users WHERE referral_code = ?')
        .bind(newReferralCode)
        .first()
      if (!existing) {
        isUnique = true
      }
    }

    // 비밀번호 해싱
    const hashedPassword = await hashPassword(password)

    // 사용자 생성
    const result = await db.prepare(`
      INSERT INTO users (email, password, name, phone, wallet_address, usdt_wallet_address, qta_balance, qx_balance, qkey_balance, usdt_balance, referral_code, referrer_id, country, language)
      VALUES (?, ?, ?, ?, ?, ?, 0, 0, 0, 0, ?, ?, ?, ?)
    `).bind(normalizedEmail, hashedPassword, name, cleanPhone, walletAddress, usdtWalletAddress, newReferralCode, referrerId, country || '', language || 'ko').run()

    return c.json({ 
      success: true, 
      message: t(c, 'auth.register_success'),
      userId: result.meta.last_row_id,
      referralCode: newReferralCode
    })
  } catch (error) {
    return c.json({ error: t(c, 'auth.register_error') }, 500)
  }
})

// 로그인
app.post('/api/auth/login', async (c) => {
  try {
    const { email, password } = await c.req.json()

    if (!email || !password) {
      return c.json({ error: t(c, 'auth.email_password_required') }, 400)
    }

    // 이메일을 소문자로 변환 (대소문자 구분 제거)
    const normalizedEmail = email.toLowerCase().trim()

    const db = c.env.DB

    // 이메일로 사용자 조회 (비밀번호는 별도 검증)
    // ★ 영구정책 (2026-05-14): qta_initial/qx_initial(회사 지급분, 출금불가) + qta_withdrawable/qx_withdrawable/usdt_withdrawable(출금가능) 함께 조회
    await ensureWithdrawableSchema(c.env.DB)
    const user = await db.prepare(`
      SELECT id, email, password, name, phone, wallet_address, usdt_wallet_address,
             qta_balance, qx_balance, qkey_balance, usdt_balance,
             COALESCE(qta_initial,0) as qta_initial,
             COALESCE(qx_initial,0) as qx_initial,
             COALESCE(qta_withdrawable,0) as qta_withdrawable,
             COALESCE(qx_withdrawable,0) as qx_withdrawable,
             COALESCE(usdt_withdrawable,0) as usdt_withdrawable,
             referral_code, created_at
      FROM users WHERE LOWER(email) = ?
    `).bind(normalizedEmail).first()

    if (!user) {
      return c.json({ error: t(c, 'auth.invalid_credentials') }, 401)
    }

    // 비밀번호 검증 (해시/평문 호환)
    const passwordMatch = await verifyPassword(password, user.password as string)
    if (!passwordMatch) {
      return c.json({ error: t(c, 'auth.invalid_credentials') }, 401)
    }

    // 평문 비밀번호인 경우 해시로 마이그레이션
    const storedPw = user.password as string
    if (!(storedPw.length === 64 && /^[a-f0-9]{64}$/.test(storedPw))) {
      const hashedPw = await hashPassword(password)
      await db.prepare('UPDATE users SET password = ? WHERE id = ?').bind(hashedPw, user.id).run()
    }

    // referral_code가 없으면 생성 (6자리 랜덤, 중복 체크)
    let referralCode = user.referral_code
    if (!referralCode) {
      let isUnique = false
      while (!isUnique) {
        referralCode = 'QTA' + Math.random().toString(36).substring(2, 8).toUpperCase()
        const existing = await db.prepare('SELECT id FROM users WHERE referral_code = ?').bind(referralCode).first()
        if (!existing) isUnique = true
      }
      await db.prepare(`
        UPDATE users SET referral_code = ? WHERE id = ?
      `).bind(referralCode, user.id).run()
    }

    return c.json({ 
      success: true, 
      message: t(c, 'auth.login_success'),
      user: {
        id: user.id,
        email: user.email,
        name: user.name,
        phone: user.phone,
        wallet_address: user.wallet_address,
        usdt_wallet_address: user.usdt_wallet_address || '',
        qta_balance: user.qta_balance,
        qx_balance: user.qx_balance,
        qkey_balance: user.qkey_balance,
        usdt_balance: user.usdt_balance,
        // ★ 영구정책 (2026-05-14): 출처별 분리 노출 — 카드 UI 옵션 A "회사지급 (출금가능)" 형식
        qta_initial: Number(user.qta_initial || 0),
        qx_initial: Number(user.qx_initial || 0),
        qta_withdrawable: Number(user.qta_withdrawable || 0),
        qx_withdrawable: Number(user.qx_withdrawable || 0),
        usdt_withdrawable: Number(user.usdt_withdrawable || 0),
        referral_code: referralCode,
        created_at: user.created_at
      }
    })
  } catch (error) {
    return c.json({ error: t(c, 'auth.login_error') }, 500)
  }
})

// 아이디 찾기 (QKEY 지갑주소)
app.post('/api/auth/find-id', async (c) => {
  try {
    const { walletAddress } = await c.req.json()

    if (!walletAddress) {
      return c.json({ error: t(c, 'auth.wallet_required') }, 400)
    }

    if (!walletAddress.match(/^0x[a-fA-F0-9]{40}$/)) {
      return c.json({ error: t(c, 'auth.invalid_qkey_wallet') }, 400)
    }

    const db = c.env.DB

    const user = await db.prepare(`
      SELECT email FROM users WHERE wallet_address = ?
    `).bind(walletAddress).first()

    if (!user) {
      return c.json({ error: t(c, 'auth.account_not_found') }, 404)
    }

    return c.json({ 
      success: true, 
      email: user.email
    })
  } catch (error) {
    return c.json({ error: t(c, 'auth.find_id_error') }, 500)
  }
})

// 비밀번호 찾기 (QKEY 지갑주소)
app.post('/api/auth/find-password', async (c) => {
  try {
    const { walletAddress } = await c.req.json()

    if (!walletAddress) {
      return c.json({ error: t(c, 'auth.wallet_required') }, 400)
    }

    if (!walletAddress.match(/^0x[a-fA-F0-9]{40}$/)) {
      return c.json({ error: t(c, 'auth.invalid_qkey_wallet') }, 400)
    }

    const db = c.env.DB

    const user = await db.prepare(`
      SELECT id FROM users WHERE wallet_address = ?
    `).bind(walletAddress).first()

    if (!user) {
      return c.json({ error: t(c, 'auth.account_not_found') }, 404)
    }

    // 임시 비밀번호 생성 (해시하여 저장)
    const tempPassword = Math.random().toString(36).slice(-8)
    const hashedTemp = await hashPassword(tempPassword)

    await db.prepare(`
      UPDATE users SET password = ? WHERE id = ?
    `).bind(hashedTemp, user.id).run()

    return c.json({ 
      success: true, 
      tempPassword: tempPassword,
      message: t(c, 'auth.temp_password_issued')
    })
  } catch (error) {
    return c.json({ error: t(c, 'auth.find_pw_error') }, 500)
  }
})

// 사용자 프로필 업데이트
app.post('/api/user/update-profile', async (c) => {
  try {
    const { userId, name, phone, password } = await c.req.json()

    if (!userId || !name) {
      return c.json({ error: t(c, 'profile.required_fields') }, 400)
    }

    const db = c.env.DB

    // 비밀번호 변경이 있는 경우 (해시하여 저장)
    if (password) {
      const hashedPw = await hashPassword(password)
      await db.prepare(`
        UPDATE users 
        SET name = ?, phone = ?, password = ?, updated_at = CURRENT_TIMESTAMP
        WHERE id = ?
      `).bind(name, phone || null, hashedPw, userId).run()
    } else {
      // 비밀번호 변경 없이 이름, 전화번호만 업데이트
      await db.prepare(`
        UPDATE users 
        SET name = ?, phone = ?, updated_at = CURRENT_TIMESTAMP
        WHERE id = ?
      `).bind(name, phone || null, userId).run()
    }

    return c.json({ 
      success: true, 
      message: t(c, 'profile.update_success')
    })
  } catch (error) {
    return c.json({ error: t(c, 'profile.update_error') }, 500)
  }
})

// ============================================
// API Routes - Withdrawal
// ============================================

// ★ 출금 수수료 정책 상수 (사장님 결재 2026-05-11, A/A/A)
//   - 어떤 코인이든 무조건 신청 수량의 5% 공제
//   - 잔액에서 100% 차감, 회사 5% 공제, 사용자 실수령 95%
//   - 거절 시 100% 환불 + 수수료 reverse 행 INSERT
const WITHDRAWAL_FEE_RATE = 0.05

// ★ Lazy migration: withdrawals 테이블에 fee/net_amount/fee_rate 컬럼 보장
//   원격 D1 직접 ALTER 불가 환경 대응 — 코드 진입 시 자체 적용
let _withdrawalFeeSchemaEnsured = false
async function ensureWithdrawalFeeSchema(db: any) {
  if (_withdrawalFeeSchemaEnsured) return
  try {
    const info = await db.prepare(`PRAGMA table_info(withdrawals)`).all()
    const cols = new Set((info.results || []).map((r: any) => r.name))
    if (!cols.has('fee')) {
      await db.prepare(`ALTER TABLE withdrawals ADD COLUMN fee REAL DEFAULT 0`).run()
    }
    if (!cols.has('net_amount')) {
      await db.prepare(`ALTER TABLE withdrawals ADD COLUMN net_amount REAL DEFAULT 0`).run()
    }
    if (!cols.has('fee_rate')) {
      await db.prepare(`ALTER TABLE withdrawals ADD COLUMN fee_rate REAL DEFAULT 0.05`).run()
    }
    _withdrawalFeeSchemaEnsured = true
  } catch (e) {
    // ALTER 실패는 무시 (이미 적용된 경우 등) — INSERT 시점에 다시 시도되지 않도록 플래그 set
    _withdrawalFeeSchemaEnsured = true
  }
}

// ★★★ 영구정책 (2026-05-14, 사장님 .md 명시) ★★★
// users 테이블에 출처 추적 컬럼 보장 — 회사 지급분(initial) vs 출금가능(withdrawable) 분리
//   qta_initial:      회사 최초 진입 시 지급된 QTA (절대 출금 불가)
//   qx_initial:       회사 최초 진입 시 지급된 QX (절대 출금 불가)
//   qta_withdrawable: 데일리/매칭/추천 출처 → QTA 스왑 결과 (출금 가능)
//   qx_withdrawable:  데일리/매칭/추천 출처 → QX 스왑 결과 (출금 가능)
//   usdt_withdrawable: 데일리/매칭/추천 출처 → USDT 스왑 결과 (출금 가능, 100 USDT 이상부터)
// QKEY 는 모두 데일리/매칭/추천 출처 → qkey_balance 그대로 출금 가능
// 표시용 qta_balance / qx_balance / usdt_balance = initial + withdrawable 합산 (카드 UI 표시 + 호환성)
let _withdrawableSchemaEnsured = false
async function ensureWithdrawableSchema(db: any) {
  if (_withdrawableSchemaEnsured) return
  try {
    const info = await db.prepare(`PRAGMA table_info(users)`).all()
    const cols = new Set((info.results || []).map((r: any) => r.name))
    if (!cols.has('qta_initial')) {
      await db.prepare(`ALTER TABLE users ADD COLUMN qta_initial REAL DEFAULT 0`).run()
    }
    if (!cols.has('qx_initial')) {
      await db.prepare(`ALTER TABLE users ADD COLUMN qx_initial REAL DEFAULT 0`).run()
    }
    if (!cols.has('qta_withdrawable')) {
      await db.prepare(`ALTER TABLE users ADD COLUMN qta_withdrawable REAL DEFAULT 0`).run()
    }
    if (!cols.has('qx_withdrawable')) {
      await db.prepare(`ALTER TABLE users ADD COLUMN qx_withdrawable REAL DEFAULT 0`).run()
    }
    if (!cols.has('usdt_withdrawable')) {
      await db.prepare(`ALTER TABLE users ADD COLUMN usdt_withdrawable REAL DEFAULT 0`).run()
    }
    _withdrawableSchemaEnsured = true
  } catch (e) {
    _withdrawableSchemaEnsured = true
  }
}

// 출금 신청 (금요일 오전 10시 ~ 오후 2시 KST만 가능)
app.post('/api/withdrawal/request', async (c) => {
  try {
    // 출금 신청 가능 시간 체크: 매주 금요일 10:00~14:00 KST (공휴일 무관)
    const now = new Date()
    if (!isWithdrawalWindowOpen(now)) {
      return c.json({ 
        error: '출금 신청은 매주 금요일 오전 10시 ~ 오후 2시(KST)에만 가능합니다. / Withdrawals are only available on Fridays 10:00 AM - 2:00 PM (KST).',
        withdrawal_closed: true
      }, 400)
    }

    const { userId, coinType, amount: _amountRaw, walletAddress } = await c.req.json()

    if (!userId || !coinType || !_amountRaw || !walletAddress) {
      return c.json({ error: t(c, 'profile.required_fields') }, 400)
    }

    if (!['QTA', 'QX', 'QKEY', 'USDT'].includes(coinType)) {
      return c.json({ error: t(c, 'withdrawal.invalid_coin') }, 400)
    }

    // ★★★ 영구룰 #no-decimal (사장님 2026-05-26) ★★★
    //   소수점 절대 금지 — 0.1, 0.3, 0.9 모두 1로 자동 보정 (Math.ceil)
    //   입력 단계부터 정수로 강제하여 이후 모든 계산이 정수 단위로 진행되도록 함
    const amount = Math.ceil(Number(_amountRaw))

    if (amount <= 0) {
      return c.json({ error: t(c, 'withdrawal.invalid_amount') }, 400)
    }

    const db = c.env.DB

    // ★ Lazy migration: withdrawals 테이블에 fee/net_amount/fee_rate 컬럼 확보
    await ensureWithdrawalFeeSchema(db)

    // ★★★ 영구정책 (2026-05-14, 사장님 .md 명시) ★★★
    // 출금 가능 대상 = 데일리/매칭/추천 출처 코인 + 그 스왑 결과물 (qta_withdrawable, qx_withdrawable, usdt_withdrawable)
    // 출금 절대 금지 = 회사 최초 진입 시 지급분 (qta_initial, qx_initial) + 그 스왑 결과물
    // QKEY 는 데일리/매칭 출처만 존재 → qkey_balance 그대로 사용
    await ensureWithdrawableSchema(db)

    // USDT 100 이하 출금 불가 경고 (사장님 정책 2026-05-14)
    if (coinType === 'USDT' && amount < 100) {
      return c.json({ error: 'USDT 출금은 100 USDT 이상부터 가능합니다. (100개 이하 출금 불가)' }, 400)
    }

    // ★★★ 영구룰 #qta-qx-net-천단위 + #no-decimal (사장님 정책 2026-05-26) ★★★
    //   QTA/QX 출금은 "수수료 차감 후 실수령액(net)" 이 1,000 의 배수여야 함
    //   소수점 절대 금지 — Math.ceil 로 정수 강제
    //   예: net=5,000 → amount=ceil(5,000/0.95)=5,264 (정수)
    //       net=10,000 → amount=ceil(10,000/0.95)=10,527 (정수)
    if (coinType === 'QTA' || coinType === 'QX') {
      // fee 와 net 도 정수 (Math.ceil — 수수료 올림)
      const _feeChk = Math.ceil(amount * WITHDRAWAL_FEE_RATE)
      const _net = amount - _feeChk  // 정수 - 정수 = 정수
      if (_net <= 0 || _net % 1000 !== 0) {
        // 가능한 최대 net (현재 amount 이하의 최대 1000 배수)
        const _maxNetFloor = Math.floor(_net / 1000) * 1000
        const _suggestAmount = _maxNetFloor > 0 ? Math.ceil(_maxNetFloor / (1 - WITHDRAWAL_FEE_RATE)) : 0
        return c.json({
          error: `${coinType} 출금은 수수료 5% 차감 후 실수령액(net)이 1,000 ${coinType} 의 배수여야 합니다. 현재 신청: ${amount.toLocaleString()} ${coinType} → 실수령: ${_net.toLocaleString()} ${coinType}. 권장 신청액: ${_suggestAmount.toLocaleString()} ${coinType} (실수령 ${_maxNetFloor.toLocaleString()} ${coinType})`,
          net_not_thousand: true,
          requested_amount: amount,
          calculated_net: _net,
          suggested_amount: _suggestAmount,
          suggested_net: _maxNetFloor
        }, 400)
      }
    }

    // 사용자 잔액 확인 (출금가능 컬럼 우선)
    const user = await db.prepare(`
      SELECT qta_balance, qx_balance, qkey_balance, usdt_balance,
             COALESCE(qta_withdrawable,0) as qta_withdrawable,
             COALESCE(qx_withdrawable,0) as qx_withdrawable,
             COALESCE(usdt_withdrawable,0) as usdt_withdrawable
      FROM users WHERE id = ?
    `).bind(userId).first()

    if (!user) {
      return c.json({ error: t(c, 'withdrawal.user_not_found') }, 404)
    }

    // ★ 사장님 2026-05-15 (5차) 지시: 출금 신청은 같은 금요일(주간) 내 1회로 제한 ★
    //   기준: 이번 주 월요일 ~ 일요일(KST) 사이에 해당 user_id 의 withdrawals 행이 1건이라도 있으면 추가 신청 차단
    //   상태(status) 무관 — pending / approved / rejected / completed / cancelled 모두 카운트
    //   다음 주 금요일 이후에는 다시 1회 신청 가능
    //   - 이전(4차) 룰: 계정 평생 1회 → 사장님 5차 지시로 주간 1회로 변경
    //
    //   주간 경계: KST 기준 이번 주 월요일 00:00 ~ 다음 주 월요일 00:00 (반열린 구간)
    const nowKstMs = new Date(Date.now() + (9 * 60 * 60 * 1000))
    // getUTCDay: 0=일, 1=월, ..., 6=토 (KST 보정 후)
    const _dayNum = nowKstMs.getUTCDay() // 0=일 .. 6=토
    const _daysFromMonday = (_dayNum + 6) % 7 // 월=0, 화=1, ..., 일=6
    const _kstMidnightToday = Date.UTC(nowKstMs.getUTCFullYear(), nowKstMs.getUTCMonth(), nowKstMs.getUTCDate())
    const _kstWeekStartMs = _kstMidnightToday - (_daysFromMonday * 24 * 60 * 60 * 1000)
    const _kstWeekEndMs = _kstWeekStartMs + (7 * 24 * 60 * 60 * 1000)
    // KST 자정을 UTC 로 다시 환산 (KST 자정 == UTC 전날 15:00) — created_at 비교용
    const weekStartUtc = new Date(_kstWeekStartMs - (9 * 60 * 60 * 1000)).toISOString().slice(0, 19).replace('T', ' ')
    const weekEndUtc = new Date(_kstWeekEndMs - (9 * 60 * 60 * 1000)).toISOString().slice(0, 19).replace('T', ' ')

    const existingWithdrawal = await db.prepare(`
      SELECT id, coin_type, amount, status, created_at FROM withdrawals
      WHERE user_id = ? AND created_at >= ? AND created_at < ?
      ORDER BY created_at DESC LIMIT 1
    `).bind(userId, weekStartUtc, weekEndUtc).first()

    if (existingWithdrawal) {
      return c.json({
        error: '이번 주 출금 신청은 이미 1회 접수되었습니다. 다음 주 금요일에 다시 신청 가능합니다.',
        already_requested: true,
        existing: existingWithdrawal,
        week_start_kst: weekStartUtc,
        week_end_kst: weekEndUtc
      }, 400)
    }

    // ★ 출금가능 컬럼만 차감 대상 — 회사 지급분(initial) 절대 제외 ★
    // QTA/QX/USDT: 출금가능(*_withdrawable) 컬럼 사용
    // QKEY: 데일리/매칭 출처만 존재 → 기존 qkey_balance 그대로
    const withdrawableField = coinType === 'QTA' ? 'qta_withdrawable' :
                              coinType === 'QX' ? 'qx_withdrawable' :
                              coinType === 'QKEY' ? 'qkey_balance' : 'usdt_withdrawable'
    // 표시용 총합 컬럼 (동기 차감 대상 — QTA/QX/USDT 만)
    const displayField = coinType === 'QTA' ? 'qta_balance' :
                         coinType === 'QX' ? 'qx_balance' :
                         coinType === 'QKEY' ? null : 'usdt_balance'

    const currentWithdrawable = Number(user[withdrawableField] || 0)

    // ★ 5% 출금 수수료 계산 (사장님 정책 2026-05-11 + #no-decimal 2026-05-26)
    //   Math.ceil — 수수료 올림 (사용자에게 유리한 방향 아니지만 정수 강제 + 잔액 정합 보장)
    const fee = Math.ceil(amount * WITHDRAWAL_FEE_RATE)         // 정수
    const netAmount = amount - fee                              // 정수 - 정수 = 정수
    // ★★★ 영구룰 #balance↔tx정합 (사장님 정책 2026-05-26) ★★★
    //   잔액에서 차감할 총량 = 신청액(amount) + 수수료(fee) — 모두 정수
    const totalRequired = amount + fee

    if (currentWithdrawable < totalRequired) {
      const coinLabel = coinType === 'QTA' ? 'QTA' : coinType === 'QX' ? 'QX' : coinType === 'QKEY' ? 'QKEY' : 'USDT'
      // 최대 출금 가능액 계산 (수수료 포함하여 잔액 내에서) — 모두 정수
      //   currentWithdrawable >= amount + ceil(amount*0.05) ≈ amount × 1.05
      //   amount ≤ floor(currentWithdrawable / 1.05)
      let maxWithdrawable = Math.floor(currentWithdrawable / (1 + WITHDRAWAL_FEE_RATE))
      // QTA/QX 의 경우 net 이 1000 배수 되도록 보정
      if (coinType === 'QTA' || coinType === 'QX') {
        // net = maxW - ceil(maxW*0.05) 를 1000 배수로 내림 후 gross 재계산
        const _maxNetRaw = maxWithdrawable - Math.ceil(maxWithdrawable * WITHDRAWAL_FEE_RATE)
        const _maxNet = Math.floor(_maxNetRaw / 1000) * 1000
        // gross = ceil(net / 0.95) — net 의 1000 배수에서 역산
        maxWithdrawable = _maxNet > 0 ? Math.ceil(_maxNet / (1 - WITHDRAWAL_FEE_RATE)) : 0
        // 재검증: 잔액 초과 시 한 단위(1000) 내려서 재시도
        while (maxWithdrawable > 0 && (maxWithdrawable + Math.ceil(maxWithdrawable * WITHDRAWAL_FEE_RATE)) > currentWithdrawable) {
          const _adjustedNet = _maxNet - 1000
          maxWithdrawable = _adjustedNet > 0 ? Math.ceil(_adjustedNet / (1 - WITHDRAWAL_FEE_RATE)) : 0
          if (_adjustedNet <= 0) break
        }
      }
      const _maxNetDisplay = maxWithdrawable - Math.ceil(maxWithdrawable * WITHDRAWAL_FEE_RATE)
      return c.json({
        error: `출금가능 ${coinLabel} 수량이 부족합니다. 출금가능 잔액 ${currentWithdrawable.toLocaleString()} ${coinLabel} / 신청 ${amount.toLocaleString()} ${coinLabel} + 수수료 5% ${fee.toLocaleString()} ${coinLabel} = 총 필요 ${totalRequired.toLocaleString()} ${coinLabel}. 최대 출금 가능: ${maxWithdrawable.toLocaleString()} ${coinLabel} (실수령 ${_maxNetDisplay.toLocaleString()} ${coinLabel}). 회사 최초 지급분은 출금 대상이 아닙니다.`,
        insufficient_with_fee: true,
        current_withdrawable: currentWithdrawable,
        requested_amount: amount,
        fee: fee,
        total_required: totalRequired,
        max_withdrawable: maxWithdrawable,
        max_net: _maxNetDisplay
      }, 400)
    }

    // 잔액 즉시 차감 — 출금가능 컬럼(필수) + 표시용 총합 컬럼(동기) 양쪽 차감
    //   ★ 영구룰 #balance↔tx정합: (amount + fee) 전체를 차감 → TX 합 = -(amount+fee) 와 정합
    //   경쟁조건 방지: 출금가능 컬럼 기준 UPDATE 결과 확인 (totalRequired 이상일 때만 차감)
    let deductResult
    if (displayField) {
      // QTA/QX/USDT: withdrawable + balance 양쪽에서 (amount + fee) 차감
      deductResult = await db.prepare(`
        UPDATE users
        SET ${withdrawableField} = ${withdrawableField} - ?,
            ${displayField} = ${displayField} - ?
        WHERE id = ? AND ${withdrawableField} >= ?
      `).bind(totalRequired, totalRequired, userId, totalRequired).run()
    } else {
      // QKEY: qkey_balance 에서 (amount + fee) 차감
      deductResult = await db.prepare(`
        UPDATE users SET qkey_balance = qkey_balance - ? WHERE id = ? AND qkey_balance >= ?
      `).bind(totalRequired, userId, totalRequired).run()
    }

    if (!deductResult.meta.changes || deductResult.meta.changes === 0) {
      return c.json({ error: t(c, 'withdrawal.insufficient_balance') }, 400)
    }

    // 출금 신청 생성 (수수료/실수령액 함께 저장)
    const withdrawalResult = await db.prepare(`
      INSERT INTO withdrawals (user_id, coin_type, amount, wallet_address, status, fee, net_amount, fee_rate)
      VALUES (?, ?, ?, ?, 'pending', ?, ?, ?)
    `).bind(userId, coinType, amount, walletAddress, fee, netAmount, WITHDRAWAL_FEE_RATE).run()

    // ★ 거래내역(transactions) 기록 — 사장님 .md 룰 준수 (사용자 노출 안전 한국어)
    //   1) 출금 신청 본 거래 (음수 amount, 신청 원본 수량)
    await db.prepare(`
      INSERT INTO transactions (user_id, type, coin_type, amount, description)
      VALUES (?, 'withdrawal', ?, ?, ?)
    `).bind(userId, coinType, -Math.abs(amount), '출금 신청').run()

    //   2) 출금 수수료 공제 거래 (음수 amount, 5%) — 사장님 명시 문구 그대로
    await db.prepare(`
      INSERT INTO transactions (user_id, type, coin_type, amount, description)
      VALUES (?, 'withdrawal_fee', ?, ?, ?)
    `).bind(userId, coinType, -Math.abs(fee), '출금수수료 공제 5%').run()

    return c.json({ 
      success: true, 
      message: t(c, 'withdrawal.request_success'),
      withdrawal: {
        id: withdrawalResult.meta.last_row_id,
        coinType: coinType,
        amount: amount,
        fee: fee,
        net_amount: netAmount,
        fee_rate: WITHDRAWAL_FEE_RATE,
        status: 'pending'
      }
    })
  } catch (error) {
    return c.json({ error: t(c, 'withdrawal.request_error') }, 500)
  }
})

// 출금 신청 창 상태 조회 (클라이언트 UI 동기화용)
// 룰: 매주 금요일 10:00~14:00 KST (공휴일 무관)
// ★ 사장님 2026-05-15 (5차) 지시: 2026-05-15 (금) 당일만 18:00 까지 연장 (10:00~18:00). 5/16부터 원래 룰 자동 복원.
app.get('/api/withdrawal/window', (c) => {
  const now = new Date()
  const kst = new Date(now.getTime() + (9 * 60 * 60 * 1000))
  const todayKst = kst.toISOString().split('T')[0]
  const day = kst.getUTCDay()
  const hour = kst.getUTCHours()
  const minute = kst.getUTCMinutes()
  // 1회성 예외: 2026-05-15 (금) → 10:00 ~ 18:00 (사장님 직접 지시, 매우 중요)
  const isMay15 = todayKst === '2026-05-15'
  const closeHourEffective = isMay15 ? 18 : 14
  const isOpen = day === 5 && hour >= 10 && hour < closeHourEffective
  // 다음 금요일 날짜 계산 (안내용)
  let diffToNextFriday: number
  if (day < 5) diffToNextFriday = 5 - day
  else if (day === 5) diffToNextFriday = 0
  else diffToNextFriday = 6 // 토요일이면 다음 주 금요일
  const nextFriday = new Date(kst.getTime() + diffToNextFriday * 24 * 60 * 60 * 1000)
  return c.json({
    success: true,
    isOpen,
    todayKst,
    withdrawalDate: nextFriday.toISOString().split('T')[0],
    hour,
    minute,
    openHour: 10,
    closeHour: closeHourEffective
  })
})

// 출금 신청 목록 조회
app.get('/api/withdrawal/list/:userId', async (c) => {
  try {
    const userId = c.req.param('userId')
    const db = c.env.DB

    const withdrawals = await db.prepare(`
      SELECT * FROM withdrawals
      WHERE user_id = ?
      ORDER BY created_at DESC
    `).bind(userId).all()

    return c.json({ 
      success: true, 
      withdrawals: withdrawals.results 
    })
  } catch (error) {
    return c.json({ error: t(c, 'withdrawal.list_error') }, 500)
  }
})

// 사용자: 출금 신청 취소 (pending 상태에서만, 차감된 잔액 즉시 환불)
app.post('/api/withdrawal/cancel/:withdrawalId', async (c) => {
  try {
    const db = c.env.DB
    const withdrawalId = c.req.param('withdrawalId')
    const body = await c.req.json().catch(() => ({}))
    const userId = body?.userId

    if (!userId) return c.json({ error: '사용자 정보가 필요합니다' }, 400)

    // cancelled_at / cancelled_by 컬럼 보장
    try { await db.prepare(`ALTER TABLE withdrawals ADD COLUMN cancelled_at DATETIME`).run() } catch(e) {}
    try { await db.prepare(`ALTER TABLE withdrawals ADD COLUMN cancelled_by TEXT`).run() } catch(e) {}

    // 본인 소유 + pending 상태인 출금건만 취소 가능
    const withdrawal = await db.prepare(`
      SELECT * FROM withdrawals WHERE id = ? AND user_id = ?
    `).bind(withdrawalId, userId).first()

    if (!withdrawal) {
      return c.json({ error: '출금 신청을 찾을 수 없습니다' }, 404)
    }
    if (withdrawal.status !== 'pending') {
      const labelMap: Record<string,string> = { approved: '승인완료', rejected: '거절됨', cancelled: '이미 취소됨' }
      return c.json({ error: `취소할 수 없는 상태입니다 (현재: ${labelMap[withdrawal.status as string] || withdrawal.status}). 처리 전(pending) 상태에서만 취소 가능합니다.` }, 400)
    }

    // 상태 변경 (경쟁조건 방지: pending 상태에서만)
    const upd = await db.prepare(`
      UPDATE withdrawals SET status = 'cancelled', cancelled_at = CURRENT_TIMESTAMP, cancelled_by = 'user'
      WHERE id = ? AND status = 'pending'
    `).bind(withdrawalId).run()

    if (!upd.meta.changes) {
      return c.json({ error: '이미 처리된 신청입니다' }, 400)
    }

    // ★★★ 영구룰 #balance↔tx정합 (사장님 정책 2026-05-26) ★★★
    //   차감했던 잔액 복원 = (amount + fee) 전체 환불 (차감 시 totalRequired 차감했으므로)
    //   출금가능 컬럼 + 표시용 총합 양쪽 복원
    await ensureWithdrawableSchema(db)
    const coin = withdrawal.coin_type as string
    const wField = coin === 'QTA' ? 'qta_withdrawable' :
                   coin === 'QX' ? 'qx_withdrawable' :
                   coin === 'QKEY' ? 'qkey_balance' : 'usdt_withdrawable'
    const dField = coin === 'QTA' ? 'qta_balance' :
                   coin === 'QX' ? 'qx_balance' :
                   coin === 'QKEY' ? null : 'usdt_balance'
    const feeValue = ((withdrawal as any).fee || 0) as number
    // 영구룰 #no-decimal — 환불액도 정수 강제 (구 데이터 소수 → 올림)
    const refundAmount = Math.ceil((withdrawal.amount as number) + feeValue)
    if (dField) {
      await db.prepare(`
        UPDATE users SET ${wField} = COALESCE(${wField},0) + ?, ${dField} = ${dField} + ? WHERE id = ?
      `).bind(refundAmount, refundAmount, withdrawal.user_id).run()
    } else {
      await db.prepare(`
        UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?
      `).bind(refundAmount, withdrawal.user_id).run()
    }

    // 환불 거래 기록 — 본 거래 환불 + 수수료 환불 분리 (영구룰 #balance↔tx정합)
    try {
      // 1) 신청 원본 수량 환불
      await db.prepare(`
        INSERT INTO transactions (user_id, type, coin_type, amount, description)
        VALUES (?, 'withdrawal_cancel_refund', ?, ?, ?)
      `).bind(
        withdrawal.user_id,
        withdrawal.coin_type,
        withdrawal.amount,
        `출금 신청 취소 환불 (#${withdrawalId})`
      ).run()
      // 2) 수수료 환불 (fee 컬럼이 있을 때만)
      if (feeValue > 0) {
        await db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description)
          VALUES (?, 'withdrawal_fee_refund', ?, ?, ?)
        `).bind(
          withdrawal.user_id,
          withdrawal.coin_type,
          Math.abs(feeValue),
          `출금수수료 환불 5% (#${withdrawalId} 취소)`
        ).run()
      }
    } catch(eTx) {}

    return c.json({
      success: true,
      message: `출금 신청이 취소되었습니다. ${Number(withdrawal.amount).toLocaleString()} ${withdrawal.coin_type}가 즉시 환불되었습니다.`,
      refunded: withdrawal.amount,
      coinType: withdrawal.coin_type
    })
  } catch (error) {
    return c.json({ error: '출금 취소 처리 중 오류가 발생했습니다' }, 500)
  }
})

// ============================================
// API Routes - Swap (QKEY → USDT)
// ============================================

// QKEY → USDT 스왑 (150 QKEY = 1 USDT, 최소 100 USDT, 100 단위)
app.post('/api/swap/qkey-to-usdt', async (c) => {
  try {
    const { userId, amount } = await c.req.json() // amount = 받고 싶은 USDT 수량
    const QKEY_PER_USDT = 150 // 150 QKEY = 1 USDT

    if (!userId || !amount) {
      return c.json({ error: t(c, 'profile.required_fields') }, 400)
    }

    // ★ 사장님 2026-05-15 지시: 쿠키코인(QKEY) 보유 수량 기준 USDT 스왑 가능
    //   기존 최소 100 / 100 단위 제한 완화 → 최소 1 USDT 부터 1 단위로 스왑 허용
    //   (출금 시점의 최소 100 USDT 가드는 그대로 유지)
    if (amount < 1) {
      return c.json({ error: t(c, 'swap.min_amount') }, 400)
    }
    if (!Number.isInteger(amount) || amount <= 0) {
      return c.json({ error: t(c, 'swap.unit_error') }, 400)
    }

    const requiredQkey = amount * QKEY_PER_USDT // 필요한 QKEY 수량

    const db = c.env.DB

    // 사용자 QKEY 잔액 확인
    const user = await db.prepare(`
      SELECT qkey_balance FROM users WHERE id = ?
    `).bind(userId).first()

    if (!user) {
      return c.json({ error: t(c, 'withdrawal.user_not_found') }, 404)
    }

    const qkeyBalance = user.qkey_balance || 0

    // QKEY 잔액 부족 체크
    if (qkeyBalance < requiredQkey) {
      return c.json({ error: `${t(c, 'swap.insufficient_qkey')} (${qkeyBalance.toLocaleString()} QKEY / ${requiredQkey.toLocaleString()} QKEY)` }, 400)
    }

    // QKEY 차감 & USDT 증가 (150 QKEY = 1 USDT) - 경쟁조건 방지
    // ★ 영구정책 (2026-05-14): QKEY(데일리/매칭/추천 출처)→USDT 스왑 결과는 출금 가능 → usdt_withdrawable 누적
    await ensureWithdrawableSchema(db)
    const swapResult = await db.prepare(`
      UPDATE users 
      SET qkey_balance = qkey_balance - ?,
          usdt_balance = usdt_balance + ?,
          usdt_withdrawable = COALESCE(usdt_withdrawable,0) + ?
      WHERE id = ? AND qkey_balance >= ?
    `).bind(requiredQkey, amount, amount, userId, requiredQkey).run()

    if (!swapResult.meta.changes || swapResult.meta.changes === 0) {
      return c.json({ error: `${t(c, 'swap.insufficient_qkey')} (concurrent request)` }, 400)
    }

    // 거래 내역 기록 (QKEY 차감) — ★ 출금성 거래는 음수로 저장 (잔액=tx_sum 정합성)
    await db.prepare(`
      INSERT INTO transactions (user_id, type, coin_type, amount, description)
      VALUES (?, 'swap_out', 'QKEY', ?, ?)
    `).bind(userId, -Math.abs(requiredQkey), `QKEY → USDT swap (${requiredQkey.toLocaleString()} QKEY → ${amount.toLocaleString()} USDT)`).run()

    // Transaction record (USDT increase)
    await db.prepare(`
      INSERT INTO transactions (user_id, type, coin_type, amount, description)
      VALUES (?, 'swap_in', 'USDT', ?, ?)
    `).bind(userId, amount, `QKEY → USDT swap (${requiredQkey.toLocaleString()} QKEY → ${amount.toLocaleString()} USDT)`).run()

    return c.json({ 
      success: true, 
      message: `${t(c, 'swap.success')} (${requiredQkey.toLocaleString()} QKEY → ${amount.toLocaleString()} USDT)`,
      swap: {
        from: 'QKEY',
        to: 'USDT',
        qkeyUsed: requiredQkey,
        usdtReceived: amount
      }
    })
  } catch (error) {
    console.error('Swap error:', error)
    return c.json({ error: t(c, 'swap.error') }, 500)
  }
})

// QKEY → QTA 스왑 (1:1, QKEY 1개 = QTA 1개)
app.post('/api/swap/qkey-to-qta', async (c) => {
  try {
    const { userId, amount } = await c.req.json() // amount = 받고 싶은 QTA 수량
    if (!userId || !amount || amount <= 0) {
      return c.json({ error: t(c, 'profile.required_fields') }, 400)
    }
    const requiredQkey = amount // 1:1 비율

    const db = c.env.DB
    const user = await db.prepare(`SELECT qkey_balance FROM users WHERE id = ?`).bind(userId).first()
    if (!user) return c.json({ error: t(c, 'withdrawal.user_not_found') }, 404)

    if ((user.qkey_balance || 0) < requiredQkey) {
      return c.json({ error: `${t(c, 'swap.insufficient_qkey')} (${(user.qkey_balance || 0).toLocaleString()} QKEY / ${requiredQkey.toLocaleString()} QKEY)` }, 400)
    }

    // ★ 영구정책 (2026-05-14): QKEY → QTA 스왑 시 데일리/매칭 출처 → qta_withdrawable 누적 (출금 가능)
    await ensureWithdrawableSchema(db)
    // QKEY 차감 & QTA 증가 (qta_balance 표시용 + qta_withdrawable 출금가능) - 경쟁조건 방지
    const swapQtaResult = await db.prepare(`
      UPDATE users
      SET qkey_balance = qkey_balance - ?,
          qta_balance = qta_balance + ?,
          qta_withdrawable = COALESCE(qta_withdrawable,0) + ?
      WHERE id = ? AND qkey_balance >= ?
    `).bind(requiredQkey, amount, amount, userId, requiredQkey).run()
    if (!swapQtaResult.meta.changes || swapQtaResult.meta.changes === 0) {
      return c.json({ error: `${t(c, 'swap.insufficient_qkey')} (concurrent request)` }, 400)
    }

    // ★ 스왑 거래내역 보강 (영구룰 #112 한국어 안전 + ref_id dedupe + 실패 시 rollback)
    const swapTs = Date.now()
    const refOut = `swap_${userId}_${swapTs}_out`
    const refIn = `swap_${userId}_${swapTs}_in`
    const descKor = `QKEY → QTA 스왑 (${requiredQkey.toLocaleString()} QKEY → ${amount.toLocaleString()} QTA)`
    try {
      // 거래 내역 (QKEY 차감) — ★ 출금성 거래는 음수로 저장
      await db.prepare(`INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id) VALUES (?, 'swap_out', 'QKEY', ?, ?, ?)`).bind(userId, -Math.abs(requiredQkey), descKor, refOut).run()
      // 거래 내역 (QTA 증가 - swap_in으로 기록 → 출금 가능 수량에 반영)
      await db.prepare(`INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id) VALUES (?, 'swap_in', 'QTA', ?, ?, ?)`).bind(userId, amount, descKor, refIn).run()
    } catch (txErr) {
      // tx INSERT 실패 시 잔액 역방향 rollback (스왑 로직 보강 #4) — withdrawable 도 rollback
      await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ?, qta_balance = qta_balance - ?, qta_withdrawable = COALESCE(qta_withdrawable,0) - ? WHERE id = ?`).bind(requiredQkey, amount, amount, userId).run()
      console.error('swap qkey->qta tx insert failed, balance rolled back:', txErr)
      return c.json({ error: '스왑 거래내역 기록 실패 — 잔액 원복되었습니다. 다시 시도해주세요.' }, 500)
    }

    return c.json({ success: true, message: `${requiredQkey.toLocaleString()} QKEY → ${amount.toLocaleString()} QTA`, swap: { from: 'QKEY', to: 'QTA', qkeyUsed: requiredQkey, received: amount, ref_id: refOut } })
  } catch (error) {
    return c.json({ error: t(c, 'swap.error') }, 500)
  }
})

// QKEY → QX 스왑 (5:1, QKEY 5개 = QX 1개)
app.post('/api/swap/qkey-to-qx', async (c) => {
  try {
    const { userId, amount } = await c.req.json() // amount = 받고 싶은 QX 수량
    if (!userId || !amount || amount <= 0) {
      return c.json({ error: t(c, 'profile.required_fields') }, 400)
    }
    const requiredQkey = amount * 5 // 5:1 비율

    const db = c.env.DB
    const user = await db.prepare(`SELECT qkey_balance FROM users WHERE id = ?`).bind(userId).first()
    if (!user) return c.json({ error: t(c, 'withdrawal.user_not_found') }, 404)

    if ((user.qkey_balance || 0) < requiredQkey) {
      return c.json({ error: `${t(c, 'swap.insufficient_qkey')} (${(user.qkey_balance || 0).toLocaleString()} QKEY / ${requiredQkey.toLocaleString()} QKEY)` }, 400)
    }

    // ★ 영구정책 (2026-05-14): QKEY → QX 스왑 시 데일리/매칭 출처 → qx_withdrawable 누적 (출금 가능)
    await ensureWithdrawableSchema(db)
    const swapQxResult = await db.prepare(`
      UPDATE users
      SET qkey_balance = qkey_balance - ?,
          qx_balance = qx_balance + ?,
          qx_withdrawable = COALESCE(qx_withdrawable,0) + ?
      WHERE id = ? AND qkey_balance >= ?
    `).bind(requiredQkey, amount, amount, userId, requiredQkey).run()
    if (!swapQxResult.meta.changes || swapQxResult.meta.changes === 0) {
      return c.json({ error: `${t(c, 'swap.insufficient_qkey')} (concurrent request)` }, 400)
    }

    // ★ 스왑 거래내역 보강 (영구룰 #112 한국어 + ref_id dedupe + 실패 시 rollback)
    const swapTs = Date.now()
    const refOut = `swap_${userId}_${swapTs}_out`
    const refIn = `swap_${userId}_${swapTs}_in`
    const descKor = `QKEY → QX 스왑 (${requiredQkey.toLocaleString()} QKEY → ${amount.toLocaleString()} QX)`
    try {
      // ★ 출금성 거래는 음수로 저장 (잔액=tx_sum 정합성)
      await db.prepare(`INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id) VALUES (?, 'swap_out', 'QKEY', ?, ?, ?)`).bind(userId, -Math.abs(requiredQkey), descKor, refOut).run()
      await db.prepare(`INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id) VALUES (?, 'swap_in', 'QX', ?, ?, ?)`).bind(userId, amount, descKor, refIn).run()
    } catch (txErr) {
      await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ?, qx_balance = qx_balance - ?, qx_withdrawable = COALESCE(qx_withdrawable,0) - ? WHERE id = ?`).bind(requiredQkey, amount, amount, userId).run()
      console.error('swap qkey->qx tx insert failed, balance rolled back:', txErr)
      return c.json({ error: '스왑 거래내역 기록 실패 — 잔액 원복되었습니다. 다시 시도해주세요.' }, 500)
    }

    return c.json({ success: true, message: `${requiredQkey.toLocaleString()} QKEY → ${amount.toLocaleString()} QX`, swap: { from: 'QKEY', to: 'QX', qkeyUsed: requiredQkey, received: amount, ref_id: refOut } })
  } catch (error) {
    return c.json({ error: t(c, 'swap.error') }, 500)
  }
})

// USDT → QKEY 스왑 (1 USDT = 150 QKEY, 역방향)
app.post('/api/swap/usdt-to-qkey', async (c) => {
  try {
    const { userId, amount } = await c.req.json() // amount = 사용할 USDT 수량
    if (!userId || !amount || amount <= 0) {
      return c.json({ error: t(c, 'profile.required_fields') }, 400)
    }
    const qkeyToReceive = amount * 150 // 1 USDT = 150 QKEY

    const db = c.env.DB
    const user = await db.prepare(`SELECT usdt_balance FROM users WHERE id = ?`).bind(userId).first()
    if (!user) return c.json({ error: t(c, 'withdrawal.user_not_found') }, 404)

    if ((user.usdt_balance || 0) < amount) {
      return c.json({ error: `USDT 잔액이 부족합니다 (${(user.usdt_balance || 0).toFixed(2)} USDT / ${amount.toFixed(2)} USDT)` }, 400)
    }

    // ★ 영구정책: USDT 는 데일리/매칭 출처 스왑으로만 생김 → usdt_withdrawable 함께 차감
    await ensureWithdrawableSchema(db)
    const swapUkResult = await db.prepare(`
      UPDATE users
      SET usdt_balance = usdt_balance - ?,
          usdt_withdrawable = MAX(COALESCE(usdt_withdrawable,0) - ?, 0),
          qkey_balance = qkey_balance + ?
      WHERE id = ? AND usdt_balance >= ?
    `).bind(amount, amount, qkeyToReceive, userId, amount).run()
    if (!swapUkResult.meta.changes || swapUkResult.meta.changes === 0) {
      return c.json({ error: `USDT 잔액이 부족합니다 (concurrent request)` }, 400)
    }

    // ★ 스왑 거래내역 보강 (영구룰 #112 한국어 + ref_id dedupe + 실패 시 rollback)
    const swapTs = Date.now()
    const refOut = `swap_${userId}_${swapTs}_out`
    const refIn = `swap_${userId}_${swapTs}_in`
    const descKor = `USDT → QKEY 스왑 (${amount.toLocaleString()} USDT → ${qkeyToReceive.toLocaleString()} QKEY)`
    try {
      // ★ 출금성 거래는 음수로 저장 (잔액=tx_sum 정합성)
      await db.prepare(`INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id) VALUES (?, 'swap_out', 'USDT', ?, ?, ?)`).bind(userId, -Math.abs(amount), descKor, refOut).run()
      await db.prepare(`INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id) VALUES (?, 'swap_in', 'QKEY', ?, ?, ?)`).bind(userId, qkeyToReceive, descKor, refIn).run()
    } catch (txErr) {
      await db.prepare(`UPDATE users SET usdt_balance = usdt_balance + ?, qkey_balance = qkey_balance - ? WHERE id = ?`).bind(amount, qkeyToReceive, userId).run()
      console.error('swap usdt->qkey tx insert failed, balance rolled back:', txErr)
      return c.json({ error: '스왑 거래내역 기록 실패 — 잔액 원복되었습니다. 다시 시도해주세요.' }, 500)
    }

    return c.json({ success: true, message: `${amount.toLocaleString()} USDT → ${qkeyToReceive.toLocaleString()} QKEY`, swap: { from: 'USDT', to: 'QKEY', usdtUsed: amount, received: qkeyToReceive, ref_id: refOut } })
  } catch (error) {
    return c.json({ error: t(c, 'swap.error') }, 500)
  }
})

