// 전체 매출 현황 (아이디/이름/판매금액/판매일)
app.get('/api/admin/sales', async (c) => {
  try {
    const db = c.env.DB
    // 어드민용 매출 목록: 리셋된 항목도 함께 반환하되 reset_at 컬럼으로 식별 가능하게 함
    const sales = await db.prepare(`
      SELECT 
        s.id as staking_id,
        u.id as user_id,
        u.email,
        u.name,
        u.country,
        u.language,
        s.amount,
        s.status,
        s.created_at as sale_date,
        s.start_date,
        s.end_date,
        s.period_days,
        s.daily_rate,
        s.reset_at
      FROM staking s
      JOIN users u ON s.user_id = u.id
      WHERE s.status IN ('active', 'completed')
      ORDER BY s.created_at DESC
    `).all()

    // 총 매출 집계 (전체)
    const totalSales = await db.prepare(`
      SELECT 
        COALESCE(SUM(amount), 0) as total_amount,
        COUNT(*) as total_count
      FROM staking WHERE status IN ('active', 'completed')
    `).first()

    const todaySales = await db.prepare(`
      SELECT COALESCE(SUM(amount), 0) as amount, COUNT(*) as count
      FROM staking WHERE status IN ('active', 'completed') AND DATE(start_date) = DATE('now')
    `).first()

    const weekSales = await db.prepare(`
      SELECT COALESCE(SUM(amount), 0) as amount, COUNT(*) as count
      FROM staking WHERE status IN ('active', 'completed') AND start_date >= DATE('now', '-7 days')
    `).first()

    const monthSales = await db.prepare(`
      SELECT COALESCE(SUM(amount), 0) as amount, COUNT(*) as count
      FROM staking WHERE status IN ('active', 'completed') AND start_date >= DATE('now', '-30 days')
    `).first()

    // 리셋된(=어드민 강제 리셋 처리된) 매출 별도 집계
    const resetSales = await db.prepare(`
      SELECT 
        COALESCE(SUM(amount), 0) as amount,
        COUNT(*) as count
      FROM staking
      WHERE status IN ('active', 'completed') AND reset_at IS NOT NULL
    `).first()

    // 정상(=리셋되지 않은) 매출 별도 집계
    const activeSales = await db.prepare(`
      SELECT 
        COALESCE(SUM(amount), 0) as amount,
        COUNT(*) as count
      FROM staking
      WHERE status IN ('active', 'completed') AND reset_at IS NULL
    `).first()

    return c.json({
      success: true,
      stats: {
        totalAmount: totalSales?.total_amount || 0,
        totalCount: totalSales?.total_count || 0,
        todayAmount: todaySales?.amount || 0,
        todayCount: todaySales?.count || 0,
        weekAmount: weekSales?.amount || 0,
        weekCount: weekSales?.count || 0,
        monthAmount: monthSales?.amount || 0,
        monthCount: monthSales?.count || 0,
        // 리셋 분리 통계
        activeAmount: activeSales?.amount || 0,
        activeCount: activeSales?.count || 0,
        resetAmount: resetSales?.amount || 0,
        resetCount: resetSales?.count || 0
      },
      sales: sales.results
    })
  } catch (error) {
    return c.json({ error: t(c, 'admin.sales_error') }, 500)
  }
})

// ★★★ [요구사항 #1 / 2026-07-03] 승인처리되어 활성화된 매출건 삭제 ★★★
//   삭제 시 이 매출로 지급된 모든 코인을 즉시 회수:
//   (A) 본인: 승인 코인(QTA/QX/QKEY) 원복 + initial 대칭 차감, staking_reward 거래내역 삭제
//   (B) 본인: 일일배당(QKEY) 전액 회수(daily_rewards.usdt_amount 합산) + daily_qkey 거래내역/원장 삭제
//   (C)+(D) 위/아래(추천인): 직접추천수당(level0) + 매칭수당(level1·2) 회수 + 관련 거래내역/원장 삭제
//   ※ referral_rewards.staking_id 가 NULL 인 legacy row 는 특정 매출 귀속 불가 → 과다회수 방지 위해 회수 제외
app.delete('/api/admin/sales/:stakingId', async (c) => {
  try {
    const db = c.env.DB
    const stakingId = c.req.param('stakingId')

    // 대상 매출(스테이킹) 조회 — active/completed 만 삭제 대상 (pending 은 reject 사용)
    const staking = await db.prepare(`
      SELECT * FROM staking WHERE id = ? AND status IN ('active', 'completed')
    `).bind(stakingId).first()

    if (!staking) {
      return c.json({ error: t(c, 'admin.sales_delete_not_found') }, 404)
    }

    const userId = staking.user_id
    const qtaReward = staking.qta_reward || 0
    const qxReward = staking.qx_reward || 0
    const qkeyReward = staking.qkey_reward || 0

    await ensureWithdrawableSchema(db)

    // 집계용 (응답 리포트)
    let recoveredDailyQkey = 0
    let recoveredReferralQkey = 0
    const referralRecipients: any[] = []

    // ─────────────────────────────────────────────────────────────
    // (A) 본인 : 승인 시 지급 코인 원복 (QTA/QX/QKEY) — initial 컬럼도 대칭 차감
    // ─────────────────────────────────────────────────────────────
    if (qtaReward > 0) {
      await db.prepare(`
        UPDATE users
        SET qta_balance = MAX(0, qta_balance - ?),
            qta_initial = MAX(0, COALESCE(qta_initial,0) - ?)
        WHERE id = ?
      `).bind(qtaReward, qtaReward, userId).run()
    }
    if (qxReward > 0) {
      await db.prepare(`
        UPDATE users
        SET qx_balance = MAX(0, qx_balance - ?),
            qx_initial = MAX(0, COALESCE(qx_initial,0) - ?)
        WHERE id = ?
      `).bind(qxReward, qxReward, userId).run()
    }
    if (qkeyReward > 0) {
      await db.prepare(`
        UPDATE users SET qkey_balance = MAX(0, qkey_balance - ?) WHERE id = ?
      `).bind(qkeyReward, userId).run()
    }
    // 승인 보상 transactions(staking_reward) 코인별 1건씩 정리 (금액 정확 매칭)
    async function deleteOneStakingRewardTx(coin: string, amt: number) {
      if (!(amt > 0)) return
      try {
        await db.prepare(`
          DELETE FROM transactions
          WHERE ROWID = (
            SELECT ROWID FROM transactions
            WHERE user_id = ? AND type = 'staking_reward' AND coin_type = ? AND amount = ?
            ORDER BY id DESC LIMIT 1
          )
        `).bind(userId, coin, amt).run()
      } catch (e) { }
    }
    await deleteOneStakingRewardTx('QTA', qtaReward)
    await deleteOneStakingRewardTx('QX', qxReward)
    await deleteOneStakingRewardTx('QKEY', qkeyReward)

    // ─────────────────────────────────────────────────────────────
    // (B) 본인 : 이 스테이킹 일일배당(QKEY) 전액 회수
    //     daily_rewards.usdt_amount 에 실제 지급 QKEY 가 저장됨 → 합산해서 본인 잔액에서 차감
    // ─────────────────────────────────────────────────────────────
    try {
      const dailySum = await db.prepare(`
        SELECT COALESCE(SUM(usdt_amount), 0) as total
        FROM daily_rewards WHERE staking_id = ?
      `).bind(stakingId).first()
      recoveredDailyQkey = (dailySum && (dailySum.total as number)) || 0

      if (recoveredDailyQkey > 0) {
        await db.prepare(`
          UPDATE users SET qkey_balance = MAX(0, qkey_balance - ?) WHERE id = ?
        `).bind(recoveredDailyQkey, userId).run()
      }

      // daily_qkey transactions 삭제 (ref_id = daily_rewards.id)
      await db.prepare(`
        DELETE FROM transactions
        WHERE type = 'daily_qkey' AND ref_id IN (
          SELECT id FROM daily_rewards WHERE staking_id = ?
        )
      `).bind(stakingId).run()

      // daily_rewards ledger 삭제
      await db.prepare(`DELETE FROM daily_rewards WHERE staking_id = ?`).bind(stakingId).run()
    } catch (e) { }

    // ─────────────────────────────────────────────────────────────
    // (C)+(D) 위·아래 : 추천/매칭 보상(QKEY) 회수
    //     referral_rewards where staking_id = X → referrer_id 별로 reward_amount 합산해 각자 회수
    //     (level 0 = 직접추천수당 / level 1·2 = 매칭수당)  ledger + transactions 함께 삭제
    // ─────────────────────────────────────────────────────────────
    try {
      const rrRows = await db.prepare(`
        SELECT referrer_id, level, COALESCE(SUM(reward_amount),0) as total
        FROM referral_rewards
        WHERE staking_id = ?
        GROUP BY referrer_id, level
      `).bind(stakingId).all()

      // referrer_id 별 총 회수액 합산
      const byRecipient: Record<string, number> = {}
      for (const r of (rrRows.results as any[])) {
        const rid = String(r.referrer_id)
        byRecipient[rid] = (byRecipient[rid] || 0) + (r.total || 0)
        recoveredReferralQkey += (r.total || 0)
      }

      // 각 수령인 잔액에서 차감
      for (const rid of Object.keys(byRecipient)) {
        const amt = byRecipient[rid]
        if (amt > 0) {
          await db.prepare(`
            UPDATE users SET qkey_balance = MAX(0, qkey_balance - ?) WHERE id = ?
          `).bind(amt, rid).run()
          referralRecipients.push({ userId: Number(rid), recoveredQkey: amt })
        }
      }

      // 관련 transactions 삭제 (direct_referral level0 / referral_reward level1·2)
      //   ref_id = referral_rewards.id 로 1:1 매핑되어 있음
      await db.prepare(`
        DELETE FROM transactions
        WHERE type IN ('direct_referral', 'referral_reward')
          AND ref_id IN (
            SELECT id FROM referral_rewards WHERE staking_id = ?
          )
      `).bind(stakingId).run()

      // referral_rewards ledger 삭제
      await db.prepare(`DELETE FROM referral_rewards WHERE staking_id = ?`).bind(stakingId).run()
    } catch (e) { }

    // ─────────────────────────────────────────────────────────────
    // 마지막: staking row 삭제
    // ─────────────────────────────────────────────────────────────
    await db.prepare(`DELETE FROM staking WHERE id = ?`).bind(stakingId).run()

    return c.json({
      success: true,
      message: t(c, 'admin.sales_delete_success'),
      deleted: {
        stakingId: stakingId,
        userId: userId,
        amount: staking.amount,
        reversed: {
          self: { qta: qtaReward, qx: qxReward, qkey: qkeyReward },
          selfDailyQkey: recoveredDailyQkey,
          referralQkeyTotal: recoveredReferralQkey,
          referralRecipients: referralRecipients
        }
      }
    })
  } catch (error) {
    return c.json({ error: t(c, 'admin.sales_delete_error') }, 500)
  }
})

// 회원 산하 매출 조회 (1대/2대/전체)
app.get('/api/admin/downline-sales/:userId', async (c) => {
  try {
    const userId = c.req.param('userId')
    const db = c.env.DB

    // 해당 회원 정보
    const user = await db.prepare('SELECT id, name, email, referral_code FROM users WHERE id = ?').bind(userId).first()
    if (!user) return c.json({ error: t(c, 'admin.member_not_found') }, 404)

    // 1대 (직접 추천) 산하
    const level1Users = await db.prepare(`
      SELECT u.id, u.name, u.email, u.country, u.language, u.created_at,
        COALESCE(SUM(CASE WHEN s.status IN ('active','completed') THEN s.amount ELSE 0 END), 0) as staking_amount
      FROM users u
      LEFT JOIN staking s ON u.id = s.user_id
      WHERE u.referrer_id = ?
      GROUP BY u.id, u.name, u.email, u.country, u.language, u.created_at
      ORDER BY staking_amount DESC
    `).bind(userId).all()

    // 1대 산하 ID 목록
    const level1Ids = (level1Users.results || []).map((u: any) => u.id)

    // 2대 (간접 추천) 산하
    let level2Users = { results: [] as any[] }
    if (level1Ids.length > 0) {
      const placeholders = level1Ids.map(() => '?').join(',')
      level2Users = await db.prepare(`
        SELECT u.id, u.name, u.email, u.country, u.language, u.created_at,
          COALESCE(SUM(CASE WHEN s.status IN ('active','completed') THEN s.amount ELSE 0 END), 0) as staking_amount,
          r.name as referrer_name
        FROM users u
        LEFT JOIN staking s ON u.id = s.user_id
        LEFT JOIN users r ON u.referrer_id = r.id
        WHERE u.referrer_id IN (${placeholders})
        GROUP BY u.id, u.name, u.email, u.country, u.language, u.created_at, r.name
        ORDER BY staking_amount DESC
      `).bind(...level1Ids).all()
    }

    // 집계
    const level1Total = (level1Users.results || []).reduce((sum: number, u: any) => sum + (u.staking_amount || 0), 0)
    const level2Total = (level2Users.results || []).reduce((sum: number, u: any) => sum + (u.staking_amount || 0), 0)

    return c.json({
      success: true,
      user: { id: user.id, name: user.name, email: user.email, referral_code: user.referral_code },
      level1: {
        count: level1Users.results?.length || 0,
        totalAmount: level1Total,
        users: level1Users.results
      },
      level2: {
        count: level2Users.results?.length || 0,
        totalAmount: level2Total,
        users: level2Users.results
      },
      grandTotal: level1Total + level2Total
    })
  } catch (error) {
    return c.json({ error: t(c, 'admin.downline_error') }, 500)
  }
})

// 회원 검색 API (이메일/이름으로 검색)
app.get('/api/admin/search-user', async (c) => {
  try {
    const query = c.req.query('q') || ''
    if (!query || query.length < 1) {
      return c.json({ error: t(c, 'admin.search_required') }, 400)
    }
    const db = c.env.DB
    const searchTerm = '%' + query + '%'
    const users = await db.prepare(`
      SELECT u.id, u.name, u.email, u.country, u.language, u.referral_code, u.created_at,
        COALESCE(SUM(CASE WHEN s.status IN ('active','completed') THEN s.amount ELSE 0 END), 0) as staking_amount
      FROM users u
      LEFT JOIN staking s ON u.id = s.user_id
      WHERE u.email LIKE ? OR u.name LIKE ? OR u.referral_code LIKE ?
      GROUP BY u.id, u.name, u.email, u.country, u.language, u.referral_code, u.created_at
      ORDER BY staking_amount DESC
      LIMIT 20
    `).bind(searchTerm, searchTerm, searchTerm).all()

    return c.json({ success: true, users: users.results })
  } catch (error) {
    return c.json({ error: t(c, 'admin.search_error') }, 500)
  }
})

// 회원 전체 수당 체크 (모든 회원의 보상 현황)
app.get('/api/admin/member-rewards', async (c) => {
  try {
    const db = c.env.DB

    // 회원별 전체 수당 집계
    const memberRewards = await db.prepare(`
      SELECT 
        u.id, u.name, u.email, u.country, u.language,
        u.qta_balance, u.qx_balance, u.qkey_balance, u.usdt_balance,
        COALESCE(SUM(CASE WHEN s.status IN ('active','completed') THEN s.amount ELSE 0 END), 0) as staking_amount,
        COALESCE(dr.daily_total, 0) as daily_reward_total,
        COALESCE(rr.referral_total, 0) as referral_reward_total,
        COALESCE(dr.daily_total, 0) + COALESCE(rr.referral_total, 0) as total_reward
      FROM users u
      LEFT JOIN staking s ON u.id = s.user_id
      LEFT JOIN (
        SELECT user_id, SUM(usdt_amount) as daily_total FROM daily_rewards GROUP BY user_id
      ) dr ON u.id = dr.user_id
      LEFT JOIN (
        SELECT referrer_id, SUM(reward_amount) as referral_total FROM referral_rewards GROUP BY referrer_id
      ) rr ON u.id = rr.referrer_id
      GROUP BY u.id, u.name, u.email, u.country, u.language,
               u.qta_balance, u.qx_balance, u.qkey_balance, u.usdt_balance,
               dr.daily_total, rr.referral_total
      ORDER BY total_reward DESC
    `).all()

    // ===== 영구룰 #cap200정책 — staking별 CAP % 계산 (READ-ONLY) =====
    // 1) 모든 staking 조회 (active/completed/capped 모두 포함, FIFO 정렬: user_id ASC, start_date ASC)
    const allStakings = await db.prepare(`
      SELECT id, user_id, amount, status, start_date
      FROM staking
      WHERE status IN ('active','completed','capped')
      ORDER BY user_id ASC, start_date ASC, id ASC
    `).all()

    // 2) 모든 4종 cap 대상 transactions 조회 (created_at ASC for FIFO 시뮬레이션)
    //    4종: daily_qkey, referral_reward, direct_referral
    //    제외: staking_reward, admin_adjustment, swap_*, withdrawal*
    const allCapTxs = await db.prepare(`
      SELECT user_id, type, amount, created_at, id
      FROM transactions
      WHERE coin_type = 'QKEY'
        AND type IN ('daily_qkey', 'referral_reward', 'direct_referral')
      ORDER BY user_id ASC, created_at ASC, id ASC
    `).all()

    // 3) user_id별로 stakings/txs 그룹화 후 FIFO 분배 시뮬레이션
    const stakingsByUser: Record<number, any[]> = {}
    for (const s of (allStakings.results || []) as any[]) {
      const uid = Number(s.user_id)
      if (!stakingsByUser[uid]) stakingsByUser[uid] = []
      stakingsByUser[uid].push({
        id: Number(s.id),
        amount: Number(s.amount),
        status: String(s.status),
        start_date: String(s.start_date),
        cap_target: Number(s.amount) * 300,  // 영구룰 #cap200정책: amount × 300
        baseline: Number(s.amount) * 150,     // 100% 기준점
        paid_total: 0,
        capped: false,
      })
    }

    const txsByUser: Record<number, any[]> = {}
    for (const tx of (allCapTxs.results || []) as any[]) {
      const uid = Number(tx.user_id)
      if (!txsByUser[uid]) txsByUser[uid] = []
      txsByUser[uid].push({
        type: String(tx.type),
        amount: Number(tx.amount),
        created_at: String(tx.created_at),
        id: Number(tx.id),
      })
    }

    // 4) 각 user의 stakings에 FIFO로 paid_total 분배
    const stakingCapsByUser: Record<number, any[]> = {}
    for (const uid of Object.keys(stakingsByUser)) {
      const uidNum = Number(uid)
      const stks = stakingsByUser[uidNum]  // 이미 start_date ASC 정렬됨
      const txs = txsByUser[uidNum] || []

      for (const ev of txs) {
        // ev.created_at의 날짜 부분 (UTC raw, KST 변환 안함 — staking.start_date와 동일 기준)
        const paidDate = ev.created_at.substring(0, 10)
        let remaining = ev.amount
        // 활성(start_date ≤ paid_date) + 미-cap staking 중 가장 오래된 것에 분배
        while (remaining > 0) {
          let target: any = null
          for (const s of stks) {
            if (s.start_date.substring(0, 10) > paidDate) continue
            if (s.capped) continue
            target = s
            break
          }
          if (!target) {
            // 모든 staking capped: 영구룰 위반 가능성, 그러나 표시 단계에서는
            // 마지막 staking에 overflow 기록 (DB는 변경 안함)
            if (stks.length > 0) stks[stks.length - 1].paid_total += remaining
            remaining = 0
            break
          }
          const available = target.cap_target - target.paid_total
          if (remaining <= available) {
            target.paid_total += remaining
            if (target.paid_total >= target.cap_target) target.capped = true
            remaining = 0
          } else {
            // Case B: 1회만 초과 허용 + capped
            target.paid_total += remaining
            target.capped = true
            remaining = 0
          }
        }
      }

      stakingCapsByUser[uidNum] = stks.map(s => {
        const cap_pct = s.baseline > 0 ? (s.paid_total / s.baseline * 100) : 0
        return {
          staking_id: s.id,
          amount: s.amount,
          status: s.status,
          start_date: s.start_date,
          baseline: s.baseline,
          cap_target: s.cap_target,
          paid_total: s.paid_total,
          cap_pct: Math.round(cap_pct * 100) / 100,  // 소수 2자리
          capped: s.capped,
        }
      })
    }

    // 5) members에 staking_caps 필드 추가
    const enrichedMembers = ((memberRewards.results || []) as any[]).map(m => {
      const uid = Number(m.id)
      const caps = stakingCapsByUser[uid] || []
      // user 전체 합계 (참고용)
      const total_baseline = caps.reduce((sum, c) => sum + c.baseline, 0)
      const total_cap_target = caps.reduce((sum, c) => sum + c.cap_target, 0)
      const total_paid_for_cap = caps.reduce((sum, c) => sum + c.paid_total, 0)
      const user_cap_pct = total_baseline > 0 ? Math.round(total_paid_for_cap / total_baseline * 100 * 100) / 100 : 0
      return {
        ...m,
        staking_caps: caps,
        cap_summary: {
          total_baseline,
          total_cap_target,
          total_paid_for_cap,
          user_cap_pct,
          any_capped: caps.some(c => c.capped),
        }
      }
    })

    // 전체 합계
    const totals = await db.prepare(`
      SELECT 
        COALESCE(SUM(usdt_amount), 0) as total_daily_qkey
      FROM daily_rewards
    `).first()

    const referralTotals = await db.prepare(`
      SELECT COALESCE(SUM(reward_amount), 0) as total_referral_qkey
      FROM referral_rewards
    `).first()

    return c.json({
      success: true,
      members: enrichedMembers,
      totals: {
        totalDailyQkey: totals?.total_daily_qkey || 0,
        totalReferralQkey: referralTotals?.total_referral_qkey || 0,
        totalCombined: (totals?.total_daily_qkey || 0) + (referralTotals?.total_referral_qkey || 0)
      }
    })
  } catch (error) {
    return c.json({ error: t(c, 'admin.member_rewards_error') }, 500)
  }
})

