// 한국 공휴일/국경일 목록 (2026년)
// 매년 업데이트 필요
function getKoreanHolidays(year: number): string[] {
  const holidays: Record<number, string[]> = {
    2025: [
      '2025-01-01','2025-01-28','2025-01-29','2025-01-30',
      '2025-03-01','2025-05-01','2025-05-05','2025-05-06','2025-06-06',
      '2025-08-15','2025-10-03','2025-10-05','2025-10-06','2025-10-07',
      '2025-10-09','2025-12-25'
    ],
    2026: [
      '2026-01-01',                        // 신정
      '2026-02-16','2026-02-17','2026-02-18', // 설날
      '2026-03-01',                        // 삼일절(일) → 대체공휴일은 인사처 고시 확인 후 추가
      '2026-05-01',                        // 근로자의 날
      '2026-05-05',                        // 어린이날
      '2026-05-24',                        // 부처님오신날(일)
      '2026-05-25',                        // ★ 부처님오신날 대체공휴일 (월) — 사장님 영구명령 2026-05-22
      '2026-06-03',                        // ★ 제9회 전국동시지방선거일 (수) 법정공휴일 — 사장님 영구명령 2026-05-29
      '2026-06-06',                        // 현충일
      '2026-07-17',                        // ★ 임시공휴일 (금) — 사장님 영구명령 2026-07-17 (연휴 아님, 당일 1일)
      '2026-08-15',                        // 광복절(토) → 대체공휴일은 인사처 고시 확인 후 추가
      '2026-09-24','2026-09-25','2026-09-26', // 추석
      '2026-10-03',                        // 개천절(토) → 대체공휴일은 인사처 고시 확인 후 추가
      '2026-10-09',                        // 한글날
      '2026-12-25'                         // 성탄절
    ],
    2027: [
      '2027-01-01',
      '2027-02-05','2027-02-06','2027-02-07',
      '2027-03-01','2027-05-01','2027-05-05','2027-05-13','2027-06-06',
      '2027-08-15','2027-10-03','2027-10-09',
      '2027-10-14','2027-10-15','2027-10-16',
      '2027-12-25'
    ]
  }
  return holidays[year] || holidays[2026]
}

function isKoreanBusinessDay(date: Date): { isBusinessDay: boolean, reason: string } {
  // KST 기준으로 변환
  const kst = new Date(date.getTime() + (9 * 60 * 60 * 1000))
  const day = kst.getUTCDay() // 0=일, 6=토
  const dateStr = kst.toISOString().split('T')[0]
  const year = kst.getUTCFullYear()

  // 토/일 체크
  if (day === 0) return { isBusinessDay: false, reason: 'sunday' }
  if (day === 6) return { isBusinessDay: false, reason: 'saturday' }

  // 공휴일 체크
  const holidays = getKoreanHolidays(year)
  if (holidays.includes(dateStr)) return { isBusinessDay: false, reason: 'holiday' }

  return { isBusinessDay: true, reason: 'business_day' }
}

// KST 기준 날짜 -> YYYY-MM-DD
function kstDateStr(d: Date): string {
  const kst = new Date(d.getTime() + (9 * 60 * 60 * 1000))
  return kst.toISOString().split('T')[0]
}

// 직전 영업일(KST) 계산 — 토/일/공휴일을 건너뛰며 어제, 그제 ... 로 거슬러 올라감
// 발생일/지급일 분리 정책: 영업일에 발생한 배당은 다음 영업일에 지급
// 예) 금요일 발생분 → 월요일 지급, 4/30 발생분 → 5/1~3 휴일 → 5/4(월) 지급
function getPrevBusinessDayKst(today: Date): { dateStr: string, daysBack: number } {
  // 최대 14일까지 거꾸로 탐색 (연휴 대비)
  for (let i = 1; i <= 14; i++) {
    const candidate = new Date(today.getTime() - i * 24 * 60 * 60 * 1000)
    const { isBusinessDay } = isKoreanBusinessDay(candidate)
    if (isBusinessDay) {
      return { dateStr: kstDateStr(candidate), daysBack: i }
    }
  }
  // 안전 fallback (일반적으로 도달 불가)
  return { dateStr: kstDateStr(new Date(today.getTime() - 24 * 60 * 60 * 1000)), daysBack: 1 }
}

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// 영구룰 #익일처리 (PERMANENT_RULES.md L347) — 사장님 영구명령 (2026-05-19)
//
// **다음 영업일(KST) 계산** — reward_date → paid_date 결정용
//
// 사장님 직접 인용:
//   "5/7(목) 확정 → 5/8(금) 표시"
//   "5/8(금) 확정 → 5/11(월) 표시" (토/일 skip)
//   "5/15(금) 확정 → 5/18(월) 표시" (토/일 skip)
//
// 사용처: cron 본체에서 paid_date = nextBusinessDayKstStr(reward_date) 로 INSERT
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
function nextBusinessDayKstStr(rewardDateStr: string): string {
  // rewardDateStr 'YYYY-MM-DD' 을 KST 자정으로 해석
  const base = new Date(rewardDateStr + 'T00:00:00+09:00')
  // 최대 14일까지 앞으로 탐색 (연휴 대비)
  for (let i = 1; i <= 14; i++) {
    const candidate = new Date(base.getTime() + i * 24 * 60 * 60 * 1000)
    const { isBusinessDay } = isKoreanBusinessDay(candidate)
    if (isBusinessDay) {
      return kstDateStr(candidate)
    }
  }
  // 안전 fallback (일반적으로 도달 불가)
  return kstDateStr(new Date(base.getTime() + 24 * 60 * 60 * 1000))
}

// 영구룰 #정규시각 — paid_date 의 KST 08:00 = UTC (paid_date - 1) 23:00
// 사용처: created_at INSERT 시
function createdAtUtcForPaidDate(paidDateStr: string, extraSeconds: number = 0): string {
  // paid_date KST 08:00 = UTC (prev-day) 23:00:00
  const paidObj = new Date(paidDateStr + 'T00:00:00+09:00')
  const prevDay = new Date(paidObj.getTime() - 24 * 60 * 60 * 1000)
  const prevDayKst = kstDateStr(prevDay)
  const ss = String(extraSeconds).padStart(2, '0')
  return `${prevDayKst} 23:00:${ss}`
}

// ★★ B 보강 (2026-05-06 확정) ★★
// 사장님 룰 (재확정):
//  1) 휴일/공휴일 매출도 직판수당은 즉시 지급 (이미 staking-approve 에서 처리)
//  2) 휴일/공휴일 staking 의 일일배당(본인+위/아래 매칭)은 "그 다음 첫 평일" 에 무조건 발생
//  3) 휴일/공휴일에 위·아래 매출이 전혀 없으면 일일배당 자체 0원 (기존 룰)
//
// "한 staking 에 대해 cron 이 채워야 할 reward_date 목록" 을 반환:
//  - lastRewardDate: 그 staking 의 daily_rewards 테이블 내 마지막 reward_date (없으면 NULL)
//  - startDateKst   : staking.start_date 의 KST 날짜 (YYYY-MM-DD)
//  - todayKst       : 오늘 KST 날짜 (cron 실행일, 평일임이 보장됨)
// 룰:
//  A. lastRewardDate 가 있으면 → "lastRewardDate 다음 영업일 ~ todayKst" 사이의 모든 영업일
//     (todayKst 포함; 오늘이 평일이므로 오늘분도 포함)
//  B. lastRewardDate 가 없으면 (첫 지급) → "startDateKst ~ todayKst" 사이 영업일 중
//     startDateKst 가 평일이면 그 평일 포함, 휴일이면 그 다음 첫 평일부터 todayKst 까지
//     → 단순히 "max(startDateKst, todayKst 까지) 영업일 전부"
//  안전 제한: 최대 30일 (연휴+버퍼)
function getStakingAccrualDatesKst(
  lastRewardDate: string | null,
  startDateKst: string,
  todayKst: string,
  firstBusinessDayKst?: string
): string[] {
  // 시작점: lastRewardDate 가 있으면 그 다음날, 없으면 startDateKst 부터
  let cursorStr: string
  if (lastRewardDate && /^\d{4}-\d{2}-\d{2}$/.test(lastRewardDate)) {
    const d = new Date(lastRewardDate + 'T00:00:00Z')
    cursorStr = new Date(d.getTime() + 24 * 60 * 60 * 1000).toISOString().split('T')[0]
  } else {
    cursorStr = startDateKst
  }
  // 끝점: todayKst (포함) — 일반 백필 endDate (= yesterdayKst 가 전달됨)
  const endDate = new Date(todayKst + 'T00:00:00Z')
  let cursor = new Date(cursorStr + 'T00:00:00Z')
  const result: string[] = []
  let safety = 0
  while (cursor.getTime() <= endDate.getTime() && safety < 30) {
    const dateStr = cursor.toISOString().split('T')[0]
    // KST 영업일 판정: cursor 는 KST 00:00 의 UTC 표현 → 실제 UTC 시각은 -9h
    const checkDate = new Date(cursor.getTime() - 9 * 60 * 60 * 1000)
    const { isBusinessDay } = isKoreanBusinessDay(checkDate)
    if (isBusinessDay) result.push(dateStr)
    cursor = new Date(cursor.getTime() + 24 * 60 * 60 * 1000)
    safety++
  }
  // ★ 사장님 정책 (2026-05-08 영구) — 휴일 진입자 첫 평일 데일리 1회 강제 지급 (B 방안) ★
  //   사장님 원문: "공휴일 진입자는 언제 진입하든 첫 평일에 딱 1회 지급"
  //   조건: lastRewardDate 가 NULL (첫 지급)
  //         AND startDateKst 가 휴일(토/일/공휴일)
  //         AND 정상 백필 결과가 0건 (yesterdayKst 까지 영업일이 없음)
  //         AND firstBusinessDayKst 가 전달됨 (cron 실행일 = 오늘 첫 평일)
  //   → firstBusinessDayKst 를 첫 reward_date 로 강제 push
  //   예: 5/11(월) cron 시
  //     - 5/9(토) 진입자: 결과 0건 → push [5/11] 1건
  //     - 5/10(일) 진입자: 결과 0건 → push [5/11] 1건
  //     - 5/8(금) 진입자: 결과 [5/8] 1건 → 강제 push 미발동 (8일 1회 정책 일치)
  if (!lastRewardDate && result.length === 0 && firstBusinessDayKst) {
    const startObj = new Date(startDateKst + 'T00:00:00Z')
    const fbdObj = new Date(firstBusinessDayKst + 'T00:00:00Z')
    if (startObj.getTime() <= fbdObj.getTime()) {
      const startCheck = new Date(startObj.getTime() - 9 * 60 * 60 * 1000)
      const { isBusinessDay: startIsBiz } = isKoreanBusinessDay(startCheck)
      const fbdCheck = new Date(fbdObj.getTime() - 9 * 60 * 60 * 1000)
      const { isBusinessDay: fbdIsBiz } = isKoreanBusinessDay(fbdCheck)
      if (!startIsBiz && fbdIsBiz) {
        // ★ 사장님 영구명령 (2026-06-16 확정) ★
        //   휴일 진입자의 첫 1일치 확정일(reward_date) = 진입일(startDateKst, 토/일/공휴일) 자체.
        //   지급일(paid_date)은 cron 루프의 nextBusinessDay(startDateKst) = 첫 평일 로 계산됨.
        //   예) 6/13(토) 진입 → reward_date=6/13(토) → paid=nextBiz(6/13)=6/15(월) [첫 평일 1일치]
        //       그 후 last_reward_date=6/13 → 다음 cron 이 6/15(월) 확정분(→6/16 지급) 자동 백필.
        //   (기존 버그: firstBusinessDayKst(=첫평일)를 reward_date 로 push → 확정일이 토가 아니라
        //    첫 평일이 되어, 첫 평일 확정분이 통째로 누락되고 지급도 하루 밀림)
        result.push(startDateKst)
      }
    }
  }
  return result
}

// 출금 신청 창 체크
// 룰: 매주 금요일 10:00~14:00 KST. 공휴일 여부 무관. 실제 지급 처리는 관리자가 수동으로 진행.
// ★ 사장님 2026-05-15 (5차) 지시: 2026-05-15 (금) 당일만 18:00 까지 연장. 5/16부터 원래 룰 자동 복원.
function isWithdrawalWindowOpen(d: Date): boolean {
  const kst = new Date(d.getTime() + (9 * 60 * 60 * 1000))
  const day = kst.getUTCDay() // 0=일, 5=금
  const hour = kst.getUTCHours()
  const dateStr = `${kst.getUTCFullYear()}-${String(kst.getUTCMonth()+1).padStart(2,'0')}-${String(kst.getUTCDate()).padStart(2,'0')}`
  // 1회성 예외: 2026-05-15 (금) → 10:00 ~ 18:00 (사장님 직접 지시, 매우 중요)
  if (dateStr === '2026-05-15') {
    return day === 5 && hour >= 10 && hour < 18
  }
  // 기본 룰: 매주 금요일 10:00 ~ 14:00 KST
  return day === 5 && hour >= 10 && hour < 14
}

// 일일 배당금 지급 (하루 1회 자동 지급)
// 정책: 승인일 익일부터, 거치기간 내 매일 지급, 금액별 차등 배당률
// 월~금만 지급 (토/일/공휴일/국경일 제외)
app.post('/api/rewards/daily', async (c) => {
  try {
    // ★ 사장님 2026-05-07 지시 ★ 강제 일괄 배당은 cron(GitHub Actions) 전용
    // GitHub Actions cron 호출은 'X-Cron-Trigger: github-actions' 헤더로 식별
    // 어드민 UI/사람이 호출하는 경우는 User-Agent 가 axios/Mozilla 등이므로 차단
    const cronTrigger = c.req.header('X-Cron-Trigger') || ''
    const userAgent = c.req.header('User-Agent') || ''
    const isCronCall = cronTrigger === 'github-actions' || /node|github-actions/i.test(userAgent)
    // ★ 사장님 2026-05-12 영구 룰 ★ 내부 manual-trigger 우회 헤더
    //   manual-daily-trigger 가 자기 자신을 호출할 때만 통과 (request body 의 internalSecret 으로 식별)
    const internalManualCall = cronTrigger === 'manual-admin'
    if (!isCronCall && !internalManualCall) {
      return c.json({
        success: false,
        error: '강제 일괄 배당은 비활성화되었습니다. 매 평일 KST 08:00 cron 자동 실행 전용입니다. 개별 보정은 /api/admin/rewards/manual-adjust 를 사용하세요.',
        blocked: true
      }, 403)
    }

    const db = c.env.DB
    const now = new Date()
    const todayKstForLock = kstDateStr(now)

    // ★★★★★★★★★★★★★★★★★★★★ 영구 룰 — daily_cron_lock (2026-05-12 사장님 명령) ★★★★★★★★★★★★★★★★★★★★
    //   사장님 .md 원문 (2026-05-12):
    //     "그시간뒤에 실행버튼을 사람이 수동으로 클릭했을때는 무조건 별도의 자동클론이
    //      당일에는 내 별도의 명령없이 작동하면 안된다"
    //
    //   동작 원리:
    //   1) daily_cron_lock 테이블에 (lock_date, source) 기록
    //   2) source = 'manual_admin' 이 같은 날짜에 이미 있으면 → 모든 자동 cron 호출 차단 (403)
    //   3) source = 'cron_auto'    가 같은 날짜에 이미 있으면 → 중복 cron 차단 (이중 배당 방지)
    //   4) 사장님 별도 명령 (force=GO + ADMIN_PW key) 으로만 lock 해제 가능
    //   5) lock 은 batch 페이지네이션을 방해하지 않음 — 같은 날 같은 source 의 batch 호출은 통과
    try {
      await db.prepare(`
        CREATE TABLE IF NOT EXISTS daily_cron_lock (
          lock_date        TEXT PRIMARY KEY,
          source           TEXT NOT NULL,
          locked_at        TEXT NOT NULL DEFAULT (datetime('now','+9 hours')),
          locked_by        TEXT,
          note             TEXT,
          last_finished_at TEXT
        )
      `).run()
    } catch(e) {}
    // ★ P3 (2026-05-13) ★ — 기존 테이블에 last_finished_at 컬럼 없으면 추가 (멱등)
    try { await db.prepare(`ALTER TABLE daily_cron_lock ADD COLUMN last_finished_at TEXT`).run() } catch(e) {}

    // 기존 lock 확인 — 같은 날 다른 source 가 이미 실행했으면 차단
    const existingLock = await db.prepare(`
      SELECT source, locked_at, locked_by FROM daily_cron_lock WHERE lock_date = ?
    `).bind(todayKstForLock).first() as any
    if (existingLock) {
      const incomingSource = internalManualCall ? 'manual_admin' : 'cron_auto'
      if (existingLock.source !== incomingSource) {
        // source 불일치 = 다른 경로(수동/자동)가 이미 같은 날 처리 완료 → 차단
        return c.json({
          success: false,
          error: `오늘(${todayKstForLock}) 데일리 배당은 이미 [${existingLock.source}] 에 의해 ${existingLock.locked_at} 에 실행되었습니다. 사장님 별도 명령 없이는 추가 실행 불가 (영구 룰).`,
          blocked: true,
          lock: existingLock
        }, 423) // 423 Locked
      }
      // 같은 source 의 batch 페이지네이션 재호출은 통과
    } else {
      // 신규 lock INSERT (cron_auto 또는 manual_admin)
      try {
        await db.prepare(`
          INSERT INTO daily_cron_lock (lock_date, source, locked_by, note)
          VALUES (?, ?, ?, ?)
        `).bind(
          todayKstForLock,
          internalManualCall ? 'manual_admin' : 'cron_auto',
          internalManualCall ? 'admin-manual-button' : 'github-actions',
          internalManualCall ? '어드민 수동 실행 버튼' : 'GitHub Actions cron (KST 08:00)'
        ).run()
      } catch(e) {}
    }
    // ★ 사장님 2026-05-07 명확화 (UPDATED 2026-05-19: KST 08:00 정규시각) ★
    //   기준일 = 어제 (KST 00:00:00 ~ 23:59:59)
    //   cron 실행 시각: KST 08:00 (UTC 23:00 prev-day) — GitHub Actions schedule '0 23 * * *'
    //   reward_date = 어제(KST)  /  paid_date = 오늘(KST)
    //   tx/DR/RR created_at = KST 08:00 of paid_date (= UTC prev-day 23:00) [영구룰 #정규시각 2026-05-19]
    //
    //   기존 today 기준 -> yesterdayKst 기준으로 전면 변경 (2026-05-07)
    const today = kstDateStr(now)
    const yesterdayKst = kstDateStr(new Date(now.getTime() - 24 * 60 * 60 * 1000))

    // ★★★★★ 영구룰 #정규시각 (2026-05-19 변경) — KST 08:00 통일 ★★★★★
    //   기존: KST 15:15 (= UTC 06:15)  ← 폐기
    //   현재: KST 08:00 (= UTC 23:00 of paid_date - 1day)
    //   사장님 명령: "매일 아침 08시에 배당을 할것"
    //   DB 저장값은 UTC, 사용자 화면은 +9h 보정으로 paid_date KST 08:00 표시
    //
    //   계산 방식:
    //     paid_date = today (KST 날짜, 예: '2026-05-20')
    //     KST 08:00 of '2026-05-20' = UTC 23:00 of '2026-05-19'
    //     → UTC datetime string: '${today - 1day} 23:00:00'
    //
    //   사고 방지: DB default CURRENT_TIMESTAMP 사용 절대 금지 (5/18 19:04 사고)
    //              INSERT 시 created_at 명시 필수
    const paidDateObj = new Date(today + 'T00:00:00+09:00')
    const prevDayObj = new Date(paidDateObj.getTime() - 24 * 60 * 60 * 1000)
    const prevDayKstStr = kstDateStr(prevDayObj)  // 'YYYY-MM-DD' for paid_date - 1day (KST)
    const dailyCreatedAtUtc = `${prevDayKstStr} 23:00:00`       // KST 08:00:00 of paid_date
    const referralCreatedAtUtc = `${prevDayKstStr} 23:00:01`    // KST 08:00:01 (RR 은 1초 늦게 — 정규 cron 순서 모사)

    // ★ 사장님 정책 (2026-05-08 영구) — 진입 차단 룰 변경 ★
    //   기존: 어제(KST)가 휴일이면 cron 전체 차단 → 휴일 진입자 첫 평일 데일리 누락 발생
    //   변경: "오늘(KST)이 평일이면" cron 진행 (어제가 휴일이어도 진행)
    //         → getStakingAccrualDatesKst 가 staking 별로 누락된 영업일만 백필
    //         → 휴일 진입자(예: 5/9·5/10 진입)는 첫 평일(5/11) cron 에서 [5/11] 1건 강제 지급
    //         → 평일 진입자(5/8) 는 [5/8] 1건만 지급 (사장님: "8일진입자는 좀 억울하겠지만")
    //   오늘 자체가 휴일이면 cron skip (룰 B 그대로)
    const todayDateObjKst = new Date(today + 'T00:00:00+09:00')
    const { isBusinessDay, reason } = isKoreanBusinessDay(todayDateObjKst)
    if (!isBusinessDay) {
      const reasonText = reason === 'saturday' ? '토요일' : reason === 'sunday' ? '일요일' : '공휴일/국경일'
      return c.json({
        success: true,
        message: `오늘(${today})은 ${reasonText}이므로 배당 처리 불가 (룰 B: 휴일 cron skip, 다음 평일 cron 에서 일괄 백필).`,
        rewarded: 0,
        totalQkey: 0,
        skipped: 0,
        reason: reason,
        targetDate: today
      })
    }

    // ★★ B 보강 (2026-05-06 확정) — 사장님 최종 룰 ★★
    //   1) 휴일/공휴일 매출도 직판수당은 즉시 지급 (staking-approve 단계)
    //   2) 휴일/공휴일 staking 의 일일배당(본인+위/아래 매칭)은 그 다음 첫 평일에 무조건 발생
    //   3) 휴일/공휴일에 위·아래 매출이 전혀 없으면 일일배당 0원 (cron 자체 미실행)
    //
    //   변경점: 기존엔 "직전 1영업일분" 만 처리 → 이제는 staking 별로
    //   "마지막 reward_date 다음 영업일 ~ 오늘" 의 모든 누락 평일을 일괄 처리.
    //   휴일에 시작한 staking 의 reward_date 는 자동으로 "그 다음 첫 평일" 부터 채워짐.

    // paid_date 컬럼 보장 (없으면 추가)
    try { await db.prepare(`ALTER TABLE daily_rewards ADD COLUMN paid_date TEXT`).run() } catch(e) {}
    try { await db.prepare(`ALTER TABLE referral_rewards ADD COLUMN paid_date TEXT`).run() } catch(e) {}
    // H plan (2026-05-13) — referral_rewards.staking_id 컬럼 보장 (G2-B 영구 인프라)
    //   기존 row 는 NULL (legacy), 신규 row 부터 staking_id 명시 의무
    //   cron 의 referee 다중 staking 매칭 결함 영구 해결
    try { await db.prepare(`ALTER TABLE referral_rewards ADD COLUMN staking_id INTEGER`).run() } catch(e) {}
    try { await db.prepare(`CREATE INDEX IF NOT EXISTS idx_referral_rewards_staking_id ON referral_rewards(staking_id)`).run() } catch(e) {}

    // ★★★★★ 영구 대책 #2 (2026-05-14) — UNIQUE 인덱스 (DB 레벨 이중지급 절대 차단) ★★★★★
    //   사장님 영구명령: "1회만 지급한걸로 보이게 흔적없이"
    //   원인: 4중 가드가 reward_date 컬럼만 보고 같은 paid_date 인 다른 reward_date 행 허용 → 중복 INSERT
    //   대책: D1 UNIQUE 인덱스로 (user, staking, paid_date) 조합 1회만 INSERT 허용
    //         → 코드 가드 빠뜨려도 D1 단에서 INSERT 자체가 실패
    //
    //   ※ 기존 행에 중복 있는 상태로 인덱스 생성하면 실패하므로 try-catch 로 안전 처리
    //     첫 배포 시 인덱스 생성 실패 → may14-dup-cleanup 으로 중복 제거 후 재배포 → 성공
    try { await db.prepare(`CREATE UNIQUE INDEX IF NOT EXISTS uniq_daily_rewards_paid_per_staking
      ON daily_rewards(user_id, staking_id, paid_date)`).run() } catch(e) {
      console.warn('[Permanent#2] uniq_daily_rewards_paid_per_staking 인덱스 생성 실패 (기존 중복 존재 가능):', (e as any)?.message)
    }
    try { await db.prepare(`CREATE UNIQUE INDEX IF NOT EXISTS uniq_referral_rewards_paid
      ON referral_rewards(referrer_id, referee_id, level, staking_id, paid_date)`).run() } catch(e) {
      console.warn('[Permanent#2] uniq_referral_rewards_paid 인덱스 생성 실패 (기존 중복 존재 가능):', (e as any)?.message)
    }

    // ★ 사장님 룰 (2026-05-07 명확화) ★
    //   기준일 = yesterdayKst (어제 KST 00:00:00 ~ 23:59:59 의 24시간 윈도우 매출 전체 포함)
    //   ⇒ start_date_kst <= yesterdayKst 인 staking 만 어제 매출로 인정 (휴일 가입자 포함, 룰 B 백필)
    //   ⇒ end_date_kst   >= yesterdayKst 인 staking 만 거치기간 내 (어제 시점 활성)
    //
    //   이렇게 하면 어제 KST 23:59:59 직전에 가입한 회원도 무조건 어제 매출로 잡혀서
    //   오늘 새벽 01:00 cron 에서 일일배당이 발생함 (영국시간/UTC 경계 문제 완전 차단).
    //
    // ★★★ 사장님 영구 룰 (2026-05-12 사용자 증가 대응) ★★★
    //   Cloudflare Workers subrequest 한도(1000/req) 초과 방지를 위해 batch 페이지네이션 도입
    //   - 트리거는 1개 cron(daily-rewards.yml) 그대로 유지 (단일화 룰 준수)
    //   - 1개 cron job 이 내부적으로 batch 호출 N회 반복 → 외부에서는 1회 cron 으로 보임
    //   - 잔액 즉시 반영 룰 유지: 각 batch 응답 종료 = 해당 batch 의 잔액 반영 완료 (캐시/지연 없음)
    //   - 쿼리: ?batchSize=20&offset=0 (기본 batchSize=20, offset=0)
    //   - 응답: { ..., batchSize, offset, batch_processed, has_more }
    //   - 워크플로 스크립트에서 has_more=false 까지 반복 호출
    const batchSize = Math.max(1, Math.min(50, parseInt(c.req.query('batchSize') || '20') || 20))
    const offset = Math.max(0, parseInt(c.req.query('offset') || '0') || 0)

    // ★★★★★ 영구룰 #pagination-stable (2026-05-22 사장님 명령) ★★★★★
    //   원인: 기존 SQL이 status='active' 만 SELECT → cap pre-check 시 status='capped'로
    //         UPDATE한 후, 다음 batch 호출 시 active 집합이 줄어들어 OFFSET 시프트 발생
    //         → 5/22 cron에서 빅뱅 staking#45 capped UPDATE 직후 batch#2 에서 staking#47(qt1234)
    //           이 건너뛰어진 사고 발생 (uid=50 daily 750 + uid=44 L1 150 + uid=42 L2 75 누락)
    //   대책: SQL은 status IN ('active','capped','completed')로 안정 집합 유지,
    //         cap pre-check가 자체적으로 capped를 skip → OFFSET 시프트 없음
    //   부작용: 이미 capped된 staking이 매 cron마다 pre-check까지 도달 (cappedSkipCount +1)
    //         하지만 L5189의 UPDATE는 WHERE status='active' 조건이라 capped 행에는 무영향
    //         (idempotent). 잔액/INSERT 영향 0건.
    const totalRow = await db.prepare(`
      SELECT COUNT(*) as cnt
      FROM staking s
      WHERE s.status IN ('active','capped','completed')
        AND date(s.end_date, '+9 hours') >= date(?)
        AND date(s.start_date, '+9 hours') <= date(?)
    `).bind(yesterdayKst, yesterdayKst).first() as any
    const totalActive = Number(totalRow?.cnt || 0)

    const activeStakings = await db.prepare(`
      SELECT
        s.user_id,
        s.id as staking_id,
        s.amount,
        s.period_days,
        s.period_months,
        s.daily_rate,
        s.start_date,
        s.end_date,
        s.reset_at,
        date(s.start_date, '+9 hours') as start_date_kst,
        (SELECT COUNT(*) FROM daily_rewards WHERE staking_id = s.id) as rewarded_count,
        (SELECT MAX(reward_date) FROM daily_rewards WHERE staking_id = s.id) as last_reward_date
      FROM staking s
      WHERE s.status IN ('active','capped','completed')
        AND date(s.end_date, '+9 hours') >= date(?)
        AND date(s.start_date, '+9 hours') <= date(?)
      ORDER BY s.id ASC
      LIMIT ? OFFSET ?
    `).bind(yesterdayKst, yesterdayKst, batchSize, offset).all()

    if (activeStakings.results.length === 0) {
      return c.json({
        success: true,
        message: t(c, 'rewards.no_active'),
        rewarded: 0,
        batchSize,
        offset,
        batch_processed: 0,
        total_active: totalActive,
        has_more: false
      })
    }

    let rewardedCount = 0
    let totalQkeyRewarded = 0
    let skippedCount = 0
    let cappedSkipCount = 0
    let processedDates: { staking_id: any, dates: string[] }[] = []
    const cappedUsers: number[] = []

    // 환율: 1 USD = 1,500 KRW, 1 QKEY = 10 KRW → 1 USD = 150 QKEY
    const USD_TO_QKEY = 150

    // ★★★ 영구룰 #cap200정책 (2026-05-21 사장님 직접 정의) ★★★
    //   ① 분자 4종 = daily_qkey + referral_reward(L1+L2) + direct_referral(L0)
    //   ② Staking별 완전 독립: paid_total을 FIFO(진입일 ASC)로 staking에 분배
    //   ⑥ L1/L2 매칭은 receiver의 staking_id 단위로 cap 체크
    //
    // 구현: 인메모리 상태(stakingStateCache)로 cron 실행 중 fill 누적 추적
    //       매 staking 별 (cap_target까지 남은 fill) 잔여를 추적 → 다른 staking 영향 X
    //
    // stakingStateCache: Map<userId, { totalPaid, stakings: [{id, amount, capTarget, fill, capped, status_db}] }>
    type StakingState = {
      id: number
      amount: number
      capTarget: number   // amount × 300
      fill: number        // FIFO 분배된 paid
      capped: boolean     // fill >= capTarget
      status_db: string   // DB의 status (active/capped/completed)
      start_date_kst: string
    }
    type UserCapState = {
      userId: number
      totalPaid: number   // 분자 4종 합계 (캐시 직전 DB 값)
      stakings: StakingState[]   // 진입일 ASC
    }
    const stakingStateCache = new Map<number, UserCapState>()

    async function loadUserCapState(userId: number): Promise<UserCapState> {
      const cached = stakingStateCache.get(userId)
      if (cached) return cached

      // 사용자 staking 목록 (진입일 ASC = FIFO)
      const stakingRows = await db.prepare(`
        SELECT id, amount, status, start_date,
               date(start_date, '+9 hours') as start_date_kst
        FROM staking
        WHERE user_id = ? AND status IN ('active','completed','capped')
        ORDER BY date(start_date, '+9 hours') ASC, id ASC
      `).bind(userId).all()

      // ★ 영구룰 #cap200정책 3️⃣ 분자 4종 ★ (direct_referral 반드시 포함)
      const paidRow = await db.prepare(`
        SELECT COALESCE(SUM(amount), 0) as total
        FROM transactions
        WHERE user_id = ? AND coin_type = 'QKEY'
          AND type IN ('daily_qkey','referral_reward','direct_referral')
      `).bind(userId).first() as any
      let pool = Number(paidRow?.total || 0)

      // FIFO 분배: 진입일 빠른 staking부터 cap_target까지 채움
      const stakings: StakingState[] = []
      for (const r of stakingRows.results as any[]) {
        const amount = Number(r.amount)
        const capTarget = amount * 2 * USD_TO_QKEY
        const fill = Math.min(pool, capTarget)
        pool -= fill
        stakings.push({
          id: Number(r.id),
          amount,
          capTarget,
          fill,
          capped: fill >= capTarget,
          status_db: String(r.status || 'active'),
          start_date_kst: String(r.start_date_kst || '')
        })
      }

      const state: UserCapState = {
        userId,
        totalPaid: Number(paidRow?.total || 0),
        stakings
      }
      stakingStateCache.set(userId, state)
      return state
    }

    // ★ 영구룰 #cap200정책 2️⃣ — 특정 staking이 capped인지 (FIFO 분배 후)
    async function isStakingCapped(userId: number, stakingId: number): Promise<{
      capped: boolean, fill: number, capTarget: number, remaining: number, state: UserCapState
    }> {
      const state = await loadUserCapState(userId)
      const s = state.stakings.find(x => x.id === stakingId)
      if (!s) {
        // staking 없음 — 안전상 capped로 간주
        return { capped: true, fill: 0, capTarget: 0, remaining: 0, state }
      }
      return {
        capped: s.capped,
        fill: s.fill,
        capTarget: s.capTarget,
        remaining: Math.max(0, s.capTarget - s.fill),
        state
      }
    }

    // ★ 영구룰 #cap200정책 2️⃣/6️⃣ — 추가 paid 발생 시 FIFO로 가장 빠른 미충전 staking에 채움
    //   반환: { acceptedAmount, targetStakingId } — acceptedAmount는 잔여 cap에 의해 줄어들 수 있음
    function applyPaidIncrementFIFO(state: UserCapState, requestedAmount: number): {
      accepted: number, targetStakingId: number | null
    } {
      if (requestedAmount <= 0) return { accepted: 0, targetStakingId: null }
      // 진입일 ASC 순으로 가장 먼저 fill < capTarget 인 staking 찾기
      for (const s of state.stakings) {
        if (s.fill >= s.capTarget) continue
        const room = s.capTarget - s.fill
        const accept = Math.min(requestedAmount, room)
        if (accept <= 0) continue
        // 인메모리 fill 업데이트
        s.fill += accept
        if (s.fill >= s.capTarget) s.capped = true
        state.totalPaid += accept
        return { accepted: accept, targetStakingId: s.id }
      }
      // 모든 staking이 capped — 추가 지급 불가
      return { accepted: 0, targetStakingId: null }
    }

    // ★ 영구룰 #cap200정책 2️⃣ — 특정 staking이 본인 daily 지급을 받을 수 있는 잔여 계산
    //   본인 채굴은 staking이 1:1 매핑 — 해당 staking이 capped면 다른 staking으로 이전 X (영구룰 2️⃣)
    function applyOwnDailyToStaking(state: UserCapState, stakingId: number, requestedAmount: number): number {
      const s = state.stakings.find(x => x.id === stakingId)
      if (!s) return 0
      if (s.fill >= s.capTarget) return 0
      const room = s.capTarget - s.fill
      const accept = Math.min(requestedAmount, room)
      s.fill += accept
      if (s.fill >= s.capTarget) s.capped = true
      state.totalPaid += accept
      return accept
    }

    // (호환용 wrapper — 기존 isUserCapped 호출부에서 user 전체 합산 cap 체크용)
    //   영구룰 2️⃣ 위반 — 절대 본인 채굴 cap 체크용으로 쓰면 안 됨.
    //   ※ 유일하게 안전한 용도: "사용자의 모든 staking이 다 capped인지" 확인 (사전 skip)
    async function isUserAllStakingsCapped(userId: number): Promise<{ allCapped: boolean, state: UserCapState }> {
      const state = await loadUserCapState(userId)
      if (state.stakings.length === 0) return { allCapped: false, state }
      return { allCapped: state.stakings.every(s => s.capped), state }
    }

    for (const staking of activeStakings.results) {
      try {
        const periodDays = staking.period_days || (staking.period_months * 30)

        // ★★★ 영구룰 #cap200정책 2️⃣ — 본 staking 단위 cap 사전 체크 ★★★
        //   기존: user 단위 합산 → staking별 독립 위반
        //   변경: 이 staking 만 FIFO 분배 후 fill >= capTarget 이면 본인 daily skip
        //         다른 staking 은 계속 진행 (영구룰 2️⃣)
        const stkCapPre = await isStakingCapped(staking.user_id as number, staking.staking_id as number)
        if (stkCapPre.capped) {
          cappedSkipCount++
          if (!cappedUsers.includes(staking.user_id as number)) cappedUsers.push(staking.user_id as number)
          // ★ 영구룰 2️⃣ — 이 staking 만 capped 표시 (다른 active staking 영향 X)
          try {
            await db.prepare(`UPDATE staking SET status='capped' WHERE id=? AND status='active'`).bind(staking.staking_id).run()
          } catch(e) {}
          continue
        }

        // ★ 사장님 룰 (2026-05-07 명확화) ★
        //   reward_date 는 어제(yesterdayKst) 까지만 채움. 오늘 매출은 내일 01:00 cron 에서 처리.
        //   - lastRewardDate 가 있으면 그 다음 영업일 ~ yesterdayKst
        //   - 없으면 startDateKst ~ yesterdayKst (휴일이면 자동 skip 되어 첫 평일부터)
        //   ⇒ 어제 가입자(00시~23시59분)도 startDateKst <= yesterdayKst 라 무조건 포함
        // ★ 사장님 정책 (2026-05-08) — 4번째 인자 today 전달 (B 방안) ★
        //   휴일 진입자(5/9 토·5/10 일 등) 첫 평일 데일리 1회 강제 지급용
        //   일반 백필 endDate = yesterdayKst 그대로 유지 (5/8 진입자: [5/8] 1건만)
        const accrualDates = getStakingAccrualDatesKst(
          (staking.last_reward_date as string) || null,
          staking.start_date_kst as string,
          yesterdayKst,
          today
        )

        if (accrualDates.length === 0) {
          continue // 처리할 평일 없음
        }

        const stakingProcessed: string[] = []

        for (const accrualDate of accrualDates) {
          // ★★★ 영구룰 #익일처리 (2026-05-19 사장님 D 명령) ★★★
          //   paid_date = nextBusinessDay(accrualDate) — 각 reward 별로 독립 계산
          //   기존: paid_date = today (cron 실행일) → backfill 시 5/8 reward 도 5/12 paid 되는 위반
          //   정정: 5/8 reward → paid=5/11, 5/11 reward → paid=5/12 처럼 reward 별 정답 paid
          //   created_at = paid_date 의 KST 08:00 (= UTC paid_date-1 23:00)
          //
          // ★★★ 영구명령 (2026-06-16 사장님 확정) — 토/일/공휴일 진입자 ★★★
          //   휴일 진입자의 첫 확정일(reward_date)은 getStakingAccrualDatesKst 에서
          //   진입일(토/일/공휴일) 자체로 push 됨. 지급일 = nextBusinessDay(진입일) = 첫 평일.
          //   예) reward 6/13(토) → paid nextBiz(6/13)=6/15(월). 별도 분기 불필요 — 일반식 그대로.
          const accrualPaidDate = nextBusinessDayKstStr(accrualDate)
          const accrualDailyCreatedAtUtc = createdAtUtcForPaidDate(accrualPaidDate, 0)
          const accrualReferralCreatedAtUtc = createdAtUtcForPaidDate(accrualPaidDate, 1)

          // 거치기간 일수 초과 시 종료
          const currentRewardedCount = staking.rewarded_count + stakingProcessed.length
          if (currentRewardedCount >= periodDays) {
            skippedCount++
            break
          }

          // ★★★ 영구 대책 #1 (2026-05-14) — 5중 가드 (paid_date 추가) ★★★
          //   사장님 영구명령: #이중지급 절대 금지
          //   원인: 기존 4중 가드는 reward_date 만 봄 → 같은 paid_date 인 다른 reward_date 행 허용
          //         (today-fix 사고 재현 방지)
          //   대책: (user, staking, reward_date) OR (user, staking, paid_date=today) 동시 체크
          //         → 같은 날 paid_date 행이 이미 있으면 무조건 SKIP (reward_date 무관)
          const exists = await db.prepare(`
            SELECT COUNT(*) as count FROM daily_rewards
            WHERE user_id = ? AND staking_id = ?
              AND (reward_date = ? OR paid_date = ?)
          `).bind(staking.user_id, staking.staking_id, accrualDate, today).first()
          if (exists.count > 0) continue

          // 금액별 차등 배당률 적용
          const dailyRate = staking.daily_rate || getDailyRate(staking.amount)
          const usdAmount = staking.amount * dailyRate
          let qkeyAmount = Math.round(usdAmount * USD_TO_QKEY)

          // ★★★ 영구룰 #cap200정책 2️⃣ — 본 staking 도중 cap 재확인 ★★★
          //   기존: user 단위 합산 → staking별 독립 위반
          //   변경: 이 staking 자체의 fill ≥ capTarget 인지 검사
          //         부분지급(Case B) 시: room = capTarget - fill 만큼만 지급
          //         capped 시: 이 staking 만 status='capped', 다른 staking은 계속 (영구룰 2️⃣)
          const stkCapNow = await isStakingCapped(staking.user_id as number, staking.staking_id as number)
          if (stkCapNow.capped) {
            cappedSkipCount++
            if (!cappedUsers.includes(staking.user_id as number)) cappedUsers.push(staking.user_id as number)
            try { await db.prepare(`UPDATE staking SET status='capped' WHERE id=? AND status='active'`).bind(staking.staking_id).run() } catch(e) {}
            break
          }
          // 부분 지급 (Case B) — 이 staking 잔여만큼만
          const stkRoom = stkCapNow.remaining
          if (qkeyAmount > stkRoom) {
            qkeyAmount = Math.max(0, Math.floor(stkRoom))
            if (qkeyAmount <= 0) {
              cappedSkipCount++
              if (!cappedUsers.includes(staking.user_id as number)) cappedUsers.push(staking.user_id as number)
              try { await db.prepare(`UPDATE staking SET status='capped' WHERE id=? AND status='active'`).bind(staking.staking_id).run() } catch(e) {}
              break
            }
          }
          // ★ 인메모리 cap state 업데이트 (다음 iteration이 정확한 fill 보도록) ★
          //   영구룰 2️⃣ — 본인 daily는 자기 staking으로만 (FIFO 이전 금지)
          const _appliedOwn = applyOwnDailyToStaking(stkCapNow.state, staking.staking_id as number, qkeyAmount)
          // _appliedOwn 은 qkeyAmount 와 동일해야 함 (위에서 잔여만큼만 잘랐기 때문)

          // [본인 배당 지급]
          //   reward_date = accrualDate (해당 평일)
          //   paid_date   = nextBusinessDayKstStr(accrualDate)  ★ 영구룰 #익일처리 (2026-05-19 D 명령)
          //   ★ 영구룰 #정규시각 (2026-05-19) — created_at = paid_date KST 08:00 (= UTC prev-day 23:00)
          //     사고 방지: DB default CURRENT_TIMESTAMP 사용 금지 (5/18 사고)
          // [패치 2026-05-11] ref_id 1:1 매핑 — daily_rewards INSERT 후 last_row_id 캡처
          const drIns = await db.prepare(`
            INSERT INTO daily_rewards (user_id, staking_id, usdt_amount, reward_date, paid_date, created_at)
            VALUES (?, ?, ?, ?, ?, ?)
          `).bind(staking.user_id, staking.staking_id, qkeyAmount, accrualDate, accrualPaidDate, accrualDailyCreatedAtUtc).run()
          const drId = (drIns as any)?.meta?.last_row_id ?? null

          await db.prepare(`
            UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?
          `).bind(qkeyAmount, staking.user_id).run()

          const newCount = currentRewardedCount + 1
          // EXISTS 가드 (ref_id 1:1) — 동일 daily_rewards.id 에 대응하는 transactions 행 차단
          const dqExists2 = await db.prepare(`
            SELECT id FROM transactions
            WHERE type = 'daily_qkey' AND ref_id = ?
            LIMIT 1
          `).bind(drId).first()
          if (!dqExists2) {
            // ★ 영구룰 #정규시각 (2026-05-19) — created_at 명시 (KST 08:00, accrualPaidDate 기준)
            await db.prepare(`
              INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id, created_at)
              VALUES (?, 'daily_qkey', 'QKEY', ?, ?, ?, ?)
            `).bind(staking.user_id, qkeyAmount, '일일 배당 (QKEY)', drId, accrualDailyCreatedAtUtc).run()
          }

          rewardedCount++
          totalQkeyRewarded += qkeyAmount
          stakingProcessed.push(accrualDate)

          // 매칭추천수당 (L1 20%, L2 10%) — 추천인이 accrualDate 시점 active 일 때만
          try {
            const level1Referrer = await db.prepare(`
              SELECT referrer_id FROM users WHERE id = ?
            `).bind(staking.user_id).first()

            if (level1Referrer && level1Referrer.referrer_id) {
              const level1Active = await db.prepare(`
                SELECT id FROM staking
                WHERE user_id = ?
                  AND status = 'active'
                  AND date(start_date, '+9 hours') <= date(?)
                  AND date(end_date, '+9 hours') >= date(?)
                LIMIT 1
              `).bind(level1Referrer.referrer_id, accrualDate, accrualDate).first()

              if (level1Active) {
                // ★ H plan (2026-05-13) ★ — staking_id 인식 중복 가드
                //   기존: (referrer, referee, level, reward_date) 4-tuple 만 → referee 의 첫 staking 만 처리 (결함)
                //   변경: staking_id 까지 5-tuple 정확 매칭 → referee 의 N 개 staking 모두 처리
                //   legacy NULL 호환: staking_id IS NULL + original_amount 같으면 SKIP (이중지급 방지)
                // ★★★ 영구 대책 #1 (2026-05-14) — paid_date 추가 6중 가드 ★★★
                //   같은 paid_date(today) 에 같은 (referrer, referee, level, staking_id) 행 있으면 무조건 SKIP
                const l1Exists = await db.prepare(`
                  SELECT COUNT(*) as count FROM referral_rewards
                  WHERE referrer_id = ? AND referee_id = ? AND level = 1
                    AND (reward_date = ? OR paid_date = ?)
                    AND (staking_id = ? OR (staking_id IS NULL AND original_amount = ?))
                `).bind(level1Referrer.referrer_id, staking.user_id, accrualDate, accrualPaidDate, staking.staking_id, qkeyAmount).first()

                if (l1Exists.count === 0) {
                  let level1Reward = Math.round(qkeyAmount * 0.20)

                  // ★★★ 영구룰 #cap200정책 2️⃣/6️⃣ — L1 receiver(referrer)의 staking 단위 cap 체크 ★★★
                  //   기존: user 단위 합산 → 영구룰 위반
                  //   변경: receiver의 모든 staking을 FIFO 순회, 가장 빠른 미충전 staking으로 분배
                  //         모든 staking이 capped면 0건
                  const l1State = await loadUserCapState(level1Referrer.referrer_id as number)
                  const l1Apply = applyPaidIncrementFIFO(l1State, level1Reward)
                  if (l1Apply.accepted === 0) {
                    // L1 추천인 모든 staking이 capped → 매칭 수당 0건
                    if (!cappedUsers.includes(level1Referrer.referrer_id as number)) cappedUsers.push(level1Referrer.referrer_id as number)
                  } else {
                    level1Reward = l1Apply.accepted
                    if (level1Reward > 0) {
                      await db.prepare(`
                        UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?
                      `).bind(level1Reward, level1Referrer.referrer_id).run()

                      // [패치 2026-05-11] ref_id 1:1 매핑 — referral_rewards 먼저 INSERT 후 last_row_id 캡처
                      // H plan (2026-05-13): staking_id 명시 INSERT (G2-B 영구 인프라 활용)
                      // ★ 영구룰 #정규시각 (2026-05-19) — created_at = paid_date KST 08:00
                      const rrL1Ins = await db.prepare(`
                        INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, staking_id, created_at)
                        VALUES (?, ?, 1, ?, ?, ?, ?, ?, ?)
                      `).bind(level1Referrer.referrer_id, staking.user_id, qkeyAmount, level1Reward, accrualDate, accrualPaidDate, staking.staking_id, accrualDailyCreatedAtUtc).run()
                      const rrL1Id = (rrL1Ins as any)?.meta?.last_row_id ?? null

                      // ★ 영구룰 2️⃣ — L1 receiver의 채워진 staking을 정확히 capped로 표시 (한 건이라도 capped 됐다면)
                      const justCappedL1 = l1State.stakings.find(s => s.id === l1Apply.targetStakingId && s.capped)
                      if (justCappedL1) {
                        try { await db.prepare(`UPDATE staking SET status='capped' WHERE id=? AND status='active'`).bind(justCappedL1.id).run() } catch(e) {}
                      }

                      // EXISTS 가드 (ref_id 1:1) — 동일 referral_rewards.id 에 대응하는 transactions 행이 이미 있으면 차단
                      const l1TxExists2 = await db.prepare(`
                        SELECT id FROM transactions
                        WHERE type = 'referral_reward' AND ref_id = ?
                        LIMIT 1
                      `).bind(rrL1Id).first()
                      if (!l1TxExists2) {
                        // ★ 영구룰 #정규시각 (2026-05-19) — created_at 명시 (KST 08:00:01, DR 보다 1초 늦게, accrualPaidDate 기준)
                        await db.prepare(`
                          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id, created_at)
                          VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?, ?)
                        `).bind(level1Referrer.referrer_id, level1Reward, '추천 보너스 (Level 1)', rrL1Id, accrualReferralCreatedAtUtc).run()
                      }
                    }
                  }
                }

                // 2대 매칭추천수당 (10%)
                const level2Referrer = await db.prepare(`
                  SELECT referrer_id FROM users WHERE id = ?
                `).bind(level1Referrer.referrer_id).first()

                if (level2Referrer && level2Referrer.referrer_id) {
                  const level2Active = await db.prepare(`
                    SELECT id FROM staking
                    WHERE user_id = ?
                      AND status = 'active'
                      AND date(start_date, '+9 hours') <= date(?)
                      AND date(end_date, '+9 hours') >= date(?)
                    LIMIT 1
                  `).bind(level2Referrer.referrer_id, accrualDate, accrualDate).first()

                  if (level2Active) {
                    // ★ H plan (2026-05-13) ★ — staking_id 인식 중복 가드 (L2)
                    //   기존: (referrer, referee, level, reward_date) 4-tuple 만 → referee 의 첫 staking 만 처리 (결함)
                    //   변경: staking_id 까지 5-tuple 정확 매칭 → referee 의 N 개 staking 모두 처리
                    //   legacy NULL 호환: staking_id IS NULL + original_amount 같으면 SKIP (이중지급 방지)
                    // ★★★ 영구 대책 #1 (2026-05-14) — paid_date 추가 6중 가드 ★★★
                    const l2Exists = await db.prepare(`
                      SELECT COUNT(*) as count FROM referral_rewards
                      WHERE referrer_id = ? AND referee_id = ? AND level = 2
                        AND (reward_date = ? OR paid_date = ?)
                        AND (staking_id = ? OR (staking_id IS NULL AND original_amount = ?))
                    `).bind(level2Referrer.referrer_id, staking.user_id, accrualDate, accrualPaidDate, staking.staking_id, qkeyAmount).first()

                    if (l2Exists.count === 0) {
                      let level2Reward = Math.round(qkeyAmount * 0.10)

                      // ★★★ 영구룰 #cap200정책 2️⃣/6️⃣ — L2 receiver의 staking 단위 cap 체크 ★★★
                      const l2State = await loadUserCapState(level2Referrer.referrer_id as number)
                      const l2Apply = applyPaidIncrementFIFO(l2State, level2Reward)
                      if (l2Apply.accepted === 0) {
                        if (!cappedUsers.includes(level2Referrer.referrer_id as number)) cappedUsers.push(level2Referrer.referrer_id as number)
                      } else {
                        level2Reward = l2Apply.accepted
                        if (level2Reward > 0) {
                          await db.prepare(`
                            UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?
                          `).bind(level2Reward, level2Referrer.referrer_id).run()

                          // [패치 2026-05-11] ref_id 1:1 매핑 — referral_rewards 먼저 INSERT 후 last_row_id 캡처
                          // H plan (2026-05-13): staking_id 명시 INSERT (G2-B 영구 인프라 활용)
                          // ★ 영구룰 #정규시각 (2026-05-19) — created_at = paid_date KST 08:00
                          const rrL2Ins = await db.prepare(`
                            INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, staking_id, created_at)
                            VALUES (?, ?, 2, ?, ?, ?, ?, ?, ?)
                          `).bind(level2Referrer.referrer_id, staking.user_id, qkeyAmount, level2Reward, accrualDate, accrualPaidDate, staking.staking_id, accrualDailyCreatedAtUtc).run()
                          const rrL2Id = (rrL2Ins as any)?.meta?.last_row_id ?? null

                          // ★ 영구룰 2️⃣ — L2 receiver의 채워진 staking을 정확히 capped로 표시
                          const justCappedL2 = l2State.stakings.find(s => s.id === l2Apply.targetStakingId && s.capped)
                          if (justCappedL2) {
                            try { await db.prepare(`UPDATE staking SET status='capped' WHERE id=? AND status='active'`).bind(justCappedL2.id).run() } catch(e) {}
                          }

                          // EXISTS 가드 (ref_id 1:1) — 동일 referral_rewards.id 에 대응하는 transactions 행이 이미 있으면 차단
                          const l2TxExists2 = await db.prepare(`
                            SELECT id FROM transactions
                            WHERE type = 'referral_reward' AND ref_id = ?
                            LIMIT 1
                          `).bind(rrL2Id).first()
                          if (!l2TxExists2) {
                            // ★ 영구룰 #정규시각 (2026-05-19) — created_at 명시 (KST 08:00:01, accrualPaidDate 기준)
                            await db.prepare(`
                              INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id, created_at)
                              VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?, ?)
                            `).bind(level2Referrer.referrer_id, level2Reward, '추천 보너스 (Level 2)', rrL2Id, accrualReferralCreatedAtUtc).run()
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          } catch (referralError) {
            console.error(`매칭추천수당 처리 오류 (user ${staking.user_id}, accrual ${accrualDate}):`, referralError)
          }
        }

        if (stakingProcessed.length > 0) {
          processedDates.push({ staking_id: staking.staking_id, dates: stakingProcessed })
        }
      } catch (err) {
        console.error(`보상 지급 오류 (user ${staking.user_id}):`, err)
      }
    }

    const batchProcessed = activeStakings.results.length
    const nextOffset = offset + batchProcessed
    const hasMore = nextOffset < totalActive

    let message = `[기준일(어제) ${yesterdayKst} / 지급처리일 ${today}] batch ${offset}~${nextOffset}/${totalActive} : ${rewardedCount} rewarded across ${processedDates.length} stakings (${totalQkeyRewarded.toLocaleString()} QKEY)`
    if (skippedCount > 0) {
      message += ` | ${skippedCount} completed`
    }
    if (cappedSkipCount > 0) {
      message += ` | ${cappedSkipCount} CAPPED-skip (200% reached)`
    }
    if (hasMore) {
      message += ` | has_more=true (next offset=${nextOffset})`
    }

    // ★ P3 (2026-05-13) ★ — 마지막 batch (hasMore=false) 에서만 daily_cron_lock.last_finished_at 업데이트
    //   배경: 같은 날 같은 source 의 batch 페이지네이션 호출들은 lock row 를 공유.
    //   첫 batch 에서 INSERT, 이후 batch 는 통과만 함. 마지막 batch 가 끝났을 때 finished_at 기록.
    //   → 헬스체크/audit 가 (locked_at 있고 last_finished_at NULL 이고 30분+ 지남) 이면 stale 로 판별.
    let cronFinishedAtKst: string | null = null
    if (!hasMore) {
      try {
        const finishRes = await db.prepare(`
          UPDATE daily_cron_lock
          SET last_finished_at = datetime('now','+9 hours')
          WHERE lock_date = ?
        `).bind(todayKstForLock).run()
        // 업데이트 후 실제 값을 다시 조회해 응답에 포함 (사장님/AI 확인용)
        const row = await db.prepare(`
          SELECT last_finished_at FROM daily_cron_lock WHERE lock_date = ?
        `).bind(todayKstForLock).first() as any
        cronFinishedAtKst = row?.last_finished_at || null
      } catch(e) {
        console.error('[P3] daily_cron_lock.last_finished_at UPDATE 실패:', e)
      }
    }

    return c.json({
      success: true,
      message: message,
      targetDate: yesterdayKst,   // 기준일(어제 KST)
      paidDate: today,            // 처리일(오늘 KST 01:00)
      rewarded: rewardedCount,
      totalQkey: totalQkeyRewarded,
      skipped: skippedCount,
      cappedSkipCount: cappedSkipCount,
      cappedUsers: cappedUsers,
      processedDates: processedDates,
      // ★ batch 페이지네이션 메타 (2026-05-12 사용자 증가 대응) ★
      batchSize,
      offset,
      batch_processed: batchProcessed,
      next_offset: nextOffset,
      total_active: totalActive,
      has_more: hasMore,
      // ★ P3 (2026-05-13) — cron 완료 시각 추적 ★
      cron_finished_at_kst: cronFinishedAtKst,
      cron_completed: !hasMore && cronFinishedAtKst !== null
    })
  } catch (error) {
    console.error('Daily reward error:', error)
    return c.json({ error: t(c, 'rewards.daily_error') }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★ 어드민 수동 데일리 실행 (사장님 2026-05-12 영구 룰) ★★★★★★★★★★★★★★★★★★★★
//   사장님 .md 원문 (2026-05-12):
//     "만약 니가 아침 09시까지 자동크론이 실패해서 못돌릴때를 대비해서 어드민에 수동으로 실행할수 있는 버튼을 만들어줘!
//      그시간뒤에 실행버튼을 사람이 수동으로 클릭했을때는 무조건 별도의 자동클론이 당일에는 내 별도의 명령없이 작동하면 안된다"
//
//   동작:
//   1) Bearer 토큰 어드민 인증 필수
//   2) 같은 날 cron_auto 가 이미 처리했으면 423 (이중 배당 차단)
//   3) 같은 날 manual_admin 이 이미 실행했으면 423 (이중 배당 차단)
//   4) 첫 실행 시 daily_cron_lock 에 source='manual_admin' INSERT → 당일 자동 cron 영구 차단
//   5) 내부적으로 batch 페이지네이션 호출 (X-Cron-Trigger: manual-admin 헤더)
//   6) confirm=GO 게이트 (실수 클릭 방지)
//   7) 사장님 별도 명령 (?force=GO&unlock=GO) 으로만 lock 강제 해제 가능
//
//   영구 룰 #일일 배당 cron 단일화 준수: 1일 1회만 실행 (이중 배당 금지)
//   영구 룰 #신규 (2026-05-12): 수동 버튼 클릭 후 자동 cron 같은 날 작동 금지
app.post('/api/admin/rewards/manual-daily-trigger', async (c) => {
  try {
    // 어드민 Bearer 토큰 인증
    const authHeader = c.req.header('Authorization') || ''
    if (!authHeader.startsWith('Bearer ')) {
      return c.json({ success: false, error: '어드민 인증 필요 (Bearer 토큰)' }, 401)
    }
    const token = authHeader.substring(7)
    if (!verifyAdminToken(token)) {
      return c.json({ success: false, error: '어드민 토큰 검증 실패' }, 401)
    }

    const confirm = c.req.query('confirm') || ''
    if (confirm !== 'GO') {
      return c.json({
        success: false,
        error: '수동 데일리 실행은 confirm=GO 필수입니다. (실수 클릭 방지)',
        usage: 'POST /api/admin/rewards/manual-daily-trigger?confirm=GO'
      }, 400)
    }

    // ============================================================
    // ★ 영구룰 #정규시각 (2026-05-19 KST 08:00 통일) + 사장님 09:00 게이트 명령 ★
    // 매일 KST 08:00 자동 cron 이 정규 실행 → 사용자는 09:00 까지 cron 결과 대기
    // 09:00 이후에도 cron 결과 없으면 (= daily_cron_lock 비어있으면) 긴급 수동 버튼 사용
    // 09:00 이전 수동 누르면 423 차단 (08:00 cron 도착 대기) — 사장님 명령
    // 우회: &force=GO (사장님 별도 명령으로만 강제 실행 가능)
    // ============================================================
    const forceQ = c.req.query('force') || ''
    const nowForGate = new Date()
    // KST hour = UTC hour + 9 (mod 24)
    const kstHourNow = (nowForGate.getUTCHours() + 9) % 24
    const kstMinNow = nowForGate.getUTCMinutes()
    const kstHhmmNow = String(kstHourNow).padStart(2, '0') + ':' + String(kstMinNow).padStart(2, '0')
    if (kstHourNow < 9 && forceQ !== 'GO') {
      return c.json({
        success: false,
        error: `긴급 수동 버튼은 KST 09:00 이후에만 사용 가능합니다 (현재 KST ${kstHhmmNow}). 매일 KST 08:00 자동 cron 결과를 우선 대기하세요. 강제 실행: &force=GO&unlock=GO`,
        blocked_by: 'kst_09_gate',
        current_kst: kstHhmmNow,
        rule: '영구룰 #정규시각 KST 08:00 + 09:00 이전 수동 차단 (사장님 2026-05-19 명령)',
        unlock_hint: '강제 실행 (사장님 명령): POST /api/admin/rewards/manual-daily-trigger?confirm=GO&force=GO&unlock=GO'
      }, 423)
    }

    const db = c.env.DB
    const now = new Date()
    const todayKst = kstDateStr(now)

    // daily_cron_lock 테이블 보장
    try {
      await db.prepare(`
        CREATE TABLE IF NOT EXISTS daily_cron_lock (
          lock_date        TEXT PRIMARY KEY,
          source           TEXT NOT NULL,
          locked_at        TEXT NOT NULL DEFAULT (datetime('now','+9 hours')),
          locked_by        TEXT,
          note             TEXT,
          last_finished_at TEXT
        )
      `).run()
    } catch(e) {}

    // 사장님 강제 해제 옵션 (영구 룰 위반 아님 — 사장님 별도 명령으로만 해제)
    // 위에서 이미 forceQ 선언했으므로 재선언하지 않음
    const unlock = c.req.query('unlock') || ''
    if (forceQ === 'GO' && unlock === 'GO') {
      await db.prepare(`DELETE FROM daily_cron_lock WHERE lock_date = ?`).bind(todayKst).run()
      return c.json({
        success: true,
        message: `[사장님 명령] ${todayKst} daily_cron_lock 강제 해제 완료. 이제 다시 cron 또는 manual 트리거 가능.`,
        unlocked_date: todayKst
      })
    }

    // 기존 lock 체크 — 같은 날 이미 실행되었으면 차단
    const existingLock = await db.prepare(`
      SELECT source, locked_at, locked_by, note FROM daily_cron_lock WHERE lock_date = ?
    `).bind(todayKst).first() as any
    if (existingLock) {
      const srcLabel = existingLock.source === 'cron_auto' ? '자동 cron (KST 08:00)' : '어드민 수동 버튼'
      return c.json({
        success: false,
        error: `오늘(${todayKst}) 데일리 배당은 이미 [${srcLabel}] 에 의해 ${existingLock.locked_at} 에 실행되었습니다. 사장님 별도 명령 없이는 추가 실행 불가 (영구 룰 #이중배당금지).`,
        blocked: true,
        lock: existingLock,
        unlock_hint: '강제 해제: POST /api/admin/rewards/manual-daily-trigger?confirm=GO&force=GO&unlock=GO (사장님 명령)'
      }, 423)
    }

    // 내부적으로 /api/rewards/daily 를 batch 페이지네이션으로 호출
    // X-Cron-Trigger: manual-admin 헤더로 식별
    const BATCH_SIZE = 10
    const MAX_ITER = 50
    let offset = 0
    let iter = 0
    let totalRewarded = 0
    let totalQkey = 0
    const batchLogs: any[] = []

    // 자기 자신을 fetch 호출 (Cloudflare Workers 내부 라우팅)
    // c.req.url 에서 origin 추출
    const reqUrl = new URL(c.req.url)
    const origin = `${reqUrl.protocol}//${reqUrl.host}`

    while (iter < MAX_ITER) {
      iter++
      const targetUrl = `${origin}/api/rewards/daily?batchSize=${BATCH_SIZE}&offset=${offset}`
      const res = await fetch(targetUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': authHeader,
          'X-Cron-Trigger': 'manual-admin',
          'User-Agent': 'manual-admin-button/1.0'
        },
        body: JSON.stringify({})
      })
      const bodyText = await res.text()
      let bodyJson: any = null
      try { bodyJson = JSON.parse(bodyText) } catch(e) { bodyJson = { raw: bodyText } }

      batchLogs.push({
        iter,
        offset,
        status: res.status,
        rewarded: bodyJson?.rewarded || 0,
        totalQkey: bodyJson?.totalQkey || 0,
        batch_processed: bodyJson?.batch_processed || 0,
        has_more: bodyJson?.has_more || false,
        message: bodyJson?.message || null
      })

      if (res.status !== 200) {
        return c.json({
          success: false,
          error: `batch #${iter} 실패 (HTTP ${res.status})`,
          batchLogs,
          totalRewarded,
          totalQkey
        }, 500)
      }
      if (!bodyJson?.success) {
        return c.json({
          success: false,
          error: `batch #${iter} 응답 success=false: ${bodyJson?.error || bodyJson?.message || 'unknown'}`,
          batchLogs,
          totalRewarded,
          totalQkey
        }, 500)
      }
      totalRewarded += (bodyJson.rewarded || 0)
      totalQkey += (bodyJson.totalQkey || 0)
      if (!bodyJson.has_more) break
      offset = bodyJson.next_offset
    }

    return c.json({
      success: true,
      message: `[어드민 수동 실행] ${todayKst} 데일리 배당 완료. 오늘은 자동 cron 영구 차단됨 (사장님 별도 명령 필요).`,
      todayKst,
      totalRewarded,
      totalQkey,
      iterations: iter,
      batchLogs,
      lock_policy: '영구 룰 #신규 (2026-05-12): 수동 버튼 클릭 후 같은 날 자동 cron 작동 금지',
      unlock_command: 'POST /api/admin/rewards/manual-daily-trigger?confirm=GO&force=GO&unlock=GO (사장님 별도 명령 필요)'
    })
  } catch (error: any) {
    console.error('Manual daily trigger error:', error)
    return c.json({ success: false, error: error?.message || 'unknown error' }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★ daily_cron_lock 상태 조회 (어드민 UI 표시용) ★★★★★★★★★★★★★★★★★★★★
app.get('/api/admin/rewards/cron-lock-status', async (c) => {
  try {
    const authHeader = c.req.header('Authorization') || ''
    if (!authHeader.startsWith('Bearer ')) {
      return c.json({ success: false, error: '어드민 인증 필요' }, 401)
    }
    const token = authHeader.substring(7)
    if (!verifyAdminToken(token)) {
      return c.json({ success: false, error: '어드민 토큰 검증 실패' }, 401)
    }

    const db = c.env.DB
    try {
      await db.prepare(`
        CREATE TABLE IF NOT EXISTS daily_cron_lock (
          lock_date        TEXT PRIMARY KEY,
          source           TEXT NOT NULL,
          locked_at        TEXT NOT NULL DEFAULT (datetime('now','+9 hours')),
          locked_by        TEXT,
          note             TEXT,
          last_finished_at TEXT
        )
      `).run()
    } catch(e) {}

    const todayKst = kstDateStr(new Date())
    const todayLock = await db.prepare(`
      SELECT lock_date, source, locked_at, locked_by, note FROM daily_cron_lock WHERE lock_date = ?
    `).bind(todayKst).first() as any
    const recentLocks = await db.prepare(`
      SELECT lock_date, source, locked_at, locked_by, note
      FROM daily_cron_lock
      ORDER BY lock_date DESC LIMIT 14
    `).all()

    return c.json({
      success: true,
      todayKst,
      todayLock: todayLock || null,
      isLockedToday: !!todayLock,
      recentLocks: recentLocks.results
    })
  } catch (error: any) {
    return c.json({ success: false, error: error?.message || 'unknown' }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★ 데일리 cron 리포트 (사장님 명령 2026-06-22) ★★★★★★★★★★★★★★★★★★★★
//   목적: "무조건 클론이 돌면 보고를 해줘! 매일 오전에 돌리고 나서"
//   동작: 최근 N일(기본 10일)의 각 평일에 대해
//         지급대상(active staking, 영업일, start<=d<=end) vs 실지급(daily_rewards reward_date=d)
//         을 자동 대조하여 누락 staking 명단을 산출.
//         + daily_cron_lock 의 cron 완료 시각(last_finished_at) 도 함께 보고.
//   주의: capped(=200% cap 도달 후 정상중단) staking 은 누락에서 제외 (영구룰 #cap200).
//         토/일/공휴일은 영업일이 아니므로 점검 대상에서 자동 제외 (영구룰 #공휴일).
//   읽기전용 (INSERT/UPDATE 절대 없음). GET /api/admin/rewards/cron-report?days=10
app.get('/api/admin/rewards/cron-report', async (c) => {
  try {
    const authHeader = c.req.header('Authorization') || ''
    if (!authHeader.startsWith('Bearer ')) {
      return c.json({ success: false, error: '어드민 인증 필요' }, 401)
    }
    const token = authHeader.substring(7)
    if (!verifyAdminToken(token)) {
      return c.json({ success: false, error: '어드민 토큰 검증 실패' }, 401)
    }

    const db = c.env.DB
    const daysParam = Math.max(1, Math.min(30, parseInt(c.req.query('days') || '10')))
    const todayKst = kstDateStr(new Date())

    // 점검 대상 날짜 목록 (오늘 제외, 어제부터 과거로 daysParam 일, 영업일만)
    const checkDates: string[] = []
    let cursor = new Date(todayKst + 'T00:00:00Z')
    let guard = 0
    while (checkDates.length < daysParam && guard < 60) {
      guard++
      cursor = new Date(cursor.getTime() - 24 * 60 * 60 * 1000)
      const dStr = cursor.toISOString().slice(0, 10)
      const checkDate = new Date(cursor.getTime() - 9 * 60 * 60 * 1000)
      const { isBusinessDay } = isKoreanBusinessDay(checkDate)
      if (isBusinessDay) checkDates.push(dStr)
    }

    // 최근 cron lock 상태
    const recentLocks = await db.prepare(`
      SELECT lock_date, source, locked_at, last_finished_at
      FROM daily_cron_lock ORDER BY lock_date DESC LIMIT 14
    `).all()
    const lockByDate = new Map<string, any>()
    for (const r of (recentLocks.results || []) as any[]) {
      lockByDate.set(String(r.lock_date), r)
    }

    const report: any[] = []
    let totalMissing = 0

    for (const d of checkDates) {
      // 지급대상: active staking, 영업일 d 에 진행 중 (start<=d<=end)
      // capped/completed 는 정상 종료이므로 제외 — 순수 active 만 "지급되어야 할" 대상
      const dueRows = await db.prepare(`
        SELECT s.id AS staking_id, s.user_id, s.amount
        FROM staking s
        WHERE s.status = 'active'
          AND date(s.start_date, '+9 hours') <= ?
          AND date(s.end_date, '+9 hours') >= ?
      `).bind(d, d).all()
      const dueList = (dueRows.results || []) as any[]

      // 실지급: daily_rewards reward_date = d
      const paidRows = await db.prepare(`
        SELECT DISTINCT staking_id FROM daily_rewards WHERE reward_date = ?
      `).bind(d).all()
      const paidSet = new Set<number>()
      for (const r of (paidRows.results || []) as any[]) {
        if (r.staking_id != null) paidSet.add(Number(r.staking_id))
      }

      // 누락 = 지급대상인데 daily_rewards 없는 active staking
      const missing: any[] = []
      for (const due of dueList) {
        if (!paidSet.has(Number(due.staking_id))) {
          missing.push({ staking_id: Number(due.staking_id), user_id: Number(due.user_id), amount: Number(due.amount) })
        }
      }

      // 누락 staking 의 회원 이메일 보강
      if (missing.length > 0) {
        const ids = missing.map(m => m.user_id)
        const ph = ids.map(() => '?').join(',')
        const emailRows = await db.prepare(`SELECT id, email FROM users WHERE id IN (${ph})`).bind(...ids).all()
        const emailById = new Map<number, string>()
        for (const u of (emailRows.results || []) as any[]) emailById.set(Number(u.id), String(u.email))
        for (const m of missing) m.email = emailById.get(m.user_id) || ('user#' + m.user_id)
      }

      const lock = lockByDate.get(d) || null
      totalMissing += missing.length
      report.push({
        date: d,
        due_count: dueList.length,
        paid_count: paidSet.size,
        missing_count: missing.length,
        missing: missing,
        cron_locked_at: lock ? lock.locked_at : null,
        cron_finished_at: lock ? lock.last_finished_at : null,
        cron_completed: !!(lock && lock.last_finished_at),
        status: missing.length === 0 ? 'OK' : 'MISSING'
      })
    }

    return c.json({
      success: true,
      generated_at_kst: kstDateStr(new Date()) + ' ' + new Date(Date.now() + 9 * 3600 * 1000).toISOString().slice(11, 19),
      todayKst,
      checked_business_days: checkDates.length,
      total_missing: totalMissing,
      overall_status: totalMissing === 0 ? 'ALL_OK' : 'HAS_MISSING',
      report
    })
  } catch (error: any) {
    return c.json({ success: false, error: error?.message || 'unknown' }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★ 휴일진입자 전수 평일 누락 점검 (사장님 영구룰 #휴일진입자) ★★★★★★★★★★★★★★★★★★★★
//   사장님 명령 (2026-05-13): "휴일진입자 현황 빨리 추출, 지급 안되었으면 즉각 지급, 상위 매칭 반영, 두번다시 잊지말것"
//
//   진단 범위:
//   - 모든 active staking 중 start_date_kst 가 토/일/공휴일 인 staking 전수
//   - 진입일 이후 ~ 어제(KST) 까지 모든 평일(KST)에 대해 daily_rewards 존재 여부 점검
//   - 누락 평일 발견 시 해당 staking 의 self/L1/L2 누락 QKEY 산출
//
//   경로: GET /api/diag/audit-holiday-entrant-all-weekday?key=ADMIN_PW
app.get('/api/diag/audit-holiday-entrant-all-weekday', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  try {
    const db = c.env.DB
    const now = new Date()
    const todayKst = kstDateStr(now)
    const yesterdayKst = kstDateStr(new Date(now.getTime() - 24 * 60 * 60 * 1000))
    // KST 현재 시각 (audit 스냅샷 촬영 시점) — 사용자/AI 가 stale audit 판별용
    const auditTakenAtKst = new Date(now.getTime() + 9*60*60*1000).toISOString().replace('T',' ').replace('Z','')

    // ★ P1 (2026-05-13) ★ — cron 실행 상태 메타데이터
    //   audit 응답에 오늘 cron 이 이미 돌았는지, 언제 시작했는지 표시 →
    //   "휴일진입자 누락 0건" 같은 결과가 stale snapshot 인지 즉시 판별 가능
    let cronStatusToday: any = null
    let cronStatusYesterday: any = null
    try {
      // daily_cron_lock 테이블 보장 (없으면 생성)
      await db.prepare(`
        CREATE TABLE IF NOT EXISTS daily_cron_lock (
          lock_date        TEXT PRIMARY KEY,
          source           TEXT NOT NULL,
          locked_at        TEXT NOT NULL DEFAULT (datetime('now','+9 hours')),
          locked_by        TEXT,
          note             TEXT,
          last_finished_at TEXT
        )
      `).run()
      // ★ P3 (2026-05-13) ★ — 기존 테이블에 last_finished_at 컬럼 없으면 추가 (멱등)
      try { await db.prepare(`ALTER TABLE daily_cron_lock ADD COLUMN last_finished_at TEXT`).run() } catch(e) {}
      cronStatusToday = await db.prepare(`
        SELECT lock_date, source, locked_at, locked_by, note, last_finished_at FROM daily_cron_lock WHERE lock_date = ?
      `).bind(todayKst).first()
      cronStatusYesterday = await db.prepare(`
        SELECT lock_date, source, locked_at, locked_by, note, last_finished_at FROM daily_cron_lock WHERE lock_date = ?
      `).bind(yesterdayKst).first()
    } catch(e) {}

    // STEP 1: 모든 active staking 추출 + start_date_kst 휴일 여부 판정
    const allActive = await db.prepare(`
      SELECT s.id AS staking_id, s.user_id, s.amount, s.daily_rate, s.status,
             s.start_date,
             date(datetime(s.start_date, '+9 hours')) AS kst_start_date,
             u.name AS user_name, u.email AS user_email,
             u.qkey_balance, u.referrer_id
      FROM staking s JOIN users u ON s.user_id = u.id
      WHERE s.status = 'active'
      ORDER BY s.id ASC
    `).all()

    // STEP 2: 휴일진입자 필터링 (KST 기준 start_date 가 토/일/공휴일)
    const holidayEntrants: any[] = []
    for (const s of (allActive.results as any[])) {
      const startDateObj = new Date(s.kst_start_date + 'T00:00:00+09:00')
      const { isBusinessDay, reason } = isKoreanBusinessDay(startDateObj)
      if (!isBusinessDay) {
        holidayEntrants.push({ ...s, start_reason: reason })
      }
    }

    // STEP 3: 각 휴일진입자별 진입일 다음날 ~ 어제(KST) 까지 평일 데일리 누락 점검
    const auditResults: any[] = []
    let totalMissingSelfQkey = 0
    let totalMissingDays = 0
    const missingByDate: Record<string, { count: number; sum_qkey: number; stakings: number[] }> = {}

    for (const s of holidayEntrants) {
      // 평일 목록 산출: 진입일 다음날부터 어제까지 KST 평일만
      // ★ P1 BUGFIX (2026-05-13) ★
      //   cursor 는 이미 'T00:00:00+09:00' 로 만들어진 KST 정각 Date 객체이므로
      //   kstDateStr(cursor) 만 호출해도 올바른 KST 날짜 문자열이 나옴.
      //   기존 코드: kstDateStr(new Date(cursor.getTime() - 9*60*60*1000)) 는
      //   -9시간을 뺀 후 kstDateStr 내부에서 +9시간을 더해 결과적으로 cursor 자체가 되어야 하지만,
      //   ISO 변환 과정에서 -9시간 보정이 자정을 넘겨 라벨이 -1일 어긋남.
      //   → cursor 그대로 kstDateStr 에 넘기는 것이 정확.
      const weekdaysExpected: string[] = []
      const startObj = new Date(s.kst_start_date + 'T00:00:00+09:00')
      const yestObj = new Date(yesterdayKst + 'T00:00:00+09:00')
      let cursor = new Date(startObj.getTime() + 24 * 60 * 60 * 1000) // 진입일 다음날부터
      while (cursor.getTime() <= yestObj.getTime()) {
        const { isBusinessDay } = isKoreanBusinessDay(cursor)
        if (isBusinessDay) {
          weekdaysExpected.push(kstDateStr(cursor))
        }
        cursor = new Date(cursor.getTime() + 24 * 60 * 60 * 1000)
      }

      // staking 의 기존 daily_rewards 조회
      const paidRows = await db.prepare(`
        SELECT reward_date FROM daily_rewards WHERE staking_id = ?
      `).bind(s.staking_id).all()
      const paidDates = new Set((paidRows.results as any[]).map((r: any) => r.reward_date))

      const missing: string[] = []
      for (const wd of weekdaysExpected) {
        if (!paidDates.has(wd)) missing.push(wd)
      }

      const expectedQkeyPerDay = Math.round(Number(s.amount) * Number(s.daily_rate) * 150)

      // L1/L2 인 referrer 조회
      let l1UserId: number | null = null
      let l2UserId: number | null = null
      let l1Name = '', l2Name = ''
      if (s.referrer_id) {
        const l1u = await db.prepare(`SELECT id, name, referrer_id FROM users WHERE id = ?`).bind(s.referrer_id).first() as any
        if (l1u) {
          l1UserId = l1u.id; l1Name = l1u.name
          if (l1u.referrer_id) {
            const l2u = await db.prepare(`SELECT id, name FROM users WHERE id = ?`).bind(l1u.referrer_id).first() as any
            if (l2u) { l2UserId = l2u.id; l2Name = l2u.name }
          }
        }
      }

      auditResults.push({
        staking_id: s.staking_id,
        user_id: s.user_id,
        user_name: s.user_name,
        user_email: s.user_email,
        amount: s.amount,
        daily_rate: s.daily_rate,
        kst_start_date: s.kst_start_date,
        start_reason: s.start_reason,
        expected_qkey_per_day: expectedQkeyPerDay,
        weekdays_expected: weekdaysExpected,
        weekdays_paid: weekdaysExpected.filter(wd => paidDates.has(wd)),
        weekdays_missing: missing,
        missing_count: missing.length,
        missing_self_qkey: missing.length * expectedQkeyPerDay,
        l1: l1UserId ? { user_id: l1UserId, name: l1Name, qkey_per_day: Math.round(expectedQkeyPerDay * 0.20) } : null,
        l2: l2UserId ? { user_id: l2UserId, name: l2Name, qkey_per_day: Math.round(expectedQkeyPerDay * 0.10) } : null,
      })

      totalMissingSelfQkey += missing.length * expectedQkeyPerDay
      totalMissingDays += missing.length

      for (const m of missing) {
        if (!missingByDate[m]) missingByDate[m] = { count: 0, sum_qkey: 0, stakings: [] }
        missingByDate[m].count++
        missingByDate[m].sum_qkey += expectedQkeyPerDay
        missingByDate[m].stakings.push(s.staking_id)
      }
    }

    // 누락 있는 staking 만 따로
    const missingOnly = auditResults.filter(a => a.missing_count > 0)

    // ★ P1 (2026-05-13) ★ — cron 완료/진행 메타데이터 종합
    //   cron_completed = 오늘 cron lock 이 존재하고 source 가 cron_auto/manual_admin 중 하나
    //   last_cron_run_kst_at = 오늘 cron 의 locked_at (시작 시각)
    //   audit_taken_at_kst = audit 호출 순간 (stale 판별용)
    //   ⚠ last_cron_run_kst_at 이 audit_taken_at_kst 보다 5분 이상 과거이고
    //     missing_count > 0 이면 진짜 누락 (재시도 필요).
    //     반대로 cron 이 아직 안 돌았으면 missing 은 정상 (놀라지 말것).
    const cronCompletedToday = !!cronStatusToday
    const lastCronRunKstAt = cronStatusToday?.locked_at || null
    const stalenessWarning = !cronCompletedToday
      ? `⚠ 오늘(${todayKst}) cron 아직 미실행 — audit 의 weekdays_missing 은 자연스러운 상태입니다. cron 실행 후 재검사하세요.`
      : null

    return c.json({
      success: true,
      audit_today: todayKst,
      audit_yesterday: yesterdayKst,
      // ★ P1 메타데이터 (stale snapshot 판별용) ★
      audit_taken_at_kst: auditTakenAtKst,
      last_cron_run_kst_at: lastCronRunKstAt,
      cron_completed: cronCompletedToday,
      cron_status_today: cronStatusToday,
      cron_status_yesterday: cronStatusYesterday,
      staleness_warning: stalenessWarning,
      policy: '영구룰 #휴일진입자: 휴일(토/일/공휴일) 진입 staking 도 진입일 이후 모든 평일 데일리 지급 의무',
      total_active_stakings: (allActive.results as any[]).length,
      total_holiday_entrants: holidayEntrants.length,
      total_with_missing: missingOnly.length,
      total_missing_days: totalMissingDays,
      total_missing_self_qkey: totalMissingSelfQkey,
      missing_by_date: missingByDate,
      audit_all: auditResults,
      audit_missing_only: missingOnly,
    })
  } catch (error: any) {
    return c.json({ error: error?.message || String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★ 계정별 일일 배당 집계 (사장님 보고용) ★★★★★★★★★★★★★★★★★★★★
//   경로: GET /api/diag/daily-by-paid-date?key=ADMIN_PW&paid_date=YYYY-MM-DD
//   - paid_date 미지정 시 오늘 KST
//   - 응답: 계정별 본인 daily + L1 매칭 + L2 매칭 + 합계
//   - reward_date 기준 + paid_date 기준 모두 집계 (cron 호출 시 paid_date=오늘, reward_date=어제)
app.get('/api/diag/daily-by-paid-date', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const paidDate = c.req.query('paid_date') || kstDateStr(new Date())

    // 본인 daily 집계 (paid_date 기준)
    const dailyByUser = await db.prepare(`
      SELECT
        dr.user_id,
        u.email,
        u.name,
        COUNT(*) as daily_count,
        SUM(dr.usdt_amount) as daily_qkey,
        GROUP_CONCAT(DISTINCT dr.reward_date) as reward_dates
      FROM daily_rewards dr
      LEFT JOIN users u ON u.id = dr.user_id
      WHERE dr.paid_date = ?
      GROUP BY dr.user_id
    `).bind(paidDate).all()

    // L1/L2 매칭 보너스 집계 (paid_date 기준)
    const refByUser = await db.prepare(`
      SELECT
        rr.referrer_id as user_id,
        u.email,
        u.name,
        rr.level,
        COUNT(*) as cnt,
        SUM(rr.reward_amount) as ref_qkey
      FROM referral_rewards rr
      LEFT JOIN users u ON u.id = rr.referrer_id
      WHERE rr.paid_date = ?
      GROUP BY rr.referrer_id, rr.level
    `).bind(paidDate).all()

    // 집계 병합
    const acct: Record<number, any> = {}
    for (const r of dailyByUser.results as any[]) {
      acct[r.user_id] = {
        user_id: r.user_id,
        email: r.email,
        name: r.name,
        own_daily_count: r.daily_count,
        own_daily_qkey: Number(r.daily_qkey || 0),
        reward_dates: r.reward_dates,
        l1_count: 0, l1_qkey: 0,
        l2_count: 0, l2_qkey: 0,
        total_qkey: 0
      }
    }
    for (const r of refByUser.results as any[]) {
      if (!acct[r.user_id]) {
        acct[r.user_id] = {
          user_id: r.user_id, email: r.email, name: r.name,
          own_daily_count: 0, own_daily_qkey: 0, reward_dates: null,
          l1_count: 0, l1_qkey: 0, l2_count: 0, l2_qkey: 0, total_qkey: 0
        }
      }
      if (r.level === 1) {
        acct[r.user_id].l1_count = r.cnt
        acct[r.user_id].l1_qkey = Number(r.ref_qkey || 0)
      } else if (r.level === 2) {
        acct[r.user_id].l2_count = r.cnt
        acct[r.user_id].l2_qkey = Number(r.ref_qkey || 0)
      }
    }
    for (const k of Object.keys(acct)) {
      const a = acct[k as any]
      a.total_qkey = a.own_daily_qkey + a.l1_qkey + a.l2_qkey
    }

    const list = Object.values(acct).sort((a: any, b: any) => b.total_qkey - a.total_qkey)
    const grandTotal = list.reduce((s: number, a: any) => s + a.total_qkey, 0)
    const grandOwn = list.reduce((s: number, a: any) => s + a.own_daily_qkey, 0)
    const grandL1 = list.reduce((s: number, a: any) => s + a.l1_qkey, 0)
    const grandL2 = list.reduce((s: number, a: any) => s + a.l2_qkey, 0)

    return c.json({
      success: true,
      paid_date: paidDate,
      account_count: list.length,
      grand_total_qkey: grandTotal,
      grand_own_daily_qkey: grandOwn,
      grand_l1_qkey: grandL1,
      grand_l2_qkey: grandL2,
      accounts: list
    })
  } catch (error: any) {
    return c.json({ error: error?.message || 'unknown' }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★ 일일 배당 v2 — bottom-up 순회 (사장님 영구 룰 2026-05-12) ★★★★★★★★★★★★★★★★★★★★
//   사장님 .md 원문 (2026-05-12):
//     "무조건 당일 데일리 배당을 실시할 경우에는 배당에 해당하는 맨 아래 데일리 정산된
//      하부부터 데일리 정산을 하면서 위로 올라갈것"
//
//   경로: POST /api/rewards/daily-v2?key=ADMIN_PW&targetDate=YYYY-MM-DD&confirm=GO
//   - confirm=GO 필수 (실 INSERT/UPDATE 작업)
//   - targetDate 미지정 시 오늘 KST (= cron 정상 호출 시 = today)
//   - reward_date = targetDate - 1 (= yesterdayKst)
//   - 사장님 5/11치 5/12 전원 배당: targetDate=2026-05-12 → reward_date=2026-05-11
//
//   bottom-up 처리 절차 (4-PHASE):
//     PHASE 1: yesterdayKst 활성 staking 전체 수집 + 트리 depth 계산
//     PHASE 2: depth 내림차순(max → 0) 정렬 — 자식부터 처리
//     PHASE 3: 본인 daily 일괄 처리 (own_daily INSERT + transactions + 잔액 UPDATE)
//     PHASE 4: 매칭 보너스 처리 (L1 20% / L2 10%) — own_daily 완전 확정 후
//
//   기존 룰 유지: 200% Cap, 휴일 진입자 룰 B, ref_id 1:1, description 한국어, 거치기간 종료 skip
app.post('/api/rewards/daily-v2', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const confirm = c.req.query('confirm') || ''
    if (confirm !== 'GO') return c.json({ error: 'confirm=GO 필요 (실 INSERT/UPDATE 게이트)' }, 400)

    const db = c.env.DB
    const USD_TO_QKEY = 150

    const now = new Date()
    const todayAuto = kstDateStr(now)
    const targetDate = c.req.query('targetDate') || todayAuto
    if (!/^\d{4}-\d{2}-\d{2}$/.test(targetDate)) {
      return c.json({ error: 'targetDate=YYYY-MM-DD 필요' }, 400)
    }
    const today = targetDate
    const tdObj = new Date(today + 'T00:00:00Z')
    const ydObj = new Date(tdObj.getTime() - 24 * 60 * 60 * 1000)
    const yesterdayKst = ydObj.toISOString().slice(0, 10)

    const todayDateObjKst = new Date(today + 'T00:00:00+09:00')
    const { isBusinessDay, reason } = isKoreanBusinessDay(todayDateObjKst)
    if (!isBusinessDay) {
      const reasonText = reason === 'saturday' ? '토요일' : reason === 'sunday' ? '일요일' : '공휴일/국경일'
      return c.json({
        success: true,
        message: `오늘(${today})은 ${reasonText}이므로 배당 처리 불가 (룰 B: 휴일 cron skip).`,
        rewarded: 0, totalQkey: 0, skipped: 0, reason, targetDate: today,
      })
    }

    try { await db.prepare(`ALTER TABLE daily_rewards ADD COLUMN paid_date TEXT`).run() } catch(e) {}
    try { await db.prepare(`ALTER TABLE referral_rewards ADD COLUMN paid_date TEXT`).run() } catch(e) {}

    // === PHASE 1: 활성 staking 전체 수집 ===
    const activeStakings = await db.prepare(`
      SELECT
        s.user_id,
        s.id AS staking_id,
        s.amount,
        s.period_days,
        s.period_months,
        s.daily_rate,
        s.start_date,
        s.end_date,
        s.reset_at,
        date(s.start_date, '+9 hours') AS start_date_kst,
        (SELECT COUNT(*) FROM daily_rewards WHERE staking_id = s.id) AS rewarded_count,
        (SELECT MAX(reward_date) FROM daily_rewards WHERE staking_id = s.id) AS last_reward_date
      FROM staking s
      WHERE s.status = 'active'
        AND date(s.end_date, '+9 hours') >= date(?)
        AND date(s.start_date, '+9 hours') <= date(?)
      ORDER BY s.user_id ASC, s.id ASC
    `).bind(yesterdayKst, yesterdayKst).all()
    const stakingRows = (activeStakings.results || []) as any[]

    if (stakingRows.length === 0) {
      return c.json({
        success: true,
        message: '활성 staking 없음 — 배당 대상 0건',
        targetDate: today, yesterdayKst,
        rewarded: 0, totalQkey: 0,
      })
    }

    // === 회원별 stake_total / paid_total 일괄 조회 (200% Cap target) ===
    const stakeTotalsRaw = await db.prepare(`
      SELECT user_id, COALESCE(SUM(amount), 0) AS total
      FROM staking WHERE status IN ('active','completed','capped')
      GROUP BY user_id
    `).all()
    const stakeTotalByUser = new Map<number, number>()
    for (const r of (stakeTotalsRaw.results || []) as any[]) {
      stakeTotalByUser.set(Number(r.user_id), Number(r.total) || 0)
    }
    const paidTotalsRaw = await db.prepare(`
      SELECT user_id, COALESCE(SUM(amount), 0) AS total
      FROM transactions
      WHERE coin_type = 'QKEY' AND type IN ('daily_qkey', 'referral_reward')
      GROUP BY user_id
    `).all()
    const paidTotalByUser = new Map<number, number>()
    for (const r of (paidTotalsRaw.results || []) as any[]) {
      paidTotalByUser.set(Number(r.user_id), Number(r.total) || 0)
    }
    function targetOf(uid: number): number {
      return (stakeTotalByUser.get(uid) || 0) * 2 * USD_TO_QKEY
    }
    function paidOf(uid: number): number {
      return paidTotalByUser.get(uid) || 0
    }
    function isCapped(uid: number): boolean {
      const t = targetOf(uid)
      return t > 0 && paidOf(uid) >= t
    }
    function remainingOf(uid: number): number {
      const t = targetOf(uid)
      return Math.max(0, t - paidOf(uid))
    }
    function addPaid(uid: number, amt: number): void {
      paidTotalByUser.set(uid, (paidTotalByUser.get(uid) || 0) + amt)
    }

    // === referrer 트리 조회 + depth 계산 ===
    const usersRaw = await db.prepare(`SELECT id, referrer_id FROM users`).all()
    const referrerOf = new Map<number, number | null>()
    for (const u of (usersRaw.results || []) as any[]) {
      referrerOf.set(Number(u.id), u.referrer_id != null ? Number(u.referrer_id) : null)
    }
    const depthMemo = new Map<number, number>()
    function computeDepth(uid: number, stack: Set<number>): number {
      if (depthMemo.has(uid)) return depthMemo.get(uid)!
      if (stack.has(uid)) { depthMemo.set(uid, 0); return 0 }
      stack.add(uid)
      const rid = referrerOf.get(uid)
      if (rid == null) { depthMemo.set(uid, 0); stack.delete(uid); return 0 }
      const d = 1 + computeDepth(rid, stack)
      depthMemo.set(uid, d)
      stack.delete(uid)
      return d
    }
    for (const s of stakingRows) computeDepth(Number(s.user_id), new Set())

    // === PHASE 2: depth 내림차순 정렬 (bottom-up) ===
    stakingRows.sort((a, b) => {
      const da = depthMemo.get(Number(a.user_id)) || 0
      const db_ = depthMemo.get(Number(b.user_id)) || 0
      if (db_ !== da) return db_ - da
      if (Number(a.user_id) !== Number(b.user_id)) return Number(a.user_id) - Number(b.user_id)
      return Number(a.staking_id) - Number(b.staking_id)
    })

    // === PHASE 3: 본인 daily 일괄 처리 ===
    type DailyInsertResult = {
      user_id: number, staking_id: number, reward_date: string,
      qkey_amount: number, dr_id: number | null,
    }
    const dailyInserts: DailyInsertResult[] = []
    let rewardedCount = 0
    let totalQkeyRewarded = 0
    let skippedCount = 0
    let cappedSkipCount = 0
    const cappedUsers: number[] = []
    const processedDates: { staking_id: number, dates: string[] }[] = []

    for (const staking of stakingRows) {
      try {
        const uid = Number(staking.user_id)
        const sid = Number(staking.staking_id)
        const amount = Number(staking.amount) || 0
        const rate = Number(staking.daily_rate) || getDailyRate(amount)
        const periodDays = Number(staking.period_days) || (Number(staking.period_months) * 30) || 0

        if (isCapped(uid)) {
          cappedSkipCount++
          if (!cappedUsers.includes(uid)) cappedUsers.push(uid)
          try { await db.prepare(`UPDATE staking SET status='capped' WHERE user_id=? AND status='active'`).bind(uid).run() } catch(e) {}
          continue
        }

        const accrualDates = getStakingAccrualDatesKst(
          (staking.last_reward_date as string) || null,
          staking.start_date_kst as string,
          yesterdayKst,
          today
        )
        if (accrualDates.length === 0) continue

        const stakingProcessed: string[] = []

        for (const accrualDate of accrualDates) {
          // ★★★ 영구룰 #익일처리 (2026-05-19 사장님 D 명령) ★★★
          // daily-v2 도 cron 본체와 동일하게 reward 별 독립 paid_date 계산
          const accrualPaidDate = nextBusinessDayKstStr(accrualDate)
          const accrualDailyCreatedAtUtc = createdAtUtcForPaidDate(accrualPaidDate, 0)

          const currentRewardedCount = Number(staking.rewarded_count) + stakingProcessed.length
          if (periodDays > 0 && currentRewardedCount >= periodDays) {
            skippedCount++
            break
          }

          const exists = await db.prepare(`
            SELECT COUNT(*) AS count FROM daily_rewards
            WHERE user_id = ? AND staking_id = ? AND reward_date = ?
          `).bind(uid, sid, accrualDate).first() as any
          if (Number(exists?.count || 0) > 0) continue

          if (isCapped(uid)) {
            cappedSkipCount++
            if (!cappedUsers.includes(uid)) cappedUsers.push(uid)
            try { await db.prepare(`UPDATE staking SET status='capped' WHERE user_id=? AND status='active'`).bind(uid).run() } catch(e) {}
            break
          }
          let qkeyAmount = Math.round(amount * rate * USD_TO_QKEY)
          const remaining = remainingOf(uid)
          if (qkeyAmount > remaining) {
            qkeyAmount = Math.max(0, Math.floor(remaining))
          }
          if (qkeyAmount <= 0) {
            cappedSkipCount++
            if (!cappedUsers.includes(uid)) cappedUsers.push(uid)
            try { await db.prepare(`UPDATE staking SET status='capped' WHERE user_id=? AND status='active'`).bind(uid).run() } catch(e) {}
            break
          }

          // ★ D 명령 (2026-05-19): paid_date = accrualPaidDate, created_at = KST 08:00 명시
          const drIns = await db.prepare(`
            INSERT INTO daily_rewards (user_id, staking_id, usdt_amount, reward_date, paid_date, created_at)
            VALUES (?, ?, ?, ?, ?, ?)
          `).bind(uid, sid, qkeyAmount, accrualDate, accrualPaidDate, accrualDailyCreatedAtUtc).run()
          const drId = (drIns as any)?.meta?.last_row_id ?? null

          await db.prepare(`
            UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?
          `).bind(qkeyAmount, uid).run()

          const dqExists = await db.prepare(`
            SELECT id FROM transactions WHERE type = 'daily_qkey' AND ref_id = ? LIMIT 1
          `).bind(drId).first()
          if (!dqExists) {
            // ★ D 명령: tx created_at 명시 (KST 08:00)
            await db.prepare(`
              INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id, created_at)
              VALUES (?, 'daily_qkey', 'QKEY', ?, ?, ?, ?)
            `).bind(uid, qkeyAmount, '일일 배당 (QKEY)', drId, accrualDailyCreatedAtUtc).run()
          }

          addPaid(uid, qkeyAmount)
          dailyInserts.push({ user_id: uid, staking_id: sid, reward_date: accrualDate, qkey_amount: qkeyAmount, dr_id: drId, paid_date: accrualPaidDate, created_at: accrualDailyCreatedAtUtc })
          rewardedCount++
          totalQkeyRewarded += qkeyAmount
          stakingProcessed.push(accrualDate)
        }

        if (stakingProcessed.length > 0) {
          processedDates.push({ staking_id: sid, dates: stakingProcessed })
        }
      } catch (err) {
        console.error(`v2 본인 daily 오류 (user ${staking.user_id}):`, err)
      }
    }

    // === PHASE 4: 매칭 보너스 (L1 20% / L2 10%) ===
    let l1Count = 0, l1Total = 0
    let l2Count = 0, l2Total = 0
    const matchingErrors: any[] = []

    for (const ins of dailyInserts) {
      try {
        const childUid = ins.user_id
        const childOwn = ins.qkey_amount
        const accrualDate = ins.reward_date
        const childStakingId = ins.staking_id  // H plan (2026-05-13) — staking_id 컨텍스트
        // ★ D 명령 (2026-05-19): own daily 와 동일 paid_date / created_at 사용
        const accrualPaidDate = (ins as any).paid_date || nextBusinessDayKstStr(accrualDate)
        const accrualDailyCreatedAtUtc = (ins as any).created_at || createdAtUtcForPaidDate(accrualPaidDate, 0)
        const accrualReferralCreatedAtUtc = createdAtUtcForPaidDate(accrualPaidDate, 1)
        if (childOwn <= 0) continue

        const parentId = referrerOf.get(childUid)
        if (parentId != null) {
          const parentActive = await db.prepare(`
            SELECT id FROM staking
            WHERE user_id = ? AND status = 'active'
              AND date(start_date, '+9 hours') <= date(?)
              AND date(end_date, '+9 hours') >= date(?)
            LIMIT 1
          `).bind(parentId, accrualDate, accrualDate).first()

          if (parentActive) {
            // ★ H plan (2026-05-13) ★ — staking_id 인식 중복 가드 (daily-v2 L1)
            //   기존 4-tuple → 5-tuple (staking_id 추가) + legacy NULL 호환
            const l1Exists = await db.prepare(`
              SELECT COUNT(*) AS count FROM referral_rewards
              WHERE referrer_id = ? AND referee_id = ? AND level = 1 AND reward_date = ?
                AND (staking_id = ? OR (staking_id IS NULL AND original_amount = ?))
            `).bind(parentId, childUid, accrualDate, childStakingId, childOwn).first() as any
            if (Number(l1Exists?.count || 0) === 0) {
              if (!isCapped(parentId)) {
                let l1Reward = Math.round(childOwn * 0.20)
                const l1Remaining = remainingOf(parentId)
                if (l1Reward > l1Remaining) l1Reward = Math.max(0, Math.floor(l1Remaining))
                if (l1Reward > 0) {
                  await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(l1Reward, parentId).run()
                  // H plan (2026-05-13): staking_id 명시 INSERT
                  // ★ D 명령: accrualPaidDate + accrualDailyCreatedAtUtc 사용
                  const rrL1Ins = await db.prepare(`
                    INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, staking_id, created_at)
                    VALUES (?, ?, 1, ?, ?, ?, ?, ?, ?)
                  `).bind(parentId, childUid, childOwn, l1Reward, accrualDate, accrualPaidDate, childStakingId, accrualDailyCreatedAtUtc).run()
                  const rrL1Id = (rrL1Ins as any)?.meta?.last_row_id ?? null
                  const l1TxExists = await db.prepare(`
                    SELECT id FROM transactions WHERE type = 'referral_reward' AND ref_id = ? LIMIT 1
                  `).bind(rrL1Id).first()
                  if (!l1TxExists) {
                    await db.prepare(`
                      INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id, created_at)
                      VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?, ?)
                    `).bind(parentId, l1Reward, '추천 보너스 (Level 1)', rrL1Id, accrualReferralCreatedAtUtc).run()
                  }
                  addPaid(parentId, l1Reward)
                  l1Count++
                  l1Total += l1Reward
                }
              } else {
                try { await db.prepare(`UPDATE staking SET status='capped' WHERE user_id=? AND status='active'`).bind(parentId).run() } catch(e) {}
                if (!cappedUsers.includes(parentId)) cappedUsers.push(parentId)
              }
            }
          }

          const grandId = referrerOf.get(parentId)
          if (grandId != null) {
            const grandActive = await db.prepare(`
              SELECT id FROM staking
              WHERE user_id = ? AND status = 'active'
                AND date(start_date, '+9 hours') <= date(?)
                AND date(end_date, '+9 hours') >= date(?)
              LIMIT 1
            `).bind(grandId, accrualDate, accrualDate).first()

            if (grandActive) {
              // ★ H plan (2026-05-13) ★ — staking_id 인식 중복 가드 (daily-v2 L2)
              const l2Exists = await db.prepare(`
                SELECT COUNT(*) AS count FROM referral_rewards
                WHERE referrer_id = ? AND referee_id = ? AND level = 2 AND reward_date = ?
                  AND (staking_id = ? OR (staking_id IS NULL AND original_amount = ?))
              `).bind(grandId, childUid, accrualDate, childStakingId, childOwn).first() as any
              if (Number(l2Exists?.count || 0) === 0) {
                if (!isCapped(grandId)) {
                  let l2Reward = Math.round(childOwn * 0.10)
                  const l2Remaining = remainingOf(grandId)
                  if (l2Reward > l2Remaining) l2Reward = Math.max(0, Math.floor(l2Remaining))
                  if (l2Reward > 0) {
                    await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(l2Reward, grandId).run()
                    // H plan (2026-05-13): staking_id 명시 INSERT
                    // ★ D 명령: accrualPaidDate + accrualReferralCreatedAtUtc 사용
                    const rrL2Ins = await db.prepare(`
                      INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, staking_id, created_at)
                      VALUES (?, ?, 2, ?, ?, ?, ?, ?, ?)
                    `).bind(grandId, childUid, childOwn, l2Reward, accrualDate, accrualPaidDate, childStakingId, accrualDailyCreatedAtUtc).run()
                    const rrL2Id = (rrL2Ins as any)?.meta?.last_row_id ?? null
                    const l2TxExists = await db.prepare(`
                      SELECT id FROM transactions WHERE type = 'referral_reward' AND ref_id = ? LIMIT 1
                    `).bind(rrL2Id).first()
                    if (!l2TxExists) {
                      await db.prepare(`
                        INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id, created_at)
                        VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?, ?)
                      `).bind(grandId, l2Reward, '추천 보너스 (Level 2)', rrL2Id, accrualReferralCreatedAtUtc).run()
                    }
                    addPaid(grandId, l2Reward)
                    l2Count++
                    l2Total += l2Reward
                  }
                } else {
                  try { await db.prepare(`UPDATE staking SET status='capped' WHERE user_id=? AND status='active'`).bind(grandId).run() } catch(e) {}
                  if (!cappedUsers.includes(grandId)) cappedUsers.push(grandId)
                }
              }
            }
          }
        }
      } catch (err) {
        matchingErrors.push({ user_id: ins.user_id, error: String(err) })
      }
    }

    const grandTotal = totalQkeyRewarded + l1Total + l2Total

    return c.json({
      success: true,
      version: 'v2-bottom-up',
      note: '사장님 영구 룰 (2026-05-12): bottom-up 순회로 자식 own_daily 확정 후 부모 매칭 산출',
      targetDate: today,
      yesterdayKst,
      total_active_staking: stakingRows.length,
      phase3_own_daily: {
        rewarded: rewardedCount,
        total_qkey: totalQkeyRewarded,
        skipped_completed: skippedCount,
        processed_dates_count: processedDates.length,
      },
      phase4_matching: {
        l1_count: l1Count,
        l1_total_qkey: l1Total,
        l2_count: l2Count,
        l2_total_qkey: l2Total,
      },
      cap: {
        capped_skip_count: cappedSkipCount,
        capped_users: cappedUsers,
      },
      grand_total_qkey: grandTotal,
      matching_errors_count: matchingErrors.length,
      matching_errors_sample: matchingErrors.slice(0, 5),
    })
  } catch (error) {
    console.error('daily-v2 error:', error)
    return c.json({ error: String(error) }, 500)
  }
})


// ★★★★★ 5/11 reward_date 안전 배당 — 옵션 (가) 사장님 결재 (2026-05-12) ★★★★★
//   영구 룰 (사장님 .md 2026-05-12):
//     "무조건 당일 데일리 배당을 실시할 경우에는 배당에 해당하는 맨 아래 데일리 정산된
//      하부부터 데일리 정산을 하면서 위로 올라갈것"
//   - bottom-up traversal (depth desc) — leaf → root
//   - 자식 own_daily 확정 → 부모 매칭 (L1 20% / L2 10%)
//   - EXISTS guard 강화 (daily_rewards / referral_rewards / transactions 3중)
//   - 200% Cap, 휴일 진입자 룰 B, ref_id 1:1, description 한국어 안전
//   - chunk-safe: 524 timeout 회피 — &startIdx=N&limitN=M 로 분할 호출 가능
//
//   경로: POST /api/diag/exec-may11-rewards-safe
//     ?key=ADMIN_PW&confirm=GO
//     [&phase=phase3|phase4]  // 기본 both
//     [&startIdx=0&limitN=20] // chunk 분할 (phase3 만 적용; phase4 는 dailyInserts 누적 후 처리)
//   - reward_date 고정 = '2026-05-11'
//   - paid_date 고정 = '2026-05-12'
app.post('/api/diag/exec-may11-rewards-safe', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const dep = assertNotDeprecated(c, 'exec-may11-rewards-safe', '5/11 보정 완료 (2026-05-11). safeInsertTransaction 가드 미적용 → 재호출 시 이중지급 위험')
    if (dep) return dep
    const confirm = c.req.query('confirm') || ''
    if (confirm !== 'GO') return c.json({ error: 'confirm=GO 필요' }, 400)

    const db = c.env.DB
    const USD_TO_QKEY = 150
    const REWARD_DATE = '2026-05-11'
    const PAID_DATE = '2026-05-12'
    const phase = c.req.query('phase') || 'both'  // phase3 / phase4 / both
    const startIdx = Number(c.req.query('startIdx') || '0')
    const limitN = Number(c.req.query('limitN') || '999')

    // === PHASE 1: 활성 staking 수집 (reward_date 기준) ===
    const activeStakings = await db.prepare(`
      SELECT
        s.user_id, s.id AS staking_id, s.amount, s.period_days, s.period_months,
        s.daily_rate, s.start_date, s.end_date,
        date(s.start_date, '+9 hours') AS start_date_kst,
        (SELECT COUNT(*) FROM daily_rewards WHERE staking_id = s.id) AS rewarded_count,
        (SELECT MAX(reward_date) FROM daily_rewards WHERE staking_id = s.id) AS last_reward_date
      FROM staking s
      WHERE s.status = 'active'
        AND date(s.end_date, '+9 hours') >= date(?)
        AND date(s.start_date, '+9 hours') <= date(?)
      ORDER BY s.user_id ASC, s.id ASC
    `).bind(REWARD_DATE, REWARD_DATE).all()
    const stakingRows = (activeStakings.results || []) as any[]

    // === 회원별 stake_total / paid_total ===
    const stakeTotalsRaw = await db.prepare(`
      SELECT user_id, COALESCE(SUM(amount),0) AS total
      FROM staking WHERE status IN ('active','completed','capped')
      GROUP BY user_id
    `).all()
    const stakeTotalByUser = new Map<number, number>()
    for (const r of (stakeTotalsRaw.results || []) as any[]) {
      stakeTotalByUser.set(Number(r.user_id), Number(r.total) || 0)
    }
    const paidTotalsRaw = await db.prepare(`
      SELECT user_id, COALESCE(SUM(amount),0) AS total
      FROM transactions
      WHERE coin_type='QKEY' AND type IN ('daily_qkey','referral_reward')
      GROUP BY user_id
    `).all()
    const paidTotalByUser = new Map<number, number>()
    for (const r of (paidTotalsRaw.results || []) as any[]) {
      paidTotalByUser.set(Number(r.user_id), Number(r.total) || 0)
    }
    const targetOf = (uid: number) => (stakeTotalByUser.get(uid) || 0) * 2 * USD_TO_QKEY
    const paidOf = (uid: number) => paidTotalByUser.get(uid) || 0
    const isCapped = (uid: number) => {
      const t = targetOf(uid); return t > 0 && paidOf(uid) >= t
    }
    const remainingOf = (uid: number) => Math.max(0, targetOf(uid) - paidOf(uid))
    const addPaid = (uid: number, amt: number) => paidTotalByUser.set(uid, (paidTotalByUser.get(uid) || 0) + amt)

    // === referrer 트리 + depth ===
    const usersRaw = await db.prepare(`SELECT id, referrer_id FROM users`).all()
    const referrerOf = new Map<number, number | null>()
    for (const u of (usersRaw.results || []) as any[]) {
      referrerOf.set(Number(u.id), u.referrer_id != null ? Number(u.referrer_id) : null)
    }
    const depthMemo = new Map<number, number>()
    function computeDepth(uid: number, stack: Set<number>): number {
      if (depthMemo.has(uid)) return depthMemo.get(uid)!
      if (stack.has(uid)) { depthMemo.set(uid, 0); return 0 }
      stack.add(uid)
      const rid = referrerOf.get(uid)
      if (rid == null) { depthMemo.set(uid, 0); stack.delete(uid); return 0 }
      const d = 1 + computeDepth(rid, stack)
      depthMemo.set(uid, d)
      stack.delete(uid)
      return d
    }
    for (const s of stakingRows) computeDepth(Number(s.user_id), new Set())

    // === PHASE 2: depth 내림차순 (bottom-up) ===
    stakingRows.sort((a, b) => {
      const da = depthMemo.get(Number(a.user_id)) || 0
      const db_ = depthMemo.get(Number(b.user_id)) || 0
      if (db_ !== da) return db_ - da
      if (Number(a.user_id) !== Number(b.user_id)) return Number(a.user_id) - Number(b.user_id)
      return Number(a.staking_id) - Number(b.staking_id)
    })

    const phase3Rows = stakingRows.slice(startIdx, startIdx + limitN)

    // === PHASE 3: 본인 daily (chunk 분할 가능) ===
    type DailyIns = { user_id: number, staking_id: number, qkey_amount: number, dr_id: number | null }
    const dailyInserts: DailyIns[] = []
    let rewardedCount = 0, totalQkey = 0, skippedExists = 0
    const cappedSkipUsers: number[] = []

    if (phase === 'phase3' || phase === 'both') {
      for (const staking of phase3Rows) {
        try {
          const uid = Number(staking.user_id)
          const sid = Number(staking.staking_id)
          const amount = Number(staking.amount) || 0
          const rate = Number(staking.daily_rate) || getDailyRate(amount)
          const periodDays = Number(staking.period_days) || (Number(staking.period_months) * 30) || 0

          // 거치기간 종료 check
          if (periodDays > 0 && Number(staking.rewarded_count) >= periodDays) {
            skippedExists++
            continue
          }
          // start_date_kst > REWARD_DATE 면 skip
          if (String(staking.start_date_kst) > REWARD_DATE) continue
          if (isCapped(uid)) {
            if (!cappedSkipUsers.includes(uid)) cappedSkipUsers.push(uid)
            continue
          }

          // EXISTS guard 1: daily_rewards
          const drExists = await db.prepare(`
            SELECT COUNT(*) AS c FROM daily_rewards
            WHERE user_id=? AND staking_id=? AND reward_date=?
          `).bind(uid, sid, REWARD_DATE).first() as any
          if (Number(drExists?.c || 0) > 0) { skippedExists++; continue }

          let qkeyAmount = Math.round(amount * rate * USD_TO_QKEY)
          const rem = remainingOf(uid)
          if (qkeyAmount > rem) qkeyAmount = Math.max(0, Math.floor(rem))
          if (qkeyAmount <= 0) {
            if (!cappedSkipUsers.includes(uid)) cappedSkipUsers.push(uid)
            continue
          }

          // INSERT daily_rewards
          const drIns = await db.prepare(`
            INSERT INTO daily_rewards (user_id, staking_id, usdt_amount, reward_date, paid_date)
            VALUES (?, ?, ?, ?, ?)
          `).bind(uid, sid, qkeyAmount, REWARD_DATE, PAID_DATE).run()
          const drId = (drIns as any)?.meta?.last_row_id ?? null

          // 잔액 UPDATE
          await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(qkeyAmount, uid).run()

          // EXISTS guard 2: transactions (ref_id 매칭)
          const txExists = await db.prepare(`
            SELECT id FROM transactions WHERE type='daily_qkey' AND ref_id=? LIMIT 1
          `).bind(drId).first()
          if (!txExists) {
            await db.prepare(`
              INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
              VALUES (?, 'daily_qkey', 'QKEY', ?, ?, ?)
            `).bind(uid, qkeyAmount, '일일 배당 (QKEY)', drId).run()
          }

          addPaid(uid, qkeyAmount)
          dailyInserts.push({ user_id: uid, staking_id: sid, qkey_amount: qkeyAmount, dr_id: drId })
          rewardedCount++
          totalQkey += qkeyAmount
        } catch (err) {
          console.error(`phase3 err user=${staking.user_id}:`, err)
        }
      }
    }

    // === PHASE 4: 매칭 보너스 (L1 20% / L2 10%) ===
    // chunk 처리 시에도 PHASE 4 는 이 호출에서 새로 INSERT 된 dailyInserts 만 처리
    // (다른 chunk 의 dailyInserts 는 EXISTS guard 로 안전)
    let l1Count = 0, l1Total = 0, l2Count = 0, l2Total = 0

    if (phase === 'phase4' || phase === 'both') {
      // phase4 단독 호출 시: 이번 PAID_DATE 에 INSERT 된 daily_rewards 전체에 대해 매칭 산출
      let workItems: { user_id: number, staking_id: number, qkey_amount: number, dr_id: number }[]
      if (phase === 'phase4') {
        const drRows = await db.prepare(`
          SELECT id AS dr_id, user_id, staking_id, usdt_amount AS qkey_amount
          FROM daily_rewards WHERE reward_date=? AND paid_date=?
        `).bind(REWARD_DATE, PAID_DATE).all()
        workItems = ((drRows.results || []) as any[]).map(r => ({
          user_id: Number(r.user_id),
          staking_id: Number(r.staking_id),
          qkey_amount: Number(r.qkey_amount),
          dr_id: Number(r.dr_id),
        }))
      } else {
        workItems = dailyInserts.filter(x => x.dr_id != null) as any[]
      }

      for (const ins of workItems) {
        try {
          const childUid = ins.user_id
          const childOwn = ins.qkey_amount
          const childStakingId = ins.staking_id  // H plan (2026-05-13) — staking_id 컨텍스트
          if (childOwn <= 0) continue
          const parentId = referrerOf.get(childUid)
          if (parentId == null) continue

          // L1
          const parentActive = await db.prepare(`
            SELECT id FROM staking WHERE user_id=? AND status='active'
              AND date(start_date,'+9 hours')<=date(?) AND date(end_date,'+9 hours')>=date(?)
            LIMIT 1
          `).bind(parentId, REWARD_DATE, REWARD_DATE).first()
          if (parentActive) {
            // ★ H plan (2026-05-13) ★ — staking_id 인식 중복 가드 (daily-v2 phase4 L1)
            const l1Exists = await db.prepare(`
              SELECT COUNT(*) AS c FROM referral_rewards
              WHERE referrer_id=? AND referee_id=? AND level=1 AND reward_date=?
                AND (staking_id = ? OR (staking_id IS NULL AND original_amount = ?))
            `).bind(parentId, childUid, REWARD_DATE, childStakingId, childOwn).first() as any
            if (Number(l1Exists?.c || 0) === 0 && !isCapped(parentId)) {
              let l1 = Math.round(childOwn * 0.20)
              const rem = remainingOf(parentId)
              if (l1 > rem) l1 = Math.max(0, Math.floor(rem))
              if (l1 > 0) {
                await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(l1, parentId).run()
                // H plan (2026-05-13): staking_id 명시 INSERT
                const rrIns = await db.prepare(`
                  INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, staking_id)
                  VALUES (?, ?, 1, ?, ?, ?, ?, ?)
                `).bind(parentId, childUid, childOwn, l1, REWARD_DATE, PAID_DATE, childStakingId).run()
                const rrId = (rrIns as any)?.meta?.last_row_id ?? null
                const txEx = await db.prepare(`SELECT id FROM transactions WHERE type='referral_reward' AND ref_id=? LIMIT 1`).bind(rrId).first()
                if (!txEx) {
                  await db.prepare(`
                    INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
                    VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?)
                  `).bind(parentId, l1, '추천 보너스 (Level 1)', rrId).run()
                }
                addPaid(parentId, l1)
                l1Count++; l1Total += l1
              }
            }
          }

          // L2
          const grandId = referrerOf.get(parentId)
          if (grandId == null) continue
          const grandActive = await db.prepare(`
            SELECT id FROM staking WHERE user_id=? AND status='active'
              AND date(start_date,'+9 hours')<=date(?) AND date(end_date,'+9 hours')>=date(?)
            LIMIT 1
          `).bind(grandId, REWARD_DATE, REWARD_DATE).first()
          if (grandActive) {
            // ★ H plan (2026-05-13) ★ — staking_id 인식 중복 가드 (daily-v2 phase4 L2)
            const l2Exists = await db.prepare(`
              SELECT COUNT(*) AS c FROM referral_rewards
              WHERE referrer_id=? AND referee_id=? AND level=2 AND reward_date=?
                AND (staking_id = ? OR (staking_id IS NULL AND original_amount = ?))
            `).bind(grandId, childUid, REWARD_DATE, childStakingId, childOwn).first() as any
            if (Number(l2Exists?.c || 0) === 0 && !isCapped(grandId)) {
              let l2 = Math.round(childOwn * 0.10)
              const rem = remainingOf(grandId)
              if (l2 > rem) l2 = Math.max(0, Math.floor(rem))
              if (l2 > 0) {
                await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(l2, grandId).run()
                // H plan (2026-05-13): staking_id 명시 INSERT
                const rrIns = await db.prepare(`
                  INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, staking_id)
                  VALUES (?, ?, 2, ?, ?, ?, ?, ?)
                `).bind(grandId, childUid, childOwn, l2, REWARD_DATE, PAID_DATE, childStakingId).run()
                const rrId = (rrIns as any)?.meta?.last_row_id ?? null
                const txEx = await db.prepare(`SELECT id FROM transactions WHERE type='referral_reward' AND ref_id=? LIMIT 1`).bind(rrId).first()
                if (!txEx) {
                  await db.prepare(`
                    INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
                    VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?)
                  `).bind(grandId, l2, '추천 보너스 (Level 2)', rrId).run()
                }
                addPaid(grandId, l2)
                l2Count++; l2Total += l2
              }
            }
          }
        } catch (err) {
          console.error(`phase4 err user=${ins.user_id}:`, err)
        }
      }
    }

    return c.json({
      success: true,
      reward_date: REWARD_DATE,
      paid_date: PAID_DATE,
      phase,
      startIdx, limitN,
      total_active_staking: stakingRows.length,
      phase3_processed: phase3Rows.length,
      phase3_result: {
        rewarded: rewardedCount,
        total_qkey: totalQkey,
        skipped_exists_or_completed: skippedExists,
      },
      phase4_result: {
        l1_count: l1Count, l1_total_qkey: l1Total,
        l2_count: l2Count, l2_total_qkey: l2Total,
      },
      capped_skip_users: cappedSkipUsers,
      grand_total_qkey: totalQkey + l1Total + l2Total,
      next_chunk_hint: (phase3Rows.length === limitN && startIdx + limitN < stakingRows.length)
        ? `?confirm=GO&phase=phase3&startIdx=${startIdx + limitN}&limitN=${limitN}` : null,
    })
  } catch (error) {
    console.error('exec-may11-rewards-safe error:', error)
    return c.json({ error: String(error) }, 500)
  }
})


// ★★★★★ 5/12 v2 cron 오염분 전체 DELETE — 사장님 옵션 A 결재 (2026-05-12) ★★★★★
//   대상: paid_date = '2026-05-12' 인 daily_rewards / referral_rewards + 관련 transactions
//   처리:
//     1. daily_rewards (paid_date='2026-05-12') 식별 → ref_id 로 연결된 daily_qkey tx 삭제
//     2. referral_rewards (paid_date='2026-05-12') 식별 → ref_id 로 연결된 referral_reward tx 삭제
//     3. daily_rewards / referral_rewards 행 자체 삭제
//     4. 사용자별 qkey_balance 환원 (차감)
//   gate: key=ADMIN_PW + confirm=GO
app.post('/api/diag/exec-delete-may12-v2-pollution', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const confirm = c.req.query('confirm') || ''
    const dryRun = confirm !== 'GO'
    const db = c.env.DB
    const paidDate = '2026-05-12'

    // STEP A: 삭제 대상 식별
    const drRows = await db.prepare(`
      SELECT id, user_id, staking_id, usdt_amount, reward_date, paid_date
      FROM daily_rewards WHERE paid_date = ?
    `).bind(paidDate).all()
    const drList = (drRows.results || []) as any[]
    const drIds = drList.map(r => Number(r.id))

    const rrRows = await db.prepare(`
      SELECT id, referrer_id, referee_id, level, reward_amount, reward_date, paid_date
      FROM referral_rewards WHERE paid_date = ?
    `).bind(paidDate).all()
    const rrList = (rrRows.results || []) as any[]
    const rrIds = rrList.map(r => Number(r.id))

    // STEP B: 연결된 transactions 식별 (ref_id 매칭) + 미연결 v2 tx (created_at KST 5/12 + daily_qkey/referral_reward)
    const dqTxRows = drIds.length > 0
      ? await db.prepare(`
          SELECT id, user_id, amount FROM transactions
          WHERE type = 'daily_qkey' AND ref_id IN (${drIds.map(()=>'?').join(',')})
        `).bind(...drIds).all()
      : { results: [] as any[] }
    const dqTxList = ((dqTxRows as any).results || []) as any[]

    const rrTxRows = rrIds.length > 0
      ? await db.prepare(`
          SELECT id, user_id, amount FROM transactions
          WHERE type = 'referral_reward' AND ref_id IN (${rrIds.map(()=>'?').join(',')})
        `).bind(...rrIds).all()
      : { results: [] as any[] }
    const rrTxList = ((rrTxRows as any).results || []) as any[]

    // 추가: paid_date='2026-05-12' 인데 ref_id 가 누락된 tx (cutoff 보호용)
    const orphanTxRows = await db.prepare(`
      SELECT id, user_id, type, amount, description, created_at
      FROM transactions
      WHERE date(created_at, '+9 hours') = ?
        AND type IN ('daily_qkey', 'referral_reward')
        AND (ref_id IS NULL OR ref_id NOT IN (
          SELECT id FROM daily_rewards WHERE paid_date != ?
          UNION ALL
          SELECT id FROM referral_rewards WHERE paid_date != ?
        ))
    `).bind(paidDate, paidDate, paidDate).all()
    const orphanTxList = (orphanTxRows.results || []) as any[]

    // 모든 tx id 집합 (중복 제거)
    const allTxIdsSet = new Set<number>()
    for (const t of dqTxList) allTxIdsSet.add(Number(t.id))
    for (const t of rrTxList) allTxIdsSet.add(Number(t.id))
    for (const t of orphanTxList) allTxIdsSet.add(Number(t.id))
    const allTxIds = Array.from(allTxIdsSet)

    // STEP C: 사용자별 환원 금액 집계
    const refundByUser = new Map<number, number>()
    const txDetailRows = allTxIds.length > 0
      ? await db.prepare(`
          SELECT id, user_id, amount FROM transactions
          WHERE id IN (${allTxIds.map(()=>'?').join(',')})
        `).bind(...allTxIds).all()
      : { results: [] as any[] }
    for (const t of ((txDetailRows as any).results || [])) {
      const uid = Number(t.user_id)
      refundByUser.set(uid, (refundByUser.get(uid) || 0) + Number(t.amount || 0))
    }

    if (dryRun) {
      return c.json({
        success: true,
        mode: 'dry_run',
        note: 'DB 무변경. confirm=GO 추가 시 실제 삭제 + 잔액 환원',
        paid_date_target: paidDate,
        delete_plan: {
          daily_rewards_count: drList.length,
          daily_rewards_ids: drIds,
          referral_rewards_count: rrList.length,
          referral_rewards_ids: rrIds,
          transactions_count: allTxIds.length,
          transactions_ids: allTxIds,
          refund_by_user: Object.fromEntries(refundByUser),
          total_refund_qkey: Array.from(refundByUser.values()).reduce((s,v)=>s+v,0),
        }
      })
    }

    // STEP D: 실제 삭제 (사용자 GO)
    let deletedTxCount = 0
    let deletedDrCount = 0
    let deletedRrCount = 0
    let balanceUpdatedCount = 0

    // 1. transactions 삭제 (chunks of 50)
    for (let i = 0; i < allTxIds.length; i += 50) {
      const chunk = allTxIds.slice(i, i + 50)
      const res = await db.prepare(`
        DELETE FROM transactions WHERE id IN (${chunk.map(()=>'?').join(',')})
      `).bind(...chunk).run()
      deletedTxCount += Number((res as any)?.meta?.changes || 0)
    }

    // 2. daily_rewards 삭제
    for (let i = 0; i < drIds.length; i += 50) {
      const chunk = drIds.slice(i, i + 50)
      const res = await db.prepare(`
        DELETE FROM daily_rewards WHERE id IN (${chunk.map(()=>'?').join(',')})
      `).bind(...chunk).run()
      deletedDrCount += Number((res as any)?.meta?.changes || 0)
    }

    // 3. referral_rewards 삭제
    for (let i = 0; i < rrIds.length; i += 50) {
      const chunk = rrIds.slice(i, i + 50)
      const res = await db.prepare(`
        DELETE FROM referral_rewards WHERE id IN (${chunk.map(()=>'?').join(',')})
      `).bind(...chunk).run()
      deletedRrCount += Number((res as any)?.meta?.changes || 0)
    }

    // 4. 사용자별 잔액 차감 환원
    for (const [uid, amt] of refundByUser.entries()) {
      const res = await db.prepare(`
        UPDATE users SET qkey_balance = MAX(0, qkey_balance - ?) WHERE id = ?
      `).bind(amt, uid).run()
      balanceUpdatedCount += Number((res as any)?.meta?.changes || 0)
    }

    return c.json({
      success: true,
      mode: 'exec',
      paid_date_target: paidDate,
      result: {
        deleted_transactions: deletedTxCount,
        deleted_daily_rewards: deletedDrCount,
        deleted_referral_rewards: deletedRrCount,
        users_balance_refunded: balanceUpdatedCount,
        total_refund_qkey: Array.from(refundByUser.values()).reduce((s,v)=>s+v,0),
        refund_by_user: Object.fromEntries(refundByUser),
      },
      note: '5/12 v2 cron 오염분 전부 삭제 완료. 사장님 결재 후 v2 결함 수정 + 재실행 단계 진행 가능'
    })
  } catch (error) {
    console.error('exec-delete-may12-v2-pollution error:', error)
    return c.json({ error: String(error) }, 500)
  }
})


// ★★★★★ 5/11 Phase 4 referral_rewards 만 정밀 삭제 — 옵션 A (2026-05-12, 중복지급 사고 대응) ★★★★★
//   배경: exec-may11-rewards-safe phase4 호출이 curl timeout 후 다중 재호출되며
//         referral_rewards 75건 삽입 (preview 예측 48건 대비 27건 초과, 15 그룹 중복 확인)
//   대상: paid_date='2026-05-12' AND reward_date='2026-05-11' 의 referral_rewards 전부 + 매칭 tx
//   보존: paid_date='2026-05-12' 의 daily_rewards 50건 (Phase 3 own_daily, 정상) — 절대 보존
//   처리:
//     1. referral_rewards (paid_date='2026-05-12', reward_date='2026-05-11') 식별
//     2. transactions (type='referral_reward', ref_id IN 위 목록) 식별
//     3. 추가: created_at KST=2026-05-12 인 type='referral_reward' orphan tx (ref_id null/dangling) 식별
//     4. transactions 삭제 → referral_rewards 삭제 → qkey_balance 차감
//   gate: key=ADMIN_PW + (dryRun 기본) / confirm=GO 시 실행
app.post('/api/diag/exec-delete-may11-phase4-only', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const confirm = c.req.query('confirm') || ''
    const dryRun = confirm !== 'GO'
    const db = c.env.DB
    const PAID_DATE = '2026-05-12'
    const REWARD_DATE = '2026-05-11'

    // STEP A: 삭제 대상 referral_rewards 식별 (paid + reward 둘 다 일치)
    const rrRows = await db.prepare(`
      SELECT id, referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date
      FROM referral_rewards
      WHERE paid_date = ? AND reward_date = ?
    `).bind(PAID_DATE, REWARD_DATE).all()
    const rrList = (rrRows.results || []) as any[]
    const rrIds = rrList.map(r => Number(r.id))

    // STEP B: 매칭 transactions 식별 (ref_id IN rrIds)
    const rrTxRows = rrIds.length > 0
      ? await db.prepare(`
          SELECT id, user_id, amount, ref_id FROM transactions
          WHERE type = 'referral_reward' AND ref_id IN (${rrIds.map(()=>'?').join(',')})
        `).bind(...rrIds).all()
      : { results: [] as any[] }
    const rrTxList = ((rrTxRows as any).results || []) as any[]

    // STEP C: orphan tx (5/12 created + referral_reward + ref_id NULL OR ref_id 가 rrIds 와 무관)
    //   — Phase 4 중복 실행 시 일부 tx 가 ref_id 매칭 안 될 수 있음
    const orphanRows = await db.prepare(`
      SELECT id, user_id, amount, ref_id, description, created_at
      FROM transactions
      WHERE type = 'referral_reward'
        AND date(created_at, '+9 hours') = ?
        AND (
          ref_id IS NULL
          OR ref_id NOT IN (SELECT id FROM referral_rewards)
        )
    `).bind(PAID_DATE).all()
    const orphanList = (orphanRows.results || []) as any[]

    // 모든 tx id 집합 (중복 제거)
    const allTxIdsSet = new Set<number>()
    for (const t of rrTxList) allTxIdsSet.add(Number(t.id))
    for (const t of orphanList) allTxIdsSet.add(Number(t.id))
    const allTxIds = Array.from(allTxIdsSet)

    // STEP D: 사용자별 환원 금액 집계
    const refundByUser = new Map<number, number>()
    const txDetailRows = allTxIds.length > 0
      ? await db.prepare(`
          SELECT id, user_id, amount FROM transactions
          WHERE id IN (${allTxIds.map(()=>'?').join(',')})
        `).bind(...allTxIds).all()
      : { results: [] as any[] }
    for (const t of ((txDetailRows as any).results || [])) {
      const uid = Number(t.user_id)
      refundByUser.set(uid, (refundByUser.get(uid) || 0) + Number(t.amount || 0))
    }

    // 중복 그룹 분석 (보고용)
    const dupKey = new Map<string, number>()
    for (const t of rrTxList) {
      const k = `u${t.user_id}_a${t.amount}`
      dupKey.set(k, (dupKey.get(k) || 0) + 1)
    }
    const dupGroups = Array.from(dupKey.entries()).filter(([_, v]) => v > 1)
      .map(([k, v]) => ({ key: k, count: v }))

    if (dryRun) {
      return c.json({
        success: true,
        mode: 'dry_run',
        note: 'DB 무변경. Phase 3 daily 50건은 보존. confirm=GO 추가 시 referral_rewards 만 삭제 + 잔액 환원',
        target: { paid_date: PAID_DATE, reward_date: REWARD_DATE },
        preserved: {
          phase3_daily_rewards_paid_2026_05_12: '50건 / 162,150 QKEY (Phase 3 정상분, 절대 보존)',
        },
        delete_plan: {
          referral_rewards_count: rrList.length,
          referral_rewards_ids: rrIds,
          ref_id_matched_tx_count: rrTxList.length,
          orphan_tx_count: orphanList.length,
          total_tx_count: allTxIds.length,
          total_tx_ids: allTxIds,
          dup_groups: dupGroups,
          refund_by_user: Object.fromEntries(refundByUser),
          total_refund_qkey: Array.from(refundByUser.values()).reduce((s,v)=>s+v,0),
        },
        next_step: 'confirm=GO 추가 호출 시 실제 삭제 진행 → 이후 phase4 EXISTS guard 검증 후 재실행 결재 요청',
      })
    }

    // STEP E: 실제 삭제 (confirm=GO)
    let deletedTxCount = 0
    let deletedRrCount = 0
    let balanceUpdatedCount = 0

    // 1. transactions 삭제 (chunks of 50)
    for (let i = 0; i < allTxIds.length; i += 50) {
      const chunk = allTxIds.slice(i, i + 50)
      const res = await db.prepare(`
        DELETE FROM transactions WHERE id IN (${chunk.map(()=>'?').join(',')})
      `).bind(...chunk).run()
      deletedTxCount += Number((res as any)?.meta?.changes || 0)
    }

    // 2. referral_rewards 삭제
    for (let i = 0; i < rrIds.length; i += 50) {
      const chunk = rrIds.slice(i, i + 50)
      const res = await db.prepare(`
        DELETE FROM referral_rewards WHERE id IN (${chunk.map(()=>'?').join(',')})
      `).bind(...chunk).run()
      deletedRrCount += Number((res as any)?.meta?.changes || 0)
    }

    // 3. 사용자별 잔액 차감 환원 (MAX(0, balance - amt))
    for (const [uid, amt] of refundByUser.entries()) {
      const res = await db.prepare(`
        UPDATE users SET qkey_balance = MAX(0, qkey_balance - ?) WHERE id = ?
      `).bind(amt, uid).run()
      balanceUpdatedCount += Number((res as any)?.meta?.changes || 0)
    }

    return c.json({
      success: true,
      mode: 'exec',
      target: { paid_date: PAID_DATE, reward_date: REWARD_DATE },
      preserved: 'Phase 3 daily_rewards 50건 (paid_date=2026-05-12) 보존됨',
      result: {
        deleted_transactions: deletedTxCount,
        deleted_referral_rewards: deletedRrCount,
        users_balance_refunded: balanceUpdatedCount,
        total_refund_qkey: Array.from(refundByUser.values()).reduce((s,v)=>s+v,0),
        refund_by_user: Object.fromEntries(refundByUser),
        dup_groups_detected: dupGroups,
      },
      next_step: 'Phase 4 EXISTS guard 정밀 검증 후 사장님 결재 받아 재실행 (또는 abandon)'
    })
  } catch (error) {
    console.error('exec-delete-may11-phase4-only error:', error)
    return c.json({ error: String(error) }, 500)
  }
})


// ★★★★★ 특정 user 지급 내역서 — daily_rewards / referral_rewards / transactions 합산 (2026-05-12) ★★★★★
//   경로: GET /api/diag/user-payout-ledger?user_id=N&key=ADMIN_PW [&from=YYYY-MM-DD] [&to=YYYY-MM-DD]
//   조회: 해당 user 의 모든 QKEY 수령 내역 (own_daily + referral_reward L1/L2) + 잔액
//   기본 기간: 전체 (from/to 없을 때)
app.get('/api/diag/user-payout-ledger', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const userIdQ = c.req.query('user_id') || ''
    const userId = Number(userIdQ)
    if (!Number.isFinite(userId) || userId <= 0) return c.json({ error: 'invalid user_id' }, 400)
    const from = c.req.query('from') || ''
    const to = c.req.query('to') || ''
    const db = c.env.DB

    // user 정보
    const user = await db.prepare(`
      SELECT id, name, email, referrer_id, qkey_balance, qta_balance, qx_balance
      FROM users WHERE id = ?
    `).bind(userId).first() as any
    if (!user) return c.json({ error: 'user not found' }, 404)

    // staking 정보
    const stakings = await db.prepare(`
      SELECT id, amount, daily_rate, period_days, period_months,
        date(start_date,'+9 hours') AS start_kst,
        date(end_date,'+9 hours') AS end_kst, status
      FROM staking WHERE user_id = ? ORDER BY id
    `).bind(userId).all()

    // daily_rewards (own_daily)
    const drQuery = from && to
      ? `SELECT id, staking_id, usdt_amount AS qkey_amount, reward_date, paid_date
         FROM daily_rewards WHERE user_id = ? AND reward_date >= ? AND reward_date <= ?
         ORDER BY reward_date, staking_id`
      : `SELECT id, staking_id, usdt_amount AS qkey_amount, reward_date, paid_date
         FROM daily_rewards WHERE user_id = ?
         ORDER BY reward_date, staking_id`
    const drStmt = from && to ? db.prepare(drQuery).bind(userId, from, to) : db.prepare(drQuery).bind(userId)
    const drRows = await drStmt.all()
    const drList = (drRows.results || []) as any[]

    // referral_rewards (받은 매칭 보너스, referrer_id 기준)
    const rrQuery = from && to
      ? `SELECT id, referee_id, level, original_amount, reward_amount, reward_date, paid_date
         FROM referral_rewards WHERE referrer_id = ? AND reward_date >= ? AND reward_date <= ?
         ORDER BY reward_date, level, referee_id`
      : `SELECT id, referee_id, level, original_amount, reward_amount, reward_date, paid_date
         FROM referral_rewards WHERE referrer_id = ?
         ORDER BY reward_date, level, referee_id`
    const rrStmt = from && to ? db.prepare(rrQuery).bind(userId, from, to) : db.prepare(rrQuery).bind(userId)
    const rrRows = await rrStmt.all()
    const rrList = (rrRows.results || []) as any[]

    // transactions (모든 QKEY 입금)
    const txQuery = from && to
      ? `SELECT id, type, coin_type, amount, description, ref_id,
                created_at, date(created_at,'+9 hours') AS created_kst
         FROM transactions
         WHERE user_id = ? AND coin_type = 'QKEY' AND amount > 0
           AND date(created_at,'+9 hours') >= ? AND date(created_at,'+9 hours') <= ?
         ORDER BY id`
      : `SELECT id, type, coin_type, amount, description, ref_id,
                created_at, date(created_at,'+9 hours') AS created_kst
         FROM transactions
         WHERE user_id = ? AND coin_type = 'QKEY' AND amount > 0
         ORDER BY id`
    const txStmt = from && to ? db.prepare(txQuery).bind(userId, from, to) : db.prepare(txQuery).bind(userId)
    const txRows = await txStmt.all()
    const txList = (txRows.results || []) as any[]

    // 합계 산출
    const drSum = drList.reduce((s, r) => s + Number(r.qkey_amount || 0), 0)
    const rrL1Sum = rrList.filter(r => Number(r.level) === 1).reduce((s, r) => s + Number(r.reward_amount || 0), 0)
    const rrL2Sum = rrList.filter(r => Number(r.level) === 2).reduce((s, r) => s + Number(r.reward_amount || 0), 0)
    const rrL1Count = rrList.filter(r => Number(r.level) === 1).length
    const rrL2Count = rrList.filter(r => Number(r.level) === 2).length
    const txSum = txList.reduce((s, r) => s + Number(r.amount || 0), 0)
    const txByType: Record<string, { count: number, sum: number }> = {}
    for (const t of txList) {
      const k = String(t.type)
      if (!txByType[k]) txByType[k] = { count: 0, sum: 0 }
      txByType[k].count++
      txByType[k].sum += Number(t.amount || 0)
    }

    // stake_total + target + remaining (200% Cap)
    const stakeTotal = (stakings.results || []).reduce((s: number, r: any) => {
      if (['active','completed','capped'].includes(String(r.status))) return s + Number(r.amount || 0)
      return s
    }, 0)
    const target = stakeTotal * 2 * 150
    const remaining = Math.max(0, target - txSum)
    const cappedPercent = target > 0 ? (txSum / target * 100) : 0

    return c.json({
      success: true,
      user: {
        id: user.id, name: user.name, email: user.email,
        referrer_id: user.referrer_id,
        qkey_balance: user.qkey_balance, qta_balance: user.qta_balance, qx_balance: user.qx_balance,
      },
      stakings: stakings.results || [],
      filter: { from: from || 'ALL', to: to || 'ALL' },
      summary: {
        own_daily_count: drList.length,
        own_daily_sum_qkey: drSum,
        referral_l1_count: rrL1Count,
        referral_l1_sum_qkey: rrL1Sum,
        referral_l2_count: rrL2Count,
        referral_l2_sum_qkey: rrL2Sum,
        transactions_count: txList.length,
        transactions_sum_qkey: txSum,
        transactions_by_type: txByType,
      },
      cap_progress: {
        stake_total_usdt: stakeTotal,
        target_qkey: target,
        paid_total_qkey: txSum,
        remaining_qkey: remaining,
        percent: Math.round(cappedPercent * 100) / 100,
      },
      daily_rewards: drList,
      referral_rewards: rrList,
      transactions: txList,
    })
  } catch (error) {
    console.error('user-payout-ledger error:', error)
    return c.json({ error: String(error) }, 500)
  }
})


// ★★★★★ 사용자 지급 내역서 read-only 조회 — diag (2026-05-12, 사장님 보고용) ★★★★★
//   경로: GET /api/diag/user-statement?email=...&key=ADMIN_PW  또는  ?user_id=N&key=...
//   반환:
//     - users 기본 정보 + qkey_balance
//     - staking 내역 (전체)
//     - daily_rewards 전체 (reward_date 오름차순)
//     - referral_rewards 본인이 받은 것 (referrer_id=본인)
//     - transactions QKEY 관련 (daily_qkey + referral_reward) 전체 + 합계
//     - 200% Cap 진행률
//   read-only, DB 무변경
app.get('/api/diag/user-statement', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const USD_TO_QKEY = 150

    const emailQ = c.req.query('email') || ''
    const userIdQ = c.req.query('user_id') || ''

    let user: any = null
    if (userIdQ) {
      user = await db.prepare(`
        SELECT id, email, name, qkey_balance, qta_balance, qx_balance, usdt_balance,
               referrer_id, referral_code, created_at
        FROM users WHERE id = ?
      `).bind(Number(userIdQ)).first()
    } else if (emailQ) {
      user = await db.prepare(`
        SELECT id, email, name, qkey_balance, qta_balance, qx_balance, usdt_balance,
               referrer_id, referral_code, created_at
        FROM users WHERE email = ?
      `).bind(emailQ).first()
    } else {
      return c.json({ error: 'email or user_id required' }, 400)
    }
    if (!user) return c.json({ error: 'user not found' }, 404)
    const uid = Number(user.id)

    // staking
    const stRows = await db.prepare(`
      SELECT id, amount, daily_rate, period_days, period_months, status,
             date(start_date,'+9 hours') AS start_date_kst,
             date(end_date,'+9 hours') AS end_date_kst,
             (SELECT COUNT(*) FROM daily_rewards WHERE staking_id = staking.id) AS rewarded_count
      FROM staking WHERE user_id = ?
      ORDER BY id
    `).bind(uid).all()
    const stakings = (stRows.results || []) as any[]

    // daily_rewards (본인)
    const drRows = await db.prepare(`
      SELECT id, staking_id, usdt_amount AS qkey_amount, reward_date, paid_date,
             datetime(created_at,'+9 hours') AS created_at_kst
      FROM daily_rewards WHERE user_id = ?
      ORDER BY reward_date ASC, id ASC
    `).bind(uid).all()
    const dailyRewards = (drRows.results || []) as any[]
    const dailySum = dailyRewards.reduce((s, r) => s + Number(r.qkey_amount || 0), 0)

    // referral_rewards (본인이 받은 매칭 보너스)
    const rrRows = await db.prepare(`
      SELECT r.id, r.referrer_id, r.referee_id, r.level, r.original_amount, r.reward_amount,
             r.reward_date, r.paid_date,
             datetime(r.created_at,'+9 hours') AS created_at_kst,
             u.email AS referee_email
      FROM referral_rewards r
      LEFT JOIN users u ON r.referee_id = u.id
      WHERE r.referrer_id = ?
      ORDER BY r.reward_date ASC, r.id ASC
    `).bind(uid).all()
    const referralRewards = (rrRows.results || []) as any[]
    const refSum = referralRewards.reduce((s, r) => s + Number(r.reward_amount || 0), 0)

    // transactions (QKEY 관련 전체)
    const txRows = await db.prepare(`
      SELECT id, type, coin_type, amount, description, ref_id,
             datetime(created_at,'+9 hours') AS created_at_kst
      FROM transactions
      WHERE user_id = ? AND coin_type = 'QKEY'
      ORDER BY datetime(created_at,'+9 hours') ASC, id ASC
    `).bind(uid).all()
    const txs = (txRows.results || []) as any[]
    const txDailySum = txs.filter(t => t.type === 'daily_qkey').reduce((s, t) => s + Number(t.amount || 0), 0)
    const txRefSum = txs.filter(t => t.type === 'referral_reward').reduce((s, t) => s + Number(t.amount || 0), 0)
    const txOtherSum = txs.filter(t => t.type !== 'daily_qkey' && t.type !== 'referral_reward').reduce((s, t) => s + Number(t.amount || 0), 0)
    const txAllSum = txs.reduce((s, t) => s + Number(t.amount || 0), 0)

    // 200% Cap
    const stakeTotal = stakings
      .filter(s => ['active','completed','capped'].includes(String(s.status)))
      .reduce((s, x) => s + Number(x.amount || 0), 0)
    const target = stakeTotal * 2 * USD_TO_QKEY
    const paidTotal = txDailySum + txRefSum
    const remaining = Math.max(0, target - paidTotal)
    const progressPct = target > 0 ? Math.min(100, (paidTotal / target) * 100) : 0

    return c.json({
      success: true,
      user: {
        id: user.id, email: user.email, name: user.name,
        qkey_balance: user.qkey_balance,
        referrer_id: user.referrer_id,
        referral_code: user.referral_code,
      },
      stakings,
      summary: {
        staking_total_usdt: stakeTotal,
        target_qkey_200pct: target,
        paid_total_qkey: paidTotal,
        remaining_qkey: remaining,
        progress_percent: Number(progressPct.toFixed(2)),
        daily_rewards_count: dailyRewards.length,
        daily_rewards_sum_qkey: dailySum,
        referral_rewards_count: referralRewards.length,
        referral_rewards_sum_qkey: refSum,
        tx_daily_sum_qkey: txDailySum,
        tx_referral_sum_qkey: txRefSum,
        tx_other_sum_qkey: txOtherSum,
        tx_all_sum_qkey: txAllSum,
      },
      daily_rewards: dailyRewards,
      referral_rewards: referralRewards,
      transactions: txs,
    })
  } catch (error) {
    console.error('user-statement diag error:', error)
    return c.json({ error: String(error) }, 500)
  }
})


// ★★★★★ 5/8 reward_date AND paid_date=2026-05-11 중복 47건 정밀 삭제 — 옵션 A (2026-05-12) ★★★★★
//   배경: 5/11 cron 실행 시 5/8 적립분이 재INSERT 되어 (staking_id, reward_date)='5/8' 동일 행이
//         paid_date=2026-05-08 + paid_date=2026-05-11 두 번 들어감 (47 staking 영향)
//   삭제 대상:
//     1. daily_rewards WHERE reward_date='2026-05-08' AND paid_date='2026-05-11'  (47건)
//     2. transactions (ref_id IN 위 dr_ids, type='daily_qkey')
//     3. referral_rewards WHERE reward_date='2026-05-08' AND paid_date='2026-05-11'  (매칭 보너스 중복분, 있을 경우)
//     4. transactions (ref_id IN 위 rr_ids, type='referral_reward')
//     5. qkey_balance MAX(0, balance - amt) 환원
//   보존 (절대 보존):
//     - daily_rewards WHERE reward_date='2026-05-08' AND paid_date='2026-05-08' (47건 — 5/8 당일 정산 정상분)
//     - referral_rewards WHERE reward_date='2026-05-08' AND paid_date='2026-05-08' (정상분)
//   gate: key=ADMIN_PW + dryRun 기본 / confirm=GO 시 실행
app.post('/api/diag/exec-delete-may8-dup-paid-may11', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const confirm = c.req.query('confirm') || ''
    const dryRun = confirm !== 'GO'
    const db = c.env.DB
    const REWARD_DATE = '2026-05-08'
    const PAID_DATE_DUP = '2026-05-11'

    // STEP A: 삭제 대상 daily_rewards 식별
    const drRows = await db.prepare(`
      SELECT id, user_id, staking_id, usdt_amount, reward_date, paid_date
      FROM daily_rewards
      WHERE reward_date = ? AND paid_date = ?
      ORDER BY id
    `).bind(REWARD_DATE, PAID_DATE_DUP).all()
    const drList = (drRows.results || []) as any[]
    const drIds = drList.map(r => Number(r.id))

    // STEP B: 매칭 referral_rewards 식별 (reward_date=5/8 + paid_date=5/11)
    const rrRows = await db.prepare(`
      SELECT id, referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date
      FROM referral_rewards
      WHERE reward_date = ? AND paid_date = ?
      ORDER BY id
    `).bind(REWARD_DATE, PAID_DATE_DUP).all()
    const rrList = (rrRows.results || []) as any[]
    const rrIds = rrList.map(r => Number(r.id))

    // STEP C: 매칭 transactions 식별 (ref_id IN drIds OR rrIds)
    const dqTxRows = drIds.length > 0
      ? await db.prepare(`
          SELECT id, user_id, amount, ref_id FROM transactions
          WHERE type = 'daily_qkey' AND ref_id IN (${drIds.map(()=>'?').join(',')})
        `).bind(...drIds).all()
      : { results: [] as any[] }
    const dqTxList = ((dqTxRows as any).results || []) as any[]

    const rrTxRows = rrIds.length > 0
      ? await db.prepare(`
          SELECT id, user_id, amount, ref_id FROM transactions
          WHERE type = 'referral_reward' AND ref_id IN (${rrIds.map(()=>'?').join(',')})
        `).bind(...rrIds).all()
      : { results: [] as any[] }
    const rrTxList = ((rrTxRows as any).results || []) as any[]

    // 모든 tx id 집합 (중복 제거)
    const allTxIdsSet = new Set<number>()
    for (const t of dqTxList) allTxIdsSet.add(Number(t.id))
    for (const t of rrTxList) allTxIdsSet.add(Number(t.id))
    const allTxIds = Array.from(allTxIdsSet)

    // STEP D: 사용자별 환원 금액 집계
    const refundByUser = new Map<number, number>()
    const txDetailRows = allTxIds.length > 0
      ? await db.prepare(`
          SELECT id, user_id, amount FROM transactions
          WHERE id IN (${allTxIds.map(()=>'?').join(',')})
        `).bind(...allTxIds).all()
      : { results: [] as any[] }
    for (const t of ((txDetailRows as any).results || [])) {
      const uid = Number(t.user_id)
      refundByUser.set(uid, (refundByUser.get(uid) || 0) + Number(t.amount || 0))
    }

    const drSum = drList.reduce((s, r) => s + Number(r.usdt_amount || 0), 0)
    const rrSum = rrList.reduce((s, r) => s + Number(r.reward_amount || 0), 0)

    if (dryRun) {
      return c.json({
        success: true,
        mode: 'dry_run',
        note: 'DB 무변경. confirm=GO 추가 시 삭제 + 잔액 환원. 5/8 paid_date=5/8 정상분은 절대 보존',
        target: { reward_date: REWARD_DATE, paid_date_dup: PAID_DATE_DUP },
        preserved: {
          message: 'reward_date=2026-05-08 AND paid_date=2026-05-08 (5/8 당일 정상분) 보존',
        },
        delete_plan: {
          daily_rewards_count: drList.length,
          daily_rewards_sum_qkey: drSum,
          daily_rewards_ids: drIds,
          referral_rewards_count: rrList.length,
          referral_rewards_sum_qkey: rrSum,
          referral_rewards_ids: rrIds,
          dq_tx_count: dqTxList.length,
          rr_tx_count: rrTxList.length,
          total_tx_count: allTxIds.length,
          total_tx_ids: allTxIds,
          refund_by_user: Object.fromEntries(refundByUser),
          total_refund_qkey: Array.from(refundByUser.values()).reduce((s,v)=>s+v,0),
        }
      })
    }

    // STEP E: 실제 삭제 (confirm=GO)
    let deletedTxCount = 0, deletedDrCount = 0, deletedRrCount = 0
    let balanceUpdatedCount = 0

    // 1. transactions 삭제 (chunks of 50)
    for (let i = 0; i < allTxIds.length; i += 50) {
      const chunk = allTxIds.slice(i, i + 50)
      const res = await db.prepare(`
        DELETE FROM transactions WHERE id IN (${chunk.map(()=>'?').join(',')})
      `).bind(...chunk).run()
      deletedTxCount += Number((res as any)?.meta?.changes || 0)
    }

    // 2. daily_rewards 삭제 (reward_date=5/8 AND paid_date=5/11 만)
    for (let i = 0; i < drIds.length; i += 50) {
      const chunk = drIds.slice(i, i + 50)
      const res = await db.prepare(`
        DELETE FROM daily_rewards WHERE id IN (${chunk.map(()=>'?').join(',')})
      `).bind(...chunk).run()
      deletedDrCount += Number((res as any)?.meta?.changes || 0)
    }

    // 3. referral_rewards 삭제 (reward_date=5/8 AND paid_date=5/11 만)
    for (let i = 0; i < rrIds.length; i += 50) {
      const chunk = rrIds.slice(i, i + 50)
      const res = await db.prepare(`
        DELETE FROM referral_rewards WHERE id IN (${chunk.map(()=>'?').join(',')})
      `).bind(...chunk).run()
      deletedRrCount += Number((res as any)?.meta?.changes || 0)
    }

    // 4. 사용자별 잔액 차감 환원
    for (const [uid, amt] of refundByUser.entries()) {
      const res = await db.prepare(`
        UPDATE users SET qkey_balance = MAX(0, qkey_balance - ?) WHERE id = ?
      `).bind(amt, uid).run()
      balanceUpdatedCount += Number((res as any)?.meta?.changes || 0)
    }

    return c.json({
      success: true,
      mode: 'exec',
      target: { reward_date: REWARD_DATE, paid_date_dup: PAID_DATE_DUP },
      preserved: 'reward_date=2026-05-08 AND paid_date=2026-05-08 (5/8 당일 정상분) 보존됨',
      result: {
        deleted_transactions: deletedTxCount,
        deleted_daily_rewards: deletedDrCount,
        deleted_referral_rewards: deletedRrCount,
        users_balance_refunded: balanceUpdatedCount,
        total_refund_qkey: Array.from(refundByUser.values()).reduce((s,v)=>s+v,0),
        refund_by_user: Object.fromEntries(refundByUser),
      },
      note: '5/8 reward_date 의 paid_date=2026-05-11 중복 INSERT 분 삭제 완료. 5/8 당일 정상분 47건 / 5/11 reward_date 142건 보존.'
    })
  } catch (error) {
    console.error('exec-delete-may8-dup-paid-may11 error:', error)
    return c.json({ error: String(error) }, 500)
  }
})


// ★★★★★ 5/11 Phase 4 매칭 보너스 안전 재실행 (L1 20% / L2 10%) — 사장님 영구 룰 준수 (2026-05-12) ★★★★★
//   사장님 영구 룰 #3 ★★★ 0순위 — bottom-up traversal:
//     "무조건 당일 데일리 배당을 실시할 경우에는 배당에 해당하는 맨 아래 데일리 정산된
//      하부부터 데일리 정산을 하면서 위로 올라갈것"
//   - depth desc 정렬로 leaf → root 순회 (자식 own_daily 확정 후 부모 매칭 산출)
//   - L1 = 자식 own_daily × 0.20 (사장님 정책)
//   - L2 = 자식 own_daily × 0.10 (사장님 정책)
//
//   중복 차단 강화 (이전 75건/15그룹 중복 사고 대응):
//   1. Pre-compute 방식: 메모리에서 전체 plan 산출 후 한 번에 INSERT
//   2. 매 INSERT 직전 DB 재확인 (double-check lock) — race condition 차단
//   3. dedupe key: (referrer_id, referee_id, level, reward_date) — 1회만 허용
//   4. txExists guard: ref_id 매칭 + (user_id, type, amount, KST date) 매칭 모두 검증
//   5. dry_run 필수 — preview 안 보고 confirm=GO 금지
//
//   경로: POST /api/diag/exec-may11-phase4-safe
//     ?key=ADMIN_PW [&confirm=GO]
//   - reward_date = '2026-05-11' (고정)
//   - paid_date = '2026-05-12' (고정)
//   - 200% Cap, EXISTS guard, depth desc 정렬 적용
app.post('/api/diag/exec-may11-phase4-safe', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const dep = assertNotDeprecated(c, 'exec-may11-phase4-safe', '5/11 Phase4 보정 완료 (2026-05-11). safeInsertTransaction 가드 미적용 → 재호출 시 이중지급 위험')
    if (dep) return dep
    const confirm = c.req.query('confirm') || ''
    const dryRun = confirm !== 'GO'
    const db = c.env.DB
    const USD_TO_QKEY = 150
    const REWARD_DATE = '2026-05-11'
    const PAID_DATE = '2026-05-12'

    // === STEP 1: daily_rewards (reward_date=2026-05-11) 조회 — 매칭 산출 입력 ===
    const drRows = await db.prepare(`
      SELECT id AS dr_id, user_id, staking_id, usdt_amount AS qkey_amount
      FROM daily_rewards
      WHERE reward_date = ?
      ORDER BY user_id, staking_id
    `).bind(REWARD_DATE).all()
    const drList = ((drRows.results || []) as any[]).map(r => ({
      dr_id: Number(r.dr_id),
      user_id: Number(r.user_id),
      staking_id: Number(r.staking_id),
      qkey_amount: Number(r.qkey_amount),
    }))

    // === STEP 2: 회원별 stake_total / paid_total / referrer 트리 ===
    const stakeTotalsRaw = await db.prepare(`
      SELECT user_id, COALESCE(SUM(amount),0) AS total
      FROM staking WHERE status IN ('active','completed','capped')
      GROUP BY user_id
    `).all()
    const stakeTotalByUser = new Map<number, number>()
    for (const r of (stakeTotalsRaw.results || []) as any[]) {
      stakeTotalByUser.set(Number(r.user_id), Number(r.total) || 0)
    }
    const paidTotalsRaw = await db.prepare(`
      SELECT user_id, COALESCE(SUM(amount),0) AS total
      FROM transactions
      WHERE coin_type='QKEY' AND type IN ('daily_qkey','referral_reward')
      GROUP BY user_id
    `).all()
    const paidTotalByUser = new Map<number, number>()
    for (const r of (paidTotalsRaw.results || []) as any[]) {
      paidTotalByUser.set(Number(r.user_id), Number(r.total) || 0)
    }
    const targetOf = (uid: number) => (stakeTotalByUser.get(uid) || 0) * 2 * USD_TO_QKEY
    const paidOf = (uid: number) => paidTotalByUser.get(uid) || 0
    const isCapped = (uid: number) => { const t = targetOf(uid); return t > 0 && paidOf(uid) >= t }
    const remainingOf = (uid: number) => Math.max(0, targetOf(uid) - paidOf(uid))
    const addPaid = (uid: number, amt: number) => paidTotalByUser.set(uid, (paidTotalByUser.get(uid) || 0) + amt)

    const usersRaw = await db.prepare(`SELECT id, referrer_id FROM users`).all()
    const referrerOf = new Map<number, number | null>()
    for (const u of (usersRaw.results || []) as any[]) {
      referrerOf.set(Number(u.id), u.referrer_id != null ? Number(u.referrer_id) : null)
    }
    const depthMemo = new Map<number, number>()
    function computeDepth(uid: number, stack: Set<number>): number {
      if (depthMemo.has(uid)) return depthMemo.get(uid)!
      if (stack.has(uid)) { depthMemo.set(uid, 0); return 0 }
      stack.add(uid)
      const rid = referrerOf.get(uid)
      if (rid == null) { depthMemo.set(uid, 0); stack.delete(uid); return 0 }
      const d = 1 + computeDepth(rid, stack)
      depthMemo.set(uid, d); stack.delete(uid); return d
    }
    for (const r of drList) computeDepth(r.user_id, new Set())

    // === STEP 3: bottom-up 정렬 (depth desc — leaf → root) ===
    //   사장님 영구 룰 #3 준수: 자식 own_daily 확정 후 부모 매칭 산출
    drList.sort((a, b) => {
      const da = depthMemo.get(a.user_id) || 0
      const db_ = depthMemo.get(b.user_id) || 0
      if (db_ !== da) return db_ - da
      if (a.user_id !== b.user_id) return a.user_id - b.user_id
      return a.staking_id - b.staking_id
    })

    // === STEP 4: 기존 referral_rewards (reward_date=2026-05-11) 조회 — dedupe key ===
    const existingRR = await db.prepare(`
      SELECT referrer_id, referee_id, level FROM referral_rewards WHERE reward_date = ?
    `).bind(REWARD_DATE).all()
    const existingKey = new Set<string>()
    for (const r of (existingRR.results || []) as any[]) {
      existingKey.add(`${r.referrer_id}_${r.referee_id}_${r.level}`)
    }

    // === STEP 5: parent active staking + depth 계산 — 매칭 plan pre-compute ===
    type PlanItem = {
      referrer_id: number, referee_id: number, level: 1 | 2,
      original_amount: number, reward_amount: number,
      reason: string
    }
    const plan: PlanItem[] = []
    const skipped: { referee_id: number, level: number, reason: string }[] = []

    // user별 own_daily 합 (자식이 여러 staking 있으면 합산해서 한 번만 매칭)
    const ownDailyByUser = new Map<number, number>()
    for (const r of drList) {
      ownDailyByUser.set(r.user_id, (ownDailyByUser.get(r.user_id) || 0) + r.qkey_amount)
    }

    // bottom-up: depth desc 정렬된 자식 user 순회
    const processedReferees = new Set<number>()
    for (const r of drList) {
      if (processedReferees.has(r.user_id)) continue
      processedReferees.add(r.user_id)
      const childUid = r.user_id
      const childOwn = ownDailyByUser.get(childUid) || 0
      if (childOwn <= 0) continue

      const parentId = referrerOf.get(childUid)
      if (parentId == null) {
        skipped.push({ referee_id: childUid, level: 1, reason: 'no parent' })
        continue
      }

      // L1 매칭 (parent 의 active staking + cap + dedupe check)
      const l1Key = `${parentId}_${childUid}_1`
      if (existingKey.has(l1Key)) {
        skipped.push({ referee_id: childUid, level: 1, reason: 'already exists' })
      } else {
        const parentActive = await db.prepare(`
          SELECT id FROM staking WHERE user_id=? AND status='active'
            AND date(start_date,'+9 hours')<=date(?) AND date(end_date,'+9 hours')>=date(?)
          LIMIT 1
        `).bind(parentId, REWARD_DATE, REWARD_DATE).first()
        if (!parentActive) {
          skipped.push({ referee_id: childUid, level: 1, reason: `parent ${parentId} no active staking` })
        } else if (isCapped(parentId)) {
          skipped.push({ referee_id: childUid, level: 1, reason: `parent ${parentId} capped` })
        } else {
          let l1 = Math.round(childOwn * 0.20)
          const rem = remainingOf(parentId)
          if (l1 > rem) l1 = Math.max(0, Math.floor(rem))
          if (l1 > 0) {
            plan.push({
              referrer_id: parentId, referee_id: childUid, level: 1,
              original_amount: childOwn, reward_amount: l1,
              reason: 'L1 20% match'
            })
            existingKey.add(l1Key)  // 같은 호출 내 중복 차단
            addPaid(parentId, l1)
          }
        }
      }

      // L2 매칭 (grandparent)
      const grandId = referrerOf.get(parentId)
      if (grandId == null) {
        skipped.push({ referee_id: childUid, level: 2, reason: 'no grandparent' })
        continue
      }
      const l2Key = `${grandId}_${childUid}_2`
      if (existingKey.has(l2Key)) {
        skipped.push({ referee_id: childUid, level: 2, reason: 'already exists' })
      } else {
        const grandActive = await db.prepare(`
          SELECT id FROM staking WHERE user_id=? AND status='active'
            AND date(start_date,'+9 hours')<=date(?) AND date(end_date,'+9 hours')>=date(?)
          LIMIT 1
        `).bind(grandId, REWARD_DATE, REWARD_DATE).first()
        if (!grandActive) {
          skipped.push({ referee_id: childUid, level: 2, reason: `grandparent ${grandId} no active staking` })
        } else if (isCapped(grandId)) {
          skipped.push({ referee_id: childUid, level: 2, reason: `grandparent ${grandId} capped` })
        } else {
          let l2 = Math.round(childOwn * 0.10)
          const rem = remainingOf(grandId)
          if (l2 > rem) l2 = Math.max(0, Math.floor(rem))
          if (l2 > 0) {
            plan.push({
              referrer_id: grandId, referee_id: childUid, level: 2,
              original_amount: childOwn, reward_amount: l2,
              reason: 'L2 10% match'
            })
            existingKey.add(l2Key)
            addPaid(grandId, l2)
          }
        }
      }
    }

    // === STEP 6: plan 요약 ===
    const l1Plan = plan.filter(p => p.level === 1)
    const l2Plan = plan.filter(p => p.level === 2)
    const l1Sum = l1Plan.reduce((s, p) => s + p.reward_amount, 0)
    const l2Sum = l2Plan.reduce((s, p) => s + p.reward_amount, 0)

    // user별 환산 (받을 사람 = referrer)
    const recvByUser = new Map<number, number>()
    for (const p of plan) {
      recvByUser.set(p.referrer_id, (recvByUser.get(p.referrer_id) || 0) + p.reward_amount)
    }

    if (dryRun) {
      return c.json({
        success: true,
        mode: 'dry_run',
        note: 'DB 무변경. confirm=GO 추가 시 INSERT 진행',
        target: { reward_date: REWARD_DATE, paid_date: PAID_DATE },
        input: {
          daily_rewards_count: drList.length,
          unique_referee_users: ownDailyByUser.size,
        },
        plan_summary: {
          l1_count: l1Plan.length, l1_total_qkey: l1Sum,
          l2_count: l2Plan.length, l2_total_qkey: l2Sum,
          grand_total_qkey: l1Sum + l2Sum,
        },
        receive_by_user: Object.fromEntries(recvByUser),
        skipped_count: skipped.length,
        skipped_sample: skipped.slice(0, 30),
        plan_sample: plan.slice(0, 20),
      })
    }

    // === STEP 7: 실제 INSERT (confirm=GO) — double-check lock 적용 ===
    let l1Count = 0, l1Total = 0, l2Count = 0, l2Total = 0
    let txInserted = 0, balanceUpdated = 0
    const insertErrors: any[] = []

    for (const p of plan) {
      try {
        // Double-check: INSERT 직전 DB 재확인 (race condition 차단)
        const exists = await db.prepare(`
          SELECT id FROM referral_rewards
          WHERE referrer_id=? AND referee_id=? AND level=? AND reward_date=?
          LIMIT 1
        `).bind(p.referrer_id, p.referee_id, p.level, REWARD_DATE).first()
        if (exists) {
          insertErrors.push({ ...p, error: 'double-check: already exists' })
          continue
        }

        // INSERT referral_rewards
        const rrIns = await db.prepare(`
          INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date)
          VALUES (?, ?, ?, ?, ?, ?, ?)
        `).bind(p.referrer_id, p.referee_id, p.level, p.original_amount, p.reward_amount, REWARD_DATE, PAID_DATE).run()
        const rrId = (rrIns as any)?.meta?.last_row_id ?? null

        // INSERT transactions (ref_id 매칭 guard)
        const txEx = await db.prepare(`
          SELECT id FROM transactions WHERE type='referral_reward' AND ref_id=? LIMIT 1
        `).bind(rrId).first()
        if (!txEx) {
          await db.prepare(`
            INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
            VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?)
          `).bind(p.referrer_id, p.reward_amount, p.level === 1 ? '추천 보너스 (Level 1)' : '추천 보너스 (Level 2)', rrId).run()
          txInserted++
        }

        // UPDATE qkey_balance
        await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(p.reward_amount, p.referrer_id).run()
        balanceUpdated++

        if (p.level === 1) { l1Count++; l1Total += p.reward_amount }
        else { l2Count++; l2Total += p.reward_amount }
      } catch (err) {
        insertErrors.push({ ...p, error: String(err) })
      }
    }

    return c.json({
      success: true,
      mode: 'exec',
      target: { reward_date: REWARD_DATE, paid_date: PAID_DATE },
      result: {
        l1_count: l1Count, l1_total_qkey: l1Total,
        l2_count: l2Count, l2_total_qkey: l2Total,
        grand_total_qkey: l1Total + l2Total,
        tx_inserted: txInserted,
        balance_updated_count: balanceUpdated,
      },
      receive_by_user: Object.fromEntries(recvByUser),
      skipped_count: skipped.length,
      insert_errors_count: insertErrors.length,
      insert_errors_sample: insertErrors.slice(0, 5),
      note: '사장님 영구 룰 #3 bottom-up traversal 준수 (depth desc, L1=20%, L2=10%). EXISTS guard 3중 (pre-compute + memory set + double-check lock)'
    })
  } catch (error) {
    console.error('exec-may11-phase4-safe error:', error)
    return c.json({ error: String(error) }, 500)
  }
})


// ★ 200% Cap 진행률 조회 API (사용자/UI용) ★
//   사용자가 받은 모든 QKEY 수당 총합(daily_qkey + referral_reward + direct_referral)을
//   사용자 진입금액 합계 × 2 × 150 (target) 과 비교한 진행률 반환.
//   단계 (사장님 정책 2026-05-10 수정):
//     <100% green / 100~150% orange / 150~200% red / >=200% capped
//   ★ 영구룰 #cap200정책 (2026-05-21) — 분자 4종:
//     daily_qkey + referral_reward(L1+L2) + direct_referral(L0)
//     → 기존 SQL 은 direct_referral(L0) 가 누락되어 솔밧 등 직판 큰 회원의 % 가
//        과소표시(예: 솔밧 17.25% 실제 94.50%) 되던 표시 버그 수정. DB/잔액 영향 0.
app.get('/api/staking/progress/:userId', async (c) => {
  try {
    const db = c.env.DB
    const userId = Number(c.req.param('userId'))
    if (!Number.isFinite(userId) || userId <= 0) {
      return c.json({ error: 'invalid userId' }, 400)
    }
    const USD_TO_QKEY = 150

    const stakeRow = await db.prepare(`
      SELECT COALESCE(SUM(amount), 0) as total
      FROM staking WHERE user_id = ? AND status IN ('active','completed','capped')
    `).bind(userId).first() as any
    const stakeTotal = Number(stakeRow?.total || 0)

    // ★ 영구룰 #cap200정책 3️⃣ — 분자 4종 (daily_qkey + L1 + L2 + L0 direct_referral)
    const paidRow = await db.prepare(`
      SELECT COALESCE(SUM(amount), 0) as total
      FROM transactions
      WHERE user_id = ? AND coin_type = 'QKEY'
        AND type IN ('daily_qkey', 'referral_reward', 'direct_referral')
    `).bind(userId).first() as any
    const paidTotal = Number(paidRow?.total || 0)

    // ★ 영구룰 #cap200정책 1️⃣ (2026-07-23 사장님 승인 정정)
    //   산정기준(100%) = amount × 150 (= 투자금), cap_target(200%=CAPPED) = amount × 300 (= 투자금 2배)
    //   cap_pct = paid_total ÷ 산정기준(amount×150) × 100  ← 분모는 반드시 baseline(150), 2배지점(300) 아님
    //   (이전 버그: 분모를 amount×300 으로 나눠 269% 가 134.53% 로 절반 낮게 표시됨 → 200% 초과인데 차단 안내 안 뜸)
    const baseline = stakeTotal * USD_TO_QKEY          // 100% 산정기준 (= 투자금)
    const target = stakeTotal * 2 * USD_TO_QKEY        // 200% cap_target (= 투자금 2배, 출금/잔여 한도)
    const percent = baseline > 0 ? (paidTotal / baseline * 100) : 0

    // 단계 판정 (사장님 정책 2026-05-10 수정 — 100/150/200 임계값)
    let stage: 'green' | 'orange' | 'red' | 'capped' = 'green'
    if (percent >= 200) stage = 'capped'
    else if (percent >= 150) stage = 'red'
    else if (percent >= 100) stage = 'orange'

    // staking 별 status 반환 (capped 표시용)
    const stakings = await db.prepare(`
      SELECT id, amount, daily_rate, start_date, end_date, status
      FROM staking WHERE user_id = ? AND status IN ('active','completed','capped')
      ORDER BY id ASC
    `).bind(userId).all()

    return c.json({
      success: true,
      user_id: userId,
      stake_total_usd: stakeTotal,
      baseline_qkey: baseline,
      target_qkey: target,
      paid_total_qkey: paidTotal,
      percent: Math.round(percent * 100) / 100,
      stage,
      capped: stage === 'capped',
      remaining_qkey: Math.max(0, target - paidTotal),
      stakings: stakings.results
    })
  } catch (error) {
    console.error('staking progress error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★ 영구룰 #cap200정책 8️⃣ — staking별 cap audit (per-staking 분리 검증) ★★★
//   영구룰 2️⃣ Staking별 완전 독립 적용: paid_total을 FIFO(진입날짜 ASC)로 staking에 분배
//   영구룰 3️⃣ 분자 4종: daily_qkey + referral_reward(L1+L2) + direct_referral
//   사용 예: GET /api/admin/diag/cap200-per-staking?user_id=42
//          GET /api/admin/diag/cap200-per-staking          (전체 사용자)
app.get('/api/admin/diag/cap200-per-staking', async (c) => {
  try {
    const db = c.env.DB
    const USD_TO_QKEY = 150
    const userIdParam = c.req.query('user_id') || ''
    const onlyUser = userIdParam ? parseInt(userIdParam) : null

    // 1. 대상 사용자 목록 (스테이크 있는 사람)
    const usersSql = onlyUser
      ? `SELECT id, email FROM users WHERE id = ?`
      : `SELECT DISTINCT u.id, u.email FROM users u
         INNER JOIN staking s ON s.user_id = u.id
         WHERE s.status IN ('active','completed','capped')
         ORDER BY u.id ASC`
    const usersRes = onlyUser
      ? await db.prepare(usersSql).bind(onlyUser).all()
      : await db.prepare(usersSql).all()

    const results: any[] = []

    for (const u of usersRes.results as any[]) {
      const uid = u.id
      // 2. 사용자 staking 목록 (진입일 ASC = FIFO)
      const stakingsRes = await db.prepare(`
        SELECT id, amount, start_date, end_date, status, daily_rate
        FROM staking
        WHERE user_id = ? AND status IN ('active','completed','capped')
        ORDER BY date(start_date, '+9 hours') ASC, id ASC
      `).bind(uid).all()
      const stakings = stakingsRes.results as any[]
      if (stakings.length === 0) continue

      // 3. paid_total 분자 4종 (cap 계산에 들어가는 4종) 전체 합계
      const paidRow = await db.prepare(`
        SELECT COALESCE(SUM(amount), 0) as total
        FROM transactions
        WHERE user_id = ? AND coin_type = 'QKEY'
          AND type IN ('daily_qkey','referral_reward','direct_referral')
      `).bind(uid).first() as any
      let paidPool = Number(paidRow?.total || 0)

      // 4. FIFO 분배 — 각 staking에 cap_target(=amount×300)까지 채우고 남으면 다음 staking으로
      const perStaking: any[] = []
      for (const s of stakings) {
        const amount = Number(s.amount)
        const capTarget = amount * 2 * USD_TO_QKEY  // 200% target = amount × 300
        const baseline = amount * USD_TO_QKEY        // 100% baseline = amount × 150
        // 이 staking이 받을 수 있는 최대
        const fill = Math.min(paidPool, capTarget)
        paidPool -= fill
        const pct = capTarget > 0 ? (fill / baseline * 100) : 0  // 100% scale로 표시 (영구룰 1)
        const status_cap = fill >= capTarget ? 'CAPPED' : (fill >= baseline ? '100%+' : 'active')
        perStaking.push({
          staking_id: s.id,
          amount_usd: amount,
          start_date_kst: String(s.start_date).slice(0,10),
          end_date_kst: String(s.end_date).slice(0,10),
          status_db: s.status,
          baseline_qkey: baseline,           // 100% = amount × 150
          cap_target_qkey: capTarget,        // 200% = amount × 300
          paid_qkey_assigned: fill,          // FIFO 분배된 paid
          remaining_to_cap_qkey: Math.max(0, capTarget - fill),
          cap_pct_100scale: Math.round(pct * 100) / 100,    // 100% scale
          cap_pct_200scale: Math.round(fill / capTarget * 100 * 100) / 100,
          cap_status: status_cap,
          can_receive_payment: fill < capTarget  // 내일 cron이 이 staking에 지급할 수 있는지
        })
      }

      const totalPaid = Number(paidRow?.total || 0)
      const totalCapTarget = stakings.reduce((sum, s) => sum + Number(s.amount) * 2 * USD_TO_QKEY, 0)
      const leftoverPool = paidPool  // 모든 staking을 채우고도 남은 paid (영구룰 위반 신호)

      results.push({
        user_id: uid,
        email: u.email,
        stakings_count: stakings.length,
        total_paid_qkey: totalPaid,
        total_cap_target_qkey: totalCapTarget,
        leftover_after_fifo: leftoverPool,    // > 0 이면 모든 staking cap 도달 + 초과지급 의심
        warning: leftoverPool > 0 ? '⚠️ 모든 staking CAPPED 이후 추가 지급 감지' : null,
        any_capped: perStaking.some(s => s.cap_status === 'CAPPED'),
        any_under_100: perStaking.some(s => s.cap_pct_100scale < 100),
        stakings: perStaking
      })
    }

    return c.json({
      success: true,
      rule_refs: ['#cap200정책 2️⃣ (staking별 독립)', '#cap200정책 3️⃣ (분자 4종)', '#cap200정책 4️⃣ Case A/B/C'],
      fifo_method: 'paid_total을 진입일 ASC 순으로 각 staking의 cap_target(=amount×300)까지 채움',
      total_users: results.length,
      results
    })
  } catch (error) {
    console.error('cap200-per-staking error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★ 어드민 200% Cap 진단 — 53명 전체 진행률 일람 ★
app.get('/api/admin/diag/staking-progress', async (c) => {
  try {
    const db = c.env.DB
    const USD_TO_QKEY = 150

    // ★ 영구룰 #cap200정책 3️⃣ — 분자 4종 (daily_qkey + L1 + L2 + L0 direct_referral)
    const rows = await db.prepare(`
      SELECT
        u.id as user_id,
        u.email,
        COALESCE(SUM(CASE WHEN s.status IN ('active','completed','capped') THEN s.amount ELSE 0 END), 0) as stake_total,
        (SELECT COALESCE(SUM(amount), 0) FROM transactions
          WHERE user_id = u.id AND coin_type = 'QKEY'
            AND type IN ('daily_qkey','referral_reward','direct_referral')) as paid_total
      FROM users u
      LEFT JOIN staking s ON s.user_id = u.id
      GROUP BY u.id
      ORDER BY u.id ASC
    `).all()

    const list: any[] = []
    let cappedCount = 0
    let warnCount = 0
    let orangeCount = 0
    for (const r of rows.results as any[]) {
      const stake = Number(r.stake_total || 0)
      if (stake <= 0) continue
      const paid = Number(r.paid_total || 0)
      const target = stake * 2 * USD_TO_QKEY
      const percent = target > 0 ? (paid / target * 100) : 0
      // 단계 판정 (사장님 정책 2026-05-10 수정 — 100/150/200 임계값)
      let stage: 'green' | 'orange' | 'red' | 'capped' = 'green'
      if (percent >= 200) { stage = 'capped'; cappedCount++ }
      else if (percent >= 150) { stage = 'red'; warnCount++ }
      else if (percent >= 100) { stage = 'orange'; orangeCount++ }
      list.push({
        user_id: r.user_id,
        email: r.email,
        stake_total_usd: stake,
        paid_total_qkey: paid,
        target_qkey: target,
        percent: Math.round(percent * 100) / 100,
        stage,
        remaining_qkey: Math.max(0, target - paid)
      })
    }

    return c.json({
      success: true,
      total_active_users: list.length,
      capped_count: cappedCount,
      warn_count: warnCount,
      orange_count: orangeCount,
      list
    })
  } catch (error) {
    console.error('admin staking-progress error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★ 5/12 일일 배당 사전 예정액 dry-run (2026-05-11 사장님 옵션 A 결재) ★★★
//   /api/rewards/daily 와 100% 동일한 산식으로 계산하되 INSERT/UPDATE 절대 안 함 (읽기 전용)
//   기준일: ?targetDate=YYYY-MM-DD 쿼리로 지정 (없으면 자동 = 오늘 KST)
//   응답: 사용자별 예정 daily/L1/L2/총액 + 전체 합계 + 200% Cap 사전 스킵자 명단
//   사용 예: GET /api/admin/daily-preview?targetDate=2026-05-12
//     → 5/12 cron 이 실행될 때의 예정 지급액 사전 보고
app.get('/api/admin/daily-preview', async (c) => {
  try {
    const db = c.env.DB
    const USD_TO_QKEY = 150

    // targetDate = cron 실행일 (= paid_date / today), 미지정 시 오늘 KST
    const now = new Date()
    const todayAuto = kstDateStr(now)
    const targetDate = c.req.query('targetDate') || todayAuto
    if (!/^\d{4}-\d{2}-\d{2}$/.test(targetDate)) {
      return c.json({ error: 'targetDate=YYYY-MM-DD 필요' }, 400)
    }
    // yesterdayKst = targetDate - 1일 (실제 cron 의 reward_date 기준일)
    const tdObj = new Date(targetDate + 'T00:00:00Z')
    const yesterdayKst = new Date(tdObj.getTime() - 24 * 60 * 60 * 1000).toISOString().split('T')[0]

    // targetDate(= cron 실행일) 이 평일인지 체크
    const todayDateObjKst = new Date(targetDate + 'T00:00:00+09:00')
    const { isBusinessDay: targetIsBiz, reason: targetReason } = isKoreanBusinessDay(todayDateObjKst)
    if (!targetIsBiz) {
      return c.json({
        success: true,
        preview: true,
        targetDate,
        yesterdayKst,
        message: `${targetDate} 는 휴일(${targetReason}) — cron skip 예정 (지급 0건)`,
        cron_will_run: false,
        plan_total_users: 0,
        plan_total_qkey: 0,
        plan_daily_qkey: 0,
        plan_l1_qkey: 0,
        plan_l2_qkey: 0,
        cap_skip_users: [],
        users: []
      })
    }

    // 활성 staking 조회 (실제 cron 과 동일 쿼리)
    const activeStakings = await db.prepare(`
      SELECT
        s.user_id,
        s.id as staking_id,
        s.amount,
        s.period_days,
        s.period_months,
        s.daily_rate,
        s.start_date,
        s.end_date,
        date(s.start_date, '+9 hours') as start_date_kst,
        (SELECT COUNT(*) FROM daily_rewards WHERE staking_id = s.id) as rewarded_count,
        (SELECT MAX(reward_date) FROM daily_rewards WHERE staking_id = s.id) as last_reward_date
      FROM staking s
      WHERE s.status = 'active'
        AND date(s.end_date, '+9 hours') >= date(?)
        AND date(s.start_date, '+9 hours') <= date(?)
      ORDER BY s.user_id ASC, s.id ASC
    `).bind(yesterdayKst, yesterdayKst).all()

    // ★★★ 영구룰 #cap200정책 (2026-05-21) 적용된 dry-run ★★★
    //   ① 분자 4종 = daily_qkey + referral_reward + direct_referral
    //   ② Staking별 완전 독립 (FIFO 진입일 ASC)
    //   ⑥ L1/L2 매칭은 receiver의 staking_id 단위로 cap 체크
    type SimStaking = {
      id: number, amount: number, capTarget: number, fill: number,
      capped: boolean, start_date_kst: string, status_db: string
    }
    type PreviewUserState = {
      user_id: number,
      email: string | null,
      stake_total: number,
      paid_total_real: number,   // DB 현재 누적 (분자 4종)
      target: number,            // = stake_total × 300 (전체 합산용 표시)
      stakings: SimStaking[],    // FIFO 분배 적용된 in-memory state
      daily_qkey: number,
      l1_qkey: number,
      l2_qkey: number,
      total_qkey: number,
      cap_hit_during: boolean,
      all_capped_initial: boolean,
      stakings_processed: { staking_id: number, accrual_dates: string[], amount: number, daily_rate: number, per_day_qkey: number, capped_during_loop: boolean }[]
    }
    const userMap = new Map<number, PreviewUserState>()
    const capSkipUsers: number[] = []

    async function getOrInitUser(userId: number): Promise<PreviewUserState> {
      let u = userMap.get(userId)
      if (u) return u
      // 분자 4종 (direct_referral 포함) ★ 영구룰 3️⃣ ★
      const paidRow = await db.prepare(`
        SELECT COALESCE(SUM(amount), 0) as total
        FROM transactions
        WHERE user_id = ? AND coin_type = 'QKEY'
          AND type IN ('daily_qkey','referral_reward','direct_referral')
      `).bind(userId).first() as any
      const emailRow = await db.prepare(`SELECT email FROM users WHERE id = ?`).bind(userId).first() as any

      // 사용자 staking 진입일 ASC = FIFO
      const stkRows = await db.prepare(`
        SELECT id, amount, status,
               date(start_date, '+9 hours') as start_date_kst
        FROM staking
        WHERE user_id = ? AND status IN ('active','completed','capped')
        ORDER BY date(start_date, '+9 hours') ASC, id ASC
      `).bind(userId).all()

      const paid_total_real = Number(paidRow?.total || 0)
      let pool = paid_total_real
      const stakings: SimStaking[] = []
      let stake_total = 0
      for (const r of stkRows.results as any[]) {
        const amount = Number(r.amount)
        stake_total += amount
        const capTarget = amount * 2 * USD_TO_QKEY
        const fill = Math.min(pool, capTarget)
        pool -= fill
        stakings.push({
          id: Number(r.id), amount, capTarget, fill,
          capped: fill >= capTarget,
          start_date_kst: String(r.start_date_kst || ''),
          status_db: String(r.status || 'active')
        })
      }
      const target = stake_total * 2 * USD_TO_QKEY
      const all_capped_initial = stakings.length > 0 && stakings.every(s => s.capped)
      u = {
        user_id: userId,
        email: emailRow?.email || null,
        stake_total,
        paid_total_real,
        target,
        stakings,
        daily_qkey: 0,
        l1_qkey: 0,
        l2_qkey: 0,
        total_qkey: 0,
        cap_hit_during: false,
        all_capped_initial,
        stakings_processed: []
      }
      userMap.set(userId, u)
      return u
    }

    // 영구룰 2️⃣ — 본인 daily: 자기 staking 으로만 (FIFO 이전 금지)
    function simApplyOwnDaily(state: PreviewUserState, stakingId: number, requested: number): number {
      const s = state.stakings.find(x => x.id === stakingId)
      if (!s) return 0
      if (s.capped) return 0
      const room = s.capTarget - s.fill
      const accept = Math.min(requested, room)
      s.fill += accept
      if (s.fill >= s.capTarget) s.capped = true
      return accept
    }

    // 영구룰 2️⃣/6️⃣ — L1/L2 매칭: receiver의 FIFO 첫 미충전 staking으로
    function simApplyReferralFIFO(state: PreviewUserState, requested: number): { accepted: number, targetStakingId: number | null } {
      if (requested <= 0) return { accepted: 0, targetStakingId: null }
      for (const s of state.stakings) {
        if (s.capped) continue
        const room = s.capTarget - s.fill
        const accept = Math.min(requested, room)
        if (accept <= 0) continue
        s.fill += accept
        if (s.fill >= s.capTarget) s.capped = true
        return { accepted: accept, targetStakingId: s.id }
      }
      return { accepted: 0, targetStakingId: null }
    }

    // ===== dry-run 메인 루프 (실제 cron 과 동일 흐름) =====
    for (const staking of activeStakings.results as any[]) {
      const ownerState = await getOrInitUser(staking.user_id as number)
      // 사전 staking-level cap check
      const ownStk = ownerState.stakings.find(s => s.id === Number(staking.staking_id))
      if (!ownStk || ownStk.capped) {
        if (!capSkipUsers.includes(staking.user_id as number)) capSkipUsers.push(staking.user_id as number)
        continue
      }
      const periodDays = staking.period_days || (staking.period_months * 30)
      const accrualDates = getStakingAccrualDatesKst(
        (staking.last_reward_date as string) || null,
        staking.start_date_kst as string,
        yesterdayKst,
        targetDate
      )
      if (accrualDates.length === 0) continue

      const stakingDailyRate = staking.daily_rate || getDailyRate(staking.amount as number)
      const stakingProcessed: string[] = []
      let perDayQkey = Math.round((staking.amount as number) * stakingDailyRate * USD_TO_QKEY)
      let cappedDuringLoop = false

      for (const accrualDate of accrualDates) {
        const currentRewardedCount = (staking.rewarded_count as number) + stakingProcessed.length
        if (currentRewardedCount >= periodDays) break

        // ★ 영구룰 2️⃣ — 이 staking 단독 cap check
        if (ownStk.capped) {
          ownerState.cap_hit_during = true
          cappedDuringLoop = true
          if (!capSkipUsers.includes(ownerState.user_id)) capSkipUsers.push(ownerState.user_id)
          break
        }
        let qkeyAmount = perDayQkey
        const room = ownStk.capTarget - ownStk.fill
        if (qkeyAmount > room) qkeyAmount = Math.max(0, Math.floor(room))
        if (qkeyAmount <= 0) {
          ownerState.cap_hit_during = true
          cappedDuringLoop = true
          if (!capSkipUsers.includes(ownerState.user_id)) capSkipUsers.push(ownerState.user_id)
          break
        }

        const applied = simApplyOwnDaily(ownerState, ownStk.id, qkeyAmount)
        ownerState.daily_qkey += applied
        stakingProcessed.push(accrualDate)

        // L1 매칭 (20%) — receiver staking 단위 FIFO
        const lvl1 = await db.prepare(`SELECT referrer_id FROM users WHERE id = ?`).bind(staking.user_id).first() as any
        if (lvl1 && lvl1.referrer_id) {
          const l1Active = await db.prepare(`
            SELECT id FROM staking
            WHERE user_id = ? AND status = 'active'
              AND date(start_date, '+9 hours') <= date(?)
              AND date(end_date, '+9 hours') >= date(?)
            LIMIT 1
          `).bind(lvl1.referrer_id, accrualDate, accrualDate).first()
          if (l1Active) {
            const l1State = await getOrInitUser(lvl1.referrer_id as number)
            const l1Req = Math.round(applied * 0.20)
            const l1Res = simApplyReferralFIFO(l1State, l1Req)
            if (l1Res.accepted > 0) {
              l1State.l1_qkey += l1Res.accepted
            } else {
              if (!capSkipUsers.includes(lvl1.referrer_id as number)) capSkipUsers.push(lvl1.referrer_id as number)
            }

            // L2 매칭 (10%) — 동일
            const lvl2 = await db.prepare(`SELECT referrer_id FROM users WHERE id = ?`).bind(lvl1.referrer_id).first() as any
            if (lvl2 && lvl2.referrer_id) {
              const l2Active = await db.prepare(`
                SELECT id FROM staking
                WHERE user_id = ? AND status = 'active'
                  AND date(start_date, '+9 hours') <= date(?)
                  AND date(end_date, '+9 hours') >= date(?)
                LIMIT 1
              `).bind(lvl2.referrer_id, accrualDate, accrualDate).first()
              if (l2Active) {
                const l2State = await getOrInitUser(lvl2.referrer_id as number)
                const l2Req = Math.round(applied * 0.10)
                const l2Res = simApplyReferralFIFO(l2State, l2Req)
                if (l2Res.accepted > 0) {
                  l2State.l2_qkey += l2Res.accepted
                } else {
                  if (!capSkipUsers.includes(lvl2.referrer_id as number)) capSkipUsers.push(lvl2.referrer_id as number)
                }
              }
            }
          }
        }
      }

      if (stakingProcessed.length > 0 || cappedDuringLoop) {
        ownerState.stakings_processed.push({
          staking_id: staking.staking_id as number,
          accrual_dates: stakingProcessed,
          amount: staking.amount as number,
          daily_rate: stakingDailyRate,
          per_day_qkey: perDayQkey,
          capped_during_loop: cappedDuringLoop
        })
      }
    }

    // 집계
    const users: any[] = []
    let totalDaily = 0, totalL1 = 0, totalL2 = 0
    for (const u of userMap.values()) {
      u.total_qkey = u.daily_qkey + u.l1_qkey + u.l2_qkey
      if (u.total_qkey > 0 || u.capped_initial || u.cap_hit_during) {
        users.push({
          user_id: u.user_id,
          email: u.email,
          stake_total_usd: u.stake_total,
          paid_total_real_qkey: u.paid_total_real,
          target_qkey: u.target,
          remaining_qkey_before: u.remaining_initial,
          plan_daily_qkey: u.daily_qkey,
          plan_l1_qkey: u.l1_qkey,
          plan_l2_qkey: u.l2_qkey,
          plan_total_qkey: u.total_qkey,
          simulated_paid_after: u.simulated_paid,
          capped_initial: u.capped_initial,
          cap_hit_during: u.cap_hit_during,
          stakings: u.stakings_processed
        })
        totalDaily += u.daily_qkey
        totalL1 += u.l1_qkey
        totalL2 += u.l2_qkey
      }
    }
    users.sort((a, b) => b.plan_total_qkey - a.plan_total_qkey)

    return c.json({
      success: true,
      preview: true,
      targetDate,
      yesterdayKst,
      message: `[DRY-RUN] ${targetDate} cron 실행 예정 — 기준일(어제) ${yesterdayKst}`,
      cron_will_run: true,
      plan_total_users: users.filter(u => u.plan_total_qkey > 0).length,
      plan_total_qkey: totalDaily + totalL1 + totalL2,
      plan_daily_qkey: totalDaily,
      plan_l1_qkey: totalL1,
      plan_l2_qkey: totalL2,
      cap_skip_users: capSkipUsers,
      cap_skip_count: capSkipUsers.length,
      active_stakings_count: activeStakings.results.length,
      users
    })
  } catch (error) {
    console.error('daily-preview error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★ 일일 배당 누락 영구 진단 엔드포인트 (2026-05-12 사장님 결재 옵션 B) ★★★
//   경로: /api/diag/missing-rewards (admin/* 미들웨어 우회 — 자체 ?key= 보호)
//   파라미터:
//     ?from=YYYY-MM-DD   (필수, 검사 시작일 KST)
//     ?to=YYYY-MM-DD     (필수, 검사 종료일 KST, from <= to)
//     ?key=ADMIN_PW      (필수, ADMIN_PW 와 100% 일치 시만 응답)
//     ?staking_id=N      (선택, 특정 staking 만 검사)
//   동작:
//     1) status IN (active, completed, capped) 모든 staking 조회
//        (start_date <= to_date 인 것만, 발생 가능 staking 한정)
//     2) 각 staking 의 발생해야 했던 영업일(KST) 목록 산출
//        - getStakingAccrualDatesKst(null, start_date_kst, to_date, firstBusinessDayKst)
//        - start_date_kst 가 from 보다 이르면 from 으로 클램프 (구간 검사)
//        - firstBusinessDayKst = start_date_kst 가 휴일이면 그 다음 첫 평일 (없으면 to_date)
//     3) daily_rewards 테이블에서 reward_date BETWEEN from AND to AND staking_id = ? 조회
//     4) 차집합 = 누락 영업일 목록
//   응답: 누락 staking 명단 + 누락일자 + user_id/email/총 누락건수
//   ★ 읽기 전용 (INSERT/UPDATE/DELETE 절대 안 함) ★
app.get('/api/diag/missing-rewards', async (c) => {
  try {
    // 자체 보호 (admin 미들웨어 우회 경로이므로 key 강제 검증)
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) {
      return c.json({ error: 'unauthorized' }, 401)
    }

    const db = c.env.DB
    const from = c.req.query('from') || ''
    const to = c.req.query('to') || ''
    const stakingIdFilter = c.req.query('staking_id') || ''

    if (!/^\d{4}-\d{2}-\d{2}$/.test(from)) {
      return c.json({ error: 'from=YYYY-MM-DD 필요' }, 400)
    }
    if (!/^\d{4}-\d{2}-\d{2}$/.test(to)) {
      return c.json({ error: 'to=YYYY-MM-DD 필요' }, 400)
    }
    const fromObj = new Date(from + 'T00:00:00Z')
    const toObj = new Date(to + 'T00:00:00Z')
    if (fromObj.getTime() > toObj.getTime()) {
      return c.json({ error: 'from <= to 필요' }, 400)
    }

    // active/completed/capped staking 모두 조회 (start_date <= to)
    let stakingsQuery = `
      SELECT
        s.id as staking_id,
        s.user_id,
        u.email,
        s.amount,
        s.period_days,
        s.period_months,
        s.daily_rate,
        s.status,
        s.start_date,
        s.end_date,
        date(s.start_date, '+9 hours') as start_date_kst,
        date(s.end_date, '+9 hours') as end_date_kst
      FROM staking s
      LEFT JOIN users u ON u.id = s.user_id
      WHERE s.status IN ('active','completed','capped')
        AND date(s.start_date, '+9 hours') <= date(?)
    `
    const bindArgs: any[] = [to]
    if (stakingIdFilter && /^\d+$/.test(stakingIdFilter)) {
      stakingsQuery += ` AND s.id = ?`
      bindArgs.push(stakingIdFilter)
    }
    stakingsQuery += ` ORDER BY s.user_id ASC, s.id ASC`
    const stakings = await db.prepare(stakingsQuery).bind(...bindArgs).all()

    // 사용자 200% Cap 상태 (참고용 — 누락 발견 시 cap 으로 인한 정상 스킵 구분)
    const USD_TO_QKEY = 150
    const userCapMap = new Map<number, { stake_total: number, paid_total: number, target: number, capped: boolean }>()
    async function getUserCap(userId: number) {
      let u = userCapMap.get(userId)
      if (u) return u
      const stakeRow = await db.prepare(`
        SELECT COALESCE(SUM(amount), 0) as total
        FROM staking WHERE user_id = ? AND status IN ('active','completed','capped')
      `).bind(userId).first() as any
      const paidRow = await db.prepare(`
        SELECT COALESCE(SUM(amount), 0) as total
        FROM transactions
        WHERE user_id = ? AND coin_type = 'QKEY'
          AND type IN ('daily_qkey', 'referral_reward')
      `).bind(userId).first() as any
      const stake_total = Number(stakeRow?.total || 0)
      const paid_total = Number(paidRow?.total || 0)
      const target = stake_total * 2 * USD_TO_QKEY
      const capped = stake_total > 0 && paid_total >= target
      u = { stake_total, paid_total, target, capped }
      userCapMap.set(userId, u)
      return u
    }

    // 휴일 진입자 firstBusinessDay 계산 헬퍼 — start_date_kst 가 휴일이면 그 다음 첫 평일
    function calcFirstBusinessDay(startDateKst: string, toDateKst: string): string {
      const startObj = new Date(startDateKst + 'T00:00:00Z')
      const startCheck = new Date(startObj.getTime() - 9 * 60 * 60 * 1000)
      const { isBusinessDay: startIsBiz } = isKoreanBusinessDay(startCheck)
      if (startIsBiz) return startDateKst
      // 휴일이면 최대 14일 뒤까지 다음 평일 탐색
      for (let i = 1; i <= 14; i++) {
        const candidate = new Date(startObj.getTime() + i * 24 * 60 * 60 * 1000)
        const check = new Date(candidate.getTime() - 9 * 60 * 60 * 1000)
        const { isBusinessDay } = isKoreanBusinessDay(check)
        if (isBusinessDay) return candidate.toISOString().split('T')[0]
      }
      return toDateKst
    }

    type MissRow = {
      staking_id: number,
      user_id: number,
      email: string | null,
      status: string,
      start_date_kst: string,
      end_date_kst: string,
      amount: number,
      expected_dates: string[],         // from~to 사이 발생해야 했던 영업일
      actual_dates: string[],            // from~to 사이 실제 지급된 reward_date
      missing_dates: string[],           // 차집합 = 누락 영업일
      missing_count: number,
      user_capped: boolean,              // 본인 200% cap 여부 (정상 스킵 구분용)
      note: string
    }

    const missList: MissRow[] = []
    const fullList: any[] = []
    let totalChecked = 0
    let totalMissing = 0
    let totalMissingDates = 0

    for (const st of stakings.results as any[]) {
      totalChecked++
      const stakingId = st.staking_id as number
      const startKst = st.start_date_kst as string
      const endKst = st.end_date_kst as string
      // 검사 구간: [max(from, start_date_kst) .. min(to, end_date_kst)]
      const effFromObj = new Date(Math.max(
        fromObj.getTime(),
        new Date(startKst + 'T00:00:00Z').getTime()
      ))
      const effToObj = new Date(Math.min(
        toObj.getTime(),
        new Date(endKst + 'T00:00:00Z').getTime()
      ))
      if (effFromObj.getTime() > effToObj.getTime()) continue
      const effFrom = effFromObj.toISOString().split('T')[0]
      const effTo = effToObj.toISOString().split('T')[0]

      // 발생해야 했던 영업일 산출 (lastRewardDate=null → start_date 부터 풀 발생)
      const firstBizDay = calcFirstBusinessDay(startKst, effTo)
      const allAccrualDates = getStakingAccrualDatesKst(null, startKst, effTo, firstBizDay)
      // 검사 구간으로 클램프 (effFrom 이전 영업일은 별도 cron 에서 처리됐을 수 있음)
      const expectedInRange = allAccrualDates.filter(d => d >= effFrom && d <= effTo)

      // 실제 지급 조회
      const actualRows = await db.prepare(`
        SELECT reward_date FROM daily_rewards
        WHERE staking_id = ? AND reward_date >= ? AND reward_date <= ?
        ORDER BY reward_date ASC
      `).bind(stakingId, effFrom, effTo).all()
      const actualDates = (actualRows.results as any[]).map(r => r.reward_date as string)
      const actualSet = new Set(actualDates)

      // 차집합 = 누락
      const missingDates = expectedInRange.filter(d => !actualSet.has(d))

      // user cap 상태 (정상 스킵 구분)
      const userCap = await getUserCap(st.user_id as number)

      let note = ''
      if (missingDates.length > 0 && userCap.capped) {
        note = '본인 200% cap 도달 — 누락이 정상일 수 있음 (cron 의 cap 스킵)'
      } else if (missingDates.length > 0) {
        note = '실제 누락 — 백필 검토 필요'
      } else {
        note = 'OK'
      }

      const row: MissRow = {
        staking_id: stakingId,
        user_id: st.user_id as number,
        email: st.email || null,
        status: st.status as string,
        start_date_kst: startKst,
        end_date_kst: endKst,
        amount: Number(st.amount || 0),
        expected_dates: expectedInRange,
        actual_dates: actualDates,
        missing_dates: missingDates,
        missing_count: missingDates.length,
        user_capped: userCap.capped,
        note
      }
      fullList.push(row)
      if (missingDates.length > 0) {
        missList.push(row)
        totalMissing++
        totalMissingDates += missingDates.length
      }
    }

    // 누락 staking 우선 정렬 (누락 건수 많은 순)
    missList.sort((a, b) => b.missing_count - a.missing_count)
    fullList.sort((a, b) => b.missing_count - a.missing_count)

    // 날짜별 누락 통계
    const byDate = new Map<string, number>()
    for (const m of missList) {
      for (const d of m.missing_dates) {
        byDate.set(d, (byDate.get(d) || 0) + 1)
      }
    }
    const missingByDate: { date: string, count: number }[] = []
    for (const [date, count] of byDate.entries()) {
      missingByDate.push({ date, count })
    }
    missingByDate.sort((a, b) => a.date.localeCompare(b.date))

    return c.json({
      success: true,
      diag: true,
      readonly: true,
      from,
      to,
      summary: {
        total_stakings_checked: totalChecked,
        stakings_with_missing: totalMissing,
        total_missing_date_rows: totalMissingDates,
        missing_by_date: missingByDate
      },
      missing_stakings: missList,
      all_stakings: fullList
    })
  } catch (error) {
    console.error('missing-rewards diag error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★ 휴일 진입자 전수 조사 (5/9, 5/10 등 토/일/공휴일 진입자) ★★★
//   경로: /api/diag/holiday-entrants?from=YYYY-MM-DD&to=YYYY-MM-DD&check_date=YYYY-MM-DD&key=ADMIN_PW
//   읽기 전용:
//     1) start_date_kst BETWEEN from AND to AND 그 날짜가 토/일/공휴일인 staking 전수
//     2) 각 staking 의 last_reward_date + daily_rewards 행수
//     3) check_date 의 reward_date 가 있는지 (= 그날 일일배당 지급됐는지)
app.get('/api/diag/holiday-entrants', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)

    const db = c.env.DB
    const from = c.req.query('from') || ''
    const to = c.req.query('to') || ''
    const checkDate = c.req.query('check_date') || ''
    if (!/^\d{4}-\d{2}-\d{2}$/.test(from) || !/^\d{4}-\d{2}-\d{2}$/.test(to) || !/^\d{4}-\d{2}-\d{2}$/.test(checkDate)) {
      return c.json({ error: 'from, to, check_date 모두 YYYY-MM-DD 필요' }, 400)
    }

    // start_date_kst BETWEEN from AND to 의 모든 staking 조회
    const stakings = await db.prepare(`
      SELECT
        s.id as staking_id, s.user_id, u.email,
        s.amount, s.status,
        date(s.start_date, '+9 hours') as start_date_kst,
        date(s.end_date, '+9 hours') as end_date_kst,
        (SELECT COUNT(*) FROM daily_rewards WHERE staking_id = s.id) as rewarded_count,
        (SELECT MAX(reward_date) FROM daily_rewards WHERE staking_id = s.id) as last_reward_date,
        (SELECT id FROM daily_rewards WHERE staking_id = s.id AND reward_date = ?) as reward_on_check_date
      FROM staking s
      LEFT JOIN users u ON u.id = s.user_id
      WHERE date(s.start_date, '+9 hours') BETWEEN ? AND ?
        AND s.status IN ('active','completed','capped')
      ORDER BY s.user_id ASC, s.id ASC
    `).bind(checkDate, from, to).all()

    // 휴일 판정 + 결과 정리
    const list: any[] = []
    let holidayCount = 0
    let missingOnCheckDate = 0
    let paidOnCheckDate = 0
    for (const st of stakings.results as any[]) {
      const startKst = st.start_date_kst as string
      const startObj = new Date(startKst + 'T00:00:00Z')
      const startCheck = new Date(startObj.getTime() - 9 * 60 * 60 * 1000)
      const { isBusinessDay: isStartBiz, reason: startReason } = isKoreanBusinessDay(startCheck)
      const isHolidayEntry = !isStartBiz
      if (!isHolidayEntry) continue
      holidayCount++
      const hasRewardOnCheckDate = !!st.reward_on_check_date
      if (hasRewardOnCheckDate) paidOnCheckDate++
      else missingOnCheckDate++
      list.push({
        staking_id: st.staking_id,
        user_id: st.user_id,
        email: st.email,
        amount: st.amount,
        status: st.status,
        start_date_kst: startKst,
        start_reason: startReason,  // saturday / sunday / holiday
        end_date_kst: st.end_date_kst,
        rewarded_count: st.rewarded_count,
        last_reward_date: st.last_reward_date,
        check_date: checkDate,
        paid_on_check_date: hasRewardOnCheckDate
      })
    }

    return c.json({
      success: true,
      from, to, check_date: checkDate,
      summary: {
        total_holiday_entrants: holidayCount,
        paid_on_check_date: paidOnCheckDate,
        missing_on_check_date: missingOnCheckDate
      },
      entrants: list
    })
  } catch (error) {
    console.error('holiday-entrants diag error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★ 5/12 누락 5건 백필 (옵션2 manual_insert) — 사장님 결재 2026-05-12 ★★★
//   경로: POST /api/diag/backfill-may12-missing?key=ADMIN_PW&dry_run=1|0
//   대상 staking_id: [94, 95, 96, 97, 98] (5/9 토 + 5/10 일 진입자, 5/11 1회만 지급되고 5/12 누락)
//   처리 흐름 (cron 정확히 동일 패턴):
//     1) EXISTS guard: daily_rewards (user, staking, reward_date=2026-05-12) 이미 있으면 skip
//     2) 200% cap 체크 (B안) — 본인 cap 도달 시 skip / 부분지급
//     3) daily_rate = getDailyRate(amount, asOf=2026-05-12) — V2 적용
//     4) usdt_amount = amount * dailyRate (USD), qkeyAmount = round(usdt_amount * 150)
//     5) INSERT daily_rewards (reward_date=2026-05-12, paid_date=2026-05-12) → ref_id 캡처
//     6) UPDATE users.qkey_balance += qkeyAmount
//     7) INSERT transactions (type=daily_qkey, description='일일 배당 (QKEY)', ref_id=drId)
//     8) L1 매칭 20% + EXISTS guard + cap 체크 (description='추천 보너스 (Level 1)')
//     9) L2 매칭 10% + EXISTS guard + cap 체크 (description='추천 보너스 (Level 2)')
//   ★ description 영구룰: 사용자 노출 안전 한국어만 (boss-ordered/reason= 등 절대 금지)
app.post('/api/diag/backfill-may12-missing', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const dep = assertNotDeprecated(c, 'backfill-may12-missing', '5/12 누락 백필 완료 (2026-05-12). safeInsertTransaction 가드 미적용 → 재호출 시 이중지급 위험. 후속: may13-multi-staking-backfill 사용')
    if (dep) return dep

    const dryRun = c.req.query('dry_run') === '1'
    const db = c.env.DB

    // 하드코드 대상 staking_id 5건 (X-A 사실 검증 완료)
    // ★ D1 timeout 방지: ?only=N 으로 1건씩 실행 가능 (없으면 5건 전체)
    const ALL_TARGET_STAKING_IDS = [94, 95, 96, 97, 98]
    const onlyParam = c.req.query('only')
    const TARGET_STAKING_IDS = onlyParam
      ? ALL_TARGET_STAKING_IDS.filter(id => id === Number(onlyParam))
      : ALL_TARGET_STAKING_IDS
    const REWARD_DATE = '2026-05-12'
    const PAID_DATE = '2026-05-12'
    const USD_TO_QKEY = 150

    // 200% cap 체크 헬퍼 (cron 과 동일)
    async function isUserCapped(userId: number): Promise<{ capped: boolean, paidTotal: number, target: number, percent: number }> {
      const stakeRow = await db.prepare(`
        SELECT COALESCE(SUM(amount), 0) as total
        FROM staking WHERE user_id = ? AND status IN ('active','completed','capped')
      `).bind(userId).first() as any
      const stakeTotal = Number(stakeRow?.total || 0)
      if (stakeTotal <= 0) return { capped: false, paidTotal: 0, target: 0, percent: 0 }

      const paidRow = await db.prepare(`
        SELECT COALESCE(SUM(amount), 0) as total
        FROM transactions
        WHERE user_id = ? AND coin_type = 'QKEY'
          AND type IN ('daily_qkey', 'referral_reward')
      `).bind(userId).first() as any
      const paidTotal = Number(paidRow?.total || 0)
      const target = stakeTotal * 2 * USD_TO_QKEY
      const percent = target > 0 ? (paidTotal / target * 100) : 0
      return { capped: paidTotal >= target, paidTotal, target, percent }
    }

    // asOf = 2026-05-12 KST (V2 정책 적용)
    const asOf = new Date('2026-05-12T00:00:00+09:00')

    const results: any[] = []
    let totalDailyQkey = 0
    let totalL1Qkey = 0
    let totalL2Qkey = 0
    let insertedCount = 0
    let skippedCount = 0

    for (const stakingId of TARGET_STAKING_IDS) {
      const row: any = {
        staking_id: stakingId,
        dry_run: dryRun,
        steps: [] as string[]
      }

      // 1) staking 정보 조회 (rewarded_count + last_reward_date 모두 daily_rewards 서브쿼리로 계산)
      const staking = await db.prepare(`
        SELECT s.id as staking_id, s.user_id, s.amount, s.daily_rate, s.status,
               s.start_date, s.end_date, s.period_days, s.period_months,
               (SELECT COUNT(*) FROM daily_rewards WHERE staking_id = s.id) as rewarded_count,
               (SELECT MAX(reward_date) FROM daily_rewards WHERE staking_id = s.id) as last_reward_date,
               u.email as user_email
        FROM staking s
        LEFT JOIN users u ON u.id = s.user_id
        WHERE s.id = ?
      `).bind(stakingId).first() as any

      if (!staking) {
        row.error = 'staking not found'
        results.push(row)
        skippedCount++
        continue
      }

      row.user_id = staking.user_id
      row.user_email = staking.user_email
      row.amount = staking.amount

      // 2) EXISTS guard — 5/12 reward_date 이미 있으면 skip
      const exists = await db.prepare(`
        SELECT COUNT(*) as count FROM daily_rewards
        WHERE user_id = ? AND staking_id = ? AND reward_date = ?
      `).bind(staking.user_id, stakingId, REWARD_DATE).first() as any

      if ((exists?.count || 0) > 0) {
        row.skip_reason = 'already_exists'
        row.steps.push('EXISTS guard hit — daily_rewards 이미 존재')
        results.push(row)
        skippedCount++
        continue
      }

      // 3) 본인 cap 체크
      const capState = await isUserCapped(staking.user_id as number)
      row.cap_state = {
        capped: capState.capped,
        paid_total: capState.paidTotal,
        target: capState.target,
        percent: Math.round(capState.percent * 100) / 100
      }
      if (capState.capped) {
        row.skip_reason = 'user_capped_200pct'
        row.steps.push('200% cap 도달 — daily skip')
        results.push(row)
        skippedCount++
        continue
      }

      // 4) 금액 계산
      const dailyRate = staking.daily_rate || getDailyRate(staking.amount, asOf)
      const usdAmount = staking.amount * dailyRate
      let qkeyAmount = Math.round(usdAmount * USD_TO_QKEY)

      // 부분지급 (cap 잔여 한도)
      const remaining = capState.target - capState.paidTotal
      if (qkeyAmount > remaining) {
        qkeyAmount = Math.max(0, Math.floor(remaining))
        row.steps.push(`partial payment (cap remaining=${remaining})`)
      }

      if (qkeyAmount <= 0) {
        row.skip_reason = 'qkey_amount_zero'
        results.push(row)
        skippedCount++
        continue
      }

      row.daily_rate = dailyRate
      row.usdt_amount = usdAmount
      row.qkey_amount = qkeyAmount

      if (dryRun) {
        row.steps.push(`[DRY] would INSERT daily_rewards + transactions (${qkeyAmount} QKEY)`)
      } else {
        // 5) INSERT daily_rewards
        const drIns = await db.prepare(`
          INSERT INTO daily_rewards (user_id, staking_id, usdt_amount, reward_date, paid_date)
          VALUES (?, ?, ?, ?, ?)
        `).bind(staking.user_id, stakingId, qkeyAmount, REWARD_DATE, PAID_DATE).run()
        const drId = (drIns as any)?.meta?.last_row_id ?? null
        row.dr_id = drId

        // 6) UPDATE users.qkey_balance
        await db.prepare(`
          UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?
        `).bind(qkeyAmount, staking.user_id).run()

        // 7) INSERT transactions (EXISTS guard ref_id 1:1)
        const dqExists = await db.prepare(`
          SELECT id FROM transactions
          WHERE type = 'daily_qkey' AND ref_id = ?
          LIMIT 1
        `).bind(drId).first()
        if (!dqExists) {
          await db.prepare(`
            INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
            VALUES (?, 'daily_qkey', 'QKEY', ?, ?, ?)
          `).bind(staking.user_id, qkeyAmount, '일일 배당 (QKEY)', drId).run()
        }

        row.steps.push(`INSERT daily_rewards id=${drId}, qkey=${qkeyAmount}, balance updated`)
      }
      totalDailyQkey += qkeyAmount
      if (!dryRun) insertedCount++

      // 8) L1 매칭 (20%)
      const l1Ref = await db.prepare(`
        SELECT referrer_id FROM users WHERE id = ?
      `).bind(staking.user_id).first() as any

      if (l1Ref && l1Ref.referrer_id) {
        // L1 active staking 여부 확인 (accrualDate=5/12 시점)
        const l1Active = await db.prepare(`
          SELECT id FROM staking
          WHERE user_id = ?
            AND status = 'active'
            AND date(start_date, '+9 hours') <= date(?)
            AND date(end_date, '+9 hours') >= date(?)
          LIMIT 1
        `).bind(l1Ref.referrer_id, REWARD_DATE, REWARD_DATE).first()

        row.l1_referrer_id = l1Ref.referrer_id
        row.l1_active = !!l1Active

        if (l1Active) {
          const l1Exists = await db.prepare(`
            SELECT COUNT(*) as count FROM referral_rewards
            WHERE referrer_id = ? AND referee_id = ? AND level = 1 AND reward_date = ?
          `).bind(l1Ref.referrer_id, staking.user_id, REWARD_DATE).first() as any

          if ((l1Exists?.count || 0) === 0) {
            const l1Cap = await isUserCapped(l1Ref.referrer_id as number)
            if (l1Cap.capped) {
              row.l1_skip = 'l1_capped'
            } else {
              let l1Reward = Math.round(qkeyAmount * 0.20)
              const l1Rem = l1Cap.target - l1Cap.paidTotal
              if (l1Reward > l1Rem) l1Reward = Math.max(0, Math.floor(l1Rem))

              if (l1Reward > 0) {
                row.l1_reward = l1Reward
                if (dryRun) {
                  row.steps.push(`[DRY] would INSERT L1 reward ${l1Reward} QKEY → user#${l1Ref.referrer_id}`)
                } else {
                  await db.prepare(`
                    UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?
                  `).bind(l1Reward, l1Ref.referrer_id).run()

                  const rrL1Ins = await db.prepare(`
                    INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date)
                    VALUES (?, ?, 1, ?, ?, ?, ?)
                  `).bind(l1Ref.referrer_id, staking.user_id, qkeyAmount, l1Reward, REWARD_DATE, PAID_DATE).run()
                  const rrL1Id = (rrL1Ins as any)?.meta?.last_row_id ?? null

                  const l1TxExists = await db.prepare(`
                    SELECT id FROM transactions
                    WHERE type = 'referral_reward' AND ref_id = ?
                    LIMIT 1
                  `).bind(rrL1Id).first()
                  if (!l1TxExists) {
                    await db.prepare(`
                      INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
                      VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?)
                    `).bind(l1Ref.referrer_id, l1Reward, '추천 보너스 (Level 1)', rrL1Id).run()
                  }
                  row.steps.push(`INSERT L1 reward id=${rrL1Id}, ${l1Reward} QKEY → user#${l1Ref.referrer_id}`)
                }
                totalL1Qkey += l1Reward
              }
            }
          } else {
            row.l1_skip = 'l1_already_exists'
          }

          // 9) L2 매칭 (10%)
          const l2Ref = await db.prepare(`
            SELECT referrer_id FROM users WHERE id = ?
          `).bind(l1Ref.referrer_id).first() as any

          if (l2Ref && l2Ref.referrer_id) {
            const l2Active = await db.prepare(`
              SELECT id FROM staking
              WHERE user_id = ?
                AND status = 'active'
                AND date(start_date, '+9 hours') <= date(?)
                AND date(end_date, '+9 hours') >= date(?)
              LIMIT 1
            `).bind(l2Ref.referrer_id, REWARD_DATE, REWARD_DATE).first()

            row.l2_referrer_id = l2Ref.referrer_id
            row.l2_active = !!l2Active

            if (l2Active) {
              const l2Exists = await db.prepare(`
                SELECT COUNT(*) as count FROM referral_rewards
                WHERE referrer_id = ? AND referee_id = ? AND level = 2 AND reward_date = ?
              `).bind(l2Ref.referrer_id, staking.user_id, REWARD_DATE).first() as any

              if ((l2Exists?.count || 0) === 0) {
                const l2Cap = await isUserCapped(l2Ref.referrer_id as number)
                if (l2Cap.capped) {
                  row.l2_skip = 'l2_capped'
                } else {
                  let l2Reward = Math.round(qkeyAmount * 0.10)
                  const l2Rem = l2Cap.target - l2Cap.paidTotal
                  if (l2Reward > l2Rem) l2Reward = Math.max(0, Math.floor(l2Rem))

                  if (l2Reward > 0) {
                    row.l2_reward = l2Reward
                    if (dryRun) {
                      row.steps.push(`[DRY] would INSERT L2 reward ${l2Reward} QKEY → user#${l2Ref.referrer_id}`)
                    } else {
                      await db.prepare(`
                        UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?
                      `).bind(l2Reward, l2Ref.referrer_id).run()

                      const rrL2Ins = await db.prepare(`
                        INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date)
                        VALUES (?, ?, 2, ?, ?, ?, ?)
                      `).bind(l2Ref.referrer_id, staking.user_id, qkeyAmount, l2Reward, REWARD_DATE, PAID_DATE).run()
                      const rrL2Id = (rrL2Ins as any)?.meta?.last_row_id ?? null

                      const l2TxExists = await db.prepare(`
                        SELECT id FROM transactions
                        WHERE type = 'referral_reward' AND ref_id = ?
                        LIMIT 1
                      `).bind(rrL2Id).first()
                      if (!l2TxExists) {
                        await db.prepare(`
                          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
                          VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?)
                        `).bind(l2Ref.referrer_id, l2Reward, '추천 보너스 (Level 2)', rrL2Id).run()
                      }
                      row.steps.push(`INSERT L2 reward id=${rrL2Id}, ${l2Reward} QKEY → user#${l2Ref.referrer_id}`)
                    }
                    totalL2Qkey += l2Reward
                  }
                }
              } else {
                row.l2_skip = 'l2_already_exists'
              }
            }
          }
        }
      }

      results.push(row)
    }

    return c.json({
      success: true,
      dry_run: dryRun,
      reward_date: REWARD_DATE,
      paid_date: PAID_DATE,
      target_staking_ids: TARGET_STAKING_IDS,
      summary: {
        inserted_count: insertedCount,
        skipped_count: skippedCount,
        total_daily_qkey: totalDailyQkey,
        total_l1_qkey: totalL1Qkey,
        total_l2_qkey: totalL2Qkey,
        grand_total_qkey: totalDailyQkey + totalL1Qkey + totalL2Qkey
      },
      results
    })
  } catch (error) {
    console.error('backfill-may12-missing error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★ 5/4 누락 18건 백필 — 휴일(5/3 일요일) 진입자 첫 평일 데일리 (사장님 2026-05-15 결재) ★★★
//   진단 결과 (audit-holiday-entrant-all-weekday): missing_by_date.2026-05-04 = 18건 / 13,500 QKEY
//   대상 staking_id: [44, 45, 46, 47, 48, 49, 53, 54, 56, 57, 58, 59, 60, 61, 62, 63, 64, 65]
//   원인: 5/4(월) cron 실행 당시 휴일진입자 첫 평일 강제 push 로직 미적용 → 5/3 일요일 진입자 5/4 첫 데일리 누락
//   현재 5/6~5/14 평일 데일리는 정상 지급됨 — 오직 5/4 1일치만 보정
//   경로: POST /api/diag/backfill-may04-missing?key=ADMIN_PW&dry_run=1|0
//   처리: backfill-may12-missing 와 100% 동일 패턴 (EXISTS guard + 200% cap + L1 20% + L2 10% + description 영구룰)
app.post('/api/diag/backfill-may04-missing', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)

    const dryRun = c.req.query('dry_run') === '1'
    const db = c.env.DB

    const ALL_TARGET_STAKING_IDS = [44, 45, 46, 47, 48, 49, 53, 54, 56, 57, 58, 59, 60, 61, 62, 63, 64, 65]
    const onlyParam = c.req.query('only')
    const TARGET_STAKING_IDS = onlyParam
      ? ALL_TARGET_STAKING_IDS.filter(id => id === Number(onlyParam))
      : ALL_TARGET_STAKING_IDS
    const REWARD_DATE = '2026-05-04'
    const PAID_DATE = '2026-05-04'
    const USD_TO_QKEY = 150

    async function isUserCapped(userId: number): Promise<{ capped: boolean, paidTotal: number, target: number, percent: number }> {
      const stakeRow = await db.prepare(`
        SELECT COALESCE(SUM(amount), 0) as total
        FROM staking WHERE user_id = ? AND status IN ('active','completed','capped')
      `).bind(userId).first() as any
      const stakeTotal = Number(stakeRow?.total || 0)
      if (stakeTotal <= 0) return { capped: false, paidTotal: 0, target: 0, percent: 0 }
      const paidRow = await db.prepare(`
        SELECT COALESCE(SUM(amount), 0) as total
        FROM transactions
        WHERE user_id = ? AND coin_type = 'QKEY'
          AND type IN ('daily_qkey', 'referral_reward')
      `).bind(userId).first() as any
      const paidTotal = Number(paidRow?.total || 0)
      const target = stakeTotal * 2 * USD_TO_QKEY
      const percent = target > 0 ? (paidTotal / target * 100) : 0
      return { capped: paidTotal >= target, paidTotal, target, percent }
    }

    const asOf = new Date('2026-05-04T00:00:00+09:00')

    const results: any[] = []
    let totalDailyQkey = 0
    let totalL1Qkey = 0
    let totalL2Qkey = 0
    let insertedCount = 0
    let skippedCount = 0

    for (const stakingId of TARGET_STAKING_IDS) {
      const row: any = { staking_id: stakingId, dry_run: dryRun, steps: [] as string[] }

      const staking = await db.prepare(`
        SELECT s.id as staking_id, s.user_id, s.amount, s.daily_rate, s.status,
               s.start_date, s.end_date,
               u.email as user_email
        FROM staking s
        LEFT JOIN users u ON u.id = s.user_id
        WHERE s.id = ?
      `).bind(stakingId).first() as any

      if (!staking) {
        row.error = 'staking not found'
        results.push(row); skippedCount++; continue
      }
      row.user_id = staking.user_id
      row.user_email = staking.user_email
      row.amount = staking.amount

      // EXISTS guard (이중지급 절대 방지)
      const exists = await db.prepare(`
        SELECT COUNT(*) as count FROM daily_rewards
        WHERE user_id = ? AND staking_id = ? AND reward_date = ?
      `).bind(staking.user_id, stakingId, REWARD_DATE).first() as any
      if ((exists?.count || 0) > 0) {
        row.skip_reason = 'already_exists'
        row.steps.push('EXISTS guard hit — daily_rewards 이미 존재')
        results.push(row); skippedCount++; continue
      }

      const capState = await isUserCapped(staking.user_id as number)
      row.cap_state = { capped: capState.capped, paid_total: capState.paidTotal, target: capState.target, percent: Math.round(capState.percent * 100) / 100 }
      if (capState.capped) {
        row.skip_reason = 'user_capped_200pct'
        row.steps.push('200% cap 도달 — daily skip')
        results.push(row); skippedCount++; continue
      }

      const dailyRate = staking.daily_rate || getDailyRate(staking.amount, asOf)
      const usdAmount = staking.amount * dailyRate
      let qkeyAmount = Math.round(usdAmount * USD_TO_QKEY)
      const remaining = capState.target - capState.paidTotal
      if (qkeyAmount > remaining) {
        qkeyAmount = Math.max(0, Math.floor(remaining))
        row.steps.push(`partial payment (cap remaining=${remaining})`)
      }
      if (qkeyAmount <= 0) {
        row.skip_reason = 'qkey_amount_zero'
        results.push(row); skippedCount++; continue
      }

      row.daily_rate = dailyRate
      row.usdt_amount = usdAmount
      row.qkey_amount = qkeyAmount

      let drId: any = null
      if (dryRun) {
        row.steps.push(`[DRY] would INSERT daily_rewards + transactions (${qkeyAmount} QKEY)`)
      } else {
        const drIns = await db.prepare(`
          INSERT INTO daily_rewards (user_id, staking_id, usdt_amount, reward_date, paid_date)
          VALUES (?, ?, ?, ?, ?)
        `).bind(staking.user_id, stakingId, qkeyAmount, REWARD_DATE, PAID_DATE).run()
        drId = (drIns as any)?.meta?.last_row_id ?? null
        row.dr_id = drId

        await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(qkeyAmount, staking.user_id).run()

        const dqExists = await db.prepare(`SELECT id FROM transactions WHERE type = 'daily_qkey' AND ref_id = ? LIMIT 1`).bind(drId).first()
        if (!dqExists) {
          await db.prepare(`
            INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
            VALUES (?, 'daily_qkey', 'QKEY', ?, ?, ?)
          `).bind(staking.user_id, qkeyAmount, '일일 배당 (QKEY)', drId).run()
        }
        row.steps.push(`INSERT daily_rewards id=${drId}, qkey=${qkeyAmount}, balance updated`)
      }
      totalDailyQkey += qkeyAmount
      if (!dryRun) insertedCount++

      // L1 매칭 (20%)
      const l1Ref = await db.prepare(`SELECT referrer_id FROM users WHERE id = ?`).bind(staking.user_id).first() as any
      if (l1Ref && l1Ref.referrer_id) {
        const l1Active = await db.prepare(`
          SELECT id FROM staking WHERE user_id = ? AND status = 'active'
            AND date(start_date, '+9 hours') <= date(?) AND date(end_date, '+9 hours') >= date(?) LIMIT 1
        `).bind(l1Ref.referrer_id, REWARD_DATE, REWARD_DATE).first()
        row.l1_referrer_id = l1Ref.referrer_id
        row.l1_active = !!l1Active

        if (l1Active) {
          const l1Exists = await db.prepare(`
            SELECT COUNT(*) as count FROM referral_rewards
            WHERE referrer_id = ? AND referee_id = ? AND level = 1 AND reward_date = ?
          `).bind(l1Ref.referrer_id, staking.user_id, REWARD_DATE).first() as any
          if ((l1Exists?.count || 0) === 0) {
            const l1Cap = await isUserCapped(l1Ref.referrer_id as number)
            if (l1Cap.capped) {
              row.l1_skip = 'l1_capped'
            } else {
              let l1Reward = Math.round(qkeyAmount * 0.20)
              const l1Rem = l1Cap.target - l1Cap.paidTotal
              if (l1Reward > l1Rem) l1Reward = Math.max(0, Math.floor(l1Rem))
              if (l1Reward > 0) {
                row.l1_reward = l1Reward
                if (dryRun) {
                  row.steps.push(`[DRY] would INSERT L1 reward ${l1Reward} QKEY -> user#${l1Ref.referrer_id}`)
                } else {
                  await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(l1Reward, l1Ref.referrer_id).run()
                  const rrL1Ins = await db.prepare(`
                    INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date)
                    VALUES (?, ?, 1, ?, ?, ?, ?)
                  `).bind(l1Ref.referrer_id, staking.user_id, qkeyAmount, l1Reward, REWARD_DATE, PAID_DATE).run()
                  const rrL1Id = (rrL1Ins as any)?.meta?.last_row_id ?? null
                  const l1TxExists = await db.prepare(`SELECT id FROM transactions WHERE type = 'referral_reward' AND ref_id = ? LIMIT 1`).bind(rrL1Id).first()
                  if (!l1TxExists) {
                    await db.prepare(`
                      INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
                      VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?)
                    `).bind(l1Ref.referrer_id, l1Reward, '추천 보너스 (Level 1)', rrL1Id).run()
                  }
                  row.steps.push(`INSERT L1 reward id=${rrL1Id}, ${l1Reward} QKEY -> user#${l1Ref.referrer_id}`)
                }
                totalL1Qkey += l1Reward
              }
            }
          } else {
            row.l1_skip = 'l1_already_exists'
          }

          // L2 매칭 (10%)
          const l2Ref = await db.prepare(`SELECT referrer_id FROM users WHERE id = ?`).bind(l1Ref.referrer_id).first() as any
          if (l2Ref && l2Ref.referrer_id) {
            const l2Active = await db.prepare(`
              SELECT id FROM staking WHERE user_id = ? AND status = 'active'
                AND date(start_date, '+9 hours') <= date(?) AND date(end_date, '+9 hours') >= date(?) LIMIT 1
            `).bind(l2Ref.referrer_id, REWARD_DATE, REWARD_DATE).first()
            row.l2_referrer_id = l2Ref.referrer_id
            row.l2_active = !!l2Active
            if (l2Active) {
              const l2Exists = await db.prepare(`
                SELECT COUNT(*) as count FROM referral_rewards
                WHERE referrer_id = ? AND referee_id = ? AND level = 2 AND reward_date = ?
              `).bind(l2Ref.referrer_id, staking.user_id, REWARD_DATE).first() as any
              if ((l2Exists?.count || 0) === 0) {
                const l2Cap = await isUserCapped(l2Ref.referrer_id as number)
                if (l2Cap.capped) {
                  row.l2_skip = 'l2_capped'
                } else {
                  let l2Reward = Math.round(qkeyAmount * 0.10)
                  const l2Rem = l2Cap.target - l2Cap.paidTotal
                  if (l2Reward > l2Rem) l2Reward = Math.max(0, Math.floor(l2Rem))
                  if (l2Reward > 0) {
                    row.l2_reward = l2Reward
                    if (dryRun) {
                      row.steps.push(`[DRY] would INSERT L2 reward ${l2Reward} QKEY -> user#${l2Ref.referrer_id}`)
                    } else {
                      await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(l2Reward, l2Ref.referrer_id).run()
                      const rrL2Ins = await db.prepare(`
                        INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date)
                        VALUES (?, ?, 2, ?, ?, ?, ?)
                      `).bind(l2Ref.referrer_id, staking.user_id, qkeyAmount, l2Reward, REWARD_DATE, PAID_DATE).run()
                      const rrL2Id = (rrL2Ins as any)?.meta?.last_row_id ?? null
                      const l2TxExists = await db.prepare(`SELECT id FROM transactions WHERE type = 'referral_reward' AND ref_id = ? LIMIT 1`).bind(rrL2Id).first()
                      if (!l2TxExists) {
                        await db.prepare(`
                          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
                          VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?)
                        `).bind(l2Ref.referrer_id, l2Reward, '추천 보너스 (Level 2)', rrL2Id).run()
                      }
                      row.steps.push(`INSERT L2 reward id=${rrL2Id}, ${l2Reward} QKEY -> user#${l2Ref.referrer_id}`)
                    }
                    totalL2Qkey += l2Reward
                  }
                }
              } else {
                row.l2_skip = 'l2_already_exists'
              }
            }
          }
        }
      }

      results.push(row)
    }

    return c.json({
      success: true,
      dry_run: dryRun,
      reward_date: REWARD_DATE,
      paid_date: PAID_DATE,
      target_staking_ids: TARGET_STAKING_IDS,
      summary: {
        inserted_count: insertedCount,
        skipped_count: skippedCount,
        total_daily_qkey: totalDailyQkey,
        total_l1_qkey: totalL1Qkey,
        total_l2_qkey: totalL2Qkey,
        grand_total_qkey: totalDailyQkey + totalL1Qkey + totalL2Qkey
      },
      results
    })
  } catch (error) {
    console.error('backfill-may04-missing error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ 직접판매수당 누락 백필 (2026-06-16 사장님 지시) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   사실관계:
//     - 안금주(108) 가 2026-06-13 매출 1,000 USD 스테이킹 승인됨.
//     - 안금주의 직접 추천인 = 노학선(101).
//     - 정책: 직접판매수당 = 매출원금 × 10% × 150(USD→QKEY) = 1000 × 0.10 × 150 = 15,000 QKEY.
//     - 같은 날 오주석(110)/이두형(111) 매출 → 안금주에게 직접판매수당 15,000 QKEY 정상 지급됨.
//     - 그러나 안금주 매출 → 노학선 직접판매수당 15,000 QKEY 가 referral_rewards/transactions 어디에도 없음 (누락).
//   추정 원인:
//     - staking 승인 핸들러(2876줄)는 추천인 본인이 'active 스테이킹 거치기간 내'일 때만 직접판매수당 지급.
//       안금주 승인 시점에 노학선의 active 스테이킹 윈도(start<=오늘<=end) 판정이 빗나갔거나
//       승인 트랜잭션 도중 직접추천수당 블록이 예외/스킵된 것으로 보임.
//   처리:
//     - 다른 백필 endpoint 와 동일한 EXISTS guard + ref_id 1:1 매핑 패턴.
//     - (referrer=노학선, referee=안금주, level=0) referral_rewards 행이 이미 있으면 절대 재지급 안 함.
//     - dry_run=1 로 먼저 검증 후 dry_run=0 으로 실지급.
//   경로: POST /api/diag/backfill-direct-anguemju?key=ADMIN_PW&dry_run=1|0
app.post('/api/diag/backfill-direct-anguemju', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)

    const dryRun = c.req.query('dry_run') === '1'
    const db = c.env.DB

    const USD_TO_QKEY = 150
    const REFEREE_NAME = '안금주'   // 매출 발생자 (직접 하부)
    const REFERRER_NAME = '노학선'  // 직접판매수당 수령자 (직접 추천인)
    const LEVEL = 0                 // 직접판매(direct_referral)
    const REWARD_DATE = '2026-06-13'
    const PAID_DATE = '2026-06-13'

    // 1) 당사자 조회
    const referee = await db.prepare(`SELECT id, name, email, referrer_id FROM users WHERE name = ? LIMIT 1`).bind(REFEREE_NAME).first() as any
    const referrer = await db.prepare(`SELECT id, name, email, qkey_balance FROM users WHERE name = ? LIMIT 1`).bind(REFERRER_NAME).first() as any
    if (!referee) return c.json({ error: `referee '${REFEREE_NAME}' not found` }, 404)
    if (!referrer) return c.json({ error: `referrer '${REFERRER_NAME}' not found` }, 404)

    const audit: any = {
      referee: { id: referee.id, name: referee.name, email: referee.email, referrer_id: referee.referrer_id },
      referrer: { id: referrer.id, name: referrer.name, email: referrer.email, qkey_balance_before: referrer.qkey_balance },
      checks: {} as any,
      steps: [] as string[]
    }

    // 2) 무결성: 안금주의 referrer_id 가 실제로 노학선인지
    audit.checks.referrer_link_ok = Number(referee.referrer_id) === Number(referrer.id)
    if (!audit.checks.referrer_link_ok) {
      return c.json({ error: 'referrer link mismatch', audit }, 400)
    }

    // 3) 안금주의 매출(staking) 조회 — 직접판매 산정 기준 원금
    const refereeStaking = await db.prepare(`
      SELECT id, amount, status, start_date, end_date
      FROM staking
      WHERE user_id = ? AND status IN ('active','completed','capped')
      ORDER BY id ASC
    `).bind(referee.id).all()
    const stakingRows = (refereeStaking.results || []) as any[]
    audit.checks.referee_stakings = stakingRows.map(s => ({ id: s.id, amount: s.amount, status: s.status }))
    const originalAmount = stakingRows.reduce((sum, s) => sum + Number(s.amount || 0), 0)
    if (originalAmount <= 0) {
      return c.json({ error: 'referee has no eligible staking amount', audit }, 400)
    }
    audit.checks.original_amount_usd = originalAmount

    // 4) 기대 직접판매수당
    const directBonusQkey = Math.round(originalAmount * 0.10 * USD_TO_QKEY)
    audit.checks.expected_direct_qkey = directBonusQkey

    // 5) EXISTS guard — 이미 (노학선, 안금주, level=0) 직접판매 행이 있으면 차단
    const rrExists = await db.prepare(`
      SELECT id, reward_amount, reward_date FROM referral_rewards
      WHERE referrer_id = ? AND referee_id = ? AND level = 0
      LIMIT 1
    `).bind(referrer.id, referee.id).first() as any
    audit.checks.referral_reward_exists = rrExists ? { id: rrExists.id, reward_amount: rrExists.reward_amount, reward_date: rrExists.reward_date } : null

    if (rrExists) {
      audit.skip_reason = 'already_paid (referral_rewards level=0 exists)'
      return c.json({ success: true, dry_run: dryRun, action: 'skip', audit }, 200)
    }

    // 6) 지급 실행 (또는 dry-run)
    if (dryRun) {
      audit.steps.push(`[DRY] would UPDATE users(#${referrer.id}) qkey_balance += ${directBonusQkey}`)
      audit.steps.push(`[DRY] would INSERT referral_rewards(referrer=${referrer.id}, referee=${referee.id}, level=0, original=${originalAmount}, reward=${directBonusQkey}, date=${REWARD_DATE})`)
      audit.steps.push(`[DRY] would INSERT transactions(type='direct_referral', amount=${directBonusQkey}, ref_id=<rr_id>)`)
      return c.json({ success: true, dry_run: true, action: 'would_pay', pay_qkey: directBonusQkey, audit })
    }

    // 잔액 증가
    await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(directBonusQkey, referrer.id).run()

    // referral_rewards 먼저 INSERT → last_row_id 캡처 (승인 핸들러와 동일 스키마/패턴)
    const rrIns = await db.prepare(`
      INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date)
      VALUES (?, ?, 0, ?, ?, ?, ?)
    `).bind(referrer.id, referee.id, originalAmount, directBonusQkey, REWARD_DATE, PAID_DATE).run()
    const rrId = (rrIns as any)?.meta?.last_row_id ?? null
    audit.steps.push(`INSERT referral_rewards id=${rrId}`)

    // transactions ref_id 1:1 매핑 가드
    const txExists = await db.prepare(`
      SELECT id FROM transactions WHERE type = 'direct_referral' AND ref_id = ? LIMIT 1
    `).bind(rrId).first()
    if (!txExists) {
      await db.prepare(`
        INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
        VALUES (?, 'direct_referral', 'QKEY', ?, ?, ?)
      `).bind(referrer.id, directBonusQkey, '직접 추천 보너스', rrId).run()
      audit.steps.push(`INSERT transactions(direct_referral) ref_id=${rrId}`)
    } else {
      audit.steps.push(`transactions already exists for ref_id=${rrId} (skip tx insert)`)
    }

    const after = await db.prepare(`SELECT qkey_balance FROM users WHERE id = ?`).bind(referrer.id).first() as any
    audit.referrer.qkey_balance_after = after?.qkey_balance

    return c.json({
      success: true,
      dry_run: false,
      action: 'paid',
      referral_reward_id: rrId,
      pay_qkey: directBonusQkey,
      audit
    })
  } catch (error) {
    console.error('backfill-direct-anguemju error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ 직접판매수당 누락 백필 — 안금주(referee) → 노학선(referrer) (2026-06-16 보스 지시) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   현상: 안금주(108) 가입/스테이킹 승인(2026-06-13) 시 직접 추천인 노학선(101)에게
//          직접판매수당(매출 1,000 USD × 10% × 150 = 15,000 QKEY)이 지급되지 않음.
//   비교: 같은 날 오주석(110)/이두형(111) 매출 → 직접 추천인 안금주(108)에게 각 15,000 QKEY 정상 지급됨.
//          노학선 매출(1,000) → 빅뱅공에게 15,000 QKEY 정상 지급됨.
//          오직 안금주 매출에 대한 노학선 직접판매수당 1건만 누락.
//   원인: 스테이킹 승인 로직(직접추천수당)의 referrerActive 판정(start<=today<=end, KST)이
//          안금주 승인 시점에 노학선 스테이킹 active 조건을 만족하지 못해 스킵된 것으로 추정.
//   정책: 직접판매수당 = referee 매출 원금(USD) × 0.10 × 150(USD→QKEY) = 원금 × 15
//   처리: referral_rewards(level=0) + transactions(direct_referral) + users.qkey_balance 보정.
//          EXISTS 가드로 이중지급 절대 방지. ref_id 1:1 매핑. dry_run=1 지원.
//   경로: POST /api/diag/backfill-direct-anqueue-nohaksun?key=ADMIN_PW&dry_run=1|0
app.post('/api/diag/backfill-direct-anqueue-nohaksun', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)

    const dryRun = c.req.query('dry_run') === '1'
    const db = c.env.DB
    const USD_TO_QKEY = 150

    // 대상: referee=안금주, referrer=노학선 (이메일 고정 — 동명이인 방지)
    const REFEREE_EMAIL = 'an5798'   // 안금주
    const REFERRER_EMAIL = 'nhs3636' // 노학선

    const referee = await db.prepare(`SELECT id, name, email, referrer_id FROM users WHERE email = ?`).bind(REFEREE_EMAIL).first() as any
    const referrer = await db.prepare(`SELECT id, name, email, qkey_balance FROM users WHERE email = ?`).bind(REFERRER_EMAIL).first() as any

    if (!referee) return c.json({ error: `referee not found (${REFEREE_EMAIL})` }, 404)
    if (!referrer) return c.json({ error: `referrer not found (${REFERRER_EMAIL})` }, 404)

    const result: any = {
      dry_run: dryRun,
      referee: { id: referee.id, name: referee.name, email: referee.email, referrer_id: referee.referrer_id },
      referrer: { id: referrer.id, name: referrer.name, email: referrer.email, qkey_balance_before: referrer.qkey_balance },
      steps: [] as string[]
    }

    // 무결성 검증: referee.referrer_id 가 실제로 referrer.id 인지 확인 (구조 보장)
    if (Number(referee.referrer_id) !== Number(referrer.id)) {
      result.error = `구조 불일치: 안금주.referrer_id(${referee.referrer_id}) != 노학선.id(${referrer.id}). 백필 중단.`
      return c.json(result, 409)
    }

    // referee 의 매출 원금 산출 — 직접판매수당 미지급분 대상 staking (승인된 것)
    const refereeStakes = await db.prepare(`
      SELECT id, amount, status, start_date, end_date
      FROM staking
      WHERE user_id = ? AND status IN ('active','completed','capped')
      ORDER BY id ASC
    `).bind(referee.id).all()
    const stakeRows = (refereeStakes.results || []) as any[]
    result.referee_stakes = stakeRows.map(s => ({ id: s.id, amount: s.amount, status: s.status }))

    const totalAmount = stakeRows.reduce((sum, s) => sum + Number(s.amount || 0), 0)
    result.referee_total_amount_usd = totalAmount

    if (totalAmount <= 0) {
      result.error = 'referee 매출 원금 0 — 백필 대상 없음'
      return c.json(result, 409)
    }

    // EXISTS 가드 — 이미 level=0(직접판매) referral_rewards 가 (노학선←안금주) 로 존재하면 차단
    const existsRr = await db.prepare(`
      SELECT id, reward_amount, reward_date FROM referral_rewards
      WHERE referrer_id = ? AND referee_id = ? AND level = 0
      LIMIT 1
    `).bind(referrer.id, referee.id).first() as any
    if (existsRr) {
      result.skip_reason = 'already_exists'
      result.existing_referral_reward = { id: existsRr.id, reward_amount: existsRr.reward_amount, reward_date: existsRr.reward_date }
      result.steps.push(`EXISTS guard hit — referral_rewards(level=0, 노학선←안금주) id=${existsRr.id} 이미 존재. 백필 스킵.`)
      return c.json(result)
    }

    const directBonusUsd = totalAmount * 0.10
    const directBonusQkey = Math.round(directBonusUsd * USD_TO_QKEY) // = 원금 × 15
    result.direct_bonus_usd = directBonusUsd
    result.direct_bonus_qkey = directBonusQkey

    // reward_date / paid_date — 매출 발생일(안금주 staking 시작/승인일) 기준. 데이터상 2026-06-13.
    const REWARD_DATE = '2026-06-13'
    const PAID_DATE = '2026-06-13'
    result.reward_date = REWARD_DATE
    result.paid_date = PAID_DATE

    if (dryRun) {
      result.steps.push(`[DRY] would INSERT referral_rewards(level=0, 노학선#${referrer.id}←안금주#${referee.id}, ${directBonusQkey} QKEY)`)
      result.steps.push(`[DRY] would INSERT transactions(direct_referral, user#${referrer.id}, ${directBonusQkey} QKEY)`)
      result.steps.push(`[DRY] would UPDATE users SET qkey_balance += ${directBonusQkey} WHERE id=${referrer.id}`)
      result.referrer.qkey_balance_after = Number(referrer.qkey_balance) + directBonusQkey
      return c.json(result)
    }

    // 실지급 — referral_rewards 먼저 INSERT 후 last_row_id 캡처 (ref_id 1:1 매핑)
    const rrIns = await db.prepare(`
      INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date)
      VALUES (?, ?, 0, ?, ?, ?, ?)
    `).bind(referrer.id, referee.id, totalAmount, directBonusQkey, REWARD_DATE, PAID_DATE).run()
    const rrId = (rrIns as any)?.meta?.last_row_id ?? null
    result.referral_reward_id = rrId
    result.steps.push(`INSERT referral_rewards id=${rrId} (level=0, ${directBonusQkey} QKEY)`)

    // transactions(direct_referral) — EXISTS 가드 (ref_id 1:1)
    const dirTxExists = await db.prepare(`
      SELECT id FROM transactions WHERE type = 'direct_referral' AND ref_id = ? LIMIT 1
    `).bind(rrId).first()
    if (!dirTxExists) {
      await db.prepare(`
        INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
        VALUES (?, 'direct_referral', 'QKEY', ?, ?, ?)
      `).bind(referrer.id, directBonusQkey, '직접 추천 보너스 (백필 2026-06-16)', rrId).run()
      result.steps.push(`INSERT transactions(direct_referral) ref_id=${rrId}, ${directBonusQkey} QKEY`)
    } else {
      result.steps.push(`transactions(direct_referral) ref_id=${rrId} 이미 존재 — tx INSERT 스킵`)
    }

    // qkey_balance 보정
    await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(directBonusQkey, referrer.id).run()
    const after = await db.prepare(`SELECT qkey_balance FROM users WHERE id = ?`).bind(referrer.id).first() as any
    result.referrer.qkey_balance_after = after?.qkey_balance
    result.steps.push(`UPDATE users qkey_balance: ${referrer.qkey_balance} -> ${after?.qkey_balance} (+${directBonusQkey})`)

    result.success = true
    return c.json(result)
  } catch (error) {
    console.error('backfill-direct-anqueue-nohaksun error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ 5/4 백필 정밀 원상복구 (사장님 2026-05-15 긴급 지시 — 중복지급 발생, 즉시 원위치) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   사장님 원문: "휴일매출자들 수당지급을 수정해달라고 하니 기존매출자 매출이 중복으로 되었어
//                  중복으로 된 부분 전부 원래 수정전으로 전산 원위치"
//
//   복구 fingerprint (백필 endpoint /api/diag/backfill-may04-missing 가 INSERT 한 것만 정확히 식별):
//     1) daily_rewards: reward_date='2026-05-04' AND paid_date='2026-05-04'
//                       AND staking_id IN (44,45,46,47,48,49,53,54,56,57,58,59,60,61,62,63,64,65)
//     2) transactions:  type='daily_qkey' AND ref_id IN (위 dr_id)
//     3) referral_rewards: reward_date='2026-05-04' AND paid_date='2026-05-04'
//                          AND referee_id IN (백필 대상 staking 들의 user_id)
//                          ※ 사전조건: 백필 외에는 5/4 reward_date + 5/4 paid_date 인 referral_rewards 가 존재해서는 안 됨
//                          ※ 안전을 위해 referee_id IN (백필 user_id) AND reward_date='2026-05-04' AND paid_date='2026-05-04' 까지 추가 제한
//     4) transactions:  type='referral_reward' AND ref_id IN (위 rr_id)
//     5) users.qkey_balance: 차감 (각 INSERT 시 가산했던 amount 정확히 reverse)
//
//   안전장치:
//     - dry_run=1 기본 (실행은 confirm=GO 명시 필요)
//     - 각 행 삭제 전 fingerprint 재검증 (reward_date/paid_date/staking_id 모두 일치할 때만 처리)
//     - 200% cap / 5/6 정상 cron 행 / 4/30 데이터 등 PREEXIST 데이터에는 절대 손대지 않음
//     - 모든 작업은 동일 트랜잭션 단위 (실패 시 부분 적용 방지 — D1 batch 사용)
//
//   경로: POST /api/diag/revert-backfill-may04?key=ADMIN_PW&dry_run=1   (조회만)
//         POST /api/diag/revert-backfill-may04?key=ADMIN_PW&confirm=GO  (실제 실행)
app.post('/api/diag/revert-backfill-may04', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)

    const confirm = c.req.query('confirm') === 'GO'
    const dryRun = !confirm
    const db = c.env.DB

    // 백필 endpoint 가 사용한 정확한 target staking IDs (line 8608)
    const BACKFILL_STAKING_IDS = [44, 45, 46, 47, 48, 49, 53, 54, 56, 57, 58, 59, 60, 61, 62, 63, 64, 65]
    const REWARD_DATE = '2026-05-04'
    const PAID_DATE = '2026-05-04'

    // ============================================================
    // STEP 1: daily_rewards 백필 행 정확 식별
    // ============================================================
    // fingerprint: reward_date=5/4 AND paid_date=5/4 AND staking_id IN (백필 18건)
    const drPlaceholders = BACKFILL_STAKING_IDS.map(() => '?').join(',')
    const drRows = await db.prepare(`
      SELECT dr.id as dr_id, dr.user_id, dr.staking_id, dr.usdt_amount as qkey_amount,
             dr.reward_date, dr.paid_date,
             u.email as user_email, u.name as user_name
      FROM daily_rewards dr
      LEFT JOIN users u ON u.id = dr.user_id
      WHERE dr.reward_date = ? AND dr.paid_date = ?
        AND dr.staking_id IN (${drPlaceholders})
      ORDER BY dr.id ASC
    `).bind(REWARD_DATE, PAID_DATE, ...BACKFILL_STAKING_IDS).all() as any
    const dailyRowsToRevert = drRows?.results || []

    // 각 daily_rewards 의 mirror transaction (daily_qkey) 식별
    const dailyTxRows: any[] = []
    for (const dr of dailyRowsToRevert) {
      const tx = await db.prepare(`
        SELECT id, user_id, amount, description, created_at
        FROM transactions WHERE type = 'daily_qkey' AND ref_id = ? LIMIT 1
      `).bind(dr.dr_id).first() as any
      if (tx) dailyTxRows.push({ ...tx, dr_id: dr.dr_id })
    }

    // ============================================================
    // STEP 2: referral_rewards 백필 행 정확 식별
    // ============================================================
    // fingerprint: reward_date=5/4 AND paid_date=5/4 AND referee_id IN (백필 user_id 목록)
    //   ※ 백필 endpoint 는 referee_id 가 staking 의 user_id 임 (line 8758, 8807)
    const backfillUserIds = Array.from(new Set(dailyRowsToRevert.map((r: any) => r.user_id)))
    let rrL1Rows: any[] = []
    let rrL2Rows: any[] = []
    if (backfillUserIds.length > 0) {
      const rrPlaceholders = backfillUserIds.map(() => '?').join(',')
      const rrL1 = await db.prepare(`
        SELECT rr.id as rr_id, rr.referrer_id, rr.referee_id, rr.level, rr.reward_amount,
               rr.reward_date, rr.paid_date,
               u.email as referrer_email, u.name as referrer_name
        FROM referral_rewards rr
        LEFT JOIN users u ON u.id = rr.referrer_id
        WHERE rr.reward_date = ? AND rr.paid_date = ? AND rr.level = 1
          AND rr.referee_id IN (${rrPlaceholders})
        ORDER BY rr.id ASC
      `).bind(REWARD_DATE, PAID_DATE, ...backfillUserIds).all() as any
      rrL1Rows = rrL1?.results || []

      const rrL2 = await db.prepare(`
        SELECT rr.id as rr_id, rr.referrer_id, rr.referee_id, rr.level, rr.reward_amount,
               rr.reward_date, rr.paid_date,
               u.email as referrer_email, u.name as referrer_name
        FROM referral_rewards rr
        LEFT JOIN users u ON u.id = rr.referrer_id
        WHERE rr.reward_date = ? AND rr.paid_date = ? AND rr.level = 2
          AND rr.referee_id IN (${rrPlaceholders})
        ORDER BY rr.id ASC
      `).bind(REWARD_DATE, PAID_DATE, ...backfillUserIds).all() as any
      rrL2Rows = rrL2?.results || []
    }

    // 각 referral_rewards 의 mirror transaction (referral_reward) 식별
    const referralTxRows: any[] = []
    for (const rr of [...rrL1Rows, ...rrL2Rows]) {
      const tx = await db.prepare(`
        SELECT id, user_id, amount, description, created_at
        FROM transactions WHERE type = 'referral_reward' AND ref_id = ? LIMIT 1
      `).bind(rr.rr_id).first() as any
      if (tx) referralTxRows.push({ ...tx, rr_id: rr.rr_id, level: rr.level })
    }

    // ============================================================
    // STEP 3: 합산 (검증용)
    // ============================================================
    const totalDailyQkey = dailyRowsToRevert.reduce((s: number, r: any) => s + Number(r.qkey_amount || 0), 0)
    const totalL1Qkey = rrL1Rows.reduce((s: number, r: any) => s + Number(r.reward_amount || 0), 0)
    const totalL2Qkey = rrL2Rows.reduce((s: number, r: any) => s + Number(r.reward_amount || 0), 0)
    const grandTotal = totalDailyQkey + totalL1Qkey + totalL2Qkey

    // ============================================================
    // STEP 4: 사용자별 잔액 차감 계획 (qkey_balance)
    // ============================================================
    const balanceDeltas: Record<number, { daily: number, l1: number, l2: number, total: number }> = {}
    for (const dr of dailyRowsToRevert) {
      const uid = Number(dr.user_id)
      if (!balanceDeltas[uid]) balanceDeltas[uid] = { daily: 0, l1: 0, l2: 0, total: 0 }
      balanceDeltas[uid].daily += Number(dr.qkey_amount || 0)
      balanceDeltas[uid].total += Number(dr.qkey_amount || 0)
    }
    for (const rr of rrL1Rows) {
      const uid = Number(rr.referrer_id)
      if (!balanceDeltas[uid]) balanceDeltas[uid] = { daily: 0, l1: 0, l2: 0, total: 0 }
      balanceDeltas[uid].l1 += Number(rr.reward_amount || 0)
      balanceDeltas[uid].total += Number(rr.reward_amount || 0)
    }
    for (const rr of rrL2Rows) {
      const uid = Number(rr.referrer_id)
      if (!balanceDeltas[uid]) balanceDeltas[uid] = { daily: 0, l1: 0, l2: 0, total: 0 }
      balanceDeltas[uid].l2 += Number(rr.reward_amount || 0)
      balanceDeltas[uid].total += Number(rr.reward_amount || 0)
    }

    // ============================================================
    // STEP 5: DRY_RUN 이면 여기서 조회 결과만 반환
    // ============================================================
    if (dryRun) {
      return c.json({
        success: true,
        mode: 'DRY_RUN',
        message: '실제 실행을 원하시면 confirm=GO 파라미터를 추가하세요',
        fingerprint: {
          reward_date: REWARD_DATE,
          paid_date: PAID_DATE,
          target_staking_ids: BACKFILL_STAKING_IDS
        },
        plan: {
          daily_rewards_to_delete: dailyRowsToRevert.length,
          daily_transactions_to_delete: dailyTxRows.length,
          referral_rewards_l1_to_delete: rrL1Rows.length,
          referral_rewards_l2_to_delete: rrL2Rows.length,
          referral_transactions_to_delete: referralTxRows.length,
          total_daily_qkey_to_revert: totalDailyQkey,
          total_l1_qkey_to_revert: totalL1Qkey,
          total_l2_qkey_to_revert: totalL2Qkey,
          grand_total_qkey_to_revert: grandTotal,
          affected_users: Object.keys(balanceDeltas).length
        },
        daily_rewards: dailyRowsToRevert,
        daily_transactions: dailyTxRows,
        referral_rewards_l1: rrL1Rows,
        referral_rewards_l2: rrL2Rows,
        referral_transactions: referralTxRows,
        balance_deltas: balanceDeltas
      })
    }

    // ============================================================
    // STEP 6: 실제 실행 (confirm=GO)
    // ============================================================
    const executed: any = {
      daily_transactions_deleted: 0,
      daily_rewards_deleted: 0,
      referral_transactions_deleted: 0,
      referral_rewards_deleted: 0,
      users_balance_updated: 0
    }

    // 6-1: daily_qkey transactions 삭제 (mirror 먼저)
    for (const tx of dailyTxRows) {
      const r = await db.prepare(`DELETE FROM transactions WHERE id = ? AND type = 'daily_qkey'`).bind(tx.id).run()
      if ((r as any)?.meta?.changes > 0) executed.daily_transactions_deleted++
    }

    // 6-2: referral_reward transactions 삭제 (mirror 먼저)
    for (const tx of referralTxRows) {
      const r = await db.prepare(`DELETE FROM transactions WHERE id = ? AND type = 'referral_reward'`).bind(tx.id).run()
      if ((r as any)?.meta?.changes > 0) executed.referral_transactions_deleted++
    }

    // 6-3: referral_rewards 삭제 (L1 + L2)
    for (const rr of [...rrL1Rows, ...rrL2Rows]) {
      const r = await db.prepare(`
        DELETE FROM referral_rewards
        WHERE id = ? AND reward_date = ? AND paid_date = ?
      `).bind(rr.rr_id, REWARD_DATE, PAID_DATE).run()
      if ((r as any)?.meta?.changes > 0) executed.referral_rewards_deleted++
    }

    // 6-4: daily_rewards 삭제
    for (const dr of dailyRowsToRevert) {
      const r = await db.prepare(`
        DELETE FROM daily_rewards
        WHERE id = ? AND reward_date = ? AND paid_date = ?
      `).bind(dr.dr_id, REWARD_DATE, PAID_DATE).run()
      if ((r as any)?.meta?.changes > 0) executed.daily_rewards_deleted++
    }

    // 6-5: users.qkey_balance 차감
    for (const [uid, delta] of Object.entries(balanceDeltas)) {
      const amount = delta.total
      if (amount > 0) {
        const r = await db.prepare(`UPDATE users SET qkey_balance = qkey_balance - ? WHERE id = ?`).bind(amount, Number(uid)).run()
        if ((r as any)?.meta?.changes > 0) executed.users_balance_updated++
      }
    }

    return c.json({
      success: true,
      mode: 'EXECUTED',
      fingerprint: {
        reward_date: REWARD_DATE,
        paid_date: PAID_DATE,
        target_staking_ids: BACKFILL_STAKING_IDS
      },
      executed,
      total_qkey_reverted: grandTotal,
      total_daily_qkey_reverted: totalDailyQkey,
      total_l1_qkey_reverted: totalL1Qkey,
      total_l2_qkey_reverted: totalL2Qkey,
      balance_deltas: balanceDeltas
    })
  } catch (error) {
    console.error('revert-backfill-may04 error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ 5/4 본인 데일리만 정밀 백필 (사장님 2026-05-15 C옵션 선택 1 결재) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   사장님 결재 (2026-05-15):
//     - 휴일진입자(5/3 일요일 진입) 18건의 첫 평일(5/4) 본인 데일리 1일치만 보정
//     - L1/L2 매칭 INSERT 는 0건 (referrer 들은 이미 5/6 cron 에서 첫 매칭을 받았으므로,
//       5/4 분 매칭을 또 INSERT 하면 "수정 대상이 아닌 기존 회원 매출 중복" 재발 → 절대 금지)
//
//   대상 staking_id: [44, 45, 46, 47, 48, 49, 53, 54, 56, 57, 58, 59, 60, 61, 62, 63, 64, 65]
//   reward_date='2026-05-04', paid_date='2026-05-04'
//   처리량: 본인 데일리 18 × 750 = 13,500 QKEY (매칭 INSERT 0건)
//
//   안전장치:
//     - dry_run=1 기본 (실행은 confirm=GO 명시 필요)
//     - daily_rewards (user, staking, reward_date) EXISTS 가드 (재실행 안전)
//     - 200% cap 검증 (영구룰)
//     - description 영구룰 '일일 배당 (QKEY)' 사용
//     - transactions mirror INSERT 시 (type, ref_id) UNIQUE 가드
//
//   경로: POST /api/diag/backfill-may04-self-only?key=ADMIN_PW&dry_run=1   (조회)
//         POST /api/diag/backfill-may04-self-only?key=ADMIN_PW&confirm=GO  (실행)
app.post('/api/diag/backfill-may04-self-only', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)

    const confirm = c.req.query('confirm') === 'GO'
    const dryRun = !confirm
    const db = c.env.DB

    const TARGET_STAKING_IDS = [44, 45, 46, 47, 48, 49, 53, 54, 56, 57, 58, 59, 60, 61, 62, 63, 64, 65]
    const REWARD_DATE = '2026-05-04'
    const PAID_DATE = '2026-05-04'
    const USD_TO_QKEY = 150

    // 200% cap 검증 함수
    async function isUserCapped(userId: number): Promise<{ capped: boolean, paidTotal: number, target: number }> {
      const stakeRow = await db.prepare(`
        SELECT COALESCE(SUM(amount), 0) as total
        FROM staking WHERE user_id = ? AND status IN ('active','completed','capped')
      `).bind(userId).first() as any
      const stakeTotal = Number(stakeRow?.total || 0)
      if (stakeTotal <= 0) return { capped: false, paidTotal: 0, target: 0 }
      const paidRow = await db.prepare(`
        SELECT COALESCE(SUM(amount), 0) as total
        FROM transactions
        WHERE user_id = ? AND coin_type = 'QKEY'
          AND type IN ('daily_qkey', 'referral_reward')
      `).bind(userId).first() as any
      const paidTotal = Number(paidRow?.total || 0)
      const target = stakeTotal * 2 * USD_TO_QKEY
      return { capped: paidTotal >= target, paidTotal, target }
    }

    const asOf = new Date('2026-05-04T00:00:00+09:00')
    const results: any[] = []
    let insertedCount = 0
    let skippedCount = 0
    let totalDailyQkey = 0

    for (const stakingId of TARGET_STAKING_IDS) {
      const row: any = { staking_id: stakingId, dry_run: dryRun, steps: [] as string[] }

      const staking = await db.prepare(`
        SELECT s.id as staking_id, s.user_id, s.amount, s.daily_rate, s.status,
               s.start_date, s.end_date,
               u.email as user_email, u.name as user_name
        FROM staking s
        LEFT JOIN users u ON u.id = s.user_id
        WHERE s.id = ?
      `).bind(stakingId).first() as any

      if (!staking) {
        row.error = 'staking not found'
        results.push(row); skippedCount++; continue
      }
      row.user_id = staking.user_id
      row.user_email = staking.user_email
      row.user_name = staking.user_name
      row.amount = staking.amount

      // EXISTS guard — daily_rewards (user, staking, reward_date) 이미 있으면 skip
      const exists = await db.prepare(`
        SELECT COUNT(*) as count FROM daily_rewards
        WHERE user_id = ? AND staking_id = ? AND reward_date = ?
      `).bind(staking.user_id, stakingId, REWARD_DATE).first() as any
      if ((exists?.count || 0) > 0) {
        row.skip_reason = 'already_exists'
        row.steps.push('EXISTS guard hit — daily_rewards 이미 존재')
        results.push(row); skippedCount++; continue
      }

      // 200% cap 검증
      const capState = await isUserCapped(staking.user_id as number)
      row.cap_state = { capped: capState.capped, paid_total: capState.paidTotal, target: capState.target }
      if (capState.capped) {
        row.skip_reason = 'user_capped_200pct'
        row.steps.push('200% cap 도달 — daily skip')
        results.push(row); skippedCount++; continue
      }

      // 본인 데일리 금액 계산
      const dailyRate = staking.daily_rate || getDailyRate(staking.amount, asOf)
      const usdAmount = staking.amount * dailyRate
      let qkeyAmount = Math.round(usdAmount * USD_TO_QKEY)
      const remaining = capState.target - capState.paidTotal
      if (qkeyAmount > remaining) {
        qkeyAmount = Math.max(0, Math.floor(remaining))
        row.steps.push(`partial payment (cap remaining=${remaining})`)
      }
      if (qkeyAmount <= 0) {
        row.skip_reason = 'qkey_amount_zero'
        results.push(row); skippedCount++; continue
      }

      row.daily_rate = dailyRate
      row.qkey_amount = qkeyAmount

      if (dryRun) {
        row.steps.push(`[DRY] would INSERT daily_rewards + transactions (${qkeyAmount} QKEY)`)
        row.steps.push(`[DRY] L1/L2 매칭 INSERT 는 0건 (선택 1 정책 — referrer 5/6 분 매칭 있어 중복 방지)`)
        totalDailyQkey += qkeyAmount
      } else {
        // 1) daily_rewards INSERT
        const drIns = await db.prepare(`
          INSERT INTO daily_rewards (user_id, staking_id, usdt_amount, reward_date, paid_date)
          VALUES (?, ?, ?, ?, ?)
        `).bind(staking.user_id, stakingId, qkeyAmount, REWARD_DATE, PAID_DATE).run()
        const drId = (drIns as any)?.meta?.last_row_id ?? null
        row.dr_id = drId

        // 2) qkey_balance 가산
        await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(qkeyAmount, staking.user_id).run()

        // 3) transactions mirror INSERT
        const dqExists = await db.prepare(`SELECT id FROM transactions WHERE type = 'daily_qkey' AND ref_id = ? LIMIT 1`).bind(drId).first()
        if (!dqExists) {
          await db.prepare(`
            INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
            VALUES (?, 'daily_qkey', 'QKEY', ?, ?, ?)
          `).bind(staking.user_id, qkeyAmount, '일일 배당 (QKEY)', drId).run()
        }

        row.steps.push(`INSERT daily_rewards id=${drId}, ${qkeyAmount} QKEY, balance updated`)
        row.steps.push(`L1/L2 매칭 INSERT 0건 (선택 1 정책)`)
        insertedCount++
        totalDailyQkey += qkeyAmount
      }

      results.push(row)
    }

    return c.json({
      success: true,
      mode: dryRun ? 'DRY_RUN' : 'EXECUTED',
      policy: '선택 1 — 본인 데일리만 INSERT, L1/L2 매칭 0건 (referrer 5/6 매칭 중복 방지)',
      reward_date: REWARD_DATE,
      paid_date: PAID_DATE,
      target_staking_ids: TARGET_STAKING_IDS,
      summary: {
        inserted_count: insertedCount,
        skipped_count: skippedCount,
        total_daily_qkey: totalDailyQkey,
        total_l1_qkey: 0,
        total_l2_qkey: 0,
        grand_total_qkey: totalDailyQkey
      },
      results
    })
  } catch (error) {
    console.error('backfill-may04-self-only error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ 기존 사업자 중복 지급 전수 진단 (사장님 2026-05-15 긴급 지시 — 중요한 문제) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   사장님 원문: "기존사업자들중 중복으로 지급된 배당금 전부 원위치로 다시 수정해줘 이건 중요한 문제야"
//
//   진단 대상 — 같은 키 조합이 2건 이상 존재하면 중복:
//     1) daily_rewards: (user_id, staking_id, reward_date) GROUP BY 후 COUNT > 1
//     2) referral_rewards: (referrer_id, referee_id, level, reward_date) GROUP BY 후 COUNT > 1
//     3) transactions: (type, ref_id) GROUP BY 후 COUNT > 1 (mirror 중복)
//
//   각 중복의 잔액 영향:
//     - 첫 행 (가장 작은 id) = KEEP, 나머지 = DUPLICATE 로 분류
//     - 중복 row 의 amount 만큼 qkey_balance 가 과다 가산된 상태
//
//   경로: GET /api/diag/audit-duplicate-rewards?key=ADMIN_PW
app.get('/api/diag/audit-duplicate-rewards', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB

    // ============================================================
    // 1) daily_rewards 중복 — 같은 (user_id, staking_id, reward_date) 가 2건 이상
    // ============================================================
    const drDup = await db.prepare(`
      SELECT user_id, staking_id, reward_date,
             COUNT(*) as cnt,
             GROUP_CONCAT(id, ',') as ids,
             SUM(usdt_amount) as sum_qkey,
             MIN(id) as keep_id,
             MIN(usdt_amount) as keep_amount
      FROM daily_rewards
      GROUP BY user_id, staking_id, reward_date
      HAVING COUNT(*) > 1
      ORDER BY user_id, staking_id, reward_date
    `).all() as any
    const drDupRows = drDup?.results || []

    // 각 중복의 상세 행 조회 (어떤 id 가 keep / 어떤 id 가 dup 인지 명시)
    const drDupDetails: any[] = []
    let drDupTotalExcess = 0
    for (const g of drDupRows) {
      const allRows = await db.prepare(`
        SELECT id, user_id, staking_id, reward_date, paid_date, usdt_amount, created_at
        FROM daily_rewards
        WHERE user_id = ? AND staking_id = ? AND reward_date = ?
        ORDER BY id ASC
      `).bind(g.user_id, g.staking_id, g.reward_date).all() as any
      const rows = allRows?.results || []
      const keep = rows[0]
      const dups = rows.slice(1)
      const excessSum = dups.reduce((s: number, r: any) => s + Number(r.usdt_amount || 0), 0)
      drDupTotalExcess += excessSum
      drDupDetails.push({
        user_id: g.user_id,
        staking_id: g.staking_id,
        reward_date: g.reward_date,
        cnt: g.cnt,
        keep: keep,
        duplicates: dups,
        excess_qkey: excessSum
      })
    }

    // ============================================================
    // 2) referral_rewards 중복 — 같은 (referrer_id, referee_id, level, reward_date) 가 2건 이상
    // ============================================================
    const rrDup = await db.prepare(`
      SELECT referrer_id, referee_id, level, reward_date,
             COUNT(*) as cnt,
             GROUP_CONCAT(id, ',') as ids,
             SUM(reward_amount) as sum_qkey,
             MIN(id) as keep_id
      FROM referral_rewards
      GROUP BY referrer_id, referee_id, level, reward_date
      HAVING COUNT(*) > 1
      ORDER BY referrer_id, reward_date, level
    `).all() as any
    const rrDupRows = rrDup?.results || []

    const rrDupDetails: any[] = []
    let rrDupTotalExcess = 0
    for (const g of rrDupRows) {
      const allRows = await db.prepare(`
        SELECT id, referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, created_at
        FROM referral_rewards
        WHERE referrer_id = ? AND referee_id = ? AND level = ? AND reward_date = ?
        ORDER BY id ASC
      `).bind(g.referrer_id, g.referee_id, g.level, g.reward_date).all() as any
      const rows = allRows?.results || []
      const keep = rows[0]
      const dups = rows.slice(1)
      const excessSum = dups.reduce((s: number, r: any) => s + Number(r.reward_amount || 0), 0)
      rrDupTotalExcess += excessSum

      // referrer 이름 조회
      const referrer = await db.prepare(`SELECT id, email, name FROM users WHERE id = ?`).bind(g.referrer_id).first() as any
      const referee = await db.prepare(`SELECT id, email, name FROM users WHERE id = ?`).bind(g.referee_id).first() as any
      rrDupDetails.push({
        referrer_id: g.referrer_id,
        referrer_name: referrer?.name || null,
        referrer_email: referrer?.email || null,
        referee_id: g.referee_id,
        referee_name: referee?.name || null,
        referee_email: referee?.email || null,
        level: g.level,
        reward_date: g.reward_date,
        cnt: g.cnt,
        keep: keep,
        duplicates: dups,
        excess_qkey: excessSum
      })
    }

    // ============================================================
    // 3) transactions mirror 중복 — 같은 (type, ref_id) 가 2건 이상
    //    daily_qkey / referral_reward 만 점검 (다른 type 은 ref_id 의미 다름)
    // ============================================================
    const txDup = await db.prepare(`
      SELECT type, ref_id,
             COUNT(*) as cnt,
             GROUP_CONCAT(id, ',') as ids,
             SUM(amount) as sum_qkey,
             MIN(id) as keep_id,
             MIN(user_id) as user_id
      FROM transactions
      WHERE type IN ('daily_qkey', 'referral_reward') AND ref_id IS NOT NULL
      GROUP BY type, ref_id
      HAVING COUNT(*) > 1
      ORDER BY type, ref_id
    `).all() as any
    const txDupRows = txDup?.results || []

    const txDupDetails: any[] = []
    let txDupTotalExcess = 0
    for (const g of txDupRows) {
      const allRows = await db.prepare(`
        SELECT id, user_id, type, coin_type, amount, description, ref_id, created_at
        FROM transactions
        WHERE type = ? AND ref_id = ?
        ORDER BY id ASC
      `).bind(g.type, g.ref_id).all() as any
      const rows = allRows?.results || []
      const keep = rows[0]
      const dups = rows.slice(1)
      const excessSum = dups.reduce((s: number, r: any) => s + Number(r.amount || 0), 0)
      txDupTotalExcess += excessSum
      txDupDetails.push({
        type: g.type,
        ref_id: g.ref_id,
        user_id: g.user_id,
        cnt: g.cnt,
        keep: keep,
        duplicates: dups,
        excess_qkey: excessSum
      })
    }

    // ============================================================
    // 4) 사용자별 잔액 과다 가산 영향 집계
    // ============================================================
    const userExcess: Record<number, { daily: number, l1: number, l2: number, total: number, name?: string, email?: string }> = {}

    for (const g of drDupDetails) {
      const uid = Number(g.user_id)
      if (!userExcess[uid]) userExcess[uid] = { daily: 0, l1: 0, l2: 0, total: 0 }
      userExcess[uid].daily += Number(g.excess_qkey || 0)
      userExcess[uid].total += Number(g.excess_qkey || 0)
    }
    for (const g of rrDupDetails) {
      const uid = Number(g.referrer_id)
      if (!userExcess[uid]) userExcess[uid] = { daily: 0, l1: 0, l2: 0, total: 0, name: g.referrer_name, email: g.referrer_email }
      else { userExcess[uid].name = userExcess[uid].name || g.referrer_name; userExcess[uid].email = userExcess[uid].email || g.referrer_email }
      if (Number(g.level) === 1) userExcess[uid].l1 += Number(g.excess_qkey || 0)
      else if (Number(g.level) === 2) userExcess[uid].l2 += Number(g.excess_qkey || 0)
      userExcess[uid].total += Number(g.excess_qkey || 0)
    }

    // 사용자 이름/이메일 보충
    for (const uidStr of Object.keys(userExcess)) {
      const uid = Number(uidStr)
      if (!userExcess[uid].name) {
        const u = await db.prepare(`SELECT name, email FROM users WHERE id = ?`).bind(uid).first() as any
        if (u) { userExcess[uid].name = u.name; userExcess[uid].email = u.email }
      }
    }

    return c.json({
      success: true,
      summary: {
        daily_rewards_duplicate_groups: drDupRows.length,
        daily_rewards_excess_qkey: drDupTotalExcess,
        referral_rewards_duplicate_groups: rrDupRows.length,
        referral_rewards_excess_qkey: rrDupTotalExcess,
        transactions_duplicate_groups: txDupRows.length,
        transactions_excess_qkey: txDupTotalExcess,
        affected_users: Object.keys(userExcess).length,
        total_balance_excess_qkey: Object.values(userExcess).reduce((s, v) => s + v.total, 0)
      },
      daily_rewards_duplicates: drDupDetails,
      referral_rewards_duplicates: rrDupDetails,
      transactions_duplicates: txDupDetails,
      user_balance_excess: userExcess
    })
  } catch (error) {
    console.error('audit-duplicate-rewards error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ 5/15 paid_date 를 5/14 와 1:1 동일하게 재구축 (사장님 2026-05-15 방식 A 결재) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   사장님 원문: "무조건 배당은 신규 진입자가 없으니 어제와 같아야 한다.
//                  중복이 또 발생했으니 흔적없이 지우고 어제와 각 계정별 동일 배당하라"
//
//   처리 절차:
//     STEP 1 — 5/15 paid_date 전체 WIPE (흔적 없이 제거):
//       a) transactions WHERE type='daily_qkey' AND ref_id IN (5/15 dr_id) DELETE
//       b) transactions WHERE type='referral_reward' AND ref_id IN (5/15 rr_id) DELETE
//       c) referral_rewards WHERE paid_date='2026-05-15' DELETE
//       d) daily_rewards WHERE paid_date='2026-05-15' DELETE
//       e) users.qkey_balance 차감 (각 row amount 만큼 reverse)
//
//     STEP 2 — 5/14 → 5/15 1:1 미러링 INSERT:
//       a) daily_rewards: 5/14 paid_date 행을 reward_date='2026-05-15', paid_date='2026-05-15' 로 복제
//       b) transactions (daily_qkey): 새 dr_id 로 mirror INSERT, description='일일 배당 (QKEY)'
//       c) referral_rewards: 5/14 paid_date 행을 reward_date='2026-05-15', paid_date='2026-05-15' 로 복제
//       d) transactions (referral_reward): 새 rr_id 로 mirror INSERT, description='추천 보너스 (Level 1/2)'
//       e) users.qkey_balance 가산 (복제된 amount 만큼)
//
//   안전장치:
//     - dry_run=1 기본 (실행은 confirm=GO 명시 필요)
//     - 5/15 paid_date 만 처리 (다른 날짜 절대 손대지 않음)
//     - description 영구룰 100% 준수
//     - 5/14 reward_date 가 아닌 paid_date 기준 (cron 실제 지급일)
//
//   경로: POST /api/diag/rebuild-may15-from-may14?key=ADMIN_PW&dry_run=1   (조회)
//         POST /api/diag/rebuild-may15-from-may14?key=ADMIN_PW&confirm=GO  (실행)
app.post('/api/diag/rebuild-may15-from-may14', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)

    const confirm = c.req.query('confirm') === 'GO'
    const dryRun = !confirm
    const db = c.env.DB

    const SRC_PAID_DATE = '2026-05-14'   // 원본 (어제)
    const DST_PAID_DATE = '2026-05-15'   // 대상 (오늘)
    const DST_REWARD_DATE = '2026-05-15' // 대상 reward_date

    // ============================================================
    // PHASE 0 — 사전 조회 (양쪽 데이터 스냅샷)
    // ============================================================
    // 5/14 daily_rewards 원본 (paid_date 기준)
    const srcDr = await db.prepare(`
      SELECT id, user_id, staking_id, usdt_amount, reward_date, paid_date
      FROM daily_rewards WHERE paid_date = ?
      ORDER BY id ASC
    `).bind(SRC_PAID_DATE).all() as any
    const srcDrRows = srcDr?.results || []

    // 5/14 referral_rewards 원본
    const srcRr = await db.prepare(`
      SELECT id, referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date
      FROM referral_rewards WHERE paid_date = ?
      ORDER BY id ASC
    `).bind(SRC_PAID_DATE).all() as any
    const srcRrRows = srcRr?.results || []

    // 5/15 daily_rewards 현재 (지울 대상)
    const dstDr = await db.prepare(`
      SELECT id, user_id, staking_id, usdt_amount, reward_date, paid_date
      FROM daily_rewards WHERE paid_date = ?
      ORDER BY id ASC
    `).bind(DST_PAID_DATE).all() as any
    const dstDrRows = dstDr?.results || []

    // 5/15 referral_rewards 현재 (지울 대상)
    const dstRr = await db.prepare(`
      SELECT id, referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date
      FROM referral_rewards WHERE paid_date = ?
      ORDER BY id ASC
    `).bind(DST_PAID_DATE).all() as any
    const dstRrRows = dstRr?.results || []

    // 5/15 transactions 현재 (지울 대상)
    const dstDrIds = dstDrRows.map((r: any) => Number(r.id))
    const dstRrIds = dstRrRows.map((r: any) => Number(r.id))

    let dstDailyTxRows: any[] = []
    if (dstDrIds.length > 0) {
      const placeholders = dstDrIds.map(() => '?').join(',')
      const r = await db.prepare(`
        SELECT id, user_id, type, amount, ref_id FROM transactions
        WHERE type = 'daily_qkey' AND ref_id IN (${placeholders})
      `).bind(...dstDrIds).all() as any
      dstDailyTxRows = r?.results || []
    }
    let dstRefTxRows: any[] = []
    if (dstRrIds.length > 0) {
      const placeholders = dstRrIds.map(() => '?').join(',')
      const r = await db.prepare(`
        SELECT id, user_id, type, amount, ref_id FROM transactions
        WHERE type = 'referral_reward' AND ref_id IN (${placeholders})
      `).bind(...dstRrIds).all() as any
      dstRefTxRows = r?.results || []
    }

    // ============================================================
    // PHASE 1 — 잔액 변동 계산
    // ============================================================
    // 5/15 wipe 시 사용자별 차감해야 할 잔액
    const wipeDeltas: Record<number, number> = {}
    for (const r of dstDrRows) {
      const uid = Number(r.user_id)
      wipeDeltas[uid] = (wipeDeltas[uid] || 0) + Number(r.usdt_amount || 0)
    }
    for (const r of dstRrRows) {
      const uid = Number(r.referrer_id)
      wipeDeltas[uid] = (wipeDeltas[uid] || 0) + Number(r.reward_amount || 0)
    }

    // 5/14 → 5/15 미러링 시 사용자별 가산할 잔액
    const insertDeltas: Record<number, number> = {}
    for (const r of srcDrRows) {
      const uid = Number(r.user_id)
      insertDeltas[uid] = (insertDeltas[uid] || 0) + Number(r.usdt_amount || 0)
    }
    for (const r of srcRrRows) {
      const uid = Number(r.referrer_id)
      insertDeltas[uid] = (insertDeltas[uid] || 0) + Number(r.reward_amount || 0)
    }

    // 순 변동 (insert - wipe)
    const netDeltas: Record<number, number> = {}
    const allUids = new Set<number>([...Object.keys(wipeDeltas).map(Number), ...Object.keys(insertDeltas).map(Number)])
    for (const uid of allUids) {
      const w = wipeDeltas[uid] || 0
      const i = insertDeltas[uid] || 0
      const net = i - w
      if (net !== 0) netDeltas[uid] = net
    }

    const wipeSummary = {
      daily_rewards_to_delete: dstDrRows.length,
      daily_rewards_qkey: dstDrRows.reduce((s: number, r: any) => s + Number(r.usdt_amount || 0), 0),
      referral_rewards_to_delete: dstRrRows.length,
      referral_rewards_qkey: dstRrRows.reduce((s: number, r: any) => s + Number(r.reward_amount || 0), 0),
      daily_transactions_to_delete: dstDailyTxRows.length,
      referral_transactions_to_delete: dstRefTxRows.length
    }
    const insertSummary = {
      daily_rewards_to_insert: srcDrRows.length,
      daily_rewards_qkey: srcDrRows.reduce((s: number, r: any) => s + Number(r.usdt_amount || 0), 0),
      referral_rewards_to_insert: srcRrRows.length,
      referral_rewards_qkey: srcRrRows.reduce((s: number, r: any) => s + Number(r.reward_amount || 0), 0)
    }

    // ============================================================
    // DRY_RUN — 계획만 반환
    // ============================================================
    if (dryRun) {
      return c.json({
        success: true,
        mode: 'DRY_RUN',
        message: '실제 실행을 원하시면 confirm=GO 파라미터를 추가하세요',
        src_paid_date: SRC_PAID_DATE,
        dst_paid_date: DST_PAID_DATE,
        wipe_plan: wipeSummary,
        insert_plan: insertSummary,
        balance_net_deltas: netDeltas,
        affected_users: allUids.size
      })
    }

    // ============================================================
    // PHASE 2 — 5/15 paid_date 전체 WIPE
    // ============================================================
    const executed: any = {
      daily_transactions_deleted: 0,
      referral_transactions_deleted: 0,
      referral_rewards_deleted: 0,
      daily_rewards_deleted: 0,
      balance_wipe_users: 0,
      daily_rewards_inserted: 0,
      daily_transactions_inserted: 0,
      referral_rewards_inserted: 0,
      referral_transactions_inserted: 0,
      balance_insert_users: 0
    }

    // 2-a) daily_qkey transactions 삭제
    for (const tx of dstDailyTxRows) {
      const r = await db.prepare(`DELETE FROM transactions WHERE id = ? AND type = 'daily_qkey'`).bind(tx.id).run()
      if ((r as any)?.meta?.changes > 0) executed.daily_transactions_deleted++
    }

    // 2-b) referral_reward transactions 삭제
    for (const tx of dstRefTxRows) {
      const r = await db.prepare(`DELETE FROM transactions WHERE id = ? AND type = 'referral_reward'`).bind(tx.id).run()
      if ((r as any)?.meta?.changes > 0) executed.referral_transactions_deleted++
    }

    // 2-c) referral_rewards 삭제
    for (const rr of dstRrRows) {
      const r = await db.prepare(`DELETE FROM referral_rewards WHERE id = ? AND paid_date = ?`).bind(rr.id, DST_PAID_DATE).run()
      if ((r as any)?.meta?.changes > 0) executed.referral_rewards_deleted++
    }

    // 2-d) daily_rewards 삭제
    for (const dr of dstDrRows) {
      const r = await db.prepare(`DELETE FROM daily_rewards WHERE id = ? AND paid_date = ?`).bind(dr.id, DST_PAID_DATE).run()
      if ((r as any)?.meta?.changes > 0) executed.daily_rewards_deleted++
    }

    // 2-e) qkey_balance 차감
    for (const [uid, amt] of Object.entries(wipeDeltas)) {
      if (amt > 0) {
        const r = await db.prepare(`UPDATE users SET qkey_balance = qkey_balance - ? WHERE id = ?`).bind(amt, Number(uid)).run()
        if ((r as any)?.meta?.changes > 0) executed.balance_wipe_users++
      }
    }

    // ============================================================
    // PHASE 3 — 5/14 → 5/15 1:1 미러링 INSERT
    // ============================================================
    // 3-a) daily_rewards 복제 + transactions mirror
    for (const src of srcDrRows) {
      const drIns = await db.prepare(`
        INSERT INTO daily_rewards (user_id, staking_id, usdt_amount, reward_date, paid_date)
        VALUES (?, ?, ?, ?, ?)
      `).bind(src.user_id, src.staking_id, src.usdt_amount, DST_REWARD_DATE, DST_PAID_DATE).run()
      const newDrId = (drIns as any)?.meta?.last_row_id ?? null
      if (newDrId) {
        executed.daily_rewards_inserted++
        // transactions mirror
        await db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
          VALUES (?, 'daily_qkey', 'QKEY', ?, ?, ?)
        `).bind(src.user_id, src.usdt_amount, '일일 배당 (QKEY)', newDrId).run()
        executed.daily_transactions_inserted++
      }
    }

    // 3-b) referral_rewards 복제 + transactions mirror
    for (const src of srcRrRows) {
      const rrIns = await db.prepare(`
        INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date)
        VALUES (?, ?, ?, ?, ?, ?, ?)
      `).bind(src.referrer_id, src.referee_id, src.level, src.original_amount, src.reward_amount, DST_REWARD_DATE, DST_PAID_DATE).run()
      const newRrId = (rrIns as any)?.meta?.last_row_id ?? null
      if (newRrId) {
        executed.referral_rewards_inserted++
        const level = Number(src.level)
        const desc = level === 1 ? '추천 보너스 (Level 1)' : (level === 2 ? '추천 보너스 (Level 2)' : '추천 보너스')
        await db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
          VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?)
        `).bind(src.referrer_id, src.reward_amount, desc, newRrId).run()
        executed.referral_transactions_inserted++
      }
    }

    // 3-c) qkey_balance 가산
    for (const [uid, amt] of Object.entries(insertDeltas)) {
      if (amt > 0) {
        const r = await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(amt, Number(uid)).run()
        if ((r as any)?.meta?.changes > 0) executed.balance_insert_users++
      }
    }

    return c.json({
      success: true,
      mode: 'EXECUTED',
      src_paid_date: SRC_PAID_DATE,
      dst_paid_date: DST_PAID_DATE,
      wipe_summary: wipeSummary,
      insert_summary: insertSummary,
      executed,
      balance_net_deltas: netDeltas,
      affected_users: allUids.size
    })
  } catch (error) {
    console.error('rebuild-may15-from-may14 error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ 5/15 referral_rewards 보충 INSERT (옵션 1, 멱등 안전, 사장님 2026-05-15 결재) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   사장님 원문: "옵션1로 지금 모든 회원들이 민감하게 바라보고 있어 확실하고 논리적으로 계산이 맞아야해"
//
//   배경 — rebuild-may15-from-may14 endpoint 가 Cloudflare 524 (Origin timeout) 으로
//          2회 중단되어 5/15 referral_rewards INSERT 가 일부만 진행된 상태:
//          현재 5/15: own=183,000 ✅, L1=24,270 (목표 35,550), L2=10,785 (목표 16,275)
//          → daily_rewards 56건은 모두 INSERT 완료, referral_rewards 109건 중 일부 INSERT 누락
//
//   처리 원칙 (멱등 안전):
//     1) 5/14 referral_rewards 109건을 source of truth 로 read-only 사용
//     2) 각 5/14 행에 대해 5/15 에 동일 키 행이 이미 존재하는지 EXISTS 검사:
//        키 = (referrer_id, referee_id, level, reward_date='2026-05-15')
//     3) 미존재 시에만 INSERT (reward_date='2026-05-15', paid_date='2026-05-15')
//     4) INSERT 성공 시 transactions mirror INSERT (type, ref_id 가드 동반)
//     5) INSERT 성공 시 users.qkey_balance += reward_amount
//     6) 이미 존재하는 행은 skip (재호출 시 중복 절대 발생 안 함)
//
//   daily_rewards 는 손대지 않음 (own=183,000 이미 5/14 와 일치).
//   다른 paid_date 데이터 절대 손대지 않음 (5/14 read-only, 5/15 만 INSERT).
//
//   경로: POST /api/diag/topup-may15-referrals?key=ADMIN_PW&dry_run=1   (조회)
//         POST /api/diag/topup-may15-referrals?key=ADMIN_PW&confirm=GO  (실행)
app.post('/api/diag/topup-may15-referrals', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)

    const confirm = c.req.query('confirm') === 'GO'
    const dryRun = !confirm
    const db = c.env.DB

    const SRC_PAID_DATE = '2026-05-14'   // 원본 (어제, read-only)
    const DST_REWARD_DATE = '2026-05-15' // 대상
    const DST_PAID_DATE = '2026-05-15'   // 대상

    // ============================================================
    // STEP 1 — 5/14 referral_rewards 원본 109건 SELECT (read-only source of truth)
    // ============================================================
    const srcRr = await db.prepare(`
      SELECT id, referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date
      FROM referral_rewards WHERE paid_date = ?
      ORDER BY id ASC
    `).bind(SRC_PAID_DATE).all() as any
    const srcRrRows = srcRr?.results || []

    // ============================================================
    // STEP 2 — 각 5/14 행에 대해 5/15 EXISTS 검사 + INSERT 계획
    // ============================================================
    const plan: any[] = []
    let toInsertCount = 0
    let alreadyExistsCount = 0
    let toInsertQkey = 0
    const balanceDeltas: Record<number, number> = {}

    for (const src of srcRrRows) {
      const exists = await db.prepare(`
        SELECT id FROM referral_rewards
        WHERE referrer_id = ? AND referee_id = ? AND level = ? AND reward_date = ?
        LIMIT 1
      `).bind(src.referrer_id, src.referee_id, src.level, DST_REWARD_DATE).first() as any

      if (exists) {
        alreadyExistsCount++
        plan.push({
          src_rr_id: src.id,
          action: 'skip_exists',
          existing_dst_rr_id: exists.id,
          referrer_id: src.referrer_id,
          referee_id: src.referee_id,
          level: src.level,
          reward_amount: src.reward_amount
        })
      } else {
        toInsertCount++
        toInsertQkey += Number(src.reward_amount || 0)
        const uid = Number(src.referrer_id)
        balanceDeltas[uid] = (balanceDeltas[uid] || 0) + Number(src.reward_amount || 0)
        plan.push({
          src_rr_id: src.id,
          action: 'insert',
          referrer_id: src.referrer_id,
          referee_id: src.referee_id,
          level: src.level,
          original_amount: src.original_amount,
          reward_amount: src.reward_amount
        })
      }
    }

    // ============================================================
    // STEP 3 — DRY_RUN 이면 계획만 반환
    // ============================================================
    if (dryRun) {
      return c.json({
        success: true,
        mode: 'DRY_RUN',
        message: '실제 실행을 원하시면 confirm=GO 파라미터를 추가하세요',
        src_paid_date: SRC_PAID_DATE,
        dst_paid_date: DST_PAID_DATE,
        src_rr_total: srcRrRows.length,
        plan_summary: {
          to_insert_count: toInsertCount,
          already_exists_count: alreadyExistsCount,
          to_insert_qkey: toInsertQkey,
          affected_users: Object.keys(balanceDeltas).length
        },
        balance_deltas: balanceDeltas,
        plan_first_30: plan.slice(0, 30)
      })
    }

    // ============================================================
    // STEP 4 — 실제 실행 (confirm=GO, EXISTS 가드로 멱등 안전)
    // ============================================================
    const executed = {
      referral_rewards_inserted: 0,
      referral_rewards_skipped_exists: 0,
      transactions_inserted: 0,
      transactions_skipped_exists: 0,
      balance_users_updated: 0
    }
    const insertedDetails: any[] = []
    const balanceActual: Record<number, number> = {}

    for (const src of srcRrRows) {
      // EXISTS 재검사 (실행 시점에 다시 확인 — 동시성 안전)
      const exists = await db.prepare(`
        SELECT id FROM referral_rewards
        WHERE referrer_id = ? AND referee_id = ? AND level = ? AND reward_date = ?
        LIMIT 1
      `).bind(src.referrer_id, src.referee_id, src.level, DST_REWARD_DATE).first() as any

      if (exists) {
        executed.referral_rewards_skipped_exists++
        continue
      }

      // 4-1) referral_rewards INSERT
      const rrIns = await db.prepare(`
        INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date)
        VALUES (?, ?, ?, ?, ?, ?, ?)
      `).bind(
        src.referrer_id, src.referee_id, src.level,
        src.original_amount, src.reward_amount,
        DST_REWARD_DATE, DST_PAID_DATE
      ).run()
      const newRrId = (rrIns as any)?.meta?.last_row_id ?? null
      if (!newRrId) continue
      executed.referral_rewards_inserted++

      // 4-2) transactions mirror INSERT (type, ref_id 가드)
      const txExists = await db.prepare(`
        SELECT id FROM transactions WHERE type = 'referral_reward' AND ref_id = ? LIMIT 1
      `).bind(newRrId).first()
      if (!txExists) {
        const level = Number(src.level)
        const desc = level === 1 ? '추천 보너스 (Level 1)' : (level === 2 ? '추천 보너스 (Level 2)' : '추천 보너스')
        await db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
          VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?)
        `).bind(src.referrer_id, src.reward_amount, desc, newRrId).run()
        executed.transactions_inserted++
      } else {
        executed.transactions_skipped_exists++
      }

      // 4-3) qkey_balance 가산 (각 row 별로 즉시 반영 → 부분 실행 시에도 일관성)
      await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`)
        .bind(src.reward_amount, src.referrer_id).run()

      const uid = Number(src.referrer_id)
      balanceActual[uid] = (balanceActual[uid] || 0) + Number(src.reward_amount || 0)

      insertedDetails.push({
        src_rr_id: src.id,
        new_rr_id: newRrId,
        referrer_id: src.referrer_id,
        referee_id: src.referee_id,
        level: src.level,
        reward_amount: src.reward_amount
      })
    }

    executed.balance_users_updated = Object.keys(balanceActual).length

    return c.json({
      success: true,
      mode: 'EXECUTED',
      src_paid_date: SRC_PAID_DATE,
      dst_paid_date: DST_PAID_DATE,
      src_rr_total: srcRrRows.length,
      executed,
      balance_actual_deltas: balanceActual,
      inserted_count: insertedDetails.length,
      inserted_first_30: insertedDetails.slice(0, 30)
    })
  } catch (error) {
    console.error('topup-may15-referrals error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ FINAL-C 완벽 동기화 마스터 (사장님 2026-05-15 "c" 결재, 완벽 수정) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   사장님 원문: "나는 완벽한 수정을 원해... 모든게 오류없이 중복없이 수정되는 옵션...
//                다시는 이런 2가지 일 중복지급+미지급 이런건 일어나면 안돼"
//   사장님 결재: [최종-C] = 5/15 완전 wipe + 5/14 잔존 중복 8건 정리 + 5/14 정상분 1:1 미러링
//
//   Phase 1: 5/15 paid_date 완전 wipe (transactions 173 + daily_rewards 56 + referral_rewards 99
//            + qkey_balance 정확 차감)
//   Phase 2: 5/14 paid_date 잔존 중복 8건 정리 (audit identified):
//            referral_rewards.id IN (1217, 1225, 1226, 1227, 1241, 1242, 1245, 1246)
//            (모두 reward_date=5/13 이나 paid_date=5/14 로 잘못 들어간 legacy 중복)
//            연관 transactions(type='referral_reward', ref_id IN ...) 삭제
//            각 referrer qkey_balance 정확 차감 (합 -900 QKEY)
//   Phase 3: Phase 2 후 5/14 의 모든 row 를 5/15 로 1:1 미러링
//            daily_rewards 56 → INSERT (reward_date=5/15, paid_date=5/15)
//            referral_rewards 101 → INSERT (reward_date 원본 유지, paid_date=5/15)
//            각 INSERT 직후 transactions mirror + qkey_balance 가산
//   Phase 4: 4-layer 자동 검증
//
//   경로:
//     POST /api/diag/final-c-perfect-sync?key=ADMIN_PW&dry_run=1  (사전점검)
//     POST /api/diag/final-c-perfect-sync?key=ADMIN_PW&confirm=GO (실행)
app.post('/api/diag/final-c-perfect-sync', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const dryRun = c.req.query('dry_run') === '1'
    const confirm = c.req.query('confirm') || ''
    if (!dryRun && confirm !== 'GO') {
      return c.json({ error: 'Missing confirm=GO (or use dry_run=1)' }, 400)
    }

    const SRC_PAID_DATE = '2026-05-14'
    const DST_PAID_DATE = '2026-05-15'
    const DST_REWARD_DATE_DAILY = '2026-05-15'

    // ============================================================
    // 5/14 잔존 중복 8건 (audit 결과 확정, reward_date=5/13 → paid_date=5/14 오기재)
    // ============================================================
    const PHASE2_DUP_IDS = [1217, 1225, 1226, 1227, 1241, 1242, 1245, 1246]

    // ============================================================
    // PHASE 0 — 사전 진단 + 5/14 스냅샷 (Phase 2 정리 후 기준)
    // ============================================================

    // 0-1) 5/15 wipe 대상 카운트 + 합계 (per-user qkey 차감용)
    const may15Tx = await db.prepare(`
      SELECT id, user_id, type, amount, ref_id
      FROM transactions
      WHERE DATE(created_at) = ? AND type IN ('daily_qkey', 'referral_reward')
    `).bind(DST_PAID_DATE).all()
    const may15TxRows = (may15Tx.results || []) as any[]
    const may15TxQkeyByUser: Record<number, number> = {}
    for (const t of may15TxRows) {
      const uid = Number(t.user_id)
      may15TxQkeyByUser[uid] = (may15TxQkeyByUser[uid] || 0) + Number(t.amount || 0)
    }

    const may15Dr = await db.prepare(`SELECT id, user_id, usdt_amount FROM daily_rewards WHERE paid_date = ?`).bind(DST_PAID_DATE).all()
    const may15DrRows = (may15Dr.results || []) as any[]
    const may15Rr = await db.prepare(`SELECT id, referrer_id, reward_amount FROM referral_rewards WHERE paid_date = ?`).bind(DST_PAID_DATE).all()
    const may15RrRows = (may15Rr.results || []) as any[]

    // 0-2) 5/14 잔존 중복 8건 확인 + 합계
    const dupRows = await db.prepare(`
      SELECT id, referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date
      FROM referral_rewards WHERE id IN (${PHASE2_DUP_IDS.join(',')})
    `).all()
    const dupList = (dupRows.results || []) as any[]
    const dupTxRows = await db.prepare(`
      SELECT id, user_id, type, amount, ref_id FROM transactions
      WHERE type = 'referral_reward' AND ref_id IN (${PHASE2_DUP_IDS.join(',')})
    `).all()
    const dupTxList = (dupTxRows.results || []) as any[]
    const dupQkeyByUser: Record<number, number> = {}
    for (const r of dupList) {
      const uid = Number(r.referrer_id)
      dupQkeyByUser[uid] = (dupQkeyByUser[uid] || 0) + Number(r.reward_amount || 0)
    }
    const dupExcessTotal = dupList.reduce((s, r) => s + Number(r.reward_amount || 0), 0)

    // 0-3) 5/14 paid_date 의 원본 SELECT (Phase 2 이후 = 잔존 중복 제외하고 미러링)
    const srcDr = await db.prepare(`
      SELECT id, user_id, staking_id, usdt_amount, reward_date, paid_date
      FROM daily_rewards WHERE paid_date = ?
      ORDER BY id ASC
    `).bind(SRC_PAID_DATE).all()
    const srcDrRows = (srcDr.results || []) as any[]

    const srcRr = await db.prepare(`
      SELECT id, referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date
      FROM referral_rewards WHERE paid_date = ?
      ORDER BY id ASC
    `).bind(SRC_PAID_DATE).all()
    const srcRrRowsAll = (srcRr.results || []) as any[]
    const srcRrRowsClean = srcRrRowsAll.filter(r => !PHASE2_DUP_IDS.includes(Number(r.id)))

    // 0-4) 5/14 정상분(Phase 2 적용 후) per-user 합계 (검증 기준)
    const srcOwnByUser: Record<number, number> = {}
    for (const r of srcDrRows) {
      const uid = Number(r.user_id)
      srcOwnByUser[uid] = (srcOwnByUser[uid] || 0) + Number(r.usdt_amount || 0)
    }
    const srcL1ByUser: Record<number, number> = {}
    const srcL2ByUser: Record<number, number> = {}
    for (const r of srcRrRowsClean) {
      const uid = Number(r.referrer_id)
      if (Number(r.level) === 1) srcL1ByUser[uid] = (srcL1ByUser[uid] || 0) + Number(r.reward_amount || 0)
      if (Number(r.level) === 2) srcL2ByUser[uid] = (srcL2ByUser[uid] || 0) + Number(r.reward_amount || 0)
    }
    const srcGrandOwn = Object.values(srcOwnByUser).reduce((s: number, v: any) => s + Number(v), 0)
    const srcGrandL1 = Object.values(srcL1ByUser).reduce((s: number, v: any) => s + Number(v), 0)
    const srcGrandL2 = Object.values(srcL2ByUser).reduce((s: number, v: any) => s + Number(v), 0)

    const planSummary = {
      phase1_wipe: {
        tx_to_delete: may15TxRows.length,
        dr_to_delete: may15DrRows.length,
        rr_to_delete: may15RrRows.length,
        qkey_balance_subtract_per_user: may15TxQkeyByUser,
        total_qkey_subtracted: Object.values(may15TxQkeyByUser).reduce((s: number, v: any) => s + Number(v), 0)
      },
      phase2_dedupe_may14: {
        rr_to_delete_ids: PHASE2_DUP_IDS,
        rr_to_delete_count: dupList.length,
        tx_linked_to_delete: dupTxList.length,
        qkey_balance_subtract_per_user: dupQkeyByUser,
        total_qkey_subtracted: dupExcessTotal
      },
      phase3_mirror_to_may15: {
        dr_to_insert: srcDrRows.length,
        rr_to_insert: srcRrRowsClean.length,
        tx_to_insert: srcDrRows.length + srcRrRowsClean.length,
        qkey_balance_add_total:
          srcDrRows.reduce((s, r) => s + Number(r.usdt_amount || 0), 0) +
          srcRrRowsClean.reduce((s, r) => s + Number(r.reward_amount || 0), 0)
      },
      expected_final_state: {
        may14_paid_date: {
          own: srcGrandOwn, l1: srcGrandL1, l2: srcGrandL2, total: srcGrandOwn + srcGrandL1 + srcGrandL2
        },
        may15_paid_date_target: {
          own: srcGrandOwn, l1: srcGrandL1, l2: srcGrandL2, total: srcGrandOwn + srcGrandL1 + srcGrandL2
        },
        match: 'EXPECTED_PERFECT_MATCH'
      }
    }

    if (dryRun) {
      return c.json({
        success: true,
        mode: 'DRY_RUN',
        message: '실제 실행을 원하시면 confirm=GO 파라미터를 추가하세요',
        plan_summary: planSummary,
        details: {
          may14_dup_rows: dupList,
          may14_dup_tx_rows: dupTxList,
          may15_wipe_tx_first_10: may15TxRows.slice(0, 10),
          may15_wipe_dr_first_10: may15DrRows.slice(0, 10),
          may15_wipe_rr_first_10: may15RrRows.slice(0, 10)
        }
      })
    }

    // ============================================================
    // PHASE 1 — 5/15 paid_date 완전 wipe
    // ============================================================
    const phase1Result = { tx_deleted: 0, dr_deleted: 0, rr_deleted: 0, qkey_subtracted_per_user: {} as Record<number, number> }

    // 1-1) qkey_balance 차감 (transactions 합 기준 — 가장 정확)
    for (const [uidStr, qkey] of Object.entries(may15TxQkeyByUser)) {
      const uid = Number(uidStr)
      await db.prepare('UPDATE users SET qkey_balance = qkey_balance - ? WHERE id = ?')
        .bind(qkey, uid).run()
      phase1Result.qkey_subtracted_per_user[uid] = Number(qkey)
    }

    // 1-2) transactions 삭제
    const txDel = await db.prepare(`
      DELETE FROM transactions WHERE DATE(created_at) = ? AND type IN ('daily_qkey', 'referral_reward')
    `).bind(DST_PAID_DATE).run()
    phase1Result.tx_deleted = txDel.meta?.changes ?? 0

    // 1-3) daily_rewards 삭제
    const drDel = await db.prepare(`DELETE FROM daily_rewards WHERE paid_date = ?`).bind(DST_PAID_DATE).run()
    phase1Result.dr_deleted = drDel.meta?.changes ?? 0

    // 1-4) referral_rewards 삭제
    const rrDel = await db.prepare(`DELETE FROM referral_rewards WHERE paid_date = ?`).bind(DST_PAID_DATE).run()
    phase1Result.rr_deleted = rrDel.meta?.changes ?? 0

    // ============================================================
    // PHASE 2 — 5/14 잔존 중복 8건 정리
    // ============================================================
    const phase2Result = { rr_deleted: 0, tx_deleted: 0, qkey_subtracted_per_user: {} as Record<number, number> }

    // 2-1) qkey_balance 차감 (referrer 기준)
    for (const [uidStr, qkey] of Object.entries(dupQkeyByUser)) {
      const uid = Number(uidStr)
      await db.prepare('UPDATE users SET qkey_balance = qkey_balance - ? WHERE id = ?')
        .bind(qkey, uid).run()
      phase2Result.qkey_subtracted_per_user[uid] = Number(qkey)
    }

    // 2-2) transactions 삭제 (type='referral_reward', ref_id IN dup_ids)
    const dupTxDel = await db.prepare(`
      DELETE FROM transactions WHERE type = 'referral_reward' AND ref_id IN (${PHASE2_DUP_IDS.join(',')})
    `).run()
    phase2Result.tx_deleted = dupTxDel.meta?.changes ?? 0

    // 2-3) referral_rewards 삭제
    const dupRrDel = await db.prepare(`
      DELETE FROM referral_rewards WHERE id IN (${PHASE2_DUP_IDS.join(',')})
    `).run()
    phase2Result.rr_deleted = dupRrDel.meta?.changes ?? 0

    // ============================================================
    // PHASE 3 — 5/14 정상분 → 5/15 1:1 미러링
    // ============================================================
    const phase3Result = {
      dr_inserted: 0, rr_inserted: 0, tx_inserted: 0,
      qkey_added_per_user: {} as Record<number, number>
    }

    // 3-1) daily_rewards 미러링
    for (const r of srcDrRows) {
      const drIns = await db.prepare(`
        INSERT INTO daily_rewards (user_id, staking_id, usdt_amount, reward_date, paid_date)
        VALUES (?, ?, ?, ?, ?)
      `).bind(r.user_id, r.staking_id, r.usdt_amount, DST_REWARD_DATE_DAILY, DST_PAID_DATE).run()
      const newDrId = (drIns as any)?.meta?.last_row_id
      if (!newDrId) continue
      phase3Result.dr_inserted++

      // transactions mirror
      await db.prepare(`
        INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
        VALUES (?, 'daily_qkey', 'QKEY', ?, '일일 배당 (QKEY)', ?)
      `).bind(r.user_id, r.usdt_amount, newDrId).run()
      phase3Result.tx_inserted++

      // qkey_balance 가산
      await db.prepare('UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?')
        .bind(r.usdt_amount, r.user_id).run()

      const uid = Number(r.user_id)
      phase3Result.qkey_added_per_user[uid] = (phase3Result.qkey_added_per_user[uid] || 0) + Number(r.usdt_amount || 0)
    }

    // 3-2) referral_rewards 미러링 (Phase 2 후 정상분만)
    for (const r of srcRrRowsClean) {
      const rrIns = await db.prepare(`
        INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date)
        VALUES (?, ?, ?, ?, ?, ?, ?)
      `).bind(
        r.referrer_id, r.referee_id, r.level,
        r.original_amount, r.reward_amount,
        r.reward_date,    // 원본 reward_date 유지 (예: 5/14, 5/13)
        DST_PAID_DATE
      ).run()
      const newRrId = (rrIns as any)?.meta?.last_row_id
      if (!newRrId) continue
      phase3Result.rr_inserted++

      const level = Number(r.level)
      const desc = level === 1 ? '추천 보너스 (Level 1)' : (level === 2 ? '추천 보너스 (Level 2)' : '추천 보너스')
      await db.prepare(`
        INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
        VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?)
      `).bind(r.referrer_id, r.reward_amount, desc, newRrId).run()
      phase3Result.tx_inserted++

      await db.prepare('UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?')
        .bind(r.reward_amount, r.referrer_id).run()

      const uid = Number(r.referrer_id)
      phase3Result.qkey_added_per_user[uid] = (phase3Result.qkey_added_per_user[uid] || 0) + Number(r.reward_amount || 0)
    }

    // ============================================================
    // PHASE 4 — 4-Layer 자동 검증
    // ============================================================

    // L1: 5/14 dr count == 5/15 dr count
    const may14DrCount = await db.prepare(`SELECT COUNT(*) as c FROM daily_rewards WHERE paid_date = ?`).bind(SRC_PAID_DATE).first() as any
    const may15DrCount = await db.prepare(`SELECT COUNT(*) as c FROM daily_rewards WHERE paid_date = ?`).bind(DST_PAID_DATE).first() as any
    const layer1Pass = Number(may14DrCount?.c || 0) === Number(may15DrCount?.c || 0)

    // L2: 5/14 rr count == 5/15 rr count
    const may14RrCount = await db.prepare(`SELECT COUNT(*) as c FROM referral_rewards WHERE paid_date = ?`).bind(SRC_PAID_DATE).first() as any
    const may15RrCount = await db.prepare(`SELECT COUNT(*) as c FROM referral_rewards WHERE paid_date = ?`).bind(DST_PAID_DATE).first() as any
    const layer2Pass = Number(may14RrCount?.c || 0) === Number(may15RrCount?.c || 0)

    // L3: per-user own/L1/L2 비교
    const may14OwnRows = await db.prepare(`SELECT user_id, SUM(usdt_amount) as own FROM daily_rewards WHERE paid_date = ? GROUP BY user_id`).bind(SRC_PAID_DATE).all()
    const may14L1Rows = await db.prepare(`SELECT referrer_id, SUM(reward_amount) as l1 FROM referral_rewards WHERE paid_date = ? AND level = 1 GROUP BY referrer_id`).bind(SRC_PAID_DATE).all()
    const may14L2Rows = await db.prepare(`SELECT referrer_id, SUM(reward_amount) as l2 FROM referral_rewards WHERE paid_date = ? AND level = 2 GROUP BY referrer_id`).bind(SRC_PAID_DATE).all()
    const may15OwnRows = await db.prepare(`SELECT user_id, SUM(usdt_amount) as own FROM daily_rewards WHERE paid_date = ? GROUP BY user_id`).bind(DST_PAID_DATE).all()
    const may15L1Rows = await db.prepare(`SELECT referrer_id, SUM(reward_amount) as l1 FROM referral_rewards WHERE paid_date = ? AND level = 1 GROUP BY referrer_id`).bind(DST_PAID_DATE).all()
    const may15L2Rows = await db.prepare(`SELECT referrer_id, SUM(reward_amount) as l2 FROM referral_rewards WHERE paid_date = ? AND level = 2 GROUP BY referrer_id`).bind(DST_PAID_DATE).all()

    const m14Own: Record<number, number> = {}
    for (const r of (may14OwnRows.results || []) as any[]) m14Own[Number(r.user_id)] = Number(r.own)
    const m14L1: Record<number, number> = {}
    for (const r of (may14L1Rows.results || []) as any[]) m14L1[Number(r.referrer_id)] = Number(r.l1)
    const m14L2: Record<number, number> = {}
    for (const r of (may14L2Rows.results || []) as any[]) m14L2[Number(r.referrer_id)] = Number(r.l2)
    const m15Own: Record<number, number> = {}
    for (const r of (may15OwnRows.results || []) as any[]) m15Own[Number(r.user_id)] = Number(r.own)
    const m15L1: Record<number, number> = {}
    for (const r of (may15L1Rows.results || []) as any[]) m15L1[Number(r.referrer_id)] = Number(r.l1)
    const m15L2: Record<number, number> = {}
    for (const r of (may15L2Rows.results || []) as any[]) m15L2[Number(r.referrer_id)] = Number(r.l2)

    const allUids = new Set<number>([
      ...Object.keys(m14Own).map(Number), ...Object.keys(m14L1).map(Number), ...Object.keys(m14L2).map(Number),
      ...Object.keys(m15Own).map(Number), ...Object.keys(m15L1).map(Number), ...Object.keys(m15L2).map(Number)
    ])
    const l3Mismatches: any[] = []
    for (const uid of allUids) {
      const own14 = m14Own[uid] || 0
      const l1_14 = m14L1[uid] || 0
      const l2_14 = m14L2[uid] || 0
      const own15 = m15Own[uid] || 0
      const l1_15 = m15L1[uid] || 0
      const l2_15 = m15L2[uid] || 0
      if (own14 !== own15 || l1_14 !== l1_15 || l2_14 !== l2_15) {
        l3Mismatches.push({
          user_id: uid,
          may14: { own: own14, l1: l1_14, l2: l2_14 },
          may15: { own: own15, l1: l1_15, l2: l2_15 },
          diff: { own: own15 - own14, l1: l1_15 - l1_14, l2: l2_15 - l2_14 }
        })
      }
    }
    const layer3Pass = l3Mismatches.length === 0

    // L4: 5/15 transactions 합 == 5/15 (dr + rr) 합
    const may15TxSum = await db.prepare(`
      SELECT SUM(amount) as s FROM transactions
      WHERE DATE(created_at) = ? AND type IN ('daily_qkey','referral_reward')
    `).bind(DST_PAID_DATE).first() as any
    const may15DrSum = await db.prepare(`SELECT SUM(usdt_amount) as s FROM daily_rewards WHERE paid_date = ?`).bind(DST_PAID_DATE).first() as any
    const may15RrSum = await db.prepare(`SELECT SUM(reward_amount) as s FROM referral_rewards WHERE paid_date = ?`).bind(DST_PAID_DATE).first() as any
    const txSum = Number(may15TxSum?.s || 0)
    const expected = Number(may15DrSum?.s || 0) + Number(may15RrSum?.s || 0)
    const layer4Pass = txSum === expected

    const allLayersPass = layer1Pass && layer2Pass && layer3Pass && layer4Pass

    return c.json({
      success: true,
      mode: 'EXECUTED',
      phase1_wipe_may15: phase1Result,
      phase2_dedupe_may14: phase2Result,
      phase3_mirror_may14_to_may15: phase3Result,
      phase4_verify: {
        layer1_dr_count_match: { pass: layer1Pass, may14: Number(may14DrCount?.c), may15: Number(may15DrCount?.c) },
        layer2_rr_count_match: { pass: layer2Pass, may14: Number(may14RrCount?.c), may15: Number(may15RrCount?.c) },
        layer3_per_user_match: { pass: layer3Pass, mismatch_count: l3Mismatches.length, mismatches: l3Mismatches },
        layer4_tx_sum_eq_dr_plus_rr: { pass: layer4Pass, tx_sum: txSum, dr_plus_rr: expected },
        verdict: allLayersPass ? 'PERFECT_MATCH' : 'MISMATCH_DETECTED'
      }
    })
  } catch (error) {
    console.error('final-c-perfect-sync error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ FINAL-C 안전 분할 — Phase 1: 5/15 paid_date 완전 wipe (사장님 결재: 가장 안전한 방법) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   사장님 원문: "가장 안전한 방법으로 진행해줘 1번"
//   처리: 5/15 paid_date 의 transactions / daily_rewards / referral_rewards 전부 삭제 +
//         qkey_balance 정확 차감 (transactions amount 합 기준)
//   멱등: 재호출 시 이미 0건이면 skip — 안전
//   경로: POST /api/diag/final-c-phase1-wipe-may15?key=ADMIN_PW&dry_run=1
//         POST /api/diag/final-c-phase1-wipe-may15?key=ADMIN_PW&confirm=GO
app.post('/api/diag/final-c-phase1-wipe-may15', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const dryRun = c.req.query('dry_run') === '1'
    const confirm = c.req.query('confirm') || ''
    if (!dryRun && confirm !== 'GO') {
      return c.json({ error: 'Missing confirm=GO (or use dry_run=1)' }, 400)
    }
    const PAID_DATE = '2026-05-15'

    // 1) wipe 대상 조회 + per-user 잔액 차감액 (tx amount 합 기준)
    const txRows = await db.prepare(`
      SELECT id, user_id, type, amount, ref_id
      FROM transactions
      WHERE DATE(created_at) = ? AND type IN ('daily_qkey', 'referral_reward')
    `).bind(PAID_DATE).all()
    const txList = (txRows.results || []) as any[]
    const qkeyByUser: Record<number, number> = {}
    for (const t of txList) {
      const uid = Number(t.user_id)
      qkeyByUser[uid] = (qkeyByUser[uid] || 0) + Number(t.amount || 0)
    }

    const drRows = await db.prepare(`SELECT id FROM daily_rewards WHERE paid_date = ?`).bind(PAID_DATE).all()
    const rrRows = await db.prepare(`SELECT id FROM referral_rewards WHERE paid_date = ?`).bind(PAID_DATE).all()

    const plan = {
      tx_to_delete: txList.length,
      dr_to_delete: (drRows.results || []).length,
      rr_to_delete: (rrRows.results || []).length,
      qkey_subtract_per_user: qkeyByUser,
      total_qkey_subtract: Object.values(qkeyByUser).reduce((s: number, v: any) => s + Number(v), 0),
      affected_users: Object.keys(qkeyByUser).length
    }

    if (dryRun) {
      return c.json({ success: true, mode: 'DRY_RUN', message: '실제 실행을 원하시면 confirm=GO 추가', phase: 'phase1_wipe_may15', plan })
    }

    // 멱등: 이미 모두 비어있으면 skip
    if (plan.tx_to_delete === 0 && plan.dr_to_delete === 0 && plan.rr_to_delete === 0) {
      return c.json({ success: true, mode: 'NOOP_ALREADY_EMPTY', phase: 'phase1_wipe_may15' })
    }

    // 2) 잔액 차감 먼저 (각 사용자별 — tx 삭제 전에 합계 확정된 값 사용)
    const balanceBefore: Record<number, number> = {}
    const balanceAfter: Record<number, number> = {}
    for (const [uidStr, qkey] of Object.entries(qkeyByUser)) {
      const uid = Number(uidStr)
      const b1 = await db.prepare('SELECT qkey_balance FROM users WHERE id = ?').bind(uid).first() as any
      balanceBefore[uid] = Number(b1?.qkey_balance || 0)
      await db.prepare('UPDATE users SET qkey_balance = qkey_balance - ? WHERE id = ?').bind(qkey, uid).run()
      const b2 = await db.prepare('SELECT qkey_balance FROM users WHERE id = ?').bind(uid).first() as any
      balanceAfter[uid] = Number(b2?.qkey_balance || 0)
    }

    // 3) tx 삭제
    const txDel = await db.prepare(`
      DELETE FROM transactions WHERE DATE(created_at) = ? AND type IN ('daily_qkey', 'referral_reward')
    `).bind(PAID_DATE).run()

    // 4) dr 삭제
    const drDel = await db.prepare(`DELETE FROM daily_rewards WHERE paid_date = ?`).bind(PAID_DATE).run()

    // 5) rr 삭제
    const rrDel = await db.prepare(`DELETE FROM referral_rewards WHERE paid_date = ?`).bind(PAID_DATE).run()

    return c.json({
      success: true,
      mode: 'EXECUTED',
      phase: 'phase1_wipe_may15',
      result: {
        tx_deleted: txDel.meta?.changes ?? 0,
        dr_deleted: drDel.meta?.changes ?? 0,
        rr_deleted: rrDel.meta?.changes ?? 0,
        users_balance_subtracted: Object.keys(qkeyByUser).length,
        total_qkey_subtracted: plan.total_qkey_subtract,
        balance_before: balanceBefore,
        balance_after: balanceAfter
      }
    })
  } catch (error) {
    console.error('final-c-phase1-wipe-may15 error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ FINAL-C 안전 분할 — Phase 2: 5/14 잔존 중복 8건 정리 (audit identified) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   대상 referral_rewards.id IN (1217, 1225, 1226, 1227, 1241, 1242, 1245, 1246)
//   모두 reward_date=5/13 이나 paid_date=5/14 로 잘못 들어간 legacy 중복
//   총 -900 QKEY 차감 (user 2, 41, 42, 44, 48, 49, 57)
//   멱등: 이미 정리되어 있으면 skip
app.post('/api/diag/final-c-phase2-dedupe-may14', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const dryRun = c.req.query('dry_run') === '1'
    const confirm = c.req.query('confirm') || ''
    if (!dryRun && confirm !== 'GO') {
      return c.json({ error: 'Missing confirm=GO (or use dry_run=1)' }, 400)
    }
    const DUP_IDS = [1217, 1225, 1226, 1227, 1241, 1242, 1245, 1246]

    // 1) 현존 확인
    const dupRows = await db.prepare(`
      SELECT id, referrer_id, referee_id, level, reward_amount, reward_date, paid_date
      FROM referral_rewards WHERE id IN (${DUP_IDS.join(',')})
    `).all()
    const dupList = (dupRows.results || []) as any[]
    const dupTxRows = await db.prepare(`
      SELECT id, user_id, amount, ref_id FROM transactions
      WHERE type = 'referral_reward' AND ref_id IN (${DUP_IDS.join(',')})
    `).all()
    const dupTxList = (dupTxRows.results || []) as any[]
    const qkeyByUser: Record<number, number> = {}
    for (const r of dupList) {
      const uid = Number(r.referrer_id)
      qkeyByUser[uid] = (qkeyByUser[uid] || 0) + Number(r.reward_amount || 0)
    }

    const plan = {
      rr_to_delete_ids: DUP_IDS,
      rr_to_delete_count: dupList.length,
      tx_to_delete_count: dupTxList.length,
      qkey_subtract_per_user: qkeyByUser,
      total_qkey_subtract: Object.values(qkeyByUser).reduce((s: number, v: any) => s + Number(v), 0)
    }

    if (dryRun) {
      return c.json({ success: true, mode: 'DRY_RUN', message: '실제 실행을 원하시면 confirm=GO 추가', phase: 'phase2_dedupe_may14', plan, dup_rows: dupList, dup_tx_rows: dupTxList })
    }

    // 멱등
    if (dupList.length === 0) {
      return c.json({ success: true, mode: 'NOOP_ALREADY_CLEANED', phase: 'phase2_dedupe_may14' })
    }

    // 안전: dupList 의 id 가 모두 DUP_IDS 내에 있는지 + reward_date='2026-05-13' + paid_date='2026-05-14' 확인
    const allSafe = dupList.every(r =>
      DUP_IDS.includes(Number(r.id)) &&
      String(r.reward_date) === '2026-05-13' &&
      String(r.paid_date) === '2026-05-14'
    )
    if (!allSafe) {
      return c.json({
        success: false, error: 'SAFETY_CHECK_FAILED: row metadata mismatch',
        dup_list: dupList
      }, 400)
    }

    // 2) 잔액 차감
    const balanceBefore: Record<number, number> = {}
    const balanceAfter: Record<number, number> = {}
    for (const [uidStr, qkey] of Object.entries(qkeyByUser)) {
      const uid = Number(uidStr)
      const b1 = await db.prepare('SELECT qkey_balance FROM users WHERE id = ?').bind(uid).first() as any
      balanceBefore[uid] = Number(b1?.qkey_balance || 0)
      await db.prepare('UPDATE users SET qkey_balance = qkey_balance - ? WHERE id = ?').bind(qkey, uid).run()
      const b2 = await db.prepare('SELECT qkey_balance FROM users WHERE id = ?').bind(uid).first() as any
      balanceAfter[uid] = Number(b2?.qkey_balance || 0)
    }

    // 3) tx 삭제
    const txDel = await db.prepare(`
      DELETE FROM transactions WHERE type = 'referral_reward' AND ref_id IN (${DUP_IDS.join(',')})
    `).run()

    // 4) rr 삭제
    const rrDel = await db.prepare(`DELETE FROM referral_rewards WHERE id IN (${DUP_IDS.join(',')})`).run()

    return c.json({
      success: true,
      mode: 'EXECUTED',
      phase: 'phase2_dedupe_may14',
      result: {
        rr_deleted: rrDel.meta?.changes ?? 0,
        tx_deleted: txDel.meta?.changes ?? 0,
        users_balance_subtracted: Object.keys(qkeyByUser).length,
        total_qkey_subtracted: plan.total_qkey_subtract,
        balance_before: balanceBefore,
        balance_after: balanceAfter
      }
    })
  } catch (error) {
    console.error('final-c-phase2-dedupe-may14 error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ FINAL-C 안전 분할 — Phase 3: 5/14 정상분 → 5/15 1:1 미러링 (멱등) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   처리: 5/14 paid_date 의 모든 daily_rewards + referral_rewards 를 5/15 로 복제
//         daily_rewards: reward_date='2026-05-15', paid_date='2026-05-15'
//         referral_rewards: reward_date 원본 유지, paid_date='2026-05-15'
//         각 INSERT 직후 transactions mirror + qkey_balance 가산
//   멱등 가드:
//     - daily_rewards: (user_id, staking_id, reward_date='2026-05-15') EXISTS skip
//     - referral_rewards: (referrer_id, referee_id, level, reward_amount, original_amount, reward_date, paid_date='2026-05-15') EXISTS skip
//   524 timeout 시 재호출 안전 — 이미 INSERT 된 행은 skip
//   batch_size 파라미터로 분할 처리 가능 (default 50, dr/rr 합산 기준)
app.post('/api/diag/final-c-phase3-mirror', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const dryRun = c.req.query('dry_run') === '1'
    const confirm = c.req.query('confirm') || ''
    if (!dryRun && confirm !== 'GO') {
      return c.json({ error: 'Missing confirm=GO (or use dry_run=1)' }, 400)
    }
    const batchSize = Math.max(1, Math.min(500, Number(c.req.query('batch_size') || '60')))
    const SRC = '2026-05-14'
    const DST = '2026-05-15'

    // 1) source 데이터 SELECT
    const srcDr = await db.prepare(`
      SELECT id, user_id, staking_id, usdt_amount, reward_date, paid_date
      FROM daily_rewards WHERE paid_date = ? ORDER BY id ASC
    `).bind(SRC).all()
    const srcDrRows = (srcDr.results || []) as any[]

    const srcRr = await db.prepare(`
      SELECT id, referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date
      FROM referral_rewards WHERE paid_date = ? ORDER BY id ASC
    `).bind(SRC).all()
    const srcRrRows = (srcRr.results || []) as any[]

    // 2) 각 행에 대해 EXISTS 검사
    type DrPlan = { src: any, action: 'insert' | 'skip_exists', existing_id?: number }
    type RrPlan = { src: any, action: 'insert' | 'skip_exists', existing_id?: number }
    const drPlan: DrPlan[] = []
    const rrPlan: RrPlan[] = []

    for (const r of srcDrRows) {
      const ex = await db.prepare(`
        SELECT id FROM daily_rewards WHERE user_id = ? AND staking_id = ? AND reward_date = ? LIMIT 1
      `).bind(r.user_id, r.staking_id, DST).first() as any
      drPlan.push({ src: r, action: ex ? 'skip_exists' : 'insert', existing_id: ex?.id })
    }
    for (const r of srcRrRows) {
      const ex = await db.prepare(`
        SELECT id FROM referral_rewards
        WHERE referrer_id = ? AND referee_id = ? AND level = ?
          AND reward_amount = ? AND COALESCE(original_amount, 0) = COALESCE(?, 0)
          AND reward_date = ? AND paid_date = ?
        LIMIT 1
      `).bind(r.referrer_id, r.referee_id, r.level, r.reward_amount, r.original_amount, r.reward_date, DST).first() as any
      rrPlan.push({ src: r, action: ex ? 'skip_exists' : 'insert', existing_id: ex?.id })
    }

    const drToInsert = drPlan.filter(p => p.action === 'insert')
    const rrToInsert = rrPlan.filter(p => p.action === 'insert')

    const planSummary = {
      src_dr_total: srcDrRows.length,
      src_rr_total: srcRrRows.length,
      dr_to_insert: drToInsert.length,
      dr_skip_exists: drPlan.length - drToInsert.length,
      rr_to_insert: rrToInsert.length,
      rr_skip_exists: rrPlan.length - rrToInsert.length,
      tx_to_insert: drToInsert.length + rrToInsert.length,
      qkey_balance_add_total:
        drToInsert.reduce((s, p) => s + Number(p.src.usdt_amount || 0), 0) +
        rrToInsert.reduce((s, p) => s + Number(p.src.reward_amount || 0), 0)
    }

    if (dryRun) {
      return c.json({ success: true, mode: 'DRY_RUN', message: '실제 실행을 원하시면 confirm=GO 추가', phase: 'phase3_mirror', batch_size: batchSize, plan: planSummary })
    }

    // 3) EXECUTE — batch_size 만큼만 처리 후 응답 (524 회피)
    let drInserted = 0, rrInserted = 0, txInserted = 0
    const balanceDeltas: Record<number, number> = {}
    const insertedDr: any[] = []
    const insertedRr: any[] = []
    let processedInBatch = 0

    // 3-1) daily_rewards 먼저
    for (const p of drToInsert) {
      if (processedInBatch >= batchSize) break
      const r = p.src
      // 다시 EXISTS (재호출 안전)
      const ex = await db.prepare(`
        SELECT id FROM daily_rewards WHERE user_id = ? AND staking_id = ? AND reward_date = ? LIMIT 1
      `).bind(r.user_id, r.staking_id, DST).first()
      if (ex) continue

      const ins = await db.prepare(`
        INSERT INTO daily_rewards (user_id, staking_id, usdt_amount, reward_date, paid_date)
        VALUES (?, ?, ?, ?, ?)
      `).bind(r.user_id, r.staking_id, r.usdt_amount, DST, DST).run()
      const newId = (ins as any)?.meta?.last_row_id
      if (!newId) continue
      drInserted++

      await db.prepare(`
        INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
        VALUES (?, 'daily_qkey', 'QKEY', ?, '일일 배당 (QKEY)', ?)
      `).bind(r.user_id, r.usdt_amount, newId).run()
      txInserted++

      await db.prepare('UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?')
        .bind(r.usdt_amount, r.user_id).run()

      const uid = Number(r.user_id)
      balanceDeltas[uid] = (balanceDeltas[uid] || 0) + Number(r.usdt_amount || 0)
      insertedDr.push({ src_id: r.id, new_id: newId, user_id: r.user_id, qkey: r.usdt_amount })
      processedInBatch++
    }

    // 3-2) referral_rewards
    for (const p of rrToInsert) {
      if (processedInBatch >= batchSize) break
      const r = p.src
      const ex = await db.prepare(`
        SELECT id FROM referral_rewards
        WHERE referrer_id = ? AND referee_id = ? AND level = ?
          AND reward_amount = ? AND COALESCE(original_amount, 0) = COALESCE(?, 0)
          AND reward_date = ? AND paid_date = ?
        LIMIT 1
      `).bind(r.referrer_id, r.referee_id, r.level, r.reward_amount, r.original_amount, r.reward_date, DST).first()
      if (ex) continue

      const ins = await db.prepare(`
        INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date)
        VALUES (?, ?, ?, ?, ?, ?, ?)
      `).bind(r.referrer_id, r.referee_id, r.level, r.original_amount, r.reward_amount, r.reward_date, DST).run()
      const newId = (ins as any)?.meta?.last_row_id
      if (!newId) continue
      rrInserted++

      const level = Number(r.level)
      const desc = level === 1 ? '추천 보너스 (Level 1)' : (level === 2 ? '추천 보너스 (Level 2)' : '추천 보너스')
      await db.prepare(`
        INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
        VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?)
      `).bind(r.referrer_id, r.reward_amount, desc, newId).run()
      txInserted++

      await db.prepare('UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?')
        .bind(r.reward_amount, r.referrer_id).run()

      const uid = Number(r.referrer_id)
      balanceDeltas[uid] = (balanceDeltas[uid] || 0) + Number(r.reward_amount || 0)
      insertedRr.push({ src_id: r.id, new_id: newId, referrer_id: r.referrer_id, level: r.level, qkey: r.reward_amount })
      processedInBatch++
    }

    const remainingDr = drToInsert.length - drInserted
    const remainingRr = rrToInsert.length - rrInserted - (drInserted < drToInsert.length ? rrToInsert.length : 0)
    const done = (drInserted === drToInsert.length) && (rrInserted === rrToInsert.length)

    return c.json({
      success: true,
      mode: 'EXECUTED',
      phase: 'phase3_mirror',
      batch_size: batchSize,
      result: {
        dr_inserted: drInserted,
        rr_inserted: rrInserted,
        tx_inserted: txInserted,
        balance_deltas: balanceDeltas,
        inserted_dr_sample: insertedDr.slice(0, 10),
        inserted_rr_sample: insertedRr.slice(0, 10)
      },
      progress: {
        dr_total_planned: drToInsert.length,
        rr_total_planned: rrToInsert.length,
        dr_inserted_this_call: drInserted,
        rr_inserted_this_call: rrInserted,
        all_done: done,
        next_action: done ? 'CALL_VERIFY' : 'RE_CALL_THIS_ENDPOINT_TO_CONTINUE'
      }
    })
  } catch (error) {
    console.error('final-c-phase3-mirror error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ 누락 배당 종합 진단 (사장님 2026-05-15 6차 지시) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   사장님 원문: "solbat 1대 1050/2대 1950 인데 덜 지급된거같다,
//                 bang8241 4000$ 0.5% 데일리 3000 QKEY 인데 5/12·5/13 미지급 + 마이너스 잔액"
//
//   진단 범위:
//     1. 모든 active staking 보유 회원의 5/12·5/13·5/14·5/15 일일배당(daily_rewards) 존재 여부
//        - staking.start_date <= 해당일 AND (end_date IS NULL OR end_date > 해당일) 조건
//        - 휴일 진입 첫평일 룰 적용 (5/11 부터 첫 평일 = 5/11 월요일)
//     2. 각 회원의 L1/L2 매칭 누락 여부 (하부 회원 데일리 vs 매칭 보너스 비교)
//     3. 잔액 마이너스 회원 전수 추출 + 누락 일자 진단
//
//   경로: GET /api/diag/missing-rewards-scan?key=ADMIN_PW&dates=2026-05-12,2026-05-13,2026-05-14,2026-05-15
app.get('/api/diag/missing-rewards-scan', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const datesParam = c.req.query('dates') || '2026-05-12,2026-05-13,2026-05-14,2026-05-15'
    const dates = datesParam.split(',').map(s => s.trim()).filter(Boolean)

    // ============================================================
    // 1) 모든 active staking 회원 + staking 정보
    // ============================================================
    const stakings = await db.prepare(`
      SELECT s.id AS staking_id, s.user_id, s.amount, s.daily_rate, s.start_date, s.end_date,
             u.email, u.name
      FROM staking s
      JOIN users u ON u.id = s.user_id
      WHERE s.status = 'active' OR s.status IS NULL OR s.status = ''
      ORDER BY s.user_id, s.id
    `).all<any>()

    // ============================================================
    // 2) 각 날짜별 누락된 daily_rewards 진단
    // ============================================================
    const missingDailyByDate: Record<string, any[]> = {}
    for (const dateStr of dates) {
      missingDailyByDate[dateStr] = []
      for (const s of (stakings.results || [])) {
        // staking 활성 여부 (start_date <= dateStr AND (end_date IS NULL OR end_date > dateStr))
        const start = (s.start_date || '').slice(0, 10)
        const end = (s.end_date || '').slice(0, 10)
        if (start > dateStr) continue
        if (end && end !== '' && end <= dateStr) continue

        // 휴일진입 첫평일 룰: 5/9(토)·5/10(일) 진입자는 5/11(월) 부터 데일리 시작
        // 5/12·5/13·5/14·5/15 는 모두 5/11 이후이므로 정상 평일이면 무조건 지급되어야 함
        // 단, 5/16(토)·5/17(일) 은 휴일이므로 스킵

        // 평일 체크 (KST 기준 dateStr 의 요일)
        const dt = new Date(dateStr + 'T12:00:00+09:00')
        const dow = dt.getUTCDay() // KST 정오 기준이므로 UTC day = KST day
        // 0=일, 6=토 = 휴일 (배당 안 함)
        if (dow === 0 || dow === 6) continue

        // 해당 일자에 daily_reward 존재하는지 체크
        const dr = await db.prepare(`
          SELECT id, usdt_amount FROM daily_rewards
          WHERE user_id = ? AND staking_id = ? AND reward_date = ?
          LIMIT 1
        `).bind(s.user_id, s.staking_id, dateStr).first<any>()

        if (!dr) {
          // 예상 일일배당 = amount × daily_rate × 150
          const expectedQkey = Math.round(Number(s.amount) * Number(s.daily_rate) * 150)
          missingDailyByDate[dateStr].push({
            user_id: s.user_id,
            email: s.email,
            name: s.name,
            staking_id: s.staking_id,
            amount: s.amount,
            daily_rate: s.daily_rate,
            start_date: s.start_date,
            expected_qkey: expectedQkey
          })
        }
      }
    }

    // ============================================================
    // 3) 마이너스 잔액 회원 전수 추출
    // ============================================================
    const negBalanceUsers = await db.prepare(`
      SELECT id, email, name, qkey_balance
      FROM users
      WHERE qkey_balance < 0
      ORDER BY qkey_balance ASC
    `).all<any>()

    // ============================================================
    // 4) L1/L2 매칭 누락 진단 (각 날짜별)
    //    각 referrer 에 대해: 하부(L1/L2) 데일리 합 × 0.20 / 0.10 vs 실제 referral_rewards 합 비교
    // ============================================================
    const missingMatchingByDate: Record<string, any[]> = {}
    for (const dateStr of dates) {
      missingMatchingByDate[dateStr] = []

      // 평일만
      const dt = new Date(dateStr + 'T12:00:00+09:00')
      const dow = dt.getUTCDay()
      if (dow === 0 || dow === 6) continue

      // 모든 referrer (즉 다른 회원의 referrer_id 로 등록된 회원) 추출
      const referrers = await db.prepare(`
        SELECT DISTINCT u.id, u.email, u.name
        FROM users u
        WHERE EXISTS (SELECT 1 FROM users u2 WHERE u2.referrer_id = u.id)
        ORDER BY u.id
      `).all<any>()

      for (const r of (referrers.results || [])) {
        const referrerId = r.id

        // L1 산하 회원들의 dateStr 일일배당 합
        const l1DailySum = await db.prepare(`
          SELECT COALESCE(SUM(dr.usdt_amount), 0) AS sum_qkey
          FROM daily_rewards dr
          JOIN users u ON u.id = dr.user_id
          WHERE u.referrer_id = ? AND dr.reward_date = ?
        `).bind(referrerId, dateStr).first<any>()

        // L2 산하 회원들의 dateStr 일일배당 합 (referrer 의 손자)
        const l2DailySum = await db.prepare(`
          SELECT COALESCE(SUM(dr.usdt_amount), 0) AS sum_qkey
          FROM daily_rewards dr
          JOIN users u ON u.id = dr.user_id
          JOIN users p ON p.id = u.referrer_id
          WHERE p.referrer_id = ? AND dr.reward_date = ?
        `).bind(referrerId, dateStr).first<any>()

        const expectedL1 = Math.round(Number(l1DailySum?.sum_qkey || 0) * 0.20)
        const expectedL2 = Math.round(Number(l2DailySum?.sum_qkey || 0) * 0.10)

        // 실제 referral_rewards 합 (reward_date = dateStr 기준)
        const actualL1 = await db.prepare(`
          SELECT COALESCE(SUM(reward_amount), 0) AS sum_qkey
          FROM referral_rewards
          WHERE referrer_id = ? AND level = 1 AND reward_date = ?
        `).bind(referrerId, dateStr).first<any>()

        const actualL2 = await db.prepare(`
          SELECT COALESCE(SUM(reward_amount), 0) AS sum_qkey
          FROM referral_rewards
          WHERE referrer_id = ? AND level = 2 AND reward_date = ?
        `).bind(referrerId, dateStr).first<any>()

        const l1Diff = expectedL1 - Number(actualL1?.sum_qkey || 0)
        const l2Diff = expectedL2 - Number(actualL2?.sum_qkey || 0)

        if (l1Diff !== 0 || l2Diff !== 0) {
          missingMatchingByDate[dateStr].push({
            referrer_id: referrerId,
            email: r.email,
            name: r.name,
            l1_subordinate_daily_sum: Number(l1DailySum?.sum_qkey || 0),
            l2_subordinate_daily_sum: Number(l2DailySum?.sum_qkey || 0),
            l1_expected: expectedL1,
            l1_actual: Number(actualL1?.sum_qkey || 0),
            l1_diff: l1Diff,
            l2_expected: expectedL2,
            l2_actual: Number(actualL2?.sum_qkey || 0),
            l2_diff: l2Diff
          })
        }
      }
    }

    // ============================================================
    // 5) 요약
    // ============================================================
    const summary: Record<string, any> = {}
    for (const dateStr of dates) {
      summary[dateStr] = {
        missing_daily_count: missingDailyByDate[dateStr].length,
        missing_daily_total_qkey: missingDailyByDate[dateStr].reduce((acc, x) => acc + x.expected_qkey, 0),
        missing_matching_count: (missingMatchingByDate[dateStr] || []).length,
        missing_matching_total_qkey: (missingMatchingByDate[dateStr] || []).reduce((acc, x) => acc + Math.max(0, x.l1_diff) + Math.max(0, x.l2_diff), 0)
      }
    }

    return c.json({
      success: true,
      dates_scanned: dates,
      summary,
      missing_daily_by_date: missingDailyByDate,
      missing_matching_by_date: missingMatchingByDate,
      negative_balance_users: negBalanceUsers.results || []
    })
  } catch (error) {
    console.error('missing-rewards-scan error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ 5/15 transactions 전수 무결성 진단 (사장님 2026-05-15 결재) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   사장님 원문: "solbat 1대가 1050 2대가 1950 발생되어야 하는데 배당금은 두번발생되고, 일일배당 두번씩 중복 지급되었다"
//
//   진단 목적: 5/15 transactions 중 다음 이상 패턴 전수 추출
//     A. 동일 user + 동일 type (daily_qkey) 가 5/15 created_at 에 2건 이상 (일일배당 중복)
//     B. transactions.ref_id 가 daily_rewards / referral_rewards 에 존재하지 않음 (orphan tx)
//     C. transactions.ref_id 가 다른 paid_date 의 row 를 가리킴 (cross-date reference)
//     D. user 단위로 5/15 daily_qkey tx 합 vs daily_rewards.usdt_amount 합 비교
//
//   경로: GET /api/diag/scan-may15-tx-integrity?key=ADMIN_PW
app.get('/api/diag/scan-may15-tx-integrity', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const PAID_DATE = '2026-05-15'

    // ============================================================
    // 1) 5/15 transactions (daily_qkey + referral_reward) 전부 조회
    // ============================================================
    const txRows = await db.prepare(`
      SELECT id, user_id, type, amount, ref_id, description, created_at, DATE(created_at) as tx_date
      FROM transactions
      WHERE DATE(created_at) = ? AND type IN ('daily_qkey', 'referral_reward')
      ORDER BY user_id ASC, type ASC, id ASC
    `).bind(PAID_DATE).all()
    const txList = (txRows.results || []) as any[]

    // ============================================================
    // 2) 5/15 daily_rewards / referral_rewards 전부 조회
    // ============================================================
    const drRows = await db.prepare(`
      SELECT id, user_id, staking_id, usdt_amount, reward_date, paid_date, created_at
      FROM daily_rewards WHERE paid_date = ?
    `).bind(PAID_DATE).all()
    const drList = (drRows.results || []) as any[]
    const drById: Record<number, any> = {}
    for (const r of drList) drById[Number(r.id)] = r

    const rrRows = await db.prepare(`
      SELECT id, referrer_id, referee_id, level, reward_amount, reward_date, paid_date, created_at
      FROM referral_rewards WHERE paid_date = ?
    `).bind(PAID_DATE).all()
    const rrList = (rrRows.results || []) as any[]
    const rrById: Record<number, any> = {}
    for (const r of rrList) rrById[Number(r.id)] = r

    // 다른 paid_date 의 row 도 참조 가능성 (cross-date) — ref_id 가 어디든 있는지 확인용
    // 단순히 전체 daily_rewards / referral_rewards 의 id 집합만 가지면 됨
    const drAnyDate = await db.prepare(`SELECT id, paid_date FROM daily_rewards`).all()
    const drAnyById: Record<number, string> = {}
    for (const r of (drAnyDate.results || []) as any[]) drAnyById[Number(r.id)] = String(r.paid_date)
    const rrAnyDate = await db.prepare(`SELECT id, paid_date FROM referral_rewards`).all()
    const rrAnyById: Record<number, string> = {}
    for (const r of (rrAnyDate.results || []) as any[]) rrAnyById[Number(r.id)] = String(r.paid_date)

    // ============================================================
    // 3) 패턴 A — 동일 user + daily_qkey 가 2건 이상
    // ============================================================
    const dailyByUser: Record<number, any[]> = {}
    for (const t of txList) {
      if (t.type !== 'daily_qkey') continue
      const uid = Number(t.user_id)
      if (!dailyByUser[uid]) dailyByUser[uid] = []
      dailyByUser[uid].push(t)
    }
    const patternA_dailyDup: any[] = []
    for (const [uid, rows] of Object.entries(dailyByUser)) {
      if (rows.length > 1) {
        patternA_dailyDup.push({
          user_id: Number(uid),
          tx_count: rows.length,
          total_amount: rows.reduce((s, r) => s + Number(r.amount || 0), 0),
          rows: rows.map(r => ({
            tx_id: r.id, amount: r.amount, ref_id: r.ref_id, created_at: r.created_at,
            ref_dr_paid_date: drAnyById[Number(r.ref_id)] ?? null,
            ref_exists_in_dr: drAnyById[Number(r.ref_id)] !== undefined,
            ref_in_may15_dr: drById[Number(r.ref_id)] !== undefined
          }))
        })
      }
    }

    // ============================================================
    // 4) 패턴 B/C — transactions.ref_id 가 5/15 daily_rewards/referral_rewards 에 없음
    // ============================================================
    const patternB_orphanDailyTx: any[] = []
    const patternB_orphanReferralTx: any[] = []
    const patternC_crossDateRef: any[] = []

    for (const t of txList) {
      const refId = Number(t.ref_id || 0)
      if (t.type === 'daily_qkey') {
        if (!drById[refId]) {
          // 5/15 daily_rewards 에 없음
          const otherPaidDate = drAnyById[refId]
          if (otherPaidDate) {
            patternC_crossDateRef.push({
              tx_id: t.id, user_id: t.user_id, type: 'daily_qkey', amount: t.amount,
              ref_id: refId, ref_actual_paid_date: otherPaidDate,
              created_at: t.created_at
            })
          } else {
            patternB_orphanDailyTx.push({
              tx_id: t.id, user_id: t.user_id, amount: t.amount,
              ref_id: refId, created_at: t.created_at
            })
          }
        }
      } else if (t.type === 'referral_reward') {
        if (!rrById[refId]) {
          const otherPaidDate = rrAnyById[refId]
          if (otherPaidDate) {
            patternC_crossDateRef.push({
              tx_id: t.id, user_id: t.user_id, type: 'referral_reward', amount: t.amount,
              ref_id: refId, ref_actual_paid_date: otherPaidDate,
              created_at: t.created_at
            })
          } else {
            patternB_orphanReferralTx.push({
              tx_id: t.id, user_id: t.user_id, amount: t.amount,
              ref_id: refId, created_at: t.created_at
            })
          }
        }
      }
    }

    // ============================================================
    // 5) 패턴 D — user 단위 tx 합 vs daily_rewards/referral_rewards 합 비교
    // ============================================================
    const txDailySumByUser: Record<number, number> = {}
    const txReferralSumByUser: Record<number, number> = {}
    for (const t of txList) {
      const uid = Number(t.user_id)
      if (t.type === 'daily_qkey') txDailySumByUser[uid] = (txDailySumByUser[uid] || 0) + Number(t.amount || 0)
      if (t.type === 'referral_reward') txReferralSumByUser[uid] = (txReferralSumByUser[uid] || 0) + Number(t.amount || 0)
    }
    const drSumByUser: Record<number, number> = {}
    for (const r of drList) {
      const uid = Number(r.user_id)
      drSumByUser[uid] = (drSumByUser[uid] || 0) + Number(r.usdt_amount || 0)
    }
    const rrSumByUser: Record<number, number> = {}
    for (const r of rrList) {
      const uid = Number(r.referrer_id)
      rrSumByUser[uid] = (rrSumByUser[uid] || 0) + Number(r.reward_amount || 0)
    }
    const allUids = new Set<number>([
      ...Object.keys(txDailySumByUser).map(Number),
      ...Object.keys(txReferralSumByUser).map(Number),
      ...Object.keys(drSumByUser).map(Number),
      ...Object.keys(rrSumByUser).map(Number)
    ])
    const patternD_mismatch: any[] = []
    for (const uid of allUids) {
      const txDaily = txDailySumByUser[uid] || 0
      const txReferral = txReferralSumByUser[uid] || 0
      const drSum = drSumByUser[uid] || 0
      const rrSum = rrSumByUser[uid] || 0
      const dailyDiff = txDaily - drSum
      const referralDiff = txReferral - rrSum
      if (dailyDiff !== 0 || referralDiff !== 0) {
        patternD_mismatch.push({
          user_id: uid,
          tx_daily_sum: txDaily, dr_sum: drSum, daily_diff: dailyDiff,
          tx_referral_sum: txReferral, rr_sum: rrSum, referral_diff: referralDiff,
          total_balance_excess: dailyDiff + referralDiff
        })
      }
    }
    patternD_mismatch.sort((a, b) => b.total_balance_excess - a.total_balance_excess)

    return c.json({
      success: true,
      paid_date: PAID_DATE,
      summary: {
        total_tx_rows: txList.length,
        total_dr_rows: drList.length,
        total_rr_rows: rrList.length,
        pattern_A_users_with_duplicate_daily_tx: patternA_dailyDup.length,
        pattern_A_total_excess_qkey: patternA_dailyDup.reduce((s, u) => {
          // excess = (rows count - 1) * row amount, assume same amount per row
          return s + Number(u.rows[0]?.amount || 0) * (u.tx_count - 1)
        }, 0),
        pattern_B_orphan_daily_tx_count: patternB_orphanDailyTx.length,
        pattern_B_orphan_referral_tx_count: patternB_orphanReferralTx.length,
        pattern_C_cross_date_ref_count: patternC_crossDateRef.length,
        pattern_D_user_mismatch_count: patternD_mismatch.length,
        pattern_D_total_balance_excess: patternD_mismatch.reduce((s, u) => s + Number(u.total_balance_excess || 0), 0)
      },
      pattern_A_daily_tx_duplicates: patternA_dailyDup,
      pattern_B_orphan_daily_tx: patternB_orphanDailyTx,
      pattern_B_orphan_referral_tx: patternB_orphanReferralTx,
      pattern_C_cross_date_refs: patternC_crossDateRef,
      pattern_D_user_mismatches: patternD_mismatch
    })
  } catch (error) {
    console.error('scan-may15-tx-integrity error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ 특정 회원 paid_date 전수 조사 (사장님 2026-05-15 결재) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   사장님 원문: "예로 solbat 1대가 1050 2대가 1950 발생되어야 하는데 배당금은 두번발생되고, 일일배당 두번씩 중복 지급되었다"
//
//   처리: 특정 user_id 와 paid_date 에 대해
//     - daily_rewards 전체 행 (reward_date 별 그룹)
//     - referral_rewards 전체 행 (referrer 입장 + referee 입장)
//     - transactions 전체 행 (type='daily_qkey' / 'referral_reward')
//     - 합계 계산 (own / L1 / L2 / total)
//   를 상세 출력하여 중복 여부를 한눈에 식별
//
//   경로: GET /api/diag/user-paid-date-detail?key=ADMIN_PW&user_id=44&paid_date=2026-05-15
app.get('/api/diag/user-paid-date-detail', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const userId = Number(c.req.query('user_id') || '0')
    const paidDate = c.req.query('paid_date') || ''
    const email = c.req.query('email') || ''
    if (!paidDate) return c.json({ error: 'paid_date required (YYYY-MM-DD)' }, 400)
    const db = c.env.DB

    let uid = userId
    if (!uid && email) {
      const u = await db.prepare('SELECT id FROM users WHERE email = ?').bind(email).first() as any
      if (u) uid = Number(u.id)
    }
    if (!uid) return c.json({ error: 'user_id or email required' }, 400)

    const userRow = await db.prepare('SELECT id, name, email, qkey_balance FROM users WHERE id = ?').bind(uid).first()

    // 1) daily_rewards on this paid_date
    const drRows = await db.prepare(`
      SELECT id, user_id, staking_id, usdt_amount, reward_date, paid_date, created_at
      FROM daily_rewards WHERE user_id = ? AND paid_date = ?
      ORDER BY reward_date ASC, id ASC
    `).bind(uid, paidDate).all()
    const drList = (drRows.results || []) as any[]
    const drByRewardDate: Record<string, any[]> = {}
    for (const r of drList) {
      const k = String(r.reward_date)
      if (!drByRewardDate[k]) drByRewardDate[k] = []
      drByRewardDate[k].push(r)
    }
    const drDupes: any[] = []
    for (const [rd, rows] of Object.entries(drByRewardDate)) {
      if (rows.length > 1) {
        drDupes.push({
          reward_date: rd,
          count: rows.length,
          rows: rows.map(r => ({ id: r.id, staking_id: r.staking_id, qkey: r.usdt_amount, created_at: r.created_at }))
        })
      }
    }
    const drTotal = drList.reduce((s, r) => s + Number(r.usdt_amount || 0), 0)

    // 2) referral_rewards on this paid_date — as referrer (receiving)
    const rrRcv = await db.prepare(`
      SELECT id, referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, created_at
      FROM referral_rewards WHERE referrer_id = ? AND paid_date = ?
      ORDER BY level ASC, reward_date ASC, id ASC
    `).bind(uid, paidDate).all()
    const rrRcvList = (rrRcv.results || []) as any[]
    // L1, L2 합계 + 중복 그룹
    const rrByKey: Record<string, any[]> = {}
    for (const r of rrRcvList) {
      const k = `${r.referee_id}|${r.level}|${r.reward_date}`
      if (!rrByKey[k]) rrByKey[k] = []
      rrByKey[k].push(r)
    }
    const rrDupes: any[] = []
    for (const [k, rows] of Object.entries(rrByKey)) {
      if (rows.length > 1) {
        const [refereeId, level, rd] = k.split('|')
        rrDupes.push({
          referee_id: Number(refereeId),
          level: Number(level),
          reward_date: rd,
          count: rows.length,
          rows: rows.map(r => ({ id: r.id, original_amount: r.original_amount, reward_amount: r.reward_amount, created_at: r.created_at }))
        })
      }
    }
    const l1Total = rrRcvList.filter(r => Number(r.level) === 1).reduce((s, r) => s + Number(r.reward_amount || 0), 0)
    const l2Total = rrRcvList.filter(r => Number(r.level) === 2).reduce((s, r) => s + Number(r.reward_amount || 0), 0)

    // 3) referral_rewards on this paid_date — as referee (someone else got bonus FROM this user's daily)
    const rrAsReferee = await db.prepare(`
      SELECT id, referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, created_at
      FROM referral_rewards WHERE referee_id = ? AND paid_date = ?
      ORDER BY level ASC, reward_date ASC, id ASC
    `).bind(uid, paidDate).all()

    // 4) transactions on this paid_date (DATE(created_at) ≈ paid_date)
    const txRows = await db.prepare(`
      SELECT id, user_id, type, coin_type, amount, description, ref_id, created_at, DATE(created_at) as tx_date
      FROM transactions WHERE user_id = ? AND DATE(created_at) = ?
        AND type IN ('daily_qkey', 'referral_reward')
      ORDER BY created_at ASC, id ASC
    `).bind(uid, paidDate).all()
    const txList = (txRows.results || []) as any[]
    // Group by type+ref_id to find duplicates
    const txByKey: Record<string, any[]> = {}
    for (const t of txList) {
      const k = `${t.type}|${t.ref_id}`
      if (!txByKey[k]) txByKey[k] = []
      txByKey[k].push(t)
    }
    const txDupes: any[] = []
    for (const [k, rows] of Object.entries(txByKey)) {
      if (rows.length > 1) {
        const [type, refId] = k.split('|')
        txDupes.push({ type, ref_id: refId, count: rows.length, rows })
      }
    }
    const txDailySum = txList.filter(t => t.type === 'daily_qkey').reduce((s, t) => s + Number(t.amount || 0), 0)
    const txReferralSum = txList.filter(t => t.type === 'referral_reward').reduce((s, t) => s + Number(t.amount || 0), 0)

    return c.json({
      success: true,
      user: userRow,
      paid_date: paidDate,
      summary: {
        daily_rewards: { row_count: drList.length, qkey_total: drTotal, distinct_reward_dates: Object.keys(drByRewardDate).length, duplicate_groups: drDupes.length },
        referral_rewards_received: { row_count: rrRcvList.length, l1_qkey_total: l1Total, l2_qkey_total: l2Total, duplicate_groups: rrDupes.length },
        referral_rewards_as_referee: { row_count: (rrAsReferee.results || []).length },
        transactions: { row_count: txList.length, daily_qkey_sum: txDailySum, referral_reward_sum: txReferralSum, duplicate_groups: txDupes.length },
        grand_total_qkey_credited: drTotal + l1Total + l2Total
      },
      duplicates_found: {
        daily_rewards: drDupes,
        referral_rewards: rrDupes,
        transactions: txDupes
      },
      raw: {
        daily_rewards: drList,
        referral_rewards_received: rrRcvList,
        referral_rewards_as_referee: rrAsReferee.results || [],
        transactions: txList
      }
    })
  } catch (error) {
    console.error('user-paid-date-detail error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ 사용자 전체 staking + 일자별 daily_rewards 매트릭스 (사장님 2026-05-15 7차 결재) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   사장님 원문: "bang8241 case 가장 오류나기 쉽다. 1000$ 리셋 후 휴일 추가 4000$.
//                 5/11 정상, 5/12·5/13 4000$건 누락, 5/14·5/15 다시 정상"
//
//   진단 목적: 한 회원의 모든 staking (active + closed) × 일자별 daily_rewards 매트릭스 확인
//             특히 같은 user_id 가 staking_id 별로 각각 데일리 받았는지 검증
//
//   경로: GET /api/diag/user-staking-matrix?key=ADMIN_PW&email=bang8241&dates=2026-05-11,2026-05-12,2026-05-13,2026-05-14,2026-05-15
//   또는 user_id=33 로도 조회 가능
app.get('/api/diag/user-staking-matrix-v2', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const email = c.req.query('email') || ''
    const userIdParam = c.req.query('user_id') || ''
    const datesParam = c.req.query('dates') || '2026-05-11,2026-05-12,2026-05-13,2026-05-14,2026-05-15'
    const dates = datesParam.split(',').map(s => s.trim()).filter(Boolean)

    // user 조회
    let user: any = null
    if (userIdParam) {
      user = await db.prepare(`SELECT id, email, name, qkey_balance FROM users WHERE id = ?`).bind(parseInt(userIdParam)).first()
    } else if (email) {
      user = await db.prepare(`SELECT id, email, name, qkey_balance FROM users WHERE email = ?`).bind(email).first()
    }
    if (!user) return c.json({ error: 'user not found', email, user_id: userIdParam }, 404)

    // 모든 staking (active + closed) — 확정 컬럼만 SELECT
    const stakings = await db.prepare(`
      SELECT id, user_id, amount, daily_rate, period_days, period_months,
             qta_reward, qx_reward, qkey_reward,
             start_date, end_date, status, txid, reset_at, created_at
      FROM staking
      WHERE user_id = ?
      ORDER BY id ASC
    `).bind(user.id).all<any>()

    // 일자별 × staking_id 별 daily_rewards 매트릭스
    const matrix: Record<string, Record<number, any>> = {}
    for (const dateStr of dates) {
      matrix[dateStr] = {}
      for (const s of (stakings.results || [])) {
        const dr = await db.prepare(`
          SELECT id, usdt_amount, reward_date, paid_date, created_at
          FROM daily_rewards
          WHERE user_id = ? AND staking_id = ? AND reward_date = ?
        `).bind(user.id, s.id, dateStr).all<any>()

        // staking 활성 여부 (해당 일자에 active 였는지)
        const start = (s.start_date || '').slice(0, 10)
        const end = (s.end_date || '').slice(0, 10)
        const wasActive = start <= dateStr && (!end || end === '' || end > dateStr)

        // 평일 여부 (KST 정오 기준)
        const dt = new Date(dateStr + 'T12:00:00+09:00')
        const dow = dt.getUTCDay() // 0=일, 6=토
        const isWeekday = dow !== 0 && dow !== 6

        const expectedQkey = Math.round(Number(s.amount) * Number(s.daily_rate) * 150)
        const actualQkey = (dr.results || []).reduce((acc: number, r: any) => acc + Number(r.usdt_amount || 0), 0)

        matrix[dateStr][s.id] = {
          staking_id: s.id,
          amount: s.amount,
          daily_rate: s.daily_rate,
          status: s.status,
          start_date: s.start_date,
          end_date: s.end_date,
          was_active_on_date: wasActive,
          is_weekday: isWeekday,
          should_be_paid: wasActive && isWeekday,
          expected_qkey: expectedQkey,
          actual_qkey: actualQkey,
          dr_row_count: (dr.results || []).length,
          dr_rows: dr.results || [],
          status_label: wasActive && isWeekday
            ? (actualQkey === 0 ? 'MISSING' : (actualQkey === expectedQkey ? 'OK' : (actualQkey > expectedQkey ? 'OVERPAID' : 'PARTIAL')))
            : 'N/A'
        }
      }
    }

    // 일자별 합계
    const dailySummary: Record<string, any> = {}
    for (const dateStr of dates) {
      let expectedSum = 0
      let actualSum = 0
      let missingStakings: number[] = []
      for (const s of (stakings.results || [])) {
        const cell = matrix[dateStr][s.id]
        if (cell.should_be_paid) {
          expectedSum += cell.expected_qkey
          actualSum += cell.actual_qkey
          if (cell.status_label === 'MISSING') missingStakings.push(s.id)
        }
      }
      dailySummary[dateStr] = {
        expected_total: expectedSum,
        actual_total: actualSum,
        diff: expectedSum - actualSum,
        missing_staking_ids: missingStakings
      }
    }

    // transactions 5/11 ~ 5/15 daily_qkey 만 추출 (참고용)
    const txDaily = await db.prepare(`
      SELECT id, user_id, amount, ref_id, description, created_at
      FROM transactions
      WHERE user_id = ?
        AND type = 'daily_qkey'
        AND DATE(created_at) >= '2026-05-11'
        AND DATE(created_at) <= '2026-05-15'
      ORDER BY created_at ASC
    `).bind(user.id).all<any>()

    return c.json({
      success: true,
      user,
      stakings_count: (stakings.results || []).length,
      stakings: stakings.results || [],
      dates_scanned: dates,
      daily_summary: dailySummary,
      matrix,
      transactions_daily_5_11_to_5_15: txDaily.results || []
    })
  } catch (error) {
    console.error('user-staking-matrix error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ daily_rewards 있는데 transactions 없는 case 전수 스캔 (사장님 2026-05-15 8차 결재) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   목적: bang8241 처럼 dr 행은 있는데 tx 행이 없는 case 전수 발굴
//   원리: dr 와 tx 의 left join, tx.id IS NULL 인 dr 만 추출
//
//   경로: GET /api/diag/scan-dr-without-tx?key=ADMIN_PW&date_from=2026-05-11&date_to=2026-05-15
app.get('/api/diag/scan-dr-without-tx', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const dateFrom = c.req.query('date_from') || '2026-05-11'
    const dateTo = c.req.query('date_to') || '2026-05-15'

    // daily_rewards 있는데 type='daily_qkey' AND ref_id=dr.id 인 transactions 가 없는 행 모두 추출
    const rows = await db.prepare(`
      SELECT dr.id AS dr_id, dr.user_id, dr.staking_id, dr.usdt_amount AS qkey, dr.reward_date, dr.paid_date, dr.created_at AS dr_created,
             u.email, u.name, u.qkey_balance,
             s.amount AS staking_amount, s.daily_rate, s.status AS staking_status
      FROM daily_rewards dr
      JOIN users u ON u.id = dr.user_id
      LEFT JOIN staking s ON s.id = dr.staking_id
      LEFT JOIN transactions tx
        ON tx.user_id = dr.user_id
        AND tx.type = 'daily_qkey'
        AND tx.ref_id = dr.id
      WHERE dr.reward_date >= ? AND dr.reward_date <= ?
        AND tx.id IS NULL
      ORDER BY dr.user_id, dr.reward_date, dr.staking_id
    `).bind(dateFrom, dateTo).all<any>()

    // 사용자별 집계
    const byUser: Record<string, any> = {}
    for (const r of (rows.results || [])) {
      const k = String(r.user_id)
      if (!byUser[k]) {
        byUser[k] = {
          user_id: r.user_id, email: r.email, name: r.name, qkey_balance: r.qkey_balance,
          total_missing_qkey: 0, missing_count: 0, items: []
        }
      }
      byUser[k].total_missing_qkey += Number(r.qkey || 0)
      byUser[k].missing_count += 1
      byUser[k].items.push({
        dr_id: r.dr_id, staking_id: r.staking_id, staking_amount: r.staking_amount,
        daily_rate: r.daily_rate, staking_status: r.staking_status,
        qkey: r.qkey, reward_date: r.reward_date, paid_date: r.paid_date, dr_created: r.dr_created
      })
    }

    const userList = Object.values(byUser).sort((a: any, b: any) => b.total_missing_qkey - a.total_missing_qkey)
    const totalMissing = userList.reduce((acc: number, u: any) => acc + u.total_missing_qkey, 0)

    return c.json({
      success: true,
      date_from: dateFrom,
      date_to: dateTo,
      total_dr_without_tx_count: (rows.results || []).length,
      total_missing_qkey: totalMissing,
      affected_users_count: userList.length,
      affected_users: userList
    })
  } catch (error) {
    console.error('scan-dr-without-tx error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ 단일 회원 단일 staking 단일 일자 정밀 tx 백필 (사장님 2026-05-15 8차 결재) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   목적: bang8241 (user 33) 5/12·5/13 staking 97 dr 행은 있는데 tx 누락 보정 같은 케이스
//   안전: 단일 회원·단일 staking·단일 일자 명시 (전수 적용 금지)
//        EXISTS guard 로 재호출 안전
//        다른 회원·다른 staking·다른 일자 절대 0건 영향
//
//   경로: POST /api/diag/fix-tx-for-dr?key=ADMIN_PW&user_id=33&staking_id=97&dates=2026-05-12,2026-05-13&dry_run=1
//        실행: confirm=GO 추가
app.post('/api/diag/fix-tx-for-dr', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const userId = parseInt(c.req.query('user_id') || '0')
    const stakingIdParam = c.req.query('staking_id') || ''
    const datesParam = c.req.query('dates') || ''
    const dryRun = c.req.query('dry_run') === '1'
    const confirm = c.req.query('confirm') || ''

    if (!userId) return c.json({ error: 'user_id required' }, 400)
    if (!datesParam) return c.json({ error: 'dates required (comma-separated)' }, 400)

    const dates = datesParam.split(',').map(s => s.trim()).filter(Boolean)
    const stakingId = stakingIdParam ? parseInt(stakingIdParam) : null

    // user 확인
    const user = await db.prepare(`SELECT id, email, name, qkey_balance FROM users WHERE id = ?`).bind(userId).first<any>()
    if (!user) return c.json({ error: 'user not found', user_id: userId }, 404)

    // dr 행 + tx 존재 여부 조회
    const plan: any[] = []
    let totalToAdd = 0

    for (const dateStr of dates) {
      let drQuery = `
        SELECT dr.id AS dr_id, dr.user_id, dr.staking_id, dr.usdt_amount AS qkey,
               dr.reward_date, dr.paid_date, dr.created_at AS dr_created
        FROM daily_rewards dr
        WHERE dr.user_id = ? AND dr.reward_date = ?
      `
      const binds: any[] = [userId, dateStr]
      if (stakingId !== null) {
        drQuery += ` AND dr.staking_id = ?`
        binds.push(stakingId)
      }
      drQuery += ` ORDER BY dr.staking_id, dr.id`

      const drRows = await db.prepare(drQuery).bind(...binds).all<any>()

      for (const dr of (drRows.results || [])) {
        // 해당 dr.id 를 ref_id 로 하는 daily_qkey tx 존재?
        const existingTx = await db.prepare(`
          SELECT id, amount FROM transactions
          WHERE user_id = ? AND type = 'daily_qkey' AND ref_id = ?
          LIMIT 1
        `).bind(userId, dr.dr_id).first<any>()

        if (existingTx) {
          plan.push({
            action: 'SKIP_TX_EXISTS',
            dr_id: dr.dr_id, staking_id: dr.staking_id, reward_date: dr.reward_date,
            qkey: dr.qkey, existing_tx_id: existingTx.id
          })
        } else {
          plan.push({
            action: 'INSERT_TX',
            dr_id: dr.dr_id, staking_id: dr.staking_id, reward_date: dr.reward_date,
            qkey: dr.qkey, paid_date: dr.paid_date
          })
          totalToAdd += Number(dr.qkey || 0)
        }
      }
    }

    if (dryRun || confirm !== 'GO') {
      return c.json({
        success: true,
        mode: 'DRY_RUN',
        message: '실제 실행을 원하시면 confirm=GO 추가',
        user: { id: user.id, email: user.email, name: user.name, qkey_balance_before: user.qkey_balance },
        target: { user_id: userId, staking_id: stakingId, dates },
        plan,
        plan_summary: {
          to_insert_tx_count: plan.filter(p => p.action === 'INSERT_TX').length,
          to_skip_count: plan.filter(p => p.action === 'SKIP_TX_EXISTS').length,
          qkey_to_add: totalToAdd,
          qkey_balance_after: user.qkey_balance + totalToAdd
        }
      })
    }

    // EXECUTE
    let insertedTxIds: number[] = []
    let actualAdded = 0
    for (const item of plan) {
      if (item.action === 'INSERT_TX') {
        // INSERT transactions
        // description: 영구룰 — '일일 배당 (QKEY)' 만 사용 (변수 보간 0건)
        const ins = await db.prepare(`
          INSERT INTO transactions (user_id, type, amount, coin_type, description, ref_id, created_at)
          VALUES (?, 'daily_qkey', ?, 'QKEY', '일일 배당 (QKEY)', ?, datetime('now'))
        `).bind(userId, item.qkey, item.dr_id).run()

        const newTxId = (ins as any).meta?.last_row_id || null
        if (newTxId) insertedTxIds.push(newTxId)
        actualAdded += Number(item.qkey || 0)
      }
    }

    // users.qkey_balance += actualAdded
    if (actualAdded > 0) {
      await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(actualAdded, userId).run()
    }

    // 최종 잔액 조회
    const userAfter = await db.prepare(`SELECT qkey_balance FROM users WHERE id = ?`).bind(userId).first<any>()

    return c.json({
      success: true,
      mode: 'EXECUTED',
      user: { id: user.id, email: user.email, name: user.name,
              qkey_balance_before: user.qkey_balance,
              qkey_balance_after: userAfter?.qkey_balance || null },
      target: { user_id: userId, staking_id: stakingId, dates },
      plan,
      result: {
        inserted_tx_count: insertedTxIds.length,
        inserted_tx_ids: insertedTxIds,
        skipped_count: plan.filter(p => p.action === 'SKIP_TX_EXISTS').length,
        qkey_added: actualAdded
      }
    })
  } catch (error) {
    console.error('fix-tx-for-dr error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ fix-tx-created-at: 단일 사용자 한정, 특정 tx_id 들의 created_at 만 UPDATE (날짜 시각 보정) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   목적: fix-tx-for-dr 로 INSERT된 tx 들이 created_at='now()' 로 박혀
//        거래내역 화면에 오늘 여러건 표시되는 시각적 혼란 해결
//   안전성:
//     - amount/type/ref_id/description/coin_type 일체 손대지 않음 (UPDATE created_at만)
//     - tx_id 와 expected_user_id 일치 확인 후만 진행 (다른 사용자 영향 0)
//     - tx_id 와 expected_ref_id (dr_id) 일치 확인 후만 진행 (잘못된 tx 보정 방지)
//     - DRY_RUN 기본 / confirm=GO 명시시만 실행
//   경로 (POST):
//     /api/diag/fix-tx-created-at?key=ADMIN_PW
//        &user_id=33
//        &mappings=4333:2026-05-11 22:08:37,4334:2026-05-12 13:17:41,4335:2026-05-13 02:58:22
//        &expected_refs=4333:306,4334:510,4335:569
//        &dry_run=1   (또는 confirm=GO)
app.post('/api/diag/fix-tx-created-at', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const userId = parseInt(c.req.query('user_id') || '0')
    const mappingsParam = c.req.query('mappings') || ''
    const expectedRefsParam = c.req.query('expected_refs') || ''
    const dryRun = c.req.query('dry_run') === '1'
    const confirm = c.req.query('confirm') || ''

    if (!userId) return c.json({ error: 'user_id required' }, 400)
    if (!mappingsParam) return c.json({ error: 'mappings required (tx_id:created_at,tx_id:created_at,...)' }, 400)

    // parse mappings: "4333:2026-05-11 22:08:37,4334:2026-05-12 13:17:41"
    const mappings: { tx_id: number, new_created_at: string }[] = []
    for (const pair of mappingsParam.split(',')) {
      const idx = pair.indexOf(':')
      if (idx < 0) continue
      const txId = parseInt(pair.substring(0, idx).trim())
      const newCreatedAt = pair.substring(idx + 1).trim()
      if (txId && newCreatedAt) mappings.push({ tx_id: txId, new_created_at: newCreatedAt })
    }
    if (mappings.length === 0) return c.json({ error: 'no valid mappings parsed' }, 400)

    // parse expected_refs: "4333:306,4334:510,4335:569"
    const expectedRefs: Record<number, number> = {}
    if (expectedRefsParam) {
      for (const pair of expectedRefsParam.split(',')) {
        const idx = pair.indexOf(':')
        if (idx < 0) continue
        const txId = parseInt(pair.substring(0, idx).trim())
        const refId = parseInt(pair.substring(idx + 1).trim())
        if (txId && refId) expectedRefs[txId] = refId
      }
    }

    // user 확인
    const user = await db.prepare(`SELECT id, email, name, qkey_balance FROM users WHERE id = ?`).bind(userId).first<any>()
    if (!user) return c.json({ error: 'user not found', user_id: userId }, 404)

    // 각 tx 검증 후 plan 생성
    const plan: any[] = []
    for (const m of mappings) {
      const tx = await db.prepare(`
        SELECT id, user_id, type, amount, coin_type, description, ref_id, created_at
        FROM transactions WHERE id = ?
      `).bind(m.tx_id).first<any>()
      if (!tx) {
        plan.push({ action: 'SKIP_TX_NOT_FOUND', tx_id: m.tx_id })
        continue
      }
      if (tx.user_id !== userId) {
        plan.push({ action: 'SKIP_USER_MISMATCH', tx_id: m.tx_id, tx_user_id: tx.user_id, expected_user_id: userId })
        continue
      }
      if (expectedRefs[m.tx_id] && tx.ref_id !== expectedRefs[m.tx_id]) {
        plan.push({
          action: 'SKIP_REF_MISMATCH', tx_id: m.tx_id,
          tx_ref_id: tx.ref_id, expected_ref_id: expectedRefs[m.tx_id]
        })
        continue
      }
      plan.push({
        action: 'UPDATE_CREATED_AT',
        tx_id: m.tx_id,
        old_created_at: tx.created_at,
        new_created_at: m.new_created_at,
        type: tx.type,
        amount: tx.amount,
        ref_id: tx.ref_id,
        description: tx.description
      })
    }

    if (dryRun || confirm !== 'GO') {
      return c.json({
        success: true,
        mode: 'DRY_RUN',
        message: '실제 실행을 원하시면 confirm=GO 추가',
        user: { id: user.id, email: user.email, name: user.name, qkey_balance: user.qkey_balance },
        plan,
        plan_summary: {
          to_update_count: plan.filter(p => p.action === 'UPDATE_CREATED_AT').length,
          to_skip_count: plan.filter(p => p.action !== 'UPDATE_CREATED_AT').length
        }
      })
    }

    // EXECUTE: 각 tx 의 created_at 만 UPDATE (amount/balance 변동 없음)
    let updatedCount = 0
    const updatedIds: number[] = []
    for (const item of plan) {
      if (item.action === 'UPDATE_CREATED_AT') {
        await db.prepare(`
          UPDATE transactions SET created_at = ? WHERE id = ? AND user_id = ?
        `).bind(item.new_created_at, item.tx_id, userId).run()
        updatedCount++
        updatedIds.push(item.tx_id)
      }
    }

    return c.json({
      success: true,
      mode: 'EXECUTED',
      user: { id: user.id, email: user.email, name: user.name, qkey_balance: user.qkey_balance },
      plan,
      result: {
        updated_count: updatedCount,
        updated_tx_ids: updatedIds,
        note: 'qkey_balance/amount/ref_id 등 일체 변동 없음, created_at 만 보정됨'
      }
    })
  } catch (error) {
    console.error('fix-tx-created-at error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ fix-delete-tx-single: 단일 tx_id DELETE + users.qkey_balance 동시 차감 (중복 제거용) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   목적: 사장님 한국시간 기준 중복지급 발견시 정확한 1건 DELETE
//   안전성:
//     - 반드시 user_id + tx_id + expected_amount + expected_ref_id + expected_type 5중 검증 후만 진행
//     - 단일 tx 한정 (배열 입력 금지)
//     - DRY_RUN 기본 / confirm=GO 명시시만 실행
//     - DELETE 후 users.qkey_balance -= amount 자동 차감 (정합성 유지)
//   경로 (POST):
//     /api/diag/fix-delete-tx-single?key=ADMIN_PW
//        &user_id=33
//        &tx_id=4333
//        &expected_amount=3000
//        &expected_ref_id=306
//        &expected_type=daily_qkey
//        &dry_run=1   (또는 confirm=GO)
app.post('/api/diag/fix-delete-tx-single', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const userId = parseInt(c.req.query('user_id') || '0')
    const txId = parseInt(c.req.query('tx_id') || '0')
    const expectedAmount = Number(c.req.query('expected_amount') || '0')
    const expectedRefId = parseInt(c.req.query('expected_ref_id') || '0')
    const expectedType = c.req.query('expected_type') || ''
    const dryRun = c.req.query('dry_run') === '1'
    const confirm = c.req.query('confirm') || ''

    if (!userId) return c.json({ error: 'user_id required' }, 400)
    if (!txId) return c.json({ error: 'tx_id required' }, 400)
    if (!expectedAmount) return c.json({ error: 'expected_amount required' }, 400)
    if (!expectedType) return c.json({ error: 'expected_type required' }, 400)

    // user 확인
    const user = await db.prepare(`SELECT id, email, name, qkey_balance FROM users WHERE id = ?`).bind(userId).first<any>()
    if (!user) return c.json({ error: 'user not found', user_id: userId }, 404)

    // tx 확인 + 5중 검증
    const tx = await db.prepare(`
      SELECT id, user_id, type, amount, coin_type, description, ref_id, created_at
      FROM transactions WHERE id = ?
    `).bind(txId).first<any>()

    if (!tx) {
      return c.json({ error: 'tx not found', tx_id: txId }, 404)
    }

    const validation: any = {
      tx_id_match: tx.id === txId,
      user_id_match: tx.user_id === userId,
      type_match: tx.type === expectedType,
      amount_match: Number(tx.amount) === expectedAmount,
      ref_id_match: expectedRefId ? (tx.ref_id === expectedRefId) : true
    }
    const allValid = Object.values(validation).every(v => v === true)

    if (!allValid) {
      return c.json({
        success: false,
        error: 'VALIDATION_FAILED',
        message: '5중 검증 실패 — 진행 중단',
        tx_actual: {
          id: tx.id, user_id: tx.user_id, type: tx.type, amount: tx.amount,
          ref_id: tx.ref_id, coin_type: tx.coin_type, description: tx.description, created_at: tx.created_at
        },
        expected: {
          user_id: userId, tx_id: txId, type: expectedType,
          amount: expectedAmount, ref_id: expectedRefId
        },
        validation
      }, 400)
    }

    const plan = {
      action: 'DELETE_TX_AND_DEDUCT_BALANCE',
      tx_id: tx.id,
      user_id: tx.user_id,
      type: tx.type,
      amount: tx.amount,
      ref_id: tx.ref_id,
      description: tx.description,
      created_at: tx.created_at,
      qkey_balance_before: user.qkey_balance,
      qkey_balance_after: Number(user.qkey_balance) - Number(tx.amount)
    }

    if (dryRun || confirm !== 'GO') {
      return c.json({
        success: true,
        mode: 'DRY_RUN',
        message: '실제 실행을 원하시면 confirm=GO 추가',
        user: { id: user.id, email: user.email, name: user.name, qkey_balance: user.qkey_balance },
        validation,
        plan
      })
    }

    // EXECUTE: DELETE tx + balance -= amount (atomic order: tx 삭제 후 balance 차감)
    await db.prepare(`DELETE FROM transactions WHERE id = ? AND user_id = ?`).bind(txId, userId).run()
    await db.prepare(`UPDATE users SET qkey_balance = qkey_balance - ? WHERE id = ?`).bind(tx.amount, userId).run()

    const userAfter = await db.prepare(`SELECT qkey_balance FROM users WHERE id = ?`).bind(userId).first<any>()

    return c.json({
      success: true,
      mode: 'EXECUTED',
      user: {
        id: user.id, email: user.email, name: user.name,
        qkey_balance_before: user.qkey_balance,
        qkey_balance_after: userAfter?.qkey_balance || null
      },
      validation,
      result: {
        deleted_tx_id: txId,
        deducted_qkey: tx.amount,
        note: 'tx 행 삭제됨 + users.qkey_balance 동시 차감 (정합성 유지). dr 행은 그대로 유지됨 (의도적).'
      }
    })
  } catch (error) {
    console.error('fix-delete-tx-single error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ fix-delete-tx-no-balance: 잔액 차감 없이 tx 만 DELETE (잔액 미반영 잘못된 tx 정리) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   목적: type='daily_reward' 같이 영구룰 위반 type 으로 잘못 들어간 tx 정리
//        (이미 잔액에는 반영 안 되어 있어 차감 없이 행만 삭제)
//   안전성:
//     - user_id + tx_id + expected_amount + expected_type 4중 검증
//     - 단일 tx 한정
//     - 잔액 변경 0 (의도적)
//     - DRY_RUN 기본 / confirm=GO 명시시만 실행
//   경로 (POST):
//     /api/diag/fix-delete-tx-no-balance?key=ADMIN_PW
//        &user_id=33
//        &tx_id=3100
//        &expected_amount=3000
//        &expected_type=daily_reward
//        &dry_run=1   (또는 confirm=GO)
app.post('/api/diag/fix-delete-tx-no-balance', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const userId = parseInt(c.req.query('user_id') || '0')
    const txId = parseInt(c.req.query('tx_id') || '0')
    const expectedAmount = Number(c.req.query('expected_amount') || 'NaN')
    const expectedType = c.req.query('expected_type') || ''
    const dryRun = c.req.query('dry_run') === '1'
    const confirm = c.req.query('confirm') || ''

    if (!userId) return c.json({ error: 'user_id required' }, 400)
    if (!txId) return c.json({ error: 'tx_id required' }, 400)
    if (!expectedType) return c.json({ error: 'expected_type required' }, 400)
    if (Number.isNaN(expectedAmount)) return c.json({ error: 'expected_amount required (number)' }, 400)

    const user = await db.prepare(`SELECT id, email, name, qkey_balance FROM users WHERE id = ?`).bind(userId).first<any>()
    if (!user) return c.json({ error: 'user not found', user_id: userId }, 404)

    const tx = await db.prepare(`
      SELECT id, user_id, type, amount, coin_type, description, ref_id, created_at
      FROM transactions WHERE id = ?
    `).bind(txId).first<any>()
    if (!tx) return c.json({ error: 'tx not found', tx_id: txId }, 404)

    const validation = {
      tx_id_match: tx.id === txId,
      user_id_match: tx.user_id === userId,
      type_match: tx.type === expectedType,
      amount_match: Number(tx.amount) === expectedAmount
    }
    const allValid = Object.values(validation).every(v => v === true)
    if (!allValid) {
      return c.json({
        success: false,
        error: 'VALIDATION_FAILED',
        message: '4중 검증 실패 — 진행 중단',
        tx_actual: { id: tx.id, user_id: tx.user_id, type: tx.type, amount: tx.amount, ref_id: tx.ref_id, description: tx.description, created_at: tx.created_at },
        expected: { user_id: userId, tx_id: txId, type: expectedType, amount: expectedAmount },
        validation
      }, 400)
    }

    const plan = {
      action: 'DELETE_TX_ONLY_NO_BALANCE_CHANGE',
      tx_id: tx.id, user_id: tx.user_id, type: tx.type, amount: tx.amount,
      ref_id: tx.ref_id, description: tx.description, created_at: tx.created_at,
      qkey_balance_before: user.qkey_balance,
      qkey_balance_after: user.qkey_balance,
      balance_delta: 0
    }

    if (dryRun || confirm !== 'GO') {
      return c.json({ success: true, mode: 'DRY_RUN', message: '실제 실행을 원하시면 confirm=GO 추가', user: { id: user.id, email: user.email, name: user.name, qkey_balance: user.qkey_balance }, validation, plan })
    }

    await db.prepare(`DELETE FROM transactions WHERE id = ? AND user_id = ?`).bind(txId, userId).run()

    return c.json({
      success: true, mode: 'EXECUTED',
      user: { id: user.id, email: user.email, name: user.name, qkey_balance_before: user.qkey_balance, qkey_balance_after: user.qkey_balance },
      validation,
      result: { deleted_tx_id: txId, balance_changed: false, note: 'tx 행만 삭제, 잔액 변동 없음 (잔액에 미반영된 영구룰 위반 type 정리용)' }
    })
  } catch (error) {
    console.error('fix-delete-tx-no-balance error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ fix-adjust-qkey-balance: 단일 회원 잔액 직접 보정 (사장님 기준 정확한 잔액으로) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   목적: tx 정리 후에도 잔액이 사장님 기준과 다르면 직접 UPDATE
//   안전성:
//     - user_id + expected_current_balance (현재 DB값 확인) + new_balance 명시
//     - DRY_RUN 기본 / confirm=GO 명시시만 실행
//   경로 (POST):
//     /api/diag/fix-adjust-qkey-balance?key=ADMIN_PW
//        &user_id=33
//        &expected_current_balance=2250
//        &new_balance=3750
//        &reason_label=bang8241_recalc_kst_basis
//        &dry_run=1   (또는 confirm=GO)
app.post('/api/diag/fix-adjust-qkey-balance', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const userId = parseInt(c.req.query('user_id') || '0')
    const expectedCurrent = Number(c.req.query('expected_current_balance') || 'NaN')
    const newBalance = Number(c.req.query('new_balance') || 'NaN')
    const reasonLabel = c.req.query('reason_label') || ''
    const dryRun = c.req.query('dry_run') === '1'
    const confirm = c.req.query('confirm') || ''

    if (!userId) return c.json({ error: 'user_id required' }, 400)
    if (Number.isNaN(expectedCurrent)) return c.json({ error: 'expected_current_balance required' }, 400)
    if (Number.isNaN(newBalance)) return c.json({ error: 'new_balance required' }, 400)
    if (!reasonLabel) return c.json({ error: 'reason_label required (audit trail)' }, 400)

    const user = await db.prepare(`SELECT id, email, name, qkey_balance FROM users WHERE id = ?`).bind(userId).first<any>()
    if (!user) return c.json({ error: 'user not found', user_id: userId }, 404)

    if (Number(user.qkey_balance) !== expectedCurrent) {
      return c.json({
        success: false,
        error: 'EXPECTED_CURRENT_MISMATCH',
        message: '현재 DB 잔액이 expected_current_balance 와 다름 — 누군가 동시 변경한 가능성, 진행 중단',
        db_qkey_balance: user.qkey_balance,
        expected_current_balance: expectedCurrent
      }, 400)
    }

    const delta = newBalance - expectedCurrent

    const plan = {
      action: 'UPDATE_QKEY_BALANCE',
      user_id: user.id,
      qkey_balance_before: user.qkey_balance,
      qkey_balance_after: newBalance,
      delta,
      reason_label: reasonLabel
    }

    if (dryRun || confirm !== 'GO') {
      return c.json({ success: true, mode: 'DRY_RUN', message: '실제 실행을 원하시면 confirm=GO 추가', user: { id: user.id, email: user.email, name: user.name, qkey_balance: user.qkey_balance }, plan })
    }

    await db.prepare(`UPDATE users SET qkey_balance = ? WHERE id = ?`).bind(newBalance, userId).run()
    const userAfter = await db.prepare(`SELECT qkey_balance FROM users WHERE id = ?`).bind(userId).first<any>()

    return c.json({
      success: true, mode: 'EXECUTED',
      user: { id: user.id, email: user.email, name: user.name, qkey_balance_before: user.qkey_balance, qkey_balance_after: userAfter?.qkey_balance },
      result: { delta, reason_label: reasonLabel, note: 'users.qkey_balance 직접 보정. tx 행 변동 없음.' }
    })
  } catch (error) {
    console.error('fix-adjust-qkey-balance error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ fix-insert-daily-qkey-tx-no-balance: dr 행 기반 누락된 daily_qkey tx 생성 (잔액 변동 없음) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   목적: daily_rewards 행은 존재하나 대응되는 type='daily_qkey' transactions 행이 없는 경우 보충
//        (영구룰 위반 daily_reward 행을 삭제한 뒤 거래내역 화면 정합성 회복용)
//   영구룰 100% 준수:
//     - type = 'daily_qkey'
//     - coin_type = 'QKEY'
//     - description = '일일 배당 (QKEY)'
//     - ref_id = dr.id (정수)
//     - amount = dr.qkey_amount
//     - created_at = dr.created_at (원본 dr 시각 그대로)
//   안전성 (5중 검증):
//     - user_id + dr_id (존재 확인 + dr.user_id 일치)
//     - expected_amount == dr.qkey_amount
//     - expected_reward_date == dr.reward_date
//     - 동일 ref_id 의 type='daily_qkey' tx 가 이미 있으면 거부 (ALREADY_EXISTS)
//     - 잔액 변동 0 (잔액은 이미 정확한 상태 전제)
//   경로 (POST):
//     /api/diag/fix-insert-daily-qkey-tx-no-balance?key=ADMIN_PW
//        &user_id=40
//        &dr_id=512
//        &expected_amount=5250
//        &expected_reward_date=2026-05-12
//        &dry_run=1   (또는 confirm=GO)
app.post('/api/diag/fix-insert-daily-qkey-tx-no-balance', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const userId = parseInt(c.req.query('user_id') || '0')
    const drId = parseInt(c.req.query('dr_id') || '0')
    const expectedAmount = Number(c.req.query('expected_amount') || 'NaN')
    const expectedRewardDate = c.req.query('expected_reward_date') || ''
    const dryRun = c.req.query('dry_run') === '1'
    const confirm = c.req.query('confirm') || ''

    if (!userId) return c.json({ error: 'user_id required' }, 400)
    if (!drId) return c.json({ error: 'dr_id required' }, 400)
    if (Number.isNaN(expectedAmount)) return c.json({ error: 'expected_amount required (number)' }, 400)
    if (!expectedRewardDate) return c.json({ error: 'expected_reward_date required (YYYY-MM-DD)' }, 400)

    const user = await db.prepare(`SELECT id, email, name, qkey_balance FROM users WHERE id = ?`).bind(userId).first<any>()
    if (!user) return c.json({ error: 'user not found', user_id: userId }, 404)

    const dr = await db.prepare(`
      SELECT id, user_id, staking_id, qkey_amount, reward_date, paid_date, created_at
      FROM daily_rewards WHERE id = ?
    `).bind(drId).first<any>()
    if (!dr) return c.json({ error: 'daily_rewards row not found', dr_id: drId }, 404)

    // 5중 검증
    const validation = {
      dr_exists: true,
      dr_user_id_match: dr.user_id === userId,
      dr_amount_match: Number(dr.qkey_amount) === expectedAmount,
      dr_reward_date_match: String(dr.reward_date) === expectedRewardDate,
      no_existing_daily_qkey_tx_for_this_dr: true // 아래에서 체크
    }

    // 이미 동일 ref_id 의 daily_qkey tx 가 있는지 확인
    const existingTx = await db.prepare(`
      SELECT id, type, amount, ref_id FROM transactions
      WHERE user_id = ? AND type = 'daily_qkey' AND coin_type = 'QKEY' AND ref_id = ?
    `).bind(userId, String(drId)).first<any>()
    if (existingTx) {
      validation.no_existing_daily_qkey_tx_for_this_dr = false
    }

    const allValid = Object.values(validation).every(v => v === true)
    if (!allValid) {
      return c.json({
        success: false,
        error: 'VALIDATION_FAILED',
        message: '5중 검증 실패 — 진행 중단',
        dr_actual: { id: dr.id, user_id: dr.user_id, qkey_amount: dr.qkey_amount, reward_date: dr.reward_date, created_at: dr.created_at },
        expected: { user_id: userId, dr_id: drId, amount: expectedAmount, reward_date: expectedRewardDate },
        existing_tx: existingTx || null,
        validation
      }, 400)
    }

    const plan = {
      action: 'INSERT_DAILY_QKEY_TX_NO_BALANCE_CHANGE',
      user_id: userId,
      type: 'daily_qkey',
      coin_type: 'QKEY',
      amount: Number(dr.qkey_amount),
      description: '일일 배당 (QKEY)',
      ref_id: String(drId),
      created_at: dr.created_at,
      qkey_balance_before: user.qkey_balance,
      qkey_balance_after: user.qkey_balance,
      balance_delta: 0
    }

    if (dryRun || confirm !== 'GO') {
      return c.json({ success: true, mode: 'DRY_RUN', message: '실제 실행을 원하시면 confirm=GO 추가', user: { id: user.id, email: user.email, name: user.name, qkey_balance: user.qkey_balance }, validation, plan })
    }

    // INSERT (잔액 변동 없음)
    const insertResult = await db.prepare(`
      INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id, created_at)
      VALUES (?, 'daily_qkey', 'QKEY', ?, '일일 배당 (QKEY)', ?, ?)
    `).bind(userId, Number(dr.qkey_amount), String(drId), dr.created_at).run()

    const newTxId = (insertResult as any)?.meta?.last_row_id || null

    return c.json({
      success: true, mode: 'EXECUTED',
      user: { id: user.id, email: user.email, name: user.name, qkey_balance_before: user.qkey_balance, qkey_balance_after: user.qkey_balance },
      validation,
      result: {
        inserted_tx_id: newTxId,
        dr_id: drId,
        type: 'daily_qkey',
        amount: Number(dr.qkey_amount),
        created_at: dr.created_at,
        balance_changed: false,
        note: 'daily_qkey tx 삽입 완료. 잔액 변동 없음 (이미 정확한 잔액 전제).'
      }
    })
  } catch (error) {
    console.error('fix-insert-daily-qkey-tx-no-balance error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ scan-balance-mismatch-v2: swap_out 포함 정확한 잔액 검증식 전수 ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   영구룰 잔액 검증식:
//     expected =
//         Σ(tx WHERE type='daily_qkey' AND coin_type='QKEY')
//       + Σ(tx WHERE type='referral_reward' AND coin_type='QKEY')
//       + Σ(tx WHERE type='swap_out' AND coin_type='QKEY')   ← amount 가 음수로 저장됨
//       + Σ(tx WHERE type='swap_in' AND coin_type='QKEY')    ← 양수
//       - Σ(withdrawals.amount WHERE coin_type='QKEY' AND status IN approved/completed/processing/pending)
//   영구룰 위반 type 별도 표시 (daily_reward 등)
//   안전성: SELECT only
//   경로: GET /api/diag/scan-balance-mismatch-v2?key=ADMIN_PW&threshold=1&limit=200
app.get('/api/diag/scan-balance-mismatch-v2', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const threshold = Number(c.req.query('threshold') || '1')
    const limit = parseInt(c.req.query('limit') || '500')

    const users = await db.prepare(`
      SELECT id, email, name, qkey_balance
      FROM users
      WHERE qkey_balance IS NOT NULL
      ORDER BY id ASC
    `).all<any>()

    // 정상 type 합계: daily_qkey + referral_reward + swap_out + swap_in
    const txNormal = await db.prepare(`
      SELECT user_id,
             SUM(CASE WHEN type='daily_qkey' THEN amount ELSE 0 END) AS sum_daily,
             SUM(CASE WHEN type='referral_reward' THEN amount ELSE 0 END) AS sum_referral,
             SUM(CASE WHEN type='swap_out' THEN amount ELSE 0 END) AS sum_swap_out,
             SUM(CASE WHEN type='swap_in' THEN amount ELSE 0 END) AS sum_swap_in
      FROM transactions
      WHERE coin_type = 'QKEY'
        AND type IN ('daily_qkey','referral_reward','swap_out','swap_in')
      GROUP BY user_id
    `).all<any>()

    // 영구룰 위반 type 합계 (별도 표시)
    const txIllegal = await db.prepare(`
      SELECT user_id, type,
             SUM(amount) AS sum_amount,
             COUNT(*) AS cnt
      FROM transactions
      WHERE coin_type = 'QKEY'
        AND type NOT IN ('daily_qkey','referral_reward','swap_out','swap_in','withdrawal')
      GROUP BY user_id, type
    `).all<any>()

    const wdSums = await db.prepare(`
      SELECT user_id, SUM(amount) AS sum_withdraw
      FROM withdrawals
      WHERE coin_type = 'QKEY'
        AND status IN ('approved','completed','processing','pending')
      GROUP BY user_id
    `).all<any>()

    const normMap: Record<string, { d: number, r: number, so: number, si: number }> = {}
    for (const row of (txNormal.results || [])) {
      normMap[String(row.user_id)] = {
        d: Number(row.sum_daily || 0),
        r: Number(row.sum_referral || 0),
        so: Number(row.sum_swap_out || 0),
        si: Number(row.sum_swap_in || 0)
      }
    }
    const illegalMap: Record<string, { types: { type: string, sum: number, cnt: number }[], total_sum: number, total_cnt: number }> = {}
    for (const row of (txIllegal.results || [])) {
      const k = String(row.user_id)
      if (!illegalMap[k]) illegalMap[k] = { types: [], total_sum: 0, total_cnt: 0 }
      illegalMap[k].types.push({ type: row.type, sum: Number(row.sum_amount || 0), cnt: Number(row.cnt || 0) })
      illegalMap[k].total_sum += Number(row.sum_amount || 0)
      illegalMap[k].total_cnt += Number(row.cnt || 0)
    }
    const wdMap: Record<string, number> = {}
    for (const row of (wdSums.results || [])) wdMap[String(row.user_id)] = Number(row.sum_withdraw || 0)

    const mismatches: any[] = []
    let totalChecked = 0, totalOk = 0, totalNegative = 0, totalIllegalUsers = 0

    for (const u of (users.results || [])) {
      totalChecked++
      const k = String(u.id)
      const n = normMap[k] || { d: 0, r: 0, so: 0, si: 0 }
      const sumWd = wdMap[k] || 0
      const expected = n.d + n.r + n.so + n.si - sumWd
      const actual = Number(u.qkey_balance || 0)
      const diff = actual - expected
      const illegal = illegalMap[k] || null

      if (actual < 0) totalNegative++
      if (illegal) totalIllegalUsers++

      if (Math.abs(diff) >= threshold || illegal) {
        mismatches.push({
          user_id: u.id, email: u.email, name: u.name,
          qkey_balance: actual,
          sum_daily_qkey: n.d,
          sum_referral_reward: n.r,
          sum_swap_out: n.so,
          sum_swap_in: n.si,
          sum_withdraw: sumWd,
          expected_balance: expected,
          diff,
          diff_sign: diff > 0 ? 'BALANCE_HIGH' : (diff < 0 ? 'BALANCE_LOW' : 'OK'),
          negative_balance: actual < 0,
          illegal_types: illegal ? illegal.types : [],
          illegal_total_sum: illegal ? illegal.total_sum : 0,
          illegal_total_cnt: illegal ? illegal.total_cnt : 0
        })
      } else {
        totalOk++
      }
    }

    mismatches.sort((a, b) => {
      const aP = a.illegal_total_cnt > 0 ? 1 : 0
      const bP = b.illegal_total_cnt > 0 ? 1 : 0
      if (aP !== bP) return bP - aP
      return Math.abs(b.diff) - Math.abs(a.diff)
    })
    const top = mismatches.slice(0, limit)
    const totalDiffAbs = mismatches.reduce((acc, m) => acc + Math.abs(m.diff), 0)
    const totalDiffSigned = mismatches.reduce((acc, m) => acc + m.diff, 0)

    return c.json({
      success: true,
      formula: "expected = Σdaily_qkey + Σreferral_reward + Σswap_out + Σswap_in - Σwithdrawals (active)",
      summary: {
        total_users_checked: totalChecked,
        users_ok: totalOk,
        users_mismatch_or_illegal: mismatches.length,
        users_with_negative_balance: totalNegative,
        users_with_illegal_tx_types: totalIllegalUsers,
        sum_abs_diff: totalDiffAbs,
        sum_signed_diff: totalDiffSigned,
        threshold,
        returned: top.length
      },
      mismatches: top
    })
  } catch (error) {
    console.error('scan-balance-mismatch-v2 error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ scan-illegal-tx-types: 영구룰 위반 type 전수 적발 (daily_reward 등 잘못된 행) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   허용 type: 'daily_qkey','referral_reward','swap_out','swap_in','withdrawal'
//   안전성: SELECT only
//   경로: GET /api/diag/scan-illegal-tx-types?key=ADMIN_PW
app.get('/api/diag/scan-illegal-tx-types', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB

    const rows = await db.prepare(`
      SELECT t.id AS tx_id, t.user_id, t.type, t.amount, t.coin_type, t.description, t.ref_id,
             datetime(t.created_at,'+9 hours') AS created_at_kst,
             u.email, u.name, u.qkey_balance
      FROM transactions t
      LEFT JOIN users u ON u.id = t.user_id
      WHERE t.coin_type = 'QKEY'
        AND t.type NOT IN ('daily_qkey','referral_reward','swap_out','swap_in','withdrawal')
      ORDER BY t.user_id, t.id
    `).all<any>()

    const byUser: Record<string, any> = {}
    for (const r of (rows.results || [])) {
      const k = String(r.user_id)
      if (!byUser[k]) byUser[k] = {
        user_id: r.user_id, email: r.email, name: r.name, qkey_balance: r.qkey_balance,
        illegal_count: 0, illegal_sum: 0, items: []
      }
      byUser[k].illegal_count++
      byUser[k].illegal_sum += Number(r.amount || 0)
      byUser[k].items.push({
        tx_id: r.tx_id, type: r.type, amount: r.amount,
        description: r.description, ref_id: r.ref_id, created_at_kst: r.created_at_kst
      })
    }
    const userList = Object.values(byUser).sort((a: any, b: any) => b.illegal_count - a.illegal_count)
    const totalRows = (rows.results || []).length

    return c.json({
      success: true,
      allowed_types: ['daily_qkey','referral_reward','swap_out','swap_in','withdrawal'],
      total_illegal_rows: totalRows,
      affected_users_count: userList.length,
      affected_users: userList
    })
  } catch (error) {
    console.error('scan-illegal-tx-types error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ scan-thursday-missing-paid-on-friday: 목요일 dr 미지급 → 금요일 지급 영구룰 점검 ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   영구룰: 휴일(KST 토/일) 진입자 → 다음 첫 평일에 데일리 지급
//          + 평일 사이 dr 누락 시 다음 평일에 합쳐서 지급
//   사장님 직접 지시: "이전 휴일진입자들의 목요일치를 금요일날 지급해야된다"
//   판정 로직:
//     - active staking (KST 기준 reward 발생 가능 시점 도래)
//     - reward_date='2026-05-14' (목) dr 행이 없음
//     - reward_date='2026-05-15' (금) dr 행도 없음 (즉 5/15에 보충 지급 안됨)
//   안전성: SELECT only
//   경로: GET /api/diag/scan-thursday-missing-paid-on-friday?key=ADMIN_PW
app.get('/api/diag/scan-thursday-missing-paid-on-friday', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB

    // KST 기준 5/14(목), 5/15(금) dr 점검 — 모든 active staking 중 둘 다 없는 케이스 적발
    const rows = await db.prepare(`
      SELECT
        s.id AS staking_id,
        s.user_id,
        u.email,
        u.name,
        s.amount,
        s.daily_rate,
        s.start_date,
        datetime(s.start_date, '+9 hours') AS start_kst,
        strftime('%w', datetime(s.start_date, '+9 hours')) AS start_dow_kst,
        s.status,
        (SELECT COUNT(*) FROM daily_rewards dr WHERE dr.staking_id = s.id AND dr.reward_date = '2026-05-11') AS dr_511_cnt,
        (SELECT SUM(usdt_amount) FROM daily_rewards dr WHERE dr.staking_id = s.id AND dr.reward_date = '2026-05-11') AS dr_511_sum,
        (SELECT COUNT(*) FROM daily_rewards dr WHERE dr.staking_id = s.id AND dr.reward_date = '2026-05-12') AS dr_512_cnt,
        (SELECT SUM(usdt_amount) FROM daily_rewards dr WHERE dr.staking_id = s.id AND dr.reward_date = '2026-05-12') AS dr_512_sum,
        (SELECT COUNT(*) FROM daily_rewards dr WHERE dr.staking_id = s.id AND dr.reward_date = '2026-05-13') AS dr_513_cnt,
        (SELECT SUM(usdt_amount) FROM daily_rewards dr WHERE dr.staking_id = s.id AND dr.reward_date = '2026-05-13') AS dr_513_sum,
        (SELECT COUNT(*) FROM daily_rewards dr WHERE dr.staking_id = s.id AND dr.reward_date = '2026-05-14') AS dr_514_cnt,
        (SELECT SUM(usdt_amount) FROM daily_rewards dr WHERE dr.staking_id = s.id AND dr.reward_date = '2026-05-14') AS dr_514_sum,
        (SELECT COUNT(*) FROM daily_rewards dr WHERE dr.staking_id = s.id AND dr.reward_date = '2026-05-15') AS dr_515_cnt,
        (SELECT SUM(usdt_amount) FROM daily_rewards dr WHERE dr.staking_id = s.id AND dr.reward_date = '2026-05-15') AS dr_515_sum
      FROM staking s
      JOIN users u ON u.id = s.user_id
      WHERE s.status = 'active'
        AND date(datetime(s.start_date, '+9 hours')) <= '2026-05-14'
      ORDER BY s.user_id, s.id
    `).all<any>()

    const all = rows.results || []
    // 5/14 목 누락 + 5/15 금에도 보충 없음 (영구룰 위반 핵심)
    const thursdayMissingAndNotPaidFriday = all.filter((r: any) => r.dr_514_cnt === 0 && r.dr_515_cnt === 0)
    // 5/14 목 누락이지만 5/15 금에는 받음 (영구룰 OK 가능성 — 금에 합산 지급된 경우)
    const thursdayMissingButFridayOk = all.filter((r: any) => r.dr_514_cnt === 0 && r.dr_515_cnt >= 1)
    // 5/15 금 자체 누락 (별도 케이스)
    const fridayMissing = all.filter((r: any) => r.dr_515_cnt === 0)
    // 5/15 금에 dr 가 2건 이상 = 목+금 합산 케이스 가능성
    const fridayDouble = all.filter((r: any) => r.dr_515_cnt >= 2)

    // 영구룰: 1일치 QKEY 금액은 dr_511~dr_513 의 실제 평균치로 산출 (안전)
    // staking.amount * daily_rate * 1.5 류 추정식은 사용하지 않음
    const expectedDailyAmount = (r: any) => {
      const amounts = [r.dr_511_sum, r.dr_512_sum, r.dr_513_sum, r.dr_514_sum]
        .map((v: any) => v == null ? null : Number(v))
        .filter((v: any) => v != null && v > 0)
      if (amounts.length === 0) return null
      // 평균이 아니라 가장 빈도 높은 값을 1일치로 (안전: 모든 값이 같으면 그것이 1일치)
      const sum = amounts.reduce((a: number, b: number) => a + b, 0)
      return Math.round(sum / amounts.length * 100) / 100
    }

    return c.json({
      success: true,
      kst_now: new Date(Date.now() + 9 * 3600 * 1000).toISOString(),
      reward_rule: '영구룰: 휴일 진입자 → 다음 첫 평일 지급 / 목요일 미지급 → 금요일 합산 지급',
      summary: {
        total_active_stakings_started_by_514: all.length,
        thursday_missing_AND_friday_missing: thursdayMissingAndNotPaidFriday.length,
        thursday_missing_BUT_friday_ok: thursdayMissingButFridayOk.length,
        friday_missing_total: fridayMissing.length,
        friday_double_dr: fridayDouble.length
      },
      critical_targets_thursday_unpaid_friday_unpaid: thursdayMissingAndNotPaidFriday.map((r: any) => ({
        staking_id: r.staking_id,
        user_id: r.user_id,
        email: r.email,
        name: r.name,
        amount: r.amount,
        daily_rate: r.daily_rate,
        start_kst: r.start_kst,
        start_dow_kst: r.start_dow_kst, // 0=Sun,6=Sat
        is_holiday_entry: r.start_dow_kst === '0' || r.start_dow_kst === '6',
        expected_daily_qkey: expectedDailyAmount(r),
        dr_511: r.dr_511_cnt, dr_512: r.dr_512_cnt, dr_513: r.dr_513_cnt,
        dr_514: r.dr_514_cnt, dr_515: r.dr_515_cnt, dr_515_sum: r.dr_515_sum
      })),
      friday_missing_only: fridayMissing.filter((r: any) => r.dr_514_cnt >= 1).map((r: any) => ({
        staking_id: r.staking_id,
        user_id: r.user_id,
        email: r.email,
        name: r.name,
        amount: r.amount,
        start_kst: r.start_kst,
        start_dow_kst: r.start_dow_kst,
        expected_daily_qkey: expectedDailyAmount(r),
        dr_514: r.dr_514_cnt, dr_515: r.dr_515_cnt
      })),
      friday_combined_pay_candidates: fridayDouble.map((r: any) => ({
        staking_id: r.staking_id, user_id: r.user_id, email: r.email, name: r.name,
        amount: r.amount, start_kst: r.start_kst, start_dow_kst: r.start_dow_kst,
        expected_daily_qkey: expectedDailyAmount(r),
        dr_514: r.dr_514_cnt, dr_515_cnt: r.dr_515_cnt, dr_515_sum: r.dr_515_sum
      })),
      thursday_missing_but_friday_ok_list: thursdayMissingButFridayOk.map((r: any) => ({
        staking_id: r.staking_id,
        user_id: r.user_id,
        email: r.email,
        name: r.name,
        amount: r.amount,
        daily_rate: r.daily_rate,
        start_kst: r.start_kst,
        start_dow_kst: r.start_dow_kst,
        is_holiday_entry: r.start_dow_kst === '0' || r.start_dow_kst === '6',
        expected_daily_qkey: expectedDailyAmount(r),
        dr_511: r.dr_511_cnt, dr_512: r.dr_512_cnt, dr_513: r.dr_513_cnt,
        dr_514: r.dr_514_cnt, dr_515: r.dr_515_cnt, dr_515_sum: r.dr_515_sum,
        violation_note: '5/14 dr 없음, 5/15 에 합산 지급 안 됨 (5/15 dr 가 단건 = 5/15분만) → 5/14분 보충 필요'
      }))
    })
  } catch (error) {
    console.error('scan-thursday-missing-paid-on-friday error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ fix-insert-thursday-dr-paid-friday: 단일 staking 5/14 dr+tx 보충 (영구룰: 금요일 합산 지급) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   사장님 영구룰: 휴일 진입자 → 다음 첫 평일 지급 / 목요일 미지급분 → 금요일 합산 지급
//   동작:
//     1) daily_rewards INSERT (reward_date='2026-05-14', paid_date='2026-05-15', qkey_amount=expected)
//     2) transactions INSERT (type='daily_qkey', description='일일 배당 (QKEY)', ref_id=new_dr.id, created_at=5/15 KST 시각)
//     3) users.qkey_balance += expected
//   안전성 5중 검증:
//     - staking 존재 + active
//     - staking.user_id == 요청 user_id
//     - 5/14 dr 가 0건 (중복 방지)
//     - 5/15 dr 가 정확히 1건 (이미 5/14 합산 안 됨 = 위반 케이스 일치)
//     - expected_daily_qkey 가 외부 계산과 일치
//   경로 (POST):
//     /api/diag/fix-insert-thursday-dr-paid-friday?key=ADMIN_PW
//       &staking_id=...
//       &user_id=...
//       &expected_daily_qkey=...
//       &dry_run=1   (또는 confirm=GO)
app.post('/api/diag/fix-insert-thursday-dr-paid-friday', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const stakingId = parseInt(c.req.query('staking_id') || '0')
    const userId = parseInt(c.req.query('user_id') || '0')
    const expectedDailyQkey = Number(c.req.query('expected_daily_qkey') || 'NaN')
    const dryRun = c.req.query('dry_run') === '1'
    const confirm = c.req.query('confirm') || ''

    if (!stakingId) return c.json({ error: 'staking_id required' }, 400)
    if (!userId) return c.json({ error: 'user_id required' }, 400)
    if (Number.isNaN(expectedDailyQkey)) return c.json({ error: 'expected_daily_qkey required' }, 400)

    const staking = await db.prepare(`
      SELECT id, user_id, amount, daily_rate, status, start_date
      FROM staking WHERE id = ?
    `).bind(stakingId).first<any>()
    if (!staking) return c.json({ error: 'staking not found', staking_id: stakingId }, 404)

    const user = await db.prepare(`SELECT id, email, name, qkey_balance FROM users WHERE id = ?`).bind(userId).first<any>()
    if (!user) return c.json({ error: 'user not found', user_id: userId }, 404)

    // 5/14 dr cnt
    const dr514 = await db.prepare(`
      SELECT COUNT(*) AS cnt FROM daily_rewards WHERE staking_id = ? AND reward_date = '2026-05-14'
    `).bind(stakingId).first<any>()
    // 5/15 dr cnt + row (sum check) — usdt_amount = QKEY 수량 legacy 컬럼
    const dr515 = await db.prepare(`
      SELECT COUNT(*) AS cnt, SUM(usdt_amount) AS sum_amt FROM daily_rewards WHERE staking_id = ? AND reward_date = '2026-05-15'
    `).bind(stakingId).first<any>()
    // 5/11~5/13 1일치 평균으로 검증
    const dr1113 = await db.prepare(`
      SELECT SUM(usdt_amount) AS sum_amt, COUNT(*) AS cnt FROM daily_rewards WHERE staking_id = ? AND reward_date IN ('2026-05-11','2026-05-12','2026-05-13')
    `).bind(stakingId).first<any>()
    const avgDaily = Number(dr1113?.cnt) > 0 ? Math.round(Number(dr1113.sum_amt) / Number(dr1113.cnt) * 100) / 100 : null

    const validation = {
      staking_exists: true,
      staking_active: staking.status === 'active',
      staking_user_id_match: staking.user_id === userId,
      dr_514_is_zero: Number(dr514?.cnt) === 0,
      dr_515_is_one: Number(dr515?.cnt) === 1,
      expected_qkey_match_history: avgDaily == null ? false : Math.abs(avgDaily - expectedDailyQkey) < 0.01
    }
    const allValid = Object.values(validation).every(v => v === true)
    if (!allValid) {
      return c.json({
        success: false,
        error: 'VALIDATION_FAILED',
        message: '5중 검증 실패 — 진행 중단',
        staking_actual: staking,
        dr_514_cnt: dr514?.cnt, dr_515_cnt: dr515?.cnt, dr_515_sum: dr515?.sum_amt,
        history_avg_daily: avgDaily,
        request_expected: expectedDailyQkey,
        validation
      }, 400)
    }

    // 영구룰: 실제 지급일자가 5/15 (금) 이므로 created_at 도 5/15 새벽으로 설정 (UTC 기준)
    // 5/15 09:00:00 KST = 5/15 00:00:00 UTC
    const tx_created_at_utc = '2026-05-15 00:00:00'

    const plan = {
      action: 'INSERT_DR_AND_TX_THURSDAY_PAID_FRIDAY',
      staking_id: stakingId, user_id: userId,
      dr_to_insert: { staking_id: stakingId, user_id: userId, usdt_amount: expectedDailyQkey, reward_date: '2026-05-14', paid_date: '2026-05-15' },
      tx_to_insert: { user_id: userId, type: 'daily_qkey', coin_type: 'QKEY', amount: expectedDailyQkey, description: '일일 배당 (QKEY)', created_at_utc: tx_created_at_utc },
      qkey_balance_before: user.qkey_balance,
      qkey_balance_after: Number(user.qkey_balance) + expectedDailyQkey,
      balance_delta: expectedDailyQkey
    }

    if (dryRun || confirm !== 'GO') {
      return c.json({ success: true, mode: 'DRY_RUN', message: '실제 실행을 원하시면 confirm=GO 추가', user: { id: user.id, email: user.email, name: user.name, qkey_balance: user.qkey_balance }, validation, plan })
    }

    // 1) INSERT dr — 컬럼 이름 영구룰: usdt_amount (실제 QKEY 수량 legacy 저장)
    const drInsert = await db.prepare(`
      INSERT INTO daily_rewards (staking_id, user_id, usdt_amount, reward_date, paid_date)
      VALUES (?, ?, ?, '2026-05-14', '2026-05-15')
    `).bind(stakingId, userId, expectedDailyQkey).run()
    const newDrId = (drInsert as any)?.meta?.last_row_id || null

    // 2) INSERT tx (ref_id = new dr.id)
    const txInsert = await db.prepare(`
      INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id, created_at)
      VALUES (?, 'daily_qkey', 'QKEY', ?, '일일 배당 (QKEY)', ?, ?)
    `).bind(userId, expectedDailyQkey, String(newDrId), tx_created_at_utc).run()
    const newTxId = (txInsert as any)?.meta?.last_row_id || null

    // 3) UPDATE balance
    await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(expectedDailyQkey, userId).run()
    const userAfter = await db.prepare(`SELECT qkey_balance FROM users WHERE id = ?`).bind(userId).first<any>()

    return c.json({
      success: true, mode: 'EXECUTED',
      user: { id: user.id, email: user.email, name: user.name, qkey_balance_before: user.qkey_balance, qkey_balance_after: userAfter?.qkey_balance },
      validation,
      result: { inserted_dr_id: newDrId, inserted_tx_id: newTxId, amount: expectedDailyQkey, reward_date: '2026-05-14', paid_date: '2026-05-15', balance_delta: expectedDailyQkey, note: '영구룰: 휴일 진입자 목요일 미지급분 → 금요일 합산 지급' }
    })
  } catch (error) {
    console.error('fix-insert-thursday-dr-paid-friday error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ scan-thursday-friday-amount-mismatch: 5/14 dr sum vs 5/15 dr sum 전수 비교 ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   목적(boss directive): "5월14의 배당금액과 5월 15일의 배당금액이 신규 진입이 그 사이에
//   일체 없었던 평일이어서 전부 모든 계정이 같아야 한다"
//   → 5/14 ≤ 진입일인 active staking 전부에 대해 SUM(dr 5/14) == SUM(dr 5/15) 검증.
//   불일치 발견 시 해당 staking 정보를 모두 반환.
//
//   경로: GET /api/diag/scan-thursday-friday-amount-mismatch?key=ADMIN_PW
app.get('/api/diag/scan-thursday-friday-amount-mismatch', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB

    // active + 5/14 이전 진입(=KST 기준) 인 staking 전수 + dr 5/14, 5/15 합계
    const rows = await db.prepare(`
      SELECT
        s.id AS staking_id,
        s.user_id,
        u.email,
        u.name,
        s.amount AS staking_amount,
        s.daily_rate,
        s.status,
        s.start_date,
        date(datetime(s.start_date, '+9 hours')) AS start_kst,
        (SELECT COUNT(*) FROM daily_rewards WHERE staking_id=s.id AND reward_date='2026-05-14') AS cnt_514,
        (SELECT IFNULL(SUM(usdt_amount),0) FROM daily_rewards WHERE staking_id=s.id AND reward_date='2026-05-14') AS sum_514,
        (SELECT COUNT(*) FROM daily_rewards WHERE staking_id=s.id AND reward_date='2026-05-15') AS cnt_515,
        (SELECT IFNULL(SUM(usdt_amount),0) FROM daily_rewards WHERE staking_id=s.id AND reward_date='2026-05-15') AS sum_515,
        (SELECT IFNULL(SUM(usdt_amount),0) FROM daily_rewards WHERE staking_id=s.id AND reward_date='2026-05-13') AS sum_513,
        (SELECT IFNULL(SUM(usdt_amount),0) FROM daily_rewards WHERE staking_id=s.id AND reward_date='2026-05-12') AS sum_512,
        (SELECT IFNULL(SUM(usdt_amount),0) FROM daily_rewards WHERE staking_id=s.id AND reward_date='2026-05-11') AS sum_511
      FROM staking s
      JOIN users u ON u.id = s.user_id
      WHERE s.status = 'active'
        AND date(datetime(s.start_date, '+9 hours')) <= '2026-05-14'
      ORDER BY s.id ASC
    `).all()

    const all = rows.results || []
    const totalActive = all.length

    // 비교: 5/14 sum vs 5/15 sum
    const mismatches: any[] = []
    const matched: any[] = []
    const both_zero: any[] = []
    for (const r of all) {
      const s514 = Number((r as any).sum_514 || 0)
      const s515 = Number((r as any).sum_515 || 0)
      if (s514 === 0 && s515 === 0) {
        both_zero.push(r)
        continue
      }
      // 소수점 노이즈 방지 0.01 tolerance
      if (Math.abs(s514 - s515) < 0.01) {
        matched.push(r)
      } else {
        const diff = Math.round((s515 - s514) * 100) / 100
        const cat =
          s514 === 0 ? 'thursday_missing' :
          s515 === 0 ? 'friday_missing' :
          s514 < s515 ? 'thursday_lower' :
          'thursday_higher'
        mismatches.push({ ...(r as any), diff_515_minus_514: diff, category: cat })
      }
    }

    return c.json({
      ok: true,
      total_active_staking: totalActive,
      matched_count: matched.length,
      mismatch_count: mismatches.length,
      both_zero_count: both_zero.length,
      summary_by_category: {
        thursday_missing: mismatches.filter((m: any) => m.category === 'thursday_missing').length,
        friday_missing: mismatches.filter((m: any) => m.category === 'friday_missing').length,
        thursday_lower: mismatches.filter((m: any) => m.category === 'thursday_lower').length,
        thursday_higher: mismatches.filter((m: any) => m.category === 'thursday_higher').length,
      },
      mismatches,
      both_zero_list: both_zero,
      note: 'boss directive: 신규 진입이 없는 평일 5/14-5/15는 전부 모든 계정이 같아야 한다 — 불일치 staking 전수 반환'
    })
  } catch (error) {
    console.error('scan-thursday-friday-amount-mismatch error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ scan-duplicate-daily-qkey-on-date: 특정 날짜(KST) 에 daily_qkey tx 2건 이상 user 전수 ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   boss directive: "15일날 중복 지급된 계정 찾아서 1회로 줄이라고 깨끗하게"
//   기준: date(tx.created_at, '+9 hours') = target_date AND type='daily_qkey'
//   기본: target_date=2026-05-15
//   경로: GET /api/diag/scan-duplicate-daily-qkey-on-date?key=ADMIN_PW&date=2026-05-15
app.get('/api/diag/scan-duplicate-daily-qkey-on-date', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const targetDate = c.req.query('date') || '2026-05-15'
    if (!/^\d{4}-\d{2}-\d{2}$/.test(targetDate)) {
      return c.json({ error: 'date=YYYY-MM-DD 필요' }, 400)
    }

    // 1) target_date 에 daily_qkey tx 2건 이상인 user_id 추출
    const dupUsers = await db.prepare(`
      SELECT user_id, COUNT(*) AS tx_cnt, SUM(amount) AS tx_sum
      FROM transactions
      WHERE type = 'daily_qkey'
        AND date(created_at, '+9 hours') = ?
      GROUP BY user_id
      HAVING COUNT(*) >= 2
      ORDER BY user_id ASC
    `).bind(targetDate).all()

    const dupList: any[] = []
    for (const row of (dupUsers.results as any[])) {
      const uid = row.user_id
      const u = await db.prepare(`SELECT id, email, name, qkey_balance FROM users WHERE id = ?`).bind(uid).first<any>()
      const txs = await db.prepare(`
        SELECT id, type, amount, description, ref_id,
               datetime(created_at, '+9 hours') AS created_at_kst,
               created_at AS created_at_utc
        FROM transactions
        WHERE user_id = ?
          AND type = 'daily_qkey'
          AND date(created_at, '+9 hours') = ?
        ORDER BY datetime(created_at, '+9 hours') ASC, id ASC
      `).bind(uid, targetDate).all()

      // 각 tx 의 ref_id 에 해당하는 dr 매핑 조회
      const txDetails: any[] = []
      for (const t of (txs.results as any[])) {
        let drInfo: any = null
        if (t.ref_id) {
          drInfo = await db.prepare(`
            SELECT id, staking_id, reward_date, paid_date, usdt_amount
            FROM daily_rewards WHERE id = ?
          `).bind(t.ref_id).first<any>()
        }
        txDetails.push({
          tx_id: t.id,
          amount: t.amount,
          created_at_kst: t.created_at_kst,
          ref_id: t.ref_id,
          dr: drInfo ? {
            dr_id: drInfo.id, staking_id: drInfo.staking_id,
            reward_date: drInfo.reward_date, paid_date: drInfo.paid_date,
            amount: drInfo.usdt_amount
          } : null
        })
      }

      dupList.push({
        user_id: uid,
        email: u?.email, name: u?.name,
        qkey_balance: u?.qkey_balance,
        tx_count_on_date: row.tx_cnt,
        tx_sum_on_date: row.tx_sum,
        txs: txDetails
      })
    }

    return c.json({
      ok: true,
      target_date_kst: targetDate,
      total_duplicate_users: dupList.length,
      duplicates: dupList,
      note: 'date 기준 daily_qkey tx 2건 이상 user 전수. 각 tx 에 매핑된 dr.reward_date 로 어느 것이 휴일룰 보충 tx 인지 판별 가능.'
    })
  } catch (error) {
    console.error('scan-duplicate-daily-qkey-on-date error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ fix-bulk-delete-holiday-rule-duplicate-tx-515: 5/15 09:00 휴일룰 보충 tx 전수 DELETE ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   boss directive: "15일날 중복 지급된 계정 찾아서 1회로 줄이라고 깨끗하게"
//
//   대상: tx WHERE type='daily_qkey' AND created_at='2026-05-15 00:00:00' (UTC) = '2026-05-15 09:00' (KST)
//     → 이전 휴일룰 보충 작업(어제) 에서 INSERT 된 tx 들. ref_id = dr.id where dr.reward_date='2026-05-14' AND dr.paid_date='2026-05-15'
//
//   5중 검증 (각 row):
//     (a) tx.type = 'daily_qkey'
//     (b) tx.created_at = '2026-05-15 00:00:00' (UTC) — 정확 매칭
//     (c) tx.ref_id is not null
//     (d) dr 행 존재 + dr.reward_date='2026-05-14' AND dr.paid_date='2026-05-15'
//     (e) dr.usdt_amount = tx.amount
//
//   처리: 검증 통과한 tx 만 DELETE + users.qkey_balance -= tx.amount (atomic per-row, D1 트랜잭션 없음)
//   dr 행은 의도적 유지 (rd=5/14 사실/감사 보존)
//
//   경로:
//     DRY_RUN: POST /api/diag/fix-bulk-delete-holiday-rule-duplicate-tx-515?key=ADMIN_PW&dry_run=1
//     실행:   POST /api/diag/fix-bulk-delete-holiday-rule-duplicate-tx-515?key=ADMIN_PW&confirm=GO
app.post('/api/diag/fix-bulk-delete-holiday-rule-duplicate-tx-515', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const dryRun = c.req.query('dry_run') === '1'
    const confirm = c.req.query('confirm') || ''

    // 1) 대상 tx 후보 추출: type='daily_qkey' AND created_at='2026-05-15 00:00:00'
    const candidates = await db.prepare(`
      SELECT id, user_id, type, amount, ref_id, created_at, description
      FROM transactions
      WHERE type = 'daily_qkey'
        AND created_at = '2026-05-15 00:00:00'
      ORDER BY id ASC
    `).all()

    const plan: any[] = []
    const validationFails: any[] = []

    for (const t of (candidates.results as any[])) {
      // 5중 검증
      const v: any = {
        type_match: t.type === 'daily_qkey',
        created_at_match: t.created_at === '2026-05-15 00:00:00',
        ref_id_not_null: !!t.ref_id,
        dr_exists_and_rd514_pd515: false,
        dr_amount_match: false
      }
      let dr: any = null
      if (t.ref_id) {
        dr = await db.prepare(`
          SELECT id, user_id, staking_id, reward_date, paid_date, usdt_amount
          FROM daily_rewards WHERE id = ?
        `).bind(t.ref_id).first<any>()
        if (dr) {
          v.dr_exists_and_rd514_pd515 = (dr.reward_date === '2026-05-14' && dr.paid_date === '2026-05-15' && dr.user_id === t.user_id)
          v.dr_amount_match = Number(dr.usdt_amount) === Number(t.amount)
        }
      }
      const allValid = Object.values(v).every(x => x === true)

      const row = {
        tx_id: t.id,
        user_id: t.user_id,
        amount: t.amount,
        ref_id: t.ref_id,
        created_at: t.created_at,
        dr: dr ? { dr_id: dr.id, rd: dr.reward_date, pd: dr.paid_date, amt: dr.usdt_amount, staking_id: dr.staking_id } : null,
        validation: v,
        valid: allValid
      }
      if (allValid) plan.push(row)
      else validationFails.push(row)
    }

    // 사용자별 합계
    const userMap: Record<number, { user_id: number, tx_count: number, total_deduct: number }> = {}
    for (const p of plan) {
      if (!userMap[p.user_id]) userMap[p.user_id] = { user_id: p.user_id, tx_count: 0, total_deduct: 0 }
      userMap[p.user_id].tx_count += 1
      userMap[p.user_id].total_deduct += Number(p.amount)
    }
    const userSummary = Object.values(userMap).sort((a, b) => a.user_id - b.user_id)
    const totalDeleteCount = plan.length
    const totalDeductAmount = plan.reduce((s, p) => s + Number(p.amount), 0)

    if (dryRun || confirm !== 'GO') {
      return c.json({
        ok: true,
        mode: 'DRY_RUN',
        message: '실제 실행을 원하시면 confirm=GO 추가',
        candidates_found: (candidates.results as any[]).length,
        validation_pass: plan.length,
        validation_fail: validationFails.length,
        total_delete_count: totalDeleteCount,
        total_deduct_amount: totalDeductAmount,
        affected_user_count: userSummary.length,
        user_summary: userSummary,
        plan_sample_first10: plan.slice(0, 10),
        validation_fails: validationFails
      })
    }

    // EXECUTE: atomic per-row (D1 트랜잭션 없음)
    const executed: any[] = []
    const errors: any[] = []
    for (const p of plan) {
      try {
        // user balance before
        const ub = await db.prepare(`SELECT qkey_balance FROM users WHERE id = ?`).bind(p.user_id).first<any>()
        const balanceBefore = Number(ub?.qkey_balance || 0)
        // DELETE tx
        await db.prepare(`DELETE FROM transactions WHERE id = ? AND user_id = ?`).bind(p.tx_id, p.user_id).run()
        // balance 차감
        await db.prepare(`UPDATE users SET qkey_balance = qkey_balance - ? WHERE id = ?`).bind(p.amount, p.user_id).run()
        const ua = await db.prepare(`SELECT qkey_balance FROM users WHERE id = ?`).bind(p.user_id).first<any>()
        executed.push({
          tx_id: p.tx_id, user_id: p.user_id, amount: p.amount, ref_id: p.ref_id,
          balance_before: balanceBefore, balance_after: Number(ua?.qkey_balance || 0)
        })
      } catch (e) {
        errors.push({ tx_id: p.tx_id, user_id: p.user_id, error: String(e) })
      }
    }

    return c.json({
      ok: true,
      mode: 'EXECUTED',
      total_delete_count: executed.length,
      total_deduct_amount: executed.reduce((s, e) => s + Number(e.amount), 0),
      affected_user_count: new Set(executed.map(e => e.user_id)).size,
      executed,
      errors,
      validation_fails: validationFails,
      note: 'tx DELETE + qkey_balance 차감 완료. dr 행은 그대로 유지 (의도적, rd=5/14 사실/감사 보존).'
    })
  } catch (error) {
    console.error('fix-bulk-delete-holiday-rule-duplicate-tx-515 error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ fix-insert-solbat-rd514-missing-rr: solbat 5/14 reward_date 누락 9건 rr+tx INSERT ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   boss directive: "5/13 기준으로 5/14 배당도 맞추라"
//   → reward_date=5/13 unique 12개 referee+level 중 reward_date=5/14 에 없는 9개를 INSERT.
//   영구룰: 5/14(목) 휴일 효과 → paid_date=2026-05-15 (금) 합산 지급
//
//   처리 단위: 단일 user(solbat=44) 하드코딩. 다른 회원 영향 0.
//   허용 referee 9개 (필수 5중 검증):
//     L1 referee_id ∈ {54, 52, 48, 89, 50} amount=150
//     L2 referee_id ∈ {90, 76, 46, 73}     amount=75 (lis7238 76 만 1500)
//
//   경로: POST /api/diag/fix-insert-solbat-rd514-missing-rr?key=ADMIN_PW&dry_run=1
//        실행: POST /api/diag/fix-insert-solbat-rd514-missing-rr?key=ADMIN_PW&confirm=GO
app.post('/api/diag/fix-insert-solbat-rd514-missing-rr', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const dryRun = c.req.query('dry_run') === '1' || c.req.query('dry_run') === 'true'
    const confirm = c.req.query('confirm') || ''
    if (!dryRun && confirm !== 'GO') {
      return c.json({ error: 'confirm=GO 필요 (또는 dry_run=1)' }, 400)
    }
    const db = c.env.DB
    const SOLBAT_ID = 44

    // 누락 9건 (referee_id, level, amount)
    const inserts: Array<{ referee_id: number, level: number, amount: number }> = [
      { referee_id: 54, level: 1, amount: 150 },  // aafhka
      { referee_id: 52, level: 1, amount: 150 },  // csh
      { referee_id: 48, level: 1, amount: 150 },  // naim1970
      { referee_id: 89, level: 1, amount: 150 },  // psj7406
      { referee_id: 50, level: 1, amount: 150 },  // qt1234
      { referee_id: 90, level: 2, amount: 75 },   // cys
      { referee_id: 76, level: 2, amount: 1500 }, // lis7238
      { referee_id: 46, level: 2, amount: 75 },   // pjb5818
      { referee_id: 73, level: 2, amount: 75 },   // pputti
    ]

    // ===== 5중 사전 검증 =====
    // 1) solbat user 존재
    const user: any = await db.prepare(`SELECT id, email, name, qkey_balance FROM users WHERE id = ?`).bind(SOLBAT_ID).first()
    if (!user) return c.json({ error: 'solbat(44) not found' }, 404)
    if (user.email !== 'solbat') return c.json({ error: `user 44 email mismatch: ${user.email}` }, 400)

    // 2) 각 referee 존재 확인 + 3) original_amount(추정 stake amount) 구하기
    const refDetails: any[] = []
    for (const ins of inserts) {
      const ref: any = await db.prepare(`SELECT id, email, name FROM users WHERE id = ?`).bind(ins.referee_id).first()
      if (!ref) return c.json({ error: `referee ${ins.referee_id} not found` }, 404)

      // 4) reward_date=5/13 에 동일 referee+level rr 존재(=패턴 기준)
      const has513: any = await db.prepare(`
        SELECT COUNT(*) AS cnt, MAX(original_amount) AS orig_amt
        FROM referral_rewards
        WHERE referrer_id=? AND referee_id=? AND level=? AND reward_date='2026-05-13'
      `).bind(SOLBAT_ID, ins.referee_id, ins.level).first()
      if (!has513 || Number(has513.cnt) === 0) {
        return c.json({ error: `referee ${ins.referee_id} L${ins.level} 5/13 rd 없음 → 패턴 위반` }, 400)
      }

      // 5) reward_date=5/14 에 중복 INSERT 방지 (이미 있으면 skip 또는 에러)
      const has514: any = await db.prepare(`
        SELECT COUNT(*) AS cnt
        FROM referral_rewards
        WHERE referrer_id=? AND referee_id=? AND level=? AND reward_date='2026-05-14'
      `).bind(SOLBAT_ID, ins.referee_id, ins.level).first()
      if (Number(has514.cnt) > 0) {
        return c.json({ error: `referee ${ins.referee_id} L${ins.level} 5/14 rd 이미 존재 (중복 INSERT 방지)` }, 400)
      }

      refDetails.push({
        referee_id: ins.referee_id, email: ref.email, level: ins.level, amount: ins.amount,
        original_amount: Number(has513.orig_amt || 0),
        rd_513_cnt: Number(has513.cnt),
        rd_514_cnt_before: Number(has514.cnt),
      })
    }

    const totalAmount = inserts.reduce((a, b) => a + b.amount, 0)

    if (dryRun) {
      return c.json({
        ok: true, dry_run: true,
        user: { id: user.id, email: user.email, balance_before: user.qkey_balance, balance_after_expected: Number(user.qkey_balance) + totalAmount },
        validation: { solbat_user_match: true, all_referees_exist: true, all_have_rd513_pattern: true, no_rd514_duplicate: true, total_inserts: inserts.length },
        plan: refDetails,
        total_amount: totalAmount,
        note: 'rd=2026-05-14, pd=2026-05-15 (영구룰 휴일 합산), tx description=영구룰 표기'
      })
    }

    // ===== EXECUTE =====
    const results: any[] = []
    let okCount = 0
    let errCount = 0
    const nowIso = new Date().toISOString().slice(0, 19).replace('T', ' ')

    for (const rd of refDetails) {
      try {
        // 1) referral_rewards INSERT
        const rrIns = await db.prepare(`
          INSERT INTO referral_rewards
            (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, created_at)
          VALUES (?, ?, ?, ?, ?, '2026-05-14', '2026-05-15', ?)
        `).bind(SOLBAT_ID, rd.referee_id, rd.level, rd.original_amount, rd.amount, nowIso).run()
        const newRrId = (rrIns as any).meta?.last_row_id

        // 2) transactions INSERT (영구룰 desc: "추천 보너스 (Level 1/2)")
        const desc = `추천 보너스 (Level ${rd.level})`
        const txIns = await db.prepare(`
          INSERT INTO transactions
            (user_id, type, coin_type, amount, description, ref_id, created_at)
          VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?, ?)
        `).bind(SOLBAT_ID, rd.amount, desc, String(newRrId), nowIso).run()
        const newTxId = (txIns as any).meta?.last_row_id

        // 3) users.qkey_balance += amount
        await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(rd.amount, SOLBAT_ID).run()

        results.push({ ok: true, referee_id: rd.referee_id, email: rd.email, level: rd.level, amount: rd.amount, new_rr_id: newRrId, new_tx_id: newTxId })
        okCount++
      } catch (e) {
        results.push({ ok: false, referee_id: rd.referee_id, email: rd.email, level: rd.level, error: String(e) })
        errCount++
      }
    }

    const userAfter: any = await db.prepare(`SELECT qkey_balance FROM users WHERE id = ?`).bind(SOLBAT_ID).first()

    return c.json({
      ok: errCount === 0,
      executed: true,
      summary: { ok: okCount, err: errCount, total_amount_inserted: totalAmount },
      balance_before: user.qkey_balance,
      balance_after: userAfter?.qkey_balance,
      results,
    })
  } catch (error) {
    console.error('fix-insert-solbat-rd514-missing-rr error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ fix-solbat-align-daily-3750: solbat 매일 본인 750 + L1 1050 + L2 1950 = 3750 정렬 ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   boss 영구룰: solbat 매일 본인 750 + L1 합 1050 + L2 합 1950 = 3750 QKEY
//
//   현 상태(EXECUTE 직전):
//     5/11=3750(O)  5/12=3450(-300)  5/13=6000(+2250)  5/14=3825(+75)  5/15=750(-3000)
//
//   처리 (2 STEP):
//     STEP A) UPDATE rr.reward_date — 잉여 12건을 reward_date=5/15로 이동 (balance 영향 0)
//       5/13 rd & paid=5/15 인 9건 → rd=5/15
//       5/14 rd & paid=5/15 인 3건 → rd=5/15
//     STEP B) INSERT rr+tx — 부족 9건 보충 (balance +975)
//       5/12: lis7239 L1 150, naim197059 L2 75, afhka L2 75 → +300
//       5/13: lis7239 L1 150, naim197059 L2 75            → +225
//       5/14: lis7239 L1 150, naim197059 L2 75            → +225
//       5/15: lis7239 L1 150, naim197059 L2 75            → +225
//
//   EXECUTE 후 기대: 5/12~5/15 모두 = 3750 ✅, balance 39525 → 40500
//
//   경로: POST /api/diag/fix-solbat-align-daily-3750?key=ADMIN_PW&dry_run=1
//        실행: POST /api/diag/fix-solbat-align-daily-3750?key=ADMIN_PW&confirm=GO
app.post('/api/diag/fix-solbat-align-daily-3750', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const dryRun = c.req.query('dry_run') === '1' || c.req.query('dry_run') === 'true'
    const confirm = c.req.query('confirm') || ''
    if (!dryRun && confirm !== 'GO') {
      return c.json({ error: 'confirm=GO 필요 (또는 dry_run=1)' }, 400)
    }
    const db = c.env.DB
    const SOLBAT_ID = 44

    // STEP A: 재배치 12건 (rr_id 정확히 지정)
    const relocates: Array<{ rr_id: number, level: number, referee_email: string, amt: number, from: string, to: string }> = [
      { rr_id: 1687, level: 1, referee_email: 'aafhka',     amt: 150,  from: '2026-05-13', to: '2026-05-15' },
      { rr_id: 1699, level: 1, referee_email: 'csh',        amt: 150,  from: '2026-05-13', to: '2026-05-15' },
      { rr_id: 1744, level: 2, referee_email: 'cys',        amt: 75,   from: '2026-05-13', to: '2026-05-15' },
      { rr_id: 1724, level: 2, referee_email: 'lis7238',    amt: 1500, from: '2026-05-13', to: '2026-05-15' },
      { rr_id: 1682, level: 1, referee_email: 'naim1970',   amt: 150,  from: '2026-05-13', to: '2026-05-15' },
      { rr_id: 1686, level: 2, referee_email: 'pjb5818',    amt: 75,   from: '2026-05-13', to: '2026-05-15' },
      { rr_id: 1720, level: 2, referee_email: 'pputti',     amt: 75,   from: '2026-05-13', to: '2026-05-15' },
      { rr_id: 1741, level: 1, referee_email: 'psj7406',    amt: 150,  from: '2026-05-13', to: '2026-05-15' },
      { rr_id: 1680, level: 1, referee_email: 'qt1234',     amt: 150,  from: '2026-05-13', to: '2026-05-15' },
      { rr_id: 1750, level: 2, referee_email: 'naim197059', amt: 75,   from: '2026-05-14', to: '2026-05-15' },
      { rr_id: 1751, level: 1, referee_email: 'lis7239',    amt: 150,  from: '2026-05-14', to: '2026-05-15' },
      { rr_id: 1764, level: 2, referee_email: 'afhka',      amt: 75,   from: '2026-05-14', to: '2026-05-15' },
    ]

    // STEP B: 부족 INSERT 9건
    const inserts: Array<{ rd: string, pd: string, referee_id: number, referee_email: string, level: number, amount: number, orig: number }> = [
      // 5/12 부족 -300
      { rd: '2026-05-12', pd: '2026-05-13', referee_id: 45, referee_email: 'lis7239',    level: 1, amount: 150, orig: 750 },
      { rd: '2026-05-12', pd: '2026-05-13', referee_id: 49, referee_email: 'naim197059', level: 2, amount: 75,  orig: 750 },
      { rd: '2026-05-12', pd: '2026-05-13', referee_id: 93, referee_email: 'afhka',      level: 2, amount: 75,  orig: 750 },
      // 5/13 부족 -225
      { rd: '2026-05-13', pd: '2026-05-14', referee_id: 45, referee_email: 'lis7239',    level: 1, amount: 150, orig: 750 },
      { rd: '2026-05-13', pd: '2026-05-14', referee_id: 49, referee_email: 'naim197059', level: 2, amount: 75,  orig: 750 },
      // 5/14 부족 -225
      { rd: '2026-05-14', pd: '2026-05-15', referee_id: 45, referee_email: 'lis7239',    level: 1, amount: 150, orig: 750 },
      { rd: '2026-05-14', pd: '2026-05-15', referee_id: 49, referee_email: 'naim197059', level: 2, amount: 75,  orig: 750 },
      // 5/15 부족 -225
      { rd: '2026-05-15', pd: '2026-05-15', referee_id: 45, referee_email: 'lis7239',    level: 1, amount: 150, orig: 750 },
      { rd: '2026-05-15', pd: '2026-05-15', referee_id: 49, referee_email: 'naim197059', level: 2, amount: 75,  orig: 750 },
    ]

    // ===== 사전 5중 검증 =====
    const user: any = await db.prepare(`SELECT id, email, qkey_balance FROM users WHERE id = ?`).bind(SOLBAT_ID).first()
    if (!user) return c.json({ error: 'solbat not found' }, 404)
    if (user.email !== 'solbat') return c.json({ error: `email mismatch: ${user.email}` }, 400)

    // STEP A 검증: 각 rr이 존재 + referrer=44 + reward_date=from + paid_date=to + reward_amount=amt
    const aValidation: any[] = []
    for (const rl of relocates) {
      const row: any = await db.prepare(`SELECT id, referrer_id, referee_id, level, reward_amount, reward_date, paid_date FROM referral_rewards WHERE id = ?`).bind(rl.rr_id).first()
      if (!row) return c.json({ error: `rr#${rl.rr_id} not found (relocate STEP A)` }, 404)
      const ok =
        row.referrer_id === SOLBAT_ID &&
        Number(row.level) === rl.level &&
        Number(row.reward_amount) === rl.amt &&
        row.reward_date === rl.from &&
        row.paid_date === rl.to
      if (!ok) return c.json({ error: `rr#${rl.rr_id} 5중 검증 실패 (실제 ${JSON.stringify(row)} vs 기대 ${JSON.stringify(rl)})` }, 400)
      aValidation.push({ rr_id: rl.rr_id, ok: true })
    }

    // STEP B 검증: 각 referee 존재
    const bValidation: any[] = []
    for (const ins of inserts) {
      const ref: any = await db.prepare(`SELECT id, email FROM users WHERE id = ?`).bind(ins.referee_id).first()
      if (!ref) return c.json({ error: `referee ${ins.referee_id} (${ins.referee_email}) not found (insert STEP B)` }, 404)
      if (ref.email !== ins.referee_email) return c.json({ error: `referee ${ins.referee_id} email mismatch: ${ref.email} vs ${ins.referee_email}` }, 400)
      bValidation.push({ referee_id: ins.referee_id, email: ref.email, ok: true })
    }

    const totalInsertAmt = inserts.reduce((a, b) => a + b.amount, 0)

    if (dryRun) {
      return c.json({
        ok: true, dry_run: true,
        user: { id: user.id, email: user.email, balance_before: user.qkey_balance, balance_after_expected: Number(user.qkey_balance) + totalInsertAmt },
        step_A_relocate: { count: relocates.length, balance_delta: 0, validation_ok: aValidation.length === relocates.length, items: relocates },
        step_B_insert: { count: inserts.length, balance_delta: totalInsertAmt, validation_ok: bValidation.length === inserts.length, items: inserts },
        expected_daily_3750: {
          '5/12': 3450 + 300,
          '5/13': 6000 - 2475 + 225,
          '5/14': 3825 - 300 + 225,
          '5/15': 750 + 2475 + 300 + 225,
        }
      })
    }

    // ===== EXECUTE =====
    const results = { step_A: [] as any[], step_B: [] as any[], errors: [] as any[] }
    const nowIso = new Date().toISOString().slice(0, 19).replace('T', ' ')

    // STEP A: UPDATE rr.reward_date
    for (const rl of relocates) {
      try {
        await db.prepare(`UPDATE referral_rewards SET reward_date = ? WHERE id = ? AND referrer_id = ?`).bind(rl.to, rl.rr_id, SOLBAT_ID).run()
        results.step_A.push({ ok: true, rr_id: rl.rr_id, referee_email: rl.referee_email, level: rl.level, amt: rl.amt, rd_from: rl.from, rd_to: rl.to })
      } catch (e) {
        results.step_A.push({ ok: false, rr_id: rl.rr_id, error: String(e) })
        results.errors.push({ step: 'A', rr_id: rl.rr_id, error: String(e) })
      }
    }

    // STEP B: INSERT rr + tx + balance
    for (const ins of inserts) {
      try {
        // 1) rr INSERT
        const rrIns = await db.prepare(`
          INSERT INTO referral_rewards
            (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, created_at)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        `).bind(SOLBAT_ID, ins.referee_id, ins.level, ins.orig, ins.amount, ins.rd, ins.pd, nowIso).run()
        const newRrId = (rrIns as any).meta?.last_row_id

        // 2) tx INSERT (영구룰 desc)
        const desc = `추천 보너스 (Level ${ins.level})`
        const txIns = await db.prepare(`
          INSERT INTO transactions
            (user_id, type, coin_type, amount, description, ref_id, created_at)
          VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?, ?)
        `).bind(SOLBAT_ID, ins.amount, desc, String(newRrId), nowIso).run()
        const newTxId = (txIns as any).meta?.last_row_id

        // 3) balance +
        await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(ins.amount, SOLBAT_ID).run()

        results.step_B.push({ ok: true, referee_email: ins.referee_email, level: ins.level, amount: ins.amount, rd: ins.rd, pd: ins.pd, new_rr_id: newRrId, new_tx_id: newTxId })
      } catch (e) {
        results.step_B.push({ ok: false, referee_email: ins.referee_email, error: String(e) })
        results.errors.push({ step: 'B', referee_email: ins.referee_email, error: String(e) })
      }
    }

    const userAfter: any = await db.prepare(`SELECT qkey_balance FROM users WHERE id = ?`).bind(SOLBAT_ID).first()

    // 사후 검증: 각 날짜 합계
    const dailySums: any = {}
    for (const d of ['2026-05-12', '2026-05-13', '2026-05-14', '2026-05-15']) {
      const dr: any = await db.prepare(`SELECT IFNULL(SUM(usdt_amount),0) AS s FROM daily_rewards WHERE user_id = ? AND reward_date = ?`).bind(SOLBAT_ID, d).first()
      const l1: any = await db.prepare(`SELECT IFNULL(SUM(reward_amount),0) AS s FROM referral_rewards WHERE referrer_id = ? AND level = 1 AND reward_date = ?`).bind(SOLBAT_ID, d).first()
      const l2: any = await db.prepare(`SELECT IFNULL(SUM(reward_amount),0) AS s FROM referral_rewards WHERE referrer_id = ? AND level = 2 AND reward_date = ?`).bind(SOLBAT_ID, d).first()
      dailySums[d] = { self: Number(dr?.s || 0), L1: Number(l1?.s || 0), L2: Number(l2?.s || 0), total: Number(dr?.s || 0) + Number(l1?.s || 0) + Number(l2?.s || 0) }
    }

    return c.json({
      ok: results.errors.length === 0,
      executed: true,
      balance_before: user.qkey_balance,
      balance_after: userAfter?.qkey_balance,
      summary: { step_A_count: relocates.length, step_B_count: inserts.length, total_insert_amount: totalInsertAmt, errors: results.errors.length },
      daily_sums_after: dailySums,
      verification: {
        '5/12_is_3750': dailySums['2026-05-12'].total === 3750,
        '5/13_is_3750': dailySums['2026-05-13'].total === 3750,
        '5/14_is_3750': dailySums['2026-05-14'].total === 3750,
        '5/15_is_3750': dailySums['2026-05-15'].total === 3750,
      },
      results,
    })
  } catch (error) {
    console.error('fix-solbat-align-daily-3750 error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ referral_rewards 있는데 transactions 없는 case 전수 스캔 (L1/L2 매칭 누락용) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   목적: solbat L1/L2 누락 case 처럼 rr 행은 있는데 tx 행이 없는 case 전수
//
//   경로: GET /api/diag/scan-rr-without-tx?key=ADMIN_PW&date_from=2026-05-11&date_to=2026-05-15
app.get('/api/diag/scan-rr-without-tx', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const dateFrom = c.req.query('date_from') || '2026-05-11'
    const dateTo = c.req.query('date_to') || '2026-05-15'

    const rows = await db.prepare(`
      SELECT rr.id AS rr_id, rr.referrer_id AS user_id, rr.referee_id, rr.level,
             rr.original_amount, rr.reward_amount AS qkey, rr.reward_date, rr.paid_date, rr.created_at AS rr_created,
             u.email, u.name, u.qkey_balance
      FROM referral_rewards rr
      JOIN users u ON u.id = rr.referrer_id
      LEFT JOIN transactions tx
        ON tx.user_id = rr.referrer_id
        AND tx.type = 'referral_reward'
        AND tx.ref_id = rr.id
      WHERE rr.paid_date >= ? AND rr.paid_date <= ?
        AND tx.id IS NULL
      ORDER BY rr.referrer_id, rr.paid_date, rr.level
    `).bind(dateFrom, dateTo).all<any>()

    const byUser: Record<string, any> = {}
    for (const r of (rows.results || [])) {
      const k = String(r.user_id)
      if (!byUser[k]) {
        byUser[k] = {
          user_id: r.user_id, email: r.email, name: r.name, qkey_balance: r.qkey_balance,
          total_missing_qkey: 0, missing_count: 0, items: []
        }
      }
      byUser[k].total_missing_qkey += Number(r.qkey || 0)
      byUser[k].missing_count += 1
      byUser[k].items.push({
        rr_id: r.rr_id, referee_id: r.referee_id, level: r.level,
        original_amount: r.original_amount, qkey: r.qkey,
        reward_date: r.reward_date, paid_date: r.paid_date, rr_created: r.rr_created
      })
    }

    const userList = Object.values(byUser).sort((a: any, b: any) => b.total_missing_qkey - a.total_missing_qkey)
    const totalMissing = userList.reduce((acc: number, u: any) => acc + u.total_missing_qkey, 0)

    return c.json({
      success: true,
      date_from: dateFrom,
      date_to: dateTo,
      total_rr_without_tx_count: (rows.results || []).length,
      total_missing_qkey: totalMissing,
      affected_users_count: userList.length,
      affected_users: userList
    })
  } catch (error) {
    console.error('scan-rr-without-tx error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ QKEY 잔액 정합성 전수 스캔: users.qkey_balance vs Σ(daily + referral - withdrawal) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   목적: 합계 안 맞는 계정 전수조사 — boss 직접 요청
//   계산식:
//     expected_balance =
//         Σ(transactions.amount WHERE type='daily_qkey' AND coin_type='QKEY')
//       + Σ(transactions.amount WHERE type='referral_reward' AND coin_type='QKEY')
//       - Σ(withdrawals.amount WHERE coin_type='QKEY' AND status IN ('approved','completed','processing','pending'))
//     mismatch = users.qkey_balance - expected_balance
//   안전성: SELECT only, UPDATE 없음
//   경로: GET /api/diag/scan-balance-mismatch?key=ADMIN_PW
//        옵션: &threshold=1  (|diff|>=1 만 보고), &limit=200
app.get('/api/diag/scan-balance-mismatch', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const threshold = Number(c.req.query('threshold') || '1')
    const limit = parseInt(c.req.query('limit') || '500')

    // 1) users 전체 (qkey_balance != null)
    const users = await db.prepare(`
      SELECT id, email, name, qkey_balance
      FROM users
      WHERE qkey_balance IS NOT NULL
      ORDER BY id ASC
    `).all<any>()

    // 2) tx 합계 by user (daily + referral)
    const txSums = await db.prepare(`
      SELECT user_id,
             SUM(CASE WHEN type='daily_qkey' THEN amount ELSE 0 END) AS sum_daily,
             SUM(CASE WHEN type='referral_reward' THEN amount ELSE 0 END) AS sum_referral
      FROM transactions
      WHERE coin_type = 'QKEY'
        AND type IN ('daily_qkey','referral_reward')
      GROUP BY user_id
    `).all<any>()

    // 3) 출금 합계 by user (pending+approved+completed+processing 모두 포함 = 이미 잔액에서 차감된 것)
    const wdSums = await db.prepare(`
      SELECT user_id,
             SUM(amount) AS sum_withdraw
      FROM withdrawals
      WHERE coin_type = 'QKEY'
        AND status IN ('approved','completed','processing','pending')
      GROUP BY user_id
    `).all<any>()

    const txMap: Record<string, { d: number, r: number }> = {}
    for (const row of (txSums.results || [])) {
      txMap[String(row.user_id)] = { d: Number(row.sum_daily || 0), r: Number(row.sum_referral || 0) }
    }
    const wdMap: Record<string, number> = {}
    for (const row of (wdSums.results || [])) {
      wdMap[String(row.user_id)] = Number(row.sum_withdraw || 0)
    }

    const mismatches: any[] = []
    let totalChecked = 0
    let totalOk = 0
    let totalNegative = 0

    for (const u of (users.results || [])) {
      totalChecked++
      const k = String(u.id)
      const sumDaily = txMap[k]?.d || 0
      const sumReferral = txMap[k]?.r || 0
      const sumWd = wdMap[k] || 0
      const expected = sumDaily + sumReferral - sumWd
      const actual = Number(u.qkey_balance || 0)
      const diff = actual - expected

      if (actual < 0) totalNegative++

      if (Math.abs(diff) >= threshold) {
        mismatches.push({
          user_id: u.id, email: u.email, name: u.name,
          qkey_balance: actual,
          sum_daily_tx: sumDaily,
          sum_referral_tx: sumReferral,
          sum_withdraw: sumWd,
          expected_balance: expected,
          diff: diff,
          diff_sign: diff > 0 ? 'BALANCE_HIGH_THAN_TX' : 'BALANCE_LOW_THAN_TX',
          negative_balance: actual < 0
        })
      } else {
        totalOk++
      }
    }

    // diff 절대값 큰 순 정렬
    mismatches.sort((a, b) => Math.abs(b.diff) - Math.abs(a.diff))
    const top = mismatches.slice(0, limit)

    const totalDiffAbs = mismatches.reduce((acc, m) => acc + Math.abs(m.diff), 0)
    const totalDiffSigned = mismatches.reduce((acc, m) => acc + m.diff, 0)

    return c.json({
      success: true,
      summary: {
        total_users_checked: totalChecked,
        users_ok: totalOk,
        users_mismatch: mismatches.length,
        users_with_negative_balance: totalNegative,
        sum_abs_diff: totalDiffAbs,
        sum_signed_diff: totalDiffSigned,
        threshold,
        returned: top.length
      },
      mismatches: top
    })
  } catch (error) {
    console.error('scan-balance-mismatch error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ 단일 회원 referral_rewards tx 백필 (solbat 같은 case 용) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   경로: POST /api/diag/fix-tx-for-rr?key=ADMIN_PW&user_id=44&paid_dates=2026-05-15&dry_run=1
//        실행: confirm=GO 추가
app.post('/api/diag/fix-tx-for-rr', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const userId = parseInt(c.req.query('user_id') || '0')
    const paidDatesParam = c.req.query('paid_dates') || ''
    const dryRun = c.req.query('dry_run') === '1'
    const confirm = c.req.query('confirm') || ''

    if (!userId) return c.json({ error: 'user_id required' }, 400)
    if (!paidDatesParam) return c.json({ error: 'paid_dates required (comma-separated)' }, 400)

    const paidDates = paidDatesParam.split(',').map(s => s.trim()).filter(Boolean)

    const user = await db.prepare(`SELECT id, email, name, qkey_balance FROM users WHERE id = ?`).bind(userId).first<any>()
    if (!user) return c.json({ error: 'user not found', user_id: userId }, 404)

    const plan: any[] = []
    let totalToAdd = 0

    for (const pd of paidDates) {
      const rrRows = await db.prepare(`
        SELECT id AS rr_id, referrer_id AS user_id, referee_id, level,
               original_amount, reward_amount AS qkey, reward_date, paid_date, created_at AS rr_created
        FROM referral_rewards
        WHERE referrer_id = ? AND paid_date = ?
        ORDER BY id
      `).bind(userId, pd).all<any>()

      for (const rr of (rrRows.results || [])) {
        const existingTx = await db.prepare(`
          SELECT id, amount FROM transactions
          WHERE user_id = ? AND type = 'referral_reward' AND ref_id = ?
          LIMIT 1
        `).bind(userId, rr.rr_id).first<any>()

        if (existingTx) {
          plan.push({
            action: 'SKIP_TX_EXISTS',
            rr_id: rr.rr_id, level: rr.level, paid_date: rr.paid_date, qkey: rr.qkey,
            existing_tx_id: existingTx.id
          })
        } else {
          plan.push({
            action: 'INSERT_TX',
            rr_id: rr.rr_id, level: rr.level, paid_date: rr.paid_date, qkey: rr.qkey,
            reward_date: rr.reward_date, referee_id: rr.referee_id
          })
          totalToAdd += Number(rr.qkey || 0)
        }
      }
    }

    if (dryRun || confirm !== 'GO') {
      return c.json({
        success: true,
        mode: 'DRY_RUN',
        message: '실제 실행을 원하시면 confirm=GO 추가',
        user: { id: user.id, email: user.email, name: user.name, qkey_balance_before: user.qkey_balance },
        target: { user_id: userId, paid_dates: paidDates },
        plan,
        plan_summary: {
          to_insert_tx_count: plan.filter(p => p.action === 'INSERT_TX').length,
          to_skip_count: plan.filter(p => p.action === 'SKIP_TX_EXISTS').length,
          qkey_to_add: totalToAdd,
          qkey_balance_after: user.qkey_balance + totalToAdd
        }
      })
    }

    // EXECUTE
    let insertedTxIds: number[] = []
    let actualAdded = 0
    for (const item of plan) {
      if (item.action === 'INSERT_TX') {
        // description: 영구룰 — '추천 보너스 (Level 1)' 또는 '추천 보너스 (Level 2)' 만
        const desc = item.level === 1 ? '추천 보너스 (Level 1)' : '추천 보너스 (Level 2)'
        const ins = await db.prepare(`
          INSERT INTO transactions (user_id, type, amount, coin_type, description, ref_id, created_at)
          VALUES (?, 'referral_reward', ?, 'QKEY', ?, ?, datetime('now'))
        `).bind(userId, item.qkey, desc, item.rr_id).run()

        const newTxId = (ins as any).meta?.last_row_id || null
        if (newTxId) insertedTxIds.push(newTxId)
        actualAdded += Number(item.qkey || 0)
      }
    }

    if (actualAdded > 0) {
      await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(actualAdded, userId).run()
    }

    const userAfter = await db.prepare(`SELECT qkey_balance FROM users WHERE id = ?`).bind(userId).first<any>()

    return c.json({
      success: true,
      mode: 'EXECUTED',
      user: { id: user.id, email: user.email, name: user.name,
              qkey_balance_before: user.qkey_balance,
              qkey_balance_after: userAfter?.qkey_balance || null },
      target: { user_id: userId, paid_dates: paidDates },
      plan,
      result: {
        inserted_tx_count: insertedTxIds.length,
        inserted_tx_ids: insertedTxIds,
        skipped_count: plan.filter(p => p.action === 'SKIP_TX_EXISTS').length,
        qkey_added: actualAdded
      }
    })
  } catch (error) {
    console.error('fix-tx-for-rr error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ 5/14 paid_date 보강 미러링 — A안 강행 (사장님 2026-05-15 결재 "A안으로 해줘") ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   사장님 원문: "A안으로 해줘" (5/14와 무조건 동일하게)
//
//   배경: topup-may15-referrals 는 EXISTS 키가 (referrer_id, referee_id, level, reward_date='2026-05-15')
//        라서 5/14 paid_date 의 row 중 reward_date=2026-05-13 인 8건 (legacy 지연 페이) 을
//        5/15 에 미러링하지 못함. verify 결과 정확히 -1,800 QKEY 차이.
//
//   verify 식별 8명 누락 (총 1,800 QKEY):
//     user 1 (QTA엔젤):  L2 -300
//     user 2 (연이):     L1 -600, L2 -75
//     user 41 (강세미):  L1 -150
//     user 42 (빅빡공):  L2 -75
//     user 44 (강인팔):  L1 -150, L2 -75
//     user 48 (주희):    L1 -150
//     user 49 (유정):    L2 -75
//     user 57 (유선):    ?
//
//   처리: 5/14 paid_date 의 모든 referral_rewards 를 5/15 paid_date 로 1:1 미러링.
//         단, 5/15 paid_date 에 동일 source 행이 이미 존재하면 skip (멱등).
//         EXISTS 키 = (referrer_id, referee_id, level, reward_amount, original_amount, reward_date)
//         — reward_date 까지 키에 포함하여 동일 source row 중복 방지하면서 누락분만 INSERT
//
//   경로: POST /api/diag/mirror-may14-paid-to-may15?key=ADMIN_PW&dry_run=1
//         POST /api/diag/mirror-may14-paid-to-may15?key=ADMIN_PW&confirm=GO
app.post('/api/diag/mirror-may14-paid-to-may15', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const dryRun = c.req.query('dry_run') === '1'
    const confirm = c.req.query('confirm') || ''
    if (!dryRun && confirm !== 'GO') {
      return c.json({ error: 'Missing confirm=GO (or use dry_run=1)' }, 400)
    }

    const SRC_PAID_DATE = '2026-05-14'
    const DST_PAID_DATE = '2026-05-15'

    // STEP 1 — 5/14 paid_date 의 모든 referral_rewards (read-only)
    const srcRr = await db.prepare(`
      SELECT id, referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date
      FROM referral_rewards WHERE paid_date = ?
      ORDER BY id ASC
    `).bind(SRC_PAID_DATE).all() as any
    const srcRrRows = (srcRr?.results || []) as any[]

    // STEP 2 — 각 행을 5/15 paid_date 에 미러링 계획
    // EXISTS 키 = (referrer_id, referee_id, level, reward_amount, original_amount, reward_date, paid_date='2026-05-15')
    // (reward_date 까지 매칭 → 같은 source row 의 미러 중복 방지)
    const plan: any[] = []
    let toInsertCount = 0
    let alreadyExistsCount = 0
    let toInsertQkey = 0
    const balanceDeltas: Record<number, number> = {}

    for (const src of srcRrRows) {
      const exists = await db.prepare(`
        SELECT id FROM referral_rewards
        WHERE referrer_id = ? AND referee_id = ? AND level = ?
          AND reward_amount = ? AND COALESCE(original_amount, 0) = COALESCE(?, 0)
          AND reward_date = ? AND paid_date = ?
        LIMIT 1
      `).bind(
        src.referrer_id, src.referee_id, src.level,
        src.reward_amount, src.original_amount,
        src.reward_date, DST_PAID_DATE
      ).first() as any

      if (exists) {
        alreadyExistsCount++
        plan.push({
          src_rr_id: src.id,
          action: 'skip_exists',
          existing_dst_rr_id: exists.id,
          referrer_id: src.referrer_id,
          referee_id: src.referee_id,
          level: src.level,
          reward_date: src.reward_date,
          reward_amount: src.reward_amount
        })
      } else {
        toInsertCount++
        toInsertQkey += Number(src.reward_amount || 0)
        const uid = Number(src.referrer_id)
        balanceDeltas[uid] = (balanceDeltas[uid] || 0) + Number(src.reward_amount || 0)
        plan.push({
          src_rr_id: src.id,
          action: 'insert',
          referrer_id: src.referrer_id,
          referee_id: src.referee_id,
          level: src.level,
          reward_date: src.reward_date,
          original_amount: src.original_amount,
          reward_amount: src.reward_amount
        })
      }
    }

    if (dryRun) {
      return c.json({
        success: true,
        mode: 'DRY_RUN',
        message: '실제 실행을 원하시면 confirm=GO 파라미터를 추가하세요',
        src_paid_date: SRC_PAID_DATE,
        dst_paid_date: DST_PAID_DATE,
        src_rr_total: srcRrRows.length,
        plan_summary: {
          to_insert_count: toInsertCount,
          already_exists_count: alreadyExistsCount,
          to_insert_qkey: toInsertQkey,
          affected_users: Object.keys(balanceDeltas).length
        },
        balance_deltas: balanceDeltas,
        plan_inserts_only: plan.filter(p => p.action === 'insert')
      })
    }

    // STEP 3 — EXECUTE
    const executed = {
      referral_rewards_inserted: 0,
      referral_rewards_skipped_exists: 0,
      transactions_inserted: 0,
      balance_users_updated: 0
    }
    const insertedDetails: any[] = []
    const balanceActual: Record<number, number> = {}

    for (const src of srcRrRows) {
      const exists = await db.prepare(`
        SELECT id FROM referral_rewards
        WHERE referrer_id = ? AND referee_id = ? AND level = ?
          AND reward_amount = ? AND COALESCE(original_amount, 0) = COALESCE(?, 0)
          AND reward_date = ? AND paid_date = ?
        LIMIT 1
      `).bind(
        src.referrer_id, src.referee_id, src.level,
        src.reward_amount, src.original_amount,
        src.reward_date, DST_PAID_DATE
      ).first() as any

      if (exists) {
        executed.referral_rewards_skipped_exists++
        continue
      }

      const rrIns = await db.prepare(`
        INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date)
        VALUES (?, ?, ?, ?, ?, ?, ?)
      `).bind(
        src.referrer_id, src.referee_id, src.level,
        src.original_amount, src.reward_amount,
        src.reward_date, DST_PAID_DATE
      ).run()
      const newRrId = (rrIns as any)?.meta?.last_row_id ?? null
      if (!newRrId) continue
      executed.referral_rewards_inserted++

      // transactions mirror
      const level = Number(src.level)
      const desc = level === 1 ? '추천 보너스 (Level 1)' : (level === 2 ? '추천 보너스 (Level 2)' : '추천 보너스')
      await db.prepare(`
        INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
        VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?)
      `).bind(src.referrer_id, src.reward_amount, desc, newRrId).run()
      executed.transactions_inserted++

      // qkey_balance 가산
      await db.prepare('UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?')
        .bind(src.reward_amount, src.referrer_id).run()

      const uid = Number(src.referrer_id)
      balanceActual[uid] = (balanceActual[uid] || 0) + Number(src.reward_amount || 0)

      insertedDetails.push({
        src_rr_id: src.id,
        new_rr_id: newRrId,
        referrer_id: src.referrer_id,
        referee_id: src.referee_id,
        level: src.level,
        reward_date: src.reward_date,
        reward_amount: src.reward_amount
      })
    }

    executed.balance_users_updated = Object.keys(balanceActual).length

    return c.json({
      success: true,
      mode: 'EXECUTED',
      src_paid_date: SRC_PAID_DATE,
      dst_paid_date: DST_PAID_DATE,
      src_rr_total: srcRrRows.length,
      executed,
      balance_actual_deltas: balanceActual,
      inserted_count: insertedDetails.length,
      inserted_details: insertedDetails
    })
  } catch (error) {
    console.error('mirror-may14-paid-to-may15 error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ 5/15 잔존 중복 2건 정확 정리 (사장님 2026-05-15 결재) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   사장님 지시: "5/15 잔존 중복 2건 정리후 A안"
//
//   대상: referral_rewards.id IN (1604, 1605)
//     - id=1604: referrer=2, referee=42, level=2, reward_date=2026-05-15, amount=75 (keep=1577)
//     - id=1605: referrer=42, referee=45, level=2, reward_date=2026-05-15, amount=75 (keep=1587)
//   처리: dup row 삭제 + 연관 transactions 삭제 + qkey_balance 차감 (75씩 user 2, 42)
//   경로: POST /api/diag/cleanup-may15-residual-dups?key=ADMIN_PW&confirm=GO
app.post('/api/diag/cleanup-may15-residual-dups', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const dryRun = c.req.query('dry_run') === '1'
    const confirm = c.req.query('confirm') || ''
    if (!dryRun && confirm !== 'GO') {
      return c.json({ error: 'Missing confirm=GO (or use dry_run=1)' }, 400)
    }

    // 정확히 이 2건만 정리 (audit 결과 확정)
    const TARGET_DUPS = [
      { dup_id: 1604, keep_id: 1577, referrer_id: 2,  referee_id: 42, level: 2, amount: 75, reward_date: '2026-05-15', paid_date: '2026-05-15' },
      { dup_id: 1605, keep_id: 1587, referrer_id: 42, referee_id: 45, level: 2, amount: 75, reward_date: '2026-05-15', paid_date: '2026-05-15' }
    ]

    const plan: any[] = []
    const balanceDeltas: Record<string, number> = {}

    for (const t of TARGET_DUPS) {
      // 1) dup row 존재 확인
      const dupRow = await db.prepare(
        'SELECT id, referrer_id, referee_id, level, reward_amount, reward_date, paid_date FROM referral_rewards WHERE id = ?'
      ).bind(t.dup_id).first() as any

      // 2) keep row 존재 확인 (안전성)
      const keepRow = await db.prepare(
        'SELECT id, referrer_id, referee_id, level, reward_amount, reward_date FROM referral_rewards WHERE id = ?'
      ).bind(t.keep_id).first() as any

      // 3) 연관 transactions 조회 (type='referral_reward', ref_id=dup_id)
      const txRows = await db.prepare(
        "SELECT id, user_id, type, amount, ref_id FROM transactions WHERE type = 'referral_reward' AND ref_id = ?"
      ).bind(t.dup_id).all()

      const txList = (txRows.results || []) as any[]

      plan.push({
        dup_id: t.dup_id,
        keep_id: t.keep_id,
        dup_exists: !!dupRow,
        keep_exists: !!keepRow,
        dup_matches_target: dupRow ? (
          dupRow.referrer_id === t.referrer_id &&
          dupRow.referee_id === t.referee_id &&
          dupRow.level === t.level &&
          Number(dupRow.reward_amount) === t.amount &&
          dupRow.reward_date === t.reward_date
        ) : false,
        keep_matches_target: keepRow ? (
          keepRow.referrer_id === t.referrer_id &&
          keepRow.referee_id === t.referee_id &&
          keepRow.level === t.level &&
          keepRow.reward_date === t.reward_date
        ) : false,
        related_tx_count: txList.length,
        related_tx_ids: txList.map(x => x.id),
        will_delete_rr: !!dupRow,
        will_delete_tx_count: txList.length,
        will_subtract_qkey_from_user: t.referrer_id,
        will_subtract_amount: t.amount
      })

      if (dupRow) {
        balanceDeltas[String(t.referrer_id)] = (balanceDeltas[String(t.referrer_id)] || 0) - t.amount
      }
    }

    // Safety: 모든 dup이 존재하고 정확히 일치해야만 실행
    const allSafe = plan.every(p => p.dup_exists && p.keep_exists && p.dup_matches_target && p.keep_matches_target)

    if (dryRun) {
      return c.json({
        success: true,
        mode: 'DRY_RUN',
        message: '실제 실행을 원하시면 confirm=GO 파라미터를 추가하세요',
        all_safe_to_execute: allSafe,
        plan,
        balance_deltas: balanceDeltas
      })
    }

    if (!allSafe) {
      return c.json({
        success: false,
        error: 'SAFETY_CHECK_FAILED: dup or keep row missing, or values mismatched',
        plan
      }, 400)
    }

    // ===== EXECUTE =====
    const executed: any[] = []
    const balanceActual: Record<string, number> = {}

    for (const t of TARGET_DUPS) {
      // a) transactions 삭제
      const txDel = await db.prepare(
        "DELETE FROM transactions WHERE type = 'referral_reward' AND ref_id = ?"
      ).bind(t.dup_id).run()

      // b) referral_rewards dup 삭제
      const rrDel = await db.prepare(
        'DELETE FROM referral_rewards WHERE id = ?'
      ).bind(t.dup_id).run()

      // c) qkey_balance 차감 (referrer)
      const balBefore = await db.prepare(
        'SELECT qkey_balance FROM users WHERE id = ?'
      ).bind(t.referrer_id).first() as any

      await db.prepare(
        'UPDATE users SET qkey_balance = qkey_balance - ? WHERE id = ?'
      ).bind(t.amount, t.referrer_id).run()

      const balAfter = await db.prepare(
        'SELECT qkey_balance FROM users WHERE id = ?'
      ).bind(t.referrer_id).first() as any

      executed.push({
        dup_id: t.dup_id,
        rr_deleted: rrDel.meta?.changes ?? 0,
        tx_deleted: txDel.meta?.changes ?? 0,
        user_id: t.referrer_id,
        qkey_before: balBefore?.qkey_balance,
        qkey_after: balAfter?.qkey_balance,
        qkey_delta: (balAfter?.qkey_balance ?? 0) - (balBefore?.qkey_balance ?? 0)
      })

      balanceActual[String(t.referrer_id)] = (balanceActual[String(t.referrer_id)] || 0) + ((balAfter?.qkey_balance ?? 0) - (balBefore?.qkey_balance ?? 0))
    }

    return c.json({
      success: true,
      mode: 'EXECUTED',
      executed,
      balance_actual_deltas: balanceActual
    })
  } catch (error) {
    console.error('cleanup-may15-residual-dups error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ 5/14 vs 5/15 계정별 1:1 검증 (사장님 2026-05-15 결재) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   사장님 지시: "확실하고 논리적으로 계산이 맞아야해"
//
//   처리: 5/14 paid_date 와 5/15 paid_date 의 계정별 (own / L1 / L2 / total) 을 비교하여
//         완전 일치하지 않는 계정을 모두 보고
//
//   경로: GET /api/diag/verify-may15-equals-may14?key=ADMIN_PW
app.get('/api/diag/verify-may15-equals-may14', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB

    async function getDayData(paidDate: string) {
      const drRows = await db.prepare(`
        SELECT user_id, SUM(usdt_amount) as own_qkey, COUNT(*) as own_count
        FROM daily_rewards WHERE paid_date = ?
        GROUP BY user_id
      `).bind(paidDate).all() as any
      const l1Rows = await db.prepare(`
        SELECT referrer_id as user_id, SUM(reward_amount) as l1_qkey, COUNT(*) as l1_count
        FROM referral_rewards WHERE paid_date = ? AND level = 1
        GROUP BY referrer_id
      `).bind(paidDate).all() as any
      const l2Rows = await db.prepare(`
        SELECT referrer_id as user_id, SUM(reward_amount) as l2_qkey, COUNT(*) as l2_count
        FROM referral_rewards WHERE paid_date = ? AND level = 2
        GROUP BY referrer_id
      `).bind(paidDate).all() as any
      const map: Record<number, any> = {}
      for (const r of (drRows?.results || [])) {
        const uid = Number(r.user_id)
        if (!map[uid]) map[uid] = { user_id: uid, own: 0, l1: 0, l2: 0, own_count: 0, l1_count: 0, l2_count: 0 }
        map[uid].own = Number(r.own_qkey || 0); map[uid].own_count = Number(r.own_count || 0)
      }
      for (const r of (l1Rows?.results || [])) {
        const uid = Number(r.user_id)
        if (!map[uid]) map[uid] = { user_id: uid, own: 0, l1: 0, l2: 0, own_count: 0, l1_count: 0, l2_count: 0 }
        map[uid].l1 = Number(r.l1_qkey || 0); map[uid].l1_count = Number(r.l1_count || 0)
      }
      for (const r of (l2Rows?.results || [])) {
        const uid = Number(r.user_id)
        if (!map[uid]) map[uid] = { user_id: uid, own: 0, l1: 0, l2: 0, own_count: 0, l1_count: 0, l2_count: 0 }
        map[uid].l2 = Number(r.l2_qkey || 0); map[uid].l2_count = Number(r.l2_count || 0)
      }
      let totalOwn = 0, totalL1 = 0, totalL2 = 0
      for (const v of Object.values(map)) {
        totalOwn += v.own; totalL1 += v.l1; totalL2 += v.l2
      }
      return { map, totalOwn, totalL1, totalL2, total: totalOwn + totalL1 + totalL2, count: Object.keys(map).length }
    }

    const d14 = await getDayData('2026-05-14')
    const d15 = await getDayData('2026-05-15')

    const allUids = new Set<number>([...Object.keys(d14.map).map(Number), ...Object.keys(d15.map).map(Number)])
    const mismatches: any[] = []
    let matchCount = 0

    for (const uid of allUids) {
      const a = d14.map[uid] || { own: 0, l1: 0, l2: 0, own_count: 0, l1_count: 0, l2_count: 0 }
      const b = d15.map[uid] || { own: 0, l1: 0, l2: 0, own_count: 0, l1_count: 0, l2_count: 0 }
      const ownDiff = b.own - a.own
      const l1Diff = b.l1 - a.l1
      const l2Diff = b.l2 - a.l2
      if (ownDiff === 0 && l1Diff === 0 && l2Diff === 0) {
        matchCount++
      } else {
        const u = await db.prepare(`SELECT name, email FROM users WHERE id = ?`).bind(uid).first() as any
        mismatches.push({
          user_id: uid,
          name: u?.name || null,
          email: u?.email || null,
          may14: { own: a.own, l1: a.l1, l2: a.l2, total: a.own + a.l1 + a.l2 },
          may15: { own: b.own, l1: b.l1, l2: b.l2, total: b.own + b.l1 + b.l2 },
          diff: { own: ownDiff, l1: l1Diff, l2: l2Diff, total: ownDiff + l1Diff + l2Diff }
        })
      }
    }

    return c.json({
      success: true,
      summary_may14: { count: d14.count, own: d14.totalOwn, l1: d14.totalL1, l2: d14.totalL2, total: d14.total },
      summary_may15: { count: d15.count, own: d15.totalOwn, l1: d15.totalL1, l2: d15.totalL2, total: d15.total },
      totals_diff: {
        own: d15.totalOwn - d14.totalOwn,
        l1: d15.totalL1 - d14.totalL1,
        l2: d15.totalL2 - d14.totalL2,
        total: d15.total - d14.total
      },
      affected_users: allUids.size,
      match_count: matchCount,
      mismatch_count: mismatches.length,
      verdict: mismatches.length === 0 ? 'PERFECT_MATCH' : 'MISMATCH_EXISTS',
      mismatches
    })
  } catch (error) {
    console.error('verify-may15-equals-may14 error:', error)
    return c.json({ error: String(error) }, 500)
  }
})


// ★★★ 솔밧(u#44) L2 매칭 미러링 누락 2건 정밀 백필 (Phase 1, 2026-05-12 사장님 C안 결재) ★★★
//   원장 referral_rewards 25건 / 9,150 QKEY  vs  transactions 미러링 23건 / 7,500 QKEY
//   누락 2건: rr#347 (150 QKEY, 2026-05-06 referee u#49) + rr#524 (1,500 QKEY, 2026-05-06 referee u#76)
//   ★ 잔액(users.qkey_balance) 절대 안 건드림 — 이미 정확히 반영됨 ★
//   ★ description 영구룰 100% 준수: '추천 보너스 (Level 2)' 만 사용 ★
//   경로: POST /api/diag/backfill-l2-mirror-missing?key=ADMIN_PW&dry_run=1|0
app.post('/api/diag/backfill-l2-mirror-missing', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const dep = assertNotDeprecated(c, 'backfill-l2-mirror-missing', 'L2 미러 누락 백필 완료. safeInsertTransaction 가드 미적용 → 재호출 시 이중지급 위험')
    if (dep) return dep

    const dryRun = c.req.query('dry_run') === '1'
    const db = c.env.DB

    // 정밀 진단으로 확정된 누락 2건 — referral_rewards.id 하드코드
    const TARGET_RR_IDS = [347, 524]
    const results: any[] = []
    let inserted = 0
    let alreadyExists = 0
    let notFound = 0

    for (const rrId of TARGET_RR_IDS) {
      // 1. 원장 referral_rewards 행 조회
      const rr = await db.prepare(`
        SELECT id, referrer_id, referee_id, level, reward_amount, reward_date, paid_date
        FROM referral_rewards
        WHERE id = ?
      `).bind(rrId).first() as any

      if (!rr) {
        results.push({ rr_id: rrId, status: 'not_found_in_referral_rewards' })
        notFound++
        continue
      }

      // 2. EXISTS 가드 — 이미 미러링 존재하면 skip
      const exists = await db.prepare(`
        SELECT id FROM transactions
        WHERE type = 'referral_reward' AND ref_id = ?
        LIMIT 1
      `).bind(rrId).first()

      if (exists) {
        results.push({
          rr_id: rrId,
          referrer_id: rr.referrer_id,
          referee_id: rr.referee_id,
          level: rr.level,
          reward_amount: rr.reward_amount,
          status: 'already_exists',
          existing_tx_id: (exists as any).id,
        })
        alreadyExists++
        continue
      }

      // 3. dry_run 모드 — INSERT 미수행
      if (dryRun) {
        results.push({
          rr_id: rrId,
          referrer_id: rr.referrer_id,
          referee_id: rr.referee_id,
          level: rr.level,
          reward_amount: rr.reward_amount,
          paid_date: rr.paid_date,
          status: 'would_insert',
          planned_description: rr.level === 1 ? '추천 보너스 (Level 1)' : '추천 보너스 (Level 2)',
        })
        continue
      }

      // 4. 실 INSERT — description 영구룰 안전 한국어만, 잔액 미수정
      const desc = rr.level === 1 ? '추천 보너스 (Level 1)' : '추천 보너스 (Level 2)'
      const paidDateIso = (rr.paid_date || rr.reward_date) + ' 00:00:00'

      const ins = await db.prepare(`
        INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id, created_at)
        VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?, ?)
      `).bind(rr.referrer_id, rr.reward_amount, desc, rrId, paidDateIso).run()

      const newTxId = (ins as any)?.meta?.last_row_id ?? null
      results.push({
        rr_id: rrId,
        referrer_id: rr.referrer_id,
        referee_id: rr.referee_id,
        level: rr.level,
        reward_amount: rr.reward_amount,
        paid_date: rr.paid_date,
        status: 'inserted',
        new_tx_id: newTxId,
      })
      inserted++
    }

    return c.json({
      success: true,
      mode: dryRun ? 'dry_run' : 'real',
      target_count: TARGET_RR_IDS.length,
      inserted_count: inserted,
      already_exists_count: alreadyExists,
      not_found_count: notFound,
      results,
      note: '잔액(users.qkey_balance) 절대 안 건드림 — referral_rewards 원장에 의해 이미 정확히 반영됨',
    })
  } catch (error) {
    console.error('backfill-l2-mirror-missing error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★ 전 회원 referral_rewards vs transactions 미러링 차이 일괄 백필 (Phase 3, C안) ★★★
//   level IN (1,2) 만 대상 (L0 직판은 type='direct_referral' 로 별도 미러링)
//   EXISTS 가드 + description 영구룰 100% 준수 + 잔액 절대 미수정
//   경로: POST /api/diag/backfill-referral-mirror-all?key=ADMIN_PW&dry_run=1|0&level=1|2|all&limit=N
app.post('/api/diag/backfill-referral-mirror-all', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const dep = assertNotDeprecated(c, 'backfill-referral-mirror-all', '전체 referral 미러 백필 완료. safeInsertTransaction 가드 미적용 → 재호출 시 이중지급 위험')
    if (dep) return dep

    const dryRun = c.req.query('dry_run') === '1'
    const levelParam = c.req.query('level') || 'all'
    const limit = Math.min(Number(c.req.query('limit') || 500), 1000)
    const db = c.env.DB

    // 대상 level 절
    let levelClause = ''
    if (levelParam === '1') levelClause = 'AND rr.level = 1'
    else if (levelParam === '2') levelClause = 'AND rr.level = 2'
    else levelClause = 'AND rr.level IN (1, 2)'

    // 1. 원장 referral_rewards 중 transactions.ref_id 와 매핑 안된 행만 추출
    const missing = await db.prepare(`
      SELECT rr.id, rr.referrer_id, rr.referee_id, rr.level, rr.reward_amount, rr.reward_date, rr.paid_date
      FROM referral_rewards rr
      LEFT JOIN transactions tx
        ON tx.type = 'referral_reward' AND tx.ref_id = rr.id
      WHERE tx.id IS NULL
        ${levelClause}
        AND COALESCE(rr.reward_amount, 0) > 0
      ORDER BY rr.id ASC
      LIMIT ?
    `).bind(limit).all() as any

    const missingRows = (missing.results || []) as any[]
    const results: any[] = []
    let inserted = 0

    for (const rr of missingRows) {
      const desc = rr.level === 1 ? '추천 보너스 (Level 1)' : '추천 보너스 (Level 2)'
      const paidDateIso = (rr.paid_date || rr.reward_date) + ' 00:00:00'

      if (dryRun) {
        results.push({
          rr_id: rr.id,
          referrer_id: rr.referrer_id,
          referee_id: rr.referee_id,
          level: rr.level,
          reward_amount: rr.reward_amount,
          paid_date: rr.paid_date,
          status: 'would_insert',
          planned_description: desc,
        })
        continue
      }

      // 실 INSERT
      const ins = await db.prepare(`
        INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id, created_at)
        VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?, ?)
      `).bind(rr.referrer_id, rr.reward_amount, desc, rr.id, paidDateIso).run()

      const newTxId = (ins as any)?.meta?.last_row_id ?? null
      results.push({
        rr_id: rr.id,
        referrer_id: rr.referrer_id,
        referee_id: rr.referee_id,
        level: rr.level,
        reward_amount: rr.reward_amount,
        paid_date: rr.paid_date,
        status: 'inserted',
        new_tx_id: newTxId,
      })
      inserted++
    }

    // 영향 받은 사용자 통계 (referrer_id 별 누락 건수/금액)
    const byReferrer: Record<string, { count: number, sum: number }> = {}
    for (const r of missingRows) {
      const k = String(r.referrer_id)
      if (!byReferrer[k]) byReferrer[k] = { count: 0, sum: 0 }
      byReferrer[k].count += 1
      byReferrer[k].sum += Number(r.reward_amount || 0)
    }

    return c.json({
      success: true,
      mode: dryRun ? 'dry_run' : 'real',
      level_filter: levelParam,
      total_missing_in_scan: missingRows.length,
      limit_applied: limit,
      inserted_count: inserted,
      by_referrer: byReferrer,
      results,
      note: '잔액 절대 미수정 — referral_rewards 원장이 이미 잔액 반영. transactions 미러링만 추가.',
    })
  } catch (error) {
    console.error('backfill-referral-mirror-all error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★ 솔밧 5/12 L2 tx created_at 정정 — A안 결재 (2026-05-12) ★★★
//   경로: POST /api/diag/fix-solbat-l2-may12-createdat?key=ADMIN_PW&dry_run=1|0
//   목적: 솔밧(u#44) L2 4건(ref_id 810,814,836,838)의 transactions.created_at 을
//         원장 reward_date(2026-05-12) 기준으로 정정하여 화면 일자별 집계 정상화
//   불변: amount/description/ref_id/잔액 모두 변경 없음 — created_at만 UPDATE
//   기대: 5/12 L2 화면 합계 150 → 1,950 (원장과 일치)
app.post('/api/diag/fix-solbat-l2-may12-createdat', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const dryRun = c.req.query('dry_run') !== '0'

    const TARGET_REF_IDS = [810, 814, 836, 838]
    const TARGET_USER_ID = 44
    const NEW_CREATED_AT = '2026-05-12'

    const db = c.env.DB
    const before: any[] = []
    const after: any[] = []

    // 사전 raw 조회
    for (const rid of TARGET_REF_IDS) {
      const row = await db.prepare(`
        SELECT id, user_id, type, coin_type, amount, description, ref_id, created_at
        FROM transactions
        WHERE type='referral_reward' AND ref_id = ? AND user_id = ?
      `).bind(rid, TARGET_USER_ID).first()
      if (row) before.push(row)
    }

    if (dryRun) {
      return c.json({
        success: true,
        mode: 'dry_run',
        target_ref_ids: TARGET_REF_IDS,
        target_user_id: TARGET_USER_ID,
        new_created_at_date: NEW_CREATED_AT,
        before,
        would_update_count: before.length,
        note: '잔액 절대 미수정 — created_at 컬럼만 UPDATE',
      })
    }

    // 실 적용: created_at 만 UPDATE (시각은 정오 KST = 03:00 UTC 로 고정)
    let updated = 0
    for (const rid of TARGET_REF_IDS) {
      const res = await db.prepare(`
        UPDATE transactions
        SET created_at = ?
        WHERE type='referral_reward' AND ref_id = ? AND user_id = ?
      `).bind(`${NEW_CREATED_AT} 03:00:00`, rid, TARGET_USER_ID).run()
      if (res.meta?.changes && res.meta.changes > 0) updated += res.meta.changes
    }

    // 사후 raw 조회
    for (const rid of TARGET_REF_IDS) {
      const row = await db.prepare(`
        SELECT id, user_id, type, coin_type, amount, description, ref_id, created_at
        FROM transactions
        WHERE type='referral_reward' AND ref_id = ? AND user_id = ?
      `).bind(rid, TARGET_USER_ID).first()
      if (row) after.push(row)
    }

    return c.json({
      success: true,
      mode: 'real',
      target_ref_ids: TARGET_REF_IDS,
      target_user_id: TARGET_USER_ID,
      new_created_at: `${NEW_CREATED_AT} 03:00:00`,
      updated_count: updated,
      before,
      after,
      note: '잔액 미수정 — created_at만 변경. amount/description/ref_id 불변.',
    })
  } catch (error) {
    console.error('fix-solbat-l2-may12-createdat error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★ 전체 스왑 내역 dump — 사실 확인용 영구 진단 (read-only) ★★★
//   경로: /api/diag/all-swaps?key=ADMIN_PW&user_id=N(옵션)&limit=N(옵션)
//   목적: 어드민 "스왑 내역 관리" 화면에 노출되는 28건 raw dump
//   인증: ?key=ADMIN_PW (admin Bearer 토큰 없이도 사장님 검증 가능)
app.get('/api/diag/all-swaps', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const filterUser = c.req.query('user_id') || ''
    const limit = parseInt(c.req.query('limit') || '500', 10)

    const db = c.env.DB
    const baseSql = `
      SELECT t.id, t.user_id, u.email, u.name, t.type, t.coin_type, t.amount, t.description, t.created_at
      FROM transactions t
      JOIN users u ON t.user_id = u.id
      WHERE t.type IN ('swap_in', 'swap_out')
      ${filterUser ? 'AND t.user_id = ?' : ''}
      ORDER BY t.id ASC
      LIMIT ?
    `
    const stmt = filterUser
      ? db.prepare(baseSql).bind(parseInt(filterUser, 10), limit)
      : db.prepare(baseSql).bind(limit)
    const swaps = await stmt.all()

    // 통계
    const stats = await db.prepare(`
      SELECT
        COUNT(*) as total_count,
        COUNT(DISTINCT user_id) as unique_users,
        SUM(CASE WHEN type = 'swap_out' AND coin_type = 'QKEY' THEN amount ELSE 0 END) as total_qkey_used,
        SUM(CASE WHEN type = 'swap_out' AND coin_type = 'USDT' THEN amount ELSE 0 END) as total_usdt_used,
        SUM(CASE WHEN type = 'swap_in' AND coin_type = 'QTA' THEN amount ELSE 0 END) as total_qta_received,
        SUM(CASE WHEN type = 'swap_in' AND coin_type = 'QX' THEN amount ELSE 0 END) as total_qx_received,
        SUM(CASE WHEN type = 'swap_in' AND coin_type = 'USDT' THEN amount ELSE 0 END) as total_usdt_received,
        SUM(CASE WHEN type = 'swap_in' AND coin_type = 'QKEY' THEN amount ELSE 0 END) as total_qkey_received
      FROM transactions
      WHERE type IN ('swap_in', 'swap_out')
    `).first()

    // user_id 별 카운트
    const perUserSql = `
      SELECT t.user_id, u.name, u.email, COUNT(*) as cnt,
        SUM(CASE WHEN t.type='swap_out' THEN 1 ELSE 0 END) as out_cnt,
        SUM(CASE WHEN t.type='swap_in'  THEN 1 ELSE 0 END) as in_cnt
      FROM transactions t JOIN users u ON t.user_id=u.id
      WHERE t.type IN ('swap_in','swap_out')
      GROUP BY t.user_id, u.name, u.email
      ORDER BY cnt DESC
    `
    const perUser = await db.prepare(perUserSql).all()

    return c.json({
      success: true,
      filter: { user_id: filterUser || null, limit },
      total_rows: (swaps.results || []).length,
      stats,
      per_user: perUser.results,
      swaps: swaps.results,
    })
  } catch (error) {
    console.error('all-swaps error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★ 솔밧 L2 5/11 KST 자 tx 정밀 역추적 — D안 결재 (2026-05-12, read-only) ★★★
//   경로: /api/diag/solbat-l2-trace?key=ADMIN_PW
//   목적: NULL ref 6건 (KST 7시대) vs Phase 3 6건 (KST 9시대) 이중 미러링 1:1 매칭 검증
//   - 솔밧(u#44) L2 referral_reward tx 중 KST date(created_at,'+9 hours')=2026-05-11 행 전체
//   - NULL ref 행: ref_id IS NULL → referee 추정 (amount+created_at 인접 referral_rewards 매칭)
//   - Phase 3 행: ref_id NOT NULL → referral_rewards JOIN 으로 referee/reward_date/paid_date 직접 확인
//   - 잔액(qkey_balance) / DB UPDATE 0건 — 순수 SELECT 만
app.get('/api/diag/solbat-l2-trace', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const SOLBAT_ID = 44
    const KST_DATE = '2026-05-11'

    // 1) 솔밧 L2 tx 전체 (KST 5/11)
    const txAll = await db.prepare(`
      SELECT id, user_id, type, coin_type, amount, description, ref_id, created_at AS created_at_utc,
             datetime(created_at, '+9 hours') AS created_at_kst,
             substr(datetime(created_at, '+9 hours'), 12, 2) AS kst_hour
      FROM transactions
      WHERE user_id = ?
        AND type = 'referral_reward'
        AND description LIKE '%Level 2%'
        AND date(created_at, '+9 hours') = ?
      ORDER BY datetime(created_at, '+9 hours') ASC, id ASC
    `).bind(SOLBAT_ID, KST_DATE).all()

    const txRows = txAll.results || []
    const nullRefRows = txRows.filter((r: any) => r.ref_id === null)
    const phase3Rows = txRows.filter((r: any) => r.ref_id !== null)

    // 2) Phase 3 행의 referee_id / reward_date / paid_date (referral_rewards JOIN)
    const phase3Detailed: any[] = []
    for (const row of phase3Rows) {
      const r: any = row
      const rr = await db.prepare(`
        SELECT id AS ref_id, referrer_id, referee_id, level,
               original_amount, reward_amount,
               reward_date, paid_date,
               datetime(created_at, '+9 hours') AS rr_created_kst
        FROM referral_rewards
        WHERE id = ?
      `).bind(r.ref_id).first()
      const refereeUser: any = rr ? await db.prepare(`SELECT id, name, email FROM users WHERE id = ?`).bind((rr as any).referee_id).first() : null
      phase3Detailed.push({
        tx_id: r.id,
        tx_kst: r.created_at_kst,
        tx_hour: r.kst_hour,
        tx_amount: r.amount,
        ref_id: r.ref_id,
        ledger: rr,
        referee: refereeUser,
      })
    }

    // 3) NULL ref 행의 referee 후보 추정 — 같은 reward_amount + created_at 인접 referral_rewards (referrer_id=44 AND level=2)
    const nullRefDetailed: any[] = []
    for (const row of nullRefRows) {
      const r: any = row
      // 후보 1: 같은 reward_amount AND referrer=44 AND level=2 인 모든 referral_rewards 행
      const candidates = await db.prepare(`
        SELECT id AS ref_id, referee_id, original_amount, reward_amount, reward_date, paid_date,
               datetime(created_at, '+9 hours') AS rr_created_kst,
               ABS(strftime('%s', created_at) - strftime('%s', ?)) AS sec_diff
        FROM referral_rewards
        WHERE referrer_id = ? AND level = 2 AND reward_amount = ?
        ORDER BY sec_diff ASC
        LIMIT 5
      `).bind(r.created_at_utc, SOLBAT_ID, r.amount).all()

      // 후보 referee names
      const candRows = candidates.results || []
      const enriched = [] as any[]
      for (const c2 of candRows) {
        const cc: any = c2
        const u: any = await db.prepare(`SELECT id, name, email FROM users WHERE id = ?`).bind(cc.referee_id).first()
        enriched.push({ ...cc, referee: u })
      }

      nullRefDetailed.push({
        tx_id: r.id,
        tx_kst: r.created_at_kst,
        tx_hour: r.kst_hour,
        tx_amount: r.amount,
        ref_id: null,
        referee_candidates: enriched,
      })
    }

    // 4) 1:1 매칭 시도 — NULL ref 행 각각에 대해 (amount, referee_id) 가 Phase 3 행과 일치하는지
    const matches: any[] = []
    for (const nr of nullRefDetailed) {
      const matched: any[] = []
      for (const cand of nr.referee_candidates) {
        // Phase 3 detailed 에 referee_id 동일 + amount 동일 행 찾기
        const hit = phase3Detailed.find(p =>
          p.ledger && p.ledger.referee_id === cand.referee_id && Number(p.tx_amount) === Number(nr.tx_amount)
        )
        if (hit) {
          matched.push({
            null_ref_tx_id: nr.tx_id,
            null_ref_kst: nr.tx_kst,
            phase3_tx_id: hit.tx_id,
            phase3_kst: hit.tx_kst,
            phase3_ref_id: hit.ref_id,
            referee_id: cand.referee_id,
            referee_name: cand.referee && cand.referee.name,
            amount: nr.tx_amount,
            ledger_reward_date: hit.ledger.reward_date,
            ledger_paid_date: hit.ledger.paid_date,
          })
        }
      }
      matches.push({ null_ref_tx_id: nr.tx_id, amount: nr.tx_amount, matched })
    }

    // 5) 합계 검증
    const sumByHour: Record<string, number> = {}
    for (const r of txRows) {
      const rr: any = r
      sumByHour[rr.kst_hour] = (sumByHour[rr.kst_hour] || 0) + Number(rr.amount)
    }

    return c.json({
      success: true,
      target: { user_id: SOLBAT_ID, kst_date: KST_DATE },
      counts: {
        tx_total: txRows.length,
        null_ref: nullRefRows.length,
        phase3: phase3Rows.length,
      },
      sum_by_kst_hour: sumByHour,
      tx_rows: txRows,
      null_ref_detailed: nullRefDetailed,
      phase3_detailed: phase3Detailed,
      one_to_one_matches: matches,
      note: 'read-only — DB/잔액 무변경 보장',
    })
  } catch (error) {
    console.error('solbat-l2-trace error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★ 솔밧 L2 5/04일 진입자 매핑 검증 — D안-2 결재 (2026-05-12, read-only) ★★★
//   경로: /api/diag/solbat-l2-may04-verify?key=ADMIN_PW
//   목적: 사장님 엑셀 1,950 (5/04일 2대 정상 발생액) 진실 기준 검증
//   - 솔밧(u#44) 의 1대(직추천) 회원 명단 → 그 회원들의 1대(=솔밧의 2대) 회원 명단
//   - 각 2대 회원의 5/04일 신규 스테이킹 → 정상 L2 발생액 계산 (10% of L1 보너스)
//   - tx KST 5/11 07시대 7건 (cron) vs 09시대 6건 (Phase 3) 양쪽 매칭 비교
//   - referee 별 1:1 분포로 어느 쪽이 진실 데이터인지 판정
//   - 잔액(qkey_balance) / DB UPDATE 0건 — 순수 SELECT 만
app.get('/api/diag/solbat-l2-may04-verify', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const SOLBAT_ID = 44
    const ENTRY_DATE = '2026-05-04'  // 사장님 엑셀 기준 진입일

    // 1) 솔밧 직추천(L1) 회원 명단
    const l1Users = await db.prepare(`
      SELECT id, name, email, referrer_id, created_at,
             datetime(created_at, '+9 hours') AS created_kst
      FROM users
      WHERE referrer_id = ?
      ORDER BY id ASC
    `).bind(SOLBAT_ID).all()

    // 2) 솔밧 2대(=L1 회원들의 직추천) 명단
    const l2Users = await db.prepare(`
      SELECT u.id, u.name, u.email, u.referrer_id AS l1_id,
             datetime(u.created_at, '+9 hours') AS created_kst,
             date(u.created_at, '+9 hours') AS created_kst_date,
             l1.name AS l1_name
      FROM users u
      JOIN users l1 ON u.referrer_id = l1.id
      WHERE l1.referrer_id = ?
      ORDER BY u.created_at ASC, u.id ASC
    `).bind(SOLBAT_ID).all()

    // 3) 2대 회원들 중 5/04 KST 진입자 + 각자 5/04 스테이킹
    const may04L2: any[] = []
    for (const u of (l2Users.results || [])) {
      const uu: any = u
      if (uu.created_kst_date !== ENTRY_DATE) continue
      const stakes = await db.prepare(`
        SELECT id, amount, status,
               datetime(created_at, '+9 hours') AS staked_kst,
               date(created_at, '+9 hours') AS staked_kst_date
        FROM staking
        WHERE user_id = ? AND date(created_at, '+9 hours') = ?
        ORDER BY created_at ASC
      `).bind(uu.id, ENTRY_DATE).all()
      may04L2.push({ ...uu, stakes: stakes.results || [] })
    }

    // 4) 5/04 진입 2대 회원에 대한 referral_rewards 원장 행 (솔밧이 받은 L2 보너스)
    const rrLedger = await db.prepare(`
      SELECT rr.id AS ref_id, rr.referee_id, rr.original_amount, rr.reward_amount,
             rr.reward_date, rr.paid_date,
             datetime(rr.created_at, '+9 hours') AS rr_created_kst,
             u.name AS referee_name, u.email AS referee_email,
             date(u.created_at, '+9 hours') AS referee_entry_kst_date
      FROM referral_rewards rr
      JOIN users u ON rr.referee_id = u.id
      WHERE rr.referrer_id = ? AND rr.level = 2
        AND date(u.created_at, '+9 hours') = ?
      ORDER BY rr.id ASC
    `).bind(SOLBAT_ID, ENTRY_DATE).all()

    // 5) tx KST 5/11 자 솔밧 L2 행 전체 (07시대 vs 09시대)
    const txMay11 = await db.prepare(`
      SELECT id, amount, ref_id, created_at AS created_at_utc,
             datetime(created_at, '+9 hours') AS created_at_kst,
             substr(datetime(created_at, '+9 hours'), 12, 2) AS kst_hour
      FROM transactions
      WHERE user_id = ? AND type = 'referral_reward'
        AND description LIKE '%Level 2%'
        AND date(created_at, '+9 hours') = '2026-05-11'
      ORDER BY datetime(created_at, '+9 hours') ASC, id ASC
    `).bind(SOLBAT_ID).all()
    const txRows = txMay11.results || []
    const tx07 = txRows.filter((r: any) => r.kst_hour === '07')
    const tx09 = txRows.filter((r: any) => r.kst_hour === '09')

    // 6) 정상 발생액 계산 (5/04 진입 2대 회원 stakes 기준, L2 = original_amount * 7.5%)
    //    Q: 75 = $1000 * 7.5% (1대 $5 일일 + 2대 = 본인 진입 보너스), 1500 = $10000 * 15%
    //    사장님 엑셀 패턴: 1대 진입 보너스 → 솔밧 L2 = original_amount * 0.075
    let expectedTotal = 0
    const expectedRows: any[] = []
    for (const u of may04L2) {
      for (const s of u.stakes) {
        const amt = Number(s.amount)
        // 사장님 엑셀 룰: $1000→75, $2000→150, $10000→1500 (즉 7.5%)
        const expected = Math.round(amt * 0.075)
        expectedTotal += expected
        expectedRows.push({
          referee_id: u.id, referee_name: u.name, l1_id: u.l1_id, l1_name: u.l1_name,
          staking_id: s.id, staking_amount: amt,
          expected_l2_qkey: expected,
        })
      }
    }

    // 7) referee_id 별 분포 비교 (07시대 cron tx vs 09시대 Phase3 tx vs 원장 vs 기대값)
    //    07시대 NULL ref 는 referee 모름 → amount 분포만 비교
    const sum07 = tx07.reduce((a: number, r: any) => a + Number(r.amount), 0)
    const sum09 = tx09.reduce((a: number, r: any) => a + Number(r.amount), 0)
    const sumLedger = (rrLedger.results || []).reduce((a: number, r: any) => a + Number(r.reward_amount), 0)

    // 07시대 ref_id 있는 행 → referee_id 매핑
    const tx07WithRef: any[] = []
    for (const r of tx07) {
      const rr: any = r
      if (rr.ref_id) {
        const led: any = await db.prepare(`SELECT referee_id FROM referral_rewards WHERE id = ?`).bind(rr.ref_id).first()
        tx07WithRef.push({ tx_id: rr.id, ref_id: rr.ref_id, amount: rr.amount, referee_id: led && led.referee_id })
      } else {
        tx07WithRef.push({ tx_id: rr.id, ref_id: null, amount: rr.amount, referee_id: null })
      }
    }

    // 09시대 ref_id → referee_id 매핑
    const tx09WithRef: any[] = []
    for (const r of tx09) {
      const rr: any = r
      const led: any = await db.prepare(`SELECT referee_id FROM referral_rewards WHERE id = ?`).bind(rr.ref_id).first()
      tx09WithRef.push({ tx_id: rr.id, ref_id: rr.ref_id, amount: rr.amount, referee_id: led && led.referee_id })
    }

    // 8) 판정 요약
    const verdict: any = {
      excel_truth: 1950,
      tx_07_sum: sum07,
      tx_09_sum: sum09,
      ledger_sum_may04_entrants: sumLedger,
      expected_sum_from_stakes: expectedTotal,
      tx_07_matches_excel: sum07 === 1950,
      tx_09_matches_excel: sum09 === 1950,
      conclusion_hint: sum07 === 1950 ? '07시대 cron 7건이 정상, 09시대 6건이 사후 중복 의심' :
                       sum09 === 1950 ? '09시대 Phase 3 6건이 정상, 07시대 7건이 사후 중복 의심' :
                       '양쪽 모두 엑셀 1,950 과 불일치 — 추가 분석 필요',
    }

    return c.json({
      success: true,
      target: { user_id: SOLBAT_ID, entry_date: ENTRY_DATE },
      l1_user_count: (l1Users.results || []).length,
      l2_user_total: (l2Users.results || []).length,
      may04_l2_entrants: may04L2,
      expected_l2_rewards: { rows: expectedRows, total: expectedTotal },
      ledger_may04_entrants: rrLedger.results,
      tx_07_kst_cron: tx07WithRef,
      tx_09_kst_phase3: tx09WithRef,
      verdict,
      note: 'read-only — DB/잔액 무변경 보장. 사장님 엑셀 1,950 이 진실 기준.',
    })
  } catch (error) {
    console.error('solbat-l2-may04-verify error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★ 솔밧 L2 5/11 Phase 3 중복 6건 삭제 dry_run preview — D안-2 결재 (2026-05-12) ★★★
//   경로: GET /api/diag/dryrun-delete-solbat-phase3?key=ADMIN_PW
//   목적: 09시대 Phase 3 백필 6건 (사장님 엑셀 1,950 검증 후 중복 확정분) 삭제 preview
//   - 삭제 대상 6건 tx 상세 + 짝지어진 referral_rewards 원장 행 preview
//   - 솔밧 qkey_balance 현재값 + 정정 후 예상값 preview
//   - 실제 DELETE / UPDATE 0건 — 순수 read-only SELECT 만 (사장님 GO 후 별도 endpoint 에서 실제 실행)
app.get('/api/diag/dryrun-delete-solbat-phase3', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const SOLBAT_ID = 44

    // 삭제 대상 6건 (09시 KST Phase 3 백필 행)
    const TARGET_TX_IDS = [2667, 2676, 2703, 2707, 2709, 2750]
    const TARGET_REF_IDS = [688, 698, 725, 729, 731, 773]

    // 1) 삭제 대상 tx 상세
    const placeholders = TARGET_TX_IDS.map(() => '?').join(',')
    const txRows = await db.prepare(`
      SELECT id, user_id, type, coin_type, amount, description, ref_id,
             created_at AS created_at_utc,
             datetime(created_at, '+9 hours') AS created_at_kst
      FROM transactions
      WHERE id IN (${placeholders})
      ORDER BY id ASC
    `).bind(...TARGET_TX_IDS).all()

    // 2) 짝지어진 referral_rewards 원장 행 상세 (참고용, 삭제 대상 아님)
    const rrRows = await db.prepare(`
      SELECT rr.id AS ref_id, rr.referrer_id, rr.referee_id, rr.level,
             rr.original_amount, rr.reward_amount, rr.reward_date, rr.paid_date,
             datetime(rr.created_at, '+9 hours') AS rr_created_kst,
             u.name AS referee_name, u.email AS referee_email
      FROM referral_rewards rr
      JOIN users u ON rr.referee_id = u.id
      WHERE rr.id IN (${TARGET_REF_IDS.map(() => '?').join(',')})
      ORDER BY rr.id ASC
    `).bind(...TARGET_REF_IDS).all()

    // 3) 솔밧 현재 잔액
    const solbat: any = await db.prepare(`
      SELECT id, name, email, qkey_balance, qta_balance, qx_balance, usdt_balance
      FROM users WHERE id = ?
    `).bind(SOLBAT_ID).first()

    // 4) 검증: 실제로 존재하는 tx 만 (이미 누군가 지웠을 가능성 사전 확인)
    const existing = (txRows.results || []).map((r: any) => r.id)
    const missing = TARGET_TX_IDS.filter(id => !existing.includes(id))

    // 5) 삭제 시 잔액 정정 금액 계산
    const totalToRevert = (txRows.results || []).reduce((a: number, r: any) => a + Number(r.amount), 0)
    const newQkeyBalance = Number(solbat.qkey_balance) - totalToRevert

    // 6) 안전 검증
    const safetyChecks = {
      target_tx_count_expected: 6,
      target_tx_count_found: (txRows.results || []).length,
      missing_tx_ids: missing,
      all_targets_are_solbat: (txRows.results || []).every((r: any) => r.user_id === SOLBAT_ID),
      all_targets_are_referral_reward: (txRows.results || []).every((r: any) => r.type === 'referral_reward'),
      all_targets_are_level2: (txRows.results || []).every((r: any) => (r.description || '').indexOf('Level 2') !== -1),
      total_revert_amount: totalToRevert,
      expected_revert_amount: 1875,
      revert_amount_matches: totalToRevert === 1875,
    }

    return c.json({
      success: true,
      target: { user_id: SOLBAT_ID, name: solbat.name, email: solbat.email },
      target_tx_ids: TARGET_TX_IDS,
      target_ref_ids: TARGET_REF_IDS,
      delete_preview: {
        tx_rows_to_delete: txRows.results,
        ref_id_count: TARGET_REF_IDS.length,
        total_qkey_amount_to_revert: totalToRevert,
      },
      ledger_for_reference: {
        note: 'referral_rewards 원장은 삭제하지 않음 (참고용 — 사장님 추가 결재 시에만)',
        rows: rrRows.results,
      },
      balance_preview: {
        current_qkey_balance: Number(solbat.qkey_balance),
        revert_amount: totalToRevert,
        new_qkey_balance_after_fix: newQkeyBalance,
      },
      safety_checks: safetyChecks,
      summary: {
        will_delete: 'transactions 6행 (Phase 3 중복 미러)',
        will_update: `users.qkey_balance: ${solbat.qkey_balance} → ${newQkeyBalance} (-${totalToRevert})`,
        will_keep: 'referral_rewards 원장 6행 (참고용, 추가 결재 시에만 처리)',
      },
      next_step: {
        message: '사장님 GO 결재 받은 후 별도 endpoint POST /api/diag/exec-delete-solbat-phase3 작성 + 실행',
        boss_decision_required: true,
      },
      note: 'read-only — DB UPDATE / DELETE 0건 보장. 본 endpoint 는 오직 preview 만.',
    })
  } catch (error) {
    console.error('dryrun-delete-solbat-phase3 error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★ 솔밧 L2 5/11 Phase 3 중복 6건 실제 삭제 + 잔액 정정 — D안-2 사장님 GO 결재 (2026-05-12) ★★★
//   경로: POST /api/diag/exec-delete-solbat-phase3?key=ADMIN_PW&confirm=GO
//   목적: dry_run preview 검증 완료된 6건 tx 삭제 + 솔밧 qkey_balance -1875 정정
//   - 삭제 대상: tx#2667,2676,2703,2707,2709,2750 (Phase 3 중복 미러)
//   - 잔액 정정: 122,850 → 120,975 (-1,875)
//   - 원장(referral_rewards) 6행은 보존 (정상 데이터)
//   - safety: tx 6건 정확 일치 + 합 1875 정확 일치 사전 검증, 불일치 시 abort
//   - confirm=GO 파라미터 필수 (실수 방지)
app.post('/api/diag/exec-delete-solbat-phase3', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const confirm = c.req.query('confirm') || ''
    if (confirm !== 'GO') return c.json({ error: 'confirm=GO 필요 (사장님 명시 GO 확인용)' }, 400)
    const db = c.env.DB
    const SOLBAT_ID = 44
    const TARGET_TX_IDS = [2667, 2676, 2703, 2707, 2709, 2750]
    const EXPECTED_REVERT = 1875

    // 1) 사전 검증 — dry_run 과 동일 safety 검사
    const placeholders = TARGET_TX_IDS.map(() => '?').join(',')
    const txRows = await db.prepare(`
      SELECT id, user_id, type, coin_type, amount, description
      FROM transactions WHERE id IN (${placeholders})
    `).bind(...TARGET_TX_IDS).all()
    const found = (txRows.results || []) as any[]
    if (found.length !== 6) {
      return c.json({ error: 'abort', reason: `target tx count mismatch — expected 6, found ${found.length}` }, 400)
    }
    const allSolbat = found.every(r => r.user_id === SOLBAT_ID)
    const allReferral = found.every(r => r.type === 'referral_reward')
    const allL2 = found.every(r => (r.description || '').indexOf('Level 2') !== -1)
    const totalAmount = found.reduce((a, r) => a + Number(r.amount), 0)
    if (!allSolbat || !allReferral || !allL2) {
      return c.json({ error: 'abort', reason: 'safety check failed (user/type/level mismatch)', allSolbat, allReferral, allL2 }, 400)
    }
    if (totalAmount !== EXPECTED_REVERT) {
      return c.json({ error: 'abort', reason: `revert amount mismatch — expected ${EXPECTED_REVERT}, got ${totalAmount}` }, 400)
    }

    // 2) 현재 잔액 snapshot
    const before: any = await db.prepare(`SELECT id, name, email, qkey_balance FROM users WHERE id = ?`).bind(SOLBAT_ID).first()
    const beforeBalance = Number(before.qkey_balance)

    // 3) 실제 실행: 6건 DELETE + qkey_balance -1875
    const deleteResult = await db.prepare(`
      DELETE FROM transactions WHERE id IN (${placeholders}) AND user_id = ? AND type = 'referral_reward'
    `).bind(...TARGET_TX_IDS, SOLBAT_ID).run()

    const updateResult = await db.prepare(`
      UPDATE users SET qkey_balance = qkey_balance - ? WHERE id = ?
    `).bind(EXPECTED_REVERT, SOLBAT_ID).run()

    // 4) 사후 검증
    const after: any = await db.prepare(`SELECT id, name, email, qkey_balance FROM users WHERE id = ?`).bind(SOLBAT_ID).first()
    const afterBalance = Number(after.qkey_balance)

    const stillExists = await db.prepare(`
      SELECT id FROM transactions WHERE id IN (${placeholders})
    `).bind(...TARGET_TX_IDS).all()

    // 5) 솔밧 L2 5/11 KST tx 재확인
    const recheck = await db.prepare(`
      SELECT id, amount, ref_id,
             datetime(created_at, '+9 hours') AS created_at_kst,
             substr(datetime(created_at, '+9 hours'), 12, 2) AS kst_hour
      FROM transactions
      WHERE user_id = ? AND type = 'referral_reward'
        AND description LIKE '%Level 2%'
        AND date(created_at, '+9 hours') = '2026-05-11'
      ORDER BY datetime(created_at, '+9 hours') ASC, id ASC
    `).bind(SOLBAT_ID).all()
    const recheckRows = (recheck.results || []) as any[]
    const recheckSum = recheckRows.reduce((a, r) => a + Number(r.amount), 0)

    return c.json({
      success: true,
      executed: true,
      target_tx_ids: TARGET_TX_IDS,
      delete_result: {
        rows_affected: deleteResult.meta && (deleteResult.meta as any).changes,
        rows_still_exist_after_delete: (stillExists.results || []).length,
      },
      balance_change: {
        before: beforeBalance,
        after: afterBalance,
        diff: afterBalance - beforeBalance,
        expected_diff: -EXPECTED_REVERT,
        matches_expected: (afterBalance - beforeBalance) === -EXPECTED_REVERT,
      },
      update_result: {
        rows_affected: updateResult.meta && (updateResult.meta as any).changes,
      },
      recheck_may11_kst: {
        tx_count: recheckRows.length,
        tx_sum: recheckSum,
        expected_sum: 1950,
        matches_excel_truth: recheckSum === 1950,
        rows: recheckRows,
      },
      summary: {
        deleted: `transactions 6행 (Phase 3 중복 미러)`,
        balance_updated: `users.qkey_balance: ${beforeBalance} → ${afterBalance}`,
        kept: 'referral_rewards 원장 6행 (정상 데이터, 보존)',
      },
      note: '사장님 GO 결재 (2026-05-12) 실행 완료',
    })
  } catch (error) {
    console.error('exec-delete-solbat-phase3 error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★ 솔밧 산하 전체 referral_rewards 중복자 일괄 식별 — 사장님 지시 (2026-05-12, read-only) ★★★
//   경로: GET /api/diag/solbat-dup-referees?key=ADMIN_PW
//   목적: 같은 (referrer, referee, level, reward_date) 조합으로 2개 이상 분리 INSERT 된 행 모두 식별
//   - 솔밧(u#44) 본인 + 산하 22명 모든 referrer 기준으로 검사
//   - 분리된 행들을 1명1행 으로 합쳤을 때 정상 staking*7.5% 와 일치하는지 검증
//   - read-only: DB 변경 0건
app.get('/api/diag/solbat-dup-referees', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const SOLBAT_ID = 44

    // 1) 솔밧 산하 전체 회원 (재귀 CTE)
    const downline = await db.prepare(`
      WITH RECURSIVE tree(id, level) AS (
        SELECT id, 1 AS level FROM users WHERE referrer_id = ?
        UNION ALL
        SELECT u.id, t.level + 1 FROM users u JOIN tree t ON u.referrer_id = t.id WHERE t.level < 10
      )
      SELECT id FROM tree
    `).bind(SOLBAT_ID).all()
    const allIds = [SOLBAT_ID, ...(downline.results || []).map((r: any) => r.id)]
    const idPlaceholders = allIds.map(() => '?').join(',')

    // 2) (referrer, referee, level, reward_date) 다중 행 그룹 추출
    const dupGroups = await db.prepare(`
      SELECT referrer_id, referee_id, level, reward_date,
             COUNT(*) AS cnt, SUM(reward_amount) AS sum_reward,
             GROUP_CONCAT(id, ',') AS ref_ids,
             GROUP_CONCAT(reward_amount, ',') AS amounts
      FROM referral_rewards
      WHERE referrer_id IN (${idPlaceholders})
      GROUP BY referrer_id, referee_id, level, reward_date
      HAVING COUNT(*) > 1
      ORDER BY referrer_id ASC, referee_id ASC, reward_date ASC
    `).bind(...allIds).all()

    // 3) 각 그룹별 referee staking 합 + expected vs sum_reward 비교
    const groups: any[] = []
    for (const g of (dupGroups.results || [])) {
      const gg: any = g
      const referee: any = await db.prepare(`SELECT id, name, email FROM users WHERE id = ?`).bind(gg.referee_id).first()
      const referrer: any = await db.prepare(`SELECT id, name, email FROM users WHERE id = ?`).bind(gg.referrer_id).first()

      const stakes = await db.prepare(`
        SELECT id, amount, status, date(created_at, '+9 hours') AS staked_kst_date
        FROM staking
        WHERE user_id = ? AND status IN ('active', 'completed', 'capped')
        ORDER BY created_at ASC
      `).bind(gg.referee_id).all()
      const totalStake = (stakes.results || []).reduce((a: number, s: any) => a + Number(s.amount), 0)

      // L2 expected = totalStake * 7.5%, L1 expected = totalStake * 15%
      const rate = Number(gg.level) === 1 ? 0.15 : 0.075
      const expectedReward = Math.round(totalStake * rate)
      const sumReward = Number(gg.sum_reward)

      // tx 미러 행도 같이 추출 (각 ref_id 별)
      const refIdsArr = (gg.ref_ids || '').split(',').map((s: string) => parseInt(s, 10))
      const refPh = refIdsArr.map(() => '?').join(',')
      const txMirrors = await db.prepare(`
        SELECT id AS tx_id, ref_id, amount,
               datetime(created_at, '+9 hours') AS tx_kst
        FROM transactions
        WHERE ref_id IN (${refPh}) AND user_id = ? AND type = 'referral_reward'
        ORDER BY id ASC
      `).bind(...refIdsArr, gg.referrer_id).all()

      groups.push({
        referrer: referrer ? { id: referrer.id, name: referrer.name } : { id: gg.referrer_id },
        referee: referee ? { id: referee.id, name: referee.name, email: referee.email } : { id: gg.referee_id },
        level: gg.level,
        reward_date: gg.reward_date,
        dup_count: gg.cnt,
        ref_ids: refIdsArr,
        amounts: (gg.amounts || '').split(',').map((s: string) => Number(s)),
        sum_reward: sumReward,
        referee_total_stake: totalStake,
        expected_reward: expectedReward,
        sum_matches_expected: sumReward === expectedReward,
        tx_mirrors: txMirrors.results,
        action_suggestion: {
          keep_first_ref_id: refIdsArr[0],
          set_to_amount: expectedReward,
          delete_other_ref_ids: refIdsArr.slice(1),
          // tx 미러도 동일하게: 첫 번째 ref_id 의 tx 들 amount UPDATE, 나머지 ref_id 의 tx 들 DELETE
        },
      })
    }

    return c.json({
      success: true,
      scope: { solbat_id: SOLBAT_ID, downline_count: allIds.length - 1, total: allIds.length },
      dup_group_count: groups.length,
      groups,
      note: 'read-only — DB 무변경. 같은 (referrer,referee,level,reward_date) 다중 행 식별',
    })
  } catch (error) {
    console.error('solbat-dup-referees error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★ 솔밧 산하 중복 그룹 전체 정리 DRY-RUN PREVIEW — 사장님 지시 (2026-05-12, read-only) ★★★
//   경로: GET /api/diag/dryrun-cleanup-solbat-dups?key=ADMIN_PW
//   목적: 옵션 1 (1명1행 정리) 의 정확한 영향(잔액/tx/원장) 사전 미리보기
//     사장님 명시 지시: "옵션 1 (DB 깨끗하게 정리, 1명1행) 그리고 다른 중복자 다 찾아서 원래대로 돌려놔!"
//
//   본 endpoint 가 보고하는 것 (DB UPDATE 0건):
//   - 29 중복 그룹 각각: keep_ref_id(첫 행) + new_amount(expected) + delete_ref_ids(나머지)
//   - 각 그룹별 원장(referral_rewards) UPDATE 1건 + DELETE N건 미리보기
//   - 각 그룹별 tx(transactions) UPDATE 1건 + DELETE N건 미리보기
//   - 각 referrer 별 qkey_balance 정정 영향 합계 (현재 sum_reward → expected_reward 차이)
//   - safety_checks:
//       * sum_matches_expected = true 인 그룹은 정리 후 합계 보존 확인
//       * keep ref_id 의 tx 미러 존재 여부 확인
//       * 5/03 L0 표기 같은 이상한 행 별도 표시 (사장님 결재 필요)
//   - 본 endpoint 호출 시 DB 변경 0건. exec 는 별도 endpoint 에서 confirm=GO 로 진행
app.get('/api/diag/dryrun-cleanup-solbat-dups', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const SOLBAT_ID = 44

    // 1) 솔밧 산하 전체 회원 (재귀 CTE)
    const downline = await db.prepare(`
      WITH RECURSIVE tree(id, level) AS (
        SELECT id, 1 AS level FROM users WHERE referrer_id = ?
        UNION ALL
        SELECT u.id, t.level + 1 FROM users u JOIN tree t ON u.referrer_id = t.id WHERE t.level < 10
      )
      SELECT id FROM tree
    `).bind(SOLBAT_ID).all()
    const allIds = [SOLBAT_ID, ...(downline.results || []).map((r: any) => r.id)]
    const idPlaceholders = allIds.map(() => '?').join(',')

    // 2) (referrer, referee, level, reward_date) 다중 행 그룹 추출
    const dupGroups = await db.prepare(`
      SELECT referrer_id, referee_id, level, reward_date,
             COUNT(*) AS cnt, SUM(reward_amount) AS sum_reward,
             GROUP_CONCAT(id, ',') AS ref_ids,
             GROUP_CONCAT(reward_amount, ',') AS amounts
      FROM referral_rewards
      WHERE referrer_id IN (${idPlaceholders})
      GROUP BY referrer_id, referee_id, level, reward_date
      HAVING COUNT(*) > 1
      ORDER BY referrer_id ASC, referee_id ASC, level ASC, reward_date ASC
    `).bind(...allIds).all()

    // 3) 각 그룹별 정리 plan 계산
    const groups: any[] = []
    const balanceImpactByReferrer = new Map<number, { name: string, delta: number, groups: number }>()
    let totalRrUpdateCount = 0
    let totalRrDeleteCount = 0
    let totalTxUpdateCount = 0
    let totalTxDeleteCount = 0
    const suspiciousRows: any[] = []  // 이상한 5/03 L0 amount=15000 행 별도

    for (const g of (dupGroups.results || [])) {
      const gg: any = g
      const referee: any = await db.prepare(`SELECT id, name, email FROM users WHERE id = ?`).bind(gg.referee_id).first()
      const referrer: any = await db.prepare(`SELECT id, name, email, qkey_balance FROM users WHERE id = ?`).bind(gg.referrer_id).first()

      // referee staking 총합
      const stakes = await db.prepare(`
        SELECT id, amount, status, date(created_at, '+9 hours') AS staked_kst_date
        FROM staking
        WHERE user_id = ? AND status IN ('active', 'completed', 'capped')
        ORDER BY created_at ASC
      `).bind(gg.referee_id).all()
      const totalStake = (stakes.results || []).reduce((a: number, s: any) => a + Number(s.amount), 0)

      // expected rate
      const lvl = Number(gg.level)
      const rate = lvl === 1 ? 0.15 : (lvl === 2 ? 0.075 : 0)
      const expectedReward = Math.round(totalStake * rate)
      const sumReward = Number(gg.sum_reward)

      // ref_id 정렬: 가장 오래된(작은 id) 가 keep
      const refIdsArrRaw: number[] = (gg.ref_ids || '').split(',').map((s: string) => parseInt(s, 10))
      const refIdsArr = refIdsArrRaw.slice().sort((a, b) => a - b)
      const amountsArr: number[] = (gg.amounts || '').split(',').map((s: string) => Number(s))
      const keepRefId = refIdsArr[0]
      const deleteRefIds = refIdsArr.slice(1)

      // 원장 keep 행의 현재 amount
      const keepRow: any = await db.prepare(`
        SELECT id, reward_amount, original_amount, paid_date
        FROM referral_rewards WHERE id = ?
      `).bind(keepRefId).first()
      const keepCurrentAmount = keepRow ? Number(keepRow.reward_amount) : 0
      const rrUpdateNeeded = expectedReward !== keepCurrentAmount

      // tx 미러 추출
      const refPh = refIdsArr.map(() => '?').join(',')
      const txMirrors: any = await db.prepare(`
        SELECT id AS tx_id, ref_id, amount, description,
               datetime(created_at, '+9 hours') AS tx_kst
        FROM transactions
        WHERE ref_id IN (${refPh}) AND user_id = ? AND type = 'referral_reward'
        ORDER BY ref_id ASC, id ASC
      `).bind(...refIdsArr, gg.referrer_id).all()
      const txRows = (txMirrors.results || []) as any[]
      const keepTxRows = txRows.filter(t => Number(t.ref_id) === keepRefId)
      const deleteTxRows = txRows.filter(t => Number(t.ref_id) !== keepRefId)
      const keepTxId = keepTxRows.length > 0 ? keepTxRows[0].tx_id : null
      const keepTxCurrentAmount = keepTxRows.length > 0 ? Number(keepTxRows[0].amount) : 0
      const txUpdateNeeded = keepTxId !== null && keepTxCurrentAmount !== expectedReward
      const txKeepMissing = keepTxRows.length === 0  // keep 의 tx 미러 없음 (safety)

      // 잔액 영향 계산 (referrer 의 qkey_balance):
      //   정리 후 referrer 에게 발생할 변화 = (expected) - (sum_reward 현재)
      //   현재 잔액엔 sum_reward 가 이미 반영돼 있음 (tx 합) → expected 로 줄여야 함
      const balanceDelta = expectedReward - sumReward  // 음수면 차감
      const cur = balanceImpactByReferrer.get(Number(gg.referrer_id)) || { name: referrer?.name || `u#${gg.referrer_id}`, delta: 0, groups: 0 }
      cur.delta += balanceDelta
      cur.groups += 1
      balanceImpactByReferrer.set(Number(gg.referrer_id), cur)

      // 이상한 행 식별 (L0 표기 또는 amount=15000 같은 abnormal)
      const hasL0 = lvl !== 1 && lvl !== 2
      const hasAbnormalAmount = amountsArr.some(a => a === 15000 || a >= 10000)
      const isSuspicious = hasL0 || hasAbnormalAmount || (referrer && Number(gg.reward_date.substring(0, 10).replace(/-/g, '')) < 20260504)

      if (isSuspicious) {
        suspiciousRows.push({
          referrer: { id: gg.referrer_id, name: referrer?.name },
          referee: { id: gg.referee_id, name: referee?.name },
          level: lvl,
          reward_date: gg.reward_date,
          ref_ids: refIdsArr,
          amounts: amountsArr,
          reason: { hasL0, hasAbnormalAmount },
        })
      }

      totalRrUpdateCount += rrUpdateNeeded ? 1 : 0
      totalRrDeleteCount += deleteRefIds.length
      totalTxUpdateCount += txUpdateNeeded ? 1 : 0
      totalTxDeleteCount += deleteTxRows.length

      groups.push({
        referrer: { id: gg.referrer_id, name: referrer?.name },
        referee: { id: gg.referee_id, name: referee?.name },
        level: lvl,
        reward_date: gg.reward_date,
        dup_count: gg.cnt,
        current: {
          ref_ids: refIdsArr,
          amounts: amountsArr,
          sum_reward: sumReward,
        },
        referee_total_stake: totalStake,
        expected_reward: expectedReward,
        sum_matches_expected: sumReward === expectedReward,
        plan: {
          rr: {
            keep_ref_id: keepRefId,
            keep_current_amount: keepCurrentAmount,
            update_to: expectedReward,
            update_needed: rrUpdateNeeded,
            delete_ref_ids: deleteRefIds,
          },
          tx: {
            keep_tx_id: keepTxId,
            keep_tx_current_amount: keepTxCurrentAmount,
            update_to: expectedReward,
            update_needed: txUpdateNeeded,
            keep_missing: txKeepMissing,
            delete_tx_ids: deleteTxRows.map(t => t.tx_id),
            delete_tx_sum: deleteTxRows.reduce((a, t) => a + Number(t.amount), 0),
          },
          balance_delta: balanceDelta,  // referrer qkey_balance 변화량 (대부분 음수)
        },
        suspicious: isSuspicious,
      })
    }

    // 4) referrer 별 잔액 영향 합계 + 현재 잔액 & 정리 후 예상 잔액
    const balanceImpactArr: any[] = []
    for (const [refId, info] of balanceImpactByReferrer.entries()) {
      const u: any = await db.prepare(`SELECT id, name, qkey_balance FROM users WHERE id = ?`).bind(refId).first()
      const before = u ? Number(u.qkey_balance) : 0
      balanceImpactArr.push({
        referrer_id: refId,
        name: info.name,
        groups_affected: info.groups,
        balance_before: before,
        balance_delta: info.delta,
        balance_after_preview: before + info.delta,
      })
    }
    balanceImpactArr.sort((a, b) => a.referrer_id - b.referrer_id)

    // 5) 총합
    const totalBalanceDelta = balanceImpactArr.reduce((a, b) => a + Number(b.balance_delta), 0)

    return c.json({
      success: true,
      mode: 'dry_run',
      scope: { solbat_id: SOLBAT_ID, downline_count: allIds.length - 1, total_users: allIds.length },
      summary: {
        dup_group_count: groups.length,
        rr_update_count: totalRrUpdateCount,
        rr_delete_count: totalRrDeleteCount,
        tx_update_count: totalTxUpdateCount,
        tx_delete_count: totalTxDeleteCount,
        total_balance_delta_qkey: totalBalanceDelta,  // 합쳐서 잔액에 가해질 총 변화량
        suspicious_group_count: suspiciousRows.length,
      },
      balance_impact_by_referrer: balanceImpactArr,
      groups,
      suspicious_groups: suspiciousRows,
      next_step: {
        exec_endpoint: 'POST /api/diag/exec-cleanup-solbat-dups?key=ADMIN_PW&confirm=GO',
        guard: '이상한 그룹(suspicious_groups) 은 별도 결재 — 본 exec 에서 제외 옵션(skip_suspicious=1) 기본 ON',
      },
      note: 'read-only DRY-RUN — DB 변경 0건. 사장님 결재 후 exec endpoint 에서 실제 정리 진행',
    })
  } catch (error) {
    console.error('dryrun-cleanup-solbat-dups error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★ 5/11 23:59:59 KST 원장 복귀 dump — 사장님 명시 지시 (2026-05-12, read-only) ★★★
//   경로: GET /api/diag/dump-after-may11-cutoff?key=ADMIN_PW
//   목적: cutoff (KST 2026-05-11 23:59:59 = UTC 2026-05-11 14:59:59) 이후 D1 에 변경된 모든 행 식별
//   - transactions: created_at > cutoff 인 행 전체 (DELETE 대상)
//   - daily_rewards: created_at > cutoff (스키마에 created_at 없으면 reward_date >= '2026-05-12' 보조)
//   - referral_rewards: created_at > cutoff
//   - 회원별 영향 잔액 합계: sum(amount) by user_id, coin_type
//   - DB UPDATE 0건 — 순수 SELECT
app.get('/api/diag/dump-after-may11-cutoff', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    // UTC cutoff = KST 5/11 23:59:59 - 9h = 5/11 14:59:59 UTC
    const CUTOFF_UTC = '2026-05-11 14:59:59'

    // 1) transactions: cutoff 이후 INSERT 된 행 (created_at > cutoff)
    const txAfter: any = await db.prepare(`
      SELECT id, user_id, type, coin_type, amount, description, ref_id,
             created_at AS created_utc,
             datetime(created_at, '+9 hours') AS created_kst
      FROM transactions
      WHERE created_at > ?
      ORDER BY created_at ASC, id ASC
    `).bind(CUTOFF_UTC).all()
    const txRows = (txAfter.results || []) as any[]

    // 2) daily_rewards: cutoff 이후 (created_at 컬럼 우선, 없으면 reward_date)
    //    먼저 schema 확인
    let dailyAfter: any = { results: [] }
    try {
      dailyAfter = await db.prepare(`
        SELECT id, user_id, staking_id, usdt_amount, reward_date, paid_date
        FROM daily_rewards
        WHERE reward_date >= '2026-05-12'
           OR paid_date >= '2026-05-12'
        ORDER BY id ASC
      `).all()
    } catch (e) {
      dailyAfter = { results: [], error: String(e) }
    }
    const dailyRows = (dailyAfter.results || []) as any[]

    // 3) referral_rewards: cutoff 이후
    let rrAfter: any = { results: [] }
    try {
      rrAfter = await db.prepare(`
        SELECT id, referrer_id, referee_id, level, original_amount, reward_amount,
               reward_date, paid_date, created_at AS created_utc,
               datetime(created_at, '+9 hours') AS created_kst
        FROM referral_rewards
        WHERE created_at > ?
           OR reward_date >= '2026-05-12'
           OR paid_date >= '2026-05-12'
        ORDER BY id ASC
      `).bind(CUTOFF_UTC).all()
    } catch (e) {
      rrAfter = { results: [], error: String(e) }
    }
    const rrRows = (rrAfter.results || []) as any[]

    // 4) 회원별 잔액 영향 합산 (transactions 기준 — 실제 qkey_balance 영향 = QKEY tx 합)
    const balByUser = new Map<number, { qkey: number, qta: number, qx: number, usdt: number, tx_count: number }>()
    for (const t of txRows) {
      const uid = Number(t.user_id)
      const cur = balByUser.get(uid) || { qkey: 0, qta: 0, qx: 0, usdt: 0, tx_count: 0 }
      const amt = Number(t.amount) || 0
      const coin = String(t.coin_type || '').toUpperCase()
      if (coin === 'QKEY') cur.qkey += amt
      else if (coin === 'QTA') cur.qta += amt
      else if (coin === 'QX') cur.qx += amt
      else if (coin === 'USDT') cur.usdt += amt
      cur.tx_count += 1
      balByUser.set(uid, cur)
    }
    const balanceImpact: any[] = []
    for (const [uid, v] of balByUser.entries()) {
      const u: any = await db.prepare(`SELECT id, name, email, qkey_balance, qta_balance, qx_balance FROM users WHERE id = ?`).bind(uid).first()
      balanceImpact.push({
        user_id: uid,
        name: u?.name || `u#${uid}`,
        email: u?.email,
        current_balance: {
          qkey: u?.qkey_balance,
          qta: u?.qta_balance,
          qx: u?.qx_balance,
        },
        tx_count_after_cutoff: v.tx_count,
        delta_to_revert: {
          qkey: -v.qkey,
          qta: -v.qta,
          qx: -v.qx,
          usdt: -v.usdt,
        },
        preview_balance_after_revert: {
          qkey: (Number(u?.qkey_balance) || 0) - v.qkey,
          qta: (Number(u?.qta_balance) || 0) - v.qta,
          qx: (Number(u?.qx_balance) || 0) - v.qx,
        },
      })
    }
    balanceImpact.sort((a, b) => a.user_id - b.user_id)

    // 5) tx type 별 분포 요약
    const typeBreakdown = new Map<string, { count: number, sum_qkey: number }>()
    for (const t of txRows) {
      const k = `${t.type}|${t.coin_type}`
      const cur = typeBreakdown.get(k) || { count: 0, sum_qkey: 0 }
      cur.count += 1
      if (String(t.coin_type).toUpperCase() === 'QKEY') cur.sum_qkey += Number(t.amount) || 0
      typeBreakdown.set(k, cur)
    }
    const typeSummary: any[] = []
    for (const [k, v] of typeBreakdown.entries()) {
      typeSummary.push({ key: k, count: v.count, sum_qkey: v.sum_qkey })
    }
    typeSummary.sort((a, b) => b.count - a.count)

    return c.json({
      success: true,
      mode: 'dry_run_dump',
      cutoff: { kst: '2026-05-11 23:59:59', utc: CUTOFF_UTC },
      summary: {
        tx_count_after_cutoff: txRows.length,
        tx_sum_qkey: txRows.filter(t => String(t.coin_type).toUpperCase() === 'QKEY').reduce((a, t) => a + Number(t.amount), 0),
        daily_rewards_count_after_cutoff: dailyRows.length,
        daily_rewards_sum_usdt: dailyRows.reduce((a, r) => a + Number(r.usdt_amount || 0), 0),
        referral_rewards_count_after_cutoff: rrRows.length,
        referral_rewards_sum: rrRows.reduce((a, r) => a + Number(r.reward_amount || 0), 0),
        affected_user_count: balanceImpact.length,
      },
      tx_type_breakdown: typeSummary,
      balance_impact_by_user: balanceImpact,
      raw: {
        transactions: txRows,
        daily_rewards: dailyRows,
        referral_rewards: rrRows,
      },
      note: 'read-only — DB 변경 0건. 사장님 결재 후 exec endpoint 에서 cutoff 이후 행 전부 DELETE + qkey/qta/qx/usdt 잔액 환원',
    })
  } catch (error) {
    console.error('dump-after-may11-cutoff error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★ KST 5/11 23:59:59 이전 상태로 D1 전체 원복 EXEC — 사장님 명시 지시 (2026-05-12) ★★★
//   경로: POST /api/diag/exec-revert-to-may11-cutoff?key=ADMIN_PW&confirm=GO
//   사장님 명령 원문: "5월 11일 23시59분까지의 원장 상태로 돌려놓으라니깐"
//   동작:
//   1) cutoff (UTC 2026-05-11 14:59:59) 이후 INSERT 된 transactions 전부 DELETE
//      → 회원별 coin_type 별 amount 합 = 잔액 환원 delta
//   2) cutoff 이후 INSERT 된 daily_rewards 전부 DELETE
//   3) cutoff 이후 INSERT 된 referral_rewards 전부 DELETE
//   4) 영향 회원의 qkey_balance / qta_balance / qx_balance / usdt_balance 환원
//   - confirm=GO 필수
//   - 사후 검증: cutoff 이후 행 0건 확인 + 영향 회원 잔액 before/after 보고
app.post('/api/diag/exec-revert-to-may11-cutoff', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const confirm = c.req.query('confirm') || ''
    if (confirm !== 'GO') return c.json({ error: 'confirm=GO 필요' }, 400)
    const db = c.env.DB
    const CUTOFF_UTC = '2026-05-11 14:59:59'  // = KST 2026-05-11 23:59:59

    // 1) cutoff 이후 transactions 추출 (DELETE 대상 + 잔액 환원 delta 계산)
    const txAfter: any = await db.prepare(`
      SELECT id, user_id, coin_type, amount FROM transactions WHERE created_at > ?
    `).bind(CUTOFF_UTC).all()
    const txRows = (txAfter.results || []) as any[]

    // 회원별 코인별 환원 delta 계산
    const deltaByUser = new Map<number, { qkey: number, qta: number, qx: number, usdt: number }>()
    const txIds: number[] = []
    for (const t of txRows) {
      const uid = Number(t.user_id)
      const amt = Number(t.amount) || 0
      const coin = String(t.coin_type || '').toUpperCase()
      const cur = deltaByUser.get(uid) || { qkey: 0, qta: 0, qx: 0, usdt: 0 }
      if (coin === 'QKEY') cur.qkey += amt
      else if (coin === 'QTA') cur.qta += amt
      else if (coin === 'QX') cur.qx += amt
      else if (coin === 'USDT') cur.usdt += amt
      deltaByUser.set(uid, cur)
      txIds.push(Number(t.id))
    }

    // 영향 회원 before 잔액 캡쳐
    const userIds = Array.from(deltaByUser.keys())
    const beforeBalances: any[] = []
    for (const uid of userIds) {
      const u: any = await db.prepare(`
        SELECT id, name, email, qkey_balance, qta_balance, qx_balance, usdt_balance
        FROM users WHERE id = ?
      `).bind(uid).first()
      beforeBalances.push({
        user_id: uid,
        name: u?.name,
        before: {
          qkey: Number(u?.qkey_balance) || 0,
          qta: Number(u?.qta_balance) || 0,
          qx: Number(u?.qx_balance) || 0,
          usdt: Number(u?.usdt_balance) || 0,
        },
        delta: deltaByUser.get(uid),
      })
    }

    // 2) daily_rewards cutoff 이후 (reward_date 또는 paid_date 가 5/12 이상)
    const dailyAfter: any = await db.prepare(`
      SELECT id FROM daily_rewards
      WHERE reward_date >= '2026-05-12' OR paid_date >= '2026-05-12'
    `).all()
    const dailyIds = (dailyAfter.results || []).map((r: any) => Number(r.id))

    // 3) referral_rewards cutoff 이후
    const rrAfter: any = await db.prepare(`
      SELECT id FROM referral_rewards
      WHERE created_at > ?
         OR reward_date >= '2026-05-12'
         OR paid_date >= '2026-05-12'
    `).bind(CUTOFF_UTC).all()
    const rrIds = (rrAfter.results || []).map((r: any) => Number(r.id))

    // 4) 실제 DELETE 실행
    //    chunked DELETE (D1 IN(...) placeholder 한계 고려, 100건씩)
    //    TSX 파일에서 제네릭 화살표 함수 파싱 문제 회피 위해 일반 함수로 작성
    function chunk(arr: any[], n: number): any[][] {
      const out: any[][] = []
      for (let i = 0; i < arr.length; i += n) out.push(arr.slice(i, i + n))
      return out
    }

    let txDeleted = 0
    for (const part of chunk(txIds, 100)) {
      if (part.length === 0) continue
      const ph = part.map(() => '?').join(',')
      const r: any = await db.prepare(`DELETE FROM transactions WHERE id IN (${ph})`).bind(...part).run()
      txDeleted += (r.meta?.changes ?? part.length)
    }
    let dailyDeleted = 0
    for (const part of chunk(dailyIds, 100)) {
      if (part.length === 0) continue
      const ph = part.map(() => '?').join(',')
      const r: any = await db.prepare(`DELETE FROM daily_rewards WHERE id IN (${ph})`).bind(...part).run()
      dailyDeleted += (r.meta?.changes ?? part.length)
    }
    let rrDeleted = 0
    for (const part of chunk(rrIds, 100)) {
      if (part.length === 0) continue
      const ph = part.map(() => '?').join(',')
      const r: any = await db.prepare(`DELETE FROM referral_rewards WHERE id IN (${ph})`).bind(...part).run()
      rrDeleted += (r.meta?.changes ?? part.length)
    }

    // 5) 잔액 환원 (회원별 코인별)
    for (const [uid, d] of deltaByUser.entries()) {
      await db.prepare(`
        UPDATE users
        SET qkey_balance = qkey_balance - ?,
            qta_balance  = qta_balance  - ?,
            qx_balance   = qx_balance   - ?,
            usdt_balance = usdt_balance - ?
        WHERE id = ?
      `).bind(d.qkey, d.qta, d.qx, d.usdt, uid).run()
    }

    // 6) 사후 검증: cutoff 이후 행 잔존 확인
    const verifyTx: any = await db.prepare(`SELECT COUNT(*) AS c FROM transactions WHERE created_at > ?`).bind(CUTOFF_UTC).first()
    const verifyDaily: any = await db.prepare(`SELECT COUNT(*) AS c FROM daily_rewards WHERE reward_date >= '2026-05-12' OR paid_date >= '2026-05-12'`).first()
    const verifyRr: any = await db.prepare(`SELECT COUNT(*) AS c FROM referral_rewards WHERE created_at > ? OR reward_date >= '2026-05-12' OR paid_date >= '2026-05-12'`).bind(CUTOFF_UTC).first()

    // 영향 회원 after 잔액
    const afterBalances: any[] = []
    for (const b of beforeBalances) {
      const u: any = await db.prepare(`
        SELECT qkey_balance, qta_balance, qx_balance, usdt_balance FROM users WHERE id = ?
      `).bind(b.user_id).first()
      afterBalances.push({
        user_id: b.user_id,
        name: b.name,
        before: b.before,
        delta: b.delta,
        after: {
          qkey: Number(u?.qkey_balance) || 0,
          qta: Number(u?.qta_balance) || 0,
          qx: Number(u?.qx_balance) || 0,
          usdt: Number(u?.usdt_balance) || 0,
        },
      })
    }

    return c.json({
      success: true,
      cutoff: { kst: '2026-05-11 23:59:59', utc: CUTOFF_UTC },
      deleted: {
        transactions: txDeleted,
        daily_rewards: dailyDeleted,
        referral_rewards: rrDeleted,
      },
      affected_users: afterBalances.length,
      verify_remaining: {
        transactions_after_cutoff: Number(verifyTx?.c) || 0,
        daily_rewards_after_cutoff: Number(verifyDaily?.c) || 0,
        referral_rewards_after_cutoff: Number(verifyRr?.c) || 0,
      },
      balances: afterBalances,
      note: '사장님 명시 지시 (2026-05-12): 5월 11일 23시59분 이전 원장 상태로 전부 원복 완료',
    })
  } catch (error) {
    console.error('exec-revert-to-may11-cutoff error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★ 솔밧 L2 referee 6건 staking 금액 정밀 확인 — 사장님 지시 (2026-05-12, read-only) ★★★
//   경로: GET /api/diag/solbat-l2-referee-stakes?key=ADMIN_PW
//   목적: ref_id 688,698,725,729,731,773 의 referee 각자 staking 진입 금액 확인
//   - 사장님 지시: "6명중 1명이 2천달라면 150이 되야하는데 75로 계산했자나"
//   - referee_id 별 모든 staking 행 + amount 확인
//   - 정상 L2 = original_amount * 7.5% 인지 검증 ($2,000 → 150, $1,000 → 75)
//   - read-only: DB UPDATE 0건
app.get('/api/diag/solbat-l2-referee-stakes', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const REF_IDS = [688, 698, 725, 729, 731, 773]
    const placeholders = REF_IDS.map(() => '?').join(',')

    // 1) 원장 6행 + referee 정보
    const rrRows = await db.prepare(`
      SELECT rr.id AS ref_id, rr.referee_id, rr.original_amount, rr.reward_amount,
             rr.reward_date, rr.paid_date,
             datetime(rr.created_at, '+9 hours') AS rr_kst,
             u.name AS referee_name, u.email AS referee_email,
             date(u.created_at, '+9 hours') AS referee_signup_kst
      FROM referral_rewards rr
      JOIN users u ON rr.referee_id = u.id
      WHERE rr.id IN (${placeholders})
      ORDER BY rr.id ASC
    `).bind(...REF_IDS).all()

    // 2) 각 referee 의 전체 staking 행 + 그 중 5/04 KST 진입분
    const detailed: any[] = []
    let totalExpected = 0
    for (const r of (rrRows.results || [])) {
      const rr: any = r
      const stakes = await db.prepare(`
        SELECT id, amount, status,
               datetime(created_at, '+9 hours') AS staked_kst,
               date(created_at, '+9 hours') AS staked_kst_date,
               start_date, end_date
        FROM staking
        WHERE user_id = ?
        ORDER BY created_at ASC
      `).bind(rr.referee_id).all()

      const stakeRows = (stakes.results || []) as any[]
      const totalStakeAmount = stakeRows
        .filter((s: any) => ['active', 'completed', 'capped'].includes(s.status))
        .reduce((a: number, s: any) => a + Number(s.amount), 0)

      // L2 정상값 = sum(staking.amount) * 0.075 (사장님 엑셀 룰: $1,000 → 75, $2,000 → 150)
      const expectedL2 = Math.round(totalStakeAmount * 0.075)
      const actualL2 = Number(rr.reward_amount)
      const isCorrect = expectedL2 === actualL2
      if (!isCorrect) totalExpected += (expectedL2 - actualL2)

      detailed.push({
        ref_id: rr.ref_id,
        referee: { id: rr.referee_id, name: rr.referee_name, email: rr.referee_email, signup_kst: rr.referee_signup_kst },
        ledger: {
          original_amount: rr.original_amount,
          reward_amount: actualL2,
          reward_date: rr.reward_date,
          paid_date: rr.paid_date,
          rr_kst: rr.rr_kst,
        },
        stakes: stakeRows,
        total_stake_amount: totalStakeAmount,
        expected_l2_qkey: expectedL2,
        actual_l2_qkey: actualL2,
        diff: expectedL2 - actualL2,
        is_correct: isCorrect,
        action_required: isCorrect ? null : `reward_amount ${actualL2} → ${expectedL2} (+${expectedL2 - actualL2})`,
      })
    }

    return c.json({
      success: true,
      target_ref_ids: REF_IDS,
      summary: {
        total_ref_count: REF_IDS.length,
        correct_count: detailed.filter(d => d.is_correct).length,
        incorrect_count: detailed.filter(d => !d.is_correct).length,
        total_diff_to_add: totalExpected,
      },
      detailed,
      note: 'read-only — DB 무변경. 사장님 지시: 6명중 1명이 $2,000 → L2=150 인데 75 인지 확인',
    })
  } catch (error) {
    console.error('solbat-l2-referee-stakes error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★ 솔밧 L2 Phase 3 6건 원복 (사장님 명시 지시 2026-05-12: 어제처럼 1,950으로 돌려놔) ★★★
//   경로: POST /api/diag/restore-solbat-phase3?key=ADMIN_PW&confirm=GO
//   목적: exec-delete-solbat-phase3 으로 DELETE 된 6건을 원복 (INSERT) + qkey_balance +1,875
//   - 대상 ref_id: 688, 698, 725, 729, 731, 773 (원장은 그대로 보존됨)
//   - 원래 tx created_at (UTC): 2026-05-11 00:00:00 = KST 09:00:00 정각 (사장님 어제 본 행)
//   - amount 매핑: 688/698/725/729/731=75, 773=1500 (합 1,875)
//   - confirm=GO 필수
app.post('/api/diag/restore-solbat-phase3', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const dep = assertNotDeprecated(c, 'restore-solbat-phase3', '솔밧 phase3 복원 완료. safeInsertTransaction 가드 미적용 → 재호출 시 이중지급 위험')
    if (dep) return dep
    const confirm = c.req.query('confirm') || ''
    if (confirm !== 'GO') return c.json({ error: 'confirm=GO 필요' }, 400)
    const db = c.env.DB
    const SOLBAT_ID = 44
    const ORIG_CREATED_UTC = '2026-05-11 00:00:00'  // KST 09:00:00
    const REVERT_AMOUNT = 1875

    // 원장 6행 매핑 (ref_id, amount)
    const ITEMS = [
      { ref_id: 688, amount: 75 },
      { ref_id: 698, amount: 75 },
      { ref_id: 725, amount: 75 },
      { ref_id: 729, amount: 75 },
      { ref_id: 731, amount: 75 },
      { ref_id: 773, amount: 1500 },
    ]

    // 사전 검증 — 원장 6행이 그대로 존재하는지 + 현재 tx 에 중복 INSERT 방지
    const refIds = ITEMS.map(i => i.ref_id)
    const placeholders = refIds.map(() => '?').join(',')
    const rrRows = await db.prepare(`
      SELECT id, referrer_id, referee_id, reward_amount FROM referral_rewards WHERE id IN (${placeholders})
    `).bind(...refIds).all()
    if ((rrRows.results || []).length !== 6) {
      return c.json({ error: 'abort', reason: `원장 6행 누락 — found ${(rrRows.results || []).length}` }, 400)
    }

    const existingTx = await db.prepare(`
      SELECT id, ref_id FROM transactions WHERE ref_id IN (${placeholders}) AND user_id = ? AND type = 'referral_reward'
    `).bind(...refIds, SOLBAT_ID).all()
    if ((existingTx.results || []).length > 0) {
      return c.json({
        error: 'abort',
        reason: '이미 tx 가 존재 — 중복 INSERT 방지',
        existing: existingTx.results,
      }, 400)
    }

    const before: any = await db.prepare(`SELECT qkey_balance FROM users WHERE id = ?`).bind(SOLBAT_ID).first()
    const beforeBalance = Number(before.qkey_balance)

    // 실제 INSERT 6건 (원본 created_at = '2026-05-11 00:00:00' UTC = KST 09:00:00 정각)
    const insertedIds: number[] = []
    for (const item of ITEMS) {
      const res = await db.prepare(`
        INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id, created_at)
        VALUES (?, 'referral_reward', 'QKEY', ?, '추천 보너스 (Level 2)', ?, ?)
      `).bind(SOLBAT_ID, item.amount, item.ref_id, ORIG_CREATED_UTC).run()
      const id = (res.meta as any) && (res.meta as any).last_row_id
      insertedIds.push(id)
    }

    // qkey_balance 원복: +1875
    await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(REVERT_AMOUNT, SOLBAT_ID).run()

    const after: any = await db.prepare(`SELECT qkey_balance FROM users WHERE id = ?`).bind(SOLBAT_ID).first()
    const afterBalance = Number(after.qkey_balance)

    // 사후 검증: 5/11 KST tx 합계
    const recheck = await db.prepare(`
      SELECT id, amount, ref_id, datetime(created_at, '+9 hours') AS kst
      FROM transactions
      WHERE user_id = ? AND type = 'referral_reward'
        AND description LIKE '%Level 2%'
        AND date(created_at, '+9 hours') = '2026-05-11'
      ORDER BY datetime(created_at, '+9 hours') ASC, id ASC
    `).bind(SOLBAT_ID).all()
    const rows = (recheck.results || []) as any[]
    const sumAll = rows.reduce((a, r) => a + Number(r.amount), 0)

    return c.json({
      success: true,
      restored: true,
      inserted_tx_ids: insertedIds,
      balance: { before: beforeBalance, after: afterBalance, diff: afterBalance - beforeBalance },
      recheck_may11_kst: { tx_count: rows.length, tx_sum: sumAll, rows },
      note: '사장님 명시 지시 (2026-05-12): 어제처럼 1,950 으로 원복 완료',
    })
  } catch (error) {
    console.error('restore-solbat-phase3 error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★ 5/12 cron 사전 예측 — bottom-up 각 계정별 데일리 합 산출 (사장님 영구 룰 2026-05-12, read-only) ★★★
//   경로: GET /api/diag/daily-preview-bottom-up?key=ADMIN_PW&targetDate=2026-05-12
//   사장님 영구 명령: "맨 아래 데일리 정산된 하부부터 데일리 정산하면서 위로 올라갈것"
//   - read-only / INSERT/UPDATE/DELETE 0건
//   - 정확한 cron 룰 적용:
//       (a) reward_date = yesterdayKst (= targetDate - 1)
//       (b) 활성 staking 조건: start_date_kst <= yesterdayKst AND end_date_kst >= yesterdayKst AND status='active'
//       (c) 본인 데일리(QKEY) = staking.amount × staking.daily_rate × 150 (D1 daily_rate 직접 조회, 추측 금지)
//       (d) L1 매칭(QKEY) = Σ(L1 산하 회원의 본인 데일리) × 20%
//       (e) L2 매칭(QKEY) = Σ(L2 산하 회원의 본인 데일리) × 10%
//   - bottom-up 순회: 트리 depth 계산 후 max_depth → 0 역순으로 산출
app.get('/api/diag/daily-preview-bottom-up', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const USD_TO_QKEY = 150

    const now = new Date()
    const todayAuto = kstDateStr(now)
    const targetDate = c.req.query('targetDate') || todayAuto
    if (!/^\d{4}-\d{2}-\d{2}$/.test(targetDate)) {
      return c.json({ error: 'targetDate=YYYY-MM-DD 필요' }, 400)
    }
    const tdObj = new Date(targetDate + 'T00:00:00Z')
    const ydObj = new Date(tdObj.getTime() - 24 * 60 * 60 * 1000)
    const yesterdayKst = ydObj.toISOString().slice(0, 10)

    // STEP 1: yesterdayKst 시점 active staking 전체 조회
    const activeRows = await db.prepare(`
      SELECT
        s.user_id,
        s.id AS staking_id,
        s.amount,
        s.daily_rate,
        s.period_days,
        s.period_months,
        date(s.start_date, '+9 hours') AS start_date_kst,
        date(s.end_date, '+9 hours') AS end_date_kst,
        (SELECT COUNT(*) FROM daily_rewards WHERE staking_id = s.id) AS rewarded_count
      FROM staking s
      WHERE s.status = 'active'
        AND date(s.end_date, '+9 hours') >= date(?)
        AND date(s.start_date, '+9 hours') <= date(?)
      ORDER BY s.user_id ASC, s.id ASC
    `).bind(yesterdayKst, yesterdayKst).all()

    // 회원별 stake_total / paid_total 일괄 조회 (200% cap target)
    const stakeTotalsRaw = await db.prepare(`
      SELECT user_id, COALESCE(SUM(amount), 0) AS total
      FROM staking
      WHERE status IN ('active','completed','capped')
      GROUP BY user_id
    `).all()
    const stakeTotalByUser = new Map<number, number>()
    for (const r of (stakeTotalsRaw.results || []) as any[]) {
      stakeTotalByUser.set(Number(r.user_id), Number(r.total) || 0)
    }
    const paidTotalsRaw = await db.prepare(`
      SELECT user_id, COALESCE(SUM(amount), 0) AS total
      FROM transactions
      WHERE coin_type = 'QKEY' AND type IN ('daily_qkey', 'referral_reward')
      GROUP BY user_id
    `).all()
    const paidTotalByUser = new Map<number, number>()
    for (const r of (paidTotalsRaw.results || []) as any[]) {
      paidTotalByUser.set(Number(r.user_id), Number(r.total) || 0)
    }

    // STEP 2: 회원별 본인 데일리(own_daily) 산출 (cap 사전 보정)
    type OwnEntry = { user_id: number, own_daily: number, staking_count: number, capped: boolean }
    const ownByUser = new Map<number, OwnEntry>()
    let totalOwnDaily = 0
    let cappedSkipCount = 0
    const cappedSkipUsers: number[] = []

    for (const s of (activeRows.results || []) as any[]) {
      const uid = Number(s.user_id)
      const amount = Number(s.amount) || 0
      const rate = Number(s.daily_rate) || 0
      const rewardedCount = Number(s.rewarded_count) || 0
      const periodDays = Number(s.period_days) || (Number(s.period_months) * 30) || 0

      if (periodDays > 0 && rewardedCount >= periodDays) continue

      const stakeTotal = stakeTotalByUser.get(uid) || 0
      const paidTotal = paidTotalByUser.get(uid) || 0
      const target = stakeTotal * 2 * USD_TO_QKEY
      const isCapped = target > 0 && paidTotal >= target

      if (isCapped) {
        cappedSkipCount++
        if (!cappedSkipUsers.includes(uid)) cappedSkipUsers.push(uid)
        const cur = ownByUser.get(uid) || { user_id: uid, own_daily: 0, staking_count: 0, capped: true }
        cur.capped = true
        cur.staking_count++
        ownByUser.set(uid, cur)
        continue
      }

      let qkeyAmount = Math.round(amount * rate * USD_TO_QKEY)
      const remaining = target - paidTotal
      if (target > 0 && qkeyAmount > remaining) {
        qkeyAmount = Math.max(0, Math.floor(remaining))
      }

      const cur = ownByUser.get(uid) || { user_id: uid, own_daily: 0, staking_count: 0, capped: false }
      cur.own_daily += qkeyAmount
      cur.staking_count++
      ownByUser.set(uid, cur)
      totalOwnDaily += qkeyAmount
    }

    // STEP 3: 회원 referrer 관계 조회
    const usersRaw = await db.prepare(`
      SELECT id, name, email, referrer_id FROM users
    `).all()
    const userInfo = new Map<number, { name: string, email: string, referrer_id: number | null }>()
    for (const u of (usersRaw.results || []) as any[]) {
      userInfo.set(Number(u.id), {
        name: String(u.name || ''),
        email: String(u.email || ''),
        referrer_id: u.referrer_id != null ? Number(u.referrer_id) : null,
      })
    }

    // STEP 4: bottom-up 매칭 보너스 산출
    const activeStakingUsersRaw = await db.prepare(`
      SELECT DISTINCT user_id FROM staking
      WHERE status = 'active'
        AND date(end_date, '+9 hours') >= date(?)
        AND date(start_date, '+9 hours') <= date(?)
    `).bind(yesterdayKst, yesterdayKst).all()
    const activeStakingUserSet = new Set<number>()
    for (const r of (activeStakingUsersRaw.results || []) as any[]) {
      activeStakingUserSet.add(Number(r.user_id))
    }

    type MatchEntry = {
      l1_match: number, l2_match: number,
      l1_contributors: { user_id: number, contribution: number }[],
      l2_contributors: { user_id: number, contribution: number }[],
    }
    const matchByUser = new Map<number, MatchEntry>()

    function computeDepth(uid: number, memo: Map<number, number>, stack: Set<number>): number {
      if (memo.has(uid)) return memo.get(uid)!
      if (stack.has(uid)) { memo.set(uid, 0); return 0 }
      stack.add(uid)
      const info = userInfo.get(uid)
      if (!info || info.referrer_id == null) {
        memo.set(uid, 0)
        stack.delete(uid)
        return 0
      }
      const d = 1 + computeDepth(info.referrer_id, memo, stack)
      memo.set(uid, d)
      stack.delete(uid)
      return d
    }
    const depthMemo = new Map<number, number>()
    const ownEntries = Array.from(ownByUser.values())
    for (const e of ownEntries) computeDepth(e.user_id, depthMemo, new Set())
    ownEntries.sort((a, b) => (depthMemo.get(b.user_id) || 0) - (depthMemo.get(a.user_id) || 0))

    for (const child of ownEntries) {
      if (child.own_daily <= 0) continue
      const childInfo = userInfo.get(child.user_id)
      if (!childInfo) continue

      const parentId = childInfo.referrer_id
      if (parentId != null && activeStakingUserSet.has(parentId)) {
        const contribution = Math.round(child.own_daily * 0.20)
        if (contribution > 0) {
          const m = matchByUser.get(parentId) || { l1_match: 0, l2_match: 0, l1_contributors: [], l2_contributors: [] }
          m.l1_match += contribution
          m.l1_contributors.push({ user_id: child.user_id, contribution })
          matchByUser.set(parentId, m)
        }
      }

      const parentInfo = parentId != null ? userInfo.get(parentId) : null
      const grandId = parentInfo ? parentInfo.referrer_id : null
      if (grandId != null && activeStakingUserSet.has(grandId)) {
        const contribution = Math.round(child.own_daily * 0.10)
        if (contribution > 0) {
          const m = matchByUser.get(grandId) || { l1_match: 0, l2_match: 0, l1_contributors: [], l2_contributors: [] }
          m.l2_match += contribution
          m.l2_contributors.push({ user_id: child.user_id, contribution })
          matchByUser.set(grandId, m)
        }
      }
    }

    // STEP 5: 회원별 최종 예상 데일리 합 + cap 보정
    type FinalEntry = {
      user_id: number, name: string, email: string, depth: number,
      staking_count: number, own_daily: number, l1_match: number, l2_match: number,
      total_pre_cap: number, total_after_cap: number, capped: boolean,
      paid_total: number, target: number, remaining_before: number,
      l1_contributors: { user_id: number, contribution: number }[],
      l2_contributors: { user_id: number, contribution: number }[],
    }
    const finalList: FinalEntry[] = []

    const allUserIds = new Set<number>()
    for (const u of ownByUser.keys()) allUserIds.add(u)
    for (const u of matchByUser.keys()) allUserIds.add(u)

    let grandTotalOwn = 0, grandTotalL1 = 0, grandTotalL2 = 0, grandTotalFinal = 0

    for (const uid of allUserIds) {
      const own = ownByUser.get(uid)
      const match = matchByUser.get(uid) || { l1_match: 0, l2_match: 0, l1_contributors: [], l2_contributors: [] }
      const info = userInfo.get(uid)
      const stakeTotal = stakeTotalByUser.get(uid) || 0
      const paidTotal = paidTotalByUser.get(uid) || 0
      const target = stakeTotal * 2 * USD_TO_QKEY
      const remaining = Math.max(0, target - paidTotal)
      const isCappedAlready = !!own?.capped || (target > 0 && paidTotal >= target)

      const ownDaily = own?.own_daily || 0
      const totalPreCap = ownDaily + match.l1_match + match.l2_match

      let totalAfterCap = totalPreCap
      if (isCappedAlready) totalAfterCap = 0
      else if (target > 0 && totalPreCap > remaining) totalAfterCap = remaining

      grandTotalOwn += ownDaily
      grandTotalL1 += match.l1_match
      grandTotalL2 += match.l2_match
      grandTotalFinal += totalAfterCap

      finalList.push({
        user_id: uid,
        name: info?.name || '',
        email: info?.email || '',
        depth: depthMemo.get(uid) || 0,
        staking_count: own?.staking_count || 0,
        own_daily: ownDaily,
        l1_match: match.l1_match,
        l2_match: match.l2_match,
        total_pre_cap: totalPreCap,
        total_after_cap: totalAfterCap,
        capped: isCappedAlready,
        paid_total: paidTotal,
        target,
        remaining_before: remaining,
        l1_contributors: match.l1_contributors,
        l2_contributors: match.l2_contributors,
      })
    }

    finalList.sort((a, b) => b.total_after_cap - a.total_after_cap)

    return c.json({
      success: true,
      note: '사장님 영구 룰 (2026-05-12): bottom-up 순회, read-only, DB 무변경',
      target_date: targetDate,
      yesterday_kst: yesterdayKst,
      active_staking_user_count: activeStakingUserSet.size,
      active_staking_row_count: (activeRows.results || []).length,
      capped_skip_count: cappedSkipCount,
      capped_skip_users: cappedSkipUsers,
      grand_totals: {
        own_daily: grandTotalOwn,
        l1_match: grandTotalL1,
        l2_match: grandTotalL2,
        final_after_cap: grandTotalFinal,
      },
      user_count: finalList.length,
      list: finalList,
    })
  } catch (error) {
    console.error('daily-preview-bottom-up error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★ 솔밧 산하 조직원 데일리 + L1/L2 매칭 배당 정합성 일괄 분석 — 사장님 GO 결재 (2026-05-12, read-only) ★★★
//   경로: GET /api/diag/solbat-downline-audit?key=ADMIN_PW
//   목적: 솔밧(u#44) 산하 전체 조직원(L1/L2/L3+ 모두) 의 배당 정합성 정밀 진단
//   - 각 조직원 별 daily_reward / referral_reward(L1) / referral_reward(L2) 원장 vs tx 미러 일치 검증
//   - referral_rewards 원장 행 vs transactions 미러 LEFT JOIN + IS NULL 누락 추출
//   - tx 행 vs 원장 LEFT JOIN + IS NULL 유령(원장 없는 tx) 추출
//   - daily_rewards 원장 vs tx ('daily_reward' type) 미러 정합성
//   - 각 조직원 qkey_balance vs sum(tx.amount) 합산 일치 검증
//   - 잔액(qkey_balance) / DB UPDATE 0건 — 순수 SELECT 만
app.get('/api/diag/solbat-downline-audit', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const SOLBAT_ID = 44

    // 1) 솔밧 산하 전체 조직원 명단 (재귀: L1 + L2 + L3+ 모두)
    //    SQLite CTE 사용
    const downline = await db.prepare(`
      WITH RECURSIVE tree(id, name, email, referrer_id, level, root_referrer) AS (
        SELECT id, name, email, referrer_id, 1 AS level, referrer_id AS root_referrer
        FROM users WHERE referrer_id = ?
        UNION ALL
        SELECT u.id, u.name, u.email, u.referrer_id, t.level + 1, t.root_referrer
        FROM users u JOIN tree t ON u.referrer_id = t.id
        WHERE t.level < 10
      )
      SELECT id, name, email, referrer_id, level FROM tree ORDER BY level ASC, id ASC
    `).bind(SOLBAT_ID).all()
    const downlineUsers = (downline.results || []) as any[]
    const allIds = [SOLBAT_ID, ...downlineUsers.map(u => u.id)]

    if (allIds.length === 0) {
      return c.json({ success: true, message: '솔밧 산하 조직원 0명', downline: [] })
    }

    const idPlaceholders = allIds.map(() => '?').join(',')

    // 2) 각 회원별 referral_rewards 원장 vs transactions 미러 정합성
    //    referral_rewards 1행 ↔ transactions 1행 (type='referral_reward' AND ref_id=rr.id) 매칭
    //    누락(원장 있는데 미러 없음) + 유령(미러 있는데 원장 없음) 추출

    // 2-a) 원장 있는데 미러 없음 (누락)
    const rrMissingTx = await db.prepare(`
      SELECT rr.id AS ref_id, rr.referrer_id, rr.referee_id, rr.level,
             rr.original_amount, rr.reward_amount, rr.reward_date, rr.paid_date,
             u.name AS referrer_name
      FROM referral_rewards rr
      JOIN users u ON rr.referrer_id = u.id
      LEFT JOIN transactions t ON t.ref_id = rr.id AND t.type = 'referral_reward' AND t.user_id = rr.referrer_id
      WHERE rr.referrer_id IN (${idPlaceholders})
        AND t.id IS NULL
      ORDER BY rr.referrer_id ASC, rr.id ASC
    `).bind(...allIds).all()

    // 2-b) 미러 있는데 원장 없음 (유령 = ref_id NULL 또는 ref_id 존재 안 함)
    const txGhostNull = await db.prepare(`
      SELECT t.id AS tx_id, t.user_id, t.amount, t.description,
             datetime(t.created_at, '+9 hours') AS created_kst,
             u.name
      FROM transactions t
      JOIN users u ON t.user_id = u.id
      WHERE t.user_id IN (${idPlaceholders})
        AND t.type = 'referral_reward'
        AND t.ref_id IS NULL
      ORDER BY t.user_id ASC, t.id ASC
    `).bind(...allIds).all()

    const txGhostBadRef = await db.prepare(`
      SELECT t.id AS tx_id, t.user_id, t.ref_id, t.amount, t.description,
             datetime(t.created_at, '+9 hours') AS created_kst,
             u.name
      FROM transactions t
      JOIN users u ON t.user_id = u.id
      LEFT JOIN referral_rewards rr ON rr.id = t.ref_id
      WHERE t.user_id IN (${idPlaceholders})
        AND t.type = 'referral_reward'
        AND t.ref_id IS NOT NULL
        AND rr.id IS NULL
      ORDER BY t.user_id ASC, t.id ASC
    `).bind(...allIds).all()

    // 3) daily_rewards 원장 vs tx 미러 정합성
    //    daily_rewards 컬럼: user_id, staking_id, usdt_amount, reward_date, paid_date (QKEY 컬럼 없음)
    //    tx 'daily_reward' QKEY 행과 1:1 매칭 (건수 기준) — 원장 1행 ↔ tx 1행
    const dailyLedgerCount = await db.prepare(`
      SELECT user_id, COUNT(*) AS cnt, SUM(usdt_amount) AS sum_usdt
      FROM daily_rewards
      WHERE user_id IN (${idPlaceholders})
      GROUP BY user_id
    `).bind(...allIds).all()

    const dailyTxCount = await db.prepare(`
      SELECT user_id, COUNT(*) AS cnt, SUM(amount) AS sum_qkey
      FROM transactions
      WHERE user_id IN (${idPlaceholders})
        AND type = 'daily_reward' AND coin_type = 'QKEY'
      GROUP BY user_id
    `).bind(...allIds).all()

    // 4) 각 회원별 잔액 vs tx 합산
    const balances = await db.prepare(`
      SELECT id, name, email, qkey_balance, qta_balance, qx_balance, usdt_balance
      FROM users
      WHERE id IN (${idPlaceholders})
      ORDER BY id ASC
    `).bind(...allIds).all()

    // 5) 회원별 종합 요약 (data join in JS)
    const dailyLedgerMap: Record<number, any> = {}
    for (const r of (dailyLedgerCount.results || [])) {
      const rr: any = r
      dailyLedgerMap[rr.user_id] = { cnt: rr.cnt, sum_usdt: rr.sum_usdt }
    }
    const dailyTxMap: Record<number, any> = {}
    for (const r of (dailyTxCount.results || [])) {
      const rr: any = r
      dailyTxMap[rr.user_id] = { cnt: rr.cnt, sum_qkey: rr.sum_qkey }
    }
    const rrMissingMap: Record<number, any[]> = {}
    for (const r of (rrMissingTx.results || [])) {
      const rr: any = r
      if (!rrMissingMap[rr.referrer_id]) rrMissingMap[rr.referrer_id] = []
      rrMissingMap[rr.referrer_id].push(rr)
    }
    const txGhostNullMap: Record<number, any[]> = {}
    for (const r of (txGhostNull.results || [])) {
      const rr: any = r
      if (!txGhostNullMap[rr.user_id]) txGhostNullMap[rr.user_id] = []
      txGhostNullMap[rr.user_id].push(rr)
    }
    const txGhostBadRefMap: Record<number, any[]> = {}
    for (const r of (txGhostBadRef.results || [])) {
      const rr: any = r
      if (!txGhostBadRefMap[rr.user_id]) txGhostBadRefMap[rr.user_id] = []
      txGhostBadRefMap[rr.user_id].push(rr)
    }

    // 6) 각 사용자 요약
    const userSummary: any[] = []
    for (const u of (balances.results || [])) {
      const uu: any = u
      const uid = uu.id
      const dailyL = dailyLedgerMap[uid] || { cnt: 0, sum: 0 }
      const dailyT = dailyTxMap[uid] || { cnt: 0, sum: 0 }
      const downlineEntry = downlineUsers.find(d => d.id === uid)
      const level = uid === SOLBAT_ID ? 0 : (downlineEntry ? downlineEntry.level : null)

      const rrMissCnt = (rrMissingMap[uid] || []).length
      const rrMissSum = (rrMissingMap[uid] || []).reduce((a, r) => a + Number(r.reward_amount), 0)
      const ghostNullCnt = (txGhostNullMap[uid] || []).length
      const ghostNullSum = (txGhostNullMap[uid] || []).reduce((a, r) => a + Number(r.amount), 0)
      const ghostBadCnt = (txGhostBadRefMap[uid] || []).length
      const ghostBadSum = (txGhostBadRefMap[uid] || []).reduce((a, r) => a + Number(r.amount), 0)

      const dailyCntDiff = Number(dailyT.cnt || 0) - Number(dailyL.cnt || 0)
      const issues: string[] = []
      if (rrMissCnt > 0) issues.push(`referral_rewards 원장 ${rrMissCnt}건/${rrMissSum} QKEY tx 미러 누락`)
      if (ghostNullCnt > 0) issues.push(`tx ref_id NULL 유령 ${ghostNullCnt}건/${ghostNullSum} QKEY`)
      if (ghostBadCnt > 0) issues.push(`tx ref_id 원장 매칭 실패 ${ghostBadCnt}건/${ghostBadSum} QKEY`)
      if (dailyCntDiff !== 0) issues.push(`daily_rewards 건수 불일치: tx ${dailyT.cnt}건 vs 원장 ${dailyL.cnt}건 (diff=${dailyCntDiff})`)

      userSummary.push({
        id: uid,
        name: uu.name,
        email: uu.email,
        level,
        qkey_balance: uu.qkey_balance,
        daily: { ledger: dailyL, tx: dailyT, count_diff: dailyCntDiff },
        referral_missing_tx: { count: rrMissCnt, sum: rrMissSum, rows: rrMissingMap[uid] || [] },
        tx_ghost_null_ref: { count: ghostNullCnt, sum: ghostNullSum, rows: txGhostNullMap[uid] || [] },
        tx_ghost_bad_ref: { count: ghostBadCnt, sum: ghostBadSum, rows: txGhostBadRefMap[uid] || [] },
        is_clean: issues.length === 0,
        issues,
      })
    }

    // 7) 전체 합산
    const grandTotal = {
      total_users: userSummary.length,
      clean_users: userSummary.filter(u => u.is_clean).length,
      problem_users: userSummary.filter(u => !u.is_clean).length,
      total_rr_missing_count: userSummary.reduce((a, u) => a + u.referral_missing_tx.count, 0),
      total_rr_missing_sum: userSummary.reduce((a, u) => a + u.referral_missing_tx.sum, 0),
      total_ghost_null_count: userSummary.reduce((a, u) => a + u.tx_ghost_null_ref.count, 0),
      total_ghost_null_sum: userSummary.reduce((a, u) => a + u.tx_ghost_null_ref.sum, 0),
      total_ghost_bad_count: userSummary.reduce((a, u) => a + u.tx_ghost_bad_ref.count, 0),
      total_ghost_bad_sum: userSummary.reduce((a, u) => a + u.tx_ghost_bad_ref.sum, 0),
      total_daily_count_diff: userSummary.reduce((a, u) => a + u.daily.count_diff, 0),
    }

    // 8) 레벨별 분포
    const byLevel: Record<string, any> = {}
    for (const u of userSummary) {
      const lv = String(u.level)
      if (!byLevel[lv]) byLevel[lv] = { count: 0, clean: 0, problem: 0 }
      byLevel[lv].count += 1
      if (u.is_clean) byLevel[lv].clean += 1
      else byLevel[lv].problem += 1
    }

    return c.json({
      success: true,
      root: { id: SOLBAT_ID, included: true },
      grand_total: grandTotal,
      by_level: byLevel,
      problem_users: userSummary.filter(u => !u.is_clean),
      clean_users_count: userSummary.filter(u => u.is_clean).length,
      all_users_detail: userSummary,
      note: 'read-only — DB/잔액 무변경. solbat 본인 + 산하 모든 레벨 포함',
    })
  } catch (error) {
    console.error('solbat-downline-audit error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★ 회원 검색 (이름/이메일/추천코드 LIKE) — 사실 확인용 영구 진단 ★★★
//   경로: /api/diag/search-user?q=검색어&key=ADMIN_PW
app.get('/api/diag/search-user', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const q = c.req.query('q') || ''
    if (!q || q.length < 1) return c.json({ error: 'q 파라미터 필요' }, 400)

    const db = c.env.DB
    const term = '%' + q + '%'
    const users = await db.prepare(`
      SELECT u.id, u.name, u.email, u.country, u.language, u.referral_code, u.referrer_id, u.created_at,
        u.qta_balance, u.qx_balance, u.qkey_balance, u.usdt_balance,
        COALESCE(SUM(CASE WHEN s.status IN ('active','completed','capped') THEN s.amount ELSE 0 END), 0) as staking_amount,
        COUNT(DISTINCT s.id) as staking_count
      FROM users u
      LEFT JOIN staking s ON u.id = s.user_id
      WHERE u.email LIKE ? OR u.name LIKE ? OR u.referral_code LIKE ?
      GROUP BY u.id
      ORDER BY u.id ASC
      LIMIT 50
    `).bind(term, term, term).all()

    return c.json({ success: true, query: q, count: users.results.length, users: users.results })
  } catch (error) {
    console.error('search-user diag error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★ 특정 사용자 상세 (잔액 + 스테이킹 + 일일배당 + 추천보너스 + 거래내역) ★★★
//   경로: /api/diag/user-detail?user_id=N&from=YYYY-MM-DD&to=YYYY-MM-DD&key=ADMIN_PW
app.get('/api/diag/user-detail', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)

    const userId = Number(c.req.query('user_id') || 0)
    if (!userId) return c.json({ error: 'user_id 필요' }, 400)
    const from = c.req.query('from') || '2026-05-01'
    const to = c.req.query('to') || '2026-05-31'

    const db = c.env.DB

    await ensureWithdrawableSchema(db)
    const user = await db.prepare(`
      SELECT id, name, email, country, language, referral_code, referrer_id, created_at,
        qta_balance, qx_balance, qkey_balance, usdt_balance,
        COALESCE(qta_initial,0) as qta_initial,
        COALESCE(qx_initial,0) as qx_initial,
        COALESCE(qta_withdrawable,0) as qta_withdrawable,
        COALESCE(qx_withdrawable,0) as qx_withdrawable,
        COALESCE(usdt_withdrawable,0) as usdt_withdrawable
      FROM users WHERE id = ?
    `).bind(userId).first() as any

    if (!user) return c.json({ error: 'user not found' }, 404)

    const referrer = user.referrer_id ? await db.prepare(`
      SELECT id, name, email, referral_code FROM users WHERE id = ?
    `).bind(user.referrer_id).first() : null

    const stakings = await db.prepare(`
      SELECT id, amount, daily_rate, status, start_date, end_date, period_days, period_months
      FROM staking WHERE user_id = ? ORDER BY id ASC
    `).bind(userId).all()

    const dailyRewards = await db.prepare(`
      SELECT id, staking_id, usdt_amount, reward_date, paid_date
      FROM daily_rewards
      WHERE user_id = ? AND reward_date BETWEEN ? AND ?
      ORDER BY reward_date ASC, id ASC
    `).bind(userId, from, to).all()

    const referralRewardsReceived = await db.prepare(`
      SELECT id, referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date
      FROM referral_rewards
      WHERE referrer_id = ? AND reward_date BETWEEN ? AND ?
      ORDER BY reward_date ASC, id ASC
    `).bind(userId, from, to).all()

    // ★ KST 표시 영구룰 (사장님 C안 결재 2026-05-12): created_at 응답값을 KST(+9h) 변환
    const transactions = await db.prepare(`
      SELECT id, type, coin_type, amount, description,
             datetime(created_at, '+9 hours') AS created_at,
             ref_id
      FROM transactions
      WHERE user_id = ? AND date(created_at, '+9 hours') BETWEEN ? AND ?
      ORDER BY datetime(created_at, '+9 hours') ASC, id ASC
    `).bind(userId, from, to).all()

    return c.json({
      success: true,
      from, to,
      user,
      referrer,
      stakings: stakings.results,
      daily_rewards_count: dailyRewards.results.length,
      daily_rewards_sum: (dailyRewards.results as any[]).reduce((s, r) => s + Number(r.usdt_amount || 0), 0),
      daily_rewards: dailyRewards.results,
      referral_rewards_received_count: referralRewardsReceived.results.length,
      referral_rewards_received_sum: (referralRewardsReceived.results as any[]).reduce((s, r) => s + Number(r.reward_amount || 0), 0),
      referral_rewards_received: referralRewardsReceived.results,
      transactions_count: transactions.results.length,
      transactions: transactions.results
    })
  } catch (error) {
    console.error('user-detail diag error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★ 특정 사용자 다운라인 명단 + 기간 내 매출/배당 추적 (사실 확인용 영구 진단) ★★★
//   경로: /api/diag/downline-trace?user_id=N&from=YYYY-MM-DD&to=YYYY-MM-DD&key=ADMIN_PW
//   읽기 전용:
//     1) target user 정보 + 직계(L1)/2단계(L2) 다운라인 user_id 명단
//     2) 다운라인 각자의 staking 명단 (start_date, status, amount)
//     3) 다운라인 각자의 daily_rewards (reward_date BETWEEN from AND to)
//     4) target user 의 referral_reward transactions (date BETWEEN from AND to)
app.get('/api/diag/downline-trace', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)

    const db = c.env.DB
    const userId = parseInt(c.req.query('user_id') || '0')
    const from = c.req.query('from') || ''
    const to = c.req.query('to') || ''
    if (!userId || !/^\d{4}-\d{2}-\d{2}$/.test(from) || !/^\d{4}-\d{2}-\d{2}$/.test(to)) {
      return c.json({ error: 'user_id, from=YYYY-MM-DD, to=YYYY-MM-DD 필요' }, 400)
    }

    // 1) target user
    const target = await db.prepare(`SELECT id, email, referrer_id FROM users WHERE id = ?`).bind(userId).first() as any
    if (!target) return c.json({ error: 'user not found' }, 404)

    // 2) L1 직계 다운라인 (target 의 referrer_id = userId)
    const l1Rows = await db.prepare(`
      SELECT id, email, referrer_id, created_at
      FROM users WHERE referrer_id = ?
      ORDER BY id ASC
    `).bind(userId).all()
    const l1Ids = (l1Rows.results as any[]).map(r => r.id)

    // 3) L2 다운라인 (L1 의 다운라인)
    let l2Rows: any = { results: [] }
    if (l1Ids.length > 0) {
      const placeholders = l1Ids.map(() => '?').join(',')
      l2Rows = await db.prepare(`
        SELECT id, email, referrer_id, created_at
        FROM users WHERE referrer_id IN (${placeholders})
        ORDER BY id ASC
      `).bind(...l1Ids).all()
    }
    const l2Ids = (l2Rows.results as any[]).map(r => r.id)
    const allDownlineIds = [...l1Ids, ...l2Ids]

    // 4) 다운라인 staking 명단
    let stakings: any[] = []
    if (allDownlineIds.length > 0) {
      const placeholders = allDownlineIds.map(() => '?').join(',')
      const stRows = await db.prepare(`
        SELECT id as staking_id, user_id, amount, status,
               date(start_date, '+9 hours') as start_date_kst,
               date(end_date, '+9 hours') as end_date_kst
        FROM staking WHERE user_id IN (${placeholders})
        ORDER BY user_id ASC, id ASC
      `).bind(...allDownlineIds).all()
      stakings = stRows.results as any[]
    }

    // 5) 다운라인 daily_rewards (reward_date BETWEEN from AND to)
    let downlineRewards: any[] = []
    if (allDownlineIds.length > 0) {
      const placeholders = allDownlineIds.map(() => '?').join(',')
      const drRows = await db.prepare(`
        SELECT dr.id, dr.staking_id, dr.user_id, u.email,
               dr.reward_date, dr.paid_date, dr.usdt_amount
        FROM daily_rewards dr
        LEFT JOIN users u ON u.id = dr.user_id
        WHERE dr.user_id IN (${placeholders})
          AND dr.reward_date BETWEEN ? AND ?
        ORDER BY dr.user_id ASC, dr.reward_date ASC, dr.id ASC
      `).bind(...allDownlineIds, from, to).all()
      downlineRewards = drRows.results as any[]
    }

    // 6) target user 의 referral_reward transactions (KST 기준)
    const targetTxRows = await db.prepare(`
      SELECT id, type, coin_type, amount, description, created_at,
             date(created_at, '+9 hours') as paid_date_kst
      FROM transactions
      WHERE user_id = ? AND type = 'referral_reward'
        AND date(created_at, '+9 hours') BETWEEN ? AND ?
      ORDER BY id ASC
    `).bind(userId, from, to).all()

    // 사용자 → level 매핑
    const levelMap = new Map<number, 1 | 2>()
    for (const id of l1Ids) levelMap.set(id, 1)
    for (const id of l2Ids) levelMap.set(id, 2)

    // 다운라인 reward 를 staking_id → user_id 로 정리 (level 정보 추가)
    const enrichedRewards = downlineRewards.map(r => ({
      ...r,
      level: levelMap.get(r.user_id as number) || 0
    }))

    return c.json({
      success: true,
      target_user: target,
      l1_count: l1Ids.length,
      l2_count: l2Ids.length,
      l1_downline: l1Rows.results,
      l2_downline: l2Rows.results,
      downline_stakings: stakings,
      downline_rewards_in_range: enrichedRewards,
      target_referral_transactions_in_range: targetTxRows.results
    })
  } catch (error) {
    console.error('downline-trace diag error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★ 특정 날짜 daily_rewards 실제 D1 row 조회 (사실 확인용) ★★★
//   경로: /api/diag/rewards-by-date?date=YYYY-MM-DD&key=ADMIN_PW
//   읽기 전용 — 그 날짜의 daily_rewards 테이블 전체 row + transactions 5/12 daily_qkey/referral_reward 행 모두 노출
app.get('/api/diag/rewards-by-date', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)

    const db = c.env.DB
    const date = c.req.query('date') || ''
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      return c.json({ error: 'date=YYYY-MM-DD 필요' }, 400)
    }

    // daily_rewards (그 날짜의 발생일)
    const drRows = await db.prepare(`
      SELECT dr.id, dr.staking_id, dr.user_id, u.email, dr.reward_date, dr.paid_date, dr.usdt_amount
      FROM daily_rewards dr
      LEFT JOIN users u ON u.id = dr.user_id
      WHERE dr.reward_date = ?
      ORDER BY dr.id ASC
    `).bind(date).all()

    // transactions (그 날짜의 paid — KST 기준 created_at)
    const txRows = await db.prepare(`
      SELECT id, user_id, type, coin_type, amount, description, created_at
      FROM transactions
      WHERE date(created_at, '+9 hours') = ?
        AND type IN ('daily_qkey','referral_reward')
      ORDER BY id ASC
    `).bind(date).all()

    return c.json({
      success: true,
      date,
      daily_rewards_count: drRows.results.length,
      daily_rewards_sum_usdt: (drRows.results as any[]).reduce((s, r) => s + Number(r.usdt_amount || 0), 0),
      transactions_count: txRows.results.length,
      transactions_sum_qkey: (txRows.results as any[]).reduce((s, r) => s + Number(r.amount || 0), 0),
      daily_rewards: drRows.results,
      transactions: txRows.results
    })
  } catch (error) {
    console.error('rewards-by-date diag error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// 어드민 진단: 특정 날짜 + 특정 사용자의 transactions 조회 (중복지급 원인 파악용)
app.get('/api/admin/diag/transactions', async (c) => {
  try {
    const db = c.env.DB
    const date = c.req.query('date') || ''
    const userId = c.req.query('userId') || ''
    if (!date || !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      return c.json({ error: 'date=YYYY-MM-DD 필요' }, 400)
    }
    let rows
    if (userId) {
      rows = await db.prepare(
        `SELECT id, user_id, type, coin_type, amount, description, created_at
         FROM transactions
         WHERE user_id = ? AND date(created_at, '+9 hours') = ?
         ORDER BY id`
      ).bind(userId, date).all()
    } else {
      rows = await db.prepare(
        `SELECT id, user_id, type, coin_type, amount, description, created_at
         FROM transactions
         WHERE date(created_at, '+9 hours') = ?
         ORDER BY user_id, id`
      ).bind(date).all()
    }
    // type 별 집계
    const byType: Record<string, { count: number, total: number }> = {}
    for (const r of (rows.results || [])) {
      const t = String(r.type)
      if (!byType[t]) byType[t] = { count: 0, total: 0 }
      byType[t].count++
      byType[t].total += Number(r.amount) || 0
    }
    // 같은 (user_id, type, description) 중복 검출
    const dupes: any[] = []
    const seen: Record<string, any[]> = {}
    for (const r of (rows.results || [])) {
      const key = `${r.user_id}|${r.type}|${r.description}`
      if (!seen[key]) seen[key] = []
      seen[key].push(r)
    }
    for (const k of Object.keys(seen)) {
      if (seen[k].length > 1) dupes.push({ key: k, rows: seen[k] })
    }
    return c.json({
      success: true,
      date,
      userId: userId || 'all',
      total_rows: rows.results.length,
      by_type: byType,
      duplicates: dupes,
      rows: rows.results
    })
  } catch (error) {
    return c.json({ error: String(error) }, 500)
  }
})

// 어드민 진단: 특정 날짜의 daily_rewards / referral_rewards 행 조회 (디버깅용)
app.get('/api/admin/diag/rewards', async (c) => {
  try {
    const db = c.env.DB
    const date = c.req.query('date') || ''
    if (!date || !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      return c.json({ error: 'date=YYYY-MM-DD 필요' }, 400)
    }
    // reward_date 또는 paid_date 기준으로 조회
    const dailyByReward = await db.prepare(
      `SELECT id, user_id, staking_id, usdt_amount, reward_date, paid_date, created_at
       FROM daily_rewards WHERE reward_date = ? ORDER BY id`
    ).bind(date).all()
    const dailyByPaid = await db.prepare(
      `SELECT id, user_id, staking_id, usdt_amount, reward_date, paid_date, created_at
       FROM daily_rewards WHERE paid_date = ? ORDER BY id`
    ).bind(date).all()
    const refByReward = await db.prepare(
      `SELECT id, referrer_id, referee_id, level, reward_amount, reward_date, paid_date, created_at
       FROM referral_rewards WHERE reward_date = ? ORDER BY id`
    ).bind(date).all()
    const refByPaid = await db.prepare(
      `SELECT id, referrer_id, referee_id, level, reward_amount, reward_date, paid_date, created_at
       FROM referral_rewards WHERE paid_date = ? ORDER BY id`
    ).bind(date).all()
    // 같은 (user, staking, reward_date) 중복 검출
    const dupes = await db.prepare(
      `SELECT user_id, staking_id, reward_date, COUNT(*) as cnt
       FROM daily_rewards WHERE reward_date = ? OR paid_date = ?
       GROUP BY user_id, staking_id, reward_date HAVING cnt > 1`
    ).bind(date, date).all()

    // transactions 테이블에서 해당 날짜에 발생한 보상 관련 행 전체 조회
    // (date()는 SQLite에서 created_at의 날짜 부분 추출 → KST 저장 기준)
    const txRewards = await db.prepare(
      `SELECT id, user_id, type, coin_type, amount, description, created_at
       FROM transactions
       WHERE date(created_at, '+9 hours') = ?
         AND type IN ('daily_qkey','direct_referral','referral_reward','daily_reward_rollback','referral_reward_rollback','rollback_restore')
       ORDER BY id`
    ).bind(date).all()

    // type별 집계
    const txSummary = await db.prepare(
      `SELECT type,
              COUNT(*) as cnt,
              COALESCE(SUM(amount), 0) as total_amount
       FROM transactions
       WHERE date(created_at, '+9 hours') = ?
         AND type IN ('daily_qkey','direct_referral','referral_reward','daily_reward_rollback','referral_reward_rollback')
       GROUP BY type`
    ).bind(date).all()

    // referral_reward 중 description에 Level 1 / Level 2 포함 여부별 분리 집계
    const txReferralBreakdown = await db.prepare(
      `SELECT
         SUM(CASE WHEN description LIKE '%Level 1%' THEN 1 ELSE 0 END) as lvl1_cnt,
         SUM(CASE WHEN description LIKE '%Level 1%' THEN amount ELSE 0 END) as lvl1_amount,
         SUM(CASE WHEN description LIKE '%Level 2%' THEN 1 ELSE 0 END) as lvl2_cnt,
         SUM(CASE WHEN description LIKE '%Level 2%' THEN amount ELSE 0 END) as lvl2_amount,
         SUM(CASE WHEN description NOT LIKE '%Level 1%' AND description NOT LIKE '%Level 2%' THEN 1 ELSE 0 END) as other_cnt,
         SUM(CASE WHEN description NOT LIKE '%Level 1%' AND description NOT LIKE '%Level 2%' THEN amount ELSE 0 END) as other_amount
       FROM transactions
       WHERE date(created_at, '+9 hours') = ? AND type = 'referral_reward'`
    ).bind(date).all()

    return c.json({
      success: true,
      date,
      daily_by_reward_date: dailyByReward.results,
      daily_by_paid_date: dailyByPaid.results,
      referral_by_reward_date: refByReward.results,
      referral_by_paid_date: refByPaid.results,
      duplicates_daily: dupes.results,
      tx_rewards: txRewards.results,
      tx_summary: txSummary.results,
      tx_referral_breakdown: txReferralBreakdown.results
    })
  } catch (error) {
    return c.json({ error: String(error) }, 500)
  }
})

// ★★ 사장님 2026-05-07 지시 ★★ KST 24시간 윈도우 누락 매출자 진단/보충
// 룰 (재확정):
//   - KST 어제 00:00:00 ~ 23:59:59 사이에 staking-approve 된 회원 = 어제 매출자
//   - 가입 시간이 KST 00:01 이든 23:59 이든 무조건 같은 KST 날짜로 묶음
//   - 점검 cron 은 익일 KST 01:00, 지급 cron 은 익일 KST 08:00 으로 분리
// body:
//   { targetDate: 'YYYY-MM-DD' (KST, 점검 대상일, 기본=어제 KST),
//     paidDate:   'YYYY-MM-DD' (KST, 지급일,    기본=오늘 KST),
//     dryRun: true|false }
app.post('/api/admin/rewards/check-missing-by-kst', async (c) => {
  try {
    const db = c.env.DB
    const body = await c.req.json().catch(() => ({}))
    const dryRun = body.dryRun !== false  // 기본 true 안전

    // KST 기준 today / yesterday 계산
    const nowMs = Date.now()
    const todayKstStr = new Date(nowMs + 9*60*60*1000).toISOString().slice(0,10)
    const yKstMs = nowMs + 9*60*60*1000 - 24*60*60*1000
    const yKstStr = new Date(yKstMs).toISOString().slice(0,10)

    const targetDate = body.targetDate ? String(body.targetDate) : yKstStr
    const paidDate = body.paidDate ? String(body.paidDate) : todayKstStr

    // ★ 핵심: KST 24시간 윈도우 — date(start_date, '+9 hours') = targetDate (KST)
    // 즉 start_date(UTC) 를 KST 로 변환했을 때 targetDate 와 정확히 같은 날
    const candidates = await db.prepare(`
      SELECT 
        s.user_id, 
        s.id as staking_id, 
        s.amount, 
        s.period_days, 
        s.period_months, 
        s.daily_rate, 
        s.start_date,
        s.end_date,
        s.status,
        date(s.start_date, '+9 hours') as start_date_kst,
        date(s.end_date, '+9 hours') as end_date_kst,
        u.email, u.name,
        (SELECT COUNT(*) FROM daily_rewards dr 
          WHERE dr.staking_id = s.id AND dr.reward_date = ?) as already_paid_for_target,
        (SELECT COUNT(*) FROM daily_rewards dr WHERE dr.staking_id = s.id) as total_paid_count
      FROM staking s
      LEFT JOIN users u ON u.id = s.user_id
      WHERE s.status = 'active'
        AND date(s.start_date, '+9 hours') = ?
        AND date(s.end_date, '+9 hours') >= ?
      ORDER BY s.id ASC
    `).bind(targetDate, targetDate, paidDate).all()

    const all = (candidates.results || []) as any[]
    const missing = all.filter(r => Number(r.already_paid_for_target) === 0)
    const already = all.filter(r => Number(r.already_paid_for_target) > 0)

    // dryRun: 분석만
    if (dryRun) {
      return c.json({
        success: true,
        dryRun: true,
        kst: { today: todayKstStr, yesterday: yKstStr, targetDate, paidDate },
        scope_query: `KST 24시간: start_date_kst = ${targetDate}`,
        candidates_total: all.length,
        already_paid: already.length,
        missing: missing.length,
        rule: '본인 룰: 승인 다음 영업일 첫 배당. 어제 매출자(평일/휴일 무관) → 오늘이 영업일이면 오늘 reward_date=어제 로 보충 1회 지급.',
        sample_missing: missing.slice(0, 50),
        sample_already_paid: already.slice(0, 10)
      })
    }

    // 실제 보충 — KST 영업일 룰: paidDate 가 영업일이어야 지급 (휴일이면 다음 영업일까지 누적)
    const paidDateObj = new Date(paidDate + 'T00:00:00Z')
    paidDateObj.setUTCHours(paidDateObj.getUTCHours() - 9)  // KST→UTC 변환 후 영업일 체크
    const { isBusinessDay: paidIsBiz, reason: paidReason } = isKoreanBusinessDay(paidDateObj)
    if (!paidIsBiz) {
      return c.json({
        success: false,
        dryRun: false,
        message: `paidDate(${paidDate}) 가 KST 영업일이 아닙니다 (${paidReason}). 다음 영업일에 다시 시도해 주세요.`
      })
    }

    const USD_TO_QKEY = 150
    let inserted = 0
    let totalQkey = 0
    const inserts: any[] = []

    for (const s of missing) {
      const dailyRate = (s.daily_rate as number) || getDailyRate(s.amount as number)
      const usdAmount = (s.amount as number) * dailyRate
      const qkeyAmount = Math.round(usdAmount * USD_TO_QKEY)
      const periodDays = (s.period_days as number) || ((s.period_months as number) * 30)
      if (Number(s.total_paid_count) >= periodDays) continue

      // 1) daily_rewards 본인 배당 — reward_date = targetDate(어제 KST), paid_date = paidDate(오늘 KST)
      await db.prepare(`
        INSERT INTO daily_rewards (user_id, staking_id, usdt_amount, reward_date, paid_date)
        VALUES (?, ?, ?, ?, ?)
      `).bind(s.user_id, s.staking_id, qkeyAmount, targetDate, paidDate).run()

      // 2) 잔액 반영
      await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`)
        .bind(qkeyAmount, s.user_id).run()

      // 3) 거래내역 기록 — EXISTS 가드 (user_id, type='daily_qkey', amount, KST date) 중복 INSERT 차단
      const newCount = Number(s.total_paid_count) + 1
      const dqExists = await db.prepare(`
        SELECT id FROM transactions
        WHERE user_id = ? AND type = 'daily_qkey' AND coin_type = 'QKEY'
          AND amount = ?
          AND date(created_at, '+9 hours') = ?
        LIMIT 1
      `).bind(s.user_id, qkeyAmount, paidDate).first()
      if (!dqExists) {
        await db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description)
          VALUES (?, 'daily_qkey', 'QKEY', ?, ?)
        `).bind(s.user_id, qkeyAmount,
          `[KST 24h 보충] Daily ${qkeyAmount.toLocaleString()} QKEY (${(dailyRate*100).toFixed(1)}%, ${newCount}/${periodDays}d, KST매출일 ${targetDate} 지급일 ${paidDate})`).run()
      }

      inserted++
      totalQkey += qkeyAmount
      inserts.push({ user_id: s.user_id, staking_id: s.staking_id, qkey: qkeyAmount, email: s.email, name: s.name })

      // 4) L1 매칭 (20%)
      try {
        const lvl1 = await db.prepare(`SELECT referrer_id FROM users WHERE id = ?`).bind(s.user_id).first() as any
        if (lvl1?.referrer_id) {
          const l1Active = await db.prepare(`
            SELECT id FROM staking 
            WHERE user_id = ? AND status = 'active'
              AND date(start_date, '+9 hours') <= ? AND date(end_date, '+9 hours') >= ?
            LIMIT 1
          `).bind(lvl1.referrer_id, targetDate, targetDate).first()
          if (l1Active) {
            const l1Exists = await db.prepare(`
              SELECT COUNT(*) as count FROM referral_rewards
              WHERE referrer_id = ? AND referee_id = ? AND level = 1 AND reward_date = ?
            `).bind(lvl1.referrer_id, s.user_id, targetDate).first() as any
            if (Number(l1Exists?.count || 0) === 0) {
              const l1Reward = Math.round(qkeyAmount * 0.20)
              await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`)
                .bind(l1Reward, lvl1.referrer_id).run()
              await db.prepare(`
                INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date)
                VALUES (?, ?, 1, ?, ?, ?, ?)
              `).bind(lvl1.referrer_id, s.user_id, qkeyAmount, l1Reward, targetDate, paidDate).run()
              // EXISTS 가드 — (referrer, type='referral_reward', amount, KST date) 중복 INSERT 차단
              const l1TxExists = await db.prepare(`
                SELECT id FROM transactions
                WHERE user_id = ? AND type = 'referral_reward' AND coin_type = 'QKEY'
                  AND amount = ?
                  AND date(created_at, '+9 hours') = ?
                LIMIT 1
              `).bind(lvl1.referrer_id, l1Reward, paidDate).first()
              if (!l1TxExists) {
                await db.prepare(`
                  INSERT INTO transactions (user_id, type, coin_type, amount, description)
                  VALUES (?, 'referral_reward', 'QKEY', ?, ?)
                `).bind(lvl1.referrer_id, l1Reward,
                  `[KST 24h 보충] Level 1 referral bonus (${qkeyAmount.toLocaleString()} QKEY x 20%, KST매출일 ${targetDate} 지급일 ${paidDate})`).run()
              }

              // 5) L2 매칭 (10%)
              const lvl2 = await db.prepare(`SELECT referrer_id FROM users WHERE id = ?`).bind(lvl1.referrer_id).first() as any
              if (lvl2?.referrer_id) {
                const l2Active = await db.prepare(`
                  SELECT id FROM staking 
                  WHERE user_id = ? AND status = 'active'
                    AND date(start_date, '+9 hours') <= ? AND date(end_date, '+9 hours') >= ?
                  LIMIT 1
                `).bind(lvl2.referrer_id, targetDate, targetDate).first()
                if (l2Active) {
                  const l2Exists = await db.prepare(`
                    SELECT COUNT(*) as count FROM referral_rewards
                    WHERE referrer_id = ? AND referee_id = ? AND level = 2 AND reward_date = ?
                  `).bind(lvl2.referrer_id, s.user_id, targetDate).first() as any
                  if (Number(l2Exists?.count || 0) === 0) {
                    const l2Reward = Math.round(qkeyAmount * 0.10)
                    await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`)
                      .bind(l2Reward, lvl2.referrer_id).run()
                    await db.prepare(`
                      INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date)
                      VALUES (?, ?, 2, ?, ?, ?, ?)
                    `).bind(lvl2.referrer_id, s.user_id, qkeyAmount, l2Reward, targetDate, paidDate).run()
                    // EXISTS 가드 — (referrer, type='referral_reward', amount, KST date) 중복 INSERT 차단
                    const l2TxExists = await db.prepare(`
                      SELECT id FROM transactions
                      WHERE user_id = ? AND type = 'referral_reward' AND coin_type = 'QKEY'
                        AND amount = ?
                        AND date(created_at, '+9 hours') = ?
                      LIMIT 1
                    `).bind(lvl2.referrer_id, l2Reward, paidDate).first()
                    if (!l2TxExists) {
                      await db.prepare(`
                        INSERT INTO transactions (user_id, type, coin_type, amount, description)
                        VALUES (?, 'referral_reward', 'QKEY', ?, ?)
                      `).bind(lvl2.referrer_id, l2Reward,
                        `[KST 24h 보충] Level 2 referral bonus (${qkeyAmount.toLocaleString()} QKEY x 10%, KST매출일 ${targetDate} 지급일 ${paidDate})`).run()
                    }
                  }
                }
              }
            }
          }
        }
      } catch (e: any) {
        console.error('matching reward error:', e?.message || e)
      }
    }

    return c.json({
      success: true,
      dryRun: false,
      kst: { today: todayKstStr, yesterday: yKstStr, targetDate, paidDate },
      candidates_total: all.length,
      already_paid: already.length,
      inserted_self_daily: inserted,
      total_qkey_paid: totalQkey,
      inserts
    })
  } catch (error: any) {
    console.error('check-missing-by-kst error:', error)
    return c.json({ error: String(error?.message || error) }, 500)
  }
})

// ★★ 사장님 2026-05-07 지시 ★★
// "영국시간(UTC) 기준으로 reward_date 가 다른 날로 찍혀서 같은 KST 영업일 1회 지급이 2회로 중복 보이는 건 정리"
// 분석 로직:
//  1) daily_rewards 의 created_at(UTC 저장) 을 KST 로 변환 → kst_date
//  2) 같은 (user_id, staking_id) 에 대해 다른 reward_date 가 KST 기준 같은 영업일에 들어있으면 중복으로 식별
//  3) dryRun=true 이면 분석만, false 이면 가장 최근(id 큰) 것만 남기고 나머지는 삭제 + 잔액 차감 + transactions 회수 로그 기록
app.post('/api/admin/rewards/dedupe-kst-utc', async (c) => {
  try {
    const db = c.env.DB
    const body = await c.req.json().catch(() => ({}))
    const dryRun = body.dryRun !== false  // 기본값 true (안전)
    const targetUserId = body.userId ? Number(body.userId) : null
    const fromDate = body.fromDate ? String(body.fromDate) : '2026-04-01'
    const toDate = body.toDate ? String(body.toDate) : '2099-12-31'

    // 모든 daily_rewards 조회 (created_at + reward_date 둘 다)
    // SQLite datetime(created_at, '+9 hours') 로 KST 변환, KST 날짜만 추출
    const sql = `
      SELECT id, user_id, staking_id, usdt_amount, reward_date, paid_date, created_at,
             date(datetime(created_at, '+9 hours')) as kst_created_date
      FROM daily_rewards
      WHERE reward_date BETWEEN ? AND ?
      ${targetUserId ? 'AND user_id = ?' : ''}
      ORDER BY user_id, staking_id, kst_created_date, id
    `
    const args: any[] = [fromDate, toDate]
    if (targetUserId) args.push(targetUserId)
    const rows = await db.prepare(sql).bind(...args).all()
    const allRows = (rows.results || []) as any[]

    // KST 기준 중복 그룹핑: (user_id + staking_id + kst_created_date) 가 같으면 중복
    const groups: Record<string, any[]> = {}
    for (const r of allRows) {
      const key = `${r.user_id}|${r.staking_id}|${r.kst_created_date}`
      if (!groups[key]) groups[key] = []
      groups[key].push(r)
    }

    // 중복 그룹 (2개 이상) 만 추출
    const duplicateGroups: any[] = []
    let totalDuplicateRows = 0
    let totalDuplicateAmount = 0
    for (const key in groups) {
      const grp = groups[key]
      if (grp.length < 2) continue
      // reward_date 가 서로 다르면 UTC/KST 경계 문제로 의심
      const distinctRewardDates = Array.from(new Set(grp.map(r => r.reward_date)))
      const isUtcBoundaryIssue = distinctRewardDates.length > 1
      const keepRow = grp.reduce((a, b) => (b.id > a.id ? b : a))  // id 가장 큰 것 유지
      const removeRows = grp.filter(r => r.id !== keepRow.id)
      const removeAmount = removeRows.reduce((sum, r) => sum + Number(r.usdt_amount || 0), 0)
      totalDuplicateRows += removeRows.length
      totalDuplicateAmount += removeAmount
      duplicateGroups.push({
        key,
        user_id: grp[0].user_id,
        staking_id: grp[0].staking_id,
        kst_created_date: grp[0].kst_created_date,
        distinct_reward_dates: distinctRewardDates,
        is_utc_boundary_issue: isUtcBoundaryIssue,
        rows_total: grp.length,
        keep_row_id: keepRow.id,
        keep_row: keepRow,
        remove_rows: removeRows,
        remove_amount: removeAmount
      })
    }

    if (dryRun) {
      return c.json({
        success: true,
        dryRun: true,
        scope: { fromDate, toDate, userId: targetUserId },
        analyzed_rows: allRows.length,
        duplicate_groups: duplicateGroups.length,
        rows_to_remove: totalDuplicateRows,
        amount_to_subtract: totalDuplicateAmount,
        groups: duplicateGroups,
        note: 'dryRun=true 분석만 수행. 실제 삭제는 dryRun:false 로 다시 호출하세요.'
      })
    }

    // 실제 삭제 + 잔액 차감 + transactions 회수 로그
    let deletedCount = 0
    let balanceSubtracted = 0
    const txLogs: any[] = []
    for (const grp of duplicateGroups) {
      for (const r of grp.remove_rows) {
        // 1) daily_rewards 삭제
        const del = await db.prepare(`DELETE FROM daily_rewards WHERE id = ?`).bind(r.id).run()
        const removed = (del.meta?.changes || 0)
        deletedCount += removed
        if (removed > 0) {
          // 2) 잔액 차감
          await db.prepare(`UPDATE users SET qkey_balance = qkey_balance - ? WHERE id = ?`)
            .bind(Number(r.usdt_amount || 0), r.user_id).run()
          balanceSubtracted += Number(r.usdt_amount || 0)
          // 3) transactions 회수 로그
          const desc = `[KST/UTC 중복 정리] daily_reward_id=${r.id} reward_date=${r.reward_date} kst_date=${r.kst_created_date} amount=-${r.usdt_amount}`
          const ins = await db.prepare(`
            INSERT INTO transactions (user_id, type, coin_type, amount, description)
            VALUES (?, 'daily_reward_rollback', 'QKEY', ?, ?)
          `).bind(r.user_id, -Number(r.usdt_amount || 0), desc).run()
          txLogs.push({ user_id: r.user_id, deleted_id: r.id, tx_id: (ins.meta as any)?.last_row_id })
        }
      }
    }

    return c.json({
      success: true,
      dryRun: false,
      scope: { fromDate, toDate, userId: targetUserId },
      duplicate_groups: duplicateGroups.length,
      deleted_rows: deletedCount,
      balance_subtracted: balanceSubtracted,
      tx_logs: txLogs,
      groups: duplicateGroups
    })
  } catch (error) {
    console.error('dedupe-kst-utc error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// 어드민: 특정 날짜의 일일 배당 + 1대/2대 매칭수당 전체 회수 (잘못 지급된 휴일 배당 롤백용)
//   - daily_rewards 의 해당 reward_date 행 전부 삭제
//   - users.qkey_balance 에서 해당 금액 차감
//   - referral_rewards 의 해당 reward_date 행 전부 삭제
//   - users.qkey_balance 에서 매칭수당 금액 차감
//   - transactions 에 회수 로그 INSERT (type='daily_reward_rollback' / 'referral_reward_rollback')
app.post('/api/admin/rewards/rollback-daily', async (c) => {
  try {
    const db = c.env.DB
    const body = await c.req.json().catch(() => ({}))
    const targetDate = (body && body.date) ? String(body.date) : ''
    if (!targetDate || !/^\d{4}-\d{2}-\d{2}$/.test(targetDate)) {
      return c.json({ error: 'date 파라미터(YYYY-MM-DD)가 필요합니다' }, 400)
    }

    // 1) 본인 일일 배당 회수
    const dailyRows = await db.prepare(
      `SELECT id, user_id, staking_id, usdt_amount FROM daily_rewards WHERE reward_date = ?`
    ).bind(targetDate).all()

    let dailyCount = 0
    let dailyQkeyTotal = 0
    for (const r of (dailyRows.results || [])) {
      const amt = Number(r.usdt_amount) || 0
      try {
        await db.prepare(`UPDATE users SET qkey_balance = qkey_balance - ? WHERE id = ?`).bind(amt, r.user_id).run()
        await db.prepare(`DELETE FROM daily_rewards WHERE id = ?`).bind(r.id).run()
        await db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description)
          VALUES (?, 'daily_reward_rollback', 'QKEY', ?, ?)
        `).bind(r.user_id, -amt, `[휴일 회수] ${targetDate} 일일배당 회수 (-${amt.toLocaleString()} QKEY, staking #${r.staking_id})`).run()
        dailyCount++
        dailyQkeyTotal += amt
      } catch (e) {
        console.error('daily rollback row error:', e)
      }
    }

    // 2) 매칭수당(1대/2대) 회수
    const refRows = await db.prepare(
      `SELECT id, referrer_id, referee_id, level, reward_amount FROM referral_rewards WHERE reward_date = ?`
    ).bind(targetDate).all()

    let refCount = 0
    let refQkeyTotal = 0
    for (const r of (refRows.results || [])) {
      const amt = Number(r.reward_amount) || 0
      try {
        await db.prepare(`UPDATE users SET qkey_balance = qkey_balance - ? WHERE id = ?`).bind(amt, r.referrer_id).run()
        await db.prepare(`DELETE FROM referral_rewards WHERE id = ?`).bind(r.id).run()
        await db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description)
          VALUES (?, 'referral_reward_rollback', 'QKEY', ?, ?)
        `).bind(r.referrer_id, -amt, `[휴일 회수] ${targetDate} Level ${r.level} 매칭수당 회수 (-${amt.toLocaleString()} QKEY, referee #${r.referee_id})`).run()
        refCount++
        refQkeyTotal += amt
      } catch (e) {
        console.error('referral rollback row error:', e)
      }
    }

    return c.json({
      success: true,
      message: `${targetDate} 배당 회수 완료. 본인 ${dailyCount}건(-${dailyQkeyTotal.toLocaleString()} QKEY), 매칭 ${refCount}건(-${refQkeyTotal.toLocaleString()} QKEY)`,
      date: targetDate,
      dailyRolledBack: dailyCount,
      dailyQkeyTotal,
      referralRolledBack: refCount,
      referralQkeyTotal: refQkeyTotal,
      grandTotalQkey: dailyQkeyTotal + refQkeyTotal
    })
  } catch (error) {
    console.error('Rollback daily error:', error)
    return c.json({ error: '배당 회수 처리 중 오류가 발생했습니다' }, 500)
  }
})

// 어드민: transactions.created_at 기준 기간 회수 (휴일/주말에 잘못 찍힌 daily_qkey + referral_reward 회수)
//   - direct_referral 은 즉시지급 정책이므로 회수 대상에서 제외
//   - daily_rewards / referral_rewards 테이블 행은 reward_date 기준이라 별개로 두고,
//     여기서는 transactions 행 자체를 음수 보전 + 잔액 차감만 처리한다.
//   - 사용 예: { "fromDate": "2026-05-01", "toDate": "2026-05-03" }
app.post('/api/admin/rewards/rollback-tx-range', async (c) => {
  try {
    const db = c.env.DB
    const body = await c.req.json().catch(() => ({}))
    const fromDate = body && body.fromDate ? String(body.fromDate) : ''
    const toDate = body && body.toDate ? String(body.toDate) : ''
    if (!/^\d{4}-\d{2}-\d{2}$/.test(fromDate) || !/^\d{4}-\d{2}-\d{2}$/.test(toDate)) {
      return c.json({ error: 'fromDate/toDate (YYYY-MM-DD) 필요' }, 400)
    }

    // 회수 대상: daily_qkey + referral_reward (direct_referral 제외)
    // 단, 이미 회수 로그(daily_reward_rollback / referral_reward_rollback)가 있는 사용자/금액은
    // 한 번 더 빼면 마이너스가 되므로, 같은 기간 회수 로그가 있으면 net 양수만 회수.
    const rows = await db.prepare(
      `SELECT id, user_id, type, amount, description, created_at
       FROM transactions
       WHERE date(created_at, '+9 hours') BETWEEN ? AND ?
         AND type IN ('daily_qkey','referral_reward')
       ORDER BY id`
    ).bind(fromDate, toDate).all()

    // 같은 기간에 이미 발생한 롤백 합계 (사용자별)
    const existingRollbacks = await db.prepare(
      `SELECT user_id, SUM(amount) as rolled
       FROM transactions
       WHERE date(created_at, '+9 hours') BETWEEN ? AND ?
         AND type IN ('daily_reward_rollback','referral_reward_rollback')
       GROUP BY user_id`
    ).bind(fromDate, toDate).all()
    const rolledMap: Record<string, number> = {}
    for (const r of (existingRollbacks.results || [])) {
      rolledMap[String(r.user_id)] = Number(r.rolled) || 0
    }

    // 회수해야 할 사용자별 amount 합계 (양수)
    const toRollback: Record<string, { daily: number; ref: number; ids: number[] }> = {}
    for (const r of (rows.results || [])) {
      const uid = String(r.user_id)
      if (!toRollback[uid]) toRollback[uid] = { daily: 0, ref: 0, ids: [] }
      const amt = Number(r.amount) || 0
      if (r.type === 'daily_qkey') toRollback[uid].daily += amt
      else if (r.type === 'referral_reward') toRollback[uid].ref += amt
      toRollback[uid].ids.push(Number(r.id))
    }

    let processedUsers = 0
    let totalDailyQkey = 0
    let totalRefQkey = 0
    const details: any[] = []

    for (const uid in toRollback) {
      const d = toRollback[uid]
      const grossPaid = d.daily + d.ref
      const alreadyRolled = -1 * (rolledMap[uid] || 0) // 롤백은 음수로 저장되므로 부호 반전 (양수=이미 회수된 금액)
      const netToRollback = Math.max(0, grossPaid - alreadyRolled)
      if (netToRollback <= 0) {
        details.push({ user_id: Number(uid), grossPaid, alreadyRolled, netToRollback, skipped: 'already_rolled' })
        continue
      }
      // daily / ref 비율로 분배
      const ratio = grossPaid > 0 ? d.daily / grossPaid : 0
      const dailyPart = Math.round(netToRollback * ratio)
      const refPart = netToRollback - dailyPart
      try {
        await db.prepare(`UPDATE users SET qkey_balance = qkey_balance - ? WHERE id = ?`).bind(netToRollback, Number(uid)).run()
        if (dailyPart > 0) {
          await db.prepare(`
            INSERT INTO transactions (user_id, type, coin_type, amount, description)
            VALUES (?, 'daily_reward_rollback', 'QKEY', ?, ?)
          `).bind(Number(uid), -dailyPart, `[휴일 회수] ${fromDate}~${toDate} 일일배당 회수 (-${dailyPart.toLocaleString()} QKEY)`).run()
          totalDailyQkey += dailyPart
        }
        if (refPart > 0) {
          await db.prepare(`
            INSERT INTO transactions (user_id, type, coin_type, amount, description)
            VALUES (?, 'referral_reward_rollback', 'QKEY', ?, ?)
          `).bind(Number(uid), -refPart, `[휴일 회수] ${fromDate}~${toDate} 매칭수당 회수 (-${refPart.toLocaleString()} QKEY)`).run()
          totalRefQkey += refPart
        }
        processedUsers++
        details.push({ user_id: Number(uid), grossPaid, alreadyRolled, netToRollback, dailyPart, refPart })
      } catch (e) {
        console.error('rollback-tx-range error for user', uid, e)
      }
    }

    return c.json({
      success: true,
      fromDate,
      toDate,
      processedUsers,
      totalDailyQkey,
      totalRefQkey,
      grandTotalQkey: totalDailyQkey + totalRefQkey,
      details
    })
  } catch (error) {
    console.error('rollback-tx-range error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// 어드민: 기간 내 사용자별 net 정합성 자동 보정
//   - paid (daily_qkey + referral_reward) 합계 vs rollback 합계 비교
//   - net > 0 (미회수): qkey_balance 추가 차감 + 음수 트랜잭션 INSERT
//   - net < 0 (과회수): qkey_balance 복구 가산 + 양수 트랜잭션 INSERT
app.post('/api/admin/rewards/reconcile-tx-range', async (c) => {
  try {
    const db = c.env.DB
    const body = await c.req.json().catch(() => ({}))
    const fromDate = body && body.fromDate ? String(body.fromDate) : ''
    const toDate = body && body.toDate ? String(body.toDate) : ''
    if (!/^\d{4}-\d{2}-\d{2}$/.test(fromDate) || !/^\d{4}-\d{2}-\d{2}$/.test(toDate)) {
      return c.json({ error: 'fromDate/toDate (YYYY-MM-DD) 필요' }, 400)
    }

    const paidRows = await db.prepare(
      `SELECT user_id, COALESCE(SUM(amount), 0) as total
       FROM transactions
       WHERE date(created_at, '+9 hours') BETWEEN ? AND ?
         AND type IN ('daily_qkey','referral_reward')
       GROUP BY user_id`
    ).bind(fromDate, toDate).all()

    const rolledRows = await db.prepare(
      `SELECT user_id, COALESCE(SUM(amount), 0) as total
       FROM transactions
       WHERE date(created_at, '+9 hours') BETWEEN ? AND ?
         AND type IN ('daily_reward_rollback','referral_reward_rollback','rollback_restore')
       GROUP BY user_id`
    ).bind(fromDate, toDate).all()

    const paidMap: Record<string, number> = {}
    for (const r of (paidRows.results || [])) paidMap[String(r.user_id)] = Number(r.total) || 0
    const rolledMap: Record<string, number> = {}
    for (const r of (rolledRows.results || [])) rolledMap[String(r.user_id)] = Number(r.total) || 0

    const allUids = new Set([...Object.keys(paidMap), ...Object.keys(rolledMap)])
    const details: any[] = []
    let underAdjustedCount = 0
    let overAdjustedCount = 0
    let totalUnderQkey = 0
    let totalOverQkey = 0

    for (const uid of allUids) {
      const paid = paidMap[uid] || 0
      const rolled = rolledMap[uid] || 0
      const net = paid + rolled
      if (net === 0) {
        details.push({ user_id: Number(uid), paid, rolled, net, action: 'ok' })
        continue
      }
      try {
        if (net > 0) {
          await db.prepare(`UPDATE users SET qkey_balance = qkey_balance - ? WHERE id = ?`).bind(net, Number(uid)).run()
          await db.prepare(`
            INSERT INTO transactions (user_id, type, coin_type, amount, description)
            VALUES (?, 'daily_reward_rollback', 'QKEY', ?, ?)
          `).bind(Number(uid), -net, `[정합성 보정] ${fromDate}~${toDate} 잔여 미회수 차감 (-${net.toLocaleString()} QKEY)`).run()
          underAdjustedCount++
          totalUnderQkey += net
          details.push({ user_id: Number(uid), paid, rolled, net, action: 'deducted', amount: net })
        } else {
          const restoreAmt = -net
          await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(restoreAmt, Number(uid)).run()
          await db.prepare(`
            INSERT INTO transactions (user_id, type, coin_type, amount, description)
            VALUES (?, 'rollback_restore', 'QKEY', ?, ?)
          `).bind(Number(uid), restoreAmt, `[정합성 보정] ${fromDate}~${toDate} 과회수 복구 (+${restoreAmt.toLocaleString()} QKEY)`).run()
          overAdjustedCount++
          totalOverQkey += restoreAmt
          details.push({ user_id: Number(uid), paid, rolled, net, action: 'restored', amount: restoreAmt })
        }
      } catch (e) {
        console.error('reconcile error for user', uid, e)
        details.push({ user_id: Number(uid), paid, rolled, net, action: 'error', error: String(e) })
      }
    }

    return c.json({
      success: true,
      fromDate,
      toDate,
      underAdjustedCount,
      totalUnderQkey,
      overAdjustedCount,
      totalOverQkey,
      netDelta: totalUnderQkey - totalOverQkey,
      details
    })
  } catch (error) {
    console.error('reconcile-tx-range error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// 어드민: B-3 강화판 — 휴일 양수 행 100% 삭제 + 동일 금액 음수 매칭 삭제 + 잔여 음수 통합
//   1) positiveDates 의 양수 행(daily_qkey, referral_reward)을 사용자별로 모두 삭제
//   2) 사용자별 삭제된 양수 합계만큼, negativeDates 의 음수 회수 행에서 동일 금액으로 매칭하여 삭제
//      - 동일 금액 매칭 우선 (1:1)
//      - 동일 금액으로 못 채우면, 가장 큰 음수 행부터 부분 매칭 (전체 삭제 또는 일부 삭제 + 차액은 신규 보정 행)
//   3) 페어 매칭 후 남은 음수 잔여분은 사용자당 단일 [잔액 보정] 행 1개로 통합 (description만 변경, 금액 합산)
//   ★ direct_referral 은 type 필터에서 완전 제외 → 직접판매 수당은 절대 건드리지 않음
//   ★ dryRun=true 시 미리보기만
app.post('/api/admin/rewards/pair-purge-tx', async (c) => {
  try {
    const db = c.env.DB
    const body = await c.req.json().catch(() => ({}))
    const positiveDates: string[] = Array.isArray(body?.positiveDates) ? body.positiveDates : []
    const negativeDates: string[] = Array.isArray(body?.negativeDates) ? body.negativeDates : []
    const dryRun: boolean = body?.dryRun === true
    const renameOrphans: boolean = body?.renameOrphans !== false // 기본 true
    if (positiveDates.length === 0 || negativeDates.length === 0) {
      return c.json({ error: 'positiveDates, negativeDates 배열이 모두 필요합니다' }, 400)
    }

    // 1. 양수 후보: positiveDates KST 기준, daily_qkey + referral_reward (양수만)
    const posDateClause = positiveDates.map(() => `substr(datetime(created_at,'+9 hours'),1,10) = ?`).join(' OR ')
    const positives = await db.prepare(`
      SELECT id, user_id, type, amount, description, created_at
      FROM transactions
      WHERE type IN ('daily_qkey','referral_reward')
        AND coin_type = 'QKEY'
        AND amount > 0
        AND (${posDateClause})
      ORDER BY user_id, amount DESC, id ASC
    `).bind(...positiveDates).all()

    // 2. 회수/복구 후보: negativeDates KST 기준
    //    - daily_reward_rollback / referral_reward_rollback (음수) → 회수 행
    //    - rollback_restore (양수) → 과회수 복구 행 (이것도 잔액 차감 매칭 후보로 사용)
    //    잔액 변화 0 보장을 위해 양수+음수 모두 후보로 잡음.
    //    "음수 매칭" 처리 시 절댓값 기준이 아니라 amount 그대로 사용:
    //      양수 삭제로 줄어드는 잔액(posSum) = 회수(음수)+복구(양수) 합산해서 동일 부호로 상쇄해야 함
    //    → 실제 의미: 양수합 만큼 "(-회수-복구)"의 합이 -posSum 이 되도록 매칭 삭제하면 잔액 변화 0
    //    구현 단순화: 후보 행 amount 합 = -posSum 이 되도록 매칭하여 삭제
    const negDateClause = negativeDates.map(() => `substr(datetime(created_at,'+9 hours'),1,10) = ?`).join(' OR ')
    const negatives = await db.prepare(`
      SELECT id, user_id, type, amount, description, created_at
      FROM transactions
      WHERE type IN ('daily_reward_rollback','referral_reward_rollback','rollback_restore')
        AND coin_type = 'QKEY'
        AND (${negDateClause})
      ORDER BY user_id, amount ASC, id ASC
    `).bind(...negativeDates).all()

    // 3. 사용자별로 양수/음수 그룹화 (★ direct_referral 은 type 필터로 이미 제외됨)
    const posByUser: Record<number, any[]> = {}
    const negByUser: Record<number, any[]> = {}
    for (const r of (positives.results || []) as any[]) {
      const u = Number(r.user_id)
      if (!posByUser[u]) posByUser[u] = []
      posByUser[u].push(r)
    }
    for (const r of (negatives.results || []) as any[]) {
      const u = Number(r.user_id)
      if (!negByUser[u]) negByUser[u] = []
      negByUser[u].push(r)
    }

    // 4. B-3 강화판 (A안) — 사용자별 처리
    //    (1) 양수 행(5/1·5/3 daily_qkey + referral_reward) 100% 삭제 대상
    //    (2) 삭제로 줄어드는 잔액(posSum)을 5/4 회수/복구 후보 행들의 amount 합산으로 정확히 -posSum 만큼 매칭 삭제
    //        - 후보 amount 합 = -posSum 이 되도록 (음수 회수 + 양수 복구 모두 사용)
    //        - 그리디 알고리즘: |posSum + sumDeleted| 가 0 에 수렴하도록 반복 선택
    //    (3) 잔여 후보(삭제 안 된 행)는 사용자당 단일 [잔액 보정] 행 1개로 통합 (description + amount 합산)
    //    ★ 잔액 변화 0 보장: posSum + (삭제된 후보 amount 합) = 0
    //    ★ direct_referral 절대 미손상 (type 필터 제외)
    const allUserIds = new Set<number>([...Object.keys(posByUser).map(Number), ...Object.keys(negByUser).map(Number)])
    const userPlan: any[] = []   // 계획 수립용
    const userSummary: any[] = []

    for (const uid of Array.from(allUserIds)) {
      const posList = (posByUser[uid] || []).slice()
      const candList = (negByUser[uid] || []).slice() // 회수(-) + 복구(+) 후보
      const posSum = posList.reduce((s:number,p:any)=>s+Number(p.amount), 0)        // 양수 합 (삭제될 +)
      const candSumRaw = candList.reduce((s:number,c:any)=>s+Number(c.amount), 0)   // 후보 amount 합 (음수+양수 그대로)

      // 목표: 후보들 중에서 amount 합 = -posSum 이 되도록 부분집합을 골라 삭제
      //   현재 잔액 영향: 양수 행 삭제로 -posSum, 후보 행 삭제로 -(amount 합)
      //   잔액 변화 = -posSum - (삭제된 후보 amount 합) → 0 이려면 (삭제된 후보 amount 합) = -posSum
      //   즉 sumDeletedCandidates 가 -posSum 이 되어야 함
      const target = -posSum
      const candToDelete: any[] = []
      const candToKeep: any[] = []
      const usedIds = new Set<number>()
      let remaining = target  // 남은 목표값 (점차 0 으로 수렴)

      // 1차: 정확 매칭 — 양수 행 각각에 대해 amount = -p.amount 인 후보 우선 (= 음수 회수 행 절댓값 동일)
      const candByAmt: Record<string, any[]> = {}
      for (const c of candList) {
        const k = String(Math.round(Number(c.amount)))
        if (!candByAmt[k]) candByAmt[k] = []
        candByAmt[k].push(c)
      }
      for (const p of posList) {
        const need = -Number(p.amount)
        const k = String(Math.round(need))
        const bucket = candByAmt[k] || []
        const c = bucket.shift()
        if (c && !usedIds.has(Number(c.id))) {
          usedIds.add(Number(c.id))
          candToDelete.push(c)
          remaining -= Number(c.amount)
        }
      }

      // 2차: 그리디 — 남은 후보 중에서 |remaining - amount| 가 가장 작아지는 행을 반복 선택
      //   remaining 이 0 에 수렴하도록 (개선 없으면 즉시 종료)
      const epsilon = 0.5
      let safety = 0
      while (Math.abs(remaining) > epsilon && safety < 1000) {
        safety++
        let bestIdx = -1
        let bestAfterAbs = Math.abs(remaining)
        for (let i = 0; i < candList.length; i++) {
          const c = candList[i]
          if (usedIds.has(Number(c.id))) continue
          const after = remaining - Number(c.amount)
          const afterAbs = Math.abs(after)
          if (afterAbs < bestAfterAbs - epsilon) {
            bestAfterAbs = afterAbs
            bestIdx = i
          }
        }
        if (bestIdx < 0) break
        const c = candList[bestIdx]
        usedIds.add(Number(c.id))
        candToDelete.push(c)
        remaining -= Number(c.amount)
      }

      // 3차 (A2안 핵심): 잔여가 여전히 0이 아니면 — 잔여 후보 중 amount 부호가 remaining 과 같은 행 1건을 찾아 분할
      //   분할 split 행 1건 (amount = remaining) 을 신규 INSERT 후 즉시 삭제로 처리
      //   원래 후보 행은 amount = (원래 amount - remaining) 으로 UPDATE → orphan(통합 대상)에 잔류
      //   ※ remaining 부호와 동일한 부호의 후보 행이 있어야 분할 가능 (절댓값이 |remaining| 이상)
      let splitPlan: any = null  // {srcId, srcOriginalAmount, srcNewAmount, splitAmount}
      if (Math.abs(remaining) > epsilon) {
        const need = remaining // 부호 포함 — 이만큼 더 삭제해야 변화 0
        let bestSplitIdx = -1
        let bestSplitAbsRemainder = Infinity
        for (let i = 0; i < candList.length; i++) {
          const c = candList[i]
          if (usedIds.has(Number(c.id))) continue
          const a = Number(c.amount)
          // 분할 가능 조건: 부호가 같고, |a| > |need| (잔여가 남아야 통합 가능, 또는 같으면 분할 불필요였음)
          if ((a > 0 && need > 0 && a > need + epsilon) || (a < 0 && need < 0 && a < need - epsilon)) {
            const remainderAfter = a - need
            const absRem = Math.abs(remainderAfter)
            if (absRem < bestSplitAbsRemainder) {
              bestSplitAbsRemainder = absRem
              bestSplitIdx = i
            }
          }
        }
        if (bestSplitIdx >= 0) {
          const src = candList[bestSplitIdx]
          const srcAmt = Number(src.amount)
          splitPlan = {
            srcId: Number(src.id),
            srcOriginalAmount: srcAmt,
            srcNewAmount: srcAmt - need,   // 잔여로 남길 부분
            splitAmount: need,             // 분할 후 즉시 삭제 처리할 가상 행 amount
            srcType: String(src.type),
            srcCreatedAt: String(src.created_at)
          }
          // src 행은 분할 후 잔여(orphan 통합 대상)에 들어감 — usedIds 에 넣지 않음
          remaining = 0
        }
      }

      // 잔여 후보 = 삭제되지 않은 후보 (분할된 src 행도 잔여에 포함됨, amount 는 srcNewAmount 로 간주)
      for (const c of candList) {
        if (usedIds.has(Number(c.id))) continue
        if (splitPlan && Number(c.id) === splitPlan.srcId) {
          // 분할된 행 — 잔여에는 srcNewAmount 로 포함됨
          candToKeep.push({ ...c, amount: splitPlan.srcNewAmount, _splitFrom: splitPlan.srcOriginalAmount })
        } else {
          candToKeep.push(c)
        }
      }
      const candDeleteAmtSum = candToDelete.reduce((s:number,c:any)=>s+Number(c.amount), 0) + (splitPlan ? splitPlan.splitAmount : 0)
      // 잔액 변화 = -posSum - candDeleteAmtSum  →  0 이어야 안전
      const balanceDeltaForUser = -posSum - candDeleteAmtSum
      // 잔여 후보 통합 (description 통합 + 금액 합산하여 1행만 남기고 나머지는 삭제)
      const orphanSum = candToKeep.reduce((s:number,c:any)=>s+Number(c.amount), 0)
      const consolidateMasterId = candToKeep.length > 0 ? Number(candToKeep[0].id) : null
      const consolidateDeleteIds = candToKeep.length > 1 ? candToKeep.slice(1).map((c:any)=>Number(c.id)) : []

      userPlan.push({
        user_id: uid,
        posIds: posList.map((p:any)=>Number(p.id)),
        negDeleteIds: candToDelete.map((c:any)=>Number(c.id)),
        splitPlan,
        consolidateMasterId,
        consolidateDeleteIds,
        orphanSum,
        balanceDeltaForUser
      })
      userSummary.push({
        user_id: uid,
        positive_count: posList.length,
        positive_sum: posSum,
        candidate_count: candList.length,
        candidate_sum_raw: candSumRaw,
        deleted_positive_count: posList.length,
        deleted_candidate_count: candToDelete.length,
        deleted_candidate_amount_sum: candDeleteAmtSum,
        split_applied: splitPlan ? true : false,
        split_amount: splitPlan ? splitPlan.splitAmount : 0,
        balance_delta: balanceDeltaForUser,
        orphan_consolidated_sum: orphanSum,
        orphan_consolidated_count_deleted: consolidateDeleteIds.length,
        orphan_master_id: consolidateMasterId
      })
    }

    // 잔액 변화 0 검증 (전체 합)
    const totalDelta = userSummary.reduce((s:number,u:any)=>s+u.balance_delta, 0)
    const usersWithDelta = userSummary.filter((u:any)=>Math.abs(u.balance_delta) > 0.5).map((u:any)=>({user_id:u.user_id, delta:u.balance_delta}))

    if (dryRun) {
      return c.json({
        success: true,
        dryRun: true,
        mode: 'B3-A2',
        positiveDates,
        negativeDates,
        totalPositiveRows: (positives.results || []).length,
        totalNegativeRows: (negatives.results || []).length,
        userCount: userSummary.length,
        totalBalanceDelta: totalDelta,
        usersWithBalanceDelta: usersWithDelta,
        plannedPositiveDeletes: userPlan.reduce((s:number,p:any)=>s+p.posIds.length, 0),
        plannedNegativeMatchedDeletes: userPlan.reduce((s:number,p:any)=>s+p.negDeleteIds.length, 0),
        plannedConsolidationDeletes: userPlan.reduce((s:number,p:any)=>s+p.consolidateDeleteIds.length, 0),
        plannedConsolidationMasters: userPlan.filter((p:any)=>p.consolidateMasterId !== null).length,
        plannedSplits: userPlan.filter((p:any)=>p.splitPlan).length,
        perUserSummary: userSummary
      })
    }

    // ★ 실삭제 전 마지막 안전장치: 잔액 변화가 0이 아니면 중단
    if (Math.abs(totalDelta) > 0.5 || usersWithDelta.length > 0) {
      return c.json({
        success: false,
        error: '잔액 변화 0 검증 실패 — 실삭제 중단됨',
        totalBalanceDelta: totalDelta,
        usersWithBalanceDelta: usersWithDelta,
        perUserSummary: userSummary
      }, 400)
    }

    // 5. 실삭제 수행
    const CHUNK = 50
    let deletedPositives = 0
    let deletedNegMatched = 0
    let consolidatedDeleted = 0
    let consolidatedUpdated = 0
    let splitApplied = 0

    for (const plan of userPlan) {
      // (a) 양수 행 삭제
      if (plan.posIds.length > 0) {
        for (let i = 0; i < plan.posIds.length; i += CHUNK) {
          const chunk = plan.posIds.slice(i, i + CHUNK)
          const ph = chunk.map(() => '?').join(',')
          const r = await db.prepare(`DELETE FROM transactions WHERE id IN (${ph})`).bind(...chunk).run()
          deletedPositives += (r.meta?.changes || 0)
        }
      }
      // (b) 매칭된 음수/복구 후보 삭제
      if (plan.negDeleteIds.length > 0) {
        for (let i = 0; i < plan.negDeleteIds.length; i += CHUNK) {
          const chunk = plan.negDeleteIds.slice(i, i + CHUNK)
          const ph = chunk.map(() => '?').join(',')
          const r = await db.prepare(`DELETE FROM transactions WHERE id IN (${ph})`).bind(...chunk).run()
          deletedNegMatched += (r.meta?.changes || 0)
        }
      }
      // (b-2) 분할 적용: src 행을 srcNewAmount 로 UPDATE (분할된 splitAmount 만큼은 잔액 변화로 흡수됨)
      //       이 행은 이후 (c) 통합 단계에서 master 가 되거나 통합으로 흡수됨
      if (plan.splitPlan) {
        const sp = plan.splitPlan
        const ru = await db.prepare(`
          UPDATE transactions
          SET amount = ?, description = COALESCE(description,'') || ' [분할]'
          WHERE id = ?
        `).bind(sp.srcNewAmount, sp.srcId).run()
        splitApplied += (ru.meta?.changes || 0)
      }
      // (c) 잔여 후보 통합 — master 1행에 합산 amount + description 통합, 나머지 삭제
      //     ★ orphanSum 은 splitPlan 의 srcNewAmount 가 이미 반영된 값 (계획 단계에서 candToKeep 에 srcNewAmount 로 push)
      if (plan.consolidateMasterId !== null && renameOrphans) {
        if (Math.abs(plan.orphanSum) > 0.5) {
          // 통합 amount 가 0 이 아니면 master 행을 보정용으로 사용
          const ru = await db.prepare(`
            UPDATE transactions
            SET amount = ?, description = '[잔액 보정] 휴일 회수 잔여분 통합'
            WHERE id = ?
          `).bind(plan.orphanSum, plan.consolidateMasterId).run()
          consolidatedUpdated += (ru.meta?.changes || 0)
        } else {
          // 통합 amount 가 0 이면 master 까지 삭제 (사용자에게 0 행 표시 방지)
          const r = await db.prepare(`DELETE FROM transactions WHERE id = ?`).bind(plan.consolidateMasterId).run()
          consolidatedDeleted += (r.meta?.changes || 0)
        }
        // delete others
        if (plan.consolidateDeleteIds.length > 0) {
          for (let i = 0; i < plan.consolidateDeleteIds.length; i += CHUNK) {
            const chunk = plan.consolidateDeleteIds.slice(i, i + CHUNK)
            const ph = chunk.map(() => '?').join(',')
            const r = await db.prepare(`DELETE FROM transactions WHERE id IN (${ph})`).bind(...chunk).run()
            consolidatedDeleted += (r.meta?.changes || 0)
          }
        }
      }
    }

    return c.json({
      success: true,
      dryRun: false,
      mode: 'B3-enhanced',
      positiveDates,
      negativeDates,
      userCount: userSummary.length,
      totalBalanceDelta: totalDelta,
      deletedPositives,
      deletedNegMatched,
      consolidatedUpdated,
      consolidatedDeleted,
      perUserSummary: userSummary
    })
  } catch (error) {
    console.error('pair-purge-tx error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// 어드민: 휴일 잘못 지급/회수 트랜잭션 흔적 완전 삭제 (5/1, 5/3 등)
//   - 안전장치: 사용자별 net=0 인 경우에만 삭제 (잔액 변화 0 보장)
//   - 대상 type: daily_qkey, referral_reward, daily_reward_rollback, referral_reward_rollback, rollback_restore
//   - 제외 type: direct_referral (직접판매는 즉시 지급되어 회수 대상 아님)
//   - dryRun=true 시 삭제하지 않고 영향 사용자/행 미리보기만 반환
app.post('/api/admin/rewards/purge-tx-by-dates', async (c) => {
  try {
    const db = c.env.DB
    const body = await c.req.json().catch(() => ({}))
    const dates: string[] = Array.isArray(body?.dates) ? body.dates : []
    const dryRun: boolean = body?.dryRun === true
    const includeRollbackCreatedDates: string[] = Array.isArray(body?.rollbackCreatedDates) ? body.rollbackCreatedDates : []
    if (dates.length === 0) return c.json({ error: 'dates 배열이 필요합니다 (예: ["2026-05-01","2026-05-03"])' }, 400)

    // 대상 type
    const TYPES = ['daily_qkey', 'referral_reward', 'daily_reward_rollback', 'referral_reward_rollback', 'rollback_restore']
    const placeholders = TYPES.map(() => '?').join(',')

    // 1. 양수 행: dates 의 created_at(KST date) 기준
    //    SQLite: substr(datetime(created_at,'+9 hours'),1,10) = ?
    const datePredicates = dates.map(() => `substr(datetime(created_at,'+9 hours'),1,10) = ?`).join(' OR ')

    // 2. 회수/복구 행: rollbackCreatedDates 의 created_at 기준 (없으면 동일 dates 사용)
    const rollbackDates = includeRollbackCreatedDates.length > 0 ? includeRollbackCreatedDates : dates
    const rollbackDatePredicates = rollbackDates.map(() => `substr(datetime(created_at,'+9 hours'),1,10) = ?`).join(' OR ')

    // 양수 후보
    const positiveQuery = `
      SELECT id, user_id, type, amount, description, created_at
      FROM transactions
      WHERE type IN (${placeholders})
        AND coin_type = 'QKEY'
        AND amount >= 0
        AND (${datePredicates})
    `
    const positiveParams: any[] = [...TYPES, ...dates]
    const positives = await db.prepare(positiveQuery).bind(...positiveParams).all()

    // 음수(회수) + rollback_restore 후보
    const negativeQuery = `
      SELECT id, user_id, type, amount, description, created_at
      FROM transactions
      WHERE type IN ('daily_reward_rollback','referral_reward_rollback','rollback_restore')
        AND coin_type = 'QKEY'
        AND (
          (${rollbackDatePredicates})
          OR description LIKE '%2026-05-01%'
          OR description LIKE '%2026-05-02%'
          OR description LIKE '%2026-05-03%'
          OR description LIKE '%5/1%'
          OR description LIKE '%5/3%'
        )
    `
    const negativeParams: any[] = [...rollbackDates]
    const negatives = await db.prepare(negativeQuery).bind(...negativeParams).all()

    // 사용자별 집계
    const perUser: Record<number, { positives: any[], negatives: any[], posSum: number, negSum: number }> = {}
    for (const r of (positives.results || []) as any[]) {
      // direct_referral 제외 보장 (이미 type 필터로 제외되어 있음)
      const uid = Number(r.user_id)
      if (!perUser[uid]) perUser[uid] = { positives: [], negatives: [], posSum: 0, negSum: 0 }
      perUser[uid].positives.push(r)
      perUser[uid].posSum += Number(r.amount) || 0
    }
    for (const r of (negatives.results || []) as any[]) {
      const uid = Number(r.user_id)
      if (!perUser[uid]) perUser[uid] = { positives: [], negatives: [], posSum: 0, negSum: 0 }
      perUser[uid].negatives.push(r)
      perUser[uid].negSum += Number(r.amount) || 0
    }

    const summary: any[] = []
    const eligibleIds: number[] = []
    const skippedUsers: any[] = []
    for (const uidStr of Object.keys(perUser)) {
      const uid = Number(uidStr)
      const u = perUser[uid]
      const net = u.posSum + u.negSum // negSum already negative
      const eligible = Math.abs(net) < 0.5
      summary.push({
        user_id: uid,
        positive_count: u.positives.length,
        positive_sum: u.posSum,
        negative_count: u.negatives.length,
        negative_sum: u.negSum,
        net,
        eligible
      })
      if (eligible) {
        for (const p of u.positives) eligibleIds.push(Number(p.id))
        for (const n of u.negatives) eligibleIds.push(Number(n.id))
      } else {
        skippedUsers.push({ user_id: uid, net, reason: 'net != 0' })
      }
    }

    if (dryRun) {
      return c.json({
        success: true,
        dryRun: true,
        dates,
        rollbackDates,
        totalPositiveRows: (positives.results || []).length,
        totalNegativeRows: (negatives.results || []).length,
        eligibleUsers: summary.filter((s:any) => s.eligible).length,
        skippedUsers: skippedUsers.length,
        deletableRowCount: eligibleIds.length,
        perUserSummary: summary,
        skipped: skippedUsers
      })
    }

    // 실제 삭제
    let deleted = 0
    if (eligibleIds.length > 0) {
      // 청크로 나눠 IN 절 길이 제한 회피
      const CHUNK = 50
      for (let i = 0; i < eligibleIds.length; i += CHUNK) {
        const chunk = eligibleIds.slice(i, i + CHUNK)
        const ph = chunk.map(() => '?').join(',')
        const r = await db.prepare(`DELETE FROM transactions WHERE id IN (${ph})`).bind(...chunk).run()
        deleted += (r.meta?.changes || 0)
      }
    }

    return c.json({
      success: true,
      dryRun: false,
      dates,
      rollbackDates,
      totalPositiveRows: (positives.results || []).length,
      totalNegativeRows: (negatives.results || []).length,
      eligibleUsers: summary.filter((s:any) => s.eligible).length,
      skippedUsers: skippedUsers.length,
      deletedRowCount: deleted,
      perUserSummary: summary,
      skipped: skippedUsers
    })
  } catch (error) {
    console.error('purge-tx-by-dates error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// 어드민: 특정 컷오프(KST) 이후 거래 전부 삭제 + 잔액 재계산
//   - 사장님 명령: 4/30까지만 남기고 5/1 이후 모든 보상/회수/복구/보정 행 삭제
//   - 대상 type: 모든 type (daily_qkey, referral_reward, direct_referral,
//                daily_reward_rollback, referral_reward_rollback, rollback_restore 포함)
//   - 적용 컷오프: KST 기준 substr(datetime(created_at,'+9 hours'),1,10) > cutoffDate
//   - 잔액 처리: 삭제 후 users.qkey_balance = SUM(remaining tx.amount WHERE coin_type='QKEY')
//                (= 4/30까지의 정상 잔액으로 자동 복원)
//   - dryRun=true 시 영향 범위만 미리보기 반환
app.post('/api/admin/rewards/purge-after-date', async (c) => {
  try {
    const db = c.env.DB
    const body = await c.req.json().catch(() => ({}))
    const { cutoffDate, dryRun, coinType, excludeTypes } = body || {}
    if (!cutoffDate) return c.json({ error: 'cutoffDate 가 필요합니다 (예: "2026-04-30")' }, 400)
    const ct = String(coinType || 'QKEY')
    // 옵션 2: 직판/스테이킹 보존 — excludeTypes 지정 시 해당 type 은 삭제 대상에서 제외
    const excludeList: string[] = Array.isArray(excludeTypes) ? excludeTypes.map(String) : []
    const excludeClause = excludeList.length > 0
      ? ` AND type NOT IN (${excludeList.map(()=>'?').join(',')})`
      : ''

    // 1. 삭제 대상 조회 (KST 기준 cutoffDate 초과, excludeTypes 제외)
    const targets = await db.prepare(`
      SELECT id, user_id, type, coin_type, amount, description, created_at
      FROM transactions
      WHERE coin_type = ?
        AND substr(datetime(created_at,'+9 hours'),1,10) > ?
        ${excludeClause}
      ORDER BY user_id, created_at ASC
    `).bind(ct, String(cutoffDate), ...excludeList).all()
    const targetRows = (targets.results || []) as any[]

    // 2. 사용자별 영향 집계
    const byUser: Record<number, any> = {}
    for (const r of targetRows) {
      const u = Number(r.user_id)
      if (!byUser[u]) byUser[u] = { user_id: u, count: 0, sum: 0, by_type: {} }
      byUser[u].count++
      byUser[u].sum += Number(r.amount) || 0
      const t = String(r.type || '')
      byUser[u].by_type[t] = (byUser[u].by_type[t] || 0) + 1
    }

    // 3. 사용자별 4/30까지 잔액 합계(보존되는 행 합)
    const survived = await db.prepare(`
      SELECT user_id, COALESCE(SUM(amount),0) as kept_sum, COUNT(*) as kept_count
      FROM transactions
      WHERE coin_type = ?
        AND substr(datetime(created_at,'+9 hours'),1,10) <= ?
      GROUP BY user_id
    `).bind(ct, String(cutoffDate)).all()
    const keptByUser: Record<number, any> = {}
    for (const r of (survived.results || []) as any[]) {
      keptByUser[Number(r.user_id)] = { kept_sum: Number(r.kept_sum) || 0, kept_count: Number(r.kept_count) || 0 }
    }

    // 4. 현재 사용자 잔액 + 새 잔액(=kept_sum) 비교
    const userIds = Array.from(new Set([
      ...Object.keys(byUser).map(Number),
      ...Object.keys(keptByUser).map(Number)
    ]))
    const summary: any[] = []
    for (const uid of userIds) {
      const cur = await db.prepare(`SELECT id, email, name, qkey_balance FROM users WHERE id = ?`).bind(uid).first()
      if (!cur) continue
      const kept = keptByUser[uid] || { kept_sum: 0, kept_count: 0 }
      const tgt = byUser[uid] || { count: 0, sum: 0, by_type: {} }
      summary.push({
        user_id: uid,
        email: (cur as any).email,
        name: (cur as any).name,
        current_qkey_balance: Number((cur as any).qkey_balance) || 0,
        new_qkey_balance: kept.kept_sum,                  // 삭제 후 잔액
        balance_change: kept.kept_sum - (Number((cur as any).qkey_balance) || 0),
        delete_count: tgt.count,
        delete_sum: tgt.sum,
        delete_by_type: tgt.by_type,
        kept_count: kept.kept_count,
        kept_sum: kept.kept_sum
      })
    }
    summary.sort((a:any,b:any)=>a.user_id-b.user_id)

    if (dryRun) {
      return c.json({
        success: true,
        dryRun: true,
        cutoffDate,
        coinType: ct,
        totalDeleteRows: targetRows.length,
        totalDeleteSum: targetRows.reduce((s,r)=>s+(Number(r.amount)||0),0),
        affectedUserCount: summary.length,
        perUserSummary: summary
      })
    }

    // 5. 실삭제 — 청크 단위 batch
    const CHUNK = 100
    let deleted = 0
    const ids = targetRows.map(r => Number(r.id))
    for (let i = 0; i < ids.length; i += CHUNK) {
      const ch = ids.slice(i, i + CHUNK)
      const ph = ch.map(()=>'?').join(',')
      const r = await db.prepare(`DELETE FROM transactions WHERE id IN (${ph})`).bind(...ch).run()
      deleted += (r.meta?.changes || 0)
    }

    // 6. 사용자 잔액 동기화 — 각 사용자 qkey_balance = kept_sum
    let updatedUsers = 0
    for (const s of summary) {
      const r = await db.prepare(`UPDATE users SET qkey_balance = ? WHERE id = ?`)
        .bind(s.new_qkey_balance, s.user_id).run()
      updatedUsers += (r.meta?.changes || 0)
    }

    return c.json({
      success: true,
      dryRun: false,
      cutoffDate,
      coinType: ct,
      deletedRows: deleted,
      updatedUsers,
      affectedUserCount: summary.length,
      perUserSummary: summary
    })
  } catch (error) {
    console.error('purge-after-date error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// 어드민: 사용자 잔액 임의 수정 + admin_adjustment 거래 자동 기록
//   - body: { userId, amount, description?, mode?, coin? }
//     amount: 양수면 가산, 음수면 차감 (mode='delta' 기본)
//     mode='set' 사용 시 amount 를 잔액 그대로 세팅하고 차이값을 admin_adjustment 로 기록
//     coin: 'QKEY' (기본) | 'QTA' | 'QX'  — 사장님 영구명령 2026-05-22 추가
//   - description 미지정 시 '관리자 보정' 사용
//
// ★ 사장님 영구명령 (2026-05-22) — 사용자 화면 캡처 기반
//    "어드민에서 qta, qx코인도 잔액수정이 가능하게 해주세요"
//   → 기존 QKEY 전용 로직을 3종 코인 모두 지원하도록 확장. coin 미지정 시 하위호환을 위해 QKEY 처리.
app.post('/api/admin/users/adjust-balance', async (c) => {
  try {
    const db = c.env.DB
    const body = await c.req.json().catch(() => ({}))
    const { userId, amount, description, mode, reason, coin } = body || {}
    if (!userId || amount === undefined || amount === null) {
      return c.json({ error: 'userId, amount 가 필요합니다' }, 400)
    }
    // ★ 사장님 룰 (2026-05-06 확정): 어드민 잔액 수정 시 사유(reason) 필수
    const reasonRaw = String(reason || description || '').trim()
    if (!reasonRaw || reasonRaw === '관리자 보정') {
      return c.json({ error: '수정 사유(reason)를 구체적으로 입력해주세요. 사유 없이는 잔액을 변경할 수 없습니다.' }, 400)
    }
    // 코인 종류 결정 (기본 QKEY - 하위호환)
    //   COIN_MAP: 표시 잔액 컬럼(col) + 출금가능 컬럼(wcol) + 회사지급분 컬럼(icol)
    //   QKEY: 단일 컬럼(qkey_balance) - wcol/icol 없음
    //   QTA/QX: balance(표시) / initial(회사지급분, 출금불가) / withdrawable(출금가능) 3컬럼 분리
    const coinRaw = String(coin || 'QKEY').toUpperCase().trim()
    const COIN_MAP: Record<string, { col: string; label: string; wcol: string | null; icol: string | null }> = {
      'QKEY': { col: 'qkey_balance', label: 'QKEY', wcol: null,               icol: null            },
      'QTA':  { col: 'qta_balance',  label: 'QTA',  wcol: 'qta_withdrawable', icol: 'qta_initial'   },
      'QX':   { col: 'qx_balance',   label: 'QX',   wcol: 'qx_withdrawable',  icol: 'qx_initial'    }
    }
    if (!COIN_MAP[coinRaw]) {
      return c.json({ error: `coin 은 QKEY, QTA, QX 중 하나여야 합니다 (받음: ${coinRaw})` }, 400)
    }
    const balanceCol = COIN_MAP[coinRaw].col
    const coinLabel  = COIN_MAP[coinRaw].label
    const wCol       = COIN_MAP[coinRaw].wcol  // QKEY 일 때 null
    const iCol       = COIN_MAP[coinRaw].icol  // QKEY 일 때 null

    const uid = Number(userId)
    // ★ 사장님 영구명령 (2026-05-23 재정의) #어드민-수정-initial우선차감:
    //   3컬럼(balance/initial/withdrawable) 모두 조회 → 차감 시 initial 우선 회수, withdrawable 절대 보존
    const cur = await db.prepare(
      `SELECT id, email, name,
              COALESCE(qta_balance,0)      as qta_balance,
              COALESCE(qx_balance,0)       as qx_balance,
              COALESCE(qkey_balance,0)     as qkey_balance,
              COALESCE(qta_withdrawable,0) as qta_withdrawable,
              COALESCE(qx_withdrawable,0)  as qx_withdrawable,
              COALESCE(qta_initial,0)      as qta_initial,
              COALESCE(qx_initial,0)       as qx_initial
         FROM users WHERE id = ?`
    ).bind(uid).first()
    if (!cur) return c.json({ error: '사용자를 찾을 수 없습니다' }, 404)
    const curBal = Number((cur as any)[balanceCol]) || 0
    const curWd  = wCol ? (Number((cur as any)[wCol]) || 0) : curBal  // QKEY는 출금가능=잔액
    const curIni = iCol ? (Number((cur as any)[iCol]) || 0) : 0       // QKEY는 initial 개념 없음
    let delta = 0
    if (String(mode || 'delta') === 'set') {
      delta = Number(amount) - curBal
    } else {
      delta = Number(amount)
    }
    if (Math.abs(delta) < 0.0001) {
      return c.json({ success: true, message: '변경 사항 없음', currentBalance: curBal, coin: coinLabel })
    }
    const newBal = curBal + delta

    // ============================================================
    // ★★★ 사장님 영구명령 (2026-05-23 최종 확정) #어드민-수정-initial우선차감
    //
    // 직접 인용:
    //   "출금가능 수량은 절대적으로 유지하는게 맞고! 사용자는 저 수량이상은 절대 출금가능이
    //    안되게 하면되고, 어드민 관리자가 잘못지급된 부분이 있다치면 이니셜을 건드려도 차감이
    //    되게 해달라는거야"
    //
    // 차감(-) 시:
    //   1) qta_initial / qx_initial 부터 차감 (회사 잘못 지급분 회수)
    //   2) qta_withdrawable / qx_withdrawable 은 절대 안 건드림 (사용자 수익 신성불가침)
    //   3) qta_balance / qx_balance 도 -delta 동기 차감 (표시 총합)
    //   4) qta_initial 이 음수가 되어도 허용 (회수 진행 - 사장님 명시 의도)
    //   5) qta_balance < 0 만 거절 (음수 표시 잔액 방지)
    //
    // 증액(+) 시:
    //   1) qta_balance / qx_balance 동기 +delta
    //   2) qta_withdrawable / qx_withdrawable 도 +delta (새 지급분은 출금 가능, 정산 포함)
    //   3) qta_initial / qx_initial 은 그대로 (회사 마케팅 지급분은 신규 증액 대상 아님)
    //
    // QKEY (단일 컬럼) 동작: balance만 +/- (이전과 동일)
    // ============================================================
    let newWd = curWd
    let newIni = curIni
    if (wCol && iCol) {
      if (delta >= 0) {
        // 증액: withdrawable 동기 + (정산 포함), initial 그대로
        newWd  = curWd + delta
        newIni = curIni
      } else {
        // 차감: initial 우선 회수, withdrawable 절대 보존
        newWd  = curWd          // 절대 안 건드림!
        newIni = curIni + delta // delta < 0 이므로 감소 (초과 시 음수 허용)
      }
    } else {
      // QKEY: 단일 컬럼이므로 balance 그대로 가는 거 = withdrawable 와 동치
      newWd  = newBal
      newIni = 0
    }

    // 가드: balance < 0 만 거절 (표시 잔액 음수 방지)
    //   initial 음수는 허용 - 어드민 회수가 회사 지급 한도를 넘는 경우 사장님 명시 허용
    //   withdrawable 은 차감 시 그대로라 음수가 될 일 없음 (증액만 영향)
    if (newBal < 0) {
      return c.json({
        error: `표시 잔액이 음수가 됩니다 (현재 ${curBal} ${coinLabel} ${delta >= 0 ? '+' : ''}${delta} = ${newBal}). 차감 가능 한도를 초과했습니다.`,
        currentBalance: curBal,
        attemptedDelta: delta,
        coin: coinLabel
      }, 400)
    }
    // ★ 출금가능 음수 가드는 제거됨 (2026-05-23 사장님 명령)
    //   사장님 인용: "출금가능 수량은 절대적으로 유지하는게 맞고! ... 이니셜을 건드려도 차감이 되게"
    //   → 차감 시 withdrawable 은 그대로(절대 보존), initial 만 회수하므로 더 이상 newWd < 0 가드 필요 없음
    //   → initial 음수는 사장님이 명시적으로 허용

    // 풍부한 description 생성 (사용자/어드민 양측에 명확히 표시)
    //   ★ 사장님 룰 (2026-05-23): 사용자 화면에 "관리자 수정" 으로 표시
    //   형식: [관리자 수정] ▲증액 +500 QKEY (이전 2,000 → 이후 2,500) | 사유: <reason>
    //   형식: [관리자 수정] ▼차감 -10,000 QX (이전 31,000 → 이후 21,000) | 사유: <reason>
    const fmt = (n: number) => Math.round(n).toLocaleString('ko-KR')
    const arrow = delta >= 0 ? '▲증액' : '▼차감'
    const sign = delta >= 0 ? '+' : ''
    const richDesc = `[관리자 수정] ${arrow} ${sign}${fmt(delta)} ${coinLabel} (이전 ${fmt(curBal)} → 이후 ${fmt(newBal)}) | 사유: ${reasonRaw}`
    // 1) admin_adjustment 거래 기록 (description 에 사유+변동량 모두 포함, coin_type 동적)
    const ins = await db.prepare(
      `INSERT INTO transactions (user_id, type, coin_type, amount, description) VALUES (?, 'admin_adjustment', ?, ?, ?)`
    ).bind(uid, coinLabel, delta, richDesc).run()
    // 2) 컬럼 업데이트 - 3컬럼(QTA/QX) or 1컬럼(QKEY)
    //    ★ 사장님 영구명령 #어드민-수정-initial우선차감 (위 큰 주석 참조)
    //    차감 시: balance -delta, initial -delta (회수), withdrawable 그대로
    //    증액 시: balance +delta, withdrawable +delta (정산 포함), initial 그대로
    if (wCol && iCol) {
      await db.prepare(
        `UPDATE users SET ${balanceCol} = ?, ${wCol} = ?, ${iCol} = ? WHERE id = ?`
      ).bind(newBal, newWd, newIni, uid).run()
    } else {
      await db.prepare(
        `UPDATE users SET ${balanceCol} = ? WHERE id = ?`
      ).bind(newBal, uid).run()
    }
    return c.json({
      success: true,
      userId: uid,
      email: (cur as any).email,
      name: (cur as any).name,
      coin: coinLabel,
      previousBalance: curBal,
      newBalance: newBal,
      previousWithdrawable: curWd,
      newWithdrawable: newWd,
      previousInitial: curIni,
      newInitial: newIni,
      withdrawablePreserved: (delta < 0 && !!wCol),  // 차감일 때만 withdrawable 보존됨
      initialAdjusted: (delta < 0 && !!iCol),         // 차감일 때만 initial 회수 발생
      withdrawableSynced: !!wCol,  // QTA/QX 일 때만 true (출금/정산 즉시 포함)
      delta,
      direction: delta >= 0 ? 'increase' : 'decrease',
      txId: ins.meta?.last_row_id,
      reason: reasonRaw,
      description: richDesc
    })
  } catch (error) {
    console.error('adjust-balance error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// 어드민: daily_rewards / referral_rewards 테이블에서 특정 reward_date 행 삭제
//   - 옵션 A: 4/30 발생분 행 정리 후 cron 재트리거용
//   - body: { rewardDate: 'YYYY-MM-DD', dryRun?: boolean }
//   - transactions 테이블은 별도로 옵션 2에서 삭제 완료된 상태이므로 건드리지 않음
// ============================================================
// [신규 룰] KST 날짜 기준 당일 시작 = 당일 배당 자격 인정
//   - 기존: date(?) >= date(s.start_date, '+1 day')  (start_date 다음날부터)
//   - 신규: date(?, '+9 hours') >= date(s.start_date, '+9 hours')  (KST 같은 날도 자격)
//   - 한국시간 기준 23:59:59 까지 가입·staking 시작은 당일분 배당 대상
// ============================================================
// ============================================================
// [신규] 3종 코인 세트 (QTA + QX + QKEY) 누락 보정 — 5/4~5/10 진입자
//   - 사장님 지시 2026-05-04: 컷오프를 5/3 → 5/10 KST 23:59:59 로 연장
//   - 5/4 이후 진입한 staking 중 qx_reward=0 OR qkey_reward=0 인 행 추적
//   - staking.qx_reward, qkey_reward 값을 amount/1000 * 10000, *5000 으로 정정
//   - 사용자 잔액 보정 (qx_balance, qkey_balance 차이만큼 +)
//   - 중복 지급 방지: 이미 staking.qx_reward > 0 AND qkey_reward > 0 이면 스킵
//   - 중복 지급 방지: transactions 에 'three_set_supplement' type 로 기록 (이미 있으면 스킵)
// ============================================================
// ============================================================
// [신규] 단일 staking 3종 보정 — staking_id 명시 지정
//   - 사장님 지시: 5/4 진입자 중 정인숙(sela, staking_id=66) 만 보정
//   - body: { stakingId, dryRun? }
//   - 중복 방지: transactions(three_set_supplement) 같은 staking_id 이미 있으면 skip
// ============================================================
app.post('/api/admin/rewards/three-set-supplement-single', async (c) => {
  try {
    const db = c.env.DB
    const body = await c.req.json().catch(() => ({}))
    const { stakingId, dryRun } = body || {}
    if (!stakingId) return c.json({ error: 'stakingId 가 필요합니다' }, 400)

    const s: any = await db.prepare(`
      SELECT s.id, s.user_id, s.amount, s.status, s.qta_reward, s.qx_reward, s.qkey_reward,
             s.created_at, u.email, u.name, u.qx_balance, u.qkey_balance
      FROM staking s LEFT JOIN users u ON s.user_id = u.id
      WHERE s.id = ?
    `).bind(stakingId).first()
    if (!s) return c.json({ error: 'staking not found' }, 404)

    const correctQx = (s.amount / 1000) * 10000
    const correctQkey = (s.amount / 1000) * 5000
    const qxDelta = correctQx - (s.qx_reward || 0)
    const qkeyDelta = correctQkey - (s.qkey_reward || 0)

    // 중복 방지
    const dup = await db.prepare(`
      SELECT id FROM transactions
      WHERE user_id = ? AND type = 'three_set_supplement' AND description LIKE ?
      LIMIT 1
    `).bind(s.user_id, `%staking_id=${s.id}%`).first()

    const result: any = {
      stakingId: s.id, userId: s.user_id, email: s.email, name: s.name,
      amount: s.amount, status: s.status,
      before: { qx_reward: s.qx_reward || 0, qkey_reward: s.qkey_reward || 0,
                qx_balance: s.qx_balance || 0, qkey_balance: s.qkey_balance || 0 },
      delta: { qx: qxDelta, qkey: qkeyDelta },
      duplicate: !!dup,
      dryRun: !!dryRun
    }

    if (dup) {
      result.skipped = 'transactions(three_set_supplement) already exists for this staking_id'
      return c.json({ success: true, ...result })
    }

    if (!dryRun) {
      // staking 행 정정
      await db.prepare(`UPDATE staking SET qx_reward = ?, qkey_reward = ? WHERE id = ?`)
        .bind(correctQx, correctQkey, s.id).run()

      // status=active 만 잔액 즉시 +
      if (s.status === 'active') {
        if (qxDelta > 0) {
          await db.prepare(`UPDATE users SET qx_balance = COALESCE(qx_balance,0) + ? WHERE id = ?`)
            .bind(qxDelta, s.user_id).run()
          await db.prepare(`
            INSERT INTO transactions (user_id, type, coin_type, amount, description)
            VALUES (?, 'three_set_supplement', 'QX', ?, ?)
          `).bind(s.user_id, qxDelta,
            `3종 보정 QX (staking_id=${s.id}, amount=$${s.amount}, 사장님 지시)`).run()
        }
        if (qkeyDelta > 0) {
          await db.prepare(`UPDATE users SET qkey_balance = COALESCE(qkey_balance,0) + ? WHERE id = ?`)
            .bind(qkeyDelta, s.user_id).run()
          await db.prepare(`
            INSERT INTO transactions (user_id, type, coin_type, amount, description)
            VALUES (?, 'three_set_supplement', 'QKEY', ?, ?)
          `).bind(s.user_id, qkeyDelta,
            `3종 보정 QKEY (staking_id=${s.id}, amount=$${s.amount}, 사장님 지시)`).run()
        }
      }
    }
    return c.json({ success: true, ...result })
  } catch (error: any) {
    console.error('three-set-supplement-single error:', error)
    return c.json({ error: 'D1 error: ' + (error?.message || String(error)) }, 500)
  }
})

app.post('/api/admin/rewards/three-set-supplement', async (c) => {
  try {
    const db = c.env.DB
    const body = await c.req.json().catch(() => ({}))
    const { fromDate, toDate, dryRun } = body || {}
    const fd = fromDate || '2026-05-04'
    const td = toDate || '2026-05-10'

    // 대상 staking 조회: created_at KST 가 fromDate~toDate 범위 + status active 또는 pending
    //   + qx_reward 또는 qkey_reward 가 0 인 행 (Phase2 룰로 잘못 0 저장된 케이스)
    const targets = await db.prepare(`
      SELECT 
        s.id, s.user_id, s.amount, s.status, s.qta_reward, s.qx_reward, s.qkey_reward,
        s.start_date, s.created_at,
        u.email, u.name, u.qta_balance, u.qx_balance, u.qkey_balance
      FROM staking s
      LEFT JOIN users u ON s.user_id = u.id
      WHERE s.status IN ('active','pending')
        AND date(s.created_at, '+9 hours') >= date(?)
        AND date(s.created_at, '+9 hours') <= date(?)
        AND ((COALESCE(s.qx_reward,0) = 0) OR (COALESCE(s.qkey_reward,0) = 0))
    `).bind(fd, td).all()

    const summary = {
      fromDate: fd, toDate: td, dryRun: !!dryRun,
      candidate_count: targets.results.length,
      processed: [] as any[],
      skipped_duplicate: [] as any[],
      total_qx_added: 0,
      total_qkey_added: 0
    }

    for (const s of targets.results) {
      const correctQx = ((s.amount as number) / 1000) * 10000
      const correctQkey = ((s.amount as number) / 1000) * 5000
      const currentQx = (s.qx_reward as number) || 0
      const currentQkey = (s.qkey_reward as number) || 0
      const qxDelta = correctQx - currentQx
      const qkeyDelta = correctQkey - currentQkey

      // 중복 방지: transactions 에 같은 staking_id 로 'three_set_supplement' 가 이미 있으면 스킵
      const dupCheck = await db.prepare(`
        SELECT id FROM transactions 
        WHERE user_id = ? AND type = 'three_set_supplement' 
          AND description LIKE ?
        LIMIT 1
      `).bind(s.user_id, `%staking_id=${s.id}%`).first()

      if (dupCheck) {
        summary.skipped_duplicate.push({
          staking_id: s.id, user_id: s.user_id, email: s.email,
          reason: 'transactions(three_set_supplement) already exists'
        })
        continue
      }

      summary.processed.push({
        staking_id: s.id, user_id: s.user_id, email: s.email, name: s.name,
        amount: s.amount, status: s.status,
        before: { qx_reward: currentQx, qkey_reward: currentQkey },
        after: { qx_reward: correctQx, qkey_reward: correctQkey },
        delta: { qx: qxDelta, qkey: qkeyDelta },
        created_at: s.created_at
      })
      summary.total_qx_added += qxDelta
      summary.total_qkey_added += qkeyDelta

      if (!dryRun) {
        // 1. staking 행의 qx_reward, qkey_reward 업데이트
        await db.prepare(`
          UPDATE staking SET qx_reward = ?, qkey_reward = ? WHERE id = ?
        `).bind(correctQx, correctQkey, s.id).run()

        // 2. status='active' 인 경우만 즉시 잔액 추가 (pending 은 승인 시 지급되므로 staking 행만 정정)
        if (s.status === 'active' && (qxDelta > 0 || qkeyDelta > 0)) {
          if (qxDelta > 0) {
            await db.prepare(`UPDATE users SET qx_balance = COALESCE(qx_balance,0) + ? WHERE id = ?`)
              .bind(qxDelta, s.user_id).run()
            await db.prepare(`
              INSERT INTO transactions (user_id, type, coin_type, amount, description)
              VALUES (?, 'three_set_supplement', 'QX', ?, ?)
            `).bind(s.user_id, qxDelta,
              `3종 보정 QX (staking_id=${s.id}, amount=$${s.amount}, 5/4-5/10 진입자 누락분)`
            ).run()
          }
          if (qkeyDelta > 0) {
            await db.prepare(`UPDATE users SET qkey_balance = COALESCE(qkey_balance,0) + ? WHERE id = ?`)
              .bind(qkeyDelta, s.user_id).run()
            await db.prepare(`
              INSERT INTO transactions (user_id, type, coin_type, amount, description)
              VALUES (?, 'three_set_supplement', 'QKEY', ?, ?)
            `).bind(s.user_id, qkeyDelta,
              `3종 보정 QKEY (staking_id=${s.id}, amount=$${s.amount}, 5/4-5/10 진입자 누락분)`
            ).run()
          }
        }
      }
    }

    return c.json({ success: true, ...summary })
  } catch (error: any) {
    console.error('three-set-supplement error:', error)
    return c.json({ error: 'D1 error: ' + (error?.message || String(error)) }, 500)
  }
})

// ============================================================
// [Phase3 신규] QX 단독 보정 — 5/22~ 진입자 중 qx_reward=0 인 staking 행 보정
//   사장님 영구명령 (2026-05-22, lis7238 화면 캡처 기반):
//     "5월 6일 이후에는 $1,000 기준당 신규로 스테이킹 진입할때
//      qta 75,000개 qx 10,000개 총 2종이 사용자 메인내역에 찍혀야 하는데
//      현재 qx 코인이 찍히지 않음"
//
//   대상: status IN ('active','pending') AND COALESCE(qx_reward,0) = 0
//         AND date(created_at, '+9 hours') BETWEEN fromDate AND toDate
//   동작:
//     - staking 행의 qx_reward 를 (amount/1000)*10000 으로 정정
//     - status='active' 인 경우만 잔액 즉시 추가 + transactions(qx_phase3_supplement) 기록
//     - status='pending' 인 경우 staking 행만 정정 (승인 시 자동 지급)
//   중복방지: transactions(qx_phase3_supplement) 에 staking_id 매핑 이미 있으면 skip
//
//   body: { fromDate?, toDate?, stakingId?, dryRun? }
//     - stakingId 지정 시 단일 보정, 미지정 시 fromDate~toDate 범위 일괄 보정
//     - fromDate 기본 '2026-05-22', toDate 기본 오늘 KST
// ============================================================
app.post('/api/admin/rewards/qx-phase3-supplement', async (c) => {
  try {
    const db = c.env.DB
    const body = await c.req.json().catch(() => ({}))
    const { fromDate, toDate, stakingId, dryRun } = body || {}

    const fd = fromDate || '2026-05-22'
    const td = toDate || kstDateStr(new Date())

    let targets: any
    if (stakingId) {
      // 단일 보정
      targets = await db.prepare(`
        SELECT s.id, s.user_id, s.amount, s.status, s.qta_reward, s.qx_reward, s.qkey_reward,
               s.created_at, u.email, u.name, u.qx_balance
        FROM staking s LEFT JOIN users u ON s.user_id = u.id
        WHERE s.id = ?
      `).bind(stakingId).all()
    } else {
      // 범위 보정
      targets = await db.prepare(`
        SELECT s.id, s.user_id, s.amount, s.status, s.qta_reward, s.qx_reward, s.qkey_reward,
               s.created_at, u.email, u.name, u.qx_balance
        FROM staking s LEFT JOIN users u ON s.user_id = u.id
        WHERE s.status IN ('active','pending')
          AND COALESCE(s.qx_reward, 0) = 0
          AND date(s.created_at, '+9 hours') >= date(?)
          AND date(s.created_at, '+9 hours') <= date(?)
      `).bind(fd, td).all()
    }

    const summary = {
      fromDate: fd, toDate: td, stakingId: stakingId || null, dryRun: !!dryRun,
      candidate_count: (targets.results || []).length,
      processed: [] as any[],
      skipped_duplicate: [] as any[],
      skipped_already_paid: [] as any[],
      total_qx_added: 0
    }

    for (const s of (targets.results || []) as any[]) {
      const correctQx = (s.amount / 1000) * 10000
      const currentQx = s.qx_reward || 0
      const qxDelta = correctQx - currentQx

      if (qxDelta <= 0) {
        summary.skipped_already_paid.push({
          staking_id: s.id, user_id: s.user_id, email: s.email,
          current_qx_reward: currentQx, reason: 'qx_reward already >= correct value'
        })
        continue
      }

      // 중복 방지: 같은 staking_id 에 qx_phase3_supplement 이미 있으면 skip
      const dup = await db.prepare(`
        SELECT id FROM transactions
        WHERE user_id = ? AND type = 'qx_phase3_supplement' AND description LIKE ?
        LIMIT 1
      `).bind(s.user_id, `%staking_id=${s.id}%`).first()

      if (dup) {
        summary.skipped_duplicate.push({
          staking_id: s.id, user_id: s.user_id, email: s.email,
          reason: 'transactions(qx_phase3_supplement) already exists'
        })
        continue
      }

      summary.processed.push({
        staking_id: s.id, user_id: s.user_id, email: s.email, name: s.name,
        amount: s.amount, status: s.status,
        before: { qx_reward: currentQx, qx_balance: s.qx_balance || 0 },
        after:  { qx_reward: correctQx },
        delta:  { qx: qxDelta },
        created_at: s.created_at
      })
      summary.total_qx_added += qxDelta

      if (!dryRun) {
        // 1) staking 행의 qx_reward 정정 (active/pending 모두)
        await db.prepare(`UPDATE staking SET qx_reward = ? WHERE id = ?`)
          .bind(correctQx, s.id).run()

        // 2) status='active' 인 경우만 잔액 즉시 +
        //    영구정책 (2026-05-14): 회사 지급분이므로 qx_initial 도 함께 증가 → 출금불가 보호
        if (s.status === 'active') {
          await ensureWithdrawableSchema(db)
          await db.prepare(`
            UPDATE users
            SET qx_balance = COALESCE(qx_balance, 0) + ?,
                qx_initial = COALESCE(qx_initial, 0) + ?
            WHERE id = ?
          `).bind(qxDelta, qxDelta, s.user_id).run()

          await db.prepare(`
            INSERT INTO transactions (user_id, type, coin_type, amount, description)
            VALUES (?, 'qx_phase3_supplement', 'QX', ?, ?)
          `).bind(s.user_id, qxDelta,
            `Phase3 QX 보정 (staking_id=${s.id}, amount=$${s.amount}, 5/22~ 룰 적용 누락분)`
          ).run()
        }
        // status='pending' 은 staking 행만 정정 (사장님 [승인] 클릭 시 자동 지급)
      }
    }

    return c.json({ success: true, ...summary })
  } catch (error: any) {
    console.error('qx-phase3-supplement error:', error)
    return c.json({ error: 'D1 error: ' + (error?.message || String(error)) }, 500)
  }
})

app.post('/api/admin/rewards/recalc-by-kst-date', async (c) => {
  try {
    const db = c.env.DB
    const body = await c.req.json().catch(() => ({}))
    const { accrualDate, paidDate, dryRun } = body || {}
    if (!accrualDate || !paidDate) {
      return c.json({ error: 'accrualDate / paidDate 필요 (예: "2026-04-30", "2026-05-04")' }, 400)
    }

    // paid_date 컬럼 보장
    try { await db.prepare(`ALTER TABLE daily_rewards ADD COLUMN paid_date TEXT`).run() } catch(e) {}
    try { await db.prepare(`ALTER TABLE referral_rewards ADD COLUMN paid_date TEXT`).run() } catch(e) {}

    // ★ KST 날짜 기준 자격 staking 조회 (당일 시작 = 당일 자격)
    //   - status = active
    //   - end_date_kst >= accrualDate
    //   - start_date_kst <= accrualDate  (당일 포함)
    const eligibleStakings = await db.prepare(`
      SELECT
        s.user_id, s.id as staking_id, s.amount, s.period_days, s.period_months,
        s.daily_rate, s.start_date, s.end_date, s.reset_at,
        (SELECT COUNT(*) FROM daily_rewards WHERE staking_id = s.id) as rewarded_count,
        (SELECT COUNT(*) FROM daily_rewards WHERE staking_id = s.id AND reward_date = ?) as already_for_date
      FROM staking s
      WHERE s.status = 'active'
        AND date(s.end_date, '+9 hours') >= date(?)
        AND date(s.start_date, '+9 hours') <= date(?)
    `).bind(accrualDate, accrualDate, accrualDate).all()

    const USD_TO_QKEY = 150
    const summary = {
      accrualDate, paidDate, dryRun: !!dryRun,
      eligible_staking_count: eligibleStakings.results.length,
      already_paid_count: 0,
      newly_added_daily: [] as any[],
      newly_added_referral: [] as any[],
      total_new_daily_qkey: 0,
      total_new_referral_qkey: 0
    }

    for (const s of eligibleStakings.results) {
      const periodDays = s.period_days || ((s.period_months as number) * 30)
      if ((s.rewarded_count as number) >= periodDays) continue
      if ((s.already_for_date as number) > 0) {
        summary.already_paid_count++
        continue
      }
      const dailyRate = s.daily_rate as number
      const usdAmount = (s.amount as number) * dailyRate
      const qkeyAmount = Math.round(usdAmount * USD_TO_QKEY)

      summary.newly_added_daily.push({
        user_id: s.user_id, staking_id: s.staking_id, amount: s.amount,
        daily_rate: dailyRate, qkey: qkeyAmount, start_date: s.start_date
      })
      summary.total_new_daily_qkey += qkeyAmount

      if (!dryRun) {
        // daily_rewards 행 신규 삽입 (reward_date=accrualDate, paid_date=paidDate)
        await db.prepare(`
          INSERT INTO daily_rewards (user_id, staking_id, usdt_amount, reward_date, paid_date)
          VALUES (?, ?, ?, ?, ?)
        `).bind(s.user_id, s.staking_id, qkeyAmount, accrualDate, paidDate).run()

        // 잔액 업데이트
        await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`)
          .bind(qkeyAmount, s.user_id).run()

        // transactions 기록 — EXISTS 가드 (user, type='daily_qkey', amount, KST date) 중복 INSERT 차단
        const newCount = (s.rewarded_count as number) + 1
        const dqExists3 = await db.prepare(`
          SELECT id FROM transactions
          WHERE user_id = ? AND type = 'daily_qkey' AND coin_type = 'QKEY'
            AND amount = ?
            AND date(created_at, '+9 hours') = ?
          LIMIT 1
        `).bind(s.user_id, qkeyAmount, paidDate).first()
        if (!dqExists3) {
          await db.prepare(`
            INSERT INTO transactions (user_id, type, coin_type, amount, description)
            VALUES (?, 'daily_qkey', 'QKEY', ?, ?)
          `).bind(s.user_id, qkeyAmount,
            `Daily reward ${qkeyAmount.toLocaleString()} QKEY (${(dailyRate*100).toFixed(1)}%, ${newCount}/${periodDays}d, accrued ${accrualDate} paid ${paidDate}) [KST-rule recalc]`
          ).run()
        }
      }

      // 매칭수당 (L1 20%, L2 10%) — 추천인이 accrualDate 시점 active 일 때만
      try {
        const l1ref = await db.prepare(`SELECT referrer_id FROM users WHERE id = ?`).bind(s.user_id).first()
        if (l1ref && l1ref.referrer_id) {
          const l1Active = await db.prepare(`
            SELECT id FROM staking
            WHERE user_id = ? AND status = 'active'
              AND date(start_date, '+9 hours') <= date(?)
              AND date(end_date, '+9 hours') >= date(?)
            LIMIT 1
          `).bind(l1ref.referrer_id, accrualDate, accrualDate).first()
          if (l1Active) {
            // 중복 체크
            const dupL1 = await db.prepare(`
              SELECT id FROM referral_rewards
              WHERE referrer_id = ? AND referee_id = ? AND level = 1 AND reward_date = ?
            `).bind(l1ref.referrer_id, s.user_id, accrualDate).first()
            if (!dupL1) {
              const l1Reward = Math.round(qkeyAmount * 0.20)
              summary.newly_added_referral.push({
                referrer_id: l1ref.referrer_id, referee_id: s.user_id, level: 1, qkey: l1Reward
              })
              summary.total_new_referral_qkey += l1Reward
              if (!dryRun) {
                await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`)
                  .bind(l1Reward, l1ref.referrer_id).run()
                await db.prepare(`
                  INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date)
                  VALUES (?, ?, 1, ?, ?, ?, ?)
                `).bind(l1ref.referrer_id, s.user_id, qkeyAmount, l1Reward, accrualDate, paidDate).run()
                // EXISTS 가드 — (referrer, type='referral_reward', amount, KST date) 중복 INSERT 차단
                const l1TxExists3 = await db.prepare(`
                  SELECT id FROM transactions
                  WHERE user_id = ? AND type = 'referral_reward' AND coin_type = 'QKEY'
                    AND amount = ?
                    AND date(created_at, '+9 hours') = ?
                  LIMIT 1
                `).bind(l1ref.referrer_id, l1Reward, paidDate).first()
                if (!l1TxExists3) {
                  await db.prepare(`
                    INSERT INTO transactions (user_id, type, coin_type, amount, description)
                    VALUES (?, 'referral_reward', 'QKEY', ?, ?)
                  `).bind(l1ref.referrer_id, l1Reward,
                    `Level 1 referral bonus (${qkeyAmount.toLocaleString()} QKEY x 20%, accrued ${accrualDate} paid ${paidDate}) [KST-rule recalc]`
                  ).run()
                }
              }
            }
            // L2
            const l2ref = await db.prepare(`SELECT referrer_id FROM users WHERE id = ?`).bind(l1ref.referrer_id).first()
            if (l2ref && l2ref.referrer_id) {
              const l2Active = await db.prepare(`
                SELECT id FROM staking
                WHERE user_id = ? AND status = 'active'
                  AND date(start_date, '+9 hours') <= date(?)
                  AND date(end_date, '+9 hours') >= date(?)
                LIMIT 1
              `).bind(l2ref.referrer_id, accrualDate, accrualDate).first()
              if (l2Active) {
                const dupL2 = await db.prepare(`
                  SELECT id FROM referral_rewards
                  WHERE referrer_id = ? AND referee_id = ? AND level = 2 AND reward_date = ?
                `).bind(l2ref.referrer_id, s.user_id, accrualDate).first()
                if (!dupL2) {
                  const l2Reward = Math.round(qkeyAmount * 0.10)
                  summary.newly_added_referral.push({
                    referrer_id: l2ref.referrer_id, referee_id: s.user_id, level: 2, qkey: l2Reward
                  })
                  summary.total_new_referral_qkey += l2Reward
                  if (!dryRun) {
                    await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`)
                      .bind(l2Reward, l2ref.referrer_id).run()
                    await db.prepare(`
                      INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date)
                      VALUES (?, ?, 2, ?, ?, ?, ?)
                    `).bind(l2ref.referrer_id, s.user_id, qkeyAmount, l2Reward, accrualDate, paidDate).run()
                    // EXISTS 가드 — (referrer, type='referral_reward', amount, KST date) 중복 INSERT 차단
                    const l2TxExists3 = await db.prepare(`
                      SELECT id FROM transactions
                      WHERE user_id = ? AND type = 'referral_reward' AND coin_type = 'QKEY'
                        AND amount = ?
                        AND date(created_at, '+9 hours') = ?
                      LIMIT 1
                    `).bind(l2ref.referrer_id, l2Reward, paidDate).first()
                    if (!l2TxExists3) {
                      await db.prepare(`
                        INSERT INTO transactions (user_id, type, coin_type, amount, description)
                        VALUES (?, 'referral_reward', 'QKEY', ?, ?)
                      `).bind(l2ref.referrer_id, l2Reward,
                        `Level 2 referral bonus (${qkeyAmount.toLocaleString()} QKEY x 10%, accrued ${accrualDate} paid ${paidDate}) [KST-rule recalc]`
                      ).run()
                    }
                  }
                }
              }
            }
          }
        }
      } catch (refErr) {
        console.error('referral recalc error:', refErr)
      }
    }

    return c.json({ success: true, ...summary })
  } catch (error: any) {
    console.error('recalc-by-kst-date error:', error)
    return c.json({ error: 'D1 error: ' + (error?.message || String(error)) }, 500)
  }
})

app.post('/api/admin/rewards/cleanup-by-reward-date', async (c) => {
  try {
    const db = c.env.DB
    const body = await c.req.json().catch(() => ({}))
    const { rewardDate, dryRun } = body || {}
    if (!rewardDate) return c.json({ error: 'rewardDate 가 필요합니다 (예: "2026-04-30")' }, 400)

    // 1. daily_rewards 영향 행 조회 (실제 스키마: usdt_amount, staking_id)
    const dr = await db.prepare(
      `SELECT id, user_id, staking_id, usdt_amount, reward_date, created_at
       FROM daily_rewards WHERE reward_date = ?`
    ).bind(String(rewardDate)).all()
    const drRows = (dr.results || []) as any[]

    // 2. referral_rewards 영향 행 조회 (실제 스키마: referrer_id, referee_id, level, reward_amount)
    let rrRows: any[] = []
    try {
      const rr = await db.prepare(
        `SELECT id, referrer_id, referee_id, level, original_amount, reward_amount, reward_date, created_at
         FROM referral_rewards WHERE reward_date = ?`
      ).bind(String(rewardDate)).all()
      rrRows = (rr.results || []) as any[]
    } catch(e) {
      // 테이블 없으면 무시
    }

    // 3. 사용자별 영향 집계
    const byUser: Record<number, any> = {}
    for (const r of drRows) {
      const u = Number(r.user_id)
      if (!byUser[u]) byUser[u] = { user_id: u, daily_count: 0, daily_amount: 0, ref_count: 0, ref_amount: 0 }
      byUser[u].daily_count++
      byUser[u].daily_amount += Number(r.usdt_amount) || 0
    }
    for (const r of rrRows) {
      const u = Number(r.referrer_id)
      if (!byUser[u]) byUser[u] = { user_id: u, daily_count: 0, daily_amount: 0, ref_count: 0, ref_amount: 0 }
      byUser[u].ref_count++
      byUser[u].ref_amount += Number(r.reward_amount) || 0
    }
    const userSummary = Object.values(byUser).sort((a:any,b:any)=>a.user_id-b.user_id)

    if (dryRun) {
      return c.json({
        success: true,
        dryRun: true,
        rewardDate,
        dailyRewardsCount: drRows.length,
        dailyRewardsSum: drRows.reduce((s,r)=>s+(Number(r.usdt_amount)||0),0),
        referralRewardsCount: rrRows.length,
        referralRewardsSum: rrRows.reduce((s,r)=>s+(Number(r.reward_amount)||0),0),
        affectedUserCount: userSummary.length,
        perUserSummary: userSummary
      })
    }

    // 4. 실삭제
    const drDel = await db.prepare(`DELETE FROM daily_rewards WHERE reward_date = ?`).bind(String(rewardDate)).run()
    let rrDel: any = { meta: { changes: 0 } }
    try {
      rrDel = await db.prepare(`DELETE FROM referral_rewards WHERE reward_date = ?`).bind(String(rewardDate)).run()
    } catch(e) {}

    return c.json({
      success: true,
      dryRun: false,
      rewardDate,
      deletedDailyRewards: drDel.meta?.changes || 0,
      deletedReferralRewards: rrDel.meta?.changes || 0,
      affectedUserCount: userSummary.length,
      perUserSummary: userSummary
    })
  } catch (error) {
    console.error('cleanup-by-reward-date error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// 어드민: referral_rewards 의 paid_date 를 일괄 갱신 (사용자단 화면 동기화용)
//   - body: { rewardDate: 'YYYY-MM-DD', paidDate?: 'YYYY-MM-DD'(default=오늘 KST), dryRun?: boolean }
//   - 효과: 해당 reward_date 의 referral_rewards 모든 행에 paid_date 를 지정해 사용자단에서도 정상 표시되도록 함
//   - transactions/잔액은 이미 발생 시점에 처리되어 있으므로 추가 변동 없음 (중복 지급 방지)
app.post('/api/admin/rewards/set-referral-paid-date', async (c) => {
  try {
    const db = c.env.DB
    const body = await c.req.json().catch(() => ({}))
    const { rewardDate, paidDate, dryRun } = body || {}
    if (!rewardDate) return c.json({ error: 'rewardDate 가 필요합니다 (예: "2026-05-05")' }, 400)

    const finalPaid = paidDate || new Date(Date.now() + 9*60*60*1000).toISOString().slice(0,10)

    const before = await db.prepare(
      `SELECT id, referrer_id, referee_id, level, reward_amount, reward_date, paid_date, created_at
       FROM referral_rewards WHERE reward_date = ? ORDER BY id`
    ).bind(String(rewardDate)).all()
    const rows = (before.results || []) as any[]
    const nullRows = rows.filter((r:any)=> r.paid_date == null || r.paid_date === '')

    if (dryRun) {
      return c.json({
        success: true, dryRun: true, rewardDate, paidDate: finalPaid,
        totalRows: rows.length, nullPaidRows: nullRows.length,
        targets: nullRows.map((r:any)=>({ id:r.id, referrer:r.referrer_id, referee:r.referee_id, amount:r.reward_amount, paid_date:r.paid_date }))
      })
    }

    let updated = 0
    for (const r of nullRows) {
      const u = await db.prepare(
        `UPDATE referral_rewards SET paid_date = ? WHERE id = ? AND (paid_date IS NULL OR paid_date = '')`
      ).bind(finalPaid, r.id).run()
      updated += (u.meta?.changes || 0)
    }

    const after = await db.prepare(
      `SELECT id, referrer_id, referee_id, reward_amount, reward_date, paid_date FROM referral_rewards WHERE reward_date = ? ORDER BY id`
    ).bind(String(rewardDate)).all()

    return c.json({
      success: true, dryRun: false, rewardDate, paidDate: finalPaid,
      totalRows: rows.length, nullBefore: nullRows.length, updatedCount: updated,
      after: after.results || []
    })
  } catch (error) {
    console.error('set-referral-paid-date error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

