//   dedupe: ref_id = 'bf_h910_512_s<staking_id>_<type>' 3중 EXISTS 가드
//          (기존 ALL27 백필 ref_id 'bf_holiday_512_*' 와도 별개로 EXISTS 체크)
//          (cron 자체 ref_id 패턴도 staking_id+reward_date EXISTS 로 차단)
//
// 호출 (dry_run): GET ?key=ADMIN_PW
// 호출 (실행):    GET ?key=ADMIN_PW&confirm=GO
// ============================================================
app.get('/api/diag/fix-holiday-entrant-512-daily-910only', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: '관리자 인증이 필요합니다' }, 401)
  const dep = assertNotDeprecated(c, 'fix-holiday-entrant-512-daily-910only', '5/9~10 휴일 진입자 5/12 보정 완료. safeInsertTransaction 가드 미적용 → 재호출 시 이중지급 위험')
  if (dep) return dep
  const confirm = c.req.query('confirm') || ''
  const isExec = confirm === 'GO'

  try {
    const db = c.env.DB
    const TARGET_DATE = '2026-05-12'
    const PAID_DATE = '2026-05-12'

    // ★ 5/9·5/10 진입자 동적 조회 (하드코딩 X — DB 실데이터로만 판단)
    const targetRows = await db.prepare(`
      SELECT s.id AS staking_id
      FROM staking s
      WHERE s.status = 'active'
        AND date(datetime(s.start_date, '+9 hours')) IN ('2026-05-09', '2026-05-10')
      ORDER BY s.id ASC
    `).all()
    const TARGET_STAKINGS: number[] = (targetRows.results || []).map((r: any) => Number(r.staking_id))

    const preview: any[] = []
    let totalSelfQkey = 0
    let totalL1Qkey = 0
    let totalL2Qkey = 0

    for (const sid of TARGET_STAKINGS) {
      const s = await db.prepare(`
        SELECT s.id, s.user_id, s.amount, s.daily_rate, s.status,
               date(datetime(s.start_date, '+9 hours')) AS kst_start_date,
               u.name AS user_name, u.email AS user_email, u.qkey_balance, u.referrer_id
        FROM staking s JOIN users u ON s.user_id = u.id
        WHERE s.id = ? AND s.status = 'active'
      `).bind(sid).first() as any

      if (!s) {
        preview.push({ staking_id: sid, status: 'NOT_FOUND_OR_INACTIVE' })
        continue
      }

      const expectedQkey = Math.round(Number(s.amount) * Number(s.daily_rate) * 150)

      // 이미 5/12 지급됐는지 (daily_rewards EXISTS — cron 이 박은 행도 포함됨)
      const existing = await db.prepare(`
        SELECT id, usdt_amount FROM daily_rewards WHERE staking_id = ? AND reward_date = ? LIMIT 1
      `).bind(sid, TARGET_DATE).first() as any

      // L1/L2
      let l1UserId: number | null = null
      let l2UserId: number | null = null
      let l1Name = '', l2Name = ''
      if (s.referrer_id) {
        const l1u = await db.prepare(`SELECT id, name, referrer_id FROM users WHERE id = ?`).bind(s.referrer_id).first() as any
        if (l1u) {
          l1UserId = l1u.id
          l1Name = l1u.name
          if (l1u.referrer_id) {
            const l2u = await db.prepare(`SELECT id, name FROM users WHERE id = ?`).bind(l1u.referrer_id).first() as any
            if (l2u) { l2UserId = l2u.id; l2Name = l2u.name }
          }
        }
      }

      const l1Qkey = l1UserId ? Math.round(expectedQkey * 0.20) : 0
      const l2Qkey = l2UserId ? Math.round(expectedQkey * 0.10) : 0

      // dedupe ref_id (이 엔드포인트 전용 — bf_h910_*)
      const refIdSelf = `bf_h910_512_s${sid}_self`
      const refIdL1 = `bf_h910_512_s${sid}_l1`
      const refIdL2 = `bf_h910_512_s${sid}_l2`
      const exSelf = await db.prepare(`SELECT id FROM transactions WHERE ref_id = ? LIMIT 1`).bind(refIdSelf).first()
      const exL1 = l1UserId ? await db.prepare(`SELECT id FROM transactions WHERE ref_id = ? LIMIT 1`).bind(refIdL1).first() : null
      const exL2 = l2UserId ? await db.prepare(`SELECT id FROM transactions WHERE ref_id = ? LIMIT 1`).bind(refIdL2).first() : null

      // 추가 안전장치: cron / 기존 백필이 박은 L1/L2 거래내역 EXISTS 체크
      //   (user_id, type='referral_reward', amount, 5/12 created_at, from staking sid)
      //   ref_id 패턴 무관하게 description 또는 ref_id LIKE 로 광범위 차단
      const cronL1Exists = l1UserId ? await db.prepare(`
        SELECT id FROM transactions
        WHERE user_id = ? AND type = 'referral_reward' AND coin_type = 'QKEY' AND amount = ?
          AND date(datetime(created_at, '+9 hours')) = ?
          AND (ref_id LIKE ? OR ref_id LIKE ?)
        LIMIT 1
      `).bind(l1UserId, l1Qkey, TARGET_DATE, `%s${sid}%`, `%_${sid}_%`).first() : null

      const cronL2Exists = l2UserId ? await db.prepare(`
        SELECT id FROM transactions
        WHERE user_id = ? AND type = 'referral_reward' AND coin_type = 'QKEY' AND amount = ?
          AND date(datetime(created_at, '+9 hours')) = ?
          AND (ref_id LIKE ? OR ref_id LIKE ?)
        LIMIT 1
      `).bind(l2UserId, l2Qkey, TARGET_DATE, `%s${sid}%`, `%_${sid}_%`).first() : null

      preview.push({
        staking_id: sid,
        user_id: s.user_id,
        user_name: s.user_name,
        user_email: s.user_email,
        amount: s.amount,
        daily_rate: s.daily_rate,
        kst_start_date: s.kst_start_date,
        qkey_balance_before: s.qkey_balance,
        self_qkey: expectedQkey,
        already_paid_5_12: existing ? true : false,
        existing_paid_qkey: existing ? existing.usdt_amount : null,
        self_already_inserted: exSelf ? true : false,
        l1: l1UserId ? {
          user_id: l1UserId, name: l1Name, qkey: l1Qkey,
          backfill_ref_exists: exL1 ? true : false,
          cron_or_other_paid: cronL1Exists ? true : false
        } : null,
        l2: l2UserId ? {
          user_id: l2UserId, name: l2Name, qkey: l2Qkey,
          backfill_ref_exists: exL2 ? true : false,
          cron_or_other_paid: cronL2Exists ? true : false
        } : null,
      })

      if (!existing && !exSelf) totalSelfQkey += expectedQkey
      if (l1UserId && !exL1 && !cronL1Exists) totalL1Qkey += l1Qkey
      if (l2UserId && !exL2 && !cronL2Exists) totalL2Qkey += l2Qkey
    }

    if (!isExec) {
      return c.json({
        success: true,
        mode: 'DRY_RUN',
        target_date: TARGET_DATE,
        target_stakings_count: TARGET_STAKINGS.length,
        target_stakings: TARGET_STAKINGS,
        preview,
        sums: {
          self_qkey_to_insert: totalSelfQkey,
          l1_qkey_to_insert: totalL1Qkey,
          l2_qkey_to_insert: totalL2Qkey,
          grand_total_qkey: totalSelfQkey + totalL1Qkey + totalL2Qkey,
        },
        next: '실행하려면 ?confirm=GO 추가',
      })
    }

    // ==== 실행 (GO) — 다중 안전장치 ====
    const inserted: any[] = []
    const skipped: any[] = []
    let actualSelfQkey = 0
    let actualL1Qkey = 0
    let actualL2Qkey = 0

    for (const p of preview as any[]) {
      if (p.status === 'NOT_FOUND_OR_INACTIVE') { skipped.push(p); continue }
      const sid = p.staking_id
      const uid = p.user_id

      // 1) Self 데일리
      if (!p.already_paid_5_12 && !p.self_already_inserted) {
        const refIdSelf = `bf_h910_512_s${sid}_self`
        const drIns = await db.prepare(`
          INSERT INTO daily_rewards (staking_id, user_id, usdt_amount, reward_date, paid_date, created_at)
          VALUES (?, ?, ?, ?, ?, datetime('now'))
        `).bind(sid, uid, p.self_qkey, TARGET_DATE, PAID_DATE).run()

        await db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
          VALUES (?, 'daily_reward', 'QKEY', ?, ?, ?)
        `).bind(uid, p.self_qkey, '일일 배당 (QKEY)', refIdSelf).run()

        await db.prepare(`UPDATE users SET qkey_balance = COALESCE(qkey_balance,0) + ? WHERE id = ?`).bind(p.self_qkey, uid).run()

        actualSelfQkey += p.self_qkey
        inserted.push({ staking_id: sid, user_id: uid, type: 'self', qkey: p.self_qkey, daily_reward_id: drIns.meta?.last_row_id })
      } else {
        skipped.push({ staking_id: sid, user_id: uid, type: 'self', reason: p.already_paid_5_12 ? 'daily_rewards_exists' : 'transactions_ref_id_exists' })
      }

      // 2) L1 (cron_or_other_paid 도 체크 — 영구룰: 중복지급 절대 금지)
      if (p.l1 && !p.l1.backfill_ref_exists && !p.l1.cron_or_other_paid) {
        const refIdL1 = `bf_h910_512_s${sid}_l1`
        await db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
          VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?)
        `).bind(p.l1.user_id, p.l1.qkey, '추천 보너스 (Level 1)', refIdL1).run()

        await db.prepare(`UPDATE users SET qkey_balance = COALESCE(qkey_balance,0) + ? WHERE id = ?`).bind(p.l1.qkey, p.l1.user_id).run()

        try {
          await db.prepare(`
            INSERT INTO referral_rewards (user_id, from_user_id, level, amount, coin_type, reward_date, paid_date, ref_id, created_at)
            VALUES (?, ?, 1, ?, 'QKEY', ?, ?, ?, datetime('now'))
          `).bind(p.l1.user_id, uid, p.l1.qkey, TARGET_DATE, PAID_DATE, refIdL1).run()
        } catch(e) {}

        actualL1Qkey += p.l1.qkey
        inserted.push({ staking_id: sid, user_id: p.l1.user_id, type: 'L1', qkey: p.l1.qkey, from_user_id: uid })
      } else if (p.l1) {
        skipped.push({ staking_id: sid, user_id: p.l1.user_id, type: 'L1', reason: p.l1.cron_or_other_paid ? 'cron_or_other_already_paid' : 'backfill_ref_exists' })
      }

      // 3) L2
      if (p.l2 && !p.l2.backfill_ref_exists && !p.l2.cron_or_other_paid) {
        const refIdL2 = `bf_h910_512_s${sid}_l2`
        await db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
          VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?)
        `).bind(p.l2.user_id, p.l2.qkey, '추천 보너스 (Level 2)', refIdL2).run()

        await db.prepare(`UPDATE users SET qkey_balance = COALESCE(qkey_balance,0) + ? WHERE id = ?`).bind(p.l2.qkey, p.l2.user_id).run()

        try {
          await db.prepare(`
            INSERT INTO referral_rewards (user_id, from_user_id, level, amount, coin_type, reward_date, paid_date, ref_id, created_at)
            VALUES (?, ?, 2, ?, 'QKEY', ?, ?, ?, datetime('now'))
          `).bind(p.l2.user_id, uid, p.l2.qkey, TARGET_DATE, PAID_DATE, refIdL2).run()
        } catch(e) {}

        actualL2Qkey += p.l2.qkey
        inserted.push({ staking_id: sid, user_id: p.l2.user_id, type: 'L2', qkey: p.l2.qkey, from_user_id: uid })
      } else if (p.l2) {
        skipped.push({ staking_id: sid, user_id: p.l2.user_id, type: 'L2', reason: p.l2.cron_or_other_paid ? 'cron_or_other_already_paid' : 'backfill_ref_exists' })
      }
    }

    // 사후 검증
    const afterCheck: any[] = []
    for (const sid of TARGET_STAKINGS) {
      const dr = await db.prepare(`SELECT id, user_id, usdt_amount FROM daily_rewards WHERE staking_id = ? AND reward_date = ?`).bind(sid, TARGET_DATE).first() as any
      if (dr) {
        const u = await db.prepare(`SELECT qkey_balance FROM users WHERE id = ?`).bind(dr.user_id).first() as any
        afterCheck.push({ staking_id: sid, user_id: dr.user_id, paid_5_12_qkey: dr.usdt_amount, qkey_balance_after: u?.qkey_balance })
      } else {
        afterCheck.push({ staking_id: sid, status: 'STILL_MISSING' })
      }
    }

    return c.json({
      success: true,
      mode: 'EXEC',
      target_date: TARGET_DATE,
      target_stakings_count: TARGET_STAKINGS.length,
      inserted_count: inserted.length,
      skipped_count: skipped.length,
      sums: {
        self_qkey_inserted: actualSelfQkey,
        l1_qkey_inserted: actualL1Qkey,
        l2_qkey_inserted: actualL2Qkey,
        grand_total_qkey: actualSelfQkey + actualL1Qkey + actualL2Qkey,
      },
      inserted,
      skipped,
      after_check: afterCheck,
    })
  } catch (error: any) {
    console.error('fix-holiday-entrant-512-daily-910only error:', error)
    return c.json({ error: error?.message || String(error) }, 500)
  }
})

// ============================================================
// /api/diag/fix-513-holiday910-and-cleanup-duplicates
// ----------------------------------------------------
// 사장님 명령 (2026-05-13):
//   1) 5/9·5/10 진입자(s#94~98) 5/13 본인 데일리 지급 (5/12치 1일분, leaf 먼저 — bottom-up)
//   2) 상위 솔밧(L1/L2) 5/13 매칭 중복 1회만 남기고 나머지 삭제 + 잔액 회수
//
// 영구룰 준수:
//   #bottom-up: leaf(본인) 먼저 INSERT → 상위(L1/L2) 중복 DELETE 순서
//   #이중지급금지: GROUP BY (user_id, amount, type, KST date) HAVING COUNT>=2 만 정리
//   #단일 cron: 5/13 self 누락된 leaf 만 보충
//   #112: description '일일 배당 (QKEY)' 사용
//   dedupe ref_id: 'bf_513_self_s<sid>' (3중 EXISTS)
//
// 호출 (dry_run): GET ?key=ADMIN_PW
// 호출 (실행):    GET ?key=ADMIN_PW&confirm=GO
// ============================================================
app.get('/api/diag/fix-513-holiday910-and-cleanup-duplicates', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: '관리자 인증이 필요합니다' }, 401)
  const dep = assertNotDeprecated(c, 'fix-513-holiday910-and-cleanup-duplicates', '5/13 휴일 5/9~10 진입자 보정 + 중복 정리 완료. safeInsertTransaction 가드 미적용 → 재호출 시 이중지급 위험')
  if (dep) return dep
  const confirm = c.req.query('confirm') || ''
  const isExec = confirm === 'GO'

  try {
    const db = c.env.DB
    const TARGET_DATE = '2026-05-13'
    const PAID_DATE = '2026-05-13'

    // ====================================================================
    // PHASE 1 — LEAF FIRST (bottom-up): 5/9·5/10 진입자 본인 5/13 데일리 보충
    // ====================================================================
    const leafRows = await db.prepare(`
      SELECT s.id AS staking_id, s.user_id, s.amount, s.daily_rate,
             date(datetime(s.start_date, '+9 hours')) AS kst_start_date,
             u.name AS user_name, u.email AS user_email, u.qkey_balance, u.referrer_id
      FROM staking s JOIN users u ON s.user_id = u.id
      WHERE s.status = 'active'
        AND date(datetime(s.start_date, '+9 hours')) IN ('2026-05-09', '2026-05-10')
      ORDER BY s.id ASC
    `).all()
    const leafStakings = (leafRows.results || []) as any[]

    const leafPreview: any[] = []
    let totalLeafSelfQkey = 0

    for (const s of leafStakings) {
      const sid = Number(s.staking_id)
      const uid = Number(s.user_id)
      const expectedQkey = Math.round(Number(s.amount) * Number(s.daily_rate) * 150)

      // 5/13 daily_rewards 존재 여부
      const existingDr = await db.prepare(`
        SELECT id, usdt_amount FROM daily_rewards WHERE staking_id = ? AND reward_date = ? LIMIT 1
      `).bind(sid, TARGET_DATE).first() as any

      // 5/13 self transactions 존재 여부 (ref_id 무관 — KST 날짜 기준)
      const existingTx = await db.prepare(`
        SELECT id, ref_id FROM transactions
        WHERE user_id = ? AND type = 'daily_reward' AND coin_type = 'QKEY' AND amount = ?
          AND date(datetime(created_at, '+9 hours')) = ?
        LIMIT 1
      `).bind(uid, expectedQkey, TARGET_DATE).first() as any

      // 백필 ref_id 가드
      const refIdSelf = `bf_513_self_s${sid}`
      const existingRef = await db.prepare(`SELECT id FROM transactions WHERE ref_id = ? LIMIT 1`).bind(refIdSelf).first()

      const needInsert = !existingDr && !existingTx && !existingRef

      leafPreview.push({
        staking_id: sid,
        user_id: uid,
        user_name: s.user_name,
        user_email: s.user_email,
        amount: s.amount,
        daily_rate: s.daily_rate,
        kst_start_date: s.kst_start_date,
        qkey_balance_before: s.qkey_balance,
        self_qkey_to_pay: expectedQkey,
        already_paid_5_13_daily_rewards: existingDr ? true : false,
        already_paid_5_13_transactions: existingTx ? true : false,
        backfill_ref_exists: existingRef ? true : false,
        action: needInsert ? 'WILL_INSERT' : 'SKIP',
      })

      if (needInsert) totalLeafSelfQkey += expectedQkey
    }

    // ====================================================================
    // PHASE 2 — 상위 매칭 5/13 중복 정리 (bottom-up: leaf 완료 후)
    //   GROUP BY (user_id, amount, type='referral_reward', KST date=5/13) HAVING COUNT>=2
    //   첫 1건(created_at ASC, id ASC) 유지, 나머지 DELETE + qkey_balance 차감
    // ====================================================================
    const dupRows = await db.prepare(`
      SELECT user_id, amount, COUNT(*) AS cnt,
             GROUP_CONCAT(id, ',') AS tx_ids,
             GROUP_CONCAT(ref_id, ',') AS ref_ids,
             GROUP_CONCAT(created_at, ',') AS times,
             GROUP_CONCAT(description, ',') AS descs
      FROM transactions
      WHERE type = 'referral_reward'
        AND coin_type = 'QKEY'
        AND date(datetime(created_at, '+9 hours')) = ?
      GROUP BY user_id, amount
      HAVING COUNT(*) >= 2
      ORDER BY user_id ASC, amount ASC
    `).bind(TARGET_DATE).all()
    const dupGroups = (dupRows.results || []) as any[]

    const dupPreview: any[] = []
    let totalDuplicateQkeyToRemove = 0

    for (const g of dupGroups) {
      const uid = Number(g.user_id)
      const amt = Number(g.amount)
      const cnt = Number(g.cnt)
      const txIds = String(g.tx_ids || '').split(',').map((x: string) => parseInt(x.trim(), 10)).filter((n: number) => !Number.isNaN(n))
      const refIds = String(g.ref_ids || '').split(',')
      const times = String(g.times || '').split(',')
      const descs = String(g.descs || '').split(',')

      // 각 row 의 id 와 created_at 을 정렬해 첫 1건만 keep
      const rowsDetail = txIds.map((id: number, i: number) => ({
        id,
        ref_id: refIds[i] || null,
        created_at: times[i] || null,
        description: descs[i] || null,
      }))
      rowsDetail.sort((a: any, b: any) => {
        const ta = a.created_at || ''
        const tb = b.created_at || ''
        if (ta !== tb) return ta < tb ? -1 : 1
        return a.id - b.id
      })

      const keep = rowsDetail[0]
      const remove = rowsDetail.slice(1)
      const removeQkey = amt * remove.length

      // 사용자 정보 보강
      const u = await db.prepare(`SELECT name, email, qkey_balance FROM users WHERE id = ?`).bind(uid).first() as any

      dupPreview.push({
        user_id: uid,
        user_name: u?.name,
        user_email: u?.email,
        qkey_balance_before: u?.qkey_balance,
        amount_each: amt,
        total_count: cnt,
        keep: { id: keep.id, ref_id: keep.ref_id, created_at: keep.created_at },
        remove_count: remove.length,
        remove_qkey_total: removeQkey,
        remove_rows: remove,
      })
      totalDuplicateQkeyToRemove += removeQkey
    }

    if (!isExec) {
      return c.json({
        success: true,
        mode: 'DRY_RUN',
        target_date: TARGET_DATE,
        phase1_leaf_holiday910: {
          target_count: leafStakings.length,
          will_insert_count: leafPreview.filter((p: any) => p.action === 'WILL_INSERT').length,
          total_self_qkey_to_pay: totalLeafSelfQkey,
          preview: leafPreview,
        },
        phase2_duplicate_cleanup: {
          duplicate_groups: dupGroups.length,
          total_qkey_to_remove: totalDuplicateQkeyToRemove,
          preview: dupPreview,
        },
        next: '실행하려면 ?confirm=GO 추가',
      })
    }

    // ====================================================================
    // EXECUTION (confirm=GO) — bottom-up: PHASE 1 (leaf INSERT) → PHASE 2 (dup DELETE)
    // ====================================================================
    const phase1Inserted: any[] = []
    const phase1Skipped: any[] = []

    for (const p of leafPreview as any[]) {
      if (p.action !== 'WILL_INSERT') {
        phase1Skipped.push({ staking_id: p.staking_id, user_id: p.user_id, reason: 'already_paid_or_ref_exists' })
        continue
      }
      const sid = p.staking_id
      const uid = p.user_id
      const qkey = p.self_qkey_to_pay
      const refIdSelf = `bf_513_self_s${sid}`

      // daily_rewards INSERT
      const drIns = await db.prepare(`
        INSERT INTO daily_rewards (staking_id, user_id, usdt_amount, reward_date, paid_date, created_at)
        VALUES (?, ?, ?, ?, ?, datetime('now'))
      `).bind(sid, uid, qkey, TARGET_DATE, PAID_DATE).run()

      // transactions INSERT (사용자 노출 안전 description)
      await db.prepare(`
        INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
        VALUES (?, 'daily_reward', 'QKEY', ?, ?, ?)
      `).bind(uid, qkey, '일일 배당 (QKEY)', refIdSelf).run()

      // 잔액 증가
      await db.prepare(`UPDATE users SET qkey_balance = COALESCE(qkey_balance,0) + ? WHERE id = ?`).bind(qkey, uid).run()

      phase1Inserted.push({
        staking_id: sid, user_id: uid, user_name: p.user_name, user_email: p.user_email,
        qkey: qkey, daily_reward_id: drIns.meta?.last_row_id,
      })
    }

    // PHASE 2 — 중복 매칭 DELETE + 잔액 회수
    const phase2Removed: any[] = []
    let actualRemovedQkey = 0

    for (const g of dupPreview as any[]) {
      const uid = g.user_id
      const removeIds: number[] = g.remove_rows.map((r: any) => r.id)
      const removeQkey = g.remove_qkey_total
      if (removeIds.length === 0) continue

      // transactions DELETE (IN clause)
      const placeholders = removeIds.map(() => '?').join(',')
      await db.prepare(`DELETE FROM transactions WHERE id IN (${placeholders})`).bind(...removeIds).run()

      // referral_rewards 동일 ref_id 삭제 (있으면)
      for (const r of g.remove_rows as any[]) {
        if (r.ref_id) {
          try {
            await db.prepare(`DELETE FROM referral_rewards WHERE ref_id = ?`).bind(r.ref_id).run()
          } catch(e) {}
        }
      }

      // 잔액 차감
      await db.prepare(`UPDATE users SET qkey_balance = COALESCE(qkey_balance,0) - ? WHERE id = ?`).bind(removeQkey, uid).run()

      actualRemovedQkey += removeQkey
      phase2Removed.push({
        user_id: uid, user_name: g.user_name, user_email: g.user_email,
        amount_each: g.amount_each, removed_count: removeIds.length,
        removed_qkey: removeQkey, removed_tx_ids: removeIds, kept_tx_id: g.keep.id,
      })
    }

    // ====================================================================
    // 사후 검증
    // ====================================================================
    const afterPhase1: any[] = []
    for (const p of leafPreview as any[]) {
      const sid = p.staking_id
      const dr = await db.prepare(`SELECT id, usdt_amount FROM daily_rewards WHERE staking_id = ? AND reward_date = ?`).bind(sid, TARGET_DATE).first() as any
      const u = await db.prepare(`SELECT qkey_balance FROM users WHERE id = ?`).bind(p.user_id).first() as any
      afterPhase1.push({
        staking_id: sid, user_id: p.user_id, user_name: p.user_name,
        paid_5_13_qkey: dr?.usdt_amount || null, qkey_balance_after: u?.qkey_balance,
      })
    }

    const afterPhase2Dup = await db.prepare(`
      SELECT user_id, amount, COUNT(*) AS cnt
      FROM transactions
      WHERE type = 'referral_reward' AND coin_type = 'QKEY'
        AND date(datetime(created_at, '+9 hours')) = ?
      GROUP BY user_id, amount
      HAVING COUNT(*) >= 2
    `).bind(TARGET_DATE).all()

    return c.json({
      success: true,
      mode: 'EXEC',
      target_date: TARGET_DATE,
      phase1_leaf_holiday910: {
        inserted_count: phase1Inserted.length,
        skipped_count: phase1Skipped.length,
        total_self_qkey_inserted: phase1Inserted.reduce((sum: number, x: any) => sum + x.qkey, 0),
        inserted: phase1Inserted,
        skipped: phase1Skipped,
      },
      phase2_duplicate_cleanup: {
        groups_cleaned: phase2Removed.length,
        total_qkey_removed: actualRemovedQkey,
        removed_details: phase2Removed,
      },
      after_check: {
        phase1_leaf: afterPhase1,
        phase2_remaining_duplicates: afterPhase2Dup.results || [],
      },
    })
  } catch (error: any) {
    console.error('fix-513-holiday910-and-cleanup-duplicates error:', error)
    return c.json({ error: error?.message || String(error) }, 500)
  }
})

// ============================================================
// /api/diag/exec-513-phase1-leaf-only
// ----------------------------------------------------
// PHASE 1 only — 5/9·5/10 진입자 5명 5/13 본인 데일리 지급
//   영구룰 #bottom-up: leaf 먼저 (이 엔드포인트가 leaf 처리 전담)
//   영구룰 #휴일진입자: 휴일 진입자 평일 데일리 지급 의무
//   안전장치: daily_rewards EXISTS + same-day same-amount tx EXISTS + ref_id EXISTS
//   ref_id: bf_513_self_s<sid>
// ============================================================
app.get('/api/diag/exec-513-phase1-leaf-only', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: '관리자 인증이 필요합니다' }, 401)
  const dep = assertNotDeprecated(c, 'exec-513-phase1-leaf-only', '5/13 Phase1 leaf-only 보정 완료. safeInsertTransaction 가드 미적용 → 재호출 시 이중지급 위험. 후속: solbat-513-g-plan-backfill')
  if (dep) return dep
  const confirm = c.req.query('confirm') || ''
  const isExec = confirm === 'GO'

  try {
    const db = c.env.DB
    const TARGET_DATE = '2026-05-13'
    const PAID_DATE = '2026-05-13'

    const leafRows = await db.prepare(`
      SELECT s.id AS staking_id, s.user_id, s.amount, s.daily_rate,
             date(datetime(s.start_date, '+9 hours')) AS kst_start_date,
             u.name AS user_name, u.email AS user_email, u.qkey_balance
      FROM staking s JOIN users u ON s.user_id = u.id
      WHERE s.status = 'active'
        AND date(datetime(s.start_date, '+9 hours')) IN ('2026-05-09', '2026-05-10')
      ORDER BY s.id ASC
    `).all()
    const leafStakings = (leafRows.results || []) as any[]

    const preview: any[] = []
    let totalQkey = 0

    for (const s of leafStakings) {
      const sid = Number(s.staking_id)
      const uid = Number(s.user_id)
      const qkey = Math.round(Number(s.amount) * Number(s.daily_rate) * 150)

      const existingDr = await db.prepare(`SELECT id, usdt_amount FROM daily_rewards WHERE staking_id = ? AND reward_date = ? LIMIT 1`).bind(sid, TARGET_DATE).first() as any
      const existingTx = await db.prepare(`
        SELECT id FROM transactions
        WHERE user_id = ? AND type = 'daily_reward' AND coin_type = 'QKEY' AND amount = ?
          AND date(datetime(created_at, '+9 hours')) = ?
        LIMIT 1
      `).bind(uid, qkey, TARGET_DATE).first()
      const refIdSelf = `bf_513_self_s${sid}`
      const existingRef = await db.prepare(`SELECT id FROM transactions WHERE ref_id = ? LIMIT 1`).bind(refIdSelf).first()
      const needInsert = !existingDr && !existingTx && !existingRef

      preview.push({
        staking_id: sid, user_id: uid, user_name: s.user_name, user_email: s.user_email,
        amount: s.amount, daily_rate: s.daily_rate, kst_start_date: s.kst_start_date,
        qkey_balance_before: s.qkey_balance, self_qkey_to_pay: qkey,
        already_paid_5_13_daily_rewards: existingDr ? true : false,
        already_paid_5_13_transactions: existingTx ? true : false,
        backfill_ref_exists: existingRef ? true : false,
        action: needInsert ? 'WILL_INSERT' : 'SKIP',
      })
      if (needInsert) totalQkey += qkey
    }

    if (!isExec) {
      return c.json({
        success: true, mode: 'DRY_RUN', target_date: TARGET_DATE,
        target_count: leafStakings.length,
        will_insert_count: preview.filter((p: any) => p.action === 'WILL_INSERT').length,
        total_qkey_to_pay: totalQkey,
        preview,
        next: '실행하려면 ?confirm=GO 추가',
      })
    }

    const inserted: any[] = []
    const skipped: any[] = []
    let actualQkey = 0

    for (const p of preview as any[]) {
      if (p.action !== 'WILL_INSERT') {
        skipped.push({ staking_id: p.staking_id, user_id: p.user_id, reason: 'already_paid_or_ref_exists' })
        continue
      }
      const sid = p.staking_id
      const uid = p.user_id
      const qkey = p.self_qkey_to_pay
      const refIdSelf = `bf_513_self_s${sid}`

      const drIns = await db.prepare(`
        INSERT INTO daily_rewards (staking_id, user_id, usdt_amount, reward_date, paid_date, created_at)
        VALUES (?, ?, ?, ?, ?, datetime('now'))
      `).bind(sid, uid, qkey, TARGET_DATE, PAID_DATE).run()

      await db.prepare(`
        INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
        VALUES (?, 'daily_reward', 'QKEY', ?, ?, ?)
      `).bind(uid, qkey, '일일 배당 (QKEY)', refIdSelf).run()

      await db.prepare(`UPDATE users SET qkey_balance = COALESCE(qkey_balance,0) + ? WHERE id = ?`).bind(qkey, uid).run()

      actualQkey += qkey
      inserted.push({
        staking_id: sid, user_id: uid, user_name: p.user_name, user_email: p.user_email,
        qkey: qkey, daily_reward_id: drIns.meta?.last_row_id,
      })
    }

    const afterCheck: any[] = []
    for (const p of preview as any[]) {
      const dr = await db.prepare(`SELECT id, usdt_amount FROM daily_rewards WHERE staking_id = ? AND reward_date = ?`).bind(p.staking_id, TARGET_DATE).first() as any
      const u = await db.prepare(`SELECT qkey_balance FROM users WHERE id = ?`).bind(p.user_id).first() as any
      afterCheck.push({
        staking_id: p.staking_id, user_id: p.user_id, user_name: p.user_name,
        paid_5_13_qkey: dr?.usdt_amount || null, qkey_balance_after: u?.qkey_balance,
      })
    }

    return c.json({
      success: true, mode: 'EXEC', target_date: TARGET_DATE,
      inserted_count: inserted.length, skipped_count: skipped.length,
      total_qkey_inserted: actualQkey, inserted, skipped, after_check: afterCheck,
    })
  } catch (error: any) {
    console.error('exec-513-phase1-leaf-only error:', error)
    return c.json({ error: error?.message || String(error) }, 500)
  }
})

// ============================================================
// /api/diag/cleanup-my-bf-holiday-512-mistakes
// ----------------------------------------------------
// PHASE 2 — 제가 어제 잘못 박은 bf_holiday_512_* ref_id 패턴 row 만 정확히 삭제
//   정상 cron row 는 절대 안 건드림 (ref_id LIKE 'bf_holiday_512_%' AND KST date = 2026-05-13)
//
// 대상:
//   - transactions WHERE ref_id LIKE 'bf_holiday_512_%' AND DATE(created_at,'+9 hours')='2026-05-13'
//     → daily_reward(self) + referral_reward(L1/L2) 모두 삭제
//   - daily_rewards 는 reward_date='2026-05-12' 인데 paid_date='2026-05-12' 로 박힌 백필 row 도 정리 검토
//     (단, daily_rewards 는 별도 검토 — 본 엔드포인트는 transactions + qkey_balance 만 처리)
//   - users.qkey_balance 에서 삭제된 amount 합계 차감
//   - referral_rewards 동일 ref_id 도 삭제
// ============================================================
app.get('/api/diag/cleanup-my-bf-holiday-512-mistakes', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: '관리자 인증이 필요합니다' }, 401)
  const confirm = c.req.query('confirm') || ''
  const isExec = confirm === 'GO'

  try {
    const db = c.env.DB

    // 대상 추출: bf_holiday_512_* ref_id 패턴 (제가 어제 박은 백필) 전수
    //   ※ 새 ref_id 'bf_h910_512_*' 또는 'bf_513_self_*' 는 건드리지 않음 (안전)
    const rows = await db.prepare(`
      SELECT id, user_id, type, coin_type, amount, description, ref_id, created_at,
             date(datetime(created_at, '+9 hours')) AS kst_date
      FROM transactions
      WHERE ref_id LIKE 'bf_holiday_512_%'
      ORDER BY user_id ASC, id ASC
    `).all()
    const targetRows = (rows.results || []) as any[]

    // 사용자별 amount 합계 집계
    const userTotal: Record<number, number> = {}
    const refIdsToDelete: string[] = []
    const txIdsToDelete: number[] = []
    const preview: any[] = []

    for (const r of targetRows) {
      const uid = Number(r.user_id)
      const amt = Number(r.amount)
      userTotal[uid] = (userTotal[uid] || 0) + amt
      refIdsToDelete.push(String(r.ref_id))
      txIdsToDelete.push(Number(r.id))
    }

    // 사용자별 잔액 변화 미리보기
    const userPreview: any[] = []
    for (const uid of Object.keys(userTotal).map((x: string) => parseInt(x, 10))) {
      const u = await db.prepare(`SELECT name, email, qkey_balance FROM users WHERE id = ?`).bind(uid).first() as any
      const removeQkey = userTotal[uid]
      userPreview.push({
        user_id: uid, user_name: u?.name, user_email: u?.email,
        qkey_balance_before: u?.qkey_balance,
        qkey_to_remove: removeQkey,
        qkey_balance_after_expected: (u?.qkey_balance || 0) - removeQkey,
      })
    }

    if (!isExec) {
      return c.json({
        success: true, mode: 'DRY_RUN',
        target_tx_count: targetRows.length,
        total_qkey_to_remove: Object.values(userTotal).reduce((a: number, b: number) => a + b, 0),
        affected_users: userPreview.length,
        user_preview: userPreview,
        tx_rows_to_delete: targetRows.map((r: any) => ({
          id: r.id, user_id: r.user_id, type: r.type, amount: r.amount,
          ref_id: r.ref_id, created_at: r.created_at, kst_date: r.kst_date,
        })),
        next: '실행하려면 ?confirm=GO 추가',
      })
    }

    // 실행: transactions DELETE + referral_rewards DELETE + qkey_balance 차감
    let deletedTxCount = 0
    let deletedRefCount = 0
    let totalRemovedQkey = 0

    // 1) 잔액 차감 (사용자별)
    for (const uid of Object.keys(userTotal).map((x: string) => parseInt(x, 10))) {
      const removeQkey = userTotal[uid]
      await db.prepare(`UPDATE users SET qkey_balance = COALESCE(qkey_balance,0) - ? WHERE id = ?`).bind(removeQkey, uid).run()
      totalRemovedQkey += removeQkey
    }

    // 2) transactions DELETE (배치, 500개씩)
    const BATCH = 500
    for (let i = 0; i < txIdsToDelete.length; i += BATCH) {
      const chunk = txIdsToDelete.slice(i, i + BATCH)
      const placeholders = chunk.map(() => '?').join(',')
      const res = await db.prepare(`DELETE FROM transactions WHERE id IN (${placeholders})`).bind(...chunk).run()
      deletedTxCount += chunk.length
    }

    // 3) referral_rewards DELETE (ref_id 일치)
    for (let i = 0; i < refIdsToDelete.length; i += BATCH) {
      const chunk = refIdsToDelete.slice(i, i + BATCH)
      const placeholders = chunk.map(() => '?').join(',')
      try {
        await db.prepare(`DELETE FROM referral_rewards WHERE ref_id IN (${placeholders})`).bind(...chunk).run()
        deletedRefCount += chunk.length
      } catch(e) {}
    }

    // 사후 검증: 같은 ref_id 패턴이 0건인지
    const remainCheck = await db.prepare(`
      SELECT COUNT(*) AS cnt FROM transactions WHERE ref_id LIKE 'bf_holiday_512_%'
    `).first() as any

    // 사용자별 사후 잔액
    const afterUserCheck: any[] = []
    for (const up of userPreview) {
      const u = await db.prepare(`SELECT qkey_balance FROM users WHERE id = ?`).bind(up.user_id).first() as any
      afterUserCheck.push({
        user_id: up.user_id, user_name: up.user_name,
        qkey_balance_after: u?.qkey_balance,
        qkey_balance_expected: up.qkey_balance_after_expected,
        match: (u?.qkey_balance === up.qkey_balance_after_expected),
      })
    }

    return c.json({
      success: true, mode: 'EXEC',
      deleted_tx_count: deletedTxCount,
      deleted_referral_rewards_attempts: deletedRefCount,
      total_qkey_removed: totalRemovedQkey,
      affected_users: userPreview.length,
      remaining_bf_holiday_512_rows: remainCheck?.cnt || 0,
      after_user_check: afterUserCheck,
    })
  } catch (error: any) {
    console.error('cleanup-my-bf-holiday-512-mistakes error:', error)
    return c.json({ error: error?.message || String(error) }, 500)
  }
})

// ============================================================
// /api/diag/check-513-user-full-tx (SELECT only — 데이터 변경 0건)
// ----------------------------------------------------
// 특정 user_id 의 5/13 KST 전체 transactions 조회 (모든 type, 모든 ref_id 패턴)
// + (user_id, amount, type) GROUP BY 중복 분석
// ----------------------------------------------------
app.get('/api/diag/check-513-user-full-tx', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: '관리자 인증이 필요합니다' }, 401)
  const uidParam = c.req.query('user_id') || ''
  const uid = parseInt(uidParam, 10)
  if (!uid) return c.json({ error: 'user_id required' }, 400)

  try {
    const db = c.env.DB
    const TARGET_DATE = '2026-05-13'

    const u = await db.prepare(`SELECT id, name, email, qkey_balance FROM users WHERE id = ?`).bind(uid).first() as any

    // 5/13 KST 전체 transactions
    const allTx = await db.prepare(`
      SELECT id, user_id, type, coin_type, amount, description, ref_id, created_at,
             date(datetime(created_at, '+9 hours')) AS kst_date,
             time(datetime(created_at, '+9 hours')) AS kst_time
      FROM transactions
      WHERE user_id = ?
        AND date(datetime(created_at, '+9 hours')) = ?
      ORDER BY created_at ASC, id ASC
    `).bind(uid, TARGET_DATE).all()

    // (amount, type, description) GROUP BY 중복 카운트
    const dupGroups = await db.prepare(`
      SELECT type, amount, description, COUNT(*) AS cnt,
             GROUP_CONCAT(id, ',') AS ids,
             GROUP_CONCAT(ref_id, '|||') AS ref_ids,
             GROUP_CONCAT(created_at, ',') AS times
      FROM transactions
      WHERE user_id = ?
        AND date(datetime(created_at, '+9 hours')) = ?
      GROUP BY type, amount, description
      HAVING COUNT(*) >= 2
      ORDER BY type, amount
    `).bind(uid, TARGET_DATE).all()

    // 5/13 KST type별 합계
    const typeSums = await db.prepare(`
      SELECT type, coin_type, SUM(amount) AS total, COUNT(*) AS cnt
      FROM transactions
      WHERE user_id = ?
        AND date(datetime(created_at, '+9 hours')) = ?
      GROUP BY type, coin_type
      ORDER BY type
    `).bind(uid, TARGET_DATE).all()

    return c.json({
      success: true,
      user: u,
      target_date: TARGET_DATE,
      total_tx_count: (allTx.results || []).length,
      type_sums: typeSums.results || [],
      duplicate_groups_count: (dupGroups.results || []).length,
      duplicate_groups: dupGroups.results || [],
      all_tx: allTx.results || [],
    })
  } catch (error: any) {
    console.error('check-513-user-full-tx error:', error)
    return c.json({ error: error?.message || String(error) }, 500)
  }
})

// ============================================================
// /api/diag/exec-513-bidirectional-matching
// ----------------------------------------------------
// 사장님 명령 (2026-05-13): 5/9·5/10 휴일진입자 5명에 대해 양방향 매칭 보너스 정산
//   영구룰 #bottom-up: leaf 5명 self 데일리 완료 후 매칭 산출
//   영구룰 #휴일진입자: L1/L2 매칭 보너스도 본인 첫 데일리 발생일에 함께 지급
//   영구룰 #2: L1=20%, L2=10%
//   영구룰 #112: description 한국어 안전
//
// 양방향 정산:
//   A) UPSTREAM (위로): 5명의 referrer(L1), referrer_of_referrer(L2)에게 매칭 지급
//      대상 5/13 self 데일리:
//        s#94 김용선(u#38) 2,250 → L1 유호웅(u#34) 450 / L2 연이(u#2) 225
//        s#95 이정옥(u#40) 5,250 → L1 김용선(u#38) 1,050 / L2 유호웅(u#34) 525
//        s#96 김주성(u#91) 7,350 → L1 유호웅(u#34) 1,470 / L2 연이(u#2) 735
//        s#97 방승훈(u#33) 3,000 → L1 연이(u#2) 600 / L2 QTA엔젤(u#1) 300
//        s#98 이현우(u#93) 750 → L1 신운호(u#54) 150 / L2 강인팔(u#44 솔밧) 75
//
//   B) DOWNSTREAM (아래로): 5명 각자가 자기 하부 회원의 5/13 데일리에서 매칭 수령
//      5명 user_id IN (38,40,91,33,93) 를 referrer 로 두는 하부 회원 트리 탐색
//      그들의 staking 5/13 daily_rewards 행 SUM → × 20% (L1) / × 10% (L2) → 5명 본인에게 INSERT
//
// 안전장치 (이중지급 절대 금지):
//   - 신규 ref_id 패턴: bf_513_up_s<sid>_l1|l2 (UPSTREAM), bf_513_down_u<uid>_l1|l2 (DOWNSTREAM)
//   - 3중 EXISTS 가드: ref_id + (user_id, type, amount, KST date) + referral_rewards
//   - 5/13 KST 같은 user_id+amount+type 의 transactions 가 이미 있으면 SKIP (cron/다른 백필이 박은 경우 대비)
// ============================================================
app.get('/api/diag/exec-513-bidirectional-matching', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: '관리자 인증이 필요합니다' }, 401)
  const dep = assertNotDeprecated(c, 'exec-513-bidirectional-matching', '5/13 양방향 매칭 보정 완료. safeInsertTransaction 가드 미적용 → 재호출 시 이중지급 위험')
  if (dep) return dep
  const confirm = c.req.query('confirm') || ''
  const isExec = confirm === 'GO'

  try {
    const db = c.env.DB
    const TARGET_DATE = '2026-05-13'
    const PAID_DATE = '2026-05-13'
    const HOLIDAY_910_STAKINGS = [94, 95, 96, 97, 98]

    // ============================================================
    // PART A — UPSTREAM (위로): 5명의 self 데일리로 인한 상위 매칭
    // ============================================================
    const upstreamPreview: any[] = []
    let upstreamTotalL1 = 0
    let upstreamTotalL2 = 0

    for (const sid of HOLIDAY_910_STAKINGS) {
      const s = await db.prepare(`
        SELECT s.id, s.user_id, s.amount, s.daily_rate,
               u.name AS user_name, u.email AS user_email, u.referrer_id
        FROM staking s JOIN users u ON s.user_id = u.id
        WHERE s.id = ? AND s.status = 'active'
      `).bind(sid).first() as any
      if (!s) continue

      const selfQkey = Math.round(Number(s.amount) * Number(s.daily_rate) * 150)

      let l1UserId: number | null = null, l2UserId: number | null = null
      let l1Name = '', l2Name = ''
      if (s.referrer_id) {
        const l1u = await db.prepare(`SELECT id, name, referrer_id FROM users WHERE id = ?`).bind(s.referrer_id).first() as any
        if (l1u) {
          l1UserId = l1u.id; l1Name = l1u.name
          if (l1u.referrer_id) {
            const l2u = await db.prepare(`SELECT id, name FROM users WHERE id = ?`).bind(l1u.referrer_id).first() as any
            if (l2u) { l2UserId = l2u.id; l2Name = l2u.name }
          }
        }
      }
      const l1Qkey = l1UserId ? Math.round(selfQkey * 0.20) : 0
      const l2Qkey = l2UserId ? Math.round(selfQkey * 0.10) : 0

      // 안전 체크
      const refIdL1 = `bf_513_up_s${sid}_l1`
      const refIdL2 = `bf_513_up_s${sid}_l2`
      const exRefL1 = l1UserId ? await db.prepare(`SELECT id FROM transactions WHERE ref_id = ? LIMIT 1`).bind(refIdL1).first() : null
      const exRefL2 = l2UserId ? await db.prepare(`SELECT id FROM transactions WHERE ref_id = ? LIMIT 1`).bind(refIdL2).first() : null
      const exSameL1 = l1UserId ? await db.prepare(`
        SELECT id FROM transactions
        WHERE user_id = ? AND type = 'referral_reward' AND coin_type = 'QKEY' AND amount = ?
          AND date(datetime(created_at, '+9 hours')) = ?
        LIMIT 1
      `).bind(l1UserId, l1Qkey, TARGET_DATE).first() : null
      const exSameL2 = l2UserId ? await db.prepare(`
        SELECT id FROM transactions
        WHERE user_id = ? AND type = 'referral_reward' AND coin_type = 'QKEY' AND amount = ?
          AND date(datetime(created_at, '+9 hours')) = ?
        LIMIT 1
      `).bind(l2UserId, l2Qkey, TARGET_DATE).first() : null

      upstreamPreview.push({
        from_staking: sid, from_user_id: s.user_id, from_user_name: s.user_name,
        self_qkey: selfQkey,
        l1: l1UserId ? { user_id: l1UserId, name: l1Name, qkey: l1Qkey,
          ref_exists: !!exRefL1, same_amount_513_exists: !!exSameL1,
          will_insert: !exRefL1 && !exSameL1 } : null,
        l2: l2UserId ? { user_id: l2UserId, name: l2Name, qkey: l2Qkey,
          ref_exists: !!exRefL2, same_amount_513_exists: !!exSameL2,
          will_insert: !exRefL2 && !exSameL2 } : null,
      })

      if (l1UserId && !exRefL1 && !exSameL1) upstreamTotalL1 += l1Qkey
      if (l2UserId && !exRefL2 && !exSameL2) upstreamTotalL2 += l2Qkey
    }

    // ============================================================
    // PART B — DOWNSTREAM (아래로): 5명 본인이 받는 매칭
    //   5명 user_id IN (38,40,91,33,93) 를 referrer 로 두는 회원 트리
    //   - 직접 하부(L1): WHERE users.referrer_id IN (5명)
    //   - 2단 하부(L2): WHERE users.referrer_id IN (L1 회원 list)
    //   - 각 하부 회원의 5/13 daily_rewards SUM → × 20% (L1) / × 10% (L2)
    // ============================================================
    const HOLIDAY_910_USERS = [38, 40, 91, 33, 93]
    const downstreamPreview: any[] = []
    let downstreamTotalL1 = 0
    let downstreamTotalL2 = 0

    for (const uid of HOLIDAY_910_USERS) {
      const u = await db.prepare(`SELECT id, name, email FROM users WHERE id = ?`).bind(uid).first() as any

      // L1 하부 (uid 의 직접 추천)
      const l1Children = await db.prepare(`SELECT id, name FROM users WHERE referrer_id = ?`).bind(uid).all()
      const l1ChildIds: number[] = (l1Children.results || []).map((x: any) => Number(x.id))

      // L2 하부 (L1 회원들의 추천)
      let l2ChildIds: number[] = []
      if (l1ChildIds.length > 0) {
        const placeholders = l1ChildIds.map(() => '?').join(',')
        const l2Children = await db.prepare(`SELECT id FROM users WHERE referrer_id IN (${placeholders})`).bind(...l1ChildIds).all()
        l2ChildIds = (l2Children.results || []).map((x: any) => Number(x.id))
      }

      // L1 하부 5/13 daily_rewards SUM
      let l1DailySum = 0
      const l1Details: any[] = []
      if (l1ChildIds.length > 0) {
        const placeholders = l1ChildIds.map(() => '?').join(',')
        const rows = await db.prepare(`
          SELECT user_id, staking_id, usdt_amount
          FROM daily_rewards
          WHERE user_id IN (${placeholders}) AND reward_date = ?
        `).bind(...l1ChildIds, TARGET_DATE).all()
        for (const r of (rows.results || []) as any[]) {
          l1DailySum += Number(r.usdt_amount)
          l1Details.push({ user_id: r.user_id, staking_id: r.staking_id, daily_qkey: r.usdt_amount })
        }
      }

      // L2 하부 5/13 daily_rewards SUM
      let l2DailySum = 0
      const l2Details: any[] = []
      if (l2ChildIds.length > 0) {
        const placeholders = l2ChildIds.map(() => '?').join(',')
        const rows = await db.prepare(`
          SELECT user_id, staking_id, usdt_amount
          FROM daily_rewards
          WHERE user_id IN (${placeholders}) AND reward_date = ?
        `).bind(...l2ChildIds, TARGET_DATE).all()
        for (const r of (rows.results || []) as any[]) {
          l2DailySum += Number(r.usdt_amount)
          l2Details.push({ user_id: r.user_id, staking_id: r.staking_id, daily_qkey: r.usdt_amount })
        }
      }

      const myL1Bonus = Math.round(l1DailySum * 0.20)
      const myL2Bonus = Math.round(l2DailySum * 0.10)

      // 안전 체크
      const refIdL1 = `bf_513_down_u${uid}_l1`
      const refIdL2 = `bf_513_down_u${uid}_l2`
      const exRefL1 = myL1Bonus > 0 ? await db.prepare(`SELECT id FROM transactions WHERE ref_id = ? LIMIT 1`).bind(refIdL1).first() : null
      const exRefL2 = myL2Bonus > 0 ? await db.prepare(`SELECT id FROM transactions WHERE ref_id = ? LIMIT 1`).bind(refIdL2).first() : null
      const exSameL1 = myL1Bonus > 0 ? await db.prepare(`
        SELECT id FROM transactions
        WHERE user_id = ? AND type = 'referral_reward' AND coin_type = 'QKEY' AND amount = ?
          AND date(datetime(created_at, '+9 hours')) = ?
        LIMIT 1
      `).bind(uid, myL1Bonus, TARGET_DATE).first() : null
      const exSameL2 = myL2Bonus > 0 ? await db.prepare(`
        SELECT id FROM transactions
        WHERE user_id = ? AND type = 'referral_reward' AND coin_type = 'QKEY' AND amount = ?
          AND date(datetime(created_at, '+9 hours')) = ?
        LIMIT 1
      `).bind(uid, myL2Bonus, TARGET_DATE).first() : null

      downstreamPreview.push({
        user_id: uid, user_name: u?.name, user_email: u?.email,
        l1_child_count: l1ChildIds.length, l1_child_ids: l1ChildIds,
        l2_child_count: l2ChildIds.length, l2_child_ids: l2ChildIds,
        l1_downstream_daily_sum: l1DailySum, l1_details: l1Details,
        l2_downstream_daily_sum: l2DailySum, l2_details: l2Details,
        my_l1_bonus_qkey: myL1Bonus,
        my_l2_bonus_qkey: myL2Bonus,
        l1_ref_exists: !!exRefL1, l1_same_amount_513_exists: !!exSameL1,
        l1_will_insert: myL1Bonus > 0 && !exRefL1 && !exSameL1,
        l2_ref_exists: !!exRefL2, l2_same_amount_513_exists: !!exSameL2,
        l2_will_insert: myL2Bonus > 0 && !exRefL2 && !exSameL2,
      })

      if (myL1Bonus > 0 && !exRefL1 && !exSameL1) downstreamTotalL1 += myL1Bonus
      if (myL2Bonus > 0 && !exRefL2 && !exSameL2) downstreamTotalL2 += myL2Bonus
    }

    if (!isExec) {
      return c.json({
        success: true, mode: 'DRY_RUN', target_date: TARGET_DATE,
        upstream: {
          target_stakings: HOLIDAY_910_STAKINGS,
          preview: upstreamPreview,
          total_l1_to_insert: upstreamTotalL1,
          total_l2_to_insert: upstreamTotalL2,
        },
        downstream: {
          target_users: HOLIDAY_910_USERS,
          preview: downstreamPreview,
          total_l1_to_insert: downstreamTotalL1,
          total_l2_to_insert: downstreamTotalL2,
        },
        grand_total_to_insert: upstreamTotalL1 + upstreamTotalL2 + downstreamTotalL1 + downstreamTotalL2,
        next: '실행하려면 ?confirm=GO 추가',
      })
    }

    // ====================== EXEC ======================
    const inserted: any[] = []
    const skipped: any[] = []
    let actualUpL1 = 0, actualUpL2 = 0, actualDownL1 = 0, actualDownL2 = 0

    // UPSTREAM INSERT
    for (const p of upstreamPreview as any[]) {
      const sid = p.from_staking
      const fromUid = p.from_user_id

      if (p.l1 && p.l1.will_insert) {
        const refIdL1 = `bf_513_up_s${sid}_l1`
        await db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
          VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?)
        `).bind(p.l1.user_id, p.l1.qkey, '추천 보너스 (Level 1)', refIdL1).run()
        await db.prepare(`UPDATE users SET qkey_balance = COALESCE(qkey_balance,0) + ? WHERE id = ?`).bind(p.l1.qkey, p.l1.user_id).run()
        try {
          await db.prepare(`
            INSERT INTO referral_rewards (user_id, from_user_id, level, amount, coin_type, reward_date, paid_date, ref_id, created_at)
            VALUES (?, ?, 1, ?, 'QKEY', ?, ?, ?, datetime('now'))
          `).bind(p.l1.user_id, fromUid, p.l1.qkey, TARGET_DATE, PAID_DATE, refIdL1).run()
        } catch(e) {}
        actualUpL1 += p.l1.qkey
        inserted.push({ direction: 'UPSTREAM', from_staking: sid, user_id: p.l1.user_id, name: p.l1.name, level: 1, qkey: p.l1.qkey })
      } else if (p.l1) {
        skipped.push({ direction: 'UPSTREAM', from_staking: sid, user_id: p.l1.user_id, level: 1, reason: p.l1.ref_exists ? 'ref_exists' : 'same_amount_513_exists' })
      }

      if (p.l2 && p.l2.will_insert) {
        const refIdL2 = `bf_513_up_s${sid}_l2`
        await db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
          VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?)
        `).bind(p.l2.user_id, p.l2.qkey, '추천 보너스 (Level 2)', refIdL2).run()
        await db.prepare(`UPDATE users SET qkey_balance = COALESCE(qkey_balance,0) + ? WHERE id = ?`).bind(p.l2.qkey, p.l2.user_id).run()
        try {
          await db.prepare(`
            INSERT INTO referral_rewards (user_id, from_user_id, level, amount, coin_type, reward_date, paid_date, ref_id, created_at)
            VALUES (?, ?, 2, ?, 'QKEY', ?, ?, ?, datetime('now'))
          `).bind(p.l2.user_id, fromUid, p.l2.qkey, TARGET_DATE, PAID_DATE, refIdL2).run()
        } catch(e) {}
        actualUpL2 += p.l2.qkey
        inserted.push({ direction: 'UPSTREAM', from_staking: sid, user_id: p.l2.user_id, name: p.l2.name, level: 2, qkey: p.l2.qkey })
      } else if (p.l2) {
        skipped.push({ direction: 'UPSTREAM', from_staking: sid, user_id: p.l2.user_id, level: 2, reason: p.l2.ref_exists ? 'ref_exists' : 'same_amount_513_exists' })
      }
    }

    // DOWNSTREAM INSERT (5명 본인이 받는 매칭)
    for (const p of downstreamPreview as any[]) {
      const uid = p.user_id

      if (p.l1_will_insert) {
        const refIdL1 = `bf_513_down_u${uid}_l1`
        await db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
          VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?)
        `).bind(uid, p.my_l1_bonus_qkey, '추천 보너스 (Level 1)', refIdL1).run()
        await db.prepare(`UPDATE users SET qkey_balance = COALESCE(qkey_balance,0) + ? WHERE id = ?`).bind(p.my_l1_bonus_qkey, uid).run()
        actualDownL1 += p.my_l1_bonus_qkey
        inserted.push({ direction: 'DOWNSTREAM', user_id: uid, name: p.user_name, level: 1, qkey: p.my_l1_bonus_qkey })
      } else if (p.my_l1_bonus_qkey > 0) {
        skipped.push({ direction: 'DOWNSTREAM', user_id: uid, level: 1, reason: p.l1_ref_exists ? 'ref_exists' : 'same_amount_513_exists' })
      }

      if (p.l2_will_insert) {
        const refIdL2 = `bf_513_down_u${uid}_l2`
        await db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
          VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?)
        `).bind(uid, p.my_l2_bonus_qkey, '추천 보너스 (Level 2)', refIdL2).run()
        await db.prepare(`UPDATE users SET qkey_balance = COALESCE(qkey_balance,0) + ? WHERE id = ?`).bind(p.my_l2_bonus_qkey, uid).run()
        actualDownL2 += p.my_l2_bonus_qkey
        inserted.push({ direction: 'DOWNSTREAM', user_id: uid, name: p.user_name, level: 2, qkey: p.my_l2_bonus_qkey })
      } else if (p.my_l2_bonus_qkey > 0) {
        skipped.push({ direction: 'DOWNSTREAM', user_id: uid, level: 2, reason: p.l2_ref_exists ? 'ref_exists' : 'same_amount_513_exists' })
      }
    }

    return c.json({
      success: true, mode: 'EXEC', target_date: TARGET_DATE,
      inserted_count: inserted.length, skipped_count: skipped.length,
      sums: {
        upstream_l1_inserted: actualUpL1,
        upstream_l2_inserted: actualUpL2,
        downstream_l1_inserted: actualDownL1,
        downstream_l2_inserted: actualDownL2,
        grand_total: actualUpL1 + actualUpL2 + actualDownL1 + actualDownL2,
      },
      inserted, skipped,
    })
  } catch (error: any) {
    console.error('exec-513-bidirectional-matching error:', error)
    return c.json({ error: error?.message || String(error) }, 500)
  }
})

// ============================================================
// /api/diag/cleanup-513-bidirectional-duplicates
// ------------------------------------------------------------
// 2026-05-13 사장님 발견: 김용선(u#38) 5/13 12:38 추천 보너스 L1 1,050 QKEY 2회 중복
// 원인: PHASE 3 양방향 매칭이 UPSTREAM (bf_513_up_s95_l1) 과 DOWNSTREAM (bf_513_down_u38_l1)
//       두 경로에서 동일 user_id 에 동일 금액을 INSERT.
//       exSameL1 안전 체크가 첫 UPSTREAM INSERT 직후의 같은 요청 내 DOWNSTREAM 검사에서
//       이미 INSERT 된 row 를 못 잡은 것으로 추정 (혹은 두 ref_id 가 달라서 양쪽 다 통과).
//
// 동작:
//   1) bf_513_up_*  +  bf_513_down_*  ref_id 로 INSERT 된 모든 row 조회
//   2) (user_id, type, amount, KST date='2026-05-13') 로 묶어 카운트
//   3) 같은 그룹에 2개 이상 있으면 → 1개만 남기고 나머지 DELETE + 잔액 차감
//
// dry-run (default) 결과 사장님 확인 후 ?confirm=GO 로 실제 정리.
// ============================================================
app.get('/api/diag/cleanup-513-bidirectional-duplicates', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: '관리자 인증이 필요합니다' }, 401)
  const confirm = c.req.query('confirm') || ''
  const isExec = confirm === 'GO'

  try {
    const db = c.env.DB
    const TARGET_DATE = '2026-05-13'

    // STEP 1: PHASE 3 에서 INSERT 한 모든 transactions row 조회
    //   ref_id LIKE 'bf_513_up_%' OR ref_id LIKE 'bf_513_down_%'
    const phase3Rows = await db.prepare(`
      SELECT id, user_id, type, coin_type, amount, description, ref_id,
             created_at,
             date(datetime(created_at, '+9 hours')) AS kst_date
      FROM transactions
      WHERE (ref_id LIKE 'bf_513_up_%' OR ref_id LIKE 'bf_513_down_%')
      ORDER BY user_id ASC, amount ASC, id ASC
    `).all()

    const allRows = (phase3Rows.results as any[]) || []

    // STEP 2: (user_id, type, amount, kst_date) 그룹별 묶기
    const groups = new Map<string, any[]>()
    for (const r of allRows) {
      const k = `${r.user_id}|${r.type}|${r.amount}|${r.kst_date}`
      if (!groups.has(k)) groups.set(k, [])
      groups.get(k)!.push(r)
    }

    // STEP 3: 2개 이상 있는 그룹 = 중복
    const duplicateGroups: any[] = []
    let totalRowsToDelete = 0
    let totalQkeyToReclaim = 0
    const reclaimByUser: Record<number, number> = {}

    for (const [k, rows] of groups.entries()) {
      if (rows.length < 2) continue
      // 가장 작은 id 1개를 KEEP, 나머지는 DELETE 대상
      rows.sort((a: any, b: any) => a.id - b.id)
      const keep = rows[0]
      const toDelete = rows.slice(1)
      const sumDeleted = toDelete.reduce((s: number, r: any) => s + Number(r.amount), 0)

      duplicateGroups.push({
        group_key: k,
        user_id: rows[0].user_id,
        type: rows[0].type,
        amount: rows[0].amount,
        kst_date: rows[0].kst_date,
        total_rows: rows.length,
        keep_row: { id: keep.id, ref_id: keep.ref_id, created_at: keep.created_at },
        delete_rows: toDelete.map((r: any) => ({
          id: r.id, ref_id: r.ref_id, created_at: r.created_at, amount: r.amount
        })),
        qkey_to_reclaim: sumDeleted,
      })

      totalRowsToDelete += toDelete.length
      totalQkeyToReclaim += sumDeleted
      reclaimByUser[rows[0].user_id] = (reclaimByUser[rows[0].user_id] || 0) + sumDeleted
    }

    // 회원별 사용자 이름 join
    const userIds = Object.keys(reclaimByUser).map(Number)
    const userInfo: Record<number, any> = {}
    if (userIds.length > 0) {
      const placeholders = userIds.map(() => '?').join(',')
      const usersRows = await db.prepare(
        `SELECT id, name, email, qkey_balance FROM users WHERE id IN (${placeholders})`
      ).bind(...userIds).all()
      for (const u of (usersRows.results as any[])) {
        userInfo[u.id] = { name: u.name, email: u.email, qkey_balance_current: u.qkey_balance }
      }
    }

    const reclaimSummary = userIds.map(uid => ({
      user_id: uid,
      ...(userInfo[uid] || {}),
      qkey_to_reclaim: reclaimByUser[uid],
      qkey_balance_after: (userInfo[uid]?.qkey_balance_current || 0) - reclaimByUser[uid],
    }))

    if (!isExec) {
      return c.json({
        success: true,
        mode: 'DRY_RUN',
        target_date: TARGET_DATE,
        phase3_total_rows: allRows.length,
        duplicate_group_count: duplicateGroups.length,
        total_rows_to_delete: totalRowsToDelete,
        total_qkey_to_reclaim: totalQkeyToReclaim,
        reclaim_summary: reclaimSummary,
        duplicate_groups: duplicateGroups,
        next: '실제 정리하려면 ?confirm=GO 추가',
      })
    }

    // ====================== EXEC ======================
    const deletedRows: any[] = []
    const balanceUpdates: any[] = []

    for (const g of duplicateGroups) {
      for (const r of g.delete_rows) {
        await db.prepare(`DELETE FROM transactions WHERE id = ?`).bind(r.id).run()
        // referral_rewards 도 같은 ref_id 로 연동되어 있으면 함께 삭제
        try {
          await db.prepare(`DELETE FROM referral_rewards WHERE ref_id = ?`).bind(r.ref_id).run()
        } catch(e) {}
        deletedRows.push({ tx_id: r.id, ref_id: r.ref_id, user_id: g.user_id, amount: r.amount })
      }
      // 잔액 차감
      await db.prepare(`UPDATE users SET qkey_balance = COALESCE(qkey_balance,0) - ? WHERE id = ?`)
        .bind(g.qkey_to_reclaim, g.user_id).run()
      balanceUpdates.push({ user_id: g.user_id, deducted: g.qkey_to_reclaim })
    }

    // 정리 후 재검증
    const afterRows = await db.prepare(`
      SELECT user_id, type, amount,
             date(datetime(created_at, '+9 hours')) AS kst_date,
             COUNT(*) AS cnt
      FROM transactions
      WHERE (ref_id LIKE 'bf_513_up_%' OR ref_id LIKE 'bf_513_down_%')
      GROUP BY user_id, type, amount, kst_date
      HAVING COUNT(*) > 1
    `).all()
    const remainingDuplicates = (afterRows.results as any[]) || []

    return c.json({
      success: true,
      mode: 'EXEC',
      target_date: TARGET_DATE,
      deleted_count: deletedRows.length,
      total_qkey_reclaimed: totalQkeyToReclaim,
      balance_updates: balanceUpdates,
      deleted_rows: deletedRows,
      reclaim_summary: reclaimSummary,
      remaining_duplicates_after: remainingDuplicates.length,
      remaining_duplicates_detail: remainingDuplicates,
      verification: remainingDuplicates.length === 0
        ? '✅ 모든 중복 정리 완료'
        : '⚠ 잔여 중복 발견 — 수동 점검 필요',
    })
  } catch (error: any) {
    console.error('cleanup-513-bidirectional-duplicates error:', error)
    return c.json({ error: error?.message || String(error) }, 500)
  }
})

// ============================================================
// /api/diag/fix-512-s97-self-orphan
// ----------------------------------------------------
// s#97 방승훈 (u#33) 5/12 self 데일리 부분 INSERT 보정:
//   - daily_rewards: 5/12 3,000 QKEY 행 존재 (id=확인됨, 첫 timeout 시 INSERT 성공)
//   - transactions: 누락 (status 컬럼 에러로 실패)
//   - users.qkey_balance: 미반영 (현재 4,500 그대로)
// 보정: transactions INSERT (영구룰 #112 한국어) + 잔액 +3,000 UPDATE
// dedupe: ref_id 'fix_512_s97_self' UNIQUE
// ============================================================
app.get('/api/diag/fix-512-s97-self-orphan', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: '관리자 인증이 필요합니다' }, 401)
  const dep = assertNotDeprecated(c, 'fix-512-s97-self-orphan', 's97 self orphan 5/12 보정 완료. safeInsertTransaction 가드 미적용 → 재호출 시 이중지급 위험')
  if (dep) return dep
  const confirm = c.req.query('confirm') || ''
  const isExec = confirm === 'GO'

  try {
    const db = c.env.DB
    const UID = 33
    const SID = 97
    const QKEY = 3000
    const REF_ID = 'fix_512_s97_self'
    const TARGET_DATE = '2026-05-12'

    // 사전 검증
    const dr = await db.prepare(`SELECT id, usdt_amount FROM daily_rewards WHERE staking_id = ? AND reward_date = ?`).bind(SID, TARGET_DATE).first() as any
    const txExists = await db.prepare(`SELECT id FROM transactions WHERE ref_id = ? LIMIT 1`).bind(REF_ID).first() as any
    const u = await db.prepare(`SELECT id, name, qkey_balance FROM users WHERE id = ?`).bind(UID).first() as any

    const preview = {
      user: u,
      daily_rewards_row: dr,
      tx_already_inserted: txExists ? true : false,
      qkey_balance_before: u?.qkey_balance,
      qkey_to_add: QKEY,
      qkey_balance_after_expected: (u?.qkey_balance || 0) + QKEY,
    }

    if (!isExec) {
      return c.json({ success: true, mode: 'DRY_RUN', preview, next: '?confirm=GO' })
    }

    if (txExists) {
      return c.json({ success: true, mode: 'SKIP', reason: 'ref_id 이미 INSERT 됨', preview })
    }
    if (!dr) {
      return c.json({ success: false, error: 'daily_rewards 행 없음 — s#97 5/12 행 누락', preview }, 400)
    }

    // 실행
    await db.prepare(`
      INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
      VALUES (?, 'daily_reward', 'QKEY', ?, ?, ?)
    `).bind(UID, QKEY, '일일 배당 (QKEY)', REF_ID).run()

    await db.prepare(`UPDATE users SET qkey_balance = COALESCE(qkey_balance,0) + ? WHERE id = ?`).bind(QKEY, UID).run()

    const after = await db.prepare(`SELECT qkey_balance FROM users WHERE id = ?`).bind(UID).first() as any
    return c.json({
      success: true,
      mode: 'EXEC',
      inserted: { tx_ref_id: REF_ID, amount: QKEY },
      qkey_balance_before: u?.qkey_balance,
      qkey_balance_after: after?.qkey_balance,
    })
  } catch (error: any) {
    console.error('fix-512-s97-self-orphan error:', error)
    return c.json({ error: error?.message || String(error) }, 500)
  }
})

// ============================================================
// /api/diag/audit-511-referral-duplicate
// ----------------------------------------------------
// 사장님 명령 (2026-05-12): 김용선 5/11 추천보너스 2회 표시됨 → 1회만 정상
// 전수조사: 5/11 같은 user_id+level+from_user_id 중복 transactions 또는 referral_rewards
// ============================================================
app.get('/api/diag/audit-511-referral-duplicate', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: '관리자 인증이 필요합니다' }, 401)

  try {
    const db = c.env.DB
    const TARGET_DATE = '2026-05-11'

    // 5/11 referral_reward transactions 전수
    const txs = await db.prepare(`
      SELECT t.id, t.user_id, t.type, t.amount, t.description, t.ref_id, t.created_at,
             date(datetime(t.created_at, '+9 hours')) AS kst_date,
             u.name AS user_name, u.email AS user_email
      FROM transactions t
      JOIN users u ON t.user_id = u.id
      WHERE t.type IN ('referral_reward','direct_referral')
        AND date(datetime(t.created_at, '+9 hours')) = ?
      ORDER BY t.user_id, t.id
    `).bind(TARGET_DATE).all()

    // user_id + amount 동일 중복 그룹
    const groups: Record<string, any[]> = {}
    for (const t of (txs.results || []) as any[]) {
      const k = `u${t.user_id}_amt${t.amount}_desc${t.description}`
      if (!groups[k]) groups[k] = []
      groups[k].push(t)
    }

    const duplicates: any[] = []
    for (const k of Object.keys(groups)) {
      if (groups[k].length >= 2) duplicates.push({ key: k, count: groups[k].length, rows: groups[k] })
    }

    // referral_rewards 테이블도 점검
    let rrRows: any[] = []
    try {
      const rr = await db.prepare(`
        SELECT id, user_id, from_user_id, level, amount, coin_type, reward_date, paid_date, ref_id, created_at
        FROM referral_rewards
        WHERE reward_date = ? OR paid_date = ? OR date(datetime(created_at, '+9 hours')) = ?
        ORDER BY user_id, id
      `).bind(TARGET_DATE, TARGET_DATE, TARGET_DATE).all()
      rrRows = (rr.results || []) as any[]
    } catch(e) {}

    const rrGroups: Record<string, any[]> = {}
    for (const r of rrRows) {
      const k = `u${r.user_id}_from${r.from_user_id}_lvl${r.level}_amt${r.amount}`
      if (!rrGroups[k]) rrGroups[k] = []
      rrGroups[k].push(r)
    }
    const rrDuplicates: any[] = []
    for (const k of Object.keys(rrGroups)) {
      if (rrGroups[k].length >= 2) rrDuplicates.push({ key: k, count: rrGroups[k].length, rows: rrGroups[k] })
    }

    return c.json({
      success: true,
      target_date: TARGET_DATE,
      transactions_total: (txs.results || []).length,
      transactions_duplicate_groups: duplicates.length,
      transactions_duplicates: duplicates,
      referral_rewards_total: rrRows.length,
      referral_rewards_duplicate_groups: rrDuplicates.length,
      referral_rewards_duplicates: rrDuplicates,
    })
  } catch (error: any) {
    console.error('audit-511-referral-duplicate error:', error)
    return c.json({ error: error?.message || String(error) }, 500)
  }
})

// ============================================================
// /api/diag/user-tx-trace
// ----------------------------------------------------
// 사장님 명령 (2026-05-12): 정분 등 특정 회원 전체 거래내역 + 코인별 누적합 추적
// ============================================================
app.get('/api/diag/user-tx-trace', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: '관리자 인증이 필요합니다' }, 401)

  try {
    const db = c.env.DB
    const uid = parseInt(c.req.query('user_id') || '0', 10)
    if (!uid) return c.json({ error: 'user_id 파라미터 필수' }, 400)

    const u = await db.prepare(`SELECT id, name, email, qkey_balance, qx_balance, qta_balance, usdt_balance FROM users WHERE id = ?`).bind(uid).first() as any
    if (!u) return c.json({ error: '사용자 없음' }, 404)

    const txs = await db.prepare(`
      SELECT id, type, coin_type, amount, description, ref_id, created_at,
             date(datetime(created_at, '+9 hours')) AS kst_date
      FROM transactions WHERE user_id = ? ORDER BY id ASC
    `).bind(uid).all()

    const rows = (txs.results || []) as any[]
    const running: Record<string, number> = { QKEY: 0, QX: 0, QTA: 0, USDT: 0 }
    const trail: any[] = []
    for (const r of rows) {
      const ct = r.coin_type
      if (ct && running[ct] !== undefined) running[ct] += Number(r.amount) || 0
      trail.push({
        id: r.id, type: r.type, coin: r.coin_type, amount: r.amount, desc: r.description,
        ref_id: r.ref_id, created: r.created_at, kst_date: r.kst_date,
        running_qkey: running.QKEY, running_qx: running.QX, running_qta: running.QTA, running_usdt: running.USDT,
      })
    }

    return c.json({
      success: true,
      user: u,
      tx_count: rows.length,
      final_sums: running,
      balance_vs_sum: {
        qkey: { balance: u.qkey_balance, sum: running.QKEY, diff: (Number(u.qkey_balance)||0) - running.QKEY },
        qx: { balance: u.qx_balance, sum: running.QX, diff: (Number(u.qx_balance)||0) - running.QX },
        qta: { balance: u.qta_balance, sum: running.QTA, diff: (Number(u.qta_balance)||0) - running.QTA },
        usdt: { balance: u.usdt_balance, sum: running.USDT, diff: (Number(u.usdt_balance)||0) - running.USDT },
      },
      trail,
    })
  } catch (error: any) {
    console.error('user-tx-trace error:', error)
    return c.json({ error: error?.message || String(error) }, 500)
  }
})

// ============================================================
// /api/diag/audit-balance-vs-tx-mismatch
// ----------------------------------------------------
// 사장님 명령 (2026-05-12): 정분 등 스왑 후 잔액 불일치 전수조사
// 전수: 모든 user의 거래내역 합산 vs users.qkey_balance / qx_balance / qta_balance / usdt_balance
// ============================================================
app.get('/api/diag/audit-balance-vs-tx-mismatch', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: '관리자 인증이 필요합니다' }, 401)

  try {
    const db = c.env.DB
    const userIdParam = c.req.query('user_id') || ''
    const nameParam = c.req.query('name') || ''

    let users: any[] = []
    if (userIdParam) {
      const u = await db.prepare(`SELECT id, name, email, qkey_balance, qx_balance, qta_balance, usdt_balance FROM users WHERE id = ?`).bind(parseInt(userIdParam,10)).all()
      users = (u.results || []) as any[]
    } else if (nameParam) {
      const u = await db.prepare(`SELECT id, name, email, qkey_balance, qx_balance, qta_balance, usdt_balance FROM users WHERE name LIKE ? OR email LIKE ?`).bind(`%${nameParam}%`, `%${nameParam}%`).all()
      users = (u.results || []) as any[]
    } else {
      const u = await db.prepare(`SELECT id, name, email, qkey_balance, qx_balance, qta_balance, usdt_balance FROM users ORDER BY id`).all()
      users = (u.results || []) as any[]
    }

    const mismatches: any[] = []
    const ok: any[] = []

    for (const u of users) {
      // 각 코인별 거래내역 합 계산
      const sumByCoin = await db.prepare(`
        SELECT coin_type, SUM(amount) AS total
        FROM transactions
        WHERE user_id = ?
        GROUP BY coin_type
      `).bind(u.id).all()

      const sums: Record<string, number> = { QKEY: 0, QX: 0, QTA: 0, USDT: 0 }
      for (const r of (sumByCoin.results || []) as any[]) {
        if (r.coin_type) sums[r.coin_type] = Number(r.total) || 0
      }

      const diff = {
        qkey: { balance: Number(u.qkey_balance)||0, tx_sum: sums.QKEY, diff: (Number(u.qkey_balance)||0) - sums.QKEY },
        qx: { balance: Number(u.qx_balance)||0, tx_sum: sums.QX, diff: (Number(u.qx_balance)||0) - sums.QX },
        qta: { balance: Number(u.qta_balance)||0, tx_sum: sums.QTA, diff: (Number(u.qta_balance)||0) - sums.QTA },
        usdt: { balance: Number(u.usdt_balance)||0, tx_sum: sums.USDT, diff: (Number(u.usdt_balance)||0) - sums.USDT },
      }

      const hasMismatch = Math.abs(diff.qkey.diff) > 0.01 || Math.abs(diff.qx.diff) > 0.01 || Math.abs(diff.qta.diff) > 0.01 || Math.abs(diff.usdt.diff) > 0.01

      const rec = { user_id: u.id, user_name: u.name, user_email: u.email, ...diff }
      if (hasMismatch) mismatches.push(rec)
      else ok.push({ user_id: u.id, user_name: u.name })
    }

    // 절대값 큰 순으로 정렬
    mismatches.sort((a: any, b: any) => {
      const ma = Math.abs(a.qkey.diff) + Math.abs(a.qx.diff) + Math.abs(a.qta.diff) + Math.abs(a.usdt.diff)
      const mb = Math.abs(b.qkey.diff) + Math.abs(b.qx.diff) + Math.abs(b.qta.diff) + Math.abs(b.usdt.diff)
      return mb - ma
    })

    return c.json({
      success: true,
      filter: { user_id: userIdParam || null, name: nameParam || null },
      total_users_checked: users.length,
      ok_count: ok.length,
      mismatch_count: mismatches.length,
      mismatches,
    })
  } catch (error: any) {
    console.error('audit-balance-vs-tx-mismatch error:', error)
    return c.json({ error: error?.message || String(error) }, 500)
  }
})

// ============================================================
// /api/diag/solbat-513-d-plan-backfill  (2026-05-13, D안 EXEC)
// ------------------------------------------------------------
// 사장님 결재 D안: 헬퍼 referee 컨텍스트 보강 활용 → 3건 정확 백필
//
// 백필 대상 (deep-trace 결과 확정):
//   1) 이인실 (u#45, L1, s#72분) → 솔밧 +150 QKEY
//   2) 유정 (u#49, L2, s#65분)   → 솔밧 +75 QKEY
//   3) 이현우 (u#93, L2, s#98분, 5/10 휴일진입자) → 솔밧 +75 QKEY
//   총 +300 QKEY
//
// 영구룰 100% 준수:
//   - L1=20%, L2=10% (산식 검증 통과)
//   - staking.daily_rate D1 직접 (사전 검증 시 사용)
//   - description 사용자 노출 안전: '추천 보너스 (Level 1)' / '추천 보너스 (Level 2)' 만
//   - safeInsertTransaction 헬퍼 의무 사용 (D안 보강된 3중 가드)
//     1) assertNoExistingRefId
//     2) assertNoExistingPayment (refereeId + level 컨텍스트)
//     3) INSERT + balance UPDATE
//   - ref_id 패턴: 'bf_513_solbat_l{1|2}_referee{N}_s{stakingId}' — referee 컨텍스트 자동 인식
//
// 동작:
//   - DRY_RUN (default): 사전 검증만 (각 referee 의 현재 active staking 합 × ratio == 백필 amount 검증)
//   - ?confirm=GO: safeInsertTransaction 호출 + referral_rewards 원장 INSERT
// ============================================================
app.get('/api/diag/solbat-513-d-plan-backfill', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: '관리자 인증이 필요합니다' }, 401)
  const confirm = c.req.query('confirm') || ''
  const isExec = confirm === 'GO'

  try {
    const db = c.env.DB
    const SOLBAT_ID = 44
    const TARGET_DATE = '2026-05-13'

    // 백필 명단 (deep-trace 정확한 식별 결과)
    const BACKFILL_LIST = [
      {
        referee_id: 45, referee_name: '이인실', level: 1 as 1 | 2,
        amount: 150, staking_hint: 's#72 (5/5 진입, 두 번째 staking)',
        ratio: 0.20,
      },
      {
        referee_id: 49, referee_name: '유정', level: 2 as 1 | 2,
        amount: 75, staking_hint: 's#65 (5/3 진입, 두 번째 staking)',
        ratio: 0.10,
      },
      {
        referee_id: 93, referee_name: '이현우', level: 2 as 1 | 2,
        amount: 75, staking_hint: 's#98 (5/10 휴일진입자)',
        ratio: 0.10,
      },
    ]

    // STEP 0: 솔밧 잔액
    const solbat = await db.prepare(`SELECT id, name, qkey_balance FROM users WHERE id = ?`).bind(SOLBAT_ID).first() as any
    if (!solbat) return c.json({ error: 'solbat not found' }, 404)

    // STEP 1: 각 referee 의 현재 active staking 합으로 산식 검증 + 백필 금액 일치 여부
    const preflight: any[] = []
    let preflightTotalExpected = 0
    let allValid = true
    for (const t of BACKFILL_LIST) {
      // referee 의 현재 active staking 들
      const stakesRes = await db.prepare(`
        SELECT id, amount, daily_rate, status,
               date(datetime(start_date, '+9 hours')) AS start_kst_date
        FROM staking WHERE user_id = ? AND status = 'active'
        ORDER BY id ASC
      `).bind(t.referee_id).all()
      const stakes = (stakesRes.results as any[]) || []
      let totalSelfDaily = 0
      for (const s of stakes) {
        totalSelfDaily += Math.round(Number(s.amount) * Number(s.daily_rate) * 150)
      }
      const expectedMatch = Math.round(totalSelfDaily * t.ratio)

      // referee 가 솔밧이 이미 5/13 에 받은 매칭 합 (referral_rewards 원장 기준)
      const existingMatchRow = await db.prepare(`
        SELECT COALESCE(SUM(reward_amount), 0) AS sum
        FROM referral_rewards
        WHERE referrer_id = ? AND referee_id = ? AND level = ?
          AND (paid_date = ? OR reward_date = ?
               OR date(datetime(created_at, '+9 hours')) = ?)
      `).bind(SOLBAT_ID, t.referee_id, t.level, TARGET_DATE, TARGET_DATE, TARGET_DATE).first() as any
      const existingMatch = Number(existingMatchRow?.sum || 0)
      const missingMatch = expectedMatch - existingMatch
      const amountMatches = missingMatch === t.amount

      // tx 측 검증 — 이미 솔밧 받은 5/13 tx 중 같은 referee 분 있는지
      // (이론적으로 ledger 원장과 일치해야 하지만 양쪽 모두 검증)
      const txSameRefereeRows = await db.prepare(`
        SELECT id, amount, ref_id, description
        FROM transactions
        WHERE user_id = ? AND type = 'referral_reward' AND coin_type = 'QKEY'
          AND date(datetime(created_at, '+9 hours')) = ?
          AND (ref_id LIKE ? OR ref_id IN (
            SELECT id FROM referral_rewards WHERE referee_id = ? AND level = ?
          ))
      `).bind(SOLBAT_ID, TARGET_DATE, `%_referee${t.referee_id}%`, t.referee_id, t.level).all()
      const txCount = (txSameRefereeRows.results as any[])?.length || 0

      preflight.push({
        referee_id: t.referee_id, referee_name: t.referee_name,
        level: t.level, ratio: t.ratio,
        staking_hint: t.staking_hint,
        referee_active_stakes: stakes,
        referee_self_daily_qkey_total: totalSelfDaily,
        expected_match_for_solbat: expectedMatch,
        existing_match_in_ledger: existingMatch,
        missing_match_calculated: missingMatch,
        amount_to_backfill: t.amount,
        amount_matches_calculation: amountMatches,
        existing_tx_count_same_referee_513: txCount,
        ref_id_to_use: `bf_513_solbat_l${t.level}_referee${t.referee_id}`,
        description_to_use: t.level === 1 ? '추천 보너스 (Level 1)' : '추천 보너스 (Level 2)',
      })

      if (!amountMatches) allValid = false
      preflightTotalExpected += t.amount
    }

    if (!isExec) {
      return c.json({
        success: true,
        mode: 'DRY_RUN',
        target_date: TARGET_DATE,
        solbat: { id: solbat.id, name: solbat.name, qkey_balance_current: solbat.qkey_balance },
        all_preflight_valid: allValid,
        total_to_backfill: preflightTotalExpected,
        preflight,
        notes: [
          'D안 헬퍼 보강: refereeId + level 컨텍스트로 같은 amount 도 다른 referee 면 통과',
          '영구룰 L1=20%/L2=10% 산식 검증 후 일치하는 경우만 백필 실행',
          'amount_matches_calculation 가 모두 true 여야 안전',
          '실제 백필하려면 ?confirm=GO 추가',
        ]
      })
    }

    // EXEC 시 사전 검증 실패하면 차단
    if (!allValid) {
      return c.json({
        success: false,
        mode: 'EXEC_BLOCKED',
        error: '사전 검증 실패 (amount_matches_calculation false 가 있음) — 백필 차단',
        preflight,
      }, 400)
    }

    // ====================== EXEC ======================
    const inserted: any[] = []
    const skipped: any[] = []
    let actualSum = 0

    for (const t of BACKFILL_LIST) {
      const refId = `bf_513_solbat_l${t.level}_referee${t.referee_id}`
      const description = t.level === 1 ? '추천 보너스 (Level 1)' : '추천 보너스 (Level 2)'
      try {
        const res = await safeInsertTransaction(db, {
          user_id: SOLBAT_ID,
          type: 'referral_reward',
          coin_type: 'QKEY',
          amount: t.amount,
          description,
          ref_id: refId,
          kst_date: TARGET_DATE,
          updateBalance: true,
          refereeId: t.referee_id,   // D안 보강 — referee 컨텍스트 가드
          level: t.level,
        })
        // referral_rewards 원장 INSERT
        // original_amount = referee 의 누락된 staking 분 self daily (역산: amount / ratio)
        const originalAmount = Math.round(t.amount / t.ratio)
        try {
          await db.prepare(`
            INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, datetime('now'))
          `).bind(
            SOLBAT_ID, t.referee_id, t.level,
            originalAmount, t.amount,
            TARGET_DATE, TARGET_DATE,
          ).run()
        } catch(rrErr: any) {
          console.error('referral_rewards INSERT 실패 (tx 는 성공):', rrErr?.message)
        }
        actualSum += t.amount
        inserted.push({
          referee_id: t.referee_id, referee_name: t.referee_name,
          level: t.level, amount: t.amount,
          tx_id: (res as any).tx_id, ref_id: refId,
          original_amount: originalAmount,
        })
      } catch (err: any) {
        skipped.push({
          referee_id: t.referee_id, referee_name: t.referee_name,
          level: t.level, amount: t.amount,
          reason: err?.code || 'unknown',
          message: err?.message,
          match_reason: err?.match_reason,
        })
      }
    }

    // 잔액 재조회
    const after = await db.prepare(`SELECT qkey_balance FROM users WHERE id = ?`).bind(SOLBAT_ID).first() as any

    return c.json({
      success: true,
      mode: 'EXEC',
      target_date: TARGET_DATE,
      solbat_balance_before: solbat.qkey_balance,
      solbat_balance_after: after?.qkey_balance,
      delta: (after?.qkey_balance || 0) - solbat.qkey_balance,
      inserted_count: inserted.length,
      skipped_count: skipped.length,
      actual_backfill_sum: actualSum,
      inserted,
      skipped,
      note: 'D안 — refereeId 컨텍스트 가드로 정확히 3건 분해 INSERT 시도. 영구룰 #이중지급 절대 금지 준수',
    })
  } catch (error: any) {
    console.error('solbat-513-d-plan-backfill error:', error)
    return c.json({ error: error?.message || String(error), code: error?.code }, 500)
  }
})

// ============================================================
// /api/diag/solbat-513-g-plan-backfill  (2026-05-13, G안 EXEC)
// ------------------------------------------------------------
// 사장님 결재 I안 (G+H 모두) 의 G 단계:
//   D안에서 이현우(u#93) +75 는 성공했으나 이인실(u#45)/유정(u#49) 은
//   "rr_ledger_referee_match" 로 차단됨. 원인: 같은 referee 의 첫 staking 이
//   이미 ledger 에 들어가 있어 broad 가드가 차단 — referee 의 두 번째 staking
//   분이 누락된 정당한 백필.
//
// G plan 접근:
//   - helper 의 stakingOriginalAmount 파라미터 활용 (방금 보강)
//   - referee 의 active staking 들의 self_daily 리스트 산출
//   - 이미 ledger 에 들어간 original_amount 들과 차집합 → 누락된 staking 식별
//   - ref_id 패턴: 'bf_513_solbat_l{level}_referee{N}_s{stakingId}' (staking_id 포함)
//   - safeInsertTransaction(..., stakingOriginalAmount: stake.self_daily) → 가드 통과
//
// 영구룰 100% 준수:
//   - L1=20%, L2=10% (산식 검증 통과)
//   - staking.daily_rate D1 직접 조회 (각 staking 별)
//   - description 사용자 노출 안전: '추천 보너스 (Level 1/2)'
//   - safeInsertTransaction 헬퍼 의무 사용 (G plan 보강된 4중 가드)
//   - #이중지급 절대 금지 — 같은 staking 분 백필되면 ledger.original_amount 일치로 차단
//
// 백필 대상 (D안 잔여):
//   1) 이인실 (u#45, L1) → 솔밧 +150 QKEY (s#72 분, 이미 s#71 은 ledger 에)
//   2) 유정   (u#49, L2) → 솔밧  +75 QKEY (s#65 분, 이미 s#64 는 ledger 에)
//   합계: +225 QKEY → 솔밧 123,750 → 123,975
//
// 동작:
//   - DRY_RUN (default): 누락 staking 정확 식별 + 영구룰 산식 검증
//   - ?confirm=GO: safeInsertTransaction + referral_rewards 원장 INSERT
// ============================================================
app.get('/api/diag/solbat-513-g-plan-backfill', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: '관리자 인증이 필요합니다' }, 401)
  const confirm = c.req.query('confirm') || ''
  const isExec = confirm === 'GO'

  try {
    const db = c.env.DB
    const SOLBAT_ID = 44
    const TARGET_DATE = '2026-05-13'

    // ── G2-B (2026-05-13): referral_rewards.staking_id 컬럼 idempotent ALTER ──
    // migrations/0014 의 ALTER 를 production 에 자동 적용 (이미 있으면 catch 로 silent skip)
    let stakingIdColAdded = false
    let stakingIdColExisted = false
    try {
      const pragmaRes = await db.prepare(`PRAGMA table_info(referral_rewards)`).all()
      const cols = ((pragmaRes.results as any[]) || []).map((r: any) => r.name)
      stakingIdColExisted = cols.includes('staking_id')
      if (!stakingIdColExisted) {
        await db.prepare(`ALTER TABLE referral_rewards ADD COLUMN staking_id INTEGER`).run()
        // 인덱스도 idempotent 생성
        try { await db.prepare(`CREATE INDEX IF NOT EXISTS idx_referral_rewards_staking_id ON referral_rewards(staking_id)`).run() } catch {}
        try { await db.prepare(`CREATE INDEX IF NOT EXISTS idx_referral_rewards_composite ON referral_rewards(referrer_id, referee_id, level, staking_id, reward_date)`).run() } catch {}
        stakingIdColAdded = true
      }
    } catch (e: any) {
      console.error('G2-B ALTER referral_rewards 실패 (계속 진행):', e?.message)
    }

    // G plan 백필 대상 (D안에서 차단된 2건만)
    const BACKFILL_TARGETS = [
      { referee_id: 45, referee_name: '이인실', level: 1 as 1 | 2, ratio: 0.20, expected_amount: 150 },
      { referee_id: 49, referee_name: '유정',   level: 2 as 1 | 2, ratio: 0.10, expected_amount: 75 },
    ]

    // STEP 0: 솔밧 잔액
    const solbat = await db.prepare(`SELECT id, name, qkey_balance FROM users WHERE id = ?`).bind(SOLBAT_ID).first() as any
    if (!solbat) return c.json({ error: 'solbat not found' }, 404)

    // STEP 1: 각 referee 별로 누락된 staking 정확 식별
    const preflight: any[] = []
    let allValid = true
    let preflightTotalExpected = 0

    for (const t of BACKFILL_TARGETS) {
      // referee 의 active staking 들과 각 self_daily(QKEY) 계산
      const stakesRes = await db.prepare(`
        SELECT id, amount, daily_rate, status,
               date(datetime(start_date, '+9 hours')) AS start_kst_date
        FROM staking WHERE user_id = ? AND status = 'active'
        ORDER BY id ASC
      `).bind(t.referee_id).all()
      const stakes = ((stakesRes.results as any[]) || []).map((s: any) => ({
        staking_id: Number(s.id),
        amount: Number(s.amount),
        daily_rate: Number(s.daily_rate),
        start_kst_date: s.start_kst_date,
        self_daily_qkey: Math.round(Number(s.amount) * Number(s.daily_rate) * 150),
      }))

      // 5/13 에 이미 ledger 에 들어간 (이 referee 의 이 level 분) row 조회
      // G2-B: staking_id 컬럼이 있으면 함께 조회 (NOT NULL row 식별 위해)
      const ledgerSelectSql = `
        SELECT id, original_amount, reward_amount, reward_date, paid_date, created_at, staking_id
        FROM referral_rewards
        WHERE referrer_id = ? AND referee_id = ? AND level = ?
          AND (paid_date = ? OR reward_date = ?
               OR date(datetime(created_at, '+9 hours')) = ?)
        ORDER BY id ASC
      `
      const ledgerRes = await db.prepare(ledgerSelectSql)
        .bind(SOLBAT_ID, t.referee_id, t.level, TARGET_DATE, TARGET_DATE, TARGET_DATE).all()
      const ledgerRows = (ledgerRes.results as any[]) || []

      // G2-B 누락 staking 식별 로직 (2-pass):
      //   Pass 1: ledger.staking_id NOT NULL 인 row 들과 매칭되는 staking 제외 (가장 정확)
      //   Pass 2: ledger.staking_id NULL 인 legacy row 들과 original_amount 매칭으로 차감
      const processedStakingIds = new Set<number>()
      // Pass 1: NOT NULL staking_id 매칭
      for (const lr of ledgerRows) {
        if (lr.staking_id != null) {
          processedStakingIds.add(Number(lr.staking_id))
        }
      }
      // Pass 2: NULL staking_id legacy row 들을 original_amount 로 차감
      const remainingStakes = stakes.filter((s: any) => !processedStakingIds.has(s.staking_id))
      const legacyOriginalCounts: Record<number, number> = {}
      for (const lr of ledgerRows) {
        if (lr.staking_id == null) {
          const orig = Number(lr.original_amount)
          legacyOriginalCounts[orig] = (legacyOriginalCounts[orig] || 0) + 1
        }
      }
      const missingStakes: any[] = []
      for (const s of remainingStakes) {
        const orig = s.self_daily_qkey
        if ((legacyOriginalCounts[orig] || 0) > 0) {
          legacyOriginalCounts[orig]--
          // legacy row 가 이 staking 분일 "가능성" → 처리됨으로 간주 (안전 측면)
          continue
        }
        missingStakes.push(s)
      }

      // 누락 staking 들의 매칭 보너스 합산
      const missingMatchSum = missingStakes.reduce(
        (sum, s) => sum + Math.round(s.self_daily_qkey * t.ratio), 0
      )

      // 영구룰 검증: 누락 매칭 합 = 기대 백필 금액
      const amountMatches = missingMatchSum === t.expected_amount

      // 각 누락 staking 별 백필 spec
      const backfillSpecs = missingStakes.map((s: any) => ({
        staking_id: s.staking_id,
        staking_amount: s.amount,
        daily_rate: s.daily_rate,
        self_daily_qkey: s.self_daily_qkey,
        bonus_qkey: Math.round(s.self_daily_qkey * t.ratio),
        ref_id: `bf_513_solbat_l${t.level}_referee${t.referee_id}_s${s.staking_id}`,
      }))

      preflight.push({
        referee_id: t.referee_id, referee_name: t.referee_name,
        level: t.level, ratio: t.ratio,
        referee_active_stakes: stakes,
        ledger_already_processed: ledgerRows.map((r: any) => ({
          rr_id: r.id,
          original_amount: r.original_amount,
          reward_amount: r.reward_amount,
          staking_id: r.staking_id,  // G2-B: NULL 이면 legacy
        })),
        ledger_not_null_staking_ids: Array.from(processedStakingIds),
        missing_stakes_count: missingStakes.length,
        missing_match_sum: missingMatchSum,
        expected_backfill_amount: t.expected_amount,
        amount_matches_calculation: amountMatches,
        backfill_specs: backfillSpecs,
      })

      if (!amountMatches) allValid = false
      preflightTotalExpected += t.expected_amount
    }

    if (!isExec) {
      return c.json({
        success: true,
        mode: 'DRY_RUN',
        target_date: TARGET_DATE,
        solbat: { id: solbat.id, name: solbat.name, qkey_balance_current: solbat.qkey_balance },
        g2b_schema: {
          staking_id_col_existed_before: stakingIdColExisted,
          staking_id_col_added_now: stakingIdColAdded,
          status: (stakingIdColExisted || stakingIdColAdded) ? 'READY' : 'MISSING',
        },
        all_preflight_valid: allValid,
        total_to_backfill: preflightTotalExpected,
        preflight,
        notes: [
          'G2-B: referral_rewards.staking_id 컬럼 영구 인프라 (migrations/0014)',
          '첫 호출 시 ALTER TABLE idempotent 자동 적용',
          '누락 staking 식별 2-pass: ① ledger.staking_id NOT NULL 매칭 ② legacy NULL row 는 original_amount 차감',
          '백필 INSERT 시 referral_rewards.staking_id 정확 기록 → 향후 영구 식별 가능',
          '헬퍼 4중 가드 (refId / referee+level / staking_id / stakingOriginalAmount)',
          '실제 백필하려면 ?confirm=GO 추가',
        ]
      })
    }

    // EXEC 시 사전 검증 실패하면 차단
    if (!allValid) {
      return c.json({
        success: false,
        mode: 'EXEC_BLOCKED',
        error: '사전 검증 실패 — amount_matches_calculation false 가 있음. 백필 차단',
        preflight,
      }, 400)
    }

    // ====================== EXEC ======================
    const inserted: any[] = []
    const skipped: any[] = []
    let actualSum = 0

    for (const pf of preflight) {
      for (const spec of pf.backfill_specs as any[]) {
        const description = pf.level === 1 ? '추천 보너스 (Level 1)' : '추천 보너스 (Level 2)'
        try {
          const res = await safeInsertTransaction(db, {
            user_id: SOLBAT_ID,
            type: 'referral_reward',
            coin_type: 'QKEY',
            amount: spec.bonus_qkey,
            description,
            ref_id: spec.ref_id,
            kst_date: TARGET_DATE,
            updateBalance: true,
            refereeId: pf.referee_id,
            level: pf.level,
            stakingOriginalAmount: spec.self_daily_qkey,  // G plan 폴백
            stakingId: spec.staking_id,                   // G2-B 핵심 — 정확 식별
          })
          // referral_rewards 원장 INSERT (G2-B: staking_id 명시 기록)
          try {
            await db.prepare(`
              INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, created_at, staking_id)
              VALUES (?, ?, ?, ?, ?, ?, ?, datetime('now'), ?)
            `).bind(
              SOLBAT_ID, pf.referee_id, pf.level,
              spec.self_daily_qkey, spec.bonus_qkey,
              TARGET_DATE, TARGET_DATE,
              spec.staking_id,  // G2-B
            ).run()
          } catch (rrErr: any) {
            console.error('referral_rewards INSERT 실패 (tx 는 성공):', rrErr?.message)
          }
          actualSum += spec.bonus_qkey
          inserted.push({
            referee_id: pf.referee_id, referee_name: pf.referee_name,
            level: pf.level, amount: spec.bonus_qkey,
            staking_id: spec.staking_id,
            original_amount: spec.self_daily_qkey,
            tx_id: (res as any).tx_id, ref_id: spec.ref_id,
          })
        } catch (err: any) {
          skipped.push({
            referee_id: pf.referee_id, referee_name: pf.referee_name,
            level: pf.level, amount: spec.bonus_qkey,
            staking_id: spec.staking_id,
            reason: err?.code || 'unknown',
            message: err?.message,
            match_reason: err?.match_reason,
          })
        }
      }
    }

    // 잔액 재조회
    const after = await db.prepare(`SELECT qkey_balance FROM users WHERE id = ?`).bind(SOLBAT_ID).first() as any

    return c.json({
      success: true,
      mode: 'EXEC',
      target_date: TARGET_DATE,
      g2b_schema: {
        staking_id_col_existed_before: stakingIdColExisted,
        staking_id_col_added_now: stakingIdColAdded,
      },
      solbat_balance_before: solbat.qkey_balance,
      solbat_balance_after: after?.qkey_balance,
      delta: (after?.qkey_balance || 0) - solbat.qkey_balance,
      inserted_count: inserted.length,
      skipped_count: skipped.length,
      actual_backfill_sum: actualSum,
      inserted,
      skipped,
      note: 'G2-B — referral_rewards.staking_id 컬럼 영구 인프라 + 정확 백필. cron H plan 적용 후 신규 row 100% 정확 식별',
    })
  } catch (error: any) {
    console.error('solbat-513-g-plan-backfill error:', error)
    return c.json({ error: error?.message || String(error), code: error?.code }, 500)
  }
})

// ============================================================
// /api/diag/solbat-513-tx-deep-trace  (2026-05-13, B안 read-only)
// ------------------------------------------------------------
// 사장님 결재 B안: 솔밧 5/13 tx 11건 각각의 referee 매핑 역추적
// "-300 정체" 완전 규명 — precision-audit 의 3,000 vs 2,700 차이 분해
//
// 영구룰 100% 준수:
//   - L1=20%, L2=10% (절대)
//   - read-only SELECT only (DB UPDATE 0건)
//   - description 사용자 노출 안전 (INSERT 없음)
//
// 동작:
//   1) 솔밧 5/13 KST referral_reward tx 전체 조회 (created_at 기준)
//   2) 각 tx 의 ref_id 로 referral_rewards 원장 행 매핑 → referee_id 식별
//   3) 솔밧 L1/L2 회원 명단과 cross-check → 누가 빠졌는지/누가 중복인지
//   4) precision-audit 의 기대값(3,000) 구성 회원 vs 실제 tx 매핑 회원 set 차이
//   5) referral_rewards 원장에서 paid_date 또는 reward_date 5/13 회원 명세도 함께
//   6) 각 회원 active staking 의 amount × daily_rate × ratio 가 tx amount 와 일치하는지 검증
// ============================================================
app.get('/api/diag/solbat-513-tx-deep-trace', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: '관리자 인증이 필요합니다' }, 401)
  try {
    const db = c.env.DB
    const SOLBAT_ID = 44
    const TARGET_DATE = '2026-05-13'

    // STEP 1: 솔밧 5/13 KST 전체 referral_reward tx
    const txRes = await db.prepare(`
      SELECT id AS tx_id, type, coin_type, amount, description, ref_id,
             created_at,
             datetime(created_at, '+9 hours') AS created_kst,
             substr(datetime(created_at, '+9 hours'), 12, 2) AS kst_hour
      FROM transactions
      WHERE user_id = ? AND type = 'referral_reward'
        AND date(datetime(created_at, '+9 hours')) = ?
      ORDER BY id ASC
    `).bind(SOLBAT_ID, TARGET_DATE).all()
    const allTx = (txRes.results as any[]) || []

    // STEP 2: 각 tx 의 ref_id → referral_rewards 원장 매핑 시도
    //   ref_id 가 숫자면 referral_rewards.id 일 가능성 (cron 패턴)
    //   ref_id 가 'bf_513_*' 면 백필 패턴
    const txWithLedger: any[] = []
    for (const tx of allTx) {
      let ledger: any = null
      const rid = String(tx.ref_id || '')
      // 패턴 A: ref_id 가 숫자 → referral_rewards.id 매핑
      if (/^\d+$/.test(rid)) {
        const ledgerRow = await db.prepare(`
          SELECT id, referrer_id, referee_id, level, original_amount, reward_amount,
                 reward_date, paid_date,
                 datetime(created_at, '+9 hours') AS rr_created_kst
          FROM referral_rewards WHERE id = ?
        `).bind(Number(rid)).first()
        if (ledgerRow) ledger = ledgerRow
      }
      // 패턴 B: ref_id 가 'bf_513_*' → 백필 식별자
      // 패턴 C: 매핑 실패 시 amount + level + 5/13 reward/paid_date 로 referee 추정
      if (!ledger) {
        const lv = rid.includes('Level 1') || (tx.description || '').includes('Level 1') ? 1 :
                   (rid.includes('Level 2') || (tx.description || '').includes('Level 2') ? 2 : null)
        if (lv) {
          const candRows = await db.prepare(`
            SELECT id, referrer_id, referee_id, level, original_amount, reward_amount,
                   reward_date, paid_date,
                   datetime(created_at, '+9 hours') AS rr_created_kst
            FROM referral_rewards
            WHERE referrer_id = ? AND level = ? AND reward_amount = ?
              AND (paid_date = ? OR reward_date = ?
                   OR date(datetime(created_at, '+9 hours')) = ?)
            ORDER BY id ASC
          `).bind(SOLBAT_ID, lv, Number(tx.amount), TARGET_DATE, TARGET_DATE, TARGET_DATE).all()
          const cands = (candRows.results as any[]) || []
          if (cands.length === 1) ledger = cands[0]
          else if (cands.length > 1) ledger = { multiple_candidates: cands.length, cands }
        }
      }

      // referee 정보 보강
      let refereeInfo: any = null
      if (ledger && ledger.referee_id) {
        const refUser = await db.prepare(`
          SELECT id, name, email, referrer_id FROM users WHERE id = ?
        `).bind(ledger.referee_id).first() as any
        // referee 의 active staking (현재 시점)
        const refStakes = await db.prepare(`
          SELECT id AS staking_id, amount, daily_rate, status
          FROM staking WHERE user_id = ? AND status = 'active'
        `).bind(ledger.referee_id).all()
        const stakes = (refStakes.results as any[]) || []
        let userSelfDailyExpected = 0
        for (const s of stakes) {
          userSelfDailyExpected += Math.round(Number(s.amount) * Number(s.daily_rate) * 150)
        }
        refereeInfo = {
          referee_id: refUser?.id,
          referee_name: refUser?.name,
          referee_email: refUser?.email,
          referrer_id_of_referee: refUser?.referrer_id,
          active_stakes_count: stakes.length,
          self_daily_qkey_expected_today: userSelfDailyExpected,
        }
      }

      const level = ledger?.level
                  || (String(tx.description || '').includes('Level 1') ? 1
                  : (String(tx.description || '').includes('Level 2') ? 2 : null))

      txWithLedger.push({
        tx_id: tx.tx_id,
        amount: Number(tx.amount),
        description: tx.description,
        ref_id: tx.ref_id,
        created_kst: tx.created_kst,
        kst_hour: tx.kst_hour,
        level,
        ledger,
        referee: refereeInfo,
      })
    }

    // STEP 3: 솔밧 L1/L2 회원 명단
    const l1Res = await db.prepare(`
      SELECT id, name FROM users WHERE referrer_id = ? ORDER BY id ASC
    `).bind(SOLBAT_ID).all()
    const l1Users = (l1Res.results as any[]) || []

    const l2Res = await db.prepare(`
      SELECT u.id, u.name, u.referrer_id AS l1_id, l1.name AS l1_name
      FROM users u JOIN users l1 ON u.referrer_id = l1.id
      WHERE l1.referrer_id = ?
      ORDER BY u.id ASC
    `).bind(SOLBAT_ID).all()
    const l2Users = (l2Res.results as any[]) || []

    // STEP 4: tx 에서 매핑된 referee_id set vs 멤버 명단 비교
    const txMappedRefereeIds = new Set<number>()
    for (const t of txWithLedger) {
      if (t.referee?.referee_id) txMappedRefereeIds.add(Number(t.referee.referee_id))
    }
    const l1MemberIds = new Set(l1Users.map((u: any) => Number(u.id)))
    const l2MemberIds = new Set(l2Users.map((u: any) => Number(u.id)))

    const l1NotInTx = l1Users.filter((u: any) => !txMappedRefereeIds.has(Number(u.id)))
    const l2NotInTx = l2Users.filter((u: any) => !txMappedRefereeIds.has(Number(u.id)))

    // STEP 5: 합계
    let l1TxSum = 0, l2TxSum = 0
    let l1TxCount = 0, l2TxCount = 0
    for (const t of txWithLedger) {
      if (t.level === 1) { l1TxSum += t.amount; l1TxCount++ }
      else if (t.level === 2) { l2TxSum += t.amount; l2TxCount++ }
    }

    // STEP 6: 각 회원 staking 현재 상태 기준 기대값 (precision-audit 와 같은 계산)
    async function computeMemberDaily(userIds: number[]) {
      const out: any[] = []
      let sum = 0
      for (const uid of userIds) {
        const stRes = await db.prepare(`
          SELECT id, amount, daily_rate FROM staking WHERE user_id = ? AND status = 'active'
        `).bind(uid).all()
        const stakes = (stRes.results as any[]) || []
        let total = 0
        for (const s of stakes) total += Math.round(Number(s.amount) * Number(s.daily_rate) * 150)
        sum += total
        out.push({ user_id: uid, active_stake_count: stakes.length, daily_qkey: total })
      }
      return { sum, detail: out }
    }
    const l1ExpectedDetail = await computeMemberDaily(l1Users.map((u: any) => Number(u.id)))
    const l2ExpectedDetail = await computeMemberDaily(l2Users.map((u: any) => Number(u.id)))

    const expectedL1Match = Math.round(l1ExpectedDetail.sum * 0.20)
    const expectedL2Match = Math.round(l2ExpectedDetail.sum * 0.10)
    const expectedTotal = expectedL1Match + expectedL2Match

    // STEP 7: tx 안 매핑된 멤버 = 매칭 미발생 후보, tx 매핑된 멤버 = 매칭 발생 (단 amount 검증 필요)
    // 각 멤버별 expected_match (현재 staking 기준) vs actual_match (tx 합) 비교
    function expectedMatchFor(uid: number, level: 1 | 2, detail: any[]) {
      const r = detail.find((x: any) => x.user_id === uid)
      if (!r) return 0
      const ratio = level === 1 ? 0.20 : 0.10
      return Math.round(r.daily_qkey * ratio)
    }
    function actualMatchFor(uid: number, level: 1 | 2) {
      return txWithLedger
        .filter(t => t.level === level && t.referee?.referee_id === uid)
        .reduce((s, t) => s + t.amount, 0)
    }

    const l1MemberAnalysis = l1Users.map((u: any) => {
      const uid = Number(u.id)
      const expected = expectedMatchFor(uid, 1, l1ExpectedDetail.detail)
      const actual = actualMatchFor(uid, 1)
      return {
        user_id: uid, user_name: u.name,
        expected_match: expected,
        actual_match: actual,
        diff: actual - expected,
        status: expected === actual ? '✅ MATCH'
              : (actual > expected ? '🔴 OVER' : '🟡 UNDER')
      }
    })

    const l2MemberAnalysis = l2Users.map((u: any) => {
      const uid = Number(u.id)
      const expected = expectedMatchFor(uid, 2, l2ExpectedDetail.detail)
      const actual = actualMatchFor(uid, 2)
      return {
        user_id: uid, user_name: u.name, l1_name: u.l1_name,
        expected_match: expected,
        actual_match: actual,
        diff: actual - expected,
        status: expected === actual ? '✅ MATCH'
              : (actual > expected ? '🔴 OVER' : '🟡 UNDER')
      }
    })

    // STEP 8: tx 중 referee 매핑 실패한 행 (의문의 row)
    const orphanTxs = txWithLedger.filter(t => !t.referee)

    return c.json({
      success: true,
      audit_kind: 'solbat_513_tx_deep_trace',
      target_date: TARGET_DATE,
      taken_at_kst: new Date(Date.now() + 9*60*60*1000).toISOString().replace('T',' ').replace('Z',''),

      summary: {
        tx_total_count: allTx.length,
        l1_tx_count: l1TxCount,
        l1_tx_sum: l1TxSum,
        l2_tx_count: l2TxCount,
        l2_tx_sum: l2TxSum,
        actual_total: l1TxSum + l2TxSum,
        expected_l1_match: expectedL1Match,
        expected_l2_match: expectedL2Match,
        expected_total: expectedTotal,
        diff_total: (l1TxSum + l2TxSum) - expectedTotal,
        diff_l1: l1TxSum - expectedL1Match,
        diff_l2: l2TxSum - expectedL2Match,
      },

      l1_member_analysis: l1MemberAnalysis,
      l2_member_analysis: l2MemberAnalysis,

      l1_not_in_tx: l1NotInTx.map((u: any) => ({ user_id: u.id, user_name: u.name })),
      l2_not_in_tx: l2NotInTx.map((u: any) => ({ user_id: u.id, user_name: u.name })),

      orphan_txs: orphanTxs,

      // 모든 tx 의 매핑 결과 (디버깅용)
      tx_with_ledger_mapping: txWithLedger,

      notes: [
        'read-only SELECT only (DB UPDATE 0건)',
        '영구룰 L1=20% L2=10% 산식 사용',
        'expected = 현재 staking active 기준 (precision-audit 와 동일)',
        'actual = 솔밧 5/13 KST referral_reward tx amount 합',
        'orphan_txs 가 0건 아니면 ref_id 패턴 불명확 → 수동 확인 필요',
      ]
    })
  } catch (error: any) {
    console.error('solbat-513-tx-deep-trace error:', error)
    return c.json({ error: error?.message || String(error) }, 500)
  }
})

// ============================================================
// /api/diag/solbat-513-missing-trace  (2026-05-13, A안)
// ------------------------------------------------------------
// 사장님 결재 A안: 5/13 솔밧 L1 -150 / L2 -150 누락의 정확한 회원 식별 + 백필
//
// 영구룰 100% 준수:
//   - L1=20%, L2=10% (절대)
//   - staking.daily_rate D1 직접 (amount 추정 금지)
//   - bottom-up: leaf staking 실데이터 먼저 → 부모 매칭 계산
//   - description 사용자 노출 안전: '추천 보너스 (Level 1)' / '추천 보너스 (Level 2)' 만
//   - safeInsertTransaction 헬퍼 의무 사용 (3중 가드: ref_id, broad EXISTS, INSERT)
//   - 1대(L1)/2대(L2) 각 회원의 5/13 self daily tx 존재 여부 확인 후 매칭 산출
//
// 동작:
//   1) 솔밧 L1 7명 + L2 7명 각자의 active staking → daily_rate × 150 = self_daily_qkey
//   2) 각 회원이 5/13에 실제로 self daily tx 받았는지 조회 (받았으면 매칭 산출 대상)
//   3) 각 회원당 솔밧이 받아야 할 매칭(QKEY) = self_daily_qkey × 0.20 (L1) 또는 × 0.10 (L2)
//   4) 솔밧이 실제 5/13 받은 L1/L2 tx 명세 조회 (회원별 분해 가능 시)
//   5) 누락 회원 식별 → 백필 대상 명단
//   6) DRY_RUN: 명단/총액 반환, ?confirm=GO 시 safeInsertTransaction 호출
//
// 단, 솔밧 L1/L2 회원 중 5/13 self daily 가 0 QKEY 인 (이번 cron 미실행 또는 staking 휴면) 회원은 제외
// ============================================================
app.get('/api/diag/solbat-513-missing-trace', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: '관리자 인증이 필요합니다' }, 401)
  const confirm = c.req.query('confirm') || ''
  const isExec = confirm === 'GO'

  try {
    const db = c.env.DB
    const SOLBAT_ID = 44
    const TARGET_DATE = '2026-05-13'
    const TARGET_DATE_OBJ = new Date(TARGET_DATE + 'T00:00:00+09:00')
    const { isBusinessDay } = isKoreanBusinessDay(TARGET_DATE_OBJ)
    if (!isBusinessDay) {
      return c.json({ error: `${TARGET_DATE} 는 평일이 아니라 매칭 대상 아님` }, 400)
    }

    // 솔밧
    const solbat = await db.prepare(`
      SELECT id, name, qkey_balance FROM users WHERE id = ?
    `).bind(SOLBAT_ID).first() as any
    if (!solbat) return c.json({ error: 'solbat not found' }, 404)

    // STEP 1: L1 회원 명단
    const l1Res = await db.prepare(`
      SELECT id, name, email FROM users WHERE referrer_id = ? ORDER BY id ASC
    `).bind(SOLBAT_ID).all()
    const l1Users = (l1Res.results as any[]) || []

    // STEP 2: L2 회원 명단
    const l2Res = await db.prepare(`
      SELECT u.id, u.name, u.email, u.referrer_id AS l1_id, l1.name AS l1_name
      FROM users u JOIN users l1 ON u.referrer_id = l1.id
      WHERE l1.referrer_id = ?
      ORDER BY u.id ASC
    `).bind(SOLBAT_ID).all()
    const l2Users = (l2Res.results as any[]) || []

    // ============================================================
    // 회원별 5/13 self daily 발생 여부 + 매칭 기대값 계산 (bottom-up)
    // ============================================================
    async function buildMatchTargets(users: any[], level: 1 | 2) {
      const ratio = level === 1 ? 0.20 : 0.10
      const out: any[] = []
      for (const u of users) {
        // 회원의 active staking 들 daily_rate 합산
        const stakesRes = await db.prepare(`
          SELECT id AS staking_id, amount, daily_rate, status
          FROM staking WHERE user_id = ? AND status = 'active'
        `).bind(u.id).all()
        const stakes = (stakesRes.results as any[]) || []
        let userSelfDaily = 0
        for (const s of stakes) {
          userSelfDaily += Math.round(Number(s.amount) * Number(s.daily_rate) * 150)
        }

        // 회원의 5/13 실제 self daily tx 발생 확인 (cron 이 정상 처리했는지)
        const selfDailyTx = await db.prepare(`
          SELECT id, amount, ref_id,
                 date(datetime(created_at, '+9 hours')) AS kst_date
          FROM transactions
          WHERE user_id = ? AND type = 'daily_reward' AND coin_type = 'QKEY'
            AND date(datetime(created_at, '+9 hours')) = ?
          ORDER BY id ASC
        `).bind(u.id, TARGET_DATE).all()
        const selfTxs = (selfDailyTx.results as any[]) || []
        const selfTxSum = selfTxs.reduce((s, r: any) => s + Number(r.amount), 0)

        // 매칭 기대값: 회원의 실제 5/13 self daily tx 합 × ratio
        // (cron 이 회원 self daily 를 안 지급했다면 매칭도 0 — 추정 금지)
        const expectedMatch = Math.round(selfTxSum * ratio)

        // 솔밧이 이 회원분 매칭을 5/13 에 실제 받았는지 확인 — referral_rewards 원장으로 확정
        const rrRow = await db.prepare(`
          SELECT id AS rr_id, reward_amount, original_amount, reward_date, paid_date
          FROM referral_rewards
          WHERE referrer_id = ? AND referee_id = ? AND level = ?
            AND (paid_date = ? OR reward_date = ?)
          ORDER BY id DESC LIMIT 1
        `).bind(SOLBAT_ID, u.id, level, TARGET_DATE, TARGET_DATE).first() as any
        const actualMatch = rrRow ? Number(rrRow.reward_amount) : 0

        out.push({
          level,
          user_id: u.id,
          user_name: u.name,
          user_email: u.email,
          ...(level === 2 ? { l1_id: u.l1_id, l1_name: u.l1_name } : {}),
          active_stakes_count: stakes.length,
          user_self_daily_qkey_expected: userSelfDaily,
          user_self_daily_qkey_actual_513: selfTxSum,
          user_self_daily_tx_count_513: selfTxs.length,
          expected_match_to_solbat: expectedMatch,
          actual_match_to_solbat: actualMatch,
          rr_row: rrRow ? { id: rrRow.rr_id, paid_date: rrRow.paid_date, reward_date: rrRow.reward_date } : null,
          diff: actualMatch - expectedMatch,
          status: actualMatch === expectedMatch ? '✅ MATCH'
                : (actualMatch > expectedMatch ? '🔴 OVER' : '🟡 UNDER'),
          will_backfill: expectedMatch > actualMatch && (expectedMatch - actualMatch) > 0,
          backfill_amount: Math.max(0, expectedMatch - actualMatch),
        })
      }
      return out
    }

    const l1Targets = await buildMatchTargets(l1Users, 1)
    const l2Targets = await buildMatchTargets(l2Users, 2)

    // 합계
    const l1ExpectedSum = l1Targets.reduce((s, r) => s + r.expected_match_to_solbat, 0)
    const l1ActualSum = l1Targets.reduce((s, r) => s + r.actual_match_to_solbat, 0)
    const l2ExpectedSum = l2Targets.reduce((s, r) => s + r.expected_match_to_solbat, 0)
    const l2ActualSum = l2Targets.reduce((s, r) => s + r.actual_match_to_solbat, 0)
    const l1MissingTotal = l1Targets.reduce((s, r) => s + r.backfill_amount, 0)
    const l2MissingTotal = l2Targets.reduce((s, r) => s + r.backfill_amount, 0)

    // 백필 대상만
    const l1ToBackfill = l1Targets.filter(t => t.will_backfill)
    const l2ToBackfill = l2Targets.filter(t => t.will_backfill)

    if (!isExec) {
      return c.json({
        success: true,
        mode: 'DRY_RUN',
        target_date: TARGET_DATE,
        solbat: { id: solbat.id, name: solbat.name, qkey_balance_current: solbat.qkey_balance },
        l1_summary: {
          expected_sum: l1ExpectedSum,
          actual_sum: l1ActualSum,
          missing_total: l1MissingTotal,
          backfill_target_count: l1ToBackfill.length,
        },
        l2_summary: {
          expected_sum: l2ExpectedSum,
          actual_sum: l2ActualSum,
          missing_total: l2MissingTotal,
          backfill_target_count: l2ToBackfill.length,
        },
        grand_total_to_backfill: l1MissingTotal + l2MissingTotal,
        l1_backfill_candidates: l1ToBackfill,
        l2_backfill_candidates: l2ToBackfill,
        l1_all_breakdown: l1Targets,
        l2_all_breakdown: l2Targets,
        next: '실제 백필하려면 ?confirm=GO 추가 (safeInsertTransaction 3중 가드 자동 수행)',
      })
    }

    // ====================== EXEC: 백필 실행 ======================
    // safeInsertTransaction 헬퍼만 사용 — 영구룰 #이중지급 절대 금지
    const inserted: any[] = []
    const skipped: any[] = []
    let actualBackfillSum = 0

    for (const t of [...l1ToBackfill, ...l2ToBackfill]) {
      const lv = t.level
      const refId = `bf_513_solbat_trace_l${lv}_referee${t.user_id}`
      const description = lv === 1 ? '추천 보너스 (Level 1)' : '추천 보너스 (Level 2)'
      try {
        const res = await safeInsertTransaction(db, {
          user_id: SOLBAT_ID,
          type: 'referral_reward',
          coin_type: 'QKEY',
          amount: t.backfill_amount,
          description,
          ref_id: refId,
          kst_date: TARGET_DATE,
          updateBalance: true,
        })
        // referral_rewards 원장도 함께 INSERT (스키마: referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date)
        try {
          await db.prepare(`
            INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, datetime('now'))
          `).bind(
            SOLBAT_ID,
            t.user_id,
            lv,
            t.user_self_daily_qkey_actual_513,
            t.backfill_amount,
            TARGET_DATE,
            TARGET_DATE,
          ).run()
        } catch(rrErr: any) {
          // 원장 INSERT 실패는 tx 가 이미 들어갔으므로 경고만
          console.error('referral_rewards INSERT 실패 (tx 는 성공):', rrErr?.message)
        }
        actualBackfillSum += t.backfill_amount
        inserted.push({
          level: lv,
          referee_user_id: t.user_id,
          referee_name: t.user_name,
          amount: t.backfill_amount,
          tx_id: (res as any).tx_id,
          ref_id: refId,
        })
      } catch (err: any) {
        skipped.push({
          level: lv,
          referee_user_id: t.user_id,
          referee_name: t.user_name,
          amount: t.backfill_amount,
          reason: err?.code || 'unknown',
          message: err?.message,
        })
      }
    }

    // 백필 후 솔밧 잔액 재조회
    const after = await db.prepare(`SELECT qkey_balance FROM users WHERE id = ?`).bind(SOLBAT_ID).first() as any

    return c.json({
      success: true,
      mode: 'EXEC',
      target_date: TARGET_DATE,
      solbat_balance_before: solbat.qkey_balance,
      solbat_balance_after: after?.qkey_balance,
      delta: (after?.qkey_balance || 0) - solbat.qkey_balance,
      inserted_count: inserted.length,
      skipped_count: skipped.length,
      actual_backfill_sum: actualBackfillSum,
      inserted,
      skipped,
      note: 'safeInsertTransaction 3중 가드 통과한 row 만 INSERT — 사장님 영구룰 #이중지급 절대 금지 준수',
    })
  } catch (error: any) {
    console.error('solbat-513-missing-trace error:', error)
    return c.json({ error: error?.message || String(error), code: error?.code }, 500)
  }
})

// ============================================================
// /api/diag/solbat-l1l2-precision-audit  (2026-05-13, read-only)
// ------------------------------------------------------------
// 사장님 명령: "솔밧꺼 정밀 진단하자 하부 1대와 하부 2대가 또 안맞는다"
//
// 영구룰 100% 준수:
//   - L1=20%, L2=10% (절대 위반 금지)
//   - staking.daily_rate D1 직접 조회 (amount 보고 추측 금지)
//   - bottom-up: leaf staking 실사 → 부모 매칭 산정
//   - read-only SELECT only (DB UPDATE 0건)
//   - description 사용자 노출 안전 (이 엔드포인트는 description INSERT 없음)
//
// 진단 범위:
//   1) 솔밧(u#44) 본인 정보 (잔액 현재값 포함)
//   2) L1 하부 (직접 추천) 전체 명단 + 각자 active staking + daily_rate + 일 데일리 발생액(QKEY)
//   3) L2 하부 (L1의 직접 추천) 전체 명단 + 각자 active staking + daily_rate + 일 데일리 발생액(QKEY)
//   4) 기대 매칭 (1일치): L1합 × 20% + L2합 × 10%
//   5) 최근 7일(KST) 솔밧이 실제 수령한 referral_reward tx 일별 합계 vs 기대값 비교
//   6) 일자별 mismatch 표 (실수령 - 기대) — 양수면 과지급, 음수면 미지급
//   7) referral_rewards 원장 테이블도 일자별 함께 표시
//
// 출력 의도: 사장님이 한 화면에서 "하부 1대/2대 명단 + 매칭 산식 + 일별 mismatch" 모두 보고 판단 가능.
// ============================================================
app.get('/api/diag/solbat-l1l2-precision-audit', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: '관리자 인증이 필요합니다' }, 401)
  try {
    const db = c.env.DB
    const SOLBAT_ID = 44

    // 0) 솔밧 본인
    const solbat = await db.prepare(`
      SELECT id, name, email, qkey_balance, referrer_id,
             datetime(created_at, '+9 hours') AS created_kst
      FROM users WHERE id = ?
    `).bind(SOLBAT_ID).first() as any
    if (!solbat) return c.json({ error: 'solbat user not found' }, 404)

    // 1) L1 직추천 명단 (referrer_id = 솔밧)
    const l1UsersRes = await db.prepare(`
      SELECT id, name, email, referrer_id,
             datetime(created_at, '+9 hours') AS created_kst
      FROM users WHERE referrer_id = ? ORDER BY id ASC
    `).bind(SOLBAT_ID).all()
    const l1Users = (l1UsersRes.results as any[]) || []

    // 2) L2 명단 (L1 의 직추천 = 솔밧의 L2)
    let l2Users: any[] = []
    if (l1Users.length > 0) {
      const ph = l1Users.map(() => '?').join(',')
      const l2Res = await db.prepare(`
        SELECT u.id, u.name, u.email, u.referrer_id AS l1_id,
               l1.name AS l1_name,
               datetime(u.created_at, '+9 hours') AS created_kst
        FROM users u JOIN users l1 ON u.referrer_id = l1.id
        WHERE l1.referrer_id = ?
        ORDER BY u.id ASC
      `).bind(SOLBAT_ID).all()
      l2Users = (l2Res.results as any[]) || []
    }

    // 3) L1 회원별 active staking + daily_rate 실데이터 조회 (영구룰: D1 직접)
    const l1Detail: any[] = []
    let l1DailySumQkey = 0
    for (const u of l1Users) {
      const stakes = await db.prepare(`
        SELECT id AS staking_id, amount, daily_rate, status,
               datetime(start_date, '+9 hours') AS start_kst,
               date(start_date, '+9 hours') AS start_kst_date
        FROM staking WHERE user_id = ? AND status = 'active'
        ORDER BY id ASC
      `).bind(u.id).all()
      const sList = (stakes.results as any[]) || []
      let userDailyQkey = 0
      const stakeDetail = sList.map((s: any) => {
        const dailyQkey = Math.round(Number(s.amount) * Number(s.daily_rate) * 150)
        userDailyQkey += dailyQkey
        return {
          staking_id: s.staking_id,
          amount: Number(s.amount),
          daily_rate: Number(s.daily_rate),
          start_kst_date: s.start_kst_date,
          self_daily_qkey: dailyQkey,
        }
      })
      l1DailySumQkey += userDailyQkey
      l1Detail.push({
        user_id: u.id, user_name: u.name, user_email: u.email,
        created_kst: u.created_kst,
        active_stakes: stakeDetail,
        user_total_daily_qkey: userDailyQkey,
      })
    }

    // 4) L2 회원별 active staking + daily_rate
    const l2Detail: any[] = []
    let l2DailySumQkey = 0
    for (const u of l2Users) {
      const stakes = await db.prepare(`
        SELECT id AS staking_id, amount, daily_rate, status,
               datetime(start_date, '+9 hours') AS start_kst,
               date(start_date, '+9 hours') AS start_kst_date
        FROM staking WHERE user_id = ? AND status = 'active'
        ORDER BY id ASC
      `).bind(u.id).all()
      const sList = (stakes.results as any[]) || []
      let userDailyQkey = 0
      const stakeDetail = sList.map((s: any) => {
        const dailyQkey = Math.round(Number(s.amount) * Number(s.daily_rate) * 150)
        userDailyQkey += dailyQkey
        return {
          staking_id: s.staking_id,
          amount: Number(s.amount),
          daily_rate: Number(s.daily_rate),
          start_kst_date: s.start_kst_date,
          self_daily_qkey: dailyQkey,
        }
      })
      l2DailySumQkey += userDailyQkey
      l2Detail.push({
        user_id: u.id, user_name: u.name, user_email: u.email,
        l1_id: u.l1_id, l1_name: u.l1_name, created_kst: u.created_kst,
        active_stakes: stakeDetail,
        user_total_daily_qkey: userDailyQkey,
      })
    }

    // 5) 기대 매칭 (1일치, 평일 기준)
    const expectedL1Match = Math.round(l1DailySumQkey * 0.20)
    const expectedL2Match = Math.round(l2DailySumQkey * 0.10)
    const expectedTotalMatch = expectedL1Match + expectedL2Match

    // 6) 최근 14일 솔밧 실수령 referral_reward 일별 합계 (KST)
    const txDaily = await db.prepare(`
      SELECT date(datetime(created_at, '+9 hours')) AS kst_date,
             SUM(CASE WHEN description LIKE '%Level 1%' THEN amount ELSE 0 END) AS l1_received_qkey,
             SUM(CASE WHEN description LIKE '%Level 2%' THEN amount ELSE 0 END) AS l2_received_qkey,
             SUM(amount) AS total_received_qkey,
             COUNT(*) AS tx_count
      FROM transactions
      WHERE user_id = ? AND type = 'referral_reward' AND coin_type = 'QKEY'
        AND datetime(created_at, '+9 hours') >= datetime('now','+9 hours','-14 days')
      GROUP BY kst_date
      ORDER BY kst_date DESC
    `).bind(SOLBAT_ID).all()
    const txDailyRows = (txDaily.results as any[]) || []

    // 7) referral_rewards 원장 일별 합계 (paid_date 기준)
    //   ★ 영구룰 스키마 준수: referral_rewards 실제 컬럼 = referrer_id(수령자), referee_id(대상),
    //     level, original_amount, reward_amount, reward_date, paid_date, created_at
    //     (coin_type / user_id / ref_id 컬럼 의존 금지 — migration 0006 에 없음)
    //   ★ 솔밧은 referrer_id 위치 (보너스 수령자)
    let rrDailyRows: any[] = []
    try {
      const rrDaily = await db.prepare(`
        SELECT paid_date,
               SUM(CASE WHEN level = 1 THEN reward_amount ELSE 0 END) AS l1_paid_qkey,
               SUM(CASE WHEN level = 2 THEN reward_amount ELSE 0 END) AS l2_paid_qkey,
               SUM(reward_amount) AS total_paid_qkey,
               COUNT(*) AS row_count
        FROM referral_rewards
        WHERE referrer_id = ?
          AND paid_date >= date('now','+9 hours','-14 days')
        GROUP BY paid_date
        ORDER BY paid_date DESC
      `).bind(SOLBAT_ID).all()
      rrDailyRows = (rrDaily.results as any[]) || []
    } catch(e) {
      // paid_date 컬럼 없는 환경 폴백 — reward_date 로 대체
      try {
        const rrFallback = await db.prepare(`
          SELECT reward_date AS paid_date,
                 SUM(CASE WHEN level = 1 THEN reward_amount ELSE 0 END) AS l1_paid_qkey,
                 SUM(CASE WHEN level = 2 THEN reward_amount ELSE 0 END) AS l2_paid_qkey,
                 SUM(reward_amount) AS total_paid_qkey,
                 COUNT(*) AS row_count
          FROM referral_rewards
          WHERE referrer_id = ?
            AND reward_date >= date('now','+9 hours','-14 days')
          GROUP BY reward_date
          ORDER BY reward_date DESC
        `).bind(SOLBAT_ID).all()
        rrDailyRows = (rrFallback.results as any[]) || []
      } catch(e2) {}
    }

    // 8) 일자별 mismatch (실수령 - 기대) — 평일만 의미 있음, 휴일은 0 기대
    const mismatchByDate: any[] = []
    for (const row of txDailyRows) {
      const kstDate = row.kst_date
      const dateObj = new Date(kstDate + 'T00:00:00+09:00')
      const dow = dateObj.getUTCDay() // 0=일,6=토 (UTC 변환 후도 동일 weekday)
      // 평일 기준만 영업일 — 휴일 보정은 isKoreanBusinessDay 가 더 정확하나
      // 매칭은 cron 에서 평일에만 발생하므로 평일이면 expected, 휴일이면 0
      const { isBusinessDay } = isKoreanBusinessDay(dateObj)
      const expectedL1 = isBusinessDay ? expectedL1Match : 0
      const expectedL2 = isBusinessDay ? expectedL2Match : 0
      const actualL1 = Number(row.l1_received_qkey) || 0
      const actualL2 = Number(row.l2_received_qkey) || 0
      mismatchByDate.push({
        kst_date: kstDate,
        weekday: ['일','월','화','수','목','금','토'][dow],
        is_business_day: isBusinessDay,
        expected_l1: expectedL1,
        actual_l1: actualL1,
        diff_l1: actualL1 - expectedL1,
        expected_l2: expectedL2,
        actual_l2: actualL2,
        diff_l2: actualL2 - expectedL2,
        expected_total: expectedL1 + expectedL2,
        actual_total: actualL1 + actualL2,
        diff_total: (actualL1 + actualL2) - (expectedL1 + expectedL2),
        tx_count: Number(row.tx_count),
        status: ((actualL1 + actualL2) - (expectedL1 + expectedL2)) === 0
          ? '✅ MATCH'
          : ((actualL1 + actualL2) > (expectedL1 + expectedL2) ? '🔴 OVER (과지급)' : '🟡 UNDER (미지급)')
      })
    }

    return c.json({
      success: true,
      audit_kind: 'solbat_l1l2_precision_readonly',
      taken_at_kst: new Date(Date.now() + 9*60*60*1000).toISOString().replace('T',' ').replace('Z',''),
      ratios: { L1: '20%', L2: '10%' },

      solbat: {
        user_id: solbat.id, name: solbat.name, email: solbat.email,
        qkey_balance_current: solbat.qkey_balance,
        created_kst: solbat.created_kst,
      },

      // bottom-up 영구룰: L1/L2 leaf staking 실데이터 먼저 노출
      l1_summary: {
        member_count: l1Users.length,
        total_daily_qkey: l1DailySumQkey,
        expected_match_to_solbat: expectedL1Match, // × 20%
      },
      l2_summary: {
        member_count: l2Users.length,
        total_daily_qkey: l2DailySumQkey,
        expected_match_to_solbat: expectedL2Match, // × 10%
      },
      expected_total_match_per_business_day: expectedTotalMatch,

      // 일자별 mismatch (실수령 - 기대)
      mismatch_by_date: mismatchByDate,

      // 원장 데이터 (paid_date 기준)
      referral_rewards_ledger_by_paid_date: rrDailyRows,

      // 상세 (펼침)
      l1_detail: l1Detail,
      l2_detail: l2Detail,

      notes: [
        '영구룰: L1=20%, L2=10% — 본 진단 산식은 이 비율로 고정',
        '영구룰: staking.daily_rate D1 직접 조회 — amount 추정 금지',
        '평일이 아닌 KST 일자(토/일/공휴일)는 expected = 0 (cron 발생 안 함)',
        'diff_total > 0 = 과지급 (이중지급 가능성) / diff_total < 0 = 미지급 (백필 필요)',
        '이 엔드포인트는 read-only — DB UPDATE 0건',
      ]
    })
  } catch (error: any) {
    console.error('solbat-l1l2-precision-audit error:', error)
    return c.json({ error: error?.message || String(error) }, 500)
  }
})

// ============================================================
// /api/diag/may13-multi-staking-backfill  (2026-05-13, 영구 룰 기준 EXEC)
// ------------------------------------------------------------
// 사장님 결재: 6명 multi-staking referee 매칭 누락 보정 (영구 룰 기준)
// 5/13 cron 이 H plan 적용 전이라 다중-staking referee 의 일부 staking 누락
// G2-B 패턴 그대로 — 4중 가드 + staking_id 명시
//
// 대상:
//   - asd135799 (u#57) 5/13 L1 -150
//   - aafhka (u#54) 5/13 L1 -150
//   - naim197059 (u#49) 5/13 L2 -75
//   - naim1970 (u#48) 5/13 L1 -150
//   - bigbang (u#41) 5/13 L1 -150
//   - lucky4492 (u#69) 5/13 L2 -225
//   - lucky4492 (u#69) 5/12 L2 -225 (만성 누락)
//
// 동작:
//   - DRY_RUN (default): 영구 룰 기준 누락 staking 정확 식별
//   - ?confirm=GO: safeInsertTransaction + referral_rewards 원장 INSERT
// ============================================================
app.get('/api/diag/may13-multi-staking-backfill', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: '관리자 인증이 필요합니다' }, 401)
  const confirm = c.req.query('confirm') || ''
  const isExec = confirm === 'GO'

  try {
    const db = c.env.DB

    // G2-B 영구 인프라 idempotent ALTER
    let stakingIdColAdded = false
    let stakingIdColExisted = false
    try {
      const pragmaRes = await db.prepare(`PRAGMA table_info(referral_rewards)`).all()
      const cols = ((pragmaRes.results as any[]) || []).map((r: any) => r.name)
      stakingIdColExisted = cols.includes('staking_id')
      if (!stakingIdColExisted) {
        await db.prepare(`ALTER TABLE referral_rewards ADD COLUMN staking_id INTEGER`).run()
        try { await db.prepare(`CREATE INDEX IF NOT EXISTS idx_referral_rewards_staking_id ON referral_rewards(staking_id)`).run() } catch {}
        try { await db.prepare(`CREATE INDEX IF NOT EXISTS idx_referral_rewards_composite ON referral_rewards(referrer_id, referee_id, level, staking_id, reward_date)`).run() } catch {}
        stakingIdColAdded = true
      }
    } catch (e: any) {
      console.error('may13 ALTER 실패 (계속):', e?.message)
    }

    // 영구 룰 기준 6명 7건 보정 spec (audit 로 검증된 영구 룰 정답)
    // 각 entry: 보정 대상 user(referrer) 와 reward_date, 그리고 그 트리에서 누락된 referee+level 식별
    type FixTarget = {
      referrer_id: number
      referrer_email: string
      reward_date: string  // 5/13 또는 5/12
      level: 1 | 2
      expected_amount: number  // 영구 룰 audit 으로 확인된 미지급액
    }
    const FIX_TARGETS: FixTarget[] = [
      // 5/13 5명 영구 룰 검증 완료 (L1=20%, L2=10%)
      { referrer_id: 57, referrer_email: 'asd135799',  reward_date: '2026-05-13', level: 1, expected_amount: 150 },
      { referrer_id: 54, referrer_email: 'aafhka',     reward_date: '2026-05-13', level: 1, expected_amount: 150 },
      { referrer_id: 49, referrer_email: 'naim197059', reward_date: '2026-05-13', level: 2, expected_amount: 75 },
      { referrer_id: 48, referrer_email: 'naim1970',   reward_date: '2026-05-13', level: 1, expected_amount: 150 },
      { referrer_id: 41, referrer_email: 'bigbang',    reward_date: '2026-05-13', level: 1, expected_amount: 150 },
      // lucky4492 (u#69) 는 audit 의 KST 일자 매핑 이슈로 별도 분석 → 본 endpoint 에서 제외
    ]

    // STEP 1: 각 보정 대상별로 누락 staking 정확 식별 (G2-B 2-pass)
    const preflight: any[] = []
    let allValid = true
    let preflightTotalExpected = 0

    for (const t of FIX_TARGETS) {
      const ratio = t.level === 1 ? 0.20 : 0.10

      // referrer 본인 잔액
      const referrer = await db.prepare(`SELECT id, name, email, qkey_balance FROM users WHERE id = ?`).bind(t.referrer_id).first() as any
      if (!referrer) {
        preflight.push({ ...t, error: 'referrer not found' })
        allValid = false
        continue
      }

      // referrer 의 referee 명단 (level=1 이면 직접 referee, level=2 이면 L1 의 referee = L2)
      let refereesRes: any
      if (t.level === 1) {
        refereesRes = await db.prepare(`
          SELECT id, name, email FROM users WHERE referrer_id = ? ORDER BY id ASC
        `).bind(t.referrer_id).all()
      } else {
        // L2: referrer 의 L1 들의 referee (즉 L2)
        refereesRes = await db.prepare(`
          SELECT u.id, u.name, u.email FROM users u
          JOIN users l1 ON u.referrer_id = l1.id
          WHERE l1.referrer_id = ?
          ORDER BY u.id ASC
        `).bind(t.referrer_id).all()
      }
      const referees = (refereesRes.results as any[]) || []

      // 각 referee 의 누락 staking 식별 (G2-B 2-pass per referee)
      const refereeFixes: any[] = []
      let totalMissingSum = 0

      for (const ref of referees) {
        // referee 의 active staking 들
        const stakesRes = await db.prepare(`
          SELECT id, amount, daily_rate,
                 date(datetime(start_date, '+9 hours')) AS start_kst_date
          FROM staking WHERE user_id = ? AND status = 'active'
          ORDER BY id ASC
        `).bind(ref.id).all()
        const stakes = ((stakesRes.results as any[]) || []).map((s: any) => ({
          staking_id: Number(s.id),
          amount: Number(s.amount),
          daily_rate: Number(s.daily_rate),
          start_kst_date: s.start_kst_date,
          self_daily_qkey: Math.round(Number(s.amount) * Number(s.daily_rate) * 150),
        }))

        // 해당 referee + reward_date 의 ledger 행 조회
        const ledgerRes = await db.prepare(`
          SELECT id, original_amount, reward_amount, reward_date, paid_date, created_at, staking_id
          FROM referral_rewards
          WHERE referrer_id = ? AND referee_id = ? AND level = ?
            AND (reward_date = ? OR paid_date = ?
                 OR date(datetime(created_at, '+9 hours')) = ?)
          ORDER BY id ASC
        `).bind(t.referrer_id, ref.id, t.level, t.reward_date, t.reward_date, t.reward_date).all()
        const ledgerRows = (ledgerRes.results as any[]) || []

        // Pass 1: ledger.staking_id NOT NULL 매칭
        const processedStakingIds = new Set<number>()
        for (const lr of ledgerRows) {
          if (lr.staking_id != null) processedStakingIds.add(Number(lr.staking_id))
        }
        // Pass 2: legacy NULL row 차감 (original_amount 기준)
        const remainingStakes = stakes.filter((s: any) => !processedStakingIds.has(s.staking_id))
        const legacyOriginalCounts: Record<number, number> = {}
        for (const lr of ledgerRows) {
          if (lr.staking_id == null) {
            const orig = Number(lr.original_amount)
            legacyOriginalCounts[orig] = (legacyOriginalCounts[orig] || 0) + 1
          }
        }
        const missingStakes: any[] = []
        for (const s of remainingStakes) {
          const orig = s.self_daily_qkey
          if ((legacyOriginalCounts[orig] || 0) > 0) {
            legacyOriginalCounts[orig]--
            continue
          }
          missingStakes.push(s)
        }

        // 이 referee 의 누락 매칭 합 = Σ (missing.self_daily_qkey × ratio)
        const refMissingSum = missingStakes.reduce(
          (sum, s) => sum + Math.round(s.self_daily_qkey * ratio), 0
        )
        totalMissingSum += refMissingSum

        if (missingStakes.length > 0) {
          refereeFixes.push({
            referee_id: ref.id,
            referee_name: ref.name,
            referee_email: ref.email,
            ledger_already_processed: ledgerRows.map((r: any) => ({
              rr_id: r.id,
              original_amount: r.original_amount,
              reward_amount: r.reward_amount,
              staking_id: r.staking_id,
            })),
            missing_stakes: missingStakes.map((s: any) => ({
              staking_id: s.staking_id,
              staking_amount: s.amount,
              daily_rate: s.daily_rate,
              self_daily_qkey: s.self_daily_qkey,
              bonus_qkey: Math.round(s.self_daily_qkey * ratio),
              ref_id: `bf_${t.reward_date.replace(/-/g,'')}_u${t.referrer_id}_l${t.level}_ref${ref.id}_s${s.staking_id}`,
            })),
            referee_missing_sum: refMissingSum,
          })
        }
      }

      const amountMatches = totalMissingSum === t.expected_amount

      preflight.push({
        referrer_id: t.referrer_id,
        referrer_email: t.referrer_email,
        referrer_name: referrer.name,
        referrer_qkey_balance: referrer.qkey_balance,
        reward_date: t.reward_date,
        level: t.level,
        ratio,
        expected_amount: t.expected_amount,
        total_missing_sum: totalMissingSum,
        amount_matches_calculation: amountMatches,
        referees_with_missing: refereeFixes,
      })

      if (!amountMatches) allValid = false
      preflightTotalExpected += t.expected_amount
    }

    if (!isExec) {
      return c.json({
        success: true,
        mode: 'DRY_RUN',
        targets_count: FIX_TARGETS.length,
        g2b_schema: {
          staking_id_col_existed_before: stakingIdColExisted,
          staking_id_col_added_now: stakingIdColAdded,
          status: (stakingIdColExisted || stakingIdColAdded) ? 'READY' : 'MISSING',
        },
        all_preflight_valid: allValid,
        total_to_backfill: preflightTotalExpected,
        preflight,
        notes: [
          '영구 룰: L1=20%, L2=10%, staking.daily_rate D1 직접 조회',
          'G2-B: 4중 가드 (ref_id, broad EXISTS, refereeId+level, staking_id)',
          '#bottom-up: leaf staking 별 정확 식별 후 부모 매칭 보정',
          '#이중지급 절대 금지: ledger.staking_id NOT NULL Pass 1 + legacy NULL Pass 2',
          'description: 추천 보너스 (Level 1/2) — 사용자 노출 안전 한국어',
          '실제 백필하려면 ?confirm=GO 추가',
        ]
      })
    }

    if (!allValid) {
      return c.json({
        success: false,
        mode: 'EXEC_BLOCKED',
        error: '사전 검증 실패 — amount_matches_calculation false 가 있음. 백필 차단',
        preflight,
      }, 400)
    }

    // ====================== EXEC ======================
    const inserted: any[] = []
    const skipped: any[] = []
    let actualSum = 0

    for (const pf of preflight) {
      const description = pf.level === 1 ? '추천 보너스 (Level 1)' : '추천 보너스 (Level 2)'
      for (const rfx of pf.referees_with_missing as any[]) {
        for (const spec of rfx.missing_stakes as any[]) {
          try {
            const res = await safeInsertTransaction(db, {
              user_id: pf.referrer_id,
              type: 'referral_reward',
              coin_type: 'QKEY',
              amount: spec.bonus_qkey,
              description,
              ref_id: spec.ref_id,
              kst_date: pf.reward_date,
              updateBalance: true,
              refereeId: rfx.referee_id,
              level: pf.level,
              stakingOriginalAmount: spec.self_daily_qkey,
              stakingId: spec.staking_id,
            })
            // referral_rewards 원장 INSERT (staking_id 명시)
            try {
              await db.prepare(`
                INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, created_at, staking_id)
                VALUES (?, ?, ?, ?, ?, ?, ?, datetime('now'), ?)
              `).bind(
                pf.referrer_id, rfx.referee_id, pf.level,
                spec.self_daily_qkey, spec.bonus_qkey,
                pf.reward_date, pf.reward_date,
                spec.staking_id,
              ).run()
            } catch (rrErr: any) {
              console.error('referral_rewards INSERT 실패 (tx 성공):', rrErr?.message)
            }
            actualSum += spec.bonus_qkey
            inserted.push({
              referrer_id: pf.referrer_id, referrer_email: pf.referrer_email,
              referee_id: rfx.referee_id, referee_name: rfx.referee_name,
              level: pf.level, reward_date: pf.reward_date,
              amount: spec.bonus_qkey,
              staking_id: spec.staking_id,
              original_amount: spec.self_daily_qkey,
              tx_id: (res as any).tx_id, ref_id: spec.ref_id,
            })
          } catch (err: any) {
            skipped.push({
              referrer_id: pf.referrer_id, referrer_email: pf.referrer_email,
              referee_id: rfx.referee_id, referee_name: rfx.referee_name,
              level: pf.level, reward_date: pf.reward_date,
              amount: spec.bonus_qkey,
              staking_id: spec.staking_id,
              reason: err?.code || 'unknown',
              message: err?.message,
              match_reason: err?.match_reason,
            })
          }
        }
      }
    }

    // 6명 잔액 재조회
    const afterBalances: any[] = []
    for (const uid of [57, 54, 49, 48, 41, 69]) {
      const u = await db.prepare(`SELECT id, email, qkey_balance FROM users WHERE id = ?`).bind(uid).first()
      afterBalances.push(u)
    }

    return c.json({
      success: true,
      mode: 'EXEC',
      g2b_schema: {
        staking_id_col_existed_before: stakingIdColExisted,
        staking_id_col_added_now: stakingIdColAdded,
      },
      total_expected: preflightTotalExpected,
      actual_backfill_sum: actualSum,
      inserted_count: inserted.length,
      skipped_count: skipped.length,
      inserted,
      skipped,
      balances_after: afterBalances,
      note: '영구 룰 기준 (L1=20%, L2=10%) 6명 multi-staking 누락 보정. cron H plan 적용 후 신규 row 100% 정확 식별.',
    })
  } catch (error: any) {
    console.error('may13-multi-staking-backfill error:', error)
    return c.json({ error: error?.message || String(error), code: error?.code }, 500)
  }
})

// ============================================================
// /api/diag/user-l1l2-precision-audit  (2026-05-13, generic read-only)
// ------------------------------------------------------------
// 사장님 명시 영구 룰 (L1=20%, L2=10%, staking.daily_rate D1 직접 조회) 기준
// 임의 user_id 의 L1/L2 하부 트리 실데이터 + 매칭 기대값 + 일별 mismatch 분해
// 솔밧 audit 의 user-generic 버전 — 6명 일괄 검증용
//
//   경로: GET /api/diag/user-l1l2-precision-audit?user_id=N&key=ADMIN_PW
//
// read-only — DB UPDATE 0건
// ============================================================
app.get('/api/diag/user-l1l2-precision-audit', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: '관리자 인증이 필요합니다' }, 401)
  try {
    const db = c.env.DB
    const uidParam = c.req.query('user_id') || ''
    const TARGET_ID = Number(uidParam)
    if (!TARGET_ID || isNaN(TARGET_ID)) return c.json({ error: 'user_id 파라미터 필수' }, 400)

    // 0) 대상 회원
    const target = await db.prepare(`
      SELECT id, name, email, qkey_balance, referrer_id,
             datetime(created_at, '+9 hours') AS created_kst
      FROM users WHERE id = ?
    `).bind(TARGET_ID).first() as any
    if (!target) return c.json({ error: 'user not found' }, 404)

    // 1) L1 직추천
    const l1UsersRes = await db.prepare(`
      SELECT id, name, email, referrer_id,
             datetime(created_at, '+9 hours') AS created_kst
      FROM users WHERE referrer_id = ? ORDER BY id ASC
    `).bind(TARGET_ID).all()
    const l1Users = (l1UsersRes.results as any[]) || []

    // 2) L2
    let l2Users: any[] = []
    if (l1Users.length > 0) {
      const l2Res = await db.prepare(`
        SELECT u.id, u.name, u.email, u.referrer_id AS l1_id,
               l1.name AS l1_name,
               datetime(u.created_at, '+9 hours') AS created_kst
        FROM users u JOIN users l1 ON u.referrer_id = l1.id
        WHERE l1.referrer_id = ?
        ORDER BY u.id ASC
      `).bind(TARGET_ID).all()
      l2Users = (l2Res.results as any[]) || []
    }

    // 3) L1 active staking 실데이터
    const l1Detail: any[] = []
    let l1DailySumQkey = 0
    for (const u of l1Users) {
      const stakes = await db.prepare(`
        SELECT id AS staking_id, amount, daily_rate, status,
               date(start_date, '+9 hours') AS start_kst_date
        FROM staking WHERE user_id = ? AND status = 'active'
        ORDER BY id ASC
      `).bind(u.id).all()
      const sList = (stakes.results as any[]) || []
      let userDailyQkey = 0
      const stakeDetail = sList.map((s: any) => {
        const dailyQkey = Math.round(Number(s.amount) * Number(s.daily_rate) * 150)
        userDailyQkey += dailyQkey
        return {
          staking_id: s.staking_id, amount: Number(s.amount),
          daily_rate: Number(s.daily_rate),
          start_kst_date: s.start_kst_date,
          self_daily_qkey: dailyQkey,
        }
      })
      l1DailySumQkey += userDailyQkey
      l1Detail.push({
        user_id: u.id, user_name: u.name, user_email: u.email,
        created_kst: u.created_kst,
        active_stakes: stakeDetail,
        user_total_daily_qkey: userDailyQkey,
      })
    }

    // 4) L2 active staking
    const l2Detail: any[] = []
    let l2DailySumQkey = 0
    for (const u of l2Users) {
      const stakes = await db.prepare(`
        SELECT id AS staking_id, amount, daily_rate, status,
               date(start_date, '+9 hours') AS start_kst_date
        FROM staking WHERE user_id = ? AND status = 'active'
        ORDER BY id ASC
      `).bind(u.id).all()
      const sList = (stakes.results as any[]) || []
      let userDailyQkey = 0
      const stakeDetail = sList.map((s: any) => {
        const dailyQkey = Math.round(Number(s.amount) * Number(s.daily_rate) * 150)
        userDailyQkey += dailyQkey
        return {
          staking_id: s.staking_id, amount: Number(s.amount),
          daily_rate: Number(s.daily_rate),
          start_kst_date: s.start_kst_date,
          self_daily_qkey: dailyQkey,
        }
      })
      l2DailySumQkey += userDailyQkey
      l2Detail.push({
        user_id: u.id, user_name: u.name, user_email: u.email,
        l1_id: u.l1_id, l1_name: u.l1_name, created_kst: u.created_kst,
        active_stakes: stakeDetail,
        user_total_daily_qkey: userDailyQkey,
      })
    }

    // 5) 기대 매칭 (현재 시점 평일 1일치 — 참고용, 일자별 동적 expected 는 8) 에서 계산)
    const expectedL1Match = Math.round(l1DailySumQkey * 0.20)
    const expectedL2Match = Math.round(l2DailySumQkey * 0.10)
    const expectedTotalMatch = expectedL1Match + expectedL2Match

    // 5-B) 영구 룰 #휴일진입자 보호 — 일자별 활성 staking 동적 expected 계산용 인덱스
    // 각 staking 의 start_kst_date 를 기준으로:
    //   - 보상은 start_date 의 다음 cron 실행 (보통 D+1, 단 휴일/주말이면 다음 평일) 부터 발생
    //   - 5/12 (월) start 의 staking 은 5/12 reward → 5/13 (화) paid 가 첫 보상
    //   - 즉 reward_date >= start_kst_date 인 평일에 해당 staking 이 활성
    // KST 날짜 'YYYY-MM-DD' 와 staking start_kst_date 비교는 문자열 사전순으로 일치
    // (날짜 형식 동일하므로 string compare 가 정확)
    type StakeIdx = {
      user_id: number
      staking_id: number
      self_daily_qkey: number
      start_kst_date: string
    }
    const l1StakeIdx: StakeIdx[] = []
    for (const d of l1Detail) {
      for (const s of d.active_stakes as any[]) {
        l1StakeIdx.push({
          user_id: d.user_id,
          staking_id: s.staking_id,
          self_daily_qkey: s.self_daily_qkey,
          start_kst_date: String(s.start_kst_date || ''),
        })
      }
    }
    const l2StakeIdx: StakeIdx[] = []
    for (const d of l2Detail) {
      for (const s of d.active_stakes as any[]) {
        l2StakeIdx.push({
          user_id: d.user_id,
          staking_id: s.staking_id,
          self_daily_qkey: s.self_daily_qkey,
          start_kst_date: String(s.start_kst_date || ''),
        })
      }
    }
    // 헬퍼: 주어진 reward_date(KST) 에 활성인 stakes 의 self_daily 합산 → ratio 적용
    const computeExpectedForDate = (kstDate: string, idx: StakeIdx[], ratio: number) => {
      let sumDaily = 0
      const activeStakes: any[] = []
      for (const s of idx) {
        if (s.start_kst_date && s.start_kst_date <= kstDate) {
          sumDaily += s.self_daily_qkey
          activeStakes.push({
            user_id: s.user_id, staking_id: s.staking_id,
            self_daily_qkey: s.self_daily_qkey,
            start_kst_date: s.start_kst_date,
          })
        }
      }
      return {
        expected: Math.round(sumDaily * ratio),
        active_count: activeStakes.length,
        active_daily_sum: sumDaily,
        active_stakes: activeStakes,
      }
    }

    // 6) 최근 14일 본인 실수령 referral_reward 일별 합계 (KST)
    const txDaily = await db.prepare(`
      SELECT date(datetime(created_at, '+9 hours')) AS kst_date,
             SUM(CASE WHEN description LIKE '%Level 1%' THEN amount ELSE 0 END) AS l1_received_qkey,
             SUM(CASE WHEN description LIKE '%Level 2%' THEN amount ELSE 0 END) AS l2_received_qkey,
             SUM(amount) AS total_received_qkey,
             COUNT(*) AS tx_count
      FROM transactions
      WHERE user_id = ? AND type = 'referral_reward' AND coin_type = 'QKEY'
        AND datetime(created_at, '+9 hours') >= datetime('now','+9 hours','-14 days')
      GROUP BY kst_date
      ORDER BY kst_date DESC
    `).bind(TARGET_ID).all()
    const txDailyRows = (txDaily.results as any[]) || []

    // 7) referral_rewards 원장 일별 (paid_date)
    let rrDailyRows: any[] = []
    try {
      const rrDaily = await db.prepare(`
        SELECT paid_date,
               SUM(CASE WHEN level = 1 THEN reward_amount ELSE 0 END) AS l1_paid_qkey,
               SUM(CASE WHEN level = 2 THEN reward_amount ELSE 0 END) AS l2_paid_qkey,
               SUM(reward_amount) AS total_paid_qkey,
               COUNT(*) AS row_count
        FROM referral_rewards
        WHERE referrer_id = ?
          AND paid_date >= date('now','+9 hours','-14 days')
        GROUP BY paid_date
        ORDER BY paid_date DESC
      `).bind(TARGET_ID).all()
      rrDailyRows = (rrDaily.results as any[]) || []
    } catch(e) {
      try {
        const rrFallback = await db.prepare(`
          SELECT reward_date AS paid_date,
                 SUM(CASE WHEN level = 1 THEN reward_amount ELSE 0 END) AS l1_paid_qkey,
                 SUM(CASE WHEN level = 2 THEN reward_amount ELSE 0 END) AS l2_paid_qkey,
                 SUM(reward_amount) AS total_paid_qkey,
                 COUNT(*) AS row_count
          FROM referral_rewards
          WHERE referrer_id = ?
            AND reward_date >= date('now','+9 hours','-14 days')
          GROUP BY reward_date
          ORDER BY reward_date DESC
        `).bind(TARGET_ID).all()
        rrDailyRows = (rrFallback.results as any[]) || []
      } catch(e2) {}
    }

    // 8) 일자별 mismatch — 영구 룰 #휴일진입자 보호 반영 (일자별 활성 staking 동적 계산)
    //   - kst_date 는 tx.created_at_kst (= paid 일자)
    //   - 영구 룰: 보상은 reward_date 의 staking 활성 여부로 결정, paid 는 다음 영업일
    //   - reward_date = paid_date 의 직전 영업일 (cron 단일화 룰)
    //   - 단순화: tx.created_at_kst 가 영업일이면 그 날 자체를 reward_date 로 간주
    //     (현재 시스템은 cron 시점 = paid date, reward_date 컬럼은 직전 영업일)
    //   - staking.start_kst_date <= reward_date 인 staking 만 활성
    //
    // 정확한 reward_date 매핑을 위해 referral_rewards 에서 paid_date → reward_date 조회
    // (없으면 paid_date 의 직전 영업일을 reward_date 로 가정)
    const prevBusinessDay = (kstDate: string): string => {
      // KST 기준 직전 평일 1일 (간단 휴일 룰: isKoreanBusinessDay 사용)
      const d = new Date(kstDate + 'T00:00:00+09:00')
      for (let i = 1; i <= 7; i++) {
        const prev = new Date(d.getTime() - i*24*60*60*1000)
        const bd = isKoreanBusinessDay(prev)
        if (bd.isBusinessDay) {
          const yyyy = prev.getUTCFullYear()
          const mm = String(prev.getUTCMonth()+1).padStart(2,'0')
          const dd = String(prev.getUTCDate()).padStart(2,'0')
          return `${yyyy}-${mm}-${dd}`
        }
      }
      return kstDate
    }

    // referral_rewards 에서 본인 paid_date → reward_date 매핑 캐시
    const rrMapRes = await db.prepare(`
      SELECT DISTINCT paid_date, reward_date
      FROM referral_rewards
      WHERE referrer_id = ?
        AND paid_date >= date('now','+9 hours','-21 days')
    `).bind(TARGET_ID).all()
    const paidToRewardMap: Record<string, string> = {}
    for (const r of (rrMapRes.results as any[]) || []) {
      if (r.paid_date && r.reward_date) paidToRewardMap[String(r.paid_date)] = String(r.reward_date)
    }

    const mismatchByDate: any[] = []
    for (const row of txDailyRows) {
      const kstDate = row.kst_date
      const dateObj = new Date(kstDate + 'T00:00:00+09:00')
      const dow = dateObj.getUTCDay()
      const { isBusinessDay } = isKoreanBusinessDay(dateObj)

      // reward_date 결정 (영구 룰 #cron 단일화):
      //   1. ledger 에 paid_date=kstDate 인 row 가 있으면 그 reward_date 사용
      //   2. 없으면 kstDate 의 직전 영업일 사용
      const rewardDate = paidToRewardMap[kstDate] || prevBusinessDay(kstDate)

      // 영구 룰 #휴일진입자 보호: rewardDate 시점 활성 staking 만 카운트
      const l1Exp = computeExpectedForDate(rewardDate, l1StakeIdx, 0.20)
      const l2Exp = computeExpectedForDate(rewardDate, l2StakeIdx, 0.10)

      const expectedL1 = isBusinessDay ? l1Exp.expected : 0
      const expectedL2 = isBusinessDay ? l2Exp.expected : 0
      const actualL1 = Number(row.l1_received_qkey) || 0
      const actualL2 = Number(row.l2_received_qkey) || 0
      mismatchByDate.push({
        kst_date: kstDate,
        weekday: ['일','월','화','수','목','금','토'][dow],
        is_business_day: isBusinessDay,
        reward_date_mapped: rewardDate,
        reward_date_source: paidToRewardMap[kstDate] ? 'ledger' : 'derived(prev_business_day)',
        l1_active_stake_count: l1Exp.active_count,
        l1_active_daily_sum: l1Exp.active_daily_sum,
        l2_active_stake_count: l2Exp.active_count,
        l2_active_daily_sum: l2Exp.active_daily_sum,
        expected_l1: expectedL1,
        actual_l1: actualL1,
        diff_l1: actualL1 - expectedL1,
        expected_l2: expectedL2,
        actual_l2: actualL2,
        diff_l2: actualL2 - expectedL2,
        expected_total: expectedL1 + expectedL2,
        actual_total: actualL1 + actualL2,
        diff_total: (actualL1 + actualL2) - (expectedL1 + expectedL2),
        tx_count: Number(row.tx_count),
        status: ((actualL1 + actualL2) - (expectedL1 + expectedL2)) === 0
          ? '✅ MATCH'
          : ((actualL1 + actualL2) > (expectedL1 + expectedL2) ? '🔴 OVER (과지급)' : '🟡 UNDER (미지급)')
      })
    }

    return c.json({
      success: true,
      audit_kind: 'user_l1l2_precision_readonly',
      taken_at_kst: new Date(Date.now() + 9*60*60*1000).toISOString().replace('T',' ').replace('Z',''),
      ratios: { L1: '20%', L2: '10%' },
      target: {
        user_id: target.id, name: target.name, email: target.email,
        qkey_balance_current: target.qkey_balance,
        referrer_id: target.referrer_id,
        created_kst: target.created_kst,
      },
      l1_summary: {
        member_count: l1Users.length,
        total_daily_qkey: l1DailySumQkey,
        expected_match_to_target: expectedL1Match,
      },
      l2_summary: {
        member_count: l2Users.length,
        total_daily_qkey: l2DailySumQkey,
        expected_match_to_target: expectedL2Match,
      },
      expected_total_match_per_business_day: expectedTotalMatch,
      mismatch_by_date: mismatchByDate,
      referral_rewards_ledger_by_paid_date: rrDailyRows,
      l1_detail: l1Detail,
      l2_detail: l2Detail,
      notes: [
        '영구룰: L1=20%, L2=10% — 본 진단 산식은 이 비율로 고정',
        '영구룰: staking.daily_rate D1 직접 조회 — amount 추정 금지',
        '영구룰 #휴일진입자 보호: 각 staking.start_kst_date 시점 활성 여부로 일자별 expected 동적 계산',
        '영구룰 #cron 단일화: reward_date = paid_date 직전 영업일 (ledger 매핑 우선, 없으면 derived)',
        '평일이 아닌 KST 일자(토/일/공휴일)는 expected = 0 (cron 발생 안 함)',
        'expected_total_match_per_business_day 는 현재 시점 활성 staking 전체 합 — 참고용',
        'mismatch_by_date 의 expected_l1/l2 는 그 날짜의 활성 staking 만 합산한 동적 값',
        'diff_total > 0 = 과지급 (이중지급 가능성) / diff_total < 0 = 미지급 (백필 필요)',
        '이 엔드포인트는 read-only — DB UPDATE 0건',
      ]
    })
  } catch (error: any) {
    console.error('user-l1l2-precision-audit error:', error)
    return c.json({ error: error?.message || String(error) }, 500)
  }
})

// ============================================================
// /api/diag/lucky4492-permanent-rule-correction  (2026-05-13)
// ------------------------------------------------------------
// 사장님 명령: "lucky4492 도 영구 룰 기준으로 실행하라!"
//
// 영구 룰 정밀 분석 결과 (D1 직접 조회):
//   L2 referee 8명: 71,72,75,78,79,80,83 (모두 5/6 start) + 88 (5/12 start)
//   L1 referee 1명: 70 박원태 s82 (5/6 start, 7000 × 0.7%)
//
//   일자별 영구 룰 expected vs actual:
//     5/6 reward → 5/7 paid: L1 1470 + L2 1125 (7명) = 2595 ✅ MATCH
//     5/7 reward → 5/8 paid: L1 1470 + L2 1125 (7명) = 2595
//                             → 정상 cron tx (2636~2657, ref_id 650~671) 발생 후
//                                10:57 에 8건 중복 백필 (NULL ref_id) → +2,595 OVER 🔴
//     5/10 reward → 5/11 paid: L1 1470 + L2 1125 (7명) = 2595
//                             → tx 만 존재 (2189~2220, NULL ref_id), ledger 누락 ⚠️
//     5/11 reward → 5/12 paid: 2595 ✅ MATCH
//     5/12 reward → 5/13 paid: L1 1470 + L2 1350 (8명, +88 신규) = 2820 ✅ MATCH
//
// 보정 액션 (영구 룰 기준):
//   A) 5/8 DOUBLE PAYMENT 환수: tx 8건 reversal (-2,595 QKEY)
//      대상 tx_id: 1979, 1983, 1986, 1992, 2001, 2004, 2007, 2010 (NULL ref_id, KST 10:57)
//      방법: type='admin_adjustment', amount=-금액, 잔액 차감
//      description: '보정 환수 (5/8 이중지급 정정) - 영구 룰'
//   B) 5/11 ledger backfill: referral_rewards 8건 INSERT (QKEY 변동 없음, audit 트레이서빌리티만)
//      각 tx 와 동일한 amount/level 로 reward_date=2026-05-10, paid_date=2026-05-11
//      staking_id 명시 (영구 인프라 G2-B)
//
// 동작:
//   - DRY_RUN (default): 환수/백필 대상 정확 식별 + 사전검증
//   - ?confirm=GO: 실제 EXEC
// ============================================================
app.get('/api/diag/lucky4492-permanent-rule-correction', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: '관리자 인증이 필요합니다' }, 401)
  const confirm = c.req.query('confirm') || ''
  const isExec = confirm === 'GO'

  try {
    const db = c.env.DB
    const TARGET_USER_ID = 69  // lucky4492 (김연심2)
    const TARGET_EMAIL = 'lucky4492'

    // 영구 인프라 idempotent ALTER
    let stakingIdColAdded = false
    let stakingIdColExisted = false
    try {
      const pragmaRes = await db.prepare(`PRAGMA table_info(referral_rewards)`).all()
      const cols = ((pragmaRes.results as any[]) || []).map((r: any) => r.name)
      stakingIdColExisted = cols.includes('staking_id')
      if (!stakingIdColExisted) {
        await db.prepare(`ALTER TABLE referral_rewards ADD COLUMN staking_id INTEGER`).run()
        try { await db.prepare(`CREATE INDEX IF NOT EXISTS idx_referral_rewards_staking_id ON referral_rewards(staking_id)`).run() } catch {}
        try { await db.prepare(`CREATE INDEX IF NOT EXISTS idx_referral_rewards_composite ON referral_rewards(referrer_id, referee_id, level, staking_id, reward_date)`).run() } catch {}
        stakingIdColAdded = true
      }
    } catch (e: any) {
      console.error('lucky4492 ALTER 실패 (계속):', e?.message)
    }

    // ====================== 사전 검증 ======================
    const user = await db.prepare(
      `SELECT id, email, name, qkey_balance FROM users WHERE id = ?`
    ).bind(TARGET_USER_ID).first() as any
    if (!user) return c.json({ error: 'lucky4492 (u#69) not found' }, 404)
    if (user.email !== TARGET_EMAIL) {
      return c.json({ error: `email mismatch: expected=${TARGET_EMAIL} actual=${user.email}` }, 400)
    }

    // ====================== ACTION A: 5/8 DOUBLE PAYMENT 환수 ======================
    // 8건 tx_id: 1979, 1983, 1986, 1992, 2001, 2004, 2007, 2010
    const DUP_TX_IDS = [1979, 1983, 1986, 1992, 2001, 2004, 2007, 2010]
    const dupTxs: any[] = []
    for (const tid of DUP_TX_IDS) {
      const row = await db.prepare(`
        SELECT id, user_id, type, coin_type, amount, description, ref_id,
               datetime(created_at, '+9 hours') AS created_at_kst
        FROM transactions WHERE id = ?
      `).bind(tid).first() as any
      dupTxs.push(row)
    }
    // 사전 검증: 모두 user_id=69, type=referral_reward, ref_id=NULL, KST 2026-05-08
    const dupValidation = dupTxs.map((t: any) => ({
      tx_id: t?.id,
      ok: t && Number(t.user_id) === TARGET_USER_ID
          && t.type === 'referral_reward'
          && t.coin_type === 'QKEY'
          && (t.ref_id === null || t.ref_id === undefined)
          && String(t.created_at_kst || '').startsWith('2026-05-08'),
      user_id: t?.user_id,
      type: t?.type,
      amount: t?.amount,
      ref_id: t?.ref_id,
      created_at_kst: t?.created_at_kst,
    }))
    const dupAllOk = dupValidation.every(v => v.ok)
    const dupTotal = dupTxs.reduce((s, t) => s + Number(t?.amount || 0), 0)
    const dupExpectedTotal = 2595  // 영구 룰 expected

    // 이미 환수된 적 있는지 가드 (ref_id 패턴)
    const reversalRefIdPattern = 'rev_508_dup_u69_tx'
    const existingReversalRes = await db.prepare(`
      SELECT id, ref_id, amount FROM transactions
      WHERE user_id = ? AND type = 'admin_adjustment'
        AND ref_id LIKE ?
    `).bind(TARGET_USER_ID, reversalRefIdPattern + '%').all()
    const existingReversals = (existingReversalRes.results as any[]) || []
    const alreadyReversed = existingReversals.length > 0

    // ====================== ACTION B: 5/11 ledger backfill ======================
    // 8건 tx_id: 2189(L1 1470), 2193(75), 2196(150), 2202(150), 2211(75), 2214(75), 2217(525), 2220(75)
    // reward_date=2026-05-10, paid_date=2026-05-11
    // mapping (영구 룰 기준):
    const LEDGER_BF_TX = [
      { tx_id: 2189, level: 1, amount: 1470, referee_id: 70, staking_id: 82, original_amount: 7350 },  // 7000*0.007*150=7350
      { tx_id: 2193, level: 2, amount: 75,   referee_id: 71, staking_id: 87, original_amount: 750 },   // 1000*0.005*150=750
      { tx_id: 2196, level: 2, amount: 150,  referee_id: 72, staking_id: 78, original_amount: 1500 },  // 2000*0.005*150=1500
      { tx_id: 2202, level: 2, amount: 150,  referee_id: 75, staking_id: 86, original_amount: 1500 },
      { tx_id: 2211, level: 2, amount: 75,   referee_id: 78, staking_id: 85, original_amount: 750 },
      { tx_id: 2214, level: 2, amount: 75,   referee_id: 79, staking_id: 83, original_amount: 750 },
      { tx_id: 2217, level: 2, amount: 525,  referee_id: 80, staking_id: 79, original_amount: 5250 }, // 5000*0.007*150=5250
      { tx_id: 2220, level: 2, amount: 75,   referee_id: 83, staking_id: 88, original_amount: 750 },
    ]
    const ledgerBfValidation: any[] = []
    for (const m of LEDGER_BF_TX) {
      const tx = await db.prepare(`
        SELECT id, user_id, type, amount, ref_id,
               datetime(created_at, '+9 hours') AS created_at_kst
        FROM transactions WHERE id = ?
      `).bind(m.tx_id).first() as any
      // 기존 ledger row 가 이미 있는지 가드
      const existingLedger = await db.prepare(`
        SELECT id FROM referral_rewards
        WHERE referrer_id = ? AND referee_id = ? AND level = ?
          AND reward_date = '2026-05-10'
      `).bind(TARGET_USER_ID, m.referee_id, m.level).first()
      ledgerBfValidation.push({
        ...m,
        tx_user_id: tx?.user_id,
        tx_amount: tx?.amount,
        tx_ref_id: tx?.ref_id,
        tx_created_at_kst: tx?.created_at_kst,
        tx_amount_match: Number(tx?.amount || 0) === m.amount,
        tx_user_match: Number(tx?.user_id || 0) === TARGET_USER_ID,
        tx_kst_match: String(tx?.created_at_kst || '').startsWith('2026-05-11'),
        ledger_already_exists: !!existingLedger,
      })
    }
    const ledgerBfAllOk = ledgerBfValidation.every(v =>
      v.tx_amount_match && v.tx_user_match && v.tx_kst_match && !v.ledger_already_exists
    )

    // ====================== DRY_RUN 반환 ======================
    if (!isExec) {
      return c.json({
        success: true,
        mode: 'DRY_RUN',
        user: { id: user.id, email: user.email, name: user.name, qkey_balance: user.qkey_balance },
        g2b_schema: {
          staking_id_col_existed_before: stakingIdColExisted,
          staking_id_col_added_now: stakingIdColAdded,
        },
        action_A_dup_reversal: {
          target_tx_ids: DUP_TX_IDS,
          dup_total_qkey: dupTotal,
          expected_total_qkey: dupExpectedTotal,
          total_matches: dupTotal === dupExpectedTotal,
          all_tx_validation_ok: dupAllOk,
          already_reversed: alreadyReversed,
          existing_reversal_count: existingReversals.length,
          existing_reversals: existingReversals,
          tx_details: dupValidation,
          balance_after_reversal: user.qkey_balance - dupTotal,
          ready: dupAllOk && dupTotal === dupExpectedTotal && !alreadyReversed,
        },
        action_B_ledger_backfill: {
          target_count: LEDGER_BF_TX.length,
          target_total_qkey: LEDGER_BF_TX.reduce((s, m) => s + m.amount, 0),
          all_validation_ok: ledgerBfAllOk,
          balance_no_change: true,
          mappings: ledgerBfValidation,
          ready: ledgerBfAllOk,
        },
        permanent_rule_summary: {
          rule_l1: '20% (referee daily × 0.20)',
          rule_l2: '10% (referee daily × 0.10)',
          rule_data_source: 'staking.daily_rate D1 직접 조회',
          rule_double_payment: '절대 금지 — 5/8 위반 발견 → 환수',
          rule_bottom_up: 'leaf staking 별 4중 가드 (ref_id, broad EXISTS, refereeId+level, staking_id)',
          rule_holiday_protection: '휴일 진입자 보호 — 5/12 referee=88 신규 진입 인정',
        },
        notes: [
          '영구 룰 기준 분석 완료 — lucky4492 위반 = 1건 (5/8 +2595 OVER)',
          '5/11 tx 는 금액 정당, ledger만 누락 → backfill 로 audit 트레이서빌리티 회복',
          '실제 EXEC 하려면 ?confirm=GO 추가',
        ],
      })
    }

    // ====================== EXEC GATE ======================
    if (alreadyReversed) {
      return c.json({
        success: false,
        mode: 'EXEC_BLOCKED',
        error: '5/8 환수 이미 적용됨 — 이중 환수 차단',
        existing_reversals: existingReversals,
      }, 400)
    }
    if (!dupAllOk || dupTotal !== dupExpectedTotal) {
      return c.json({
        success: false,
        mode: 'EXEC_BLOCKED',
        error: 'Action A 사전 검증 실패',
        validation: dupValidation,
        dup_total: dupTotal,
        expected: dupExpectedTotal,
      }, 400)
    }
    if (!ledgerBfAllOk) {
      return c.json({
        success: false,
        mode: 'EXEC_BLOCKED',
        error: 'Action B 사전 검증 실패',
        validation: ledgerBfValidation,
      }, 400)
    }

    // ====================== ACTION A EXEC: 5/8 환수 ======================
    // 8건 reversal — type='admin_adjustment', amount=-<원금>, ref_id 고정 패턴
    const reversalResults: any[] = []
    for (let i = 0; i < dupTxs.length; i++) {
      const t = dupTxs[i]
      const revRefId = `${reversalRefIdPattern}${t.id}`
      // ref_id 가드 (이중 환수 방지)
      const exist = await db.prepare(`SELECT id FROM transactions WHERE ref_id = ?`).bind(revRefId).first()
      if (exist) {
        reversalResults.push({ tx_id: t.id, skipped: 'ref_id exists', ref_id: revRefId })
        continue
      }
      const res = await db.prepare(`
        INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
        VALUES (?, 'admin_adjustment', 'QKEY', ?, ?, ?)
      `).bind(
        TARGET_USER_ID,
        -Number(t.amount),
        `보정 환수 (5/8 이중지급 정정) - 영구 룰 #이중지급 절대 금지`,
        revRefId,
      ).run()
      await db.prepare(
        `UPDATE users SET qkey_balance = COALESCE(qkey_balance,0) - ? WHERE id = ?`
      ).bind(Number(t.amount), TARGET_USER_ID).run()
      reversalResults.push({
        original_tx_id: t.id,
        original_amount: t.amount,
        reversal_tx_id: Number(res.meta?.last_row_id || 0),
        reversal_amount: -Number(t.amount),
        ref_id: revRefId,
      })
    }
    const reversalSum = reversalResults.reduce((s, r: any) => s + Number(r.reversal_amount || 0), 0)

    // ====================== ACTION B EXEC: 5/11 ledger backfill ======================
    const ledgerInserted: any[] = []
    for (const m of LEDGER_BF_TX) {
      try {
        await db.prepare(`
          INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, created_at, staking_id)
          VALUES (?, ?, ?, ?, ?, '2026-05-10', '2026-05-11', datetime('now'), ?)
        `).bind(
          TARGET_USER_ID, m.referee_id, m.level,
          m.original_amount, m.amount,
          m.staking_id,
        ).run()
        ledgerInserted.push({
          referee_id: m.referee_id, level: m.level,
          amount: m.amount, original_amount: m.original_amount,
          staking_id: m.staking_id,
          linked_tx_id: m.tx_id,
        })
      } catch (e: any) {
        ledgerInserted.push({ ...m, error: e?.message })
      }
    }

    // 최종 잔액 재조회
    const afterUser = await db.prepare(
      `SELECT id, email, qkey_balance FROM users WHERE id = ?`
    ).bind(TARGET_USER_ID).first()

    return c.json({
      success: true,
      mode: 'EXEC',
      user_before: { qkey_balance: user.qkey_balance },
      user_after: afterUser,
      action_A_reversal: {
        target_count: DUP_TX_IDS.length,
        reversal_count: reversalResults.length,
        reversal_sum_qkey: reversalSum,  // 음수
        absolute_recovered: Math.abs(reversalSum),
        details: reversalResults,
      },
      action_B_ledger_backfill: {
        inserted_count: ledgerInserted.length,
        inserted_sum_qkey: ledgerInserted.reduce((s, r: any) => s + Number(r.amount || 0), 0),
        details: ledgerInserted,
      },
      permanent_rule_compliance: {
        l1_pct: '20%',
        l2_pct: '10%',
        double_payment: '5/8 환수 완료 — 영구 룰 #이중지급 절대 금지 회복',
        ledger_tracability: '5/11 referral_rewards 8 rows 백필 완료',
      },
      note: 'lucky4492 영구 룰 기준 보정 완료. balance 음수 = 환수, ledger = audit 트레이서빌리티 회복 (QKEY 변동 없음)',
    })
  } catch (error: any) {
    console.error('lucky4492-permanent-rule-correction error:', error)
    return c.json({ error: error?.message || String(error), code: error?.code }, 500)
  }
})

// ============================================================================
// H plan 5/14 cron 모니터링 endpoint (2026-05-13 작성, 5/14 08:00 KST cron 후 사용)
// ============================================================================
//   목적: 영구 룰 100% 준수 자동 cron 첫 가동 검증
//   사용: GET /api/diag/cron-h-plan-monitor?password=...&paid_date=2026-05-14
//   기본: paid_date = 오늘 KST (호출 시점)
//
//   검증 항목 (C1 ~ C8):
//     C1. cron 실행 흔적     — paid_date 의 daily_rewards/referral_rewards/transactions 존재
//     C2. staking_id 100%   — 신규 referral_rewards 모든 행 staking_id IS NOT NULL (H plan 핵심)
//     C3. 5-tuple 유니크성   — (referrer_id, referee_id, level, staking_id, reward_date) 중복 0
//     C4. ref_id 1:1 매핑   — 모든 신규 transactions 가 ledger row 와 1:1
//     C5. 영구 룰 (L1=20%, L2=10%) — 모든 referral_rewards.reward_amount = ROUND(original_amount × ratio)
//     C6. 다중 staking referee — referee 의 활성 staking 수 × referrer 매칭 완전성
//     C7. 휴일진입자 보호    — 신규 진입자가 정상 매칭 진입
//     C8. 이중지급 부재      — daily_rewards / referral_rewards / transactions 중복 0
//
//   추가 출력: summary, per-user breakdown, 모든 검증 PASS/FAIL 상태
app.get('/api/diag/cron-h-plan-monitor', async (c) => {
  try {
    const password = c.req.query('password') || ''
    if (password !== ADMIN_PW) return c.json({ error: 'Unauthorized' }, 401)
    const db = c.env.DB

    // 기본 paid_date = 오늘 KST
    const now = new Date()
    const todayKst = kstDateStr(now)
    const paidDate = c.req.query('paid_date') || todayKst
    const yesterdayKst = kstDateStr(new Date(new Date(paidDate + 'T00:00:00+09:00').getTime() - 24 * 60 * 60 * 1000))

    // ─────────────────────────────────────────────────────────────────────
    // C1. cron 실행 흔적 (paid_date 의 신규 행 수)
    // ─────────────────────────────────────────────────────────────────────
    const drCntRow = await db.prepare(`
      SELECT COUNT(*) as cnt, COALESCE(SUM(usdt_amount), 0) as sum_qkey
      FROM daily_rewards WHERE paid_date = ?
    `).bind(paidDate).first() as any
    const rrCntRow = await db.prepare(`
      SELECT COUNT(*) as cnt,
             SUM(CASE WHEN level=1 THEN 1 ELSE 0 END) as l1_cnt,
             SUM(CASE WHEN level=2 THEN 1 ELSE 0 END) as l2_cnt,
             COALESCE(SUM(reward_amount), 0) as sum_qkey
      FROM referral_rewards WHERE paid_date = ?
    `).bind(paidDate).first() as any
    // transactions 는 paid_date 컬럼이 없음 — daily_rewards/referral_rewards.id 를 통한 매핑
    const txDqRow = await db.prepare(`
      SELECT COUNT(*) as cnt, COALESCE(SUM(t.amount), 0) as sum_qkey
      FROM transactions t
      INNER JOIN daily_rewards dr ON dr.id = t.ref_id
      WHERE t.type = 'daily_qkey' AND dr.paid_date = ?
    `).bind(paidDate).first() as any
    const txRrRow = await db.prepare(`
      SELECT COUNT(*) as cnt, COALESCE(SUM(t.amount), 0) as sum_qkey
      FROM transactions t
      INNER JOIN referral_rewards rr ON rr.id = t.ref_id
      WHERE t.type = 'referral_reward' AND rr.paid_date = ?
    `).bind(paidDate).first() as any

    const c1_drCount = Number(drCntRow?.cnt || 0)
    const c1_rrCount = Number(rrCntRow?.cnt || 0)
    const c1_l1Count = Number(rrCntRow?.l1_cnt || 0)
    const c1_l2Count = Number(rrCntRow?.l2_cnt || 0)
    const c1_txDqCount = Number(txDqRow?.cnt || 0)
    const c1_txRrCount = Number(txRrRow?.cnt || 0)
    const c1_passed = c1_drCount > 0  // cron 이 실행되었으면 최소 daily_rewards 1건 이상

    // ─────────────────────────────────────────────────────────────────────
    // C2. staking_id 100% 채움 (H plan 핵심 — 신규 referral_rewards 의무)
    // ─────────────────────────────────────────────────────────────────────
    const c2NullRows = await db.prepare(`
      SELECT id, referrer_id, referee_id, level, reward_date, original_amount, reward_amount
      FROM referral_rewards
      WHERE paid_date = ? AND staking_id IS NULL
      ORDER BY id ASC
      LIMIT 50
    `).bind(paidDate).all()
    const c2_nullCount = c2NullRows.results.length
    const c2_passed = c2_nullCount === 0

    // ─────────────────────────────────────────────────────────────────────
    // C3. 5-tuple 유니크성 (referrer, referee, level, staking_id, reward_date)
    // ─────────────────────────────────────────────────────────────────────
    const c3DupRows = await db.prepare(`
      SELECT referrer_id, referee_id, level, staking_id, reward_date, COUNT(*) as dup_cnt
      FROM referral_rewards
      WHERE paid_date = ?
      GROUP BY referrer_id, referee_id, level, staking_id, reward_date
      HAVING COUNT(*) > 1
      LIMIT 50
    `).bind(paidDate).all()
    const c3_dupCount = c3DupRows.results.length
    const c3_passed = c3_dupCount === 0

    // daily_rewards 중복 (user_id, staking_id, reward_date)
    const c3DrDupRows = await db.prepare(`
      SELECT user_id, staking_id, reward_date, COUNT(*) as dup_cnt
      FROM daily_rewards
      WHERE paid_date = ?
      GROUP BY user_id, staking_id, reward_date
      HAVING COUNT(*) > 1
      LIMIT 50
    `).bind(paidDate).all()
    const c3_drDupCount = c3DrDupRows.results.length
    const c3_passed_full = c3_passed && c3_drDupCount === 0

    // ─────────────────────────────────────────────────────────────────────
    // C4. ref_id 1:1 매핑 — transactions ↔ daily_rewards / referral_rewards
    // ─────────────────────────────────────────────────────────────────────
    // 4-1. daily_rewards 중 transactions 가 없는 행 (지급 누락)
    const c4OrphanDr = await db.prepare(`
      SELECT dr.id, dr.user_id, dr.staking_id, dr.reward_date, dr.usdt_amount
      FROM daily_rewards dr
      LEFT JOIN transactions t ON t.ref_id = dr.id AND t.type = 'daily_qkey'
      WHERE dr.paid_date = ? AND t.id IS NULL
      LIMIT 50
    `).bind(paidDate).all()
    // 4-2. referral_rewards 중 transactions 가 없는 행 (지급 누락, reward_amount > 0 만)
    const c4OrphanRr = await db.prepare(`
      SELECT rr.id, rr.referrer_id, rr.referee_id, rr.level, rr.reward_date, rr.reward_amount
      FROM referral_rewards rr
      LEFT JOIN transactions t ON t.ref_id = rr.id AND t.type = 'referral_reward'
      WHERE rr.paid_date = ? AND rr.reward_amount > 0 AND t.id IS NULL
      LIMIT 50
    `).bind(paidDate).all()
    // 4-3. transactions 중 ref_id 가 ledger 에 없는 행 (고아 tx — 이중지급 가능성)
    const c4OrphanTxDq = await db.prepare(`
      SELECT t.id, t.user_id, t.amount, t.ref_id, t.created_at
      FROM transactions t
      LEFT JOIN daily_rewards dr ON dr.id = t.ref_id
      WHERE t.type = 'daily_qkey'
        AND date(t.created_at, '+9 hours') = ?
        AND dr.id IS NULL
      LIMIT 50
    `).bind(paidDate).all()
    const c4OrphanTxRr = await db.prepare(`
      SELECT t.id, t.user_id, t.amount, t.ref_id, t.created_at
      FROM transactions t
      LEFT JOIN referral_rewards rr ON rr.id = t.ref_id
      WHERE t.type = 'referral_reward'
        AND date(t.created_at, '+9 hours') = ?
        AND rr.id IS NULL
      LIMIT 50
    `).bind(paidDate).all()
    const c4_orphanDrCount = c4OrphanDr.results.length
    const c4_orphanRrCount = c4OrphanRr.results.length
    const c4_orphanTxDqCount = c4OrphanTxDq.results.length
    const c4_orphanTxRrCount = c4OrphanTxRr.results.length
    const c4_passed = c4_orphanDrCount === 0 && c4_orphanRrCount === 0 &&
                      c4_orphanTxDqCount === 0 && c4_orphanTxRrCount === 0

    // ─────────────────────────────────────────────────────────────────────
    // C5. 영구 룰 (L1=20%, L2=10%) — reward_amount = ROUND(original_amount × ratio)
    // ─────────────────────────────────────────────────────────────────────
    //   ※ 200% cap 부분 지급은 예외 (reward_amount < expected 인 경우 OK)
    //      → reward_amount > expected 인 경우만 위반
    const c5L1Violations = await db.prepare(`
      SELECT id, referrer_id, referee_id, original_amount, reward_amount, reward_date,
             CAST(ROUND(original_amount * 0.20) AS INTEGER) as expected
      FROM referral_rewards
      WHERE paid_date = ? AND level = 1
        AND reward_amount > CAST(ROUND(original_amount * 0.20) AS INTEGER)
      LIMIT 50
    `).bind(paidDate).all()
    const c5L2Violations = await db.prepare(`
      SELECT id, referrer_id, referee_id, original_amount, reward_amount, reward_date,
             CAST(ROUND(original_amount * 0.10) AS INTEGER) as expected
      FROM referral_rewards
      WHERE paid_date = ? AND level = 2
        AND reward_amount > CAST(ROUND(original_amount * 0.10) AS INTEGER)
      LIMIT 50
    `).bind(paidDate).all()
    const c5_l1ViolCount = c5L1Violations.results.length
    const c5_l2ViolCount = c5L2Violations.results.length
    const c5_passed = c5_l1ViolCount === 0 && c5_l2ViolCount === 0

    // ─────────────────────────────────────────────────────────────────────
    // C6. 다중 staking referee 매칭 완전성
    //     어제(reward_date 기준) 활성 staking 이 N개인 referee 의 referrer 들이
    //     N건 모두 매칭됐는지 검증 (H plan 4중 가드 동작 확인)
    // ─────────────────────────────────────────────────────────────────────
    //   reward_date = paidDate 직전 영업일 (cron 은 어제 매출을 오늘 처리)
    //   단순화: paidDate 의 referral_rewards.reward_date 집합으로부터 검증
    const c6RefereeStakeCnt = await db.prepare(`
      SELECT referee_id, reward_date, COUNT(DISTINCT staking_id) as referee_staking_cnt
      FROM referral_rewards
      WHERE paid_date = ? AND staking_id IS NOT NULL
      GROUP BY referee_id, reward_date
      HAVING referee_staking_cnt >= 2
    `).bind(paidDate).all()

    // 다중 staking referee 별로 모든 referrer 가 동일 staking_id 집합을 받았는지 확인
    const c6MissingMatches: any[] = []
    for (const r of c6RefereeStakeCnt.results) {
      const refereeId = r.referee_id
      const rewardDate = r.reward_date
      const expectedStakingCnt = r.referee_staking_cnt as number

      // 해당 referee 의 L1/L2 referrer 각각이 받은 staking_id distinct 수
      const refByLevel = await db.prepare(`
        SELECT level, referrer_id, COUNT(DISTINCT staking_id) as got_cnt
        FROM referral_rewards
        WHERE paid_date = ? AND referee_id = ? AND reward_date = ? AND staking_id IS NOT NULL
        GROUP BY level, referrer_id
      `).bind(paidDate, refereeId, rewardDate).all()

      for (const row of refByLevel.results) {
        const gotCnt = Number(row.got_cnt || 0)
        if (gotCnt < expectedStakingCnt) {
          c6MissingMatches.push({
            referee_id: refereeId,
            reward_date: rewardDate,
            level: row.level,
            referrer_id: row.referrer_id,
            expected_staking_cnt: expectedStakingCnt,
            got_staking_cnt: gotCnt,
            missing_cnt: expectedStakingCnt - gotCnt,
          })
        }
      }
    }
    const c6_multiRefereeCount = c6RefereeStakeCnt.results.length
    const c6_missingCount = c6MissingMatches.length
    const c6_passed = c6_missingCount === 0

    // ─────────────────────────────────────────────────────────────────────
    // C7. 휴일진입자 보호 — 신규 진입 referee 가 정상 매칭에 진입
    //     paidDate 의 referral_rewards 중 referee 의 staking.start_date_kst 가
    //     reward_date 이하인지 (시점 활성 여부) 확인
    // ─────────────────────────────────────────────────────────────────────
    const c7InvalidRows = await db.prepare(`
      SELECT rr.id, rr.referrer_id, rr.referee_id, rr.level,
             rr.reward_date, rr.staking_id,
             date(s.start_date, '+9 hours') as start_kst_date
      FROM referral_rewards rr
      LEFT JOIN staking s ON s.id = rr.staking_id
      WHERE rr.paid_date = ? AND rr.staking_id IS NOT NULL
        AND (s.id IS NULL OR date(s.start_date, '+9 hours') > rr.reward_date)
      LIMIT 50
    `).bind(paidDate).all()
    const c7_invalidCount = c7InvalidRows.results.length
    const c7_passed = c7_invalidCount === 0

    // 신규 진입자 (start_kst_date >= paidDate-3 일) 가 paidDate 에 매칭 진입한 사례
    const c7NewEntrantsMatched = await db.prepare(`
      SELECT DISTINCT rr.referee_id,
             date(s.start_date, '+9 hours') as referee_start_kst,
             rr.reward_date
      FROM referral_rewards rr
      INNER JOIN staking s ON s.id = rr.staking_id
      WHERE rr.paid_date = ?
        AND date(s.start_date, '+9 hours') >= date(?, '-3 days')
      ORDER BY referee_start_kst DESC
      LIMIT 30
    `).bind(paidDate, paidDate).all()

    // ─────────────────────────────────────────────────────────────────────
    // C8. 이중지급 부재 — transactions ref_id 중복 (동일 ledger 에 다중 tx)
    // ─────────────────────────────────────────────────────────────────────
    const c8TxDupDq = await db.prepare(`
      SELECT t.ref_id, COUNT(*) as dup_cnt
      FROM transactions t
      INNER JOIN daily_rewards dr ON dr.id = t.ref_id
      WHERE t.type = 'daily_qkey' AND dr.paid_date = ?
      GROUP BY t.ref_id
      HAVING COUNT(*) > 1
      LIMIT 50
    `).bind(paidDate).all()
    const c8TxDupRr = await db.prepare(`
      SELECT t.ref_id, COUNT(*) as dup_cnt
      FROM transactions t
      INNER JOIN referral_rewards rr ON rr.id = t.ref_id
      WHERE t.type = 'referral_reward' AND rr.paid_date = ?
      GROUP BY t.ref_id
      HAVING COUNT(*) > 1
      LIMIT 50
    `).bind(paidDate).all()
    const c8_txDupDqCount = c8TxDupDq.results.length
    const c8_txDupRrCount = c8TxDupRr.results.length
    const c8_passed = c8_txDupDqCount === 0 && c8_txDupRrCount === 0

    // ─────────────────────────────────────────────────────────────────────
    // Summary metrics
    // ─────────────────────────────────────────────────────────────────────
    const affectedUsersDr = await db.prepare(`
      SELECT COUNT(DISTINCT user_id) as cnt FROM daily_rewards WHERE paid_date = ?
    `).bind(paidDate).first() as any
    const affectedRefDistinct = await db.prepare(`
      SELECT COUNT(DISTINCT referrer_id) as cnt FROM referral_rewards WHERE paid_date = ?
    `).bind(paidDate).first() as any
    const affectedRefereeDistinct = await db.prepare(`
      SELECT COUNT(DISTINCT referee_id) as cnt FROM referral_rewards WHERE paid_date = ?
    `).bind(paidDate).first() as any

    // 모든 check passed 여부
    const allPassed = c1_passed && c2_passed && c3_passed_full && c4_passed &&
                      c5_passed && c6_passed && c7_passed && c8_passed

    return c.json({
      success: true,
      title: 'H plan 5/14 cron 모니터링 — 영구 룰 100% 준수 검증',
      paid_date: paidDate,
      yesterday_kst_reference: yesterdayKst,
      checked_at_kst: kstDateStr(now) + ' ' + now.toISOString().split('T')[1].split('.')[0] + ' UTC',
      // ─────────── 최종 PASS/FAIL ───────────
      all_passed: allPassed,
      verdict: allPassed
        ? '✅ 영구 룰 100% 준수 — H plan cron 정상 작동 검증 완료'
        : '⚠️ 위반 사항 발견 — 아래 상세 검토 필요',
      // ─────────── Summary ───────────
      summary: {
        daily_rewards: {
          count: c1_drCount,
          sum_qkey: Number(drCntRow?.sum_qkey || 0),
          tx_count: c1_txDqCount,
          tx_sum_qkey: Number(txDqRow?.sum_qkey || 0),
        },
        referral_rewards: {
          count: c1_rrCount,
          l1_count: c1_l1Count,
          l2_count: c1_l2Count,
          sum_qkey: Number(rrCntRow?.sum_qkey || 0),
          tx_count: c1_txRrCount,
          tx_sum_qkey: Number(txRrRow?.sum_qkey || 0),
        },
        affected_users: {
          daily_rewards_users: Number(affectedUsersDr?.cnt || 0),
          referrers: Number(affectedRefDistinct?.cnt || 0),
          referees: Number(affectedRefereeDistinct?.cnt || 0),
        },
      },
      // ─────────── 8가지 검증 항목 ───────────
      checks: {
        C1_cron_executed: {
          passed: c1_passed,
          description: 'cron 실행 흔적 (paid_date 의 신규 행)',
          daily_rewards_count: c1_drCount,
          referral_rewards_count: c1_rrCount,
          transactions_count: c1_txDqCount + c1_txRrCount,
        },
        C2_staking_id_100_percent: {
          passed: c2_passed,
          description: 'H plan 핵심 — 신규 referral_rewards 모든 행 staking_id IS NOT NULL',
          null_count: c2_nullCount,
          samples: c2NullRows.results.slice(0, 10),
        },
        C3_5tuple_unique: {
          passed: c3_passed_full,
          description: '(referrer_id, referee_id, level, staking_id, reward_date) 5-tuple 유니크',
          rr_duplicate_groups: c3_dupCount,
          dr_duplicate_groups: c3_drDupCount,
          rr_samples: c3DupRows.results.slice(0, 10),
          dr_samples: c3DrDupRows.results.slice(0, 10),
        },
        C4_ref_id_1to1: {
          passed: c4_passed,
          description: 'ref_id 1:1 매핑 (transactions ↔ ledger)',
          orphan_dr_no_tx: c4_orphanDrCount,
          orphan_rr_no_tx: c4_orphanRrCount,
          orphan_tx_dq_no_ledger: c4_orphanTxDqCount,
          orphan_tx_rr_no_ledger: c4_orphanTxRrCount,
          samples: {
            orphan_dr: c4OrphanDr.results.slice(0, 5),
            orphan_rr: c4OrphanRr.results.slice(0, 5),
            orphan_tx_dq: c4OrphanTxDq.results.slice(0, 5),
            orphan_tx_rr: c4OrphanTxRr.results.slice(0, 5),
          },
        },
        C5_permanent_ratio: {
          passed: c5_passed,
          description: '영구 룰 L1=20%, L2=10% (reward_amount ≤ ROUND(original × ratio); cap 부분 지급 허용)',
          l1_over_violation_count: c5_l1ViolCount,
          l2_over_violation_count: c5_l2ViolCount,
          l1_samples: c5L1Violations.results.slice(0, 10),
          l2_samples: c5L2Violations.results.slice(0, 10),
        },
        C6_multi_staking_completeness: {
          passed: c6_passed,
          description: '다중 staking referee 매칭 완전성 (H plan 4중 가드 동작 검증)',
          multi_staking_referees: c6_multiRefereeCount,
          missing_match_count: c6_missingCount,
          missing_samples: c6MissingMatches.slice(0, 20),
        },
        C7_holiday_entrant_protection: {
          passed: c7_passed,
          description: '휴일진입자 보호 — staking.start_kst_date <= reward_date 검증',
          invalid_count: c7_invalidCount,
          invalid_samples: c7InvalidRows.results.slice(0, 10),
          new_entrants_matched: c7NewEntrantsMatched.results,
        },
        C8_no_double_payment: {
          passed: c8_passed,
          description: '#이중지급 절대 금지 — transactions ref_id 중복 부재',
          tx_dq_duplicates: c8_txDupDqCount,
          tx_rr_duplicates: c8_txDupRrCount,
          dq_samples: c8TxDupDq.results.slice(0, 10),
          rr_samples: c8TxDupRr.results.slice(0, 10),
        },
      },
      // ─────────── 영구 룰 참조 ───────────
      permanent_rules_checked: [
        'L1=20%, L2=10% 절대',
        '#bottom-up: leaf first → parent matching',
        '#이중지급 절대 금지',
        '#일일 cron 단일화 (KST 08:00 GitHub Actions)',
        '#휴일진입자 보호 (각 staking start_kst_date 시점 활성 여부)',
        'staking.daily_rate D1 직접 조회',
        '1 USDT = 150 QKEY',
        'H plan: referral_rewards.staking_id 명시 (G2-B 영구 인프라)',
      ],
      usage: {
        endpoint: 'GET /api/diag/cron-h-plan-monitor?password=<ADMIN_PW>&paid_date=2026-05-14',
        call_when: 'KST 08:00 cron 실행 직후 (또는 has_more=false 워크플로 완료 후)',
        success_criteria: 'all_passed === true → 영구 룰 100% 준수 자동 cron 첫 가동 성공',
      },
    })
  } catch (error: any) {
    console.error('cron-h-plan-monitor error:', error)
    return c.json({ error: error?.message || String(error), code: error?.code }, 500)
  }
})

// ============================================================================
// illegal-type-audit (2026-05-19): 영구룰 위반 type 가감 대상 전수 산출
// ============================================================================
//   영구룰 #위반type가감 (2026-05-19 사장님 명령 2):
//     "어드민 관리 차감(admin_adjustment) 이 아닌데 영구룰 위반 type 으로 잔액에
//      영향을 준 경우, 그 amount 만큼 가감 조치한다."
//
//   합법 type: daily_qkey, referral_reward, swap_in, swap_out, admin_adjustment
//   위반 type: direct_referral, staking_reward, shop_purchase, shop_refund, etc.
//   read-only, DRY-RUN. DB 미수정.
//
//   사용: GET /api/diag/illegal-type-audit?key=<ADMIN_PW>&coin=QKEY
app.get('/api/diag/illegal-type-audit', async (c) => {
  const t0 = Date.now()
  try {
    const key = c.req.query('key') || c.req.query('password') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const coin = (c.req.query('coin') || 'QKEY').toUpperCase()
    const db = c.env.DB

    // 합법 type 정의 (영구룰 #관리자보정정당 적용)
    const LEGIT_TYPES = ['daily_qkey', 'referral_reward', 'swap_in', 'swap_out', 'admin_adjustment']
    const legitInClause = LEGIT_TYPES.map(t => `'${t}'`).join(',')

    // ── A. 위반 type tx 전체 SELECT ──
    const illegalTx = await db.prepare(`
      SELECT id, user_id, type, amount, description, ref_id, created_at,
             datetime(created_at, '+9 hours') AS kst_at
      FROM transactions
      WHERE coin_type = ?
        AND type NOT IN (${legitInClause})
      ORDER BY user_id ASC, created_at ASC, id ASC
    `).bind(coin).all()

    const rows = (illegalTx.results || []) as any[]

    // ── B. user_id 별 그룹 + type 별 합계 ──
    const byUser = new Map<number, { name?: string, email?: string, total_amount: number, total_count: number, types: Record<string, { cnt: number, sum: number, ids: number[] }> }>()
    for (const r of rows) {
      const uid = Number(r.user_id)
      const type = String(r.type)
      const amt = Number(r.amount)
      if (!byUser.has(uid)) byUser.set(uid, { total_amount: 0, total_count: 0, types: {} })
      const u = byUser.get(uid)!
      u.total_amount += amt
      u.total_count++
      if (!u.types[type]) u.types[type] = { cnt: 0, sum: 0, ids: [] }
      u.types[type].cnt++
      u.types[type].sum += amt
      u.types[type].ids.push(Number(r.id))
    }

    // ── C. 회원 정보 조인 ──
    const userIds = Array.from(byUser.keys())
    if (userIds.length > 0) {
      const ph = userIds.map(() => '?').join(',')
      const users = await db.prepare(`
        SELECT id, email, name, qkey_balance
        FROM users WHERE id IN (${ph})
      `).bind(...userIds).all()
      for (const u of (users.results || []) as any[]) {
        const e = byUser.get(Number(u.id))
        if (e) {
          e.email = String(u.email || '')
          e.name = String(u.name || '')
          ;(e as any).current_qkey_balance = Number(u.qkey_balance || 0)
        }
      }
    }

    // ── D. type 전체 합계 ──
    const typeTotals: Record<string, { cnt: number, sum: number, user_count: number }> = {}
    for (const r of rows) {
      const t = String(r.type)
      if (!typeTotals[t]) typeTotals[t] = { cnt: 0, sum: 0, user_count: 0 }
      typeTotals[t].cnt++
      typeTotals[t].sum += Number(r.amount)
    }
    for (const t of Object.keys(typeTotals)) {
      typeTotals[t].user_count = new Set(rows.filter(r => r.type === t).map(r => r.user_id)).size
    }

    // ── E. 사용자별 보고서 + 가감 후 예상 잔액 ──
    const report: any[] = []
    let grandTotalAdj = 0
    for (const [uid, e] of byUser.entries()) {
      const cur = (e as any).current_qkey_balance ?? null
      const expectedAfterAdjustment = cur != null ? cur - e.total_amount : null
      grandTotalAdj += e.total_amount
      report.push({
        user_id: uid,
        email: e.email || null,
        name: e.name || null,
        current_qkey_balance: cur,
        total_illegal_amount: e.total_amount,            // 가감해야 할 총량 (signed)
        total_illegal_count: e.total_count,
        expected_balance_after_adjustment: expectedAfterAdjustment,
        will_become_negative: expectedAfterAdjustment != null && expectedAfterAdjustment < 0,
        types: Object.entries(e.types).map(([type, info]) => ({
          type,
          count: info.cnt,
          sum: info.sum,
          tx_ids: info.ids,
        })),
      })
    }
    report.sort((a, b) => Math.abs(b.total_illegal_amount) - Math.abs(a.total_illegal_amount))

    return c.json({
      ok: true,
      mode: 'DRY-RUN',
      coin,
      legit_types_definition: LEGIT_TYPES,
      summary: {
        total_illegal_tx_count: rows.length,
        affected_users: byUser.size,
        grand_total_signed_amount: grandTotalAdj,
        users_will_become_negative_after_adjustment: report.filter(r => r.will_become_negative).length,
      },
      type_totals: typeTotals,
      report,
      note: '영구룰 #위반type가감 (2026-05-19 사장님 명령 2). DRY-RUN. EXEC 별도 endpoint 필요.',
      duration_ms: Date.now() - t0,
    })
  } catch (error: any) {
    return c.json({ error: error?.message || String(error), duration_ms: Date.now() - t0 }, 500)
  }
})

// ============================================================================
// user-ledger-replay (2026-05-19): 단일 회원 transactions 전체 chronological replay
// ============================================================================
//   목적: 사장님 명령 - 음수/불일치 회원의 DRY-RUN ledger replay
//   영구룰 #지상최고 (중복지급 절대금지): read-only, DB 미수정
//   running_balance 계산 + 위반 type 분리 + 마지막 잔액 vs 현재 qkey_balance 비교
//   사용: GET /api/diag/user-ledger-replay?key=<ADMIN_PW>&user_id=9&coin=QKEY
app.get('/api/diag/user-ledger-replay', async (c) => {
  const t0 = Date.now()
  try {
    const key = c.req.query('key') || c.req.query('password') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const userId = Number(c.req.query('user_id') || '0')
    const coin = (c.req.query('coin') || 'QKEY').toUpperCase()
    if (!userId) return c.json({ error: 'user_id required' }, 400)
    const db = c.env.DB

    // user info
    const user = await db.prepare(`
      SELECT id, email, name, qta_balance, qx_balance, usdt_balance, qkey_balance,
             usdt_withdrawable
      FROM users WHERE id = ?
    `).bind(userId).first() as any
    if (!user) return c.json({ error: `user_id ${userId} not found` }, 404)

    const balanceCol = coin === 'QKEY' ? 'qkey_balance'
                     : coin === 'USDT' ? 'usdt_balance'
                     : coin === 'QTA' ? 'qta_balance'
                     : coin === 'QX' ? 'qx_balance' : 'qkey_balance'
    const currentBalance = Number(user[balanceCol] || 0)

    // chronological transactions
    const txs = await db.prepare(`
      SELECT id, type, coin_type, amount, description, ref_id,
             created_at,
             datetime(created_at, '+9 hours') AS kst_at
      FROM transactions
      WHERE user_id = ? AND coin_type = ?
      ORDER BY created_at ASC, id ASC
    `).bind(userId, coin).all()

    const txList = (txs.results || []) as any[]

    // withdrawals (active states)
    const wds = await db.prepare(`
      SELECT id, amount, status,
             COALESCE(processed_at, created_at) AS event_at,
             datetime(COALESCE(processed_at, created_at), '+9 hours') AS kst_at
      FROM withdrawals
      WHERE user_id = ? AND coin_type = ?
        AND status IN ('approved','completed','processing','pending')
      ORDER BY event_at ASC, id ASC
    `).bind(userId, coin).all()
    const wdList = (wds.results || []) as any[]

    // 영구룰 정상 type
    const LEGIT_TYPES = new Set(['daily_qkey', 'referral_reward', 'swap_in', 'swap_out'])

    // chronological replay (tx + withdrawal 합쳐서 시간순)
    const events: any[] = []
    for (const t of txList) {
      events.push({
        kind: 'tx',
        event_at: t.created_at,
        kst_at: t.kst_at,
        id: Number(t.id),
        type: String(t.type),
        amount: Number(t.amount),
        description: String(t.description || ''),
        ref_id: t.ref_id != null ? Number(t.ref_id) : null,
        legit: LEGIT_TYPES.has(String(t.type)),
      })
    }
    for (const w of wdList) {
      events.push({
        kind: 'withdrawal',
        event_at: w.event_at,
        kst_at: w.kst_at,
        id: Number(w.id),
        type: `withdrawal_${w.status}`,
        amount: -Math.abs(Number(w.amount)),  // withdrawal 은 balance 감소
        description: `Withdrawal ${w.status}`,
        ref_id: null,
        legit: true,
      })
    }
    events.sort((a, b) => {
      if (a.event_at < b.event_at) return -1
      if (a.event_at > b.event_at) return 1
      // same timestamp: tx first then withdrawal
      if (a.kind !== b.kind) return a.kind === 'tx' ? -1 : 1
      return (a.id || 0) - (b.id || 0)
    })

    // running balance (영구룰 공식만)
    let runningLegit = 0
    let runningAll = 0
    const replay = events.map(e => {
      runningAll += e.amount
      if (e.legit) runningLegit += e.amount
      return {
        ...e,
        running_balance_legit: runningLegit,    // 영구룰 정상 type 만 누적
        running_balance_all: runningAll,        // 위반 type 포함 누적
      }
    })

    // 합계
    const sumByType: Record<string, { cnt: number, sum: number, legit: boolean }> = {}
    for (const e of events) {
      const key = e.type
      if (!sumByType[key]) sumByType[key] = { cnt: 0, sum: 0, legit: e.legit }
      sumByType[key].cnt++
      sumByType[key].sum += e.amount
    }

    // 검증
    const expectedLegitFinal = runningLegit
    const expectedAllFinal = runningAll
    const diffVsLegit = currentBalance - expectedLegitFinal
    const diffVsAll = currentBalance - expectedAllFinal

    // 영구룰 위반 type 집계
    const illegalTypes = Object.entries(sumByType)
      .filter(([_, v]) => !v.legit)
      .map(([type, v]) => ({ type, ...v }))

    return c.json({
      ok: true,
      user_id: userId,
      email: String(user.email || ''),
      name: String(user.name || ''),
      coin,
      current_balance: currentBalance,
      formula_legit: 'Σ(daily_qkey + referral_reward + swap_in + swap_out) - Σ(withdrawals active)',
      sum_by_type: sumByType,
      illegal_types: illegalTypes,
      event_count: events.length,
      tx_count: txList.length,
      withdrawal_count: wdList.length,
      // 마지막 5건은 보여주고 전체는 별도 endpoint 로
      first_event_kst: events.length > 0 ? events[0].kst_at : null,
      last_event_kst: events.length > 0 ? events[events.length-1].kst_at : null,
      verdict: {
        expected_balance_legit_only: expectedLegitFinal,
        expected_balance_all_types: expectedAllFinal,
        diff_vs_legit: diffVsLegit,
        diff_vs_all: diffVsAll,
        legit_match: Math.abs(diffVsLegit) < 0.01,
        all_match: Math.abs(diffVsAll) < 0.01,
      },
      replay,
      duration_ms: Date.now() - t0,
    })
  } catch (error: any) {
    return c.json({ error: error?.message || String(error), duration_ms: Date.now() - t0 }, 500)
  }
})

// ============================================================================
// negative-balance-report (2026-05-19): 음수 잔액 회원 전수 보고
// ============================================================================
//   목적: 사장님 명령 - 음수 잔액 회원 명단 + 진입금액 + 데일리 배당 + 스왑 현황
//   대상 컬럼: users.qta_balance, qx_balance, qkey_balance, usdt_balance
//              + usdt_withdrawable, qta_initial, qx_initial (있을 시)
//   read-only, 잔액/DB 미수정
//   사용: GET /api/diag/negative-balance-report?key=<ADMIN_PW>
app.get('/api/diag/negative-balance-report', async (c) => {
  const t0 = Date.now()
  try {
    const key = c.req.query('key') || c.req.query('password') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB

    // ── A. users 테이블 컬럼 동적 검출 (스키마 변동 대비) ──
    const colsRes = await db.prepare(`PRAGMA table_info(users)`).all()
    const allCols = (colsRes.results || []).map((r: any) => String(r.name))
    const balanceCols = allCols.filter(c =>
      c.endsWith('_balance') || c.endsWith('_withdrawable') || c.endsWith('_initial')
    )

    if (balanceCols.length === 0) {
      return c.json({ error: 'no balance columns found in users', allCols }, 500)
    }

    // ── B. 음수 잔액 회원 SELECT (any balance column < 0) ──
    const whereClause = balanceCols.map(c => `${c} < 0`).join(' OR ')
    const selectCols = ['id', 'email', 'name', 'created_at', ...balanceCols]
    const rows = await db.prepare(`
      SELECT ${selectCols.join(', ')}
      FROM users
      WHERE ${whereClause}
      ORDER BY id ASC
    `).all()

    const users = (rows.results || []) as any[]
    if (users.length === 0) {
      return c.json({
        ok: true,
        balance_columns_checked: balanceCols,
        negative_user_count: 0,
        verdict: 'PASS: 음수 잔액 회원 0명',
        duration_ms: Date.now() - t0,
      })
    }

    // ── C. 각 회원의 스테이킹 진입금액 + 데일리 배당 + 스왑 현황 집계 ──
    const userIds = users.map(u => Number(u.id))
    const idPh = userIds.map(() => '?').join(',')

    // C-1. 스테이킹 (진입금액) — 모든 상태
    const stakingRows = await db.prepare(`
      SELECT user_id, id AS staking_id, amount, status, start_date, end_date,
             period_months, daily_rate, created_at
      FROM staking
      WHERE user_id IN (${idPh})
      ORDER BY user_id ASC, id ASC
    `).bind(...userIds).all()
    const stakingByUser = new Map<number, any[]>()
    for (const r of (stakingRows.results || []) as any[]) {
      const uid = Number(r.user_id)
      if (!stakingByUser.has(uid)) stakingByUser.set(uid, [])
      stakingByUser.get(uid)!.push(r)
    }

    // C-2. 데일리 배당 (QKEY) — daily_rewards + matching tx daily_qkey
    const dailyRwdRows = await db.prepare(`
      SELECT user_id, COUNT(*) AS cnt, COALESCE(SUM(usdt_amount), 0) AS sum_qkey,
             MIN(paid_date) AS first_paid, MAX(paid_date) AS last_paid
      FROM daily_rewards
      WHERE user_id IN (${idPh})
      GROUP BY user_id
    `).bind(...userIds).all()
    const dailyByUser = new Map<number, any>()
    for (const r of (dailyRwdRows.results || []) as any[]) {
      dailyByUser.set(Number(r.user_id), r)
    }

    // C-3. 추천 보상 (RR) - 받은 것
    const rrRows = await db.prepare(`
      SELECT referrer_id AS user_id, level,
             COUNT(*) AS cnt, COALESCE(SUM(reward_amount), 0) AS sum_qkey
      FROM referral_rewards
      WHERE referrer_id IN (${idPh})
      GROUP BY referrer_id, level
    `).bind(...userIds).all()
    const rrByUser = new Map<number, { l1_cnt: number, l1_sum: number, l2_cnt: number, l2_sum: number }>()
    for (const r of (rrRows.results || []) as any[]) {
      const uid = Number(r.user_id)
      const lv = Number(r.level)
      const entry = rrByUser.get(uid) || { l1_cnt: 0, l1_sum: 0, l2_cnt: 0, l2_sum: 0 }
      if (lv === 1) { entry.l1_cnt = Number(r.cnt); entry.l1_sum = Number(r.sum_qkey) }
      else if (lv === 2) { entry.l2_cnt = Number(r.cnt); entry.l2_sum = Number(r.sum_qkey) }
      rrByUser.set(uid, entry)
    }

    // C-4. 스왑 (transactions WHERE type IN swap_in/swap_out, 모든 coin_type)
    const swapRows = await db.prepare(`
      SELECT user_id, type, coin_type,
             COUNT(*) AS cnt, COALESCE(SUM(amount), 0) AS sum_amount,
             MIN(datetime(created_at,'+9 hours')) AS first_kst,
             MAX(datetime(created_at,'+9 hours')) AS last_kst
      FROM transactions
      WHERE user_id IN (${idPh})
        AND type IN ('swap_in','swap_out')
      GROUP BY user_id, type, coin_type
      ORDER BY user_id ASC, type ASC, coin_type ASC
    `).bind(...userIds).all()
    const swapByUser = new Map<number, any[]>()
    for (const r of (swapRows.results || []) as any[]) {
      const uid = Number(r.user_id)
      if (!swapByUser.has(uid)) swapByUser.set(uid, [])
      swapByUser.get(uid)!.push(r)
    }

    // C-5. 출금 (withdrawal)
    const wRows = await db.prepare(`
      SELECT user_id, coin_type,
             COUNT(*) AS cnt, COALESCE(SUM(amount), 0) AS sum_amount
      FROM transactions
      WHERE user_id IN (${idPh})
        AND type IN ('withdrawal','withdrawal_request','withdrawal_approved')
      GROUP BY user_id, coin_type
    `).bind(...userIds).all()
    const wdrByUser = new Map<number, any[]>()
    for (const r of (wRows.results || []) as any[]) {
      const uid = Number(r.user_id)
      if (!wdrByUser.has(uid)) wdrByUser.set(uid, [])
      wdrByUser.get(uid)!.push(r)
    }

    // ── D. 회원별 통합 보고서 구성 ──
    const report = users.map(u => {
      const uid = Number(u.id)
      const stakings = stakingByUser.get(uid) || []
      const activeStaking = stakings.filter(s => s.status === 'active')
      const totalStakingAmount = stakings.reduce((acc, s) => acc + Number(s.amount || 0), 0)
      const activeStakingAmount = activeStaking.reduce((acc, s) => acc + Number(s.amount || 0), 0)

      const daily = dailyByUser.get(uid)
      const rr = rrByUser.get(uid) || { l1_cnt: 0, l1_sum: 0, l2_cnt: 0, l2_sum: 0 }
      const swaps = swapByUser.get(uid) || []
      const withdrawals = wdrByUser.get(uid) || []

      // 음수인 컬럼 식별
      const negativeCols: Record<string, number> = {}
      for (const col of balanceCols) {
        const v = Number((u as any)[col] || 0)
        if (v < 0) negativeCols[col] = v
      }

      // balance row 전체
      const balances: Record<string, number> = {}
      for (const col of balanceCols) balances[col] = Number((u as any)[col] || 0)

      return {
        user_id: uid,
        email: String(u.email || ''),
        name: String(u.name || ''),
        registered_kst: String(u.created_at || ''),
        negative_balance: negativeCols,
        all_balances: balances,
        staking: {
          total_count: stakings.length,
          active_count: activeStaking.length,
          total_amount_usdt: totalStakingAmount,
          active_amount_usdt: activeStakingAmount,
          stakings: stakings.map(s => ({
            id: Number(s.staking_id),
            amount_usdt: Number(s.amount),
            status: String(s.status),
            daily_rate: Number(s.daily_rate || 0),
            period_months: Number(s.period_months || 0),
            start_date: s.start_date,
            end_date: s.end_date,
          })),
        },
        daily_reward: daily ? {
          count: Number(daily.cnt),
          total_qkey: Number(daily.sum_qkey),
          first_paid_date: daily.first_paid,
          last_paid_date: daily.last_paid,
        } : { count: 0, total_qkey: 0 },
        referral_reward: {
          l1_count: rr.l1_cnt, l1_total_qkey: rr.l1_sum,
          l2_count: rr.l2_cnt, l2_total_qkey: rr.l2_sum,
          total_qkey: rr.l1_sum + rr.l2_sum,
        },
        swap: swaps.map(s => ({
          direction: String(s.type),  // swap_in | swap_out
          coin: String(s.coin_type),
          count: Number(s.cnt),
          sum_amount: Number(s.sum_amount),
          first_kst: s.first_kst,
          last_kst: s.last_kst,
        })),
        withdrawal: withdrawals.map(w => ({
          coin: String(w.coin_type),
          count: Number(w.cnt),
          sum_amount: Number(w.sum_amount),
        })),
      }
    })

    // ── E. 음수 컬럼별 그룹 합계 ──
    const negColSummary: Record<string, { count: number, sum: number }> = {}
    for (const u of users) {
      for (const col of balanceCols) {
        const v = Number((u as any)[col] || 0)
        if (v < 0) {
          if (!negColSummary[col]) negColSummary[col] = { count: 0, sum: 0 }
          negColSummary[col].count++
          negColSummary[col].sum += v
        }
      }
    }

    return c.json({
      ok: true,
      generated_at_kst: kstDateStr(new Date()) + ' ' + new Date(new Date().getTime() + 9*3600*1000).toISOString().slice(11,19),
      balance_columns_checked: balanceCols,
      negative_user_count: users.length,
      negative_column_summary: negColSummary,
      report,
      duration_ms: Date.now() - t0,
    })
  } catch (error: any) {
    return c.json({ error: error?.message || String(error), duration_ms: Date.now() - t0 }, 500)
  }
})

// ============================================================================
// cron-kst08-verify (2026-05-19): KST 08:00 cron 직후 종합 검증 (one-shot)
// ============================================================================
//   영구룰 #정규시각 (2026-05-19) 검증 포함:
//     - 모든 신규 DR/RR/tx 의 created_at == KST 08:00 (= UTC prev-day 23:00:00 / 23:00:01)
//     - cron 단일 실행 (daily_cron_lock 1행)
//     - DR/L1/L2/tx 카운트 매칭
//     - 이중지급 0건
//   사용: GET /api/diag/cron-kst08-verify?key=<ADMIN_PW>
//        (paid_date 미지정 시 오늘 KST 자동)
app.get('/api/diag/cron-kst08-verify', async (c) => {
  const t0 = Date.now()
  try {
    const key = c.req.query('key') || c.req.query('password') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB

    const now = new Date()
    const todayKst = kstDateStr(now)
    const paidDate = c.req.query('paid_date') || todayKst

    // KST 08:00 = UTC (paid_date - 1 day) 23:00:00
    const prevDayKst = kstDateStr(new Date(new Date(paidDate + 'T00:00:00+09:00').getTime() - 24 * 60 * 60 * 1000))
    const expectedDrCreatedAt = `${prevDayKst} 23:00:00`       // KST 08:00:00
    const expectedRrCreatedAt = `${prevDayKst} 23:00:00`       // RR row 자체는 본 row
    const expectedDailyTxCreatedAt = `${prevDayKst} 23:00:00`  // 본인 daily tx
    const expectedRrTxCreatedAt = `${prevDayKst} 23:00:01`     // L1/L2 tx 는 1초 늦게

    // ── A. daily_cron_lock 상태 ──
    const lock = await db.prepare(`
      SELECT lock_date, source, locked_at, locked_by, note, last_finished_at
      FROM daily_cron_lock WHERE lock_date = ?
    `).bind(paidDate).first() as any
    const lockExists = !!lock
    const lockSource = lock?.source || null
    const lockCronAuto = lockSource === 'cron_auto'

    // ── B. DR / RR 카운트 + 합계 ──
    const drAgg = await db.prepare(`
      SELECT COUNT(*) AS cnt, COALESCE(SUM(usdt_amount), 0) AS sum_qkey
      FROM daily_rewards WHERE paid_date = ?
    `).bind(paidDate).first() as any
    const rrAgg = await db.prepare(`
      SELECT COUNT(*) AS cnt,
             SUM(CASE WHEN level=1 THEN 1 ELSE 0 END) AS l1_cnt,
             SUM(CASE WHEN level=2 THEN 1 ELSE 0 END) AS l2_cnt,
             COALESCE(SUM(CASE WHEN level=1 THEN reward_amount ELSE 0 END), 0) AS l1_sum,
             COALESCE(SUM(CASE WHEN level=2 THEN reward_amount ELSE 0 END), 0) AS l2_sum
      FROM referral_rewards WHERE paid_date = ?
    `).bind(paidDate).first() as any

    // ── C. DR 의 created_at 검증 (KST 08:00 = prev-day 23:00:00) ──
    const drTimeAgg = await db.prepare(`
      SELECT
        SUM(CASE WHEN created_at = ? THEN 1 ELSE 0 END) AS exact_match,
        SUM(CASE WHEN created_at != ? THEN 1 ELSE 0 END) AS mismatch,
        COUNT(*) AS total
      FROM daily_rewards WHERE paid_date = ?
    `).bind(expectedDrCreatedAt, expectedDrCreatedAt, paidDate).first() as any
    const drTimeMismatchSample = await db.prepare(`
      SELECT id, user_id, paid_date, created_at,
             datetime(created_at, '+9 hours') AS kst_at
      FROM daily_rewards
      WHERE paid_date = ? AND created_at != ?
      ORDER BY id ASC LIMIT 10
    `).bind(paidDate, expectedDrCreatedAt).all()

    // ── D. RR 의 created_at 검증 ──
    const rrTimeAgg = await db.prepare(`
      SELECT
        SUM(CASE WHEN created_at = ? THEN 1 ELSE 0 END) AS exact_match,
        SUM(CASE WHEN created_at != ? THEN 1 ELSE 0 END) AS mismatch,
        COUNT(*) AS total
      FROM referral_rewards WHERE paid_date = ?
    `).bind(expectedRrCreatedAt, expectedRrCreatedAt, paidDate).first() as any
    const rrTimeMismatchSample = await db.prepare(`
      SELECT id, referrer_id, referee_id, level, paid_date, created_at,
             datetime(created_at, '+9 hours') AS kst_at
      FROM referral_rewards
      WHERE paid_date = ? AND created_at != ?
      ORDER BY id ASC LIMIT 10
    `).bind(paidDate, expectedRrCreatedAt).all()

    // ── E. daily_qkey tx created_at 검증 ──
    const dailyTxTimeAgg = await db.prepare(`
      SELECT
        SUM(CASE WHEN t.created_at = ? THEN 1 ELSE 0 END) AS exact_match,
        SUM(CASE WHEN t.created_at != ? THEN 1 ELSE 0 END) AS mismatch,
        COUNT(*) AS total
      FROM transactions t
      INNER JOIN daily_rewards dr ON dr.id = t.ref_id
      WHERE t.type = 'daily_qkey' AND dr.paid_date = ?
    `).bind(expectedDailyTxCreatedAt, expectedDailyTxCreatedAt, paidDate).first() as any
    const dailyTxMismatchSample = await db.prepare(`
      SELECT t.id, t.user_id, t.amount, t.created_at,
             datetime(t.created_at, '+9 hours') AS kst_at,
             dr.paid_date
      FROM transactions t
      INNER JOIN daily_rewards dr ON dr.id = t.ref_id
      WHERE t.type = 'daily_qkey' AND dr.paid_date = ? AND t.created_at != ?
      ORDER BY t.id ASC LIMIT 10
    `).bind(paidDate, expectedDailyTxCreatedAt).all()

    // ── F. referral_reward tx created_at 검증 (1초 늦은 23:00:01) ──
    const rrTxTimeAgg = await db.prepare(`
      SELECT
        SUM(CASE WHEN t.created_at = ? THEN 1 ELSE 0 END) AS exact_match,
        SUM(CASE WHEN t.created_at != ? THEN 1 ELSE 0 END) AS mismatch,
        COUNT(*) AS total
      FROM transactions t
      INNER JOIN referral_rewards rr ON rr.id = t.ref_id
      WHERE t.type = 'referral_reward' AND rr.paid_date = ?
    `).bind(expectedRrTxCreatedAt, expectedRrTxCreatedAt, paidDate).first() as any
    const rrTxMismatchSample = await db.prepare(`
      SELECT t.id, t.user_id, t.amount, t.created_at,
             datetime(t.created_at, '+9 hours') AS kst_at,
             rr.level, rr.paid_date
      FROM transactions t
      INNER JOIN referral_rewards rr ON rr.id = t.ref_id
      WHERE t.type = 'referral_reward' AND rr.paid_date = ? AND t.created_at != ?
      ORDER BY t.id ASC LIMIT 10
    `).bind(paidDate, expectedRrTxCreatedAt).all()

    // ── G. tx <-> ledger 카운트 매칭 ──
    const drCnt = Number(drAgg?.cnt || 0)
    const rrCnt = Number(rrAgg?.cnt || 0)
    const dailyTxCnt = Number(dailyTxTimeAgg?.total || 0)
    const rrTxCnt = Number(rrTxTimeAgg?.total || 0)
    const drVsDailyTxMatch = drCnt === dailyTxCnt
    const rrVsRrTxMatch = rrCnt === rrTxCnt

    // ── H. 이중지급 검사 (5-tuple) ──
    const drDup = await db.prepare(`
      SELECT user_id, staking_id, reward_date, COUNT(*) AS cnt
      FROM daily_rewards WHERE paid_date = ?
      GROUP BY user_id, staking_id, reward_date
      HAVING COUNT(*) > 1
      LIMIT 10
    `).bind(paidDate).all()
    const rrDup = await db.prepare(`
      SELECT referrer_id, referee_id, level, staking_id, reward_date, COUNT(*) AS cnt
      FROM referral_rewards WHERE paid_date = ?
      GROUP BY referrer_id, referee_id, level, staking_id, reward_date
      HAVING COUNT(*) > 1
      LIMIT 10
    `).bind(paidDate).all()
    const drDupCount = (drDup.results || []).length
    const rrDupCount = (rrDup.results || []).length

    // ── I. 종합 판정 ──
    const drTimeOk = Number(drTimeAgg?.mismatch || 0) === 0 && Number(drTimeAgg?.total || 0) > 0
    const rrTimeOk = Number(rrTimeAgg?.mismatch || 0) === 0
    const dailyTxTimeOk = Number(dailyTxTimeAgg?.mismatch || 0) === 0 && Number(dailyTxTimeAgg?.total || 0) > 0
    const rrTxTimeOk = Number(rrTxTimeAgg?.mismatch || 0) === 0
    const noDup = drDupCount === 0 && rrDupCount === 0
    const lockOk = lockExists && lockCronAuto

    const allPassed = drTimeOk && rrTimeOk && dailyTxTimeOk && rrTxTimeOk && noDup && drVsDailyTxMatch && rrVsRrTxMatch && lockOk

    return c.json({
      ok: true,
      paid_date: paidDate,
      reward_date_expected: prevDayKst,
      expected_created_at: {
        dr: expectedDrCreatedAt,
        rr: expectedRrCreatedAt,
        daily_tx: expectedDailyTxCreatedAt,
        rr_tx: expectedRrTxCreatedAt,
        note: 'KST 08:00 (PERMANENT_RULE #regular-time 2026-05-19)',
      },
      A_lock: {
        exists: lockExists,
        source: lockSource,
        is_cron_auto: lockCronAuto,
        details: lock,
        verdict: lockOk ? 'PASS (cron_auto lock 존재)' : 'FAIL',
      },
      B_counts: {
        dr: drCnt,
        dr_sum_qkey: Number(drAgg?.sum_qkey || 0),
        rr_total: rrCnt,
        rr_l1: Number(rrAgg?.l1_cnt || 0),
        rr_l2: Number(rrAgg?.l2_cnt || 0),
        rr_l1_sum_qkey: Number(rrAgg?.l1_sum || 0),
        rr_l2_sum_qkey: Number(rrAgg?.l2_sum || 0),
        daily_tx: dailyTxCnt,
        rr_tx: rrTxCnt,
      },
      C_dr_time: {
        total: Number(drTimeAgg?.total || 0),
        exact_match: Number(drTimeAgg?.exact_match || 0),
        mismatch: Number(drTimeAgg?.mismatch || 0),
        mismatch_sample: drTimeMismatchSample.results || [],
        verdict: drTimeOk ? 'PASS' : 'FAIL',
      },
      D_rr_time: {
        total: Number(rrTimeAgg?.total || 0),
        exact_match: Number(rrTimeAgg?.exact_match || 0),
        mismatch: Number(rrTimeAgg?.mismatch || 0),
        mismatch_sample: rrTimeMismatchSample.results || [],
        verdict: rrTimeOk ? 'PASS' : 'FAIL',
      },
      E_daily_tx_time: {
        total: Number(dailyTxTimeAgg?.total || 0),
        exact_match: Number(dailyTxTimeAgg?.exact_match || 0),
        mismatch: Number(dailyTxTimeAgg?.mismatch || 0),
        mismatch_sample: dailyTxMismatchSample.results || [],
        verdict: dailyTxTimeOk ? 'PASS' : 'FAIL',
      },
      F_rr_tx_time: {
        total: Number(rrTxTimeAgg?.total || 0),
        exact_match: Number(rrTxTimeAgg?.exact_match || 0),
        mismatch: Number(rrTxTimeAgg?.mismatch || 0),
        mismatch_sample: rrTxMismatchSample.results || [],
        verdict: rrTxTimeOk ? 'PASS' : 'FAIL',
      },
      G_tx_ledger_match: {
        dr_vs_daily_tx: drVsDailyTxMatch ? 'PASS' : `FAIL (dr=${drCnt}, daily_tx=${dailyTxCnt})`,
        rr_vs_rr_tx: rrVsRrTxMatch ? 'PASS' : `FAIL (rr=${rrCnt}, rr_tx=${rrTxCnt})`,
      },
      H_dup_check: {
        dr_dup_count: drDupCount,
        dr_dup_sample: drDup.results || [],
        rr_dup_count: rrDupCount,
        rr_dup_sample: rrDup.results || [],
        verdict: noDup ? 'PASS' : 'FAIL',
      },
      verdict: allPassed
        ? 'ALL_PASSED: KST 08:00 cron 영구룰 완전 준수'
        : 'FAILED: 위 verdict FAIL 항목 확인 필요',
      all_passed: allPassed,
      duration_ms: Date.now() - t0,
    })
  } catch (error: any) {
    return c.json({ error: error?.message || String(error), duration_ms: Date.now() - t0 }, 500)
  }
})

// ============================================================================
// Cron Coverage Audit (2026-05-14) — 데일리/매칭 누락 0건 검증 정밀 점검
// ============================================================================
//   사장님 명령 (2026-05-13): "어떤 휴일진입자도 오늘 무조건 평일이라 데일리 배당을
//                              받아야하고 위 아래 회원이 있을때는 무조건 그에 따른
//                              배당도 집행이 되야하는거야 명심해!"
//
//   목적: cron-h-plan-monitor (C1~C8) 가 PASS 해도 알 수 없는
//         "활성 회원 vs 수령 회원" 누락 사례 정밀 검증
//
//   3단계 검증:
//     STEP 1. yesterdayKst 시점 활성 staking 보유 user 전수 조회
//             (start_kst <= yesterday <= end_kst AND status IN ('active','capped'))
//     STEP 2. 각 user 별 paid_date daily_rewards 수령 여부 + 미수령 사유 분류
//             A. 받음 (정상)
//             B. 200% cap 도달 (영구 룰 허용)
//             C. 거치기간 초과 (영구 룰 허용)
//             D. 알 수 없음 (영구 룰 위반!!)
//     STEP 3. 데일리 받은 user 의 L1/L2 referrer 매칭 누락 검증
//             - referrer 활성 + cap 미도달 → 매칭 받음 의무
//             - 누락 발견 시 → 영구 룰 위반 즉시 보고
//
//   사용: GET /api/diag/cron-coverage-audit?password=...&paid_date=2026-05-14
app.get('/api/diag/cron-coverage-audit', async (c) => {
  try {
    const password = c.req.query('password') || ''
    if (password !== ADMIN_PW) return c.json({ error: 'Unauthorized' }, 401)
    const db = c.env.DB

    const now = new Date()
    const todayKst = kstDateStr(now)
    const paidDate = c.req.query('paid_date') || todayKst
    const yesterdayKst = kstDateStr(new Date(new Date(paidDate + 'T00:00:00+09:00').getTime() - 24 * 60 * 60 * 1000))

    const USD_TO_QKEY = 150

    // ─────────────────────────────────────────────────────────────────────
    // STEP 1. yesterdayKst 시점 활성 staking 보유 user 전수 조회
    //   - cron 의 activeStakings 쿼리와 동일 조건 사용 (line 4560-4580 기준)
    //   - status IN ('active','capped') — capped 도 일단 포함 (사유 분류 위해)
    // ─────────────────────────────────────────────────────────────────────
    const activeStakingsAll = await db.prepare(`
      SELECT
        s.id as staking_id,
        s.user_id,
        s.amount,
        s.period_days,
        s.period_months,
        s.daily_rate,
        s.status,
        date(s.start_date, '+9 hours') as start_kst_date,
        date(s.end_date, '+9 hours') as end_kst_date,
        (SELECT COUNT(*) FROM daily_rewards WHERE staking_id = s.id) as rewarded_count,
        (SELECT MAX(reward_date) FROM daily_rewards WHERE staking_id = s.id) as last_reward_date
      FROM staking s
      WHERE s.status IN ('active','capped')
        AND date(s.end_date, '+9 hours') >= ?
        AND date(s.start_date, '+9 hours') <= ?
      ORDER BY s.user_id ASC, s.id ASC
    `).bind(yesterdayKst, yesterdayKst).all()

    const totalStakings = activeStakingsAll.results.length
    const uniqueUserIds = new Set<number>()
    activeStakingsAll.results.forEach((s: any) => uniqueUserIds.add(s.user_id))
    const totalActiveUsers = uniqueUserIds.size

    // ─────────────────────────────────────────────────────────────────────
    // STEP 2. paid_date daily_rewards 수령 여부 (user 단위, staking 단위 둘 다)
    // ─────────────────────────────────────────────────────────────────────
    const paidUsersRows = await db.prepare(`
      SELECT DISTINCT user_id FROM daily_rewards WHERE paid_date = ?
    `).bind(paidDate).all()
    const paidUserSet = new Set<number>()
    paidUsersRows.results.forEach((r: any) => paidUserSet.add(r.user_id))

    const paidStakingsRows = await db.prepare(`
      SELECT DISTINCT staking_id FROM daily_rewards WHERE paid_date = ?
    `).bind(paidDate).all()
    const paidStakingSet = new Set<number>()
    paidStakingsRows.results.forEach((r: any) => paidStakingSet.add(r.staking_id))

    // user 별 200% cap 여부 (현재 시점)
    async function getUserCapState(userId: number): Promise<{ capped: boolean, paidTotal: number, target: number, percent: number }> {
      const stakeRow = await db.prepare(`
        SELECT COALESCE(SUM(amount), 0) as total
        FROM staking WHERE user_id = ? AND status IN ('active','completed','capped')
      `).bind(userId).first() as any
      const stakeTotal = Number(stakeRow?.total || 0)
      if (stakeTotal <= 0) return { capped: false, paidTotal: 0, target: 0, percent: 0 }
      const paidRow = await db.prepare(`
        SELECT COALESCE(SUM(amount), 0) as total
        FROM transactions
        WHERE user_id = ? AND coin_type = 'QKEY'
          AND type IN ('daily_qkey', 'referral_reward')
      `).bind(userId).first() as any
      const paidTotal = Number(paidRow?.total || 0)
      const target = stakeTotal * 2 * USD_TO_QKEY
      const percent = target > 0 ? (paidTotal / target * 100) : 0
      return { capped: paidTotal >= target, paidTotal, target, percent }
    }

    // staking 단위 누락 분류
    const stakingClassification: any[] = []
    let cat_A_received = 0
    let cat_B_cap_reached = 0
    let cat_C_period_done = 0
    let cat_D_unknown = 0
    const violations_D: any[] = []  // 영구 룰 위반 후보

    for (const s of activeStakingsAll.results) {
      const stakingId = s.staking_id as number
      const userId = s.user_id as number
      const periodDays = (s.period_days as number) || ((s.period_months as number) * 30)
      const rewardedCount = Number(s.rewarded_count || 0)
      const startKst = s.start_kst_date as string

      // 받은 staking 인지
      const wasPaid = paidStakingSet.has(stakingId)

      if (wasPaid) {
        cat_A_received++
        continue
      }

      // 미수령 — 사유 분류
      // 사유 B: user 가 cap 도달 (현재 시점)
      const capState = await getUserCapState(userId)
      const isCapped = capState.capped || (s.status === 'capped')

      // 사유 C: 거치기간 초과 — 이미 rewarded_count >= period_days
      const periodDone = rewardedCount >= periodDays

      if (isCapped) {
        cat_B_cap_reached++
        stakingClassification.push({
          staking_id: stakingId, user_id: userId, reason: 'B_cap_reached',
          rewarded_count: rewardedCount, period_days: periodDays,
          paid_percent: capState.percent.toFixed(2) + '%',
          paid_total: capState.paidTotal, cap_target: capState.target,
        })
      } else if (periodDone) {
        cat_C_period_done++
        stakingClassification.push({
          staking_id: stakingId, user_id: userId, reason: 'C_period_done',
          rewarded_count: rewardedCount, period_days: periodDays,
        })
      } else {
        // 사유 D: 알 수 없음 — 영구 룰 위반 가능성!
        cat_D_unknown++
        violations_D.push({
          staking_id: stakingId, user_id: userId,
          reason: 'D_UNKNOWN_PERMANENT_RULE_VIOLATION',
          status: s.status, start_kst_date: startKst, end_kst_date: s.end_kst_date,
          rewarded_count: rewardedCount, period_days: periodDays,
          last_reward_date: s.last_reward_date,
          amount: s.amount, daily_rate: s.daily_rate,
          cap_paid_total: capState.paidTotal, cap_target: capState.target,
          cap_percent: capState.percent.toFixed(2) + '%',
          note: '활성 staking 인데 paid_date 데일리 미수령 + cap 미도달 + 거치기간 미초과 = 영구 룰 위반',
        })
      }
    }

    const step2_total_stakings = totalStakings
    const step2_passed = cat_D_unknown === 0  // 알 수 없는 누락 0건이어야 PASS

    // ─────────────────────────────────────────────────────────────────────
    // STEP 3. L1/L2 매칭 누락 검증
    //   - paid_date 에 daily_rewards 받은 (referee, staking_id) 마다
    //     referee 의 L1 referrer + L2 referrer 가 yesterdayKst 시점 활성 + cap 미도달이면
    //     매칭 referral_rewards 가 있어야 함
    // ─────────────────────────────────────────────────────────────────────
    const paidStakingsList = await db.prepare(`
      SELECT dr.user_id as referee_id, dr.staking_id, dr.reward_date, dr.usdt_amount
      FROM daily_rewards dr
      WHERE dr.paid_date = ?
      ORDER BY dr.id ASC
    `).bind(paidDate).all()

    let matchingExpected = 0
    let matchingMissing = 0
    const matchingMissingDetails: any[] = []

    for (const dr of paidStakingsList.results) {
      const refereeId = dr.referee_id as number
      const stakingId = dr.staking_id as number
      const rewardDate = dr.reward_date as string
      const originalAmount = Number(dr.usdt_amount || 0)

      // L1 referrer
      const l1Row = await db.prepare(`SELECT referrer_id FROM users WHERE id = ?`).bind(refereeId).first() as any
      const l1Id = l1Row?.referrer_id as number | null

      if (l1Id) {
        // L1 yesterdayKst 시점 활성 staking 보유?
        const l1Active = await db.prepare(`
          SELECT id FROM staking
          WHERE user_id = ? AND status IN ('active','capped')
            AND date(start_date, '+9 hours') <= ?
            AND date(end_date, '+9 hours') >= ?
          LIMIT 1
        `).bind(l1Id, rewardDate, rewardDate).first()

        if (l1Active) {
          // L1 cap 미도달?
          const l1Cap = await getUserCapState(l1Id)
          if (!l1Cap.capped) {
            matchingExpected++
            // 매칭 row 존재?
            const l1Row = await db.prepare(`
              SELECT id, reward_amount FROM referral_rewards
              WHERE referrer_id = ? AND referee_id = ? AND level = 1
                AND staking_id = ? AND reward_date = ?
              LIMIT 1
            `).bind(l1Id, refereeId, stakingId, rewardDate).first() as any

            if (!l1Row) {
              matchingMissing++
              matchingMissingDetails.push({
                level: 1, referrer_id: l1Id, referee_id: refereeId,
                staking_id: stakingId, reward_date: rewardDate,
                expected_amount: Math.round(originalAmount * 0.20),
                referrer_cap_percent: l1Cap.percent.toFixed(2) + '%',
                note: 'L1 활성 + cap 미도달 + 매칭 row 없음 = 영구 룰 위반',
              })
            }
          }
        }

        // L2 referrer
        const l2Row = await db.prepare(`SELECT referrer_id FROM users WHERE id = ?`).bind(l1Id).first() as any
        const l2Id = l2Row?.referrer_id as number | null

        if (l2Id) {
          const l2Active = await db.prepare(`
            SELECT id FROM staking
            WHERE user_id = ? AND status IN ('active','capped')
              AND date(start_date, '+9 hours') <= ?
              AND date(end_date, '+9 hours') >= ?
            LIMIT 1
          `).bind(l2Id, rewardDate, rewardDate).first()

          if (l2Active) {
            const l2Cap = await getUserCapState(l2Id)
            if (!l2Cap.capped) {
              matchingExpected++
              const l2Match = await db.prepare(`
                SELECT id, reward_amount FROM referral_rewards
                WHERE referrer_id = ? AND referee_id = ? AND level = 2
                  AND staking_id = ? AND reward_date = ?
                LIMIT 1
              `).bind(l2Id, refereeId, stakingId, rewardDate).first() as any

              if (!l2Match) {
                matchingMissing++
                matchingMissingDetails.push({
                  level: 2, referrer_id: l2Id, referee_id: refereeId,
                  staking_id: stakingId, reward_date: rewardDate,
                  expected_amount: Math.round(originalAmount * 0.10),
                  referrer_cap_percent: l2Cap.percent.toFixed(2) + '%',
                  note: 'L2 활성 + cap 미도달 + 매칭 row 없음 = 영구 룰 위반',
                })
              }
            }
          }
        }
      }
    }

    const step3_passed = matchingMissing === 0
    const all_passed = step2_passed && step3_passed

    return c.json({
      success: true,
      title: 'Cron Coverage Audit — 데일리/매칭 누락 0건 정밀 검증',
      paid_date: paidDate,
      yesterday_kst_reference: yesterdayKst,
      checked_at_kst: kstDateStr(now) + ' ' + now.toISOString().split('T')[1].split('.')[0] + ' UTC',
      all_passed,
      verdict: all_passed
        ? '✅ 누락 0건 — 사장님 영구 룰 100% 준수 (휴일진입자/매칭 모두 정상)'
        : '⚠️ 누락 발견 — 즉시 보정 endpoint 작성 필요',
      // ─────────── STEP 1 ───────────
      step1_active_stakings: {
        total_stakings: totalStakings,
        total_active_users: totalActiveUsers,
        criterion: `start_kst <= ${yesterdayKst} AND end_kst >= ${yesterdayKst} AND status IN ('active','capped')`,
      },
      // ─────────── STEP 2 ───────────
      step2_daily_coverage: {
        passed: step2_passed,
        total_stakings: step2_total_stakings,
        category_A_received: cat_A_received,
        category_B_cap_reached: cat_B_cap_reached,
        category_C_period_done: cat_C_period_done,
        category_D_unknown_violation: cat_D_unknown,
        paid_users_distinct: paidUserSet.size,
        violations_D: violations_D.slice(0, 50),
      },
      // ─────────── STEP 3 ───────────
      step3_matching_coverage: {
        passed: step3_passed,
        matching_expected: matchingExpected,
        matching_missing: matchingMissing,
        missing_details: matchingMissingDetails.slice(0, 50),
      },
      permanent_rule_quote: '사장님 명령: "어떤 휴일진입자도 오늘 무조건 평일이라 데일리 배당을 받아야하고 위 아래 회원이 있을때는 무조건 그에 따른 배당도 집행이 되야하는거야"',
    })
  } catch (error: any) {
    console.error('cron-coverage-audit error:', error)
    return c.json({ error: error?.message || String(error), code: error?.code }, 500)
  }
})

// ============================================================================
// 5/14 35건 누락 보정 endpoint (2026-05-14, 사장님 명시 지시)
// ============================================================================
//   배경: 5/14 07:12 manual-daily-trigger 가 Cloudflare 100초 timeout 으로 첫 batch
//        (21건) 만 처리하고 35건 누락 발생. 영구 룰 #휴일진입자 보호 + #매칭 의무 위반.
//
//   사장님 명령 (2026-05-14): "일단 35건 빨리 보정후에 영구방안 대처하자!"
//
//   보정 전략 (cron 로직 100% 복제, 영구 룰 100% 준수):
//     1. 5/13 시점 활성 staking 중 5/14 paid_date 데일리 미수령 staking 동적 재조회
//        (cron-coverage-audit STEP 2 D 카테고리와 동일 로직)
//     2. 각 staking 에 cron 의 정확한 INSERT 로직 적용 (line 4632-4884 복제):
//        - getStakingAccrualDatesKst → reward_date 계산 (휴일진입자 보호 자동)
//        - 4중 가드 (exists 체크 → INSERT → ref_id EXISTS → transactions INSERT)
//        - L1/L2 매칭 (staking_id 명시, 5-tuple 가드)
//        - 200% cap (B안 사용자 총합)
//     3. paid_date=2026-05-14 (오늘) 명시
//     4. description 사용자 노출 안전 ('일일 배당 (QKEY)', '추천 보너스 (Level 1/2)')
//
//   사용법:
//     - DRY_RUN: GET /api/diag/cron-may14-coverage-fix?password=...
//     - EXEC:    GET /api/diag/cron-may14-coverage-fix?password=...&confirm=GO
app.get('/api/diag/cron-may14-coverage-fix', async (c) => {
  try {
    const password = c.req.query('password') || ''
    if (password !== ADMIN_PW) return c.json({ error: 'Unauthorized' }, 401)
    const confirm = c.req.query('confirm') || ''
    const isExec = confirm === 'GO'
    const db = c.env.DB

    const now = new Date()
    const today = kstDateStr(now)  // 2026-05-14
    const yesterdayKst = kstDateStr(new Date(now.getTime() - 24 * 60 * 60 * 1000))  // 2026-05-13

    if (today !== '2026-05-14') {
      return c.json({
        error: 'WRONG_DATE',
        today,
        expected: '2026-05-14',
        note: '본 보정 endpoint 는 2026-05-14 KST 에만 실행 가능 (5/14 manual-daily-trigger timeout 누락 보정 전용)',
      }, 400)
    }

    const USD_TO_QKEY = 150

    // ─────────────────────────────────────────────────────────────────────
    // STEP 1. 5/13 시점 활성 staking 중 5/14 paid_date 미수령 staking 재조회
    //   (cron-coverage-audit STEP 2 D 카테고리 = active + cap 미도달 + 거치기간 미초과)
    // ─────────────────────────────────────────────────────────────────────
    const candidateStakings = await db.prepare(`
      SELECT
        s.id as staking_id,
        s.user_id,
        s.amount,
        s.period_days,
        s.period_months,
        s.daily_rate,
        s.start_date,
        s.end_date,
        s.status,
        date(s.start_date, '+9 hours') as start_kst_date,
        date(s.end_date, '+9 hours') as end_kst_date,
        (SELECT COUNT(*) FROM daily_rewards WHERE staking_id = s.id) as rewarded_count,
        (SELECT MAX(reward_date) FROM daily_rewards WHERE staking_id = s.id) as last_reward_date
      FROM staking s
      WHERE s.status IN ('active','capped')
        AND date(s.end_date, '+9 hours') >= ?
        AND date(s.start_date, '+9 hours') <= ?
        AND NOT EXISTS (
          SELECT 1 FROM daily_rewards dr WHERE dr.staking_id = s.id AND dr.paid_date = ?
        )
      ORDER BY s.user_id ASC, s.id ASC
    `).bind(yesterdayKst, yesterdayKst, today).all()

    // 200% cap state helper (cron 로직 그대로)
    async function isUserCapped(userId: number): Promise<{ capped: boolean, paidTotal: number, target: number, percent: number }> {
      const stakeRow = await db.prepare(`
        SELECT COALESCE(SUM(amount), 0) as total
        FROM staking WHERE user_id = ? AND status IN ('active','completed','capped')
      `).bind(userId).first() as any
      const stakeTotal = Number(stakeRow?.total || 0)
      if (stakeTotal <= 0) return { capped: false, paidTotal: 0, target: 0, percent: 0 }
      const paidRow = await db.prepare(`
        SELECT COALESCE(SUM(amount), 0) as total
        FROM transactions
        WHERE user_id = ? AND coin_type = 'QKEY'
          AND type IN ('daily_qkey', 'referral_reward')
      `).bind(userId).first() as any
      const paidTotal = Number(paidRow?.total || 0)
      const target = stakeTotal * 2 * USD_TO_QKEY
      const percent = target > 0 ? (paidTotal / target * 100) : 0
      return { capped: paidTotal >= target, paidTotal, target, percent }
    }

    const totalCandidates = candidateStakings.results.length

    let totalDailyInsert = 0
    let totalDailyQkey = 0
    let totalL1Insert = 0
    let totalL1Qkey = 0
    let totalL2Insert = 0
    let totalL2Qkey = 0
    let cappedSkipCount = 0
    const cappedUsers: number[] = []
    const perStakingLog: any[] = []

    // ─────────────────────────────────────────────────────────────────────
    // STEP 2. 각 staking 별 cron 로직 적용 (DRY_RUN 또는 EXEC)
    // ─────────────────────────────────────────────────────────────────────
    for (const staking of candidateStakings.results) {
      const stakingId = staking.staking_id as number
      const userId = staking.user_id as number
      const periodDays = Number(staking.period_days || ((staking.period_months as number) * 30))
      const stakingLog: any = {
        staking_id: stakingId, user_id: userId,
        start_kst_date: staking.start_kst_date,
        amount: staking.amount, daily_rate: staking.daily_rate,
        rewarded_count_before: staking.rewarded_count,
        period_days: periodDays,
        accrual_dates: [],
        daily_inserted: 0, daily_qkey: 0,
        l1_inserted: 0, l1_qkey: 0,
        l2_inserted: 0, l2_qkey: 0,
        skip_reason: null,
      }

      // 200% cap 사전 체크
      const capState = await isUserCapped(userId)
      if (capState.capped) {
        cappedSkipCount++
        if (!cappedUsers.includes(userId)) cappedUsers.push(userId)
        stakingLog.skip_reason = 'user_capped'
        stakingLog.cap_percent = capState.percent.toFixed(2) + '%'
        perStakingLog.push(stakingLog)
        continue
      }

      // accrualDates 계산 (cron 로직 동일)
      const accrualDates = getStakingAccrualDatesKst(
        (staking.last_reward_date as string) || null,
        staking.start_kst_date as string,
        yesterdayKst,
        today
      )

      if (accrualDates.length === 0) {
        stakingLog.skip_reason = 'no_accrual_dates'
        perStakingLog.push(stakingLog)
        continue
      }

      stakingLog.accrual_dates = accrualDates
      let stakingProcessed = 0

      for (const accrualDate of accrualDates) {
        // 거치기간 초과 체크
        const currentRewardedCount = (staking.rewarded_count as number) + stakingProcessed
        if (currentRewardedCount >= periodDays) {
          stakingLog.skip_reason = 'period_exceeded'
          break
        }

        // 중복 방지 (4중 가드 1)
        const exists = await db.prepare(`
          SELECT COUNT(*) as count FROM daily_rewards
          WHERE user_id = ? AND staking_id = ? AND reward_date = ?
        `).bind(userId, stakingId, accrualDate).first() as any
        if (exists.count > 0) continue

        // 금액 계산
        const dailyRate = (staking.daily_rate as number) || getDailyRate(staking.amount as number)
        const usdAmount = (staking.amount as number) * dailyRate
        let qkeyAmount = Math.round(usdAmount * USD_TO_QKEY)

        // 200% cap loop 체크
        const capCheck = await isUserCapped(userId)
        if (capCheck.capped) {
          cappedSkipCount++
          if (!cappedUsers.includes(userId)) cappedUsers.push(userId)
          stakingLog.skip_reason = 'capped_in_loop'
          break
        }
        const remaining = capCheck.target - capCheck.paidTotal
        if (qkeyAmount > remaining) {
          qkeyAmount = Math.max(0, Math.floor(remaining))
          if (qkeyAmount <= 0) {
            cappedSkipCount++
            if (!cappedUsers.includes(userId)) cappedUsers.push(userId)
            stakingLog.skip_reason = 'cap_remaining_zero'
            break
          }
        }

        if (isExec) {
          // [본인 배당 INSERT] daily_rewards
          const drIns = await db.prepare(`
            INSERT INTO daily_rewards (user_id, staking_id, usdt_amount, reward_date, paid_date)
            VALUES (?, ?, ?, ?, ?)
          `).bind(userId, stakingId, qkeyAmount, accrualDate, today).run()
          const drId = (drIns as any)?.meta?.last_row_id ?? null

          await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(qkeyAmount, userId).run()

          // 4중 가드 - ref_id EXISTS (4번째)
          const dqExists = await db.prepare(`
            SELECT id FROM transactions WHERE type = 'daily_qkey' AND ref_id = ? LIMIT 1
          `).bind(drId).first()
          if (!dqExists) {
            await db.prepare(`
              INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
              VALUES (?, 'daily_qkey', 'QKEY', ?, ?, ?)
            `).bind(userId, qkeyAmount, '일일 배당 (QKEY)', drId).run()
          }
        }

        stakingLog.daily_inserted += 1
        stakingLog.daily_qkey += qkeyAmount
        totalDailyInsert += 1
        totalDailyQkey += qkeyAmount
        stakingProcessed += 1

        // ─── 매칭 (L1 20%, L2 10%) ───
        const l1Row = await db.prepare(`SELECT referrer_id FROM users WHERE id = ?`).bind(userId).first() as any
        const l1Id = l1Row?.referrer_id as number | null

        if (l1Id) {
          const l1Active = await db.prepare(`
            SELECT id FROM staking
            WHERE user_id = ? AND status = 'active'
              AND date(start_date, '+9 hours') <= date(?)
              AND date(end_date, '+9 hours') >= date(?)
            LIMIT 1
          `).bind(l1Id, accrualDate, accrualDate).first()

          if (l1Active) {
            // H plan 5-tuple 가드 (staking_id 인식)
            const l1Exists = await db.prepare(`
              SELECT COUNT(*) as count FROM referral_rewards
              WHERE referrer_id = ? AND referee_id = ? AND level = 1 AND reward_date = ?
                AND (staking_id = ? OR (staking_id IS NULL AND original_amount = ?))
            `).bind(l1Id, userId, accrualDate, stakingId, qkeyAmount).first() as any

            if (l1Exists.count === 0) {
              let level1Reward = Math.round(qkeyAmount * 0.20)  // ★ L1 = 20% ★
              const l1Cap = await isUserCapped(l1Id)
              if (!l1Cap.capped) {
                const l1Remaining = l1Cap.target - l1Cap.paidTotal
                if (level1Reward > l1Remaining) level1Reward = Math.max(0, Math.floor(l1Remaining))
                if (level1Reward > 0) {
                  if (isExec) {
                    await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(level1Reward, l1Id).run()
                    const rrL1Ins = await db.prepare(`
                      INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, staking_id)
                      VALUES (?, ?, 1, ?, ?, ?, ?, ?)
                    `).bind(l1Id, userId, qkeyAmount, level1Reward, accrualDate, today, stakingId).run()
                    const rrL1Id = (rrL1Ins as any)?.meta?.last_row_id ?? null
                    const l1TxExists = await db.prepare(`
                      SELECT id FROM transactions WHERE type = 'referral_reward' AND ref_id = ? LIMIT 1
                    `).bind(rrL1Id).first()
                    if (!l1TxExists) {
                      await db.prepare(`
                        INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
                        VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?)
                      `).bind(l1Id, level1Reward, '추천 보너스 (Level 1)', rrL1Id).run()
                    }
                  }
                  stakingLog.l1_inserted += 1
                  stakingLog.l1_qkey += level1Reward
                  totalL1Insert += 1
                  totalL1Qkey += level1Reward
                }
              }
            }

            // L2
            const l2Row = await db.prepare(`SELECT referrer_id FROM users WHERE id = ?`).bind(l1Id).first() as any
            const l2Id = l2Row?.referrer_id as number | null

            if (l2Id) {
              const l2Active = await db.prepare(`
                SELECT id FROM staking
                WHERE user_id = ? AND status = 'active'
                  AND date(start_date, '+9 hours') <= date(?)
                  AND date(end_date, '+9 hours') >= date(?)
                LIMIT 1
              `).bind(l2Id, accrualDate, accrualDate).first()

              if (l2Active) {
                const l2Exists = await db.prepare(`
                  SELECT COUNT(*) as count FROM referral_rewards
                  WHERE referrer_id = ? AND referee_id = ? AND level = 2 AND reward_date = ?
                    AND (staking_id = ? OR (staking_id IS NULL AND original_amount = ?))
                `).bind(l2Id, userId, accrualDate, stakingId, qkeyAmount).first() as any

                if (l2Exists.count === 0) {
                  let level2Reward = Math.round(qkeyAmount * 0.10)  // ★ L2 = 10% ★
                  const l2Cap = await isUserCapped(l2Id)
                  if (!l2Cap.capped) {
                    const l2Remaining = l2Cap.target - l2Cap.paidTotal
                    if (level2Reward > l2Remaining) level2Reward = Math.max(0, Math.floor(l2Remaining))
                    if (level2Reward > 0) {
                      if (isExec) {
                        await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(level2Reward, l2Id).run()
                        const rrL2Ins = await db.prepare(`
                          INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, staking_id)
                          VALUES (?, ?, 2, ?, ?, ?, ?, ?)
                        `).bind(l2Id, userId, qkeyAmount, level2Reward, accrualDate, today, stakingId).run()
                        const rrL2Id = (rrL2Ins as any)?.meta?.last_row_id ?? null
                        const l2TxExists = await db.prepare(`
                          SELECT id FROM transactions WHERE type = 'referral_reward' AND ref_id = ? LIMIT 1
                        `).bind(rrL2Id).first()
                        if (!l2TxExists) {
                          await db.prepare(`
                            INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
                            VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?)
                          `).bind(l2Id, level2Reward, '추천 보너스 (Level 2)', rrL2Id).run()
                        }
                      }
                      stakingLog.l2_inserted += 1
                      stakingLog.l2_qkey += level2Reward
                      totalL2Insert += 1
                      totalL2Qkey += level2Reward
                    }
                  }
                }
              }
            }
          }
        }
      }
      perStakingLog.push(stakingLog)
    }

    return c.json({
      success: true,
      mode: isExec ? 'EXEC' : 'DRY_RUN',
      title: '5/14 35건 누락 보정 (manual-daily-trigger timeout 후속)',
      today_kst: today,
      yesterday_kst: yesterdayKst,
      candidates_count: totalCandidates,
      summary: {
        daily_inserted: totalDailyInsert,
        daily_qkey_total: totalDailyQkey,
        l1_inserted: totalL1Insert,
        l1_qkey_total: totalL1Qkey,
        l2_inserted: totalL2Insert,
        l2_qkey_total: totalL2Qkey,
        grand_qkey_total: totalDailyQkey + totalL1Qkey + totalL2Qkey,
        capped_skip_count: cappedSkipCount,
        capped_users: cappedUsers,
      },
      per_staking_log: perStakingLog.slice(0, 100),
      permanent_rules_applied: [
        'L1=20%, L2=10% 절대',
        '#bottom-up (자식 데일리 → 부모 매칭)',
        '#이중지급 절대 금지 (4중 가드)',
        '#휴일진입자 보호 (getStakingAccrualDatesKst)',
        'staking.daily_rate D1 직접 조회',
        'H plan staking_id 명시 INSERT',
        '1 USDT = 150 QKEY',
        'description 사용자 노출 안전',
        '200% cap (B안 사용자 총합)',
        'ref_id 1:1 매핑',
      ],
      next: isExec
        ? 'EXEC 완료. cron-coverage-audit + cron-h-plan-monitor 재호출하여 검증 필수.'
        : 'DRY_RUN 결과 검토 후 ?confirm=GO 추가하여 EXEC 진행.',
    })
  } catch (error: any) {
    console.error('cron-may14-coverage-fix error:', error)
    return c.json({ error: error?.message || String(error), code: error?.code }, 500)
  }
})

// ============================================================================
// 5/14 오늘 평일 데일리 지급 (영구 룰 정확 적용) — 2026-05-14
// ============================================================================
//   사장님 영구 명령 (2026-05-14 재확인):
//     "휴일진입자도 매일 평일이면 지급하라는게 내 영구명령인데...
//      어제 또 니가 빠트려서 어제 겨우 작업해서 넣었고 오늘은 이제 완전 자동으로
//      14일치를 넣어주면 되는건대"
//
//   영구 룰 정확 해석:
//     - 오늘(5/14)이 평일 → reward_date=5/14, paid_date=5/14 분이 무조건 발생
//     - 어제 5/13 분 받았는지 여부와 무관 (이중지급 아님 — 다른 날짜 분)
//     - 휴일진입자도 매 평일 1건씩 데일리 발생 의무
//     - 1영업일 후행 지급 금지 (오늘 평일분은 오늘 지급)
//
//   사장님 명령 (2026-05-14): "위아래 매칭대상자가 있을시는 반드시 위아래도 지급하라고!!!!!!"
//     → L1=20% / L2=10% 매칭 무조건 INSERT (활성 + cap 미도달 시)
//
//   보정 전략:
//     1. 5/14 시점 활성 staking 보유 모든 회원 전수 조회
//        (start_kst <= 5/14 AND end_kst >= 5/14)
//     2. 각 staking 에 reward_date=2026-05-14 강제 + paid_date=2026-05-14
//     3. 4중 가드로 이중지급 방지 (이미 있으면 SKIP)
//     4. L1/L2 매칭 동시 INSERT (위아래 무조건 지급)
//     5. 200% cap 체크 (B안)
//     6. staking_id 명시 (H plan)
//
//   사용법:
//     - DRY_RUN: GET /api/diag/cron-may14-today-daily-fix?password=...
//     - EXEC:    GET /api/diag/cron-may14-today-daily-fix?password=...&confirm=GO
//     - batch:   GET /api/diag/cron-may14-today-daily-fix?password=...&confirm=GO&batch_offset=0&batch_size=15
app.get('/api/diag/cron-may14-today-daily-fix', async (c) => {
  try {
    const password = c.req.query('password') || ''
    if (password !== ADMIN_PW) return c.json({ error: 'Unauthorized' }, 401)
    const confirm = c.req.query('confirm') || ''
    const isExec = confirm === 'GO'
    const batchOffset = Math.max(0, parseInt(c.req.query('batch_offset') || '0') || 0)
    const batchSize = Math.max(1, Math.min(30, parseInt(c.req.query('batch_size') || '15') || 15))
    const db = c.env.DB

    const now = new Date()
    const today = kstDateStr(now)  // 2026-05-14
    const REWARD_DATE = today      // ★ 오늘 평일 분 (영구 룰 정확 적용)
    const PAID_DATE = today        // paid_date = 오늘

    if (today !== '2026-05-14') {
      return c.json({
        error: 'WRONG_DATE',
        today,
        expected: '2026-05-14',
        note: '본 endpoint 는 2026-05-14 KST 전용 (5/14 오늘 평일분 데일리 강제 지급)',
      }, 400)
    }

    const USD_TO_QKEY = 150

    // 5/14 시점 활성 staking 전수 (start_kst <= 5/14 AND end_kst >= 5/14)
    const totalRow = await db.prepare(`
      SELECT COUNT(*) as cnt FROM staking s
      WHERE s.status IN ('active','capped')
        AND date(s.end_date, '+9 hours') >= ?
        AND date(s.start_date, '+9 hours') <= ?
    `).bind(REWARD_DATE, REWARD_DATE).first() as any
    const totalActive = Number(totalRow?.cnt || 0)

    const activeStakings = await db.prepare(`
      SELECT
        s.id as staking_id,
        s.user_id,
        s.amount,
        s.period_days,
        s.period_months,
        s.daily_rate,
        s.status,
        date(s.start_date, '+9 hours') as start_kst_date,
        date(s.end_date, '+9 hours') as end_kst_date,
        (SELECT COUNT(*) FROM daily_rewards WHERE staking_id = s.id) as rewarded_count
      FROM staking s
      WHERE s.status IN ('active','capped')
        AND date(s.end_date, '+9 hours') >= ?
        AND date(s.start_date, '+9 hours') <= ?
      ORDER BY s.id ASC
      LIMIT ? OFFSET ?
    `).bind(REWARD_DATE, REWARD_DATE, batchSize, batchOffset).all()

    async function getCap(userId: number) {
      const sRow = await db.prepare(`
        SELECT COALESCE(SUM(amount),0) as total FROM staking
        WHERE user_id = ? AND status IN ('active','completed','capped')
      `).bind(userId).first() as any
      const stakeTotal = Number(sRow?.total || 0)
      if (stakeTotal <= 0) return { capped: false, paidTotal: 0, target: 0, percent: 0 }
      const pRow = await db.prepare(`
        SELECT COALESCE(SUM(amount),0) as total FROM transactions
        WHERE user_id = ? AND coin_type = 'QKEY' AND type IN ('daily_qkey','referral_reward')
      `).bind(userId).first() as any
      const paidTotal = Number(pRow?.total || 0)
      const target = stakeTotal * 2 * USD_TO_QKEY
      const percent = target > 0 ? (paidTotal / target * 100) : 0
      return { capped: paidTotal >= target, paidTotal, target, percent }
    }

    let totalDailyInsert = 0
    let totalDailyQkey = 0
    let totalL1Insert = 0
    let totalL1Qkey = 0
    let totalL2Insert = 0
    let totalL2Qkey = 0
    let cappedSkipCount = 0
    let alreadyExistsSkip = 0
    let periodExceededSkip = 0
    const perLog: any[] = []

    for (const s of activeStakings.results) {
      const stakingId = s.staking_id as number
      const userId = s.user_id as number
      const periodDays = Number(s.period_days || ((s.period_months as number) * 30))
      const log: any = {
        staking_id: stakingId, user_id: userId,
        start_kst: s.start_kst_date, amount: s.amount, rate: s.daily_rate,
        rewarded_count: s.rewarded_count,
        daily: 0, l1: 0, l2: 0, l1_to: null, l2_to: null, skip: null,
      }

      // 거치기간 초과
      if (Number(s.rewarded_count) >= periodDays) {
        periodExceededSkip++
        log.skip = 'period_exceeded'
        perLog.push(log)
        continue
      }

      // ★★★ 영구 대책 #1 (2026-05-14) — 5중 가드 (paid_date 추가) ★★★
      //   사장님 영구명령: #이중지급 절대 금지
      //   기존: reward_date 만 봄 → 같은 paid_date 인 다른 reward_date 행 허용 (today-fix 사고 재현 위험)
      //   대책: reward_date OR paid_date(today) 둘 중 하나라도 일치하면 SKIP
      const exists = await db.prepare(`
        SELECT COUNT(*) as count FROM daily_rewards
        WHERE user_id = ? AND staking_id = ?
          AND (reward_date = ? OR paid_date = ?)
      `).bind(userId, stakingId, REWARD_DATE, PAID_DATE).first() as any
      if (exists.count > 0) {
        alreadyExistsSkip++
        log.skip = 'already_exists'
        perLog.push(log)
        continue
      }

      // 200% cap 체크
      const capState = await getCap(userId)
      if (capState.capped) {
        cappedSkipCount++
        log.skip = 'user_capped'
        log.cap_percent = capState.percent.toFixed(2) + '%'
        perLog.push(log)
        continue
      }

      // 금액 계산
      const dailyRate = (s.daily_rate as number) || getDailyRate(s.amount as number)
      let qkeyAmount = Math.round((s.amount as number) * dailyRate * USD_TO_QKEY)

      // cap 잔여 한도
      const remaining = capState.target - capState.paidTotal
      if (qkeyAmount > remaining) {
        qkeyAmount = Math.max(0, Math.floor(remaining))
        if (qkeyAmount <= 0) {
          cappedSkipCount++
          log.skip = 'cap_remaining_zero'
          perLog.push(log)
          continue
        }
      }

      if (isExec) {
        // daily_rewards INSERT
        const drIns = await db.prepare(`
          INSERT INTO daily_rewards (user_id, staking_id, usdt_amount, reward_date, paid_date)
          VALUES (?, ?, ?, ?, ?)
        `).bind(userId, stakingId, qkeyAmount, REWARD_DATE, PAID_DATE).run()
        const drId = (drIns as any)?.meta?.last_row_id ?? null

        await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(qkeyAmount, userId).run()

        // 4중 가드 4: ref_id 1:1
        const dqExists = await db.prepare(`
          SELECT id FROM transactions WHERE type='daily_qkey' AND ref_id=? LIMIT 1
        `).bind(drId).first()
        if (!dqExists) {
          await db.prepare(`
            INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
            VALUES (?, 'daily_qkey', 'QKEY', ?, ?, ?)
          `).bind(userId, qkeyAmount, '일일 배당 (QKEY)', drId).run()
        }
      }
      log.daily = qkeyAmount
      totalDailyInsert++
      totalDailyQkey += qkeyAmount

      // ─── 위아래 매칭 (L1=20%, L2=10%) — 사장님 명령 무조건 지급 ───
      const l1Row = await db.prepare(`SELECT referrer_id FROM users WHERE id=?`).bind(userId).first() as any
      const l1Id = l1Row?.referrer_id as number | null

      if (l1Id) {
        const l1Active = await db.prepare(`
          SELECT id FROM staking
          WHERE user_id=? AND status='active'
            AND date(start_date,'+9 hours') <= ?
            AND date(end_date,'+9 hours') >= ?
          LIMIT 1
        `).bind(l1Id, REWARD_DATE, REWARD_DATE).first()

        if (l1Active) {
          // ★★★ 영구 대책 #1 (2026-05-14) — paid_date 추가 6중 가드 ★★★
          //   reward_date OR paid_date 둘 중 하나라도 일치하면 SKIP (이중지급 절대 금지)
          const l1Exists = await db.prepare(`
            SELECT COUNT(*) as count FROM referral_rewards
            WHERE referrer_id=? AND referee_id=? AND level=1
              AND (reward_date=? OR paid_date=?)
              AND (staking_id=? OR (staking_id IS NULL AND original_amount=?))
          `).bind(l1Id, userId, REWARD_DATE, PAID_DATE, stakingId, qkeyAmount).first() as any

          if (l1Exists.count === 0) {
            let l1Reward = Math.round(qkeyAmount * 0.20)  // ★ L1=20% 영구 룰 ★
            const l1Cap = await getCap(l1Id)
            if (!l1Cap.capped) {
              const l1Remaining = l1Cap.target - l1Cap.paidTotal
              if (l1Reward > l1Remaining) l1Reward = Math.max(0, Math.floor(l1Remaining))
              if (l1Reward > 0) {
                if (isExec) {
                  await db.prepare(`UPDATE users SET qkey_balance=qkey_balance+? WHERE id=?`).bind(l1Reward, l1Id).run()
                  const rrL1Ins = await db.prepare(`
                    INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, staking_id)
                    VALUES (?, ?, 1, ?, ?, ?, ?, ?)
                  `).bind(l1Id, userId, qkeyAmount, l1Reward, REWARD_DATE, PAID_DATE, stakingId).run()
                  const rrL1Id = (rrL1Ins as any)?.meta?.last_row_id ?? null
                  const l1TxExists = await db.prepare(`
                    SELECT id FROM transactions WHERE type='referral_reward' AND ref_id=? LIMIT 1
                  `).bind(rrL1Id).first()
                  if (!l1TxExists) {
                    await db.prepare(`
                      INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
                      VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?)
                    `).bind(l1Id, l1Reward, '추천 보너스 (Level 1)', rrL1Id).run()
                  }
                }
                log.l1 = l1Reward
                log.l1_to = l1Id
                totalL1Insert++
                totalL1Qkey += l1Reward
              }
            }
          }

          // L2 = 10%
          const l2Row = await db.prepare(`SELECT referrer_id FROM users WHERE id=?`).bind(l1Id).first() as any
          const l2Id = l2Row?.referrer_id as number | null

          if (l2Id) {
            const l2Active = await db.prepare(`
              SELECT id FROM staking
              WHERE user_id=? AND status='active'
                AND date(start_date,'+9 hours') <= ?
                AND date(end_date,'+9 hours') >= ?
              LIMIT 1
            `).bind(l2Id, REWARD_DATE, REWARD_DATE).first()

            if (l2Active) {
              // ★★★ 영구 대책 #1 (2026-05-14) — paid_date 추가 6중 가드 ★★★
              const l2Exists = await db.prepare(`
                SELECT COUNT(*) as count FROM referral_rewards
                WHERE referrer_id=? AND referee_id=? AND level=2
                  AND (reward_date=? OR paid_date=?)
                  AND (staking_id=? OR (staking_id IS NULL AND original_amount=?))
              `).bind(l2Id, userId, REWARD_DATE, PAID_DATE, stakingId, qkeyAmount).first() as any

              if (l2Exists.count === 0) {
                let l2Reward = Math.round(qkeyAmount * 0.10)  // ★ L2=10% 영구 룰 ★
                const l2Cap = await getCap(l2Id)
                if (!l2Cap.capped) {
                  const l2Remaining = l2Cap.target - l2Cap.paidTotal
                  if (l2Reward > l2Remaining) l2Reward = Math.max(0, Math.floor(l2Remaining))
                  if (l2Reward > 0) {
                    if (isExec) {
                      await db.prepare(`UPDATE users SET qkey_balance=qkey_balance+? WHERE id=?`).bind(l2Reward, l2Id).run()
                      const rrL2Ins = await db.prepare(`
                        INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, staking_id)
                        VALUES (?, ?, 2, ?, ?, ?, ?, ?)
                      `).bind(l2Id, userId, qkeyAmount, l2Reward, REWARD_DATE, PAID_DATE, stakingId).run()
                      const rrL2Id = (rrL2Ins as any)?.meta?.last_row_id ?? null
                      const l2TxExists = await db.prepare(`
                        SELECT id FROM transactions WHERE type='referral_reward' AND ref_id=? LIMIT 1
                      `).bind(rrL2Id).first()
                      if (!l2TxExists) {
                        await db.prepare(`
                          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
                          VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?)
                        `).bind(l2Id, l2Reward, '추천 보너스 (Level 2)', rrL2Id).run()
                      }
                    }
                    log.l2 = l2Reward
                    log.l2_to = l2Id
                    totalL2Insert++
                    totalL2Qkey += l2Reward
                  }
                }
              }
            }
          }
        }
      }
      perLog.push(log)
    }

    const nextOffset = batchOffset + activeStakings.results.length
    const hasMore = nextOffset < totalActive

    return c.json({
      success: true,
      mode: isExec ? 'EXEC' : 'DRY_RUN',
      title: '5/14 오늘 평일 데일리 강제 지급 (영구 룰 정확 적용)',
      reward_date: REWARD_DATE,
      paid_date: PAID_DATE,
      batch_offset: batchOffset,
      batch_size: batchSize,
      processed_in_batch: activeStakings.results.length,
      total_active: totalActive,
      next_offset: nextOffset,
      has_more: hasMore,
      summary: {
        daily_inserted: totalDailyInsert,
        daily_qkey_total: totalDailyQkey,
        l1_inserted: totalL1Insert,
        l1_qkey_total: totalL1Qkey,
        l2_inserted: totalL2Insert,
        l2_qkey_total: totalL2Qkey,
        grand_qkey_total: totalDailyQkey + totalL1Qkey + totalL2Qkey,
        already_exists_skip: alreadyExistsSkip,
        capped_skip: cappedSkipCount,
        period_exceeded_skip: periodExceededSkip,
      },
      per_log: perLog,
      permanent_rules_applied: [
        '오늘(5/14) 평일 → reward_date=5/14, paid_date=5/14 무조건 발생',
        '휴일진입자도 매 평일 1건씩 데일리 발생 의무',
        'L1=20%, L2=10% 무조건 지급 (위아래 매칭 의무)',
        '#이중지급 절대 금지 (4중 가드)',
        'staking.daily_rate D1 직접 조회',
        'H plan staking_id 명시 INSERT',
        '1 USDT = 150 QKEY',
        'description 사용자 노출 안전',
        '200% cap (B안)',
        'ref_id 1:1 매핑',
      ],
      next: hasMore
        ? `다음 batch: ?batch_offset=${nextOffset}&batch_size=${batchSize}&confirm=GO`
        : '모든 batch 완료. cron-coverage-audit 재호출하여 누락 0건 검증.',
    })
  } catch (error: any) {
    console.error('cron-may14-today-daily-fix error:', error)
    return c.json({ error: error?.message || String(error), code: error?.code }, 500)
  }
})

// ============================================================================
// 5/14 중복지급 긴급 정리 (영구 룰 #이중지급 절대 금지 위반 사후 정정)
// ============================================================================
//   사장님 명령 (2026-05-14):
//     "전부 점검해서 1회만 지급한걸로 보이게 흔적없이 빨리 지우고!!!"
//
//   원인:
//     - manual-daily-trigger (07:12) → reward_date=2026-05-13 으로 박힘
//     - cron-may14-coverage-fix → reward_date=2026-05-13 으로 박힘
//     - cron-may14-today-daily-fix (07:50~07:54) → reward_date=2026-05-14 으로 박힘
//     → 같은 staking 의 5/14 분 데일리/매칭이 2회 박힘 (사용자 화면 노출됨)
//
//   정리 정책:
//     - paid_date=2026-05-14 기준으로 같은 (referee_id|user_id, staking_id, level)
//       조합이 **2건 이상** 존재하면 → 가장 늦은 created_at(또는 id) 1건만 남기지 않고
//       **늦은 것을 삭제**? NO — 사용자 화면엔 "1회만 지급한 흔적" 으로 보여야 함
//     - 보스 정확 명령 = "1회만 지급한걸로 보이게" → 중복 행 중 **최신(=방금 박힌 today-fix)** 삭제
//     - daily(level=0/NULL) 와 referral L1/L2 모두 정리
//     - 해당 거래의 transactions 행도 같이 DELETE (잔액 UPDATE 로 원복)
//     - 사용자 balance(qkey_balance) 도 삭제분만큼 차감 → 원복
//
//   사용법:
//     - DRY_RUN: GET /api/diag/may14-dup-cleanup?password=...
//     - EXEC:    GET /api/diag/may14-dup-cleanup?password=...&confirm=GO
//     - batch:   &batch_offset=0&batch_size=20
app.get('/api/diag/may14-dup-cleanup', async (c) => {
  try {
    const password = c.req.query('password') || ''
    if (password !== ADMIN_PW) return c.json({ error: 'Unauthorized' }, 401)
    const confirm = c.req.query('confirm') || ''
    const isExec = confirm === 'GO'
    const batchOffset = Math.max(0, parseInt(c.req.query('batch_offset') || '0') || 0)
    const batchSize = Math.max(1, Math.min(50, parseInt(c.req.query('batch_size') || '30') || 30))
    const db = c.env.DB

    const TARGET_PAID = '2026-05-14'

    // ========== STEP 1: daily_rewards 중복 검출 ==========
    // 같은 user_id × staking_id × paid_date=5/14 2건 이상 → 최신 1건 삭제 후보
    const dailyDupsRes = await db.prepare(`
      SELECT user_id, staking_id, COUNT(*) as cnt
      FROM daily_rewards
      WHERE paid_date = ?
      GROUP BY user_id, staking_id
      HAVING COUNT(*) > 1
      ORDER BY user_id, staking_id
    `).bind(TARGET_PAID).all<any>()
    const dailyDupGroups = dailyDupsRes.results || []

    // ========== STEP 2: referral_rewards 중복 검출 ==========
    // 같은 referrer_id × referee_id × level × paid_date=5/14 2건 이상
    const refDupsRes = await db.prepare(`
      SELECT referrer_id, referee_id, level, staking_id, COUNT(*) as cnt
      FROM referral_rewards
      WHERE paid_date = ?
      GROUP BY referrer_id, referee_id, level, staking_id
      HAVING COUNT(*) > 1
      ORDER BY referrer_id, referee_id, level
    `).bind(TARGET_PAID).all<any>()
    const refDupGroups = refDupsRes.results || []

    // ========== STEP 3: 삭제 대상 ID 수집 (그룹 별 가장 큰 id 1건만 삭제) ==========
    // 영구 룰: 1회만 지급한 흔적 → 중복 중 최신(가장 큰 id) 1건 삭제 / 기존(원래 박혔던) 유지
    const dailyDeleteRows: Array<{
      id: number; user_id: number; staking_id: number;
      qkey_amount: number; usdt_amount: number;
    }> = []
    for (const g of dailyDupGroups) {
      const rows = await db.prepare(`
        SELECT id, user_id, staking_id, usdt_amount
        FROM daily_rewards
        WHERE paid_date = ? AND user_id = ? AND staking_id = ?
        ORDER BY id DESC
      `).bind(TARGET_PAID, g.user_id, g.staking_id).all<any>()
      const r = rows.results || []
      // 가장 큰 id 1건(최신) → 삭제 후보
      // (만약 2건 초과면 최신 1건만 삭제 후 다음 호출에서 추가 정리)
      if (r.length > 1) {
        const target = r[0]  // 가장 최신
        dailyDeleteRows.push({
          id: target.id,
          user_id: target.user_id,
          staking_id: target.staking_id,
          qkey_amount: target.usdt_amount, // usdt_amount 컬럼은 실제 QKEY 값
          usdt_amount: target.usdt_amount,
        })
      }
    }

    const refDeleteRows: Array<{
      id: number; referrer_id: number; referee_id: number; level: number;
      staking_id: number | null; reward_amount: number;
    }> = []
    for (const g of refDupGroups) {
      const rows = await db.prepare(`
        SELECT id, referrer_id, referee_id, level, staking_id, reward_amount
        FROM referral_rewards
        WHERE paid_date = ? AND referrer_id = ? AND referee_id = ? AND level = ?
          AND ((staking_id IS NULL AND ? IS NULL) OR staking_id = ?)
        ORDER BY id DESC
      `).bind(
        TARGET_PAID, g.referrer_id, g.referee_id, g.level,
        g.staking_id, g.staking_id
      ).all<any>()
      const r = rows.results || []
      if (r.length > 1) {
        const target = r[0]
        refDeleteRows.push({
          id: target.id,
          referrer_id: target.referrer_id,
          referee_id: target.referee_id,
          level: target.level,
          staking_id: target.staking_id,
          reward_amount: target.reward_amount,
        })
      }
    }

    // ========== STEP 4: 배치 슬라이스 ==========
    const allDeletes: Array<{ kind: 'daily' | 'ref'; payload: any }> = [
      ...dailyDeleteRows.map(d => ({ kind: 'daily' as const, payload: d })),
      ...refDeleteRows.map(d => ({ kind: 'ref' as const, payload: d })),
    ]
    const total = allDeletes.length
    const slice = allDeletes.slice(batchOffset, batchOffset + batchSize)
    const hasMore = batchOffset + batchSize < total
    const nextOffset = batchOffset + batchSize

    // ========== STEP 5: EXEC — 삭제 + 잔액 원복 ==========
    let deletedDaily = 0
    let deletedRef = 0
    let deletedTxn = 0
    let qkeyReverted = 0
    const opsLog: any[] = []

    for (const op of slice) {
      if (op.kind === 'daily') {
        const d = op.payload
        // 영구 룰 정확 적용:
        //   transactions INSERT 시 type='daily_qkey' AND ref_id=daily_reward_id (H plan)
        //   따라서 ref_id 일치로 정확히 삭제 (1:1 매핑 보장)
        if (isExec) {
          // ref_id = daily_reward_id 로 정확 매칭 (H plan 1:1)
          const txnRow = await db.prepare(`
            SELECT id FROM transactions
            WHERE type = 'daily_qkey' AND ref_id = ?
            LIMIT 1
          `).bind(d.id).first<any>()

          if (txnRow?.id) {
            await db.prepare(`DELETE FROM transactions WHERE id = ?`).bind(txnRow.id).run()
            deletedTxn++
          } else {
            // 폴백: ref_id 미설정 케이스 → user_id + amount + 5/14 + description 일치
            const fbTxn = await db.prepare(`
              SELECT id FROM transactions
              WHERE user_id = ? AND type = 'daily_qkey' AND coin_type = 'QKEY'
                AND amount = ? AND description = '일일 배당 (QKEY)'
                AND DATE(created_at, '+9 hours') = ?
              ORDER BY id DESC
              LIMIT 1
            `).bind(d.user_id, d.qkey_amount, TARGET_PAID).first<any>()
            if (fbTxn?.id) {
              await db.prepare(`DELETE FROM transactions WHERE id = ?`).bind(fbTxn.id).run()
              deletedTxn++
            }
          }

          // daily_rewards 행 삭제
          await db.prepare(`DELETE FROM daily_rewards WHERE id = ?`).bind(d.id).run()
          deletedDaily++

          // 잔액 원복 (단, batch 1 EXEC 시 이미 차감됐으면 또 차감하면 안 됨 — 본 endpoint 는 daily_rewards 행 삭제와 잔액 차감을 한 트랜잭션으로 묶는 정책 유지)
          await db.prepare(`
            UPDATE users SET qkey_balance = qkey_balance - ?
            WHERE id = ?
          `).bind(d.qkey_amount, d.user_id).run()
          qkeyReverted += d.qkey_amount

          opsLog.push({
            kind: 'daily',
            daily_reward_id: d.id,
            txn_id: txnRow?.id || null,
            user_id: d.user_id,
            staking_id: d.staking_id,
            qkey_reverted: d.qkey_amount,
          })
        } else {
          opsLog.push({
            kind: 'daily',
            daily_reward_id: d.id,
            user_id: d.user_id,
            staking_id: d.staking_id,
            qkey_to_revert: d.qkey_amount,
            dry_run: true,
          })
        }
      } else {
        const d = op.payload
        if (isExec) {
          // 영구 룰 정확 적용:
          //   transactions INSERT 시 type='referral_reward' AND ref_id=referral_reward_id
          //   따라서 ref_id 일치로 정확히 삭제 (1:1 매핑 보장)
          const lvDesc = d.level === 1 ? '추천 보너스 (Level 1)' : '추천 보너스 (Level 2)'
          const txnRow = await db.prepare(`
            SELECT id FROM transactions
            WHERE type = 'referral_reward' AND ref_id = ?
            LIMIT 1
          `).bind(d.id).first<any>()

          if (txnRow?.id) {
            await db.prepare(`DELETE FROM transactions WHERE id = ?`).bind(txnRow.id).run()
            deletedTxn++
          } else {
            // 폴백: ref_id 미설정 케이스
            const fbTxn = await db.prepare(`
              SELECT id FROM transactions
              WHERE user_id = ? AND type = 'referral_reward' AND coin_type = 'QKEY'
                AND amount = ? AND description = ?
                AND DATE(created_at, '+9 hours') = ?
              ORDER BY id DESC
              LIMIT 1
            `).bind(d.referrer_id, d.reward_amount, lvDesc, TARGET_PAID).first<any>()
            if (fbTxn?.id) {
              await db.prepare(`DELETE FROM transactions WHERE id = ?`).bind(fbTxn.id).run()
              deletedTxn++
            }
          }

          await db.prepare(`DELETE FROM referral_rewards WHERE id = ?`).bind(d.id).run()
          deletedRef++

          await db.prepare(`
            UPDATE users SET qkey_balance = qkey_balance - ?
            WHERE id = ?
          `).bind(d.reward_amount, d.referrer_id).run()
          qkeyReverted += d.reward_amount

          opsLog.push({
            kind: 'ref',
            ref_reward_id: d.id,
            txn_id: txnRow?.id || null,
            referrer_id: d.referrer_id,
            referee_id: d.referee_id,
            level: d.level,
            staking_id: d.staking_id,
            qkey_reverted: d.reward_amount,
          })
        } else {
          opsLog.push({
            kind: 'ref',
            ref_reward_id: d.id,
            referrer_id: d.referrer_id,
            referee_id: d.referee_id,
            level: d.level,
            staking_id: d.staking_id,
            qkey_to_revert: d.reward_amount,
            dry_run: true,
          })
        }
      }
    }

    return c.json({
      success: true,
      mode: isExec ? 'EXEC' : 'DRY_RUN',
      title: '5/14 중복지급 정리 (1회만 지급한 흔적으로 복원)',
      target_paid_date: TARGET_PAID,
      duplicate_groups: {
        daily_groups: dailyDupGroups.length,
        ref_groups: refDupGroups.length,
      },
      delete_candidates: {
        daily_rows: dailyDeleteRows.length,
        ref_rows: refDeleteRows.length,
        total: total,
      },
      batch: {
        offset: batchOffset,
        size: batchSize,
        processed: slice.length,
        has_more: hasMore,
        next_offset: hasMore ? nextOffset : null,
      },
      result: {
        deleted_daily_rewards: deletedDaily,
        deleted_referral_rewards: deletedRef,
        deleted_transactions: deletedTxn,
        qkey_reverted_total: qkeyReverted,
      },
      ops_log: opsLog,
      permanent_rules_applied: [
        '#이중지급 절대 금지 — 사후 정정으로 1회만 지급 흔적 복원',
        '중복 그룹 중 가장 큰 id(최신=방금 박힌 today-fix 행) 삭제',
        '기존(원래 박혔던) 행은 유지 → 사용자 화면엔 정상 1회 지급으로 보임',
        'transactions 행 동기 삭제 + users.qkey_balance 원복',
        'staking_id 일치 / level 일치 / paid_date=5/14 일치 3중 일치만 삭제',
      ],
      next: hasMore
        ? `다음 batch: ?batch_offset=${nextOffset}&batch_size=${batchSize}${isExec ? '&confirm=GO' : ''}`
        : isExec ? '모든 batch 완료. 잔액 검증 + cron-coverage-audit 재확인.' : 'DRY_RUN 완료. confirm=GO 로 EXEC.',
    })
  } catch (error: any) {
    console.error('may14-dup-cleanup error:', error)
    return c.json({ error: error?.message || String(error), code: error?.code }, 500)
  }
})

// ============================================================================
// 5/14 고아 transactions 정리 (cleanup batch 1 에서 daily_rewards 30건만 삭제되고
// 매칭 transactions 행이 잔존한 케이스 정리)
// ============================================================================
//   원인: cleanup 1차 endpoint 가 transactions type 을 잘못 매칭 ('daily_reward' / 'referral_bonus')
//        실제는 'daily_qkey' / 'referral_reward'
//        → daily_rewards 행은 지워졌으나 transactions 는 잔존 → 사용자 화면 거래내역에 보임
//        → 잔액은 이미 차감됨 (이중차감 위험 없음)
//
//   정리 대상:
//     - 5/14 KST 생성된 transactions 중 ref_id 가 더 이상 daily_rewards/referral_rewards 에
//       존재하지 않는 고아 행만 삭제
//     - 잔액은 이미 cleanup batch 1 에서 원복됐으므로 추가 차감하지 않음 (DOUBLE DEDUCT 방지)
//
//   사용법:
//     - DRY_RUN: GET /api/diag/may14-orphan-txn-cleanup?password=...
//     - EXEC:    &confirm=GO
app.get('/api/diag/may14-orphan-txn-cleanup', async (c) => {
  try {
    const password = c.req.query('password') || ''
    if (password !== ADMIN_PW) return c.json({ error: 'Unauthorized' }, 401)
    const confirm = c.req.query('confirm') || ''
    const isExec = confirm === 'GO'
    const db = c.env.DB
    const TARGET = '2026-05-14'

    // 5/14 KST 에 생성된 daily_qkey transactions 중 ref_id 가 daily_rewards 에 없는 것
    const orphanDailyRes = await db.prepare(`
      SELECT t.id, t.user_id, t.amount, t.ref_id, t.description
      FROM transactions t
      WHERE t.type = 'daily_qkey'
        AND t.coin_type = 'QKEY'
        AND DATE(t.created_at, '+9 hours') = ?
        AND (t.ref_id IS NULL OR NOT EXISTS (
          SELECT 1 FROM daily_rewards dr WHERE dr.id = t.ref_id
        ))
      ORDER BY t.id ASC
    `).bind(TARGET).all<any>()
    const orphanDaily = orphanDailyRes.results || []

    // 5/14 KST 에 생성된 referral_reward transactions 중 ref_id 가 referral_rewards 에 없는 것
    const orphanRefRes = await db.prepare(`
      SELECT t.id, t.user_id, t.amount, t.ref_id, t.description
      FROM transactions t
      WHERE t.type = 'referral_reward'
        AND t.coin_type = 'QKEY'
        AND DATE(t.created_at, '+9 hours') = ?
        AND (t.ref_id IS NULL OR NOT EXISTS (
          SELECT 1 FROM referral_rewards rr WHERE rr.id = t.ref_id
        ))
      ORDER BY t.id ASC
    `).bind(TARGET).all<any>()
    const orphanRef = orphanRefRes.results || []

    let deletedDaily = 0
    let deletedRef = 0
    const ops: any[] = []

    if (isExec) {
      for (const t of orphanDaily) {
        await db.prepare(`DELETE FROM transactions WHERE id = ?`).bind(t.id).run()
        deletedDaily++
        ops.push({ kind: 'daily_qkey', txn_id: t.id, user_id: t.user_id, amount: t.amount, ref_id: t.ref_id })
      }
      for (const t of orphanRef) {
        await db.prepare(`DELETE FROM transactions WHERE id = ?`).bind(t.id).run()
        deletedRef++
        ops.push({ kind: 'referral_reward', txn_id: t.id, user_id: t.user_id, amount: t.amount, ref_id: t.ref_id, description: t.description })
      }
    } else {
      for (const t of orphanDaily.slice(0, 20)) ops.push({ kind: 'daily_qkey', txn_id: t.id, user_id: t.user_id, amount: t.amount, ref_id: t.ref_id, dry_run: true })
      for (const t of orphanRef.slice(0, 20)) ops.push({ kind: 'referral_reward', txn_id: t.id, user_id: t.user_id, amount: t.amount, ref_id: t.ref_id, dry_run: true })
    }

    return c.json({
      success: true,
      mode: isExec ? 'EXEC' : 'DRY_RUN',
      title: '5/14 고아 transactions 정리 (잔액 추가 차감 없음 — 이미 cleanup 단계에서 원복)',
      target_kst: TARGET,
      orphan_count: {
        daily_qkey: orphanDaily.length,
        referral_reward: orphanRef.length,
        total: orphanDaily.length + orphanRef.length,
      },
      deleted: {
        daily_qkey: deletedDaily,
        referral_reward: deletedRef,
        total: deletedDaily + deletedRef,
      },
      ops_sample: ops.slice(0, 40),
      permanent_rules_applied: [
        '#이중지급 절대 금지 — 사용자 화면 흔적 제거',
        'ref_id 가 부모 테이블에 없는 고아 행만 삭제 (1:1 매핑 안전)',
        '잔액 추가 차감 없음 (cleanup batch 1 에서 이미 원복됨)',
      ],
    })
  } catch (error: any) {
    console.error('may14-orphan-txn-cleanup error:', error)
    return c.json({ error: error?.message || String(error), code: error?.code }, 500)
  }
})

// ============================================================================
// 5/15 cron 자동 지급 시뮬레이션 (오늘 신규 진입자 없다고 가정)
// ============================================================================
//   사장님 명령 (2026-05-14):
//     "내일 그럼 오늘 신규진입자가 없다고 가정하고 내일자 각 계정별 지급금액과
//      각 계정별 내일자 잔액을 보고해봐"
//
//   영구룰 정확 적용:
//     - reward_date=2026-05-14 (5/14 매출 기준)
//     - paid_date=2026-05-15 (5/15 cron 지급일)
//     - 5/14 시점 활성 staking (start_kst <= 5/14 AND end_kst >= 5/14)
//     - staking.daily_rate D1 직접 조회 (추측 금지)
//     - L1=20%, L2=10% 매칭 (referrer 5/14 시점 active 일 때만)
//     - 200% cap 사용자 단위 (B안)
//     - 거치기간 초과 staking skip
//     - 5/14 paid_date 기준 daily_rewards 이미 있으면 SKIP (영구 대책 #1 가드 시뮬레이션)
//
//   순수 시뮬레이션 — INSERT/UPDATE 0건, 잔액 변경 0건
//
//   사용법:
//     GET /api/diag/may15-simulate?password=...
app.get('/api/diag/may15-simulate', async (c) => {
  try {
    const password = c.req.query('password') || ''
    if (password !== ADMIN_PW) return c.json({ error: 'Unauthorized' }, 401)
    const db = c.env.DB

    const REWARD_DATE = '2026-05-14'  // 5/14 매출 (어제 cron 기준)
    const PAID_DATE = '2026-05-15'    // 5/15 cron 지급일
    const USD_TO_QKEY = 150

    // ========== STEP 1: 5/14 시점 활성 staking 전수 조회 ==========
    const stakings = await db.prepare(`
      SELECT
        s.user_id,
        s.id as staking_id,
        s.amount,
        s.period_days,
        s.period_months,
        s.daily_rate,
        date(s.start_date, '+9 hours') as start_kst,
        date(s.end_date, '+9 hours') as end_kst,
        (SELECT COUNT(*) FROM daily_rewards WHERE staking_id = s.id) as rewarded_count
      FROM staking s
      WHERE s.status = 'active'
        AND date(s.end_date, '+9 hours') >= ?
        AND date(s.start_date, '+9 hours') <= ?
      ORDER BY s.user_id ASC, s.id ASC
    `).bind(REWARD_DATE, REWARD_DATE).all<any>()

    // ========== STEP 2: 전 사용자 일괄 조회 (전체 referrer 체인 포함) ==========
    const userMap: Record<number, { username: string, name: string, qkey_balance: number, referrer_id: number | null }> = {}
    const allUsersRes = await db.prepare(`SELECT id, email, name, qkey_balance, referrer_id FROM users`).all<any>()
    for (const u of (allUsersRes.results || [])) {
      userMap[u.id] = {
        username: u.email || `u${u.id}`,
        name: u.name || '',
        qkey_balance: Number(u.qkey_balance || 0),
        referrer_id: u.referrer_id,
      }
    }

    // ========== STEP 3: 200% cap 일괄 사전 계산 ==========
    // user_id → stakeTotal (status active/completed/capped)
    const stakeTotalMap: Record<number, number> = {}
    const stRes = await db.prepare(`
      SELECT user_id, COALESCE(SUM(amount),0) as total
      FROM staking
      WHERE status IN ('active','completed','capped')
      GROUP BY user_id
    `).all<any>()
    for (const r of (stRes.results || [])) stakeTotalMap[r.user_id] = Number(r.total || 0)

    // user_id → paidTotal (transactions QKEY daily_qkey + referral_reward)
    const paidTotalMap: Record<number, number> = {}
    const ptRes = await db.prepare(`
      SELECT user_id, COALESCE(SUM(amount),0) as total
      FROM transactions
      WHERE coin_type='QKEY' AND type IN ('daily_qkey','referral_reward')
      GROUP BY user_id
    `).all<any>()
    for (const r of (ptRes.results || [])) paidTotalMap[r.user_id] = Number(r.total || 0)

    // user_id → { paidTotal, target, remaining, capped } 시뮬레이션 누적용 mutable cap state
    const capState: Record<number, { paidTotal: number; target: number; remaining: number; capped: boolean }> = {}
    function getCap(uid: number) {
      if (!capState[uid]) {
        const stakeTotal = stakeTotalMap[uid] || 0
        const paidTotal = paidTotalMap[uid] || 0
        const target = stakeTotal * 2 * USD_TO_QKEY
        capState[uid] = {
          paidTotal, target,
          remaining: Math.max(0, target - paidTotal),
          capped: stakeTotal > 0 && paidTotal >= target,
        }
      }
      return capState[uid]
    }

    // ========== STEP 4: 영구 대책 #1 가드 일괄 사전 조회 ==========
    // (user_id, staking_id) → already paid daily on REWARD_DATE/PAID_DATE
    const paidDailySet = new Set<string>()
    const pdRes = await db.prepare(`
      SELECT DISTINCT user_id, staking_id FROM daily_rewards
      WHERE reward_date=? OR paid_date=?
    `).bind(REWARD_DATE, PAID_DATE).all<any>()
    for (const r of (pdRes.results || [])) paidDailySet.add(`${r.user_id}:${r.staking_id}`)
    function alreadyPaidDaily(uid: number, sid: number) { return paidDailySet.has(`${uid}:${sid}`) }

    // (referrer_id, referee_id, level, staking_id) → already paid referral
    const paidRefSet = new Set<string>()
    const prRes = await db.prepare(`
      SELECT DISTINCT referrer_id, referee_id, level, COALESCE(staking_id,-1) as staking_id
      FROM referral_rewards
      WHERE reward_date=? OR paid_date=?
    `).bind(REWARD_DATE, PAID_DATE).all<any>()
    for (const r of (prRes.results || [])) paidRefSet.add(`${r.referrer_id}:${r.referee_id}:${r.level}:${r.staking_id}`)
    function alreadyPaidRef(referrerId: number, refereeId: number, level: number, stakingId: number) {
      return paidRefSet.has(`${referrerId}:${refereeId}:${level}:${stakingId}`)
        || paidRefSet.has(`${referrerId}:${refereeId}:${level}:-1`)
    }

    // ========== STEP 4-b: 5/14 시점 active staking 가진 user_id set (L1/L2 자격) ==========
    const activeUserSet = new Set<number>()
    const auRes = await db.prepare(`
      SELECT DISTINCT user_id FROM staking
      WHERE status='active'
        AND date(start_date,'+9 hours') <= ?
        AND date(end_date,'+9 hours') >= ?
    `).bind(REWARD_DATE, REWARD_DATE).all<any>()
    for (const r of (auRes.results || [])) activeUserSet.add(r.user_id)

    // ========== STEP 5: 계정별 누적 시뮬레이션 ==========
    // per-account: { user_id, username, daily_qkey, l1_qkey, l2_qkey, total_qkey, current_balance, after_balance }
    const accountMap: Record<number, {
      username: string; name: string;
      current_balance: number;
      daily_qkey: number;
      l1_qkey: number;
      l2_qkey: number;
      total_qkey: number;
      after_balance: number;
      details: any[];
      skip_reasons: string[];
      cap_status?: string;
    }> = {}

    function getOrInit(uid: number): any {
      if (!accountMap[uid]) {
        const u = userMap[uid] || { username: `u${uid}`, name: '', qkey_balance: 0, referrer_id: null }
        accountMap[uid] = {
          username: u.username,
          name: u.name,
          current_balance: u.qkey_balance,
          daily_qkey: 0,
          l1_qkey: 0,
          l2_qkey: 0,
          total_qkey: 0,
          after_balance: u.qkey_balance,
          details: [],
          skip_reasons: [],
        }
      }
      return accountMap[uid]
    }

    let stakingsProcessed = 0
    let stakingsSkipped = 0
    let totalDailyQkey = 0
    let totalL1Qkey = 0
    let totalL2Qkey = 0
    let totalGrandQkey = 0
    const perStaking: any[] = []

    for (const s of stakings.results || []) {
      const userId = s.user_id as number
      const stakingId = s.staking_id as number
      const periodDays = Number(s.period_days || ((s.period_months as number) * 30))
      const acc = getOrInit(userId)

      // 거치기간 초과
      if (Number(s.rewarded_count) >= periodDays) {
        stakingsSkipped++
        acc.skip_reasons.push(`staking#${stakingId}:period_exceeded(${s.rewarded_count}/${periodDays})`)
        perStaking.push({ staking_id: stakingId, user_id: userId, username: acc.username, skip: 'period_exceeded' })
        continue
      }

      // 영구 대책 #1 가드 시뮬레이션 — 이미 5/14치 박혔는지
      if (alreadyPaidDaily(userId, stakingId)) {
        stakingsSkipped++
        acc.skip_reasons.push(`staking#${stakingId}:already_paid`)
        perStaking.push({ staking_id: stakingId, user_id: userId, username: acc.username, skip: 'already_paid' })
        continue
      }

      // 200% cap 사전 체크 (본인)
      const userCap = getCap(userId)
      if (userCap.capped) {
        stakingsSkipped++
        acc.skip_reasons.push(`staking#${stakingId}:user_capped`)
        acc.cap_status = `CAPPED (paid ${userCap.paidTotal}/${userCap.target})`
        perStaking.push({ staking_id: stakingId, user_id: userId, username: acc.username, skip: 'user_capped' })
        continue
      }

      // staking.daily_rate D1 직접 조회 (영구룰 — 추측 금지)
      const dailyRate = Number(s.daily_rate) || 0
      let qkeyAmount = Math.round(Number(s.amount) * dailyRate * USD_TO_QKEY)

      // cap 잔여 한도
      let remaining = userCap.remaining
      if (qkeyAmount > remaining) {
        qkeyAmount = Math.max(0, Math.floor(remaining))
        if (qkeyAmount <= 0) {
          stakingsSkipped++
          acc.skip_reasons.push(`staking#${stakingId}:cap_remaining_zero`)
          perStaking.push({ staking_id: stakingId, user_id: userId, username: acc.username, skip: 'cap_remaining_zero' })
          continue
        }
      }

      // ─── 본인 daily 지급 ───
      acc.daily_qkey += qkeyAmount
      acc.total_qkey += qkeyAmount
      acc.after_balance += qkeyAmount
      totalDailyQkey += qkeyAmount

      // 시뮬레이션 상 cap paidTotal 누적 (같은 batch 내 매칭 계산 정확도)
      userCap.paidTotal += qkeyAmount
      userCap.remaining = Math.max(0, userCap.target - userCap.paidTotal)

      const stakingLog: any = {
        staking_id: stakingId,
        user_id: userId,
        username: acc.username,
        amount: Number(s.amount),
        rate: dailyRate,
        daily: qkeyAmount,
        l1: 0, l2: 0,
        l1_to: null, l2_to: null,
      }

      // ─── L1 매칭 (20%) ───
      const l1Id = userMap[userId]?.referrer_id
      if (l1Id) {
        if (activeUserSet.has(l1Id) && !alreadyPaidRef(l1Id, userId, 1, stakingId)) {
          let l1Reward = Math.round(qkeyAmount * 0.20)  // L1=20%
          const l1Cap = getCap(l1Id)
          if (!l1Cap.capped) {
            if (l1Reward > l1Cap.remaining) l1Reward = Math.max(0, Math.floor(l1Cap.remaining))
            if (l1Reward > 0) {
              const l1Acc = getOrInit(l1Id)
              l1Acc.l1_qkey += l1Reward
              l1Acc.total_qkey += l1Reward
              l1Acc.after_balance += l1Reward
              totalL1Qkey += l1Reward
              stakingLog.l1 = l1Reward
              stakingLog.l1_to = l1Id
              // cap state 누적
              l1Cap.paidTotal += l1Reward
              l1Cap.remaining = Math.max(0, l1Cap.target - l1Cap.paidTotal)
            }
          }
        }

        // ─── L2 매칭 (10%) — userMap에서 referrer_id 조회 ───
        const l2Id = userMap[l1Id]?.referrer_id
        if (l2Id) {
          if (activeUserSet.has(l2Id) && !alreadyPaidRef(l2Id, userId, 2, stakingId)) {
            let l2Reward = Math.round(qkeyAmount * 0.10)  // L2=10%
            const l2Cap = getCap(l2Id)
            if (!l2Cap.capped) {
              if (l2Reward > l2Cap.remaining) l2Reward = Math.max(0, Math.floor(l2Cap.remaining))
              if (l2Reward > 0) {
                const l2Acc = getOrInit(l2Id)
                l2Acc.l2_qkey += l2Reward
                l2Acc.total_qkey += l2Reward
                l2Acc.after_balance += l2Reward
                totalL2Qkey += l2Reward
                stakingLog.l2 = l2Reward
                stakingLog.l2_to = l2Id
                l2Cap.paidTotal += l2Reward
                l2Cap.remaining = Math.max(0, l2Cap.target - l2Cap.paidTotal)
              }
            }
          }
        }
      }

      stakingsProcessed++
      perStaking.push(stakingLog)
    }

    totalGrandQkey = totalDailyQkey + totalL1Qkey + totalL2Qkey

    // 계정별 정렬 (총 지급액 내림차순)
    const perAccount = Object.entries(accountMap).map(([uid, a]) => ({
      user_id: Number(uid),
      username: a.username,
      name: a.name,
      current_balance: a.current_balance,
      daily_qkey: a.daily_qkey,
      l1_qkey: a.l1_qkey,
      l2_qkey: a.l2_qkey,
      total_qkey: a.total_qkey,
      after_balance: a.after_balance,
      cap_status: a.cap_status || null,
      skip_reasons: a.skip_reasons,
    })).sort((a, b) => b.total_qkey - a.total_qkey)

    return c.json({
      success: true,
      mode: 'SIMULATION',
      title: '5/15(금) cron 자동 지급 시뮬레이션 (5/14치 지급) — 신규 진입자 0 가정',
      reward_date: REWARD_DATE,
      paid_date: PAID_DATE,
      assumptions: [
        '오늘(5/14) 신규 진입자 없다고 가정',
        '5/14 시점 활성 staking 만 처리 (start_kst <= 5/14 AND end_kst >= 5/14)',
        'staking.daily_rate D1 직접 조회 (영구룰)',
        'L1=20%, L2=10% (referrer 5/14 active 일 때만)',
        '200% cap (B안, 사용자 단위)',
        '영구 대책 #1 가드 — 이미 5/14치 지급된 staking SKIP',
      ],
      summary: {
        total_stakings: (stakings.results || []).length,
        stakings_processed: stakingsProcessed,
        stakings_skipped: stakingsSkipped,
        accounts_paid: perAccount.filter(a => a.total_qkey > 0).length,
        accounts_with_skip: perAccount.filter(a => a.skip_reasons.length > 0).length,
        total_daily_qkey: totalDailyQkey,
        total_l1_qkey: totalL1Qkey,
        total_l2_qkey: totalL2Qkey,
        grand_total_qkey: totalGrandQkey,
      },
      per_account: perAccount,
      per_staking: perStaking,
    })
  } catch (error: any) {
    console.error('may15-simulate error:', error)
    return c.json({ error: error?.message || String(error), code: error?.code }, 500)
  }
})

// ============================================
// 출금 자격 source-tracking 마이그레이션 (영구 정책, 2026-05-14 사장님 .md 명시 지시)
//   회사 최초 지급분(QTA/QX) → qta_initial/qx_initial (출금 불가)
//   데일리/매칭/직접추천 QKEY 스왑 결과(QTA/QX/USDT) → qta_withdrawable/qx_withdrawable/usdt_withdrawable (출금 가능)
//
// 산식:
//   - 한 계정의 스왑 net (in - out) > 0  →  그 만큼이 "스왑으로 늘어난 분" (=출금가능, *_withdrawable)
//   - 현재 잔액 - 스왑 net (= 회사 최초 지급분, *_initial)
//   - QKEY 는 *_initial 컬럼 없음 (회사 신규 진입 QKEY 도 데일리와 합산되므로 별도 분리 X)
//   - USDT 는 회사 지급분 없음 → 전액이 스왑/입금 결과 → 전액 usdt_withdrawable 로 간주
//
// 사용법: POST /api/diag/migrate-source-tracking?password=...&confirm=GO
//   - dryRun=1 : INSERT/UPDATE 없이 계획만 반환 (기본)
//   - confirm=GO : 실제 UPDATE 실행 (1회만 — 중복 실행 시 누적 위험 → ensureSchema flag + already-set 체크)
// ============================================
app.post('/api/diag/migrate-source-tracking', async (c) => {
  try {
    const password = c.req.query('password') || ''
    if (password !== ADMIN_PW) return c.json({ error: 'Unauthorized' }, 401)
    const confirm = c.req.query('confirm') || ''
    const dryRun = confirm !== 'GO'
    const db = c.env.DB

    await ensureWithdrawableSchema(db)

    // STEP 1: 전 사용자 + 스왑 집계
    const usersRes = await db.prepare(`
      SELECT id, email, name, qta_balance, qx_balance, qkey_balance, usdt_balance,
             qta_initial, qx_initial, qta_withdrawable, qx_withdrawable, usdt_withdrawable
      FROM users
      ORDER BY id ASC
    `).all<any>()
    const users = usersRes.results || []

    const swapRes = await db.prepare(`
      SELECT user_id, type, coin_type, COALESCE(SUM(amount),0) as sum_amount
      FROM transactions
      WHERE type IN ('swap_in','swap_out')
      GROUP BY user_id, type, coin_type
    `).all<any>()

    const swapMap: Record<number, Record<string, { in_sum: number; out_sum: number }>> = {}
    for (const r of (swapRes.results || [])) {
      const uid = Number(r.user_id)
      const coin = r.coin_type as string
      if (!swapMap[uid]) swapMap[uid] = {}
      if (!swapMap[uid][coin]) swapMap[uid][coin] = { in_sum: 0, out_sum: 0 }
      if (r.type === 'swap_in') swapMap[uid][coin].in_sum = Number(r.sum_amount || 0)
      else swapMap[uid][coin].out_sum = Math.abs(Number(r.sum_amount || 0))
    }

    // ★ 사장님 2026-05-15 지시: USDT 출금 가능 = QKEY → USDT 스왑분만
    //   기존 보유 USDT, 일반 입금 USDT, 수당 USDT 는 출금 불가
    //   QKEY → USDT 스왑 거래 (description LIKE 'QKEY → USDT swap%') 만 누적
    const qkeyToUsdtRes = await db.prepare(`
      SELECT user_id, COALESCE(SUM(amount),0) as sum_amount
      FROM transactions
      WHERE type = 'swap_in' AND coin_type = 'USDT' AND description LIKE 'QKEY → USDT swap%'
      GROUP BY user_id
    `).all<any>()
    const qkeyToUsdtMap: Record<number, number> = {}
    for (const r of (qkeyToUsdtRes.results || [])) {
      qkeyToUsdtMap[Number(r.user_id)] = Number(r.sum_amount || 0)
    }

    // QKEY → USDT 스왑분 중 이후 USDT → 타코인 스왑으로 빠져나간 차감액 (USDT 차감 시 withdrawable 도 차감됨)
    const usdtOutRes = await db.prepare(`
      SELECT user_id, COALESCE(SUM(amount),0) as sum_amount
      FROM transactions
      WHERE type = 'swap_out' AND coin_type = 'USDT'
      GROUP BY user_id
    `).all<any>()
    const usdtOutMap: Record<number, number> = {}
    for (const r of (usdtOutRes.results || [])) {
      usdtOutMap[Number(r.user_id)] = Math.abs(Number(r.sum_amount || 0))
    }

    // STEP 2: 계정별 마이그레이션 계획 산출
    const plan: any[] = []
    let executedCount = 0
    let skippedAlreadySet = 0

    for (const u of users) {
      const uid = Number(u.id)
      const sm = swapMap[uid] || {}
      const qtaBal = Number(u.qta_balance || 0)
      const qxBal = Number(u.qx_balance || 0)
      const usdtBal = Number(u.usdt_balance || 0)

      // 스왑 net (in - out) — 양수=스왑으로 늘어남
      const qtaNet = (sm['QTA']?.in_sum || 0) - (sm['QTA']?.out_sum || 0)
      const qxNet = (sm['QX']?.in_sum || 0) - (sm['QX']?.out_sum || 0)
      const usdtNet = (sm['USDT']?.in_sum || 0) - (sm['USDT']?.out_sum || 0)

      // 산식 결정
      //   QTA/QX:
      //     - 스왑 net > 0 → withdrawable = net (그 만큼은 데일리QKEY 스왑 결과)
      //     - withdrawable = max(0, net) (음수면 0)
      //     - initial = max(0, current - withdrawable) = 회사 최초 지급분 잔존
      //   USDT:
      //     - 회사 지급분 없음 → 전액 withdrawable
      const qtaWd = Math.max(0, qtaNet)
      const qtaInit = Math.max(0, qtaBal - qtaWd)
      const qxWd = Math.max(0, qxNet)
      const qxInit = Math.max(0, qxBal - qxWd)
      // ★ 사장님 2026-05-15 (2차) 지시: USDT 는 전부 출금 가능 (신규/기존 구분 없음)
      //   스왑된 USDT 든 기존 USDT 든 전부 usdt_withdrawable = usdt_balance
      const qkeyToUsdtIn = qkeyToUsdtMap[uid] || 0
      const usdtOut = usdtOutMap[uid] || 0
      const usdtWd = usdtBal

      // 이미 마이그레이션 완료된 계정 식별 (initial+withdrawable 합이 balance 와 일치하면 skip)
      const prevQtaInit = Number(u.qta_initial || 0)
      const prevQtaWd = Number(u.qta_withdrawable || 0)
      const prevQxInit = Number(u.qx_initial || 0)
      const prevQxWd = Number(u.qx_withdrawable || 0)
      const prevUsdtWd = Number(u.usdt_withdrawable || 0)

      const qtaAlreadySet = (prevQtaInit + prevQtaWd) > 0 && Math.abs((prevQtaInit + prevQtaWd) - qtaBal) < 0.0001
      const qxAlreadySet = (prevQxInit + prevQxWd) > 0 && Math.abs((prevQxInit + prevQxWd) - qxBal) < 0.0001
      // ★ 사장님 2026-05-15 (2차) 지시: USDT 는 전부 출금 가능 (구분 없음)
      //   prev usdt_withdrawable 이 usdt_balance 와 일치할 때만 skip
      const usdtAlreadySet = Math.abs(prevUsdtWd - usdtBal) < 0.0001

      const allSet = (qtaBal === 0 || qtaAlreadySet) && (qxBal === 0 || qxAlreadySet) && usdtAlreadySet
      if (allSet) {
        skippedAlreadySet++
        continue
      }

      const row = {
        user_id: uid,
        email: u.email,
        name: u.name || '',
        before: {
          qta_balance: qtaBal, qx_balance: qxBal, usdt_balance: usdtBal,
          qta_initial: prevQtaInit, qta_withdrawable: prevQtaWd,
          qx_initial: prevQxInit, qx_withdrawable: prevQxWd,
          usdt_withdrawable: prevUsdtWd,
        },
        swap_net: { QTA: qtaNet, QX: qxNet, USDT: usdtNet },
        after: {
          qta_initial: qtaInit, qta_withdrawable: qtaWd,
          qx_initial: qxInit, qx_withdrawable: qxWd,
          usdt_withdrawable: usdtWd,
        },
      }
      plan.push(row)

      if (!dryRun) {
        await db.prepare(`UPDATE users SET 
          qta_initial = ?, 
          qx_initial = ?, 
          qta_withdrawable = ?, 
          qx_withdrawable = ?, 
          usdt_withdrawable = ? 
          WHERE id = ?`).bind(qtaInit, qxInit, qtaWd, qxWd, usdtWd, uid).run()
        executedCount++
      }
    }

    return c.json({
      success: true,
      mode: dryRun ? 'DRY_RUN' : 'EXECUTED',
      title: '출금 자격 source-tracking 마이그레이션 (영구 정책 2026-05-14)',
      generated_at_kst: new Date(Date.now() + 9*3600*1000).toISOString().replace('T',' ').slice(0,19),
      total_users: users.length,
      plan_rows: plan.length,
      executed_count: executedCount,
      skipped_already_set: skippedAlreadySet,
      formula: {
        QTA: 'withdrawable = max(0, swap_in - swap_out) / initial = max(0, balance - withdrawable)',
        QX:  'withdrawable = max(0, swap_in - swap_out) / initial = max(0, balance - withdrawable)',
        USDT: 'withdrawable = usdt_balance (전액 출금 가능 — 사장님 2026-05-15 2차 지시)',
        QKEY: '컬럼 분리 없음 (qkey_balance 전체가 출금 가능 — 데일리/매칭/추천 합산)',
      },
      plan,
      hint: dryRun ? '실행하려면 ?password=...&confirm=GO 추가' : '실행 완료',
    })
  } catch (error: any) {
    console.error('migrate-source-tracking error:', error)
    return c.json({ error: error?.message || String(error) }, 500)
  }
})

// ============================================
// 진단 — 스왑 거래내역 (qta_balance/qx_balance/qkey_balance 중 스왑으로 가감된 계정 보고)
// 영구룰: 회사 정책상 최초 지갑 전송된 QTA/QX 수량 외에, 스왑(swap_in / swap_out)으로 잔액 변화가 발생한 계정 식별
// 사용법: GET /api/diag/swap-balance-audit?password=...
// 순수 read-only — INSERT/UPDATE 0건
// ============================================
app.get('/api/diag/swap-balance-audit', async (c) => {
  try {
    const password = c.req.query('password') || ''
    if (password !== ADMIN_PW) return c.json({ error: 'Unauthorized' }, 401)
    const db = c.env.DB

    // STEP 1: 전 사용자 조회 (현재 잔액 4종)
    const usersRes = await db.prepare(`
      SELECT id, email, name, qta_balance, qx_balance, qkey_balance, usdt_balance
      FROM users
      ORDER BY id ASC
    `).all<any>()
    const users = usersRes.results || []

    // STEP 2: 전 사용자 스왑 내역 일괄 집계 (transactions 테이블)
    //   swap_in : 받은 코인 (+) — 양수로 저장
    //   swap_out: 보낸 코인 (-) — 음수로 저장 (정합성 룰)
    const swapRes = await db.prepare(`
      SELECT user_id, type, coin_type, COALESCE(SUM(amount),0) as sum_amount, COUNT(*) as cnt
      FROM transactions
      WHERE type IN ('swap_in','swap_out')
      GROUP BY user_id, type, coin_type
    `).all<any>()

    // user_id → coin_type → { in_sum, out_sum_abs, in_cnt, out_cnt }
    const swapMap: Record<number, Record<string, { in_sum: number; out_sum: number; in_cnt: number; out_cnt: number }>> = {}
    for (const r of (swapRes.results || [])) {
      const uid = Number(r.user_id)
      const coin = r.coin_type as string
      if (!swapMap[uid]) swapMap[uid] = {}
      if (!swapMap[uid][coin]) swapMap[uid][coin] = { in_sum: 0, out_sum: 0, in_cnt: 0, out_cnt: 0 }
      if (r.type === 'swap_in') {
        swapMap[uid][coin].in_sum = Number(r.sum_amount || 0)
        swapMap[uid][coin].in_cnt = Number(r.cnt || 0)
      } else {
        // swap_out 은 음수로 저장됨 → 절대값
        swapMap[uid][coin].out_sum = Math.abs(Number(r.sum_amount || 0))
        swapMap[uid][coin].out_cnt = Number(r.cnt || 0)
      }
    }

    // STEP 3: 각 사용자별 코인별 net 스왑 (in - out)
    //   QTA, QX, QKEY, USDT 각각에 대해 net 계산
    //   net > 0 → 스왑으로 잔액 증가 (그 만큼이 "스왑분" — 출금 가능 대상)
    //   net < 0 → 스왑으로 잔액 감소 (QKEY 가 보통 음수)
    const COINS = ['QTA', 'QX', 'QKEY', 'USDT']
    const accountReport: any[] = []
    for (const u of users) {
      const uid = Number(u.id)
      const sm = swapMap[uid] || {}
      const hasSwap = COINS.some(c => sm[c] && ((sm[c].in_sum || 0) > 0 || (sm[c].out_sum || 0) > 0))
      if (!hasSwap) continue  // 스왑 내역이 전혀 없는 계정 제외

      const coinDetail: Record<string, any> = {}
      for (const coin of COINS) {
        const s = sm[coin] || { in_sum: 0, out_sum: 0, in_cnt: 0, out_cnt: 0 }
        const net = s.in_sum - s.out_sum
        if (s.in_sum === 0 && s.out_sum === 0) continue
        coinDetail[coin] = {
          swap_in_total: s.in_sum,
          swap_in_count: s.in_cnt,
          swap_out_total: s.out_sum,
          swap_out_count: s.out_cnt,
          net: net,  // (+)면 스왑으로 늘어난 분 / (-)면 스왑으로 줄어든 분
        }
      }

      accountReport.push({
        user_id: uid,
        email: u.email || `u${uid}`,
        name: u.name || '',
        current_balance: {
          QTA: Number(u.qta_balance || 0),
          QX: Number(u.qx_balance || 0),
          QKEY: Number(u.qkey_balance || 0),
          USDT: Number(u.usdt_balance || 0),
        },
        swap_activity: coinDetail,
        // 회사 최초 지급분 추정 = 현재 잔액 - 스왑 net
        // (단, 데일리 배당으로 쌓인 QKEY 는 회사 최초 지급분이 아닌 매일 발생 → QKEY 는 별도 해석 필요)
        estimated_company_initial: {
          QTA: Number(u.qta_balance || 0) - ((coinDetail['QTA']?.net) || 0),
          QX: Number(u.qx_balance || 0) - ((coinDetail['QX']?.net) || 0),
        },
        estimated_swap_only: {
          QTA: (coinDetail['QTA']?.net) || 0,
          QX: (coinDetail['QX']?.net) || 0,
          USDT: (coinDetail['USDT']?.net) || 0,
        },
      })
    }

    // 정렬: QTA 또는 QX 스왑 net 절대값 큰 순
    accountReport.sort((a, b) => {
      const aSum = Math.abs(a.estimated_swap_only.QTA) + Math.abs(a.estimated_swap_only.QX) + Math.abs(a.estimated_swap_only.USDT)
      const bSum = Math.abs(b.estimated_swap_only.QTA) + Math.abs(b.estimated_swap_only.QX) + Math.abs(b.estimated_swap_only.USDT)
      return bSum - aSum
    })

    // 코인별 전체 합계
    const totals = {
      QTA: { swap_in: 0, swap_out: 0, net: 0 },
      QX:  { swap_in: 0, swap_out: 0, net: 0 },
      QKEY:{ swap_in: 0, swap_out: 0, net: 0 },
      USDT:{ swap_in: 0, swap_out: 0, net: 0 },
    }
    for (const r of accountReport) {
      for (const coin of COINS) {
        const d = r.swap_activity[coin]
        if (!d) continue
        totals[coin as keyof typeof totals].swap_in += d.swap_in_total
        totals[coin as keyof typeof totals].swap_out += d.swap_out_total
        totals[coin as keyof typeof totals].net += d.net
      }
    }

    return c.json({
      success: true,
      mode: 'READ_ONLY_DIAGNOSTIC',
      title: '스왑으로 가감된 계정 전수 보고 (회사 최초 지급분 외 스왑 활동 식별)',
      generated_at_kst: new Date(Date.now() + 9*3600*1000).toISOString().replace('T',' ').slice(0,19),
      total_users: users.length,
      users_with_swap_activity: accountReport.length,
      coin_totals: totals,
      accounts: accountReport,
      legend: {
        swap_in_total: '받은 누적 수량 (양수)',
        swap_out_total: '보낸 누적 수량 (절대값)',
        net: 'in - out (양수=스왑으로 늘어난 분 / 음수=스왑으로 줄어든 분)',
        estimated_company_initial: '현재잔액 - 스왑net (= 회사 최초 지급분으로 추정, QTA/QX 만)',
        estimated_swap_only: '스왑으로 가감된 net 만 (QTA/QX/USDT)',
      },
    })
  } catch (error: any) {
    console.error('swap-balance-audit error:', error)
    return c.json({ error: error?.message || String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ fix-solbat-display-align-3750: solbat 5/12~5/15 tx 화면 표시 영구룰 정렬 (balance 동시 정정) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   boss directive: "표시는 본인 750 / L1 1050 / L2 1950 으로 5/15까지 맞춰라 + 잔액도 무조건 같이"
//   ※ user_id=44 (solbat) 단일 회원 하드코딩, 다른 회원 영향 0
//
//   작업:
//     A) DELETE tx#3085 (5/12 L2 orphan 75, ref_id=None) → balance -75
//     B) INSERT 4건 tx (rd=5/14 L1 ref45, rd=5/14 L2 ref49, rd=5/15 L1 ref45, rd=5/15 L2 ref49)
//        각각 rr_id 매핑: rr#1779, rr#1780, rr#1781, rr#1782 (이미 rr 테이블에 존재, tx 만 누락)
//        → balance +150+75+150+75 = +450
//
//   순 잔액 변화: -75 + 450 = +375 (39,750 → 40,125)
//   최종 표시 결과: 5/12~5/15 매일 self=750 / L1=1050 / L2=1950 / total=3750 ✅
//
//   5중 검증:
//     - DELETE: tx#3085 actual: user_id=44, type='referral_reward', amount=75, ref_id=None, created_at='2026-05-12 10:24:27'
//     - INSERT 각 행: rr 존재 확인 + tx 미존재 확인 + referrer_id=44 + amount 일치 + level/desc 정확
//
//   경로:
//     DRY: POST /api/diag/fix-solbat-display-align-3750?key=ADMIN_PW&dry_run=1
//     GO:  POST /api/diag/fix-solbat-display-align-3750?key=ADMIN_PW&confirm=GO
app.post('/api/diag/fix-solbat-display-align-3750', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const dryRun = c.req.query('dry_run') === '1'
    const confirm = c.req.query('confirm') || ''

    const USER_ID = 44
    const user = await db.prepare(`SELECT id, email, name, qkey_balance FROM users WHERE id = ?`).bind(USER_ID).first<any>()
    if (!user || user.email !== 'solbat') {
      return c.json({ error: 'user_id=44 not solbat', user }, 400)
    }

    // ----- STEP A: DELETE tx#3085 (orphan L2 5/12 75) 5중 검증
    const deleteTx = await db.prepare(`
      SELECT id, user_id, type, amount, description, ref_id, created_at
      FROM transactions WHERE id = 3085
    `).first<any>()

    const deleteValidation = {
      tx_exists: !!deleteTx,
      user_id_match: deleteTx?.user_id === USER_ID,
      type_match: deleteTx?.type === 'referral_reward',
      amount_match: Number(deleteTx?.amount) === 75,
      ref_id_is_null: deleteTx?.ref_id === null,
      desc_contains_level2: (deleteTx?.description || '').includes('Level 2'),
      created_at_kst_512: (deleteTx?.created_at || '').startsWith('2026-05-12')
    }
    const deleteOK = Object.values(deleteValidation).every(v => v === true)

    // ----- STEP B: INSERT 4 rr tx (rr#1779, 1780, 1781, 1782)
    const insertPlan = [
      { rr_id: 1779, level: 1, amount: 150, referee_id: 45, rd: '2026-05-14', pd: '2026-05-15' },
      { rr_id: 1780, level: 2, amount: 75,  referee_id: 49, rd: '2026-05-14', pd: '2026-05-15' },
      { rr_id: 1781, level: 1, amount: 150, referee_id: 45, rd: '2026-05-15', pd: '2026-05-15' },
      { rr_id: 1782, level: 2, amount: 75,  referee_id: 49, rd: '2026-05-15', pd: '2026-05-15' }
    ]

    const insertValidations: any[] = []
    for (const p of insertPlan) {
      // rr 존재 검증
      const rr = await db.prepare(`
        SELECT id, referrer_id, referee_id, level, reward_amount, reward_date, paid_date
        FROM referral_rewards WHERE id = ?
      `).bind(p.rr_id).first<any>()

      // 동일 ref_id 의 tx 가 이미 있는지 확인
      const exists = await db.prepare(`
        SELECT id FROM transactions WHERE ref_id = ? AND type = 'referral_reward' AND user_id = ?
      `).bind(String(p.rr_id), USER_ID).first<any>()

      const v = {
        rr_exists: !!rr,
        rr_referrer_match: rr?.referrer_id === USER_ID,
        rr_referee_match: rr?.referee_id === p.referee_id,
        rr_level_match: rr?.level === p.level,
        rr_amount_match: Number(rr?.reward_amount) === p.amount,
        rr_rd_match: rr?.reward_date === p.rd,
        rr_pd_match: rr?.paid_date === p.pd,
        tx_not_yet_inserted: !exists
      }
      insertValidations.push({ plan: p, rr, validation: v, ok: Object.values(v).every(x => x === true) })
    }

    const allInsertOK = insertValidations.every(v => v.ok)
    const totalDeductForDelete = deleteOK ? 75 : 0
    const totalAddForInsert = insertPlan.reduce((s, p) => s + p.amount, 0)
    const netBalanceDelta = -totalDeductForDelete + totalAddForInsert

    const summary = {
      action: 'fix-solbat-display-align-3750',
      user_id: USER_ID, email: user.email,
      qkey_balance_before: user.qkey_balance,
      qkey_balance_after_planned: Number(user.qkey_balance) + netBalanceDelta,
      delete_count: deleteOK ? 1 : 0,
      delete_tx_id: 3085,
      delete_amount: 75,
      insert_count: insertPlan.length,
      insert_total_amount: totalAddForInsert,
      net_balance_delta: netBalanceDelta
    }

    if (dryRun || confirm !== 'GO') {
      return c.json({
        ok: true,
        mode: 'DRY_RUN',
        message: '실제 실행은 confirm=GO 추가',
        delete_validation: deleteValidation,
        delete_ok: deleteOK,
        delete_tx_actual: deleteTx,
        insert_validations: insertValidations,
        all_insert_ok: allInsertOK,
        summary,
        proceed_safe: deleteOK && allInsertOK
      })
    }

    if (!deleteOK || !allInsertOK) {
      return c.json({
        ok: false,
        mode: 'EXECUTE_BLOCKED',
        message: '5중 검증 실패 — 실행 중단',
        delete_validation: deleteValidation,
        insert_validations: insertValidations
      }, 400)
    }

    // EXECUTE
    const executed: any[] = []
    const errors: any[] = []

    // STEP A: DELETE tx#3085
    try {
      await db.prepare(`DELETE FROM transactions WHERE id = 3085 AND user_id = ?`).bind(USER_ID).run()
      await db.prepare(`UPDATE users SET qkey_balance = qkey_balance - 75 WHERE id = ?`).bind(USER_ID).run()
      executed.push({ step: 'A_DELETE', tx_id: 3085, balance_delta: -75 })
    } catch (e) {
      errors.push({ step: 'A_DELETE', error: String(e) })
    }

    // STEP B: INSERT 4 tx + balance +amount
    for (const p of insertPlan) {
      try {
        // created_at: KST p.pd 의 08:00 = UTC p.pd-1day 23:00... 사장님 표시 영구룰 따라 KST p.rd 화면에 나타나야 함
        // → tx.created_at(UTC) = p.rd 의 KST 08:00 (=UTC 23:00 of (rd-1))
        //   p.rd='2026-05-14' → KST 2026-05-14 08:00 = UTC 2026-05-13 23:00
        // 단순화: KST 08:00:00 일관 표시를 위해 SQL datetime 사용
        const kstHour = '08:00:00'
        const txCreatedAtUtc = await db.prepare(`SELECT datetime(?||' '||?, '-9 hours') AS u`).bind(p.rd, kstHour).first<any>()
        const createdAt = txCreatedAtUtc?.u || `${p.rd} ${kstHour}`
        const desc = `추천 보너스 (Level ${p.level})`

        await db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id, created_at)
          VALUES (?, 'referral_reward', 'qkey', ?, ?, ?, ?)
        `).bind(USER_ID, p.amount, desc, String(p.rr_id), createdAt).run()

        await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(p.amount, USER_ID).run()

        executed.push({ step: 'B_INSERT', rr_id: p.rr_id, amount: p.amount, level: p.level, rd: p.rd, created_at: createdAt, balance_delta: p.amount })
      } catch (e) {
        errors.push({ step: 'B_INSERT', rr_id: p.rr_id, error: String(e) })
      }
    }

    const userAfter = await db.prepare(`SELECT qkey_balance FROM users WHERE id = ?`).bind(USER_ID).first<any>()

    return c.json({
      ok: errors.length === 0,
      mode: 'EXECUTED',
      qkey_balance_before: user.qkey_balance,
      qkey_balance_after: userAfter?.qkey_balance,
      net_balance_delta: netBalanceDelta,
      executed,
      errors,
      summary
    })
  } catch (error) {
    console.error('fix-solbat-display-align-3750 error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ fix-solbat-clean-slate-3750: solbat 5/12~5/18 일일배당+추천수당 tx 전부 삭제 후 영구룰대로 재기록 ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   boss directive: "방법 1로 가" (5/12~5/18 일일/추천 tx 전부 삭제 + 5/12~5/15 영구룰대로 60건 재기록)
//
//   STEP A — DELETE 73건:
//     - user_id=44 (solbat)
//     - tx WHERE type IN ('daily_qkey','referral_reward')
//     - date(tx.created_at, '+9 hours') BETWEEN '2026-05-12' AND '2026-05-18'
//     - balance -= sum(amount) (18,075)
//
//   STEP B — INSERT 60건 (영구룰: 매일 self 750 + L1 1050 + L2 1950 = 3,750):
//     - 4일 × (1 daily + 7 L1 + 7 L2) = 60건
//     - 5/13 의 referee_id+level+amount 매핑을 표준으로 적용:
//         L1 (7명, 150씩):  ref=45, 45, 48, 50, 52, 54, 89
//         L2 (7명, 75 또는 1500): ref=46(75), 49(75), 49(75), 73(75), 76(1500), 90(75), 93(75)
//     - tx.created_at = KST rd 08:00 (= UTC rd-day 23:00)
//     - ref_id = null (재기록이므로 신규 rr 만들지 않음 — 단순 표시용)
//     - balance += 15,000 (4 × 3,750)
//
//   순 잔액 변화: -18,075 + 15,000 = -3,075 (39,750 → 36,675)
//
//   경로:
//     DRY: POST /api/diag/fix-solbat-clean-slate-3750?key=ADMIN_PW&dry_run=1
//     GO:  POST /api/diag/fix-solbat-clean-slate-3750?key=ADMIN_PW&confirm=GO
app.post('/api/diag/fix-solbat-clean-slate-3750', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB
    const dryRun = c.req.query('dry_run') === '1'
    const confirm = c.req.query('confirm') || ''

    const USER_ID = 44
    const user = await db.prepare(`SELECT id, email, name, qkey_balance FROM users WHERE id = ?`).bind(USER_ID).first<any>()
    if (!user || user.email !== 'solbat') {
      return c.json({ error: 'user not solbat', user }, 400)
    }

    // ----- STEP A: DELETE 대상 list
    const deleteTargets = await db.prepare(`
      SELECT id, type, amount, description, ref_id,
             datetime(created_at, '+9 hours') AS created_at_kst,
             created_at AS created_at_utc
      FROM transactions
      WHERE user_id = ?
        AND type IN ('daily_qkey', 'referral_reward')
        AND date(created_at, '+9 hours') BETWEEN '2026-05-12' AND '2026-05-18'
      ORDER BY id ASC
    `).bind(USER_ID).all()

    const deleteList = deleteTargets.results as any[]
    const totalDeleteAmount = deleteList.reduce((s, t) => s + Number(t.amount), 0)

    // 5중 검증 (집계 레벨)
    const deleteValidation = {
      count_in_range: deleteList.length,
      all_valid_types: deleteList.every(t => t.type === 'daily_qkey' || t.type === 'referral_reward'),
      all_in_date_range: deleteList.every(t => {
        const d = (t.created_at_kst || '').slice(0, 10)
        return d >= '2026-05-12' && d <= '2026-05-18'
      }),
      all_user_id_44: true, // 위에서 user_id=? 로 필터됨
      total_amount: totalDeleteAmount
    }
    const deleteOK = deleteList.length === 73 && totalDeleteAmount === 18075

    // ----- STEP B: INSERT 60건 plan (4일 × 15건)
    const standardMap = [
      { kind: 'self', level: 0, amount: 750, referee_id: null },
      { kind: 'l1',   level: 1, amount: 150, referee_id: 45 },
      { kind: 'l1',   level: 1, amount: 150, referee_id: 45 },
      { kind: 'l1',   level: 1, amount: 150, referee_id: 48 },
      { kind: 'l1',   level: 1, amount: 150, referee_id: 50 },
      { kind: 'l1',   level: 1, amount: 150, referee_id: 52 },
      { kind: 'l1',   level: 1, amount: 150, referee_id: 54 },
      { kind: 'l1',   level: 1, amount: 150, referee_id: 89 },
      { kind: 'l2',   level: 2, amount: 75,  referee_id: 46 },
      { kind: 'l2',   level: 2, amount: 75,  referee_id: 49 },
      { kind: 'l2',   level: 2, amount: 75,  referee_id: 49 },
      { kind: 'l2',   level: 2, amount: 75,  referee_id: 73 },
      { kind: 'l2',   level: 2, amount: 1500, referee_id: 76 },
      { kind: 'l2',   level: 2, amount: 75,  referee_id: 90 },
      { kind: 'l2',   level: 2, amount: 75,  referee_id: 93 }
    ]

    const dates = ['2026-05-12', '2026-05-13', '2026-05-14', '2026-05-15']
    const insertPlan: any[] = []
    for (const rd of dates) {
      // KST rd 08:00 = UTC (rd) 23:00 of previous day; 가장 단순한 SQL 처리는 datetime 매크로
      // 더 단순: tx.created_at = rd + ' -1 day 23:00:00' ... 복잡하므로 KST 08:00 명세로 SQL 변환
      let secOffset = 0
      for (const m of standardMap) {
        secOffset += 1
        const kstHHmm = '08:00:' + String(secOffset).padStart(2, '0')
        insertPlan.push({
          rd,
          kst_created_at: `${rd} ${kstHHmm}`,
          type: m.kind === 'self' ? 'daily_qkey' : 'referral_reward',
          amount: m.amount,
          level: m.level,
          referee_id: m.referee_id,
          description: m.kind === 'self' ? '일일 배당 (QKEY)' : `추천 보너스 (Level ${m.level})`
        })
      }
    }

    const totalInsertAmount = insertPlan.reduce((s, p) => s + Number(p.amount), 0)
    const netBalanceDelta = -totalDeleteAmount + totalInsertAmount
    const plannedFinalBalance = Number(user.qkey_balance) + netBalanceDelta

    const summary = {
      action: 'fix-solbat-clean-slate-3750',
      user_id: USER_ID, email: user.email,
      qkey_balance_before: user.qkey_balance,
      qkey_balance_after_planned: plannedFinalBalance,
      delete_count: deleteList.length,
      delete_total_amount: totalDeleteAmount,
      insert_count: insertPlan.length,
      insert_total_amount: totalInsertAmount,
      net_balance_delta: netBalanceDelta
    }

    if (dryRun || confirm !== 'GO') {
      return c.json({
        ok: true,
        mode: 'DRY_RUN',
        message: '실제 실행은 confirm=GO 추가',
        delete_validation: deleteValidation,
        delete_ok: deleteOK,
        delete_targets_sample: deleteList.slice(0, 10),
        delete_targets_count: deleteList.length,
        insert_plan_sample: insertPlan.slice(0, 15),
        insert_plan_count: insertPlan.length,
        summary,
        proceed_safe: deleteOK
      })
    }

    if (!deleteOK) {
      return c.json({
        ok: false, mode: 'EXECUTE_BLOCKED',
        message: '검증 실패: delete count or total mismatch',
        delete_validation: deleteValidation
      }, 400)
    }

    // EXECUTE
    const executed: any[] = []
    const errors: any[] = []

    // STEP A: 일괄 DELETE
    try {
      const deleteResult = await db.prepare(`
        DELETE FROM transactions
        WHERE user_id = ?
          AND type IN ('daily_qkey', 'referral_reward')
          AND date(created_at, '+9 hours') BETWEEN '2026-05-12' AND '2026-05-18'
      `).bind(USER_ID).run()
      await db.prepare(`UPDATE users SET qkey_balance = qkey_balance - ? WHERE id = ?`).bind(totalDeleteAmount, USER_ID).run()
      executed.push({ step: 'A_DELETE_ALL', deleted_count: deleteList.length, balance_delta: -totalDeleteAmount })
    } catch (e) {
      errors.push({ step: 'A_DELETE_ALL', error: String(e) })
      return c.json({ ok: false, mode: 'EXECUTE_PARTIAL', executed, errors }, 500)
    }

    // STEP B: INSERT 60건 + balance += 15000
    for (const p of insertPlan) {
      try {
        // created_at(UTC) = KST - 9h
        const utcRow = await db.prepare(`SELECT datetime(?, '-9 hours') AS u`).bind(p.kst_created_at).first<any>()
        const createdAt = utcRow?.u || p.kst_created_at
        await db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id, created_at)
          VALUES (?, ?, 'qkey', ?, ?, NULL, ?)
        `).bind(USER_ID, p.type, p.amount, p.description, createdAt).run()
        executed.push({ step: 'B_INSERT', rd: p.rd, type: p.type, amount: p.amount, kst_created_at: p.kst_created_at, utc_created_at: createdAt })
      } catch (e) {
        errors.push({ step: 'B_INSERT', plan: p, error: String(e) })
      }
    }
    // balance += totalInsertAmount
    try {
      await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(totalInsertAmount, USER_ID).run()
      executed.push({ step: 'B_BALANCE_ADD', delta: totalInsertAmount })
    } catch (e) {
      errors.push({ step: 'B_BALANCE_ADD', error: String(e) })
    }

    const userAfter = await db.prepare(`SELECT qkey_balance FROM users WHERE id = ?`).bind(USER_ID).first<any>()

    // 재검증: tx 표시 영구룰 확인
    const verifyRows = await db.prepare(`
      SELECT date(created_at, '+9 hours') AS rd_kst, type, description, SUM(amount) AS sum_amt, COUNT(*) AS cnt
      FROM transactions
      WHERE user_id = ?
        AND type IN ('daily_qkey','referral_reward')
        AND date(created_at, '+9 hours') BETWEEN '2026-05-12' AND '2026-05-18'
      GROUP BY rd_kst, type, description
      ORDER BY rd_kst, type, description
    `).bind(USER_ID).all()

    return c.json({
      ok: errors.length === 0,
      mode: 'EXECUTED',
      qkey_balance_before: user.qkey_balance,
      qkey_balance_after: userAfter?.qkey_balance,
      net_balance_delta: netBalanceDelta,
      executed_count: executed.length,
      errors_count: errors.length,
      errors,
      verification_tx_by_date: verifyRows.results,
      summary
    })
  } catch (error) {
    console.error('fix-solbat-clean-slate-3750 error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
// ★★★ admin-block-today-cron: 오늘(KST) 자동 cron 즉시 차단 (daily_cron_lock manual_admin INSERT) ★★★
// ★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★★
//   boss directive (2026-05-18):
//     "전부 오늘은 절대로 돌리지말것! 수동으로 진행 예정임"
//
//   동작:
//     1) daily_cron_lock 에 (today_kst, 'manual_admin', note='사장님 18일 절대 차단 명령') INSERT
//     2) 이미 lock 있으면 그대로 유지 (idempotent)
//     3) 이후 KST 08:00 GitHub Actions cron 호출 시 existingLock.source='manual_admin' ne incoming='cron_auto'
//        → 즉시 423 Locked 반환, 배당 처리 0건
//     4) 사장님 수동 실행 시점에 ?force=GO&unlock=GO 로 해제 가능
//
//   경로: POST /api/diag/admin-block-today-cron?key=ADMIN_PW&confirm=GO
//        (날짜 override: ?date=YYYY-MM-DD)
app.post('/api/diag/admin-block-today-cron', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const confirm = c.req.query('confirm') || ''
    if (confirm !== 'GO') return c.json({ error: 'confirm=GO 필수' }, 400)

    const db = c.env.DB
    const now = new Date()
    const kstNow = new Date(now.getTime() + 9 * 3600 * 1000)
    const todayKst = c.req.query('date') || kstNow.toISOString().slice(0, 10)
    const note = c.req.query('note') || '사장님 절대 차단 명령 (수동 진행 예정)'

    // 테이블 보장
    try {
      await db.prepare(`
        CREATE TABLE IF NOT EXISTS daily_cron_lock (
          lock_date        TEXT PRIMARY KEY,
          source           TEXT NOT NULL,
          locked_at        TEXT NOT NULL DEFAULT (datetime('now','+9 hours')),
          locked_by        TEXT,
          note             TEXT,
          last_finished_at TEXT
        )
      `).run()
    } catch(e) {}

    // 기존 lock 확인
    const existing = await db.prepare(`
      SELECT lock_date, source, locked_at, locked_by, note, last_finished_at
      FROM daily_cron_lock WHERE lock_date = ?
    `).bind(todayKst).first<any>()

    if (existing) {
      return c.json({
        ok: true,
        mode: 'ALREADY_LOCKED',
        message: `${todayKst} 는 이미 lock 되어 있습니다 (source=${existing.source}).`,
        lock: existing
      })
    }

    // 신규 lock INSERT — manual_admin 소스로 → cron_auto 호출 시 자동 차단
    await db.prepare(`
      INSERT INTO daily_cron_lock (lock_date, source, locked_by, note)
      VALUES (?, 'manual_admin', 'admin-direct-block', ?)
    `).bind(todayKst, note).run()

    const lock = await db.prepare(`
      SELECT lock_date, source, locked_at, locked_by, note
      FROM daily_cron_lock WHERE lock_date = ?
    `).bind(todayKst).first<any>()

    // daily_rewards 가 이미 생성된 게 있는지 추가 확인 (안심용)
    const drCount = await db.prepare(`
      SELECT COUNT(*) AS c, COALESCE(SUM(usdt_amount),0) AS total
      FROM daily_rewards WHERE reward_date = ?
    `).bind(todayKst).first<any>()

    const txCount = await db.prepare(`
      SELECT COUNT(*) AS c, COALESCE(SUM(amount),0) AS total
      FROM transactions
      WHERE type = 'daily_qkey' AND date(created_at, '+9 hours') = ?
    `).bind(todayKst).first<any>()

    return c.json({
      ok: true,
      mode: 'LOCKED',
      message: `${todayKst} 자동 cron 차단 완료. KST 08:00 GitHub Actions 호출 시 즉시 423 Locked 반환됩니다.`,
      lock,
      verification: {
        daily_rewards_with_today_rd: drCount,
        daily_qkey_tx_today_kst: txCount,
        note: '둘 다 0 이어야 정상 (아직 미실행)'
      },
      unlock_hint: '나중에 수동 진행 시: POST /api/admin/rewards/manual-daily-trigger?confirm=GO (Bearer 어드민 토큰 필요). 단, lock 이 manual_admin 이므로 그냥 통과됨 (같은 source).'
    })
  } catch (error) {
    console.error('admin-block-today-cron error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ─────────────────────────────────────────────────────────────────
// /api/diag/fix-solbat-cleanup-duplicates
// 사장님 명령 (2026-05-18): 솔밧 (u#44) 중복지급 정리
//   1) transactions WHERE user_id=44 AND description LIKE '%clean-slate%' → DELETE (120건, 33,000 QKEY)
//   2) referral_rewards WHERE referrer_id=44 AND created_at >= '2026-05-17 21:00:00' UTC → DELETE (18건)
//   3) qkey_balance 를 잔여 transactions 합계로 재계산
//   4) (옵션) transactions.created_at 공백→T 치환 (Safari Invalid Date 수정)
// DRY:  POST /api/diag/fix-solbat-cleanup-duplicates?key=ADMIN_PW&dry_run=1
// GO:   POST /api/diag/fix-solbat-cleanup-duplicates?key=ADMIN_PW&confirm=GO
// ─────────────────────────────────────────────────────────────────
app.post('/api/diag/fix-solbat-cleanup-duplicates', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const dryRun = c.req.query('dry_run') === '1'
    const confirm = c.req.query('confirm') || ''
    if (!dryRun && confirm !== 'GO') return c.json({ error: 'confirm=GO 또는 dry_run=1 필요' }, 400)

    const db = c.env.DB
    const uid = 44

    // === 1. 삭제 대상 미리 조회 ===
    const txTargets = await db.prepare(`
      SELECT id, type, amount, description, created_at
      FROM transactions
      WHERE user_id = ? AND description LIKE '%clean-slate%'
      ORDER BY id
    `).bind(uid).all<any>()
    const txList = (txTargets.results || []) as any[]
    const txSum = txList.reduce((s, t) => s + Number(t.amount || 0), 0)

    const rrTargets = await db.prepare(`
      SELECT id, referee_id, level, reward_amount, reward_date, paid_date, created_at
      FROM referral_rewards
      WHERE referrer_id = ? AND created_at >= '2026-05-17 21:00:00'
      ORDER BY id
    `).bind(uid).all<any>()
    const rrList = (rrTargets.results || []) as any[]
    const rrSum = rrList.reduce((s, r) => s + Number(r.reward_amount || 0), 0)

    // === 현재 잔고 + 재계산 예상 ===
    const userRow = await db.prepare(`SELECT qkey_balance FROM users WHERE id = ?`).bind(uid).first<any>()
    const currentBalance = Number(userRow?.qkey_balance || 0)

    // 삭제 후 잔여 tx 합계 = 재계산할 잔고
    const txAllAfter = await db.prepare(`
      SELECT COALESCE(SUM(amount),0) AS total
      FROM transactions
      WHERE user_id = ? AND coin_type = 'QKEY'
        AND id NOT IN (SELECT id FROM transactions WHERE user_id = ? AND description LIKE '%clean-slate%')
    `).bind(uid, uid).first<any>()
    const newBalance = Number(txAllAfter?.total || 0)

    if (dryRun) {
      return c.json({
        ok: true,
        mode: 'DRY_RUN',
        targets: {
          transactions_delete: {
            count: txList.length,
            sum_qkey: txSum,
            id_range: txList.length > 0 ? `${txList[0].id} ~ ${txList[txList.length-1].id}` : null,
            sample_descriptions: Array.from(new Set(txList.map(t => t.description))).slice(0, 10)
          },
          referral_rewards_delete: {
            count: rrList.length,
            sum_qkey: rrSum,
            id_range: rrList.length > 0 ? `${rrList[0].id} ~ ${rrList[rrList.length-1].id}` : null,
            items: rrList
          }
        },
        balance: {
          current: currentBalance,
          new_after_delete: newBalance,
          diff: newBalance - currentBalance
        }
      })
    }

    // === EXECUTE ===
    const results: any = {
      tx_deleted: 0,
      rr_deleted: 0,
      created_at_fixed: 0,
      balance_before: currentBalance,
      balance_after: 0
    }

    // (1) transactions DELETE
    const txDel = await db.prepare(`
      DELETE FROM transactions
      WHERE user_id = ? AND description LIKE '%clean-slate%'
    `).bind(uid).run()
    results.tx_deleted = txDel.meta?.changes || 0

    // (2) referral_rewards DELETE
    const rrDel = await db.prepare(`
      DELETE FROM referral_rewards
      WHERE referrer_id = ? AND created_at >= '2026-05-17 21:00:00'
    `).bind(uid).run()
    results.rr_deleted = rrDel.meta?.changes || 0

    // (3) 잔고 재계산 — 잔여 QKEY transactions 합으로 UPDATE
    const finalSum = await db.prepare(`
      SELECT COALESCE(SUM(amount),0) AS total
      FROM transactions
      WHERE user_id = ? AND coin_type = 'QKEY'
    `).bind(uid).first<any>()
    const finalBalance = Number(finalSum?.total || 0)

    await db.prepare(`UPDATE users SET qkey_balance = ? WHERE id = ?`).bind(finalBalance, uid).run()
    results.balance_after = finalBalance

    // (4) created_at 공백 → T 치환 (Safari Invalid Date 수정)
    // SQLite REPLACE 사용: "2026-05-18 06:57:44" → "2026-05-18T06:57:44"
    const fixDt = await db.prepare(`
      UPDATE transactions
      SET created_at = REPLACE(created_at, ' ', 'T')
      WHERE user_id = ?
        AND created_at IS NOT NULL
        AND created_at LIKE '____-__-__ __:__:__%'
    `).bind(uid).run()
    results.created_at_fixed = fixDt.meta?.changes || 0

    return c.json({
      ok: true,
      mode: 'EXECUTED',
      action: 'fix-solbat-cleanup-duplicates',
      user_id: uid,
      results,
      message: `중복 tx 120건 + rr 18건 삭제 완료, 잔고 ${currentBalance} → ${finalBalance} 재계산, created_at ${results.created_at_fixed}건 ISO 형식 수정.`
    })
  } catch (error) {
    console.error('fix-solbat-cleanup-duplicates error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ─────────────────────────────────────────────────────────────────
// /api/diag/fix-all-cleanup-duplicates
// 사장님 명령 (2026-05-18): 솔밧과 같은 케이스의 모든 계정 일괄 정리
//   1) DRY-RUN: 영향받은 user_id 전수 조사
//   2) EXECUTE:
//      A. transactions WHERE description LIKE '%clean-slate%' → DELETE (전 계정)
//      B. referral_rewards WHERE created_at >= '2026-05-17 21:00:00' → DELETE (전 계정)
//      C. 영향받은 모든 사용자의 qkey_balance 를 잔여 QKEY tx 합계로 재계산
//      D. 영향받은 모든 사용자의 transactions.created_at 공백→T 치환
// DRY:  POST /api/diag/fix-all-cleanup-duplicates?key=ADMIN_PW&dry_run=1
// GO:   POST /api/diag/fix-all-cleanup-duplicates?key=ADMIN_PW&confirm=GO
// ─────────────────────────────────────────────────────────────────
app.post('/api/diag/fix-all-cleanup-duplicates', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const dryRun = c.req.query('dry_run') === '1'
    const confirm = c.req.query('confirm') || ''
    if (!dryRun && confirm !== 'GO') return c.json({ error: 'confirm=GO 또는 dry_run=1 필요' }, 400)

    const db = c.env.DB

    // === A. clean-slate tx 영향 user 조사 ===
    const txAffected = await db.prepare(`
      SELECT user_id,
             COUNT(*) AS cnt,
             COALESCE(SUM(amount),0) AS sum_amt,
             MIN(id) AS min_id,
             MAX(id) AS max_id
      FROM transactions
      WHERE description LIKE '%clean-slate%'
      GROUP BY user_id
      ORDER BY user_id
    `).all<any>()
    const txGroups = (txAffected.results || []) as any[]

    // === B. 5/18 작업 rr 영향 user 조사 (referrer_id 와 referee_id 둘 다) ===
    const rrAffectedReferrer = await db.prepare(`
      SELECT referrer_id AS user_id, COUNT(*) AS cnt, COALESCE(SUM(reward_amount),0) AS sum_amt
      FROM referral_rewards
      WHERE created_at >= '2026-05-17 21:00:00'
      GROUP BY referrer_id
      ORDER BY referrer_id
    `).all<any>()
    const rrGroups = (rrAffectedReferrer.results || []) as any[]

    // 합쳐서 영향받은 user_id 집합
    const affectedUserSet = new Set<number>()
    for (const g of txGroups) affectedUserSet.add(Number(g.user_id))
    for (const g of rrGroups) affectedUserSet.add(Number(g.user_id))
    const affectedUsers = Array.from(affectedUserSet).sort((a,b) => a-b)

    // user 정보
    const userDetails: any[] = []
    if (affectedUsers.length > 0) {
      const placeholders = affectedUsers.map(() => '?').join(',')
      const rows = await db.prepare(`
        SELECT id, email, name, qkey_balance
        FROM users
        WHERE id IN (${placeholders})
        ORDER BY id
      `).bind(...affectedUsers).all<any>()
      userDetails.push(...((rows.results || []) as any[]))
    }

    // user별 매트릭스 통합
    const txMap = new Map<number, any>()
    for (const g of txGroups) txMap.set(Number(g.user_id), g)
    const rrMap = new Map<number, any>()
    for (const g of rrGroups) rrMap.set(Number(g.user_id), g)

    const matrix = userDetails.map(u => {
      const tx = txMap.get(Number(u.id))
      const rr = rrMap.get(Number(u.id))
      return {
        user_id: u.id,
        email: u.email,
        name: u.name,
        current_balance: u.qkey_balance,
        tx_clean_slate_count: tx ? Number(tx.cnt) : 0,
        tx_clean_slate_sum: tx ? Number(tx.sum_amt) : 0,
        rr_late_count: rr ? Number(rr.cnt) : 0,
        rr_late_sum: rr ? Number(rr.sum_amt) : 0,
        expected_balance_after: Number(u.qkey_balance) - (tx ? Number(tx.sum_amt) : 0)
      }
    })

    const totalTxCount = txGroups.reduce((s, g) => s + Number(g.cnt), 0)
    const totalTxSum = txGroups.reduce((s, g) => s + Number(g.sum_amt), 0)
    const totalRrCount = rrGroups.reduce((s, g) => s + Number(g.cnt), 0)
    const totalRrSum = rrGroups.reduce((s, g) => s + Number(g.sum_amt), 0)

    if (dryRun) {
      return c.json({
        ok: true,
        mode: 'DRY_RUN',
        summary: {
          affected_user_count: affectedUsers.length,
          tx_clean_slate_total_count: totalTxCount,
          tx_clean_slate_total_qkey: totalTxSum,
          rr_late_total_count: totalRrCount,
          rr_late_total_qkey: totalRrSum
        },
        matrix
      })
    }

    // === EXECUTE ===
    const results: any = {
      affected_users: affectedUsers.length,
      tx_deleted: 0,
      rr_deleted: 0,
      balance_updated: 0,
      created_at_fixed: 0,
      user_changes: [] as any[]
    }

    // (A) transactions DELETE (전체)
    const txDel = await db.prepare(`
      DELETE FROM transactions
      WHERE description LIKE '%clean-slate%'
    `).run()
    results.tx_deleted = txDel.meta?.changes || 0

    // (B) referral_rewards DELETE (전체)
    const rrDel = await db.prepare(`
      DELETE FROM referral_rewards
      WHERE created_at >= '2026-05-17 21:00:00'
    `).run()
    results.rr_deleted = rrDel.meta?.changes || 0

    // (C) 영향받은 모든 사용자의 잔고 재계산 + (D) created_at 형식 수정
    for (const uid of affectedUsers) {
      // 잔고 재계산
      const finalSum = await db.prepare(`
        SELECT COALESCE(SUM(amount),0) AS total
        FROM transactions
        WHERE user_id = ? AND coin_type = 'QKEY'
      `).bind(uid).first<any>()
      const finalBalance = Number(finalSum?.total || 0)

      const before = userDetails.find(u => Number(u.id) === uid)
      const beforeBal = Number(before?.qkey_balance || 0)

      await db.prepare(`UPDATE users SET qkey_balance = ? WHERE id = ?`).bind(finalBalance, uid).run()
      results.balance_updated++

      // created_at 공백→T 치환
      const fixDt = await db.prepare(`
        UPDATE transactions
        SET created_at = REPLACE(created_at, ' ', 'T')
        WHERE user_id = ?
          AND created_at IS NOT NULL
          AND created_at LIKE '____-__-__ __:__:__%'
      `).bind(uid).run()
      const dtFixed = fixDt.meta?.changes || 0
      results.created_at_fixed += dtFixed

      results.user_changes.push({
        user_id: uid,
        email: before?.email,
        name: before?.name,
        balance_before: beforeBal,
        balance_after: finalBalance,
        balance_diff: finalBalance - beforeBal,
        created_at_fixed: dtFixed
      })
    }

    return c.json({
      ok: true,
      mode: 'EXECUTED',
      action: 'fix-all-cleanup-duplicates',
      results,
      message: `${affectedUsers.length}명 정리 완료: tx ${results.tx_deleted}건, rr ${results.rr_deleted}건, balance ${results.balance_updated}건, created_at ${results.created_at_fixed}건.`
    })
  } catch (error) {
    console.error('fix-all-cleanup-duplicates error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ─────────────────────────────────────────────────────────────────
// /api/diag/scan-missing-tx-from-dr-rr
// 사장님 명령 (2026-05-18): 김용선 같은 케이스 — dr/rr 테이블엔 있는데 tx 가 누락된 사용자 전수조사
// READ-ONLY 진단 (수정 안 함)
// GET /api/diag/scan-missing-tx-from-dr-rr?key=ADMIN_PW
// ─────────────────────────────────────────────────────────────────
app.get('/api/diag/scan-missing-tx-from-dr-rr', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = c.env.DB

    // 전 사용자별 dr/rr/tx 합 집계
    const rows = await db.prepare(`
      SELECT
        u.id AS user_id,
        u.email,
        u.name,
        u.qkey_balance,
        COALESCE(dr.dr_sum, 0)  AS dr_sum,
        COALESCE(dr.dr_cnt, 0)  AS dr_cnt,
        COALESCE(rr.rr_sum, 0)  AS rr_sum,
        COALESCE(rr.rr_cnt, 0)  AS rr_cnt,
        COALESCE(tx.tx_daily_sum, 0)    AS tx_daily_sum,
        COALESCE(tx.tx_daily_cnt, 0)    AS tx_daily_cnt,
        COALESCE(tx.tx_referral_sum, 0) AS tx_referral_sum,
        COALESCE(tx.tx_referral_cnt, 0) AS tx_referral_cnt,
        COALESCE(tx.tx_total_qkey, 0)   AS tx_total_qkey
      FROM users u
      LEFT JOIN (
        SELECT user_id, SUM(usdt_amount) AS dr_sum, COUNT(*) AS dr_cnt
        FROM daily_rewards GROUP BY user_id
      ) dr ON dr.user_id = u.id
      LEFT JOIN (
        SELECT referrer_id AS user_id, SUM(reward_amount) AS rr_sum, COUNT(*) AS rr_cnt
        FROM referral_rewards GROUP BY referrer_id
      ) rr ON rr.user_id = u.id
      LEFT JOIN (
        SELECT user_id,
          SUM(CASE WHEN type='daily_qkey'      AND coin_type='QKEY' THEN amount ELSE 0 END) AS tx_daily_sum,
          SUM(CASE WHEN type='daily_qkey'      AND coin_type='QKEY' THEN 1     ELSE 0 END) AS tx_daily_cnt,
          SUM(CASE WHEN type='referral_reward' AND coin_type='QKEY' THEN amount ELSE 0 END) AS tx_referral_sum,
          SUM(CASE WHEN type='referral_reward' AND coin_type='QKEY' THEN 1     ELSE 0 END) AS tx_referral_cnt,
          SUM(CASE WHEN coin_type='QKEY' THEN amount ELSE 0 END) AS tx_total_qkey
        FROM transactions GROUP BY user_id
      ) tx ON tx.user_id = u.id
      WHERE COALESCE(dr.dr_sum,0) > 0 OR COALESCE(rr.rr_sum,0) > 0
      ORDER BY u.id
    `).all<any>()

    const items = (rows.results || []) as any[]

    // 누락 진단:
    //   dr_missing: dr_sum > tx_daily_sum
    //   rr_missing: rr_sum > tx_referral_sum
    //   총 미지급 = (dr_sum - tx_daily_sum) + (rr_sum - tx_referral_sum)
    const affected: any[] = []
    for (const r of items) {
      const drDiff = Number(r.dr_sum || 0) - Number(r.tx_daily_sum || 0)
      const rrDiff = Number(r.rr_sum || 0) - Number(r.tx_referral_sum || 0)
      if (drDiff > 0 || rrDiff > 0) {
        affected.push({
          user_id: r.user_id,
          email: r.email,
          name: r.name,
          current_balance: Number(r.qkey_balance),
          dr_sum: Number(r.dr_sum),
          dr_cnt: Number(r.dr_cnt),
          tx_daily_sum: Number(r.tx_daily_sum),
          tx_daily_cnt: Number(r.tx_daily_cnt),
          rr_sum: Number(r.rr_sum),
          rr_cnt: Number(r.rr_cnt),
          tx_referral_sum: Number(r.tx_referral_sum),
          tx_referral_cnt: Number(r.tx_referral_cnt),
          dr_missing_qkey: drDiff,
          rr_missing_qkey: rrDiff,
          total_missing_qkey: drDiff + rrDiff
        })
      }
    }

    const totalMissing = affected.reduce((s, a) => s + a.total_missing_qkey, 0)
    return c.json({
      ok: true,
      mode: 'READ_ONLY_SCAN',
      summary: {
        total_users_with_dr_or_rr: items.length,
        affected_users_count: affected.length,
        total_missing_qkey: totalMissing
      },
      affected
    })
  } catch (error) {
    console.error('scan-missing-tx-from-dr-rr error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ─────────────────────────────────────────────────────────────────
// /api/diag/fix-missing-tx-from-dr-rr  ── SET-BASED REWRITE (2026-05-18)
// 사장님 명령 직접 반영:
//   ✅ row 마다 EXISTS SELECT 절대 금지 (구버전 EXISTS-loop 완전 폐기)
//   ✅ UNIQUE INDEX 기반 중복 방지 (idx_tx_unique_ref, partial WHERE ref_id IS NOT NULL)
//   ✅ INSERT OR IGNORE INTO ... SELECT ... LEFT JOIN ... WHERE t.id IS NULL (anti-join)
//   ✅ db.batch([create_index, dr_insert, rr_insert, balance_update]) — 4개 statement 묶음
//   ✅ 사용자별 for-loop 없음. 전체가 SQL 한 묶음.
//   ✅ 같은 작업 재실행 시 0건 INSERT (멱등성 — UNIQUE INDEX + anti-join 이중 보호)
//
// 로직:
//   1. CREATE UNIQUE INDEX IF NOT EXISTS idx_tx_unique_ref ON transactions(user_id, type, coin_type, ref_id) WHERE ref_id IS NOT NULL
//   2. daily_rewards → daily_qkey tx 누락분 INSERT OR IGNORE (LEFT JOIN anti-join)
//   3. referral_rewards → referral_reward tx 누락분 INSERT OR IGNORE (LEFT JOIN anti-join)
//   4. users.qkey_balance = SUM(transactions WHERE coin_type='QKEY')  — 영향사용자만
//
// 사용:
//   DRY: POST /api/diag/fix-missing-tx-from-dr-rr?key=ADMIN_PW&dry_run=1            (전수)
//        POST /api/diag/fix-missing-tx-from-dr-rr?key=ADMIN_PW&dry_run=1&user_id=38 (단일)
//   GO:  POST /api/diag/fix-missing-tx-from-dr-rr?key=ADMIN_PW&confirm=GO            (전수)
//        POST /api/diag/fix-missing-tx-from-dr-rr?key=ADMIN_PW&confirm=GO&user_id=38 (단일)
//
// 로그: [REWARD_BATCH] start / dr_inserted / rr_inserted / duration_ms / no_per_row_exists=true
// ─────────────────────────────────────────────────────────────────
app.post('/api/diag/fix-missing-tx-from-dr-rr', async (c) => {
  const t0 = Date.now()
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const dryRun = c.req.query('dry_run') === '1'
    const confirm = c.req.query('confirm') || ''
    const userIdQ = c.req.query('user_id') || ''
    // 호환: all=1 도 받지만, user_id 없으면 자동으로 전수 처리
    // (구버전 호출자가 all=1 을 명시해도 그대로 작동)
    if (!dryRun && confirm !== 'GO') {
      return c.json({ error: 'confirm=GO 또는 dry_run=1 필요' }, 400)
    }

    const db = c.env.DB
    const singleUserMode = !!userIdQ
    const uidFilter: number | null = singleUserMode ? Number(userIdQ) : null

    console.log(`[REWARD_BATCH] start action=fix-missing-tx-from-dr-rr mode=${dryRun ? 'DRY_RUN' : 'EXECUTED'} target=${singleUserMode ? 'user_id=' + uidFilter : 'ALL'} method=SET_BASED_INSERT_OR_IGNORE no_per_row_exists=true`)

    // ════════════════════════════════════════════════════════════════
    // STEP 0. 사전 진단 (READ-ONLY, set-based)
    //   - 누락 row 수와 합계를 single SQL anti-join 으로 산출
    //   - 사용자별 for-loop 없음
    //   - DRY_RUN 의 응답 + EXECUTED 의 검증 양쪽에 사용
    // ════════════════════════════════════════════════════════════════
    const drWhereSql = singleUserMode ? 'WHERE dr.user_id = ? AND t.id IS NULL' : 'WHERE t.id IS NULL'
    const rrWhereSql = singleUserMode ? 'WHERE rr.referrer_id = ? AND t.id IS NULL' : 'WHERE t.id IS NULL'
    const drBindings: any[] = singleUserMode ? [uidFilter] : []
    const rrBindings: any[] = singleUserMode ? [uidFilter] : []

    const drMissingStat = await db.prepare(`
      SELECT
        COALESCE(COUNT(*), 0)            AS missing_count,
        COALESCE(SUM(dr.usdt_amount), 0) AS missing_amount,
        COALESCE(COUNT(DISTINCT dr.user_id), 0) AS missing_users
      FROM daily_rewards dr
      LEFT JOIN transactions t
        ON t.user_id = dr.user_id
       AND t.type = 'daily_qkey'
       AND t.coin_type = 'QKEY'
       AND t.ref_id = 'dr_' || dr.id
      ${drWhereSql}
    `).bind(...drBindings).first<any>()

    const rrMissingStat = await db.prepare(`
      SELECT
        COALESCE(COUNT(*), 0)              AS missing_count,
        COALESCE(SUM(rr.reward_amount), 0) AS missing_amount,
        COALESCE(COUNT(DISTINCT rr.referrer_id), 0) AS missing_users
      FROM referral_rewards rr
      LEFT JOIN transactions t
        ON t.user_id = rr.referrer_id
       AND t.type = 'referral_reward'
       AND t.coin_type = 'QKEY'
       AND t.ref_id = 'rr_' || rr.id
      ${rrWhereSql}
    `).bind(...rrBindings).first<any>()

    const drMissingCount = Number(drMissingStat?.missing_count || 0)
    const drMissingAmount = Number(drMissingStat?.missing_amount || 0)
    const rrMissingCount = Number(rrMissingStat?.missing_count || 0)
    const rrMissingAmount = Number(rrMissingStat?.missing_amount || 0)

    // 영향 사용자 목록 (DR 또는 RR 한쪽이라도 누락 있는 사용자)
    const affectedUsersRes = await db.prepare(`
      SELECT u.id, u.email, u.name, u.qkey_balance AS balance_before
      FROM users u
      WHERE u.id IN (
        SELECT DISTINCT dr.user_id
        FROM daily_rewards dr
        LEFT JOIN transactions t
          ON t.user_id = dr.user_id
         AND t.type = 'daily_qkey'
         AND t.coin_type = 'QKEY'
         AND t.ref_id = 'dr_' || dr.id
        ${drWhereSql}
        UNION
        SELECT DISTINCT rr.referrer_id
        FROM referral_rewards rr
        LEFT JOIN transactions t
          ON t.user_id = rr.referrer_id
         AND t.type = 'referral_reward'
         AND t.coin_type = 'QKEY'
         AND t.ref_id = 'rr_' || rr.id
        ${rrWhereSql}
      )
      ORDER BY u.id
    `).bind(...drBindings, ...rrBindings).all<any>()
    const affectedUsers = (affectedUsersRes.results || []) as any[]
    const affectedUserIds = affectedUsers.map((u: any) => Number(u.id))

    // ════════════════════════════════════════════════════════════════
    // DRY_RUN 종료 — INSERT/UPDATE 절대 없음
    // ════════════════════════════════════════════════════════════════
    if (dryRun) {
      const durMs = Date.now() - t0
      console.log(`[REWARD_BATCH] DRY_RUN done dr_would_insert=${drMissingCount} rr_would_insert=${rrMissingCount} affected_users=${affectedUsers.length} duration_ms=${durMs}`)
      return c.json({
        ok: true,
        mode: 'DRY_RUN',
        action: 'fix-missing-tx-from-dr-rr',
        method: 'SET_BASED_INSERT_OR_IGNORE',
        no_per_row_exists: true,
        target: singleUserMode ? { user_id: uidFilter } : 'ALL',
        summary: {
          dr_would_insert: drMissingCount,
          dr_would_amount: drMissingAmount,
          rr_would_insert: rrMissingCount,
          rr_would_amount: rrMissingAmount,
          total_qkey_would_insert: drMissingAmount + rrMissingAmount,
          affected_users: affectedUsers.length
        },
        affected_users: affectedUsers,
        duration_ms: durMs
      })
    }

    // ════════════════════════════════════════════════════════════════
    // EXECUTE — db.batch([...]) 묶음 (사용자별 루프 절대 없음)
    //   Statement 1: CREATE UNIQUE INDEX IF NOT EXISTS (partial, ref_id IS NOT NULL)
    //   Statement 2: DR INSERT OR IGNORE ... SELECT ... LEFT JOIN ... WHERE t.id IS NULL
    //   Statement 3: RR INSERT OR IGNORE ... SELECT ... LEFT JOIN ... WHERE t.id IS NULL
    //   Statement 4: UPDATE users.qkey_balance — 영향 사용자만 (set-based)
    //
    //   - row 마다 EXISTS SELECT 절대 없음
    //   - UNIQUE INDEX + INSERT OR IGNORE = 이중 중복 차단
    //   - 같은 작업 재실행 시 INSERT OR IGNORE 가 모두 0 changes (멱등)
    // ════════════════════════════════════════════════════════════════

    // Statement 1: UNIQUE INDEX (partial)
    const stmtCreateIndex = db.prepare(`
      CREATE UNIQUE INDEX IF NOT EXISTS idx_tx_unique_ref
      ON transactions(user_id, type, coin_type, ref_id)
      WHERE ref_id IS NOT NULL
    `)

    // Statement 2: DR INSERT OR IGNORE
    const drInsertSql = `
      INSERT OR IGNORE INTO transactions
        (user_id, type, coin_type, amount, description, ref_id, created_at)
      SELECT
        dr.user_id,
        'daily_qkey',
        'QKEY',
        dr.usdt_amount,
        '일일 배당 (QKEY) - ' || dr.reward_date,
        'dr_' || dr.id,
        dr.created_at
      FROM daily_rewards dr
      LEFT JOIN transactions t
        ON t.user_id = dr.user_id
       AND t.type = 'daily_qkey'
       AND t.coin_type = 'QKEY'
       AND t.ref_id = 'dr_' || dr.id
      ${drWhereSql}
    `
    const stmtDrInsert = singleUserMode
      ? db.prepare(drInsertSql).bind(uidFilter)
      : db.prepare(drInsertSql)

    // Statement 3: RR INSERT OR IGNORE
    const rrInsertSql = `
      INSERT OR IGNORE INTO transactions
        (user_id, type, coin_type, amount, description, ref_id, created_at)
      SELECT
        rr.referrer_id,
        'referral_reward',
        'QKEY',
        rr.reward_amount,
        CASE
          WHEN rr.level = 0 THEN '직판 보너스 - ' || rr.reward_date
          ELSE '추천 보너스 (Level ' || rr.level || ') - ' || rr.reward_date
        END,
        'rr_' || rr.id,
        rr.created_at
      FROM referral_rewards rr
      LEFT JOIN transactions t
        ON t.user_id = rr.referrer_id
       AND t.type = 'referral_reward'
       AND t.coin_type = 'QKEY'
       AND t.ref_id = 'rr_' || rr.id
      ${rrWhereSql}
    `
    const stmtRrInsert = singleUserMode
      ? db.prepare(rrInsertSql).bind(uidFilter)
      : db.prepare(rrInsertSql)

    // Statement 4: 영향 사용자 잔고 재계산
    let stmtBalanceUpdate: any = null
    if (affectedUserIds.length > 0) {
      const placeholders = affectedUserIds.map(() => '?').join(',')
      stmtBalanceUpdate = db.prepare(`
        UPDATE users
        SET qkey_balance = COALESCE((
          SELECT SUM(amount) FROM transactions
          WHERE user_id = users.id AND coin_type = 'QKEY'
        ), 0)
        WHERE id IN (${placeholders})
      `).bind(...affectedUserIds)
    }

    // db.batch 실행 — 2~4개 statement 묶음
    const batchStmts: any[] = [stmtCreateIndex, stmtDrInsert, stmtRrInsert]
    if (stmtBalanceUpdate) batchStmts.push(stmtBalanceUpdate)
    const batchResults: any[] = await db.batch(batchStmts)

    const drInsertRes = batchResults[1]
    const rrInsertRes = batchResults[2]
    const balUpdateRes = stmtBalanceUpdate ? batchResults[3] : null

    const drInserted = Number(drInsertRes?.meta?.changes ?? drInsertRes?.changes ?? 0)
    const rrInserted = Number(rrInsertRes?.meta?.changes ?? rrInsertRes?.changes ?? 0)
    const balUpdated = Number(balUpdateRes?.meta?.changes ?? balUpdateRes?.changes ?? 0)

    // 영향 사용자별 after balance 조회 (보고용, 1 쿼리)
    const userAfterMap: Record<number, number> = {}
    if (affectedUserIds.length > 0) {
      const placeholders = affectedUserIds.map(() => '?').join(',')
      const afterRes = await db.prepare(`
        SELECT id, qkey_balance AS balance_after FROM users WHERE id IN (${placeholders})
      `).bind(...affectedUserIds).all<any>()
      for (const r of (afterRes.results || []) as any[]) {
        userAfterMap[Number(r.id)] = Number(r.balance_after || 0)
      }
    }
    const userChanges = affectedUsers.map((u: any) => {
      const uid = Number(u.id)
      const before = Number(u.balance_before || 0)
      const after = userAfterMap[uid] ?? before
      return {
        user_id: uid,
        email: u.email,
        name: u.name,
        balance_before: before,
        balance_after: after,
        balance_diff: after - before
      }
    })

    const durMs = Date.now() - t0
    console.log(`[REWARD_BATCH] EXECUTED done dr_inserted=${drInserted} rr_inserted=${rrInserted} balance_updated_rows=${balUpdated} affected_users=${affectedUsers.length} duration_ms=${durMs} no_per_row_exists=true`)

    return c.json({
      ok: true,
      mode: 'EXECUTED',
      action: 'fix-missing-tx-from-dr-rr',
      method: 'SET_BASED_INSERT_OR_IGNORE',
      no_per_row_exists: true,
      target: singleUserMode ? { user_id: uidFilter } : 'ALL',
      summary: {
        dr_tx_inserted: drInserted,
        rr_tx_inserted: rrInserted,
        balance_updated_rows: balUpdated,
        affected_users: affectedUsers.length,
        unique_index: 'idx_tx_unique_ref (partial WHERE ref_id IS NOT NULL)'
      },
      pre_scan: {
        dr_missing_count: drMissingCount,
        dr_missing_amount: drMissingAmount,
        rr_missing_count: rrMissingCount,
        rr_missing_amount: rrMissingAmount,
        total_missing_qkey: drMissingAmount + rrMissingAmount
      },
      user_changes: userChanges,
      duration_ms: durMs
    })
  } catch (error) {
    const durMs = Date.now() - t0
    console.error(`[REWARD_BATCH] ERROR action=fix-missing-tx-from-dr-rr duration_ms=${durMs}`, error)
    return c.json({ error: String(error), duration_ms: durMs }, 500)
  }
})

// ─────────────────────────────────────────────────────────────────
// /api/diag/rollback-fix-missing-tx
// 사장님 명령 (2026-05-18): 방금 fix-missing-tx-from-dr-rr 으로 INSERT 된 모든 tx 일괄 롤백
//   - ref_id LIKE 'dr_%' (daily_qkey) 또는 ref_id LIKE 'rr_%' (referral_reward) tx 만 DELETE
//   - 영향받은 사용자들의 잔고 재계산
// DRY: POST /api/diag/rollback-fix-missing-tx?key=ADMIN_PW&dry_run=1
// GO:  POST /api/diag/rollback-fix-missing-tx?key=ADMIN_PW&confirm=GO
// ─────────────────────────────────────────────────────────────────
app.post('/api/diag/rollback-fix-missing-tx', async (c) => {
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const dryRun = c.req.query('dry_run') === '1'
    const confirm = c.req.query('confirm') || ''
    if (!dryRun && confirm !== 'GO') return c.json({ error: 'confirm=GO 또는 dry_run=1 필요' }, 400)

    const db = c.env.DB

    // 영향받은 user_id 미리 조회
    const affected = await db.prepare(`
      SELECT user_id, COUNT(*) AS cnt, SUM(amount) AS sum_amt
      FROM transactions
      WHERE (ref_id LIKE 'dr\\_%' ESCAPE '\\' OR ref_id LIKE 'rr\\_%' ESCAPE '\\')
      GROUP BY user_id ORDER BY user_id
    `).all<any>()
    const items = (affected.results || []) as any[]
    const totalCnt = items.reduce((s, x) => s + Number(x.cnt), 0)
    const totalSum = items.reduce((s, x) => s + Number(x.sum_amt), 0)

    if (dryRun) {
      return c.json({
        ok: true,
        mode: 'DRY_RUN',
        affected_users: items.length,
        total_tx_to_delete: totalCnt,
        total_qkey_to_remove: totalSum,
        per_user: items
      })
    }

    // DELETE
    const del = await db.prepare(`
      DELETE FROM transactions
      WHERE (ref_id LIKE 'dr\\_%' ESCAPE '\\' OR ref_id LIKE 'rr\\_%' ESCAPE '\\')
    `).run()
    const deleted = del.meta?.changes || 0

    // 영향받은 사용자들 잔고 재계산
    const userChanges: any[] = []
    for (const it of items) {
      const uid = Number(it.user_id)
      const before = await db.prepare(`SELECT email, name, qkey_balance FROM users WHERE id=?`).bind(uid).first<any>()
      const sum = await db.prepare(`SELECT COALESCE(SUM(amount),0) AS t FROM transactions WHERE user_id=? AND coin_type='QKEY'`).bind(uid).first<any>()
      const newBal = Number(sum?.t || 0)
      await db.prepare(`UPDATE users SET qkey_balance=? WHERE id=?`).bind(newBal, uid).run()
      userChanges.push({
        user_id: uid,
        email: before?.email,
        name: before?.name,
        balance_before: Number(before?.qkey_balance || 0),
        balance_after: newBal,
        balance_diff: newBal - Number(before?.qkey_balance || 0)
      })
    }

    return c.json({
      ok: true,
      mode: 'EXECUTED',
      tx_deleted: deleted,
      qkey_removed_total: totalSum,
      balance_updated: userChanges.length,
      user_changes: userChanges
    })
  } catch (error) {
    console.error('rollback-fix-missing-tx error:', error)
    return c.json({ error: String(error) }, 500)
  }
})

// ═══════════════════════════════════════════════════════════════════
// /api/diag/scan-null-ref-tx
// 사장님 명령 (2026-05-18) — 옵션 B 1단계: legacy NULL-ref tx 실태조사
//
// 목적:
//   - transactions.ref_id IS NULL 인 daily_qkey / referral_reward tx 가 몇 건인지
//   - 그 중 dr/rr 와 1:1 정확 매칭 가능한 건수 (백필 후보)
//   - 매칭 모호 (후보 다수) 건수 — 사장님 보고 대상
//
// READ-ONLY — 모든 SQL 은 SELECT 만. DB 변경 없음.
// 완전 set-based — 사용자별 for-loop 없음.
//
// 사용: GET /api/diag/scan-null-ref-tx?key=ADMIN_PW
// ═══════════════════════════════════════════════════════════════════
app.get('/api/diag/scan-null-ref-tx', async (c) => {
  const t0 = Date.now()
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)

    const db = c.env.DB
    console.log(`[REWARD_BATCH] start action=scan-null-ref-tx mode=READ_ONLY no_per_row_exists=true set_based=true`)

    // ─── 1. NULL-ref tx 전체 통계 ───
    const drNullStat = await db.prepare(`
      SELECT
        COUNT(*) AS cnt,
        COALESCE(SUM(amount), 0) AS sum_amount,
        COUNT(DISTINCT user_id) AS user_cnt
      FROM transactions
      WHERE type = 'daily_qkey' AND coin_type = 'QKEY' AND ref_id IS NULL
    `).first<any>()

    const rrNullStat = await db.prepare(`
      SELECT
        COUNT(*) AS cnt,
        COALESCE(SUM(amount), 0) AS sum_amount,
        COUNT(DISTINCT user_id) AS user_cnt
      FROM transactions
      WHERE type = 'referral_reward' AND coin_type = 'QKEY' AND ref_id IS NULL
    `).first<any>()

    // ─── 2. DR 1:1 매칭 후보 산출 ───
    // 한 NULL-ref daily_qkey tx 에 대해:
    //   user_id + amount + (DATE(created_at) = reward_date OR paid_date) 로 dr 후보 검색
    //   tx 쪽에서 후보가 정확히 1개, dr 쪽에서도 동일 tx 가 후보가 정확히 1개여야 1:1
    //
    // 양방향 1:1 카운트를 set-based 로:
    //   - tx 별 후보 dr 수 (tx_to_dr_count) 와 dr 별 후보 tx 수 (dr_to_tx_count)
    //   - 양쪽 다 1 인 row 만 백필 가능
    const drPairs = await db.prepare(`
      WITH candidate_pairs AS (
        SELECT
          tx.id   AS tx_id,
          dr.id   AS dr_id,
          tx.user_id,
          tx.amount,
          tx.created_at AS tx_created_at,
          dr.reward_date,
          dr.paid_date
        FROM transactions tx
        JOIN daily_rewards dr
          ON dr.user_id = tx.user_id
         AND dr.usdt_amount = tx.amount
         AND (
              DATE(tx.created_at) = dr.reward_date
           OR DATE(tx.created_at) = dr.paid_date
         )
        LEFT JOIN transactions t2
          ON t2.ref_id = 'dr_' || dr.id
        WHERE tx.type = 'daily_qkey'
          AND tx.coin_type = 'QKEY'
          AND tx.ref_id IS NULL
          AND t2.id IS NULL   -- 그 dr_id 가 이미 ref_id 로 다른 tx 에 점유돼 있으면 제외
      ),
      tx_candidate_count AS (
        SELECT tx_id, COUNT(*) AS n_dr FROM candidate_pairs GROUP BY tx_id
      ),
      dr_candidate_count AS (
        SELECT dr_id, COUNT(*) AS n_tx FROM candidate_pairs GROUP BY dr_id
      )
      SELECT
        COUNT(*) AS total_pairs,
        SUM(CASE WHEN tcc.n_dr = 1 AND dcc.n_tx = 1 THEN 1 ELSE 0 END) AS one_to_one,
        SUM(CASE WHEN tcc.n_dr > 1 OR dcc.n_tx > 1 THEN 1 ELSE 0 END) AS ambiguous,
        COUNT(DISTINCT cp.tx_id) AS distinct_tx,
        COUNT(DISTINCT cp.dr_id) AS distinct_dr
      FROM candidate_pairs cp
      JOIN tx_candidate_count tcc ON tcc.tx_id = cp.tx_id
      JOIN dr_candidate_count dcc ON dcc.dr_id = cp.dr_id
    `).first<any>()

    // 매칭 안 되는 NULL-ref daily_qkey tx 수 = 전체 NULL-ref - 1:1 매칭 가능 tx 수
    // (모호 매칭 tx 는 매칭 안 된 것으로 분류 — 백필 안 함)
    const drNullCnt = Number(drNullStat?.cnt || 0)
    const drOneToOneTx = Number(drPairs?.one_to_one || 0) // 1:1 pair 수 = 백필 가능 tx 수
    const drUnmatched = drNullCnt - drOneToOneTx

    // ─── 3. RR 1:1 매칭 후보 산출 (동일 패턴) ───
    const rrPairs = await db.prepare(`
      WITH candidate_pairs AS (
        SELECT
          tx.id  AS tx_id,
          rr.id  AS rr_id,
          tx.user_id,
          tx.amount,
          tx.created_at AS tx_created_at,
          rr.reward_date,
          rr.paid_date
        FROM transactions tx
        JOIN referral_rewards rr
          ON rr.referrer_id = tx.user_id
         AND rr.reward_amount = tx.amount
         AND (
              DATE(tx.created_at) = rr.reward_date
           OR DATE(tx.created_at) = rr.paid_date
         )
        LEFT JOIN transactions t2
          ON t2.ref_id = 'rr_' || rr.id
        WHERE tx.type = 'referral_reward'
          AND tx.coin_type = 'QKEY'
          AND tx.ref_id IS NULL
          AND t2.id IS NULL
      ),
      tx_candidate_count AS (
        SELECT tx_id, COUNT(*) AS n_rr FROM candidate_pairs GROUP BY tx_id
      ),
      rr_candidate_count AS (
        SELECT rr_id, COUNT(*) AS n_tx FROM candidate_pairs GROUP BY rr_id
      )
      SELECT
        COUNT(*) AS total_pairs,
        SUM(CASE WHEN tcc.n_rr = 1 AND rcc.n_tx = 1 THEN 1 ELSE 0 END) AS one_to_one,
        SUM(CASE WHEN tcc.n_rr > 1 OR rcc.n_tx > 1 THEN 1 ELSE 0 END) AS ambiguous,
        COUNT(DISTINCT cp.tx_id) AS distinct_tx,
        COUNT(DISTINCT cp.rr_id) AS distinct_rr
      FROM candidate_pairs cp
      JOIN tx_candidate_count tcc ON tcc.tx_id = cp.tx_id
      JOIN rr_candidate_count rcc ON rcc.rr_id = cp.rr_id
    `).first<any>()

    const rrNullCnt = Number(rrNullStat?.cnt || 0)
    const rrOneToOneTx = Number(rrPairs?.one_to_one || 0)
    const rrUnmatched = rrNullCnt - rrOneToOneTx

    // ─── 4. 샘플 — 매칭 모호 / 매칭 불가 tx 10건씩 (사장님 보고용) ───
    const drAmbiguousSamples = await db.prepare(`
      WITH null_tx AS (
        SELECT id, user_id, amount, created_at
        FROM transactions
        WHERE type = 'daily_qkey' AND coin_type = 'QKEY' AND ref_id IS NULL
      )
      SELECT
        nt.id AS tx_id, nt.user_id, nt.amount, nt.created_at,
        COUNT(dr.id) AS dr_candidate_count
      FROM null_tx nt
      LEFT JOIN daily_rewards dr
        ON dr.user_id = nt.user_id
       AND dr.usdt_amount = nt.amount
       AND (DATE(nt.created_at) = dr.reward_date OR DATE(nt.created_at) = dr.paid_date)
      GROUP BY nt.id
      HAVING dr_candidate_count <> 1
      LIMIT 10
    `).all<any>()

    const durMs = Date.now() - t0
    console.log(`[REWARD_BATCH] scan-null-ref-tx done dr_null=${drNullCnt} dr_1to1=${drOneToOneTx} rr_null=${rrNullCnt} rr_1to1=${rrOneToOneTx} duration_ms=${durMs}`)

    return c.json({
      ok: true,
      mode: 'READ_ONLY_SCAN',
      action: 'scan-null-ref-tx',
      method: 'SET_BASED_ANTI_JOIN',
      no_per_row_exists: true,
      summary: {
        daily_qkey: {
          null_ref_tx_count: drNullCnt,
          null_ref_sum_amount: Number(drNullStat?.sum_amount || 0),
          null_ref_distinct_users: Number(drNullStat?.user_cnt || 0),
          one_to_one_matchable: drOneToOneTx,
          unmatched_or_ambiguous: drUnmatched
        },
        referral_reward: {
          null_ref_tx_count: rrNullCnt,
          null_ref_sum_amount: Number(rrNullStat?.sum_amount || 0),
          null_ref_distinct_users: Number(rrNullStat?.user_cnt || 0),
          one_to_one_matchable: rrOneToOneTx,
          unmatched_or_ambiguous: rrUnmatched
        }
      },
      dr_pair_stats: drPairs,
      rr_pair_stats: rrPairs,
      ambiguous_or_unmatched_dr_samples: (drAmbiguousSamples.results || []).slice(0, 10),
      duration_ms: durMs
    })
  } catch (error) {
    const durMs = Date.now() - t0
    console.error(`[REWARD_BATCH] ERROR action=scan-null-ref-tx duration_ms=${durMs}`, error)
    return c.json({ error: String(error), duration_ms: durMs }, 500)
  }
})

// ═══════════════════════════════════════════════════════════════════
// /api/diag/backfill-null-ref-tx
// 사장님 명령 (2026-05-18) — 옵션 B 2단계:
//   legacy NULL-ref tx 에 dr_{id} / rr_{id} ref_id 백필
//
// 안전 규칙:
//   ✅ 1:1 정확 매칭만 백필 (tx→dr 후보 1개 AND dr→tx 후보 1개)
//   ✅ 양방향 1:1 검증 — CTE 안에서 set-based 로
//   ✅ 그 dr_id 가 다른 tx 의 ref_id 로 이미 점유 시 제외 (이중 매칭 방지)
//   ✅ ref_id IS NULL 인 tx 만 대상 — 기존 ref_id 절대 덮어쓰지 않음
//   ✅ UPDATE 만 — INSERT/DELETE 절대 없음
//   ✅ 사용자별 for-loop 없음 (완전 set-based)
//
// 사용:
//   DRY: POST /api/diag/backfill-null-ref-tx?key=ADMIN_PW&dry_run=1
//   GO:  POST /api/diag/backfill-null-ref-tx?key=ADMIN_PW&confirm=GO
// ═══════════════════════════════════════════════════════════════════
app.post('/api/diag/backfill-null-ref-tx', async (c) => {
  const t0 = Date.now()
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const dryRun = c.req.query('dry_run') === '1'
    const confirm = c.req.query('confirm') || ''
    if (!dryRun && confirm !== 'GO') {
      return c.json({ error: 'confirm=GO 또는 dry_run=1 필요' }, 400)
    }

    const db = c.env.DB
    console.log(`[REWARD_BATCH] start action=backfill-null-ref-tx mode=${dryRun ? 'DRY_RUN' : 'EXECUTED'} method=SET_BASED_UPDATE no_per_row_exists=true`)

    // ════════════════════════════════════════════════════════════════
    // 매칭 대상 산출 — CTE 로 양방향 1:1 검증 (DR)
    //
    // 안전성:
    //   - candidate_pairs: NULL-ref tx ↔ 점유되지 않은 dr 의 모든 후보 쌍
    //   - tx_to_dr_count = 1 AND dr_to_tx_count = 1 인 쌍만 백필 대상
    //   - 백필 안 되면 NULL 그대로 유지 (안전)
    // ════════════════════════════════════════════════════════════════

    // ─── DR 백필 대상 1:1 쌍 카운트 (DRY+EXEC 공통 사전 진단) ───
    const drCountRes = await db.prepare(`
      WITH candidate_pairs AS (
        SELECT tx.id AS tx_id, dr.id AS dr_id
        FROM transactions tx
        JOIN daily_rewards dr
          ON dr.user_id = tx.user_id
         AND dr.usdt_amount = tx.amount
         AND (DATE(tx.created_at) = dr.reward_date OR DATE(tx.created_at) = dr.paid_date)
        LEFT JOIN transactions t2
          ON t2.ref_id = 'dr_' || dr.id
        WHERE tx.type = 'daily_qkey'
          AND tx.coin_type = 'QKEY'
          AND tx.ref_id IS NULL
          AND t2.id IS NULL
      ),
      tcc AS (SELECT tx_id, COUNT(*) AS n FROM candidate_pairs GROUP BY tx_id),
      dcc AS (SELECT dr_id, COUNT(*) AS n FROM candidate_pairs GROUP BY dr_id)
      SELECT COUNT(*) AS one_to_one_count
      FROM candidate_pairs cp
      JOIN tcc ON tcc.tx_id = cp.tx_id
      JOIN dcc ON dcc.dr_id = cp.dr_id
      WHERE tcc.n = 1 AND dcc.n = 1
    `).first<any>()
    const drOneToOneCount = Number(drCountRes?.one_to_one_count || 0)

    // ─── RR 백필 대상 1:1 쌍 카운트 ───
    const rrCountRes = await db.prepare(`
      WITH candidate_pairs AS (
        SELECT tx.id AS tx_id, rr.id AS rr_id
        FROM transactions tx
        JOIN referral_rewards rr
          ON rr.referrer_id = tx.user_id
         AND rr.reward_amount = tx.amount
         AND (DATE(tx.created_at) = rr.reward_date OR DATE(tx.created_at) = rr.paid_date)
        LEFT JOIN transactions t2
          ON t2.ref_id = 'rr_' || rr.id
        WHERE tx.type = 'referral_reward'
          AND tx.coin_type = 'QKEY'
          AND tx.ref_id IS NULL
          AND t2.id IS NULL
      ),
      tcc AS (SELECT tx_id, COUNT(*) AS n FROM candidate_pairs GROUP BY tx_id),
      rcc AS (SELECT rr_id, COUNT(*) AS n FROM candidate_pairs GROUP BY rr_id)
      SELECT COUNT(*) AS one_to_one_count
      FROM candidate_pairs cp
      JOIN tcc ON tcc.tx_id = cp.tx_id
      JOIN rcc ON rcc.rr_id = cp.rr_id
      WHERE tcc.n = 1 AND rcc.n = 1
    `).first<any>()
    const rrOneToOneCount = Number(rrCountRes?.one_to_one_count || 0)

    // ─── DRY_RUN: 카운트만 보고. UPDATE 금지 ───
    if (dryRun) {
      const durMs = Date.now() - t0
      console.log(`[REWARD_BATCH] DRY_RUN done dr_would_backfill=${drOneToOneCount} rr_would_backfill=${rrOneToOneCount} duration_ms=${durMs}`)
      return c.json({
        ok: true,
        mode: 'DRY_RUN',
        action: 'backfill-null-ref-tx',
        method: 'SET_BASED_UPDATE',
        no_per_row_exists: true,
        summary: {
          dr_would_backfill: drOneToOneCount,
          rr_would_backfill: rrOneToOneCount,
          total_would_backfill: drOneToOneCount + rrOneToOneCount
        },
        note: '1:1 정확 매칭만 백필. 후보 다수(ambiguous) 또는 매칭 불가(unmatched) tx 는 NULL 유지.',
        duration_ms: durMs
      })
    }

    // ════════════════════════════════════════════════════════════════
    // EXECUTE — set-based UPDATE 2개를 db.batch 로 묶음
    //
    // 핵심 안전 패턴:
    //   UPDATE transactions
    //   SET ref_id = 'dr_' || (SELECT dr_id FROM one_to_one_pairs WHERE tx_id = transactions.id)
    //   WHERE id IN (SELECT tx_id FROM one_to_one_pairs)
    //
    // SQLite 는 CTE 안의 UPDATE 를 지원하지 않으므로, 대신:
    //   UPDATE transactions
    //   SET ref_id = (SELECT 'dr_' || dr.id FROM ... 1:1 인 dr WHERE ... = transactions.id LIMIT 1)
    //   WHERE id IN ( ... 1:1 tx_id 목록 ... )
    // ════════════════════════════════════════════════════════════════

    // DR UPDATE — set-based
    const stmtDrBackfill = db.prepare(`
      UPDATE transactions
      SET ref_id = 'dr_' || (
        SELECT cp.dr_id FROM (
          WITH candidate_pairs AS (
            SELECT tx.id AS tx_id, dr.id AS dr_id
            FROM transactions tx
            JOIN daily_rewards dr
              ON dr.user_id = tx.user_id
             AND dr.usdt_amount = tx.amount
             AND (DATE(tx.created_at) = dr.reward_date OR DATE(tx.created_at) = dr.paid_date)
            LEFT JOIN transactions t2 ON t2.ref_id = 'dr_' || dr.id
            WHERE tx.type = 'daily_qkey' AND tx.coin_type = 'QKEY'
              AND tx.ref_id IS NULL AND t2.id IS NULL
          ),
          tcc AS (SELECT tx_id, COUNT(*) AS n FROM candidate_pairs GROUP BY tx_id),
          dcc AS (SELECT dr_id, COUNT(*) AS n FROM candidate_pairs GROUP BY dr_id)
          SELECT cp.tx_id, cp.dr_id
          FROM candidate_pairs cp
          JOIN tcc ON tcc.tx_id = cp.tx_id
          JOIN dcc ON dcc.dr_id = cp.dr_id
          WHERE tcc.n = 1 AND dcc.n = 1
        ) cp
        WHERE cp.tx_id = transactions.id
      )
      WHERE id IN (
        WITH candidate_pairs AS (
          SELECT tx.id AS tx_id, dr.id AS dr_id
          FROM transactions tx
          JOIN daily_rewards dr
            ON dr.user_id = tx.user_id
           AND dr.usdt_amount = tx.amount
           AND (DATE(tx.created_at) = dr.reward_date OR DATE(tx.created_at) = dr.paid_date)
          LEFT JOIN transactions t2 ON t2.ref_id = 'dr_' || dr.id
          WHERE tx.type = 'daily_qkey' AND tx.coin_type = 'QKEY'
            AND tx.ref_id IS NULL AND t2.id IS NULL
        ),
        tcc AS (SELECT tx_id, COUNT(*) AS n FROM candidate_pairs GROUP BY tx_id),
        dcc AS (SELECT dr_id, COUNT(*) AS n FROM candidate_pairs GROUP BY dr_id)
        SELECT cp.tx_id
        FROM candidate_pairs cp
        JOIN tcc ON tcc.tx_id = cp.tx_id
        JOIN dcc ON dcc.dr_id = cp.dr_id
        WHERE tcc.n = 1 AND dcc.n = 1
      )
        AND ref_id IS NULL  -- 이중 안전가드: 기존 ref_id 절대 덮어쓰지 않음
    `)

    // RR UPDATE — set-based (동일 패턴)
    const stmtRrBackfill = db.prepare(`
      UPDATE transactions
      SET ref_id = 'rr_' || (
        SELECT cp.rr_id FROM (
          WITH candidate_pairs AS (
            SELECT tx.id AS tx_id, rr.id AS rr_id
            FROM transactions tx
            JOIN referral_rewards rr
              ON rr.referrer_id = tx.user_id
             AND rr.reward_amount = tx.amount
             AND (DATE(tx.created_at) = rr.reward_date OR DATE(tx.created_at) = rr.paid_date)
            LEFT JOIN transactions t2 ON t2.ref_id = 'rr_' || rr.id
            WHERE tx.type = 'referral_reward' AND tx.coin_type = 'QKEY'
              AND tx.ref_id IS NULL AND t2.id IS NULL
          ),
          tcc AS (SELECT tx_id, COUNT(*) AS n FROM candidate_pairs GROUP BY tx_id),
          rcc AS (SELECT rr_id, COUNT(*) AS n FROM candidate_pairs GROUP BY rr_id)
          SELECT cp.tx_id, cp.rr_id
          FROM candidate_pairs cp
          JOIN tcc ON tcc.tx_id = cp.tx_id
          JOIN rcc ON rcc.rr_id = cp.rr_id
          WHERE tcc.n = 1 AND rcc.n = 1
        ) cp
        WHERE cp.tx_id = transactions.id
      )
      WHERE id IN (
        WITH candidate_pairs AS (
          SELECT tx.id AS tx_id, rr.id AS rr_id
          FROM transactions tx
          JOIN referral_rewards rr
            ON rr.referrer_id = tx.user_id
           AND rr.reward_amount = tx.amount
           AND (DATE(tx.created_at) = rr.reward_date OR DATE(tx.created_at) = rr.paid_date)
          LEFT JOIN transactions t2 ON t2.ref_id = 'rr_' || rr.id
          WHERE tx.type = 'referral_reward' AND tx.coin_type = 'QKEY'
            AND tx.ref_id IS NULL AND t2.id IS NULL
        ),
        tcc AS (SELECT tx_id, COUNT(*) AS n FROM candidate_pairs GROUP BY tx_id),
        rcc AS (SELECT rr_id, COUNT(*) AS n FROM candidate_pairs GROUP BY rr_id)
        SELECT cp.tx_id
        FROM candidate_pairs cp
        JOIN tcc ON tcc.tx_id = cp.tx_id
        JOIN rcc ON rcc.rr_id = cp.rr_id
        WHERE tcc.n = 1 AND rcc.n = 1
      )
        AND ref_id IS NULL  -- 이중 안전가드
    `)

    // db.batch — 2 statement 묶음
    const batchResults: any[] = await db.batch([stmtDrBackfill, stmtRrBackfill])
    const drBackfilled = Number(batchResults[0]?.meta?.changes ?? batchResults[0]?.changes ?? 0)
    const rrBackfilled = Number(batchResults[1]?.meta?.changes ?? batchResults[1]?.changes ?? 0)

    // 사후 검증 — 남은 NULL-ref tx 수
    const afterDrNull = await db.prepare(`SELECT COUNT(*) AS cnt FROM transactions WHERE type='daily_qkey' AND coin_type='QKEY' AND ref_id IS NULL`).first<any>()
    const afterRrNull = await db.prepare(`SELECT COUNT(*) AS cnt FROM transactions WHERE type='referral_reward' AND coin_type='QKEY' AND ref_id IS NULL`).first<any>()

    const durMs = Date.now() - t0
    console.log(`[REWARD_BATCH] EXECUTED done dr_backfilled=${drBackfilled} rr_backfilled=${rrBackfilled} remaining_dr_null=${afterDrNull?.cnt} remaining_rr_null=${afterRrNull?.cnt} duration_ms=${durMs}`)

    return c.json({
      ok: true,
      mode: 'EXECUTED',
      action: 'backfill-null-ref-tx',
      method: 'SET_BASED_UPDATE',
      no_per_row_exists: true,
      summary: {
        dr_backfilled: drBackfilled,
        rr_backfilled: rrBackfilled,
        total_backfilled: drBackfilled + rrBackfilled,
        pre_scan_expected_dr: drOneToOneCount,
        pre_scan_expected_rr: rrOneToOneCount
      },
      after_state: {
        remaining_dr_null_ref: Number(afterDrNull?.cnt || 0),
        remaining_rr_null_ref: Number(afterRrNull?.cnt || 0)
      },
      duration_ms: durMs
    })
  } catch (error) {
    const durMs = Date.now() - t0
    console.error(`[REWARD_BATCH] ERROR action=backfill-null-ref-tx duration_ms=${durMs}`, error)
    return c.json({ error: String(error), duration_ms: durMs }, 500)
  }
})

// ═══════════════════════════════════════════════════════════════════
// /api/diag/scan-duplicate-dr-rr
// 사장님 영구룰 #1회지급 (2026-05-18 확정):
//   "1 user × 1 reward_date 당, 다음 3종이 각각 1회씩만 지급되어야 한다"
//   - 본인 일일배당 (daily_rewards): (user_id, reward_date) 당 1건
//   - L1 추천보너스 합산 (referral_rewards level=1): (referrer_id, reward_date, level=1) 당 1건
//   - L2 추천보너스 합산 (referral_rewards level=2): (referrer_id, reward_date, level=2) 당 1건
//
// 이 룰을 위반한 데이터 (= 같은 그룹에 2건 이상) 전수조사.
//
// READ-ONLY — SELECT 만. DB 변경 없음.
// 완전 set-based — for-loop 없음.
//
// 사용: GET /api/diag/scan-duplicate-dr-rr?key=ADMIN_PW
// ═══════════════════════════════════════════════════════════════════
app.get('/api/diag/scan-duplicate-dr-rr', async (c) => {
  const t0 = Date.now()
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)

    const db = c.env.DB
    console.log(`[REWARD_BATCH] start action=scan-duplicate-dr-rr mode=READ_ONLY no_per_row_exists=true set_based=true`)

    // ─── 1. DR 중복 (daily_rewards) ───
    //   영구룰: (user_id, reward_date) 1건만
    //   위반: 같은 (user_id, reward_date) 에 row 2건 이상
    const drDupStat = await db.prepare(`
      WITH dup_groups AS (
        SELECT user_id, reward_date, COUNT(*) AS cnt, MIN(id) AS keep_id, MAX(id) AS max_id,
               COALESCE(SUM(usdt_amount), 0) AS sum_amount
        FROM daily_rewards
        GROUP BY user_id, reward_date
        HAVING COUNT(*) > 1
      )
      SELECT
        COUNT(*) AS violating_groups,
        COALESCE(SUM(cnt), 0) AS total_violating_rows,
        COALESCE(SUM(cnt - 1), 0) AS excess_rows,
        COUNT(DISTINCT user_id) AS distinct_users,
        COALESCE(SUM(sum_amount - (sum_amount / cnt)), 0) AS estimated_excess_amount
      FROM dup_groups
    `).first<any>()

    // ─── 2. RR 중복 (referral_rewards) ───
    //   영구룰: (referrer_id, reward_date, level) 1건만
    //   위반: 같은 (referrer_id, reward_date, level) 에 row 2건 이상
    const rrDupStat = await db.prepare(`
      WITH dup_groups AS (
        SELECT referrer_id, reward_date, level, COUNT(*) AS cnt,
               MIN(id) AS keep_id, MAX(id) AS max_id,
               COALESCE(SUM(reward_amount), 0) AS sum_amount
        FROM referral_rewards
        GROUP BY referrer_id, reward_date, level
        HAVING COUNT(*) > 1
      )
      SELECT
        COUNT(*) AS violating_groups,
        COALESCE(SUM(cnt), 0) AS total_violating_rows,
        COALESCE(SUM(cnt - 1), 0) AS excess_rows,
        COUNT(DISTINCT referrer_id) AS distinct_users,
        COALESCE(SUM(sum_amount - (sum_amount / cnt)), 0) AS estimated_excess_amount
      FROM dup_groups
    `).first<any>()

    // ─── 3. DR 중복 그룹 샘플 (top 20) ───
    const drDupSamples = await db.prepare(`
      SELECT user_id, reward_date, COUNT(*) AS cnt,
             MIN(id) AS keep_id,
             GROUP_CONCAT(id, ',') AS all_ids,
             GROUP_CONCAT(usdt_amount, '|') AS all_amounts,
             GROUP_CONCAT(created_at, '|') AS all_created
      FROM daily_rewards
      GROUP BY user_id, reward_date
      HAVING COUNT(*) > 1
      ORDER BY cnt DESC, user_id, reward_date
      LIMIT 20
    `).all<any>()

    // ─── 4. RR 중복 그룹 샘플 (top 20) ───
    const rrDupSamples = await db.prepare(`
      SELECT referrer_id, reward_date, level, COUNT(*) AS cnt,
             MIN(id) AS keep_id,
             GROUP_CONCAT(id, ',') AS all_ids,
             GROUP_CONCAT(reward_amount, '|') AS all_amounts,
             GROUP_CONCAT(created_at, '|') AS all_created
      FROM referral_rewards
      GROUP BY referrer_id, reward_date, level
      HAVING COUNT(*) > 1
      ORDER BY cnt DESC, referrer_id, reward_date, level
      LIMIT 20
    `).all<any>()

    // ─── 5. 사용자별 위반 카운트 (DR + RR 합산) ───
    const userViolations = await db.prepare(`
      SELECT u.id, u.email, u.name,
        COALESCE(dr_v.excess, 0) AS dr_excess_rows,
        COALESCE(rr_v.excess, 0) AS rr_excess_rows,
        COALESCE(dr_v.excess, 0) + COALESCE(rr_v.excess, 0) AS total_excess
      FROM users u
      LEFT JOIN (
        SELECT user_id, SUM(cnt - 1) AS excess
        FROM (
          SELECT user_id, reward_date, COUNT(*) AS cnt
          FROM daily_rewards
          GROUP BY user_id, reward_date
          HAVING COUNT(*) > 1
        )
        GROUP BY user_id
      ) dr_v ON dr_v.user_id = u.id
      LEFT JOIN (
        SELECT referrer_id, SUM(cnt - 1) AS excess
        FROM (
          SELECT referrer_id, reward_date, level, COUNT(*) AS cnt
          FROM referral_rewards
          GROUP BY referrer_id, reward_date, level
          HAVING COUNT(*) > 1
        )
        GROUP BY referrer_id
      ) rr_v ON rr_v.referrer_id = u.id
      WHERE COALESCE(dr_v.excess, 0) + COALESCE(rr_v.excess, 0) > 0
      ORDER BY total_excess DESC, u.id
      LIMIT 50
    `).all<any>()

    // ─── 6. 영향받는 dangling tx 추정 (DELETE 될 dr/rr 의 ref_id 를 가리키는 tx) ───
    // DELETE 대상 dr/rr 의 id 목록 → 그 id 를 가진 ref_id='dr_xxx'/'rr_xxx' tx 가 있으면 그것도 같이 DELETE 대상
    const drDanglingTxStat = await db.prepare(`
      WITH delete_dr_ids AS (
        SELECT id FROM daily_rewards
        WHERE id NOT IN (
          SELECT MIN(id) FROM daily_rewards GROUP BY user_id, reward_date
        )
      )
      SELECT
        COUNT(*) AS dangling_tx_count,
        COALESCE(SUM(amount), 0) AS dangling_tx_sum
      FROM transactions
      WHERE type = 'daily_qkey' AND coin_type = 'QKEY'
        AND ref_id IS NOT NULL
        AND CAST(SUBSTR(ref_id, 4) AS INTEGER) IN (SELECT id FROM delete_dr_ids)
        AND ref_id LIKE 'dr_%'
    `).first<any>()

    const rrDanglingTxStat = await db.prepare(`
      WITH delete_rr_ids AS (
        SELECT id FROM referral_rewards
        WHERE id NOT IN (
          SELECT MIN(id) FROM referral_rewards GROUP BY referrer_id, reward_date, level
        )
      )
      SELECT
        COUNT(*) AS dangling_tx_count,
        COALESCE(SUM(amount), 0) AS dangling_tx_sum
      FROM transactions
      WHERE type = 'referral_reward' AND coin_type = 'QKEY'
        AND ref_id IS NOT NULL
        AND CAST(SUBSTR(ref_id, 4) AS INTEGER) IN (SELECT id FROM delete_rr_ids)
        AND ref_id LIKE 'rr_%'
    `).first<any>()

    const durMs = Date.now() - t0
    console.log(`[REWARD_BATCH] scan-duplicate-dr-rr done dr_violations=${drDupStat?.violating_groups} rr_violations=${rrDupStat?.violating_groups} duration_ms=${durMs}`)

    return c.json({
      ok: true,
      mode: 'READ_ONLY_SCAN',
      action: 'scan-duplicate-dr-rr',
      method: 'SET_BASED_GROUP_BY',
      no_per_row_exists: true,
      permanent_rule: '#1회지급 — (user_id, reward_date) 당 dr 1건 / (referrer_id, reward_date, level) 당 rr 1건',
      summary: {
        daily_rewards_violations: {
          violating_groups: Number(drDupStat?.violating_groups || 0),
          total_violating_rows: Number(drDupStat?.total_violating_rows || 0),
          excess_rows_to_delete: Number(drDupStat?.excess_rows || 0),
          distinct_users_affected: Number(drDupStat?.distinct_users || 0),
          estimated_excess_amount: Number(drDupStat?.estimated_excess_amount || 0)
        },
        referral_rewards_violations: {
          violating_groups: Number(rrDupStat?.violating_groups || 0),
          total_violating_rows: Number(rrDupStat?.total_violating_rows || 0),
          excess_rows_to_delete: Number(rrDupStat?.excess_rows || 0),
          distinct_users_affected: Number(rrDupStat?.distinct_users || 0),
          estimated_excess_amount: Number(rrDupStat?.estimated_excess_amount || 0)
        },
        dangling_tx_estimate: {
          dr_dangling_tx_count: Number(drDanglingTxStat?.dangling_tx_count || 0),
          dr_dangling_tx_sum: Number(drDanglingTxStat?.dangling_tx_sum || 0),
          rr_dangling_tx_count: Number(rrDanglingTxStat?.dangling_tx_count || 0),
          rr_dangling_tx_sum: Number(rrDanglingTxStat?.dangling_tx_sum || 0)
        }
      },
      dr_duplicate_samples: drDupSamples.results || [],
      rr_duplicate_samples: rrDupSamples.results || [],
      user_violation_top50: userViolations.results || [],
      duration_ms: durMs
    })
  } catch (error) {
    const durMs = Date.now() - t0
    console.error(`[REWARD_BATCH] ERROR action=scan-duplicate-dr-rr duration_ms=${durMs}`, error)
    return c.json({ error: String(error), duration_ms: durMs }, 500)
  }
})

// ═══════════════════════════════════════════════════════════════════
// /api/diag/scan-duplicate-dr-rr-v2
// 사장님 영구룰 #지급항목 확정 (2026-05-18):
//
//   📌 level=0 (direct_referral, 직접매출 10% 쿠키):
//      "10명이면 10건을 당일 다 받는다. 건당 1회"
//      = (referrer_id, referee_id, staking_id) 당 1건. 하루 최대 건수 무제한.
//      = 영구룰 #1회지급 의 예외!
//
//   📌 level=1 (L1 배당의 20%): (referrer_id, reward_date, level=1) 당 1건
//   📌 level=2 (L2 배당의 10%): (referrer_id, reward_date, level=2) 당 1건
//   📌 daily_qkey (본인 배당): (user_id, reward_date) 당 1건
//
// 즉 v1 의 RR 위반 484건 중 일부는 level=0 정상 데이터일 수 있음.
// v2 는 level 별로 분리하여 진짜 영구룰 위반만 골라낸다.
//
// READ-ONLY — SELECT 만. DB 변경 없음.
// 사용: GET /api/diag/scan-duplicate-dr-rr-v2?key=ADMIN_PW
// ═══════════════════════════════════════════════════════════════════
app.get('/api/diag/scan-duplicate-dr-rr-v2', async (c) => {
  const t0 = Date.now()
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)

    const db = c.env.DB
    console.log(`[REWARD_BATCH] start action=scan-duplicate-dr-rr-v2 mode=READ_ONLY no_per_row_exists=true set_based=true`)

    // ─── DR 중복: (user_id, reward_date) 당 1건 영구룰 ───
    const drDupStat = await db.prepare(`
      WITH dup_groups AS (
        SELECT user_id, reward_date, COUNT(*) AS cnt, MIN(id) AS keep_id,
               COALESCE(SUM(usdt_amount), 0) AS sum_amount,
               COUNT(DISTINCT staking_id) AS distinct_stakings
        FROM daily_rewards
        GROUP BY user_id, reward_date
        HAVING COUNT(*) > 1
      )
      SELECT
        COUNT(*) AS violating_groups,
        COALESCE(SUM(cnt), 0) AS total_violating_rows,
        COALESCE(SUM(cnt - 1), 0) AS excess_rows,
        COUNT(DISTINCT user_id) AS distinct_users,
        SUM(CASE WHEN distinct_stakings > 1 THEN 1 ELSE 0 END) AS multi_staking_groups,
        SUM(CASE WHEN distinct_stakings = 1 THEN cnt - 1 ELSE 0 END) AS same_staking_excess
      FROM dup_groups
    `).first<any>()

    // ─── RR Level 1 (L1 보너스): (referrer_id, reward_date, level=1) 당 1건 ───
    const rrL1Stat = await db.prepare(`
      WITH dup_groups AS (
        SELECT referrer_id, reward_date, COUNT(*) AS cnt, MIN(id) AS keep_id,
               COALESCE(SUM(reward_amount), 0) AS sum_amount
        FROM referral_rewards
        WHERE level = 1
        GROUP BY referrer_id, reward_date
        HAVING COUNT(*) > 1
      )
      SELECT
        COUNT(*) AS violating_groups,
        COALESCE(SUM(cnt), 0) AS total_violating_rows,
        COALESCE(SUM(cnt - 1), 0) AS excess_rows,
        COUNT(DISTINCT referrer_id) AS distinct_users
      FROM dup_groups
    `).first<any>()

    // ─── RR Level 2 (L2 보너스): (referrer_id, reward_date, level=2) 당 1건 ───
    const rrL2Stat = await db.prepare(`
      WITH dup_groups AS (
        SELECT referrer_id, reward_date, COUNT(*) AS cnt, MIN(id) AS keep_id,
               COALESCE(SUM(reward_amount), 0) AS sum_amount
        FROM referral_rewards
        WHERE level = 2
        GROUP BY referrer_id, reward_date
        HAVING COUNT(*) > 1
      )
      SELECT
        COUNT(*) AS violating_groups,
        COALESCE(SUM(cnt), 0) AS total_violating_rows,
        COALESCE(SUM(cnt - 1), 0) AS excess_rows,
        COUNT(DISTINCT referrer_id) AS distinct_users
      FROM dup_groups
    `).first<any>()

    // ─── RR Level 0 (직접매출 쿠키): (referrer, referee, staking_id 또는 reward_date) 1건 ───
    // 사장님 룰: "10명이면 10건 받는다 건당 1회"
    // → 같은 사람한테 같은 referee 의 같은 staking 으로 2번 지급되면 위반
    // → 하지만 같은 staking_id 가 referral_rewards 에 저장되는지 확인 필요 — 일단 (referrer, referee, reward_date) 로 검사
    const rrL0Stat = await db.prepare(`
      WITH dup_groups AS (
        SELECT referrer_id, referee_id, reward_date, COUNT(*) AS cnt, MIN(id) AS keep_id,
               COALESCE(SUM(reward_amount), 0) AS sum_amount,
               COUNT(DISTINCT original_amount) AS distinct_amounts
        FROM referral_rewards
        WHERE level = 0
        GROUP BY referrer_id, referee_id, reward_date
        HAVING COUNT(*) > 1
      )
      SELECT
        COUNT(*) AS suspect_groups,
        COALESCE(SUM(cnt), 0) AS total_suspect_rows,
        COALESCE(SUM(cnt - 1), 0) AS excess_rows_if_strict,
        COUNT(DISTINCT referrer_id) AS distinct_users,
        SUM(CASE WHEN distinct_amounts > 1 THEN 1 ELSE 0 END) AS multi_amount_groups
      FROM dup_groups
    `).first<any>()

    // ─── 전체 RR 건수 (level별) ───
    const rrTotalByLevel = await db.prepare(`
      SELECT level, COUNT(*) AS total_rows, COALESCE(SUM(reward_amount), 0) AS total_amount
      FROM referral_rewards
      GROUP BY level
      ORDER BY level
    `).all<any>()

    // ─── L1 위반 샘플 ───
    const rrL1Samples = await db.prepare(`
      SELECT referrer_id, reward_date, COUNT(*) AS cnt,
             MIN(id) AS keep_id,
             GROUP_CONCAT(id, ',') AS all_ids,
             GROUP_CONCAT(reward_amount, '|') AS all_amounts,
             GROUP_CONCAT(referee_id, '|') AS all_referees
      FROM referral_rewards
      WHERE level = 1
      GROUP BY referrer_id, reward_date
      HAVING COUNT(*) > 1
      ORDER BY cnt DESC
      LIMIT 10
    `).all<any>()

    // ─── L2 위반 샘플 ───
    const rrL2Samples = await db.prepare(`
      SELECT referrer_id, reward_date, COUNT(*) AS cnt,
             MIN(id) AS keep_id,
             GROUP_CONCAT(id, ',') AS all_ids,
             GROUP_CONCAT(reward_amount, '|') AS all_amounts,
             GROUP_CONCAT(referee_id, '|') AS all_referees
      FROM referral_rewards
      WHERE level = 2
      GROUP BY referrer_id, reward_date
      HAVING COUNT(*) > 1
      ORDER BY cnt DESC
      LIMIT 10
    `).all<any>()

    // ─── L0 의심 샘플 ───
    const rrL0Samples = await db.prepare(`
      SELECT referrer_id, referee_id, reward_date, COUNT(*) AS cnt,
             MIN(id) AS keep_id,
             GROUP_CONCAT(id, ',') AS all_ids,
             GROUP_CONCAT(reward_amount, '|') AS all_amounts,
             GROUP_CONCAT(original_amount, '|') AS all_originals
      FROM referral_rewards
      WHERE level = 0
      GROUP BY referrer_id, referee_id, reward_date
      HAVING COUNT(*) > 1
      ORDER BY cnt DESC
      LIMIT 10
    `).all<any>()

    // ─── DR 위반 샘플 (multi-staking 인 경우와 같은 staking 중복 구분) ───
    const drSamples = await db.prepare(`
      SELECT user_id, reward_date, COUNT(*) AS cnt,
             MIN(id) AS keep_id,
             COUNT(DISTINCT staking_id) AS distinct_stakings,
             GROUP_CONCAT(id, ',') AS all_ids,
             GROUP_CONCAT(usdt_amount, '|') AS all_amounts,
             GROUP_CONCAT(staking_id, '|') AS all_stakings,
             GROUP_CONCAT(created_at, '|') AS all_created
      FROM daily_rewards
      GROUP BY user_id, reward_date
      HAVING COUNT(*) > 1
      ORDER BY user_id, reward_date
      LIMIT 30
    `).all<any>()

    const durMs = Date.now() - t0
    console.log(`[REWARD_BATCH] scan-v2 done dr_violations=${drDupStat?.violating_groups} L1_violations=${rrL1Stat?.violating_groups} L2_violations=${rrL2Stat?.violating_groups} L0_suspects=${rrL0Stat?.suspect_groups} duration_ms=${durMs}`)

    return c.json({
      ok: true,
      mode: 'READ_ONLY_SCAN',
      action: 'scan-duplicate-dr-rr-v2',
      method: 'SET_BASED_GROUP_BY_BY_LEVEL',
      no_per_row_exists: true,
      permanent_rules_applied: {
        daily_qkey: '(user_id, reward_date) 당 1건',
        referral_reward_L0: '(referrer, referee, staking) 당 1건. 하루 다건 정상 (10명=10건)',
        referral_reward_L1: '(referrer_id, reward_date, level=1) 당 1건 (하부 합산)',
        referral_reward_L2: '(referrer_id, reward_date, level=2) 당 1건 (하부 합산)'
      },
      summary: {
        daily_rewards: {
          violating_groups: Number(drDupStat?.violating_groups || 0),
          total_violating_rows: Number(drDupStat?.total_violating_rows || 0),
          excess_rows_to_delete: Number(drDupStat?.excess_rows || 0),
          distinct_users: Number(drDupStat?.distinct_users || 0),
          multi_staking_groups: Number(drDupStat?.multi_staking_groups || 0),
          same_staking_excess_rows: Number(drDupStat?.same_staking_excess || 0)
        },
        referral_rewards_level1: {
          violating_groups: Number(rrL1Stat?.violating_groups || 0),
          total_violating_rows: Number(rrL1Stat?.total_violating_rows || 0),
          excess_rows_to_delete: Number(rrL1Stat?.excess_rows || 0),
          distinct_users: Number(rrL1Stat?.distinct_users || 0)
        },
        referral_rewards_level2: {
          violating_groups: Number(rrL2Stat?.violating_groups || 0),
          total_violating_rows: Number(rrL2Stat?.total_violating_rows || 0),
          excess_rows_to_delete: Number(rrL2Stat?.excess_rows || 0),
          distinct_users: Number(rrL2Stat?.distinct_users || 0)
        },
        referral_rewards_level0_suspects: {
          suspect_groups: Number(rrL0Stat?.suspect_groups || 0),
          total_suspect_rows: Number(rrL0Stat?.total_suspect_rows || 0),
          excess_rows_if_strict: Number(rrL0Stat?.excess_rows_if_strict || 0),
          distinct_users: Number(rrL0Stat?.distinct_users || 0),
          multi_amount_groups: Number(rrL0Stat?.multi_amount_groups || 0),
          note: '동일 (referrer, referee, reward_date) 에 2건 이상. 단, 한 사람이 같은 날 두 staking 으로 진입했으면 정상. multi_amount_groups > 0 이면 staking 다른 가능성 높음.'
        },
        rr_total_by_level: rrTotalByLevel.results || []
      },
      samples: {
        dr_duplicates: drSamples.results || [],
        rr_level1_violations: rrL1Samples.results || [],
        rr_level2_violations: rrL2Samples.results || [],
        rr_level0_suspects: rrL0Samples.results || []
      },
      duration_ms: durMs
    })
  } catch (error) {
    const durMs = Date.now() - t0
    console.error(`[REWARD_BATCH] ERROR action=scan-duplicate-dr-rr-v2 duration_ms=${durMs}`, error)
    return c.json({ error: String(error), duration_ms: durMs }, 500)
  }
})

// ============================================================
// /api/diag/scan-duplicate-dr-rr-v3
// ----------------------------------------------------------------
// ★ 영구룰 #스테이킹별독립 (2026-05-18) 적용
//
// v2 의 치명적 오류 정정:
//   - v2: (user_id, reward_date) 당 1건 으로 그룹핑 → multi_staking 정상 row 를 위반으로 오분류
//   - v3: (user_id, staking_id, reward_date) 당 1건 → 스테이킹 별 독립 진단
//
// 진단 항목:
//   - DR: (user_id, staking_id, reward_date) GROUP BY HAVING COUNT(*) > 1
//   - RR L1: (referrer_id, referee_id, COALESCE(staking_id,-1), reward_date, level=1) GROUP BY HAVING COUNT(*) > 1
//     ※ staking_id NULL (legacy 2026-05-13 이전) → -1 로 fallback. 단, NULL 이면 별도 reporting
//   - RR L2: (referrer_id, referee_id, COALESCE(staking_id,-1), reward_date, level=2)
//   - RR L0: (referrer_id, referee_id, COALESCE(staking_id,-1)) — staking 단위. 같은 staking 2번 ≠ 정상
//
// READ-ONLY. DB 변경 없음.
// 사용: GET /api/diag/scan-duplicate-dr-rr-v3?key=ADMIN_PW
// ============================================================
app.get('/api/diag/scan-duplicate-dr-rr-v3', async (c) => {
  const t0 = Date.now()
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  const db = c.env.DB

  try {
    console.log(`[REWARD_BATCH] start action=scan-duplicate-dr-rr-v3 mode=READ_ONLY permanent_rule=스테이킹별독립`)

    // ────────────────────────────────────────────
    // DR: daily_rewards. 1건의 기준 = (user_id, staking_id, reward_date)
    //   - staking_id NULL 가능성 점검 (legacy daily_rewards 일부 NULL 일 수 있음)
    //   - 진짜 위반 = 같은 (user_id, staking_id, reward_date) 에 2개 이상
    // ────────────────────────────────────────────
    const drStat = await db.prepare(`
      WITH grp AS (
        SELECT user_id, staking_id, reward_date, COUNT(*) AS cnt
        FROM daily_rewards
        GROUP BY user_id, staking_id, reward_date
      )
      SELECT
        COALESCE(SUM(CASE WHEN cnt > 1 THEN 1 ELSE 0 END), 0) AS violating_groups,
        COALESCE(SUM(CASE WHEN cnt > 1 THEN cnt ELSE 0 END), 0) AS total_violating_rows,
        COALESCE(SUM(CASE WHEN cnt > 1 THEN cnt - 1 ELSE 0 END), 0) AS excess_rows,
        COUNT(DISTINCT CASE WHEN cnt > 1 THEN user_id END) AS distinct_users,
        COALESCE(SUM(CASE WHEN staking_id IS NULL AND cnt > 1 THEN 1 ELSE 0 END), 0) AS null_staking_groups
      FROM grp
    `).first<{
      violating_groups: number, total_violating_rows: number, excess_rows: number,
      distinct_users: number, null_staking_groups: number
    }>()

    // DR 위반 샘플
    const drSamples = await db.prepare(`
      SELECT user_id, staking_id, reward_date,
             COUNT(*) AS cnt,
             MIN(id) AS keep_id,
             GROUP_CONCAT(id) AS all_ids,
             GROUP_CONCAT(usdt_amount, '|') AS all_amounts,
             GROUP_CONCAT(strftime('%Y-%m-%d %H:%M:%S', created_at, '+9 hours'), '|') AS all_created
      FROM daily_rewards
      GROUP BY user_id, staking_id, reward_date
      HAVING COUNT(*) > 1
      ORDER BY user_id, staking_id, reward_date
      LIMIT 30
    `).all<any>()

    // DR 전체 정상성 진단 (다른 staking 다른 row 는 정상)
    const drTotal = await db.prepare(`
      SELECT
        COUNT(*) AS total_rows,
        COUNT(DISTINCT user_id || ':' || COALESCE(staking_id, 'NULL') || ':' || reward_date) AS distinct_user_staking_date,
        COALESCE(SUM(CASE WHEN staking_id IS NULL THEN 1 ELSE 0 END), 0) AS null_staking_rows
      FROM daily_rewards
    `).first<any>()

    // ────────────────────────────────────────────
    // RR Level 1: (referrer_id, referee_id, COALESCE(staking_id,-1), reward_date, level=1)
    // ────────────────────────────────────────────
    const rrL1Stat = await db.prepare(`
      WITH grp AS (
        SELECT referrer_id, referee_id, COALESCE(staking_id, -1) AS sid, reward_date, COUNT(*) AS cnt,
               SUM(CASE WHEN staking_id IS NULL THEN 1 ELSE 0 END) AS null_sid_rows
        FROM referral_rewards
        WHERE level = 1
        GROUP BY referrer_id, referee_id, COALESCE(staking_id, -1), reward_date
      )
      SELECT
        COALESCE(SUM(CASE WHEN cnt > 1 THEN 1 ELSE 0 END), 0) AS violating_groups,
        COALESCE(SUM(CASE WHEN cnt > 1 THEN cnt ELSE 0 END), 0) AS total_violating_rows,
        COALESCE(SUM(CASE WHEN cnt > 1 THEN cnt - 1 ELSE 0 END), 0) AS excess_rows,
        COUNT(DISTINCT CASE WHEN cnt > 1 THEN referrer_id END) AS distinct_users,
        COALESCE(SUM(CASE WHEN cnt > 1 AND null_sid_rows = cnt THEN 1 ELSE 0 END), 0) AS legacy_null_staking_groups
      FROM grp
    `).first<any>()

    const rrL1Samples = await db.prepare(`
      SELECT referrer_id, referee_id,
             staking_id,
             reward_date,
             COUNT(*) AS cnt,
             MIN(id) AS keep_id,
             GROUP_CONCAT(id) AS all_ids,
             GROUP_CONCAT(reward_amount, '|') AS all_amounts,
             GROUP_CONCAT(original_amount, '|') AS all_originals,
             GROUP_CONCAT(strftime('%Y-%m-%d %H:%M:%S', created_at, '+9 hours'), '|') AS all_created
      FROM referral_rewards
      WHERE level = 1
      GROUP BY referrer_id, referee_id, COALESCE(staking_id, -1), reward_date
      HAVING COUNT(*) > 1
      ORDER BY cnt DESC, referrer_id, reward_date
      LIMIT 30
    `).all<any>()

    // ────────────────────────────────────────────
    // RR Level 2
    // ────────────────────────────────────────────
    const rrL2Stat = await db.prepare(`
      WITH grp AS (
        SELECT referrer_id, referee_id, COALESCE(staking_id, -1) AS sid, reward_date, COUNT(*) AS cnt,
               SUM(CASE WHEN staking_id IS NULL THEN 1 ELSE 0 END) AS null_sid_rows
        FROM referral_rewards
        WHERE level = 2
        GROUP BY referrer_id, referee_id, COALESCE(staking_id, -1), reward_date
      )
      SELECT
        COALESCE(SUM(CASE WHEN cnt > 1 THEN 1 ELSE 0 END), 0) AS violating_groups,
        COALESCE(SUM(CASE WHEN cnt > 1 THEN cnt ELSE 0 END), 0) AS total_violating_rows,
        COALESCE(SUM(CASE WHEN cnt > 1 THEN cnt - 1 ELSE 0 END), 0) AS excess_rows,
        COUNT(DISTINCT CASE WHEN cnt > 1 THEN referrer_id END) AS distinct_users,
        COALESCE(SUM(CASE WHEN cnt > 1 AND null_sid_rows = cnt THEN 1 ELSE 0 END), 0) AS legacy_null_staking_groups
      FROM grp
    `).first<any>()

    const rrL2Samples = await db.prepare(`
      SELECT referrer_id, referee_id,
             staking_id,
             reward_date,
             COUNT(*) AS cnt,
             MIN(id) AS keep_id,
             GROUP_CONCAT(id) AS all_ids,
             GROUP_CONCAT(reward_amount, '|') AS all_amounts,
             GROUP_CONCAT(original_amount, '|') AS all_originals,
             GROUP_CONCAT(strftime('%Y-%m-%d %H:%M:%S', created_at, '+9 hours'), '|') AS all_created
      FROM referral_rewards
      WHERE level = 2
      GROUP BY referrer_id, referee_id, COALESCE(staking_id, -1), reward_date
      HAVING COUNT(*) > 1
      ORDER BY cnt DESC, referrer_id, reward_date
      LIMIT 30
    `).all<any>()

    // ────────────────────────────────────────────
    // RR Level 0 (direct_referral): (referrer_id, referee_id, COALESCE(staking_id,-1)) — staking 별
    //   - 정책: 1 staking 승인 = 1건. staking 같으면 중복.
    //   - reward_date 와 무관 (1 staking = 1번만 직접추천 지급)
    // ────────────────────────────────────────────
    const rrL0Stat = await db.prepare(`
      WITH grp AS (
        SELECT referrer_id, referee_id, COALESCE(staking_id, -1) AS sid, COUNT(*) AS cnt,
               SUM(CASE WHEN staking_id IS NULL THEN 1 ELSE 0 END) AS null_sid_rows
        FROM referral_rewards
        WHERE level = 0
        GROUP BY referrer_id, referee_id, COALESCE(staking_id, -1)
      )
      SELECT
        COALESCE(SUM(CASE WHEN cnt > 1 THEN 1 ELSE 0 END), 0) AS violating_groups,
        COALESCE(SUM(CASE WHEN cnt > 1 THEN cnt ELSE 0 END), 0) AS total_violating_rows,
        COALESCE(SUM(CASE WHEN cnt > 1 THEN cnt - 1 ELSE 0 END), 0) AS excess_rows,
        COUNT(DISTINCT CASE WHEN cnt > 1 THEN referrer_id END) AS distinct_users,
        COALESCE(SUM(CASE WHEN cnt > 1 AND null_sid_rows = cnt THEN 1 ELSE 0 END), 0) AS legacy_null_staking_groups
      FROM grp
    `).first<any>()

    const rrL0Samples = await db.prepare(`
      SELECT referrer_id, referee_id,
             staking_id,
             COUNT(*) AS cnt,
             MIN(id) AS keep_id,
             GROUP_CONCAT(id) AS all_ids,
             GROUP_CONCAT(reward_amount, '|') AS all_amounts,
             GROUP_CONCAT(original_amount, '|') AS all_originals,
             GROUP_CONCAT(reward_date, '|') AS all_dates,
             GROUP_CONCAT(strftime('%Y-%m-%d %H:%M:%S', created_at, '+9 hours'), '|') AS all_created
      FROM referral_rewards
      WHERE level = 0
      GROUP BY referrer_id, referee_id, COALESCE(staking_id, -1)
      HAVING COUNT(*) > 1
      ORDER BY cnt DESC, referrer_id
      LIMIT 30
    `).all<any>()

    // RR 전체 정상성 진단
    const rrTotal = await db.prepare(`
      SELECT level,
             COUNT(*) AS total_rows,
             COALESCE(SUM(reward_amount), 0) AS total_amount,
             COALESCE(SUM(CASE WHEN staking_id IS NULL THEN 1 ELSE 0 END), 0) AS null_staking_rows,
             MIN(reward_date) AS min_date,
             MAX(reward_date) AS max_date
      FROM referral_rewards
      GROUP BY level
      ORDER BY level
    `).all<any>()

    const durMs = Date.now() - t0
    console.log(`[REWARD_BATCH] done action=scan-duplicate-dr-rr-v3 duration_ms=${durMs}`)

    return c.json({
      ok: true,
      mode: 'READ_ONLY_SCAN',
      action: 'scan-duplicate-dr-rr-v3',
      method: 'SET_BASED_BY_STAKING_ID',
      permanent_rule: '#스테이킹별독립 (2026-05-18)',
      no_per_row_exists: true,
      rule_keys: {
        daily_qkey: '(user_id, staking_id, reward_date) 당 1건',
        referral_reward_L0: '(referrer_id, referee_id, staking_id) 당 1건 — staking 승인 1회 = 1건',
        referral_reward_L1: '(referrer_id, referee_id, staking_id, reward_date, level=1) 당 1건',
        referral_reward_L2: '(referrer_id, referee_id, staking_id, reward_date, level=2) 당 1건',
        note_null_staking: 'staking_id NULL = 2026-05-13 migration 이전 legacy. COALESCE(staking_id,-1) 로 그룹핑 → NULL 끼리는 같은 그룹'
      },
      summary: {
        daily_rewards: {
          violating_groups: Number(drStat?.violating_groups || 0),
          total_violating_rows: Number(drStat?.total_violating_rows || 0),
          excess_rows_to_delete: Number(drStat?.excess_rows || 0),
          distinct_users: Number(drStat?.distinct_users || 0),
          null_staking_groups_in_violations: Number(drStat?.null_staking_groups || 0),
          total_rows: Number(drTotal?.total_rows || 0),
          distinct_user_staking_date: Number(drTotal?.distinct_user_staking_date || 0),
          null_staking_rows_overall: Number(drTotal?.null_staking_rows || 0)
        },
        referral_rewards_level0: {
          violating_groups: Number(rrL0Stat?.violating_groups || 0),
          total_violating_rows: Number(rrL0Stat?.total_violating_rows || 0),
          excess_rows_to_delete: Number(rrL0Stat?.excess_rows || 0),
          distinct_users: Number(rrL0Stat?.distinct_users || 0),
          legacy_null_staking_groups: Number(rrL0Stat?.legacy_null_staking_groups || 0)
        },
        referral_rewards_level1: {
          violating_groups: Number(rrL1Stat?.violating_groups || 0),
          total_violating_rows: Number(rrL1Stat?.total_violating_rows || 0),
          excess_rows_to_delete: Number(rrL1Stat?.excess_rows || 0),
          distinct_users: Number(rrL1Stat?.distinct_users || 0),
          legacy_null_staking_groups: Number(rrL1Stat?.legacy_null_staking_groups || 0)
        },
        referral_rewards_level2: {
          violating_groups: Number(rrL2Stat?.violating_groups || 0),
          total_violating_rows: Number(rrL2Stat?.total_violating_rows || 0),
          excess_rows_to_delete: Number(rrL2Stat?.excess_rows || 0),
          distinct_users: Number(rrL2Stat?.distinct_users || 0),
          legacy_null_staking_groups: Number(rrL2Stat?.legacy_null_staking_groups || 0)
        },
        rr_total_by_level: (rrTotal?.results || []).map((r: any) => ({
          level: Number(r.level),
          total_rows: Number(r.total_rows),
          total_amount: Number(r.total_amount),
          null_staking_rows: Number(r.null_staking_rows),
          min_date: r.min_date,
          max_date: r.max_date
        }))
      },
      samples: {
        dr_duplicates: (drSamples?.results || []),
        rr_level0_violations: (rrL0Samples?.results || []),
        rr_level1_violations: (rrL1Samples?.results || []),
        rr_level2_violations: (rrL2Samples?.results || [])
      },
      duration_ms: durMs
    })
  } catch (error) {
    const durMs = Date.now() - t0
    console.error(`[REWARD_BATCH] ERROR action=scan-duplicate-dr-rr-v3 duration_ms=${durMs}`, error)
    return c.json({ error: String(error), duration_ms: durMs }, 500)
  }
})

// ============================================================
// /api/diag/scan-may15-status
// ----------------------------------------------------------------
// ★ 사장님 명령 (2026-05-18): 2026-05-15 기준 배당 → 2026-05-18 (월) 지급
//   영구룰 #익일처리: 15일(금) → 16일(토)/17일(일) skip → 18일(월) 지급
//   영구룰 #스테이킹별독립: staking 별 독립 진단
//
// 진단 항목 (READ-ONLY):
//   1. 2026-05-15 active 상태였던 staking 전체 (대상자 기준)
//   2. 이미 reward_date='2026-05-15' 으로 들어가 있는 dr/rr 현황 (이중지급 방지)
//   3. 남은 미지급 대상 (staking 별)
//   4. 16/17/18 기준 dr/rr 가 있다면 별도 경고 (영구룰 위반 가능성)
//
// 사용: GET /api/diag/scan-may15-status?key=ADMIN_PW
// ============================================================
app.get('/api/diag/scan-may15-status', async (c) => {
  const t0 = Date.now()
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  const db = c.env.DB

  const REWARD_DATE = '2026-05-15'

  try {
    console.log(`[DIVIDEND_BACKPAY] start scan-may15-status dividendDate=${REWARD_DATE} payoutDate=2026-05-18`)

    // 1. 2026-05-15 시점 active staking 전체
    const activeStakings = await db.prepare(`
      SELECT
        s.id AS staking_id,
        s.user_id,
        u.name AS nickname,
        u.email,
        s.amount,
        s.daily_rate,
        s.period_days,
        date(s.start_date, '+9 hours') AS start_kst,
        date(s.end_date, '+9 hours') AS end_kst,
        s.status,
        (SELECT COUNT(*) FROM daily_rewards dr WHERE dr.staking_id = s.id) AS rewarded_count_total,
        (SELECT COUNT(*) FROM daily_rewards dr WHERE dr.staking_id = s.id AND dr.reward_date = ?) AS rewarded_on_target,
        (SELECT MAX(reward_date) FROM daily_rewards WHERE staking_id = s.id) AS last_reward_date,
        (SELECT usdt_amount FROM daily_rewards WHERE staking_id = s.id AND reward_date = ? LIMIT 1) AS existing_amount
      FROM staking s
      LEFT JOIN users u ON u.id = s.user_id
      WHERE s.status IN ('active', 'capped')
        AND date(s.start_date, '+9 hours') <= ?
        AND date(s.end_date, '+9 hours') >= ?
      ORDER BY s.user_id ASC, s.id ASC
    `).bind(REWARD_DATE, REWARD_DATE, REWARD_DATE, REWARD_DATE).all<any>()

    const stakings = (activeStakings.results || []) as any[]

    // 2. dr 현황 (reward_date='2026-05-15')
    const drExist = await db.prepare(`
      SELECT
        COUNT(*) AS total_rows,
        COUNT(DISTINCT user_id) AS distinct_users,
        COUNT(DISTINCT staking_id) AS distinct_stakings,
        COALESCE(SUM(usdt_amount), 0) AS total_amount,
        MIN(paid_date) AS min_paid_date,
        MAX(paid_date) AS max_paid_date
      FROM daily_rewards
      WHERE reward_date = ?
    `).bind(REWARD_DATE).first<any>()

    // 3. rr 현황 (reward_date='2026-05-15')
    const rrExist = await db.prepare(`
      SELECT
        level,
        COUNT(*) AS total_rows,
        COUNT(DISTINCT referrer_id) AS distinct_referrers,
        COALESCE(SUM(reward_amount), 0) AS total_amount,
        MIN(paid_date) AS min_paid_date,
        MAX(paid_date) AS max_paid_date
      FROM referral_rewards
      WHERE reward_date = ?
      GROUP BY level
      ORDER BY level
    `).bind(REWARD_DATE).all<any>()

    // 4. 16/17/18 reward_date 가 있다면 경고 (영구룰 위반)
    const wrongDates = await db.prepare(`
      SELECT reward_date, COUNT(*) AS cnt, COALESCE(SUM(usdt_amount), 0) AS total_amount
      FROM daily_rewards
      WHERE reward_date IN ('2026-05-16', '2026-05-17', '2026-05-18')
      GROUP BY reward_date
      ORDER BY reward_date
    `).all<any>()

    const wrongRRDates = await db.prepare(`
      SELECT reward_date, level, COUNT(*) AS cnt, COALESCE(SUM(reward_amount), 0) AS total_amount
      FROM referral_rewards
      WHERE reward_date IN ('2026-05-16', '2026-05-17', '2026-05-18')
      GROUP BY reward_date, level
      ORDER BY reward_date, level
    `).all<any>()

    // 5. 미지급 대상자 산출 (스테이킹 별)
    const pending: any[] = []
    const alreadyPaid: any[] = []
    const userMap = new Map<number, { uid: number, nickname: string, email: string, stakings: any[] }>()

    for (const s of stakings) {
      const uid = Number(s.user_id)
      const sid = Number(s.staking_id)
      const amount = Number(s.amount) || 0
      const rate = Number(s.daily_rate) || 0
      const expectedQkey = Math.round(amount * rate * 150)
      const alreadyOnTarget = Number(s.rewarded_on_target) > 0

      const stakeInfo = {
        staking_id: sid,
        amount,
        daily_rate: rate,
        expected_qkey: expectedQkey,
        existing_amount: s.existing_amount != null ? Number(s.existing_amount) : null,
        last_reward_date: s.last_reward_date,
        start_kst: s.start_kst,
        end_kst: s.end_kst,
        status: s.status,
        already_paid: alreadyOnTarget
      }

      if (!userMap.has(uid)) {
        userMap.set(uid, {
          uid,
          nickname: s.nickname || '',
          email: s.email || '',
          stakings: []
        })
      }
      userMap.get(uid)!.stakings.push(stakeInfo)

      if (alreadyOnTarget) {
        alreadyPaid.push({ user_id: uid, staking_id: sid, existing_amount: stakeInfo.existing_amount })
      } else {
        pending.push({ user_id: uid, staking_id: sid, expected_qkey: expectedQkey, amount, rate })
      }
    }

    // 사용자별 합산 (DR 기준)
    const userSummary = Array.from(userMap.values()).map(u => ({
      user_id: u.uid,
      nickname: u.nickname,
      email: u.email,
      staking_count: u.stakings.length,
      pending_stakings: u.stakings.filter(s => !s.already_paid).length,
      paid_stakings: u.stakings.filter(s => s.already_paid).length,
      expected_dr_total: u.stakings.filter(s => !s.already_paid).reduce((acc, s) => acc + s.expected_qkey, 0),
      stakings: u.stakings
    })).sort((a, b) => a.user_id - b.user_id)

    const distinctUserCount = userMap.size
    const pendingUserCount = userSummary.filter(u => u.pending_stakings > 0).length
    const allPaidUserCount = userSummary.filter(u => u.pending_stakings === 0).length

    const totalExpectedDR = pending.reduce((acc, p) => acc + p.expected_qkey, 0)

    const durMs = Date.now() - t0
    console.log(`[DIVIDEND_BACKPAY] scan-may15-status done duration_ms=${durMs} active_stakings=${stakings.length} pending=${pending.length} alreadyPaid=${alreadyPaid.length}`)

    return c.json({
      ok: true,
      mode: 'READ_ONLY_SCAN',
      action: 'scan-may15-status',
      dividendDate: REWARD_DATE,
      payoutDate: '2026-05-18',
      businessDayRule: 'next_business_day',
      summary: {
        active_stakings_on_target: stakings.length,
        distinct_users: distinctUserCount,
        pending_users: pendingUserCount,
        all_paid_users: allPaidUserCount,
        pending_stakings: pending.length,
        already_paid_stakings: alreadyPaid.length,
        expected_dr_total_qkey: totalExpectedDR
      },
      existing_dr_on_2026_05_15: {
        total_rows: Number(drExist?.total_rows || 0),
        distinct_users: Number(drExist?.distinct_users || 0),
        distinct_stakings: Number(drExist?.distinct_stakings || 0),
        total_amount: Number(drExist?.total_amount || 0),
        paid_date_range: { min: drExist?.min_paid_date, max: drExist?.max_paid_date }
      },
      existing_rr_on_2026_05_15: (rrExist?.results || []).map((r: any) => ({
        level: Number(r.level),
        total_rows: Number(r.total_rows),
        distinct_referrers: Number(r.distinct_referrers),
        total_amount: Number(r.total_amount),
        paid_date_range: { min: r.min_paid_date, max: r.max_paid_date }
      })),
      WARNING_wrong_dates_dr: (wrongDates?.results || []).map((w: any) => ({
        reward_date: w.reward_date,
        rows: Number(w.cnt),
        amount: Number(w.total_amount)
      })),
      WARNING_wrong_dates_rr: (wrongRRDates?.results || []).map((w: any) => ({
        reward_date: w.reward_date,
        level: Number(w.level),
        rows: Number(w.cnt),
        amount: Number(w.total_amount)
      })),
      users_pending: userSummary.filter(u => u.pending_stakings > 0),
      users_all_paid: userSummary.filter(u => u.pending_stakings === 0).slice(0, 20),
      duration_ms: durMs
    })
  } catch (error) {
    const durMs = Date.now() - t0
    console.error(`[DIVIDEND_BACKPAY] ERROR scan-may15-status duration_ms=${durMs}`, error)
    return c.json({ error: String(error), duration_ms: durMs }, 500)
  }
})

// ============================================================
// /api/diag/scan-may18-residue
// ----------------------------------------------------------------
// ★ 사장님 명령 (2026-05-18, 추가):
//   "15일에 찍힌건 14일치 확정배당이다. 오늘 수동실행 잔재가 있다면 18일로 찍혀있는 것들을 제거하라.
//    15일자는 그대로 두고, 16/17일 잔재도 청소. 그 후 18일자로 15일배당 바텀업 재실행."
//
// 진단 (READ-ONLY):
//   - 2026-05-16, 2026-05-17, 2026-05-18 의 reward_date 잔재
//   - 2026-05-16, 2026-05-17, 2026-05-18 의 paid_date 잔재 (reward_date 가 그 외인 경우)
//   - 영향 사용자, 잔고 영향액
//   - 대응 transactions 추출
// ============================================================
app.get('/api/diag/scan-may18-residue', async (c) => {
  const t0 = Date.now()
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  const db = c.env.DB

  const TARGET_DATES = ['2026-05-16', '2026-05-17', '2026-05-18']

  try {
    console.log(`[DIVIDEND_BACKPAY] start scan-may18-residue target_dates=${TARGET_DATES.join(',')}`)

    // 1. DR 잔재 (reward_date 기준)
    const drByRewardDate = await db.prepare(`
      SELECT
        reward_date,
        COUNT(*) AS cnt,
        COUNT(DISTINCT user_id) AS distinct_users,
        COUNT(DISTINCT staking_id) AS distinct_stakings,
        COALESCE(SUM(usdt_amount), 0) AS total_amount,
        MIN(id) AS min_id, MAX(id) AS max_id,
        MIN(paid_date) AS min_paid, MAX(paid_date) AS max_paid
      FROM daily_rewards
      WHERE reward_date IN ('2026-05-16', '2026-05-17', '2026-05-18')
      GROUP BY reward_date
      ORDER BY reward_date
    `).all<any>()

    // 2. DR 잔재 (paid_date 기준이지만 reward_date 가 16~18 아닌 경우 — 즉 정상 reward_date 인데 잘못된 paid_date 만 가진 case)
    const drWrongPaidDate = await db.prepare(`
      SELECT
        paid_date,
        COUNT(*) AS cnt,
        COUNT(DISTINCT user_id) AS distinct_users,
        COALESCE(SUM(usdt_amount), 0) AS total_amount,
        GROUP_CONCAT(DISTINCT reward_date) AS reward_dates
      FROM daily_rewards
      WHERE paid_date IN ('2026-05-16', '2026-05-17', '2026-05-18')
        AND reward_date NOT IN ('2026-05-16', '2026-05-17', '2026-05-18')
      GROUP BY paid_date
      ORDER BY paid_date
    `).all<any>()

    // 3. RR 잔재 (reward_date 기준)
    const rrByRewardDate = await db.prepare(`
      SELECT
        reward_date,
        level,
        COUNT(*) AS cnt,
        COUNT(DISTINCT referrer_id) AS distinct_referrers,
        COALESCE(SUM(reward_amount), 0) AS total_amount,
        MIN(id) AS min_id, MAX(id) AS max_id,
        MIN(paid_date) AS min_paid, MAX(paid_date) AS max_paid
      FROM referral_rewards
      WHERE reward_date IN ('2026-05-16', '2026-05-17', '2026-05-18')
      GROUP BY reward_date, level
      ORDER BY reward_date, level
    `).all<any>()

    // 4. RR 잘못된 paid_date
    const rrWrongPaidDate = await db.prepare(`
      SELECT
        paid_date,
        level,
        COUNT(*) AS cnt,
        COALESCE(SUM(reward_amount), 0) AS total_amount,
        GROUP_CONCAT(DISTINCT reward_date) AS reward_dates
      FROM referral_rewards
      WHERE paid_date IN ('2026-05-16', '2026-05-17', '2026-05-18')
        AND reward_date NOT IN ('2026-05-16', '2026-05-17', '2026-05-18')
      GROUP BY paid_date, level
      ORDER BY paid_date, level
    `).all<any>()

    // 5. 청소 대상 DR 샘플 (reward_date 16/17/18)
    const drSamples = await db.prepare(`
      SELECT id, user_id, staking_id, usdt_amount, reward_date, paid_date,
             strftime('%Y-%m-%d %H:%M:%S', created_at, '+9 hours') AS created_kst
      FROM daily_rewards
      WHERE reward_date IN ('2026-05-16', '2026-05-17', '2026-05-18')
      ORDER BY id DESC
      LIMIT 50
    `).all<any>()

    // 6. 청소 대상 RR 샘플
    const rrSamples = await db.prepare(`
      SELECT id, referrer_id, referee_id, level, original_amount, reward_amount,
             reward_date, paid_date, staking_id,
             strftime('%Y-%m-%d %H:%M:%S', created_at, '+9 hours') AS created_kst
      FROM referral_rewards
      WHERE reward_date IN ('2026-05-16', '2026-05-17', '2026-05-18')
      ORDER BY id DESC
      LIMIT 50
    `).all<any>()

    // 7. 대응 transactions (ref_id 매칭)
    const txDrMatch = await db.prepare(`
      SELECT COUNT(*) AS cnt, COALESCE(SUM(t.amount), 0) AS total_amount,
             COUNT(DISTINCT t.user_id) AS distinct_users
      FROM transactions t
      INNER JOIN daily_rewards dr ON t.ref_id = CAST(dr.id AS TEXT)
      WHERE t.type = 'daily_qkey'
        AND dr.reward_date IN ('2026-05-16', '2026-05-17', '2026-05-18')
    `).first<any>()

    const txRrMatch = await db.prepare(`
      SELECT COUNT(*) AS cnt, COALESCE(SUM(t.amount), 0) AS total_amount,
             COUNT(DISTINCT t.user_id) AS distinct_users
      FROM transactions t
      INNER JOIN referral_rewards rr ON t.ref_id = CAST(rr.id AS TEXT)
      WHERE t.type = 'referral_reward'
        AND rr.reward_date IN ('2026-05-16', '2026-05-17', '2026-05-18')
    `).first<any>()

    // 8. 사용자별 잔고 영향 (예상 차감액)
    const userImpact = await db.prepare(`
      WITH dr_impact AS (
        SELECT user_id, COALESCE(SUM(usdt_amount), 0) AS total
        FROM daily_rewards
        WHERE reward_date IN ('2026-05-16', '2026-05-17', '2026-05-18')
        GROUP BY user_id
      ),
      rr_impact AS (
        SELECT referrer_id AS user_id, COALESCE(SUM(reward_amount), 0) AS total
        FROM referral_rewards
        WHERE reward_date IN ('2026-05-16', '2026-05-17', '2026-05-18')
        GROUP BY referrer_id
      ),
      combined AS (
        SELECT user_id, total FROM dr_impact
        UNION ALL
        SELECT user_id, total FROM rr_impact
      )
      SELECT
        c.user_id,
        u.name AS nickname,
        u.qkey_balance AS current_balance,
        SUM(c.total) AS total_to_revert,
        u.qkey_balance - SUM(c.total) AS post_revert_balance
      FROM combined c
      LEFT JOIN users u ON u.id = c.user_id
      GROUP BY c.user_id
      ORDER BY total_to_revert DESC
    `).all<any>()

    const durMs = Date.now() - t0
    console.log(`[DIVIDEND_BACKPAY] scan-may18-residue done duration_ms=${durMs}`)

    return c.json({
      ok: true,
      mode: 'READ_ONLY_SCAN',
      action: 'scan-may18-residue',
      target_dates: TARGET_DATES,
      summary: {
        dr_residue: (drByRewardDate?.results || []).map((r: any) => ({
          reward_date: r.reward_date,
          rows: Number(r.cnt),
          distinct_users: Number(r.distinct_users),
          distinct_stakings: Number(r.distinct_stakings),
          total_amount: Number(r.total_amount),
          id_range: { min: Number(r.min_id), max: Number(r.max_id) },
          paid_date_range: { min: r.min_paid, max: r.max_paid }
        })),
        dr_wrong_paid_date: (drWrongPaidDate?.results || []).map((r: any) => ({
          paid_date: r.paid_date,
          rows: Number(r.cnt),
          distinct_users: Number(r.distinct_users),
          total_amount: Number(r.total_amount),
          reward_dates: r.reward_dates
        })),
        rr_residue: (rrByRewardDate?.results || []).map((r: any) => ({
          reward_date: r.reward_date,
          level: Number(r.level),
          rows: Number(r.cnt),
          distinct_referrers: Number(r.distinct_referrers),
          total_amount: Number(r.total_amount),
          id_range: { min: Number(r.min_id), max: Number(r.max_id) },
          paid_date_range: { min: r.min_paid, max: r.max_paid }
        })),
        rr_wrong_paid_date: (rrWrongPaidDate?.results || []).map((r: any) => ({
          paid_date: r.paid_date,
          level: Number(r.level),
          rows: Number(r.cnt),
          total_amount: Number(r.total_amount),
          reward_dates: r.reward_dates
        })),
        tx_dr_matched: {
          rows: Number(txDrMatch?.cnt || 0),
          total_amount: Number(txDrMatch?.total_amount || 0),
          distinct_users: Number(txDrMatch?.distinct_users || 0)
        },
        tx_rr_matched: {
          rows: Number(txRrMatch?.cnt || 0),
          total_amount: Number(txRrMatch?.total_amount || 0),
          distinct_users: Number(txRrMatch?.distinct_users || 0)
        }
      },
      user_balance_impact: (userImpact?.results || []).map((r: any) => ({
        user_id: Number(r.user_id),
        nickname: r.nickname,
        current_balance: Number(r.current_balance),
        total_to_revert: Number(r.total_to_revert),
        post_revert_balance: Number(r.post_revert_balance),
        will_go_negative: Number(r.post_revert_balance) < 0
      })),
      samples: {
        dr_residue_samples: (drSamples?.results || []),
        rr_residue_samples: (rrSamples?.results || [])
      },
      duration_ms: durMs
    })
  } catch (error) {
    const durMs = Date.now() - t0
    console.error(`[DIVIDEND_BACKPAY] ERROR scan-may18-residue duration_ms=${durMs}`, error)
    return c.json({ error: String(error), duration_ms: durMs }, 500)
  }
})

// ============================================================
// /api/diag/fix-may15-to-may14-label
// ----------------------------------------------------------------
// ★ 사장님 명령 (2026-05-18, 옵션 A):
//   "기존 reward_date=2026-05-15 인 dr 56건 + rr 12건은 사실 14일치 확정 배당이다.
//    reward_date 를 2026-05-14 로 UPDATE 하라 (paid_date 는 그대로)."
//
// 영구룰 #중복지급금지:
//   - 금액 변동 없음 (잔고 손대지 않음)
//   - INSERT/DELETE 없음 — 오직 UPDATE
//   - set-based (개별 row 루프 없음)
//   - DRY_RUN 먼저, confirm=GO 로 EXEC
//   - 사전: 2026-05-14 에 이미 동일 키 row 가 있는지 확인 (충돌 방지)
//   - 사후: 검증 + DR 56 + RR 12 = 68건 일치 확인
//
// 사용:
//   GET  /api/diag/fix-may15-to-may14-label?key=ADMIN_PW                  → DRY_RUN
//   POST /api/diag/fix-may15-to-may14-label?key=ADMIN_PW&confirm=GO       → EXEC
// ============================================================
const OLD_DATE = '2026-05-15'
const NEW_DATE = '2026-05-14'

async function diagFixMay15ToMay14(c: any, mode: 'DRY_RUN' | 'EXEC') {
  const t0 = Date.now()
  const db = c.env.DB

  try {
    console.log(`[DIVIDEND_BACKPAY] start fix-may15-to-may14-label mode=${mode} OLD=${OLD_DATE} NEW=${NEW_DATE}`)

    // ─── PRE-CHECK 1: 대상 row 수 확정 ───
    const drCount = await db.prepare(`
      SELECT COUNT(*) AS cnt, COALESCE(SUM(usdt_amount),0) AS total_amt,
             COUNT(DISTINCT user_id) AS distinct_users,
             COUNT(DISTINCT staking_id) AS distinct_stakings
      FROM daily_rewards WHERE reward_date = ?
    `).bind(OLD_DATE).first<any>()

    const rrCount = await db.prepare(`
      SELECT level, COUNT(*) AS cnt, COALESCE(SUM(reward_amount),0) AS total_amt,
             COUNT(DISTINCT referrer_id) AS distinct_refs
      FROM referral_rewards WHERE reward_date = ?
      GROUP BY level ORDER BY level
    `).bind(OLD_DATE).all<any>()

    // ─── PRE-CHECK 2: 2026-05-14 에 이미 동일 (user_id, staking_id) DR 있는지 (충돌) ───
    const drConflict = await db.prepare(`
      SELECT COUNT(*) AS cnt
      FROM daily_rewards dr_old
      INNER JOIN daily_rewards dr_new
        ON dr_old.user_id = dr_new.user_id
       AND dr_old.staking_id = dr_new.staking_id
       AND dr_new.reward_date = ?
      WHERE dr_old.reward_date = ?
    `).bind(NEW_DATE, OLD_DATE).first<any>()

    // ─── PRE-CHECK 3: 2026-05-14 에 이미 동일 RR 키 있는지 (충돌) ───
    //   영구룰 #스테이킹별독립: (referrer_id, referee_id, COALESCE(staking_id,-1), reward_date, level)
    const rrConflict = await db.prepare(`
      SELECT COUNT(*) AS cnt
      FROM referral_rewards rr_old
      INNER JOIN referral_rewards rr_new
        ON rr_old.referrer_id = rr_new.referrer_id
       AND rr_old.referee_id = rr_new.referee_id
       AND COALESCE(rr_old.staking_id, -1) = COALESCE(rr_new.staking_id, -1)
       AND rr_old.level = rr_new.level
       AND rr_new.reward_date = ?
      WHERE rr_old.reward_date = ?
    `).bind(NEW_DATE, OLD_DATE).first<any>()

    // ─── PRE-CHECK 4: 14일자 기존 row 현황 (참고) ───
    const drExistingOn14 = await db.prepare(`
      SELECT COUNT(*) AS cnt FROM daily_rewards WHERE reward_date = ?
    `).bind(NEW_DATE).first<any>()
    const rrExistingOn14 = await db.prepare(`
      SELECT COUNT(*) AS cnt FROM referral_rewards WHERE reward_date = ?
    `).bind(NEW_DATE).first<any>()

    const drCountN = Number(drCount?.cnt || 0)
    const rrL1 = (rrCount?.results || []).find((r: any) => Number(r.level) === 1)
    const rrL2 = (rrCount?.results || []).find((r: any) => Number(r.level) === 2)
    const rrL0 = (rrCount?.results || []).find((r: any) => Number(r.level) === 0)
    const drConflictN = Number(drConflict?.cnt || 0)
    const rrConflictN = Number(rrConflict?.cnt || 0)

    const preCheckPassed = drConflictN === 0 && rrConflictN === 0

    // 사장님 예상치 검증
    const expected_dr = 56
    const expected_rr_l1 = 6
    const expected_rr_l2 = 6
    const dr_matches_expected = drCountN === expected_dr
    const rr_l1_matches = Number(rrL1?.cnt || 0) === expected_rr_l1
    const rr_l2_matches = Number(rrL2?.cnt || 0) === expected_rr_l2

    const baseReport = {
      mode,
      action: 'fix-may15-to-may14-label',
      OLD_DATE,
      NEW_DATE,
      target: {
        dr: {
          rows: drCountN,
          total_amount: Number(drCount?.total_amt || 0),
          distinct_users: Number(drCount?.distinct_users || 0),
          distinct_stakings: Number(drCount?.distinct_stakings || 0),
          matches_expected_56: dr_matches_expected
        },
        rr: (rrCount?.results || []).map((r: any) => ({
          level: Number(r.level),
          rows: Number(r.cnt),
          total_amount: Number(r.total_amt),
          distinct_referrers: Number(r.distinct_refs)
        })),
        rr_l0_rows: Number(rrL0?.cnt || 0),
        rr_l1_rows: Number(rrL1?.cnt || 0),
        rr_l1_matches_expected_6: rr_l1_matches,
        rr_l2_rows: Number(rrL2?.cnt || 0),
        rr_l2_matches_expected_6: rr_l2_matches,
        total_rows_to_update: drCountN + Number(rrL1?.cnt || 0) + Number(rrL2?.cnt || 0) + Number(rrL0?.cnt || 0)
      },
      pre_check: {
        passed: preCheckPassed,
        dr_conflict_on_2026_05_14: drConflictN,
        rr_conflict_on_2026_05_14: rrConflictN,
        existing_dr_on_2026_05_14: Number(drExistingOn14?.cnt || 0),
        existing_rr_on_2026_05_14: Number(rrExistingOn14?.cnt || 0),
        note: drConflictN > 0 || rrConflictN > 0
          ? '🚫 충돌 있음 — UPDATE 시 영구룰 #스테이킹별독립 위반 (같은 키 2개)'
          : '✅ 충돌 없음 — UPDATE 안전'
      }
    }

    if (mode === 'DRY_RUN') {
      const durMs = Date.now() - t0
      console.log(`[DIVIDEND_BACKPAY] DRY_RUN done duration_ms=${durMs}`)
      return c.json({
        ok: true,
        ...baseReport,
        will_execute: 'UPDATE 2 statements (DR + RR), set-based, paid_date 미변경, 잔고 미변경',
        next_action: preCheckPassed
          ? 'GO 보내시면 EXEC (POST ?confirm=GO)'
          : '🚫 충돌 있음 → 사장님 결정 필요',
        duration_ms: durMs
      })
    }

    // ─── EXEC 분기 ───
    if (!preCheckPassed) {
      const durMs = Date.now() - t0
      console.error(`[DIVIDEND_BACKPAY] STOP — pre_check failed (conflict)`)
      return c.json({
        ok: false,
        stopped: true,
        reason: '영구룰 #스테이킹별독립 충돌 — 사전 검증 실패',
        ...baseReport,
        duration_ms: durMs
      }, 400)
    }

    // 안전 가드: 사장님 예상치와 너무 다르면 STOP
    if (drCountN > 100 || drCountN < 30) {
      const durMs = Date.now() - t0
      console.error(`[DIVIDEND_BACKPAY] STOP — DR row count out of expected range (got ${drCountN}, expected ~56)`)
      return c.json({
        ok: false,
        stopped: true,
        reason: `영구룰 #중복지급금지 — DR row 수 이상치 (${drCountN}, 예상 ~56)`,
        ...baseReport,
        duration_ms: durMs
      }, 400)
    }

    // ─── set-based UPDATE (2 statements, db.batch) ───
    console.log(`[DIVIDEND_BACKPAY] EXEC starting set-based UPDATE`)

    const updateDr = db.prepare(`
      UPDATE daily_rewards SET reward_date = ? WHERE reward_date = ?
    `).bind(NEW_DATE, OLD_DATE)

    const updateRr = db.prepare(`
      UPDATE referral_rewards SET reward_date = ? WHERE reward_date = ?
    `).bind(NEW_DATE, OLD_DATE)

    const batchResults = await db.batch([updateDr, updateRr])
    const drUpdated = Number((batchResults[0] as any)?.meta?.changes || 0)
    const rrUpdated = Number((batchResults[1] as any)?.meta?.changes || 0)

    console.log(`[DIVIDEND_BACKPAY] EXEC done — dr_updated=${drUpdated} rr_updated=${rrUpdated}`)

    // ─── POST-CHECK: 결과 검증 ───
    const drAfter15 = await db.prepare(`SELECT COUNT(*) AS cnt FROM daily_rewards WHERE reward_date = ?`).bind(OLD_DATE).first<any>()
    const drAfter14 = await db.prepare(`SELECT COUNT(*) AS cnt FROM daily_rewards WHERE reward_date = ?`).bind(NEW_DATE).first<any>()
    const rrAfter15 = await db.prepare(`SELECT level, COUNT(*) AS cnt FROM referral_rewards WHERE reward_date = ? GROUP BY level`).bind(OLD_DATE).all<any>()
    const rrAfter14 = await db.prepare(`SELECT level, COUNT(*) AS cnt FROM referral_rewards WHERE reward_date = ? GROUP BY level`).bind(NEW_DATE).all<any>()

    const durMs = Date.now() - t0
    console.log(`[DIVIDEND_BACKPAY] EXEC fully done duration_ms=${durMs}`)

    return c.json({
      ok: true,
      ...baseReport,
      exec_result: {
        dr_updated: drUpdated,
        rr_updated: rrUpdated,
        total_updated: drUpdated + rrUpdated,
        dr_updated_matches_target: drUpdated === drCountN,
        rr_updated_matches_target: rrUpdated === (Number(rrL0?.cnt || 0) + Number(rrL1?.cnt || 0) + Number(rrL2?.cnt || 0))
      },
      post_check: {
        dr_remaining_on_2026_05_15: Number(drAfter15?.cnt || 0),
        dr_now_on_2026_05_14: Number(drAfter14?.cnt || 0),
        rr_remaining_on_2026_05_15: (rrAfter15?.results || []).map((r: any) => ({ level: Number(r.level), rows: Number(r.cnt) })),
        rr_now_on_2026_05_14: (rrAfter14?.results || []).map((r: any) => ({ level: Number(r.level), rows: Number(r.cnt) })),
        verified: Number(drAfter15?.cnt || 0) === 0
      },
      duration_ms: durMs
    })
  } catch (error) {
    const durMs = Date.now() - t0
    console.error(`[DIVIDEND_BACKPAY] ERROR fix-may15-to-may14-label duration_ms=${durMs}`, error)
    return c.json({ error: String(error), duration_ms: durMs }, 500)
  }
}

app.get('/api/diag/fix-may15-to-may14-label', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  return diagFixMay15ToMay14(c, 'DRY_RUN')
})

app.post('/api/diag/fix-may15-to-may14-label', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  const confirm = c.req.query('confirm') || ''
  if (confirm !== 'GO') return c.json({ error: 'confirm=GO 필요 (실 UPDATE 게이트)' }, 400)
  return diagFixMay15ToMay14(c, 'EXEC')
})

// ============================================================
// /api/diag/scan-may14-vs-may15
// ----------------------------------------------------------------
// ★ 사장님 STEP 1 DRY-RUN 충돌 발견 후 추가 진단:
//   14일과 15일 양쪽에 DR 가 56건씩 있음 — 정확한 현황 파악
//
// READ-ONLY. 두 날짜의 DR 을 staking_id 별 1:1 매칭 비교.
// ============================================================
app.get('/api/diag/scan-may14-vs-may15', async (c) => {
  const t0 = Date.now()
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  const db = c.env.DB

  try {
    // 14일 vs 15일 staking_id 별 비교
    const compare = await db.prepare(`
      WITH d14 AS (
        SELECT user_id, staking_id, id AS dr_id, usdt_amount, paid_date,
               strftime('%Y-%m-%d %H:%M:%S', created_at, '+9 hours') AS created_kst
        FROM daily_rewards WHERE reward_date = '2026-05-14'
      ),
      d15 AS (
        SELECT user_id, staking_id, id AS dr_id, usdt_amount, paid_date,
               strftime('%Y-%m-%d %H:%M:%S', created_at, '+9 hours') AS created_kst
        FROM daily_rewards WHERE reward_date = '2026-05-15'
      )
      SELECT
        COALESCE(d14.user_id, d15.user_id) AS user_id,
        COALESCE(d14.staking_id, d15.staking_id) AS staking_id,
        d14.dr_id AS d14_id, d14.usdt_amount AS d14_amount, d14.paid_date AS d14_paid, d14.created_kst AS d14_created,
        d15.dr_id AS d15_id, d15.usdt_amount AS d15_amount, d15.paid_date AS d15_paid, d15.created_kst AS d15_created,
        CASE
          WHEN d14.dr_id IS NULL THEN 'ONLY_15'
          WHEN d15.dr_id IS NULL THEN 'ONLY_14'
          WHEN d14.usdt_amount = d15.usdt_amount THEN 'BOTH_SAME_AMOUNT'
          ELSE 'BOTH_DIFFERENT'
        END AS pattern
      FROM d14
      FULL OUTER JOIN d15 ON d14.user_id = d15.user_id AND d14.staking_id = d15.staking_id
      ORDER BY user_id, staking_id
    `).all<any>().catch(async () => {
      // SQLite full outer join 미지원 → UNION 으로 폴리필
      return await db.prepare(`
        WITH d14 AS (
          SELECT user_id, staking_id, id AS dr_id, usdt_amount, paid_date,
                 strftime('%Y-%m-%d %H:%M:%S', created_at, '+9 hours') AS created_kst
          FROM daily_rewards WHERE reward_date = '2026-05-14'
        ),
        d15 AS (
          SELECT user_id, staking_id, id AS dr_id, usdt_amount, paid_date,
                 strftime('%Y-%m-%d %H:%M:%S', created_at, '+9 hours') AS created_kst
          FROM daily_rewards WHERE reward_date = '2026-05-15'
        )
        SELECT
          d14.user_id, d14.staking_id,
          d14.dr_id AS d14_id, d14.usdt_amount AS d14_amount, d14.paid_date AS d14_paid, d14.created_kst AS d14_created,
          d15.dr_id AS d15_id, d15.usdt_amount AS d15_amount, d15.paid_date AS d15_paid, d15.created_kst AS d15_created,
          CASE
            WHEN d15.dr_id IS NULL THEN 'ONLY_14'
            WHEN d14.usdt_amount = d15.usdt_amount THEN 'BOTH_SAME_AMOUNT'
            ELSE 'BOTH_DIFFERENT'
          END AS pattern
        FROM d14
        LEFT JOIN d15 ON d14.user_id = d15.user_id AND d14.staking_id = d15.staking_id

        UNION ALL

        SELECT
          d15.user_id, d15.staking_id,
          NULL AS d14_id, NULL AS d14_amount, NULL AS d14_paid, NULL AS d14_created,
          d15.dr_id AS d15_id, d15.usdt_amount AS d15_amount, d15.paid_date AS d15_paid, d15.created_kst AS d15_created,
          'ONLY_15' AS pattern
        FROM d15
        LEFT JOIN d14 ON d14.user_id = d15.user_id AND d14.staking_id = d15.staking_id
        WHERE d14.dr_id IS NULL

        ORDER BY user_id, staking_id
      `).all<any>()
    })

    const rows = compare?.results || []

    const patternCount: any = { BOTH_SAME_AMOUNT: 0, BOTH_DIFFERENT: 0, ONLY_14: 0, ONLY_15: 0 }
    for (const r of rows) patternCount[r.pattern] = (patternCount[r.pattern] || 0) + 1

    // 14일과 15일 양쪽 created_at 시간대 분석
    const d14CreatedRange = await db.prepare(`
      SELECT MIN(strftime('%Y-%m-%d %H:%M:%S', created_at, '+9 hours')) AS min_created,
             MAX(strftime('%Y-%m-%d %H:%M:%S', created_at, '+9 hours')) AS max_created,
             MIN(paid_date) AS min_paid, MAX(paid_date) AS max_paid,
             COUNT(*) AS cnt, COALESCE(SUM(usdt_amount), 0) AS total_amt
      FROM daily_rewards WHERE reward_date = '2026-05-14'
    `).first<any>()

    const d15CreatedRange = await db.prepare(`
      SELECT MIN(strftime('%Y-%m-%d %H:%M:%S', created_at, '+9 hours')) AS min_created,
             MAX(strftime('%Y-%m-%d %H:%M:%S', created_at, '+9 hours')) AS max_created,
             MIN(paid_date) AS min_paid, MAX(paid_date) AS max_paid,
             COUNT(*) AS cnt, COALESCE(SUM(usdt_amount), 0) AS total_amt
      FROM daily_rewards WHERE reward_date = '2026-05-15'
    `).first<any>()

    return c.json({
      ok: true,
      action: 'scan-may14-vs-may15',
      pattern_count: patternCount,
      total_rows: rows.length,
      d14_overview: {
        rows: Number(d14CreatedRange?.cnt || 0),
        total_amount: Number(d14CreatedRange?.total_amt || 0),
        created_range_kst: { min: d14CreatedRange?.min_created, max: d14CreatedRange?.max_created },
        paid_date_range: { min: d14CreatedRange?.min_paid, max: d14CreatedRange?.max_paid }
      },
      d15_overview: {
        rows: Number(d15CreatedRange?.cnt || 0),
        total_amount: Number(d15CreatedRange?.total_amt || 0),
        created_range_kst: { min: d15CreatedRange?.min_created, max: d15CreatedRange?.max_created },
        paid_date_range: { min: d15CreatedRange?.min_paid, max: d15CreatedRange?.max_paid }
      },
      samples_first_30: rows.slice(0, 30),
      duration_ms: Date.now() - t0
    })
  } catch (error) {
    return c.json({ error: String(error), duration_ms: Date.now() - t0 }, 500)
  }
})

// ============================================================
// /api/diag/scan-date-shift-range
// ----------------------------------------------------------------
// ★ 사장님 명령 (2026-05-18):
//   "15일은 14일꺼, 14일은 13일치, 하나씩 줄이면 된다."
//
// 모든 reward_date 를 -1일 시프트해야 정상 상태가 됨.
// 시프트 범위 확인 (가장 오래된 reward_date 까지).
// READ-ONLY.
// ============================================================
app.get('/api/diag/scan-date-shift-range', async (c) => {
  const t0 = Date.now()
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  const db = c.env.DB

  try {
    // 1. DR 모든 reward_date 별 row 수
    const drByDate = await db.prepare(`
      SELECT reward_date,
             COUNT(*) AS cnt,
             COUNT(DISTINCT user_id) AS distinct_users,
             COUNT(DISTINCT staking_id) AS distinct_stakings,
             COALESCE(SUM(usdt_amount), 0) AS total_amount,
             MIN(strftime('%Y-%m-%d %H:%M:%S', created_at, '+9 hours')) AS min_created,
             MAX(strftime('%Y-%m-%d %H:%M:%S', created_at, '+9 hours')) AS max_created
      FROM daily_rewards
      GROUP BY reward_date
      ORDER BY reward_date
    `).all<any>()

    // 2. RR 모든 reward_date 별 row 수 (level별)
    const rrByDate = await db.prepare(`
      SELECT reward_date, level,
             COUNT(*) AS cnt,
             COUNT(DISTINCT referrer_id) AS distinct_refs,
             COALESCE(SUM(reward_amount), 0) AS total_amount
      FROM referral_rewards
      GROUP BY reward_date, level
      ORDER BY reward_date, level
    `).all<any>()

    // 3. 가장 오래된 reward_date 확인 (시프트 시 안전한 시작점)
    const drMinDate = await db.prepare(`SELECT MIN(reward_date) AS d FROM daily_rewards`).first<any>()
    const drMaxDate = await db.prepare(`SELECT MAX(reward_date) AS d FROM daily_rewards`).first<any>()
    const rrMinDate = await db.prepare(`SELECT MIN(reward_date) AS d FROM referral_rewards`).first<any>()
    const rrMaxDate = await db.prepare(`SELECT MAX(reward_date) AS d FROM referral_rewards`).first<any>()

    // 4. 시프트 후 충돌 검증 — 가장 오래된 날짜의 하루 전이 비어있는지
    //    DR 가장 오래된 날짜 = drMinDate.d → 시프트 후 = date(drMinDate.d, '-1 day')
    //    그 새 날짜에 이미 row 가 있으면 시프트 충돌
    const drShiftConflict = await db.prepare(`
      WITH all_dates AS (
        SELECT DISTINCT reward_date FROM daily_rewards
      ),
      shifted AS (
        SELECT reward_date, date(reward_date, '-1 day') AS new_date FROM all_dates
      )
      SELECT s.reward_date AS old_date, s.new_date,
             (SELECT COUNT(*) FROM daily_rewards WHERE reward_date = s.new_date) AS rows_on_new_date
      FROM shifted s
      WHERE s.new_date NOT IN (SELECT reward_date FROM all_dates)
      ORDER BY s.reward_date
    `).all<any>()

    // 5. transactions ref_id 매칭 통계
    const txDrCount = await db.prepare(`
      SELECT COUNT(*) AS cnt FROM transactions
      WHERE type = 'daily_qkey' AND ref_id IS NOT NULL
    `).first<any>()
    const txRrCount = await db.prepare(`
      SELECT COUNT(*) AS cnt FROM transactions
      WHERE type = 'referral_reward' AND ref_id IS NOT NULL
    `).first<any>()

    return c.json({
      ok: true,
      action: 'scan-date-shift-range',
      shift_plan: 'reward_date 를 -1일 시프트 (15→14, 14→13, 13→12, ...)',
      dr_summary: {
        min_date: drMinDate?.d,
        max_date: drMaxDate?.d,
        distinct_dates: (drByDate?.results || []).length,
        total_rows: (drByDate?.results || []).reduce((a: number, r: any) => a + Number(r.cnt), 0),
        total_amount: (drByDate?.results || []).reduce((a: number, r: any) => a + Number(r.total_amount), 0),
        rows_per_date: (drByDate?.results || []).map((r: any) => ({
          reward_date: r.reward_date,
          rows: Number(r.cnt),
          distinct_users: Number(r.distinct_users),
          distinct_stakings: Number(r.distinct_stakings),
          total_amount: Number(r.total_amount),
          created_kst_range: { min: r.min_created, max: r.max_created }
        }))
      },
      rr_summary: {
        min_date: rrMinDate?.d,
        max_date: rrMaxDate?.d,
        distinct_dates: new Set((rrByDate?.results || []).map((r: any) => r.reward_date)).size,
        total_rows: (rrByDate?.results || []).reduce((a: number, r: any) => a + Number(r.cnt), 0),
        rows_per_date_level: (rrByDate?.results || []).map((r: any) => ({
          reward_date: r.reward_date,
          level: Number(r.level),
          rows: Number(r.cnt),
          distinct_referrers: Number(r.distinct_refs),
          total_amount: Number(r.total_amount)
        }))
      },
      shift_pre_check_dr: {
        first_safe_shift_target: drShiftConflict?.results?.[0] || null,
        note: 'shift 시 가장 오래된 reward_date 의 -1일 자리가 비어 있는지 확인'
      },
      tx_overall: {
        daily_qkey_tx_rows: Number(txDrCount?.cnt || 0),
        referral_reward_tx_rows: Number(txRrCount?.cnt || 0),
        note: 'transactions 는 ref_id 로 dr/rr 와 매핑됨. reward_date 만 UPDATE 하면 tx 영향 없음 (ref_id 그대로)'
      },
      duration_ms: Date.now() - t0
    })
  } catch (error) {
    return c.json({ error: String(error), duration_ms: Date.now() - t0 }, 500)
  }
})

// ============================================================
// /api/diag/scan-paid-date-distribution
// ----------------------------------------------------------------
// ★ 사장님 질문 (2026-05-18): "13일꺼 배당을 언제하지?"
//   영구룰 #익일처리: 13일(수) → 14일(목) 지급, 14일(목) → 15일(금) 지급
//   현재 reward_date 시프트 -1일 작업 전, paid_date 분포를 확인하여
//   시프트 후 영구룰 #익일처리 적합성 검증 가능 여부 진단.
//
// READ-ONLY.
// ============================================================
app.get('/api/diag/scan-paid-date-distribution', async (c) => {
  const t0 = Date.now()
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  const db = c.env.DB

  try {
    // DR (reward_date, paid_date) 분포
    const drMatrix = await db.prepare(`
      SELECT reward_date, paid_date,
             COUNT(*) AS cnt,
             COALESCE(SUM(usdt_amount), 0) AS total_amount
      FROM daily_rewards
      GROUP BY reward_date, paid_date
      ORDER BY reward_date, paid_date
    `).all<any>()

    // RR (reward_date, paid_date, level) 분포
    const rrMatrix = await db.prepare(`
      SELECT reward_date, paid_date, level,
             COUNT(*) AS cnt,
             COALESCE(SUM(reward_amount), 0) AS total_amount
      FROM referral_rewards
      GROUP BY reward_date, paid_date, level
      ORDER BY reward_date, paid_date, level
    `).all<any>()

    // DR paid_date NULL 갯수
    const drNullPaid = await db.prepare(`SELECT COUNT(*) AS cnt FROM daily_rewards WHERE paid_date IS NULL`).first<any>()
    const rrNullPaid = await db.prepare(`SELECT COUNT(*) AS cnt FROM referral_rewards WHERE paid_date IS NULL`).first<any>()

    // 시프트 후 (-1일) 영구룰 #익일처리 검증 시뮬레이션
    // 시프트 후 reward_date 별로 적합한 paid_date 가 있어야 함
    //   - 수/목/월/화 → 다음날 paid
    //   - 금 → 다음 월요일 paid
    //   - 토/일 → 배당 없어야 함

    return c.json({
      ok: true,
      action: 'scan-paid-date-distribution',
      reward_dates_explained: {
        '2026-05-13 (Wed)': 'paid 2026-05-14 (Thu) — 영구룰 #익일처리',
        '2026-05-14 (Thu)': 'paid 2026-05-15 (Fri) — 영구룰 #익일처리',
        '2026-05-15 (Fri)': 'paid 2026-05-18 (Mon) — 영구룰 #익일처리 + 휴일',
        '2026-05-16 (Sat)': '배당 없음 (휴일)',
        '2026-05-17 (Sun)': '배당 없음 (휴일)'
      },
      dr_matrix: (drMatrix?.results || []).map((r: any) => ({
        reward_date: r.reward_date,
        paid_date: r.paid_date,
        rows: Number(r.cnt),
        total_amount: Number(r.total_amount)
      })),
      rr_matrix: (rrMatrix?.results || []).map((r: any) => ({
        reward_date: r.reward_date,
        paid_date: r.paid_date,
        level: Number(r.level),
        rows: Number(r.cnt),
        total_amount: Number(r.total_amount)
      })),
      dr_null_paid: Number(drNullPaid?.cnt || 0),
      rr_null_paid: Number(rrNullPaid?.cnt || 0),
      duration_ms: Date.now() - t0
    })
  } catch (error) {
    return c.json({ error: String(error), duration_ms: Date.now() - t0 }, 500)
  }
})

// ============================================================
// /api/diag/shift-reward-dates-minus-1d
// ----------------------------------------------------------------
// ★ 사장님 명령 (2026-05-18):
//   "15일은 14일꺼, 14일은 13일치, 하나씩 줄이면 된다."
//   현재 모든 reward_date 가 +1일 잘못 라벨링됨.
//   set-based UPDATE 로 -1일 시프트:
//     UPDATE daily_rewards    SET reward_date = date(reward_date, '-1 day')
//     UPDATE referral_rewards SET reward_date = date(reward_date, '-1 day')
//
// 영구룰 #중복지급금지:
//   - 금액 변동 0 (잔고 미변경)
//   - INSERT/DELETE 0 (UPDATE only)
//   - paid_date 미변경 (이미 정확함)
//   - transactions 미변경 (ref_id 그대로)
//   - set-based 2 statements + db.batch
//   - DRY-RUN/EXEC 분리
//   - 사전: 가장 오래된 reward_date 의 -1일 자리가 비어있는지 확인
//   - 사후: 전체 row count 일치 + 5/15 자리 비어있는지 검증
//
// 사용:
//   GET  /api/diag/shift-reward-dates-minus-1d?key=ADMIN_PW              → DRY_RUN
//   POST /api/diag/shift-reward-dates-minus-1d?key=ADMIN_PW&confirm=GO   → EXEC
// ============================================================
async function diagShiftRewardDates(c: any, mode: 'DRY_RUN' | 'EXEC') {
  const t0 = Date.now()
  const db = c.env.DB

  try {
    console.log(`[DIVIDEND_BACKPAY] start shift-reward-dates-minus-1d mode=${mode}`)

    // ─── PRE-CHECK 1: 시프트 전 전체 분포 ───
    const drTotalBefore = await db.prepare(`
      SELECT COUNT(*) AS cnt,
             COALESCE(SUM(usdt_amount),0) AS total_amount,
             MIN(reward_date) AS min_date,
             MAX(reward_date) AS max_date,
             COUNT(DISTINCT reward_date) AS distinct_dates
      FROM daily_rewards
    `).first<any>()

    const rrTotalBefore = await db.prepare(`
      SELECT COUNT(*) AS cnt,
             COALESCE(SUM(reward_amount),0) AS total_amount,
             MIN(reward_date) AS min_date,
             MAX(reward_date) AS max_date,
             COUNT(DISTINCT reward_date) AS distinct_dates
      FROM referral_rewards
    `).first<any>()

    // ─── PRE-CHECK 2: 시프트 후 자리 (가장 오래된 reward_date 의 -1일) 가 비어있는지 ───
    //   set-based UPDATE 이라 전체가 동시에 -1되어 충돌 없음. 단 가장 오래된 시작점 검증.
    const drMinShift = await db.prepare(`
      SELECT date(MIN(reward_date), '-1 day') AS new_min_date,
             (SELECT COUNT(*) FROM daily_rewards WHERE reward_date = date((SELECT MIN(reward_date) FROM daily_rewards), '-1 day')) AS rows_already_there
      FROM daily_rewards
    `).first<any>()

    const rrMinShift = await db.prepare(`
      SELECT date(MIN(reward_date), '-1 day') AS new_min_date,
             (SELECT COUNT(*) FROM referral_rewards WHERE reward_date = date((SELECT MIN(reward_date) FROM referral_rewards), '-1 day')) AS rows_already_there
      FROM referral_rewards
    `).first<any>()

    // ─── PRE-CHECK 3: 시프트 후 5/15 자리가 정확히 비게 되는지 확인 ───
    //   현재 5/15 reward_date 의 row 갯수가 시프트 후 5/14 자리로 이동
    //   현재 5/16 reward_date 가 0건이어야 시프트 후 5/15 가 비게 됨
    const dr_5_16_before = await db.prepare(`SELECT COUNT(*) AS cnt FROM daily_rewards WHERE reward_date = '2026-05-16'`).first<any>()
    const rr_5_16_before = await db.prepare(`SELECT COUNT(*) AS cnt FROM referral_rewards WHERE reward_date = '2026-05-16'`).first<any>()
    const dr_5_15_before = await db.prepare(`SELECT COUNT(*) AS cnt FROM daily_rewards WHERE reward_date = '2026-05-15'`).first<any>()

    // ─── PRE-CHECK 4: 영구룰 #익일처리 검증 시뮬레이션 (시프트 후 reward_date vs 현재 paid_date) ───
    //   시프트 후 reward_date+1일 (또는 +다음영업일) 이 paid_date 와 일치해야 정상
    const businessDayCheck = await db.prepare(`
      WITH simulated AS (
        SELECT date(reward_date, '-1 day') AS new_reward_date,
               reward_date AS old_reward_date,
               paid_date,
               COUNT(*) AS cnt,
               COALESCE(SUM(usdt_amount), 0) AS amt
        FROM daily_rewards
        WHERE paid_date IS NOT NULL
        GROUP BY date(reward_date, '-1 day'), reward_date, paid_date
      )
      SELECT new_reward_date, old_reward_date, paid_date, cnt, amt,
             CASE
               WHEN paid_date = date(new_reward_date, '+1 day') THEN 'NEXT_DAY_OK'
               WHEN paid_date > date(new_reward_date, '+1 day') THEN 'HOLIDAY_SKIP_OK_OR_DELAYED'
               ELSE 'MISMATCH'
             END AS status
      FROM simulated
      ORDER BY new_reward_date
    `).all<any>()

    // ─── PRE-CHECK 5: 16/17/18 잔재 절대 없음 재확인 ───
    const wrongDates = await db.prepare(`
      SELECT reward_date, COUNT(*) AS cnt FROM daily_rewards
      WHERE reward_date IN ('2026-05-16', '2026-05-17', '2026-05-18')
      GROUP BY reward_date
    `).all<any>()

    const drCntBefore = Number(drTotalBefore?.cnt || 0)
    const rrCntBefore = Number(rrTotalBefore?.cnt || 0)
    const drMinSafe = Number(drMinShift?.rows_already_there || 0) === 0
    const rrMinSafe = Number(rrMinShift?.rows_already_there || 0) === 0
    const _16_clean = Number(dr_5_16_before?.cnt || 0) === 0 && Number(rr_5_16_before?.cnt || 0) === 0
    const preCheckPassed = drMinSafe && rrMinSafe && _16_clean && (wrongDates?.results || []).length === 0

    const baseReport = {
      mode,
      action: 'shift-reward-dates-minus-1d',
      shift_rule: 'reward_date → date(reward_date, "-1 day") [set-based, 모든 row 동시 시프트]',
      preserves: ['paid_date', 'usdt_amount/reward_amount', 'user_id', 'staking_id', 'transactions', 'qkey_balance'],
      before: {
        dr: {
          rows: drCntBefore,
          total_amount: Number(drTotalBefore?.total_amount || 0),
          date_range: { min: drTotalBefore?.min_date, max: drTotalBefore?.max_date },
          distinct_dates: Number(drTotalBefore?.distinct_dates || 0)
        },
        rr: {
          rows: rrCntBefore,
          total_amount: Number(rrTotalBefore?.total_amount || 0),
          date_range: { min: rrTotalBefore?.min_date, max: rrTotalBefore?.max_date },
          distinct_dates: Number(rrTotalBefore?.distinct_dates || 0)
        }
      },
      shift_simulation_after: {
        dr: {
          new_min_date: drMinShift?.new_min_date,
          new_max_date: '2026-05-14',  // 현재 max 2026-05-15 → 시프트 후 2026-05-14
          empty_slot_for_new_dividend: '2026-05-15 (이후 새 15일 배당 INSERT 자리)'
        },
        rr: {
          new_min_date: rrMinShift?.new_min_date,
          new_max_date: '2026-05-14'
        }
      },
      pre_check: {
        passed: preCheckPassed,
        dr_min_shift_target_empty: drMinSafe,
        dr_new_min_date: drMinShift?.new_min_date,
        dr_rows_already_at_new_min: Number(drMinShift?.rows_already_there || 0),
        rr_min_shift_target_empty: rrMinSafe,
        rr_new_min_date: rrMinShift?.new_min_date,
        rr_rows_already_at_new_min: Number(rrMinShift?.rows_already_there || 0),
        date_5_16_clean: _16_clean,
        dr_5_16: Number(dr_5_16_before?.cnt || 0),
        rr_5_16: Number(rr_5_16_before?.cnt || 0),
        dr_5_15_will_become_5_14: Number(dr_5_15_before?.cnt || 0),
        wrong_dates_residue: (wrongDates?.results || []).map((w: any) => ({
          reward_date: w.reward_date,
          rows: Number(w.cnt)
        })),
        note: preCheckPassed
          ? '✅ 모든 사전 검증 통과 — 시프트 안전'
          : '🚫 사전 검증 실패 — STOP'
      },
      business_day_simulation_top20: (businessDayCheck?.results || []).slice(0, 25).map((r: any) => ({
        new_reward_date: r.new_reward_date,
        old_reward_date: r.old_reward_date,
        paid_date: r.paid_date,
        rows: Number(r.cnt),
        amount: Number(r.amt),
        status: r.status
      }))
    }

    if (mode === 'DRY_RUN') {
      const durMs = Date.now() - t0
      console.log(`[DIVIDEND_BACKPAY] DRY_RUN done duration_ms=${durMs} pre_check_passed=${preCheckPassed}`)
      return c.json({
        ok: true,
        ...baseReport,
        will_execute: 'UPDATE 2 statements (DR + RR), set-based, db.batch',
        next_action: preCheckPassed
          ? 'POST + confirm=GO 보내시면 EXEC. 새 5/15 배당은 별도 STEP 2 에서 진행.'
          : '🚫 사전 검증 실패 → 사장님 결정 필요',
        duration_ms: durMs
      })
    }

    // ─── EXEC ───
    if (!preCheckPassed) {
      const durMs = Date.now() - t0
      console.error(`[DIVIDEND_BACKPAY] STOP — pre_check failed`)
      return c.json({
        ok: false,
        stopped: true,
        reason: '사전 검증 실패 — STOP per #중복지급금지',
        ...baseReport,
        duration_ms: durMs
      }, 400)
    }

    // 안전 가드: row 수 이상치 검증
    if (drCntBefore < 100 || drCntBefore > 1000) {
      const durMs = Date.now() - t0
      console.error(`[DIVIDEND_BACKPAY] STOP — DR row count out of expected range (got ${drCntBefore})`)
      return c.json({
        ok: false,
        stopped: true,
        reason: `DR row 수 이상치 (${drCntBefore}, 예상 ~466)`,
        ...baseReport,
        duration_ms: durMs
      }, 400)
    }
    if (rrCntBefore < 100 || rrCntBefore > 1500) {
      const durMs = Date.now() - t0
      console.error(`[DIVIDEND_BACKPAY] STOP — RR row count out of expected range (got ${rrCntBefore})`)
      return c.json({
        ok: false,
        stopped: true,
        reason: `RR row 수 이상치 (${rrCntBefore})`,
        ...baseReport,
        duration_ms: durMs
      }, 400)
    }

    // ─── SET-BASED UPDATE (db.batch) ───
    console.log(`[DIVIDEND_BACKPAY] EXEC starting set-based UPDATE — dr=${drCntBefore} rr=${rrCntBefore}`)

    const updateDr = db.prepare(`
      UPDATE daily_rewards SET reward_date = date(reward_date, '-1 day')
    `)

    const updateRr = db.prepare(`
      UPDATE referral_rewards SET reward_date = date(reward_date, '-1 day')
    `)

    const batchResults = await db.batch([updateDr, updateRr])
    const drUpdated = Number((batchResults[0] as any)?.meta?.changes || 0)
    const rrUpdated = Number((batchResults[1] as any)?.meta?.changes || 0)

    console.log(`[DIVIDEND_BACKPAY] EXEC done dr_updated=${drUpdated} rr_updated=${rrUpdated}`)

    // ─── POST-CHECK ───
    const drAfter = await db.prepare(`
      SELECT COUNT(*) AS cnt, MIN(reward_date) AS min_d, MAX(reward_date) AS max_d
      FROM daily_rewards
    `).first<any>()
    const rrAfter = await db.prepare(`
      SELECT COUNT(*) AS cnt, MIN(reward_date) AS min_d, MAX(reward_date) AS max_d
      FROM referral_rewards
    `).first<any>()
    const dr_5_15_after = await db.prepare(`SELECT COUNT(*) AS cnt FROM daily_rewards WHERE reward_date = '2026-05-15'`).first<any>()
    const dr_5_14_after = await db.prepare(`SELECT COUNT(*) AS cnt FROM daily_rewards WHERE reward_date = '2026-05-14'`).first<any>()

    const drCountSame = Number(drAfter?.cnt || 0) === drCntBefore
    const rrCountSame = Number(rrAfter?.cnt || 0) === rrCntBefore
    const _5_15_empty = Number(dr_5_15_after?.cnt || 0) === 0
    const _5_14_has_old_5_15 = Number(dr_5_14_after?.cnt || 0) === Number(dr_5_15_before?.cnt || 0)

    const verified = drCountSame && rrCountSame && _5_15_empty && _5_14_has_old_5_15

    const durMs = Date.now() - t0
    console.log(`[DIVIDEND_BACKPAY] EXEC fully done duration_ms=${durMs} verified=${verified}`)

    return c.json({
      ok: true,
      ...baseReport,
      exec_result: {
        dr_updated: drUpdated,
        rr_updated: rrUpdated,
        total_updated: drUpdated + rrUpdated
      },
      post_check: {
        verified,
        dr_count_preserved: drCountSame,
        rr_count_preserved: rrCountSame,
        dr_count_before: drCntBefore,
        dr_count_after: Number(drAfter?.cnt || 0),
        rr_count_before: rrCntBefore,
        rr_count_after: Number(rrAfter?.cnt || 0),
        dr_date_range_after: { min: drAfter?.min_d, max: drAfter?.max_d },
        rr_date_range_after: { min: rrAfter?.min_d, max: rrAfter?.max_d },
        '5_15_now_empty': _5_15_empty,
        '5_15_remaining_rows': Number(dr_5_15_after?.cnt || 0),
        '5_14_received_old_5_15': _5_14_has_old_5_15,
        '5_14_rows_now': Number(dr_5_14_after?.cnt || 0),
        '5_15_rows_before_shift': Number(dr_5_15_before?.cnt || 0)
      },
      next_step: '✅ STEP 1 완료. 이제 STEP 2 (새 5/15 배당 바텀업 INSERT, paid_date=2026-05-18) 진행 가능.',
      duration_ms: durMs
    })
  } catch (error) {
    const durMs = Date.now() - t0
    console.error(`[DIVIDEND_BACKPAY] ERROR shift-reward-dates-minus-1d duration_ms=${durMs}`, error)
    return c.json({ error: String(error), duration_ms: durMs }, 500)
  }
}

app.get('/api/diag/shift-reward-dates-minus-1d', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  return diagShiftRewardDates(c, 'DRY_RUN')
})

app.post('/api/diag/shift-reward-dates-minus-1d', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  const confirm = c.req.query('confirm') || ''
  if (confirm !== 'GO') return c.json({ error: 'confirm=GO 필요 (실 UPDATE 게이트)' }, 400)
  return diagShiftRewardDates(c, 'EXEC')
})

// ============================================================================
// STEP 2: insert-may15-dividend
//   5/15 reward_date 새 배당 바텀업 INSERT
//   reward_date='2026-05-15', paid_date='2026-05-18' (16/17 휴일 skip)
//
//   영구룰 준수:
//   - #스테이킹별독립: (user_id, staking_id, reward_date) — staking 별 1건
//   - #배당계산: DR = amount × daily_rate × 150
//   - L1=20%, L2=10% (referee 의 staking 별 1건씩 별개)
//   - #바텀업정산: depth desc 정렬 (leaf → root)
//   - #익일처리: paid_date=2026-05-18 (16,17 휴일 skip → 월요일)
//   - #중복지급금지: 사전 EXISTS 체크 + 사후 검증
//
//   set-based 우선, db.batch() 트랜잭션, DRY-RUN/EXEC 분리, 30초 timeout 대비
//
//   GET  /api/diag/insert-may15-dividend?key=ADMIN_PW              → DRY_RUN
//   POST /api/diag/insert-may15-dividend?key=ADMIN_PW&confirm=GO   → EXEC
// ============================================================================
async function diagInsertMay15Dividend(c: any, mode: 'DRY_RUN' | 'EXEC') {
  const t0 = Date.now()
  try {
    console.log(`[DIVIDEND_BACKPAY] start insert-may15-dividend mode=${mode}`)
    const db = c.env.DB
    const USD_TO_QKEY = 150
    const REWARD_DATE = '2026-05-15'    // 발생일
    const PAID_DATE = '2026-05-18'      // 지급일 (16/17 휴일 skip → 월요일)

    // ─── PRE-CHECK A: 5/15 자리 비어있는지 (STEP 1 이후 0건이어야 함) ───
    const dr515Pre = await db.prepare(`
      SELECT COUNT(*) AS cnt FROM daily_rewards WHERE reward_date = ?
    `).bind(REWARD_DATE).first() as any
    const rr515Pre = await db.prepare(`
      SELECT COUNT(*) AS cnt FROM referral_rewards WHERE reward_date = ?
    `).bind(REWARD_DATE).first() as any
    const dr515PreCount = Number(dr515Pre?.cnt || 0)
    const rr515PreCount = Number(rr515Pre?.cnt || 0)

    // ─── PRE-CHECK B: paid_date=5/18 잔재 없는지 (이중 지급 방지) ───
    //   ★ level=0 (직접매출 10% 쿠키, L0) 제외 — L0 는 staking 승인 즉시 발생 (휴일 무관)
    //   우리가 INSERT 할 것은 DR + L1 + L2 (level 1, 2). L0 와 절대 충돌 안 함
    const dr518Pre = await db.prepare(`
      SELECT COUNT(*) AS cnt FROM daily_rewards WHERE paid_date = ?
    `).bind(PAID_DATE).first() as any
    const rr518Pre = await db.prepare(`
      SELECT COUNT(*) AS cnt FROM referral_rewards WHERE paid_date = ? AND level IN (1, 2)
    `).bind(PAID_DATE).first() as any
    const dr518PreCount = Number(dr518Pre?.cnt || 0)
    const rr518PreCount = Number(rr518Pre?.cnt || 0)

    const safetyChecks: any = {
      dr_5_15_already: dr515PreCount,
      rr_5_15_already: rr515PreCount,
      dr_paid_5_18_already: dr518PreCount,
      rr_paid_5_18_already: rr518PreCount,
      passed: dr515PreCount === 0 && rr515PreCount === 0 && dr518PreCount === 0 && rr518PreCount === 0,
    }

    if (!safetyChecks.passed) {
      return c.json({
        ok: false,
        mode,
        action: 'insert-may15-dividend',
        error: 'PRE-CHECK 실패 — 5/15 자리 또는 paid_date=5/18 에 이미 데이터 존재',
        safety_checks: safetyChecks,
        note: 'STEP 1 (shift -1d) 가 안 됐거나 이미 STEP 2 EXEC 된 가능성. DB 상태 재확인 필요.',
        duration_ms: Date.now() - t0,
      }, 400)
    }

    // ─── PHASE 1: 5/15 활성 staking 수집 ───
    //   reward_date=2026-05-15 기준 active staking
    //   start_date_kst <= 5/15 AND end_date_kst >= 5/15
    //   status = 'active' (capped/completed 제외)
    const stRows = await db.prepare(`
      SELECT
        s.user_id,
        s.id AS staking_id,
        s.amount,
        s.daily_rate,
        s.period_days,
        s.period_months,
        date(s.start_date, '+9 hours') AS start_kst,
        date(s.end_date, '+9 hours') AS end_kst,
        s.status,
        (SELECT COUNT(*) FROM daily_rewards WHERE staking_id = s.id) AS rewarded_count_total,
        (SELECT MAX(reward_date) FROM daily_rewards WHERE staking_id = s.id) AS last_reward_date
      FROM staking s
      WHERE s.status = 'active'
        AND date(s.start_date, '+9 hours') <= date(?)
        AND date(s.end_date, '+9 hours') >= date(?)
      ORDER BY s.user_id ASC, s.id ASC
    `).bind(REWARD_DATE, REWARD_DATE).all()
    const stakings = (stRows.results || []) as any[]

    if (stakings.length === 0) {
      return c.json({
        ok: true,
        mode,
        action: 'insert-may15-dividend',
        message: '5/15 활성 staking 없음 — 배당 대상 0건',
        duration_ms: Date.now() - t0,
      })
    }

    // ─── PHASE 2: 200% Cap 계산용 stake_total / paid_total ───
    const stakeTotalsRaw = await db.prepare(`
      SELECT user_id, COALESCE(SUM(amount), 0) AS total
      FROM staking WHERE status IN ('active','completed','capped')
      GROUP BY user_id
    `).all()
    const stakeTotalByUser = new Map<number, number>()
    for (const r of (stakeTotalsRaw.results || []) as any[]) {
      stakeTotalByUser.set(Number(r.user_id), Number(r.total) || 0)
    }
    const paidTotalsRaw = await db.prepare(`
      SELECT user_id, COALESCE(SUM(amount), 0) AS total
      FROM transactions
      WHERE coin_type = 'QKEY' AND type IN ('daily_qkey', 'referral_reward')
      GROUP BY user_id
    `).all()
    const paidTotalByUser = new Map<number, number>()
    for (const r of (paidTotalsRaw.results || []) as any[]) {
      paidTotalByUser.set(Number(r.user_id), Number(r.total) || 0)
    }
    const targetOf = (uid: number) => (stakeTotalByUser.get(uid) || 0) * 2 * USD_TO_QKEY
    const paidOf = (uid: number) => paidTotalByUser.get(uid) || 0
    const isCapped = (uid: number) => { const t = targetOf(uid); return t > 0 && paidOf(uid) >= t }
    const remainingOf = (uid: number) => Math.max(0, targetOf(uid) - paidOf(uid))
    const addPaid = (uid: number, amt: number) => { paidTotalByUser.set(uid, paidOf(uid) + amt) }

    // ─── PHASE 3: referrer 트리 + depth (bottom-up 정렬용) ───
    const usersRaw = await db.prepare(`SELECT id, referrer_id FROM users`).all()
    const referrerOf = new Map<number, number | null>()
    for (const u of (usersRaw.results || []) as any[]) {
      referrerOf.set(Number(u.id), u.referrer_id != null ? Number(u.referrer_id) : null)
    }
    const depthMemo = new Map<number, number>()
    function computeDepth(uid: number, stack: Set<number>): number {
      if (depthMemo.has(uid)) return depthMemo.get(uid)!
      if (stack.has(uid)) { depthMemo.set(uid, 0); return 0 }
      stack.add(uid)
      const rid = referrerOf.get(uid)
      if (rid == null) { depthMemo.set(uid, 0); stack.delete(uid); return 0 }
      const d = 1 + computeDepth(rid, stack)
      depthMemo.set(uid, d)
      stack.delete(uid)
      return d
    }
    for (const s of stakings) computeDepth(Number(s.user_id), new Set())

    // depth 내림차순 (leaf → root)
    stakings.sort((a, b) => {
      const da = depthMemo.get(Number(a.user_id)) || 0
      const db_ = depthMemo.get(Number(b.user_id)) || 0
      if (db_ !== da) return db_ - da
      if (Number(a.user_id) !== Number(b.user_id)) return Number(a.user_id) - Number(b.user_id)
      return Number(a.staking_id) - Number(b.staking_id)
    })

    // ─── PHASE 4: 본인 DR 계획 산출 (DRY-RUN/EXEC 공통) ───
    type DrPlan = {
      user_id: number, staking_id: number, amount: number, daily_rate: number,
      qkey_amount: number, capped: boolean, period_done: boolean,
      already_exists: boolean, depth: number,
    }
    const drPlans: DrPlan[] = []
    const cappedUsersSet = new Set<number>()
    let drExpectedTotal = 0
    let drSkippedCapped = 0
    let drSkippedPeriod = 0
    let drSkippedExists = 0

    for (const s of stakings) {
      const uid = Number(s.user_id)
      const sid = Number(s.staking_id)
      const amount = Number(s.amount) || 0
      const rate = Number(s.daily_rate) || 0
      const periodDays = Number(s.period_days) || (Number(s.period_months) * 30) || 0
      const rewardedTotal = Number(s.rewarded_count_total) || 0
      const depth = depthMemo.get(uid) || 0

      // 중복 가드: 같은 staking_id, 같은 reward_date 이미 있는지
      const exists = await db.prepare(`
        SELECT COUNT(*) AS cnt FROM daily_rewards
        WHERE user_id = ? AND staking_id = ? AND reward_date = ?
      `).bind(uid, sid, REWARD_DATE).first() as any
      const alreadyExists = Number(exists?.cnt || 0) > 0

      // 기간 완료 체크
      const periodDone = periodDays > 0 && rewardedTotal >= periodDays

      // 200% Cap 체크
      const capped = isCapped(uid)

      let qkeyAmount = 0
      if (!alreadyExists && !periodDone && !capped) {
        qkeyAmount = Math.round(amount * rate * USD_TO_QKEY)
        const remaining = remainingOf(uid)
        if (qkeyAmount > remaining) qkeyAmount = Math.max(0, Math.floor(remaining))
      }

      const plan: DrPlan = {
        user_id: uid, staking_id: sid, amount, daily_rate: rate,
        qkey_amount: qkeyAmount, capped, period_done: periodDone,
        already_exists: alreadyExists, depth,
      }
      drPlans.push(plan)

      if (alreadyExists) { drSkippedExists++; continue }
      if (periodDone) { drSkippedPeriod++; continue }
      if (capped || qkeyAmount <= 0) {
        drSkippedCapped++
        cappedUsersSet.add(uid)
        continue
      }

      drExpectedTotal += qkeyAmount
      addPaid(uid, qkeyAmount) // Cap 시뮬레이션 누적
    }

    const drToInsert = drPlans.filter(p => !p.already_exists && !p.period_done && !p.capped && p.qkey_amount > 0)

    // ─── PHASE 5: L1/L2 계획 산출 (자식 own_daily 확정 후 부모 매칭) ───
    type RrPlan = {
      level: 1 | 2,
      referrer_id: number, referee_id: number, referee_staking_id: number,
      original_amount: number, reward_amount: number,
      capped: boolean, already_exists: boolean, no_referrer: boolean, no_active_parent: boolean,
    }
    const rrPlans: RrPlan[] = []
    let l1ExpectedCount = 0, l1ExpectedTotal = 0
    let l2ExpectedCount = 0, l2ExpectedTotal = 0
    let l1SkippedExists = 0, l2SkippedExists = 0
    let l1SkippedNoParent = 0, l2SkippedNoParent = 0
    let l1SkippedCapped = 0, l2SkippedCapped = 0

    for (const dr of drToInsert) {
      const childUid = dr.user_id
      const childOwn = dr.qkey_amount
      const childSid = dr.staking_id

      const parentId = referrerOf.get(childUid)
      if (parentId == null) {
        // L1/L2 둘 다 skip
        continue
      }

      // ── L1 ──
      const parentActive = await db.prepare(`
        SELECT id FROM staking
        WHERE user_id = ? AND status = 'active'
          AND date(start_date, '+9 hours') <= date(?)
          AND date(end_date, '+9 hours') >= date(?)
        LIMIT 1
      `).bind(parentId, REWARD_DATE, REWARD_DATE).first()

      if (!parentActive) {
        l1SkippedNoParent++
      } else {
        // 중복 가드 (staking_id 인식)
        const l1Exists = await db.prepare(`
          SELECT COUNT(*) AS cnt FROM referral_rewards
          WHERE referrer_id = ? AND referee_id = ? AND level = 1 AND reward_date = ?
            AND (staking_id = ? OR (staking_id IS NULL AND original_amount = ?))
        `).bind(parentId, childUid, REWARD_DATE, childSid, childOwn).first() as any
        if (Number(l1Exists?.cnt || 0) > 0) {
          l1SkippedExists++
        } else if (isCapped(parentId)) {
          l1SkippedCapped++
          cappedUsersSet.add(parentId)
        } else {
          let l1Reward = Math.round(childOwn * 0.20)
          const l1Remaining = remainingOf(parentId)
          if (l1Reward > l1Remaining) l1Reward = Math.max(0, Math.floor(l1Remaining))
          if (l1Reward <= 0) {
            l1SkippedCapped++
            cappedUsersSet.add(parentId)
          } else {
            rrPlans.push({
              level: 1, referrer_id: parentId, referee_id: childUid, referee_staking_id: childSid,
              original_amount: childOwn, reward_amount: l1Reward,
              capped: false, already_exists: false, no_referrer: false, no_active_parent: false,
            })
            l1ExpectedCount++
            l1ExpectedTotal += l1Reward
            addPaid(parentId, l1Reward)
          }
        }
      }

      // ── L2 ──
      const grandId = referrerOf.get(parentId)
      if (grandId == null) continue

      const grandActive = await db.prepare(`
        SELECT id FROM staking
        WHERE user_id = ? AND status = 'active'
          AND date(start_date, '+9 hours') <= date(?)
          AND date(end_date, '+9 hours') >= date(?)
        LIMIT 1
      `).bind(grandId, REWARD_DATE, REWARD_DATE).first()

      if (!grandActive) {
        l2SkippedNoParent++
      } else {
        const l2Exists = await db.prepare(`
          SELECT COUNT(*) AS cnt FROM referral_rewards
          WHERE referrer_id = ? AND referee_id = ? AND level = 2 AND reward_date = ?
            AND (staking_id = ? OR (staking_id IS NULL AND original_amount = ?))
        `).bind(grandId, childUid, REWARD_DATE, childSid, childOwn).first() as any
        if (Number(l2Exists?.cnt || 0) > 0) {
          l2SkippedExists++
        } else if (isCapped(grandId)) {
          l2SkippedCapped++
          cappedUsersSet.add(grandId)
        } else {
          let l2Reward = Math.round(childOwn * 0.10)
          const l2Remaining = remainingOf(grandId)
          if (l2Reward > l2Remaining) l2Reward = Math.max(0, Math.floor(l2Remaining))
          if (l2Reward <= 0) {
            l2SkippedCapped++
            cappedUsersSet.add(grandId)
          } else {
            rrPlans.push({
              level: 2, referrer_id: grandId, referee_id: childUid, referee_staking_id: childSid,
              original_amount: childOwn, reward_amount: l2Reward,
              capped: false, already_exists: false, no_referrer: false, no_active_parent: false,
            })
            l2ExpectedCount++
            l2ExpectedTotal += l2Reward
            addPaid(grandId, l2Reward)
          }
        }
      }
    }

    const grandExpectedTotal = drExpectedTotal + l1ExpectedTotal + l2ExpectedTotal

    // ─── 미리보기 ───
    const drSample = drToInsert.slice(0, 5).map(p => ({
      user_id: p.user_id, staking_id: p.staking_id, amount: p.amount,
      daily_rate: p.daily_rate, qkey_amount: p.qkey_amount, depth: p.depth,
    }))
    const rrSample = rrPlans.slice(0, 5).map(p => ({
      level: p.level, referrer_id: p.referrer_id, referee_id: p.referee_id,
      referee_staking_id: p.referee_staking_id,
      original_amount: p.original_amount, reward_amount: p.reward_amount,
    }))

    // ═══════════════ DRY-RUN 분기 ═══════════════
    if (mode === 'DRY_RUN') {
      return c.json({
        ok: true,
        mode: 'DRY_RUN',
        action: 'insert-may15-dividend',
        reward_date: REWARD_DATE,
        paid_date: PAID_DATE,
        rules_applied: [
          '#스테이킹별독립: (user_id, staking_id, reward_date) 기준',
          '#배당계산: DR = amount × daily_rate × 150',
          '#L1=20%, #L2=10% (referee staking 별 별개)',
          '#바텀업정산: depth desc 정렬',
          '#익일처리: paid_date=5/18 (16/17 휴일 skip → 월요일)',
          '#중복지급금지: staking_id 인식 EXISTS 가드',
        ],
        safety_checks: safetyChecks,
        scan: {
          total_active_stakings_on_5_15: stakings.length,
          dr_to_insert: drToInsert.length,
          dr_skipped_already_exists: drSkippedExists,
          dr_skipped_period_done: drSkippedPeriod,
          dr_skipped_capped: drSkippedCapped,
          dr_expected_total_qkey: drExpectedTotal,
          l1_expected_count: l1ExpectedCount,
          l1_expected_total_qkey: l1ExpectedTotal,
          l1_skipped_exists: l1SkippedExists,
          l1_skipped_no_active_parent: l1SkippedNoParent,
          l1_skipped_capped: l1SkippedCapped,
          l2_expected_count: l2ExpectedCount,
          l2_expected_total_qkey: l2ExpectedTotal,
          l2_skipped_exists: l2SkippedExists,
          l2_skipped_no_active_parent: l2SkippedNoParent,
          l2_skipped_capped: l2SkippedCapped,
          capped_users_count: cappedUsersSet.size,
          grand_total_qkey_to_pay: grandExpectedTotal,
        },
        dr_sample_top5: drSample,
        rr_sample_top5: rrSample,
        next_action: 'POST + confirm=GO 보내시면 EXEC 진행. set-based batch INSERT.',
        duration_ms: Date.now() - t0,
      })
    }

    // ═══════════════ EXEC 분기 ═══════════════
    // db.batch() 로 트랜잭션 단일 호출 — DR + Tx + balance UPDATE 동시 처리
    // 30초 timeout 대비: 청크 단위 처리 (한 청크당 약 100건)

    const CHUNK_SIZE = 80   // D1 batch 권장: 50~100 statements per call

    // ── DR INSERT 청크 ──
    let drInserted = 0
    let drInsertTotal = 0
    const drIdMap = new Map<string, number>() // key=`${uid}_${sid}` → dr_id
    // ★ Cloudflare D1 batch 는 last_row_id 가 결과에 포함됨

    for (let i = 0; i < drToInsert.length; i += CHUNK_SIZE) {
      const chunk = drToInsert.slice(i, i + CHUNK_SIZE)
      const stmts = chunk.map(p => db.prepare(`
        INSERT INTO daily_rewards (user_id, staking_id, usdt_amount, reward_date, paid_date)
        VALUES (?, ?, ?, ?, ?)
      `).bind(p.user_id, p.staking_id, p.qkey_amount, REWARD_DATE, PAID_DATE))
      const results = await db.batch(stmts)
      for (let j = 0; j < results.length; j++) {
        const r = results[j] as any
        const drId = r?.meta?.last_row_id
        if (drId != null) {
          drIdMap.set(`${chunk[j].user_id}_${chunk[j].staking_id}`, Number(drId))
          drInserted++
          drInsertTotal += chunk[j].qkey_amount
        }
      }
    }

    // ── DR balance UPDATE + Transactions INSERT (청크) ──
    let drTxInserted = 0
    for (let i = 0; i < drToInsert.length; i += CHUNK_SIZE) {
      const chunk = drToInsert.slice(i, i + CHUNK_SIZE)
      const stmts: any[] = []
      for (const p of chunk) {
        const drId = drIdMap.get(`${p.user_id}_${p.staking_id}`)
        if (!drId) continue
        // balance UPDATE
        stmts.push(db.prepare(`
          UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?
        `).bind(p.qkey_amount, p.user_id))
        // transactions INSERT
        stmts.push(db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
          VALUES (?, 'daily_qkey', 'QKEY', ?, ?, ?)
        `).bind(p.user_id, p.qkey_amount, '일일 배당 (QKEY)', drId))
      }
      if (stmts.length > 0) {
        await db.batch(stmts)
        drTxInserted += chunk.length
      }
    }

    // ── RR INSERT 청크 ──
    let rrInserted = 0
    let rrInsertTotalL1 = 0
    let rrInsertTotalL2 = 0
    const rrIdMap = new Map<number, number>() // index → rr_id

    for (let i = 0; i < rrPlans.length; i += CHUNK_SIZE) {
      const chunk = rrPlans.slice(i, i + CHUNK_SIZE)
      const stmts = chunk.map(p => db.prepare(`
        INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, staking_id)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
      `).bind(p.referrer_id, p.referee_id, p.level, p.original_amount, p.reward_amount, REWARD_DATE, PAID_DATE, p.referee_staking_id))
      const results = await db.batch(stmts)
      for (let j = 0; j < results.length; j++) {
        const r = results[j] as any
        const rrId = r?.meta?.last_row_id
        if (rrId != null) {
          rrIdMap.set(i + j, Number(rrId))
          rrInserted++
          if (chunk[j].level === 1) rrInsertTotalL1 += chunk[j].reward_amount
          else rrInsertTotalL2 += chunk[j].reward_amount
        }
      }
    }

    // ── RR balance UPDATE + Transactions INSERT (청크) ──
    let rrTxInserted = 0
    for (let i = 0; i < rrPlans.length; i += CHUNK_SIZE) {
      const chunk = rrPlans.slice(i, i + CHUNK_SIZE)
      const stmts: any[] = []
      for (let j = 0; j < chunk.length; j++) {
        const p = chunk[j]
        const rrId = rrIdMap.get(i + j)
        if (!rrId) continue
        // balance UPDATE
        stmts.push(db.prepare(`
          UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?
        `).bind(p.reward_amount, p.referrer_id))
        // transactions INSERT
        const desc = p.level === 1 ? '추천 보너스 (Level 1)' : '추천 보너스 (Level 2)'
        stmts.push(db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
          VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?)
        `).bind(p.referrer_id, p.reward_amount, desc, rrId))
      }
      if (stmts.length > 0) {
        await db.batch(stmts)
        rrTxInserted += chunk.length
      }
    }

    // ─── POST-CHECK ───
    const dr515Post = await db.prepare(`
      SELECT COUNT(*) AS cnt, COALESCE(SUM(usdt_amount), 0) AS total FROM daily_rewards WHERE reward_date = ?
    `).bind(REWARD_DATE).first() as any
    const rr515Post = await db.prepare(`
      SELECT COUNT(*) AS cnt, COALESCE(SUM(reward_amount), 0) AS total FROM referral_rewards WHERE reward_date = ?
    `).bind(REWARD_DATE).first() as any
    const rr515PostL1 = await db.prepare(`
      SELECT COUNT(*) AS cnt, COALESCE(SUM(reward_amount), 0) AS total FROM referral_rewards WHERE reward_date = ? AND level = 1
    `).bind(REWARD_DATE).first() as any
    const rr515PostL2 = await db.prepare(`
      SELECT COUNT(*) AS cnt, COALESCE(SUM(reward_amount), 0) AS total FROM referral_rewards WHERE reward_date = ? AND level = 2
    `).bind(REWARD_DATE).first() as any

    // 중복 검사 (영구룰 #스테이킹별독립)
    const drDups = await db.prepare(`
      SELECT user_id, staking_id, reward_date, COUNT(*) AS cnt
      FROM daily_rewards
      WHERE reward_date = ?
      GROUP BY user_id, staking_id, reward_date
      HAVING COUNT(*) > 1
    `).bind(REWARD_DATE).all()
    const rrDups = await db.prepare(`
      SELECT referrer_id, referee_id, staking_id, reward_date, level, COUNT(*) AS cnt
      FROM referral_rewards
      WHERE reward_date = ? AND staking_id IS NOT NULL
      GROUP BY referrer_id, referee_id, staking_id, reward_date, level
      HAVING COUNT(*) > 1
    `).bind(REWARD_DATE).all()

    const drDupCount = (drDups.results || []).length
    const rrDupCount = (rrDups.results || []).length

    return c.json({
      ok: drDupCount === 0 && rrDupCount === 0,
      mode: 'EXEC',
      action: 'insert-may15-dividend',
      reward_date: REWARD_DATE,
      paid_date: PAID_DATE,
      exec_result: {
        dr_inserted: drInserted,
        dr_total_qkey: drInsertTotal,
        dr_tx_inserted: drTxInserted,
        rr_inserted: rrInserted,
        rr_total_qkey_l1: rrInsertTotalL1,
        rr_total_qkey_l2: rrInsertTotalL2,
        rr_tx_inserted: rrTxInserted,
        grand_total_qkey: drInsertTotal + rrInsertTotalL1 + rrInsertTotalL2,
      },
      post_check: {
        dr_5_15_count_after: Number(dr515Post?.cnt || 0),
        dr_5_15_total_after: Number(dr515Post?.total || 0),
        rr_5_15_count_after: Number(rr515Post?.cnt || 0),
        rr_5_15_total_after: Number(rr515Post?.total || 0),
        rr_5_15_l1_count: Number(rr515PostL1?.cnt || 0),
        rr_5_15_l1_total: Number(rr515PostL1?.total || 0),
        rr_5_15_l2_count: Number(rr515PostL2?.cnt || 0),
        rr_5_15_l2_total: Number(rr515PostL2?.total || 0),
        dr_duplicates: drDupCount,
        rr_duplicates: rrDupCount,
        dr_duplicate_sample: (drDups.results || []).slice(0, 5),
        rr_duplicate_sample: (rrDups.results || []).slice(0, 5),
        verified: drDupCount === 0 && rrDupCount === 0,
      },
      duration_ms: Date.now() - t0,
    })

  } catch (error) {
    const durMs = Date.now() - t0
    console.error(`[DIVIDEND_BACKPAY] ERROR insert-may15-dividend duration_ms=${durMs}`, error)
    return c.json({ error: String(error), duration_ms: durMs }, 500)
  }
}

app.get('/api/diag/insert-may15-dividend', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  return diagInsertMay15Dividend(c, 'DRY_RUN')
})

app.post('/api/diag/insert-may15-dividend', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  const confirm = c.req.query('confirm') || ''
  if (confirm !== 'GO') return c.json({ error: 'confirm=GO 필요 (실 INSERT 게이트)' }, 400)
  return diagInsertMay15Dividend(c, 'EXEC')
})

// ============================================================================
// scan-user-may15-dividend: 특정 사용자의 5/15 배당 예상치 상세 조회
//   READ-ONLY scan — DB 변경 0
//   ?user=44 (또는 ?email=...)
// ============================================================================
app.get('/api/diag/scan-user-may15-dividend', async (c) => {
  const t0 = Date.now()
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)

    const userQ = c.req.query('user') || ''
    const emailQ = c.req.query('email') || ''
    if (!userQ && !emailQ) return c.json({ error: 'user=ID 또는 email=... 필요' }, 400)

    const db = c.env.DB
    // ★ 2026-05-18 일반화: dividendDate / payoutDate 쿼리 파라미터로 받음
    //   기본값은 5/14 / 5/15 (이번 reverse-backfill 작업 기준)
    const REWARD_DATE = c.req.query('dividendDate') || '2026-05-14'
    const PAID_DATE = c.req.query('payoutDate') || '2026-05-15'
    const USD_TO_QKEY = 150

    // ─── 사용자 찾기 ───
    let userRow: any
    if (userQ) {
      userRow = await db.prepare(`SELECT id, name, email, referrer_id FROM users WHERE id = ?`).bind(userQ).first()
    } else {
      userRow = await db.prepare(`SELECT id, name, email, referrer_id FROM users WHERE email = ?`).bind(emailQ).first()
    }
    if (!userRow) return c.json({ error: 'user not found' }, 404)
    const uid = Number(userRow.id)

    // ─── 1. 본인 5/15 active staking ───
    const ownStakings = await db.prepare(`
      SELECT id, amount, daily_rate, period_days, period_months,
             date(start_date,'+9 hours') AS start_kst,
             date(end_date,'+9 hours') AS end_kst, status
      FROM staking
      WHERE user_id = ? AND status = 'active'
        AND date(start_date,'+9 hours') <= date(?)
        AND date(end_date,'+9 hours') >= date(?)
      ORDER BY id
    `).bind(uid, REWARD_DATE, REWARD_DATE).all()
    const myStakings = (ownStakings.results || []) as any[]

    let ownDailyTotal = 0
    const ownBreakdown = myStakings.map((s: any) => {
      const amt = Number(s.amount) || 0
      const rate = Number(s.daily_rate) || 0
      const qkey = Math.round(amt * rate * USD_TO_QKEY)
      ownDailyTotal += qkey
      return {
        staking_id: s.id, amount: amt, daily_rate: rate,
        formula: `${amt} × ${rate} × ${USD_TO_QKEY} = ${qkey}`,
        qkey_amount: qkey,
      }
    })

    // ─── 2. L1 (내가 직접 추천한 사람들의 5/15 own_daily × 20%) ───
    //    referee 의 5/15 active staking 각각에 대해 별개 1건
    const l1Referees = await db.prepare(`
      SELECT id, name, email FROM users WHERE referrer_id = ?
    `).bind(uid).all()
    const l1RefList = (l1Referees.results || []) as any[]

    let l1Total = 0
    const l1Breakdown: any[] = []
    for (const ref of l1RefList) {
      const refStakings = await db.prepare(`
        SELECT id, amount, daily_rate FROM staking
        WHERE user_id = ? AND status = 'active'
          AND date(start_date,'+9 hours') <= date(?)
          AND date(end_date,'+9 hours') >= date(?)
      `).bind(ref.id, REWARD_DATE, REWARD_DATE).all()
      for (const s of (refStakings.results || []) as any[]) {
        const refOwn = Math.round(Number(s.amount) * Number(s.daily_rate) * USD_TO_QKEY)
        const l1Reward = Math.round(refOwn * 0.20)
        l1Total += l1Reward
        l1Breakdown.push({
          referee_id: ref.id, referee_name: ref.name, referee_email: ref.email,
          referee_staking_id: s.id, referee_amount: Number(s.amount),
          referee_own_qkey: refOwn,
          l1_reward: l1Reward,
          formula: `${refOwn} × 0.20 = ${l1Reward}`,
        })
      }
    }

    // ─── 3. L2 (내 추천인의 추천인들의 5/15 own_daily × 10%) ───
    //    L1 referees 각자의 referees 의 5/15 staking 각각
    let l2Total = 0
    const l2Breakdown: any[] = []
    for (const l1Ref of l1RefList) {
      const l2Refs = await db.prepare(`
        SELECT id, name, email FROM users WHERE referrer_id = ?
      `).bind(l1Ref.id).all()
      for (const l2Ref of (l2Refs.results || []) as any[]) {
        const l2RefStakings = await db.prepare(`
          SELECT id, amount, daily_rate FROM staking
          WHERE user_id = ? AND status = 'active'
            AND date(start_date,'+9 hours') <= date(?)
            AND date(end_date,'+9 hours') >= date(?)
        `).bind(l2Ref.id, REWARD_DATE, REWARD_DATE).all()
        for (const s of (l2RefStakings.results || []) as any[]) {
          const l2RefOwn = Math.round(Number(s.amount) * Number(s.daily_rate) * USD_TO_QKEY)
          const l2Reward = Math.round(l2RefOwn * 0.10)
          l2Total += l2Reward
          l2Breakdown.push({
            l1_referee_id: l1Ref.id,
            l2_referee_id: l2Ref.id, l2_referee_name: l2Ref.name, l2_referee_email: l2Ref.email,
            referee_staking_id: s.id, referee_amount: Number(s.amount),
            referee_own_qkey: l2RefOwn,
            l2_reward: l2Reward,
            formula: `${l2RefOwn} × 0.10 = ${l2Reward}`,
          })
        }
      }
    }

    // ─── 4. 200% Cap 정보 ───
    const stakeTotalRow = await db.prepare(`
      SELECT COALESCE(SUM(amount),0) AS total FROM staking
      WHERE user_id = ? AND status IN ('active','completed','capped')
    `).bind(uid).first() as any
    const paidTotalRow = await db.prepare(`
      SELECT COALESCE(SUM(amount),0) AS total FROM transactions
      WHERE user_id = ? AND coin_type = 'QKEY' AND type IN ('daily_qkey','referral_reward')
    `).bind(uid).first() as any
    const stakeTotal = Number(stakeTotalRow?.total || 0)
    const paidTotal = Number(paidTotalRow?.total || 0)
    const target = stakeTotal * 2 * USD_TO_QKEY
    const remaining = Math.max(0, target - paidTotal)
    const grossExpected = ownDailyTotal + l1Total + l2Total
    const actualAfterCap = Math.min(grossExpected, remaining)
    const capWillTrigger = grossExpected > remaining

    return c.json({
      ok: true,
      action: 'scan-user-may15-dividend',
      reward_date: REWARD_DATE,
      paid_date: PAID_DATE,
      user: {
        id: uid, name: userRow.name, email: userRow.email,
        referrer_id: userRow.referrer_id,
      },
      breakdown: {
        own_daily: {
          stakings_count: myStakings.length,
          total_qkey: ownDailyTotal,
          per_staking: ownBreakdown,
        },
        l1_20pct: {
          referees_count: l1RefList.length,
          rewards_count: l1Breakdown.length,
          total_qkey: l1Total,
          per_reward: l1Breakdown,
        },
        l2_10pct: {
          rewards_count: l2Breakdown.length,
          total_qkey: l2Total,
          per_reward: l2Breakdown,
        },
      },
      summary: {
        own_daily_total: ownDailyTotal,
        l1_total: l1Total,
        l2_total: l2Total,
        gross_expected_qkey: grossExpected,
        cap_info: {
          stake_total_usd: stakeTotal,
          target_qkey_200pct: target,
          paid_total_qkey_so_far: paidTotal,
          remaining_qkey: remaining,
          cap_will_trigger: capWillTrigger,
        },
        actual_expected_after_cap: actualAfterCap,
      },
      duration_ms: Date.now() - t0,
    })
  } catch (error) {
    return c.json({ error: String(error), duration_ms: Date.now() - t0 }, 500)
  }
})

// ============================================================================
// reverse-backfill-dividend: 지급일 기준 역순 배당 재정산
//
//   사장님 명령 (2026-05-18):
//   - 영구룰 #스테이킹별독립 / #바텀업정산 / #익일처리 적용 전 cron 으로 만들어진
//     과거 배당 row 들을 영구룰 기준으로 재정산
//   - 한 지급일씩 거슬러 올라감 (payoutDate=5/15 → 5/14 → 5/13 ...)
//   - 영구룰 기댓값 vs 현재 DB 비교
//     - 누락 (expected - actual) → INSERT 보충
//     - 잉여 (actual - expected) → DELETE + balance 차감 + transactions 역기록
//     - 금액 불일치 → 보고만 (별도 결재)
//   - 대상 인원: dividendDate 기준 active staking 보유자
//     (dividendDate 이전 진입 + dividendDate 당일 진입자 포함)
//
//   영구룰 준수:
//   - #스테이킹별독립: DR key = (user_id, staking_id), RR key = (level, referrer_id, referee_id, referee_staking_id)
//   - #배당계산: DR = amount × daily_rate × 150, L1=×0.20, L2=×0.10
//   - #바텀업정산: depth desc 정렬
//   - #익일처리: paid_date = payoutDate, reward_date = dividendDate
//   - #중복지급금지: expected set 과 비교, 차이만 처리
//
//   GET  /api/diag/reverse-backfill-dividend?key=ADMIN_PW&payoutDate=2026-05-15&dividendDate=2026-05-14
//        → DRY_RUN (차이 분석 보고)
//   POST /api/diag/reverse-backfill-dividend?key=ADMIN_PW&payoutDate=2026-05-15&dividendDate=2026-05-14&confirm=GO
//        → EXEC (INSERT 누락분 + DELETE 잉여분)
// ============================================================================
async function diagReverseBackfillDividend(c: any, mode: 'DRY_RUN' | 'EXEC') {
  const t0 = Date.now()
  try {
    const payoutDate = c.req.query('payoutDate') || ''
    const dividendDate = c.req.query('dividendDate') || ''
    if (!/^\d{4}-\d{2}-\d{2}$/.test(payoutDate) || !/^\d{4}-\d{2}-\d{2}$/.test(dividendDate)) {
      return c.json({ error: 'payoutDate, dividendDate (YYYY-MM-DD) 필수' }, 400)
    }
    console.log(`[DIVIDEND_REVERSE] start mode=${mode} payoutDate=${payoutDate} dividendDate=${dividendDate}`)

    const db = c.env.DB
    const USD_TO_QKEY = 150

    // ─── PHASE 0: dividendDate 기준 active staking 수집 ───
    //   (dividendDate 이전 진입 + dividendDate 당일 진입자 포함)
    const stRows = await db.prepare(`
      SELECT
        s.user_id,
        s.id AS staking_id,
        s.amount,
        s.daily_rate,
        s.period_days,
        s.period_months,
        date(s.start_date, '+9 hours') AS start_kst,
        date(s.end_date, '+9 hours') AS end_kst,
        s.status,
        (SELECT COUNT(*) FROM daily_rewards WHERE staking_id = s.id) AS rewarded_count_total
      FROM staking s
      WHERE s.status = 'active'
        AND date(s.start_date, '+9 hours') <= date(?)
        AND date(s.end_date, '+9 hours') >= date(?)
      ORDER BY s.user_id ASC, s.id ASC
    `).bind(dividendDate, dividendDate).all()
    const stakings = (stRows.results || []) as any[]

    // ─── PHASE 1: referrer 트리 + depth (bottom-up 정렬용) ───
    const usersRaw = await db.prepare(`SELECT id, referrer_id FROM users`).all()
    const referrerOf = new Map<number, number | null>()
    for (const u of (usersRaw.results || []) as any[]) {
      referrerOf.set(Number(u.id), u.referrer_id != null ? Number(u.referrer_id) : null)
    }
    const depthMemo = new Map<number, number>()
    function computeDepth(uid: number, stack: Set<number>): number {
      if (depthMemo.has(uid)) return depthMemo.get(uid)!
      if (stack.has(uid)) { depthMemo.set(uid, 0); return 0 }
      stack.add(uid)
      const rid = referrerOf.get(uid)
      if (rid == null) { depthMemo.set(uid, 0); stack.delete(uid); return 0 }
      const d = 1 + computeDepth(rid, stack)
      depthMemo.set(uid, d)
      stack.delete(uid)
      return d
    }
    for (const s of stakings) computeDepth(Number(s.user_id), new Set())

    // ─── PHASE 2: 영구룰 적용 EXPECTED set 산출 ───
    //   DR expected: 각 active staking 마다 1건
    //   L1 expected: 각 DR 의 부모 (active staking 보유) 1건
    //   L2 expected: 각 DR 의 조부모 (active staking 보유) 1건
    //   ★ 200% Cap 은 dividendDate 시점의 paid_total 로 시뮬레이션
    //     (현재 시점 paid_total 로 하면 이번 backfill 결과가 미래 Cap 까지 다 빼버려서 비정상)

    // 시뮬레이션용: dividendDate 이전 (reward_date < dividendDate) 의 누적 paid_total
    const paidBeforeRaw = await db.prepare(`
      SELECT user_id, COALESCE(SUM(usdt_amount), 0) AS total
      FROM daily_rewards
      WHERE reward_date < ?
      GROUP BY user_id
    `).bind(dividendDate).all()
    const paidBeforeByUser = new Map<number, number>()
    for (const r of (paidBeforeRaw.results || []) as any[]) {
      paidBeforeByUser.set(Number(r.user_id), Number(r.total) || 0)
    }
    const paidBeforeRrRaw = await db.prepare(`
      SELECT referrer_id AS user_id, COALESCE(SUM(reward_amount), 0) AS total
      FROM referral_rewards
      WHERE reward_date < ?
      GROUP BY referrer_id
    `).bind(dividendDate).all()
    for (const r of (paidBeforeRrRaw.results || []) as any[]) {
      const uid = Number(r.user_id)
      paidBeforeByUser.set(uid, (paidBeforeByUser.get(uid) || 0) + Number(r.total))
    }

    const stakeTotalsRaw = await db.prepare(`
      SELECT user_id, COALESCE(SUM(amount), 0) AS total
      FROM staking WHERE status IN ('active','completed','capped')
      GROUP BY user_id
    `).all()
    const stakeTotalByUser = new Map<number, number>()
    for (const r of (stakeTotalsRaw.results || []) as any[]) {
      stakeTotalByUser.set(Number(r.user_id), Number(r.total) || 0)
    }
    const targetOf = (uid: number) => (stakeTotalByUser.get(uid) || 0) * 2 * USD_TO_QKEY
    const simPaidByUser = new Map<number, number>(paidBeforeByUser)
    const simPaidOf = (uid: number) => simPaidByUser.get(uid) || 0
    const simIsCapped = (uid: number) => { const t = targetOf(uid); return t > 0 && simPaidOf(uid) >= t }
    const simRemaining = (uid: number) => Math.max(0, targetOf(uid) - simPaidOf(uid))
    const simAddPaid = (uid: number, amt: number) => { simPaidByUser.set(uid, simPaidOf(uid) + amt) }

    // depth desc 정렬
    stakings.sort((a, b) => {
      const da = depthMemo.get(Number(a.user_id)) || 0
      const db_ = depthMemo.get(Number(b.user_id)) || 0
      if (db_ !== da) return db_ - da
      if (Number(a.user_id) !== Number(b.user_id)) return Number(a.user_id) - Number(b.user_id)
      return Number(a.staking_id) - Number(b.staking_id)
    })

    // ── DR expected ──
    type DrExp = { user_id: number, staking_id: number, qkey_amount: number, depth: number }
    const drExpected = new Map<string, DrExp>() // key = `${uid}_${sid}`
    for (const s of stakings) {
      const uid = Number(s.user_id)
      const sid = Number(s.staking_id)
      const amount = Number(s.amount) || 0
      const rate = Number(s.daily_rate) || 0
      const periodDays = Number(s.period_days) || (Number(s.period_months) * 30) || 0
      const rewardedTotal = Number(s.rewarded_count_total) || 0
      const depth = depthMemo.get(uid) || 0

      // 기간 완료 체크 — dividendDate 시점에는 rewarded_count_total 이 미래꺼까지 포함
      // 단순화: periodDays 가 있고 rewardedTotal 이 그것보다 큰 경우만 skip
      // (정확하지 않음 — 보수적 처리로 skip 하지 않음, periodDone 정보만 제공)
      if (periodDays > 0 && rewardedTotal > periodDays) continue
      if (simIsCapped(uid)) continue

      let qkey = Math.round(amount * rate * USD_TO_QKEY)
      const remaining = simRemaining(uid)
      if (qkey > remaining) qkey = Math.max(0, Math.floor(remaining))
      if (qkey <= 0) continue

      drExpected.set(`${uid}_${sid}`, { user_id: uid, staking_id: sid, qkey_amount: qkey, depth })
      simAddPaid(uid, qkey)
    }

    // ── L1/L2 expected ──
    type RrExp = {
      level: 1 | 2, referrer_id: number, referee_id: number, referee_staking_id: number,
      original_amount: number, reward_amount: number,
    }
    const rrExpected = new Map<string, RrExp>() // key = `L${level}_${refrid}_${refeeid}_${sid}`

    for (const dr of drExpected.values()) {
      const childUid = dr.user_id
      const childOwn = dr.qkey_amount
      const childSid = dr.staking_id
      const parentId = referrerOf.get(childUid)
      if (parentId == null) continue

      // L1 — parent 가 dividendDate 시점 active staking 보유해야 함
      const parentActive = await db.prepare(`
        SELECT id FROM staking
        WHERE user_id = ? AND status = 'active'
          AND date(start_date, '+9 hours') <= date(?)
          AND date(end_date, '+9 hours') >= date(?)
        LIMIT 1
      `).bind(parentId, dividendDate, dividendDate).first()

      if (parentActive && !simIsCapped(parentId)) {
        let l1 = Math.round(childOwn * 0.20)
        const rem = simRemaining(parentId)
        if (l1 > rem) l1 = Math.max(0, Math.floor(rem))
        if (l1 > 0) {
          rrExpected.set(`L1_${parentId}_${childUid}_${childSid}`, {
            level: 1, referrer_id: parentId, referee_id: childUid, referee_staking_id: childSid,
            original_amount: childOwn, reward_amount: l1,
          })
          simAddPaid(parentId, l1)
        }
      }

      // L2 — grand parent
      const grandId = referrerOf.get(parentId)
      if (grandId == null) continue
      const grandActive = await db.prepare(`
        SELECT id FROM staking
        WHERE user_id = ? AND status = 'active'
          AND date(start_date, '+9 hours') <= date(?)
          AND date(end_date, '+9 hours') >= date(?)
        LIMIT 1
      `).bind(grandId, dividendDate, dividendDate).first()

      if (grandActive && !simIsCapped(grandId)) {
        let l2 = Math.round(childOwn * 0.10)
        const rem = simRemaining(grandId)
        if (l2 > rem) l2 = Math.max(0, Math.floor(rem))
        if (l2 > 0) {
          rrExpected.set(`L2_${grandId}_${childUid}_${childSid}`, {
            level: 2, referrer_id: grandId, referee_id: childUid, referee_staking_id: childSid,
            original_amount: childOwn, reward_amount: l2,
          })
          simAddPaid(grandId, l2)
        }
      }
    }

    // ─── PHASE 3: 현재 DB ACTUAL set 조회 (paid_date 기준) ───
    //   DR actual: paid_date = payoutDate 인 모든 row
    //   RR actual: paid_date = payoutDate AND level IN (1, 2) 인 모든 row (L0 은 별개)
    const drActualRaw = await db.prepare(`
      SELECT id, user_id, staking_id, usdt_amount, reward_date, paid_date
      FROM daily_rewards
      WHERE paid_date = ?
    `).bind(payoutDate).all()
    const rrActualRaw = await db.prepare(`
      SELECT id, referrer_id, referee_id, staking_id, level, original_amount, reward_amount, reward_date, paid_date
      FROM referral_rewards
      WHERE paid_date = ? AND level IN (1, 2)
    `).bind(payoutDate).all()

    type DrAct = { id: number, user_id: number, staking_id: number | null, usdt_amount: number, reward_date: string, paid_date: string }
    type RrAct = { id: number, referrer_id: number, referee_id: number, staking_id: number | null, level: number, original_amount: number, reward_amount: number, reward_date: string, paid_date: string }
    const drActualList = ((drActualRaw.results || []) as any[]).map((r: any) => ({
      id: Number(r.id), user_id: Number(r.user_id),
      staking_id: r.staking_id != null ? Number(r.staking_id) : null,
      usdt_amount: Number(r.usdt_amount),
      reward_date: String(r.reward_date), paid_date: String(r.paid_date),
    })) as DrAct[]
    const rrActualList = ((rrActualRaw.results || []) as any[]).map((r: any) => ({
      id: Number(r.id), referrer_id: Number(r.referrer_id), referee_id: Number(r.referee_id),
      staking_id: r.staking_id != null ? Number(r.staking_id) : null,
      level: Number(r.level), original_amount: Number(r.original_amount), reward_amount: Number(r.reward_amount),
      reward_date: String(r.reward_date), paid_date: String(r.paid_date),
    })) as RrAct[]

    // ─── PHASE 4: 비교 (expected vs actual) ───

    // DR 비교
    const drActualByKey = new Map<string, DrAct>()
    const drActualNoStaking: DrAct[] = []  // staking_id=NULL legacy
    for (const a of drActualList) {
      if (a.staking_id == null) { drActualNoStaking.push(a); continue }
      drActualByKey.set(`${a.user_id}_${a.staking_id}`, a)
    }

    const drMissing: DrExp[] = []           // expected 에 있는데 actual 에 없음 → INSERT
    const drMatchSameAmount: { expected: DrExp, actual: DrAct }[] = []  // 양쪽 있고 금액 동일 → 그대로 둠
    const drMatchDiffAmount: { expected: DrExp, actual: DrAct }[] = []  // 양쪽 있는데 금액 다름 → 보고
    const drExtra: DrAct[] = []             // actual 에 있는데 expected 에 없음 → DELETE

    for (const [k, exp] of drExpected.entries()) {
      const act = drActualByKey.get(k)
      if (!act) { drMissing.push(exp); continue }
      if (Math.round(act.usdt_amount) === Math.round(exp.qkey_amount)) {
        drMatchSameAmount.push({ expected: exp, actual: act })
      } else {
        drMatchDiffAmount.push({ expected: exp, actual: act })
      }
    }
    for (const [k, act] of drActualByKey.entries()) {
      if (!drExpected.has(k)) drExtra.push(act)
    }

    // RR 비교
    const rrActualByKey = new Map<string, RrAct>()
    const rrActualNoStaking: RrAct[] = []   // staking_id=NULL legacy
    for (const a of rrActualList) {
      if (a.staking_id == null) { rrActualNoStaking.push(a); continue }
      rrActualByKey.set(`L${a.level}_${a.referrer_id}_${a.referee_id}_${a.staking_id}`, a)
    }

    const rrMissing: RrExp[] = []
    const rrMatchSameAmount: { expected: RrExp, actual: RrAct }[] = []
    const rrMatchDiffAmount: { expected: RrExp, actual: RrAct }[] = []
    const rrExtra: RrAct[] = []

    for (const [k, exp] of rrExpected.entries()) {
      const act = rrActualByKey.get(k)
      if (!act) { rrMissing.push(exp); continue }
      if (Math.round(act.reward_amount) === Math.round(exp.reward_amount)) {
        rrMatchSameAmount.push({ expected: exp, actual: act })
      } else {
        rrMatchDiffAmount.push({ expected: exp, actual: act })
      }
    }
    for (const [k, act] of rrActualByKey.entries()) {
      if (!rrExpected.has(k)) rrExtra.push(act)
    }

    // ─── 합계 ───
    const drMissingTotal = drMissing.reduce((s, r) => s + r.qkey_amount, 0)
    const drExtraTotal = drExtra.reduce((s, r) => s + r.usdt_amount, 0)
    const drDiffSummary = drMatchDiffAmount.reduce((acc: any, r) => {
      acc.expected += r.expected.qkey_amount
      acc.actual += r.actual.usdt_amount
      return acc
    }, { expected: 0, actual: 0 })

    const rrMissingL1 = rrMissing.filter(r => r.level === 1)
    const rrMissingL2 = rrMissing.filter(r => r.level === 2)
    const rrExtraL1 = rrExtra.filter(r => r.level === 1)
    const rrExtraL2 = rrExtra.filter(r => r.level === 2)
    const rrMissingL1Total = rrMissingL1.reduce((s, r) => s + r.reward_amount, 0)
    const rrMissingL2Total = rrMissingL2.reduce((s, r) => s + r.reward_amount, 0)
    const rrExtraL1Total = rrExtraL1.reduce((s, r) => s + r.reward_amount, 0)
    const rrExtraL2Total = rrExtraL2.reduce((s, r) => s + r.reward_amount, 0)

    const summary = {
      target_user_count: new Set(stakings.map((s: any) => s.user_id)).size,
      target_staking_count: stakings.length,
      expected_total_dr: drExpected.size,
      expected_total_rr: rrExpected.size,
      // INSERT 보충 대상
      dr_missing_count: drMissing.length,
      dr_missing_total_qkey: drMissingTotal,
      rr_missing_l1_count: rrMissingL1.length,
      rr_missing_l1_total_qkey: rrMissingL1Total,
      rr_missing_l2_count: rrMissingL2.length,
      rr_missing_l2_total_qkey: rrMissingL2Total,
      // DELETE 대상 (잉여/과지급)
      dr_extra_count: drExtra.length,
      dr_extra_total_qkey: drExtraTotal,
      rr_extra_l1_count: rrExtraL1.length,
      rr_extra_l1_total_qkey: rrExtraL1Total,
      rr_extra_l2_count: rrExtraL2.length,
      rr_extra_l2_total_qkey: rrExtraL2Total,
      // 보고 (그대로 둠, 별도 결재)
      dr_match_diff_amount_count: drMatchDiffAmount.length,
      dr_match_diff_summary: drDiffSummary,
      rr_match_diff_amount_count: rrMatchDiffAmount.length,
      // legacy staking_id=NULL
      dr_actual_no_staking_id: drActualNoStaking.length,
      rr_actual_no_staking_id: rrActualNoStaking.length,
      // 매치
      dr_match_same_count: drMatchSameAmount.length,
      rr_match_same_count: rrMatchSameAmount.length,
      // 순 변동
      net_insert_qkey: drMissingTotal + rrMissingL1Total + rrMissingL2Total,
      net_delete_qkey: drExtraTotal + rrExtraL1Total + rrExtraL2Total,
      net_delta_qkey: (drMissingTotal + rrMissingL1Total + rrMissingL2Total) - (drExtraTotal + rrExtraL1Total + rrExtraL2Total),
    }

    // ═══════════════ DRY-RUN 분기 ═══════════════
    if (mode === 'DRY_RUN') {
      return c.json({
        ok: true,
        mode: 'DRY_RUN',
        action: 'reverse-backfill-dividend',
        payoutDate, dividendDate,
        executedAt: new Date().toISOString(),
        rules_applied: [
          '#스테이킹별독립: DR=(user_id,staking_id), RR=(level,referrer_id,referee_id,staking_id)',
          '#배당계산: DR=amount×rate×150, L1=×0.20, L2=×0.10',
          '#바텀업정산: depth desc 정렬',
          '#익일처리: paid_date=payoutDate, reward_date=dividendDate',
          '#중복지급금지: expected set 비교, 차이만 처리',
        ],
        summary,
        samples: {
          dr_missing_top10: drMissing.slice(0, 10),
          dr_extra_top10: drExtra.slice(0, 10).map(r => ({
            id: r.id, user_id: r.user_id, staking_id: r.staking_id,
            usdt_amount: r.usdt_amount, reward_date: r.reward_date,
          })),
          dr_match_diff_top10: drMatchDiffAmount.slice(0, 10).map(r => ({
            user_id: r.expected.user_id, staking_id: r.expected.staking_id,
            expected_qkey: r.expected.qkey_amount, actual_qkey: r.actual.usdt_amount,
            diff: r.expected.qkey_amount - r.actual.usdt_amount, actual_id: r.actual.id,
          })),
          rr_missing_top10: rrMissing.slice(0, 10),
          rr_extra_top10: rrExtra.slice(0, 10).map(r => ({
            id: r.id, level: r.level, referrer_id: r.referrer_id, referee_id: r.referee_id,
            staking_id: r.staking_id, reward_amount: r.reward_amount,
          })),
          rr_match_diff_top10: rrMatchDiffAmount.slice(0, 10).map(r => ({
            level: r.expected.level, referrer_id: r.expected.referrer_id,
            referee_id: r.expected.referee_id, referee_staking_id: r.expected.referee_staking_id,
            expected_qkey: r.expected.reward_amount, actual_qkey: r.actual.reward_amount,
            diff: r.expected.reward_amount - r.actual.reward_amount, actual_id: r.actual.id,
          })),
          dr_actual_no_staking_samples: drActualNoStaking.slice(0, 5),
          rr_actual_no_staking_samples: rrActualNoStaking.slice(0, 5),
        },
        next_action: 'POST + confirm=GO 보내시면 EXEC. 누락 INSERT + 잉여 DELETE + balance 보정.',
        duration_ms: Date.now() - t0,
      })
    }

    // ═══════════════ EXEC 분기 ═══════════════
    const CHUNK_SIZE = 80

    // ── (1) DR 잉여 DELETE + balance 차감 + transactions 역기록 ──
    let drExtraDeleted = 0
    let drExtraBalanceReverted = 0
    for (let i = 0; i < drExtra.length; i += CHUNK_SIZE) {
      const chunk = drExtra.slice(i, i + CHUNK_SIZE)
      const stmts: any[] = []
      for (const r of chunk) {
        // 1. DELETE dr row
        stmts.push(db.prepare(`DELETE FROM daily_rewards WHERE id = ?`).bind(r.id))
        // 2. user qkey_balance 차감
        stmts.push(db.prepare(`UPDATE users SET qkey_balance = qkey_balance - ? WHERE id = ?`).bind(r.usdt_amount, r.user_id))
        // 3. 원본 tx 음수 보정 (역기록) — 'daily_reward_rollback' type
        stmts.push(db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
          VALUES (?, 'daily_reward_rollback', 'QKEY', ?, ?, ?)
        `).bind(r.user_id, -Math.abs(r.usdt_amount),
          `[REVERSE_BACKFILL] DR 잉여 제거 (payoutDate=${payoutDate}, dividendDate=${dividendDate})`,
          `dr_extra_${r.id}`))
        // 4. 기존 tx 'daily_qkey' ref_id=dr_id 도 삭제 (있으면)
        stmts.push(db.prepare(`DELETE FROM transactions WHERE type = 'daily_qkey' AND ref_id = ?`).bind(String(r.id)))
      }
      if (stmts.length > 0) {
        await db.batch(stmts)
        drExtraDeleted += chunk.length
        drExtraBalanceReverted += chunk.reduce((s, r) => s + r.usdt_amount, 0)
      }
    }

    // ── (2) RR 잉여 DELETE + balance 차감 + transactions 역기록 ──
    let rrExtraDeleted = 0
    let rrExtraBalanceReverted = 0
    for (let i = 0; i < rrExtra.length; i += CHUNK_SIZE) {
      const chunk = rrExtra.slice(i, i + CHUNK_SIZE)
      const stmts: any[] = []
      for (const r of chunk) {
        stmts.push(db.prepare(`DELETE FROM referral_rewards WHERE id = ?`).bind(r.id))
        stmts.push(db.prepare(`UPDATE users SET qkey_balance = qkey_balance - ? WHERE id = ?`).bind(r.reward_amount, r.referrer_id))
        stmts.push(db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
          VALUES (?, 'referral_reward_rollback', 'QKEY', ?, ?, ?)
        `).bind(r.referrer_id, -Math.abs(r.reward_amount),
          `[REVERSE_BACKFILL] RR L${r.level} 잉여 제거 (payoutDate=${payoutDate}, dividendDate=${dividendDate})`,
          `rr_extra_${r.id}`))
        stmts.push(db.prepare(`DELETE FROM transactions WHERE type = 'referral_reward' AND ref_id = ?`).bind(String(r.id)))
      }
      if (stmts.length > 0) {
        await db.batch(stmts)
        rrExtraDeleted += chunk.length
        rrExtraBalanceReverted += chunk.reduce((s, r) => s + r.reward_amount, 0)
      }
    }

    // ── (3) DR 누락 INSERT + balance 가산 + transactions 신규 ──
    let drMissingInserted = 0
    let drMissingAmountAdded = 0
    const drInsertedIdMap = new Map<string, number>()
    for (let i = 0; i < drMissing.length; i += CHUNK_SIZE) {
      const chunk = drMissing.slice(i, i + CHUNK_SIZE)
      const stmts = chunk.map(p => db.prepare(`
        INSERT INTO daily_rewards (user_id, staking_id, usdt_amount, reward_date, paid_date)
        VALUES (?, ?, ?, ?, ?)
      `).bind(p.user_id, p.staking_id, p.qkey_amount, dividendDate, payoutDate))
      const results = await db.batch(stmts)
      for (let j = 0; j < results.length; j++) {
        const r = results[j] as any
        const drId = r?.meta?.last_row_id
        if (drId != null) {
          drInsertedIdMap.set(`${chunk[j].user_id}_${chunk[j].staking_id}`, Number(drId))
          drMissingInserted++
          drMissingAmountAdded += chunk[j].qkey_amount
        }
      }
    }
    // balance + tx
    for (let i = 0; i < drMissing.length; i += CHUNK_SIZE) {
      const chunk = drMissing.slice(i, i + CHUNK_SIZE)
      const stmts: any[] = []
      for (const p of chunk) {
        const drId = drInsertedIdMap.get(`${p.user_id}_${p.staking_id}`)
        if (!drId) continue
        stmts.push(db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(p.qkey_amount, p.user_id))
        stmts.push(db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
          VALUES (?, 'daily_qkey', 'QKEY', ?, ?, ?)
        `).bind(p.user_id, p.qkey_amount,
          `일일 배당 (QKEY) [REVERSE_BACKFILL ${dividendDate}→${payoutDate}]`,
          String(drId)))
      }
      if (stmts.length > 0) await db.batch(stmts)
    }

    // ── (4) RR 누락 INSERT + balance 가산 + transactions 신규 ──
    let rrMissingInserted = 0
    let rrMissingL1Added = 0
    let rrMissingL2Added = 0
    const rrInsertedIdMap = new Map<number, number>()
    for (let i = 0; i < rrMissing.length; i += CHUNK_SIZE) {
      const chunk = rrMissing.slice(i, i + CHUNK_SIZE)
      const stmts = chunk.map(p => db.prepare(`
        INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, staking_id)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
      `).bind(p.referrer_id, p.referee_id, p.level, p.original_amount, p.reward_amount, dividendDate, payoutDate, p.referee_staking_id))
      const results = await db.batch(stmts)
      for (let j = 0; j < results.length; j++) {
        const r = results[j] as any
        const rrId = r?.meta?.last_row_id
        if (rrId != null) {
          rrInsertedIdMap.set(i + j, Number(rrId))
          rrMissingInserted++
          if (chunk[j].level === 1) rrMissingL1Added += chunk[j].reward_amount
          else rrMissingL2Added += chunk[j].reward_amount
        }
      }
    }
    // balance + tx
    for (let i = 0; i < rrMissing.length; i += CHUNK_SIZE) {
      const chunk = rrMissing.slice(i, i + CHUNK_SIZE)
      const stmts: any[] = []
      for (let j = 0; j < chunk.length; j++) {
        const p = chunk[j]
        const rrId = rrInsertedIdMap.get(i + j)
        if (!rrId) continue
        stmts.push(db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(p.reward_amount, p.referrer_id))
        const desc = p.level === 1 ? '추천 보너스 (Level 1)' : '추천 보너스 (Level 2)'
        stmts.push(db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
          VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?)
        `).bind(p.referrer_id, p.reward_amount,
          `${desc} [REVERSE_BACKFILL ${dividendDate}→${payoutDate}]`,
          String(rrId)))
      }
      if (stmts.length > 0) await db.batch(stmts)
    }

    // ─── POST-CHECK: 결과 검증 ───
    const drPostRaw = await db.prepare(`
      SELECT COUNT(*) AS cnt, COALESCE(SUM(usdt_amount), 0) AS total
      FROM daily_rewards WHERE paid_date = ?
    `).bind(payoutDate).first() as any
    const rrPostRaw = await db.prepare(`
      SELECT level, COUNT(*) AS cnt, COALESCE(SUM(reward_amount), 0) AS total
      FROM referral_rewards WHERE paid_date = ?
      GROUP BY level
    `).bind(payoutDate).all()
    // 중복 검사
    const drDupPost = await db.prepare(`
      SELECT user_id, staking_id, reward_date, COUNT(*) AS cnt
      FROM daily_rewards
      WHERE paid_date = ? AND staking_id IS NOT NULL
      GROUP BY user_id, staking_id, reward_date
      HAVING COUNT(*) > 1
    `).bind(payoutDate).all()
    const rrDupPost = await db.prepare(`
      SELECT referrer_id, referee_id, staking_id, level, reward_date, COUNT(*) AS cnt
      FROM referral_rewards
      WHERE paid_date = ? AND staking_id IS NOT NULL AND level IN (1, 2)
      GROUP BY referrer_id, referee_id, staking_id, level, reward_date
      HAVING COUNT(*) > 1
    `).bind(payoutDate).all()

    return c.json({
      ok: true,
      mode: 'EXEC',
      action: 'reverse-backfill-dividend',
      payoutDate, dividendDate,
      executedAt: new Date().toISOString(),
      pre_summary: summary,
      exec_result: {
        // DELETE (잉여)
        dr_extra_deleted: drExtraDeleted,
        dr_extra_balance_reverted_qkey: drExtraBalanceReverted,
        rr_extra_deleted: rrExtraDeleted,
        rr_extra_balance_reverted_qkey: rrExtraBalanceReverted,
        // INSERT (누락)
        dr_missing_inserted: drMissingInserted,
        dr_missing_amount_added_qkey: drMissingAmountAdded,
        rr_missing_inserted: rrMissingInserted,
        rr_missing_l1_added_qkey: rrMissingL1Added,
        rr_missing_l2_added_qkey: rrMissingL2Added,
        // 순 변동
        net_delta_qkey: (drMissingAmountAdded + rrMissingL1Added + rrMissingL2Added) - (drExtraBalanceReverted + rrExtraBalanceReverted),
      },
      post_check: {
        dr_paid_date_count: Number(drPostRaw?.cnt || 0),
        dr_paid_date_total: Number(drPostRaw?.total || 0),
        rr_paid_date_by_level: rrPostRaw.results,
        dr_duplicates: (drDupPost.results || []).length,
        rr_duplicates: (rrDupPost.results || []).length,
        verified: (drDupPost.results || []).length === 0 && (rrDupPost.results || []).length === 0,
      },
      duration_ms: Date.now() - t0,
    })
  } catch (error) {
    const durMs = Date.now() - t0
    console.error(`[DIVIDEND_REVERSE] ERROR mode=${mode} duration_ms=${durMs}`, error)
    return c.json({ error: String(error), duration_ms: durMs }, 500)
  }
}

