// ============================================================================
// rollback-reverse-backfill-marker: [REVERSE_BACKFILL] 마커 박힌 row 전부 들어냄
//
//   사장님 명령 (2026-05-18 사고 후):
//   "리벌스라고 영어로 박힌거 그거 전부 들어내면 딱맞아"
//
//   대상 식별:
//     transactions.description LIKE '%[REVERSE_BACKFILL%'
//     (description 마커는 reverse-backfill EXEC 안에서만 박힘 — 정확 식별)
//
//   처리 (이 순서로 db.batch 청크):
//     1. transactions ref_id 로 referral_rewards 조인 → 해당 rr id 수집
//     2. 각 사용자의 qkey_balance -= 해당 tx.amount (음수면 +=)
//     3. transactions DELETE (마커 row 들)
//     4. referral_rewards DELETE (1 에서 수집한 rr id 들)
//
//   안전장치:
//     - DRY-RUN 우선 (사장님 확인 후 EXEC)
//     - description 마커 절대 다른 곳에서 안 박힘 (코드 grep 확인)
//     - 마커 row 만 정확히 식별, 다른 정상 row 0건 영향
//     - 사후 검증: 마커 row 0건 / referral_rewards id 0건 / balance 정합
//
//   GET  /api/diag/rollback-reverse-backfill-marker?key=ADMIN_PW              → DRY_RUN
//   POST /api/diag/rollback-reverse-backfill-marker?key=ADMIN_PW&confirm=GO   → EXEC
// ============================================================================
async function diagRollbackReverseBackfillMarker(c: any, mode: 'DRY_RUN' | 'EXEC') {
  const t0 = Date.now()
  try {
    console.log(`[ROLLBACK_RB] start mode=${mode}`)
    const db = c.env.DB

    // ── 마커 패턴 — query param 으로 받음 (기본: REVERSE_BACKFILL) ──
    //   사장님 명령: [RECONCILE 도 같은 코드로 들어내기
    const markerPattern = c.req.query('marker') || 'REVERSE_BACKFILL'
    const likePattern = `%[${markerPattern}%`

    // ★ 2026-05-18 추가: tx_only=true → transactions 마커 row 만 DELETE
    //   사용 시점: 이미 rollback EXEC 가 RR/balance 차감 끝났는데 tx 만 안 지워진 경우 (버그)
    //   동작: balance 보정/RR DELETE/DR DELETE 모두 SKIP, transactions DELETE 만 실행
    //   이중 차감 방지용
    const txOnly = c.req.query('tx_only') === 'true'

    // ─── PHASE 1: 마커 tx 수집 ───
    const txMarkerRaw = await db.prepare(`
      SELECT id, user_id, type, amount, description, ref_id,
             datetime(created_at, '+9 hours') AS created_kst
      FROM transactions
      WHERE description LIKE ?
      ORDER BY id ASC
    `).bind(likePattern).all()
    const txMarkerList = (txMarkerRaw.results || []) as any[]

    if (txMarkerList.length === 0) {
      return c.json({
        ok: true,
        mode,
        action: 'rollback-reverse-backfill-marker',
        marker_pattern: markerPattern,
        message: `[${markerPattern}] 마커 tx 0건 — 롤백할 것 없음`,
        duration_ms: Date.now() - t0,
      })
    }

    // ─── PHASE 2: tx 유형별 분류 + rr id 수집 ───
    //   type='referral_reward' → ref_id 로 referral_rewards 조인 → DELETE 대상
    //   type='daily_qkey'      → ref_id 로 daily_rewards 조인 → DELETE 대상
    //   type='*_rollback'      → 음수 보정 tx (있다면) — 정상 복구를 위해 같이 제거
    const rrIdsToDelete: number[] = []
    const drIdsToDelete: number[] = []
    let totalAmount = 0
    const balanceDelta = new Map<number, number>() // user_id → 차감해야 할 양수 / 가산해야 할 음수
    const txByType: Record<string, { count: number, total: number }> = {}

    for (const tx of txMarkerList) {
      const uid = Number(tx.user_id)
      const amt = Number(tx.amount)
      const refId = String(tx.ref_id || '')
      totalAmount += amt
      const t = String(tx.type)
      if (!txByType[t]) txByType[t] = { count: 0, total: 0 }
      txByType[t].count++
      txByType[t].total += amt

      // 사용자 잔액 보정: tx 가 +면 잔액에서 차감, tx 가 -(rollback) 이면 잔액에 가산
      balanceDelta.set(uid, (balanceDelta.get(uid) || 0) - amt)

      // 신규 INSERT 였으면 ref_id 가 rr_id 또는 dr_id 의 문자열
      if (t === 'referral_reward' && refId && /^\d+$/.test(refId)) {
        rrIdsToDelete.push(Number(refId))
      } else if (t === 'daily_qkey' && refId && /^\d+$/.test(refId)) {
        drIdsToDelete.push(Number(refId))
      }
      // type='referral_reward_rollback' / 'daily_reward_rollback' 은
      //   ref_id 가 'rr_extra_X' / 'dr_extra_X' 형태 (오늘 작업에선 잉여 0건이라 안 발생)
      //   이건 별도 DELETE 안 함 — tx 만 제거하면 balance 복구됨
    }

    // ─── PHASE 3: rr / dr 실제 존재 여부 확인 (현재 DB 상태) ───
    let rrExistList: any[] = []
    let drExistList: any[] = []
    if (rrIdsToDelete.length > 0) {
      // chunk 단위로 IN 절 처리
      const CHUNK = 100
      for (let i = 0; i < rrIdsToDelete.length; i += CHUNK) {
        const chunk = rrIdsToDelete.slice(i, i + CHUNK)
        const placeholders = chunk.map(() => '?').join(',')
        const rows = await db.prepare(`
          SELECT id, referrer_id, referee_id, level, reward_amount, reward_date, paid_date, staking_id
          FROM referral_rewards
          WHERE id IN (${placeholders})
        `).bind(...chunk).all()
        rrExistList.push(...((rows.results || []) as any[]))
      }
    }
    if (drIdsToDelete.length > 0) {
      const CHUNK = 100
      for (let i = 0; i < drIdsToDelete.length; i += CHUNK) {
        const chunk = drIdsToDelete.slice(i, i + CHUNK)
        const placeholders = chunk.map(() => '?').join(',')
        const rows = await db.prepare(`
          SELECT id, user_id, staking_id, usdt_amount, reward_date, paid_date
          FROM daily_rewards
          WHERE id IN (${placeholders})
        `).bind(...chunk).all()
        drExistList.push(...((rows.results || []) as any[]))
      }
    }

    // ─── 영향받을 사용자 / 합계 ───
    const affectedUsers = Array.from(balanceDelta.keys()).sort((a, b) => a - b)
    const balanceDeltaList = Array.from(balanceDelta.entries()).map(([uid, delta]) => ({ user_id: uid, balance_delta: delta }))

    const summary = {
      tx_marker_count: txMarkerList.length,
      tx_total_amount: totalAmount,
      tx_by_type: txByType,
      rr_ids_to_delete: rrIdsToDelete.length,
      rr_actually_exists: rrExistList.length,
      dr_ids_to_delete: drIdsToDelete.length,
      dr_actually_exists: drExistList.length,
      affected_users_count: affectedUsers.length,
    }

    // ═══════════════ DRY-RUN ═══════════════
    if (mode === 'DRY_RUN') {
      // 사용자별 balance 변동 + 사고 후 → 복구 후 시뮬레이션
      const userIdList = affectedUsers
      let userBalanceSim: any[] = []
      if (userIdList.length > 0) {
        const CHUNK = 100
        for (let i = 0; i < userIdList.length; i += CHUNK) {
          const chunk = userIdList.slice(i, i + CHUNK)
          const placeholders = chunk.map(() => '?').join(',')
          const rows = await db.prepare(`
            SELECT id, name, email, qkey_balance
            FROM users WHERE id IN (${placeholders})
          `).bind(...chunk).all()
          for (const u of (rows.results || []) as any[]) {
            const delta = balanceDelta.get(Number(u.id)) || 0
            userBalanceSim.push({
              user_id: Number(u.id), name: u.name, email: u.email,
              current_balance: Number(u.qkey_balance),
              delta: delta,  // 음수이면 차감
              post_balance: Number(u.qkey_balance) + delta,
              will_go_negative: (Number(u.qkey_balance) + delta) < 0,
            })
          }
        }
      }

      const negativeAfter = userBalanceSim.filter(u => u.will_go_negative)

      return c.json({
        ok: true,
        mode: 'DRY_RUN',
        action: 'rollback-reverse-backfill-marker',
        marker_pattern: `description LIKE ${likePattern}`,
        tx_only: txOnly,
        summary,
        affected_users_balance_top20: userBalanceSim.slice(0, 20),
        negative_balance_warning: {
          count: negativeAfter.length,
          samples: negativeAfter.slice(0, 10),
        },
        tx_marker_sample_top10: txMarkerList.slice(0, 10).map((tx: any) => ({
          id: tx.id, user_id: tx.user_id, type: tx.type,
          amount: tx.amount, description: tx.description,
          ref_id: tx.ref_id, created_kst: tx.created_kst,
        })),
        rr_sample_top10: rrExistList.slice(0, 10),
        dr_sample_top10: drExistList.slice(0, 10),
        next_action: 'POST + confirm=GO 보내시면 EXEC. set-based batch DELETE + balance 차감.',
        duration_ms: Date.now() - t0,
      })
    }

    // ═══════════════ EXEC ═══════════════
    const CHUNK_SIZE = 80

    // ── (1) users.qkey_balance 보정 ── (tx_only 일 땐 SKIP — 이중 차감 방지)
    let balanceAdjusted = 0
    if (!txOnly) {
      const balEntries = Array.from(balanceDelta.entries())
      for (let i = 0; i < balEntries.length; i += CHUNK_SIZE) {
        const chunk = balEntries.slice(i, i + CHUNK_SIZE)
        const stmts = chunk.map(([uid, delta]) =>
          db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(delta, uid)
        )
        await db.batch(stmts)
        balanceAdjusted += chunk.length
      }
    }

    // ── (2) referral_rewards DELETE ── (tx_only 일 땐 SKIP)
    let rrDeleted = 0
    if (!txOnly && rrIdsToDelete.length > 0) {
      for (let i = 0; i < rrIdsToDelete.length; i += CHUNK_SIZE) {
        const chunk = rrIdsToDelete.slice(i, i + CHUNK_SIZE)
        const placeholders = chunk.map(() => '?').join(',')
        const r = await db.prepare(`DELETE FROM referral_rewards WHERE id IN (${placeholders})`).bind(...chunk).run()
        rrDeleted += (r as any)?.meta?.changes || 0
      }
    }

    // ── (3) daily_rewards DELETE ── (tx_only 일 땐 SKIP)
    let drDeleted = 0
    if (!txOnly && drIdsToDelete.length > 0) {
      for (let i = 0; i < drIdsToDelete.length; i += CHUNK_SIZE) {
        const chunk = drIdsToDelete.slice(i, i + CHUNK_SIZE)
        const placeholders = chunk.map(() => '?').join(',')
        const r = await db.prepare(`DELETE FROM daily_rewards WHERE id IN (${placeholders})`).bind(...chunk).run()
        drDeleted += (r as any)?.meta?.changes || 0
      }
    }

    // ── (4) transactions DELETE (마커 row 들) ── ★ tx_only 일 땐 이것만 실행 ★
    //   ★ likePattern (query param 으로 받은 marker 패턴) 사용
    const txDelRes = await db.prepare(`DELETE FROM transactions WHERE description LIKE ?`).bind(likePattern).run()
    const txDeleted = (txDelRes as any)?.meta?.changes || 0

    // ─── POST-CHECK ───
    const postTxRaw = await db.prepare(`SELECT COUNT(*) AS cnt FROM transactions WHERE description LIKE ?`).bind(likePattern).first() as any
    const postTxCount = Number(postTxRaw?.cnt || 0)

    let postRrExistCount = 0
    if (rrIdsToDelete.length > 0) {
      const CHUNK = 100
      for (let i = 0; i < rrIdsToDelete.length; i += CHUNK) {
        const chunk = rrIdsToDelete.slice(i, i + CHUNK)
        const placeholders = chunk.map(() => '?').join(',')
        const rows = await db.prepare(`SELECT COUNT(*) AS cnt FROM referral_rewards WHERE id IN (${placeholders})`).bind(...chunk).first() as any
        postRrExistCount += Number(rows?.cnt || 0)
      }
    }

    return c.json({
      ok: postTxCount === 0,
      mode: 'EXEC',
      action: 'rollback-reverse-backfill-marker',
      tx_only: txOnly,
      pre_summary: summary,
      exec_result: {
        balance_adjusted_users: balanceAdjusted,
        rr_deleted: rrDeleted,
        dr_deleted: drDeleted,
        tx_deleted: txDeleted,
      },
      post_check: {
        tx_marker_remaining: postTxCount,
        rr_id_remaining: txOnly ? 'SKIPPED' : postRrExistCount,
        verified: postTxCount === 0 && (txOnly || postRrExistCount === 0),
      },
      duration_ms: Date.now() - t0,
    })
  } catch (error) {
    const durMs = Date.now() - t0
    console.error(`[ROLLBACK_RB] ERROR mode=${mode} duration_ms=${durMs}`, error)
    return c.json({ error: String(error), duration_ms: durMs }, 500)
  }
}

app.get('/api/diag/rollback-reverse-backfill-marker', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  return diagRollbackReverseBackfillMarker(c, 'DRY_RUN')
})

app.post('/api/diag/rollback-reverse-backfill-marker', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  const confirm = c.req.query('confirm') || ''
  if (confirm !== 'GO') return c.json({ error: 'confirm=GO 필요 (실 DELETE 게이트)' }, 400)
  return diagRollbackReverseBackfillMarker(c, 'EXEC')
})

// ============================================================================
// scan-may18-full: 2026-05-18 KST 일자 거래내역 + 보상 row 전체 분류
//   - tx (transactions): 5/18 KST 생성된 거 전부
//   - dr (daily_rewards): paid_date=5/18 또는 reward_date=5/18 또는 created 5/18 KST
//   - rr (referral_rewards): 위와 동일
//   - 각 row 의 tx 매칭 여부, description 마커, 시간대 분류
//
//   READ-ONLY, DB 변경 절대 없음
// ============================================================================
app.get('/api/diag/scan-may18-full', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  const db = (c.env as any).DB as D1Database

  // KST 날짜 — query param 'date' 로 override 가능 (기본 5/18)
  const KST_DATE = c.req.query('date') || '2026-05-18'

  // 1. 5/18 KST 생성된 transactions 전체
  const txAll = await db.prepare(`
    SELECT *,
           datetime(created_at, '+9 hours') as created_kst
    FROM transactions
    WHERE date(created_at, '+9 hours') = ?
    ORDER BY id ASC
  `).bind(KST_DATE).all()

  // 2. DR rows with paid_date=KST_DATE or reward_date=KST_DATE
  const drRows = await db.prepare(`
    SELECT *,
           datetime(created_at, '+9 hours') as created_kst
    FROM daily_rewards
    WHERE paid_date = ? OR reward_date = ?
    ORDER BY id ASC
  `).bind(KST_DATE, KST_DATE).all()

  // 3. RR rows with paid_date=KST_DATE or reward_date=KST_DATE
  const rrRows = await db.prepare(`
    SELECT *,
           datetime(created_at, '+9 hours') as created_kst
    FROM referral_rewards
    WHERE paid_date = ? OR reward_date = ?
    ORDER BY id ASC
  `).bind(KST_DATE, KST_DATE).all()

  // tx 분류: type, ref_id 매칭, description 마커
  const txByType: Record<string, { count: number, total: number, sample_ids: number[] }> = {}
  const txByHour: Record<string, { count: number, total: number }> = {}
  const txMarkers: Record<string, number> = {}
  for (const tx of (txAll.results || []) as any[]) {
    const t = String(tx.type)
    if (!txByType[t]) txByType[t] = { count: 0, total: 0, sample_ids: [] }
    txByType[t].count++
    txByType[t].total += Number(tx.amount || 0)
    if (txByType[t].sample_ids.length < 5) txByType[t].sample_ids.push(tx.id)

    const hh = String(tx.created_kst || '').substring(11, 13)
    const hkey = `${hh}:00`
    if (!txByHour[hkey]) txByHour[hkey] = { count: 0, total: 0 }
    txByHour[hkey].count++
    txByHour[hkey].total += Number(tx.amount || 0)

    const desc = String(tx.description || '')
    if (desc.includes('[REVERSE')) txMarkers['[REVERSE*]'] = (txMarkers['[REVERSE*]'] || 0) + 1
    if (desc.includes('[BACKFILL')) txMarkers['[BACKFILL*]'] = (txMarkers['[BACKFILL*]'] || 0) + 1
    if (desc.includes('[REDO')) txMarkers['[REDO*]'] = (txMarkers['[REDO*]'] || 0) + 1
    if (desc.includes('재정산')) txMarkers['재정산'] = (txMarkers['재정산'] || 0) + 1
    if (desc.includes('보정')) txMarkers['보정'] = (txMarkers['보정'] || 0) + 1
  }

  // DR/RR 분류
  const drBuckets: Record<string, { rows: number, total: number }> = {}
  for (const d of (drRows.results || []) as any[]) {
    const k = `reward=${d.reward_date} / paid=${d.paid_date}`
    if (!drBuckets[k]) drBuckets[k] = { rows: 0, total: 0 }
    drBuckets[k].rows++
    drBuckets[k].total += Number(d.amount || 0)
  }
  const rrBuckets: Record<string, { rows: number, total: number, staking_null: number }> = {}
  for (const r of (rrRows.results || []) as any[]) {
    const k = `reward=${r.reward_date} / paid=${r.paid_date} / L${r.level}`
    if (!rrBuckets[k]) rrBuckets[k] = { rows: 0, total: 0, staking_null: 0 }
    rrBuckets[k].rows++
    rrBuckets[k].total += Number(r.reward_amount || 0)
    if (r.staking_id == null) rrBuckets[k].staking_null++
  }

  // tx <-> DR/RR 매칭: type=daily_reward 면 ref_id=DR.id, type=referral_reward 면 ref_id=RR.id
  const drIds = new Set<number>((drRows.results || []).map((r: any) => r.id))
  const rrIds = new Set<number>((rrRows.results || []).map((r: any) => r.id))
  const txMatched = { daily: 0, referral: 0, orphan_daily: 0, orphan_referral: 0, other: 0 }
  for (const tx of (txAll.results || []) as any[]) {
    if (tx.type === 'daily_reward') {
      if (tx.ref_id && drIds.has(tx.ref_id)) txMatched.daily++
      else txMatched.orphan_daily++
    } else if (tx.type === 'referral_reward') {
      if (tx.ref_id && rrIds.has(tx.ref_id)) txMatched.referral++
      else txMatched.orphan_referral++
    } else {
      txMatched.other++
    }
  }

  // 시간대 buckets — 15시 (STEP 2) / 15:33 (REVERSE 사고) / 그 외 분류
  const txByMinute: Record<string, { count: number, total: number, types: Record<string, number> }> = {}
  for (const tx of (txAll.results || []) as any[]) {
    const ts = String(tx.created_kst || '')
    const mm = ts.substring(11, 16)  // HH:MM
    if (!txByMinute[mm]) txByMinute[mm] = { count: 0, total: 0, types: {} }
    txByMinute[mm].count++
    txByMinute[mm].total += Number(tx.amount || 0)
    txByMinute[mm].types[tx.type] = (txByMinute[mm].types[tx.type] || 0) + 1
  }
  const minuteSorted = Object.entries(txByMinute)
    .sort((a, b) => b[1].count - a[1].count)
    .slice(0, 30)
    .map(([k, v]) => ({ kst_minute: k, ...v }))

  return c.json({
    ok: true,
    mode: 'READ_ONLY_SCAN',
    action: 'scan-may18-full',
    kst_window: { start: '2026-05-18 00:00:00 KST', end: '2026-05-18 23:59:59 KST' },
    tx_total: {
      count: (txAll.results || []).length,
      total_amount: ((txAll.results || []) as any[]).reduce((s, r) => s + Number(r.amount || 0), 0),
    },
    tx_by_type: txByType,
    tx_markers_found: txMarkers,
    tx_matched_to_dr_rr: txMatched,
    tx_top_minutes: minuteSorted,
    dr_buckets: drBuckets,
    rr_buckets: rrBuckets,
    tx_sample_first_20: (txAll.results || []).slice(0, 20),
    tx_sample_last_20: (txAll.results || []).slice(-20),
    duration_ms: 0,
  })
})

// ============================================================================
// recompute-bottom-up-dividend: 영구룰 바텀업 로직으로 한 dividendDate 의
//   전체 사용자 expected vs actual 재정산 (READ-ONLY, 가감만 보고)
//
//   영구룰:
//     - 본인 DR: amount × daily_rate × 150
//     - L1: 추천한 사람의 DR × 20%
//     - L2: 추천인의 추천인의 DR × 10%
//     - #스테이킹별독립: 동일인이라도 staking_id 별개로 계산
//     - dividendDate 기준 active staking 만 (start ≤ dividendDate ≤ end)
//
//   actual_set = referral_rewards/daily_rewards WHERE reward_date=dividendDate
//   expected_set = 영구룰로 재계산
//   가감 = expected - actual
//
//   READ-ONLY, DB 변경 절대 없음
//
//   GET /api/diag/recompute-bottom-up-dividend?key=ADMIN_PW&dividendDate=2026-05-12&payoutDate=2026-05-13
// ============================================================================
app.get('/api/diag/recompute-bottom-up-dividend', async (c) => {
  const t0 = Date.now()
  try {
    const key = c.req.query('key') || ''
    if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
    const db = (c.env as any).DB as D1Database

    const dividendDate = c.req.query('dividendDate') || '2026-05-12'
    const payoutDate = c.req.query('payoutDate') || '2026-05-13'
    const USD_TO_QKEY = 150

    // ─── 1. dividendDate 에 active 였던 모든 staking 조회 ───
    const activeStakings = await db.prepare(`
      SELECT s.id AS staking_id, s.user_id, s.amount, s.daily_rate,
             u.name, u.email, u.referrer_id
      FROM staking s
      JOIN users u ON u.id = s.user_id
      WHERE s.status = 'active'
        AND date(s.start_date,'+9 hours') <= date(?)
        AND date(s.end_date,'+9 hours') >= date(?)
      ORDER BY s.user_id, s.id
    `).bind(dividendDate, dividendDate).all()
    const stakings = (activeStakings.results || []) as any[]

    // ─── 2. expected DR (본인 배당) — staking_id 단위 ───
    const expectedDR: any[] = []
    // expected RR — referrer_id 단위로 집계 (L1: amount×rate×150×0.20, L2: ...×0.10)
    const expectedL1: Record<number, { total: number, details: any[] }> = {}
    const expectedL2: Record<number, { total: number, details: any[] }> = {}

    // user_id → referrer_id 캐시
    const userMap = new Map<number, { name: string, email: string, referrer_id: number | null }>()
    for (const s of stakings) {
      if (!userMap.has(s.user_id)) {
        userMap.set(s.user_id, { name: s.name, email: s.email, referrer_id: s.referrer_id ?? null })
      }
    }
    // referrer_id 가 user_map 에 없는 경우 추가 조회
    const missingRefIds = new Set<number>()
    for (const v of userMap.values()) {
      if (v.referrer_id != null && !userMap.has(v.referrer_id)) missingRefIds.add(v.referrer_id)
    }
    if (missingRefIds.size > 0) {
      const idsList = [...missingRefIds]
      const placeholders = idsList.map(() => '?').join(',')
      const usersExtra = await db.prepare(`
        SELECT id, name, email, referrer_id FROM users WHERE id IN (${placeholders})
      `).bind(...idsList).all()
      for (const u of (usersExtra.results || []) as any[]) {
        userMap.set(u.id, { name: u.name, email: u.email, referrer_id: u.referrer_id ?? null })
      }
      // 2-hop 도 캐시
      const hop2: number[] = []
      for (const u of (usersExtra.results || []) as any[]) {
        if (u.referrer_id != null && !userMap.has(u.referrer_id)) hop2.push(u.referrer_id)
      }
      if (hop2.length > 0) {
        const p2 = hop2.map(() => '?').join(',')
        const u2 = await db.prepare(`
          SELECT id, name, email, referrer_id FROM users WHERE id IN (${p2})
        `).bind(...hop2).all()
        for (const u of (u2.results || []) as any[]) {
          userMap.set(u.id, { name: u.name, email: u.email, referrer_id: u.referrer_id ?? null })
        }
      }
    }

    // staking 별 계산
    for (const s of stakings) {
      const amt = Number(s.amount) || 0
      const rate = Number(s.daily_rate) || 0
      const dailyQkey = Math.round(amt * rate * USD_TO_QKEY)
      expectedDR.push({
        user_id: s.user_id, staking_id: s.staking_id,
        amount: amt, daily_rate: rate,
        qkey_amount: dailyQkey,
        formula: `${amt}×${rate}×${USD_TO_QKEY}=${dailyQkey}`,
      })

      // L1: refereeOwner 의 referrer → +20%
      const ownerInfo = userMap.get(s.user_id)
      const l1Id = ownerInfo?.referrer_id
      if (l1Id) {
        const l1Reward = Math.round(dailyQkey * 0.20)
        if (!expectedL1[l1Id]) expectedL1[l1Id] = { total: 0, details: [] }
        expectedL1[l1Id].total += l1Reward
        expectedL1[l1Id].details.push({
          referee_id: s.user_id, referee_staking_id: s.staking_id,
          referee_own_qkey: dailyQkey, l1_reward: l1Reward,
        })
        // L2: L1 의 referrer
        const l1Info = userMap.get(l1Id)
        const l2Id = l1Info?.referrer_id
        if (l2Id) {
          const l2Reward = Math.round(dailyQkey * 0.10)
          if (!expectedL2[l2Id]) expectedL2[l2Id] = { total: 0, details: [] }
          expectedL2[l2Id].total += l2Reward
          expectedL2[l2Id].details.push({
            l1_id: l1Id, referee_id: s.user_id, referee_staking_id: s.staking_id,
            referee_own_qkey: dailyQkey, l2_reward: l2Reward,
          })
        }
      }
    }

    // ─── 3. actual DR/RR (현재 DB) — reward_date=dividendDate ───
    //   ★ daily_rewards 컬럼은 usdt_amount (실제 QKEY 값 저장)
    const actualDR = await db.prepare(`
      SELECT id, user_id, staking_id, reward_date, paid_date, usdt_amount AS amount,
             datetime(created_at,'+9 hours') AS created_kst
      FROM daily_rewards
      WHERE reward_date = ?
      ORDER BY user_id, staking_id, id
    `).bind(dividendDate).all()
    const actualRR = await db.prepare(`
      SELECT id, referrer_id, referee_id, level, original_amount, reward_amount,
             reward_date, paid_date, staking_id,
             datetime(created_at,'+9 hours') AS created_kst
      FROM referral_rewards
      WHERE reward_date = ?
      ORDER BY referrer_id, referee_id, level, id
    `).bind(dividendDate).all()
    const actDR = (actualDR.results || []) as any[]
    const actRR = (actualRR.results || []) as any[]

    // actual DR: user_id+staking_id 별 amount 합
    const actualDRMap = new Map<string, { rows: number, total: number, ids: number[] }>()
    for (const r of actDR) {
      const k = `${r.user_id}|${r.staking_id ?? 'NULL'}`
      if (!actualDRMap.has(k)) actualDRMap.set(k, { rows: 0, total: 0, ids: [] })
      const e = actualDRMap.get(k)!
      e.rows++
      e.total += Number(r.amount || 0)
      e.ids.push(r.id)
    }
    // actual RR: referrer_id+level 별 합 (사장님 4-tuple idempotency)
    const actualL1Map = new Map<number, { rows: number, total: number, ids: number[], staking_null: number }>()
    const actualL2Map = new Map<number, { rows: number, total: number, ids: number[], staking_null: number }>()
    for (const r of actRR) {
      const m = r.level === 1 ? actualL1Map : (r.level === 2 ? actualL2Map : null)
      if (!m) continue
      if (!m.has(r.referrer_id)) m.set(r.referrer_id, { rows: 0, total: 0, ids: [], staking_null: 0 })
      const e = m.get(r.referrer_id)!
      e.rows++
      e.total += Number(r.reward_amount || 0)
      e.ids.push(r.id)
      if (r.staking_id == null) e.staking_null++
    }

    // ─── 4. expected DR ↔ actual DR 비교 (staking_id 단위) ───
    const drDiff: any[] = []
    let drExpectedTotal = 0, drActualTotal = 0
    for (const e of expectedDR) {
      drExpectedTotal += e.qkey_amount
      const k = `${e.user_id}|${e.staking_id}`
      const a = actualDRMap.get(k)
      const actualAmt = a?.total || 0
      const delta = e.qkey_amount - actualAmt
      if (delta !== 0 || !a) {
        drDiff.push({
          user_id: e.user_id, staking_id: e.staking_id,
          expected: e.qkey_amount, actual: actualAmt, delta,
          actual_row_ids: a?.ids || [],
          status: !a ? 'MISSING' : (delta > 0 ? 'UNDERPAID' : 'OVERPAID'),
        })
      }
    }
    for (const a of actDR) drActualTotal += Number(a.amount || 0)

    // 잉여 DR (expected 에 없는데 actual 에만 있는 것)
    const expectedDRKeys = new Set(expectedDR.map(e => `${e.user_id}|${e.staking_id}`))
    const drOrphan: any[] = []
    for (const [k, v] of actualDRMap.entries()) {
      if (!expectedDRKeys.has(k)) {
        const [uid, sid] = k.split('|')
        drOrphan.push({ user_id: Number(uid), staking_id: sid, rows: v.rows, actual: v.total, ids: v.ids })
      }
    }

    // ─── 5. expected L1 ↔ actual L1 비교 (referrer_id 단위) ───
    const l1Diff: any[] = []
    let l1ExpectedTotal = 0
    for (const [refId, v] of Object.entries(expectedL1)) {
      l1ExpectedTotal += v.total
      const refIdN = Number(refId)
      const a = actualL1Map.get(refIdN)
      const actualAmt = a?.total || 0
      const delta = v.total - actualAmt
      if (delta !== 0 || !a) {
        const info = userMap.get(refIdN)
        l1Diff.push({
          referrer_id: refIdN, name: info?.name, email: info?.email,
          expected: v.total, actual: actualAmt, delta,
          actual_row_ids: a?.ids || [],
          actual_staking_null: a?.staking_null || 0,
          status: !a ? 'MISSING' : (delta > 0 ? 'UNDERPAID' : 'OVERPAID'),
        })
      }
    }
    let l1ActualTotal = 0
    for (const v of actualL1Map.values()) l1ActualTotal += v.total

    // 잉여 L1 (expected 에 없는데 actual 에 있는 referrer)
    const l1Orphan: any[] = []
    for (const [refId, v] of actualL1Map.entries()) {
      if (!expectedL1[refId]) {
        const info = userMap.get(refId)
        l1Orphan.push({
          referrer_id: refId, name: info?.name, email: info?.email,
          rows: v.rows, actual: v.total, staking_null: v.staking_null, ids: v.ids,
        })
      }
    }

    // ─── 6. expected L2 ↔ actual L2 비교 ───
    const l2Diff: any[] = []
    let l2ExpectedTotal = 0
    for (const [refId, v] of Object.entries(expectedL2)) {
      l2ExpectedTotal += v.total
      const refIdN = Number(refId)
      const a = actualL2Map.get(refIdN)
      const actualAmt = a?.total || 0
      const delta = v.total - actualAmt
      if (delta !== 0 || !a) {
        const info = userMap.get(refIdN)
        l2Diff.push({
          referrer_id: refIdN, name: info?.name, email: info?.email,
          expected: v.total, actual: actualAmt, delta,
          actual_row_ids: a?.ids || [],
          actual_staking_null: a?.staking_null || 0,
          status: !a ? 'MISSING' : (delta > 0 ? 'UNDERPAID' : 'OVERPAID'),
        })
      }
    }
    let l2ActualTotal = 0
    for (const v of actualL2Map.values()) l2ActualTotal += v.total
    const l2Orphan: any[] = []
    for (const [refId, v] of actualL2Map.entries()) {
      if (!expectedL2[refId]) {
        const info = userMap.get(refId)
        l2Orphan.push({
          referrer_id: refId, name: info?.name, email: info?.email,
          rows: v.rows, actual: v.total, staking_null: v.staking_null, ids: v.ids,
        })
      }
    }

    // ─── 사용자별 종합 가감 ───
    const userDelta = new Map<number, { dr: number, l1: number, l2: number, total: number, name?: string, email?: string }>()
    function addDelta(uid: number, kind: 'dr'|'l1'|'l2', delta: number) {
      if (!userDelta.has(uid)) {
        const info = userMap.get(uid)
        userDelta.set(uid, { dr: 0, l1: 0, l2: 0, total: 0, name: info?.name, email: info?.email })
      }
      const e = userDelta.get(uid)!
      e[kind] += delta
      e.total += delta
    }
    for (const d of drDiff) addDelta(d.user_id, 'dr', d.delta)
    for (const d of drOrphan) addDelta(d.user_id, 'dr', -d.actual)
    for (const d of l1Diff) addDelta(d.referrer_id, 'l1', d.delta)
    for (const d of l1Orphan) addDelta(d.referrer_id, 'l1', -d.actual)
    for (const d of l2Diff) addDelta(d.referrer_id, 'l2', d.delta)
    for (const d of l2Orphan) addDelta(d.referrer_id, 'l2', -d.actual)

    const userDeltaArr = [...userDelta.entries()]
      .map(([uid, v]) => ({ user_id: uid, ...v }))
      .filter(r => r.total !== 0)
      .sort((a, b) => Math.abs(b.total) - Math.abs(a.total))

    return c.json({
      ok: true,
      mode: 'READ_ONLY_RECOMPUTE',
      action: 'recompute-bottom-up-dividend',
      input: { dividendDate, payoutDate, USD_TO_QKEY },
      summary: {
        active_stakings: stakings.length,
        expected_dr_count: expectedDR.length,
        expected_l1_referrers: Object.keys(expectedL1).length,
        expected_l2_referrers: Object.keys(expectedL2).length,
        actual_dr_rows: actDR.length,
        actual_rr_rows: actRR.length,
      },
      totals: {
        dr: { expected: drExpectedTotal, actual: drActualTotal, delta: drExpectedTotal - drActualTotal },
        l1: { expected: l1ExpectedTotal, actual: l1ActualTotal, delta: l1ExpectedTotal - l1ActualTotal },
        l2: { expected: l2ExpectedTotal, actual: l2ActualTotal, delta: l2ExpectedTotal - l2ActualTotal },
        grand: {
          expected: drExpectedTotal + l1ExpectedTotal + l2ExpectedTotal,
          actual: drActualTotal + l1ActualTotal + l2ActualTotal,
          delta: (drExpectedTotal + l1ExpectedTotal + l2ExpectedTotal) - (drActualTotal + l1ActualTotal + l2ActualTotal),
        },
      },
      diff_counts: {
        dr_diff: drDiff.length, dr_orphan: drOrphan.length,
        l1_diff: l1Diff.length, l1_orphan: l1Orphan.length,
        l2_diff: l2Diff.length, l2_orphan: l2Orphan.length,
      },
      user_delta_top20: userDeltaArr.slice(0, 20),
      user_delta_count: userDeltaArr.length,
      dr_diff_sample: drDiff.slice(0, 10),
      dr_orphan_sample: drOrphan.slice(0, 10),
      l1_diff_sample: l1Diff.slice(0, 10),
      l1_orphan_sample: l1Orphan.slice(0, 10),
      l2_diff_sample: l2Diff.slice(0, 10),
      l2_orphan_sample: l2Orphan.slice(0, 10),
      duration_ms: Date.now() - t0,
    })
  } catch (e: any) {
    return c.json({ ok: false, error: String(e?.message || e), stack: e?.stack }, 500)
  }
})

// ============================================================================
// reconcile-bottom-up-dividend: 영구룰 expected vs actual 가감을 실제 DB 에 반영
//
//   계산 방식 (recompute-bottom-up-dividend 와 정확히 동일):
//     - expected DR: staking 별 amount × daily_rate × 150
//     - expected L1: 본인이 추천한 사람의 DR × 0.20
//     - expected L2: 추천인의 추천인의 DR × 0.10
//     - #스테이킹별독립 (staking_id 단위)
//
//   조치 (DRY-RUN/EXEC 분리):
//     [A] 잉여 RR row 삭제 + 매칭 transactions 삭제 + balance 차감
//         - actual_referrer L1/L2 에서 영구룰 expected 초과분만큼
//         - staking_id=NULL 우선 삭제 (legacy 사고 흔적)
//     [B] 누락 RR row INSERT + transactions INSERT + balance 가산
//         - expected referrer 의 staking_null + missing 분만큼
//
//   marker: description 에 `[RECONCILE 2026-05-12→2026-05-13]` 박음 (추후 식별/롤백용)
//
//   GET  /api/diag/reconcile-bottom-up-dividend?key=...&dividendDate=2026-05-12&payoutDate=2026-05-13 → DRY_RUN
//   POST /api/diag/reconcile-bottom-up-dividend?key=...&dividendDate=...&payoutDate=...&confirm=GO → EXEC
// ============================================================================
async function diagReconcileBottomUpDividend(c: any, mode: 'DRY_RUN' | 'EXEC') {
  const t0 = Date.now()
  try {
    const db = c.env.DB as D1Database
    const dividendDate = c.req.query('dividendDate') || '2026-05-12'
    const payoutDate = c.req.query('payoutDate') || '2026-05-13'
    const USD_TO_QKEY = 150
    const MARKER = `[RECONCILE ${dividendDate}→${payoutDate}]`

    // ── 1. expected 재계산 (recompute 와 동일) ──
    const stRows = await db.prepare(`
      SELECT s.id AS staking_id, s.user_id, s.amount, s.daily_rate,
             u.referrer_id
      FROM staking s
      JOIN users u ON u.id = s.user_id
      WHERE s.status = 'active'
        AND date(s.start_date,'+9 hours') <= date(?)
        AND date(s.end_date,'+9 hours') >= date(?)
      ORDER BY s.user_id, s.id
    `).bind(dividendDate, dividendDate).all()
    const stakings = (stRows.results || []) as any[]

    // userMap: 2-hop 까지 referrer 캐시
    const userMap = new Map<number, { referrer_id: number | null }>()
    for (const s of stakings) {
      if (!userMap.has(s.user_id)) userMap.set(s.user_id, { referrer_id: s.referrer_id ?? null })
    }
    const hop1: number[] = []
    for (const v of userMap.values()) if (v.referrer_id != null && !userMap.has(v.referrer_id)) hop1.push(v.referrer_id)
    if (hop1.length > 0) {
      const ph = hop1.map(() => '?').join(',')
      const r1 = await db.prepare(`SELECT id, referrer_id FROM users WHERE id IN (${ph})`).bind(...hop1).all()
      const hop2: number[] = []
      for (const u of (r1.results || []) as any[]) {
        userMap.set(u.id, { referrer_id: u.referrer_id ?? null })
        if (u.referrer_id != null && !userMap.has(u.referrer_id)) hop2.push(u.referrer_id)
      }
      if (hop2.length > 0) {
        const ph2 = hop2.map(() => '?').join(',')
        const r2 = await db.prepare(`SELECT id, referrer_id FROM users WHERE id IN (${ph2})`).bind(...hop2).all()
        for (const u of (r2.results || []) as any[]) {
          userMap.set(u.id, { referrer_id: u.referrer_id ?? null })
        }
      }
    }

    // expected L1/L2: referrer_id → { total, details: [{ referee_id, referee_staking_id, qkeyAmount, reward }] }
    const expectedL1 = new Map<number, { total: number, details: any[] }>()
    const expectedL2 = new Map<number, { total: number, details: any[] }>()
    for (const s of stakings) {
      const qkey = Math.round(Number(s.amount) * Number(s.daily_rate) * USD_TO_QKEY)
      const l1Id = userMap.get(s.user_id)?.referrer_id
      if (l1Id) {
        const r = Math.round(qkey * 0.20)
        if (!expectedL1.has(l1Id)) expectedL1.set(l1Id, { total: 0, details: [] })
        const e = expectedL1.get(l1Id)!
        e.total += r
        e.details.push({ referee_id: s.user_id, referee_staking_id: s.staking_id, qkey, reward: r })
        const l2Id = userMap.get(l1Id)?.referrer_id
        if (l2Id) {
          const r2 = Math.round(qkey * 0.10)
          if (!expectedL2.has(l2Id)) expectedL2.set(l2Id, { total: 0, details: [] })
          const e2 = expectedL2.get(l2Id)!
          e2.total += r2
          e2.details.push({ l1_id: l1Id, referee_id: s.user_id, referee_staking_id: s.staking_id, qkey, reward: r2 })
        }
      }
    }

    // ── 2. actual RR (reward_date=dividendDate) — staking_null 우선 정렬 ──
    const actualRR = await db.prepare(`
      SELECT id, referrer_id, referee_id, level, original_amount, reward_amount,
             reward_date, paid_date, staking_id
      FROM referral_rewards
      WHERE reward_date = ?
      ORDER BY referrer_id, level,
        CASE WHEN staking_id IS NULL THEN 0 ELSE 1 END,
        paid_date DESC, id DESC
    `).bind(dividendDate).all()
    const actRR = (actualRR.results || []) as any[]

    // actual map: referrer_id+level 별
    const actMap = new Map<string, any[]>()
    for (const r of actRR) {
      const k = `${r.referrer_id}|${r.level}`
      if (!actMap.has(k)) actMap.set(k, [])
      actMap.get(k)!.push(r)
    }

    // ── 3. 잉여 (OVERPAID) RR row 식별 — staking_null 우선 삭제 ──
    const overpaidDeletes: any[] = []  // { rr_id, referrer_id, level, reward_amount, staking_id }
    // 모든 (referrer, level) 쌍 처리
    const allKeys = new Set<string>()
    for (const k of actMap.keys()) allKeys.add(k)
    for (const refId of expectedL1.keys()) allKeys.add(`${refId}|1`)
    for (const refId of expectedL2.keys()) allKeys.add(`${refId}|2`)

    for (const k of allKeys) {
      const [refIdStr, lvStr] = k.split('|')
      const refId = Number(refIdStr)
      const lv = Number(lvStr)
      const expected = lv === 1 ? (expectedL1.get(refId)?.total || 0) : (expectedL2.get(refId)?.total || 0)
      const actualRows = actMap.get(k) || []
      const actualTotal = actualRows.reduce((s, r) => s + Number(r.reward_amount || 0), 0)
      let overage = actualTotal - expected
      if (overage <= 0) continue
      // staking_null 부터 (이미 ORDER BY 로 정렬됨)
      for (const r of actualRows) {
        if (overage <= 0) break
        const amt = Number(r.reward_amount || 0)
        if (amt <= overage) {
          overpaidDeletes.push({
            rr_id: r.id, referrer_id: refId, level: lv,
            reward_amount: amt, staking_id: r.staking_id, paid_date: r.paid_date,
          })
          overage -= amt
        }
        // 부분 차감(같은 amount 가 정확히 안 떨어지면) 안전을 위해 skip — 차후 누락 INSERT 단계서 해결
      }
    }
    const overpaidRrIds = new Set(overpaidDeletes.map(x => x.rr_id))

    // 삭제 후 남는 actual map 재계산
    const remainAct = new Map<string, number>()
    for (const r of actRR) {
      if (overpaidRrIds.has(r.id)) continue
      const k = `${r.referrer_id}|${r.level}`
      remainAct.set(k, (remainAct.get(k) || 0) + Number(r.reward_amount || 0))
    }

    // ── 4. 누락 (MISSING/UNDERPAID) — 새 RR INSERT 후보 ──
    //   잔여 actual < expected 인 (referrer, level) 에 대해
    //   expected 의 details 중 아직 actual_set 에 staking_id 매칭 안 된 것 INSERT
    const newInserts: any[] = [] // { referrer_id, referee_id, level, original_amount, reward_amount, staking_id }
    // 현재 staking_id 별 actual 보유 set
    const actByStakingKey = new Set<string>()
    for (const r of actRR) {
      if (overpaidRrIds.has(r.id)) continue
      if (r.staking_id != null) {
        actByStakingKey.add(`${r.referrer_id}|${r.referee_id}|${r.level}|${r.staking_id}`)
      }
    }

    function deficit(refId: number, lv: number): number {
      const exp = lv === 1 ? (expectedL1.get(refId)?.total || 0) : (expectedL2.get(refId)?.total || 0)
      return Math.max(0, exp - (remainAct.get(`${refId}|${lv}`) || 0))
    }

    for (const [refId, e] of expectedL1.entries()) {
      let need = deficit(refId, 1)
      if (need <= 0) continue
      for (const d of e.details) {
        const key = `${refId}|${d.referee_id}|1|${d.referee_staking_id}`
        if (actByStakingKey.has(key)) continue
        // 이 staking_id 에 대응하는 actual L1 없음 → INSERT 후보
        newInserts.push({
          referrer_id: refId, referee_id: d.referee_id, level: 1,
          original_amount: d.qkey, reward_amount: d.reward, staking_id: d.referee_staking_id,
        })
        need -= d.reward
        actByStakingKey.add(key)
        if (need <= 0) break
      }
    }
    for (const [refId, e] of expectedL2.entries()) {
      let need = deficit(refId, 2)
      if (need <= 0) continue
      for (const d of e.details) {
        const key = `${refId}|${d.referee_id}|2|${d.referee_staking_id}`
        if (actByStakingKey.has(key)) continue
        newInserts.push({
          referrer_id: refId, referee_id: d.referee_id, level: 2,
          original_amount: d.qkey, reward_amount: d.reward, staking_id: d.referee_staking_id,
        })
        need -= d.reward
        actByStakingKey.add(key)
        if (need <= 0) break
      }
    }

    // ── 5. balance delta 사용자별 집계 (-삭제분 +INSERT분) ──
    const balanceDelta = new Map<number, number>()
    for (const x of overpaidDeletes) {
      balanceDelta.set(x.referrer_id, (balanceDelta.get(x.referrer_id) || 0) - x.reward_amount)
    }
    for (const x of newInserts) {
      balanceDelta.set(x.referrer_id, (balanceDelta.get(x.referrer_id) || 0) + x.reward_amount)
    }

    // 음수 잔고 체크
    const uids = [...balanceDelta.keys()]
    const balRows = uids.length > 0
      ? await db.prepare(`SELECT id, name, email, qkey_balance FROM users WHERE id IN (${uids.map(() => '?').join(',')})`).bind(...uids).all()
      : { results: [] }
    const balMap = new Map<number, any>()
    for (const u of (balRows.results || []) as any[]) balMap.set(u.id, u)
    const balanceImpact = uids.map(uid => {
      const u = balMap.get(uid)
      const delta = balanceDelta.get(uid)!
      const cur = Number(u?.qkey_balance || 0)
      const post = cur + delta
      return {
        user_id: uid, name: u?.name, email: u?.email,
        current_balance: cur, delta, post_balance: post,
        will_go_negative: post < 0 && cur >= 0,
      }
    }).sort((a, b) => a.delta - b.delta)

    // 정합 검증
    const totalDeleteAmt = overpaidDeletes.reduce((s, x) => s + x.reward_amount, 0)
    const totalInsertAmt = newInserts.reduce((s, x) => s + x.reward_amount, 0)
    const netChange = totalInsertAmt - totalDeleteAmt

    // ── DRY_RUN 보고 ──
    if (mode === 'DRY_RUN') {
      return c.json({
        ok: true,
        mode: 'DRY_RUN',
        action: 'reconcile-bottom-up-dividend',
        input: { dividendDate, payoutDate, USD_TO_QKEY, marker: MARKER },
        plan: {
          delete_rr_count: overpaidDeletes.length,
          delete_amount: totalDeleteAmt,
          insert_rr_count: newInserts.length,
          insert_amount: totalInsertAmt,
          net_change: netChange,
          affected_users: uids.length,
        },
        balance_impact: balanceImpact,
        delete_sample: overpaidDeletes.slice(0, 20),
        insert_sample: newInserts.slice(0, 20),
        delete_staking_null_count: overpaidDeletes.filter(x => x.staking_id == null).length,
        next_action: 'POST + confirm=GO 보내시면 EXEC. set-based batch.',
        duration_ms: Date.now() - t0,
      })
    }

    // ── EXEC ──
    // 음수 잔고 발생 시 자동 중단 (current >= 0 이었던 사용자만 체크)
    const goNeg = balanceImpact.filter(b => b.will_go_negative)
    if (goNeg.length > 0) {
      return c.json({
        ok: false,
        error: '음수 잔고 발생 위험 — EXEC 중단',
        will_go_negative_users: goNeg,
        plan: {
          delete_rr_count: overpaidDeletes.length,
          insert_rr_count: newInserts.length,
        },
      }, 400)
    }

    // 5-1. RR DELETE (chunked batch) + matching tx DELETE
    const CHUNK = 50
    let rrDeleted = 0, txDeleted = 0, rrInserted = 0, txInserted = 0
    for (let i = 0; i < overpaidDeletes.length; i += CHUNK) {
      const slice = overpaidDeletes.slice(i, i + CHUNK)
      const rrIds = slice.map(x => x.rr_id)
      const ph = rrIds.map(() => '?').join(',')
      const stmts: any[] = []
      // tx 매칭은 type=referral_reward AND ref_id IN (...)
      stmts.push(db.prepare(`DELETE FROM transactions WHERE type = 'referral_reward' AND ref_id IN (${ph})`).bind(...rrIds))
      stmts.push(db.prepare(`DELETE FROM referral_rewards WHERE id IN (${ph})`).bind(...rrIds))
      const res = await db.batch(stmts)
      txDeleted += Number((res[0] as any)?.meta?.changes || 0)
      rrDeleted += Number((res[1] as any)?.meta?.changes || 0)
    }

    // 5-2. RR INSERT + tx INSERT (개별 — last_row_id 캡처 필요)
    for (const x of newInserts) {
      const desc = `추천 보너스 (Level ${x.level}) ${MARKER}`
      const rrIns = await db.prepare(`
        INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, staking_id)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
      `).bind(x.referrer_id, x.referee_id, x.level, x.original_amount, x.reward_amount, dividendDate, payoutDate, x.staking_id).run()
      const rrId = (rrIns as any)?.meta?.last_row_id
      if (rrId) {
        await db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id)
          VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?)
        `).bind(x.referrer_id, x.reward_amount, desc, rrId).run()
        rrInserted++
        txInserted++
      }
    }

    // 5-3. balance 조정 (chunked UPDATE)
    for (const b of balanceImpact) {
      if (b.delta === 0) continue
      await db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(b.delta, b.user_id).run()
    }

    // ── POST-CHECK ──
    const postRR = await db.prepare(`
      SELECT level, COUNT(*) AS rows, COALESCE(SUM(reward_amount),0) AS total
      FROM referral_rewards WHERE reward_date = ?
      GROUP BY level
    `).bind(dividendDate).all()

    return c.json({
      ok: true,
      mode: 'EXEC',
      action: 'reconcile-bottom-up-dividend',
      input: { dividendDate, payoutDate, marker: MARKER },
      exec_result: {
        rr_deleted: rrDeleted,
        tx_deleted: txDeleted,
        rr_inserted: rrInserted,
        tx_inserted: txInserted,
        balance_adjusted_users: balanceImpact.filter(b => b.delta !== 0).length,
        net_qkey_change: netChange,
      },
      post_check: {
        rr_by_level: postRR.results || [],
      },
      duration_ms: Date.now() - t0,
    })
  } catch (e: any) {
    return c.json({ ok: false, error: String(e?.message || e), stack: e?.stack }, 500)
  }
}
app.get('/api/diag/reconcile-bottom-up-dividend', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  return diagReconcileBottomUpDividend(c, 'DRY_RUN')
})
app.post('/api/diag/reconcile-bottom-up-dividend', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  const confirm = c.req.query('confirm') || ''
  if (confirm !== 'GO') return c.json({ error: 'confirm=GO 필요 (실 변경 게이트)' }, 400)
  return diagReconcileBottomUpDividend(c, 'EXEC')
})

// ============================================================================
// recalc-day-dividend: 사장님 영구룰 #바텀업정산 정확 구현 (2026-05-18 확정)
// ============================================================================
//
//   사장님 영구룰 원문 (직전 격노):
//   > "영구룰이 바텀업 방식이고 내가 정해줬으면 해당날짜의 사용자수와 진입금액을
//   >  다 따져보고 바닥부터 위로 올라가서 정산하고 끝내라니깐!"
//
//   알고리즘:
//   ─────────────────────────────────────────────────────────────
//   입력: dividendDate (예: 2026-05-12) — reward 발생일
//   처리:
//     ① dividendDate 가 휴일(토/일/공휴일)이면 → 전부 0 (skip)
//     ② payoutDate = PAID_CALENDAR[dividendDate] (그 다음 영업일)
//     ③ 그 날짜의 active staking 모두 조회
//        (start_date <= dividendDate AND end_date >= dividendDate, status='active')
//     ④ 바텀업 영구룰 계산 (200% Cap 적용 — B 옵션):
//        - 각 staking 의 own_DR = amount × daily_rate × 150
//        - referrer(L1) 가 active 면 → L1_RR = own_DR × 0.20 (수신자 cap 체크)
//        - referrer 의 referrer(L2) 가 active 면 → L2_RR = own_DR × 0.10 (cap 체크)
//        - cap 도달 시: 본인 staking status='capped' 처리, 신규 reward 0
//     ⑤ EXEC (그 reward_date 통째로 삭제 후 새로 INSERT):
//        a. DELETE FROM daily_rewards WHERE reward_date=dividendDate
//           (영향 ref_id 수집해서 tx 도 매칭 삭제)
//        b. DELETE FROM referral_rewards WHERE reward_date=dividendDate
//           (영향 ref_id 수집해서 tx 도 매칭 삭제)
//        c. DELETE FROM transactions
//           WHERE (type='daily_qkey' AND ref_id IN <삭제된 dr.id>)
//              OR (type='referral_reward' AND ref_id IN <삭제된 rr.id>)
//        d. balance 복구: 삭제된 tx amount 만큼 user.qkey_balance 차감
//        e. INSERT 새 DR/RR (영구룰 amount, 마커 없는 description)
//        f. balance 가산: 새 INSERT amount 만큼 user.qkey_balance 가산
//        g. tx INSERT (description: '일일 배당 (QKEY)' / '추천 보너스 (Level 1)' / '추천 보너스 (Level 2)')
//     ⑥ POST-CHECK
//
//   사장님 절대 명령:
//     - description 에 마커 박지 말 것 (이전 [RECONCILE / REVERSE_BACKFILL 사고)
//     - 그 dividendDate 의 모든 DR/RR/tx 통째 삭제 후 새 INSERT
//     - 200% Cap 무조건 적용
//     - 매 dividendDate 한 번에 완결
//
//   엔드포인트:
//     GET  /api/diag/recalc-day-dividend?key=ADMIN_PW&dividendDate=YYYY-MM-DD     → DRY_RUN
//     POST /api/diag/recalc-day-dividend?key=ADMIN_PW&dividendDate=YYYY-MM-DD&confirm=GO  → EXEC
//
//   PAID_CALENDAR (어드민이 직접 지정한 경우 payoutDate query param 으로 override 가능):
//     dividendDate 평일 → payoutDate = 다음 영업일 (자동)
//     dividendDate 휴일 → expected 0, skip
// ============================================================================
async function diagRecalcDayDividend(c: any, mode: 'DRY_RUN' | 'EXEC') {
  const t0 = Date.now()
  try {
    const db = c.env.DB
    const USD_TO_QKEY = 150
    const dividendDate = c.req.query('dividendDate') || ''
    if (!/^\d{4}-\d{2}-\d{2}$/.test(dividendDate)) {
      return c.json({ error: 'dividendDate=YYYY-MM-DD 필수' }, 400)
    }

    // ─── (0) dividendDate 휴일 여부 체크 ───
    //   isKoreanBusinessDay 는 Date 객체를 받음 (UTC 시각이지만 +9h 보정 내부 처리)
    //   KST 자정의 UTC 시각: dividendDate T 00:00:00 KST = (dividendDate - 1) T 15:00:00 UTC
    //   하지만 isKoreanBusinessDay 의 내부 +9h 보정 때문에 그냥 (dividendDate T 00:00:00 UTC) 넘겨도 OK
    //   (확인됨: getStakingAccrualDatesKst 도 같은 방식 사용)
    const ddObj = new Date(dividendDate + 'T00:00:00Z')
    const ddCheck = new Date(ddObj.getTime() - 9 * 60 * 60 * 1000)
    const { isBusinessDay: ddIsBiz, reason: ddReason } = isKoreanBusinessDay(ddCheck)

    if (!ddIsBiz) {
      return c.json({
        ok: true,
        mode,
        action: 'recalc-day-dividend',
        dividendDate,
        is_business_day: false,
        reason: ddReason,
        message: `${dividendDate} 는 ${ddReason} — 영구룰 #휴일발생금지: expected reward 0건`,
        duration_ms: Date.now() - t0,
      })
    }

    // ─── (1) payoutDate 계산 ───
    //   사장님 PAID_CALENDAR: dividendDate 의 다음 영업일
    //   query param payoutDate 로 override 가능 (수동 백필 등)
    let payoutDate = c.req.query('payoutDate') || ''
    if (!/^\d{4}-\d{2}-\d{2}$/.test(payoutDate)) {
      // 자동 계산: dividendDate 의 다음 영업일
      let cursor = new Date(ddObj.getTime() + 24 * 60 * 60 * 1000)
      let safety = 0
      while (safety < 14) {
        const cursorCheck = new Date(cursor.getTime() - 9 * 60 * 60 * 1000)
        const { isBusinessDay } = isKoreanBusinessDay(cursorCheck)
        if (isBusinessDay) {
          payoutDate = cursor.toISOString().split('T')[0]
          break
        }
        cursor = new Date(cursor.getTime() + 24 * 60 * 60 * 1000)
        safety++
      }
      if (!payoutDate) {
        return c.json({ error: 'payoutDate 자동 계산 실패' }, 500)
      }
    }

    // ─── (2) 그 dividendDate 의 active staking 모두 조회 ───
    //   period_days 가 활성화된 staking 의 start_date_kst <= dividendDate <= end_date_kst
    const activeStakings = await db.prepare(`
      SELECT s.id AS staking_id, s.user_id, s.amount, s.daily_rate, s.period_days,
             date(s.start_date,'+9 hours') AS start_kst,
             date(s.end_date,'+9 hours') AS end_kst,
             s.status,
             u.referrer_id
      FROM staking s
      JOIN users u ON u.id = s.user_id
      WHERE s.status IN ('active','capped','completed')
        AND date(s.start_date,'+9 hours') <= ?
        AND date(s.end_date,'+9 hours') >= ?
      ORDER BY s.id ASC
    `).bind(dividendDate, dividendDate).all()
    const stakingList = (activeStakings.results || []) as any[]

    // ─── (3) 영구룰 expected 계산 (200% Cap 적용 — B 옵션, 바텀업 순서) ───
    //   바닥 (각 staking 의 own_daily) 부터 올라가서 L1/L2 가산
    //   200% Cap: 사용자 단위 paidTotal + 이번 round 누적 reward >= target 이면 차단/부분지급
    //
    //   ★ 중요: cap 계산 시 paidTotal 은 "현재 DB 상태의 daily_qkey + referral_reward 합계"
    //         하지만 이번 EXEC 에서 이 dividendDate row 들을 통째 삭제 후 새로 INSERT 하므로
    //         "cap 기준 paidTotal" 은 "기존 DB - 이번 dividendDate 의 기존 row 합계" 로 계산해야
    //         재계산 시 cap 도달 위치가 일관됨

    //   ① 각 사용자의 stake_total (cap target)
    const userStakeTotal = new Map<number, number>()
    {
      const allUserIds = new Set<number>()
      for (const s of stakingList) allUserIds.add(Number(s.user_id))
      // 추가로 referrer / referrer.referrer 도 미리 수집 (cap 계산용)
      for (const s of stakingList) {
        if (s.referrer_id) allUserIds.add(Number(s.referrer_id))
      }
      // L2 referrer 까지 한 번에 조회
      const allIdsArr = Array.from(allUserIds)
      if (allIdsArr.length > 0) {
        const placeholders = allIdsArr.map(() => '?').join(',')
        const refRows = await db.prepare(`SELECT id, referrer_id FROM users WHERE id IN (${placeholders})`).bind(...allIdsArr).all()
        for (const u of (refRows.results || []) as any[]) {
          if (u.referrer_id) allUserIds.add(Number(u.referrer_id))
        }
      }
      // 모든 후보 사용자의 stake_total 조회
      const allIdsArr2 = Array.from(allUserIds)
      if (allIdsArr2.length > 0) {
        const CHUNK = 100
        for (let i = 0; i < allIdsArr2.length; i += CHUNK) {
          const chunk = allIdsArr2.slice(i, i + CHUNK)
          const placeholders = chunk.map(() => '?').join(',')
          const rows = await db.prepare(`
            SELECT user_id, COALESCE(SUM(amount),0) AS total
            FROM staking WHERE user_id IN (${placeholders})
              AND status IN ('active','completed','capped')
            GROUP BY user_id
          `).bind(...chunk).all()
          for (const r of (rows.results || []) as any[]) {
            userStakeTotal.set(Number(r.user_id), Number(r.total))
          }
        }
      }
    }

    //   ② 각 사용자의 paidTotal_excluding_thisDate = (현재 DB paidTotal) - (이번 dividendDate 의 기존 row 합계)
    //     - 기존 dr/rr row 가 cron 사고로 잘못 들어있을 수 있으니
    //     - 재계산 기준은 "이 dividendDate 빼면 paid 가 얼마였나" 로 잡아야 cap 위치 일관
    //     - reward_date=dividendDate 인 dr/rr 의 amount 합계 사용자별
    const userPaidExcl = new Map<number, number>()
    {
      const allCandidateIds = Array.from(userStakeTotal.keys())
      if (allCandidateIds.length > 0) {
        const CHUNK = 100
        for (let i = 0; i < allCandidateIds.length; i += CHUNK) {
          const chunk = allCandidateIds.slice(i, i + CHUNK)
          const placeholders = chunk.map(() => '?').join(',')
          // 현재 paidTotal (daily_qkey + referral_reward in transactions)
          const txTotalRows = await db.prepare(`
            SELECT user_id, COALESCE(SUM(amount),0) AS total
            FROM transactions
            WHERE user_id IN (${placeholders}) AND coin_type='QKEY'
              AND type IN ('daily_qkey','referral_reward')
            GROUP BY user_id
          `).bind(...chunk).all()
          const txTotal = new Map<number, number>()
          for (const r of (txTotalRows.results || []) as any[]) {
            txTotal.set(Number(r.user_id), Number(r.total))
          }
          // 이번 dividendDate 의 기존 dr/rr amount 합계 사용자별
          //   dr: daily_rewards.user_id, usdt_amount
          //   rr: referral_rewards.referrer_id, reward_amount
          const drExcl = await db.prepare(`
            SELECT user_id, COALESCE(SUM(usdt_amount),0) AS total
            FROM daily_rewards
            WHERE user_id IN (${placeholders}) AND reward_date = ?
            GROUP BY user_id
          `).bind(...chunk, dividendDate).all()
          const rrExcl = await db.prepare(`
            SELECT referrer_id AS user_id, COALESCE(SUM(reward_amount),0) AS total
            FROM referral_rewards
            WHERE referrer_id IN (${placeholders}) AND reward_date = ?
            GROUP BY referrer_id
          `).bind(...chunk, dividendDate).all()
          const exclMap = new Map<number, number>()
          for (const r of (drExcl.results || []) as any[]) {
            exclMap.set(Number(r.user_id), (exclMap.get(Number(r.user_id)) || 0) + Number(r.total))
          }
          for (const r of (rrExcl.results || []) as any[]) {
            exclMap.set(Number(r.user_id), (exclMap.get(Number(r.user_id)) || 0) + Number(r.total))
          }
          for (const uid of chunk) {
            const tt = txTotal.get(uid) || 0
            const ex = exclMap.get(uid) || 0
            userPaidExcl.set(uid, Math.max(0, tt - ex))
          }
        }
      }
    }

    // 헬퍼: 그 사용자에게 reward 를 amount 만큼 줄 수 있나? (cap 적용 후 실 amount 반환)
    //   round 누적용 — userPaidRound 에 이번 round 누적 가산
    const userPaidRound = new Map<number, number>()
    function tryGiveReward(uid: number, requestedAmount: number): { granted: number, capped: boolean } {
      const stakeTotal = userStakeTotal.get(uid) || 0
      if (stakeTotal <= 0) return { granted: 0, capped: true } // 진입 0인 사용자에겐 reward 안 줌
      const target = stakeTotal * 2 * USD_TO_QKEY
      const paidExcl = userPaidExcl.get(uid) || 0
      const paidRound = userPaidRound.get(uid) || 0
      const current = paidExcl + paidRound
      if (current >= target) return { granted: 0, capped: true }
      const remaining = target - current
      const granted = Math.min(requestedAmount, Math.floor(remaining))
      if (granted > 0) {
        userPaidRound.set(uid, paidRound + granted)
      }
      return { granted, capped: granted < requestedAmount }
    }

    // ③ 각 staking 별 own_DR/L1/L2 계산 (바텀업)
    type ExpectedDR = { user_id: number, staking_id: number, amount: number }
    type ExpectedRR = { referrer_id: number, referee_id: number, level: number, staking_id: number, original_amount: number, reward_amount: number }
    const expectedDRs: ExpectedDR[] = []
    const expectedRRs: ExpectedRR[] = []
    const cappedSummary = { dr_capped_users: new Set<number>(), l1_capped_users: new Set<number>(), l2_capped_users: new Set<number>() }

    // ★ 사전 일괄 조회 (N+1 SELECT 박멸 — timeout 방지) ★
    //   (1) 모든 관련 사용자의 referrer_id 한번에 조회 → Map
    //   (2) 그 reward_date 시점 active staking 보유 사용자 set 한번에 조회 → Set
    const allRelatedUids = new Set<number>()
    for (const s of stakingList) allRelatedUids.add(Number(s.user_id))
    // referrer 조회는 stakingList user 만 1차로 묶음 (그 결과로 L1 uid 알아내고, L1 referrer 조회는 2차)
    const refMap = new Map<number, number>()  // uid -> referrer_id (0 if none)
    {
      const uidsArr = Array.from(allRelatedUids)
      if (uidsArr.length > 0) {
        const CHUNK = 100
        for (let i = 0; i < uidsArr.length; i += CHUNK) {
          const chunk = uidsArr.slice(i, i + CHUNK)
          const placeholders = chunk.map(() => '?').join(',')
          const rows = await db.prepare(`SELECT id, referrer_id FROM users WHERE id IN (${placeholders})`).bind(...chunk).all()
          for (const u of (rows.results || []) as any[]) {
            refMap.set(Number(u.id), u.referrer_id ? Number(u.referrer_id) : 0)
          }
        }
      }
      // L1 referrer 들의 referrer (L2 uid) 도 한번에 추가 조회
      const l1Uids = new Set<number>()
      for (const v of refMap.values()) if (v > 0) l1Uids.add(v)
      // l1Uids 중 refMap 에 없는 것들만 조회
      const l1Missing = Array.from(l1Uids).filter(u => !refMap.has(u))
      if (l1Missing.length > 0) {
        const CHUNK = 100
        for (let i = 0; i < l1Missing.length; i += CHUNK) {
          const chunk = l1Missing.slice(i, i + CHUNK)
          const placeholders = chunk.map(() => '?').join(',')
          const rows = await db.prepare(`SELECT id, referrer_id FROM users WHERE id IN (${placeholders})`).bind(...chunk).all()
          for (const u of (rows.results || []) as any[]) {
            refMap.set(Number(u.id), u.referrer_id ? Number(u.referrer_id) : 0)
          }
        }
      }
    }

    // dividendDate 시점 active 보유 사용자 set (L1/L2 자격 판정용)
    const activeUserSet = new Set<number>()
    {
      const rows = await db.prepare(`
        SELECT DISTINCT user_id FROM staking
        WHERE status IN ('active','capped','completed')
          AND date(start_date,'+9 hours') <= ?
          AND date(end_date,'+9 hours') >= ?
      `).bind(dividendDate, dividendDate).all()
      for (const r of (rows.results || []) as any[]) activeUserSet.add(Number(r.user_id))
    }

    for (const s of stakingList) {
      const stakingId = Number(s.staking_id)
      const uid = Number(s.user_id)
      const amt = Number(s.amount) || 0
      const rate = Number(s.daily_rate) || 0
      const ownReqQkey = Math.round(amt * rate * USD_TO_QKEY)
      if (ownReqQkey <= 0) continue

      // 본인 own DR (cap 적용)
      const ownGrant = tryGiveReward(uid, ownReqQkey)
      if (ownGrant.granted > 0) {
        expectedDRs.push({ user_id: uid, staking_id: stakingId, amount: ownGrant.granted })
      }
      if (ownGrant.capped && ownGrant.granted < ownReqQkey) {
        cappedSummary.dr_capped_users.add(uid)
      }

      // L1 (referrer 20%) — referrer 가 active 일 때만
      const l1Uid = refMap.get(uid) || 0
      if (l1Uid > 0 && activeUserSet.has(l1Uid)) {
        const l1Req = Math.round(ownReqQkey * 0.20)
        if (l1Req > 0) {
          const l1Grant = tryGiveReward(l1Uid, l1Req)
          if (l1Grant.granted > 0) {
            expectedRRs.push({
              referrer_id: l1Uid, referee_id: uid, level: 1,
              staking_id: stakingId,
              original_amount: ownReqQkey,
              reward_amount: l1Grant.granted,
            })
          }
          if (l1Grant.capped && l1Grant.granted < l1Req) {
            cappedSummary.l1_capped_users.add(l1Uid)
          }
        }
      }

      // L2 (L1 의 referrer 10%) — L2 가 active 일 때만
      const l2Uid = l1Uid > 0 ? (refMap.get(l1Uid) || 0) : 0
      if (l2Uid > 0 && activeUserSet.has(l2Uid)) {
        const l2Req = Math.round(ownReqQkey * 0.10)
        if (l2Req > 0) {
          const l2Grant = tryGiveReward(l2Uid, l2Req)
          if (l2Grant.granted > 0) {
            expectedRRs.push({
              referrer_id: l2Uid, referee_id: uid, level: 2,
              staking_id: stakingId,
              original_amount: ownReqQkey,
              reward_amount: l2Grant.granted,
            })
          }
          if (l2Grant.capped && l2Grant.granted < l2Req) {
            cappedSummary.l2_capped_users.add(l2Uid)
          }
        }
      }
    }

    // ─── (4) 그 dividendDate 의 기존 DR/RR/tx 수집 (삭제 대상) ───
    const existingDRs = await db.prepare(`
      SELECT id, user_id, staking_id, usdt_amount, reward_date, paid_date
      FROM daily_rewards WHERE reward_date = ?
    `).bind(dividendDate).all()
    const existingRRs = await db.prepare(`
      SELECT id, referrer_id, referee_id, level, staking_id, original_amount, reward_amount, reward_date, paid_date
      FROM referral_rewards WHERE reward_date = ?
    `).bind(dividendDate).all()
    const exDRs = (existingDRs.results || []) as any[]
    const exRRs = (existingRRs.results || []) as any[]
    const exDRIds = exDRs.map(r => Number(r.id))
    const exRRIds = exRRs.map(r => Number(r.id))

    // 매칭되는 tx 수집 (ref_id 1:1)
    let exTxList: any[] = []
    if (exDRIds.length > 0) {
      const CHUNK = 100
      for (let i = 0; i < exDRIds.length; i += CHUNK) {
        const chunk = exDRIds.slice(i, i + CHUNK)
        const placeholders = chunk.map(() => '?').join(',')
        const rows = await db.prepare(`
          SELECT id, user_id, type, amount, description, ref_id
          FROM transactions
          WHERE type = 'daily_qkey' AND ref_id IN (${placeholders})
        `).bind(...chunk).all()
        exTxList.push(...((rows.results || []) as any[]))
      }
    }
    if (exRRIds.length > 0) {
      const CHUNK = 100
      for (let i = 0; i < exRRIds.length; i += CHUNK) {
        const chunk = exRRIds.slice(i, i + CHUNK)
        const placeholders = chunk.map(() => '?').join(',')
        const rows = await db.prepare(`
          SELECT id, user_id, type, amount, description, ref_id
          FROM transactions
          WHERE type = 'referral_reward' AND ref_id IN (${placeholders})
        `).bind(...chunk).all()
        exTxList.push(...((rows.results || []) as any[]))
      }
    }

    // ─── (5) balance 변동 계산 ───
    //   existing tx amount 만큼 차감 + expected 새 INSERT amount 만큼 가산
    const balanceDelta = new Map<number, number>()
    for (const tx of exTxList) {
      const uid = Number(tx.user_id)
      balanceDelta.set(uid, (balanceDelta.get(uid) || 0) - Number(tx.amount))
    }
    for (const dr of expectedDRs) {
      balanceDelta.set(dr.user_id, (balanceDelta.get(dr.user_id) || 0) + dr.amount)
    }
    for (const rr of expectedRRs) {
      balanceDelta.set(rr.referrer_id, (balanceDelta.get(rr.referrer_id) || 0) + rr.reward_amount)
    }

    // ─── (6) 요약 ───
    const expectedDRTotal = expectedDRs.reduce((s, r) => s + r.amount, 0)
    const expectedL1Total = expectedRRs.filter(r => r.level === 1).reduce((s, r) => s + r.reward_amount, 0)
    const expectedL2Total = expectedRRs.filter(r => r.level === 2).reduce((s, r) => s + r.reward_amount, 0)
    const existingDRTotal = exDRs.reduce((s, r) => s + Number(r.usdt_amount), 0)
    const existingL1Total = exRRs.filter(r => Number(r.level) === 1).reduce((s, r) => s + Number(r.reward_amount), 0)
    const existingL2Total = exRRs.filter(r => Number(r.level) === 2).reduce((s, r) => s + Number(r.reward_amount), 0)
    const existingTxTotal = exTxList.reduce((s, r) => s + Number(r.amount), 0)
    const newTxTotal = expectedDRTotal + expectedL1Total + expectedL2Total

    const summary = {
      dividendDate,
      payoutDate,
      active_staking_count: stakingList.length,
      expected: {
        dr_count: expectedDRs.length, dr_total: expectedDRTotal,
        l1_count: expectedRRs.filter(r => r.level === 1).length, l1_total: expectedL1Total,
        l2_count: expectedRRs.filter(r => r.level === 2).length, l2_total: expectedL2Total,
        gross_total: newTxTotal,
      },
      existing: {
        dr_count: exDRs.length, dr_total: existingDRTotal,
        l1_count: exRRs.filter(r => Number(r.level) === 1).length, l1_total: existingL1Total,
        l2_count: exRRs.filter(r => Number(r.level) === 2).length, l2_total: existingL2Total,
        tx_count: exTxList.length, tx_total: existingTxTotal,
      },
      net_delta: {
        balance_total_change: newTxTotal - existingTxTotal,
        dr_diff: expectedDRTotal - existingDRTotal,
        l1_diff: expectedL1Total - existingL1Total,
        l2_diff: expectedL2Total - existingL2Total,
      },
      cap_info: {
        dr_capped_users: cappedSummary.dr_capped_users.size,
        l1_capped_users: cappedSummary.l1_capped_users.size,
        l2_capped_users: cappedSummary.l2_capped_users.size,
      },
      affected_users_count: balanceDelta.size,
    }

    // ═══════════════ DRY-RUN ═══════════════
    if (mode === 'DRY_RUN') {
      // 사용자별 balance 변동 시뮬레이션
      const userIds = Array.from(balanceDelta.keys()).sort((a, b) => a - b)
      const userSim: any[] = []
      if (userIds.length > 0) {
        const CHUNK = 100
        for (let i = 0; i < userIds.length; i += CHUNK) {
          const chunk = userIds.slice(i, i + CHUNK)
          const placeholders = chunk.map(() => '?').join(',')
          const rows = await db.prepare(`SELECT id, name, email, qkey_balance FROM users WHERE id IN (${placeholders})`).bind(...chunk).all()
          for (const u of (rows.results || []) as any[]) {
            const delta = balanceDelta.get(Number(u.id)) || 0
            userSim.push({
              user_id: Number(u.id), name: u.name, email: u.email,
              current_balance: Number(u.qkey_balance),
              delta,
              post_balance: Number(u.qkey_balance) + delta,
              will_go_negative: (Number(u.qkey_balance) + delta) < 0,
            })
          }
        }
      }
      const negAfter = userSim.filter(u => u.will_go_negative)

      return c.json({
        ok: true,
        mode: 'DRY_RUN',
        action: 'recalc-day-dividend',
        is_business_day: true,
        summary,
        expected_dr_sample_top10: expectedDRs.slice(0, 10),
        expected_rr_l1_sample_top10: expectedRRs.filter(r => r.level === 1).slice(0, 10),
        expected_rr_l2_sample_top10: expectedRRs.filter(r => r.level === 2).slice(0, 10),
        existing_dr_sample_top10: exDRs.slice(0, 10),
        existing_rr_sample_top10: exRRs.slice(0, 10),
        existing_tx_sample_top10: exTxList.slice(0, 10).map(t => ({
          id: t.id, user_id: t.user_id, type: t.type, amount: t.amount,
          description: t.description, ref_id: t.ref_id,
        })),
        balance_sim_top20: userSim.slice(0, 20),
        negative_after: { count: negAfter.length, samples: negAfter.slice(0, 10) },
        next_action: 'POST + confirm=GO 보내시면 EXEC. 그 dividendDate 의 기존 DR/RR/tx 통째 삭제 후 영구룰 바텀업 새 INSERT.',
        duration_ms: Date.now() - t0,
      })
    }

    // ═══════════════ EXEC ═══════════════
    const CHUNK_SIZE = 80

    // (E1) tx DELETE (ref_id 매칭) + balance 차감
    let txDeleted = 0
    if (exDRIds.length > 0) {
      for (let i = 0; i < exDRIds.length; i += CHUNK_SIZE) {
        const chunk = exDRIds.slice(i, i + CHUNK_SIZE)
        const placeholders = chunk.map(() => '?').join(',')
        const r = await db.prepare(`DELETE FROM transactions WHERE type='daily_qkey' AND ref_id IN (${placeholders})`).bind(...chunk).run()
        txDeleted += (r as any)?.meta?.changes || 0
      }
    }
    if (exRRIds.length > 0) {
      for (let i = 0; i < exRRIds.length; i += CHUNK_SIZE) {
        const chunk = exRRIds.slice(i, i + CHUNK_SIZE)
        const placeholders = chunk.map(() => '?').join(',')
        const r = await db.prepare(`DELETE FROM transactions WHERE type='referral_reward' AND ref_id IN (${placeholders})`).bind(...chunk).run()
        txDeleted += (r as any)?.meta?.changes || 0
      }
    }

    // (E2) referral_rewards / daily_rewards DELETE (그 reward_date 의 모든 row)
    let rrDeleted = 0
    let drDeleted = 0
    {
      const r1 = await db.prepare(`DELETE FROM referral_rewards WHERE reward_date = ?`).bind(dividendDate).run()
      rrDeleted = (r1 as any)?.meta?.changes || 0
      const r2 = await db.prepare(`DELETE FROM daily_rewards WHERE reward_date = ?`).bind(dividendDate).run()
      drDeleted = (r2 as any)?.meta?.changes || 0
    }

    // (E3) balance 차감 (existing tx amount 만큼)
    //   balance_delta 는 (existing 차감) + (expected 가산) 의 net 이므로
    //   여기서는 net 한번에 처리
    let balanceAdjusted = 0
    {
      const balEntries = Array.from(balanceDelta.entries())
      for (let i = 0; i < balEntries.length; i += CHUNK_SIZE) {
        const chunk = balEntries.slice(i, i + CHUNK_SIZE)
        const stmts = chunk.map(([uid, delta]) =>
          db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(delta, uid)
        )
        await db.batch(stmts)
        balanceAdjusted += chunk.length
      }
    }

    // (E4) 새 DR batch INSERT → SELECT 로 id 매핑 → 매칭 tx batch INSERT
    //   ★ timeout 방지: 직렬 await N번 대신 db.batch() 로 한번에
    let drInserted = 0
    let drTxInserted = 0
    //   ★ 영구룰 #정규시각 (2026-05-19 변경): created_at = paid_date 의 KST 08:00 (= UTC prev-day 23:00)
    //     KST 15:15 → KST 08:00 폐기 후 통일
    //     EXEC 시각 INSERT 사고 (5/18 19:04 사건) 방지
    const _payoutPrevDayObj = new Date(payoutDate + 'T00:00:00+09:00')
    const _payoutPrevDayKst = kstDateStr(new Date(_payoutPrevDayObj.getTime() - 24 * 60 * 60 * 1000))
    const dividendCreatedAtUtc = `${_payoutPrevDayKst} 23:00:00`  // KST 08:00:00 of payoutDate
    if (expectedDRs.length > 0) {
      // ── (E4-1) DR batch INSERT ──
      for (let i = 0; i < expectedDRs.length; i += CHUNK_SIZE) {
        const chunk = expectedDRs.slice(i, i + CHUNK_SIZE)
        const stmts = chunk.map(dr =>
          db.prepare(`
            INSERT INTO daily_rewards (user_id, staking_id, usdt_amount, reward_date, paid_date, created_at)
            VALUES (?, ?, ?, ?, ?, ?)
          `).bind(dr.user_id, dr.staking_id, dr.amount, dividendDate, payoutDate, dividendCreatedAtUtc)
        )
        await db.batch(stmts)
        drInserted += chunk.length
      }
      // ── (E4-2) 방금 INSERT 한 DR row 들의 id 조회 → (user_id, staking_id) -> id 매핑 ──
      //   reward_date+paid_date 가 (user, staking) 별로 unique 하다고 가정
      //   (DELETE 가 먼저 그 reward_date 의 모든 row 를 비웠으므로 안전)
      const drRowsAfter = await db.prepare(`
        SELECT id, user_id, staking_id FROM daily_rewards
        WHERE reward_date = ? AND paid_date = ?
      `).bind(dividendDate, payoutDate).all()
      const drIdMap = new Map<string, number>()  // "uid|stakingId" -> dr.id
      for (const r of (drRowsAfter.results || []) as any[]) {
        drIdMap.set(`${r.user_id}|${r.staking_id}`, Number(r.id))
      }
      // ── (E4-3) tx batch INSERT (ref_id = dr.id) ──
      //   ★ created_at: paid_date 의 KST 08:00 정규시각 (= UTC prev-day 23:00) — 영구룰 #정규시각 (2026-05-19)
      //     EXEC 실행 시각으로 INSERT 되면 사용자 거래내역 UX 가 EXEC 시각으로 표시되는 사고 (5/18 19:04 사건)
      //     DB 저장값은 UTC, 화면 표시는 +9h 보정으로 KST 08:00 표시
      const txCreatedAtUtc = `${_payoutPrevDayKst} 23:00:00`  // = KST 08:00 정규 cron 시각
      const drTxStmts = expectedDRs.map(dr => {
        const drId = drIdMap.get(`${dr.user_id}|${dr.staking_id}`) ?? null
        return db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id, created_at)
          VALUES (?, 'daily_qkey', 'QKEY', ?, ?, ?, ?)
        `).bind(dr.user_id, dr.amount, '일일 배당 (QKEY)', drId, txCreatedAtUtc)
      })
      for (let i = 0; i < drTxStmts.length; i += CHUNK_SIZE) {
        const chunk = drTxStmts.slice(i, i + CHUNK_SIZE)
        await db.batch(chunk)
        drTxInserted += chunk.length
      }
    }

    // (E5) 새 RR batch INSERT → SELECT 로 id 매핑 → tx batch INSERT
    let rrInserted = 0
    let rrTxInserted = 0
    if (expectedRRs.length > 0) {
      for (let i = 0; i < expectedRRs.length; i += CHUNK_SIZE) {
        const chunk = expectedRRs.slice(i, i + CHUNK_SIZE)
        const stmts = chunk.map(rr =>
          db.prepare(`
            INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, staking_id, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
          `).bind(rr.referrer_id, rr.referee_id, rr.level, rr.original_amount, rr.reward_amount, dividendDate, payoutDate, rr.staking_id, dividendCreatedAtUtc)
        )
        await db.batch(stmts)
        rrInserted += chunk.length
      }
      // ── (E5-2) RR id 매핑: (referrer_id, referee_id, level, staking_id) -> id ──
      //   reward_date 기준 unique
      const rrRowsAfter = await db.prepare(`
        SELECT id, referrer_id, referee_id, level, staking_id FROM referral_rewards
        WHERE reward_date = ? AND paid_date = ?
      `).bind(dividendDate, payoutDate).all()
      const rrIdMap = new Map<string, number>()
      for (const r of (rrRowsAfter.results || []) as any[]) {
        rrIdMap.set(`${r.referrer_id}|${r.referee_id}|${r.level}|${r.staking_id}`, Number(r.id))
      }
      // ── (E5-3) tx batch INSERT (ref_id = rr.id) ──
      //   ★ created_at: paid_date 의 KST 08:00 정규시각 (= UTC prev-day 23:00) — 영구룰 #정규시각 (2026-05-19)
      const rrTxCreatedAtUtc = `${_payoutPrevDayKst} 23:00:01`  // RR 은 DR 보다 1초 늦게 (KST 08:00:01)
      const rrTxStmts = expectedRRs.map(rr => {
        const rrId = rrIdMap.get(`${rr.referrer_id}|${rr.referee_id}|${rr.level}|${rr.staking_id}`) ?? null
        const desc = rr.level === 1 ? '추천 보너스 (Level 1)' : '추천 보너스 (Level 2)'
        return db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id, created_at)
          VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?, ?)
        `).bind(rr.referrer_id, rr.reward_amount, desc, rrId, rrTxCreatedAtUtc)
      })
      for (let i = 0; i < rrTxStmts.length; i += CHUNK_SIZE) {
        const chunk = rrTxStmts.slice(i, i + CHUNK_SIZE)
        await db.batch(chunk)
        rrTxInserted += chunk.length
      }
    }

    // ─── POST-CHECK ───
    const postDR = await db.prepare(`SELECT COUNT(*) AS cnt, COALESCE(SUM(usdt_amount),0) AS total FROM daily_rewards WHERE reward_date = ?`).bind(dividendDate).first() as any
    const postRR = await db.prepare(`SELECT COUNT(*) AS cnt, COALESCE(SUM(reward_amount),0) AS total FROM referral_rewards WHERE reward_date = ?`).bind(dividendDate).first() as any

    // 마커 잔존 체크 (RECONCILE / REVERSE_BACKFILL 0건 확인)
    const markerCheck = await db.prepare(`
      SELECT COUNT(*) AS cnt FROM transactions
      WHERE description LIKE '%[RECONCILE%' OR description LIKE '%[REVERSE_BACKFILL%'
    `).first() as any

    return c.json({
      ok: true,
      mode: 'EXEC',
      action: 'recalc-day-dividend',
      dividendDate,
      payoutDate,
      pre_summary: summary,
      exec_result: {
        existing_deleted: {
          tx: txDeleted,
          rr: rrDeleted,
          dr: drDeleted,
        },
        new_inserted: {
          dr: drInserted,
          dr_tx: drTxInserted,
          rr: rrInserted,
          rr_tx: rrTxInserted,
        },
        balance_adjusted_users: balanceAdjusted,
      },
      post_check: {
        dr_count_after: Number(postDR?.cnt || 0),
        dr_total_after: Number(postDR?.total || 0),
        rr_count_after: Number(postRR?.cnt || 0),
        rr_total_after: Number(postRR?.total || 0),
        marker_residual: Number(markerCheck?.cnt || 0),
        expected_match: Number(postDR?.cnt || 0) === expectedDRs.length && Number(postRR?.cnt || 0) === expectedRRs.length,
      },
      duration_ms: Date.now() - t0,
    })
  } catch (error) {
    const durMs = Date.now() - t0
    console.error(`[RECALC_DAY] ERROR mode=${mode} duration_ms=${durMs}`, error)
    return c.json({ error: String(error), duration_ms: durMs }, 500)
  }
}

app.get('/api/diag/recalc-day-dividend', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  return diagRecalcDayDividend(c, 'DRY_RUN')
})

app.post('/api/diag/recalc-day-dividend', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  const confirm = c.req.query('confirm') || ''
  if (confirm !== 'GO') return c.json({ error: 'confirm=GO 필요 (실 변경 게이트)' }, 400)

  // ★★★ 사장님 명령 (2026-05-18): 5/11 EXEC 만 허용. 다른날 절대 금지 ★★★
  //   "다른날 지금 잘 먹히고 있는데 절대 건들면 안된다"
  //   화이트리스트 가드 — 5/11 EXEC 완료 후 봉인 처리 예정
  const ALLOWED_DIVIDEND_DATES = ['2026-05-11']
  const reqDividend = c.req.query('dividendDate') || ''
  if (!ALLOWED_DIVIDEND_DATES.includes(reqDividend)) {
    return c.json({
      error: 'EXEC 차단됨 — 다른날 절대 금지 (사장님 영구 명령)',
      detail: `dividendDate=${reqDividend} 는 화이트리스트에 없음. 허용 목록: ${ALLOWED_DIVIDEND_DATES.join(', ')}`,
      hint: '다른 reward_date 는 정규 cron 으로 이미 정합 상태. 어드민 recalc 절대 금지.',
    }, 403)
  }
  return diagRecalcDayDividend(c, 'EXEC')
})

// ============================================================================
// diag-staking-list: 사장님 명령 (2026-05-18)
//   READ-ONLY. 특정 dividendDate (KST) 의 active staking 리스트를 두 쿼리 패턴으로
//   각각 조회해서 차이를 명확히 보여준다.
//   - PATTERN_A: status='active' 만 (recompute-bottom-up 기준)
//   - PATTERN_B: status IN ('active','capped','completed') (recalc-day-dividend 기준)
// ============================================================================
app.get('/api/diag/staking-list', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'auth' }, 401)
  const t0 = Date.now()
  const db = c.env.DB
  const dividendDate = c.req.query('dividendDate') || ''
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dividendDate)) {
    return c.json({ error: 'dividendDate=YYYY-MM-DD' }, 400)
  }

  const patternA = await db.prepare(`
    SELECT s.id AS staking_id, s.user_id, s.amount, s.daily_rate, s.status,
           date(s.start_date,'+9 hours') AS start_kst,
           date(s.end_date,'+9 hours') AS end_kst,
           u.name, u.email, u.referrer_id
    FROM staking s
    JOIN users u ON u.id = s.user_id
    WHERE s.status = 'active'
      AND date(s.start_date,'+9 hours') <= date(?)
      AND date(s.end_date,'+9 hours') >= date(?)
    ORDER BY s.id ASC
  `).bind(dividendDate, dividendDate).all()

  const patternB = await db.prepare(`
    SELECT s.id AS staking_id, s.user_id, s.amount, s.daily_rate, s.status,
           date(s.start_date,'+9 hours') AS start_kst,
           date(s.end_date,'+9 hours') AS end_kst,
           u.name, u.email, u.referrer_id
    FROM staking s
    JOIN users u ON u.id = s.user_id
    WHERE s.status IN ('active','capped','completed')
      AND date(s.start_date,'+9 hours') <= ?
      AND date(s.end_date,'+9 hours') >= ?
    ORDER BY s.id ASC
  `).bind(dividendDate, dividendDate).all()

  const aRows = (patternA.results || []) as any[]
  const bRows = (patternB.results || []) as any[]
  const aIds = new Set(aRows.map((r: any) => r.staking_id))
  const bIds = new Set(bRows.map((r: any) => r.staking_id))
  const onlyA = aRows.filter((r: any) => !bIds.has(r.staking_id))
  const onlyB = bRows.filter((r: any) => !aIds.has(r.staking_id))

  // 추가: 그 사용자의 200% cap 도달 여부 (paid_total)
  const allUserIds = Array.from(new Set([...aRows, ...bRows].map((r: any) => r.user_id)))
  const paidByUser: Record<number, number> = {}
  if (allUserIds.length > 0) {
    const ph = allUserIds.map(() => '?').join(',')
    const paidRows = await db.prepare(`
      SELECT user_id, COALESCE(SUM(amount),0) AS paid_total
      FROM transactions
      WHERE user_id IN (${ph})
        AND type IN ('daily_qkey','referral_reward','direct_referral')
        AND amount > 0
      GROUP BY user_id
    `).bind(...allUserIds).all()
    for (const r of (paidRows.results || []) as any[]) {
      paidByUser[Number(r.user_id)] = Number(r.paid_total)
    }
  }

  // staking 별 cap target (amount * 2 * 150) + paid_total 표시
  const enrich = (rows: any[]) => rows.map((r: any) => {
    const target = Number(r.amount) * 2 * 150
    const paid = paidByUser[Number(r.user_id)] || 0
    return {
      staking_id: r.staking_id,
      user_id: r.user_id,
      name: r.name,
      email: r.email,
      amount: r.amount,
      daily_rate: r.daily_rate,
      status: r.status,
      start_kst: r.start_kst,
      end_kst: r.end_kst,
      referrer_id: r.referrer_id,
      cap_target_qkey: target,
      paid_total_qkey: paid,
      is_capped_at_query_time: paid >= target,
    }
  })

  return c.json({
    ok: true,
    action: 'staking-list',
    dividendDate,
    pattern_A: { sql: "status='active'", count: aRows.length, rows: enrich(aRows) },
    pattern_B: { sql: "status IN ('active','capped','completed')", count: bRows.length, rows: enrich(bRows) },
    diff: {
      only_in_A_count: onlyA.length,
      only_in_B_count: onlyB.length,
      only_in_A: enrich(onlyA),
      only_in_B: enrich(onlyB),
    },
    duration_ms: Date.now() - t0,
  })
})

// ============================================================================
// purge-tx-by-time: 사장님 명령 (2026-05-18)
//   "5/18 KST 17:53/17:54 의 referral_reward tx 105건 즉시 제거 + balance 차감"
//
//   목적: 어시스턴트 사고 (recalc-day-dividend EXEC 2번 timeout 후 중복 INSERT)
//        로 인해 5/18 KST 17:53~17:54 에 referral_reward tx 105건 중복 들어간 것
//        정확히 그 시간대 + type 만 제거
//
//   알고리즘:
//     ① type='referral_reward' AND coin_type='QKEY'
//        AND datetime(created_at,'+9 hours') BETWEEN '<from>' AND '<to>'
//        조건의 tx 모두 수집
//     ② 사용자별 amount 합계 → balance 차감 (-amount)
//     ③ 매칭되는 referral_rewards row (ref_id) 도 함께 제거 (정합 유지)
//     ④ tx 105건 DELETE
//     ⑤ POST-CHECK: 그 시간대 type tx 0건 확인
//
//   사장님 직접 명령:
//     "다른날꺼는 절대로 넣지말것"
//     "중복이 들어갈듯하면 바로 모든걸 멈추고 보고할것"
//
//   엔드포인트:
//     GET  /api/diag/purge-tx-by-time?key=ADMIN_PW
//          &from=2026-05-18 17:53:00 &to=2026-05-18 17:54:59
//          &type=referral_reward                                    → DRY_RUN
//     POST 같은 URL + &confirm=GO                                   → EXEC
// ============================================================================
async function diagPurgeTxByTime(c: any, mode: 'DRY_RUN' | 'EXEC') {
  const t0 = Date.now()
  try {
    const db = c.env.DB
    const fromKst = c.req.query('from') || ''
    const toKst = c.req.query('to') || ''
    const txType = c.req.query('type') || ''
    if (!fromKst || !toKst || !txType) {
      return c.json({ error: 'from, to, type query 필수 (예: from=2026-05-18 17:53:00 &to=2026-05-18 17:54:59 &type=referral_reward)' }, 400)
    }
    // 안전 가드: KST 시간대 범위가 60분 이내인지 확인 (사고 방지)
    const fromMs = Date.parse(fromKst.replace(' ', 'T') + 'Z')
    const toMs = Date.parse(toKst.replace(' ', 'T') + 'Z')
    if (isNaN(fromMs) || isNaN(toMs) || toMs < fromMs) {
      return c.json({ error: 'from/to 시간 파싱 실패 또는 to < from' }, 400)
    }
    const rangeMins = (toMs - fromMs) / 60000
    if (rangeMins > 60) {
      return c.json({ error: `시간 범위가 ${rangeMins}분 — 60분 초과 금지 (안전 가드)` }, 400)
    }

    // ─── 대상 tx 수집 ───
    const txList = (await db.prepare(`
      SELECT id, user_id, type, coin_type, amount, description, ref_id,
             datetime(created_at,'+9 hours') AS created_kst
      FROM transactions
      WHERE type = ? AND coin_type = 'QKEY'
        AND datetime(created_at,'+9 hours') >= ?
        AND datetime(created_at,'+9 hours') <= ?
      ORDER BY id ASC
    `).bind(txType, fromKst, toKst).all()).results as any[] || []

    if (txList.length === 0) {
      return c.json({
        ok: true, mode, action: 'purge-tx-by-time',
        from_kst: fromKst, to_kst: toKst, type: txType,
        message: '해당 시간대 type tx 0건 — 제거할 것 없음',
        duration_ms: Date.now() - t0,
      })
    }

    // ─── 사용자별 amount 합계 (balance 차감 양) ───
    const balanceDelta = new Map<number, number>()
    const refIds: number[] = []
    let totalAmount = 0
    for (const tx of txList) {
      const uid = Number(tx.user_id)
      const amt = Number(tx.amount)
      totalAmount += amt
      balanceDelta.set(uid, (balanceDelta.get(uid) || 0) - amt)
      if (tx.ref_id && /^\d+$/.test(String(tx.ref_id))) refIds.push(Number(tx.ref_id))
    }

    // ─── 매칭 referral_rewards row 수집 (정합용) ───
    let rrExistList: any[] = []
    if (refIds.length > 0 && txType === 'referral_reward') {
      const CHUNK = 100
      for (let i = 0; i < refIds.length; i += CHUNK) {
        const chunk = refIds.slice(i, i + CHUNK)
        const placeholders = chunk.map(() => '?').join(',')
        const rows = await db.prepare(`
          SELECT id, referrer_id, referee_id, level, staking_id, reward_amount, reward_date, paid_date
          FROM referral_rewards WHERE id IN (${placeholders})
        `).bind(...chunk).all()
        rrExistList.push(...((rows.results || []) as any[]))
      }
    }

    // tx id 중복 검수 (안전 — 같은 ref_id 의 tx 가 여러개 있으면 중복 의심)
    const refIdCount = new Map<number, number>()
    for (const tx of txList) {
      const rid = Number(tx.ref_id || 0)
      if (rid > 0) refIdCount.set(rid, (refIdCount.get(rid) || 0) + 1)
    }
    const duplicatedRefIds = Array.from(refIdCount.entries()).filter(([_, c]) => c > 1).map(([rid, c]) => ({ ref_id: rid, count: c }))

    const summary = {
      tx_count: txList.length,
      tx_total_amount: totalAmount,
      affected_users_count: balanceDelta.size,
      rr_match_count: rrExistList.length,
      ref_ids_total: refIds.length,
      ref_ids_unique: new Set(refIds).size,
      duplicated_ref_ids_within_selection: duplicatedRefIds.length,
      sample_duplicates_top10: duplicatedRefIds.slice(0, 10),
    }

    // ═══════════════ DRY-RUN ═══════════════
    if (mode === 'DRY_RUN') {
      const userIds = Array.from(balanceDelta.keys())
      let userSim: any[] = []
      if (userIds.length > 0) {
        const CHUNK = 100
        for (let i = 0; i < userIds.length; i += CHUNK) {
          const chunk = userIds.slice(i, i + CHUNK)
          const placeholders = chunk.map(() => '?').join(',')
          const rows = await db.prepare(`SELECT id, name, email, qkey_balance FROM users WHERE id IN (${placeholders})`).bind(...chunk).all()
          for (const u of (rows.results || []) as any[]) {
            const delta = balanceDelta.get(Number(u.id)) || 0
            userSim.push({
              user_id: Number(u.id), name: u.name, email: u.email,
              current_balance: Number(u.qkey_balance),
              delta,
              post_balance: Number(u.qkey_balance) + delta,
              will_go_negative: (Number(u.qkey_balance) + delta) < 0,
            })
          }
        }
      }
      const negAfter = userSim.filter(u => u.will_go_negative)

      return c.json({
        ok: true,
        mode: 'DRY_RUN',
        action: 'purge-tx-by-time',
        from_kst: fromKst, to_kst: toKst, type: txType,
        summary,
        balance_sim_top20: userSim.slice(0, 20),
        negative_after: { count: negAfter.length, samples: negAfter.slice(0, 10) },
        tx_sample_first10: txList.slice(0, 10).map(t => ({
          id: t.id, user_id: t.user_id, amount: t.amount,
          description: t.description, ref_id: t.ref_id, created_kst: t.created_kst,
        })),
        tx_sample_last10: txList.slice(-10).map(t => ({
          id: t.id, user_id: t.user_id, amount: t.amount,
          description: t.description, ref_id: t.ref_id, created_kst: t.created_kst,
        })),
        rr_match_sample_top10: rrExistList.slice(0, 10),
        next_action: 'POST + confirm=GO 보내시면 EXEC. tx DELETE + balance 차감 + 매칭 RR DELETE.',
        duration_ms: Date.now() - t0,
      })
    }

    // ═══════════════ EXEC ═══════════════
    const CHUNK_SIZE = 80

    // ── (1) balance 차감 ──
    let balanceAdjusted = 0
    const balEntries = Array.from(balanceDelta.entries())
    for (let i = 0; i < balEntries.length; i += CHUNK_SIZE) {
      const chunk = balEntries.slice(i, i + CHUNK_SIZE)
      const stmts = chunk.map(([uid, delta]) =>
        db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(delta, uid)
      )
      await db.batch(stmts)
      balanceAdjusted += chunk.length
    }

    // ── (2) referral_rewards DELETE (매칭 ref_id) ──
    let rrDeleted = 0
    if (refIds.length > 0 && txType === 'referral_reward') {
      const uniqueRefIds = Array.from(new Set(refIds))
      for (let i = 0; i < uniqueRefIds.length; i += CHUNK_SIZE) {
        const chunk = uniqueRefIds.slice(i, i + CHUNK_SIZE)
        const placeholders = chunk.map(() => '?').join(',')
        const r = await db.prepare(`DELETE FROM referral_rewards WHERE id IN (${placeholders})`).bind(...chunk).run()
        rrDeleted += (r as any)?.meta?.changes || 0
      }
    }

    // ── (3) transactions DELETE (id 기반 — 정확) ──
    const txIds = txList.map(t => Number(t.id))
    let txDeleted = 0
    for (let i = 0; i < txIds.length; i += CHUNK_SIZE) {
      const chunk = txIds.slice(i, i + CHUNK_SIZE)
      const placeholders = chunk.map(() => '?').join(',')
      const r = await db.prepare(`DELETE FROM transactions WHERE id IN (${placeholders})`).bind(...chunk).run()
      txDeleted += (r as any)?.meta?.changes || 0
    }

    // ─── POST-CHECK: 그 시간대 type tx 0건 확인 ───
    const postCheck = await db.prepare(`
      SELECT COUNT(*) AS cnt FROM transactions
      WHERE type = ? AND coin_type = 'QKEY'
        AND datetime(created_at,'+9 hours') >= ?
        AND datetime(created_at,'+9 hours') <= ?
    `).bind(txType, fromKst, toKst).first() as any

    return c.json({
      ok: Number(postCheck?.cnt || 0) === 0,
      mode: 'EXEC',
      action: 'purge-tx-by-time',
      from_kst: fromKst, to_kst: toKst, type: txType,
      pre_summary: summary,
      exec_result: {
        balance_adjusted_users: balanceAdjusted,
        rr_deleted: rrDeleted,
        tx_deleted: txDeleted,
      },
      post_check: {
        tx_remaining_in_range: Number(postCheck?.cnt || 0),
        verified: Number(postCheck?.cnt || 0) === 0,
      },
      duration_ms: Date.now() - t0,
    })
  } catch (error) {
    return c.json({ error: String(error), duration_ms: Date.now() - t0 }, 500)
  }
}

app.get('/api/diag/purge-tx-by-time', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  return diagPurgeTxByTime(c, 'DRY_RUN')
})

app.post('/api/diag/purge-tx-by-time', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  const confirm = c.req.query('confirm') || ''
  if (confirm !== 'GO') return c.json({ error: 'confirm=GO 필요 (실 변경 게이트)' }, 400)
  return diagPurgeTxByTime(c, 'EXEC')
})

// ============================================================================
// purge-reward-date-fully: 사장님 명령 (2026-05-18)
//   특정 reward_date 의 DR + RR + 매칭 tx + balance 전부 reverse
//
//   배경: recalc-day-dividend EXEC 가 tx.created_at 을 EXEC 시각으로 INSERT 한 사고
//        → 사용자 거래내역에 5/18 KST 19:04 등 오늘 시각으로 잉여 tx 가 다량 표시
//        → 사장님 격노 + 명령: "전부 다 지우고 18일은 15일 확정액만 넣어"
//
//   동작 (영구룰 #1일1정산 + #스테이킹별독립 정합 유지):
//     ① 그 reward_date 의 모든 DR/RR 조회 → id 목록 + 사용자별 sum
//     ② 매칭 tx (type='daily_qkey' AND ref_id IN DR.id) + (type IN 'referral_reward','direct_referral' AND ref_id IN RR.id)
//        → 사용자별 amount 합계 (balance 차감 기준 = 실제 INSERT 된 액수)
//     ③ balance 차감 (tx 기준)
//     ④ DELETE matching tx (id 기반 — 정확)
//     ⑤ DELETE RR WHERE reward_date=?
//     ⑥ DELETE DR WHERE reward_date=?
//     ⑦ POST-CHECK: reward_date 의 DR/RR/매칭 tx 모두 0건 확인
//
//   엔드포인트:
//     GET  /api/diag/purge-reward-date-fully?key=ADMIN_PW&rewardDate=YYYY-MM-DD          → DRY_RUN
//     POST /api/diag/purge-reward-date-fully?key=ADMIN_PW&rewardDate=YYYY-MM-DD&confirm=GO → EXEC
// ============================================================================
async function diagPurgeRewardDateFully(c: any, mode: 'DRY_RUN' | 'EXEC') {
  const t0 = Date.now()
  try {
    const db = c.env.DB
    const rewardDate = c.req.query('rewardDate') || ''
    if (!/^\d{4}-\d{2}-\d{2}$/.test(rewardDate)) {
      return c.json({ error: 'rewardDate=YYYY-MM-DD 필수' }, 400)
    }

    // ─── (1) DR 조회 ───
    //   ★ daily_rewards 에는 qkey_amount 컬럼 없음 (스키마 0004). USD * 150 으로 환산.
    const drList = (await db.prepare(`
      SELECT id, user_id, staking_id, usdt_amount, reward_date, paid_date
      FROM daily_rewards
      WHERE reward_date = ?
    `).bind(rewardDate).all()).results as any[] || []

    // ─── (2) RR 조회 ───
    const rrList = (await db.prepare(`
      SELECT id, referrer_id, referee_id, level, staking_id, reward_amount, reward_date, paid_date
      FROM referral_rewards
      WHERE reward_date = ?
    `).bind(rewardDate).all()).results as any[] || []

    const drIds = drList.map(r => Number(r.id))
    const rrIds = rrList.map(r => Number(r.id))

    if (drIds.length === 0 && rrIds.length === 0) {
      return c.json({
        ok: true, mode, action: 'purge-reward-date-fully',
        reward_date: rewardDate,
        message: '해당 reward_date 의 DR/RR 0건 — 제거할 것 없음',
        duration_ms: Date.now() - t0,
      })
    }

    // ─── (3) 매칭 tx 수집 ───
    const CHUNK = 80
    const drTxList: any[] = []
    for (let i = 0; i < drIds.length; i += CHUNK) {
      const chunk = drIds.slice(i, i + CHUNK)
      const placeholders = chunk.map(() => '?').join(',')
      const rows = await db.prepare(`
        SELECT id, user_id, type, amount, description, ref_id,
               datetime(created_at,'+9 hours') AS created_kst
        FROM transactions
        WHERE type = 'daily_qkey' AND coin_type = 'QKEY'
          AND ref_id IN (${placeholders})
      `).bind(...chunk).all()
      drTxList.push(...((rows.results || []) as any[]))
    }
    const rrTxList: any[] = []
    for (let i = 0; i < rrIds.length; i += CHUNK) {
      const chunk = rrIds.slice(i, i + CHUNK)
      const placeholders = chunk.map(() => '?').join(',')
      const rows = await db.prepare(`
        SELECT id, user_id, type, amount, description, ref_id,
               datetime(created_at,'+9 hours') AS created_kst
        FROM transactions
        WHERE type IN ('referral_reward','direct_referral') AND coin_type = 'QKEY'
          AND ref_id IN (${placeholders})
      `).bind(...chunk).all()
      rrTxList.push(...((rows.results || []) as any[]))
    }

    // ─── (4) 사용자별 balance 차감액 계산 (tx 기준) ───
    const balanceDelta = new Map<number, number>()
    let drTxTotal = 0, rrTxTotal = 0
    for (const tx of drTxList) {
      const uid = Number(tx.user_id)
      const amt = Number(tx.amount)
      drTxTotal += amt
      balanceDelta.set(uid, (balanceDelta.get(uid) || 0) - amt)
    }
    for (const tx of rrTxList) {
      const uid = Number(tx.user_id)
      const amt = Number(tx.amount)
      rrTxTotal += amt
      balanceDelta.set(uid, (balanceDelta.get(uid) || 0) - amt)
    }

    // ─── 정합 검증: DR/RR 합계 vs tx 합계 ───
    //   DR.qkey = usdt * 150 (영구룰 dr.qkey_amount = amount * daily_rate * 150 — usdt_amount 가 이미 amount*daily_rate)
    const USD_TO_QKEY = 150
    const drSumUsdt = drList.reduce((s, r) => s + Number(r.usdt_amount || 0), 0)
    const drSumQkey = drSumUsdt * USD_TO_QKEY
    const rrSumQkey = rrList.reduce((s, r) => s + Number(r.reward_amount || 0), 0)

    // ─── tx created_kst 분포 (사고 진단용) ───
    const allTx = [...drTxList, ...rrTxList]
    const kstHistogram = new Map<string, number>()
    for (const tx of allTx) {
      const minKey = String(tx.created_kst || '').slice(0, 16) // YYYY-MM-DD HH:MM
      kstHistogram.set(minKey, (kstHistogram.get(minKey) || 0) + 1)
    }
    const kstHistoTop = Array.from(kstHistogram.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, 15)
      .map(([t, c]) => ({ kst_minute: t, count: c }))

    const summary = {
      reward_date: rewardDate,
      dr_count: drList.length,
      rr_count: rrList.length,
      dr_sum_qkey: drSumQkey,
      rr_sum_qkey: rrSumQkey,
      dr_tx_count: drTxList.length,
      rr_tx_count: rrTxList.length,
      dr_tx_total: drTxTotal,
      rr_tx_total: rrTxTotal,
      all_tx_count: allTx.length,
      all_tx_total: drTxTotal + rrTxTotal,
      affected_users_count: balanceDelta.size,
      tx_created_kst_top: kstHistoTop,
    }

    // ═══════════════ DRY-RUN ═══════════════
    if (mode === 'DRY_RUN') {
      const userIds = Array.from(balanceDelta.keys())
      const userSim: any[] = []
      for (let i = 0; i < userIds.length; i += CHUNK) {
        const chunk = userIds.slice(i, i + CHUNK)
        const placeholders = chunk.map(() => '?').join(',')
        const rows = await db.prepare(`SELECT id, name, email, qkey_balance FROM users WHERE id IN (${placeholders})`).bind(...chunk).all()
        for (const u of (rows.results || []) as any[]) {
          const delta = balanceDelta.get(Number(u.id)) || 0
          userSim.push({
            user_id: Number(u.id), name: u.name, email: u.email,
            current_balance: Number(u.qkey_balance),
            delta,
            post_balance: Number(u.qkey_balance) + delta,
            will_go_negative: (Number(u.qkey_balance) + delta) < 0,
          })
        }
      }
      const negAfter = userSim.filter(u => u.will_go_negative)

      // 다른 reward_date 와 섞여있지 않은지 확인 (안전)
      const drPaidDates = Array.from(new Set(drList.map(r => String(r.paid_date))))
      const rrPaidDates = Array.from(new Set(rrList.map(r => String(r.paid_date))))

      return c.json({
        ok: true,
        mode: 'DRY_RUN',
        action: 'purge-reward-date-fully',
        summary,
        paid_dates_distribution: {
          dr_paid_dates: drPaidDates,
          rr_paid_dates: rrPaidDates,
        },
        balance_sim_top20: userSim.slice(0, 20),
        negative_after: { count: negAfter.length, samples: negAfter.slice(0, 10) },
        dr_tx_sample_top5: drTxList.slice(0, 5).map(t => ({
          id: t.id, user_id: t.user_id, type: t.type, amount: t.amount,
          ref_id: t.ref_id, description: t.description, created_kst: t.created_kst,
        })),
        rr_tx_sample_top5: rrTxList.slice(0, 5).map(t => ({
          id: t.id, user_id: t.user_id, type: t.type, amount: t.amount,
          ref_id: t.ref_id, description: t.description, created_kst: t.created_kst,
        })),
        warnings: [
          drSumQkey !== drTxTotal ? `DR sum (${drSumQkey}) != DR tx total (${drTxTotal}) — balance 차감은 tx 기준` : null,
          rrSumQkey !== rrTxTotal ? `RR sum (${rrSumQkey}) != RR tx total (${rrTxTotal}) — balance 차감은 tx 기준` : null,
        ].filter(Boolean),
        next_action: 'POST + confirm=GO 보내시면 EXEC. tx DELETE + balance 차감 + RR DELETE + DR DELETE.',
        duration_ms: Date.now() - t0,
      })
    }

    // ═══════════════ EXEC ═══════════════
    // ── (a) balance 차감 ──
    let balanceAdjusted = 0
    const balEntries = Array.from(balanceDelta.entries())
    for (let i = 0; i < balEntries.length; i += CHUNK) {
      const chunk = balEntries.slice(i, i + CHUNK)
      const stmts = chunk.map(([uid, delta]) =>
        db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(delta, uid)
      )
      await db.batch(stmts)
      balanceAdjusted += chunk.length
    }

    // ── (b) tx DELETE (id 기반 — 정확) ──
    const allTxIds = [...drTxList.map(t => Number(t.id)), ...rrTxList.map(t => Number(t.id))]
    let txDeleted = 0
    for (let i = 0; i < allTxIds.length; i += CHUNK) {
      const chunk = allTxIds.slice(i, i + CHUNK)
      const placeholders = chunk.map(() => '?').join(',')
      const r = await db.prepare(`DELETE FROM transactions WHERE id IN (${placeholders})`).bind(...chunk).run()
      txDeleted += (r as any)?.meta?.changes || 0
    }

    // ── (c) RR DELETE (reward_date 기반 — set-based) ──
    const rrDelRes = await db.prepare(`DELETE FROM referral_rewards WHERE reward_date = ?`).bind(rewardDate).run()
    const rrDeleted = (rrDelRes as any)?.meta?.changes || 0

    // ── (d) DR DELETE (reward_date 기반 — set-based) ──
    const drDelRes = await db.prepare(`DELETE FROM daily_rewards WHERE reward_date = ?`).bind(rewardDate).run()
    const drDeleted = (drDelRes as any)?.meta?.changes || 0

    // ─── POST-CHECK ───
    const drRemain = await db.prepare(`SELECT COUNT(*) AS cnt FROM daily_rewards WHERE reward_date = ?`).bind(rewardDate).first() as any
    const rrRemain = await db.prepare(`SELECT COUNT(*) AS cnt FROM referral_rewards WHERE reward_date = ?`).bind(rewardDate).first() as any
    // 매칭 tx 잔여 (DR/RR id 가 다 지워졌으니 매칭은 0이 자연스러움)
    let drTxRemain = 0, rrTxRemain = 0
    for (let i = 0; i < drIds.length; i += CHUNK) {
      const chunk = drIds.slice(i, i + CHUNK)
      const placeholders = chunk.map(() => '?').join(',')
      const r = await db.prepare(`
        SELECT COUNT(*) AS cnt FROM transactions
        WHERE type = 'daily_qkey' AND coin_type = 'QKEY' AND ref_id IN (${placeholders})
      `).bind(...chunk).first() as any
      drTxRemain += Number(r?.cnt || 0)
    }
    for (let i = 0; i < rrIds.length; i += CHUNK) {
      const chunk = rrIds.slice(i, i + CHUNK)
      const placeholders = chunk.map(() => '?').join(',')
      const r = await db.prepare(`
        SELECT COUNT(*) AS cnt FROM transactions
        WHERE type IN ('referral_reward','direct_referral') AND coin_type = 'QKEY' AND ref_id IN (${placeholders})
      `).bind(...chunk).first() as any
      rrTxRemain += Number(r?.cnt || 0)
    }

    const allClean = Number(drRemain?.cnt || 0) === 0 && Number(rrRemain?.cnt || 0) === 0 && drTxRemain === 0 && rrTxRemain === 0

    return c.json({
      ok: allClean,
      mode: 'EXEC',
      action: 'purge-reward-date-fully',
      reward_date: rewardDate,
      pre_summary: summary,
      exec_result: {
        balance_adjusted_users: balanceAdjusted,
        tx_deleted: txDeleted,
        rr_deleted: rrDeleted,
        dr_deleted: drDeleted,
      },
      post_check: {
        dr_remaining: Number(drRemain?.cnt || 0),
        rr_remaining: Number(rrRemain?.cnt || 0),
        dr_tx_remaining: drTxRemain,
        rr_tx_remaining: rrTxRemain,
        verified: allClean,
      },
      duration_ms: Date.now() - t0,
    })
  } catch (error) {
    return c.json({ error: String(error), duration_ms: Date.now() - t0 }, 500)
  }
}

app.get('/api/diag/purge-reward-date-fully', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  return diagPurgeRewardDateFully(c, 'DRY_RUN')
})

app.post('/api/diag/purge-reward-date-fully', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  const confirm = c.req.query('confirm') || ''
  if (confirm !== 'GO') return c.json({ error: 'confirm=GO 필요 (실 변경 게이트)' }, 400)
  return diagPurgeRewardDateFully(c, 'EXEC')
})

// ============================================================================
// recalc-multi-day-dividend: 사장님 명령 (2026-05-18)
//   여러 reward_date 를 한 EXEC 으로 순차 처리 (정규 cron 누적과 동일)
//
//   사장님 영구룰 정확 적용:
//     - 화이트리스트 4개만 허용: 5/11, 5/12, 5/13, 5/14 (다른날 절대 차단)
//     - 각 dividendDate 마다 사전 검사: 그 reward_date 의 기존 DR/RR/tx COUNT=0 확인
//       → 1건이라도 있으면 즉시 STOP (정합 데이터 보호)
//     - 5/15 reward 분 (DR 56 / RR 109 / tx 165 / 234,825 KEY) 절대 안 건드림
//     - 각 dividendDate 별로 영구룰 #바텀업정산 적용:
//       own_DR + 자동 L1 (20%) + 자동 L2 (10%) + 200% Cap 자동
//     - tx/DR/RR created_at = 그 paid_date 의 KST 15:15 (영구룰 #정규시각)
//     - 순서: 5/11 → 5/12 → 5/13 → 5/14 (cap 누적 정확)
//
//   기존 endpoint (recalc-day-dividend) 코드 0줄 수정. 완전 별개 함수.
//
//   엔드포인트:
//     GET  /api/diag/recalc-multi-day-dividend?key=ADMIN_PW         → DRY_RUN
//     POST /api/diag/recalc-multi-day-dividend?key=ADMIN_PW&confirm=GO → EXEC
// ============================================================================
async function diagRecalcMultiDayDividend(c: any, mode: 'DRY_RUN' | 'EXEC') {
  const t0 = Date.now()
  try {
    const db = c.env.DB
    const USD_TO_QKEY = 150

    // ★ 화이트리스트 — 절대 변경 불가 ★
    const TARGETS: { dividendDate: string, payoutDate: string }[] = [
      { dividendDate: '2026-05-11', payoutDate: '2026-05-12' },
      { dividendDate: '2026-05-12', payoutDate: '2026-05-13' },
      { dividendDate: '2026-05-13', payoutDate: '2026-05-14' },
      { dividendDate: '2026-05-14', payoutDate: '2026-05-15' },
    ]
    const PROTECTED_REWARD_DATES = ['2026-05-15']  // 절대 건들지 말 것 (정합 상태)

    // ─── 사전 검사 ① 각 TARGET 의 기존 DR/RR/tx 0건 확인 ───
    const preCheckResults: any[] = []
    for (const t of TARGETS) {
      const drCnt = await db.prepare(`SELECT COUNT(*) AS cnt FROM daily_rewards WHERE reward_date = ?`).bind(t.dividendDate).first() as any
      const rrCnt = await db.prepare(`SELECT COUNT(*) AS cnt FROM referral_rewards WHERE reward_date = ?`).bind(t.dividendDate).first() as any
      preCheckResults.push({
        dividendDate: t.dividendDate, payoutDate: t.payoutDate,
        dr_existing: Number(drCnt?.cnt || 0),
        rr_existing: Number(rrCnt?.cnt || 0),
      })
    }
    const dirty = preCheckResults.filter(r => r.dr_existing > 0 || r.rr_existing > 0)
    if (dirty.length > 0) {
      return c.json({
        ok: false,
        error: '사전 검사 실패 — 일부 dividendDate 에 이미 DR/RR row 있음 (정합 데이터 보호)',
        dirty_targets: dirty,
        hint: '먼저 purge-reward-date-fully 로 정리하거나, 그 reward_date 가 정합이면 작업 중단',
      }, 400)
    }

    // ─── 사전 검사 ② 5/15 reward 정합 보존 확인 (시작 전 baseline) ───
    const protectBaseline: any[] = []
    for (const pd of PROTECTED_REWARD_DATES) {
      const drB = await db.prepare(`SELECT COUNT(*) AS cnt, COALESCE(SUM(usdt_amount),0) AS total FROM daily_rewards WHERE reward_date = ?`).bind(pd).first() as any
      const rrB = await db.prepare(`SELECT COUNT(*) AS cnt, COALESCE(SUM(reward_amount),0) AS total FROM referral_rewards WHERE reward_date = ?`).bind(pd).first() as any
      protectBaseline.push({
        reward_date: pd,
        dr_count: Number(drB?.cnt || 0), dr_total: Number(drB?.total || 0),
        rr_count: Number(rrB?.cnt || 0), rr_total: Number(rrB?.total || 0),
      })
    }

    // ─── 헬퍼 함수: 한 dividendDate 의 expected DR/RR 산정 ───
    // 기존 recalc-day-dividend 로직과 동일하지만 cap 누적 Map 을 호출자가 관리 (멀티-day 누적)
    async function computeExpected(
      dividendDate: string,
      payoutDate: string,
      userPaidExclSeed: Map<number, number>,  // 시작 시 (현재 DB tx 합계) - (그 reward_date 의 기존 row) 합계
      userStakeTotal: Map<number, number>,
      refMap: Map<number, number>,
      activeUserSet: Set<number>,
    ): Promise<{
      expectedDRs: { user_id: number, staking_id: number, amount: number }[],
      expectedRRs: { referrer_id: number, referee_id: number, level: number, staking_id: number, original_amount: number, reward_amount: number }[],
      userPaidRound: Map<number, number>,
      capInfo: { dr_capped_users: number, l1_capped_users: number, l2_capped_users: number },
    }> {
      // (1) 그 dividendDate 의 active staking 모두 조회
      const stakingRows = await db.prepare(`
        SELECT s.id AS staking_id, s.user_id, s.amount, s.daily_rate, s.period_days,
               date(s.start_date,'+9 hours') AS start_kst,
               date(s.end_date,'+9 hours') AS end_kst,
               s.status,
               u.referrer_id
        FROM staking s
        JOIN users u ON u.id = s.user_id
        WHERE s.status IN ('active','capped','completed')
          AND date(s.start_date,'+9 hours') <= ?
          AND date(s.end_date,'+9 hours') >= ?
        ORDER BY s.id ASC
      `).bind(dividendDate, dividendDate).all()
      const stakingList = (stakingRows.results || []) as any[]

      const expectedDRs: { user_id: number, staking_id: number, amount: number }[] = []
      const expectedRRs: { referrer_id: number, referee_id: number, level: number, staking_id: number, original_amount: number, reward_amount: number }[] = []
      const dr_capped = new Set<number>()
      const l1_capped = new Set<number>()
      const l2_capped = new Set<number>()
      const userPaidRound = new Map<number, number>()

      function tryGive(uid: number, requested: number): { granted: number, capped: boolean } {
        const stakeTotal = userStakeTotal.get(uid) || 0
        if (stakeTotal <= 0) return { granted: 0, capped: true }
        const target = stakeTotal * 2 * USD_TO_QKEY
        const paidExcl = userPaidExclSeed.get(uid) || 0
        const paidRound = userPaidRound.get(uid) || 0
        const current = paidExcl + paidRound
        if (current >= target) return { granted: 0, capped: true }
        const remaining = target - current
        const granted = Math.min(requested, Math.floor(remaining))
        if (granted > 0) userPaidRound.set(uid, paidRound + granted)
        return { granted, capped: granted < requested }
      }

      for (const s of stakingList) {
        const stakingId = Number(s.staking_id)
        const uid = Number(s.user_id)
        const amt = Number(s.amount) || 0
        const rate = Number(s.daily_rate) || 0
        const ownReqQkey = Math.round(amt * rate * USD_TO_QKEY)
        if (ownReqQkey <= 0) continue

        const ownGrant = tryGive(uid, ownReqQkey)
        if (ownGrant.granted > 0) expectedDRs.push({ user_id: uid, staking_id: stakingId, amount: ownGrant.granted })
        if (ownGrant.capped && ownGrant.granted < ownReqQkey) dr_capped.add(uid)

        const l1Uid = refMap.get(uid) || 0
        if (l1Uid > 0 && activeUserSet.has(l1Uid)) {
          const l1Req = Math.round(ownReqQkey * 0.20)
          if (l1Req > 0) {
            const l1Grant = tryGive(l1Uid, l1Req)
            if (l1Grant.granted > 0) expectedRRs.push({
              referrer_id: l1Uid, referee_id: uid, level: 1, staking_id: stakingId,
              original_amount: ownReqQkey, reward_amount: l1Grant.granted,
            })
            if (l1Grant.capped && l1Grant.granted < l1Req) l1_capped.add(l1Uid)
          }
        }

        const l2Uid = l1Uid > 0 ? (refMap.get(l1Uid) || 0) : 0
        if (l2Uid > 0 && activeUserSet.has(l2Uid)) {
          const l2Req = Math.round(ownReqQkey * 0.10)
          if (l2Req > 0) {
            const l2Grant = tryGive(l2Uid, l2Req)
            if (l2Grant.granted > 0) expectedRRs.push({
              referrer_id: l2Uid, referee_id: uid, level: 2, staking_id: stakingId,
              original_amount: ownReqQkey, reward_amount: l2Grant.granted,
            })
            if (l2Grant.capped && l2Grant.granted < l2Req) l2_capped.add(l2Uid)
          }
        }
      }

      return {
        expectedDRs, expectedRRs, userPaidRound,
        capInfo: { dr_capped_users: dr_capped.size, l1_capped_users: l1_capped.size, l2_capped_users: l2_capped.size },
      }
    }

    // ─── 사전 일괄 조회 (모든 dividendDate 공통) ───
    // 모든 후보 사용자 set 수집 → stake_total + refMap + activeUserSet
    const userStakeTotal = new Map<number, number>()
    const refMap = new Map<number, number>()
    const activeUserSet = new Set<number>()

    {
      // 전체 active staking 사용자 수집 (4 reward_date 통합)
      const allStakingRows = await db.prepare(`
        SELECT DISTINCT s.user_id, u.referrer_id
        FROM staking s
        JOIN users u ON u.id = s.user_id
        WHERE s.status IN ('active','capped','completed')
      `).all()
      const candidateUids = new Set<number>()
      for (const r of (allStakingRows.results || []) as any[]) {
        candidateUids.add(Number(r.user_id))
        if (r.referrer_id) candidateUids.add(Number(r.referrer_id))
      }
      // L2 referrer 도 수집
      const uidsArr0 = Array.from(candidateUids)
      if (uidsArr0.length > 0) {
        const CHUNK = 100
        for (let i = 0; i < uidsArr0.length; i += CHUNK) {
          const chunk = uidsArr0.slice(i, i + CHUNK)
          const placeholders = chunk.map(() => '?').join(',')
          const rows = await db.prepare(`SELECT id, referrer_id FROM users WHERE id IN (${placeholders})`).bind(...chunk).all()
          for (const u of (rows.results || []) as any[]) {
            refMap.set(Number(u.id), u.referrer_id ? Number(u.referrer_id) : 0)
            if (u.referrer_id) candidateUids.add(Number(u.referrer_id))
          }
        }
        // L2 referrer 들의 referrer (L3 — refMap 채우기용)
        const missingL2 = Array.from(candidateUids).filter(u => !refMap.has(u))
        if (missingL2.length > 0) {
          for (let i = 0; i < missingL2.length; i += CHUNK) {
            const chunk = missingL2.slice(i, i + CHUNK)
            const placeholders = chunk.map(() => '?').join(',')
            const rows = await db.prepare(`SELECT id, referrer_id FROM users WHERE id IN (${placeholders})`).bind(...chunk).all()
            for (const u of (rows.results || []) as any[]) {
              refMap.set(Number(u.id), u.referrer_id ? Number(u.referrer_id) : 0)
            }
          }
        }
      }
      // stake_total 한번에
      const uidsArr = Array.from(candidateUids)
      if (uidsArr.length > 0) {
        const CHUNK = 100
        for (let i = 0; i < uidsArr.length; i += CHUNK) {
          const chunk = uidsArr.slice(i, i + CHUNK)
          const placeholders = chunk.map(() => '?').join(',')
          const rows = await db.prepare(`
            SELECT user_id, COALESCE(SUM(amount),0) AS total
            FROM staking WHERE user_id IN (${placeholders})
              AND status IN ('active','completed','capped')
            GROUP BY user_id
          `).bind(...chunk).all()
          for (const r of (rows.results || []) as any[]) {
            userStakeTotal.set(Number(r.user_id), Number(r.total))
          }
        }
      }
      // activeUserSet (모든 active 사용자 union)
      const aRows = await db.prepare(`
        SELECT DISTINCT user_id FROM staking
        WHERE status IN ('active','capped','completed')
      `).all()
      for (const r of (aRows.results || []) as any[]) activeUserSet.add(Number(r.user_id))
    }

    // ─── 각 사용자의 paidExcl (시작 시점 baseline = 현재 DB tx 합계) ───
    //   대상 4 reward_date 에는 현재 0건이므로 단순히 현재 tx 합계가 baseline
    const userPaidExcl = new Map<number, number>()
    {
      const uidsArr = Array.from(userStakeTotal.keys())
      if (uidsArr.length > 0) {
        const CHUNK = 100
        for (let i = 0; i < uidsArr.length; i += CHUNK) {
          const chunk = uidsArr.slice(i, i + CHUNK)
          const placeholders = chunk.map(() => '?').join(',')
          const rows = await db.prepare(`
            SELECT user_id, COALESCE(SUM(amount),0) AS total
            FROM transactions
            WHERE user_id IN (${placeholders}) AND coin_type='QKEY'
              AND type IN ('daily_qkey','referral_reward','direct_referral')
            GROUP BY user_id
          `).bind(...chunk).all()
          for (const r of (rows.results || []) as any[]) {
            userPaidExcl.set(Number(r.user_id), Math.max(0, Number(r.total)))
          }
        }
      }
    }

    // ─── 4 dividendDate 순차 처리 ───
    const stageResults: any[] = []
    const cumulativeBalanceDelta = new Map<number, number>()  // 누적 delta (EXEC 시 한번에 UPDATE)

    for (const t of TARGETS) {
      const stage = await computeExpected(
        t.dividendDate, t.payoutDate,
        userPaidExcl, userStakeTotal, refMap, activeUserSet,
      )

      // 누적 cap 진행: 이 stage 의 userPaidRound 를 다음 stage 의 userPaidExcl 에 반영
      for (const [uid, delta] of stage.userPaidRound.entries()) {
        userPaidExcl.set(uid, (userPaidExcl.get(uid) || 0) + delta)
        cumulativeBalanceDelta.set(uid, (cumulativeBalanceDelta.get(uid) || 0) + delta)
      }

      const drTotal = stage.expectedDRs.reduce((s, r) => s + r.amount, 0)
      const l1Total = stage.expectedRRs.filter(r => r.level === 1).reduce((s, r) => s + r.reward_amount, 0)
      const l2Total = stage.expectedRRs.filter(r => r.level === 2).reduce((s, r) => s + r.reward_amount, 0)

      stageResults.push({
        dividendDate: t.dividendDate, payoutDate: t.payoutDate,
        expected: {
          dr_count: stage.expectedDRs.length, dr_total: drTotal,
          l1_count: stage.expectedRRs.filter(r => r.level === 1).length, l1_total: l1Total,
          l2_count: stage.expectedRRs.filter(r => r.level === 2).length, l2_total: l2Total,
          tx_count: stage.expectedDRs.length + stage.expectedRRs.length,
          gross_total: drTotal + l1Total + l2Total,
        },
        cap_info: stage.capInfo,
        _stage_data: stage,  // DRY-RUN 후 폐기, EXEC 에서 INSERT 용
      })
    }

    const grandTotal = stageResults.reduce((s, r) => s + r.expected.gross_total, 0)
    const grandTxCount = stageResults.reduce((s, r) => s + r.expected.tx_count, 0)

    // ═══════════════ DRY-RUN ═══════════════
    if (mode === 'DRY_RUN') {
      // 사용자별 누적 balance 시뮬
      const userIds = Array.from(cumulativeBalanceDelta.keys())
      const userSim: any[] = []
      if (userIds.length > 0) {
        const CHUNK = 100
        for (let i = 0; i < userIds.length; i += CHUNK) {
          const chunk = userIds.slice(i, i + CHUNK)
          const placeholders = chunk.map(() => '?').join(',')
          const rows = await db.prepare(`SELECT id, name, email, qkey_balance FROM users WHERE id IN (${placeholders})`).bind(...chunk).all()
          for (const u of (rows.results || []) as any[]) {
            const delta = cumulativeBalanceDelta.get(Number(u.id)) || 0
            userSim.push({
              user_id: Number(u.id), name: u.name, email: u.email,
              current_balance: Number(u.qkey_balance),
              cumulative_delta: delta,
              post_balance: Number(u.qkey_balance) + delta,
              will_go_negative: (Number(u.qkey_balance) + delta) < 0,
            })
          }
        }
      }
      const negAfter = userSim.filter(u => u.will_go_negative)

      return c.json({
        ok: true,
        mode: 'DRY_RUN',
        action: 'recalc-multi-day-dividend',
        targets: TARGETS,
        protected_reward_dates: PROTECTED_REWARD_DATES,
        pre_check: { targets_empty: preCheckResults, protect_baseline: protectBaseline },
        per_stage: stageResults.map(s => ({
          dividendDate: s.dividendDate, payoutDate: s.payoutDate,
          expected: s.expected, cap_info: s.cap_info,
        })),
        grand_total: {
          tx_count: grandTxCount,
          balance_delta_total: grandTotal,
          affected_users_count: cumulativeBalanceDelta.size,
        },
        balance_sim_top20: userSim.sort((a, b) => b.cumulative_delta - a.cumulative_delta).slice(0, 20),
        negative_after: { count: negAfter.length, samples: negAfter.slice(0, 10) },
        next_action: 'POST + confirm=GO 보내시면 EXEC 1번으로 4단계 순차 INSERT.',
        duration_ms: Date.now() - t0,
      })
    }

    // ═══════════════ EXEC ═══════════════
    const CHUNK = 80
    const execResults: any[] = []

    for (const stageR of stageResults) {
      const t1 = Date.now()
      const dividendDate = stageR.dividendDate as string
      const payoutDate = stageR.payoutDate as string
      const stage = stageR._stage_data
      const expectedDRs = stage.expectedDRs
      const expectedRRs = stage.expectedRRs

      // ★ 영구룰 #정규시각 (2026-05-19 변경): created_at = paid_date KST 08:00 (= UTC prev-day 23:00) ★
      const _prevKstStr_r3 = kstDateStr(new Date(new Date(payoutDate + 'T00:00:00+09:00').getTime() - 24 * 60 * 60 * 1000))
      const drCreatedAt = `${_prevKstStr_r3} 23:00:00`
      const rrCreatedAt = `${_prevKstStr_r3} 23:00:01`

      // ── (1) DR batch INSERT ──
      for (let i = 0; i < expectedDRs.length; i += CHUNK) {
        const chunk = expectedDRs.slice(i, i + CHUNK)
        const stmts = chunk.map((dr: any) =>
          db.prepare(`
            INSERT INTO daily_rewards (user_id, staking_id, usdt_amount, reward_date, paid_date, created_at)
            VALUES (?, ?, ?, ?, ?, ?)
          `).bind(dr.user_id, dr.staking_id, dr.amount, dividendDate, payoutDate, drCreatedAt)
        )
        if (stmts.length > 0) await db.batch(stmts)
      }

      // DR id 매핑
      const drRowsAfter = await db.prepare(`
        SELECT id, user_id, staking_id FROM daily_rewards
        WHERE reward_date = ? AND paid_date = ?
      `).bind(dividendDate, payoutDate).all()
      const drIdMap = new Map<string, number>()
      for (const r of (drRowsAfter.results || []) as any[]) {
        drIdMap.set(`${r.user_id}|${r.staking_id}`, Number(r.id))
      }

      // ── (2) DR tx batch INSERT ──
      const drTxStmts = expectedDRs.map((dr: any) => {
        const drId = drIdMap.get(`${dr.user_id}|${dr.staking_id}`) ?? null
        return db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id, created_at)
          VALUES (?, 'daily_qkey', 'QKEY', ?, ?, ?, ?)
        `).bind(dr.user_id, dr.amount, '일일 배당 (QKEY)', drId, drCreatedAt)
      })
      for (let i = 0; i < drTxStmts.length; i += CHUNK) {
        const c2 = drTxStmts.slice(i, i + CHUNK)
        if (c2.length > 0) await db.batch(c2)
      }

      // ── (3) RR batch INSERT ──
      for (let i = 0; i < expectedRRs.length; i += CHUNK) {
        const chunk = expectedRRs.slice(i, i + CHUNK)
        const stmts = chunk.map((rr: any) =>
          db.prepare(`
            INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, staking_id, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
          `).bind(rr.referrer_id, rr.referee_id, rr.level, rr.original_amount, rr.reward_amount, dividendDate, payoutDate, rr.staking_id, drCreatedAt)
        )
        if (stmts.length > 0) await db.batch(stmts)
      }

      // RR id 매핑
      const rrRowsAfter = await db.prepare(`
        SELECT id, referrer_id, referee_id, level, staking_id FROM referral_rewards
        WHERE reward_date = ? AND paid_date = ?
      `).bind(dividendDate, payoutDate).all()
      const rrIdMap = new Map<string, number>()
      for (const r of (rrRowsAfter.results || []) as any[]) {
        rrIdMap.set(`${r.referrer_id}|${r.referee_id}|${r.level}|${r.staking_id}`, Number(r.id))
      }

      // ── (4) RR tx batch INSERT ──
      const rrTxStmts = expectedRRs.map((rr: any) => {
        const rrId = rrIdMap.get(`${rr.referrer_id}|${rr.referee_id}|${rr.level}|${rr.staking_id}`) ?? null
        const desc = rr.level === 1 ? '추천 보너스 (Level 1)' : '추천 보너스 (Level 2)'
        return db.prepare(`
          INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id, created_at)
          VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?, ?)
        `).bind(rr.referrer_id, rr.reward_amount, desc, rrId, rrCreatedAt)
      })
      for (let i = 0; i < rrTxStmts.length; i += CHUNK) {
        const c2 = rrTxStmts.slice(i, i + CHUNK)
        if (c2.length > 0) await db.batch(c2)
      }

      // ── (5) POST-CHECK 각 stage ──
      const postDR = await db.prepare(`SELECT COUNT(*) AS cnt FROM daily_rewards WHERE reward_date = ?`).bind(dividendDate).first() as any
      const postRR = await db.prepare(`SELECT COUNT(*) AS cnt FROM referral_rewards WHERE reward_date = ?`).bind(dividendDate).first() as any

      execResults.push({
        dividendDate, payoutDate,
        inserted: {
          dr: expectedDRs.length,
          dr_tx: expectedDRs.length,
          rr: expectedRRs.length,
          rr_tx: expectedRRs.length,
        },
        post_check: {
          dr_count: Number(postDR?.cnt || 0),
          rr_count: Number(postRR?.cnt || 0),
          dr_match: Number(postDR?.cnt || 0) === expectedDRs.length,
          rr_match: Number(postRR?.cnt || 0) === expectedRRs.length,
        },
        stage_duration_ms: Date.now() - t1,
      })
    }

    // ─── (6) balance 누적 UPDATE (4 stages 합산) ───
    let balanceAdjusted = 0
    const balEntries = Array.from(cumulativeBalanceDelta.entries())
    for (let i = 0; i < balEntries.length; i += CHUNK) {
      const chunk = balEntries.slice(i, i + CHUNK)
      const stmts = chunk.map(([uid, delta]) =>
        db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(delta, uid)
      )
      if (stmts.length > 0) await db.batch(stmts)
      balanceAdjusted += chunk.length
    }

    // ─── (7) 보호 reward_date 정합 재확인 (5/15 baseline 변동 없는지) ───
    const protectAfter: any[] = []
    for (const pd of PROTECTED_REWARD_DATES) {
      const drB = await db.prepare(`SELECT COUNT(*) AS cnt, COALESCE(SUM(usdt_amount),0) AS total FROM daily_rewards WHERE reward_date = ?`).bind(pd).first() as any
      const rrB = await db.prepare(`SELECT COUNT(*) AS cnt, COALESCE(SUM(reward_amount),0) AS total FROM referral_rewards WHERE reward_date = ?`).bind(pd).first() as any
      protectAfter.push({
        reward_date: pd,
        dr_count: Number(drB?.cnt || 0), dr_total: Number(drB?.total || 0),
        rr_count: Number(rrB?.cnt || 0), rr_total: Number(rrB?.total || 0),
      })
    }
    const protectIntact = JSON.stringify(protectBaseline) === JSON.stringify(protectAfter)

    return c.json({
      ok: protectIntact && execResults.every(r => r.post_check.dr_match && r.post_check.rr_match),
      mode: 'EXEC',
      action: 'recalc-multi-day-dividend',
      stages: execResults,
      balance_adjusted_users: balanceAdjusted,
      cumulative_balance_delta_total: Array.from(cumulativeBalanceDelta.values()).reduce((s, v) => s + v, 0),
      protect_check: {
        baseline: protectBaseline,
        after: protectAfter,
        intact: protectIntact,
      },
      duration_ms: Date.now() - t0,
    })
  } catch (error) {
    return c.json({ error: String(error), duration_ms: Date.now() - t0 }, 500)
  }
}

app.get('/api/diag/recalc-multi-day-dividend', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  return diagRecalcMultiDayDividend(c, 'DRY_RUN')
})

app.post('/api/diag/recalc-multi-day-dividend', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  const confirm = c.req.query('confirm') || ''
  if (confirm !== 'GO') return c.json({ error: 'confirm=GO 필요 (실 변경 게이트)' }, 400)
  return diagRecalcMultiDayDividend(c, 'EXEC')
})


// ============================================================================
// recalc-single-reward-date (5/11 ONLY): 사장님 명령 (2026-05-18)
//
//   사장님 명령 (직접 인용):
//     "5월11일꺼 전부 다시 내 영구룰에 맞춰서 재 정산하라!
//      다만 9일및 10일 휴일진입자를 반드시 포함해서!
//      내 영구룰에 맞춰! 다른 날 절대 건들면 안됨!!!"
//
//     "5월 11일 지급은 가입자 (5월 8일 이전 가입자 + 5월9일 + 5월 10일)
//      의 총액을 바텀업하는거야 맞지?" → YES
//
//   영구룰 #휴일진입자:
//     "5/9/5/10 진입자 → 5/11(첫 평일) 1회 1건, 이후 매 평일"
//     → 5/10 reward_date 는 영구룰 위반. 5/11 로 통합되어야 함.
//
//   처리 순서 (atomic 1 EXEC):
//     ① PURGE: reward_date IN ('2026-05-10', '2026-05-11') 의 DR/RR + tx + balance 역차감
//        - legacy 5/10 reward 49건 (영구룰 위반) 청산
//        - 이전 EXEC 의 5/11 reward 55건+107건 (재계산 위해) 청산
//     ② RECALC INSERT: reward_date='2026-05-11' 만 영구룰 정확
//        - 5/8 이전 평일 가입자 + 5/9 + 5/10 휴일 진입자 = 전원 1일치 DR
//        - 바텀업: L1 (20%) + L2 (10%)
//        - 200% Cap: 다른 날짜 (5/12, 5/13, 5/14, 5/15) reward 가 이미 paid 되어 있으므로
//          userPaidExcl = 현재 DB tx 합계 - (5/10 + 5/11 reward 의 기존 tx 합계)
//        - tx/DR/RR created_at = 2026-05-12 06:15:00 UTC (= KST 15:15)
//        - paid_date = 2026-05-12
//     ③ PROTECT 검증: 5/12, 5/13, 5/14, 5/15 reward_date 전부 BEFORE = AFTER (한 row 도 변하면 실패)
//
//   3중 안전장치:
//     - TARGET_REWARD_DATE 하드코딩 = '2026-05-11' (변경 불가)
//     - PURGE_REWARD_DATES 하드코딩 = ['2026-05-10', '2026-05-11'] (변경 불가)
//     - PROTECTED_REWARD_DATES = ['2026-05-12','2026-05-13','2026-05-14','2026-05-15']
//
//   엔드포인트:
//     GET  /api/diag/recalc-single-reward-date?key=ADMIN_PW         → DRY_RUN
//     POST /api/diag/recalc-single-reward-date?key=ADMIN_PW&confirm=GO → EXEC
// ============================================================================
async function diagRecalcSingleRewardDate(c: any, mode: 'DRY_RUN' | 'EXEC') {
  const t0 = Date.now()
  try {
    const db = c.env.DB
    const USD_TO_QKEY = 150

    // ★ 하드코딩 — 절대 변경 불가 ★
    const TARGET_REWARD_DATE = '2026-05-11'
    const TARGET_PAID_DATE = '2026-05-12'
    const PURGE_REWARD_DATES = ['2026-05-10', '2026-05-11']  // legacy + 이전 EXEC 청산
    const PROTECTED_REWARD_DATES = ['2026-05-12', '2026-05-13', '2026-05-14', '2026-05-15']

    // ═══════════════════════════════════════════════
    // PHASE 0: PROTECTED reward_date baseline snapshot
    // ═══════════════════════════════════════════════
    const protectBaseline: any[] = []
    for (const pd of PROTECTED_REWARD_DATES) {
      const drB = await db.prepare(`SELECT COUNT(*) AS cnt, COALESCE(SUM(usdt_amount),0) AS total FROM daily_rewards WHERE reward_date = ?`).bind(pd).first() as any
      const rrB = await db.prepare(`SELECT COUNT(*) AS cnt, COALESCE(SUM(reward_amount),0) AS total FROM referral_rewards WHERE reward_date = ?`).bind(pd).first() as any
      protectBaseline.push({
        reward_date: pd,
        dr_count: Number(drB?.cnt || 0), dr_total: Number(drB?.total || 0),
        rr_count: Number(rrB?.cnt || 0), rr_total: Number(rrB?.total || 0),
      })
    }

    // ═══════════════════════════════════════════════
    // PHASE 1: PURGE 대상 수집 (DR/RR + 매핑 tx + balance delta)
    // ═══════════════════════════════════════════════
    // 영구룰 위반인 5/10 reward_date + 이전 EXEC 의 5/11 reward_date 둘 다 청산
    const purgeDrRows = await db.prepare(`
      SELECT id, user_id, staking_id, usdt_amount, reward_date, paid_date
      FROM daily_rewards WHERE reward_date IN (?, ?)
    `).bind(...PURGE_REWARD_DATES).all()
    const purgeDrList = (purgeDrRows.results || []) as any[]

    const purgeRrRows = await db.prepare(`
      SELECT id, referrer_id, referee_id, level, staking_id, reward_amount, reward_date, paid_date
      FROM referral_rewards WHERE reward_date IN (?, ?)
    `).bind(...PURGE_REWARD_DATES).all()
    const purgeRrList = (purgeRrRows.results || []) as any[]

    // 매핑된 tx 수집 (ref_id 로 추적)
    const purgeDrIds = purgeDrList.map((r: any) => Number(r.id))
    const purgeRrIds = purgeRrList.map((r: any) => Number(r.id))

    let purgeDrTxs: any[] = []
    if (purgeDrIds.length > 0) {
      const CHUNK = 100
      for (let i = 0; i < purgeDrIds.length; i += CHUNK) {
        const chunk = purgeDrIds.slice(i, i + CHUNK)
        const ph = chunk.map(() => '?').join(',')
        const res = await db.prepare(`
          SELECT id, user_id, amount, ref_id, type
          FROM transactions
          WHERE type='daily_qkey' AND coin_type='QKEY' AND ref_id IN (${ph})
        `).bind(...chunk).all()
        purgeDrTxs = purgeDrTxs.concat((res.results || []) as any[])
      }
    }

    let purgeRrTxs: any[] = []
    if (purgeRrIds.length > 0) {
      const CHUNK = 100
      for (let i = 0; i < purgeRrIds.length; i += CHUNK) {
        const chunk = purgeRrIds.slice(i, i + CHUNK)
        const ph = chunk.map(() => '?').join(',')
        const res = await db.prepare(`
          SELECT id, user_id, amount, ref_id, type
          FROM transactions
          WHERE type IN ('referral_reward','direct_referral') AND coin_type='QKEY' AND ref_id IN (${ph})
        `).bind(...chunk).all()
        purgeRrTxs = purgeRrTxs.concat((res.results || []) as any[])
      }
    }

    // balance 역차감 누계 (user_id -> delta to subtract)
    const purgeBalanceDelta = new Map<number, number>()
    for (const tx of purgeDrTxs) {
      const uid = Number(tx.user_id), amt = Number(tx.amount)
      purgeBalanceDelta.set(uid, (purgeBalanceDelta.get(uid) || 0) + amt)
    }
    for (const tx of purgeRrTxs) {
      const uid = Number(tx.user_id), amt = Number(tx.amount)
      purgeBalanceDelta.set(uid, (purgeBalanceDelta.get(uid) || 0) + amt)
    }

    const purgeStats = {
      dr_rows: purgeDrList.length,
      dr_tx: purgeDrTxs.length,
      dr_tx_total: purgeDrTxs.reduce((s, t) => s + Number(t.amount), 0),
      rr_rows: purgeRrList.length,
      rr_tx: purgeRrTxs.length,
      rr_tx_total: purgeRrTxs.reduce((s, t) => s + Number(t.amount), 0),
      total_balance_subtract: Array.from(purgeBalanceDelta.values()).reduce((s, v) => s + v, 0),
      affected_users: purgeBalanceDelta.size,
      reward_date_breakdown: {} as Record<string, { dr: number, rr: number }>,
    }
    for (const r of purgeDrList) {
      const k = String(r.reward_date)
      if (!purgeStats.reward_date_breakdown[k]) purgeStats.reward_date_breakdown[k] = { dr: 0, rr: 0 }
      purgeStats.reward_date_breakdown[k].dr += 1
    }
    for (const r of purgeRrList) {
      const k = String(r.reward_date)
      if (!purgeStats.reward_date_breakdown[k]) purgeStats.reward_date_breakdown[k] = { dr: 0, rr: 0 }
      purgeStats.reward_date_breakdown[k].rr += 1
    }

    // ═══════════════════════════════════════════════
    // PHASE 2: RECALC 계산 (영구룰대로 reward_date=5/11)
    // ═══════════════════════════════════════════════
    // user 전수 조회: stake_total + refMap + activeUserSet
    const userStakeTotal = new Map<number, number>()
    const refMap = new Map<number, number>()
    const activeUserSet = new Set<number>()

    {
      const allStakingRows = await db.prepare(`
        SELECT DISTINCT s.user_id, u.referrer_id
        FROM staking s
        JOIN users u ON u.id = s.user_id
        WHERE s.status IN ('active','capped','completed')
      `).all()
      const candidateUids = new Set<number>()
      for (const r of (allStakingRows.results || []) as any[]) {
        candidateUids.add(Number(r.user_id))
        if (r.referrer_id) candidateUids.add(Number(r.referrer_id))
      }
      const uidsArr0 = Array.from(candidateUids)
      const CHUNK = 100
      if (uidsArr0.length > 0) {
        for (let i = 0; i < uidsArr0.length; i += CHUNK) {
          const chunk = uidsArr0.slice(i, i + CHUNK)
          const ph = chunk.map(() => '?').join(',')
          const rows = await db.prepare(`SELECT id, referrer_id FROM users WHERE id IN (${ph})`).bind(...chunk).all()
          for (const u of (rows.results || []) as any[]) {
            refMap.set(Number(u.id), u.referrer_id ? Number(u.referrer_id) : 0)
            if (u.referrer_id) candidateUids.add(Number(u.referrer_id))
          }
        }
        const missingL2 = Array.from(candidateUids).filter(u => !refMap.has(u))
        if (missingL2.length > 0) {
          for (let i = 0; i < missingL2.length; i += CHUNK) {
            const chunk = missingL2.slice(i, i + CHUNK)
            const ph = chunk.map(() => '?').join(',')
            const rows = await db.prepare(`SELECT id, referrer_id FROM users WHERE id IN (${ph})`).bind(...chunk).all()
            for (const u of (rows.results || []) as any[]) {
              refMap.set(Number(u.id), u.referrer_id ? Number(u.referrer_id) : 0)
            }
          }
        }
      }
      const uidsArr = Array.from(candidateUids)
      if (uidsArr.length > 0) {
        for (let i = 0; i < uidsArr.length; i += CHUNK) {
          const chunk = uidsArr.slice(i, i + CHUNK)
          const ph = chunk.map(() => '?').join(',')
          const rows = await db.prepare(`
            SELECT user_id, COALESCE(SUM(amount),0) AS total
            FROM staking WHERE user_id IN (${ph})
              AND status IN ('active','completed','capped')
            GROUP BY user_id
          `).bind(...chunk).all()
          for (const r of (rows.results || []) as any[]) {
            userStakeTotal.set(Number(r.user_id), Number(r.total))
          }
        }
      }
      const aRows = await db.prepare(`
        SELECT DISTINCT user_id FROM staking
        WHERE status IN ('active','capped','completed')
      `).all()
      for (const r of (aRows.results || []) as any[]) activeUserSet.add(Number(r.user_id))
    }

    // userPaidExcl = (현재 DB tx 합계) - (PURGE 대상 tx 합계)
    //   → PURGE 후의 tx 합계 = RECALC 시작 시 baseline
    //   → 5/12, 5/13, 5/14, 5/15 reward 의 paid 분은 자연스럽게 포함 (이미 paid 됐으므로)
    const userPaidExcl = new Map<number, number>()
    {
      const uidsArr = Array.from(userStakeTotal.keys())
      const CHUNK = 100
      if (uidsArr.length > 0) {
        for (let i = 0; i < uidsArr.length; i += CHUNK) {
          const chunk = uidsArr.slice(i, i + CHUNK)
          const ph = chunk.map(() => '?').join(',')
          const rows = await db.prepare(`
            SELECT user_id, COALESCE(SUM(amount),0) AS total
            FROM transactions
            WHERE user_id IN (${ph}) AND coin_type='QKEY'
              AND type IN ('daily_qkey','referral_reward','direct_referral')
            GROUP BY user_id
          `).bind(...chunk).all()
          for (const r of (rows.results || []) as any[]) {
            userPaidExcl.set(Number(r.user_id), Math.max(0, Number(r.total)))
          }
        }
      }
      // PURGE 분 차감 (PURGE 후의 baseline)
      for (const [uid, sub] of purgeBalanceDelta.entries()) {
        userPaidExcl.set(uid, Math.max(0, (userPaidExcl.get(uid) || 0) - sub))
      }
    }

    // RECALC 본 계산 (reward_date=5/11)
    // 영구룰 #휴일진입자: 5/9/5/10 진입자도 5/11 이 첫 평일이므로 1일치 발생
    //   → 단순히 dividendDate=5/11 인 active staking 전수 = 5/8 이전 + 5/9 + 5/10 모두 포함
    const stakingRows = await db.prepare(`
      SELECT s.id AS staking_id, s.user_id, s.amount, s.daily_rate,
             date(s.start_date,'+9 hours') AS start_kst,
             date(s.end_date,'+9 hours') AS end_kst,
             s.status,
             u.referrer_id
      FROM staking s
      JOIN users u ON u.id = s.user_id
      WHERE s.status IN ('active','capped','completed')
        AND date(s.start_date,'+9 hours') <= ?
        AND date(s.end_date,'+9 hours') >= ?
      ORDER BY s.id ASC
    `).bind(TARGET_REWARD_DATE, TARGET_REWARD_DATE).all()
    const stakingList = (stakingRows.results || []) as any[]

    const expectedDRs: { user_id: number, staking_id: number, amount: number }[] = []
    const expectedRRs: { referrer_id: number, referee_id: number, level: number, staking_id: number, original_amount: number, reward_amount: number }[] = []
    const userPaidRound = new Map<number, number>()
    const dr_capped = new Set<number>()
    const l1_capped = new Set<number>()
    const l2_capped = new Set<number>()

    function tryGive(uid: number, requested: number): { granted: number, capped: boolean } {
      const stakeTotal = userStakeTotal.get(uid) || 0
      if (stakeTotal <= 0) return { granted: 0, capped: true }
      const target = stakeTotal * 2 * USD_TO_QKEY
      const paidExcl = userPaidExcl.get(uid) || 0
      const paidRound = userPaidRound.get(uid) || 0
      const current = paidExcl + paidRound
      if (current >= target) return { granted: 0, capped: true }
      const remaining = target - current
      const granted = Math.min(requested, Math.floor(remaining))
      if (granted > 0) userPaidRound.set(uid, paidRound + granted)
      return { granted, capped: granted < requested }
    }

    // 진입일 분류 통계 (보고용)
    const entryDateBreakdown = { before_0509: 0, on_0509: 0, on_0510: 0, other: 0 }
    for (const s of stakingList) {
      const sd = String(s.start_kst)
      if (sd <= '2026-05-08') entryDateBreakdown.before_0509 += 1
      else if (sd === '2026-05-09') entryDateBreakdown.on_0509 += 1
      else if (sd === '2026-05-10') entryDateBreakdown.on_0510 += 1
      else entryDateBreakdown.other += 1
    }

    for (const s of stakingList) {
      const stakingId = Number(s.staking_id)
      const uid = Number(s.user_id)
      const amt = Number(s.amount) || 0
      const rate = Number(s.daily_rate) || 0
      const ownReqQkey = Math.round(amt * rate * USD_TO_QKEY)
      if (ownReqQkey <= 0) continue

      const ownGrant = tryGive(uid, ownReqQkey)
      if (ownGrant.granted > 0) expectedDRs.push({ user_id: uid, staking_id: stakingId, amount: ownGrant.granted })
      if (ownGrant.capped && ownGrant.granted < ownReqQkey) dr_capped.add(uid)

      const l1Uid = refMap.get(uid) || 0
      if (l1Uid > 0 && activeUserSet.has(l1Uid)) {
        const l1Req = Math.round(ownReqQkey * 0.20)
        if (l1Req > 0) {
          const l1Grant = tryGive(l1Uid, l1Req)
          if (l1Grant.granted > 0) expectedRRs.push({
            referrer_id: l1Uid, referee_id: uid, level: 1, staking_id: stakingId,
            original_amount: ownReqQkey, reward_amount: l1Grant.granted,
          })
          if (l1Grant.capped && l1Grant.granted < l1Req) l1_capped.add(l1Uid)
        }
      }

      const l2Uid = l1Uid > 0 ? (refMap.get(l1Uid) || 0) : 0
      if (l2Uid > 0 && activeUserSet.has(l2Uid)) {
        const l2Req = Math.round(ownReqQkey * 0.10)
        if (l2Req > 0) {
          const l2Grant = tryGive(l2Uid, l2Req)
          if (l2Grant.granted > 0) expectedRRs.push({
            referrer_id: l2Uid, referee_id: uid, level: 2, staking_id: stakingId,
            original_amount: ownReqQkey, reward_amount: l2Grant.granted,
          })
          if (l2Grant.capped && l2Grant.granted < l2Req) l2_capped.add(l2Uid)
        }
      }
    }

    const recalcStats = {
      dr_count: expectedDRs.length,
      dr_total: expectedDRs.reduce((s, r) => s + r.amount, 0),
      l1_count: expectedRRs.filter(r => r.level === 1).length,
      l1_total: expectedRRs.filter(r => r.level === 1).reduce((s, r) => s + r.reward_amount, 0),
      l2_count: expectedRRs.filter(r => r.level === 2).length,
      l2_total: expectedRRs.filter(r => r.level === 2).reduce((s, r) => s + r.reward_amount, 0),
      tx_count: expectedDRs.length + expectedRRs.length,
      total_balance_add: 0,
      cap_info: { dr_capped: dr_capped.size, l1_capped: l1_capped.size, l2_capped: l2_capped.size },
      entry_date_breakdown: entryDateBreakdown,
      affected_users: new Set([...expectedDRs.map(r => r.user_id), ...expectedRRs.map(r => r.referrer_id)]).size,
    }
    recalcStats.total_balance_add = recalcStats.dr_total + recalcStats.l1_total + recalcStats.l2_total

    // ═══════════════════════════════════════════════
    // PHASE 3: net balance delta = recalc_add - purge_subtract
    // ═══════════════════════════════════════════════
    const netBalanceDelta = new Map<number, number>()
    for (const [uid, sub] of purgeBalanceDelta.entries()) {
      netBalanceDelta.set(uid, -sub)
    }
    for (const dr of expectedDRs) {
      netBalanceDelta.set(dr.user_id, (netBalanceDelta.get(dr.user_id) || 0) + dr.amount)
    }
    for (const rr of expectedRRs) {
      netBalanceDelta.set(rr.referrer_id, (netBalanceDelta.get(rr.referrer_id) || 0) + rr.reward_amount)
    }

    // ═══════════════════════════════════════════════
    // DRY-RUN 응답
    // ═══════════════════════════════════════════════
    if (mode === 'DRY_RUN') {
      const userIds = Array.from(netBalanceDelta.keys())
      const userSim: any[] = []
      if (userIds.length > 0) {
        const CHUNK = 100
        for (let i = 0; i < userIds.length; i += CHUNK) {
          const chunk = userIds.slice(i, i + CHUNK)
          const ph = chunk.map(() => '?').join(',')
          const rows = await db.prepare(`SELECT id, name, email, qkey_balance FROM users WHERE id IN (${ph})`).bind(...chunk).all()
          for (const u of (rows.results || []) as any[]) {
            const delta = netBalanceDelta.get(Number(u.id)) || 0
            userSim.push({
              user_id: Number(u.id), name: u.name, email: u.email,
              current_balance: Number(u.qkey_balance),
              net_delta: delta,
              post_balance: Number(u.qkey_balance) + delta,
              will_go_negative: (Number(u.qkey_balance) + delta) < 0,
            })
          }
        }
      }
      const negAfter = userSim.filter(u => u.will_go_negative)

      return c.json({
        ok: true,
        mode: 'DRY_RUN',
        action: 'recalc-single-reward-date',
        config: {
          target_reward_date: TARGET_REWARD_DATE,
          target_paid_date: TARGET_PAID_DATE,
          purge_reward_dates: PURGE_REWARD_DATES,
          protected_reward_dates: PROTECTED_REWARD_DATES,
        },
        phase1_purge: purgeStats,
        phase2_recalc: recalcStats,
        phase3_net: {
          net_balance_delta_total: Array.from(netBalanceDelta.values()).reduce((s, v) => s + v, 0),
          affected_users: netBalanceDelta.size,
        },
        protect_baseline: protectBaseline,
        balance_sim_top20: userSim.sort((a, b) => Math.abs(b.net_delta) - Math.abs(a.net_delta)).slice(0, 20),
        negative_after: { count: negAfter.length, samples: negAfter.slice(0, 10) },
        next_action: 'POST + confirm=GO 보내시면 1 EXEC 으로 PURGE+RECALC',
        duration_ms: Date.now() - t0,
      })
    }

    // ═══════════════════════════════════════════════
    // EXEC PHASE
    // ═══════════════════════════════════════════════
    const CHUNK = 80
    const phaseTimings: any = {}

    // ── EXEC-1: PURGE tx ──
    const t1 = Date.now()
    const allPurgeTxIds = [...purgeDrTxs.map((t: any) => Number(t.id)), ...purgeRrTxs.map((t: any) => Number(t.id))]
    for (let i = 0; i < allPurgeTxIds.length; i += CHUNK) {
      const chunk = allPurgeTxIds.slice(i, i + CHUNK)
      const stmts = chunk.map(id => db.prepare(`DELETE FROM transactions WHERE id = ?`).bind(id))
      if (stmts.length > 0) await db.batch(stmts)
    }
    phaseTimings.purge_tx_ms = Date.now() - t1

    // ── EXEC-2: PURGE RR ──
    const t2 = Date.now()
    const rrIds = purgeRrList.map((r: any) => Number(r.id))
    for (let i = 0; i < rrIds.length; i += CHUNK) {
      const chunk = rrIds.slice(i, i + CHUNK)
      const stmts = chunk.map(id => db.prepare(`DELETE FROM referral_rewards WHERE id = ?`).bind(id))
      if (stmts.length > 0) await db.batch(stmts)
    }
    phaseTimings.purge_rr_ms = Date.now() - t2

    // ── EXEC-3: PURGE DR ──
    const t3 = Date.now()
    const drIds = purgeDrList.map((r: any) => Number(r.id))
    for (let i = 0; i < drIds.length; i += CHUNK) {
      const chunk = drIds.slice(i, i + CHUNK)
      const stmts = chunk.map(id => db.prepare(`DELETE FROM daily_rewards WHERE id = ?`).bind(id))
      if (stmts.length > 0) await db.batch(stmts)
    }
    phaseTimings.purge_dr_ms = Date.now() - t3

    // ── EXEC-4: RECALC DR INSERT ──
    const t4 = Date.now()
    // PERMANENT_RULE #regular-time (2026-05-19): KST 08:00 = UTC (paid_date - 1day) 23:00
    const _prevKstStr_e4 = kstDateStr(new Date(new Date(TARGET_PAID_DATE + 'T00:00:00+09:00').getTime() - 24 * 60 * 60 * 1000))
    const drCreatedAt = `${_prevKstStr_e4} 23:00:00`  // KST 08:00:00 of paid_date
    const rrCreatedAt = `${_prevKstStr_e4} 23:00:01`  // KST 08:00:01 of paid_date

    for (let i = 0; i < expectedDRs.length; i += CHUNK) {
      const chunk = expectedDRs.slice(i, i + CHUNK)
      const stmts = chunk.map(dr =>
        db.prepare(`
          INSERT INTO daily_rewards (user_id, staking_id, usdt_amount, reward_date, paid_date, created_at)
          VALUES (?, ?, ?, ?, ?, ?)
        `).bind(dr.user_id, dr.staking_id, dr.amount, TARGET_REWARD_DATE, TARGET_PAID_DATE, drCreatedAt)
      )
      if (stmts.length > 0) await db.batch(stmts)
    }

    const drRowsAfter = await db.prepare(`
      SELECT id, user_id, staking_id FROM daily_rewards
      WHERE reward_date = ? AND paid_date = ?
    `).bind(TARGET_REWARD_DATE, TARGET_PAID_DATE).all()
    const drIdMap = new Map<string, number>()
    for (const r of (drRowsAfter.results || []) as any[]) {
      drIdMap.set(`${r.user_id}|${r.staking_id}`, Number(r.id))
    }

    const drTxStmts = expectedDRs.map(dr => {
      const drId = drIdMap.get(`${dr.user_id}|${dr.staking_id}`) ?? null
      return db.prepare(`
        INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id, created_at)
        VALUES (?, 'daily_qkey', 'QKEY', ?, ?, ?, ?)
      `).bind(dr.user_id, dr.amount, '일일 배당 (QKEY)', drId, drCreatedAt)
    })
    for (let i = 0; i < drTxStmts.length; i += CHUNK) {
      const c2 = drTxStmts.slice(i, i + CHUNK)
      if (c2.length > 0) await db.batch(c2)
    }
    phaseTimings.recalc_dr_ms = Date.now() - t4

    // ── EXEC-5: RECALC RR INSERT ──
    const t5 = Date.now()
    for (let i = 0; i < expectedRRs.length; i += CHUNK) {
      const chunk = expectedRRs.slice(i, i + CHUNK)
      const stmts = chunk.map(rr =>
        db.prepare(`
          INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, staking_id, created_at)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        `).bind(rr.referrer_id, rr.referee_id, rr.level, rr.original_amount, rr.reward_amount, TARGET_REWARD_DATE, TARGET_PAID_DATE, rr.staking_id, drCreatedAt)
      )
      if (stmts.length > 0) await db.batch(stmts)
    }

    const rrRowsAfter = await db.prepare(`
      SELECT id, referrer_id, referee_id, level, staking_id FROM referral_rewards
      WHERE reward_date = ? AND paid_date = ?
    `).bind(TARGET_REWARD_DATE, TARGET_PAID_DATE).all()
    const rrIdMap = new Map<string, number>()
    for (const r of (rrRowsAfter.results || []) as any[]) {
      rrIdMap.set(`${r.referrer_id}|${r.referee_id}|${r.level}|${r.staking_id}`, Number(r.id))
    }

    const rrTxStmts = expectedRRs.map(rr => {
      const rrId = rrIdMap.get(`${rr.referrer_id}|${rr.referee_id}|${rr.level}|${rr.staking_id}`) ?? null
      const desc = rr.level === 1 ? '추천 보너스 (Level 1)' : '추천 보너스 (Level 2)'
      return db.prepare(`
        INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id, created_at)
        VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?, ?)
      `).bind(rr.referrer_id, rr.reward_amount, desc, rrId, rrCreatedAt)
    })
    for (let i = 0; i < rrTxStmts.length; i += CHUNK) {
      const c2 = rrTxStmts.slice(i, i + CHUNK)
      if (c2.length > 0) await db.batch(c2)
    }
    phaseTimings.recalc_rr_ms = Date.now() - t5

    // ── EXEC-6: net balance UPDATE (PURGE -, RECALC +) ──
    const t6 = Date.now()
    const balEntries = Array.from(netBalanceDelta.entries())
    for (let i = 0; i < balEntries.length; i += CHUNK) {
      const chunk = balEntries.slice(i, i + CHUNK)
      const stmts = chunk.map(([uid, delta]) =>
        db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(delta, uid)
      )
      if (stmts.length > 0) await db.batch(stmts)
    }
    phaseTimings.balance_update_ms = Date.now() - t6

    // ── POST-CHECK ──
    const postDR = await db.prepare(`SELECT COUNT(*) AS cnt, COALESCE(SUM(usdt_amount),0) AS total FROM daily_rewards WHERE reward_date = ?`).bind(TARGET_REWARD_DATE).first() as any
    const postRR = await db.prepare(`SELECT COUNT(*) AS cnt, COALESCE(SUM(reward_amount),0) AS total FROM referral_rewards WHERE reward_date = ?`).bind(TARGET_REWARD_DATE).first() as any
    const postPurgeDR = await db.prepare(`SELECT COUNT(*) AS cnt FROM daily_rewards WHERE reward_date IN (?, ?)`).bind(...PURGE_REWARD_DATES).first() as any
    const postPurgeRR = await db.prepare(`SELECT COUNT(*) AS cnt FROM referral_rewards WHERE reward_date IN (?, ?)`).bind(...PURGE_REWARD_DATES).first() as any

    // ── PROTECT 재확인 ──
    const protectAfter: any[] = []
    for (const pd of PROTECTED_REWARD_DATES) {
      const drB = await db.prepare(`SELECT COUNT(*) AS cnt, COALESCE(SUM(usdt_amount),0) AS total FROM daily_rewards WHERE reward_date = ?`).bind(pd).first() as any
      const rrB = await db.prepare(`SELECT COUNT(*) AS cnt, COALESCE(SUM(reward_amount),0) AS total FROM referral_rewards WHERE reward_date = ?`).bind(pd).first() as any
      protectAfter.push({
        reward_date: pd,
        dr_count: Number(drB?.cnt || 0), dr_total: Number(drB?.total || 0),
        rr_count: Number(rrB?.cnt || 0), rr_total: Number(rrB?.total || 0),
      })
    }
    const protectIntact = JSON.stringify(protectBaseline) === JSON.stringify(protectAfter)

    const postDrCount = Number(postDR?.cnt || 0)
    const postRrCount = Number(postRR?.cnt || 0)
    const drMatch = postDrCount === expectedDRs.length
    const rrMatch = postRrCount === expectedRRs.length
    const purgeClean = Number(postPurgeDR?.cnt || 0) === expectedDRs.length /* only target reward_date remains */
      && Number(postPurgeRR?.cnt || 0) === expectedRRs.length
    // Note: PURGE_REWARD_DATES includes TARGET_REWARD_DATE, so after RECALC the count
    //   equals the new insert (5/10 = 0, 5/11 = expectedDRs.length)
    // Check 5/10 specifically must be 0
    const post0510DR = await db.prepare(`SELECT COUNT(*) AS cnt FROM daily_rewards WHERE reward_date = ?`).bind('2026-05-10').first() as any
    const post0510RR = await db.prepare(`SELECT COUNT(*) AS cnt FROM referral_rewards WHERE reward_date = ?`).bind('2026-05-10').first() as any
    const legacy0510Gone = Number(post0510DR?.cnt || 0) === 0 && Number(post0510RR?.cnt || 0) === 0

    return c.json({
      ok: protectIntact && drMatch && rrMatch && legacy0510Gone,
      mode: 'EXEC',
      action: 'recalc-single-reward-date',
      config: {
        target_reward_date: TARGET_REWARD_DATE,
        target_paid_date: TARGET_PAID_DATE,
        purge_reward_dates: PURGE_REWARD_DATES,
        protected_reward_dates: PROTECTED_REWARD_DATES,
      },
      phase_timings_ms: phaseTimings,
      purge_executed: purgeStats,
      recalc_inserted: {
        dr_count: expectedDRs.length,
        dr_total: recalcStats.dr_total,
        rr_count: expectedRRs.length,
        rr_total: recalcStats.l1_total + recalcStats.l2_total,
        entry_date_breakdown: entryDateBreakdown,
      },
      net_balance_delta_total: Array.from(netBalanceDelta.values()).reduce((s, v) => s + v, 0),
      balance_adjusted_users: netBalanceDelta.size,
      post_check: {
        target_dr_count: postDrCount,
        target_dr_total: Number(postDR?.total || 0),
        target_rr_count: postRrCount,
        target_rr_total: Number(postRR?.total || 0),
        dr_match: drMatch,
        rr_match: rrMatch,
        legacy_0510_gone: legacy0510Gone,
        legacy_0510_dr: Number(post0510DR?.cnt || 0),
        legacy_0510_rr: Number(post0510RR?.cnt || 0),
      },
      protect_check: {
        baseline: protectBaseline,
        after: protectAfter,
        intact: protectIntact,
      },
      duration_ms: Date.now() - t0,
    })
  } catch (error) {
    return c.json({ error: String(error), duration_ms: Date.now() - t0 }, 500)
  }
}

app.get('/api/diag/recalc-single-reward-date', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  return diagRecalcSingleRewardDate(c, 'DRY_RUN')
})

app.post('/api/diag/recalc-single-reward-date', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  const confirm = c.req.query('confirm') || ''
  if (confirm !== 'GO') return c.json({ error: 'confirm=GO 필요 (실 변경 게이트)' }, 400)
  return diagRecalcSingleRewardDate(c, 'EXEC')
})

// ============================================================================
// user-reward-audit: 특정 사용자 의 특정 paid_date 전체 reward 흔적 (READ-ONLY)
//
//   사장님 명령: "이현우 김주성 12일 중복 점검"
//
//   대상자 찾기:
//     - name LIKE 또는 user_id 직접
//   검사 항목:
//     ① 그 user_id 가 해당 paid_date 에 받은 모든 daily_qkey tx
//     ② 그 user_id 가 해당 paid_date 에 받은 모든 referral_reward / direct_referral tx
//     ③ 매칭된 daily_rewards row 전부 (reward_date 별)
//     ④ 매칭된 referral_rewards row 전부 (reward_date 별)
//     ⑤ 사용자 staking 목록 (active/completed/capped)
//     ⑥ 누적 paid_total vs 200% target
//
//   엔드포인트:
//     GET /api/diag/user-reward-audit?key=ADMIN_PW&paidDate=2026-05-12&names=이현우,김주성
//     GET /api/diag/user-reward-audit?key=ADMIN_PW&paidDate=2026-05-12&userIds=1,2,3
// ============================================================================
// ============================================================================
// recalc-may-seven: 사장님 명령 (2026-05-18 / 깊은 밤)
//
//   "5월 7일 확정분을 5월 8일자 지급했는데 기존꺼 무시하고 내 영구룰로 다시 정산하라!"
//
//   영구룰 위반 청산 + 재정산:
//     - PURGE: reward_date='2026-05-07' AND paid_date='2026-05-08' 의 모든 항목
//       + paid_date='2026-05-08' 의 모든 tx (DR/RR id 매칭 + 패턴 매칭)
//     - RECALC: reward_date='2026-05-07' 영구룰 정확 (DR + L1 + L2 + 200% Cap)
//     - PAID: paid_date='2026-05-08', created_at = '2026-05-08 06:15:00 UTC' (KST 15:15)
//
//   대상자: 5/6 이전 가입자 (5/7 평일, 휴일 진입자 이슈 없음)
//
//   절대 보호 (BEFORE/AFTER snapshot 비교):
//     - reward_date IN ('2026-05-08','5-09','5-10','5-11','5-12','5-13','5-14','5-15')
//
//   엔드포인트:
//     GET  /api/diag/recalc-may-seven?key=ADMIN_PW          → DRY_RUN
//     POST /api/diag/recalc-may-seven?key=ADMIN_PW&confirm=GO → EXEC
// ============================================================================
async function diagRecalcMaySeven(c: any, mode: 'DRY_RUN' | 'EXEC') {
  const t0 = Date.now()
  try {
    const db = c.env.DB
    const USD_TO_QKEY = 150

    // ★ 하드코딩 ★
    const TARGET_REWARD_DATE = '2026-05-07'
    const TARGET_PAID_DATE = '2026-05-08'
    const PROTECTED_REWARD_DATES = [
      '2026-05-08','2026-05-09','2026-05-10','2026-05-11',
      '2026-05-12','2026-05-13','2026-05-14','2026-05-15',
    ]

    // ─── PROTECT BASELINE (BEFORE) ───
    const protectBaseline: any[] = []
    for (const pd of PROTECTED_REWARD_DATES) {
      const drB = await db.prepare(`SELECT COUNT(*) AS cnt, COALESCE(SUM(usdt_amount),0) AS total FROM daily_rewards WHERE reward_date = ?`).bind(pd).first() as any
      const rrB = await db.prepare(`SELECT COUNT(*) AS cnt, COALESCE(SUM(reward_amount),0) AS total FROM referral_rewards WHERE reward_date = ?`).bind(pd).first() as any
      protectBaseline.push({
        reward_date: pd,
        dr_count: Number(drB?.cnt || 0), dr_total: Number(drB?.total || 0),
        rr_count: Number(rrB?.cnt || 0), rr_total: Number(rrB?.total || 0),
      })
    }

    // ═══════════════════════════════════════════════
    // PHASE 1: PURGE 대상 수집 (3 종류)
    //   (a) DR/RR rows: reward_date=2026-05-07 인 모든 row
    //   (b) DR/RR rows: paid_date=2026-05-08 인 모든 row (혹시 reward_date 가 다른 것 있을 수 있음)
    //   (c) tx: paid_date=2026-05-08 인 DR/RR 의 ref_id 매칭 + paid_date 가 KST 5/8 인 daily_qkey/referral_reward/direct_referral
    // ═══════════════════════════════════════════════

    // (a) reward_date=5/7 의 DR/RR
    const drByRewardDate = (await db.prepare(`
      SELECT id, user_id, staking_id, usdt_amount, reward_date, paid_date
      FROM daily_rewards WHERE reward_date = ?
    `).bind(TARGET_REWARD_DATE).all()).results as any[] || []

    const rrByRewardDate = (await db.prepare(`
      SELECT id, referrer_id, referee_id, level, staking_id, reward_amount, reward_date, paid_date
      FROM referral_rewards WHERE reward_date = ?
    `).bind(TARGET_REWARD_DATE).all()).results as any[] || []

    // (b) paid_date=5/8 의 DR/RR (혹시 reward_date 다른 잡것 있는지)
    const drByPaidDate = (await db.prepare(`
      SELECT id, user_id, staking_id, usdt_amount, reward_date, paid_date
      FROM daily_rewards WHERE paid_date = ?
    `).bind(TARGET_PAID_DATE).all()).results as any[] || []

    const rrByPaidDate = (await db.prepare(`
      SELECT id, referrer_id, referee_id, level, staking_id, reward_amount, reward_date, paid_date
      FROM referral_rewards WHERE paid_date = ?
    `).bind(TARGET_PAID_DATE).all()).results as any[] || []

    // PURGE 대상 DR/RR id 통합 (중복 제거)
    const drIdSet = new Set<number>()
    for (const r of drByRewardDate) drIdSet.add(Number(r.id))
    for (const r of drByPaidDate) drIdSet.add(Number(r.id))
    const rrIdSet = new Set<number>()
    for (const r of rrByRewardDate) rrIdSet.add(Number(r.id))
    for (const r of rrByPaidDate) rrIdSet.add(Number(r.id))
    const drIds = Array.from(drIdSet)
    const rrIds = Array.from(rrIdSet)

    // 안전 검사: PURGE 대상의 reward_date 가 모두 5/7 이거나 PROTECT 외인지 확인
    // (만약 paid_date=5/8 인데 reward_date 가 5/11 같은 PROTECT 날짜면 STOP)
    const drToPurgeAll = [...drByRewardDate, ...drByPaidDate]
    const rrToPurgeAll = [...rrByRewardDate, ...rrByPaidDate]
    const drDistinctRewardDates = Array.from(new Set(drToPurgeAll.map(r => String(r.reward_date))))
    const rrDistinctRewardDates = Array.from(new Set(rrToPurgeAll.map(r => String(r.reward_date))))
    const dangerousDr = drDistinctRewardDates.filter(d => PROTECTED_REWARD_DATES.includes(d))
    const dangerousRr = rrDistinctRewardDates.filter(d => PROTECTED_REWARD_DATES.includes(d))
    if (dangerousDr.length > 0 || dangerousRr.length > 0) {
      return c.json({
        ok: false,
        error: '🚨 SAFETY STOP — PURGE 대상에 PROTECTED reward_date 포함됨',
        dangerous_dr_reward_dates: dangerousDr,
        dangerous_rr_reward_dates: dangerousRr,
        hint: '이건 다른 날 reward 가 잘못 5/8 에 paid 된 사고. 사장님 명령 필요.',
      }, 400)
    }

    // (c) tx 수집 — 3가지 경로
    //   c1: paid_date=5/8 의 DR id 에 매칭되는 daily_qkey tx
    //   c2: paid_date=5/8 의 RR id 에 매칭되는 referral_reward / direct_referral tx
    //   c3: KST 5/8 에 발생한 모든 daily_qkey/referral_reward/direct_referral tx (잡것)
    const CHUNK = 80
    const txIdSet = new Set<number>()
    const txDetail: any[] = []

    // c1
    if (drIds.length > 0) {
      for (let i = 0; i < drIds.length; i += CHUNK) {
        const chunk = drIds.slice(i, i + CHUNK)
        const ph = chunk.map(() => '?').join(',')
        const rows = await db.prepare(`
          SELECT id, user_id, type, amount, ref_id, description,
                 datetime(created_at,'+9 hours') AS kst_at
          FROM transactions
          WHERE type='daily_qkey' AND coin_type='QKEY' AND ref_id IN (${ph})
        `).bind(...chunk).all()
        for (const t of (rows.results || []) as any[]) {
          if (!txIdSet.has(Number(t.id))) { txIdSet.add(Number(t.id)); txDetail.push(t) }
        }
      }
    }

    // c2
    if (rrIds.length > 0) {
      for (let i = 0; i < rrIds.length; i += CHUNK) {
        const chunk = rrIds.slice(i, i + CHUNK)
        const ph = chunk.map(() => '?').join(',')
        const rows = await db.prepare(`
          SELECT id, user_id, type, amount, ref_id, description,
                 datetime(created_at,'+9 hours') AS kst_at
          FROM transactions
          WHERE type IN ('referral_reward','direct_referral') AND coin_type='QKEY' AND ref_id IN (${ph})
        `).bind(...chunk).all()
        for (const t of (rows.results || []) as any[]) {
          if (!txIdSet.has(Number(t.id))) { txIdSet.add(Number(t.id)); txDetail.push(t) }
        }
      }
    }

    // c3 — KST 5/8 의 모든 reward tx (DR/RR 매칭 없는 잡것도 포함 — ref_id 가 잘못된 사고분)
    {
      const rows = await db.prepare(`
        SELECT id, user_id, type, amount, ref_id, description,
               datetime(created_at,'+9 hours') AS kst_at
        FROM transactions
        WHERE coin_type='QKEY'
          AND type IN ('daily_qkey','referral_reward','direct_referral')
          AND date(created_at,'+9 hours') = ?
      `).bind(TARGET_PAID_DATE).all()
      for (const t of (rows.results || []) as any[]) {
        if (!txIdSet.has(Number(t.id))) { txIdSet.add(Number(t.id)); txDetail.push(t) }
      }
    }

    const txIds = Array.from(txIdSet)

    // PURGE balance delta (음수)
    const purgeBalanceDelta = new Map<number, number>()
    let purgeTxTotal = 0
    for (const t of txDetail) {
      const uid = Number(t.user_id), amt = Number(t.amount)
      purgeTxTotal += amt
      purgeBalanceDelta.set(uid, (purgeBalanceDelta.get(uid) || 0) - amt)
    }

    // ═══════════════════════════════════════════════
    // PHASE 2: RECALC EXPECTED 계산 (reward_date = 5/7 만)
    // ═══════════════════════════════════════════════

    // staking 조회: 5/7 발생 대상
    const stakingRows = await db.prepare(`
      SELECT s.id AS staking_id, s.user_id, s.amount, s.daily_rate, s.period_days,
             date(s.start_date,'+9 hours') AS start_kst,
             date(s.end_date,'+9 hours') AS end_kst,
             s.status,
             u.referrer_id
      FROM staking s
      JOIN users u ON u.id = s.user_id
      WHERE s.status IN ('active','capped','completed')
        AND date(s.start_date,'+9 hours') <= ?
        AND date(s.end_date,'+9 hours') >= ?
      ORDER BY s.id ASC
    `).bind(TARGET_REWARD_DATE, TARGET_REWARD_DATE).all()
    const stakingList = (stakingRows.results || []) as any[]

    // refMap + stakeTotal + activeUserSet
    const candidateUids = new Set<number>()
    for (const s of stakingList) {
      candidateUids.add(Number(s.user_id))
      if (s.referrer_id) candidateUids.add(Number(s.referrer_id))
    }
    const refMap = new Map<number, number>()
    {
      const uidsArr = Array.from(candidateUids)
      for (let i = 0; i < uidsArr.length; i += 100) {
        const chunk = uidsArr.slice(i, i + 100)
        const ph = chunk.map(() => '?').join(',')
        const rows = await db.prepare(`SELECT id, referrer_id FROM users WHERE id IN (${ph})`).bind(...chunk).all()
        for (const u of (rows.results || []) as any[]) {
          refMap.set(Number(u.id), u.referrer_id ? Number(u.referrer_id) : 0)
          if (u.referrer_id) candidateUids.add(Number(u.referrer_id))
        }
      }
      const missing = Array.from(candidateUids).filter(u => !refMap.has(u))
      for (let i = 0; i < missing.length; i += 100) {
        const chunk = missing.slice(i, i + 100)
        const ph = chunk.map(() => '?').join(',')
        const rows = await db.prepare(`SELECT id, referrer_id FROM users WHERE id IN (${ph})`).bind(...chunk).all()
        for (const u of (rows.results || []) as any[]) {
          refMap.set(Number(u.id), u.referrer_id ? Number(u.referrer_id) : 0)
        }
      }
    }

    const userStakeTotal = new Map<number, number>()
    {
      const uidsArr = Array.from(candidateUids)
      for (let i = 0; i < uidsArr.length; i += 100) {
        const chunk = uidsArr.slice(i, i + 100)
        const ph = chunk.map(() => '?').join(',')
        const rows = await db.prepare(`
          SELECT user_id, COALESCE(SUM(amount),0) AS total
          FROM staking WHERE user_id IN (${ph})
            AND status IN ('active','completed','capped')
          GROUP BY user_id
        `).bind(...chunk).all()
        for (const r of (rows.results || []) as any[]) {
          userStakeTotal.set(Number(r.user_id), Number(r.total))
        }
      }
    }
    const activeUserSet = new Set<number>()
    {
      const aRows = await db.prepare(`
        SELECT DISTINCT user_id FROM staking
        WHERE status IN ('active','capped','completed')
      `).all()
      for (const r of (aRows.results || []) as any[]) activeUserSet.add(Number(r.user_id))
    }

    // paidExcl: 현재 DB tx 합계 - PURGE 대상 tx 합계
    const userPaidExcl = new Map<number, number>()
    {
      const uidsArr = Array.from(userStakeTotal.keys())
      for (let i = 0; i < uidsArr.length; i += 100) {
        const chunk = uidsArr.slice(i, i + 100)
        const ph = chunk.map(() => '?').join(',')
        const rows = await db.prepare(`
          SELECT user_id, COALESCE(SUM(amount),0) AS total
          FROM transactions
          WHERE user_id IN (${ph}) AND coin_type='QKEY'
            AND type IN ('daily_qkey','referral_reward','direct_referral')
          GROUP BY user_id
        `).bind(...chunk).all()
        for (const r of (rows.results || []) as any[]) {
          userPaidExcl.set(Number(r.user_id), Math.max(0, Number(r.total)))
        }
      }
      // PURGE 대상 tx 합계 차감
      for (const t of txDetail) {
        const uid = Number(t.user_id)
        userPaidExcl.set(uid, Math.max(0, (userPaidExcl.get(uid) || 0) - Number(t.amount)))
      }
    }

    // Bottom-up 정산 (DR + L1 + L2 + Cap)
    const expectedDRs: { user_id: number, staking_id: number, amount: number }[] = []
    const expectedRRs: { referrer_id: number, referee_id: number, level: number, staking_id: number, original_amount: number, reward_amount: number }[] = []
    const userPaidRound = new Map<number, number>()
    const dr_capped = new Set<number>()
    const l1_capped = new Set<number>()
    const l2_capped = new Set<number>()
    const entryDateCount = { before_0506: 0, on_0506: 0, on_0507: 0, other: 0 }

    function tryGive(uid: number, requested: number): { granted: number, capped: boolean } {
      const stakeTotal = userStakeTotal.get(uid) || 0
      if (stakeTotal <= 0) return { granted: 0, capped: true }
      const target = stakeTotal * 2 * USD_TO_QKEY
      const paidExcl = userPaidExcl.get(uid) || 0
      const paidRound = userPaidRound.get(uid) || 0
      const current = paidExcl + paidRound
      if (current >= target) return { granted: 0, capped: true }
      const remaining = target - current
      const granted = Math.min(requested, Math.floor(remaining))
      if (granted > 0) userPaidRound.set(uid, paidRound + granted)
      return { granted, capped: granted < requested }
    }

    for (const s of stakingList) {
      const stakingId = Number(s.staking_id)
      const uid = Number(s.user_id)
      const amt = Number(s.amount) || 0
      const rate = Number(s.daily_rate) || 0
      const startKst = String(s.start_kst || '')
      if (startKst < '2026-05-06') entryDateCount.before_0506 += 1
      else if (startKst === '2026-05-06') entryDateCount.on_0506 += 1
      else if (startKst === '2026-05-07') entryDateCount.on_0507 += 1
      else entryDateCount.other += 1

      const ownReqQkey = Math.round(amt * rate * USD_TO_QKEY)
      if (ownReqQkey <= 0) continue

      const ownGrant = tryGive(uid, ownReqQkey)
      if (ownGrant.granted > 0) expectedDRs.push({ user_id: uid, staking_id: stakingId, amount: ownGrant.granted })
      if (ownGrant.capped && ownGrant.granted < ownReqQkey) dr_capped.add(uid)

      const l1Uid = refMap.get(uid) || 0
      if (l1Uid > 0 && activeUserSet.has(l1Uid)) {
        const l1Req = Math.round(ownReqQkey * 0.20)
        if (l1Req > 0) {
          const l1Grant = tryGive(l1Uid, l1Req)
          if (l1Grant.granted > 0) expectedRRs.push({
            referrer_id: l1Uid, referee_id: uid, level: 1, staking_id: stakingId,
            original_amount: ownReqQkey, reward_amount: l1Grant.granted,
          })
          if (l1Grant.capped && l1Grant.granted < l1Req) l1_capped.add(l1Uid)
        }
      }

      const l2Uid = l1Uid > 0 ? (refMap.get(l1Uid) || 0) : 0
      if (l2Uid > 0 && activeUserSet.has(l2Uid)) {
        const l2Req = Math.round(ownReqQkey * 0.10)
        if (l2Req > 0) {
          const l2Grant = tryGive(l2Uid, l2Req)
          if (l2Grant.granted > 0) expectedRRs.push({
            referrer_id: l2Uid, referee_id: uid, level: 2, staking_id: stakingId,
            original_amount: ownReqQkey, reward_amount: l2Grant.granted,
          })
          if (l2Grant.capped && l2Grant.granted < l2Req) l2_capped.add(l2Uid)
        }
      }
    }

    const drExpTotal = expectedDRs.reduce((s, r) => s + r.amount, 0)
    const l1ExpTotal = expectedRRs.filter(r => r.level === 1).reduce((s, r) => s + r.reward_amount, 0)
    const l2ExpTotal = expectedRRs.filter(r => r.level === 2).reduce((s, r) => s + r.reward_amount, 0)
    const grandInsert = drExpTotal + l1ExpTotal + l2ExpTotal
    const netBalanceDelta = grandInsert - purgeTxTotal

    // net user delta
    const netUserDelta = new Map<number, number>()
    for (const [uid, d] of purgeBalanceDelta.entries()) {
      netUserDelta.set(uid, (netUserDelta.get(uid) || 0) + d)
    }
    for (const dr of expectedDRs) {
      netUserDelta.set(dr.user_id, (netUserDelta.get(dr.user_id) || 0) + dr.amount)
    }
    for (const rr of expectedRRs) {
      netUserDelta.set(rr.referrer_id, (netUserDelta.get(rr.referrer_id) || 0) + rr.reward_amount)
    }

    const summary = {
      config: { reward_date: TARGET_REWARD_DATE, paid_date: TARGET_PAID_DATE },
      purge: {
        dr_rows_to_delete: drIds.length,
        rr_rows_to_delete: rrIds.length,
        tx_rows_to_delete: txIds.length,
        tx_total_to_subtract: purgeTxTotal,
        affected_users: purgeBalanceDelta.size,
        dr_reward_dates_seen: drDistinctRewardDates,
        rr_reward_dates_seen: rrDistinctRewardDates,
      },
      recalc: {
        staking_count: stakingList.length,
        entry_date_breakdown: entryDateCount,
        dr_expected: expectedDRs.length, dr_total: drExpTotal,
        l1_expected: expectedRRs.filter(r => r.level === 1).length, l1_total: l1ExpTotal,
        l2_expected: expectedRRs.filter(r => r.level === 2).length, l2_total: l2ExpTotal,
        tx_to_insert: expectedDRs.length + expectedRRs.length,
        gross_total_to_add: grandInsert,
        cap_info: { dr_capped: dr_capped.size, l1_capped: l1_capped.size, l2_capped: l2_capped.size },
      },
      net: {
        users_affected: netUserDelta.size,
        net_balance_delta_total: netBalanceDelta,
      },
    }

    // ═══════════════ DRY-RUN ═══════════════
    if (mode === 'DRY_RUN') {
      const userIds = Array.from(netUserDelta.keys())
      const userSim: any[] = []
      for (let i = 0; i < userIds.length; i += 100) {
        const chunk = userIds.slice(i, i + 100)
        const ph = chunk.map(() => '?').join(',')
        const rows = await db.prepare(`SELECT id, name, email, qkey_balance FROM users WHERE id IN (${ph})`).bind(...chunk).all()
        for (const u of (rows.results || []) as any[]) {
          const delta = netUserDelta.get(Number(u.id)) || 0
          userSim.push({
            user_id: Number(u.id), name: u.name, email: u.email,
            current_balance: Number(u.qkey_balance),
            net_delta: delta,
            post_balance: Number(u.qkey_balance) + delta,
            will_go_negative: (Number(u.qkey_balance) + delta) < 0,
          })
        }
      }
      const negAfter = userSim.filter(u => u.will_go_negative)

      // tx 패턴 분석 (영구룰 위반 흔적)
      const txByMinute: Record<string, { cnt: number, total: number }> = {}
      for (const t of txDetail) {
        const k = String(t.kst_at || '').slice(0, 16)
        if (!txByMinute[k]) txByMinute[k] = { cnt: 0, total: 0 }
        txByMinute[k].cnt += 1
        txByMinute[k].total += Number(t.amount)
      }
      const txByMinuteTop = Object.entries(txByMinute)
        .sort((a, b) => b[1].cnt - a[1].cnt)
        .slice(0, 15)
        .map(([k, v]) => ({ kst_minute: k, ...v }))

      return c.json({
        ok: true,
        mode: 'DRY_RUN',
        action: 'recalc-may-seven',
        summary,
        protect_baseline: protectBaseline,
        purge_tx_kst_distribution: txByMinuteTop,
        balance_sim_top20: userSim.sort((a, b) => Math.abs(b.net_delta) - Math.abs(a.net_delta)).slice(0, 20),
        negative_after: { count: negAfter.length, samples: negAfter.slice(0, 10) },
        next_action: 'POST + confirm=GO 보내시면 PURGE + RECALC + balance 조정 1번에 실행',
        duration_ms: Date.now() - t0,
      })
    }

    // ═══════════════ EXEC ═══════════════
    // (a) balance 차감
    let balanceUpdated = 0
    {
      const balEntries = Array.from(purgeBalanceDelta.entries())
      for (let i = 0; i < balEntries.length; i += CHUNK) {
        const chunk = balEntries.slice(i, i + CHUNK)
        const stmts = chunk.map(([uid, delta]) =>
          db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(delta, uid)
        )
        if (stmts.length > 0) await db.batch(stmts)
        balanceUpdated += chunk.length
      }
    }

    // (b) tx DELETE
    let txPurgedCnt = 0
    for (let i = 0; i < txIds.length; i += CHUNK) {
      const chunk = txIds.slice(i, i + CHUNK)
      const ph = chunk.map(() => '?').join(',')
      const r = await db.prepare(`DELETE FROM transactions WHERE id IN (${ph})`).bind(...chunk).run()
      txPurgedCnt += (r as any)?.meta?.changes || 0
    }

    // (c) RR DELETE — id 기반 (reward_date 5/7 + paid_date 5/8 통합)
    let rrPurgedCnt = 0
    for (let i = 0; i < rrIds.length; i += CHUNK) {
      const chunk = rrIds.slice(i, i + CHUNK)
      const ph = chunk.map(() => '?').join(',')
      const r = await db.prepare(`DELETE FROM referral_rewards WHERE id IN (${ph})`).bind(...chunk).run()
      rrPurgedCnt += (r as any)?.meta?.changes || 0
    }

    // (d) DR DELETE
    let drPurgedCnt = 0
    for (let i = 0; i < drIds.length; i += CHUNK) {
      const chunk = drIds.slice(i, i + CHUNK)
      const ph = chunk.map(() => '?').join(',')
      const r = await db.prepare(`DELETE FROM daily_rewards WHERE id IN (${ph})`).bind(...chunk).run()
      drPurgedCnt += (r as any)?.meta?.changes || 0
    }

    // (e) DR INSERT
    // PERMANENT_RULE #regular-time (2026-05-19): KST 08:00 = UTC (paid_date - 1day) 23:00
    const _prevKstStr_e = kstDateStr(new Date(new Date(TARGET_PAID_DATE + 'T00:00:00+09:00').getTime() - 24 * 60 * 60 * 1000))
    const drCreatedAt = `${_prevKstStr_e} 23:00:00`  // KST 08:00:00 of paid_date
    const rrCreatedAt = `${_prevKstStr_e} 23:00:01`  // KST 08:00:01 of paid_date

    for (let i = 0; i < expectedDRs.length; i += CHUNK) {
      const chunk = expectedDRs.slice(i, i + CHUNK)
      const stmts = chunk.map(dr =>
        db.prepare(`
          INSERT INTO daily_rewards (user_id, staking_id, usdt_amount, reward_date, paid_date, created_at)
          VALUES (?, ?, ?, ?, ?, ?)
        `).bind(dr.user_id, dr.staking_id, dr.amount, TARGET_REWARD_DATE, TARGET_PAID_DATE, drCreatedAt)
      )
      if (stmts.length > 0) await db.batch(stmts)
    }

    // DR id 매핑
    const drRowsAfter = await db.prepare(`
      SELECT id, user_id, staking_id FROM daily_rewards
      WHERE reward_date = ? AND paid_date = ?
    `).bind(TARGET_REWARD_DATE, TARGET_PAID_DATE).all()
    const drIdMap = new Map<string, number>()
    for (const r of (drRowsAfter.results || []) as any[]) {
      drIdMap.set(`${r.user_id}|${r.staking_id}`, Number(r.id))
    }

    // (f) DR tx INSERT
    const drTxStmts = expectedDRs.map(dr => {
      const drId = drIdMap.get(`${dr.user_id}|${dr.staking_id}`) ?? null
      return db.prepare(`
        INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id, created_at)
        VALUES (?, 'daily_qkey', 'QKEY', ?, ?, ?, ?)
      `).bind(dr.user_id, dr.amount, '일일 배당 (QKEY)', drId, drCreatedAt)
    })
    for (let i = 0; i < drTxStmts.length; i += CHUNK) {
      const c2 = drTxStmts.slice(i, i + CHUNK)
      if (c2.length > 0) await db.batch(c2)
    }

    // (g) RR INSERT
    for (let i = 0; i < expectedRRs.length; i += CHUNK) {
      const chunk = expectedRRs.slice(i, i + CHUNK)
      const stmts = chunk.map(rr =>
        db.prepare(`
          INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, staking_id, created_at)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        `).bind(rr.referrer_id, rr.referee_id, rr.level, rr.original_amount, rr.reward_amount, TARGET_REWARD_DATE, TARGET_PAID_DATE, rr.staking_id, drCreatedAt)
      )
      if (stmts.length > 0) await db.batch(stmts)
    }

    // RR id 매핑
    const rrRowsAfter = await db.prepare(`
      SELECT id, referrer_id, referee_id, level, staking_id FROM referral_rewards
      WHERE reward_date = ? AND paid_date = ?
    `).bind(TARGET_REWARD_DATE, TARGET_PAID_DATE).all()
    const rrIdMap = new Map<string, number>()
    for (const r of (rrRowsAfter.results || []) as any[]) {
      rrIdMap.set(`${r.referrer_id}|${r.referee_id}|${r.level}|${r.staking_id}`, Number(r.id))
    }

    // (h) RR tx INSERT
    const rrTxStmts = expectedRRs.map(rr => {
      const rrId = rrIdMap.get(`${rr.referrer_id}|${rr.referee_id}|${rr.level}|${rr.staking_id}`) ?? null
      const desc = rr.level === 1 ? '추천 보너스 (Level 1)' : '추천 보너스 (Level 2)'
      return db.prepare(`
        INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id, created_at)
        VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?, ?)
      `).bind(rr.referrer_id, rr.reward_amount, desc, rrId, rrCreatedAt)
    })
    for (let i = 0; i < rrTxStmts.length; i += CHUNK) {
      const c2 = rrTxStmts.slice(i, i + CHUNK)
      if (c2.length > 0) await db.batch(c2)
    }

    // (i) balance 증가
    {
      const addDelta = new Map<number, number>()
      for (const dr of expectedDRs) addDelta.set(dr.user_id, (addDelta.get(dr.user_id) || 0) + dr.amount)
      for (const rr of expectedRRs) addDelta.set(rr.referrer_id, (addDelta.get(rr.referrer_id) || 0) + rr.reward_amount)
      const balEntries = Array.from(addDelta.entries())
      for (let i = 0; i < balEntries.length; i += CHUNK) {
        const chunk = balEntries.slice(i, i + CHUNK)
        const stmts = chunk.map(([uid, delta]) =>
          db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(delta, uid)
        )
        if (stmts.length > 0) await db.batch(stmts)
        balanceUpdated += chunk.length
      }
    }

    // POST-CHECK
    const drNew = await db.prepare(`SELECT COUNT(*) AS cnt, COALESCE(SUM(usdt_amount),0) AS total FROM daily_rewards WHERE reward_date = ?`).bind(TARGET_REWARD_DATE).first() as any
    const rrNew = await db.prepare(`SELECT COUNT(*) AS cnt, COALESCE(SUM(reward_amount),0) AS total FROM referral_rewards WHERE reward_date = ?`).bind(TARGET_REWARD_DATE).first() as any

    // legacy paid_date=5/8 잡것 잔여 확인
    const drLegacyRemain = await db.prepare(`SELECT COUNT(*) AS cnt FROM daily_rewards WHERE paid_date = ? AND reward_date != ?`).bind(TARGET_PAID_DATE, TARGET_REWARD_DATE).first() as any
    const rrLegacyRemain = await db.prepare(`SELECT COUNT(*) AS cnt FROM referral_rewards WHERE paid_date = ? AND reward_date != ?`).bind(TARGET_PAID_DATE, TARGET_REWARD_DATE).first() as any

    // PROTECT AFTER
    const protectAfter: any[] = []
    for (const pd of PROTECTED_REWARD_DATES) {
      const drB = await db.prepare(`SELECT COUNT(*) AS cnt, COALESCE(SUM(usdt_amount),0) AS total FROM daily_rewards WHERE reward_date = ?`).bind(pd).first() as any
      const rrB = await db.prepare(`SELECT COUNT(*) AS cnt, COALESCE(SUM(reward_amount),0) AS total FROM referral_rewards WHERE reward_date = ?`).bind(pd).first() as any
      protectAfter.push({
        reward_date: pd,
        dr_count: Number(drB?.cnt || 0), dr_total: Number(drB?.total || 0),
        rr_count: Number(rrB?.cnt || 0), rr_total: Number(rrB?.total || 0),
      })
    }
    const protectIntact = JSON.stringify(protectBaseline) === JSON.stringify(protectAfter)

    const drMatch = Number(drNew?.cnt || 0) === expectedDRs.length
    const rrMatch = Number(rrNew?.cnt || 0) === expectedRRs.length
    const legacyClean = Number(drLegacyRemain?.cnt || 0) === 0 && Number(rrLegacyRemain?.cnt || 0) === 0
    const allOk = protectIntact && drMatch && rrMatch && legacyClean

    return c.json({
      ok: allOk,
      mode: 'EXEC',
      action: 'recalc-may-seven',
      summary,
      exec_result: {
        purge: { dr_deleted: drPurgedCnt, rr_deleted: rrPurgedCnt, tx_deleted: txPurgedCnt },
        insert: { dr_inserted: expectedDRs.length, rr_inserted: expectedRRs.length, tx_inserted: expectedDRs.length + expectedRRs.length },
        balance_updates: balanceUpdated,
        net_balance_delta_total: netBalanceDelta,
      },
      post_check: {
        new_5_7_count: {
          dr: Number(drNew?.cnt || 0), dr_total: Number(drNew?.total || 0),
          rr: Number(rrNew?.cnt || 0), rr_total: Number(rrNew?.total || 0),
          dr_match: drMatch, rr_match: rrMatch,
        },
        legacy_5_8_remain: {
          dr: Number(drLegacyRemain?.cnt || 0), rr: Number(rrLegacyRemain?.cnt || 0), clean: legacyClean,
        },
        protect: { baseline: protectBaseline, after: protectAfter, intact: protectIntact },
        verdict: allOk ? '✅ 영구룰 적합 완료' : '🚨 검증 실패 — 즉시 STOP & 보고',
      },
      duration_ms: Date.now() - t0,
    })
  } catch (error) {
    return c.json({ error: String(error), duration_ms: Date.now() - t0 }, 500)
  }
}

app.get('/api/diag/recalc-may-seven', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  return diagRecalcMaySeven(c, 'DRY_RUN')
})

app.post('/api/diag/recalc-may-seven', async (c) => {
  const key = c.req.query('key') || ''
  if (key !== ADMIN_PW) return c.json({ error: 'unauthorized' }, 401)
  const confirm = c.req.query('confirm') || ''
  if (confirm !== 'GO') return c.json({ error: 'confirm=GO 필요 (실 변경 게이트)' }, 400)
  return diagRecalcMaySeven(c, 'EXEC')
})

// ============================================================================
// recalc-may-six: 사장님 명령 (2026-05-18 / 깊은 밤)
//
//   "5월 6일자 확정액을 5월 7일날 지급하는것을 내 영구룰로 바텀업으로 정산해서 처리하라!"
//
//   영구룰 위반 청산 + 재정산:
//     - PURGE: reward_date='2026-05-06' AND paid_date='2026-05-07' 의 모든 항목
//       + paid_date='2026-05-07' 의 모든 tx (DR/RR id 매칭 + 패턴 매칭)
//     - RECALC: reward_date='2026-05-06' 영구룰 정확 (DR + L1 + L2 + 200% Cap)
//     - PAID: paid_date='2026-05-07', created_at = '2026-05-07 06:15:00 UTC' (KST 15:15)
//
//   절대 보호 (BEFORE/AFTER snapshot 비교):
//     - reward_date IN ('5-08','5-09','5-10','5-11','5-12','5-13','5-14','5-15','5-18')
//
//   엔드포인트:
//     GET  /api/diag/recalc-may-six?key=ADMIN_PW          → DRY_RUN
//     POST /api/diag/recalc-may-six?key=ADMIN_PW&confirm=GO → EXEC
// ============================================================================
async function diagRecalcMaySix(c: any, mode: 'DRY_RUN' | 'EXEC') {
  const t0 = Date.now()
  try {
    const db = c.env.DB
    const USD_TO_QKEY = 150

    // ★ 하드코딩 ★
    const TARGET_REWARD_DATE = '2026-05-06'
    const TARGET_PAID_DATE = '2026-05-07'
    const PROTECTED_REWARD_DATES = [
      '2026-05-08','2026-05-09','2026-05-10','2026-05-11',
      '2026-05-12','2026-05-13','2026-05-14','2026-05-15','2026-05-18',
    ]

    // ─── PROTECT BASELINE (BEFORE) ───
    const protectBaseline: any[] = []
    for (const pd of PROTECTED_REWARD_DATES) {
      const drB = await db.prepare(`SELECT COUNT(*) AS cnt, COALESCE(SUM(usdt_amount),0) AS total FROM daily_rewards WHERE reward_date = ?`).bind(pd).first() as any
      const rrB = await db.prepare(`SELECT COUNT(*) AS cnt, COALESCE(SUM(reward_amount),0) AS total FROM referral_rewards WHERE reward_date = ?`).bind(pd).first() as any
      protectBaseline.push({
        reward_date: pd,
        dr_count: Number(drB?.cnt || 0), dr_total: Number(drB?.total || 0),
        rr_count: Number(rrB?.cnt || 0), rr_total: Number(rrB?.total || 0),
      })
    }

    // ═══════════════════════════════════════════════
    // PHASE 1: PURGE 대상 수집 (3 종류)
    //   (a) DR/RR rows: reward_date=2026-05-07 인 모든 row
    //   (b) DR/RR rows: paid_date=2026-05-08 인 모든 row (혹시 reward_date 가 다른 것 있을 수 있음)
    //   (c) tx: paid_date=2026-05-08 인 DR/RR 의 ref_id 매칭 + paid_date 가 KST 5/8 인 daily_qkey/referral_reward/direct_referral
    // ═══════════════════════════════════════════════

    // (a) reward_date=5/7 의 DR/RR
    const drByRewardDate = (await db.prepare(`
      SELECT id, user_id, staking_id, usdt_amount, reward_date, paid_date
      FROM daily_rewards WHERE reward_date = ?
    `).bind(TARGET_REWARD_DATE).all()).results as any[] || []

    const rrByRewardDate = (await db.prepare(`
      SELECT id, referrer_id, referee_id, level, staking_id, reward_amount, reward_date, paid_date
      FROM referral_rewards WHERE reward_date = ?
    `).bind(TARGET_REWARD_DATE).all()).results as any[] || []

    // (b) paid_date=5/8 의 DR/RR (혹시 reward_date 다른 잡것 있는지)
    const drByPaidDate = (await db.prepare(`
      SELECT id, user_id, staking_id, usdt_amount, reward_date, paid_date
      FROM daily_rewards WHERE paid_date = ?
    `).bind(TARGET_PAID_DATE).all()).results as any[] || []

    const rrByPaidDate = (await db.prepare(`
      SELECT id, referrer_id, referee_id, level, staking_id, reward_amount, reward_date, paid_date
      FROM referral_rewards WHERE paid_date = ?
    `).bind(TARGET_PAID_DATE).all()).results as any[] || []

    // PURGE 대상 DR/RR id 통합 (중복 제거)
    const drIdSet = new Set<number>()
    for (const r of drByRewardDate) drIdSet.add(Number(r.id))
    for (const r of drByPaidDate) drIdSet.add(Number(r.id))
    const rrIdSet = new Set<number>()
    for (const r of rrByRewardDate) rrIdSet.add(Number(r.id))
    for (const r of rrByPaidDate) rrIdSet.add(Number(r.id))
    const drIds = Array.from(drIdSet)
    const rrIds = Array.from(rrIdSet)

    // 안전 검사: PURGE 대상의 reward_date 가 모두 5/7 이거나 PROTECT 외인지 확인
    // (만약 paid_date=5/8 인데 reward_date 가 5/11 같은 PROTECT 날짜면 STOP)
    const drToPurgeAll = [...drByRewardDate, ...drByPaidDate]
    const rrToPurgeAll = [...rrByRewardDate, ...rrByPaidDate]
    const drDistinctRewardDates = Array.from(new Set(drToPurgeAll.map(r => String(r.reward_date))))
    const rrDistinctRewardDates = Array.from(new Set(rrToPurgeAll.map(r => String(r.reward_date))))
    const dangerousDr = drDistinctRewardDates.filter(d => PROTECTED_REWARD_DATES.includes(d))
    const dangerousRr = rrDistinctRewardDates.filter(d => PROTECTED_REWARD_DATES.includes(d))
    if (dangerousDr.length > 0 || dangerousRr.length > 0) {
      return c.json({
        ok: false,
        error: '🚨 SAFETY STOP — PURGE 대상에 PROTECTED reward_date 포함됨',
        dangerous_dr_reward_dates: dangerousDr,
        dangerous_rr_reward_dates: dangerousRr,
        hint: '이건 다른 날 reward 가 잘못 5/8 에 paid 된 사고. 사장님 명령 필요.',
      }, 400)
    }

    // (c) tx 수집 — 3가지 경로
    //   c1: paid_date=5/8 의 DR id 에 매칭되는 daily_qkey tx
    //   c2: paid_date=5/8 의 RR id 에 매칭되는 referral_reward / direct_referral tx
    //   c3: KST 5/8 에 발생한 모든 daily_qkey/referral_reward/direct_referral tx (잡것)
    const CHUNK = 80
    const txIdSet = new Set<number>()
    const txDetail: any[] = []

    // c1
    if (drIds.length > 0) {
      for (let i = 0; i < drIds.length; i += CHUNK) {
        const chunk = drIds.slice(i, i + CHUNK)
        const ph = chunk.map(() => '?').join(',')
        const rows = await db.prepare(`
          SELECT id, user_id, type, amount, ref_id, description,
                 datetime(created_at,'+9 hours') AS kst_at
          FROM transactions
          WHERE type='daily_qkey' AND coin_type='QKEY' AND ref_id IN (${ph})
        `).bind(...chunk).all()
        for (const t of (rows.results || []) as any[]) {
          if (!txIdSet.has(Number(t.id))) { txIdSet.add(Number(t.id)); txDetail.push(t) }
        }
      }
    }

    // c2
    if (rrIds.length > 0) {
      for (let i = 0; i < rrIds.length; i += CHUNK) {
        const chunk = rrIds.slice(i, i + CHUNK)
        const ph = chunk.map(() => '?').join(',')
        const rows = await db.prepare(`
          SELECT id, user_id, type, amount, ref_id, description,
                 datetime(created_at,'+9 hours') AS kst_at
          FROM transactions
          WHERE type IN ('referral_reward','direct_referral') AND coin_type='QKEY' AND ref_id IN (${ph})
        `).bind(...chunk).all()
        for (const t of (rows.results || []) as any[]) {
          if (!txIdSet.has(Number(t.id))) { txIdSet.add(Number(t.id)); txDetail.push(t) }
        }
      }
    }

    // c3 — KST 5/8 의 모든 reward tx (DR/RR 매칭 없는 잡것도 포함 — ref_id 가 잘못된 사고분)
    {
      const rows = await db.prepare(`
        SELECT id, user_id, type, amount, ref_id, description,
               datetime(created_at,'+9 hours') AS kst_at
        FROM transactions
        WHERE coin_type='QKEY'
          AND type IN ('daily_qkey','referral_reward','direct_referral')
          AND date(created_at,'+9 hours') = ?
      `).bind(TARGET_PAID_DATE).all()
      for (const t of (rows.results || []) as any[]) {
        if (!txIdSet.has(Number(t.id))) { txIdSet.add(Number(t.id)); txDetail.push(t) }
      }
    }

    const txIds = Array.from(txIdSet)

    // PURGE balance delta (음수)
    const purgeBalanceDelta = new Map<number, number>()
    let purgeTxTotal = 0
    for (const t of txDetail) {
      const uid = Number(t.user_id), amt = Number(t.amount)
      purgeTxTotal += amt
      purgeBalanceDelta.set(uid, (purgeBalanceDelta.get(uid) || 0) - amt)
    }

    // ═══════════════════════════════════════════════
    // PHASE 2: RECALC EXPECTED 계산 (reward_date = 5/6 만)
    // ═══════════════════════════════════════════════

    // staking 조회: 5/6 발생 대상 (영구룰 #익일리워드: 5/5 이전 진입자만)
    const stakingRows = await db.prepare(`
      SELECT s.id AS staking_id, s.user_id, s.amount, s.daily_rate, s.period_days,
             date(s.start_date,'+9 hours') AS start_kst,
             date(s.end_date,'+9 hours') AS end_kst,
             s.status,
             u.referrer_id
      FROM staking s
      JOIN users u ON u.id = s.user_id
      WHERE s.status IN ('active','capped','completed')
        AND date(s.start_date,'+9 hours') < ?
        AND date(s.end_date,'+9 hours') >= ?
      ORDER BY s.id ASC
    `).bind(TARGET_REWARD_DATE, TARGET_REWARD_DATE).all()
    const stakingList = (stakingRows.results || []) as any[]

    // refMap + stakeTotal + activeUserSet
    const candidateUids = new Set<number>()
    for (const s of stakingList) {
      candidateUids.add(Number(s.user_id))
      if (s.referrer_id) candidateUids.add(Number(s.referrer_id))
    }
    const refMap = new Map<number, number>()
    {
      const uidsArr = Array.from(candidateUids)
      for (let i = 0; i < uidsArr.length; i += 100) {
        const chunk = uidsArr.slice(i, i + 100)
        const ph = chunk.map(() => '?').join(',')
        const rows = await db.prepare(`SELECT id, referrer_id FROM users WHERE id IN (${ph})`).bind(...chunk).all()
        for (const u of (rows.results || []) as any[]) {
          refMap.set(Number(u.id), u.referrer_id ? Number(u.referrer_id) : 0)
          if (u.referrer_id) candidateUids.add(Number(u.referrer_id))
        }
      }
      const missing = Array.from(candidateUids).filter(u => !refMap.has(u))
      for (let i = 0; i < missing.length; i += 100) {
        const chunk = missing.slice(i, i + 100)
        const ph = chunk.map(() => '?').join(',')
        const rows = await db.prepare(`SELECT id, referrer_id FROM users WHERE id IN (${ph})`).bind(...chunk).all()
        for (const u of (rows.results || []) as any[]) {
          refMap.set(Number(u.id), u.referrer_id ? Number(u.referrer_id) : 0)
        }
      }
    }

    const userStakeTotal = new Map<number, number>()
    {
      const uidsArr = Array.from(candidateUids)
      for (let i = 0; i < uidsArr.length; i += 100) {
        const chunk = uidsArr.slice(i, i + 100)
        const ph = chunk.map(() => '?').join(',')
        const rows = await db.prepare(`
          SELECT user_id, COALESCE(SUM(amount),0) AS total
          FROM staking WHERE user_id IN (${ph})
            AND status IN ('active','completed','capped')
          GROUP BY user_id
        `).bind(...chunk).all()
        for (const r of (rows.results || []) as any[]) {
          userStakeTotal.set(Number(r.user_id), Number(r.total))
        }
      }
    }
    const activeUserSet = new Set<number>()
    {
      const aRows = await db.prepare(`
        SELECT DISTINCT user_id FROM staking
        WHERE status IN ('active','capped','completed')
      `).all()
      for (const r of (aRows.results || []) as any[]) activeUserSet.add(Number(r.user_id))
    }

    // paidExcl: 현재 DB tx 합계 - PURGE 대상 tx 합계
    const userPaidExcl = new Map<number, number>()
    {
      const uidsArr = Array.from(userStakeTotal.keys())
      for (let i = 0; i < uidsArr.length; i += 100) {
        const chunk = uidsArr.slice(i, i + 100)
        const ph = chunk.map(() => '?').join(',')
        const rows = await db.prepare(`
          SELECT user_id, COALESCE(SUM(amount),0) AS total
          FROM transactions
          WHERE user_id IN (${ph}) AND coin_type='QKEY'
            AND type IN ('daily_qkey','referral_reward','direct_referral')
          GROUP BY user_id
        `).bind(...chunk).all()
        for (const r of (rows.results || []) as any[]) {
          userPaidExcl.set(Number(r.user_id), Math.max(0, Number(r.total)))
        }
      }
      // PURGE 대상 tx 합계 차감
      for (const t of txDetail) {
        const uid = Number(t.user_id)
        userPaidExcl.set(uid, Math.max(0, (userPaidExcl.get(uid) || 0) - Number(t.amount)))
      }
    }

    // Bottom-up 정산 (DR + L1 + L2 + Cap)
    const expectedDRs: { user_id: number, staking_id: number, amount: number }[] = []
    const expectedRRs: { referrer_id: number, referee_id: number, level: number, staking_id: number, original_amount: number, reward_amount: number }[] = []
    const userPaidRound = new Map<number, number>()
    const dr_capped = new Set<number>()
    const l1_capped = new Set<number>()
    const l2_capped = new Set<number>()
    const entryDateCount = { before_0506: 0, on_0506: 0, on_0507: 0, other: 0 }

    function tryGive(uid: number, requested: number): { granted: number, capped: boolean } {
      const stakeTotal = userStakeTotal.get(uid) || 0
      if (stakeTotal <= 0) return { granted: 0, capped: true }
      const target = stakeTotal * 2 * USD_TO_QKEY
      const paidExcl = userPaidExcl.get(uid) || 0
      const paidRound = userPaidRound.get(uid) || 0
      const current = paidExcl + paidRound
      if (current >= target) return { granted: 0, capped: true }
      const remaining = target - current
      const granted = Math.min(requested, Math.floor(remaining))
      if (granted > 0) userPaidRound.set(uid, paidRound + granted)
      return { granted, capped: granted < requested }
    }

    for (const s of stakingList) {
      const stakingId = Number(s.staking_id)
      const uid = Number(s.user_id)
      const amt = Number(s.amount) || 0
      const rate = Number(s.daily_rate) || 0
      const startKst = String(s.start_kst || '')
      if (startKst < '2026-05-06') entryDateCount.before_0506 += 1
      else if (startKst === '2026-05-06') entryDateCount.on_0506 += 1
      else if (startKst === '2026-05-07') entryDateCount.on_0507 += 1
      else entryDateCount.other += 1

      const ownReqQkey = Math.round(amt * rate * USD_TO_QKEY)
      if (ownReqQkey <= 0) continue

      const ownGrant = tryGive(uid, ownReqQkey)
      if (ownGrant.granted > 0) expectedDRs.push({ user_id: uid, staking_id: stakingId, amount: ownGrant.granted })
      if (ownGrant.capped && ownGrant.granted < ownReqQkey) dr_capped.add(uid)

      const l1Uid = refMap.get(uid) || 0
      if (l1Uid > 0 && activeUserSet.has(l1Uid)) {
        const l1Req = Math.round(ownReqQkey * 0.20)
        if (l1Req > 0) {
          const l1Grant = tryGive(l1Uid, l1Req)
          if (l1Grant.granted > 0) expectedRRs.push({
            referrer_id: l1Uid, referee_id: uid, level: 1, staking_id: stakingId,
            original_amount: ownReqQkey, reward_amount: l1Grant.granted,
          })
          if (l1Grant.capped && l1Grant.granted < l1Req) l1_capped.add(l1Uid)
        }
      }

      const l2Uid = l1Uid > 0 ? (refMap.get(l1Uid) || 0) : 0
      if (l2Uid > 0 && activeUserSet.has(l2Uid)) {
        const l2Req = Math.round(ownReqQkey * 0.10)
        if (l2Req > 0) {
          const l2Grant = tryGive(l2Uid, l2Req)
          if (l2Grant.granted > 0) expectedRRs.push({
            referrer_id: l2Uid, referee_id: uid, level: 2, staking_id: stakingId,
            original_amount: ownReqQkey, reward_amount: l2Grant.granted,
          })
          if (l2Grant.capped && l2Grant.granted < l2Req) l2_capped.add(l2Uid)
        }
      }
    }

    const drExpTotal = expectedDRs.reduce((s, r) => s + r.amount, 0)
    const l1ExpTotal = expectedRRs.filter(r => r.level === 1).reduce((s, r) => s + r.reward_amount, 0)
    const l2ExpTotal = expectedRRs.filter(r => r.level === 2).reduce((s, r) => s + r.reward_amount, 0)
    const grandInsert = drExpTotal + l1ExpTotal + l2ExpTotal
    const netBalanceDelta = grandInsert - purgeTxTotal

    // net user delta
    const netUserDelta = new Map<number, number>()
    for (const [uid, d] of purgeBalanceDelta.entries()) {
      netUserDelta.set(uid, (netUserDelta.get(uid) || 0) + d)
    }
    for (const dr of expectedDRs) {
      netUserDelta.set(dr.user_id, (netUserDelta.get(dr.user_id) || 0) + dr.amount)
    }
    for (const rr of expectedRRs) {
      netUserDelta.set(rr.referrer_id, (netUserDelta.get(rr.referrer_id) || 0) + rr.reward_amount)
    }

    const summary = {
      config: { reward_date: TARGET_REWARD_DATE, paid_date: TARGET_PAID_DATE },
      purge: {
        dr_rows_to_delete: drIds.length,
        rr_rows_to_delete: rrIds.length,
        tx_rows_to_delete: txIds.length,
        tx_total_to_subtract: purgeTxTotal,
        affected_users: purgeBalanceDelta.size,
        dr_reward_dates_seen: drDistinctRewardDates,
        rr_reward_dates_seen: rrDistinctRewardDates,
      },
      recalc: {
        staking_count: stakingList.length,
        entry_date_breakdown: entryDateCount,
        dr_expected: expectedDRs.length, dr_total: drExpTotal,
        l1_expected: expectedRRs.filter(r => r.level === 1).length, l1_total: l1ExpTotal,
        l2_expected: expectedRRs.filter(r => r.level === 2).length, l2_total: l2ExpTotal,
        tx_to_insert: expectedDRs.length + expectedRRs.length,
        gross_total_to_add: grandInsert,
        cap_info: { dr_capped: dr_capped.size, l1_capped: l1_capped.size, l2_capped: l2_capped.size },
      },
      net: {
        users_affected: netUserDelta.size,
        net_balance_delta_total: netBalanceDelta,
      },
    }

    // ═══════════════ DRY-RUN ═══════════════
    if (mode === 'DRY_RUN') {
      const userIds = Array.from(netUserDelta.keys())
      const userSim: any[] = []
      for (let i = 0; i < userIds.length; i += 100) {
        const chunk = userIds.slice(i, i + 100)
        const ph = chunk.map(() => '?').join(',')
        const rows = await db.prepare(`SELECT id, name, email, qkey_balance FROM users WHERE id IN (${ph})`).bind(...chunk).all()
        for (const u of (rows.results || []) as any[]) {
          const delta = netUserDelta.get(Number(u.id)) || 0
          userSim.push({
            user_id: Number(u.id), name: u.name, email: u.email,
            current_balance: Number(u.qkey_balance),
            net_delta: delta,
            post_balance: Number(u.qkey_balance) + delta,
            will_go_negative: (Number(u.qkey_balance) + delta) < 0,
          })
        }
      }
      const negAfter = userSim.filter(u => u.will_go_negative)

      // tx 패턴 분석 (영구룰 위반 흔적)
      const txByMinute: Record<string, { cnt: number, total: number }> = {}
      for (const t of txDetail) {
        const k = String(t.kst_at || '').slice(0, 16)
        if (!txByMinute[k]) txByMinute[k] = { cnt: 0, total: 0 }
        txByMinute[k].cnt += 1
        txByMinute[k].total += Number(t.amount)
      }
      const txByMinuteTop = Object.entries(txByMinute)
        .sort((a, b) => b[1].cnt - a[1].cnt)
        .slice(0, 15)
        .map(([k, v]) => ({ kst_minute: k, ...v }))

      return c.json({
        ok: true,
        mode: 'DRY_RUN',
        action: 'recalc-may-six',
        summary,
        protect_baseline: protectBaseline,
        purge_tx_kst_distribution: txByMinuteTop,
        balance_sim_top20: userSim.sort((a, b) => Math.abs(b.net_delta) - Math.abs(a.net_delta)).slice(0, 20),
        negative_after: { count: negAfter.length, samples: negAfter.slice(0, 10) },
        next_action: 'POST + confirm=GO 보내시면 PURGE + RECALC + balance 조정 1번에 실행',
        duration_ms: Date.now() - t0,
      })
    }

    // ═══════════════ EXEC ═══════════════
    // (a) balance 차감
    let balanceUpdated = 0
    {
      const balEntries = Array.from(purgeBalanceDelta.entries())
      for (let i = 0; i < balEntries.length; i += CHUNK) {
        const chunk = balEntries.slice(i, i + CHUNK)
        const stmts = chunk.map(([uid, delta]) =>
          db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(delta, uid)
        )
        if (stmts.length > 0) await db.batch(stmts)
        balanceUpdated += chunk.length
      }
    }

    // (b) tx DELETE
    let txPurgedCnt = 0
    for (let i = 0; i < txIds.length; i += CHUNK) {
      const chunk = txIds.slice(i, i + CHUNK)
      const ph = chunk.map(() => '?').join(',')
      const r = await db.prepare(`DELETE FROM transactions WHERE id IN (${ph})`).bind(...chunk).run()
      txPurgedCnt += (r as any)?.meta?.changes || 0
    }

    // (c) RR DELETE — id 기반 (reward_date 5/7 + paid_date 5/8 통합)
    let rrPurgedCnt = 0
    for (let i = 0; i < rrIds.length; i += CHUNK) {
      const chunk = rrIds.slice(i, i + CHUNK)
      const ph = chunk.map(() => '?').join(',')
      const r = await db.prepare(`DELETE FROM referral_rewards WHERE id IN (${ph})`).bind(...chunk).run()
      rrPurgedCnt += (r as any)?.meta?.changes || 0
    }

    // (d) DR DELETE
    let drPurgedCnt = 0
    for (let i = 0; i < drIds.length; i += CHUNK) {
      const chunk = drIds.slice(i, i + CHUNK)
      const ph = chunk.map(() => '?').join(',')
      const r = await db.prepare(`DELETE FROM daily_rewards WHERE id IN (${ph})`).bind(...chunk).run()
      drPurgedCnt += (r as any)?.meta?.changes || 0
    }

    // (e) DR INSERT
    // PERMANENT_RULE #regular-time (2026-05-19): KST 08:00 = UTC (paid_date - 1day) 23:00
    const _prevKstStr_e = kstDateStr(new Date(new Date(TARGET_PAID_DATE + 'T00:00:00+09:00').getTime() - 24 * 60 * 60 * 1000))
    const drCreatedAt = `${_prevKstStr_e} 23:00:00`  // KST 08:00:00 of paid_date
    const rrCreatedAt = `${_prevKstStr_e} 23:00:01`  // KST 08:00:01 of paid_date

    for (let i = 0; i < expectedDRs.length; i += CHUNK) {
      const chunk = expectedDRs.slice(i, i + CHUNK)
      const stmts = chunk.map(dr =>
        db.prepare(`
          INSERT INTO daily_rewards (user_id, staking_id, usdt_amount, reward_date, paid_date, created_at)
          VALUES (?, ?, ?, ?, ?, ?)
        `).bind(dr.user_id, dr.staking_id, dr.amount, TARGET_REWARD_DATE, TARGET_PAID_DATE, drCreatedAt)
      )
      if (stmts.length > 0) await db.batch(stmts)
    }

    // DR id 매핑
    const drRowsAfter = await db.prepare(`
      SELECT id, user_id, staking_id FROM daily_rewards
      WHERE reward_date = ? AND paid_date = ?
    `).bind(TARGET_REWARD_DATE, TARGET_PAID_DATE).all()
    const drIdMap = new Map<string, number>()
    for (const r of (drRowsAfter.results || []) as any[]) {
      drIdMap.set(`${r.user_id}|${r.staking_id}`, Number(r.id))
    }

    // (f) DR tx INSERT
    const drTxStmts = expectedDRs.map(dr => {
      const drId = drIdMap.get(`${dr.user_id}|${dr.staking_id}`) ?? null
      return db.prepare(`
        INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id, created_at)
        VALUES (?, 'daily_qkey', 'QKEY', ?, ?, ?, ?)
      `).bind(dr.user_id, dr.amount, '일일 배당 (QKEY)', drId, drCreatedAt)
    })
    for (let i = 0; i < drTxStmts.length; i += CHUNK) {
      const c2 = drTxStmts.slice(i, i + CHUNK)
      if (c2.length > 0) await db.batch(c2)
    }

    // (g) RR INSERT
    for (let i = 0; i < expectedRRs.length; i += CHUNK) {
      const chunk = expectedRRs.slice(i, i + CHUNK)
      const stmts = chunk.map(rr =>
        db.prepare(`
          INSERT INTO referral_rewards (referrer_id, referee_id, level, original_amount, reward_amount, reward_date, paid_date, staking_id, created_at)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        `).bind(rr.referrer_id, rr.referee_id, rr.level, rr.original_amount, rr.reward_amount, TARGET_REWARD_DATE, TARGET_PAID_DATE, rr.staking_id, drCreatedAt)
      )
      if (stmts.length > 0) await db.batch(stmts)
    }

    // RR id 매핑
    const rrRowsAfter = await db.prepare(`
      SELECT id, referrer_id, referee_id, level, staking_id FROM referral_rewards
      WHERE reward_date = ? AND paid_date = ?
    `).bind(TARGET_REWARD_DATE, TARGET_PAID_DATE).all()
    const rrIdMap = new Map<string, number>()
    for (const r of (rrRowsAfter.results || []) as any[]) {
      rrIdMap.set(`${r.referrer_id}|${r.referee_id}|${r.level}|${r.staking_id}`, Number(r.id))
    }

    // (h) RR tx INSERT
    const rrTxStmts = expectedRRs.map(rr => {
      const rrId = rrIdMap.get(`${rr.referrer_id}|${rr.referee_id}|${rr.level}|${rr.staking_id}`) ?? null
      const desc = rr.level === 1 ? '추천 보너스 (Level 1)' : '추천 보너스 (Level 2)'
      return db.prepare(`
        INSERT INTO transactions (user_id, type, coin_type, amount, description, ref_id, created_at)
        VALUES (?, 'referral_reward', 'QKEY', ?, ?, ?, ?)
      `).bind(rr.referrer_id, rr.reward_amount, desc, rrId, rrCreatedAt)
    })
    for (let i = 0; i < rrTxStmts.length; i += CHUNK) {
      const c2 = rrTxStmts.slice(i, i + CHUNK)
      if (c2.length > 0) await db.batch(c2)
    }

    // (i) balance 증가
    {
      const addDelta = new Map<number, number>()
      for (const dr of expectedDRs) addDelta.set(dr.user_id, (addDelta.get(dr.user_id) || 0) + dr.amount)
      for (const rr of expectedRRs) addDelta.set(rr.referrer_id, (addDelta.get(rr.referrer_id) || 0) + rr.reward_amount)
      const balEntries = Array.from(addDelta.entries())
      for (let i = 0; i < balEntries.length; i += CHUNK) {
        const chunk = balEntries.slice(i, i + CHUNK)
        const stmts = chunk.map(([uid, delta]) =>
          db.prepare(`UPDATE users SET qkey_balance = qkey_balance + ? WHERE id = ?`).bind(delta, uid)
        )
        if (stmts.length > 0) await db.batch(stmts)
        balanceUpdated += chunk.length
      }
    }

    // POST-CHECK
    const drNew = await db.prepare(`SELECT COUNT(*) AS cnt, COALESCE(SUM(usdt_amount),0) AS total FROM daily_rewards WHERE reward_date = ?`).bind(TARGET_REWARD_DATE).first() as any
    const rrNew = await db.prepare(`SELECT COUNT(*) AS cnt, COALESCE(SUM(reward_amount),0) AS total FROM referral_rewards WHERE reward_date = ?`).bind(TARGET_REWARD_DATE).first() as any

    // legacy paid_date=5/8 잡것 잔여 확인
    const drLegacyRemain = await db.prepare(`SELECT COUNT(*) AS cnt FROM daily_rewards WHERE paid_date = ? AND reward_date != ?`).bind(TARGET_PAID_DATE, TARGET_REWARD_DATE).first() as any
    const rrLegacyRemain = await db.prepare(`SELECT COUNT(*) AS cnt FROM referral_rewards WHERE paid_date = ? AND reward_date != ?`).bind(TARGET_PAID_DATE, TARGET_REWARD_DATE).first() as any

    // PROTECT AFTER
    const protectAfter: any[] = []
    for (const pd of PROTECTED_REWARD_DATES) {
      const drB = await db.prepare(`SELECT COUNT(*) AS cnt, COALESCE(SUM(usdt_amount),0) AS total FROM daily_rewards WHERE reward_date = ?`).bind(pd).first() as any
      const rrB = await db.prepare(`SELECT COUNT(*) AS cnt, COALESCE(SUM(reward_amount),0) AS total FROM referral_rewards WHERE reward_date = ?`).bind(pd).first() as any
      protectAfter.push({
        reward_date: pd,
        dr_count: Number(drB?.cnt || 0), dr_total: Number(drB?.total || 0),
        rr_count: Number(rrB?.cnt || 0), rr_total: Number(rrB?.total || 0),
      })
    }
    const protectIntact = JSON.stringify(protectBaseline) === JSON.stringify(protectAfter)

    const drMatch = Number(drNew?.cnt || 0) === expectedDRs.length
    const rrMatch = Number(rrNew?.cnt || 0) === expectedRRs.length
    const legacyClean = Number(drLegacyRemain?.cnt || 0) === 0 && Number(rrLegacyRemain?.cnt || 0) === 0
    const allOk = protectIntact && drMatch && rrMatch && legacyClean

    return c.json({
      ok: allOk,
      mode: 'EXEC',
      action: 'recalc-may-six',
      summary,
      exec_result: {
        purge: { dr_deleted: drPurgedCnt, rr_deleted: rrPurgedCnt, tx_deleted: txPurgedCnt },
        insert: { dr_inserted: expectedDRs.length, rr_inserted: expectedRRs.length, tx_inserted: expectedDRs.length + expectedRRs.length },
        balance_updates: balanceUpdated,
        net_balance_delta_total: netBalanceDelta,
      },
      post_check: {
        new_5_7_count: {
          dr: Number(drNew?.cnt || 0), dr_total: Number(drNew?.total || 0),
          rr: Number(rrNew?.cnt || 0), rr_total: Number(rrNew?.total || 0),
          dr_match: drMatch, rr_match: rrMatch,
        },
        legacy_5_8_remain: {
          dr: Number(drLegacyRemain?.cnt || 0), rr: Number(rrLegacyRemain?.cnt || 0), clean: legacyClean,
        },
        protect: { baseline: protectBaseline, after: protectAfter, intact: protectIntact },
        verdict: allOk ? '✅ 영구룰 적합 완료' : '🚨 검증 실패 — 즉시 STOP & 보고',
      },
      duration_ms: Date.now() - t0,
    })
  } catch (error) {
    return c.json({ error: String(error), duration_ms: Date.now() - t0 }, 500)
  }
}


